    labelEnd,
    onSeeMore,
    seeMoreLabel,
    action,
    subtleLabel = false,
    items,
    allowsMultipleExpanded = false,
    defaultExpandedKeys,
    variant = "surface",
    emptyState: EmptyState,
    description,
    isSkeleton = false,
    identity,
