        key: item.id,
        title: (
            <FillAvailable
                at="base"
                isSkeleton={isSkeleton}
                body={() => (
                    <StackH
                        gap={2}
                        principle="content-row"
                        explain="Keeps accordion title peers on one baseline so start/end slots do not drop under the title."
                        isSkeleton={isSkeleton}
                        items={[
                            ...(item.titleStart ? [() => {
