            className={cn("flex flex-col", surfaceSectionGap(subtleLabel))}
            {...resolveIdentity(identity, { tier: "composite", name: "SurfaceCardAccordion" })}
        >
            <div>
                <SurfaceCardHeader
                    label={label}
                    labelEnd={labelEnd}
                    onSeeMore={onSeeMore}
                    seeMoreLabel={seeMoreLabel}
                    action={action}
                    subtleLabel={subtleLabel}
                    isSkeleton={isSkeleton}

                />
            </div>
            {withCaption}
        </section>
    )
}
