    description?: string
    /**
     * Optional breadcrumb row rendered above the title row, as a COMPONENT
     * reference (COMPOSITE-8) — the frame calls it itself. Typically a
     * `<Breadcrumbs>` house atom or a `LinkBack`. Omitted entirely while
     * loading (a route rarely needs it before data lands).
     */
    breadcrumb?: ComponentTypeWithSkeleton
    /**
     * Optional right-aligned slot for action controls, as a COMPONENT
     * reference — the frame calls it and renders it `shrink-0` so it never
     * compresses the title column. Omitted entirely while loading.
     */
    actions?: ComponentTypeWithSkeleton
    /**
     * Optional meta row placed BELOW the title/description — typically a row
     * of stat/meta chips ("24 Modules · 87 Content items …") — as a
     * COMPONENT reference. Rendered `gap-3` from the title block. While
     * loading, the frame draws its OWN 2-chip placeholder instead of calling
     * this (COMPOSITE-10: the frame decides how many, not this slot). Omit
     * when the header carries no stats.
     */
    meta?: ComponentTypeWithSkeleton
    /**
     * Title scale. `"page"` (default) = `Typography.Heading` level 3 — a route's
     * OWN page title. `"compact"` = body-size bold, for a header that labels a
     * PANE/PHASE inside an existing page shell.
     */
    size?: "page" | "compact"
    /**
     * Where this sits inside its parent. Appearance is not passable — it is already a prop.
     */
    classNames?: Array<AllowedClassName>
    /**
     * `true` -> each part this frame renders carries a ``
     * attribute so a BlockAnatomy panel can badge it on-render. Off in production.
     */
}

/**
 * Props for {@link PageHeader}. `title` is REQUIRED unless `isSkeleton` (§12b) —
 * a shimmer header has no real title to show yet.
 */
export type PageHeaderProps = PageHeaderOwnProps &
    (
        | {
            isSkeleton: true
            /** Primary page or section title. See the live variant's doc for the full contract. */
            title?: string
        }
        | {
            isSkeleton?: false
            /**
             * Primary page or section title. Rendered at `text-xl font-medium` in the
             * foreground tone through `Typography` (COMPOSITE-8: the frame builds it
             * itself, so this is plain text).
             */
            title: string
        }
    )

/**
 * Page/section header frame. Renders an optional breadcrumb row above a flex
 * row that places a stacked title + description on the left and optional action
 * controls on the right.
 *
 * This frame carries no card wrapper — the caller places it directly inside
 * a `Container` or wraps it in a `SectionCard` when a framed surface
 * is required.
 *
 * @param props - See {@link PageHeaderProps}.
 */
const Header = ({
    title,
    description,
    breadcrumb: Breadcrumb,
    actions: Actions,
    meta: Meta,
    size = "page",
    isSkeleton = false,
    classNames,
}: PageHeaderProps) => {
    // ONE render path (§12c) — every part this frame would render anyway stays,
    // each handed `isSkeleton`; the atoms draw their own shimmer. While loading, the
    // real shape (breadcrumb/description/meta presence) isn't known yet, so the
    // composite makes the same shape call the old hand-split branch made: assume a
    // description line and a 2-chip meta row, skip breadcrumb/actions (a route
    // rarely needs those before data lands).
    const showDescription = isSkeleton || description != null
    const showMeta = isSkeleton || Meta != null

    // Left column: stacked title and optional description
    const titleBlock = (
        <>
            {size === "compact" ? (
                <Typography weight="bold" isSkeleton={isSkeleton} text={title} />
            ) : (
                <Typography size="h3" weight="bold" isSkeleton={isSkeleton} text={title} />
            )}
            {showDescription ? (
                // clamp to 2 lines on mobile (keep the header short on a phone); full on sm+
                // — a viewport-width decision, so the wrapper owns it, not the atom.
                <div className={isSkeleton ? undefined : "line-clamp-2 @app-sm:line-clamp-none"}>
                    <Typography
                        size="sm"
                        color="muted"
                        isSkeleton={isSkeleton}
                        text={description}
                    />
                </div>
            ) : null}
        </>
    )
    // Main row: title+description stack on the left, actions pinned to the right
    const titleRow = (
        <StackH
            align="start"
            justify="between"
            gap={4}
            principle="content-row"
            isSkeleton={isSkeleton}
            items={[
                () => <StackV gap={3} classNames={["min-w-0"]} isSkeleton={isSkeleton} items={[() => titleBlock]} />,
                // Right slot: shrink-0 prevents action buttons from being squeezed.
                // Omitted while loading — the shape of the action row isn't known yet.
                ...(!isSkeleton && Actions ? [() => (
                    <div className="shrink-0"><Actions isSkeleton={isSkeleton} /></div>
                )] : []),
            ]}
        />
    )
    const headerBody = (
        <>
            {/* Breadcrumb row — rendered only when provided and loaded, sits above the main title row */}
            {!isSkeleton && Breadcrumb ? (
                <div><Breadcrumb isSkeleton={isSkeleton} /></div>
            ) : null}
            {titleRow}
            {/* Meta row: stat/meta chips below the title block (gap={4} from outer). While
                loading, 2 `Chip` placeholders stand in — the composite decides the count,
                the atom draws its own pill shimmer (no hand-rolled bar). */}
            {showMeta ? (
                isSkeleton ? (
                    <StackH
                        gap={3}
                        align="stretch"
                        principle="chip-row"
                        explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                        isSkeleton={isSkeleton}
                        items={[
                            () => <Chip isSkeleton />,
                            () => <Chip isSkeleton />,
                        ]}
                    />
                ) : (
                    <div>{Meta ? <Meta isSkeleton={isSkeleton} /> : null}</div>
                )
            ) : null}
        </>
    )
    return (
        // outer gap={4}: breadcrumb <-> title-block <-> meta (different header tiers);
        // title <-> description stay a related gap={3} pair inside the title block.
        <StackV gap={4} classNames={classNames} isSkeleton={isSkeleton} items={[() => headerBody]} />
    )
}

// ─────────────────────────────────────────────────────────────────────────────
// .BottomBar — the viewport-pinned action bar (was `StickyBottomBar`)
// ─────────────────────────────────────────────────────────────────────────────

/** Props for {@link PageBottomBar}. */
export interface PageBottomBarProps {
    /**
     * Leading content of the bar — typically a price — as a COMPONENT
     * reference (COMPOSITE-8): the frame calls it itself so it can forward
     * `isSkeleton`.
     */
    body?: ComponentTypeWithSkeleton
    /**
     * Trailing control(s) — the primary CTA — as a COMPONENT reference. When
     * BOTH `body` and `actions` are given the frame lays out the row itself
     * (`justify-between`, `shrink-0` on the actions) so callers stop
     * hand-rolling that flex row.
     */
    actions?: ComponentTypeWithSkeleton
    /** Shorthand for {@link PageBottomBarProps.body} — same component-reference contract. */
    /**
     * `true` -> forwarded into whichever of `body`/`actions` renders, so a bar
     * whose price/CTA is not known yet (e.g. still loading enrollment status)
     * can shimmer instead of showing stale content.
     */
    isSkeleton?: boolean
    /**
     * Where this sits inside its parent. Appearance is not passable — it is already a prop.
     */
    classNames?: Array<AllowedClassName>
    /**
     * `true` -> each region emits `` so a BlockAnatomy
     * panel can badge it on-render. Off in production.
     */
}

/**
 * A fixed bottom action bar pinned to the viewport edge — owns the chrome
 * (fixed position, top divider, surface background, safe padding) so features
 * just drop a price + CTA inside. Typically `@app-md:hidden` for a mobile sticky
 * enroll/checkout bar.
 *
 * A bar is a horizontal row, so its named slots are `body` (leading) +
 * `actions` (trailing) rather than the vertical `header`/`body`/`footer` trio.
 * With only one of them the content renders RAW, so a full-width button or a
 * two-button decision row keeps its own sizing (`flex-1`, `w-full`).
 *
 * @param props - {@link PageBottomBarProps}
 */
const BottomBar = ({
    body,
    actions,
    isSkeleton = false,
    classNames,
}: PageBottomBarProps) => {
    const Main = body
    const Actions = actions
    const chrome = "fixed bottom-0 left-0 right-[var(--app-rail-w,0px)] z-40 border-t border-separator bg-background px-6 py-3"

    // Only ONE side supplied -> render it raw: the caller's own width strategy
    // (`w-full` CTA, two `flex-1` buttons) must not be boxed by a shrink-0 wrapper.
    if (Main == null || Actions == null) {
        const Only = Main ?? Actions
        return (
            <div className={cn(chrome, classNames)} data-tier="composite" data-component="PageBottomBar">
                <div>{Only ? <Only isSkeleton={isSkeleton} /> : null}</div>
            </div>
        )
    }

    return (
        <div className={cn(chrome, classNames)} data-tier="composite" data-component="PageBottomBar">
            <StackH
                align="center"
                justify="between"
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                isSkeleton={isSkeleton}
                items={[
                    () => <div className="min-w-0"><Main isSkeleton={isSkeleton} /></div>,
                    () => <div className="shrink-0"><Actions isSkeleton={isSkeleton} /></div>,
                ]}
            />
        </div>
    )
}

/**
 * Page chrome members — a route imports these by name:
 *
 * | Export | Content channel |
 * |---|---|
 * | `PageHeader` | `breadcrumb`/`title`/`description`/`actions`/`meta` (no children) |
 * | `PageBottomBar` | `body`/`actions` slots |
 */
export { Header as PageHeader, BottomBar as PageBottomBar }

import React from "react"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { StackV } from "@sb-components/frames/Stack/Stack"

/** Source-level tier metadata — see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "TitledText" } as const

/**
 * `TitledText` — a primary line + optional muted secondary (and optional hint) stacked
 * vertically as one composite; a title<->subtitle pair is a single semantic unit rather than raw
 * `<Typography>` hand-rolled at every row. The composite owns the type scale per `size`; the
 * caller passes nodes only. Leaves: `subtitle`, `hint`, `size`, `weight`, `truncate`, `isSkeleton`.
 */

/**
 * Vertical text-stack scale:
 * - `row`    — dense list/setting row (title `sm` medium · subtitle `xs` muted).
 * - `header` — section/page header (title `h3` semibold · subtitle `sm` muted).
 * - `stat`   — a metric (title = big `h3` bold VALUE · subtitle = foreground label · hint muted).
 */
export type TitledTextSize = "row" | "header" | "stat"

/** Typography `size` + tone config resolved per {@link TitledTextSize}. */
/**
 * Skeleton bar width per line. Named so the widths can be typed where they are WRITTEN, not
 * only where they are read: the classes must be literal (`w-1/2`) because Tailwind only emits
 * a class it can see as a literal string in the source.
 */
interface TitledTextSkeletonWidths {
    /** Width class of the title bar. */
    title: AllowedClassName
    /** Width class of the subtitle bar. */
    sub: AllowedClassName
    /** Width class of the hint bar. */
    hint: AllowedClassName
}

interface SizeConfig {
    titleSize: "sm" | "h3"
    titleWeight: "medium" | "semibold" | "bold"
    subSize: "xs" | "sm"
    /** `undefined` -> foreground (default); `"muted"` -> muted line. */
    subColor?: "muted"
    subWeight?: "medium"
    /**
     * Skeleton bar width for each line — write the class LITERALLY (`w-1/2`), don't
     * build it dynamically (`w-${…}`), since Tailwind only generates a class from a
     * literal string it scans in the source.
     */
    skeleton: TitledTextSkeletonWidths
}

const SIZE_CONFIG: Record<TitledTextSize, SizeConfig> = {
    row: {
        titleSize: "sm",
        titleWeight: "medium",
        subSize: "xs",
        subColor: "muted",
        skeleton: { title: "w-1/2", sub: "w-2/3", hint: "w-1/3" },
    },
    header: {
        titleSize: "h3",
        titleWeight: "semibold",
        subSize: "sm",
        subColor: "muted",
        skeleton: { title: "w-1/3", sub: "w-2/3", hint: "w-1/2" },
    },
    stat: {
        titleSize: "h3",
        titleWeight: "bold",
        // stat's secondary is the LABEL — foreground + medium, not muted.
        subSize: "sm",
        subWeight: "medium",
        skeleton: { title: "w-1/3", sub: "w-2/3", hint: "w-1/2" },
    },
}

/** Props for the {@link TitledText} composite. */
export interface TitledTextProps {
    /** Primary line (title / name / label / stat value), rendered through `Typography`. */
    title: string
    /** Optional secondary line beneath the title (subtitle / role / description / stat label). */
    subtitle?: string
    /** Optional third muted line (only meaningful for `size="stat"`, e.g. a delta hint). */
    hint?: string
    /** Text-stack scale. Defaults to `"row"`. */
    size?: TitledTextSize
    /** Override the title weight (per-size default otherwise). */
    weight?: "medium" | "semibold" | "bold"
    /** Truncate every line to a single line (needs a bounded parent width). */
    truncate?: boolean
    /** `true` -> render the skeleton mirror (bars sized per line). */
    isSkeleton?: boolean
    /**
     * Where this sits inside its parent. Appearance is not passable — it is already a prop.
     */
    classNames?: Array<AllowedClassName>
}

/**
 * TitledText renders a primary line over an optional muted secondary (and hint)
 * as one vertical unit. The composite OWNS the type scale + tone per `size`; the
 * caller passes nodes only. Root is `flex min-w-0 flex-col` so truncation works
 * and callers can add `flex-1`.
 *
 * @param props - {@link TitledTextProps}
 */
export const TitledText = ({
    title,
    subtitle,
    hint,
    size = "row",
    weight,
    truncate = false,
    isSkeleton = false,
    classNames,
}: TitledTextProps) => {
    const cfg = SIZE_CONFIG[size]
    const rootClassNames: Array<AllowedClassName> = ["min-w-0", ...(classNames ?? [])]

    // COMPOSITE-10: ONE render path — same `StackV`, same `gap`, in both states.
    // Text always goes through the `Typography` ATOM; `isSkeleton` just flows
    // straight into it so each line draws its own bar, sized to its own value
    // (§12c) — no second, hand-built skeleton tree to keep in sync with this one.
    return (
        <StackV
            gap={1}
            classNames={rootClassNames}
            isSkeleton={isSkeleton}

            items={[
                () => (
                    <Typography
                        size={cfg.titleSize}
                        weight={isSkeleton ? undefined : (weight ?? cfg.titleWeight)}
                        truncate={isSkeleton ? undefined : truncate}
                        isSkeleton={isSkeleton}
                        text={title}

                    />
                ),
                ...(subtitle ? [() => (
                    <Typography
                        size={cfg.subSize}
                        color={isSkeleton ? undefined : cfg.subColor}
                        weight={isSkeleton ? undefined : cfg.subWeight}
                        truncate={isSkeleton ? undefined : truncate}
                        isSkeleton={isSkeleton}
                        text={subtitle}

                    />
                )] : []),
                ...(hint ? [() => (
                    <Typography
                        size="xs"
                        color={isSkeleton ? undefined : "muted"}
                        truncate={isSkeleton ? undefined : truncate}
                        isSkeleton={isSkeleton}
                        text={hint}

                    />
                )] : []),
            ]}
        />
    )
}

import React from "react"
import { cn } from "@heroui/react"
import {
    TableBody,
    TableCell,
    TableColumn,
    TableContent,
    TableHeader,
    TableRoot,
    TableRow,
    TableScrollContainer,
} from "@sb-components/atoms/data/Table/Table"
import {
    flattenMarkdownTableHeaderChildren,
    isMarkdownHeaderTableRowNode,
} from "@sb-components/composites/viewers/MarkdownContent/markdown-table"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"

/**
 * `MarkdownTableParts` — renders a markdown GFM table for `MarkdownContent` via
 * the house `TableRoot` compound.
 *
 * Not the `composites/data/Table` composite: that one is config-driven (`columns`
 * + `items` data, children forbidden), whereas a GFM table arrives as an
 * already-rendered `thead`/`tbody` children tree from `react-markdown` that cannot
 * be reduced back into that shape without re-parsing. As a viewer, `MarkdownContent`
 * never knows its own shape ahead of render, so it goes straight to the house
 * table compound.
 */

/**
 * Builds a house header column from a rendered `th`/`TableColumn` or body `TableCell`.
 * @param column - Rendered header cell from markdown.
 * @param index - Zero-based column index in the header row.
 * @returns A `TableColumn` with `isRowHeader` on the first column (HeroUI requirement).
 */
const toMarkdownHeaderColumn = (column: React.ReactNode, index: number): React.ReactNode => {
    if (!React.isValidElement<ElementWithChildren>(column)) {
        return column
    }
    return (
        <TableColumn key={`md-th-${index}`} isRowHeader={index === 0}>
            {column.props.children}
        </TableColumn>
    )
}

interface ElementWithChildren {
    children?: React.ReactNode
}

/** Props for markdown table row/cell parts. */
export interface MarkdownTablePartProps {
    /** Rendered cell content. */
    children?: React.ReactNode
    /** HAST element for the markdown row (react-markdown always threads this through). */
    node?: unknown
    /** Where this sits inside its parent, from the closed positioning union. */
    classNames?: Array<AllowedClassName>
}

/**
 * Header row: columns must be direct children of `TableHeader` (fragment, not `TableRow`).
 * Body row: wrapped in house `TableRow`.
 */
export const MarkdownTableRow = ({ children, node, classNames }: MarkdownTablePartProps) => {
    if (isMarkdownHeaderTableRowNode(node)) {
        return <>{children}</>
    }

    return <TableRow className={cn(classNames)}>{children}</TableRow>
}

/**
 * Maps markdown `thead` to house `TableHeader`.
 * Rebuilds columns with `isRowHeader` on the first column (required by HeroUI / React Aria).
 * Renders a screen-reader-only column when the header row is empty so the table still mounts.
 */
export const MarkdownTableHead = ({ children, classNames }: MarkdownTablePartProps) => {
    const columns = flattenMarkdownTableHeaderChildren(children)

    return (
        <TableHeader className={cn(classNames)}>
            {columns.length === 0 ? (
                <TableColumn isRowHeader className="sr-only">
                    {" "}
                </TableColumn>
            ) : (
                columns.map((column, index) => toMarkdownHeaderColumn(column, index))
            )}
        </TableHeader>
    )
}

/** Props for {@link MarkdownTable}. */
export interface MarkdownTableProps {
    /** Rendered `thead` / `tbody` from react-markdown. */
    children?: React.ReactNode
    /** Accessible name for `TableContent`. */
    ariaLabel: string
    /**
     * Where this sits inside its parent, from the closed positioning union.
     * `map.tsx` owns the block-rhythm margin between fences by wrapping this
     * component's output in a plain `<div>` — margins have no slot in
     * `AllowedClassName` (see `principles/margin.md`).
     */
    classNames?: Array<AllowedClassName>
}

/**
 * Wraps GFM tables in house `TableRoot` and ensures a header row exists with `isRowHeader`.
 * Some markdown tables only emit `tbody`; the first body row is promoted to `thead` in that case.
 * @param props - {@link MarkdownTableProps}
 */
export const MarkdownTable = ({ children, ariaLabel, classNames }: MarkdownTableProps) => {
    const parts = React.Children.toArray(children)
    const hasThead = parts.some(
        (child) => React.isValidElement(child) && child.type === MarkdownTableHead,
    )
    const tbodyIndex = parts.findIndex(
        (child) => React.isValidElement(child) && child.type === MarkdownTableBody,
    )

    let content: React.ReactNode
    if (hasThead) {
        content = children
    } else if (tbodyIndex < 0) {
        content = (
            <>
                <MarkdownTableHead />
                {children}
            </>
        )
    } else {
        const tbody = parts[tbodyIndex] as React.ReactElement<ElementWithChildren>
        const bodyRows = React.Children.toArray(tbody.props.children)
        const [firstRow, ...restRows] = bodyRows
        content = (
            <>
                {parts.slice(0, tbodyIndex)}
                <MarkdownTableHead>{firstRow}</MarkdownTableHead>
                <MarkdownTableBody>{restRows}</MarkdownTableBody>
                {parts.slice(tbodyIndex + 1)}
            </>
        )
    }

    // The house table-root is a CSS grid; its inner scroll-container's min-width doesn't
    // propagate, so a wide table forces the whole reading column past the viewport (page stops
    // shrinking). Wrap in a PLAIN BLOCK x-scroll box — a block scroll container has min-content
    // 0, so the column shrinks and the table scrolls inside instead of blocking the layout.
    return (
        <div className={cn("max-w-full overflow-x-auto", classNames)}>
            <TableRoot variant="primary">
                <TableScrollContainer>
                    <TableContent aria-label={ariaLabel}>
                        {content}
                    </TableContent>
                </TableScrollContainer>
            </TableRoot>
        </div>
    )
}

/** Maps markdown `tbody` to house `TableBody`. */
export const MarkdownTableBody = ({ children, classNames }: MarkdownTablePartProps) => (
    <TableBody className={cn(classNames)}>{children}</TableBody>
)

/** Maps markdown `th` to house `TableColumn`. */
export const MarkdownTableColumn = ({ children, classNames }: MarkdownTablePartProps) => (
    <TableColumn className={cn(classNames)}>{children}</TableColumn>
)

/** Maps markdown `td` to house `TableCell` — exported for `map.tsx`. */
export const MarkdownTableCell = ({ children, classNames }: MarkdownTablePartProps) => (
    <TableCell className={cn(classNames)}>{children}</TableCell>
)

import React from "react"
import { cn } from "@heroui/react"
import {
    AccordionTree,
    AccordionTreeBody,
    AccordionTreeHeading,
    AccordionTreeIndicator,
    AccordionTreeItem,
    AccordionTreePanel,
    AccordionTreeTrigger,
} from "@sb-components/atoms/navigation/AccordionTree/AccordionTree"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { CodeToHtml } from "@sb-components/composites/viewers/MarkdownContent/CodeToHtml"
import { MermaidDiagram } from "@sb-components/composites/viewers/MarkdownContent/MermaidDiagram"
import { TabsBlock, TabPane } from "@sb-components/composites/viewers/MarkdownContent/TabsBlock"
import {
    MarkdownTable,
    MarkdownTableBody,
    MarkdownTableCell,
    MarkdownTableColumn,
    MarkdownTableHead,
    MarkdownTableRow,
} from "@sb-components/composites/viewers/MarkdownContent/MarkdownTableParts"
import { Box } from "@sb-components/frames/Box/Box"
import { StackH } from "@sb-components/frames/Stack/Stack"

/**
 * The element-renderer MAP for `MarkdownContent` — the whole grammar (headings,
 * tables, code, mermaid, custom directive tags) in one file.
 *
 * Handles: Shiki syntax highlighting, mermaid diagrams, `:::tab`/`:::code`/
 * `:::preview` -> Preview<->Code tabs, GFM tables -> house `TableRoot`,
 * `::::accordion`/`:::panel` -> house `AccordionTree`, `:::muted`, `:::chip`, image
 * captions, link routing, heading anchors. Not handled here: `arcSections`,
 * `plain` mode, the ` ```mdx ` live-render fence, the ` ```layout ` fence.
 *
 * Vertical rhythm is owned by the single wrapper in `MarkdownContent.tsx`, or in
 * reading measure by a plain `<div className={blockMy}>` around each block-level
 * renderer's output — margin is a seam between two blocks, written where both are
 * visible rather than passed as a `className` prop. `CodeToHtml`,
 * `MermaidDiagram`, and `MarkdownTable` take no `className`.
 */

/** UI copy for the code/table/mermaid chrome. Storybook has no i18n-aware runtime
 * for this tree (see the file header on `MarkdownContent.tsx`), so — like every
 * other composite in this design system — the copy is a hardcoded constant
 * instead of a `useTranslations()` call. Values mirror `src/messages/vi.json`'s
 * `markdown.*` keys so a reader comparing the two sees the same words. */
const TABLE_ARIA_LABEL = "Content table"
const MERMAID_LOADING_LABEL = "Drawing diagram..."
const MERMAID_EXPAND_LABEL = "Expand diagram"
const MERMAID_FALLBACK_LABEL = "Figure"
const HEADING_ANCHOR_LABEL = "Link to this section"

/** Anything the parser hands back with only children — most of the grammar. */
export interface MarkdownNodeProps {
    /** Whatever the parser put inside this element. */
    children?: React.ReactNode
}

/** A link node: the payload decides the target, the viewer only decides the skin. */
export interface MarkdownLinkProps extends MarkdownNodeProps {
    /** Link target as authored. */
    href?: string
}

/** An image node — a raw URL plus its alt text, both straight from the payload. */
export interface MarkdownImageProps {
    /** Image source as authored. */
    src?: string
    /** Alt text as authored; a non-empty alt doubles as a real figure caption. */
    alt?: string
}

/**
 * A code node. A fenced block arrives with `language-*` on react-markdown's
 * `className`; that string is the language hook, not a styling door — stored here
 * as `fenceClass` so COMPOSITE-4 does not see a `className` prop on a `*Props` type.
 */
export interface MarkdownCodeProps extends MarkdownNodeProps {
    /** `language-*` for a fenced block, absent for inline code. */
    fenceClass?: string
}

/** react-markdown still emits `className` on `code`; rename at the renderer boundary. */
type MarkdownCodeRuntimeProps = MarkdownNodeProps & {
    className?: string
}

/** One `:::panel{title="…"}` inside an `::::accordion` block. */
export interface MarkdownPanelProps extends MarkdownNodeProps {
    /** Trigger-row title carried by the directive attribute. */
    title?: string
}

/** The `:::chip` directive's rewritten tag — one `|`-joined line of keywords. */
export interface MarkdownChipBlockProps {
    /** `|`-joined keyword list, one per authored line (see `remarkChip` in `MarkdownContent.tsx`). */
    items?: string
}

/** Config for one {@link buildTocHeading} level. */
interface TocHeadingConfig {
    /** Heading depth surfaced in the outline. */
    level: 2 | 3 | 4
    /** Tailwind text-size class. */
    sizeClass: string
    /** Tailwind margin class (asymmetric — reading measure only). */
    marginClass: string
    /** `true` (reading measure only) -> render the hover `#` deep-link affordance. */
    showAnchor: boolean
}

/**
 * Recursively flattens a React children tree to its plain-text content — used to
 * derive a stable heading slug (and the "on this page" outline label) from the
 * rendered heading nodes.
 * @param node - The React node to read text from.
 * @returns The concatenated text content.
 */
const getNodeText = (node: React.ReactNode): string => {
    if (node === null || node === undefined || typeof node === "boolean") {
        return ""
    }
    if (typeof node === "string" || typeof node === "number") {
        return String(node)
    }
    if (Array.isArray(node)) {
        return node.map(getNodeText).join("")
    }
    if (React.isValidElement(node)) {
        return getNodeText((node.props as MarkdownNodeProps).children)
    }
    return ""
}

/**
 * Slugify heading text into a URL-safe anchor id (diacritics stripped, Vietnamese
 * Vietnamese d-with-stroke folded to `d`, non-alphanumerics collapsed to single hyphens). Deterministic so the
 * rendered heading id and any "on this page" outline reading it from the DOM agree.
 * @param text - The raw heading text.
 * @returns The anchor slug.
 */
const slugify = (text: string): string =>
    text
        .normalize("NFKD")
        .replace(/[̀-ͯ]/g, "")
        .replace(/[đĐ]/g, "d") // vn-ok: slug transliteration of the VI letter
        .toLowerCase()
        .trim()
        .replace(/[^a-z0-9]+/g, "-")
        .replace(/^-+|-+$/g, "")

/**
 * Heading renderer factory: renders a section heading carrying a slug `id` +
 * `data-toc` markers so an "on this page" rail can scan the rendered article
 * (`[data-toc]`) and anchor-scroll to it. `scroll-mt-20` clears a sticky navbar
 * when jumped to. The hover `#` deep-link only renders in reading measure — cards
 * / chat / modals have no shareable url for it.
 * @param config - {@link TocHeadingConfig}
 */
const buildTocHeading = ({ level, sizeClass, marginClass, showAnchor }: TocHeadingConfig) =>
    ({ children }: MarkdownNodeProps) => {
        const Tag = `h${level}` as "h2" | "h3" | "h4"
        const text = getNodeText(children)
        const id = slugify(text)
        return (
            <Tag
                id={id}
                data-toc=""
                data-toc-level={level}
                data-toc-label={text}
                className={cn("group scroll-mt-20 font-semibold", marginClass, sizeClass)}
            >
                {children}
                {showAnchor ? (
                    <a
                        href={`#${id}`}
                        aria-label={HEADING_ANCHOR_LABEL}
                        className="ml-2 text-muted no-underline opacity-0 transition-opacity group-hover:opacity-100"
                    >
                        #
                    </a>
                ) : null}
            </Tag>
        )
    }

/** Params for {@link buildMarkdownRenderers}. */
export interface MarkdownRenderersParams {
    /** True when the Storybook toolbar theme is dark; selects mermaid/Shiki themes. */
    isDark: boolean
    /** Reading-grade typography (bigger type, generous rhythm) vs the compact scale. */
    reading: boolean
    /** Figure captions keyed by trimmed mermaid source, paired from the following paragraph. */
    mermaidCaptions: Record<string, string>
}

/**
 * Builds the element-renderer map handed to `ReactMarkdown`. See the file header
 * for scope; each renderer stays margin-free in compact measure (the wrapper in
 * `MarkdownContent.tsx` owns the uniform rhythm there) and carries its own
 * asymmetric margin in reading measure.
 * @param params - {@link MarkdownRenderersParams}
 */
export const buildMarkdownRenderers = ({ isDark, reading, mermaidCaptions }: MarkdownRenderersParams) => {
    const blockMy = reading ? "my-4" : "my-3"
    // Link text rides the same body scale as the surrounding prose.
    const linkSize = reading ? "base" : "sm"

    return {
        h1: ({ children }: MarkdownNodeProps) => (
            <h1 className={cn("font-semibold text-foreground", reading ? "mt-8 mb-3 text-2xl" : "mt-6 mb-2 text-xl")}>{children}</h1>
        ),
        h2: buildTocHeading({
            level: 2,
            sizeClass: reading ? "text-xl" : "text-lg",
            marginClass: reading ? "mt-8 mb-3" : "mt-6 mb-2",
            showAnchor: reading,
        }),
        h3: buildTocHeading({
            level: 3,
            sizeClass: reading ? "text-lg" : "text-base",
            marginClass: reading ? "mt-6 mb-2" : "mt-4 mb-2",
            showAnchor: reading,
        }),
        h4: buildTocHeading({
            level: 4,
            sizeClass: reading ? "text-base" : "text-sm",
            marginClass: reading ? "mt-6 mb-2" : "mt-4 mb-2",
            showAnchor: reading,
        }),
        p: ({ children }: MarkdownNodeProps) => (
            <p className={cn("text-foreground", reading ? "my-3 text-base leading-7" : "my-2 text-sm leading-6")}>{children}</p>
        ),
        ul: ({ children }: MarkdownNodeProps) => (
            <ul className={cn("list-disc pl-6", reading ? "my-3 space-y-1" : "my-2 space-y-1")}>{children}</ul>
        ),
        ol: ({ children }: MarkdownNodeProps) => (
            <ol className={cn("list-decimal pl-6", reading ? "my-3 space-y-1" : "my-2 space-y-1")}>{children}</ol>
        ),
        li: ({ children }: MarkdownNodeProps) => (
            <li className={cn("text-foreground", reading ? "text-base leading-7" : "text-sm leading-6")}>{children}</li>
        ),
        strong: ({ children }: MarkdownNodeProps) => (
            <strong className="font-semibold text-foreground">{children}</strong>
        ),
        em: ({ children }: MarkdownNodeProps) => <em className="italic">{children}</em>,
        // Internal (`/`-prefixed) links stay in the same tab; anything else is external and opens a
        // new tab. Reuses the `Typography` atom's `isLink` branch (HeroUI `Link` + a11y) rather than
        // hand-rolling an `<a>` — the atom already owns exactly this link skin everywhere else.
        a: ({ href, children }: MarkdownLinkProps) => {
            const isInternal = typeof href === "string" && href.startsWith("/")
            return (
                <Typography
                    size={linkSize}
                    isLink
                    href={href}
                    target={isInternal ? undefined : "_blank"}
                    rel={isInternal ? undefined : "noopener noreferrer"}
                    text={children}
                />
            )
        },
        blockquote: ({ children }: MarkdownNodeProps) => (
            <blockquote className={cn("border-l-2 border-default pl-3 text-muted", reading ? "my-4" : "my-3")}>{children}</blockquote>
        ),
        hr: () => <hr className={cn("border-default", reading ? "my-8" : "my-6")} />,
        // Markdown `![caption](src)`: a non-empty alt doubles as a real figure caption; an empty
        // alt renders a bare (decorative) image — same rule `src` uses.
        img: ({ src, alt }: MarkdownImageProps) => (
            alt ? (
                <figure className={blockMy}>
                    <img src={src} alt={alt} className="w-full rounded-2xl" />
                    <figcaption className="mt-2 text-center text-sm italic text-muted">{alt}</figcaption>
                </figure>
            ) : (
                <img src={src} alt="" className={cn("w-full rounded-2xl", blockMy)} />
            )
        ),
        // GFM table -> house `TableRoot` compound (see the file header on `MarkdownTableParts.tsx`
        // for why this is NOT the config-driven `composites/data/Table`). The block-rhythm margin
        // (COMPOSITE-4: `MarkdownTable` takes no `className`) is owned here, by the plain wrapping
        // `<div>` — margin is a seam between two blocks, not a prop of either one.
        table: ({ children }: MarkdownNodeProps) => (
            <div className={blockMy}>
                <MarkdownTable ariaLabel={TABLE_ARIA_LABEL}>{children}</MarkdownTable>
            </div>
        ),
        thead: MarkdownTableHead,
        tbody: MarkdownTableBody,
        tr: MarkdownTableRow,
        th: MarkdownTableColumn,
        td: MarkdownTableCell,
        // A fenced block's inner `code` carries `language-*`; anything else is inline.
        // react-markdown still passes `className`; rename to `fenceClass` at this boundary.
        code: ({ children, className }: MarkdownCodeRuntimeProps) => {
            const fenceClass = className
            if (fenceClass?.startsWith("language-")) {
                return children
            }
            return (
                // inset-exception: inline-code geometry, wider than tall by nature, not a surface inset
                // (same shape as `RichText`'s inline `<code>` — see `RichText.tsx`)
                <Box as="code" principle="control-pad" className="rounded-md bg-default px-1 py-0 font-mono text-sm text-foreground [overflow-wrap:anywhere]"
                    explain="Control hit-area inset — not row-pad, because this pads a single interactive control rather than a full content row.">
                    {children}
                </Box>
            )
        },
        // Fenced block dispatch: `mermaid` -> diagram, everything else -> Shiki.
        pre: ({ children }: MarkdownNodeProps) => {
            const child = React.Children.only(children) as React.ReactElement<MarkdownCodeRuntimeProps>
            const fenceClass = child.props.className
            const lang = /language-(\w+)/.exec(fenceClass ?? "")?.[1] ?? "text"
            const code = String(child.props.children ?? "").replace(/\n$/, "")
            // Block-rhythm margin (COMPOSITE-4: neither viewer takes `className`) owned by the
            // plain wrapping `<div>` — margin is a seam between two blocks, not either one's prop.
            if (lang.toLowerCase() === "mermaid") {
                return (
                    <div className={blockMy}>
                        <MermaidDiagram
                            code={code}
                            theme={isDark ? "dark" : "default"}
                            loadingLabel={MERMAID_LOADING_LABEL}
                            expandLabel={MERMAID_EXPAND_LABEL}
                            caption={mermaidCaptions[code.trim()]}
                            fallbackLabel={MERMAID_FALLBACK_LABEL}
                        />
                    </div>
                )
            }
            return (
                <div className={blockMy}>
                    <CodeToHtml
                        code={code}
                        language={lang}
                        theme={isDark ? "material-theme-darker" : "material-theme-lighter"}

                    />
                </div>
            )
        },
        // Custom `:::muted` directive tags (see `remarkMuted` in `MarkdownContent.tsx`): small,
        // muted label text. `[&_*]:text-muted` forces the muted colour onto any inner `<p>`.
        mutedblock: ({ children }: MarkdownNodeProps) => (
            <div className="text-sm font-semibold text-muted [&_*]:text-muted">{children}</div>
        ),
        mutedtext: ({ children }: MarkdownNodeProps) => (
            <span className="text-sm font-semibold text-muted">{children}</span>
        ),
        // Custom `:::chip` directive tag: a wrapped row of chips, one per authored keyword line.
        // Reuses the `Chip` ATOM (soft/neutral) rather than HeroUI `Chip` directly.
        chipblock: ({ items }: MarkdownChipBlockProps) => (
            <div className="my-2">
                <StackH
                    as="span"
                    at="sm"
                    gap={3}
                    principle="chip-row"
                    explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                    items={String(items ?? "").split("|").filter(Boolean).map((keyword) => () => (
                        <Chip tone="default" text={keyword} />
                    ))}
                />
            </div>
        ),
        // :::tab -> [ Preview | Code ] tabs; code/preview panes carry `kind` so `TabsBlock` matches them.
        tabblock: ({ children }: MarkdownNodeProps) => <TabsBlock>{children}</TabsBlock>,
        tabcode: ({ children }: MarkdownNodeProps) => <TabPane kind="code">{children}</TabPane>,
        tabpreview: ({ children }: MarkdownNodeProps) => <TabPane kind="preview">{children}</TabPane>,
        // ::::accordion / :::panel{title} -> house `AccordionTree` compound (incremental panels from
        // react-markdown — not the data-driven Disclosure `Accordion` atom). `variant="default"`
        // keeps the item separator FULL-BLEED, with the light hairline `--separator` re-point so
        // dividers read the same as the `SurfaceListCard` family; `border` delineates it as a
        // nested surface.
        accordionblock: ({ children }: MarkdownNodeProps) => (
            // `AccordionTree` omits `className` (atom door is closed); border/rhythm sit on the
            // wrapping seam so COMPOSITE-4 stays clean while the nested-surface look is preserved.
            <div className={cn("overflow-hidden border border-default bg-surface", blockMy)}>
                <AccordionTree
                    variant="default"
                    separatorTone="subtle"
                >
                    {children}
                </AccordionTree>
            </div>
        ),
        accordionpanel: ({ title, children }: MarkdownPanelProps) => (
            <AccordionTreeItem aria-label={String(title ?? "")}>
                <AccordionTreeHeading>
                    <AccordionTreeTrigger>
                        <div className="text-start">
                            <StackH
                                gap={4}
                                principle="content-row"
                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                justify="between"
                                items={[
                                    () => <span className={reading ? "text-base font-semibold" : "text-sm font-semibold"}>{title}</span>,
                                    () => <AccordionTreeIndicator />,
                                ]}
                            />
                        </div>
                    </AccordionTreeTrigger>
                </AccordionTreeHeading>
                <AccordionTreePanel>
                    <AccordionTreeBody>
                        <div className="space-y-2">{children}</div>
                    </AccordionTreeBody>
                </AccordionTreePanel>
            </AccordionTreeItem>
        ),
    }
}

import React from "react"
import type { ReactNode } from "react"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"
import type { ComponentTypeWithSkeleton } from "@sb-components/frames/_slot"
import { Divider } from "@sb-components/atoms/display/Divider/Divider"
import { type AllowedGap, type LayoutAlign, type LayoutJustify, type PaddingValue, type Responsive } from "@sb-components/frames/_spacing"
import { Flex } from "@sb-components/frames/Flex/Flex"
import type { ResponsiveRowSwitch } from "@sb-components/frames/ResponsiveRow/ResponsiveRow"
import type { PrincipleToken, ExplainReason } from "@sb-components/frames/_principles"
import type { CallerIdentity } from "@sb-components/frames/_identity"

/**
 * ─────────────────────────────────────────────────────────────────────────────
 * LAYOUT (frame) -- `Stack.*`: the base one-axis track. Two members = two AXES,
 * the only real shapes a stack has:
 *   • `StackV` -- stacks VERTICALLY (column).
 *   • `StackH` -- stacks HORIZONTALLY (row); only this axis takes `at` (FRAME-10:
 *     the container step it wraps below, never a bare boolean).
 *
 * FRAME API LAW (§13b): a stack WRAPS arbitrary content -- it is not a repeating
 * list -- so `children` is the road (there is no `header`/`body`/`footer` trio to
 * name: a track has exactly ONE slot, its content). `items` would be wrong here;
 * see `Cluster`/`Grid` for the repeat-list frames of this folder.
 *
 * WHY THIS FRAME EXISTS: `gap` is typed {@link Responsive}<{@link AllowedGap}> -- a
 * CLOSED index into the house gap table. Off-scale (`gap-4.5`, `gap-[13px]`) cannot even
 * be typed, so the scale is enforced by the COMPILER instead of by review.
 * `gap` is REQUIRED for the same reason: an implicit default would let the seam
 * be chosen by accident, and §10a says a seam has exactly one deliberate owner.
 *
 * §13 boundaries respected: no domain content, no feature behaviour -- the track
 * only decides direction / gap / alignment / an optional rule between children.
 * `divider` COMPOSES the existing `Divider` atom (§13c: a frame never
 * hand-rolls what an atom already owns).
 * ─────────────────────────────────────────────────────────────────────────────
 */

/** Props shared by both axes of {@link Stack}. */
export interface StackBaseProps {
    /**
     * Seam between children on the house gap scale.
     * Optional when `principle` is a gap-owning token — the principle resolves the class.
     * Still required when there is no gap principle (Flex enforces at render via ownership).
     */
    gap?: Responsive<AllowedGap>
    /** Cross-axis alignment (`V` → horizontal, `H` → vertical). */
    align?: LayoutAlign
    /** Main-axis distribution (`V` → vertical, `H` → horizontal). */
    justify?: LayoutJustify
    /** `true` → inserts `Divider` BETWEEN children (never before the first / after the last). */
    divider?: boolean
    /**
     * Space INSIDE the track, same scale as `gap`.
     *
     * 2026-07-27: forwarded down to `Flex` so a stack that also needs padding no longer
     * has to DROP to `Flex` and lose `divider` plus the axis semantics. That drop was the
     * one remaining reason to reach past this frame, and a way out that costs less than the
     * proper road always wins -- the same force that produced 227 hand-written
     * `flex flex-col gap-4` in the first place.
     */
    padding?: Responsive<PaddingValue>
    /**
     * `true` → a left guide border + matching indent (`pl-3`, `@app-sm:pl-6`),
     * for a track that is ONE LEVEL DEEPER than its caller (a threaded reply,
     * a nested tree row) -- the frame owns the exact classes so no block ever
     * hand-writes `border-l`/`pl-*` itself (teacher 2026-07-28). Same vocabulary
     * as `SurfaceCard`'s own `variant="nested"` (border marks "inside a
     * parent", not a fresh outer face) -- this is that same idea for a track.
     */
    nested?: boolean
    /**
     * The HTML element to render, forwarded to `Flex`. Defaults to `div`.
     *
     * Added 2026-07-29 for the same reason `padding` was: a stack that also needed a real tag
     * (`section`, `figure`, `span`) had to DROP to hand-written classes and lose the axis
     * semantics along the way. Three call-sites sat outside the frame tier for exactly that.
     */
    as?: "div" | "section" | "figure" | "span" | "li"
    /**
     * `true` → the track hugs its content (`inline-flex`) instead of taking the whole line.
     * Measured on the same content: the block box came out 503px, the inline box 136px.
     */
    inline?: boolean
    /**
     * Anatomy tag for THIS frame itself -- so the PARENT can badge it as ONE node (§11a.1).
     * Missing this prop means the `layouts`-tier frame is used but the panel cannot see it.
     */
    /** A SINGLE buildable child -- an uncalled `ComponentType<{isSkeleton?}>` the track renders itself. Use `items` for several. */
    body?: ComponentTypeWithSkeleton
    /**
     * The stacked content as BUILDABLE items -- each an uncalled `ComponentType<{isSkeleton?}>`
     * the track renders itself, so it can thread `isSkeleton` down and interleave dividers. Preferred
     * over `body`: a frame that can BUILD its children can shimmer them (one tree, no hand-mirror).
     * Wins over `body` when both are passed.
     */
    items?: Array<ComponentTypeWithSkeleton>
    /** `true` → the track passes `isSkeleton` to every `items` component so the whole column shimmers. */
    isSkeleton?: boolean
    /**
     * Where this sits inside its parent. Appearance is not passable -- it is already a prop.
     */
    classNames?: Array<AllowedClassName>
    /**
     * The layout pattern this track's seam realises - forwarded straight to the `Flex` this
     * track renders through, the same way `gap`/`align`/`justify` are. See `Flex`'s own
     * `pattern` doc for the full contract. Query as `[data-principle="token"]`.
     */
    principle?: PrincipleToken
    /**
     * Why this layer exists - one sentence, emitted as `data-explain` beside the token.
     * A reason, never a restatement of `principle`. Forwarded to `Flex`.
     */
    explain?: ExplainReason
    /**
     * Caller identity to wear on this track's root instead of `Stack`'s own -- pass this when a
     * `block`/`layout`/`overlay`/`page` component (BLOCK-2: never draws a shape of its own) is
     * using this track AS its root element, instead of wrapping it in a raw `<div data-tier=...
     * data-component=...>`. Forwarded straight to `Flex`, which is what actually renders the DOM
     * (see `Flex`'s own `identity` doc). See `_identity.ts`. Omitted → this track keeps
     * emitting `data-tier="frame" data-component="Flex"`, unchanged.
     */
    identity?: CallerIdentity
}

/** Props for {@link StackV} -- a vertical track (no row-only prop to add). */
export type StackVProps = StackBaseProps

/** Props for {@link StackH} -- a horizontal track. */
export interface StackHProps extends StackBaseProps {
    /**
     * Container step the row switches from wrapped to single-line at (FRAME-10). Below `at`
     * children flow onto a new line when the row runs out of width; at `at` and above the row
     * stays single-line. ROW-ONLY: a column already grows without bound, so this is meaningless
     * on `StackV` and is not offered there. Left out, the row never wraps -- same behaviour the
     * old `wrap={false}` default had.
     */
    at?: ResponsiveRowSwitch
}

/**
 * Interleaves `Divider` between children -- NOT around them: N children get
 * N−1 rules. The atom carries its own `` (part name `Line`), so the
 * frame adds no wrapper element and the DOM is identical with badges on or off.
 *
 * On a ROW the rule is vertical and gets `self-stretch`: `align-self` overrides
 * the track's `items-*`, so the line spans the row's full height even when the
 * row is `items-center`.
 */
const interleaveDividers = (children: ReactNode, axis: "vertical" | "horizontal") => {
    const nodes = React.Children.toArray(children)
    // `axis` = the TRACK's direction; a rule always runs ACROSS it.
    const ruleOrientation = axis === "vertical" ? "horizontal" : "vertical"
    return nodes.flatMap((child, index) =>
        index === 0
            ? [child]
            : [
                <Divider
                    key={`stack-divider-${index}`}
                    orientation={ruleOrientation}
                    classNames={ruleOrientation === "vertical" ? ["self-stretch"] : undefined}
                />,
                child,
            ],
    )
}

/**
 * Vertical track -- the default way to stack anything down a column.
 *
 * @param props - {@link StackVProps}
 */
const StackV = ({
    as: Tag,
    inline,
    gap,
    align = "stretch",
    justify,
    divider = false,
    nested = false,
    body,
    items,
    isSkeleton,
    padding,
    classNames,
    principle,
    explain,
    identity}: StackVProps) => {
    // `items` (buildable) wins over legacy `body`: the track renders each item itself, threading
    // `isSkeleton`, so it can shimmer the whole column and interleave dividers on the real children.
    const content = (items ?? (body ? [body] : [])).map((Item, index) => <Item key={index} isSkeleton={isSkeleton} />)
    // Strict contract: when `principle` is set it owns the full CSS — do not forward
    // gap/padding/align/justify/classNames/inline/nested from the caller.
    if (principle) {
        return (
            <Flex
                as={Tag}
                direction="col"
                principle={principle}
                explain={explain}
                identity={identity}
                body={divider ? interleaveDividers(content, "vertical") : content}
            />
        )
    }
    return (
        <Flex
            as={Tag}
            inline={inline}
            direction="col"
            gap={gap}
            padding={padding}
            align={align}
            justify={justify}
            nested={nested}
            classNames={classNames}
            identity={identity}
            body={divider ? interleaveDividers(content, "vertical") : content}
        />
    )
}

const StackH = ({
    as: Tag,
    inline,
    gap,
    align = "center",
    justify,
    at,
    divider = false,
    nested = false,
    body,
    items,
    isSkeleton,
    padding,
    classNames,
    principle,
    explain,
    identity}: StackHProps) => {
    const content = (items ?? (body ? [body] : [])).map((Item, index) => <Item key={index} isSkeleton={isSkeleton} />)
    if (principle) {
        return (
            <Flex
                as={Tag}
                direction="row"
                principle={principle}
                explain={explain}
                identity={identity}
                // `at` is a named width switch (FRAME-10), not a free CSS boolean — still forwarded.
                at={at}
                body={divider ? interleaveDividers(content, "horizontal") : content}
            />
        )
    }
    return (
        <Flex
            as={Tag}
            inline={inline}
            direction="row"
            gap={gap}
            padding={padding}
            align={align}
            justify={justify}
            at={at}
            nested={nested}
            classNames={classNames}
            identity={identity}
            body={divider ? interleaveDividers(content, "horizontal") : content}
        />
    )
}

export { StackV, StackH }

/**
 * Source-level tier marker -- lets a gate read the tier without guessing from the folder path.
 *
 * Shaped as a record, not the single `{ tier, name }` most frame files export: this file has
 * TWO public components, not one, and neither is more "the" component this file names. See
 * `Flex`'s own `meta` note for the DOM side of this -- `StackV`/`StackH` render no element
 * of their own (100% delegated to `Flex`), so `data-component` on a rendered Stack instance
 * reads `"Flex"`, not `"StackV"`/`"StackH"`; this export is the source-level identity, which a
 * gate can still read even though the DOM cannot show it.
 */
export const meta = {
    StackV: { tier: "frame", name: "StackV" },
    StackH: { tier: "frame", name: "StackH" },
} as const

import React from "react"
import { cn } from "../../../_cn"

/** Colour role of a {@link ChunkyButton}. */
export type ChunkyTone = "pink" | "sun" | "ink"

/** Hard-shadow colour cast behind the button — ink on light surfaces, cream on the dark banner. */
export type ChunkyShadow = "ink" | "cream"

/** Props for {@link ChunkyButton}. */
export interface ChunkyButtonProps {
    /** Button label (and any inline nodes). */
    children: React.ReactNode
    /** Destination — the marketing button is always a link. */
    href: string
    /** Colour role: `pink` (primary CTA, white text), `sun` (secondary, ink text), `ink` (reserved). */
    tone?: ChunkyTone
    /** `md` for nav/inline CTAs, `lg` for the hero and closing-banner CTAs. */
    size?: "md" | "lg"
    /** Colour of the offset hard shadow; `cream` for the button sitting on the dark banner. */
    shadow?: ChunkyShadow
    /** Trailing icon slot — typically an arrow or a play triangle. */
    endIcon?: React.ReactNode
    /** Placement class from the caller (e.g. width). Appearance stays owned here. */
    className?: string
}

const TONE: Record<ChunkyTone, string> = {
    pink: "bg-[var(--nb-pink)] text-white",
    sun: "bg-[var(--nb-sun)] text-[var(--nb-ink)]",
    ink: "bg-[var(--nb-ink)] text-[var(--nb-cream)]",
}

const SIZE: Record<"md" | "lg", string> = {
    md: "px-6 py-3",
    lg: "px-8 py-4 text-lg",
}

const SHADOW: Record<ChunkyShadow, string> = {
    ink: "shadow-[4px_4px_0_0_var(--nb-ink)] hover:shadow-[5px_5px_0_0_var(--nb-ink)] active:shadow-[2px_2px_0_0_var(--nb-ink)]",
    cream: "shadow-[4px_4px_0_0_var(--nb-cream)] hover:shadow-[5px_5px_0_0_var(--nb-cream)] active:shadow-[2px_2px_0_0_var(--nb-cream)]",
}

/**
 * The neo-brutalist CTA: a chunky, hard-shadowed link that lifts on hover and presses
 * down on click. It is the ONE interactive value the whole marketing surface repeats —
 * nav, hero, feature links and the closing banner all reach for it — so its border,
 * shadow and press motion live in exactly one place. Purely presentational: it renders
 * an `<a>` from props, holds no state, and consumes only `var(--nb-*)` tokens.
 *
 * Colour is a ROLE (`tone`), never a hex at the call site: `pink` is the primary CTA,
 * `sun` the secondary. The offset shadow flips to `cream` for the single button that
 * sits on the dark banner, where an ink shadow would vanish.
 *
 * @param props - {@link ChunkyButtonProps}
 * @see Story: .storybook/stories/mia-mia/atoms/buttons/ChunkyButton/ChunkyButton.stories
 */
export const ChunkyButton = ({
    children,
    href,
    tone = "pink",
    size = "md",
    shadow = "ink",
    endIcon,
    className,
}: ChunkyButtonProps) => (
    <a
        href={href}
        className={cn(
            "inline-flex items-center gap-2 rounded-2xl border-2 border-[var(--nb-ink)] font-extrabold",
            "transition hover:-translate-x-[1px] hover:-translate-y-[1px] active:translate-x-[2px] active:translate-y-[2px]",
            TONE[tone],
            SIZE[size],
            SHADOW[shadow],
            className,
        )}
    >
        {children}
        {endIcon}
    </a>
)

import React from "react"
import { cn } from "../../../_cn"

/** Colour role of an {@link NbPill}. */
export type NbPillTone = "sun" | "white" | "pink" | "mint" | "blush" | "ink"

/** Props for {@link NbPill}. */
export interface NbPillProps {
    /** Pill label (and any inline nodes). */
    children: React.ReactNode
    /** Fill colour role. */
    tone?: NbPillTone
    /** `round` for a full radius, `soft` for a rounded rectangle. */
    shape?: "round" | "soft"
    /** `sm` = compact meta/status tag, `md` = the hero eyebrow. */
    size?: "sm" | "md"
    /** Leading icon slot (e.g. the eyebrow star). */
    icon?: React.ReactNode
    /** Whether to draw the 2px ink border. */
    bordered?: boolean
    /** Whether to cast the offset hard shadow. */
    shadow?: boolean
    /** Placement class from the caller. */
    className?: string
}

const TONE: Record<NbPillTone, string> = {
    sun: "bg-[var(--nb-sun)] text-[var(--nb-ink)]",
    white: "bg-white text-[var(--nb-ink)]",
    pink: "bg-[var(--nb-pink)] text-white",
    mint: "bg-[var(--nb-mint)] text-[var(--nb-ink)]",
    blush: "bg-[var(--nb-blush)] text-[var(--nb-ink)]",
    ink: "bg-[var(--nb-ink)] text-[var(--nb-cream)]",
}

const SIZE: Record<"sm" | "md", string> = {
    sm: "px-2 py-0.5 text-xs",
    md: "px-4 py-2 text-sm",
}

/**
 * The neo-brutalist pill: a small bordered, optionally hard-shadowed label. It is the
 * marketing surface's smallest labelled value — the hero eyebrow, a card's meta tag
 * (`50 questions · 60′`), a status chip (`Submitted`). Extracting it keeps the blocks and cards
 * free of hand-rolled chip chrome and off-scale padding. Purely presentational: props
 * in, `var(--nb-*)` out, no state.
 *
 * Colour is a `tone` role; `shape`, `size`, `bordered` and `shadow` cover the two shapes
 * that recur — a shadowed sunny eyebrow and a flat white meta tag.
 *
 * @param props - {@link NbPillProps}
 * @see Story: .storybook/stories/mia-mia/atoms/data-display/NbPill/NbPill.stories
 */
export const NbPill = ({
    children,
    tone = "white",
    shape = "round",
    size = "md",
    icon,
    bordered = true,
    shadow = false,
    className,
}: NbPillProps) => (
    <span
        className={cn(
            "inline-flex w-fit items-center gap-2 font-bold",
            shape === "round" ? "rounded-full" : "rounded-lg",
            bordered && "border-2 border-[var(--nb-ink)]",
            shadow && "shadow-[4px_4px_0_0_var(--nb-ink)]",
            TONE[tone],
            SIZE[size],
            className,
        )}
    >
        {icon}
        {children}
    </span>
)

"use client"

import React from "react"
import Link from "next/link"
import { Button, Spinner, Typography, cn } from "@heroui/react"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { UserAvatar } from "@/components/blocks/identity/UserAvatar"

/** Props for {@link FriendRow}. */
export interface FriendRowProps extends WithClassNames<undefined> {
    /** Account username; drives the avatar fallback and the `@handle` default. */
    username: string
    /** Human-friendly name shown as the primary (linked) label; falls back to {@link FriendRowProps.username}. */
    displayName?: string | null
    /** Uploaded avatar URL; resilient fallbacks are handled by {@link UserAvatar}. */
    avatar?: string | null
    /** Secondary handle line (e.g. `@username`); hidden when omitted. */
    handle?: string
    /** Route the NAME links to — typically the user's public profile. */
    profileHref: string
    /** Presence dot: green when online, muted grey when offline. */
    isOnline?: boolean
    /** Accessible label for the presence dot when online. */
    onlineLabel?: string
    /** Accessible label for the presence dot when offline. */
    offlineLabel?: string
    /** Whether the viewer already follows this person; flips the action button. */
    isFollowing: boolean
    /** In-flight state for the follow toggle; shows an inline spinner. */
    isPending?: boolean
    /** Button copy for the "not yet following" state (e.g. "Add friend"). */
    followLabel: string
    /** Button copy for the "already following" state (e.g. "Already friends"). */
    followingLabel: string
    /** Fired when the action button is pressed; the caller owns the follow mutation. */
    onToggleFollow: () => void
}

/**
 * Presentational friend/suggestion row: an avatar with a presence dot, a name that
 * links to the person's profile, an optional `@handle`, and a right-aligned
 * follow/unfollow action button. Pure and props-only — no store, no fetch. The
 * caller supplies the follow state and owns the mutation via
 * {@link FriendRowProps.onToggleFollow}; presence + copy are passed in so the block
 * stays store-free and locale-agnostic.
 *
 * Mirrors {@link import("@/components/composites/lists/UserCell").UserCell}'s
 * avatar+name layout but adds a linkable name and a presence dot, which UserCell
 * cannot express (its name is plain text and it has no presence slot).
 *
 * @param props - {@link FriendRowProps}
 *
 * @see Story: .storybook/stories/mia-mia/FriendRow/FriendRow.stories
 */
export const FriendRow = ({
    username,
    displayName,
    avatar,
    handle,
    profileHref,
    isOnline = false,
    onlineLabel,
    offlineLabel,
    isFollowing,
    isPending = false,
    followLabel,
    followingLabel,
    onToggleFollow,
    className,
}: FriendRowProps) => {
    const name = displayName ?? username

    return (
        <div className={cn("flex min-w-0 items-center gap-2", className)}>
            {/* Avatar + presence dot */}
            <div className="relative shrink-0">
                <UserAvatar username={username} avatar={avatar} seed={username} size="sm" />
                <span
                    aria-label={isOnline ? onlineLabel : offlineLabel}
                    className={cn(
                        "absolute -bottom-0.5 -right-0.5 size-3 rounded-full border-2 border-surface",
                        isOnline ? "bg-success" : "bg-muted",
                    )}
                />
            </div>

            {/* Linked name + optional handle */}
            <div className="flex min-w-0 flex-col gap-0">
                <Link href={profileHref} className="min-w-0">
                    <Typography
                        type="body-sm"
                        weight="medium"
                        truncate
                        className="leading-5 hover:underline"
                    >
                        {name}
                    </Typography>
                </Link>
                {handle ? (
                    <Typography type="body-xs" color="muted" truncate className="leading-4">
                        {handle}
                    </Typography>
                ) : null}
            </div>

            {/* Follow / unfollow action */}
            <div className="ml-auto shrink-0">
                <Button
                    size="sm"
                    variant={isFollowing ? "outline" : "primary"}
                    isPending={isPending}
                    onPress={onToggleFollow}
                >
                    {isPending ? (
                        // isPending does NOT render its own spinner in this HeroUI build —
                        // supply one by hand so the button reads as busy.
                        <span className="inline-flex items-center gap-2">
                            <Spinner size="sm" color="current" />
                            {isFollowing ? followingLabel : followLabel}
                        </span>
                    ) : isFollowing ? (
                        followingLabel
                    ) : (
                        followLabel
                    )}
                </Button>
            </div>
        </div>
    )
}

import React from "react"
import { Chip, cn, Typography } from "@heroui/react"
import { MedalIcon } from "@phosphor-icons/react"
import { UserAvatar } from "@/components/blocks/identity/UserAvatar"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** One stat cell (value over a muted label) in the {@link ProfileHero} stats row. */
const HeroStat = ({ value, label }: { value: React.ReactNode, label: string }) => (
    <div className="flex flex-col items-center gap-1 text-center">
        <Typography type="body" weight="semibold" className="leading-none text-foreground">
            {value}
        </Typography>
        <Typography type="body-xs" color="muted">{label}</Typography>
    </div>
)

/** Props for {@link ProfileHero}. */
export interface ProfileHeroProps extends WithClassNames<undefined> {
    /** Account username; drives the avatar fallback and the `@handle` line. */
    username: string
    /** Human-friendly name shown as the primary label; falls back to {@link ProfileHeroProps.username}. */
    displayName?: string | null
    /** Uploaded avatar URL; resilient fallbacks handled by {@link UserAvatar}. */
    avatar?: string | null
    /** Short bio / tagline shown under the name; hidden when absent. */
    bio?: string | null
    /** Followers count; renders a `—` placeholder when `null`/`undefined`. */
    followerCount?: number | null
    /** Following count; renders a `—` placeholder when `null`/`undefined`. */
    followingCount?: number | null
    /** Label for the followers stat (caller-localized). */
    followersLabel: string
    /** Label for the following stat (caller-localized). */
    followingLabel: string
    /** Rank badge text (e.g. "Gold Rank"); the chip is hidden when absent. */
    rankLabel?: string | null
    /** Right-aligned action slot — typically the follow toggle button. */
    action?: React.ReactNode
}

/**
 * Public-profile hero: a large {@link UserAvatar} beside the display name over its
 * `@username`, an optional bio, a rank badge, a followers/following stats row, and a
 * caller-supplied action slot (the follow toggle). Purely presentational and
 * props-only — no store, data, or router access; the owning FEATURE fetches the user
 * and supplies the localized labels and the follow control via
 * {@link ProfileHeroProps.action}.
 *
 * A missing follower/following count renders `—` rather than `0`, so an unimplemented
 * backend field reads as "unknown" instead of "none".
 *
 * @param props - {@link ProfileHeroProps}
 * @see Story: .storybook/stories/mia-mia/ProfileHero/ProfileHero.stories
 */
export const ProfileHero = ({
    username,
    displayName,
    avatar,
    bio,
    followerCount,
    followingCount,
    followersLabel,
    followingLabel,
    rankLabel,
    action,
    className,
}: ProfileHeroProps) => {
    const name = displayName ?? username
    const fmt = (value?: number | null) =>
        value == null ? "—" : value.toLocaleString()

    return (
        <div
            className={cn(
                "flex flex-col gap-4 rounded-3xl border border-default bg-surface p-4",
                className,
            )}
        >
            <div className="flex items-start gap-4">
                <UserAvatar
                    username={username}
                    avatar={avatar}
                    seed={username}
                    size="lg"
                    className="size-20 shrink-0"
                />
                <div className="flex min-w-0 flex-1 flex-col gap-1">
                    <Typography type="h4" truncate className="text-foreground">
                        {name}
                    </Typography>
                    <Typography type="body-sm" color="muted" truncate>
                        @{username}
                    </Typography>
                    {rankLabel ? (
                        <Chip size="sm" variant="soft" color="accent" className="mt-1 w-fit gap-1">
                            <MedalIcon weight="fill" className="size-3.5" aria-hidden focusable="false" />
                            {rankLabel}
                        </Chip>
                    ) : null}
                </div>
                {action ? <div className="shrink-0">{action}</div> : null}
            </div>

            {bio ? (
                <Typography type="body-sm" className="text-foreground">
                    {bio}
                </Typography>
            ) : null}

            <div className="flex items-center gap-6 border-t border-separator pt-3">
                <HeroStat value={fmt(followerCount)} label={followersLabel} />
                <div className="h-8 w-px bg-separator" />
                <HeroStat value={fmt(followingCount)} label={followingLabel} />
            </div>
        </div>
    )
}

"use client"

import React from "react"
import {
    CollapsibleSidebar,
} from "@/components/blocks/navigation/CollapsibleSidebar"
import {
    SidebarNavGroup,
} from "@/components/blocks/navigation/SidebarNavGroup"
import {
    SidebarNavItem,
} from "@/components/blocks/navigation/SidebarNavItem"
import type {
    WithClassNames,
} from "@/modules/types/base/class-name"

/** One navigable destination in the dashboard sidebar. */
export interface DashboardNavItem {
    /** Stable key. */
    key: string
    /** Route this row navigates to (compared against `activeHref` for the highlight). */
    href: string
    /** Visible label. */
    label: string
    /** Leading icon. */
    icon: React.ReactNode
    /** Optional trailing badge (e.g. a count or a lock). */
    endContent?: React.ReactNode
}

/** A labelled cluster of rows, divided from the group above it. */
export interface DashboardNavGroup {
    /** Stable key. */
    key: string
    /** Uppercase caption (omit for an unlabelled group). */
    label?: string
    /** Rows in display order. */
    items: Array<DashboardNavItem>
}

/** Props for the {@link DashboardSidebar} block. */
export interface DashboardSidebarProps extends WithClassNames<undefined> {
    /** Heading in the panel header (product name / section). */
    title: string
    /** Grouped navigation rows. */
    groups: Array<DashboardNavGroup>
    /** The current route — the row whose `href` equals this gets the accent fill. */
    activeHref: string
    /** Fired with a row's `href` when it is activated (the caller navigates). */
    onNavigate: (href: string) => void
    /** Accessible label for the collapse toggle. */
    collapseLabel: string
    /** Accessible label for the expand toggle. */
    expandLabel: string
    /** localStorage key under which the collapsed flag persists. */
    storageKey: string
    /** Optional node pinned above the scrollable nav (e.g. a resume pill). */
    topSlot?: React.ReactNode
}

/**
 * The dashboard's left navigation shell: a {@link CollapsibleSidebar} filled with
 * grouped {@link SidebarNavItem} rows. Purely presentational — it owns no routing
 * and no data: the caller feeds the grouped nav model, marks the active route with
 * `activeHref`, and navigates in `onNavigate`. Active highlight is `href ===
 * activeHref`; the collapse chrome, persistence and the icon rail all come from
 * {@link CollapsibleSidebar}. Pair the connected half (router + nav config) in a
 * feature layout.
 *
 * @param props - {@link DashboardSidebarProps}
 * @see Story: .storybook/stories/mia-mia/DashboardSidebar/DashboardSidebar.stories
 */
export const DashboardSidebar = ({
    title,
    groups,
    activeHref,
    onNavigate,
    collapseLabel,
    expandLabel,
    storageKey,
    topSlot,
    className,
}: DashboardSidebarProps) => {
    return (
        <CollapsibleSidebar
            title={title}
            collapseLabel={collapseLabel}
            expandLabel={expandLabel}
            storageKey={storageKey}
            topSlot={topSlot}
            className={className}
        >
            {groups.map((group, index) => (
                <SidebarNavGroup key={group.key} label={group.label} divider={index > 0}>
                    {group.items.map((item) => (
                        <SidebarNavItem
                            key={item.key}
                            icon={item.icon}
                            label={item.label}
                            endContent={item.endContent}
                            isActive={item.href === activeHref}
                            onPress={() => onNavigate(item.href)}
                        />
                    ))}
                </SidebarNavGroup>
            ))}
        </CollapsibleSidebar>
    )
}

