                                            <InputText
                                                variant="secondary"
                                                label={labels.displayNameLabel}
                                                value={displayName}
                                                onValueChange={onDisplayNameChange}
                                            />
                                        ),
                                        () => (
                                            <InputText
                                                variant="secondary"
                                                label={labels.headlineLabel}
                                                value={headline}
                                                onValueChange={onHeadlineChange}
                                            />
                                        ),
                                        () => (
                                            <InputTextarea
                                                variant="secondary"
                                                label={labels.bioLabel}
                                                rows={4}
                                                value={bio}
