                    ({ isSkeleton: skeleton }: SkeletonProps) => (
                        <InputText isSkeleton={skeleton} value="" onValueChange={() => {}} label="" />
                    ),
                    ({ isSkeleton: skeleton }: SkeletonProps) => (
                        <InputText isSkeleton={skeleton} value="" onValueChange={() => {}} label="" />
                    ),
                    ({ isSkeleton: skeleton }: SkeletonProps) => (
                        <InputTextarea isSkeleton={skeleton} value="" onValueChange={() => {}} label="" />
                    ),
                ]}
            />
        )}
    />
)

