    heightPercent: number
}

/** One stage row of the illustrative pipeline. */
export interface DashboardProofPipelineStage {
    /** Stable React key. */
    key: string
    /** Stage name (e.g. "New lead"). */
    label: string
    /** Illustrative fill, 0–100 — a mockup shape, never a real conversion rate. */
