 */
const DashboardProof = ({
    eyebrow,
    title,
    panelLabel,
    insightLabel,
    metrics,
    activityAriaLabel,
    activityBars,
    pipelineLabel,
    pipelineStages,
    disclaimer,
}: DashboardProofProps) => {
    const panelBodyItems = [
        () => <TopBar panelLabel={panelLabel} insightLabel={insightLabel} />,
        () => (
            <Grid
                columns={{ base: 1, lg: 2 }}
