                        ),
                    },
                ]}
            />
        ),
    ]

    return (
        <div data-tier="block" data-component="DashboardProof">
            <StackV
                gap={6}
                principle="block-boundary"
                items={[
                    () => <SectionHeading eyebrow={eyebrow} title={title} align="center" />,
