    description: string
    /** `true` → this entry names a roadmap layer, not a buyable product — rendered in the warning tone. */
    isRoadmap?: boolean
    /** Fired when this row is pressed — the caller routes to the real product or the audit. */
    onPress: () => void
}

/** Props for {@link MegaMenu}. */
