    <StackV
        gap={1}
        align="center"
        principle="name-handle"
        items={[
            () => <Typography size="h3" weight="bold" align="center" text={value} />,
            () => <Typography size="sm" color="muted" align="center" text={label} />,
        ]}
    />
)

/**
