import type { ExpertSiteTemplateKey } from "@sb-components/nivo/blocks/expert-site/ExpertSiteGenerate/ExpertSiteGenerate"

/**
 * `ExpertSiteView` — the PAGE a visitor sees at `<slug>.nivo.vn`. A page is a
 * list of functions: hero, bio, offerings grid, embedded lead form, arranged in
 * frames. `templateKey` picks the section ORDER. A page's story is one complete
 * STATE per story — `loading`, `empty`, `content` — not a leaf-per-prop map.
 * Grounded in the real `ExpertSiteView`; maps onto `ExpertSiteEntity`.
 */

/** One published offering — a subset of `ExpertSiteOfferingEntity`. */
export interface ExpertSiteViewOffering {
    /** Offering id. */
    id: string
    /** Offering title. */
    title: string
    /** One-line subtitle, or null. */
    subtitle?: string | null
    /** Longer description, or null. */
    description?: string | null
    /** Display price, or null (free text — nothing transacts). */
    priceText?: string | null
    /** CTA button label, or null → a default label. */
    ctaLabel?: string | null
    /** CTA target, or null → the card shows no button. */
    ctaUrl?: string | null
    /** Fires when the CTA is pressed — the connected layer opens the link. */
    onCtaPress?: () => void
}

/** The presentation content of the site — mirrors `ExpertSiteConfig`. */
export interface ExpertSiteViewConfig {
    /** Expert's display name shown in the hero. */
    displayName?: string | null
    /** One-line positioning statement under the name. */
    headline?: string | null
    /** Longer free-text introduction. */
    bio?: string | null
    /** Absolute URL of the expert's avatar image. */
    avatarUrl?: string | null
    /** Accent hue (oklch hue, 0-360) — remapped onto the `--accent` token. */
    accentHue?: number | null
    /** Which industry template lays the site out. */
    templateKey?: ExpertSiteTemplateKey | null
}

/** Props for {@link ExpertSiteView}. */
export interface ExpertSiteViewProps {
    /** The subdomain label — the fallback name when `config.displayName` is empty. */
    slug: string
    /** Presentation content, or `null` when the site has never been filled in. */
    config: ExpertSiteViewConfig | null
    /** Published offerings, in order. */
    offerings: Array<ExpertSiteViewOffering>
    /** Forwarded to the embedded {@link ExpertSiteLeadForm}. */
    leadForm: ExpertSiteLeadFormProps
    /** Already-localized copy for the page's own sections. */
    labels: ExpertSiteViewLabels
    /** `true` → the page is still loading; the skeleton mirror is shown. */
    isLoading?: boolean
}

/** The already-resolved copy the page renders. */
export interface ExpertSiteViewLabels {
    /** Heading above the offerings grid. */
    offeringsTitle: string
    /** Heading above the contact form (falls back for `config.ctaLabel`). */
    contactTitle: string
    /** Default CTA label when an offering supplies none. */
    defaultOfferingCta: string
    /** Footer "powered by" line. */
    poweredBy: string
    /** Empty-state title (a claimed slug with no content). */
    emptyTitle: string
    /** Empty-state supporting line. */
    emptyDescription: string
}

/** How many offering placeholders the skeleton draws. */
const SKELETON_OFFERING_COUNT = 2

/** Maps a config hue onto the `--accent` token so every accent atom picks up the site's colour. */
const accentStyleOf = (config: ExpertSiteViewConfig | null): CSSProperties | undefined =>
    config?.accentHue != null
        ? ({ "--accent": `oklch(0.62 0.19 ${config.accentHue})` } as CSSProperties)
        : undefined

/**
 * The public site page. See the file header for why the sections are functions
 * this page names and why the story is one state per render.
 *
 * @param props - {@link ExpertSiteViewProps}
 */
const ExpertSiteView = ({ slug, config, offerings, leadForm, labels, isLoading = false }: ExpertSiteViewProps) => {
    const shell = (children: ReactNode, style?: CSSProperties) => (
        <div
            data-tier="page"
            data-component="ExpertSiteView"
            style={style}
            className="mx-auto flex w-full max-w-2xl flex-col gap-8 px-4 py-12"
        >
            {children}
        </div>
    )

    // ── LOADING state: the skeleton mirror, so nothing jumps when the site resolves.
    if (isLoading) {
        return shell(
            <StackV
                gap={8}
                items={[
                    () => (
                        <StackV
                            gap={3}
                            principle="sibling-stack"
                            align="center"
                            items={[
                                () => <Avatar isSkeleton size="lg" />,
                                () => <Typography size="h2" isSkeleton />,
                                () => <Typography size="sm" isSkeleton />,
                            ]}
                        />
                    ),
                    () => <SurfaceCard isSkeleton padding={3} body={() => <Typography size="sm" isSkeleton />} />,
                    () => (
                        <Grid
                            columns={{ base: 1, sm: 2 }}
                            principle="sibling-stack"
                            isSkeleton
                            items={Array.from({ length: SKELETON_OFFERING_COUNT }, (_unused, index) => ({
                                key: `offering-skeleton-${index}`,
                                content: ({ isSkeleton: skeleton }: SkeletonProps) => (
                                    <SurfaceCard
                                        variant="nested"
                                        padding={3}
                                        isSkeleton={skeleton}
                                        body={() => <Typography size="sm" isSkeleton />}
                                    />
                                ),
                            }))}
                        />
                    ),
                    () => <ExpertSiteLeadFormSkeleton isSkeleton />,
                ]}
            />,
        )
    }

    // ── EMPTY state: a claimed slug the owner has not filled in yet.
    if (config == null) {
        return shell(
            <EmptyState size="page" title={labels.emptyTitle} description={labels.emptyDescription} />,
        )
    }

    const displayName = config.displayName?.trim() || slug
    const template = config.templateKey ?? "minimal"

    const hero = (
        <StackV
            key="hero"
            gap={3}
            principle="sibling-stack"
            align="center"
            items={[
                () => <Avatar size="lg" name={displayName} src={config.avatarUrl ?? undefined} fallback="initials" />,
                () => <Typography size="h2" weight="bold" align="center" text={displayName} />,
                ...(config.headline
                    ? [() => <Typography size="base" color="accent" align="center" text={config.headline ?? ""} />]
                    : []),
            ]}
        />
    )

    const bio = config.bio ? (
        <SurfaceCard
            key="bio"
            padding={3}
            body={() => <Typography size="sm" color="muted" preserveWhitespace text={config.bio ?? ""} />}
        />
    ) : null

    const offeringsSection = offerings.length > 0 ? (
        <StackV
            key="offerings"
            gap={3}
            principle="sibling-stack"
            items={[
                () => <Typography size="base" weight="semibold" text={labels.offeringsTitle} />,
                () => (
                    <Grid
                        columns={{ base: 1, sm: 2 }}
                        principle="sibling-stack"
                        items={offerings.map((offering) => ({
                            key: offering.id,
                            content: () => (
                                <SurfaceCard
                                    variant="nested"
                                    padding={3}
                                    body={() => (
                                        <StackV
                                            gap={2}
                                            items={[
                                                () => <Typography size="sm" weight="semibold" text={offering.title} />,
                                                ...(offering.subtitle
                                                    ? [() => <Typography size="xs" color="muted" text={offering.subtitle ?? ""} />]
                                                    : []),
                                                ...(offering.description
                                                    ? [() => <Typography size="sm" preserveWhitespace text={offering.description ?? ""} />]
                                                    : []),
                                                ...(offering.priceText
                                                    ? [() => <Typography size="sm" weight="medium" color="accent" text={offering.priceText ?? ""} />]
                                                    : []),
                                                ...(offering.ctaUrl
                                                    ? [
                                                        () => (
                                                            <Button
                                                                variant="primary"
                                                                size="sm"
                                                                label={offering.ctaLabel || labels.defaultOfferingCta}
                                                                onPress={offering.onCtaPress}
                                                            />
                                                        ),
                                                    ]
                                                    : []),
                                            ]}
                                        />
                                    )}
                                />
                            ),
                        }))}
                    />
                ),
            ]}
        />
    ) : null

    const contact = (
        <SurfaceCard
            key="contact"
            padding={3}
            label={labels.contactTitle}
            body={() => <ExpertSiteLeadForm {...leadForm} />}
        />
    )

    // The template decides section ORDER + emphasis; the sections are shared, so a
    // template is a layout choice, not a separate renderer (mirrors real `src`).
    const sections =
        template === "creator"
            ? [hero, offeringsSection, bio, contact]
            : template === "consultant"
                ? [hero, contact, offeringsSection, bio]
                : [hero, bio, offeringsSection, contact]

    return shell(
        <>
            {sections.filter((section) => section != null)}
            <Typography size="xs" color="muted" align="center" text={labels.poweredBy} />
        </>,
        accentStyleOf(config),
    )
}

export { ExpertSiteView }

/** Source-level tier marker — lets a gate read the tier without guessing from the folder path. */
export const meta = { tier: "page", name: "ExpertSiteView" } as const

import type { ReactNode } from "react"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { StackV } from "@sb-components/frames/Stack/Stack"
import {
    InvoiceDetailModal,
    type InvoiceDetailModalInvoice,
    type InvoiceDetailModalLabels,
} from "@sb-components/nivo/blocks/billing/InvoiceDetailModal/InvoiceDetailModal"
import {
    InvoiceList,
    type InvoiceListLabels,
    type InvoiceRow,
} from "@sb-components/nivo/blocks/billing/InvoiceList/InvoiceList"

/**
 * `InvoicesView` — the PAGE at `/invoices`: every invoice raised from the
 * catalog (a new order or a renewal), across all three statuses. Each row
 * opens its own `InvoiceDetailModal` (`InvoiceList`'s `onOpenInvoice`), while
 * the row's own Pay button stays independently pressable for a fast unpaid
 * settle without leaving the list. A page is a list of functions: this one
 * NAMES `InvoiceList` above `InvoiceDetailModal` — nothing drawn inline beyond
 * the section heading. Grounded in the real `InvoiceEntity`
 * (`status: unpaid | paid | cancelled`,
 * `purpose: catalog_order | catalog_upgrade | catalog_renewal`); the item name
 * is resolved off each invoice's linked `CatalogOrderEntity.catalogItem`.
 *
 * `InvoiceDetailModal` is composed HERE for the same reason `CatalogView`
 * composes `BuyConfirmModal`: one short-lived modal, one row action that opens
 * it, no reason to split the open/selection state out to a separate mount
 * point. That state still arrives as PROPS (`detail.isOpen`/`detail.invoice`),
 * owned by the connected layer or a story's `Controlled` wrapper — this file
 * stays a pure function of its props.
 *
 * A page's story is one complete STATE per story — `loading`, `empty`
 * (a brand-new account with nothing billed yet, the critical case — a clear
 * path back to the catalog), `with-invoices` — not a leaf-per-prop map.
 */

/** Already-localized copy for every region this page arranges. */
export interface InvoicesViewLabels {
    /** Page heading (e.g. "Invoices"). */
    title: string
    /** Subtitle under the heading. */
    subtitle: string
    /** Forwarded to `InvoiceList`. */
    list: InvoiceListLabels
    /** Forwarded to `InvoiceDetailModal`. */
    detail: InvoiceDetailModalLabels
}

/** The `InvoiceDetailModal` region — its own props minus `labels`, which the page forwards from `labels.detail`. */
export interface InvoicesViewDetail {
    /** Whether the modal is open. */
    isOpen: boolean
    /** The invoice being read, or null before any row has been opened. */
    invoice: InvoiceDetailModalInvoice | null
    /** Open-state change handler. */
    onOpenChange: (open: boolean) => void
    /** Pay the open invoice. */
    onPay: () => void
    /** `true` → the checkout is in flight. */
    isPaying?: boolean
}

/** Props for {@link InvoicesView}. */
export interface InvoicesViewProps {
    /** The invoices, newest first. */
    invoices: Array<InvoiceRow>
    /** Pay one still-unpaid invoice directly from the list row — the connected layer runs the checkout. */
    onPayInvoice: (invoiceId: string) => void
    /** Open one invoice's own detail — the connected layer populates `detail.invoice` and opens it. */
    onOpenInvoice: (invoiceId: string) => void
    /** The invoice-detail modal's own state. */
    detail: InvoicesViewDetail
    /** Already-localized copy. */
    labels: InvoicesViewLabels
    /** `true` → the page is still loading; the skeleton mirror is shown. */
    isSkeleton?: boolean
}

/**
 * The invoices page. See the file header for why `InvoiceDetailModal` is
 * composed here rather than left for a caller to mount.
 *
 * @param props - {@link InvoicesViewProps}
 */
const InvoicesView = ({ invoices, onPayInvoice, onOpenInvoice, detail, labels, isSkeleton = false }: InvoicesViewProps) => {
    const shell = (children: ReactNode) => (
        <div data-tier="page" data-component="InvoicesView" className="mx-auto flex w-full max-w-3xl flex-col gap-8 px-4 py-8">
            {children}
        </div>
    )

    const heading = (
        <StackV
            gap={1}
            isSkeleton={isSkeleton}
            items={[
                () => <Typography size="h2" weight="bold" isSkeleton={isSkeleton} text={labels.title} />,
                () => <Typography size="sm" color="muted" isSkeleton={isSkeleton} text={labels.subtitle} />,
            ]}
        />
    )

    // ── LOADING: the heading plus the list's own skeleton mirror.
    if (isSkeleton) {
        return shell(
            <StackV
                gap={6}
                items={[
                    () => heading,
                    () => <InvoiceList invoices={[]} onPay={() => {}} labels={labels.list} isSkeleton />,
                ]}
            />,
        )
    }

    return shell(
        <>
            <StackV
                gap={6}
                items={[
                    () => heading,
                    () => (
                        <InvoiceList
                            invoices={invoices}
                            onPay={onPayInvoice}
                            onOpenInvoice={onOpenInvoice}
                            labels={labels.list}
                        />
                    ),
                ]}
            />
            <InvoiceDetailModal
                isOpen={detail.isOpen}
                onOpenChange={detail.onOpenChange}
                invoice={detail.invoice}
                onPay={detail.onPay}
                isPaying={detail.isPaying}
                labels={labels.detail}
            />
        </>,
    )
}

export { InvoicesView }

/** Source-level tier marker — lets a gate read the tier without guessing from the folder path. */
export const meta = { tier: "page", name: "InvoicesView" } as const

"use client"

import { useState } from "react"
import { Container } from "@sb-components/frames/Container/Container"
import { StackV } from "@sb-components/frames/Stack/Stack"
import { AuditCta, type AuditCtaProps } from "@sb-components/nivo/blocks/landing/AuditCta/AuditCta"
import { ClosingCta } from "@sb-components/nivo/blocks/landing/ClosingCta/ClosingCta"
import { DashboardProof, type DashboardProofProps } from "@sb-components/nivo/blocks/landing/DashboardProof/DashboardProof"
import { DemoFlow, type DemoFlowProps } from "@sb-components/nivo/blocks/landing/DemoFlow/DemoFlow"
import { FaqAccordion, type FaqAccordionItem } from "@sb-components/nivo/blocks/landing/FaqAccordion/FaqAccordion"
import { HumanInTheLoop, type HumanInTheLoopProps } from "@sb-components/nivo/blocks/landing/HumanInTheLoop/HumanInTheLoop"
import {
    OperatingLoopHero,
    type OperatingLoopHeroMetric,
    type OperatingLoopHeroTrustPoint,
} from "@sb-components/nivo/blocks/landing/OperatingLoopHero/OperatingLoopHero"
import type { OperatingLoopVisualNode } from "@sb-components/nivo/blocks/landing/OperatingLoopVisual/OperatingLoopVisual"
import { PartnerStrip, type PartnerStripProps } from "@sb-components/nivo/blocks/landing/PartnerStrip/PartnerStrip"
import {
    PricingTeaser,
    type PricingTeaserLabels,
    type PricingTeaserMode,
    type PricingTeaserProductRow,
} from "@sb-components/nivo/blocks/landing/PricingTeaser/PricingTeaser"
import { ProblemStatement, type ProblemStatementProps } from "@sb-components/nivo/blocks/landing/ProblemStatement/ProblemStatement"
import {
    ProductQuickSelector,
    type ProductQuickSelectorItem,
} from "@sb-components/nivo/blocks/landing/ProductQuickSelector/ProductQuickSelector"
import {
    ProductShowcase,
    type ProductShowcaseLabels,
    type ProductShowcaseRow,
} from "@sb-components/nivo/blocks/landing/ProductShowcase/ProductShowcase"
import { SectionHeading } from "@sb-components/nivo/blocks/landing/SectionHeading/SectionHeading"
import { SolutionByIndustry, type SolutionByIndustryProps } from "@sb-components/nivo/blocks/landing/SolutionByIndustry/SolutionByIndustry"
import { SystemFlow, type SystemFlowProps } from "@sb-components/nivo/blocks/landing/SystemFlow/SystemFlow"
import { SystemStoryCard, type SystemStoryCardProps } from "@sb-components/nivo/blocks/landing/SystemStoryCard/SystemStoryCard"

/**
 * `LandingPage` — the PAGE a guest lands on at `/`: the full V2 "operating
 * system" stack (brand §VII.2), reconciled to the real 2-product / 6-tier
 * catalog. A page's story is one complete STATE per story — `Content` (the
 * catalog resolved) and `Loading` (`ProductShowcase` + `PricingTeaser` in
 * their skeleton mirror; every other section is static and unaffected).
 */

/** The hero's resolved copy — {@link OperatingLoopHeroProps} minus its 3 CTA objects (labels only; `onPress` is supplied by this page's shared intents) and minus `flowNodes`'s own doc, unchanged. */
export interface LandingPageHero {
    /** Accent-toned kicker above the headline. */
    eyebrow: string
    /** The Big-Idea headline. */
    headline: string
    /** Supporting flow-sentence copy below the headline. */
    description: string
    /** Visible label for the single north-star primary CTA — into the catalog. */
    primaryLabel: string
    /** Visible label for the secondary CTA — into the Lead-Leakage Audit. */
    secondaryLabel: string
    /** Visible label for the tertiary CTA — a demo preview. */
    tertiaryLabel: string
    /** Short trust-microcopy fragments under the CTA row. */
    trustPoints: Array<OperatingLoopHeroTrustPoint>
    /** The flow rail's stages, forwarded to `OperatingLoopVisual`. */
    flowNodes: Array<OperatingLoopVisualNode>
    /** Which flow stage glows crimson. */
    activeFlowNodeId: string
    /** Mini dashboard card title. */
    dashboardTitle: string
    /** Small badge on the dashboard card. */
    dashboardBadgeLabel: string
    /** The dashboard card's KPI cells — illustrative values, never fabricated metrics. */
    dashboardMetrics: Array<OperatingLoopHeroMetric>
}

/** Resolved copy for the header above {@link ProductQuickSelector} — the block itself renders no heading. */
export interface LandingPageQuickSelectorHeading {
    /** Accent-toned kicker above the title. */
    eyebrow: string
    /** The section title (e.g. "Where do you want to start?"). */
    title: string
    /** Optional supporting intro line. */
    intro?: string
}

/** The problem beat's resolved copy — {@link ProblemStatementProps} minus the CTA callback (the page's shared `onAudit`). */
export type LandingPageProblem = Omit<ProblemStatementProps, "onCtaPress">

/** The system-flow beat — entirely static data, no callback of its own. */
export type LandingPageSystemFlow = SystemFlowProps

/** The product-showcase region's resolved rows + copy — {@link ProductShowcaseProps} minus its callbacks and `isSkeleton` (this page derives both). */
export interface LandingPageProductShowcase {
    /** The real catalog products, in display order. */
    products: Array<ProductShowcaseRow>
    /** Already-localized copy. */
    labels: ProductShowcaseLabels
}

/** The pricing-teaser region's resolved rows + copy — {@link PricingTeaserProps} minus its callbacks, controlled mode, and `isSkeleton`. */
export interface LandingPagePricing {
    /** The real catalog products, in display order. */
    products: Array<PricingTeaserProductRow>
    /** Already-localized copy. */
    labels: PricingTeaserLabels
}

/** The industry-solution matrix — entirely static data, no callback of its own. */
export type LandingPageSolutionByIndustry = SolutionByIndustryProps

/** The demo-flow card row — each step already carries its own `onPress`. */
export type LandingPageDemoFlow = DemoFlowProps

/** The human-in-the-loop beat's resolved copy — {@link HumanInTheLoopProps} minus the CTA callback (the page's shared `onDemo`). */
export type LandingPageHumanInTheLoop = Omit<HumanInTheLoopProps, "onCtaPress">

/** The dashboard UI mockup — entirely static, illustrative data. */
export type LandingPageDashboardProof = DashboardProofProps

/** The before/after case-study card — entirely static data. */
export type LandingPageSystemStory = SystemStoryCardProps

/** The audit CTA band's resolved copy — {@link AuditCtaProps} minus the CTA callback (the page's shared `onAudit`). */
export type LandingPageAuditCta = Omit<AuditCtaProps, "onCtaPress">

/** The ecosystem strip — entirely static data. */
export type LandingPagePartnerStrip = PartnerStripProps

/** Resolved copy for the FAQ section. */
export interface LandingPageFaq {
    /** Optional accent-toned kicker above the section title. */
    eyebrow?: string
    /** The section title. */
    title: string
    /** Optional supporting intro line. */
    intro?: string
    /** The FAQ entries, in display order. */
    items: Array<FaqAccordionItem>
}

/** The closing beat's resolved copy — both CTAs repeat the hero's own primary/secondary destinations. */
export interface LandingPageClosing {
    /** Optional accent-toned kicker above the title. */
    eyebrow?: string
    /** The beat's headline. */
    title: string
    /** Supporting intro line under the title. */
    description: string
    /** Visible label for the primary CTA — must read the same as the hero's. */
    primaryLabel: string
    /** Visible label for the secondary CTA — must read the same as the hero's. */
    secondaryLabel: string
}

/** Props for {@link LandingPage}. */
export interface LandingPageProps {
    /** The hero's resolved copy. */
    hero: LandingPageHero
    /** Resolved copy for the header above the quick-selector grid. */
    quickSelectorHeading: LandingPageQuickSelectorHeading
    /** The intent cards, already wired with their own `onPress`. */
    quickSelectorItems: Array<ProductQuickSelectorItem>
    /** The problem beat's resolved copy, including its composed `LeadLeakageMap`. */
    problem: LandingPageProblem
    /** The system-flow beat's resolved copy. */
    systemFlow: LandingPageSystemFlow
    /** The product-showcase region's resolved rows + copy. */
    productShowcase: LandingPageProductShowcase
    /** The pricing-teaser region's resolved rows + copy. */
    pricing: LandingPagePricing
    /** The industry-solution matrix's resolved copy. */
    solutionByIndustry: LandingPageSolutionByIndustry
    /** The demo-flow beat's resolved copy. */
    demoFlow: LandingPageDemoFlow
    /** The human-in-the-loop beat's resolved copy, including its composed `AiSuggestionCard`. */
    humanInTheLoop: LandingPageHumanInTheLoop
    /** The dashboard-proof mockup's resolved copy. */
    dashboardProof: LandingPageDashboardProof
    /** The system-story (case study) beat's resolved copy. */
    systemStory: LandingPageSystemStory
    /** The audit CTA band's resolved copy. */
    auditCta: LandingPageAuditCta
    /** The partner strip's resolved copy. */
    partnerStrip: LandingPagePartnerStrip
    /** The FAQ section's resolved copy. */
    faq: LandingPageFaq
    /** The closing beat's resolved copy. */
    closing: LandingPageClosing
    /** Fired by the hero primary, the closing primary, and the defensive "browse all" branch of both catalog-derived regions — the caller routes into the full `/catalog`. */
    onBrowseCatalog: () => void
    /** Fired by the hero secondary, the problem beat, the audit CTA band, the pricing solution tab, and the closing secondary — the caller routes to the Lead-Leakage Audit. */
    onAudit: () => void
    /** Fired by the hero tertiary and the human-in-the-loop CTA — the caller opens a live AI-Agent demo. */
    onDemo: () => void
    /** Fired with a product id from the product-showcase CTA — the caller routes into that product's pricing. */
    onSelectProduct: (productId: string) => void
    /** Fired with a product id from the pricing-teaser "see all plans" CTA — the caller routes into that product's pricing. */
    onViewPlans: (productId: string) => void
    /** `true` → the catalog's own first fetch is in flight: `ProductShowcase` and `PricingTeaser` render their skeleton mirror; every other section is static and renders straight away. */
    isSkeleton?: boolean
}

/**
 * The V2 landing page. See the file header for why exactly three shared
 * intents (`onBrowseCatalog` / `onAudit` / `onDemo`) cover every CTA on the
 * page, and why only two regions ever see `isSkeleton`.
 *
 * @param props - {@link LandingPageProps}
 */
const LandingPage = ({
    hero,
    quickSelectorHeading,
    quickSelectorItems,
    problem,
    systemFlow,
    productShowcase,
    pricing,
    solutionByIndustry,
    demoFlow,
    humanInTheLoop,
    dashboardProof,
    systemStory,
    auditCta,
    partnerStrip,
    faq,
    closing,
    onBrowseCatalog,
    onAudit,
    onDemo,
    onSelectProduct,
    onViewPlans,
    isSkeleton = false,
}: LandingPageProps) => {
    // Page-local UI state, not domain data — see the file header for why this
    // needs no connected half.
    const [pricingMode, setPricingMode] = useState<PricingTeaserMode>("product")

    return (
        <div data-tier="page" data-component="LandingPage" className="flex flex-col">
            <OperatingLoopHero
                eyebrow={hero.eyebrow}
                headline={hero.headline}
                description={hero.description}
                primaryCta={{ label: hero.primaryLabel, onPress: onBrowseCatalog }}
                secondaryCta={{ label: hero.secondaryLabel, onPress: onAudit }}
                tertiaryCta={{ label: hero.tertiaryLabel, onPress: onDemo }}
                trustPoints={hero.trustPoints}
                flowNodes={hero.flowNodes}
                activeFlowNodeId={hero.activeFlowNodeId}
                dashboardTitle={hero.dashboardTitle}
                dashboardBadgeLabel={hero.dashboardBadgeLabel}
                dashboardMetrics={hero.dashboardMetrics}
            />

            {/* Quick selector — bare block, no heading of its own. */}
            <section className="px-6 py-16">
                <Container
                    size="xl"
                    padding={1}
                    body={() => (
                        <StackV
