import type { ReactNode } from "react"
import { ArrowClockwiseIcon, FlowArrowIcon, TreeStructureIcon } from "@phosphor-icons/react"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { Chip, type ChipTone } from "@sb-components/atoms/chips/Chip/Chip"
import { ChoiceSwitch } from "@sb-components/atoms/forms"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { SurfaceCard } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { Table, type TableColumnSpec, type TableRowItem } from "@sb-components/composites/data/Table/Table"
import { EmptyState } from "@sb-components/composites/feedback/EmptyState/EmptyState"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `N8nWorkflowTable` -- the "n8n workflows" tab. A table of the expert's workflows
 * (name - webhook - active toggle) plus a recent-executions list and a labelled
 * region standing in for the embedded n8n editor. The three phases -- `empty`,
 * `with-workflows`, `with-executions` -- are DATA, so they are STATES of the single
 * shape. Grounded in the real `N8nToolsService.listAll()` / `executions()` and
 * `setActive(id, active)` behind the toggle.
 */

/** One workflow row -- a subset of the real `listAll()` result. */
export interface WorkflowRowView {
    /** Workflow id in n8n. */
    id: string
    /** Readable workflow name (`N8nTool.description`). */
    name: string
    /** Webhook path that fires it, or null when it has no Webhook trigger (`N8nTool.webhookPath`). */
    webhookPath?: string | null
    /** Whether the workflow is active in n8n (`active` from `listAll()`). */
    active: boolean
}

/** The three execution statuses n8n reports. */
export type ExecutionStatus = "success" | "error" | "running"

/** One recent run -- a subset of the real `executions()` result. */
export interface ExecutionRowView {
    /** Execution id. */
    id: string
    /** Name of the workflow that ran (resolved from `workflowId`). */
    workflowName: string
    /** Run status (`execution.status`). */
    status: ExecutionStatus
    /** Already-formatted start time, or null when unknown (`execution.startedAt`). */
    startedAtLabel?: string | null
}

/** Props for {@link N8nWorkflowTable}. */
export interface N8nWorkflowTableProps {
    /** The workflows, in listing order. Empty is the `empty` state. */
    workflows: Array<WorkflowRowView>
    /** Recent runs, newest first. Empty hides the executions section. */
    executions: Array<ExecutionRowView>
    /** Turn a workflow on/off -- the connected layer runs `setActive(id, active)`. */
    onToggleWorkflow: (id: string, active: boolean) => void
    /** Id of the workflow whose toggle is in flight (its switch locks), or null. */
    togglingId?: string | null
    /** Re-read the workflow list and recent runs from n8n. */
    onReload: () => void
    /**
     * `true` -> the block's own first fetch is in flight: the manage card keeps its
     * title and renders a fixed count of workflow-shaped rows with every cell
     * shimmering (§12b), the reload action and row toggles go inert, and the
     * executions card is skipped (nothing has run yet). Threaded straight down --
     * never fed to a separate skeleton tree.
     */
    isSkeleton?: boolean
    /** Already-localized copy. */
    labels: N8nWorkflowTableLabels
}

/** The already-resolved copy the block renders. */
export interface N8nWorkflowTableLabels {
    /** Card title (e.g. "Manage workflows"). */
    title: string
    /** Supporting line under the title. */
    description: string
    /** Reload button label. */
    reloadLabel: string
    /** Column header for the workflow name. */
    workflowColumn: string
    /** Column header for the webhook path. */
    webhookColumn: string
    /** Column header for the active toggle. */
    activeColumn: string
    /** Toggle label / status when the workflow is active. */
    activeLabel: string
    /** Toggle label / status when the workflow is inactive. */
    inactiveLabel: string
    /** Accessible name for the workflow table. */
    tableAriaLabel: string
    /** Shown for a workflow with no Webhook trigger. */
    noWebhookLabel: string
    /** Empty-state title. */
    emptyTitle: string
    /** Empty-state supporting line. */
    emptyDescription: string
    /** Recent-executions section title. */
    executionsTitle: string
    /** The three status labels, keyed by status. */
    statusOptions: Record<ExecutionStatus, string>
    /** Editor-placeholder title. */
    editorPlaceholderTitle: string
    /** Editor-placeholder supporting line. */
    editorPlaceholderDescription: string
}

/** Column keys, shared by the header config and each row. */
const COLUMN_KEY = { workflow: "workflow", webhook: "webhook", active: "active" } as const

/** Execution status -> chip tone. Success is healthy, error is a failure, running is in progress. */
const STATUS_TONE: Record<ExecutionStatus, ChipTone> = {
    success: "success",
    error: "danger",
    running: "warning",
}

/** How many placeholder rows the loading mirror draws while `workflows` hasn't landed yet. */
const SKELETON_ROW_COUNT = 3

/** Placeholder workflows -- sized like a real row so the table's shimmer mirrors the loaded shape. */
const SKELETON_WORKFLOWS: Array<WorkflowRowView> = Array.from({ length: SKELETON_ROW_COUNT }, (_unused, index) => ({
    id: `skeleton-${index}`,
    name: "Workflow name",
    webhookPath: "webhook-path",
    active: true,
}))

/**
 * The workflow-management table. See the file header for why empty, with-workflows,
 * and with-executions are states of one shape rather than separate leaves.
 *
 * @param props - {@link N8nWorkflowTableProps}
 */
const N8nWorkflowTable = ({
    workflows,
    executions,
    onToggleWorkflow,
    togglingId,
    onReload,
    isSkeleton = false,
    labels,
}: N8nWorkflowTableProps) => {
    const columns: ReadonlyArray<TableColumnSpec> = [
        { key: COLUMN_KEY.workflow, header: labels.workflowColumn },
        { key: COLUMN_KEY.webhook, header: labels.webhookColumn },
        { key: COLUMN_KEY.active, header: labels.activeColumn, align: "end" },
    ]

    // While loading the table renders the SAME shape from a fixed count of
    // placeholder workflows; `isSkeleton` threads into every cell so the toggle
    // and text go inert and shimmer instead of exposing a real control.
    const workflowRows = isSkeleton ? SKELETON_WORKFLOWS : workflows
    const rows: ReadonlyArray<TableRowItem> = workflowRows.map((workflow): TableRowItem => ({
        key: workflow.id,
        [COLUMN_KEY.workflow]: <Typography size="sm" weight="medium" isSkeleton={isSkeleton} text={workflow.name} />,
        [COLUMN_KEY.webhook]: (
            <Typography size="sm" color="muted" isSkeleton={isSkeleton} text={workflow.webhookPath ?? labels.noWebhookLabel} />
        ),
        [COLUMN_KEY.active]: (
            <ChoiceSwitch
                isSelected={workflow.active}
                onValueChange={(next) => onToggleWorkflow(workflow.id, next)}
                isDisabled={isSkeleton || togglingId === workflow.id}
                isSkeleton={isSkeleton}
                label={workflow.active ? labels.activeLabel : labels.inactiveLabel}
            />
        ),
    }))

    /** One recent-run row: a status chip and the workflow name + time. */
    const executionRow = (execution: ExecutionRowView): ReactNode => (
        <StackH
            gap={3}
            items={[
                () => <Chip tone={STATUS_TONE[execution.status]} text={labels.statusOptions[execution.status]} />,
                () => (
                    <Typography
                        size="xs"
                        color="muted"
                        text={
                            execution.startedAtLabel
                                ? `${execution.workflowName} · ${execution.startedAtLabel}`
                                : execution.workflowName
                        }
                    />
                ),
            ]}
        />
    )

    /** The manage card: reload action, then the table or the empty state. */
    const ManageCard = () => (
        <SurfaceCard
            padding={3}
            label={labels.title}
            isSkeleton={isSkeleton}
            action={isSkeleton ? undefined : () => (
                <Button
                    variant="secondary"
                    size="sm"
                    prefixIcon={ArrowClockwiseIcon}
                    label={labels.reloadLabel}
                    onPress={onReload}
                />
            )}
            body={() => (
                <StackV
                    principle="sibling-stack" gap={3}
                    isSkeleton={isSkeleton}
                    items={[
                        () => <Typography size="sm" color="muted" isSkeleton={isSkeleton} text={labels.description} />,
                        () =>
                            !isSkeleton && workflows.length === 0 ? (
                                <EmptyState
                                    icon={FlowArrowIcon}
                                    title={labels.emptyTitle}
                                    description={labels.emptyDescription}
                                />
                            ) : (
                                <Table columns={columns} items={rows} ariaLabel={labels.tableAriaLabel} isSkeleton={isSkeleton} />
                            ),
                    ]}
                />
            )}
        />
    )

    /** The recent-runs card -- only rendered when at least one run exists. */
    const ExecutionsCard = () => (
        <SurfaceCard
            padding={3}
            label={labels.executionsTitle}
            body={() => (
                <StackV gap={2} items={executions.map((execution) => () => executionRow(execution))} />
            )}
        />
    )

    /** The labelled region standing in for the embedded n8n editor iframe. */
    const EditorPlaceholder = () => (
        <SurfaceCard
            variant="nested"
            padding={3}
            isSkeleton={isSkeleton}
            body={() => (
                <EmptyState
                    icon={TreeStructureIcon}
                    title={labels.editorPlaceholderTitle}
                    description={labels.editorPlaceholderDescription}
                />
            )}
        />
    )

    return (
        <div data-tier="block" data-component="N8nWorkflowTable">
            <StackV
                gap={4}
                isSkeleton={isSkeleton}
                items={[
                    () => <ManageCard />,
                    // Executions are DATA that arrives with the first fetch -- while
                    // loading there is nothing to show, so the card is skipped (same
                    // omission the loaded `executions.length > 0` guard makes).
                    ...(!isSkeleton && executions.length > 0 ? [() => <ExecutionsCard />] : []),
                    () => <EditorPlaceholder />,
                ]}
            />
        </div>
    )
}

export { N8nWorkflowTable }

/** Source-level tier marker -- lets a gate read the tier without guessing from the folder path. */
export const meta = { tier: "block", name: "N8nWorkflowTable" } as const

import { Chip, type ChipTone } from "@sb-components/atoms/chips/Chip/Chip"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { SurfaceCard } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { Table, type TableColumnSpec, type TableRowItem } from "@sb-components/composites/data/Table/Table"
import { StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `OpsEventTable` -- the "platform events" tab. A reference table mapping each
 * platform event the ops layer fires to n8n to its per-event webhook path and to
 * whether an active workflow listens. The event set is FIXED (five events), so the
 * block has a single state. Grounded in the real `N8nDispatcherService`, whose
 * `OpsEvent` union is these five and whose path is `nivo-<event with dots as dashes>`.
 */

/** The five platform events the ops layer fires -- mirrors the real `OpsEvent` union. */
export type OpsEventKey =
    | "member.registered"
    | "order.paid"
    | "lesson.completed"
    | "quiz.passed"
    | "certificate.issued"

/** One event row -- an event, when it fires, its webhook path, and whether a workflow listens. */
export interface OpsEventRowView {
    /** The platform event (`OpsEvent`). */
    event: OpsEventKey
    /** Human line for when the event fires. */
    whenLabel: string
    /** The per-event webhook path the dispatcher posts to (`nivo-<event dashed>`). */
    webhookPath: string
    /** Whether an active workflow currently listens on that path. */
    isListening: boolean
}

/** Props for {@link OpsEventTable}. */
export interface OpsEventTableProps {
    /** The events, in the order they should read. */
    events: Array<OpsEventRowView>
    /** Already-localized copy. */
    labels: OpsEventTableLabels
}

/** The already-resolved copy the block renders. */
export interface OpsEventTableLabels {
    /** Card title (e.g. "Platform events"). */
    title: string
    /** Supporting line under the title. */
    description: string
    /** Column header for the event name. */
    eventColumn: string
    /** Column header for when the event fires. */
    whenColumn: string
    /** Column header for the webhook path. */
    webhookColumn: string
    /** Column header for the listening status. */
    listeningColumn: string
    /** Chip label when a workflow listens. */
    listeningLabel: string
    /** Chip label when nothing listens. */
    notListeningLabel: string
    /** Accessible name for the events table. */
    tableAriaLabel: string
}

/** Column keys, shared by the header config and each row. */
const COLUMN_KEY = { event: "event", when: "when", webhook: "webhook", listening: "listening" } as const

/**
 * The platform-events reference table. See the file header for why this block has
 * a single state (the event set is fixed).
 *
 * @param props - {@link OpsEventTableProps}
 */
const OpsEventTable = ({ events, labels }: OpsEventTableProps) => {
    const columns: ReadonlyArray<TableColumnSpec> = [
        { key: COLUMN_KEY.event, header: labels.eventColumn },
        { key: COLUMN_KEY.when, header: labels.whenColumn },
        { key: COLUMN_KEY.webhook, header: labels.webhookColumn },
        { key: COLUMN_KEY.listening, header: labels.listeningColumn, align: "end" },
    ]

    const rows: ReadonlyArray<TableRowItem> = events.map((row): TableRowItem => {
        const tone: ChipTone = row.isListening ? "success" : "default"
        return {
            key: row.event,
            [COLUMN_KEY.event]: <Typography size="sm" weight="medium" text={row.event} />,
            [COLUMN_KEY.when]: <Typography size="sm" color="muted" text={row.whenLabel} />,
            [COLUMN_KEY.webhook]: <Typography size="sm" color="muted" text={row.webhookPath} />,
            [COLUMN_KEY.listening]: (
                <Chip tone={tone} text={row.isListening ? labels.listeningLabel : labels.notListeningLabel} />
            ),
        }
    })

    return (
        <div data-tier="block" data-component="OpsEventTable">
            <SurfaceCard
                padding={3}
                label={labels.title}
                body={() => (
                    <StackV
                        principle="sibling-stack" gap={3}
                        items={[
                            () => <Typography size="sm" color="muted" text={labels.description} />,
                            () => <Table columns={columns} items={rows} ariaLabel={labels.tableAriaLabel} />,
                        ]}
                    />
                )}
            />
        </div>
    )
}

export { OpsEventTable }

/** Source-level tier marker -- lets a gate read the tier without guessing from the folder path. */
export const meta = { tier: "block", name: "OpsEventTable" } as const

import { BookOpenIcon, CheckCircleIcon, CircleIcon, CircleHalfIcon, VideoCameraIcon } from "@phosphor-icons/react"
import { Chip, type ChipTone } from "@sb-components/atoms/chips/Chip/Chip"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { SurfaceCard } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { EmptyState } from "@sb-components/composites/feedback/EmptyState/EmptyState"
import { ListRow } from "@sb-components/composites/lists/List/List"
import { ProgressMeter } from "@sb-components/composites/stats/ProgressMeter/ProgressMeter"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `CourseView` -- one published course opened in the classroom: header + overall
 * completion meter + the ordered lessons with each lesson's own state. The four
 * pictures -- `not-started`, `in-progress`, `completed`, `no-lessons` -- are DATA, so
 * they are STATES of the single shape. Grounded in the real `CourseEntity`,
 * `LessonEntity`, and `LessonProgressEntity` (each lesson's status is derived).
 */

/** A lesson's learning state, derived from its `LessonProgressEntity` row. */
export type LessonStatus = "completed" | "in-progress" | "not-started"

/** One lesson row -- a subset of `LessonEntity` joined with the viewer's progress. */
export interface CourseLessonView {
    /** Lesson id (`LessonEntity.id`). */
    id: string
    /** Lesson title (`LessonEntity.title`). */
    title: string
    /** Whether the lesson has an uploaded video (`LessonEntity.videoAssetId != null`). */
    hasVideo: boolean
    /** Learning state derived from the viewer's `LessonProgressEntity` row. */
    status: LessonStatus
}

/** The course header -- a subset of `CourseEntity`. */
export interface CourseHeaderView {
    /** Course title (`CourseEntity.title`). */
    title: string
    /** Short summary (`CourseEntity.summary`), or null when unset. */
    summary?: string | null
    /** Display price string (`CourseEntity.priceText`), or null when free/unpriced. */
    priceText?: string | null
}

/** Props for {@link CourseView}. */
export interface CourseViewProps {
    /** The course header. */
    course: CourseHeaderView
    /** The lessons, in `sortIndex` order. Empty is the `no-lessons` state. */
    lessons: Array<CourseLessonView>
    /**
     * `true` -> the block's own first fetch is in flight: the same card renders its
     * header, a shimmering progress meter, and a fixed count of lesson-shaped rows
     * (§12b), threading the flag down so every content node shimmers -- the box
     * neither shrinks nor jumps when the course resolves.
     */
    isSkeleton?: boolean
    /** Already-localized copy. */
    labels: CourseViewLabels
}

/** The already-resolved copy the block renders. */
export interface CourseViewLabels {
    /** Label above the progress meter (e.g. "Course progress"). */
    progressLabel: string
    /** Suffix after the "done / total" count (e.g. "lessons complete"). */
    lessonsCompleteSuffix: string
    /** Eyebrow prefix before a lesson's position (e.g. "Lesson"). */
    lessonPrefix: string
    /** Chip label for a lesson that has a video. */
    videoLabel: string
    /** The three lesson-status chip labels, keyed by status. */
    statusLabels: Record<LessonStatus, string>
    /** Empty-state title when the course has no lessons. */
    emptyTitle: string
    /** Empty-state supporting line. */
    emptyDescription: string
}

/** Lesson status -> the leading glyph + its tone class + the chip tone. */
const STATUS_ICON = {
    completed: CheckCircleIcon,
    "in-progress": CircleHalfIcon,
    "not-started": CircleIcon,
} as const

/** Icon colour per status -- completed reads success, in-progress warning, not-started muted. */
const STATUS_ICON_CLASS: Record<LessonStatus, string> = {
    completed: "size-5 shrink-0 text-success",
    "in-progress": "size-5 shrink-0 text-warning",
    "not-started": "size-5 shrink-0 text-muted",
}

/** Chip tone per status. */
const STATUS_CHIP_TONE: Record<LessonStatus, ChipTone> = {
    completed: "success",
    "in-progress": "warning",
    "not-started": "default",
}

/** How many placeholder lesson rows the loading mirror draws while `lessons` hasn't landed yet. */
const SKELETON_LESSON_COUNT = 3

/**
 * The classroom course view. See the file header for why the four pictures are
 * states of one shape rather than separate leaves.
 *
 * @param props - {@link CourseViewProps}
 */
const CourseView = ({ course, lessons, isSkeleton = false, labels }: CourseViewProps) => {
    const total = lessons.length
    const completedCount = lessons.filter((lesson) => lesson.status === "completed").length

    /** The course header row -- title on the left, the optional price chip on the right. */
    const Header = () => (
        <StackV
            principle="title-subtitle" gap={2}
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <StackH
                        principle="value-row" gap={3}
                        justify="between"
                        align="center"
                        isSkeleton={isSkeleton}
                        items={[
                            () => <Typography size="h4" weight="semibold" isSkeleton={isSkeleton} text={course.title} />,
                            ...(course.priceText ? [() => <Chip tone="accent" isSkeleton={isSkeleton} text={course.priceText ?? ""} />] : []),
                        ]}
                    />
                ),
                ...(course.summary ? [() => <Typography size="sm" color="muted" isSkeleton={isSkeleton} text={course.summary ?? ""} />] : []),
            ]}
        />
    )

    /** The overall completion meter plus the "done / total" count line. */
    const Progress = () => (
        <StackV
            gap={1}
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <ProgressMeter
                        value={completedCount}
                        max={total}
                        label={labels.progressLabel}
                        showValue
                        isSkeleton={isSkeleton}
                        color={completedCount === total ? "success" : "accent"}
                    />
                ),
                () => (
                    <Typography
                        size="xs"
                        color="muted"
                        isSkeleton={isSkeleton}
                        text={`${completedCount} / ${total} ${labels.lessonsCompleteSuffix}`}
                    />
                ),
            ]}
        />
    )

    /** One lesson row -- a status glyph, the title + position, and status/video chips. */
    const LessonRow = (lesson: CourseLessonView, index: number) => {
        const Icon = STATUS_ICON[lesson.status]
        return (
            <ListRow
                key={lesson.id}
                divider={index < lessons.length - 1}
                leading={() => <Icon aria-hidden focusable="false" weight="fill" className={STATUS_ICON_CLASS[lesson.status]} />}
                title={lesson.title}
                subtitle={`${labels.lessonPrefix} ${index + 1}`}
                meta={() => (
                    <StackH
                        gap={3}
                        principle="chip-row"
                        align="center"
                        items={[
                            () => <Chip tone={STATUS_CHIP_TONE[lesson.status]} text={labels.statusLabels[lesson.status]} />,
                            ...(lesson.hasVideo
                                ? [() => <Chip tone="default" icon={VideoCameraIcon} text={labels.videoLabel} />]
                                : []),
                        ]}
                    />
                )}
            />
        )
    }

    return (
        <div data-tier="block" data-component="CourseView">
            <SurfaceCard
                padding={3}
                isSkeleton={isSkeleton}
                body={() => (
                    <StackV
                        principle="label-field" gap={4}
                        isSkeleton={isSkeleton}
                        items={[
                            () => <Header />,
                            // While loading the meter shows even with no lessons yet, so the
                            // shape stays stable when the real progress lands.
                            ...(isSkeleton || total > 0 ? [() => <Progress />] : []),
                            () =>
                                isSkeleton ? (
                                    <StackV
                                        principle="name-handle" gap={1}
                                        isSkeleton
                                        items={Array.from({ length: SKELETON_LESSON_COUNT }, (_unused, index) => () => (
                                            <ListRow
                                                key={index}
                                                divider={index < SKELETON_LESSON_COUNT - 1}
                                                title="Lesson title"
                                                subtitle="Lesson 1"
                                                isSkeleton
                                            />
                                        ))}
                                    />
                                ) : total === 0 ? (
                                    <EmptyState
                                        icon={BookOpenIcon}
                                        title={labels.emptyTitle}
                                        description={labels.emptyDescription}
                                    />
                                ) : (
                                    <StackV gap={1} items={lessons.map((lesson, index) => () => LessonRow(lesson, index))} />
                                ),
                        ]}
                    />
                )}
            />
        </div>
    )
}

export { CourseView }

