                                    ]}
                                />
                            )}
                        />
                    )
                }
                return (
                    <StackV
                        gap={1}
                        items={[
                            () => <Typography size="sm" weight="bold" text={labels.emptyTitle} />,
                            () => <Typography size="sm" color="muted" text={labels.emptyDescription} />,
                        ]}
                    />
                )
            }}
            footer={() =>
                isSkeleton ? (
                    <Button isSkeleton />
                ) : (
                    <Button variant="secondary" label={labels.onwardLabel} onPress={onOpenCommunity} />
                )
            }
        />
    </div>
