    const items: Array<AccordionItem> = rows.map((course) => ({
        key: course.id,
        title: (
            <StackH
                principle="value-row" gap={3}
                justify="between"
                classNames={["w-full"]}
                items={[
                    () => <Typography size="sm" weight="semibold" truncate text={course.title} />,
