import { BookOpenIcon, NotePencilIcon, PlusIcon } from "@phosphor-icons/react"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { SurfaceCardList, type SurfaceCardListItem } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { EmptyState } from "@sb-components/composites/feedback/EmptyState/EmptyState"
import { StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `CourseRailList` -- the Course Studio's leading rail: the expert's courses, and
 * once one is picked, that course's lessons -- both single-select lists the editor
 * panel reads its open lesson from. The pictures -- no courses yet, a nonempty list
 * with nothing picked, a course with no lessons yet, a populated tree -- are DATA,
 * so they are STATES of the single shape. Grounded in the real `CourseEntity`
 * (`CourseForm.tsx`'s `slug`/`title`) and `LessonEntity` (`LessonManager.tsx`'s
 * per-course `lessons`, ordered by `sortIndex`).
 */

/** One course row -- a subset of `CourseEntity`. */
export interface CourseRailCourseView {
    /** Course id (`CourseEntity.id`). */
    id: string
    /** Course title (`CourseEntity.title`). */
    title: string
    /** Lesson count for this course (`course.lessons.length`), shown as the row's meta. */
    lessonCount: number
}

/** One lesson row of the SELECTED course -- a subset of `LessonEntity`. */
export interface CourseRailLessonView {
    /** Lesson id (`LessonEntity.id`). */
    id: string
    /** Lesson title (`LessonEntity.title`). */
    title: string
}

/** Props for {@link CourseRailList}. */
export interface CourseRailListProps {
    /** The expert's courses, in listing order. Empty is the `no-courses` state. */
    courses: Array<CourseRailCourseView>
    /** Id of the course whose lessons show below, or null when nothing is picked yet. */
    selectedCourseId: string | null
    /** Change which course's lessons show below -- the connected layer re-reads that course's lessons. */
    onSelectCourse: (id: string) => void
    /** Open the new-course flow -- the connected layer runs `createCourse`. */
    onAddCourse: () => void
    /** The SELECTED course's lessons, `sortIndex` order. Empty is that course's own `no-lessons` state. */
    lessons: Array<CourseRailLessonView>
    /** Id of the lesson open in the editor, or null when none is open yet. */
    selectedLessonId: string | null
    /** Open a lesson in the editor panel. */
    onSelectLesson: (id: string) => void
    /** Start a new lesson on the selected course -- the connected layer runs `createLesson`. */
    onAddLesson: () => void
    /**
     * `true` -> the rail's own first fetch is in flight: both lists render a fixed
     * count of course/lesson-shaped rows with every cell shimmering (§12b), and
     * both add actions go inert. Threaded straight down -- never fed to a separate
     * skeleton tree.
     */
    isSkeleton?: boolean
    /** Already-localized copy. */
    labels: CourseRailListLabels
}

/** The already-resolved copy the block renders. */
export interface CourseRailListLabels {
    /** Courses list header (e.g. "Courses"). */
    coursesTitle: string
    /** Add-course button label. */
    addCourseLabel: string
    /** Suffix after a course's lesson count (e.g. "lessons"). */
    lessonCountSuffix: string
    /** Empty-state title when the expert has no courses yet. */
    coursesEmptyTitle: string
    /** Empty-state supporting line for no courses. */
    coursesEmptyDescription: string
    /** Lessons list header (e.g. "Lessons"). */
    lessonsTitle: string
    /** Add-lesson button label. */
    addLessonLabel: string
    /** Shown in the lessons slot before any course is picked. */
    noCourseSelectedTitle: string
    /** Empty-state title when the selected course has no lessons yet. */
    lessonsEmptyTitle: string
    /** Empty-state supporting line for a course with no lessons. */
    lessonsEmptyDescription: string
}

/** How many placeholder rows each list's loading mirror draws while its data hasn't landed yet. */
const SKELETON_ROW_COUNT = 3

/** Placeholder courses -- sized like a real row so the list's shimmer mirrors the loaded shape. */
const SKELETON_COURSES: Array<CourseRailCourseView> = Array.from({ length: SKELETON_ROW_COUNT }, (_unused, index) => ({
    id: `skeleton-course-${index}`,
    title: "Course title",
    lessonCount: 0,
}))

/** Placeholder lessons -- sized like a real row so the list's shimmer mirrors the loaded shape. */
const SKELETON_LESSONS: Array<CourseRailLessonView> = Array.from({ length: SKELETON_ROW_COUNT }, (_unused, index) => ({
    id: `skeleton-lesson-${index}`,
    title: "Lesson title",
}))

/**
 * The Course Studio rail. See the file header for why the four pictures are
 * states of one shape rather than separate leaves.
 *
 * @param props - {@link CourseRailListProps}
 */
const CourseRailList = ({
    courses,
    selectedCourseId,
    onSelectCourse,
    onAddCourse,
    lessons,
    selectedLessonId,
    onSelectLesson,
    onAddLesson,
    isSkeleton = false,
    labels,
}: CourseRailListProps) => {
    const courseRows = isSkeleton ? SKELETON_COURSES : courses
    const courseItems: Array<SurfaceCardListItem> = courseRows.map((course) => ({
        key: course.id,
        title: course.title,
        subtitle: `${course.lessonCount} ${labels.lessonCountSuffix}`,
        leadingIcon: BookOpenIcon,
        selected: course.id === selectedCourseId,
        isDisabled: isSkeleton,
        onPress: () => onSelectCourse(course.id),
    }))

    // The lessons list only ever shows the SELECTED course's own lessons -- while
    // nothing is picked there is nothing to list, so the row-building below is
    // skipped entirely rather than rendering a stale/foreign set.
    const lessonRows = isSkeleton ? SKELETON_LESSONS : lessons
    const lessonItems: Array<SurfaceCardListItem> = lessonRows.map((lesson) => ({
        key: lesson.id,
        title: lesson.title,
        leadingIcon: NotePencilIcon,
        selected: lesson.id === selectedLessonId,
        isDisabled: isSkeleton,
        onPress: () => onSelectLesson(lesson.id),
    }))

    const CoursesEmpty = () => (
        <EmptyState icon={BookOpenIcon} title={labels.coursesEmptyTitle} description={labels.coursesEmptyDescription} />
    )
    // Two DIFFERENT reasons this list can be empty -- no course picked yet vs. the
    // picked course genuinely has none -- so the copy names the actual reason
    // rather than a single generic "empty" line.
    const LessonsEmpty = () => (
        <EmptyState
            icon={NotePencilIcon}
            title={selectedCourseId ? labels.lessonsEmptyTitle : labels.noCourseSelectedTitle}
            description={selectedCourseId ? labels.lessonsEmptyDescription : undefined}
        />
    )

    return (
        <div data-tier="block" data-component="CourseRailList">
            <StackV
                gap={6}
                isSkeleton={isSkeleton}
                items={[
                    () => (
                        <SurfaceCardList
                            label={labels.coursesTitle}
                            items={courseItems}
                            emptyState={CoursesEmpty}
                            isSkeleton={isSkeleton}
                            action={isSkeleton ? undefined : () => (
                                <Button variant="secondary" size="sm" prefixIcon={PlusIcon} label={labels.addCourseLabel} onPress={onAddCourse} />
                            )}
                        />
                    ),
                    () => (
                        <SurfaceCardList
                            label={labels.lessonsTitle}
                            items={selectedCourseId ? lessonItems : []}
                            emptyState={LessonsEmpty}
                            isSkeleton={isSkeleton}
                            // No course picked yet => nothing to add a lesson TO -- the action only
                            // earns its place once a course is selected (same reasoning
                            // `MembersManager` uses to gate its own header action on load state).
                            action={isSkeleton || !selectedCourseId ? undefined : () => (
                                <Button variant="secondary" size="sm" prefixIcon={PlusIcon} label={labels.addLessonLabel} onPress={onAddLesson} />
                            )}
                        />
                    ),
                ]}
            />
        </div>
    )
}

export { CourseRailList }

/** Source-level tier marker -- lets a gate read the tier without guessing from the folder path. */
export const meta = { tier: "block", name: "CourseRailList" } as const

import type { ComponentType, SVGProps } from "react"
import { BellIcon } from "@phosphor-icons/react"
import { cn } from "@heroui/react"
import type { ComponentTypeWithSkeleton, SkeletonProps } from "@sb-components/frames/_slot"
import { Avatar } from "@sb-components/atoms/display/Avatar/Avatar"
import { Badge } from "@sb-components/atoms/display/Badge/Badge"
import { Divider } from "@sb-components/atoms/display/Divider/Divider"
import { InputSearch } from "@sb-components/atoms/forms"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { RailShell } from "@sb-components/frames/RailShell/RailShell"

/**
 * `ExpertDashboardShell` -- the layout every `apps/expert` dashboard route sits
 * in: a full-width top bar (search - account - notifications) above a
 * `RailShell` whose leading rail is the nine-destination nav (three clusters
 * -- Operations / Business / Automation) and whose body is the routed page.
 */

/** A nav-row glyph passed as a COMPONENT reference, rendered at row scale. */
export type ExpertNavIcon = ComponentType<SVGProps<SVGSVGElement> & { weight?: "regular" | "bold" }>

/** One destination in the rail. */
export interface ExpertDashboardNavItem {
    /** Stable id. */
    id: string
    /** Visible label -- already localized by the caller. */
    label: string
    /** Leading glyph as a COMPONENT reference. */
    icon: ExpertNavIcon
    /** Destination the row points at -- the connected layer swaps in a real router link. */
    href: string
    /** `true` -> this row matches the current route (tonal accent treatment). */
    isActive?: boolean
    /** Fired when the row is pressed. */
    onPress: () => void
}

/**
 * One cluster of destinations. The FIRST group in {@link ExpertDashboardShellProps.navGroups}
 * never draws a divider (nothing above it to split from); every group after it does.
 */
export interface ExpertDashboardNavGroup {
    /** Stable id. */
    id: string
    /** Uppercase caption shown above the group's rows -- omit for an unlabelled cluster. */
    label?: string
    /** The group's destinations, in display order. */
    items: Array<ExpertDashboardNavItem>
}

/** The brand mark pinned at the top of the rail. */
export interface ExpertDashboardShellBrand {
    /** The academy's display name -- already localized/resolved by the caller. */
    name: string
    /** Subtitle under the name (e.g. the tenant's live domain). */
    domainLabel: string
    /** Fired when the brand mark is pressed -- routing "home" is the caller's call. */
    onLogoPress: () => void
}

/** The identity summary pinned at the bottom of the rail -- read-only display. */
export interface ExpertDashboardShellIdentity {
    /** Display name. */
    name: string
    /** Role/plan line under the name (e.g. "Academy owner"). */
    roleLabel: string
    /** Uploaded avatar URL; the `Avatar` atom's own fallback chain covers the rest. */
    avatarUrl?: string | null
}

/** The top bar's search box -- controlled. */
export interface ExpertDashboardShellSearch {
    /** Current query text. */
    value: string
    /** Fires as the query changes. */
    onValueChange: (value: string) => void
    /** Field placeholder -- already localized. */
    placeholder: string
}

/** The top bar's notification bell. */
export interface ExpertDashboardShellNotifications {
    /** Drives the bell's count badge; `0` hides it. */
    unreadCount: number
    /** Fired when the bell is pressed -- the caller opens `NotificationsDrawer`. */
    onOpen: () => void
}

/** Props for {@link ExpertDashboardShell}. */
export interface ExpertDashboardShellProps {
    /** Brand mark pinned at the top of the rail. */
    brand: ExpertDashboardShellBrand
    /** The rail's clusters, in display order -- the ONE source the nav column reads. */
    navGroups: Array<ExpertDashboardNavGroup>
    /** The identity summary pinned at the bottom of the rail. */
    identity: ExpertDashboardShellIdentity
    /** The top bar's search box. */
    search: ExpertDashboardShellSearch
    /** The top bar's notification bell. */
    notifications: ExpertDashboardShellNotifications
    /** Fired when the top bar's account avatar is pressed. */
    onAccountPress: () => void
    /** Accessible name for the search field. */
    searchLabel: string
    /** Accessible name for the top bar's account trigger. */
    accountLabel: string
    /** Accessible name for the notification bell. */
    notificationsLabel: string
    /** The routed page's own content, mounted in the body column. */
    content: ComponentTypeWithSkeleton
    /** Render the rail + content in their skeleton (loading) state. */
    isSkeleton?: boolean
}

/** Bell trigger chrome -- a plain button because `Badge` must wrap the glyph (no atom hosts that). Mirrors `NivoTopBar`'s own constant. */
const BELL_TRIGGER = "inline-flex items-center justify-center rounded-full p-2 text-foreground transition-colors hover:bg-default/40"

/** Props for one pressable nav row. */
interface ExpertDashboardNavRowProps {
    /** The destination this row renders. */
    item: ExpertDashboardNavItem
    /** `true` -> the row is a loading mirror. */
    isSkeleton?: boolean
}

/** One pressable nav row -- icon + label, tonal accent treatment while active. */
const NavRow = ({ item, isSkeleton }: ExpertDashboardNavRowProps) => (
    <button
        type="button"
        disabled={isSkeleton}
        onClick={item.onPress}
        aria-current={item.isActive ? "page" : undefined}
        className={cn(
            "flex items-center gap-3 rounded-xl px-3 py-2 text-left transition-colors disabled:cursor-default",
            item.isActive ? "bg-accent-soft text-accent-soft-foreground" : "text-muted hover:bg-default/60 hover:text-foreground",
        )}
    >
        <item.icon aria-hidden focusable="false" className={cn("size-[18px] shrink-0", item.isActive && "text-accent")} />
        <Typography size="sm" weight={item.isActive ? "semibold" : "medium"} isSkeleton={isSkeleton} text={item.label} />
    </button>
)

/** Props for one nav cluster in the rail. */
interface ExpertDashboardNavGroupViewProps {
    /** The cluster this view renders. */
    group: ExpertDashboardNavGroup
    /** `true` -> captions and rows shimmer. */
    isSkeleton?: boolean
    /** `true` -> skip the leading divider (nothing above the first group). */
    isFirst: boolean
}

/** One cluster of nav rows, with a caption (when set) and a leading divider (every group but the first). */
const NavGroup = ({ group, isSkeleton, isFirst }: ExpertDashboardNavGroupViewProps) => (
    <div className="flex flex-col gap-1">
        {!isFirst ? (
            <div className="py-2">
                <Divider />
            </div>
        ) : null}
        {group.label != null ? (
            <div className="px-3 pb-1">
                <Typography size="xs" weight="bold" color="muted" isSkeleton={isSkeleton} text={group.label} />
            </div>
        ) : null}
        <div className="flex flex-col gap-1">
            {group.items.map((item) => (
                <NavRow key={item.id} item={item} isSkeleton={isSkeleton} />
            ))}
        </div>
    </div>
)

/**
 * The dashboard shell. See the file header for why the top bar never takes
 * `isSkeleton` and why `RailShell` is the one frame carrying it into both the
 * rail and the body.
 *
 * @param props - {@link ExpertDashboardShellProps}
 */
const ExpertDashboardShell = ({
    brand,
    navGroups,
    identity,
    search,
    notifications,
    onAccountPress,
    searchLabel,
    accountLabel,
    notificationsLabel,
    content: Content,
    isSkeleton,
}: ExpertDashboardShellProps) => {
    // The rail is the brand + grouped nav + identity summary, fed the shell's skeleton
    // flag; it is a CALLER SLOT of `RailShell`, so it stays an uncalled component the
    // frame renders itself.
    const railSlot = ({ isSkeleton: skeleton }: SkeletonProps) => (
        <div className="flex h-full flex-col gap-4 border-r border-default p-3">
            <button type="button" onClick={brand.onLogoPress} disabled={skeleton} className="flex flex-col items-start gap-1 rounded-xl px-3 py-2 text-left disabled:cursor-default">
                <Typography size="lg" weight="bold" color="accent" isSkeleton={skeleton} text={brand.name} />
                <Typography size="xs" color="muted" isSkeleton={skeleton} text={brand.domainLabel} />
            </button>
            <nav className="flex min-h-0 flex-1 flex-col gap-4 overflow-y-auto">
                {navGroups.map((group, index) => (
                    <NavGroup key={group.id} group={group} isSkeleton={skeleton} isFirst={index === 0} />
                ))}
            </nav>
            <div className="flex items-center gap-2 border-t border-default pt-3">
                <Avatar size="sm" name={identity.name} src={identity.avatarUrl ?? undefined} seed={identity.name} isSkeleton={skeleton} />
                <div className="flex min-w-0 flex-1 flex-col gap-1">
                    <Typography size="sm" weight="medium" truncate isSkeleton={skeleton} text={identity.name} />
                    <Typography size="xs" color="muted" truncate isSkeleton={skeleton} text={identity.roleLabel} />
                </div>
            </div>
        </div>
    )

    // The routed page's own content -- a CALLER SLOT `RailShell` mounts itself with the
    // shell's skeleton flag threaded straight through.
    const bodySlot = ({ isSkeleton: skeleton }: SkeletonProps) => <Content isSkeleton={skeleton} />

    return (
        <div data-tier="layout" data-component="ExpertDashboardShell" className="min-h-dvh bg-background text-foreground">
            <header className="sticky top-0 z-40 flex h-16 items-center gap-3 border-b border-default bg-background/95 px-6 backdrop-blur">
                <div className="w-full max-w-md">
                    <InputSearch value={search.value} onValueChange={search.onValueChange} placeholder={search.placeholder} ariaLabel={searchLabel} />
                </div>

                <div className="flex-1" />

                <button type="button" onClick={onAccountPress} aria-label={accountLabel} className="rounded-full transition-opacity hover:opacity-80">
                    <Avatar size="sm" name={identity.name} src={identity.avatarUrl ?? undefined} seed={identity.name} />
                </button>

                {/* Bell -- plain button so `Badge` can anchor its count around the glyph, the
                    same badge-around-glyph shape `NivoTopBar` uses. */}
                <button type="button" aria-label={notificationsLabel} onClick={notifications.onOpen} className={BELL_TRIGGER}>
                    <Badge color="danger" count={notifications.unreadCount}>
                        <BellIcon aria-hidden focusable="false" className="size-5" />
                    </Badge>
                </button>
            </header>

            <div className="mx-auto w-full max-w-7xl px-6 py-8">
