import React from "react"
import dayjs from "dayjs"
import {
    Bar,
    BarChart,
    CartesianGrid,
    ResponsiveContainer,
    Tooltip,
    XAxis,
    YAxis,
} from "recharts"
import { AsyncContent } from "@sb-components/composites/async/AsyncContent/AsyncContent"
import { SurfaceCard, SurfaceCardList, type SurfaceCardListItem } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { Chip, type ChipTone } from "@sb-components/atoms/chips/Chip/Chip"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `AiQuotaHistoryPanel` — the "History" tab body inside `AiQuotaModal`: a 7-day
 * usage bar chart plus a scrollable, bordered list of recent AI charges.
 * `isLoading` swaps the whole `ChargesList` region for its shimmer mirror; an
 * empty `items` array renders the list's own empty state. The chart draws from
 * `chartPoints` regardless of either.
 */

/** What an AI charge was for — the block owns the display label per surface. */
export type AiQuotaHistorySurface = "grade" | "interview" | "chatbot"

/** {@link AiQuotaHistorySurface} → its display label. The block's own vocabulary (§14d.1). */
const PURPOSE_LABEL: Record<AiQuotaHistorySurface, string> = {
    grade: "Challenge grading",
    interview: "Interview grading",
    chatbot: "AI chat",
}

/** Fallback row title when a charge carries no specific model name. */
const AUTO_MODEL_LABEL = "Automatic model (free)"

/** Unit suffix on every credit-delta chip. */
const CREDITS_UNIT = "credit"

/** One day-bucket plotted on the usage chart. */
export interface AiQuotaHistoryChartPoint {
    /** X-axis label, already formatted (e.g. `"12/07"`). */
    day: string
    /** Credits consumed that day. */
    credits: number
}

/** One row of the recent-charges list. */
export interface AiQuotaHistoryChargeItem {
    /** Stable React key. */
    key: string
    /** Model name, when the charge names one specifically. Falls back to {@link AUTO_MODEL_LABEL}. */
    model?: string
    /** What the charge was for — drives the block-owned {@link PURPOSE_LABEL}. */
    surface: AiQuotaHistorySurface
    /** When the charge happened — the block formats this itself (`HH:mm DD/MM`). */
    occurredAt: string | number | Date
    /** Credit delta for this charge. Sign drives the trailing chip's tone (see judgement call 4). */
    credits: number
}

/** Props for {@link AiQuotaHistoryPanel}. */
export interface AiQuotaHistoryPanelProps {
    /** The 7 day-buckets for the chart. Defaults to an empty plot when omitted. */
    chartPoints?: Array<AiQuotaHistoryChartPoint>
    /** Recent charges, most recent first. `undefined` while the first load is still running. */
    items?: Array<AiQuotaHistoryChargeItem>
    /** `true` while the charges list's first load is running (drives ONLY the `ChargesList` leaf). */
    isLoading: boolean
}

/** How many placeholder rows the loading mirror shows — matches the source's 3-row skeleton. */
const SKELETON_ROW_COUNT = 3

/** Chip tone for a credit delta — see judgement call 4 in the file header: ported verbatim. */
const deltaTone = (credits: number): ChipTone => (credits > 0 ? "warning" : "success")

const toListItem = (item: AiQuotaHistoryChargeItem): SurfaceCardListItem => ({
    key: item.key,
    title: item.model ?? AUTO_MODEL_LABEL,
    subtitle: `${PURPOSE_LABEL[item.surface]} · ${dayjs(item.occurredAt).format("HH:mm DD/MM")}`,
    meta: () => <Chip tone={deltaTone(item.credits)} text={`${item.credits} ${CREDITS_UNIT}`} />,
})

/** Placeholder rows for the loading mirror — same row shape, shimmer chip in the meta slot. */
const skeletonItems = (): Array<SurfaceCardListItem> => Array.from({ length: SKELETON_ROW_COUNT }, (_, index) => ({
    key: `skeleton-${index}`,
    title: "Model",
    subtitle: "Purpose · Time",
    meta: () => <Chip isSkeleton />,
}))

/**
 * History tab body of `AiQuotaModal` — usage chart + recent-charges list.
 *
 * @param props - {@link AiQuotaHistoryPanelProps}
 */
export const AiQuotaHistoryPanel = ({
    chartPoints = [],
    items,
    isLoading,
}: AiQuotaHistoryPanelProps) => {
    const isEmpty = !isLoading && (items?.length ?? 0) === 0

    const chart = (
        <StackV gap={4} principle="card-caption"
            explain="Holds caption text under card media so the caption stays attached to the image above it."
            items={[
                () => <Typography size="sm" weight="medium" text="Credits used per day (last 7 days)" />,
                () => (
                    <SurfaceCard
                        variant="nested"
                        padding={4}

                        body={() => (
                            <div className="h-44 w-full text-accent-soft-foreground">
                                <ResponsiveContainer width="100%" height="100%">
                                    <BarChart data={chartPoints} margin={{ top: 8, right: 8, bottom: 0, left: -16 }}>
                                        <CartesianGrid
                                            strokeDasharray="3 3"
                                            stroke="currentColor"
                                            className="text-divider"
                                            vertical={false}
                                        />
                                        <XAxis dataKey="day" tick={{ fontSize: 10 }} interval={0} tickLine={false} axisLine={false} />
                                        <YAxis allowDecimals={false} tick={{ fontSize: 10 }} tickLine={false} axisLine={false} width={28} />
                                        <Tooltip
                                            cursor={{ fill: "currentColor", opacity: 0.08 }}
                                            formatter={(value) => [`${value} ${CREDITS_UNIT}`, ""]}
                                        />
                                        <Bar dataKey="credits" fill="currentColor" radius={[4, 4, 0, 0]} />
                                    </BarChart>
                                </ResponsiveContainer>
                            </div>
                        )}
                    />
                ),
            ]} />
    )

    const chargesList = (
        <StackV gap={4} items={[
            () => <Typography size="sm" weight="medium" text="AI usage history" />,
            () => (
                <div className="max-h-64 overflow-y-auto">
                    <AsyncContent
                        isLoading={isLoading}
                        skeleton={() => <SurfaceCardList variant="nested" items={skeletonItems()} isSkeleton />}
                        isEmpty={isEmpty}
                        emptyContent={{
                            title: "No AI usage yet.",

                        }}
                        content={() => <SurfaceCardList variant="nested" items={(items ?? []).map((item) => toListItem(item))} />}

                    />
                </div>
            ),
        ]} />
    )

    return (
        <StackV
            identity={{ tier: "block", component: "AiQuotaHistoryPanel" }}
            gap={6}
            items={[() => chart, () => chargesList]}
        />
    )
}

import React from "react"
import { WarningCircleIcon } from "@phosphor-icons/react"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { Cluster } from "@sb-components/frames/Cluster/Cluster"

/**
 * `PhaseScarcityNote` — the scarcity line for a pricing phase. Every number
 * comes from the backend's `coursePricePreview`; it never fabricates a
 * countdown or seat count, and a phase with no seat cap renders nothing.
 */

/** The course's pricing phases (inlined from `@/modules/types/enums/pricing-phase`). */
export enum PricingPhase {
    /** Opening phase with the fewest seats and the lowest price. */
    Pioneer = "pioneer",
    /** Mid phase after pioneer, still discounted before standard pricing. */
    EarlyBird = "early_bird",
    /** Full-price phase after early-bird seats are gone. */
    Regular = "regular",
}

/** Localised phase display name (inlined from `courseLanding.phase.*`, vi). */
const PHASE_LABEL: Record<PricingPhase, string> = {
    [PricingPhase.Pioneer]: "Pioneer",
    [PricingPhase.EarlyBird]: "Early Bird",
    [PricingPhase.Regular]: "Standard",
}

/**
 * Props for {@link PhaseScarcityNote}. `currentPhase`/`seatsRemaining`/
 * `nextPhasePriceVnd` are REQUIRED unless `isSkeleton` (§12b) — the price
 * preview hasn't arrived yet, so there is no honest phase/seat fact to state.
 */
export type PhaseScarcityNoteBaseProps =
    (
        | { isSkeleton: true; currentPhase?: PricingPhase; seatsRemaining?: number | null; nextPhasePriceVnd?: number | null }
        | {
            isSkeleton?: false
            /** The course's current pricing phase (shows its label). */
            currentPhase: PricingPhase
            /** Seats left at this phase's price; `null` = unlimited → renders NOTHING. */
            seatsRemaining: number | null
            /** VND price after this phase sells out; `null` = no rise to mention. */
            nextPhasePriceVnd: number | null
        }
    )

/**
 * Honest scarcity line for a paywall. Sits as a DIRECT SIBLING below `PriceTag`
 * (PriceTag handles discounting; scarcity is a different, orthogonal push axis).
 *
 * Only renders when the current phase has a **real seat cap**
 * (`seatsRemaining != null`) — an unlimited phase has no honest "rises when"
 * milestone to state, so it stays silent. EVERY number comes from the
 * backend's `coursePricePreview` — this file NEVER makes up a countdown or
 * seat count (fake scarcity is a banned dark pattern).
 *
 * @param props - {@link PhaseScarcityNoteBaseProps}
 */
const PhaseScarcityNoteBase = ({
    currentPhase,
    seatsRemaining,
    nextPhasePriceVnd,
    isSkeleton = false,
}: PhaseScarcityNoteBaseProps) => {
    if (isSkeleton) {
        return <Typography size="sm" isSkeleton />
    }
    // no seat cap at this phase → no honest scarcity reason → stay silent
    if (seatsRemaining == null) {
        return null
    }

    return (
        // Color is set ON THE FRAME; text inside does NOT declare `color`, so it
        // inherits `currentColor` — the exact `warning-soft-foreground` tone.
        //
        // This row is ONE TRACK of N elements that wrap ⇒ exactly the definition
        // of `Cluster`, and repeated lists go through `items` DATA (children are
        // forbidden).
        //
        // What's gained isn't "fewer classes" but that `gap` is now PINNED to
        // the scale BY TYPE: hand-written it's `gap-2` today, `gap-1.5`
        // tomorrow, nothing stops that.
        <div className="text-warning-soft-foreground">
            <Cluster
                gap={3}
                principle="separator-dot"
                explain="Places a middle-dot separator between short meta peers so the items read as one inline list."
                align="center"
                // The `·` between the two clauses is drawn by the FRAME, not written as a text item.
                // A mark that separates a track's items belongs to the track, the same way a rule
                // does; written as content it also produced a `Separator` node in the structure tree
                // whose link went to the generic Typography story.
                separator
                items={[
                    () => (
                        // §5a: icon matches the FONT-SIZE of the text beside it — `sm`
                        // (14px) ⇒ `size-3.5`. §5.0a: below `size-5` ⇒ force
                        // `weight="bold"` to compensate for the thin strokes.
                        <WarningCircleIcon
                            aria-hidden
                            focusable="false"
                            weight="bold"
                            className="size-3.5 shrink-0"
                        />
                    ),
                    () => (
                        <Typography
                            size="sm"
                            weight="medium"
                            text={`${seatsRemaining} seats left at the ${currentPhase != null ? PHASE_LABEL[currentPhase] : ""} price`}

                        />
                    ),
                    // The next two pieces go TOGETHER (no rise means nothing to separate
                    // it from) — but they're still TWO SEPARATE cluster items, since the
                    // `·` mark must be allowed to wrap onto the line with the piece after
                    // it when the row runs tight.
                    ...(nextPhasePriceVnd != null
                        ? [
                            () => (
                                <Typography
                                    size="sm"
                                    text={`price rises to ${nextPhasePriceVnd.toLocaleString("vi-VN")}₫ after that`}

                                />
                            ),
                        ]
                        : []),
                ]}
            />
        </div>
    )
}

/** `PhaseScarcityNote.*` — single-component namespace ⇒ only `.Base`. */
export { PhaseScarcityNoteBase as PhaseScarcityNote }

