import React from "react"
import { cn } from "@heroui/react"
import {
    BookmarkSimpleIcon,
    ChartBarIcon,
    CreditCardIcon,
    DesktopIcon,
    GraduationCapIcon,
    PaintBrushIcon,
    PencilSimpleIcon,
    ShieldCheckIcon,
    SlidersHorizontalIcon,
    StarIcon,
    WalletIcon,
} from "@phosphor-icons/react"
import { Divider } from "@sb-components/atoms/display/Divider/Divider"
import { Typography, type TypographyIcon } from "@sb-components/atoms/text/Typography/Typography"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"
import { CollapsibleSidebar } from "@sb-components/starci/blocks/navigation/CollapsibleSidebar/CollapsibleSidebar"
import { DesktopNavRow } from "./DesktopNavRow"

/**
 * `SettingsSidebarNav` — the account-settings destination list, drawn as a
 * collapsible desktop rail and, below `@app-md`, a sticky horizontal pill bar.
 * Two structural leaves — `DesktopRail` (collapsible `Link`-shaped rows with a
 * divider between groups) and `MobilePillBar` (a flattened rounded-full chip
 * row). Both render the same component; only the container width differs, so
 * each story shows the branch its own `@app-md` query resolves to. `activeHref`
 * is data, so within each leaf it is a state.
 *
 * Held: sticky-under-navbar desktop height host, mobile sticky pill surface, and
 * active/inactive chip `cn` — no existing frame/composite owns those shapes
 * (`ShowFrom`/`HideAbove` lack sticky+height; `NavigationRail` owns column fill;
 * `RailShell` sticky uses `top-24`, not `top-16`).
 */

/** Every account-settings destination this rail can offer — the closed vocabulary the block owns. */
export type SettingsDestinationKey =
    | "editProfile"
    | "appearance"
    | "security"
    | "sessions"
    | "courseHistory"
    | "aiSettings"
    | "aiSubscription"
    | "aiUsage"
    | "bookmarks"
    | "membership"
    | "installments"

/** One settings destination — TYPED DOMAIN DATA only: which one, and where it navigates. */
export interface SettingsNavItem {
    /** Which destination this row is — drives its icon + label (block-owned table below). */
    key: SettingsDestinationKey
    /** Absolute href the row navigates to. */
    href: string
}

/**
 * A cluster of destinations rendered together. No `label` field: every real group is
 * unlabelled (see `src`'s `getSettingsGroups` — only a divider separates them), so adding
 * an unused caption prop would be inventing a case no screen asks for (§14d.3).
 */
export interface SettingsNavGroup {
    /** Stable React key for the group — not shown, only used for reconciliation + the divider count. */
    key: string
    /** The destinations in this group, in display order. */
    items: Array<SettingsNavItem>
}

/** Destination → label. The block's own wording (§14d.1), never handed in by the caller. */
export const DESTINATION_LABEL: Record<SettingsDestinationKey, string> = {
    editProfile: "Edit profile",
    appearance: "Appearance",
    security: "Security",
    sessions: "Login sessions",
    courseHistory: "Learning history",
    aiSettings: "AI settings",
    aiSubscription: "AI plan",
    aiUsage: "AI usage",
    bookmarks: "Saved",
    membership: "Membership plan",
    installments: "Installments",
}

/** Destination → icon. Same glyphs `src`'s `nav.tsx` maps, so porting this table reads as ONE control. */
export const DESTINATION_ICON: Record<SettingsDestinationKey, TypographyIcon> = {
    editProfile: PencilSimpleIcon,
    appearance: PaintBrushIcon,
    security: ShieldCheckIcon,
    sessions: DesktopIcon,
    courseHistory: GraduationCapIcon,
    aiSettings: SlidersHorizontalIcon,
    aiSubscription: CreditCardIcon,
    aiUsage: ChartBarIcon,
    bookmarks: BookmarkSimpleIcon,
    membership: StarIcon,
    installments: WalletIcon,
}

/** Props for {@link SettingsSidebarNav}. */
export interface SettingsSidebarNavProps {
    /** Grouped destinations, in display order. */
    groups: Array<SettingsNavGroup>
    /** Which destination's `href` is being viewed right now. */
    activeHref: string
    /** Fired with a destination's `href` when its row/pill is pressed. */
    onNavigate: (href: string) => void
    /** Heading shown atop the desktop rail (hidden while collapsed). */
    title: string
    /** Accessible label for the collapse toggle (expanded state). */
    collapseLabel: string
    /** Accessible label for the expand toggle (collapsed state). */
    expandLabel: string
    /** `localStorage` key the collapsed flag persists under, so the choice survives navigation. */
    storageKey: string
    /** Accessible name for the mobile pill nav landmark. Defaults to {@link title}. */
    mobileNavAriaLabel?: string
}

/**
 * The settings destination rail. See the file header for the reused `CollapsibleSidebar`
 * gap, the two still-inlined gaps, the enum-owned vocabulary, the `@app-md` port, and the
 * two structural leaves.
 *
 * @param props - {@link SettingsSidebarNavProps}
 */
const SettingsSidebarNav = ({
    groups,
    activeHref,
    onNavigate,
    title,
    collapseLabel,
    expandLabel,
    storageKey,
    mobileNavAriaLabel,
}: SettingsSidebarNavProps) => {
    // Mobile leaf flattens every group into one scroll strip — grouping only matters to the
    // desktop rail's dividers, the mobile bar has no room to spare on a section caption.
    const flatItems = groups.flatMap((group) => group.items)

    return (
        <StackV
            identity={{ tier: "block", component: "SettingsSidebarNav" }}
            principle="group-boundary"
            explain="Separates the desktop rail from the mobile pill bar so each leaf keeps its own seam owner — not sibling-stack, because these are alternate structural leaves rather than repeating peers."
            items={[
                () => (
                    // Held: sticky-under-navbar + viewport-minus-chrome height — no named frame.
                    <div className="hidden shrink-0 @app-md:sticky @app-md:top-16 @app-md:block @app-md:h-[calc(100dvh-4rem)]">
                        <CollapsibleSidebar
                            title={title}
                            collapseLabel={collapseLabel}
                            expandLabel={expandLabel}
                            storageKey={storageKey}
                        >
                            {groups.map((group, index) => (
                                <React.Fragment key={group.key}>
                                    {index > 0 ? <Divider /> : null}
                                    <StackV
                                        principle="sibling-stack"
                                        explain="Same-kind peer stack of settings rows — not group-boundary, because rows are repeating siblings rather than section groups."
                                        items={group.items.map((item) => () => (
                                            <DesktopNavRow
                                                item={item}
                                                isActive={item.href === activeHref}
                                                onNavigate={onNavigate}
                                            />
                                        ))}
                                    />
                                </React.Fragment>
                            ))}
                        </CollapsibleSidebar>
                    </div>
                ),
                () => (
                    // Held: mobile sticky pill landmark + chip active/inactive cn.
                    <nav aria-label={mobileNavAriaLabel ?? title} className="sticky top-16 z-30 @app-md:hidden">
                        <div className="overflow-x-auto border-b border-default bg-background/80 backdrop-blur-xl">
                            <StackH
                                principle="flex-action"
                                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                items={flatItems.map((item) => () => {
                                    const isActive = item.href === activeHref
                                    const Icon = DESTINATION_ICON[item.key]
                                    return (
                                        <button
                                            type="button"
                                            aria-current={isActive ? "page" : undefined}
                                            onClick={() => onNavigate(item.href)}
                                            className={cn(
                                                "shrink-0 rounded-full border px-3 py-2 transition-colors",
                                                isActive ? "border-accent bg-accent-soft text-accent-soft-foreground" : "border-default text-muted hover:bg-default",
                                            )}
                                        >
                                            <StackH
                                                principle="icon-text"
                                                explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
                                                items={[
                                                    () => <Icon aria-hidden focusable="false" className="size-4 shrink-0" />,
                                                    () => <Typography size="sm" text={DESTINATION_LABEL[item.key]} noWrap />,
                                                ]}
                                            />
                                        </button>
                                    )
                                })}
                            />
                        </div>
                    </nav>
                ),
            ]}
        />
    )
}

export { SettingsSidebarNav }

import React from "react"
import type { ReactNode } from "react"
import { ResizableRail } from "@sb-components/behaviors/ResizableRail/ResizableRail"
import { Spinner } from "@sb-components/atoms/display/Spinner/Spinner"
import { FillAvailable } from "@sb-components/frames/FillAvailable/FillAvailable"
import { Stage } from "@sb-components/frames/Stage/Stage"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"
import { EnrollGate, type EnrollGateProps } from "@sb-components/starci/blocks/learn/EnrollGate/EnrollGate"
import { ContentAiFab } from "@sb-components/starci/blocks/learn/ContentAiFab/ContentAiFab"
import {
    ContentAiSelectionAsk,
    type ContentAiSelectionAskAnchor,
} from "@sb-components/starci/blocks/learn/ContentAiSelectionAsk/ContentAiSelectionAsk"

/**
 * `LearnShell` — the wrapper mounted once per `/learn/**` scope. Five
 * structural leaves, each gaining or losing a whole node:
 *   - `RailSurface`        — rail mounted beside `children`, one floating FAB.
 *   - `NoRailSurface`      — no rail; `children` fills the width.
 *   - `SelectionAskActive` — gains the `ContentAiSelectionAsk` pill alongside
 *     the FAB.
 *   - `AiSuppressed`       — `isAssessmentLive` loses both AI trigger nodes.
 *   - `EnrollGated`        — the whole rail+children row is replaced by
 *     `EnrollGate`.
 */

/** Which `/learn/**` surface is currently active — drives whether a rail mounts. */
export type LearnSurface = "content" | "personalProject" | "leaderboard" | "other"

/** Surfaces whose real rail body (out of scope here, see file header) exists in the real app. */
const RAIL_SURFACES: ReadonlySet<LearnSurface> = new Set(["content", "leaderboard"])

/** Rail persistence + bounds — mirrors the real `learn/layout.tsx` rail's own defaults. */
const RAIL_STORAGE_KEY = "learn-shell-rail-width"
const RAIL_DEFAULT_WIDTH = 320
const RAIL_MIN_WIDTH = 256
const RAIL_MAX_WIDTH = 480
const RAIL_ARIA_LABEL = "Drag to resize the side panel"
const RAIL_LOADING_LABEL = "Loading side panel"

/**
 * Fields `LearnShell` relays into `EnrollGate` — see the file header's
 * "`preview` IS A RELAYED SLOT" note for why `preview`/`price` ride along with
 * `title`/`description`, plus the `onEnroll` callback the gate needs to fire.
 */
export interface LearnShellEnrollGateProps
    extends Pick<EnrollGateProps, "title" | "description" | "preview" | "price"> {
    /** Fired when the learner takes the gate's enroll CTA. */
    onEnroll: () => void
}

/**
 * A resolved, already-positioned "ask AI about this selection" request — see
 * the file header for why `LearnShell` never tracks the selection itself.
 */
export interface LearnShellSelectionAsk {
    /** Viewport point to plant the pill at (already resolved by the caller). */
    anchor: ContentAiSelectionAskAnchor
    /** `true` → the pill carries the "New" badge. */
    isNew?: boolean
}

/** Props for {@link LearnShell}. */
export interface LearnShellProps {
    /** Which `/learn/**` surface is mounted right now — drives which rail body would mount. */
    activeSurface: LearnSurface
    /** `true` → the active surface requires enrollment the viewer does not have; replaces the whole body with `EnrollGate`. */
    isEnrollGated: boolean
    /** `true` → a timed/live assessment is running; suppresses BOTH AI triggers regardless of `isEnrollGated`. */
    isAssessmentLive: boolean
    /** `title`/`description`/`preview`/`price` relayed into `EnrollGate`, plus its `onEnroll`. Required only while `isEnrollGated`. */
    enrollGateProps?: LearnShellEnrollGateProps
    /** Fired when the floating AI trigger is pressed — the real layout opens the AI chat rail/drawer in response. */
    onOpenAiChat: () => void
    /** `true` → that chat surface is already open, so `ContentAiFab` hides instead of floating on top of it. */
    isAiChatOpen?: boolean
    /** The current text-selection ask request, already resolved+positioned by the caller. `null`/omitted → no selection to react to. */
    selectionAsk?: LearnShellSelectionAsk | null
    /** Fired when the selection-ask pill is pressed. */
    onOpenSelectionAsk: () => void
    /** The active route's own content — the one place `ReactNode` is valid above frame tier (§12). */
    children: ReactNode
}

/**
 * The `/learn/**` layout shell. See the file header for the full contract, the
 * scope gaps left deliberately open, and why `LeaderboardCategoryNav` was not
 * reused despite the inventory hint.
 *
 * @param props - {@link LearnShellProps}
 */
const LearnShell = ({
    activeSurface,
    isEnrollGated,
    isAssessmentLive,
    enrollGateProps,
    onOpenAiChat,
    isAiChatOpen = false,
    selectionAsk = null,
    onOpenSelectionAsk,
    children,
}: LearnShellProps) => {
    // A locked surface has nothing real to ask AI about yet, on top of the
    // brief's own `isAssessmentLive` suppression.
    const showAiTriggers = !isEnrollGated && !isAssessmentLive

    const railAndContent = [
        ...(RAIL_SURFACES.has(activeSurface) ? [() => (
            <ResizableRail
                storageKey={RAIL_STORAGE_KEY}
                defaultWidth={RAIL_DEFAULT_WIDTH}
                minWidth={RAIL_MIN_WIDTH}
                maxWidth={RAIL_MAX_WIDTH}
                ariaLabel={RAIL_ARIA_LABEL}
                handleSide="right"
                className="h-full shrink-0 border-r border-default"

            >
                <StackV
                    principle="sibling-stack"
                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."

                    items={[() => <Spinner label={RAIL_LOADING_LABEL} />]}
                />
            </ResizableRail>
        )] : []),
        () => (
            <FillAvailable
                at="base"
                explain="Learn content column takes remaining width beside the optional rail so lesson chrome can shrink without overflowing the shell."
                body={() => <>{children}</>}
            />
        ),
    ]

    return (
        <StackV
            identity={{ tier: "layout", component: "LearnShell" }}
            principle="group-boundary"
            explain="Separates the learn surface from floating AI triggers so each region keeps its own seam owner — not sibling-stack, because these are distinct section roles rather than repeating peers."
            items={[
                () => (isEnrollGated && enrollGateProps != null ? (
                    <EnrollGate
                        title={enrollGateProps.title}
                        description={enrollGateProps.description}
                        preview={enrollGateProps.preview}
                        price={enrollGateProps.price}
                        onEnroll={enrollGateProps.onEnroll}
                    />
                ) : (
                    <Stage
                        fill="viewport"
                        canvas={() => (
                            <StackH
                                principle="layout-split"
                                explain="Major layout split — not block-boundary, because this separates the optional rail from the lesson body rather than adjacent blocks."
                                items={railAndContent}
                            />
                        )}
                    />
                )),
                () => (showAiTriggers ? (
                    <StackV
                        principle="sibling-stack"
                        explain="Same-kind peer stack of AI trigger chrome — not group-boundary, because FAB and selection-ask are alternate trigger peers rather than section groups."
                        items={[
                            () => (
                                <ContentAiFab
                                    onOpen={onOpenAiChat}
                                    isOpen={isAiChatOpen}
                                />
                            ),
                            ...(selectionAsk != null
                                ? [
                                    () => (
                                        <ContentAiSelectionAsk
                                            onOpen={onOpenSelectionAsk}
                                            anchor={selectionAsk.anchor}
                                            isNew={selectionAsk.isNew}
                                        />
                                    ),
                                ]
                                : []),
                        ]}
                    />
                ) : null),
            ]}
        />
    )
}

export { LearnShell }

import React, { useEffect, useMemo, useState } from "react"
import { CheckCircleIcon, SparkleIcon, XCircleIcon } from "@phosphor-icons/react"
import { DrawerShell } from "@sb-components/composites/layout/DrawerShell/DrawerShell"
import {
    AsyncContent,
    type AsyncContentEmptyProps,
    type AsyncContentErrorProps,
} from "@sb-components/composites/async/AsyncContent/AsyncContent"
import { SurfaceCardList, type SurfaceCardListItem } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"
import { EnumChip } from "@sb-components/composites/chips/EnumChip/EnumChip"
import { InlineIconLabel } from "@sb-components/composites/text/InlineIconLabel/InlineIconLabel"
import { MODEL_CATEGORY_MAP, type AiModelCategory } from "@sb-components/starci/blocks/learn/SubmissionScoreCard/SubmissionScoreCard"
import { Pagination } from "@sb-components/atoms/navigation/Pagination/Pagination"

/**
 * `SubmissionAttemptsDrawer` — a presentational overlay drawer listing every
 * past graded attempt at one challenge requirement, client-paginated. A row is
 * the select action: tapping it both picks that attempt and closes the drawer.
 * Pagination is owned inside this block (the full attempt list in, sliced
 * 6-at-a-time), not a caller-controlled `currentPage`/`totalPages` pair.
 */

/** One past graded attempt at this challenge requirement. */
export interface SubmissionAttemptRecord {
    /** Stable id — the value reported to {@link SubmissionAttemptsDrawerProps.onSelect}. */
    id: string
    /** 1-based order the attempt was made in — the row turns this into "Attempt N". */
    attemptNumber: number
    /** `null` → not graded yet; the row shows an "ungraded" chip instead of a number. */
    score: number | null
    /** Denominator for `score`. `null` → the score renders bare (no "/max"). */
    maxScore: number | null
    /** Drives the verdict icon + `Chip` tone once `score` is set — pass (`success`) or fail (`danger`). */
    isPassing: boolean
    /** Already-humanized relative time (e.g. "2 hours ago"). Absent → the byline row drops the time. */
    processedTimeAgo?: string
    /** The model that graded this attempt. Absent → the byline row does not draw at all (same rule `SubmissionScoreCard` uses). */
    gradedByModel?: string
    /** Cost/quality tier of {@link gradedByModel}. */
    modelCategory?: AiModelCategory
}

/** Props for {@link SubmissionAttemptsDrawer}. */
export interface SubmissionAttemptsDrawerProps {
    /** Whether the drawer is currently open. Forwarded to `DrawerShell`. */
    isOpen: boolean
    /** Open-state change handler (backdrop click, Escape, close button, or a row selection). Forwarded to `DrawerShell`. */
    onOpenChange: (open: boolean) => void
    /** The FULL attempt history (newest first) — this block paginates it client-side, same as real `src`. */
    attempts: Array<SubmissionAttemptRecord>
    /** The attempt currently being viewed — highlighted with a trailing check. */
    selectedAttemptId?: string
    /** Fired with an attempt id when the reader taps its row. The drawer closes itself right after (same gesture as real `src`). */
    onSelect: (attemptId: string) => void
    /** `true` → this list's own fetch is in flight; the drawer shows its skeleton mirror. */
    isLoading?: boolean
    /** `true` (once loading has finished) → the drawer falls to its empty message. */
    isEmpty?: boolean
    /** Truthy → the drawer falls to its error message (beats loading, per `AsyncContent`). */
    error?: unknown
    /** Retry handler — paired with `retryLabel` to show a retry button on the error branch. */
    onRetry?: () => void
    /** Label of the retry button — required alongside `onRetry` for it to appear. */
    retryLabel?: string
    /** Which edge the panel slides in from. Real `src` picks bottom-on-mobile itself; this port leaves that call to the caller. @default "right" */
    placement?: "top" | "bottom" | "left" | "right"
}

/** Fixed, block-owned title (§14d.1) — real `src` appends the live count, so this does too. */
const DRAWER_TITLE = "Submission history"
const EMPTY_TITLE = "No submissions yet"
const ERROR_TITLE = "Couldn't load the submission history"
const PAGER_ARIA_LABEL = "Submission history pagination"
const UNGRADED_LABEL = "Ungraded"

/** Attempts per page — same constant real `src` uses. */
const HISTORY_PAGE_SIZE = 6
/** How many skeleton rows mirror the list while `attempts` hasn't landed yet. */
const SKELETON_ATTEMPT_COUNT = 3

/** One attempt's verdict `Chip` shape — tone/icon/text, all derived from data. */
const scoreChipFor = (attempt: SubmissionAttemptRecord): { tone: "success" | "danger" | "default"; icon?: typeof CheckCircleIcon; text: string } => {
    if (attempt.score == null) {
        return { tone: "default", text: UNGRADED_LABEL }
    }
    return {
        tone: attempt.isPassing ? "success" : "danger",
        icon: attempt.isPassing ? CheckCircleIcon : XCircleIcon,
        text: attempt.maxScore != null ? `${attempt.score}/${attempt.maxScore}` : `${attempt.score}`,
    }
}

/** Turns one attempt into a {@link SurfaceCardListItem}'s free-form `content` — mirrors real `src`'s row exactly: attempt line + verdict chip + time-ago on line 1, model byline on line 2. */
const attemptRowContent = (attempt: SubmissionAttemptRecord, isSelected: boolean) => {
    const chip = scoreChipFor(attempt)

    const attemptLabelAndChip = [
        () => (
            <Typography
                text={`Attempt ${attempt.attemptNumber}`}
                size="sm"
                weight="medium"

            />
        ),
        () => <Chip tone={chip.tone} icon={chip.icon} text={chip.text} />,
    ]

    // justify="between" pushes the timeago to the far edge — the PARENT does the
    // pushing, not a child margin; the label+chip stay grouped in their own inner track
    // so `between` only ever splits two things, not three.
    const attemptLineContent = [
        () => <StackH principle="sibling-stack"
            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
            items={attemptLabelAndChip} />,
        ...(attempt.processedTimeAgo != null ? [() => (
            <Typography
                text={attempt.processedTimeAgo}
                size="xs"
                color="muted"

            />
        )] : []),
    ]

    const bylineContent = [
        () => (
            <InlineIconLabel
                icon={SparkleIcon}
                tone="default"
                size="xs"
                label={`Graded by ${attempt.gradedByModel}`}
            />
        ),
        ...(attempt.modelCategory != null ? [() => (
            <EnumChip
                value={attempt.modelCategory ?? ""}
                map={MODEL_CATEGORY_MAP}

            />
        )] : []),
    ]

    const rowContent = [
        () => (
            <StackH
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={attemptLineContent}
            />
        ),
        ...(attempt.gradedByModel != null ? [() => (
            <StackH at="sm" principle="sibling-stack"
                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                items={bylineContent}  />
        )] : []),
    ]

    // highlight-exception: the selected row's tint is baked into the row's own
    // content wrapper (a plain, un-tightened `<div>`), since `SurfaceCardListItem`
    // no longer takes a raw `className` — same class real `src`'s
    // `SurfaceListCardItem` uses.
    return (
        <div className={isSelected ? "bg-accent-soft hover:bg-accent-soft" : undefined}>
            <StackV gap={2} items={rowContent} />
        </div>
    )
}

/**
 * The attempts-history drawer. See the file header for the real-`src` rebuild
 * and why selecting a row closes the drawer in the same gesture.
 *
 * @param props - {@link SubmissionAttemptsDrawerProps}
 */
const SubmissionAttemptsDrawer = ({
    isOpen,
    onOpenChange,
    attempts,
    selectedAttemptId,
    onSelect,
    isLoading = false,
    isEmpty = false,
    error,
    onRetry,
    retryLabel,
    placement = "right",
}: SubmissionAttemptsDrawerProps) => {
    const [page, setPage] = useState(1)

    // reset to the first page whenever the drawer opens — same as real `src`.
    useEffect(() => {
        if (isOpen) {
            setPage(1)
        }
    }, [isOpen])

    const totalPages = Math.max(1, Math.ceil(attempts.length / HISTORY_PAGE_SIZE))
    const pagedAttempts = useMemo(
        () => attempts.slice((page - 1) * HISTORY_PAGE_SIZE, page * HISTORY_PAGE_SIZE),
        [attempts, page],
    )

    const emptyContent: AsyncContentEmptyProps = {
        title: EMPTY_TITLE,

    }

    const errorContent: AsyncContentErrorProps = {
        title: ERROR_TITLE,
        onRetry,
        retryLabel,

    }

    const skeletonRows = Array.from({ length: SKELETON_ATTEMPT_COUNT }, () => () => (
        <div className="h-16 w-full rounded-2xl bg-default/40" />
    ))

    // `selected` (a trailing check) is only wired for the FIXED title/subtitle row
    // shape — this row uses free-form `content` instead (2 lines, richer than that
    // shape fits), so the highlight is baked into `attemptRowContent`'s own wrapper
    // div, same class real `src`'s `SurfaceListCardItem` uses.
    const items: Array<SurfaceCardListItem> = pagedAttempts.map((attempt) => ({
        key: attempt.id,
        content: () => attemptRowContent(attempt, attempt.id === selectedAttemptId),
        onPress: () => {
            onSelect(attempt.id)
            onOpenChange(false)
        },
    }))

    const listAndPager = [
        () => (
            <SurfaceCardList
                items={items}


            />
        ),
        ...(totalPages > 1 ? [() => (
            // `Pagination` hard-codes its own internal `aria-label` (§4) — the
            // wrapping `<nav>` is how this block's own accessible name still
            // gets attached, same convention `CourseQaQuestionList` uses.
            <nav aria-label={PAGER_ARIA_LABEL}>
                <Pagination
                    currentPage={page}
                    totalPages={totalPages}
                    onPageChange={setPage}

                />
            </nav>
        )] : []),
    ]

    return (
        <DrawerShell
            isOpen={isOpen}
            onOpenChange={onOpenChange}
            placement={placement}
            title={`${DRAWER_TITLE} · ${attempts.length}`}
            body={() => (
                <AsyncContent
                    isLoading={isLoading}
                    skeleton={() => (
                        <StackV
                            principle="sibling-stack"
                            explain="Skeleton attempt rows — not group-boundary, because these are peer loading placeholders."
                            items={skeletonRows}
                        />
                    )}
                    isEmpty={isEmpty}
                    emptyContent={emptyContent}
                    error={error}
                    errorContent={errorContent}
                    content={() => (
                        <StackV
                            principle="content-row"
                            explain="Attempt list over optional pager — not sibling-stack, because these are related content regions."
                            items={listAndPager}
                        />
                    )}
                />
            )}
        />
    )
}

export { SubmissionAttemptsDrawer }

import React from "react"
import { CourseContents } from "./CourseContents"
import { BlockAnatomy, type AnatomyNode } from "@sb-utils/BlockAnatomy/BlockAnatomy"
import { StackV } from "@sb-components/frames/Stack/Stack"

/**
 * Shared anatomy parts + a per-device·per-state leaf renderer for the
 * `Screens/CourseContents/<Device>/<State>` stories. NOT a story file (leading
 * `_` keeps it out of the `*.stories` glob) — device story files import from here
 * so the parts + framing live in ONE place.
 */

/**
 * EVERY node this screen can show, in ONE list — 11 entries: 4 frames, 3 blocks, and 4
 * composites (incl. the empty-state frame). Mirrors the real `_CourseContents` spine.
 *
 * There is deliberately NO per-state variant of this list. The panel derives the tree from
 * the DOM and uses this table only as a whitelist, so a node that is not rendered cannot
 * reach the tree even when it is declared here. The previous `partsFor(isEmpty, viewer)`
 * was therefore a THIRD place deciding presence — after the screen's own `? null` and each
 * block's self-hide — and it is what produced a tree that disagreed with the render: it
 * filtered `CourseTeamGate` out for paid viewers while the block's own condition
 * (`!isEnrolled || isInTeam`) keeps it VISIBLE for a paid viewer who is not in the team.
 * One list cannot drift from the render; a filtered copy always can.
 */
export const PARTS: Array<AnatomyNode> = [
    // A FRAME is a DEP too, and the tree recurses into its children: `Container`
    // (reading width + page padding) and `StackV` (rhythm between blocks) decide the
    // entire page frame, so the screen tree lists them, not just blocks.
    {
        name: "Container",
        tier: "frame",
        role: "reading width + page padding — `size=\"md\"` for a text column; `padding` is pinned to the §10 scale",
        storyId: "frames-container-container--default",
    },
    {
        // Different name from the `StackV` inside it: the panel groups nodes BY NAME, so a matching name would merge them into one.
        name: "StackV",
        tier: "frame",
        role: "rhythm between two REGIONS — `gap=\"page\"` separates the course-identity cluster from the content (§10: sections-wide)",
        storyId: "frames-stack-stackv--default",
    },
    {
        name: "StackV",
        tier: "frame",
        role: "VERTICAL rhythm between blocks — one seam, one owner (§10a)",
        storyId: "frames-stack-stackv--default",
    },
    {
        name: "StackH",
        tier: "frame",
        role: "horizontal row — the continue cluster (title <-> Resume) and each lesson row's meta cluster",
        storyId: "frames-stack-stackh--default",
    },
    {
        // §11a — SCREEN tier, only the HIGHEST node: the screen composes PageHeader directly
        // (mirrors the real `_CourseContents`). Breadcrumbs + HighlightChip meta are internal
        // to it → drill in PageHeader's own story, not here.
        name: "PageHeader",
        tier: "composite",
        role: "course identity — breadcrumb + title + description + catalog-meta chips",
        storyId: "composites-layout-page-pageheader--full",
    },
    // WARNING: the node name must match EXACTLY the `data-anat-part` the component emits:
    // the DOM emits `CourseTeamGate`, not `Callout` (that's the FRAME the block
    // uses internally). Declaring the wrong name ⇒ the node never makes it into the
    // tree. The tier would be wrong too: `composite` while `storyId` points to a BLOCK.
    //
    // The gate hides itself on ITS OWN data (`!isEnrolled || isInTeam`), which for a PAID
    // viewer who is not yet in the team means it STAYS. Do not describe it as "hidden once
    // purchased" — measured on the paid render, it is in the DOM.
    { name: "CourseTeamGate", tier: "block", role: "GitHub-team warning — shows for an enrolled viewer who is not in the team yet", state: "warning", storyId: "starci-blocks-learn-courseteamgate-courseteamgate--warning" },
    // The link must point at the leaf this screen ACTUALLY renders. It used to point at
    // `--price-loading`, so clicking a dep on a fully loaded screen landed on the shimmer
    // leaf. A story-id gate can only prove an id EXISTS; that it points at the right leaf
    // is a reader's job (`scripts/check-story-ids.mjs` deliberately says so).
    { name: "TrialConversionStrip", tier: "block", role: "trial→enroll conversion strip; the screen drops it entirely once purchased", storyId: "starci-blocks-commerce-trialconversionstrip-trialconversionstrip--default" },
    { name: "ProgressMeter", tier: "composite", role: "the continue cluster's honest unified completion meter (lessons + challenges in one bar)", storyId: "composites-stats-progressmeter--label-and-value" },
    { name: "LearnNudges", tier: "block", role: "what to do today — cards due · mock interview · rank. The screen passes `kind` (ENUM); the block picks the icon (§14b)", storyId: "starci-blocks-learn-learnnudges-learnnudges--nudges" },
    { name: "SurfaceCardList", tier: "composite", role: "keep-going path — the current module's lessons as rows: state icon · title · reading time · difficulty chip · lock", storyId: "composites-cards-surfacecard-surfacecardlist--default" },
    // The empty state replaces the whole spine with this frame. It lives in the SAME list:
    // on a content render it simply is not in the DOM, so it cannot reach the tree.
    { name: "AsyncContentEmpty", tier: "composite", role: "the course has no contents yet — icon + title + description", storyId: "composites-async-asynccontent-asynccontentempty--basic" },
]

/** Args for {@link deviceLeaf}. */
export interface DeviceLeafArgs {
    /** Fixed container width (px) → the layout re-lays-out to it via `@app-*`. Omit = full (desktop). */
    width?: number
    /** `true` → renders the whole screen in the RESTING state (the flag flows down into each block). */
    isSkeleton?: boolean
    /** `true` → the course has no lessons yet. */
    isEmpty?: boolean
    /** Content viewer (only meaningful when NOT empty). */
    viewer?: "trial" | "paid"
    /** Story display name = leaf label (e.g. "Default", "Loading"). */
    leaf: string
    /** Optional rationale line. */
    reason?: React.ReactNode
}

/**
 * The Code tab's snippet for one leaf — EVERY leaf carries `code`: a screen owes
 * the same two tabs as an atom does.
 *
 * The snippet is built from the very args that produced the render, so it can never drift
 * from what is on screen — hand-writing one snippet per device × state would
 * have gone stale on the first prop rename.
 */
const leafCode = ({ width, isSkeleton, isEmpty, viewer }: Required<Pick<DeviceLeafArgs, "isSkeleton" | "isEmpty" | "viewer">> & { width?: number }) => {
    const props = [
        `viewer="${viewer}"`,
        ...(isSkeleton ? ["isSkeleton"] : []),
        ...(isEmpty ? ["isEmpty"] : []),
    ]
    const call = `<CourseContents ${props.join(" ")} />`
    // The device frame is part of the STORY, not of the screen — show it so a reader
    // knows the width comes from an `@container`, not from the screen itself.
    return width == null
        ? call
        : `<div className="@container" style={{ width: ${width} }}>
    ${call}
</div>`
}

/**
 * Render ONE CourseContents leaf: BlockAnatomy (anatomy is everywhere) wrapping the
 * layout inside its OWN `@container` at the device width, in the given state.
 */
export const deviceLeaf = ({ width, isSkeleton = false, isEmpty = false, viewer = "trial", leaf, reason }: DeviceLeafArgs) => (
    <StackV
        principle="page-pad"
        explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface."
        body={() => (
            <BlockAnatomy
                name="CourseContents"
                // `screen`, NOT `block`.
                tier="screen"
                leaf={leaf}
                parts={PARTS}
                reason={reason}
                code={leafCode({ width, isSkeleton, isEmpty, viewer })}
            >
                <div
                    className="@container overflow-hidden rounded-none border border-dashed border-accent"
                    style={width ? { width, maxWidth: "100%" } : undefined}
                >
                    <CourseContents viewer={viewer} isSkeleton={isSkeleton} isEmpty={isEmpty} />
                </div>
            </BlockAnatomy>
        )}
    />
)

import React from "react"
import { MapTrifoldIcon, ShareNetworkIcon } from "@phosphor-icons/react"
import { MindMapRail, type MindMapRailItem, type MindMapRailTier } from "@sb-components/starci/blocks/learn/MindMapRail/MindMapRail"
import { MindMapContinueButton } from "@sb-components/starci/blocks/learn/MindMapContinueButton/MindMapContinueButton"
import { MindMapFullscreenButton, type MindMapFullscreenButtonAriaLabels } from "@sb-components/starci/blocks/learn/MindMapFullscreenButton/MindMapFullscreenButton"
import { Legend, type LegendItem } from "@sb-components/composites/stats/Legend/Legend"
import { AsyncContentEmpty } from "@sb-components/composites/async/AsyncContent/AsyncContent"
import { ResizableRail } from "@sb-components/behaviors/ResizableRail/ResizableRail"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * SCREEN — `MindMapPage`: the course keyword graph, in its two real shapes.
 * See the component's own file header for the full function list, the two
 * corrections against the planner's proposed tree (`MindMapBackButton` and
 * `FloatingActionButton` are both absent, on purpose), and why the canvas
 * region is a documented §B3 gap rather than a faked ReactFlow mount.
 *
 * FIVE LEAVES, by STRUCTURE — `workspace` and `standalone` are different
 * compositions (not one shape with a variant flag flipping paint), so each
 * gets its own leaves; `Empty` and `Loading` each lose or swap real nodes
 * (rail's shimmer vs. its populated list; the three floating blocks present
 * vs. absent), which is a structural change, not a data condition of one leaf.
 */

/** Which shape of the mind map this screen renders — see the file header. */
export type MindMapVariant = "workspace" | "standalone"

/** Props for {@link MindMapPage}. */
export interface MindMapPageProps {
    /** Which shape to render — see the file header for how the two differ. */
    variant: MindMapVariant

    // ── `workspace`: the `MindMapRail` search pane ──
    /** Current search text (controlled). Ignored outside `workspace`. */
    query: string
    /** Fired on every keystroke in the rail's search field. */
    onQuery: (query: string) => void
    /** Current popularity-tier filter. */
    tier: MindMapRailTier
    /** Fired with the tier the reader picked in the rail's funnel popover. */
    onTier: (tier: MindMapRailTier) => void
    /** The current query+tier's matching keywords, in display order. */
    items: Array<MindMapRailItem>
    /** Which result is currently focused on the canvas, if any. */
    selectedId?: string
    /** Fired with a result's id when its rail row is pressed. */
    onPick: (id: string) => void
    /** `true` → the rail's own query/tier fetch is in flight (independent of `isSkeleton`). */
    isRailLoading?: boolean
    /** Accessible name for the rail's search field. */
    railAriaLabel: string
    /** Accessible name for the rail's tier filter group. */
    railTierAriaLabel: string
    /** Accessible name for the rail's drag-to-resize handle. */
    railResizeAriaLabel: string

    // ── `standalone`: floating chrome over the canvas ──
    /** Href of the viewer's next unread lesson/challenge, or `null` when none resolves. Ignored outside `standalone`. */
    resumeHref?: string | null
    /** `true` → the viewer has read everything the map has to offer. */
    allContentDone?: boolean
    /** Fired on a resume press. */
    onResume?: () => void
    /** Accessible name for the resume action. */
    continueAriaLabel?: string
    /** Legend entries — colour swatch + label, e.g. done/in-progress/not-started/locked/current. */
    legendItems?: Array<LegendItem>
    /** Fired on every press of the zoom-in button. */
    onZoomIn?: () => void
    /** Fired on every press of the zoom-out button. */
    onZoomOut?: () => void
    /** Fired on every press of the fullscreen toggle. */
    onToggleFullscreen?: () => void
    /** `true` → canvas is currently fullscreen. */
    isFullscreen?: boolean
    /** Per-button accessible names for the zoom/fullscreen rail. */
    fullscreenAriaLabels?: MindMapFullscreenButtonAriaLabels

    // ── shared ──
    /** `true` → every block that can mirror itself does; the canvas gap swaps to its loading wording. */
    isSkeleton?: boolean
    /** `true` → the course has no authored map/modules yet. `workspace`-ONLY — see the file header. */
    isEmpty?: boolean
}

/** localStorage key + bounds the real `MindMapWorkspace` persists the rail width under. */
const RAIL_STORAGE_KEY = "mindmap-rail-width"
const RAIL_DEFAULT_WIDTH = 320
const RAIL_MIN_WIDTH = 264
const RAIL_MAX_WIDTH = 520

const CANVAS_GAP_TITLE = "Concept map region"
const CANVAS_GAP_DESCRIPTION = "The real ReactFlow graph (nodes, drawer, minimap) isn't built this pass — this block is where it will mount (§B3)."
const CANVAS_GAP_LOADING_TITLE = "Loading map…"

const WORKSPACE_EMPTY_TITLE = "This course has no concept map yet"
const WORKSPACE_EMPTY_DESCRIPTION = "The map is generated automatically once the course has enough modules — check back later."

/** Props for the {@link MindMapCanvasGap} stand-in below. */
interface MindMapCanvasGapProps {
    isLoading?: boolean
}

/**
 * Stand-in for the out-of-reach ReactFlow engine (§B3) — see the file header's
 * "CANVAS GAP" note for why `AsyncContentEmpty` is the reused shape here.
 */
const MindMapCanvasGap = ({ isLoading = false}: MindMapCanvasGapProps) => (
    <StackV
        principle="sibling-stack"
        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
        items={[() => (
            <AsyncContentEmpty

                icon={ShareNetworkIcon}
                title={isLoading ? CANVAS_GAP_LOADING_TITLE : CANVAS_GAP_TITLE}
                description={isLoading ? undefined : CANVAS_GAP_DESCRIPTION}
            />
        )]}
    />
)

/**
 * `workspace` empty state — the course has no authored map yet. Replaces the
 * ENTIRE spine, same "one frame + one composite, each badging itself" shape
 * `CourseContents`/`ModulePage` already established for this exact case.
 */
const MindMapWorkspaceEmpty = () => (
    <div className="h-[calc(100dvh-4rem)]">
        <StackV
            principle="sibling-stack"
            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
            items={[() => (
                <AsyncContentEmpty

                    icon={MapTrifoldIcon}
                    title={WORKSPACE_EMPTY_TITLE}
                    description={WORKSPACE_EMPTY_DESCRIPTION}
                />
            )]}
        />
    </div>
)

/**
 * The mind-map screen, in its two shapes. See the file header for the function
 * list, the two corrections against the planner's proposed tree, and the
 * canvas gap.
 *
 * @param props - {@link MindMapPageProps}
 */
const MindMapPage = ({
    variant,
    query,
    onQuery,
    tier,
    onTier,
    items,
    selectedId,
    onPick,
    isRailLoading = false,
    railAriaLabel,
    railTierAriaLabel,
    railResizeAriaLabel,
    resumeHref = null,
    allContentDone = false,
    onResume,
    continueAriaLabel = "",
    legendItems = [],
    onZoomIn = () => {},
    onZoomOut = () => {},
    onToggleFullscreen = () => {},
    isFullscreen = false,
    fullscreenAriaLabels = { zoomIn: "", zoomOut: "", toggleFullscreen: "" },
    isSkeleton = false,
    isEmpty = false,
}: MindMapPageProps) => {
    if (variant === "workspace" && isEmpty) {
        return <MindMapWorkspaceEmpty />
    }

    const railSection = (
        <MindMapRail

            query={query}
            onQuery={onQuery}
            tier={tier}
            onTier={onTier}
            items={items}
            selectedId={selectedId}
            onPick={onPick}
            isLoading={isRailLoading}
            ariaLabel={railAriaLabel}
            tierAriaLabel={railTierAriaLabel}
            isSkeleton={isSkeleton}

        />
    )

    // The canvas region's floating chrome — in the real app these render as the
    // SAME ReactFlow engine's own Panel children, see the file header's
    // "OVERLAYS ARE FRAMES" note.
    const showOverlays = variant === "standalone" && !isSkeleton

    const canvasItems = [
        () => <MindMapCanvasGap isLoading={isSkeleton} />,
        ...(showOverlays ? [
            () => (
                <div className="absolute inset-x-0 top-4 z-10">
                    <StackV
                        principle="sibling-stack"
                        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                        isSkeleton={isSkeleton}
                        items={[() => (
                            <MindMapContinueButton
                                resumeHref={resumeHref}
                                allContentDone={allContentDone}
                                onResume={onResume}
                                continueAriaLabel={continueAriaLabel}
                                isSkeleton={isSkeleton}
                            />
                        )]}
                    />
                </div>
            ),
            () => (
                <div className="absolute bottom-4 left-4 z-10">
                    <StackV
                        gap={1}
                        isSkeleton={isSkeleton}
                        items={[() => (
                            <div>
                                <Legend items={legendItems} />
                            </div>
                        )]}
                    />
                </div>
            ),
            () => (
                <div className="absolute bottom-4 right-4 z-10">
                    <StackV
                        gap={1}
                        isSkeleton={isSkeleton}
                        items={[() => (
                            <MindMapFullscreenButton
                                onZoomIn={onZoomIn}
                                onZoomOut={onZoomOut}
                                onToggleFullscreen={onToggleFullscreen}
                                isFullscreen={isFullscreen}
                                ariaLabels={fullscreenAriaLabels}
                                isSkeleton={isSkeleton}
                            />
                        )]}
                    />
                </div>
            ),
        ] : []),
    ]

    const workspaceRail = (
        <ResizableRail
            storageKey={RAIL_STORAGE_KEY}
            defaultWidth={RAIL_DEFAULT_WIDTH}
            minWidth={RAIL_MIN_WIDTH}
            maxWidth={RAIL_MAX_WIDTH}
            ariaLabel={railResizeAriaLabel}
            // eslint-disable-next-line starci-fe/handler-on-prefix -- `handleSide` is a ResizableRail layout prop (which edge the resize handle sits on), a noun not an onXxx event handler
            handleSide="right"
            className="h-full shrink-0 border-r border-default"
        >
            <div className="overflow-y-auto">
                <StackV
                    principle="page-pad"
                    explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface."
                    isSkeleton={isSkeleton}
                    items={[() => railSection]}
                />
            </div>
        </ResizableRail>
    )

    return (
        <div className="h-[calc(100dvh-4rem)]">
            <StackH
                gap={1}
                isSkeleton={isSkeleton}
                items={[
                    ...(variant === "workspace" ? [() => workspaceRail] : []),
                    // The canvas region: the out-of-reach engine's gap, plus (standalone only) the
                    // floating chrome that in the real app renders as the SAME engine's own Panel
                    // children — see the file header's "OVERLAYS ARE FRAMES" note.
                    () => (
                        <div className="relative min-w-0 flex-1">
                            <StackV
                                gap={1}
                                isSkeleton={isSkeleton}
                                items={canvasItems}
                            />
                        </div>
                    ),
                ]}
            />
        </div>
    )
}

export { MindMapPage }

import React from "react"
import { type SkeletonProps } from "@sb-components/frames/_slot"
import { CaretRightIcon, GearSixIcon, SparkleIcon } from "@phosphor-icons/react"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { Breadcrumbs, type BreadcrumbItem } from "@sb-components/atoms/navigation/Breadcrumbs/Breadcrumbs"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { InputText } from "@sb-components/atoms/forms"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import {
    SurfaceCard,
    SurfaceCardAccordion,
    type SurfaceCardAccordionItem,
} from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { Callout } from "@sb-components/composites/feedback/Callout/Callout"
import { ListRow } from "@sb-components/composites/lists/List/List"
import { PageHeader } from "@sb-components/composites/layout/Page/Page"
import { MarkdownContent } from "@sb-components/composites/viewers/MarkdownContent/MarkdownContent"
import { Container } from "@sb-components/frames/Container/Container"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"
import { SplitWorkspace } from "@sb-components/frames/SplitWorkspace/SplitWorkspace"
import {
    ContentRelatedList,
    type ContentRelatedItem,
} from "@sb-components/starci/blocks/learn/ContentRelatedList/ContentRelatedList"
import {
    SubmissionScoreCard,
    type AiModelCategory,
} from "@sb-components/starci/blocks/learn/SubmissionScoreCard/SubmissionScoreCard"

/**
 * `PersonalProjectTaskPage` — the screen to solve one personal-project task. A
 * screen owns a list of functions. Split workspace: a reading column that swaps
 * per task (task identity, the locked-preview banner, the authored brief or the
 * legacy rubric/implementation guides, and related lessons) beside a
 * persistent, sticky act column (repo URL, the settings-drawer trigger,
 * evaluate/secondary actions, and the latest graded result). Two columns
 * composed with `SplitWorkspace`: a `min-w-0 flex-1` reading column beside a
 * `shrink-0 w-[360px]` sticky aside, stacked on mobile/tablet →
 * `@app-xl:flex-row` on desktop. The grading-settings drawer content is not
 * built — `onOpenSettings` is a chrome trigger only.
 */

/** One personal-project schema-v1 evaluation criterion — the legacy rubric row. */
export interface PersonalProjectTaskLegacyCriterionItem {
    /** Stable React key, also the accordion item id. */
    key: string
    /** The criterion sentence itself. */
    text: string
    /** Points this criterion is worth. */
    score: number
    /** Optional grading hint, markdown. Omit → the panel shows a plain "no hint" line. */
    hint?: string
}

/** One legacy per-language implementation guide (schema-v1 tasks with no authored brief). */
export interface PersonalProjectTaskLegacyCodeImplementationItem {
    /** Stable React key, also the accordion item id. */
    key: string
    /** Target language label, e.g. "TypeScript". */
    lang: string
    /** How to approach the task in this language, markdown. */
    guide: string
    /** A worked example, markdown. */
    example: string
}

/** The task identity this screen reads about. */
export interface PersonalProjectTaskPageTask {
    /** Task title. */
    title: string
    /** One-paragraph summary of what the task asks for. */
    description?: string
}

/** The schema-v2 authored brief for this task. */
export interface PersonalProjectTaskPageBrief {
    /** The brief itself, markdown, already resolved to the active language/locale. */
    body: string
}

/** Cost/quality tier + model byline data for a graded submission — see {@link SubmissionScoreCard}. */
export interface PersonalProjectSubmissionResult {
    /** Points earned on the latest graded attempt. */
    score: number
    /** Points the attempt was scored out of. */
    maxScore?: number
    /** Whether this score cleared the pass bar. */
    isPassing: boolean
    /** The pass bar itself, in points. */
    passScore?: number
    /** A short line of grader feedback. */
    shortFeedback?: string
    /** The model that produced this grade. */
    gradedByModel?: string
    /** Cost/quality tier of {@link gradedByModel}. */
    modelCategory?: AiModelCategory
    /** Relative time since grading, already localized. */
    timeAgo?: string
}

/** Everything the persistent, sticky act column needs — the project-level submission loop. */
export interface PersonalProjectTaskSubmissionPanelProps {
    /** The GitHub repo URL as typed so far. */
    repoUrl: string
    /** Fired as the learner types the repo URL. */
    onRepoUrlChange: (value: string) => void
    /** Validation message for the repo URL field. Set → the field shows invalid. */
    repoUrlError?: string
    /** Grading language summary shown in the settings row, e.g. "TypeScript". */
    settingsLangLabel: string
    /** Grading branch summary shown in the settings row, e.g. "main". */
    settingsBranch: string
    /** Fired when the settings summary row is pressed — chrome trigger only, see file header. */
    onOpenSettings: () => void
    /** Fired to submit the current repo for AI evaluation. */
    onEvaluate: () => void
    /** `true` → the evaluate CTA shows its own spinner and blocks further presses. */
    isEvaluatePending?: boolean
    /** `true` → the evaluate CTA is disabled (the caller's own combined business rule — locked, syncing, …). */
    isEvaluateDisabled?: boolean
    /** `true` → at least one attempt exists, so the secondary actions unlock and the CTA reads "Re-evaluate". */
    hasAttempts?: boolean
    /** Fired to open the full feedback/result page. */
    onOpenFeedbackDetails: () => void
    /** Fired to open the attempts history drawer. */
    onOpenAttempts: () => void
    /** The latest graded attempt. Present → the score card renders; omit → nothing has been graded yet. */
    result?: PersonalProjectSubmissionResult
}

/** Props for {@link PersonalProjectTaskPage}. */
export interface PersonalProjectTaskPageProps {
    /** Breadcrumb trail as DATA — `PageHeader` builds `Breadcrumbs` itself. */
    breadcrumbItems?: Array<BreadcrumbItem>
    /** The task being read/solved. */
    task: PersonalProjectTaskPageTask
    /**
     * `true` → this task is not yet unlocked for the learner (previewing ahead
     * of their current milestone position). Shows the warning banner; nothing
     * else in the reading column changes shape.
     */
    isLocked?: boolean
    /** The schema-v2 authored brief. */
    brief: PersonalProjectTaskPageBrief
    /** Schema-v1 legacy rubric — only present on tasks with no authored brief. */
    legacyCriteria?: Array<PersonalProjectTaskLegacyCriterionItem>
    /** Schema-v1 legacy per-language implementation guides — only present alongside {@link legacyCriteria}. */
    legacyCodeImplementations?: Array<PersonalProjectTaskLegacyCodeImplementationItem>
    /** Lessons related to this task's subject, auto-derived by the caller from its title/description. */
    relatedItems: Array<ContentRelatedItem>
    /** Section label for {@link relatedItems}, e.g. "You might want to read". */
    relatedLabel: string
    /** Everything the persistent, sticky act column needs. */
    submissionPanelProps: PersonalProjectTaskSubmissionPanelProps
    /**
     * `true` → every part that can mirror itself does. Flows down into the
     * reading column's composed parts and the act column's fields/buttons/score
     * card (§12c) rather than a parallel skeleton tree built here.
     */
    isSkeleton?: boolean
}

/** Skeleton placeholder count for the legacy accordions while real data hasn't landed yet. */
const LEGACY_SKELETON_ROWS = 2

/** `ListRow.leading` for the grading-settings summary row — a gear icon, hidden while skeleton. */
const SettingsLeading = ({ isSkeleton }: SkeletonProps) =>
    isSkeleton ? null : <GearSixIcon aria-hidden focusable="false" className="size-4" />

/** `ListRow.trailing` for the grading-settings summary row — the disclosure chevron. */
const SettingsChevron = () => <CaretRightIcon aria-hidden focusable="false" weight="bold" className="size-4" />

/** One markdown body at the `compact` measure the legacy accordion panels use. */
const legacyMarkdown = (body: string) => (
    <MarkdownContent source={body} measure="compact" />
)

/** One legacy code-implementation accordion panel body: guide, then a worked example. */
const legacyCodeBody = (item: PersonalProjectTaskLegacyCodeImplementationItem) => (
    <StackV
        gap={4}

        items={[
            () => (
                <StackV
                    gap={2}
                    items={[
                        () => <Typography size="xs" weight="medium" color="muted" text="Guide" />,
                        () => legacyMarkdown(item.guide),
                    ]}
                />
            ),
            () => (
                <StackV
                    gap={2}
                    items={[
                        () => <Typography size="xs" weight="medium" color="muted" text="Example" />,
                        () => legacyMarkdown(item.example),
                    ]}
                />
            ),
        ]}
    />
)

/**
 * The reading column: task identity (`PageHeader`) + the locked banner + the
 * brief itself + the legacy rubric/implementation guides + related lessons.
 * A private render helper (see file header for why this is not a separate
 * storied component), not an anatomy node of its own.
 */
interface PersonalProjectTaskReadingColumnProps {
    breadcrumbItems?: Array<BreadcrumbItem>
    task: PersonalProjectTaskPageTask
    isLocked: boolean
    brief: PersonalProjectTaskPageBrief
    legacyCriteria?: Array<PersonalProjectTaskLegacyCriterionItem>
    legacyCodeImplementations?: Array<PersonalProjectTaskLegacyCodeImplementationItem>
    relatedItems: Array<ContentRelatedItem>
    relatedLabel: string
    isSkeleton: boolean
}

const readingColumn = (props: PersonalProjectTaskReadingColumnProps) => {
    const {
        breadcrumbItems,
        task,
        isLocked,
        brief,
        legacyCriteria,
        legacyCodeImplementations,
        relatedItems,
        relatedLabel,
        isSkeleton,
    } = props

    const hasLegacyCriteria = (legacyCriteria?.length ?? 0) > 0
    const hasLegacyCode = (legacyCodeImplementations?.length ?? 0) > 0
    const showLegacy = isSkeleton || hasLegacyCriteria || hasLegacyCode
    // Schema-v2 tasks always carry an authored brief; schema-v1 (legacy) tasks
    // hand this screen an empty `body` and rely on the legacy section instead
    // (mirrors `src`'s `TaskBrief` self-hiding when `briefs.length === 0`).
    const showBrief = isSkeleton || brief.body.trim().length > 0

    const criteriaItems: Array<SurfaceCardAccordionItem> = hasLegacyCriteria
        ? (legacyCriteria ?? []).map((item, index) => ({
            id: item.key,
            title: `${index + 1}. ${item.text}`,
            titleEnd: () => <Chip tone="accent" text={`${item.score} points`} />,
            body: () => (
                item.hint
                    ? legacyMarkdown(item.hint)
                    : <Typography size="sm" color="muted"
                        isItalic text="No grading hint yet" />
            ),
        }))
        : isSkeleton
            ? Array.from({ length: LEGACY_SKELETON_ROWS }, (_unused, index) => ({ id: `criteria-skeleton-${index}`, title: "", body: () => null }))
            : []

    const codeItems: Array<SurfaceCardAccordionItem> = hasLegacyCode
        ? (legacyCodeImplementations ?? []).map((item) => ({
            id: item.key,
            title: item.lang,
            body: () => legacyCodeBody(item),
        }))
        : isSkeleton
            ? Array.from({ length: LEGACY_SKELETON_ROWS }, (_unused, index) => ({ id: `code-skeleton-${index}`, title: "", body: () => null }))
            : []

    const readingSectionsItems = [
        () => (
            <PageHeader

                isSkeleton={isSkeleton}
                breadcrumb={() =>
                    isSkeleton || breadcrumbItems?.length ? (
                        <div className="w-fit">
                            <Breadcrumbs collapseOnMobile collapseFrom={4} items={breadcrumbItems ?? []} isSkeleton={isSkeleton} />
                        </div>
                    ) : undefined
                }
                title={task.title}
                description={task.description}
            />
        ),

        ...(!isSkeleton && isLocked
            ? [
                () => (
                    <Callout
                        status="warning"
                        title="Preview of a task not yet unlocked"
                        description="You need to finish the current task before you can work on this one."

                    />
                ),
            ]
            : []),

        ...(showBrief
            ? [
                () => (
                    <SurfaceCard
                        label="Guide"
                        isSkeleton={isSkeleton}

                        body={() => <MarkdownContent source={brief.body} />}
                    />
                ),
            ]
            : []),

        ...(showLegacy
            ? [
                () => (
                    <SurfaceCard
                        label="Evaluation criteria (legacy)"
                        isSkeleton={isSkeleton}

                        body={() => (
                            <StackV
                                gap={6}
                                items={[
                                    ...(hasLegacyCriteria || isSkeleton
                                        ? [
                                            () => (
                                                <SurfaceCardAccordion
                                                    variant="nested"
                                                    items={criteriaItems}
                                                    allowsMultipleExpanded
                                                    isSkeleton={isSkeleton}


                                                />
                                            ),
                                        ]
                                        : []),
                                    ...(hasLegacyCode || isSkeleton
                                        ? [
                                            () => (
                                                <SurfaceCardAccordion
                                                    variant="nested"
                                                    items={codeItems}
                                                    allowsMultipleExpanded
                                                    isSkeleton={isSkeleton}


                                                />
                                            ),
                                        ]
                                        : []),
                                ]}
                            />
                        )}
                    />
                ),
            ]
            : []),

        () => (
            <ContentRelatedList
                label={relatedLabel}
                items={relatedItems}
                isSkeleton={isSkeleton}

            />
        ),
    ]

    return <StackV gap={7} isSkeleton={isSkeleton} items={readingSectionsItems} />
}

/**
 * The persistent, sticky act column: repo URL + settings summary trigger +
 * evaluate/secondary actions + the latest graded result. A private render
 * helper (see file header), not an anatomy node of its own.
 */
interface PersonalProjectTaskActColumnProps {
    panel: PersonalProjectTaskSubmissionPanelProps
