import { Chip, type ChipTone } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { StackV } from "@/components/frames/Stack"

/**
 * `AiQuotaHistoryPanel` — the "History" tab body inside `AiQuotaModal`: a 7-day
 * usage bar chart plus a scrollable, bordered list of recent AI charges.
 * `isLoading` swaps the whole `ChargesList` region for its shimmer mirror; an
 * empty `items` array renders the list's own empty state. The chart draws from
 * `chartPoints` regardless of either.
 */

/** What an AI charge was for — the block owns the display label per surface. */
export type AiQuotaHistorySurface = "grade" | "interview" | "chatbot"

/** {@link AiQuotaHistorySurface} → its display label. The block's own vocabulary (§14d.1). */
const PURPOSE_LABEL: Record<AiQuotaHistorySurface, string> = {
    grade: "Challenge grading",
    interview: "Interview grading",
    chatbot: "AI chat",
}

/** Fallback row title when a charge carries no specific model name. */
const AUTO_MODEL_LABEL = "Automatic model (free)"

/** Unit suffix on every credit-delta chip. */
const CREDITS_UNIT = "credit"

/** One day-bucket plotted on the usage chart. */
export interface AiQuotaHistoryChartPoint {
    /** X-axis label, already formatted (e.g. `"12/07"`). */
    day: string
    /** Credits consumed that day. */
    credits: number
}

/** One row of the recent-charges list. */
export interface AiQuotaHistoryChargeItem {
    /** Stable React key. */
    key: string
    /** Model name, when the charge names one specifically. Falls back to {@link AUTO_MODEL_LABEL}. */
    model?: string
    /** What the charge was for — drives the block-owned {@link PURPOSE_LABEL}. */
    surface: AiQuotaHistorySurface
    /** When the charge happened — the block formats this itself (`HH:mm DD/MM`). */
    occurredAt: string | number | Date
    /** Credit delta for this charge. Sign drives the trailing chip's tone (see judgement call 4). */
    credits: number
}

/** Props for {@link AiQuotaHistoryPanel}. */
export interface AiQuotaHistoryPanelProps {
    /** The 7 day-buckets for the chart. Defaults to an empty plot when omitted. */
    chartPoints?: Array<AiQuotaHistoryChartPoint>
    /** Recent charges, most recent first. `undefined` while the first load is still running. */
    items?: Array<AiQuotaHistoryChargeItem>
    /** `true` while the charges list's first load is running (drives ONLY the `ChargesList` leaf). */
    isLoading: boolean
    /** Where this sits inside its parent. Appearance is not passable — it is already a prop. */
}

/** How many placeholder rows the loading mirror shows — matches the source's 3-row skeleton. */
const SKELETON_ROW_COUNT = 3

/** Chip tone for a credit delta — see judgement call 4 in the file header: ported verbatim. */
const deltaTone = (credits: number): ChipTone => (credits > 0 ? "warning" : "success")

const toListItem = (item: AiQuotaHistoryChargeItem): SurfaceCardListItem => ({
    key: item.key,
    title: item.model ?? AUTO_MODEL_LABEL,
    subtitle: `${PURPOSE_LABEL[item.surface]} · ${dayjs(item.occurredAt).format("HH:mm DD/MM")}`,
    meta: () => <Chip tone={deltaTone(item.credits)} text={`${item.credits} ${CREDITS_UNIT}`} />,
})

/** Placeholder rows for the loading mirror — same row shape, shimmer chip in the meta slot. */
const skeletonItems = (): Array<SurfaceCardListItem> => Array.from({ length: SKELETON_ROW_COUNT }, (_, index) => ({
    key: `skeleton-${index}`,
    title: "Model",
    subtitle: "Purpose · Time",
    meta: () => <Chip isSkeleton />,
}))

/**
 * History tab body of `AiQuotaModal` — usage chart + recent-charges list.
 *
 * @param props - {@link AiQuotaHistoryPanelProps}
 */
export const AiQuotaHistoryPanel = ({
    chartPoints = [],
    items,
    isLoading,
}: AiQuotaHistoryPanelProps) => {
    const isEmpty = !isLoading && (items?.length ?? 0) === 0

    const chart = (
        <StackV gap={4} principle="card-caption"
            explain="Holds caption text under card media so the caption stays attached to the image above it."
            items={[
                () => <Typography size="sm" weight="medium" text="Credits used per day (last 7 days)" />,
                () => (
                    <SurfaceCard
                        variant="nested"
                        padding={4}

                        body={() => (
                            <div className="h-44 w-full text-accent-soft-foreground">
                                <ResponsiveContainer width="100%" height="100%">
                                    <BarChart data={chartPoints} margin={{ top: 8, right: 8, bottom: 0, left: -16 }}>
                                        <CartesianGrid
                                            strokeDasharray="3 3"
                                            stroke="currentColor"
                                            className="text-divider"
                                            vertical={false}
                                        />
                                        <XAxis dataKey="day" tick={{ fontSize: 10 }} interval={0} tickLine={false} axisLine={false} />
                                        <YAxis allowDecimals={false} tick={{ fontSize: 10 }} tickLine={false} axisLine={false} width={28} />
                                        <Tooltip
                                            cursor={{ fill: "currentColor", opacity: 0.08 }}
                                            formatter={(value) => [`${value} ${CREDITS_UNIT}`, ""]}
                                        />
                                        <Bar dataKey="credits" fill="currentColor" radius={[4, 4, 0, 0]} />
                                    </BarChart>
                                </ResponsiveContainer>
                            </div>
                        )}
                    />
                ),
            ]} />
    )

    const chargesList = (
        <StackV gap={4} items={[
            () => <Typography size="sm" weight="medium" text="AI usage history" />,
            () => (
                <div className="max-h-64 overflow-y-auto">
                    <AsyncContent
                        isLoading={isLoading}
                        skeleton={() => <SurfaceCardList variant="nested" items={skeletonItems()} isSkeleton />}
                        isEmpty={isEmpty}
                        emptyContent={{
                            title: "No AI usage yet.",

                        }}
                        content={() => <SurfaceCardList variant="nested" items={(items ?? []).map((item) => toListItem(item))} />}

                    />
                </div>
            ),
        ]} />
    )

    return (
        <StackV
            identity={{ tier: "block", component: "AiQuotaHistoryPanel" }}
            gap={6}
            items={[() => chart, () => chargesList]}
        />
    )
}

import type { ReactNode } from "react"
import { TrayIcon } from "@phosphor-icons/react"
import { Button } from "@/components/atoms/buttons/Button"
import { Typography } from "@/components/atoms/text/Typography"
import { StackV } from "@/components/frames/Stack"

/**
 * Props for the {@link EmptyContent} composite.
 */
export interface EmptyContentProps {
    /** Primary "nothing here" line. */
    title: ReactNode
    /** Optional supporting line below the title. */
    description?: ReactNode
    /**
     * Override the default tray icon. Takes an already-built node (not a
     * component reference) — every call site hands this a pre-sized glyph
     * (`<Icon className="size-8 …" />`), so the shape stays a node here too.
     */
    icon?: ReactNode
    /** Optional retry/refresh handler — renders a button when paired with a label. */
    onRetry?: () => void
    /** Translated label for the retry button (required to render it). */
    retryLabel?: ReactNode
}

/**
 * Standalone empty state — a tray icon, a title + optional description, and
 * an optional "try again" button, centered. The standard `emptyContent` for
 * {@link import("../AsyncContent").AsyncContent}. Pure/props-only, one file (an
 * atom/composite never fetches or resolves i18n) — text arrives already
 * translated from the caller.
 */
export const EmptyContent = ({
    title,
    description,
    icon,
    onRetry,
    retryLabel,
}: EmptyContentProps) => {
    const titleLines = [
        () => <Typography size="sm" weight="medium" align="center" text={title} />,
        ...(description
            ? [() => <Typography size="xs" color="muted" align="center" text={description} />]
            : []),
    ]

    return (
        <StackV identity={{ tier: "block", component: "EmptyContent" }}
            gap={4}
            align="center"
            justify="center"
            padding={6}
            items={[
                () => (
                    <>
                        {icon ?? (
                            <TrayIcon aria-hidden focusable="false" weight="duotone" className="size-8 text-foreground" />
                        )}
                    </>
                ),
                () => <StackV gap={2} principle="title-subtitle"
                    explain="Title over supporting line — not label-field, because neither line is a form control label."
                    items={titleLines} />,
                ...(onRetry && retryLabel
                    ? [() => <Button variant="secondary" size="sm" onPress={onRetry} label={retryLabel} />]
                    : []),
            ]}
        />
    )
}

/** Tier metadata for `EmptyContent`, used by the component registry/Storybook lookup. */
export const meta = { tier: "composite", name: "EmptyContent" } as const

import { WarningOctagonIcon, type Icon as PhosphorIcon } from "@phosphor-icons/react"

import { Typography } from "@/components/atoms/text/Typography"
import { Button } from "@/components/atoms/buttons/Button"
import { StackV } from "@/components/frames/Stack"

/**
 * Props for the {@link ErrorContent} composite.
 */
export interface ErrorContentProps {
    /** Primary error line, already translated. */
    title: string
    /** Optional supporting line below the title (cause / what to do), already translated. */
    description?: string
    /** Override the default warning-octagon glyph — a COMPONENT reference (Phosphor), never JSX. */
    icon?: PhosphorIcon
    /** Retry handler — renders a button when paired with {@link ErrorContentProps.retryLabel}. */
    onRetry?: () => void
    /** Translated label for the retry button (required to render it). */
    retryLabel?: string
}

/**
 * Standalone error state — a warning glyph, a title + optional description, and a
 * "try again" button, centered. Used directly by several screens as the retry
 * state for a failed fetch, and as the `errorContent` of the legacy
 * {@link import("@/components/blocks/async/AsyncContent").AsyncContent} switch.
 *
 * This is a COMPOSITE mislabeled by its folder (BLOCK-7): it takes no domain
 * entity, only already-resolved strings and a handler, so it never fetches and
 * never resolves i18n itself — the caller always hands it translated text.
 *
 * @see Story: .storybook/stories/blocks/async/ErrorContent/ErrorContent.stories
 * @param props - {@link ErrorContentProps}
 */
export const ErrorContent = ({
    title,
    description,
    icon: Icon = WarningOctagonIcon,
    onRetry,
    retryLabel,
}: ErrorContentProps) => (
    <div data-tier="composite" data-component="ErrorContent">
        <StackV
            gap={4}
            align="center"
            padding={6}
            items={[
                () => <Icon aria-hidden focusable="false" weight="duotone" className="size-8 text-foreground" />,
                () => (
                    <StackV
                        gap={2}
                        principle="title-subtitle"
                        explain="Title over supporting line — not label-field, because neither line is a form control label."
                        items={[
                            () => <Typography size="sm" weight="medium" align="center" text={title} />,
                            ...(description
                                ? [() => <Typography size="xs" color="muted" align="center" text={description} />]
                                : []),
                        ]}
                    />
                ),
                ...(onRetry && retryLabel
                    ? [() => <Button variant="secondary" size="sm" onPress={onRetry} label={retryLabel} />]
                    : []),
            ]}
        />
    </div>
)

/** Tier metadata for `ErrorContent`, used by the component registry/Storybook lookup. */
export const meta = { tier: "composite", name: "ErrorContent" } as const

"use client"

/** @noSkeleton renders an invisible scroll marker, not a value — there is nothing behind it to wait for. */

import React from "react"

/** Props for {@link InfiniteScrollSentinel}. */
export interface InfiniteScrollSentinelProps {
    /** Fired once each time the sentinel scrolls into view (and `disabled` is false). */
    onReach: () => void
    /** When true the observer is detached (e.g. no more pages / a load in flight). */
    disabled?: boolean
    /** Scroll root to observe within (defaults to the viewport). */
    root?: Element | null
}

/**
 * Invisible end-of-list marker for infinite scroll: an `IntersectionObserver`
 * fires {@link InfiniteScrollSentinelProps.onReach} when it becomes visible, so
 * the list grows on scroll instead of via a "load more" button.
 *
 * Only for a list inside its OWN scroll container (modal / panel / rail) with
 * nothing below it. A list in the page's main column (footer underneath) must
 * use a "load more" button instead — auto-loading steals the scroll and the
 * footer becomes unreachable. A finite list the user browses to pick from wants
 * a pager instead (compose `AsyncContent` with a pagination control).
 *
 * Pair with `useSWRInfinite` — `onReach={() => setSize((s) => s + 1)}`,
 * `disabled={!hasMore || isLoadingMore}` where
 * `isLoadingMore = isValidating && (pages?.length ?? 0) < size`. While a page is
 * in flight, render skeletons mirroring 1-2 real items right here at the
 * sentinel, never a bare "loading" line.
 *
 * @see Story: .storybook/stories/blocks/async/InfiniteScrollSentinel/InfiniteScrollSentinel.stories
 * @param props - {@link InfiniteScrollSentinelProps}
 */
export const InfiniteScrollSentinel = ({
    onReach,
    disabled = false,
    root = null,
}: InfiniteScrollSentinelProps) => {
    const ref = React.useRef<HTMLDivElement>(null)
    // keep the latest callback without re-subscribing the observer each render
    const onReachRef = React.useRef(onReach)
    onReachRef.current = onReach

    React.useEffect(() => {
        const node = ref.current
        if (!node || disabled) {
            return
        }
        const observer = new IntersectionObserver(
            (entries) => {
                if (entries.some((entry) => entry.isIntersecting)) {
                    onReachRef.current()
                }
            },
            { root, rootMargin: "120px" },
        )
        observer.observe(node)
        return () => observer.disconnect()
    }, [disabled, root])

    return (
        <div
            ref={ref}
            aria-hidden
            data-tier="atom"
            data-component="InfiniteScrollSentinel"
            className="h-px w-full"
        />
    )
}

/** Tier metadata for `InfiniteScrollSentinel`, used by the component registry/Storybook lookup. */
export const meta = { tier: "atom", name: "InfiniteScrollSentinel" } as const

"use client"

import React from "react"
import {
    useTranslations,
} from "next-intl"
import { Button } from "@/components/atoms/buttons/Button"
import { StackV } from "@/components/frames/Stack"
import type {
    OauthButtonItem,
} from "../map"
import type { KeycloakIdentityProvider } from "@/modules/api/graphql/mutations/types/exchange-code-for-token"

/** Props for {@link OauthButtons}. */
export interface OauthButtonsProps {
    /** OAuth provider buttons to render, in display order. */
    items: Array<OauthButtonItem>
    /** Fired with the chosen provider when a button is pressed. */
    onOauthPress: (provider: KeycloakIdentityProvider) => void
}

/**
 * Vertical stack of OAuth shortcut buttons (Google, GitHub, …).
 *
 * Presentational: maps {@link OauthButtonItem}s to buttons and forwards the
 * chosen provider up via `onOauthPress`. No business logic.
 * @param props - provider items and the press callback
 */
export const OauthButtons = ({
    items,
    onOauthPress,
}: OauthButtonsProps) => {
    const t = useTranslations()
    const buttonItems = items.map((item) => () => (
        <Button
            variant="outline"
            label={t(item.labelKey)}
            prefixIcon={item.icon}
            classNames={["w-full"]}
            onPress={() => onOauthPress(item.provider)}
        />
    ))
    return <StackV identity={{ tier: "block", component: "OauthButtons" }} gap={3} items={buttonItems} />
}

"use client"

/**
 * **Sign-in step 1** — OAuth shortcuts, email/password, link to sign-up tab.
 *
 * Container: owns the sign-in formik (singleton `useSignInForm()`), the
 * router/dispatch wiring, and the OAuth redirect action; renders presentational
 * children as content only (no modal CloseTrigger / Header / Body).
 *
 * @see {@link SignInSection} for Redux step routing and folder conventions.
 */
import React, {
    useCallback,
    useMemo,
} from "react"
import { useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { OAUTH_BUTTON_ITEMS } from "./map"
import { OauthButtons } from "./OauthButtons"
import { EmailField } from "./EmailField"
import { PasswordField } from "./PasswordField"
import { RememberMeRow } from "./RememberMeRow"
import { SignUpPrompt } from "./SignUpPrompt"
import { useAppDispatch } from "@/redux/hooks"
import { AuthenticationModalTab, setAuthenticationModalTab } from "@/redux/slices/tabs"
import { useSignInForm } from "@/hooks/zustand/signIn/useSignInForm"
import { KeycloakIdentityProvider } from "@/modules/api/graphql/mutations/types/exchange-code-for-token"
import { keycloakRedirect } from "@/modules/api/redirect/keycloak"
import { SessionStorage } from "@/modules/storage/session/storage"
import { SessionStorageId } from "@/modules/storage/session/enums/id"
import { type SessionStorageOauthIdpHint } from "@/modules/storage/session/types/oauth-idp-hint"
import { type SessionStoragePostLoginRedirect } from "@/modules/storage/session/types/post-login-redirect"
import { useSearchParams } from "next/navigation"
import { Turnstile } from "@/components/blocks/auth/Turnstile"
import { publicEnv } from "@/resources/env/public"
import { Typography } from "@/components/atoms/text/Typography"
import { Button } from "@/components/atoms/buttons/Button"
import { Divider } from "@/components/atoms/display/Divider"
import { StackV } from "@/components/frames/Stack"
import { Box } from "@/components/frames/Box"

/**
 * Credentials step container for the sign-in tab.
 */
export const CredentialsState = () => {
    const t = useTranslations()
    const searchParams = useSearchParams()
    const {
        values,
        errors,
        touched,
        submitForm,
        setFieldValue,
        setFieldTouched,
        isSubmitting,
    } = useSignInForm()

    const router = useRouter()
    const dispatch = useAppDispatch()

    /** Stable reference to the static OAuth button catalog. */
    const oauthButtons = useMemo(
        () => OAUTH_BUTTON_ITEMS,
        [],
    )

    /** Start the Keycloak OAuth redirect for the chosen provider. */
    const onOauthPress = useCallback(
        (provider: KeycloakIdentityProvider) => {
            // remember which IdP was used so the callback can resume the flow
            SessionStorage.setItem<SessionStorageOauthIdpHint>(
                SessionStorageId.OauthIdpHint,
                { provider },
            )
            // carry the originally-requested protected route (set by the edge guard as
            // `?redirect=`) through the Keycloak round-trip, since query params on THIS
            // page don't survive the IdP hop.
            const redirectTarget = searchParams.get("redirect")
            if (redirectTarget) {
                SessionStorage.setItem<SessionStoragePostLoginRedirect>(
                    SessionStorageId.PostLoginRedirect,
                    { target: redirectTarget },
                )
            }
            const url = provider === KeycloakIdentityProvider.Google
                ? keycloakRedirect.google
                : keycloakRedirect.github
            url.searchParams.set("redirect_uri", window.location.href)
            router.push(url.toString())
        },
        [
            router,
            searchParams,
        ],
    )

    const onChangeEmail = useCallback(
        (value: string) => {
            setFieldValue("email", value)
        },
        [
            setFieldValue,
        ],
    )

    const onChangePassword = useCallback(
        (value: string) => {
            setFieldValue("password", value)
        },
        [
            setFieldValue,
        ],
    )

    const onChangeRememberMe = useCallback(
        (selected: boolean) => {
            // third arg true: run validation so dependent errors clear
            setFieldValue("rememberMe", selected, true)
            setFieldTouched("rememberMe", true, false)
        },
        [
            setFieldValue,
            setFieldTouched,
        ],
    )

    const onSubmit = useCallback(
        () => {
            submitForm()
        },
        [
            submitForm,
        ],
    )

    const onSwitchToSignUp = useCallback(
        () => {
            dispatch(setAuthenticationModalTab(AuthenticationModalTab.SignUp))
        },
        [
            dispatch,
        ],
    )

    const isSubmitDisabled = publicEnv().captcha.enabled && !values.captchaToken

    const bodyItems = [
        () => (
            <Box className="pr-8">
                <StackV
                    gap={2}
                    principle="title-subtitle"
                    explain="Title over supporting line — not label-field, because neither line is a form control label."
                    items={[
                        () => <Typography weight="semibold" align="center" text={t("auth.signIn.title")} />,
                        () => <Typography size="xs" color="muted" align="center" text={t("auth.signIn.desc")} />,
                    ]}
                />
            </Box>
        ),
        () => (
            <StackV
                gap={4}
                items={[
                    () => <OauthButtons items={oauthButtons} onOauthPress={onOauthPress} />,
                    () => <Divider label={t("auth.signIn.or")} />,
                ]}
            />
        ),
        () => (
            <StackV
                gap={4}
                items={[
                    () => (
                        <EmailField
                            value={values.email}
                            error={errors.email}
                            touched={touched.email}
                            onChangeValue={onChangeEmail}
                        />
                    ),
                    () => (
                        <PasswordField
                            value={values.password}
                            error={errors.password}
                            touched={touched.password}
                            onChangeValue={onChangePassword}
                        />
                    ),
                    () => (
                        <RememberMeRow
                            isSelected={values.rememberMe}
                            onChangeSelected={onChangeRememberMe}
                        />
                    ),
                ]}
            />
        ),
        ...(publicEnv().captcha.enabled ? [() => (
            <Turnstile
                onVerify={(token: string) => setFieldValue("captchaToken", token)}
                onExpire={() => setFieldValue("captchaToken", undefined)}
                onError={() => setFieldValue("captchaToken", undefined)}
            />
        )] : []),
        () => (
            <Button
                variant="primary"
                classNames={["w-full"]}
                isPending={isSubmitting}
                isDisabled={isSubmitDisabled}
                label={t("auth.signIn.submit")}
                onPress={onSubmit}
            />
        ),
        () => <SignUpPrompt onSwitchToSignUp={onSwitchToSignUp} />,
    ]

    return (
        <StackV
            identity={{ tier: "block", component: "CredentialsState" }}
            gap={6}
            items={bodyItems}
        />
    )
}

"use client"

/**
 * **Sign-in step 2** — OTP entry after `signInInit` succeeds.
 *
 * Same singleton Formik as credentials step. Description uses `t.rich` so the email can be styled.
 * Submit runs the OTP verify branch in `useSignInForm` while `signInState === OTP`.
 *
 * @see {@link SignInSection} for step routing; mirror this folder when sign-up adds a verify-email step.
 */
import { InputOtp } from "@/components/atoms/forms"
import React from "react"
import { useTranslations } from "next-intl"
import { useMutateSignInResendOtpSwr } from "@/hooks/swr/api/graphql/mutations/useMutateSignInResendOtpSwr"
import { useSignInForm } from "@/hooks/zustand/signIn/useSignInForm"
import { useGraphQLWithToast } from "@/modules/toast/hooks"
import { Typography } from "@/components/atoms/text/Typography"
import { Button } from "@/components/atoms/buttons/Button"

import { StackV, StackH } from "@/components/frames/Stack"
import { Box } from "@/components/frames/Box"

/**
 * OTPState component.
 */
export const OtpState = () => {
    const t = useTranslations()
    const runGraphQL = useGraphQLWithToast()
    const { trigger: mutateSignInResendOtp, isMutating: isResending } = useMutateSignInResendOtpSwr()
    const {
        values,
        errors,
        touched,
        submitForm,
        setFieldValue,
        isSubmitting,
    } = useSignInForm()

    const onResend = async () => {
        const challengeId = values.challengeId
        if (!challengeId) {
            return
        }
        await runGraphQL(
            async () => {
                const apolloResult = await mutateSignInResendOtp({
                    request: {
                        challengeId,
                    },
                })
                const env = apolloResult.data?.signInResendOtp
                if (!env?.success || !env.data?.challengeId) {
                    throw new Error(
                        env?.error ?? env?.message ?? "signInResendOtp failed"
                    )
                }
                await setFieldValue("challengeId", env.data.challengeId)
                await setFieldValue("otp", "", true)
                return env
            },
            {
                showErrorToast: true,
                showSuccessToast: true,
            }
        )
    }

    const otpInvalid = !!(touched.otp && errors.otp)

    const resendRow = [
        () => <Typography size="xs" color="muted" text={t("auth.signIn.otp.resend")} />,
        () => (
            <Typography
                size="xs"
                isLink
                color={isResending ? "muted" : "accent-soft"}
                onPress={() => {
                    if (isResending) return
                    void onResend()
                }}
                text={t("auth.signIn.otp.resendLink")}
            />
        ),
    ]

    const otpFieldItems = [
        () => (
            <InputOtp
                value={values.otp}
                onValueChange={(value) => setFieldValue("otp", value)}
                isInvalid={otpInvalid}
                errorMessage={otpInvalid ? errors.otp : undefined}
            />
        ),
        () => (
            <StackH
                gap={3}
                principle="flex-action"
                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                justify="center"
                items={resendRow}
            />
        ),
    ]

    const bodyItems = [
        () => (
            <Box className="pr-8">
