"use client"

import React, {
    useMemo,
    useState,
    type ComponentType,
} from "react"
import {
    ArrowRightIcon,
    BookOpenIcon,
    CheckCircleIcon,
    UsersIcon,
} from "@phosphor-icons/react"
import {
    Button,
    Card,
    Chip,
    Typography,
    cn,
} from "@heroui/react"
import { PriceTagInline } from "@/components/blocks/commerce/PriceTag"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import type { CourseEntity } from "@/modules/types/entities/course"
import { publicEnv } from "@/resources/env/public"

/** Props for {@link _CourseCard} — presentational; all data + labels already resolved. */
export interface CourseCardProps {
    /** The course summarised by this card (list-item data). */
    course: CourseEntity
    /**
     * Loyalty-discounted VND price (what THIS viewer is actually charged, from
     * `coursePricePreview`). When set it takes over the price block so the catalog
     * shows the same personalised price as the rest of the app; omit for the phase
     * price (guests / not-yet-loaded).
     */
    loyaltyPriceVnd?: number | null
    /** List/original VND price struck through under the loyalty price. */
    loyaltyOriginalVnd?: number | null
    /**
     * Whether the loyalty preview is still resolving (authenticated viewer only —
     * guests never set this). Skeletons the price line instead of showing the
     * phase price and then swapping to the loyalty price a beat later.
     */
    loyaltyPending?: boolean
    /**
     * Layout: a roomy `"grid"` card (default — cover + outcomes + price) or a
     * compact `"line"` row (thumbnail + title + price + CTA on one line). Lets the
     * catalog offer a grid ⇆ list view toggle without a second card component.
     */
    layout?: "grid" | "line"
    /**
     * Optional trailing action node (e.g. an "Add to cart" button) rendered beside
     * the View CTA. The block only places it; the caller (a feature) owns its logic
     * so the card stays presentational.
     */
    action?: ComponentType
    /** Already-localized primary CTA label ("Continue learning" once enrolled, else "View course"). */
    viewLabel: string
    /** Already-localized secondary "View course" label, shown once enrolled (beside the primary CTA). */
    viewCourseLabel: string
    /** Already-localized "N learners" chip label; omitted when the course has no enrollments. */
    learnersLabel?: string
    /** Already-localized/formatted USD price hint line; omitted when there's no USD price. */
    priceUsdHintLabel?: string
    /** Fired by the primary CTA — continue learning if enrolled, else go to the marketing page. */
    onView: () => void
    /** Fired by the secondary "View course" button shown once enrolled. */
    onViewDetail: () => void
}

/**
 * Featured course card (catalog block): cover (with branded fallback), title,
 * outcome, social proof + top value propositions, and a price block (active-phase
 * price, original strikethrough + % off when discounted, optional USD hint) with a
 * view CTA. Owns its whole look so features just feed the `course`.
 *
 * @param props - {@link CourseCardProps}
 */
export const _CourseCard = ({
    course,
    loyaltyPriceVnd,
    loyaltyOriginalVnd,
    loyaltyPending = false,
    layout = "grid",
    action: Action,
    viewLabel,
    viewCourseLabel,
    learnersLabel,
    priceUsdHintLabel,
    onView,
    onViewDetail,
}: CourseCardProps) => {
    const [coverFailed, setCoverFailed] = useState(false)

    // display transform for ENTITY-derived (fallback) VND prices so the catalog matches
    // the rest of the app: ÷ testDivisor in non-prod. The loyalty price (from
    // `coursePricePreview`) is ALREADY transformed → not re-applied.
    const divisor = publicEnv().pricing.testDivisor
    const toVnd = (amount: number): number =>
        divisor === 1 ? amount : Math.max(1, Math.round(amount / divisor))

    /** Active-phase price (falls back to the list/regular price when no phase row). */
    const currentPrice = useMemo(
        () => course.pricingPhases?.find(
            (pricingPhase) => pricingPhase.phase === course.currentPhase,
        )?.price ?? course.originalPrice ?? null,
        [course.pricingPhases, course.currentPhase, course.originalPrice],
    )

    /** Top three value propositions shown as a quick "what you'll learn" list. */
    const topValueProps = useMemo(
        () => (course.valuePropositions ?? []).slice(0, 3),
        [course.valuePropositions],
    )

    // enrolled → the marketing/detail page is the wrong destination for the PRIMARY
    // action (the viewer already owns this course); the connected half already routed
    // `onView` into the learning experience. The marketing page is still a legitimate
    // secondary destination once enrolled (re-check the syllabus, share the link).
    const isEnrolled = course.isEnrolled === true
    // not enrolled → the feature-owned `action` slot (cart-add, hides itself for
    // free/enrolled courses per its own logic). Enrolled → that slot would render
    // null anyway, so replace it with a secondary "View course" button (view the
    // marketing page) — teacher: "a card for an already-purchased course should have
    // 2 parts: continue learning (primary) and view course (secondary)", don't just
    // drop the second button once enrolled.
    const secondaryAction = isEnrolled ? (
        // no trailing arrow — arrow marks the ONE primary CTA per surface
        // (button.md §2: "a button WITHOUT an icon = sub-CTA"); keeping it here as
        // well as on "Continue learning" made both buttons read as equally weighted.
        <Button
            variant="secondary"
            onPress={onViewDetail}
            className="flex-1"
        >
            {viewCourseLabel}
        </Button>
    ) : Action ? <Action /> : null

    const showCover = Boolean(course.coverImageUrl) && !coverFailed

    // price block: prefer the viewer's loyalty price (uniform with the rest of the app)
    // when supplied, else fall back to the active-phase price.
    const useLoyalty = loyaltyPriceVnd != null
    const displayPrice = useLoyalty
        ? loyaltyPriceVnd
        : (currentPrice != null ? toVnd(currentPrice) : null)
    const displayOriginal = useLoyalty
        ? loyaltyOriginalVnd ?? null
        : (course.originalPrice != null ? toVnd(course.originalPrice) : null)

    // compact LINE row (catalog list view): thumbnail + title/description, with the
    // price + view CTA on the right — one course per row for fast scanning.
    if (layout === "line") {
        return (
            <Card className={cn("overflow-hidden rounded-3xl")}>
                {/* plain div, NOT Card.Content — `.card__content` bakes flex-col
                    (unlayered), so `items-center` on it centers vertically instead of
                    laying the row out horizontally. The card root already insets its
                    children (baked `p-4`), so this row carries no padding of its own. */}
                <div className="flex items-center gap-3">
                    {/* thumbnail 16:9 (branded fallback); hidden on the narrowest screens.
                        rounded-2xl = the "inner" step under the card's rounded-3xl. */}
                    <div className="relative hidden aspect-video w-36 shrink-0 overflow-hidden rounded-2xl bg-surface @app-sm:block">
                        {showCover ? (
                            <img
                                src={course.coverImageUrl ?? undefined}
                                alt={course.title}
                                className="size-full object-cover"
                                onError={() => setCoverFailed(true)}
                            />
                        ) : (
                            <div className="flex size-full items-center justify-center bg-gradient-to-br from-accent/25 to-accent/5">
                                <BookOpenIcon aria-hidden className="size-8 text-accent-soft-foreground" />
                            </div>
                        )}
                    </div>
                    {/* title + one-line description */}
                    <div className="flex min-w-0 flex-1 flex-col gap-1">
                        <div className="flex items-center gap-2">
                            <Typography type="body" weight="bold" truncate>
                                {course.title}
                            </Typography>
                            {learnersLabel != null ? (
                                <Chip variant="secondary" color="accent" size="sm" className="shrink-0">
                                    <UsersIcon aria-hidden className="size-4" />
                                    <Chip.Label>
                                        {learnersLabel}
                                    </Chip.Label>
                                </Chip>
                            ) : null}
                        </div>
                        <Typography type="body-sm" color="muted" className="line-clamp-1">
                            {course.description}
                        </Typography>
                    </div>
                    {/* price row, then a button row below — view CTA is now a real primary
                        Button (not a subtle Link), per starci-fe-block-variants round-2
                        direction "C". `size="md"` per button.md §3's compact-context
                        exception (a repeated grid card is a tight context — `lg` would
                        blow up row height across many cards). */}
                    <div className="flex shrink-0 flex-col items-end gap-2">
                        {loyaltyPending ? (
                            <Skeleton.Typography type="body-sm" width="1/2" />
                        ) : displayPrice != null ? (
                            <PriceTagInline
                                discounted={displayPrice}
                                original={displayOriginal}
                               
                            />
                        ) : null}
                        <div className="flex w-full items-center gap-2">
                            <Button
                                variant="primary"
                                onPress={onView}
                                className="flex-1"
                            >
                                {viewLabel}
                                <ArrowRightIcon aria-hidden focusable="false" className="size-4" />
                            </Button>
                            {secondaryAction}
                        </div>
                    </div>
                </div>
            </Card>
        )
    }

    return (
        <Card className={cn("flex flex-col overflow-hidden rounded-3xl")}>
            <Card.Content className="flex flex-col gap-3">
                {/* cover 16:9 — rounded-2xl = the "inner" step under the card's
                    rounded-3xl (was full-bleed/unrounded, mismatched the line thumb);
                    the card root already insets its children (baked `p-4`); branded
                    gradient fallback when missing/broken */}
                <div className="relative aspect-video w-full overflow-hidden rounded-2xl bg-surface">
                    {showCover ? (
                        <img
                            src={course.coverImageUrl ?? undefined}
                            alt={course.title}
                            className="size-full object-cover"
                            onError={() => setCoverFailed(true)}
                        />
                    ) : (
                        <div className="flex size-full items-center justify-center bg-gradient-to-br from-accent/25 to-accent/5 p-4">
                            <BookOpenIcon aria-hidden className="size-10 text-accent-soft-foreground" />
                            <Typography type="body-sm" weight="semibold" align="center" className="ml-2">
                                {course.title}
                            </Typography>
                        </div>
                    )}
                </div>

                <div className="flex flex-col gap-2">
                    <div className="flex items-center justify-between gap-2">
                        <Typography type="h6" weight="bold" truncate>
                            {course.title}
                        </Typography>
                        {learnersLabel != null ? (
                            <Chip variant="secondary" color="accent" size="sm" className="shrink-0">
                                <UsersIcon aria-hidden className="size-4" />
                                <Chip.Label>
                                    {learnersLabel}
                                </Chip.Label>
                            </Chip>
                        ) : null}
                    </div>
                    <Typography type="body-sm" color="muted" className="line-clamp-2">
                        {course.description}
                    </Typography>
                    {topValueProps.length > 0 ? (
                        <ul className="mt-1 flex flex-col gap-2">
                            {topValueProps.map((valueProp, index) => (
                                <li key={index} className="flex items-start gap-2">
                                    <CheckCircleIcon aria-hidden className="size-4 shrink-0 text-success-soft-foreground" />
                                    <Typography type="body-xs" color="muted">
                                        {valueProp.text}
                                    </Typography>
                                </li>
                            ))}
                        </ul>
                    ) : null}
                </div>
            </Card.Content>
            <Card.Footer className="mt-auto flex flex-col gap-2">
                {/* price row (informational) */}
                <div className="flex items-center gap-2">
                    {loyaltyPending ? (
                        <Skeleton.Typography type="body-sm" width="1/2" />
                    ) : displayPrice != null ? (
                        <PriceTagInline
                            discounted={displayPrice}
                            original={displayOriginal}
                           
                        />
                    ) : (
                        <span />
                    )}
                </div>
                {priceUsdHintLabel != null ? (
                    <Typography type="body-xs" color="muted">
                        {priceUsdHintLabel}
                    </Typography>
                ) : null}
                {/* action row — view CTA is a real primary Button (not a subtle Link), per
                    starci-fe-block-variants round-2 direction "C": the previous accent Link
                    read as a secondary "see more" action rather than the card's actual primary
                    action. `size="md"` per button.md §3's compact-context exception (a
                    repeated grid card is tight — `lg` would blow up card height across many
                    cards). Cart-add stays `action` (secondary, pairs with this primary). */}
                <div className="flex w-full items-center gap-2">
                    <Button
                        variant="primary"
                        onPress={onView}
                        className="flex-1"
                    >
                        {viewLabel}
                        <ArrowRightIcon aria-hidden focusable="false" className="size-4" />
                    </Button>
                    {secondaryAction}
                </div>
            </Card.Footer>
        </Card>
    )
}

"use client"

import React, { useState, type ComponentType } from "react"
import { ScrollShadow, cn } from "@heroui/react"
import { AnimatePresence, motion } from "framer-motion"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"

/** Props for the {@link FlipCard} block. */
export interface FlipCardProps {
    /** Whether the answer card is currently revealed below the question. */
    revealed: boolean
    /** Label shown OUTSIDE (above) the question card — e.g. "Question". */
    questionLabel: string
    /** Label shown OUTSIDE (above) the answer card — e.g. "Answer". */
    answerLabel: string
    /** Front (prompt) content — a buildable slot that sits in the question card. */
    front: ComponentType
    /**
     * Optional slot rendered DIRECTLY under the question card (grouped with it,
     * `gap-3`) — ABOVE the answer, so it stays anchored to the question when the
     * answer reveals below (teacher 2026-07-13: "chips gap-3 under the question"). Used for
     * the card's level/tag chips.
     */
    belowFront?: ComponentType
    /** Back (answer) content — a buildable slot shown once {@link revealed}. */
    back: ComponentType
}

/**
 * Anki-style "no-flip" prompt/answer pair: the question and the answer are TWO
 * SEPARATE {@link LabeledCard}s — each label ("Question" / "Answer") sits OUTSIDE,
 * above its card (teacher 2026-07-12: "question, answer outside as a labeled card"),
 * not an eyebrow inside the card. The answer card reveals below the question one
 * (height-animate) once {@link revealed}. Retrieval-practice research (teacher
 * 2026-07-11) says what matters for recall is committing to an answer BEFORE
 * seeing it — the caller owns the "Show answer" reveal control and renders it
 * BETWEEN this block and the rating; this block is purely presentational.
 * @param props - {@link FlipCardProps}
 */
export const FlipCard = ({ revealed, questionLabel, answerLabel, front: Front, belowFront: BelowFront, back: Back}: FlipCardProps) => {
    // `overflow-hidden` is only needed WHILE the height animates — left on at
    // rest, it permanently clips the answer `Card`'s own box-shadow along every
    // edge, so it read flatter than the question card right above it (teacher:
    // "can the yellow one render as a card like the red one, with a
    // shadow..."). Drop it once the reveal animation settles so the shadow
    // shows in full, same as the un-clipped question card.
    const [animating, setAnimating] = useState(false)
    return (
        <div className={"flex flex-col gap-6"}>
            {/* question card + its `belowFront` chips grouped `gap-3` — the chips
                stay under the QUESTION when the answer reveals below (not pushed
                to the bottom of the answer). */}
            <div className="flex flex-col gap-3">
                <LabeledCard label={questionLabel} bordered>
                    <Front />
                </LabeledCard>
                {BelowFront ? <BelowFront /> : null}
            </div>
            {/* answer = its OWN labeled card, revealed below (height-animate so the
                reveal still feels connected) */}
            <AnimatePresence initial={false}>
                {revealed ? (
                    <motion.div
                        key="answer"
                        initial={{ height: 0, opacity: 0 }}
                        animate={{ height: "auto", opacity: 1 }}
                        exit={{ height: 0, opacity: 0 }}
                        transition={{ duration: 0.25, ease: "easeInOut" }}
                        onAnimationStart={() => setAnimating(true)}
                        onAnimationComplete={() => setAnimating(false)}
                        className={cn(animating && "overflow-hidden")}
                    >
                        <LabeledCard label={answerLabel} bordered>
                            <ScrollShadow hideScrollBar className="flex max-h-[28rem] flex-col gap-3 overflow-y-auto text-left">
                                <Back />
                            </ScrollShadow>
                        </LabeledCard>
                    </motion.div>
                ) : null}
            </AnimatePresence>
        </div>
    )
}

"use client"

import React, { useEffect, type ComponentType } from "react"
import { cn } from "@heroui/react"
import { PressableCard } from "@/components/blocks/cards/PressableCard"
import { type VerdictBand, verdictBandClassName } from "@/components/blocks/cards/verdict-band"

/**
 * Column count per CONTAINER width — these are container queries, not viewport
 * breakpoints. A block cannot know where it is placed: the same grid may sit in a
 * full page column or in a 256px rail, and a viewport breakpoint gets the rail
 * case wrong every time (wide window + narrow slot = cards crushed to a sliver).
 * Steps mirror Tailwind v4's container sizes, so the key IS the class suffix.
 */
export interface GroupPressableCardColumns {
    /** Columns at the narrowest. Defaults to `1`. */
    base?: 1 | 2
    /** From a 24rem / 384px container. */
    sm?: 2 | 3 | 4
    /** From a 28rem / 448px container. */
    md?: 2 | 3 | 4
    /** From a 32rem / 512px container. */
    lg?: 2 | 3 | 4
    /** From a 36rem / 576px container. */
    xl?: 2 | 3 | 4
    /** From a 48rem / 768px container. */
    xl3?: 2 | 3 | 4
    /** From a 56rem / 896px container. */
    xl4?: 2 | 3 | 4
}

/** One pressable card inside a {@link GroupPressableCard}. */
export interface GroupPressableCardItem {
    /** Stable React key. Also fixes the item's position for the 1–N shortcut. */
    key: string
    /** Card body — a buildable slot composed freely by the caller (icon tiles, text, chips…). */
    content: ComponentType
    /** Press handler. Ignored when {@link GroupPressableCardItem.href} is set. */
    onPress?: () => void
    /** Navigation target — renders this card as an anchor. */
    href?: string
    /** Dims the card and blocks both pressing and the keyboard shortcut. */
    isDisabled?: boolean
    /** Accessible name — needed only when {@link GroupPressableCardItem.content} carries no readable text. */
    label?: string
    /**
     * Forwarded to this card's own `className` — for grid placement (`@lg:col-start-2`
     * to pin a lone card to the right column) and for tile-level tweaks on top of
     * the `PressableCard` surface (a tighter `rounded-xl px-3 py-2` rating tile).
     *
     * Placement classes must use the **container** variant (`@lg:`), NOT the viewport
     * one (`lg:`), and must name the SAME step at which
     * {@link GroupPressableCardProps.columns} actually reaches that column — a
     * `col-start-2` that outruns the column count lands in an implicit,
     * content-sized track and squeezes the card to a sliver.
     */
    className?: string
    /**
     * Verdict variant: a LEFT band (`border-l-4`) marking this tile with a signal that
     * comes from DATA (`card.md` §3i) — e.g. the SM-2 recall grade's tier. The canonical
     * {@link VerdictBand} (`variant` semantic, or `color` raw-palette escape hatch), the
     * SAME shape as `SectionCard`/`SurfaceListCardItem`.
     */
    withVerdict?: VerdictBand
}

/** Props for the {@link GroupPressableCard} block. */
export interface GroupPressableCardProps {
    /** The cards, in reading order (also the 1–N shortcut order). */
    items: Array<GroupPressableCardItem>
    /**
     * Accessible name for the whole group — REQUIRED. Without it a screen reader
     * hears N loose buttons with nothing tying them together.
     */
    ariaLabel: string
    /** Responsive column count. Defaults to a single column. */
    columns?: GroupPressableCardColumns
    /** Gap between cards on the spacing scale. Defaults to `3`. */
    gap?: 2 | 3
    /**
     * Binds number keys `1`–`N` to the items in order, so the group can be driven
     * without the mouse. Off by default — only opt in where the group IS the
     * screen's primary action (e.g. a flashcard rating bar), never for an
     * incidental grid of navigation tiles that would hijack digits globally.
     */
    keyboardShortcut?: boolean
}

// Compact grid cell, not a standalone top-level card: one step down from
// `PressableCard`'s own `rounded-3xl`/`shadow-surface` default (concentric
// radius: card 24px − 1 step → 16px) and one step UP from the flat button /
// `shadow-field` input — `GroupPressableCard` is the ONLY place this chrome
// lives; `PressableCard` used standalone (a real full-size card, e.g.
// `ConsultantCard`) keeps its own bigger default untouched.
const TILE_CHROME = "rounded-2xl shadow-field"

// Tailwind needs LITERAL class strings — `@sm:grid-cols-${n}` interpolation is
// never emitted by the compiler, so each supported count maps to a written-out
// class. The `@` prefix = container query (Tailwind v4 core, no plugin).
/** Grid template per base column count. */
const BASE_COLUMNS_CLASS: Record<1 | 2, string> = {
    1: "grid-cols-1",
    2: "grid-cols-2",
}
/** Container-step key → its literal class map, applied in ascending width order. */
const STEP_COLUMNS_CLASS: Record<
    Exclude<keyof GroupPressableCardColumns, "base">,
    Record<2 | 3 | 4, string>
> = {
    sm: { 2: "@sm:grid-cols-2", 3: "@sm:grid-cols-3", 4: "@sm:grid-cols-4" },
    md: { 2: "@md:grid-cols-2", 3: "@md:grid-cols-3", 4: "@md:grid-cols-4" },
    lg: { 2: "@lg:grid-cols-2", 3: "@lg:grid-cols-3", 4: "@lg:grid-cols-4" },
    xl: { 2: "@xl:grid-cols-2", 3: "@xl:grid-cols-3", 4: "@xl:grid-cols-4" },
    xl3: { 2: "@3xl:grid-cols-2", 3: "@3xl:grid-cols-3", 4: "@3xl:grid-cols-4" },
    xl4: { 2: "@4xl:grid-cols-2", 3: "@4xl:grid-cols-3", 4: "@4xl:grid-cols-4" },
}
/** Ascending container-step order — later steps must win, so emit them in width order. */
const STEP_ORDER = ["sm", "md", "lg", "xl", "xl3", "xl4"] as const
/** Gap class per supported spacing step. */
const GAP_CLASS: Record<2 | 3, string> = {
    2: "gap-2",
    3: "gap-3",
}

/**
 * A grid of `PressableCard`s that act and then get out of the way — the whole
 * group is ONE labelled unit (`role="group"` + `aria-label`), each cell is a
 * canonical `PressableCard`, and the cards' bodies stay the caller's to compose.
 *
 * Exists because a bare `<div className="grid">` of cards leaves a screen reader
 * hearing N loose buttons with nothing tying them together, and because the same
 * responsive-grid + keyboard plumbing was being hand-rolled at every call site.
 *
 * Reflows on the CONTAINER's width, not the viewport's ({@link GroupPressableCardColumns}) —
 * a reusable block does not know whether it was dropped into a full page column or
 * a 256px rail, and a viewport breakpoint reads a wide window as "I have room" even
 * when the actual slot is a sliver.
 *
 * **Not a selection control.** Nothing here stays "chosen": press a card and the
 * surface acts (grade the card, open the page) — so these are ACTIONS, not radios.
 * When the pick must PERSIST and read back as "this is my choice", use
 * `SelectableCardGroup` instead (a real HeroUI `RadioGroup`: `value`/`onChange`,
 * accent outline on the selected card, arrow-key roving). Deliberately no
 * `selected` prop here — that boundary is the whole point of two blocks.
 *
 * @param props - {@link GroupPressableCardProps}
 * @see Story: .storybook/stories/blocks/cards/GroupPressableCard/GroupPressableCard.stories
 */
export const GroupPressableCard = ({
    items,
    ariaLabel,
    columns = {},
    gap = 3,
    keyboardShortcut = false,
}: GroupPressableCardProps) => {
    // `items` is typically rebuilt inline by the caller (`options.map(...)`), so a
    // fresh array arrives every render. Reading it through a ref keeps the window
    // listener subscribed ONCE instead of tearing down and re-adding on each pass,
    // while the handler still sees the current items.
    const itemsRef = React.useRef(items)
    useEffect(() => {
        itemsRef.current = items
    }, [items])

    // Press 1–N to act without reaching for the mouse. Opt-in: the listener is
    // on `window`, so a group that isn't the screen's main action would steal
    // every digit the page sees.
    useEffect(() => {
        if (!keyboardShortcut) {
            return
        }
        const onKeyDown = (event: KeyboardEvent) => {
            // never hijack a digit the user is typing into a field
            const target = event.target as HTMLElement | null
            if (target && (target.tagName === "INPUT" || target.tagName === "TEXTAREA" || target.isContentEditable)) {
                return
            }
            const position = Number(event.key) - 1
            const current = itemsRef.current
            if (!Number.isInteger(position) || position < 0 || position >= current.length) {
                return
            }
            const item = current[position]
            if (item.isDisabled || !item.onPress) {
                return
            }
            event.preventDefault()
            item.onPress()
        }
        window.addEventListener("keydown", onKeyDown)
        return () => window.removeEventListener("keydown", onKeyDown)
    }, [keyboardShortcut])

    // an empty group would announce a label with nothing under it
    if (items.length === 0) {
        return null
    }

    return (
        // The `@container` wrapper is NOT decorative: an element cannot query its
        // own size, so the queried grid must live inside the container it reacts to.
        <div className="@container">
            <div
                role="group"
                aria-label={ariaLabel}
                className={cn(
                    "grid",
                    GAP_CLASS[gap],
                    BASE_COLUMNS_CLASS[columns.base ?? 1],
                    STEP_ORDER.map((step) => {
                        const count = columns[step]
                        return count === undefined ? undefined : STEP_COLUMNS_CLASS[step][count]
                    }),
                )}
            >
                {items.map((item) => {
                    const Content = item.content
                    return (
                        <PressableCard
                            key={item.key}
                            onPress={item.onPress}
                            href={item.href}
                            isDisabled={item.isDisabled}
                            label={item.label}
                            className={cn(
                                TILE_CHROME,
                                // canonical verdict left-band (shape + colour + !important fix)
                                verdictBandClassName(item.withVerdict),
                                item.className,
                            )}
                        >
                            <Content />
                        </PressableCard>
                    )
                })}
            </div>
        </div>
    )
}

"use client"

import React from "react"
/** Props for {@link HighlightCard}. */
export interface HighlightCardProps {
    /** The wrapped card (e.g. a `SectionCard`/`Card`) — `HighlightCard` only adds the sweeping-light layer, it renders no card chrome of its own. */
    children: React.ReactNode
}

/**
 * Wraps a card with a single accent-colored arc SWEEPING around it, sitting as its own
 * layer BEHIND it (peeking out past the edges by 2px) — a pure "stand-out"
 * decoration, NOT a data signal (contrast with `SectionCard`'s `withVerdict`, a static
 * left band that DOES encode band/tier/zone data — `card.md` §3i vs §3j). Renders as 2
 * stacked cards: the INNER layer (bigger, behind, carries the sweeping-light effect) and
 * the wrapped card itself (OUTER, in front, 2px smaller in radius) — see `card.md` §3j
 * for why this is 2 layers and not a `SectionCard` prop. Use for the ONE card that
 * genuinely needs to stand out on a surface (e.g. a "resume your session" hero) —
 * multiple highlighted cards on the same screen cancel each other's emphasis out.
 *
 * @param props - {@link HighlightCardProps}
 * @see Story: .storybook/stories/blocks/cards/HighlightCard/HighlightCard.stories
 */
export const HighlightCard = ({ children}: HighlightCardProps) => (
    <div className={"relative"}>
        <div aria-hidden className="highlight-card-sweep" />
        {children}
    </div>
)

import React, { type ComponentType } from "react"
import { Accordion, Typography, cn } from "@heroui/react"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { SurfaceListCard } from "@/components/blocks/cards/SurfaceListCard"

/** One collapsible section of a {@link LabeledAccordionCard}. */
export interface LabeledAccordionCardItem {
    /** Stable id — also the expand key (matched against `defaultExpandedKeys`). */
    id: string
    /** Trigger headline (the always-visible row). */
    title: string
    /** Optional muted second line in the trigger (a count / hint), under the title. */
    subtitle?: string
    /**
     * Optional trailing slot in the trigger row, right of the title and LEFT of the
     * caret — a status chip / score / count that belongs to the collapsed header
     * (e.g. a per-requirement score, a milestone `StatusChip`, a read count). The
     * title truncates to make room; this stays at intrinsic width.
     */
    titleEnd?: ComponentType
    /** Panel content, revealed when the item expands — a buildable slot. */
    body: ComponentType
}

/** Props for the {@link LabeledAccordionCard} block. */
export interface LabeledAccordionCardProps {
    /**
     * Section label rendered OUTSIDE (above) the card — forwarded to {@link LabeledCard}.
     * OMIT it when the card sits in a pane that already carries a heading/tab of its
     * own (e.g. the Playground Lab "Resources" tab): a second label there is
     * label-on-label (accordion.md §3d). With no label the card renders bare
     * (just the {@link SurfaceListCard} frame), no section wrapper.
     */
    label?: string
    /** Optional passive right-aligned tag in the label row (count / unit). Ignored without `label`. */
    labelEnd?: string
    /** Optional right-aligned action slot in the label row (a button) — a buildable slot. Ignored without `label`. */
    action?: ComponentType
    /** The collapsible sections, in order. */
    items: ReadonlyArray<LabeledAccordionCardItem>
    /**
     * Allow more than one section open at once. Default `false` (a single-open
     * accordion). `allowsMultipleExpanded`, NOT `selectionMode` — that prop does
     * not exist on HeroUI's Accordion (accordion.md §3d).
     */
    allowsMultipleExpanded?: boolean
    /**
     * Sections expanded on mount, keyed by item `id`. A `Set`, not an array
     * (react-aria's collection key set — accordion.md §3d).
     */
    defaultExpandedKeys?: Set<string>
    /**
     * When this card sits NESTED inside another surface (a modal/drawer body),
     * pass `bordered` so it delineates with a border instead of a shadow that can
     * render invisible in dark mode (card.md §0). Forwarded to {@link SurfaceListCard}.
     */
    bordered?: boolean
}

/**
 * The collapsible frame — one bounded `bg-surface` card of sections whose separators
 * run FULL-BLEED to the card edge. Shared by the labeled and unlabeled forms.
 */
const AccordionFrame = ({
    items,
    allowsMultipleExpanded,
    defaultExpandedKeys,
    bordered,
}: Pick<
    LabeledAccordionCardProps,
    "items" | "allowsMultipleExpanded" | "defaultExpandedKeys" | "bordered"
>) => (
    <SurfaceListCard bordered={bordered}>
        {/* variant="default" (NOT surface): the base variant keeps the item separator
            FULL-BLEED (`left-0 w-full`); surface would inset it to 3%. The bg-surface
            frame + clipped corners come from SurfaceListCard, so the accordion stays
            transparent and rides on it (accordion.md §3e).

            Local `--separator` override: the base variant's separator token reads a bit
            heavy; re-point it to the SAME light hairline the SurfaceListCard rows use
            (`bg-surface-foreground/6`) so this card's dividers match the surface-list
            family. Overriding the token (which the item `::after` reads via `bg-separator`)
            is escape-free — no fighting HeroUI's unlayered `::after` with `!important`. */}
        <Accordion
            variant="default"
            style={{ "--separator": "color-mix(in oklab, var(--surface-foreground) 6%, transparent)" } as React.CSSProperties}
            allowsMultipleExpanded={allowsMultipleExpanded}
            defaultExpandedKeys={defaultExpandedKeys}
        >
            {items.map((item) => {
                const TitleEnd = item.titleEnd
                const Body = item.body
                return (
                    <Accordion.Item
                        key={item.id}
                        id={item.id}
                        aria-label={item.title}
                    >
                        <Accordion.Heading>
                            <Accordion.Trigger>
                                <div className="flex min-w-0 flex-1 flex-col gap-0 text-left">
                                    <Typography type="body-sm" weight="medium" truncate>
                                        {item.title}
                                    </Typography>
                                    {item.subtitle != null ? (
                                        <Typography type="body-xs" color="muted" truncate>
                                            {item.subtitle}
                                        </Typography>
                                    ) : null}
                                </div>
                                {/* titleEnd + caret share one group so the trailing chip/count keeps
                                    a `gap-3` breathing room from the indicator instead of touching it */}
                                <div className="flex shrink-0 items-center gap-3">
                                    {TitleEnd ? <TitleEnd /> : null}
                                    <Accordion.Indicator />
                                </div>
                            </Accordion.Trigger>
                        </Accordion.Heading>
                        <Accordion.Panel>
                            <Accordion.Body className={cn("pt-0")}>
                                <Body />
                            </Accordion.Body>
                        </Accordion.Panel>
                    </Accordion.Item>
                )
            })}
        </Accordion>
    </SurfaceListCard>
)

/**
 * A "Accordion Card": one bounded `bg-surface` frame holding collapsible sections
 * whose separators run FULL-BLEED to the card edge — the same skin as
 * {@link SurfaceListCard}, but each row expands. Pass {@link LabeledAccordionCardProps.label}
 * to add a section label OUTSIDE the card; omit it in a pane that already has a tab/heading.
 *
 * The full-bleed separator is why this uses `Accordion variant="default"` rather than
 * the usual `surface` skin: HeroUI's `.accordion--surface` insets the item separator to
 * `left-[3%] w-[94%]`, while the BASE variant keeps it `left-0 w-full`. The surface look
 * (bg + radius + clipped corners) is supplied by the wrapping {@link SurfaceListCard}, so
 * the accordion can stay transparent and ride on it (accordion.md §3d / §3e, card.md §3).
 *
 * Use when a "list card" needs its rows to collapse/expand by group (e.g. the Playground
 * Lab "Resources" tab grouped by kind) — never hand-roll a `<button>` + caret, which
 * reimplements the keyboard/aria HeroUI already ships. Each item's trigger is `title`
 * (+ optional `subtitle` line, + optional trailing `titleEnd` chip); the panel `body` is
 * free content.
 *
 * @param props - {@link LabeledAccordionCardProps}
 * @see Story: .storybook/stories/blocks/cards/LabeledAccordionCard/LabeledAccordionCard.stories
 */
export const LabeledAccordionCard = ({
    label,
    labelEnd,
    action,
    items,
    allowsMultipleExpanded = false,
    defaultExpandedKeys,
    bordered = false,
}: LabeledAccordionCardProps) => {
    const frame = (
        <AccordionFrame
            items={items}
            allowsMultipleExpanded={allowsMultipleExpanded}
            defaultExpandedKeys={defaultExpandedKeys}
            bordered={bordered}
        />
    )
    // no label → the pane already carries a heading/tab; render the frame bare
    if (label == null) {
        return <div>{frame}</div>
    }
    return (
        <LabeledCard
            identity={{ tier: "block", component: "LabeledAccordionCard" }}
            label={label}
            labelEnd={labelEnd}
            action={action}
            frameless

        >
            {frame}
        </LabeledCard>
    )
}

import React, { type ComponentType } from "react"
import type { ReactNode } from "react"
import { Card, CardContent, cn } from "@heroui/react"
import { SeeMoreLink } from "@/components/blocks/navigation/SeeMoreLink"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH, StackV } from "@/components/frames/Stack"
import { resolveIdentity, type CallerIdentity } from "@/components/frames/_identity"

/** Props for the {@link LabeledCard} block. */
export interface LabeledCardProps {
    /** Section title rendered OUTSIDE (above) the card. */
    label: string
    /**
     * Optional secondary label pinned to the RIGHT of the label row (muted) — a
     * passive tag, NOT an action (e.g. a currency "VND", a count, a unit). Rendered
     * only when neither `action` nor `onSeeMore` claim the right slot.
     */
    labelEnd?: string
    /**
     * When provided, renders a shared {@link SeeMoreLink} on the right of the
     * label (semibold accent text + a caret that slides right on hover).
     */
    onSeeMore?: () => void
    /** Text for the see-more link. Defaults to "See more" — pass `t(...)` to localise. */
    seeMoreLabel?: string
    /**
     * Arbitrary right-aligned slot in the label row (e.g. an owner "Add / manage"
     * button) — a buildable slot. Takes precedence over `onSeeMore` when both are passed.
     */
    action?: ComponentType
    /** Card body content. */
    children: ReactNode
    /**
     * Optional secondary slot rendered OUTSIDE (below) the card, `gap-2` from
     * it — a caption/prompt/status that belongs to the section but not inside the
     * surface (e.g. a "complete all 3 to claim" prompt, a claim button) — a
     * buildable slot. Kept below the card so it never becomes surface-in-surface.
     * Caller owns its alignment.
     */
    description?: ComponentType
    /**
     * When true, drop the inner `<Card>` frame and render children directly under
     * the label — for sections whose content is ITSELF card(s) (e.g. a grid of
     * resume / course cards), so they never nest card-in-card.
     */
    frameless?: boolean
    /**
     * When true, the framed card drops padding on BOTH the root `.card` (HeroUI
     * bakes `p-4` there) and `CardContent`, so an EDGE-OWNING child (Accordion /
     * Table / full-bleed divider list) sits flush to the card edges — avoids the
     * inset-divider look. Ignored when `frameless`.
     */
    flushContent?: boolean
    /**
     * When true, the section + framed card stretch to fill their container's height
     * (`h-full` + the card grows via `flex-1`). Use for side-by-side cards in a grid
     * row so uneven content (e.g. a 1-line vs 2-line empty state) still renders at
     * equal height. Ignored when `frameless`.
     */
    fillHeight?: boolean
    /**
     * Renders the label as a SUBTLE eyebrow (`text-xs text-muted`) with a tighter
     * `gap-2` to the content, instead of the default section `Label` + `gap-3`. For
     * a minor/secondary header over a block — e.g. a time-bucket "Today" over a run
     * list — where a full section label reads too heavy (teacher 2026-07-13: "if a card
     * needs a secondary label, use label-gap-2"). `labelEnd` shrinks to `text-xs` to match.
     */
    subtleLabel?: boolean
    /**
     * When true, adds `border border-default` on top of the default
     * `shadow-surface` — for shells that need to stand out as a distinct
     * bounded surface even against a `bg-surface` sibling (e.g. FlipCard's
     * question/answer pair). Default false preserves the elevation-only
     * convention for every other LabeledCard consumer.
     */
    bordered?: boolean
    /**
     * Caller identity to wear on this block's root `<section>` instead of its own — pass this
     * when a `block`/`layout`/`overlay`/`page` component (BLOCK-2: never draws a shape of its
     * own) is using this card AS its root element, instead of wrapping it in a raw `<div
     * data-tier=… data-component=…>`. See `_identity.ts`. Omitted → this section keeps emitting
     * no `data-tier`/`data-component` at all, unchanged (this block has no identity of its own).
     */
    identity?: CallerIdentity
}

/**
 * The StarCi section card (UI 2.0): the title is a `Label` that sits OUTSIDE,
 * above the card, while the `Card` holds only content — `<Label/>` then
 * `<Card>…</Card>`. Optionally shows a right-aligned "see more →" link (the caret
 * slides right on hover). Replaces the legacy in-card header (SectionCard); owns
 * the whole look so features just pass label / see-more / children.
 *
 * @param props - {@link LabeledCardProps}
 * @see Story: .storybook/stories/blocks/cards/LabeledCard/LabeledCard.stories
 */
export const LabeledCard = ({
    label,
    labelEnd,
    onSeeMore,
    seeMoreLabel = "See more",
    action: Action,
    children,
    description: Description,
    frameless = false,
    flushContent = false,
    fillHeight = false,
    subtleLabel = false,
    bordered = false,
    identity,
}: LabeledCardProps) => {
    // Right slot of the label row — action wins over onSeeMore, which wins over labelEnd.
    const endSlot = Action ? <Action /> : (onSeeMore ? (
        <SeeMoreLink onPress={onSeeMore} size={subtleLabel ? "xs" : "sm"}>
            {seeMoreLabel}
        </SeeMoreLink>
    ) : labelEnd != null ? (
        <Typography size={subtleLabel ? "xs" : "sm"} color="muted" classNames={["shrink-0"]} text={labelEnd} />
    ) : null)
    // Non-subtle label goes through the atom instead of HeroUI `Label`: `Label` renders
    // exactly 14px/500/lh-20 = `size="sm" weight="medium"` (documented equivalence, see
    // `composites/cards/SurfaceCard/surface-card-header.tsx`), so the shape is unchanged.
    const labelSlot = subtleLabel ? (
        <Typography size="xs" color="muted" truncate classNames={["min-w-0"]} text={label} />
    ) : (
        <Typography size="sm" weight="medium" classNames={["min-w-0"]} text={label} />
    )
    // card body: frameless = content is itself card(s) → no inner Card (avoid nesting)
    const body = frameless ? (
        children
    ) : (
        <Card
            className={cn(
                bordered && "border border-default",
                fillHeight && "flex-1",
                // root `.card` bakes p-4 — zero it here or flush children stay inset
                flushContent && "gap-0 overflow-hidden p-0",
            )}
        >
            <CardContent className={cn(flushContent && "p-0", fillHeight && "h-full")}>
                {children}
            </CardContent>
        </Card>
    )
    return (
        <section
            {...resolveIdentity(identity, { tier: "composite", name: "LabeledCard" })}
            data-principle={subtleLabel ? "sublabel-field" : "label-field"}
            className={cn("flex flex-col", subtleLabel ? "gap-2" : "gap-3", fillHeight && "h-full")}
        >
            <StackH gap={4} principle="content-row" justify="between" items={[() => labelSlot, () => endSlot]}
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            />
            {/* description sits OUTSIDE (below) the card, gap-2 — never surface-in-surface */}
            {Description ? (
                <StackV gap={3} items={[() => body, () => <Description />]} />
            ) : body}
        </section>
    )
}

"use client"

import React, { type ComponentType } from "react"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"
import { Image } from "@/components/atoms/media/Image"
import { Typography } from "@/components/atoms/text/Typography"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { Box } from "@/components/frames/Box"
import { Cluster } from "@/components/frames/Cluster"
import { StackV } from "@/components/frames/Stack"

/** Placeholder cover when {@link MediaCardProps.cover} is omitted — 16:9. */
const FALLBACK_COVER_SRC = "https://placehold.co/640x360"

/** Props for {@link MediaCard}. */
export interface MediaCardProps {
    /**
     * Optional media node rendered flush at the very top of the card, edge-to-
     * edge under the card radius (e.g. an `<img>`). When omitted, a 16:9
     * placeholder image fills the same full-bleed slot.
     */
    cover?: ComponentType
    /**
     * Primary heading of the card (course / lesson / challenge / blog title).
     * Rendered via {@link Typography} weight="medium" (body size).
     */
    title: string
    /**
     * Optional metadata row shown directly under the title — typically a row of
     * chips or muted text (category, difficulty, duration, author).
     */
    meta?: ComponentType
    /**
     * Optional short description / excerpt. Rendered muted, clamped to two
     * lines so grid rows stay uniform.
     */
    description?: string
    /**
     * Optional footer pinned at the bottom of the body — typically a CTA button,
     * price, or progress indicator.
     */
    footer?: ComponentType
    /**
     * Optional press handler. When provided the whole card becomes pressable and
     * keyboard-accessible. Prefer {@link href} for pure navigation.
     */
    onPress?: () => void
    /**
     * Optional destination URL. When provided the card renders as an anchor so
     * the whole card is a single accessible link.
     */
    href?: string
    /**
     * Where this card sits inside its parent. Appearance is not passable — it is
     * already a prop.
     */
    classNames?: Array<AllowedClassName>
}

/**
 * Consolidated, presentational content card — one shape for course / lesson /
 * challenge / blog grids. Composes {@link SurfaceCard} for the card face itself
 * (the `nested` variant gives the flat, border-not-shadow look this card has
 * always had — globals still supply the 3xl radius) so this file owns no card
 * chrome of its own: a flush 16:9 cover slot on top, and a padded stack of
 * title / meta / description / footer underneath. When {@link cover} is
 * omitted a 16:9 placeholder image fills that slot.
 *
 * Pass `href` for navigation or `onPress` for a custom handler — either makes
 * the whole card pressable and keyboard-accessible via `SurfaceCard`'s own
 * press handling (ripple + press-scale for `onPress`, a real anchor for
 * `href`).
 *
 * @param props - {@link MediaCardProps}
 * @see Story: .storybook/stories/blocks/cards/MediaCard/MediaCard.stories
 */
export const MediaCard = ({
    cover: Cover,
    title,
    meta: Meta,
    description,
    footer: Footer,
    onPress,
    href,
    classNames,
}: MediaCardProps) => {
    const coverNode = Cover
        ? <Cover />
        : <Image src={FALLBACK_COVER_SRC} alt="" ratio="video" radius="none" />

    const body = () => (
        <StackV
            gap={1}
            items={[
                () => (
                    <Box className="aspect-video w-full shrink-0 overflow-hidden [&_img]:block [&_img]:size-full [&_img]:object-cover">
                        {coverNode}
                    </Box>
                ),
                () => (
                    <StackV
                        gap={1}
                        padding={5}
                        principle="card-padding"
                        explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome."
                        body={() => (
                            <StackV
                                gap={4}
                                principle="card-caption"
                                explain="Holds caption text under card media so the caption stays attached to the image above it."
                                items={[
                                    () => <Typography size="base" weight="medium" text={title} />,
                                    ...(Meta ? [() => <Cluster gap={3} principle="chip-row"
                                        explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                        items={[() => <Meta />]} />] : []),
                                    ...(description ? [() => <Typography size="sm" color="muted" lineClamp={2} text={description} />] : []),
                                    ...(Footer ? [() => <Footer />] : []),
                                ]}
                            />
                        )}
                    />
                ),
            ]}
        />
    )

    return (
        <SurfaceCard identity={{ tier: "block", component: "MediaCard" }}
            variant="nested"
            padding={1}
            onPress={onPress}
            href={href}
            body={body}
            classNames={classNames}
        />
    )
}

"use client"

import React, { type ComponentType } from "react"
import {
    cn,
} from "@heroui/react"
import type {
    WithClassNames,
} from "@/modules/types/base/class-name"
import { FillAvailable } from "@/components/frames/FillAvailable"
import { StackH } from "@/components/frames/Stack"
import { resolveIdentity, type CallerIdentity } from "@/components/frames/_identity"

/**
 * Props for the {@link PressableCard} block.
 *
 * TIER NOTE: this folder sits under `blocks/cards`, but the component itself
 * owns no domain entity — every prop here is a shape (`children`, `onPress`,
 * `href`, `actions`) never a field of something fetched. That is BLOCK-7's
 * detection signal: it is really a **composite** mis-filed in a block folder.
 * Left in place (moving the folder breaks every importer below), but treated
 * as a composite for this pass — one file, `cn()` allowed (COMPOSITE-5), and
 * `className` kept as a raw string rather than `classNames: Array<AllowedClassName>`
 * because three real callers outside this folder (`GroupPressableCard`,
 * `SummaryCard`, `ConsultantCard`) already forward arbitrary skin classes
 * (radius/border/hover overrides) through it — narrowing the type here would
 * break them without touching a single one of their files.
 *
 * `composites/cards/SurfaceCard` (`SurfaceCard`, exported off `Base`) is the
 * emerging canonical member for this exact job — same whole-card press target,
 * same stretched-link `actions` pattern, plus ripple/selection/verdict-band —
 * and its own header explicitly notes it folds in "was `PressableCard`". It is
 * NOT swapped in here: its hover/ripple treatment differs from this file's
 * (tint-on-hover, no ripple), so delegating to it would change the rendered
 * look for the three live callers above, not just the code shape. Consolidating
 * onto `SurfaceCard` is a separate migration (each caller needs the `children`
 * → `body` slot conversion too), left as debt rather than folded in silently.
 */
export interface PressableCardProps extends WithClassNames<undefined> {
    /** Card body — composed freely by the caller (icon tiles, text, chips…). */
    children: React.ReactNode
    /**
     * Press handler for an action card (select / toggle). Ignored when
     * {@link PressableCardProps.href} is set. One of `onPress` / `href` should
     * be provided for the card to be interactive.
     */
    onPress?: () => void
    /** Navigation target — renders the card as an anchor when provided. */
    href?: string
    /** Disables interaction and dims the card (action cards only). */
    isDisabled?: boolean
    /**
     * Secondary interactive controls (buttons / menus) that live INSIDE the card
     * but act INDEPENDENTLY of the whole-card press — e.g. a "Continue" button +
     * an overflow menu on a course-progress card.
     *
     * Providing this switches the card to the accessible **stretched-link**
     * pattern (Inclusive Components / Adrian Roselli): the whole-card target
     * becomes a TRANSPARENT overlay that covers the card, and these actions sit
     * ABOVE it (later in source order + `z-10`) so each stays separately
     * clickable. This is the correct alternative to illegally nesting a
     * `<button>` inside the card's own `<button>`/`<a>` — which is invalid HTML,
     * breaks the keyboard/AT focus order, AND is what made the card grow tall
     * (a block button laying its interactive children out on their own lines).
     *
     * REQUIRES {@link PressableCardProps.label} — the overlay target no longer
     * wraps the children text, so it needs its own accessible name.
     */
    actions?: ComponentType
    /**
     * Accessible name for the whole-card press target. REQUIRED when
     * {@link PressableCardProps.actions} is set (the stretched overlay covers the
     * card but has no visible text of its own, so it must carry an `aria-label`).
     * Optional otherwise — without `actions` the children ARE the card's
     * accessible name, so pass this only when they carry no readable text (an
     * icon-only tile). Keep it descriptive of the destination/action ("Open the
     * Fullstack Mastery track"), never generic ("click here").
     */
    label?: string
    /**
     * Caller identity to wear on this card's root instead of its own — pass this
     * when a sentence-tier component roots on this card (see `frames/_identity.ts`).
     */
    identity?: CallerIdentity
}

/**
 * A whole-card press target with the default surface card look (surface fill,
 * concentric `rounded-3xl`, fixed `px-4 py-3` padding, `shadow-surface`
 * elevation AT REST — per `card.md` §0, a top-level bounded card, so it must
 * read as a card even before hover) plus a hover affordance and keyboard
 * focus ring. Exists because HeroUI v3 `Card` is a
 * non-interactive `<div>` — this component owns the card styling on a real
 * `<button>` / `<a>` so features can compose a clickable card without
 * hand-rolling styles (per the no-style-in-features rule). Use for navigation
 * tiles, selectable option cards, and bookmark rows.
 *
 * When the card also needs its OWN buttons (a "Continue" CTA, an overflow menu),
 * pass them via {@link PressableCardProps.actions} + {@link PressableCardProps.label}:
 * the card renders as the accessible stretched-link pattern (a transparent
 * whole-card overlay UNDER the actions) instead of nesting interactive elements
 * — see the `actions` prop docs.
 *
 * @param props - {@link PressableCardProps}
 * @see Story: .storybook/stories/blocks/cards/PressableCard/PressableCard.stories
 */
export const PressableCard = ({
    children,
    onPress,
    href,
    isDisabled = false,
    actions: Actions,
    label,
    className,
    identity,
}: PressableCardProps) => {
    // Shared card surface + disabled dim, identical across both render paths so
    // a card reads the same with or without actions. `shadow-surface` is a
    // top-level bounded card (card.md §0 elevation convention) — it must read as
    // one at rest, not only once the pointer arrives (teacher: "render it as a card").
    // One hover treatment only (tint) — no lift variant, no press-scale.
    const surface = cn(
        "rounded-3xl bg-surface px-4 py-3 text-left shadow-surface transition-colors hover:bg-surface-secondary",
        isDisabled && "cursor-not-allowed opacity-60",
        className,
    )
    const identityAttrs = resolveIdentity(identity, { tier: "composite", name: "PressableCard" })

    // ── Simple whole-card target (no secondary actions) — the common case;
    // the whole card is ONE <button>/<a> and its children are its label. ──────
    if (!Actions) {
        const base = cn(
            "block w-full outline-none focus-visible:ring-2 focus-visible:ring-accent",
            surface,
        )
        if (href && !isDisabled) {
            return (
                <a href={href} aria-label={label} className={base} {...identityAttrs}>
                    {children}
                </a>
            )
        }
        return (
            <button
                type="button"
                onClick={onPress}
                disabled={isDisabled}
                aria-label={label}
                className={cn(base, !isDisabled && "cursor-pointer")}
                {...identityAttrs}
            >
                {children}
            </button>
        )
    }

    // ── Card WITH its own buttons — stretched-link pattern. The card is a plain
    // relative <div>; a transparent overlay <a>/<button> covers it (whole-card
    // press), and the actions sit ABOVE the overlay so they stay clickable. No
    // interactive element is ever nested inside another. Row built with `StackH`
    // (frame tier) instead of a hand-rolled `flex items-center gap-3` wrapper —
    // same shape as `composites/cards/SurfaceCard`'s own actions branch. ───────
    const overlay = cn(
        // covers the whole card; the focus ring reads as a card-level ring since
        // the overlay's border-box IS the card's bounds
        "absolute inset-0 rounded-3xl outline-none focus-visible:ring-2 focus-visible:ring-accent",
        isDisabled ? "cursor-not-allowed" : "cursor-pointer",
    )
    return (
        <div className={cn("relative w-full", surface)} {...identityAttrs}>
            <StackH
                principle="content-row"
                explain="Card body and trailing actions share one content row — not flex-action, because the body is content rather than a control peer."
                items={[
                    () => (
                        <FillAvailable
                            at="base"
                            explain="Card body takes remaining row width beside the actions cluster so long titles truncate instead of shoving the actions."
                            body={() => <>{children}</>}
                        />
                    ),
                    () => (
                        <div className="relative z-10">
                            <StackH
                                principle="flex-action"
                                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                items={[() => <Actions />]}
                            />
                        </div>
                    ),
                ]}
            />
            {href && !isDisabled ? (
                <a href={href} aria-label={label} className={overlay} />
            ) : (
                <button
                    type="button"
                    onClick={onPress}
                    disabled={isDisabled}
                    aria-label={label}
                    className={overlay}
                />
            )}
        </div>
    )
}

"use client"

import React, { type ComponentType } from "react"
import { cn } from "@heroui/react"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"
import { Typography } from "@/components/atoms/text/Typography"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"
import { type AllowedGap, type LayoutAlign } from "@/components/frames/_spacing"
import { type CallerIdentity } from "@/components/frames/_identity"
import { type VerdictBand, verdictBandClassName } from "../verdict-band"

/** Props for {@link SectionCard}. */
export interface SectionCardProps {
    /** Card body. */
    children: React.ReactNode
    /** Optional section title rendered in the header row. The atom wraps it in `Typography` itself. */
    title?: string
    /** Optional leading icon shown before the title — a buildable slot, not a built element. */
    icon?: ComponentType
    /** Optional action slot pinned to the right of the header (button/link) — a buildable slot. */
    action?: ComponentType
    /** Accent variant: tinted border + background (highlight / "yours"). */
    accent?: boolean
    /**
     * Verdict variant: a thick LEFT band (`border-l-4`) on top of the card's own
     * border — the asymmetric-border shape for "a card carrying a signal FROM DATA"
     * (`card.md` §3i). See {@link VerdictBand}. Left band ONLY reads as a DATA
     * signal — never ad-hoc "active region" decoration (`card.md` §3g).
     */
    withVerdict?: VerdictBand
    /**
     * Where the card sits inside its parent. Appearance is not passable — it is
     * already a prop.
     *
     * missingVocabulary (no-classname-at-sentence-tier, BLOCK-4): `QuizCard`, `MetricCard`, and
     * `PitchCard` all genuinely forward a value through here today. Dropping this prop would
     * require editing those call sites too, and they sit outside this folder — left in place and
     * flagged as known debt rather than silently removed.
     */
    classNames?: Array<AllowedClassName>
    /**
     * Seam between the header row (when present) and `children`, and between items inside
     * `children` that opt into the same track — the content wrapper's own gap step on the
     * house scale (`AllowedGap`, `_spacing.ts`). Defaults to `4` (`gap-3`), the shape every
     * caller got before this prop existed. `PricingCard` needs a roomier `6` (`gap-6`) between
     * its name/price/features/cta rows.
     */
    contentGap?: AllowedGap
    /**
     * `true` → the content wrapper stretches to fill the card's height (`h-full`) instead of
     * hugging its own content. For cards placed side-by-side in a grid (`PricingCard`,
     * `PitchCard`, the `ContinueLearning` skeleton shell) so the CTA/footer row still pins to
     * the bottom even when a sibling card's copy runs longer. Defaults to `false`.
     */
    fillHeight?: boolean
    /**
     * Cross-axis alignment of the content wrapper's track. Defaults to `"stretch"` (every child
     * takes the full width), matching the shape every caller got before this prop existed. The
     * `ContinueLearning` empty state needs `"start"` so its CTA button hugs its own width
     * instead of stretching full-bleed.
     */
    contentAlign?: LayoutAlign
    /**
     * Caller identity to wear on this card's root element instead of its own — pass this when a
     * `block`/`layout`/`overlay`/`page` component (BLOCK-2: never draws a shape of its own) is
     * using this card AS its root element, instead of wrapping it in a raw `<div data-tier=…
     * data-component=…>`. See `_identity.ts`. Omitted → this card keeps emitting its own
     * `data-tier="block" data-component="SectionCard"`, unchanged.
     */
    identity?: CallerIdentity
}

/**
 * The canonical bordered "framed" card used across profile + dashboard. A thin
 * skin (`rounded-3xl bg-surface shadow-surface`, the same face `.card` in
 * `globals.css` gives HeroUI's own `Card`) that adds an optional header row
 * (icon + title on the left, action on the right) so every titled section looks
 * identical. Use `accent` for the viewer's own / highlighted cards. The header
 * row and content wrapper compose the frame tier's `StackH`/`StackV`/`Box`.
 *
 * @param props - {@link SectionCardProps}
 * @see Story: .storybook/stories/blocks/cards/SectionCard/SectionCard.stories
 */
export const SectionCard = ({
    children,
    title,
    icon: Icon,
    action: Action,
    accent = false,
    withVerdict,
    classNames,
    contentGap = 4,
    fillHeight = false,
    contentAlign = "stretch",
    identity,
}: SectionCardProps) => {
    const hasHeader = Boolean(title || Action || Icon)
    // BLOCK-5 DEBT, left VISIBLE on purpose: this block decides its own card face —
    // radius · surface · shadow · padding · accent border · verdict band — which is a
    // lower tier's job; read it as "a composite is missing". An earlier pass hid this by
    // hand-joining the array so the `cn` rule would not fire, which changed nothing about
    // the design. The real fix is to compose `composites/cards/SurfaceCard`'s face, a
    // migration of its own.
    const rootClassName = cn(
        "rounded-3xl bg-surface shadow-surface p-4",
        accent ? "border-accent" : null,
        verdictBandClassName(withVerdict),
        ...(classNames ?? []),
    )
    return (
        <Box
            identity={identity ?? { tier: "block", component: "SectionCard" }}
            className={rootClassName}
        >
            <StackV
                gap={contentGap}
                principle={contentGap === 6 ? "block-boundary" : contentGap === 5 ? "group-boundary" : "card-caption"}
                explain={
                    contentGap === 6
                        ? "Separates the section header from the card body as major regions so a roomier PricingCard rhythm does not collapse into one band."
                        : contentGap === 5
                            ? "Spaces the header band and body as distinct section groups so they stay as separate bands rather than a flat peer list."
                            : "Stacks the optional header above the body so the title row stays on its own track above the card content."
                }
                align={contentAlign}
                classNames={fillHeight ? ["h-full"] : undefined}
                body={() => (
                    <>
                        {hasHeader ? (
                            <Box className="border-b border-separator pb-3">
                                <StackH
                                    gap={3}
                                    principle="flex-action"
                                    explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                    justify="between"
                                    items={[
                                        () => (
                                            <StackH
                                                gap={2}
                                                principle="icon-text"
                                                explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
                                                classNames={["min-w-0"]}
                                                items={[
                                                    ...(Icon ? [() => <Icon />] : []),
                                                    ...(title ? [() => (
                                                        <Typography size="base" weight="semibold" truncate text={title} />
                                                    )] : []),
                                                ]}
                                            />
                                        ),
                                        ...(Action ? [() => <span className="shrink-0"><Action /></span>] : []),
                                    ]}
                                />
                            </Box>
                        ) : null}
                        {children}
                    </>
                )}
            />
        </Box>
    )
}

"use client"

import React, { type ComponentType } from "react"
import {
    cn,
} from "@heroui/react"
import {
    CaretRightIcon as ChevronRightIcon,
} from "@phosphor-icons/react"
import {
    PressableCard,
} from "../PressableCard"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * Props for {@link SummaryCard}. Every field is an already-resolved shape
 * (icon, value, label, hint) — this card takes no domain entity, which is
 * why it lives at the composite tier despite sitting in `blocks/cards`
 * (BLOCK-7): the folder names a tier the component never earned.
 */
export interface SummaryCardProps {
    /** Leading icon for the metric — a buildable slot, not a built element. */
    icon: ComponentType
    /** Headline value (e.g. a count). */
    value: string
    /** Short label under the value. */
    label: string
    /** Optional one-line hint under the label. */
    hint?: string
    /** Called when the card is activated (e.g. jump to a tab). */
    onPress?: () => void
}

/** Source-level tier metadata — see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "SummaryCard" } as const

/**
 * A compact pressable metric card (icon + big value + label, with a trailing
 * chevron) used in the profile overview to surface a deeper tab. Built on
 * {@link PressableCard} for the spring/hover feel; layers its own outlined
 * "default" card look on top of that surface. Presentational — the caller
 * wires `onPress`.
 *
 * `PressableCard` has not itself been ported to the closed `classNames`
 * vocabulary, so its `className` string prop is composed here with `cn`
 * (COMPOSITE-5 — appearance is this tier's job); `SummaryCard` renders no
 * `<div>` of its own beyond what `PressableCard`'s button/anchor already
 * emits, so it carries no separate `data-tier`/`data-component` badge —
 * `PressableCard` offers no slot for one, and wrapping it in an extra `<div>`
 * just to hang the badge on would be the identity wrapper the composite tier
 * says not to add.
 *
 * @param props - {@link SummaryCardProps}
 */
export const SummaryCard = ({
    icon: Icon,
    value,
    label,
    hint,
    onPress,
}: SummaryCardProps) => {
    const rows = [
        () => (
            <StackH
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                justify="between"
                items={[
                    () => <span className="text-accent-soft-foreground"><Icon /></span>,
                    () => <ChevronRightIcon className="size-5 text-muted" />,
                ]}
            />
        ),
        () => (
            <StackV
                gap={1}
                items={[
                    () => <Typography size="h4" weight="bold" text={value} />,
                    () => <Typography size="sm" weight="medium" text={label} />,
                    ...(hint ? [() => <Typography size="xs" color="muted" text={hint} />] : []),
                ]}
            />
        ),
    ]

    return (
        <PressableCard
            identity={{ tier: "block", component: "SummaryCard" }}
            onPress={onPress}
            className={cn(
                "card card--default h-full rounded-xl border border-divider/60 p-4 transition-colors",
                "hover:border-accent/40 hover:bg-accent/5",
            )}
        >
            <StackV gap={4} items={rows} />
        </PressableCard>
    )
}

"use client"

import React, { type ComponentType } from "react"
import Link from "next/link"
import { cn } from "@heroui/react"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { Typography } from "@/components/atoms/text/Typography"
import { Box } from "@/components/frames/Box"
import { StackH } from "@/components/frames/Stack"
import { resolveIdentity, type CallerIdentity } from "@/components/frames/_identity"
import { type VerdictBand, verdictBandClassName } from "../verdict-band"

/**
 * The interactive anchor for a clickable surface-list row. An INTERNAL app route
 * (href starting with `/`) renders a Next `<Link>` → client-side `router.push`:
 * SPA navigation that keeps history (Back works) with NO full-page reload — and
 * NEVER `router.replace` (a link click must not erase the entry it came from).
 * Protocol / external hrefs (`mailto:`, `tel:`, `http(s)://`, `#`) fall back to a
 * native `<a>` (Next `<Link>` is for in-app routes only). Ref feedback 2026-07-17
 * "clicking a row = router.push, not router.replace, even if it's a link".
 *
 * Shared by {@link SurfaceListCardRow} and {@link SurfaceListCardItem} — each hands
 * in its own `dataComponent` so the rendered anchor still carries that caller's own
 * identity rather than a generic one.
 */
/** Props for {@link RowAnchor}. */
interface RowAnchorProps {
    href: string
    onClick?: () => void
    className?: string
    dataComponent: string
    children: React.ReactNode
}

const RowAnchor = ({
    href,
    onClick,
    className,
    dataComponent,
    children,
}: RowAnchorProps) => {
    if (href.startsWith("/")) {
        return (
            <Link href={href} onClick={onClick} className={className} data-tier="composite" data-component={dataComponent}>
                {children}
            </Link>
        )
    }
    return (
        <a href={href} onClick={onClick} className={className} data-tier="composite" data-component={dataComponent}>
            {children}
        </a>
    )
}

/** Props for {@link SurfaceListCard}. */
export interface SurfaceListCardProps extends WithClassNames<undefined> {
    /** The rows ({@link SurfaceListCardRow}) of the joined list. */
    children: React.ReactNode
    /**
     * Renders `border border-default` instead of `shadow-surface` — for when
     * this list sits NESTED inside another surface (a modal/drawer body),
     * where `--surface-shadow` can render invisible against the parent surface
     * (dark mode) — nested cards need a border to delineate (`components/card.md`
     * §"surface-in-surface / nested" — KEEP border, do NOT convert to shadow).
     * Defaults to `false` (existing top-level usages keep the shadow look).
     */
    bordered?: boolean
    /**
     * Set when a sentence-tier component roots on this card: it then emits THAT
     * component's identity instead of its own, so the caller never wraps itself in an
     * identity div (see `frames/_identity.ts`).
     */
    identity?: CallerIdentity
}

/**
 * Bounded SURFACE list card: one `bg-surface` container with a border + large
 * radius, holding {@link SurfaceListCardRow}s edge-to-edge (the `Accordion
 * variant="surface"` skin — NOT a real accordion). Each row owns the FULL-BLEED
 * separator + hover; the last row hides its separator automatically (reviewer,
 * 2026-07-14: "surface-in-surface gets a full-width separator too") — full-bleed
 * everywhere, no inset-vs-nested split).
 *
 * Use for a list of clickable items that should read as ONE card (foundation
 * categories/resources, payment methods…), not N separate cards. Style lives
 * here (block); features only feed rows. Ref `elements/card.md` §3c.
 *
 * REUSE NOTE: `composites/cards/SurfaceCard`'s `.List` member is the newer,
 * DATA-driven (`items`) sibling of this exact shape (its own header even says
 * "was `SurfaceListCard` + its two rows"). This folder keeps the original
 * children-based API on purpose — ~90 call sites across the app compose it with
 * JSX rows today, and moving them to `items` is a call-site migration outside
 * this pass's scope, not a rewrite this file can make alone.
 *
 * @param props - {@link SurfaceListCardProps}
 * @see Story: .storybook/stories/blocks/cards/SurfaceListCard/SurfaceListCard.stories
 */
export const SurfaceListCard = ({ children, bordered = false, className, identity }: SurfaceListCardProps) => (
    <div
        className={cn(
            "overflow-hidden rounded-3xl bg-surface",
            bordered ? "border border-default" : "shadow-surface",
            className,
        )}
        {...resolveIdentity(identity, { tier: "composite", name: "SurfaceListCard" })}
    >
        {children}
    </div>
)

/** Props for {@link SurfaceListCardRow}. */
export interface SurfaceListCardRowProps extends WithClassNames<undefined> {
    /** Optional leading slot (thumbnail/icon), kept at intrinsic size — a buildable slot. */
    leading?: ComponentType
    /** Primary line — medium foreground, single-line truncate. */
    title: string
    /** Optional secondary line — muted, smaller, single-line truncate. */
    subtitle?: string
    /** Optional right-aligned metadata slot (chips/counts) before the trailing slot — a buildable slot. */
    meta?: ComponentType
    /** Optional far-right slot (caret / inline action) — a buildable slot. */
    trailing?: ComponentType
    /** Press handler → renders an interactive `<button>` row. */
    onPress?: () => void
    /** Link target → renders an `<a>` row that navigates on click. */
    href?: string
    /** Tints the row as the active selection. */
    selected?: boolean
    /** Disables the row (dimmed, non-interactive). */
    isDisabled?: boolean
    /**
     * Hover treatment. `"fill"` (default) tints the whole row (`bg-default`) — for
     * card-like rows / bounded objects. `"underline"` is link-style: the TITLE
     * underlines on hover with NO row fill — for a list whose title IS the link
     * (e.g. a most-read list). Ref `interactive-needs-hover` (row-as-link → underline
     * the label, don't colour the whole block).
     */
    hover?: "fill" | "underline"
    /**
     * Verdict band: an inset colored PILL on the left marking this row with a signal
     * that comes from DATA (`card.md` §3i) — e.g. a keyword's popularity tier. See
     * {@link VerdictBand} (same shape as `SurfaceListCardItem.withVerdict`).
     */
    withVerdict?: VerdictBand
}

/**
 * One row of a {@link SurfaceListCard}, laying out leading · title+subtitle ·
 * meta+trailing (the same slot shape as `ListRow`, surface-card skin) with a
 * full-bleed inset separator auto-hidden on the last row. STATIC by default (a
 * plain `<div>`, NO hover/focus/cursor); pass `onPress`/`href` to make the whole
 * row a tappable `<button>`/`<a>` with `hover:bg-default` + focus ring. A static
 * row never fakes interactivity with a hover tint (`hover-style-matches-clickable-nature`).
 *
 * The row's OWN frame (separator, hover fill, focus ring, verdict band) is a shape
 * decision this composite owns directly (`cn`) — no frame carries an `after:`
 * pseudo-element separator or a data-driven inset shadow. The row's INTERIOR —
 * leading · title/subtitle · meta/trailing — is assembled from `Typography` inside
 * `Box`/`StackH` frames wherever a frame can express it exactly (title/subtitle
 * keeps a literal `gap-0` column, one step tighter than `Stack`'s narrowest `gap={1}`
 * step, so it stays a plain flex column).
 *
 * @param props - {@link SurfaceListCardRowProps}
 */
export const SurfaceListCardRow = ({
    leading: Leading,
    title,
    subtitle,
    meta: Meta,
    trailing: Trailing,
    onPress,
    href,
    selected = false,
    isDisabled = false,
    hover = "fill",
    withVerdict,
    className,
}: SurfaceListCardRowProps) => {
    // a row is only interactive when it actually does something; a STATIC row must
    // not fake interactivity with a hover tint / focus ring / button semantics
    // (`hover-style-matches-clickable-nature` — mirrors SurfaceListCardItem).
    const interactive = Boolean(onPress || href)
    const underlineHover = hover === "underline"
    const rowClassName = cn(
        "relative flex w-full items-center gap-3 p-3 text-left",
        // full-bleed separator, hidden on the last row of the card
        "after:absolute after:bottom-0 after:left-0 after:h-px after:w-full after:bg-surface-foreground/6 after:content-['']",
        "last:after:hidden",
        // hover + focus + cursor ONLY when interactive. link-style rows form a hover
        // `group` (the title underlines) with no fill; card-style rows tint the row
        interactive && "outline-none transition-colors focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-accent",
        interactive && (underlineHover ? "group" : "hover:bg-default"),
        interactive && !isDisabled && "cursor-pointer",
        "disabled:cursor-not-allowed disabled:opacity-60",
        selected && "bg-accent-soft",
        verdictBandClassName(withVerdict),
        // first/last row own the container's corner radius so the verdict box-shadow HOOKS the corner
        withVerdict?.enable && "first:rounded-t-3xl last:rounded-b-3xl",
        className,
    )

    const content = (
        <>
            {Leading ? <div className="shrink-0"><Leading /></div> : null}
            {/* Deliberately NOT `StackV`: the closest step on the frame's gap scale is
                `gap={1}` (0.25rem) and this column needs a true `gap-0` — the two text
                lines are meant to sit with no seam between them (missing vocabulary: the
                frame has no zero step, see `_spacing.ts` `AllowedGap`). */}
            <div className="flex min-w-0 flex-col gap-0">
                <Typography size="sm" truncate underlineOnGroupHover={underlineHover} text={title} />
                {subtitle ? <Typography size="xs" color="muted" truncate text={subtitle} /> : null}
            </div>
            {Meta || Trailing ? (
                <Box principle="push-end" className="ml-auto shrink-0"
                    explain="Pushes this peer to the trailing edge so trailing meta stays right-aligned in the row.">
                    <StackH gap={2} items={[() => (Meta ? <Meta /> : null), () => (Trailing ? <Trailing /> : null)]} />
                </Box>
            ) : null}
        </>
    )

    if (href) {
        return (
            <RowAnchor href={href} onClick={onPress} className={rowClassName} dataComponent="SurfaceListCardRow">
                {content}
            </RowAnchor>
        )
    }
    if (onPress) {
        return (
            <button
                type="button"
                onClick={onPress}
                disabled={isDisabled}
                className={rowClassName}
                data-tier="composite"
                data-component="SurfaceListCardRow"
            >
                {content}
            </button>
        )
    }
    // static row (no onPress/href) — a plain div: no button semantics, no hover
    return (
        <div className={rowClassName} data-tier="composite" data-component="SurfaceListCardRow">
            {content}
        </div>
    )
}

/** Props for {@link SurfaceListCardItem}. */
export interface SurfaceListCardItemProps extends WithClassNames<undefined> {
    /** Arbitrary row content (the block owns padding + the inset separator). */
    children: React.ReactNode
    /** Press handler → renders an interactive `<button>` row (hover + focus ring). */
    onPress?: () => void
    /** Link target → renders an `<a>` row that navigates on click. */
    href?: string
    /** Disables the interactive row (dimmed, non-interactive). */
    isDisabled?: boolean
    /**
     * Hover treatment for an interactive row. `"fill"` (default) tints the whole
     * row (`bg-default`) — the accordion-skin hover, for SELECT/expand rows that
     * keep you on the surface (e.g. payment methods). `"underline"` makes the row a
     * hover `group` with NO fill — for a NAV row whose title is a link (navigates
     * away); the feature adds `group-hover:underline` to its title. Ref
     * `hover-style-matches-clickable-nature` (go-there → underline, stay-here → fill).
     */
    hover?: "fill" | "underline"
    /**
     * Verdict variant: a LEFT band (`border-l-4`) marking this row with a signal that
     * comes from DATA (`card.md` §3i) — e.g. the league's promote/demote zone. See
     * {@link VerdictBand} (same shape as `SectionCard.withVerdict`).
     */
    withVerdict?: VerdictBand
    /**
     * Caller identity to wear on this item's root instead of its own — pass this
     * when a sentence-tier component roots on this item (see `frames/_identity.ts`).
     */
    identity?: CallerIdentity
}

/**
 * One free-form row of a {@link SurfaceListCard} — bespoke content (not the fixed
 * leading/title/subtitle slots of {@link SurfaceListCardRow}). The block owns the
 * row padding + inset bottom separator (auto-hidden on the last row); the feature
 * lays out whatever it needs inside (e.g. a changelog entry, or a course row with a
 * progress bar). STATIC by default; pass `onPress`/`href` to make the WHOLE row a
 * tappable `<button>`/`<a>`. `hover="fill"` (default) tints the row (accordion skin);
 * `hover="underline"` is link-style (the row is a `group`, no fill — the feature
 * underlines its own title). Ref `elements/card.md` §3b/§3c.
 *
 * @param props - {@link SurfaceListCardItemProps}
 */
export const SurfaceListCardItem = ({
    children,
    onPress,
    href,
    isDisabled = false,
    hover = "fill",
    withVerdict,
    className,
    identity,
}: SurfaceListCardItemProps) => {
    const interactive = Boolean(onPress || href)
    const itemClassName = cn(
        "relative block w-full p-3 text-left",
        verdictBandClassName(withVerdict),
        // first/last row own the container's corner radius so the verdict box-shadow HOOKS the corner
        withVerdict?.enable && "first:rounded-t-3xl last:rounded-b-3xl",
        // full-bleed separator, hidden on the last row of the card
        "after:absolute after:bottom-0 after:left-0 after:h-px after:w-full after:bg-surface-foreground/6 after:content-['']",
        "last:after:hidden",
        interactive && "outline-none transition-colors focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-accent",
        // link-style rows form a hover `group` (the title underlines) with NO fill;
        // select/expand rows tint the whole row (accordion skin)
        interactive && (hover === "underline" ? "group" : "hover:bg-default"),
        interactive && !isDisabled && "cursor-pointer",
        isDisabled && "cursor-not-allowed opacity-60",
        className,
    )
    const identityAttrs = resolveIdentity(identity, { tier: "composite", name: "SurfaceListCardItem" })

    if (href) {
        return (
            <RowAnchor href={href} onClick={onPress} className={itemClassName} dataComponent="SurfaceListCardItem">
                {children}
            </RowAnchor>
        )
    }
    if (onPress) {
        return (
            <button
                type="button"
                onClick={onPress}
                disabled={isDisabled}
                className={itemClassName}
                {...identityAttrs}
            >
                {children}
            </button>
        )
    }
    return (
        <div className={itemClassName} {...identityAttrs}>
            {children}
        </div>
    )
}

"use client"

import type {
    BaseSyntheticEvent,
} from "react"
import { Button, ProgressBar, Spinner, Typography } from "@heroui/react"
import { useTranslations } from "next-intl"
import { Dropzone } from "@/components/blocks/form/Dropzone"

/** Max CV upload size (10MB), mirrored in the drop hint copy. */
const MAX_CV_BYTES = 10 * 1024 * 1024

/** Props for {@link CvSubmissionFields}. */
export interface CvSubmissionFieldsProps {
    /** Currently selected CV file, or `null`. */
    cv: File | null
    /** Validation error message for the `cv` field, if any. */
    cvError?: string
    /** Whether the wrapped react-hook-form form is currently submitting. */
    isSubmitting: boolean
    /** Sets the `cv` field value on the react-hook-form form. */
    onCvChange: (file: File | null) => void
    /** Fired on form submit — react-hook-form's wrapped `handleSubmit`. */
    onSubmit: (event?: BaseSyntheticEvent) => Promise<void>
    /** Whether the S3 upload step is in progress. */
    isUploading: boolean
    /** Whether the backend processing step is in progress. */
    isProcessing: boolean
    /** Upload progress percentage (0–100). */
    uploadProgress: number
    /** Name of the successfully uploaded file, or `null`. */
    uploadedFileName: string | null
    /** S3 key of the successfully uploaded file, or `null`. */
    uploadedS3Key: string | null
    /** Fired to trigger backend processing of the uploaded CV. */
    onProcess: () => void
}

/**
 * Inner field layout for the CV submission form: canonical {@link Dropzone}
 * (real drag-drop + token styling + inline error), progress bar, and the
 * upload/process buttons. Presentational — renders react-hook-form field state +
 * upload state, no business logic. All copy via the `cv.submission.*` namespace.
 * @param props - {@link CvSubmissionFieldsProps}
 */
export const CvSubmissionFields = ({
    cv,
    cvError,
    isSubmitting,
    onCvChange,
    onSubmit,
    isUploading,
    isProcessing,
    uploadProgress,
    uploadedFileName,
    uploadedS3Key,
    onProcess}: CvSubmissionFieldsProps) => {
    const t = useTranslations("cv.submission")

    return (
        <form onSubmit={onSubmit} className={"flex flex-col gap-3"}>
            <div className="flex flex-col gap-2">
                <Typography type="body-sm" weight="medium">{t("uploadLabel")}</Typography>
                <Dropzone
                    acceptedMimeTypes={["application/pdf"]}
                    maxSizeInBytes={MAX_CV_BYTES}
                    file={cv}
                    hint={t("dropHint")}
                    errorMessage={cvError}
                    onChange={onCvChange}
                />
                {uploadedFileName && uploadedS3Key ? (
                    <Typography type="body-sm" className="text-success-soft-foreground">
                        {t("uploadSuccess")}
                    </Typography>
                ) : null}
            </div>

            {isUploading ? (
                <div className="flex flex-col gap-2">
                    <div className="flex items-center justify-between">
                        <Typography type="body-sm" weight="medium">{t("uploadingCta")}</Typography>
                        <Typography type="body-sm" color="muted">{uploadProgress}%</Typography>
                    </div>
                    <ProgressBar
                        className="w-full"
                        maxValue={100}
                        minValue={0}
                        value={uploadProgress}
                    >
                        <ProgressBar.Track>
                            <ProgressBar.Fill />
                        </ProgressBar.Track>
                    </ProgressBar>
                </div>
            ) : null}

            <Button
                type="submit"
                isDisabled={isUploading || isProcessing || isSubmitting}
                fullWidth
                variant="primary"
            >
                {isUploading ? (
                    <>
                        <Spinner size="sm" />
                        {t("uploadingCta")}
                    </>
                ) : (
                    t("uploadCta")
                )}
            </Button>

            <Button
                type="button"
                isDisabled={
                    !uploadedFileName
                    || !uploadedS3Key
                    || isUploading
                    || isProcessing
                }
                fullWidth
                variant="secondary"
                onPress={onProcess}
            >
                {isProcessing ? (
                    <>
                        <Spinner size="sm" />
                        {t("processingCta")}
                    </>
                ) : (
                    t("processCta")
                )}
            </Button>
        </form>
    )
}

"use client"

import React from "react"
import { Tooltip } from "@heroui/react"
import type { ReactNode } from "react"
import { Chip, type ChipTone, type IconComponent } from "@/components/atoms/chips/Chip"

/** Soft-chip tones usable by an {@link EnumChip} (mirrors house {@link ChipTone}). */
export type EnumChipColor = ChipTone

/** One enum value's chip presentation. */
export interface EnumChipEntry {
    /** Soft chip tone. Omit to use the Chip default. */
    color?: EnumChipColor
    /** Visible label (already localized by the caller). */
    label: ReactNode
    /**
     * Optional leading icon — a component reference (`SiYoutube`), not a rendered
     * element. The house {@link Chip} atom mounts it at chip scale (contract E).
     */
    icon?: IconComponent
    /** Optional tooltip (already localized); wraps the chip in a Tooltip when set. */
    tooltip?: ReactNode
}

/** Props for {@link EnumChip}. */
export interface EnumChipProps<E extends string> {
    /** The current enum value; looked up in {@link map}. */
    value: E
    /**
     * Map from enum value to presentation. Usually declare it `Record<E, EnumChipEntry>`
     * at the call site to get TS completeness; the prop accepts `Partial` so a domain
     * may intentionally leave some values unhandled (they throw at render, matching the
     * old switch-`default`-throw behavior).
     */
    map: Partial<Record<E, EnumChipEntry>>
}

/**
 * Legacy block-tier "enum → soft chip" primitive still used by domain badges that pass
 * brand {@link IconComponent} refs (LessonVideoKindChip, HostPlatformChip). Appearance
 * lives on `entry.color`; no public className door. Prefer the composites `EnumChip`
 * when the leading glyph is a closed check/cross symbol.
 *
 * @param props - {@link EnumChipProps}
 */
export const EnumChip = <E extends string>({ value, map }: EnumChipProps<E>) => {
    const entry = map[value]
    if (!entry) {
        // exhaustive Record makes this unreachable in typed code; guards a bad runtime value
        throw new Error(`EnumChip: no map entry for value "${value}"`)
    }
    const chip = (
        <Chip
            tone={entry.color ?? "default"}
            text={entry.label}
            icon={entry.icon}
        />
    )
    if (entry.tooltip == null) {
        return chip
    }
    return (
        <Tooltip>
            <Tooltip.Trigger>{chip}</Tooltip.Trigger>
            <Tooltip.Content>{entry.tooltip}</Tooltip.Content>
        </Tooltip>
    )
}

