            icon: SparkleIcon,
            label: t("lessonVideoKind.editedStream.label"),
            tooltip: t("lessonVideoKind.editedStream.tooltip"),
        },
        [LessonVideoKind.PremiumRecord]: {
            color: "warning",
            icon: FilmReelIcon,
            label: t("lessonVideoKind.premiumRecord.label"),
            tooltip: t("lessonVideoKind.premiumRecord.tooltip"),
        },
    }
    return <EnumChip value={kind} map={map} />
}

import React from "react"
import type { ReactNode } from "react"
import { Chip } from "@heroui/react"
import type { IconComponent } from "@/components/atoms/chips/Chip"
import { ElementCloseButton } from "@/components/blocks/buttons/ElementCloseButton"

/**
 * Semantic tone of the status chip. Each tone maps to a HeroUI Chip color
 * (the neutral tone maps to the default color).
 */
export type StatusChipTone = "neutral" | "success" | "warning" | "danger" | "accent"

/**
 * Props for the {@link StatusChip} block.
 *
 * Does NOT take `className` (BLOCK-4 — a block hands out no escape hatch; a
 * caller that needs a specific placement uses a frame, not a hole in this
 * component). `icon` is an {@link IconComponent} reference this block mounts
 * at chip scale (contract E).
 */
export interface StatusChipProps {
    /**
     * Semantic tone that drives the chip color. Defaults to "neutral".
     */
    tone?: StatusChipTone
    /**
     * Optional leading icon — a component reference (`CheckCircleIcon`), not a
     * rendered element. This block mounts it at `size-4`. When {@link onCancel}
     * is set, the leading icon is dropped (removable chips carry a trailing ×
     * instead).
     */
    icon?: IconComponent
    /**
     * Label content rendered inside the chip.
     */
    children: ReactNode
    /**
     * When provided, renders a TRAILING cancel button (X at the end) — click it to
     * remove/cancel the chip. Uses HeroUI `CloseButton` with its OWN default × glyph
     * (per `alert.md`: close-affordances use `CloseButton`, never a hand-rolled
     * `<button><XIcon/>` — and don't override its glyph either; same treatment as
     * `Callout`). When set, the leading {@link StatusChipProps.icon} is DROPPED — a
     * removable/filter chip carries EITHER a leading status icon OR a trailing
     * cancel-X, never both (teacher: "once there's an X, there's no prefix icon").
     */
    onCancel?: () => void
    /**
     * Accessible label for the cancel button (the caller passes a localised string,
     * e.g. `t("common.remove")`). Falls back to HeroUI's default "Close".
     */
    cancelLabel?: string
}

/**
 * Maps a {@link StatusChipTone} to the matching HeroUI Chip color.
 */
const toneToColor: Record<StatusChipTone, "default" | "success" | "warning" | "danger" | "accent"> = {
    neutral: "default",
    success: "success",
    warning: "warning",
    danger: "danger",
    accent: "accent",
}

/**
 * Generic, presentational status chip. A thin pill-shaped wrapper over the
 * HeroUI Chip that maps a semantic tone to a chip color and optionally mounts a
 * leading {@link IconComponent} before the label. Presentational: the only
 * callback it takes is {@link StatusChipProps.onCancel} for a removable/filter
 * chip (a trailing cancel-X).
 *
 * Root stays raw HeroUI `Chip` rather than the design system's `Chip` atom so
 * {@link ElementCloseButton} can keep tonal cancel styling on the removable
 * branch without splitting close-affordance implementations.
 *
 * Does not take `className` (BLOCK-4) — a caller that needs a specific
 * placement composes a frame (`StackH`/`Cluster`/…) around the chip instead.
 * @see Story: .storybook/stories/blocks/chips/StatusChip/StatusChip.stories
 */
export const StatusChip = ({
    tone = "neutral",
    icon: Icon,
    children,
    onCancel,
    cancelLabel,
}: StatusChipProps) => {
    return (
        <Chip
            data-tier="block"
            data-component="StatusChip"
            color={toneToColor[tone]}
            variant="soft"
            size="sm"
            // w-fit: a chip is a hug-content pill by default — an explicit width
            // defeats a parent flex-col's `align-items: stretch` so it never
            // gets stretched full-width (card family §chip). Icon forced to
            // size-4 so every chip icon reads uniformly regardless of caller.
            // Colour is HeroUI's NATIVE soft pairing (`--chip-bg`=`<color>-soft`,
            // `--chip-fg`=`<color>-soft-foreground`) — no hand-rolled tint, so the
            // label + icon inherit an accessibility-tuned foreground (the old
            // `bg-<status>/10 + text-<status>` raw-hue formula failed contrast).
            className="w-fit"
        >
            {/* leading status icon — DROPPED when the chip is removable (has a
                trailing cancel-X): a chip carries EITHER a status icon OR a cancel-X,
                never both. Icon forced to size-4 so it reads uniformly. */}
            {Icon && !onCancel ? (
                <Icon className="size-4 shrink-0" aria-hidden focusable="false" />
            ) : null}
            <Chip.Label>{children}</Chip.Label>
            {onCancel ? (
                // shared close × — bakes transparent-at-rest + tonal hover (same
                // treatment as Callout's dismiss). `tone={tone}` so the X + its hover
                // read the chip's own colour, not a foreign grey.
                <ElementCloseButton
                    label={cancelLabel ?? ""}
                    onPress={onCancel}
                    tone={tone}
                />
            ) : null}
        </Chip>
    )
}

"use client"

import { Chip, ScrollShadow, Tooltip } from "@heroui/react"
import React, { useMemo, useState } from "react"

/**
 * Props for {@link _TagChips} — presentational; the overflow label already resolved.
 */
export interface TagChipsProps {
    /** Tag labels to render (e.g. hashtags). */
    tags: Array<string>
    /**
     * Maximum number of tag chips to show before collapsing the rest into a +N chip.
     * @default 3
     */
    maxVisible?: number
    /** Visual variant passed to each `Chip`. */
    variant?: React.ComponentProps<typeof Chip>["variant"]
    /** Already-localized "+N more" label for the overflow chip (interpolated with the count). */
    overflowLabel: string
}

/**
 * Renders tags as `Chip`s; if there are more than `maxVisible` tags, shows only the first
 * `maxVisible` and a +N chip. Hovering the row opens a HeroUI `Tooltip` listing every tag
 * (controlled open + short close delay so the pointer can move into the menu).
 *
 * @param props - {@link TagChipsProps}
 */
export const _TagChips = ({ tags, maxVisible = 3, variant = "soft", overflowLabel }: TagChipsProps) => {
    const [menuOpen, setMenuOpen] = useState(false)
    const visibleTags = useMemo(() => tags.slice(0, maxVisible), [tags, maxVisible])
    // How many tags were folded away; only when > 0 is there a real "overflow" worth a +N chip (avoids a negative/zero count when empty or not overflowing).
    const overflowCount = Math.max(0, tags.length - maxVisible)
    return (
        <div className="flex items-center gap-2">
            {visibleTags.map((tag, index) => (
                <Chip key={`${String(tag)}-${index}`} variant={variant}>
                    <Chip.Label>{tag}</Chip.Label>
                </Chip>
            ))}
            {overflowCount > 0 && (
                <Tooltip isOpen={menuOpen} onOpenChange={setMenuOpen}>
                    <Tooltip.Trigger>
                        <Chip color="default" variant={variant}>
                            <Chip.Label>{overflowLabel}</Chip.Label>
                        </Chip>
                    </Tooltip.Trigger>
                    <Tooltip.Content>
                        <ScrollShadow className="max-h-[200px]" hideScrollBar={true} orientation="horizontal">
                            <div className="flex flex-col gap-2 text-sm">
                                {tags.map((tag) => (
                                    <div key={tag}>{tag}</div>
                                ))}
                            </div>
                        </ScrollShadow>
                    </Tooltip.Content>
                </Tooltip>
            )}
        </div>
    )
}

"use client"

import React from "react"
import type { ReactNode } from "react"
import { Tabs, cn } from "@heroui/react"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { ExtendedTabs } from "@/components/blocks/navigation/ExtendedTabs"

/** One tab of a {@link CodeConsole} (e.g. "Test case", "Result"). */
export interface CodeConsoleTab {
    /** Stable tab id. */
    key: string
    /** Tab label. */
    label: ReactNode
    /** Panel content shown when this tab is selected. */
    content: ReactNode
}

/** Props for the {@link CodeConsole} block. */
export interface CodeConsoleProps extends WithClassNames<undefined> {
    /** Accessible label for the tab list. */
    ariaLabel: string
    /** The console tabs, in order. */
    tabs: Array<CodeConsoleTab>
    /** Selected tab id (controlled). */
    selectedTab: string
    /** Fired with the newly selected tab id. */
    onSelectTab: (key: string) => void
    /** Right-aligned action controls in the footer bar (e.g. Run / Submit). */
    actions: ReactNode
    /** Optional muted hint shown at the left of the footer bar. */
    hint?: ReactNode
}

/**
 * The bottom CONSOLE of a code workspace: a tab strip ({@link ExtendedTabs}) over
 * a scrollable panel, capped by a footer action bar (Run / Submit). Sits under an
 * editor, delineated by a top border; the block owns the shell (tabs · scroll ·
 * footer seam) so a feature only feeds tab content + the action controls. The
 * LeetCode-style console pattern — testcases and results in tabs, actions pinned.
 *
 * @param props - {@link CodeConsoleProps}
 * @see Story: .storybook/stories/blocks/code/CodeConsole/CodeConsole.stories
 */
export const CodeConsole = ({
    ariaLabel,
    tabs,
    selectedTab,
    onSelectTab,
    actions,
    hint,
    className,
}: CodeConsoleProps) => {
    const active = tabs.find((tab) => tab.key === selectedTab) ?? tabs[0]

    return (
        <div className={cn("flex min-h-0 flex-col border-t border-default bg-surface", className)}>
            <div className="px-3 pt-1">
                <ExtendedTabs selectedKey={selectedTab} onSelectionChange={onSelectTab}>
                    <Tabs.ListContainer>
                        <Tabs.List aria-label={ariaLabel}>
                            {tabs.map((tab) => (
                                <Tabs.Tab key={tab.key} id={tab.key}>
                                    {tab.label}
                                    <Tabs.Indicator />
                                </Tabs.Tab>
                            ))}
                        </Tabs.List>
                    </Tabs.ListContainer>
                </ExtendedTabs>
            </div>

            <div className="min-h-0 flex-1 overflow-auto p-3">
                {active?.content}
            </div>

            <div className="flex items-center justify-between gap-3 border-t border-default px-3 py-2">
                {hint ? <span className="text-xs text-muted">{hint}</span> : <span />}
                <div className="flex items-center gap-2">{actions}</div>
            </div>
        </div>
    )
}

import React from "react"
import type { ReactNode } from "react"
import { cn } from "@heroui/react"

/** Semantic tone of one IO row's label (drives the label colour only). */
export type IORowTone = "default" | "success" | "danger"

/** One labelled monospace block inside an {@link IOExampleCard}. */
export interface IOExampleRow {
    /** Stable key. */
    key: string
    /** Small muted label above the value (e.g. "Input", "Expected"). */
    label: ReactNode
    /** The literal value, rendered monospace and pre-wrapped. */
    value: string
    /** Label tone — `success`/`danger` tint the label for a expected-vs-got diff. */
    tone?: IORowTone
}

/** Props for the {@link IOExampleCard} block. */
export interface IOExampleCardProps {
    /** The labelled blocks, in order — separated by a dashed inset rule. */
    rows: Array<IOExampleRow>
}

/** Label colour per tone. */
const TONE_CLASS: Record<IORowTone, string> = {
    default: "text-muted",
    success: "text-success",
    danger: "text-danger",
}

/**
 * A bounded card that renders one or more LABELLED monospace blocks — a sample
 * testcase (input → output), or a failed-case diff (input · expected · got with
 * tinted labels). Replaces the hand-rolled `<pre className="bg-default-100">`
 * scattered across the coding surfaces so every IO block reads the same: a small
 * muted label over a mono, pre-wrapped value, rows split by a dashed inset rule.
 * Presentational + props-only.
 *
 * @param props - {@link IOExampleCardProps}
 * @see Story: .storybook/stories/blocks/code/IOExampleCard/IOExampleCard.stories
 */
export const IOExampleCard = ({ rows}: IOExampleCardProps) => {
    return (
        <div className={"overflow-hidden rounded-3xl border border-default bg-surface"}>
            {rows.map((row, index) => (
                <div
                    key={row.key}
                    className={cn("px-3 py-2", index > 0 && "border-t border-dashed border-default")}
                >
                    <div className={cn("text-xs font-medium", TONE_CLASS[row.tone ?? "default"])}>
                        {row.label}
                    </div>
                    <pre className="mt-1 whitespace-pre-wrap break-words font-mono text-sm text-foreground">
                        {row.value}
                    </pre>
                </div>
            ))}
        </div>
    )
}

