/** A brand-new, empty achievement entry. */
const emptyItem = (): CvBlockItem => ({ id: crypto.randomUUID(), fields: {} })

/** Props for {@link AchievementBlockEditor}. */
export type AchievementBlockEditorProps = CvBlockEditorProps 

/**
 * Freeform achievements block editor (outside awards, certifications) —
 * repeatable, self-reported, never scored. No AI affordance (per
 * `CV_BLOCK_TYPE_REGISTRY[Achievement]`).
 *
 * Shell is StackV with identity. HeroUI TextField/Input/Button remain —
 * house form migration is contract `CvBlockEditorFormSurface` (vendor boundary).
 *
 * @param props - {@link AchievementBlockEditorProps}
 */
export const AchievementBlockEditor = ({ block, onChange }: AchievementBlockEditorProps) => {
    const t = useTranslations()

    const setItems = (items: Array<CvBlockItem>) => onChange({ ...block, items } satisfies CvBlock)

    const onFieldChange = (itemId: string, key: string, value: string) => {
        setItems(block.items.map((item) => (
            item.id === itemId ? { ...item, fields: { ...item.fields, [key]: value } } : item
        )))
    }

    const onAddItem = () => setItems([...block.items, emptyItem()])
    const onRemoveItem = (itemId: string) => setItems(block.items.filter((item) => item.id !== itemId))
    const onMove = (index: number, direction: -1 | 1) => {
        const next = [...block.items]
        const target = index + direction
        if (target < 0 || target >= next.length) {
            return
        }
        [next[index], next[target]] = [next[target], next[index]]
        setItems(next)
    }

    const itemCount = block.items.length

    return (
        <StackV
            identity={{ tier: "block", component: "AchievementBlockEditor" }}
            principle="sibling-stack"
            explain="Same-kind peer stack of repeatable achievement cards — not group-boundary, because each card is a repeating peer rather than a section group."
            items={[
                ...block.items.map((item, index) => () => (
                    <RepeatableItemCard
                        onRemove={() => onRemoveItem(item.id)}
                        onMoveUp={index > 0 ? () => onMove(index, -1) : undefined}
                        onMoveDown={index < itemCount - 1 ? () => onMove(index, 1) : undefined}
                    >
                        <TextField variant="secondary">
                            <Label htmlFor={`cv-achievement-title-${item.id}`}>
                                {t("cv.blocks.achievement.fields.title")}
                            </Label>
                            <Input
                                id={`cv-achievement-title-${item.id}`}
                                placeholder={t("cv.blocks.achievement.placeholders.title")}
                                value={typeof item.fields.title === "string" ? item.fields.title : ""}
                                onChange={(event) => onFieldChange(item.id, "title", event.target.value)}
                            />
                        </TextField>
                        <TextField variant="secondary">
                            <Label htmlFor={`cv-achievement-description-${item.id}`}>
                                {t("cv.blocks.achievement.fields.description")}
                            </Label>
                            <Input
                                id={`cv-achievement-description-${item.id}`}
                                placeholder={t("cv.blocks.achievement.placeholders.description")}
                                value={typeof item.fields.description === "string" ? item.fields.description : ""}
                                onChange={(event) => onFieldChange(item.id, "description", event.target.value)}
                            />
                        </TextField>
                    </RepeatableItemCard>
                )),
                () => (
                    <Button variant="tertiary" size="sm" className="w-fit self-start" onPress={onAddItem}>
                        <PlusIcon aria-hidden className="size-4" />
                        {t("cv.blocks.achievement.addItem")}
                    </Button>
                ),
            ]}
        />
    )
}

"use client"

import React from "react"
import { Button, Input, Label, TextField } from "@heroui/react"
import { useTranslations } from "next-intl"
import { PlusIcon } from "@phosphor-icons/react"
import type { CvBlock, CvBlockEditorProps, CvBlockItem } from "@/modules/types/entities/cv"
import { AiRewriteButton } from "../shared/AiRewriteButton"
import { RepeatableItemCard } from "../shared/RepeatableItemCard"

/** A brand-new, empty activity entry. */
const emptyItem = (): CvBlockItem => ({ id: crypto.randomUUID(), fields: {} })

/** Props for {@link ActivityBlockEditor}. */
export type ActivityBlockEditorProps = CvBlockEditorProps 

/**
 * Extracurricular / volunteering activity block editor — repeatable entries
 * (title / description), each with its OWN "✨ AI writes it for you" (rewrites that
 * one item's `description`) and reorder/remove — mirrors
 * `AchievementBlockEditor` but AI-assisted (per `CV_BLOCK_TYPE_REGISTRY[Activity]`).
 *
 * @param props - {@link ActivityBlockEditorProps}
 */
export const ActivityBlockEditor = ({ block, onChange, onAiRewrite }: ActivityBlockEditorProps) => {
    const t = useTranslations()

    const setItems = (items: Array<CvBlockItem>) => onChange({ ...block, items } satisfies CvBlock)

    const onFieldChange = (itemId: string, key: string, value: string) => {
        setItems(block.items.map((item) => (
            item.id === itemId ? { ...item, fields: { ...item.fields, [key]: value } } : item
        )))
    }

    const onAddItem = () => setItems([...block.items, emptyItem()])
    const onRemoveItem = (itemId: string) => setItems(block.items.filter((item) => item.id !== itemId))
    const onMove = (index: number, direction: -1 | 1) => {
        const next = [...block.items]
        const target = index + direction
        if (target < 0 || target >= next.length) {
            return
        }
        [next[index], next[target]] = [next[target], next[index]]
        setItems(next)
    }

    const onRewriteItem = async (itemId: string) => {
        if (!onAiRewrite) {
            return
        }
        const item = block.items.find((candidate) => candidate.id === itemId)
        if (!item) {
            return
        }
        const rewritten = await onAiRewrite(itemId)
        const description = typeof rewritten.description === "string" ? rewritten.description : item.fields.description
        onFieldChange(itemId, "description", typeof description === "string" ? description : "")
    }

    return (
        <div className={"flex flex-col gap-3"}>
            {block.items.map((item, index) => (
                <RepeatableItemCard
                    key={item.id}
                    onRemove={() => onRemoveItem(item.id)}
                    onMoveUp={index > 0 ? () => onMove(index, -1) : undefined}
                    onMoveDown={index < block.items.length - 1 ? () => onMove(index, 1) : undefined}
                >
                    <TextField variant="secondary">
                        <Label htmlFor={`cv-activity-title-${item.id}`}>
                            {t("cv.blocks.activity.fields.title")}
                        </Label>
                        <Input
                            id={`cv-activity-title-${item.id}`}
                            placeholder={t("cv.blocks.activity.placeholders.title")}
                            value={typeof item.fields.title === "string" ? item.fields.title : ""}
                            onChange={(event) => onFieldChange(item.id, "title", event.target.value)}
                        />
                    </TextField>
                    <TextField variant="secondary">
                        <Label htmlFor={`cv-activity-description-${item.id}`}>
                            {t("cv.blocks.activity.fields.description")}
                        </Label>
                        <Input
                            id={`cv-activity-description-${item.id}`}
                            placeholder={t("cv.blocks.activity.placeholders.description")}
                            value={typeof item.fields.description === "string" ? item.fields.description : ""}
                            onChange={(event) => onFieldChange(item.id, "description", event.target.value)}
                        />
                    </TextField>

                    {onAiRewrite ? (
                        <AiRewriteButton onRewrite={() => onRewriteItem(item.id)} />
                    ) : null}
                </RepeatableItemCard>
            ))}

            <Button variant="tertiary" size="sm" className="w-fit self-start" onPress={onAddItem}>
                <PlusIcon aria-hidden className="size-4" />
                {t("cv.blocks.activity.addItem")}
            </Button>
        </div>
    )
}

"use client"

import React, { useState } from "react"
import { Button, FieldError, Input, Label, TextField } from "@heroui/react"
import { useTranslations } from "next-intl"
import { PlusIcon } from "@phosphor-icons/react"
import type { CvBlock, CvBlockEditorProps, CvBlockItem } from "@/modules/types/entities/cv"
import { RepeatableItemCard } from "../shared/RepeatableItemCard"
import { isValidOptionalUrl } from "@/modules/utils/cv-url"

/** A brand-new, empty certification entry. */
const emptyItem = (): CvBlockItem => ({ id: crypto.randomUUID(), fields: {} })

/** Props for {@link CertificationBlockEditor}. */
export type CertificationBlockEditorProps = CvBlockEditorProps 

/**
 * Certification block editor — repeatable entries (name / issuer / date),
 * entirely self-reported free text (StarCi holds no certification data). No
 * AI affordance (per `CV_BLOCK_TYPE_REGISTRY[Certification]`).
 *
 * @param props - {@link CertificationBlockEditorProps}
 */
export const CertificationBlockEditor = ({ block, onChange }: CertificationBlockEditorProps) => {
    const t = useTranslations()
    const [touchedUrlItemIds, setTouchedUrlItemIds] = useState<ReadonlySet<string>>(new Set())

    const setItems = (items: Array<CvBlockItem>) => onChange({ ...block, items } satisfies CvBlock)

    const onBlurCredentialUrl = (itemId: string) => {
        setTouchedUrlItemIds((prev) => new Set(prev).add(itemId))
    }

    const onFieldChange = (itemId: string, key: string, value: string) => {
        setItems(block.items.map((item) => (
            item.id === itemId ? { ...item, fields: { ...item.fields, [key]: value } } : item
        )))
    }

    const onAddItem = () => setItems([...block.items, emptyItem()])
    const onRemoveItem = (itemId: string) => setItems(block.items.filter((item) => item.id !== itemId))
    const onMove = (index: number, direction: -1 | 1) => {
        const next = [...block.items]
        const target = index + direction
        if (target < 0 || target >= next.length) {
            return
        }
        [next[index], next[target]] = [next[target], next[index]]
        setItems(next)
    }

    return (
        <div className={"flex flex-col gap-3"}>
            {block.items.map((item, index) => (
                <RepeatableItemCard
                    key={item.id}
                    onRemove={() => onRemoveItem(item.id)}
                    onMoveUp={index > 0 ? () => onMove(index, -1) : undefined}
                    onMoveDown={index < block.items.length - 1 ? () => onMove(index, 1) : undefined}
                >
                    <div className="grid grid-cols-1 gap-3 @app-sm:grid-cols-2">
                        <TextField variant="secondary">
                            <Label htmlFor={`cv-certification-name-${item.id}`}>
                                {t("cv.blocks.certification.fields.name")}
                            </Label>
                            <Input
                                id={`cv-certification-name-${item.id}`}
                                placeholder={t("cv.blocks.certification.placeholders.name")}
                                value={typeof item.fields.name === "string" ? item.fields.name : ""}
                                onChange={(event) => onFieldChange(item.id, "name", event.target.value)}
                            />
                        </TextField>
                        <TextField variant="secondary">
                            <Label htmlFor={`cv-certification-issuer-${item.id}`}>
                                {t("cv.blocks.certification.fields.issuer")}
                            </Label>
                            <Input
                                id={`cv-certification-issuer-${item.id}`}
                                placeholder={t("cv.blocks.certification.placeholders.issuer")}
                                value={typeof item.fields.issuer === "string" ? item.fields.issuer : ""}
                                onChange={(event) => onFieldChange(item.id, "issuer", event.target.value)}
                            />
                        </TextField>
                        <TextField variant="secondary">
                            <Label htmlFor={`cv-certification-date-${item.id}`}>
                                {t("cv.blocks.certification.fields.date")}
                            </Label>
                            <Input
                                id={`cv-certification-date-${item.id}`}
                                placeholder={t("cv.blocks.certification.placeholders.date")}
                                value={typeof item.fields.date === "string" ? item.fields.date : ""}
                                onChange={(event) => onFieldChange(item.id, "date", event.target.value)}
                            />
                        </TextField>
                        {(() => {
                            const credentialUrl = typeof item.fields.credentialUrl === "string" ? item.fields.credentialUrl : ""
                            const isInvalid = touchedUrlItemIds.has(item.id) && !isValidOptionalUrl(credentialUrl)
                            return (
                                <TextField variant="secondary" isInvalid={isInvalid}>
                                    <Label htmlFor={`cv-certification-credentialUrl-${item.id}`}>
                                        {t("cv.blocks.certification.fields.credentialUrl")}
                                    </Label>
                                    <Input
                                        id={`cv-certification-credentialUrl-${item.id}`}
                                        placeholder={t("cv.blocks.certification.placeholders.credentialUrl")}
                                        value={credentialUrl}
                                        onChange={(event) => onFieldChange(item.id, "credentialUrl", event.target.value)}
                                        onBlur={() => onBlurCredentialUrl(item.id)}
                                    />
                                    <FieldError>{t("cv.blocks.common.invalidUrl")}</FieldError>
                                </TextField>
                            )
                        })()}
                    </div>
                </RepeatableItemCard>
            ))}

            <Button variant="tertiary" size="sm" className="w-fit self-start" onPress={onAddItem}>
                <PlusIcon aria-hidden className="size-4" />
                {t("cv.blocks.certification.addItem")}
            </Button>
        </div>
    )
}

