"use client"

import React, { useState } from "react"
import { Calendar, DateField, DatePicker, FieldError, Input, Label, TextField } from "@heroui/react"
import { getLocalTimeZone, parseDate, today } from "@internationalized/date"
import type { DateValue } from "@internationalized/date"
import { useTranslations } from "next-intl"
import type { CvBlockEditorProps } from "@/modules/types/entities/cv"
import { isValidOptionalUrl } from "@/modules/utils/cv-url"
import { Grid, type GridItem } from "@/components/frames/Grid"

/** Field keys read/written on the single `personal` item's `fields`. */
const FIELD_KEYS = [
    "name",
    "role",
    "email",
    "phone",
    "location",
    "birthDate",
    "linkedinUrl",
    "githubUsername",
] as const
type PersonalFieldKey = typeof FIELD_KEYS[number]

/** The only field key validated as a URL (blur-triggered, per `isValidOptionalUrl`). */
const URL_FIELD_KEYS: ReadonlySet<PersonalFieldKey> = new Set(["linkedinUrl"])

/** Parses a stored ISO date string (e.g. `"2000-01-01"`) into a `DateValue`, or `null` if empty/unparseable. */
const parseStoredDate = (value: string): DateValue | null => {
    if (!value) {
        return null
    }
    try {
        return parseDate(value)
    } catch {
        return null
    }
}

/** Props for {@link PersonalBlockEditor}. */
export type PersonalBlockEditorProps = CvBlockEditorProps 

/**
 * Header/contact block editor — singleton, non-repeatable, no AI affordance
 * (per `CV_BLOCK_TYPE_REGISTRY[Personal]`). Holds its one fields set on
 * `block.items[0]` (created on first edit if the block starts with 0 items,
 * per the uniform `CvBlock` shape every block type shares).
 *
 * @param props - {@link PersonalBlockEditorProps}
 */
export const PersonalBlockEditor = ({ block, onChange }: PersonalBlockEditorProps) => {
    const t = useTranslations()
    const fields = block.items[0]?.fields ?? {}
    const [touchedUrlKeys, setTouchedUrlKeys] = useState<ReadonlySet<PersonalFieldKey>>(new Set())

    const onFieldChange = (key: PersonalFieldKey, value: string) => {
        const item = block.items[0] ?? { id: crypto.randomUUID(), fields: {} }
        const nextItem = { ...item, fields: { ...item.fields, [key]: value } }
        onChange({ ...block, items: [nextItem] })
    }

    const onBlurUrlField = (key: PersonalFieldKey) => {
        setTouchedUrlKeys((prev) => new Set(prev).add(key))
    }

    // Shell is Grid with identity. HeroUI DatePicker/TextField remain —
    // house form migration is contract `CvBlockEditorFormSurface` (vendor boundary).
    const items: Array<GridItem> = FIELD_KEYS.map((key) => {
        const value = typeof fields[key] === "string" ? (fields[key] as string) : ""

        if (key === "birthDate") {
            return {
                key,
                content: () => (
                    <DatePicker
                        aria-label={t("cv.blocks.personal.fields.birthDate")}
                        maxValue={today(getLocalTimeZone())}
                        value={parseStoredDate(value)}
                        onChange={(date) => onFieldChange(key, date ? date.toString() : "")}
                    >
                        <Label>{t("cv.blocks.personal.fields.birthDate")}</Label>
                        <DateField.Group fullWidth variant="secondary">
                            <DateField.Input>
                                {(segment) => <DateField.Segment segment={segment} />}
                            </DateField.Input>
                            <DateField.Suffix>
                                <DatePicker.Trigger>
                                    <DatePicker.TriggerIndicator />
                                </DatePicker.Trigger>
                            </DateField.Suffix>
                        </DateField.Group>
                        <DatePicker.Popover>
                            <Calendar aria-label={t("cv.blocks.personal.fields.birthDate")}>
                                <Calendar.Header>
                                    <Calendar.YearPickerTrigger>
                                        <Calendar.YearPickerTriggerHeading />
                                        <Calendar.YearPickerTriggerIndicator />
                                    </Calendar.YearPickerTrigger>
                                    <Calendar.NavButton slot="previous" />
                                    <Calendar.NavButton slot="next" />
                                </Calendar.Header>
                                <Calendar.Grid>
                                    <Calendar.GridHeader>
                                        {(day) => <Calendar.HeaderCell>{day}</Calendar.HeaderCell>}
                                    </Calendar.GridHeader>
                                    <Calendar.GridBody>
                                        {(date) => <Calendar.Cell date={date} />}
                                    </Calendar.GridBody>
                                </Calendar.Grid>
                                <Calendar.YearPickerGrid>
                                    <Calendar.YearPickerGridBody>
                                        {({ year }) => <Calendar.YearPickerCell year={year} />}
                                    </Calendar.YearPickerGridBody>
                                </Calendar.YearPickerGrid>
                            </Calendar>
                        </DatePicker.Popover>
                    </DatePicker>
                ),
            }
        }

        const isUrlField = URL_FIELD_KEYS.has(key)
        const isInvalid = isUrlField && touchedUrlKeys.has(key) && !isValidOptionalUrl(value)
        return {
            key,
            content: () => (
                <TextField variant="secondary" isInvalid={isInvalid}>
                    <Label htmlFor={`cv-personal-${key}`}>
                        {t(`cv.blocks.personal.fields.${key}`)}
                    </Label>
                    <Input
                        id={`cv-personal-${key}`}
                        placeholder={t(`cv.blocks.personal.placeholders.${key}`)}
                        value={value}
                        onChange={(event) => onFieldChange(key, event.target.value)}
                        onBlur={isUrlField ? () => onBlurUrlField(key) : undefined}
                    />
                    {isUrlField ? (
                        <FieldError>{t("cv.blocks.common.invalidUrl")}</FieldError>
                    ) : null}
                </TextField>
            ),
        }
    })

    return (
        <Grid
            identity={{ tier: "block", component: "PersonalBlockEditor" }}
            columns={{ base: 1, sm: 3 }}
            principle="sibling-stack"
            explain="Same-kind peer field cells — not group-boundary, because each field is a repeating peer rather than a section group."
            items={items}
        />
    )
}

"use client"

import React, { useMemo } from "react"
import {
    Label,
    ListBox,
    Select,
    Typography,
} from "@heroui/react"
import { useTranslations } from "next-intl"
import { useQueryMyPickableCvAchievementsSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyPickableCvAchievementsSwr"

/** One `myPickableCvAchievements.milestoneTaskAttempts[]` entry, as a `Select.Root` item. */
interface PickableAchievementItem {
    id: string
    title: string
}

/** Props for {@link PickFromStarciSelect}. */
export interface PickFromStarciSelectProps {
    /** Fires with the picked attempt's `id`, `taskTitle`, `milestoneTitle`, `courseTitle`. */
    onPick: (attempt: { id: string, taskTitle: string, milestoneTitle: string, courseTitle: string }) => void
    /** `sourceRef`s already used by other project items — hides them from the list (no picking the same capstone twice). */
    excludeIds?: Array<string>
}

/**
 * "Pick from StarCi" combobox — a REAL `Select` (not a fake div), listing the
 * signed-in user's passed capstones (`myPickableCvAchievements`, verified by
 * construction). Picking one is a one-shot action (adds a new `project` item
 * tagged `source: "verified"`) — the picker itself holds no persistent
 * selection, so it resets to its placeholder immediately after.
 *
 * @param props - {@link PickFromStarciSelectProps}
 */
export const PickFromStarciSelect = ({ onPick, excludeIds = [] }: PickFromStarciSelectProps) => {
    const t = useTranslations()
    const pickableSwr = useQueryMyPickableCvAchievementsSwr()
    const attempts = pickableSwr.data?.milestoneTaskAttempts ?? []
    const available = attempts.filter((attempt) => !excludeIds.includes(attempt.id))

    const items = useMemo<Array<PickableAchievementItem>>(
        () => available.map((attempt) => ({
            id: attempt.id,
            title: `${attempt.taskTitle} — ${attempt.milestoneTitle} (${attempt.courseTitle})`,
        })),
        [available],
    )

    const isLoading = pickableSwr.isLoading && !pickableSwr.data
    const isDisabled = isLoading || items.length === 0

    return (
        <div>
            <div className="flex flex-col gap-2">
                <Label htmlFor="cv-project-pick-from-starci">
                    {t("cv.blocks.project.pickFromStarciLabel")}
                </Label>
                <Select.Root<PickableAchievementItem, "single">
                    id="cv-project-pick-from-starci"
                    aria-label={t("cv.blocks.project.pickFromStarciLabel")}
                    isDisabled={isDisabled}
                    selectedKey={null}
                    onSelectionChange={(key) => {
                        if (!key) {
                            return
                        }
                        const attempt = available.find((candidate) => candidate.id === String(key))
                        if (attempt) {
                            onPick(attempt)
                        }
                    }}
                >
                    <Select.Trigger aria-label={t("cv.blocks.project.pickFromStarciLabel")}>
                        <Select.Value>
                            {() => (
                                <Typography type="body-sm" color="muted">
                                    {isLoading
                                        ? t("cv.blocks.project.pickFromStarciLoading")
                                        : items.length === 0
                                            ? t("cv.blocks.project.pickFromStarciEmpty")
                                            : t("cv.blocks.project.pickFromStarciPlaceholder")}
                                </Typography>
                            )}
                        </Select.Value>
                        <Select.Indicator />
                    </Select.Trigger>
                    <Select.Popover>
                        <ListBox.Root aria-label={t("cv.blocks.project.pickFromStarciLabel")} items={items}>
                            {(item) => (
                                <ListBox.Item key={item.id} id={item.id} textValue={item.title} aria-label={item.title}>
                                    <span>{item.title}</span>
                                </ListBox.Item>
                            )}
                        </ListBox.Root>
                    </Select.Popover>
                </Select.Root>
            </div>
        </div>
    )
}

"use client"

import React from "react"
import { Button, Chip, Input, Label, TextArea, TextField } from "@heroui/react"
import { useTranslations } from "next-intl"
import { PlusIcon, SealCheckIcon, UserIcon } from "@phosphor-icons/react"
import { CvBlockItemSource } from "@/modules/types/enums/cv-block-item-source"
import type { CvBlock, CvBlockEditorProps, CvBlockItem } from "@/modules/types/entities/cv"
import { AiRewriteButton } from "../shared/AiRewriteButton"
import { RepeatableItemCard } from "../shared/RepeatableItemCard"
import { PickFromStarciSelect } from "./PickFromStarciSelect"

/** A brand-new, self-reported project entry ("+ Add outside project"). */
const emptySelfItem = (): CvBlockItem => ({
    id: crypto.randomUUID(),
    source: CvBlockItemSource.Self,
    fields: {},
})

/** Props for {@link ProjectBlockEditor}. */
export type ProjectBlockEditorProps = CvBlockEditorProps 

/**
 * Project block editor — the ONLY block whose items carry `source` /
 * `sourceRef`: picked from a passed StarCi capstone (tagged "Verified",
 * success) via {@link PickFromStarciSelect}, or typed manually via "+ Add outside
 * project" (tagged "Self-reported", muted). Every item — verified or self — shares
 * the same editable fields (title/description/bullets) plus its own "✨ AI
 * write for me"; verified items pass `capstoneAttemptId` (their `sourceRef`) so
 * the rewrite is grounded (RAG) on the real capstone data.
 *
 * @param props - {@link ProjectBlockEditorProps}
 */
export const ProjectBlockEditor = ({ block, onChange, onAiRewrite }: ProjectBlockEditorProps) => {
    const t = useTranslations()

    const setItems = (items: Array<CvBlockItem>) => onChange({ ...block, items } satisfies CvBlock)

    const onFieldChange = (itemId: string, key: string, value: string) => {
        setItems(block.items.map((item) => (
            item.id === itemId ? { ...item, fields: { ...item.fields, [key]: value } } : item
        )))
    }

    const onRemoveItem = (itemId: string) => setItems(block.items.filter((item) => item.id !== itemId))
    const onMove = (index: number, direction: -1 | 1) => {
        const next = [...block.items]
        const target = index + direction
        if (target < 0 || target >= next.length) {
            return
        }
        [next[index], next[target]] = [next[target], next[index]]
        setItems(next)
    }

    const onAddSelfItem = () => setItems([...block.items, emptySelfItem()])

    const onPickFromStarci = (attempt: { id: string, taskTitle: string, milestoneTitle: string, courseTitle: string }) => {
        const verifiedItem: CvBlockItem = {
            id: crypto.randomUUID(),
            source: CvBlockItemSource.Verified,
            sourceRef: attempt.id,
            fields: {
                title: attempt.taskTitle,
                description: `${attempt.milestoneTitle} — ${attempt.courseTitle}`,
            },
        }
        setItems([...block.items, verifiedItem])
    }

    const onRewriteItem = async (itemId: string) => {
        if (!onAiRewrite) {
            return
        }
        const item = block.items.find((candidate) => candidate.id === itemId)
        if (!item) {
            return
        }
        const rewritten = await onAiRewrite(itemId)
        setItems(block.items.map((candidate) => (
            candidate.id === itemId
                ? { ...candidate, fields: { ...candidate.fields, ...rewritten } }
                : candidate
        )))
    }

    const usedVerifiedRefs = block.items
        .filter((item) => item.source === CvBlockItemSource.Verified && item.sourceRef)
        .map((item) => item.sourceRef as string)

    return (
        <div className={"flex flex-col gap-3"}>
            {block.items.map((item, index) => {
                const isVerified = item.source === CvBlockItemSource.Verified
                return (
                    <RepeatableItemCard
                        key={item.id}
                        onRemove={() => onRemoveItem(item.id)}
                        onMoveUp={index > 0 ? () => onMove(index, -1) : undefined}
                        onMoveDown={index < block.items.length - 1 ? () => onMove(index, 1) : undefined}
                        headerEnd={(
                            <Chip
                                size="sm"
                                className={isVerified ? "bg-success-soft text-success-soft-foreground" : "bg-default text-muted"}
                            >
                                {isVerified ? (
                                    <SealCheckIcon aria-hidden className="size-4" />
                                ) : (
                                    <UserIcon aria-hidden className="size-4" />
                                )}
                                <Chip.Label>
                                    {isVerified ? t("cv.blocks.project.sourceVerified") : t("cv.blocks.project.sourceSelf")}
                                </Chip.Label>
                            </Chip>
                        )}
                    >
                        <TextField variant="secondary">
                            <Label htmlFor={`cv-project-title-${item.id}`}>
                                {t("cv.blocks.project.fields.title")}
                            </Label>
                            <Input
                                id={`cv-project-title-${item.id}`}
                                placeholder={t("cv.blocks.project.placeholders.title")}
                                value={typeof item.fields.title === "string" ? item.fields.title : ""}
                                onChange={(event) => onFieldChange(item.id, "title", event.target.value)}
                            />
                        </TextField>

                        <TextField variant="secondary">
                            <Label htmlFor={`cv-project-description-${item.id}`}>
                                {t("cv.blocks.project.fields.description")}
                            </Label>
                            <TextArea
                                id={`cv-project-description-${item.id}`}
                                rows={3}
                                className="resize-none"
                                placeholder={t("cv.blocks.project.placeholders.description")}
                                value={typeof item.fields.description === "string" ? item.fields.description : ""}
                                onChange={(event) => onFieldChange(item.id, "description", event.target.value)}
                            />
                        </TextField>

                        {/* AI write-for-me ONLY for StarCi-verified items — their `sourceRef`
                            grounds the rewrite (RAG) on the real capstone. Self-reported
                            items have nothing real to ground on, so no AI assist. */}
                        {onAiRewrite && isVerified ? (
                            <AiRewriteButton onRewrite={() => onRewriteItem(item.id)} />
                        ) : null}
                    </RepeatableItemCard>
                )
            })}

            <div className="flex flex-col gap-3 rounded-2xl border border-dashed border-default px-4 py-3">
                <PickFromStarciSelect onPick={onPickFromStarci} excludeIds={usedVerifiedRefs} />

                <Button variant="tertiary" size="sm" className="w-fit self-start" onPress={onAddSelfItem}>
                    <PlusIcon aria-hidden className="size-4" />
                    {t("cv.blocks.project.addExternal")}
                </Button>
            </div>
        </div>
    )
}

"use client"

import React, { useState } from "react"
import { Button, Chip, Input, Label, Link, TextField, Typography } from "@heroui/react"
import { useTranslations } from "next-intl"
import { PlusIcon, XIcon } from "@phosphor-icons/react"
import type { CvBlock, CvBlockEditorProps, CvBlockItem } from "@/modules/types/entities/cv"

/**
 * Curated tech-stack suggestions — a stand-in for a future "course tags /
 * selectedLang on challenge submissions" source (no FE query for that exists
 * yet). Static suggestions are explicitly acceptable here per the frozen
 * contract ("always self-declared, low risk, no label needed").
 */
const SUGGESTED_SKILLS: Array<string> = [
    "TypeScript",
    "JavaScript",
    "React",
    "Next.js",
    "Node.js",
    "NestJS",
    "PostgreSQL",
    "Docker",
    "Kubernetes",
    "GraphQL",
    "Go",
    "Java",
    "C#",
    "AWS",
]

/** Reads the skill names currently on this block's items (`fields.name`). */
const namesOf = (block: CvBlock): Array<string> => block.items
    .map((item) => (typeof item.fields.name === "string" ? item.fields.name : undefined))
    .filter((name): name is string => Boolean(name))

/** Props for {@link SkillsBlockEditor}. */
export type SkillsBlockEditorProps = CvBlockEditorProps 

/**
 * Skills block editor — one repeatable item PER skill (`fields.name`).
 * Suggested chips (tech-stack stand-in) tap to add; a free-text field adds
 * anything else. No AI affordance, no verified/self distinction (only
 * `project` items carry `source` — per `CV_BLOCK_TYPE_REGISTRY[Skills]`).
 *
 * @param props - {@link SkillsBlockEditorProps}
 */
export const SkillsBlockEditor = ({ block, onChange }: SkillsBlockEditorProps) => {
    const t = useTranslations()
    const [draft, setDraft] = useState("")
    const currentNames = namesOf(block)

    const setItems = (items: Array<CvBlockItem>) => onChange({ ...block, items } satisfies CvBlock)

    const onAddSkill = (name: string) => {
        const trimmed = name.trim()
        if (!trimmed || currentNames.some((existing) => existing.toLowerCase() === trimmed.toLowerCase())) {
            return
        }
        setItems([...block.items, { id: crypto.randomUUID(), fields: { name: trimmed } }])
    }

    const onRemoveSkill = (itemId: string) => setItems(block.items.filter((item) => item.id !== itemId))

    const remainingSuggestions = SUGGESTED_SKILLS.filter(
        (skill) => !currentNames.some((existing) => existing.toLowerCase() === skill.toLowerCase()),
    )

    return (
        <div className={"flex flex-col gap-3"}>
            {block.items.length > 0 ? (
                <div className="flex flex-wrap items-center gap-2">
                    {block.items.map((item) => {
                        const name = typeof item.fields.name === "string" ? item.fields.name : ""
                        return (
                            <Chip key={item.id} size="sm" className="bg-accent-soft text-accent-soft-foreground">
                                <Chip.Label>{name}</Chip.Label>
                                <Link
                                    className="text-accent-soft-foreground no-underline opacity-60 transition-opacity hover:opacity-100 hover:no-underline"
                                    aria-label={t("cv.blocks.skills.removeSkill", { name })}
                                    onPress={() => onRemoveSkill(item.id)}
                                >
                                    <XIcon aria-hidden className="size-4" />
                                </Link>
                            </Chip>
                        )
                    })}
                </div>
            ) : null}

            {remainingSuggestions.length > 0 ? (
                <div className="flex flex-col gap-2">
                    <Typography type="body-xs" color="muted">
                        {t("cv.blocks.skills.suggestedLabel")}
                    </Typography>
                    <div className="flex flex-wrap items-center gap-2">
                        {remainingSuggestions.map((skill) => (
                            <button
                                key={skill}
                                type="button"
                                onClick={() => onAddSkill(skill)}
                                className="cursor-pointer rounded-full border border-default bg-surface px-3 py-1 text-xs text-muted outline-none transition-colors hover:bg-default focus-visible:ring-2 focus-visible:ring-accent"
                            >
                                {skill}
                            </button>
                        ))}
                    </div>
                </div>
            ) : null}

            <div className="flex items-end gap-2">
                <TextField variant="secondary" className="flex-1">
                    <Label htmlFor="cv-skills-draft">{t("cv.blocks.skills.addLabel")}</Label>
                    <Input
                        id="cv-skills-draft"
                        placeholder={t("cv.blocks.skills.addPlaceholder")}
                        value={draft}
                        onChange={(event) => setDraft(event.target.value)}
                        onKeyDown={(event) => {
                            if (event.key === "Enter") {
                                event.preventDefault()
                                onAddSkill(draft)
                                setDraft("")
                            }
                        }}
                    />
                </TextField>
                <Button
                    variant="tertiary"
                    size="sm"
                    isDisabled={!draft.trim()}
                    onPress={() => {
                        onAddSkill(draft)
                        setDraft("")
                    }}
                >
                    <PlusIcon aria-hidden className="size-4" />
                    {t("cv.blocks.skills.addAction")}
                </Button>
            </div>
        </div>
    )
}

"use client"

import React from "react"
import { Label, TextArea, TextField } from "@heroui/react"
import { useTranslations } from "next-intl"
import type { CvBlockEditorProps } from "@/modules/types/entities/cv"
import { AiRewriteButton } from "../shared/AiRewriteButton"

/** Props for {@link SummaryBlockEditor}. */
export type SummaryBlockEditorProps = CvBlockEditorProps 

/**
 * Summary/objective paragraph editor — singleton, non-repeatable, holds its
 * one `text` field on `block.items[0]`. Has the "✨ AI write for me" affordance
 * (`onAiRewrite`, no `itemId` — the whole block's single fields set).
 *
 * @param props - {@link SummaryBlockEditorProps}
 */
export const SummaryBlockEditor = ({ block, onChange, onAiRewrite }: SummaryBlockEditorProps) => {
    const t = useTranslations()
    const text = typeof block.items[0]?.fields.text === "string" ? (block.items[0].fields.text as string) : ""

    const onTextChange = (value: string) => {
        const item = block.items[0] ?? { id: crypto.randomUUID(), fields: {} }
        onChange({ ...block, items: [{ ...item, fields: { ...item.fields, text: value } }] })
    }

    const onRewrite = async () => {
        if (!onAiRewrite) {
            return
        }
        const rewritten = await onAiRewrite(undefined)
        const value = typeof rewritten.text === "string" ? rewritten.text : text
        onTextChange(value)
    }

    return (
