"use client"

import React, { useCallback, useMemo, useState } from "react"
import axios from "axios"
import { Spinner, TextArea, TextField, Typography } from "@heroui/react"
import { useTranslations } from "next-intl"
import { Dropzone } from "@/components/blocks/form/Dropzone"
import { TabsCard } from "@/components/blocks/navigation/TabsCard"
import { sleep } from "@/modules/utils/misc"
import { useMutateGenerateSubmitCvPresignUrlSwr } from "@/hooks/swr/api/graphql/mutations/useMutateGenerateSubmitCvPresignUrlSwr"
import { useMutateExtractDocumentTextSwr } from "@/hooks/swr/api/graphql/mutations/useMutateExtractDocumentTextSwr"

/** MIME types the upload mode accepts (mirrors the BE `extractCvText`: pdf-parse / mammoth / utf-8 fallback). */
const ACCEPTED_MIME_TYPES: ReadonlyArray<string> = [
    "application/pdf",
    "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
    "text/plain",
]

/** Max upload size in bytes (10MB — mirrors the legacy CvGalleryPage-upload ceiling). */
const MAX_SIZE_IN_BYTES = 10 * 1024 * 1024

/** Which input method is active. */
type InputMode = "paste" | "upload"

/** Props for {@link CvTextOrFileInput}. */
export interface CvTextOrFileInputProps {
    /** The text value both modes ultimately produce (paste = typed, upload = extracted). */
    value: string
    /** Fired with the new text (typed directly, or extracted from an uploaded file). */
    onChange: (text: string) => void
    /** Field id for the paste `<Label htmlFor>`. */
    fieldId: string
    /** Label above the paste textarea. */
    label: string
    /** Placeholder inside the paste textarea. */
    placeholder: string
    /** Fired whenever an upload is in-flight so the parent can disable submit. */
    onExtractingChange?: (isExtracting: boolean) => void
}

/**
 * A shared "paste text OR upload a file" input — the two ways to feed the same
 * text payload into `splitCvFromText` (a CvGalleryPage) or `tailorCvBlocks` (a job
 * description). A `TabsCard` (primary) switches modes: paste = a plain textarea;
 * upload = a `Dropzone` (PDF / DOCX / TXT, 10MB) that presigns → PUTs the file
 * to storage → calls `extractDocumentText` server-side → writes the extracted
 * text back into `value` AND flips to paste mode so the user reviews/edits it
 * before submitting. Both modals reuse this so the pattern stays identical
 * (only the labels + downstream mutation differ).
 *
 * @param props - {@link CvTextOrFileInputProps}
 */
export const CvTextOrFileInput = ({
    value,
    onChange,
    fieldId,
    label,
    placeholder,
    onExtractingChange}: CvTextOrFileInputProps) => {
    const t = useTranslations()
    const [mode, setMode] = useState<InputMode>("paste")
    const [file, setFile] = useState<File | null>(null)
    const [isExtracting, setIsExtracting] = useState(false)
    const [uploadError, setUploadError] = useState<string | null>(null)
    const { trigger: presign } = useMutateGenerateSubmitCvPresignUrlSwr()
    const { trigger: extractDocumentText } = useMutateExtractDocumentTextSwr()

    const setExtracting = useCallback((next: boolean) => {
        setIsExtracting(next)
        onExtractingChange?.(next)
    }, [onExtractingChange])

    const onFileSelected = useCallback(async (selected: File | null) => {
        setFile(selected)
        setUploadError(null)
        if (!selected) {
            return
        }
        if (selected.size > MAX_SIZE_IN_BYTES) {
            setUploadError(t("cv.builder.uploadTooLarge"))
            return
        }
        setExtracting(true)
        try {
            // 1) presign a PUT URL + object key
            const presignResult = await presign({ request: { fileName: selected.name } })
            const presignData = presignResult.data?.generateSubmitCvPresignUrl?.data
            if (!presignData?.url || !presignData.cdnKey) {
                throw new Error("presign failed")
            }
            // 2) PUT the raw file to storage
            const contentType = selected.type || "application/octet-stream"
            const putResult = await axios.put(presignData.url, selected, {
                headers: { "Content-Type": contentType },
            })
            if (putResult.status !== 200) {
                throw new Error(`upload failed (${putResult.status})`)
            }
            // 3) wait for storage to propagate, then extract text server-side
            await sleep(1000)
            const extractResult = await extractDocumentText({ cdnKey: presignData.cdnKey })
            const text = extractResult.data?.extractDocumentText?.data?.text
            if (!text) {
                throw new Error("extraction empty")
            }
            // load the extracted text into the shared value + flip to paste so the
            // user reviews/edits it before submitting
            onChange(text)
            setMode("paste")
            setFile(null)
        } catch {
            setUploadError(t("cv.builder.uploadFailed"))
        } finally {
            setExtracting(false)
        }
    }, [presign, extractDocumentText, onChange, setExtracting, t])

    const modeTabs = useMemo(() => ({
        items: [
            { key: "paste", label: t("cv.builder.inputModePaste") },
            { key: "upload", label: t("cv.builder.inputModeUpload") },
        ],
        selectedKey: mode,
        ariaLabel: t("cv.builder.inputModeAria"),
        onSelectionChange: (key: React.Key) => setMode(String(key) as InputMode),
    }), [mode, t])

    return (
        <div className={"flex flex-col gap-3"}>
            {/* TabsCard pattern: mode tabs float above; the field sits DIRECTLY below
                (no outer <Card> — the modal is already a surface, so wrapping the field
                in another card = card-in-card). No field <Label> (tab labels the mode). */}
            <TabsCard leftTabs={modeTabs} />
            {mode === "paste" ? (
                <TextField variant="secondary" className="w-full">
                    <TextArea
                        id={fieldId}
                        aria-label={label}
                        rows={10}
                        className="resize-none"
                        placeholder={placeholder}
                        value={value}
                        onChange={(event) => onChange(event.target.value)}
                    />
                </TextField>
            ) : (
                <div className="flex flex-col gap-2">
                    <Dropzone
                        hint={t("cv.builder.uploadHint")}
                        file={file}
                        acceptedMimeTypes={[...ACCEPTED_MIME_TYPES]}
                        maxSizeInBytes={MAX_SIZE_IN_BYTES}
                        errorMessage={uploadError ?? undefined}
                        onChange={onFileSelected}
                    />
                    {isExtracting ? (
                        <div className="flex items-center gap-2">
                            <Spinner />
                            <Typography type="body-sm" color="muted">
                                {t("cv.builder.uploadExtracting")}
                            </Typography>
                        </div>
                    ) : null}
                </div>
            )}
        </div>
    )
}

"use client"

import React, {
    useEffect,
    useState,
} from "react"

/** Brand + celebratory palette for the falling pieces. */
const COLORS = ["#d6006e", "#eab308", "#16a34a", "#3b82f6", "#f97316", "#a855f7"]

/** Props for {@link Confetti}. */
export interface ConfettiProps {
    /**
     * Bump this to fire a burst (e.g. a counter incremented on a win). `0` stays
     * idle; each distinct non-zero value fires exactly one burst.
     */
    fireKey: number
    /** Piece count (default 90). */
    count?: number
}

/** One falling piece's randomised layout. */
interface Piece {
    id: string
    left: number
    delay: number
    duration: number
    color: string
    width: number
    rotate: number
}

/**
 * A lightweight, dependency-free confetti burst — a fixed, non-interactive overlay
 * that rains coloured pieces down the viewport once per `fireKey` change, then
 * clears itself. Pure CSS fall animation (no canvas, no library). Used to celebrate
 * a top-3 league finish when the viewer lands on a board where they've placed.
 *
 * @param props - {@link ConfettiProps}
 */
export const Confetti = ({
    fireKey,
    count = 90,
}: ConfettiProps) => {
    const [pieces, setPieces] = useState<Array<Piece>>([])

    useEffect(
        () => {
            if (!fireKey) {
                return
            }
            // randomise in the effect (client-only) so there is no SSR hydration drift
            const next: Array<Piece> = []
            for (let i = 0; i < count; i += 1) {
                next.push({
                    id: `${fireKey}-${i}`,
                    left: Math.random() * 100,
                    delay: Math.random() * 0.4,
                    duration: 2 + Math.random() * 1.5,
                    color: COLORS[i % COLORS.length],
                    width: 6 + Math.random() * 6,
                    rotate: Math.random() * 360,
                })
            }
            setPieces(next)
            const timer = window.setTimeout(() => setPieces([]), 4000)
            return () => window.clearTimeout(timer)
        },
        [fireKey, count],
    )

    if (pieces.length === 0) {
        return null
    }

    return (
        <div aria-hidden className="pointer-events-none fixed inset-0 z-50 overflow-hidden">
            <style>
                {"@keyframes starci-confetti-fall{0%{transform:translateY(-12vh) rotate(0deg);opacity:1}100%{transform:translateY(112vh) rotate(720deg);opacity:.85}}"}
            </style>
            {pieces.map((piece) => (
                <span
                    key={piece.id}
                    className="absolute top-0 rounded-[2px]"
                    style={{
                        left: `${piece.left}%`,
                        width: `${piece.width}px`,
                        height: `${piece.width * 0.6}px`,
                        backgroundColor: piece.color,
                        animation: `starci-confetti-fall ${piece.duration}s linear ${piece.delay}s forwards`,
                    }}
                />
            ))}
        </div>
    )
}

"use client"

import React from "react"
import {
    Link,
    Typography,
    cn,
} from "@heroui/react"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { SurfaceListCard, SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import type { VerdictBand } from "@/components/blocks/cards/verdict-band"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { UserCell } from "@/components/composites/lists/UserCell"
import {
    placeMedalIcon,
    rankBadgeIcon,
} from "@/components/blocks/dashboard/rankBadge"
import { StackV } from "@/components/frames/Stack"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** One normalised leaderboard row (the container maps its query data into this). */
export interface LeaderboardRow {
    /** React key + stable id. */
    key: string
    /** 1-based rank — ≤3 renders a place medal, else the number. */
    rank: number
    /** Display username (null → dash). */
    username: string | null
    /** Avatar URL (null → generated fallback). */
    avatar?: string | null
    /** Pre-formatted trailing value (e.g. "640 pts" / "1420 XP"). */
    valueLabel: React.ReactNode
    /** True → highlight as the viewer (accent value + `meLabel` suffix). */
    isMe?: boolean
    /** Profile link target; omit → the identity is non-clickable. */
    profileHref?: string
    /** Context action at the far right (rank-delta caret / follow button). */
    trailing?: React.ReactNode
    /**
     * Optional left band (`SurfaceListCardItem.withVerdict`, `card.md` §3i) — a DATA
     * signal on this row (e.g. the weekly cohort's promote/demote zone). Pass the
     * canonical {@link VerdictBand} (`variant`/`color`) — NOT a free-form `className`,
     * which `verdictBandClassName` silently ignores (was the "invisible border" bug).
     */
    verdict?: VerdictBand
}

/** The viewer's own standing shown as the card's header line. */
export interface LeaderboardStanding {
    /** Viewer's rank — drives the leading {@link IconTile} badge (medal ≤3 / cup 4+). */
    rank: number
    /** Primary line (e.g. "Rank #1 · top 20%"). */
    primary: React.ReactNode
    /** Secondary muted line (e.g. "640 pts · Resets in 1 day 18 hours"). */
    secondary?: React.ReactNode
}

/** Props for {@link LeaderboardListCard}. */
export interface LeaderboardListCardProps extends WithClassNames<undefined> {
    /**
     * Bare mode — skip the {@link LabeledCard} frame (`title`/`onSeeMore` ignored) and
     * render just the standing + list. For a full page that already has its own
     * `PageHeader` (the course leaderboard); the dashboard cards leave it off.
     */
    bare?: boolean
    /** Card label (LabeledCard heading). Ignored when `bare`. */
    title?: string
    /** "See more" handler (opens the full board). */
    onSeeMore?: () => void
    /** "See more" label. */
    seeMoreLabel?: string
    /** The viewer's own standing header line (omit when they have no rank). */
    standing?: LeaderboardStanding
    /**
     * Optional node between the standing and the list — e.g. a `Podium` on a spacious
     * page (course leaderboard). Dashboard cards omit it (compact, no podium).
     */
    topSlot?: React.ReactNode
    /** The ranked rows (top-N slice; when a podium is in `topSlot`, pass rank 4+). */
    rows: Array<LeaderboardRow>
    /** Pinned self-row when the viewer sits below the shown slice. */
    selfRow?: LeaderboardRow
    /** Ellipsis label above the pinned self-row (e.g. "41 more people"). */
    ellipsisLabel?: React.ReactNode
    /** "You" suffix appended to the viewer's own row name. */
    meLabel?: React.ReactNode
}

/**
 * The ONE shared render for a dashboard leaderboard preview — a {@link LabeledCard}
 * with the viewer's own standing (rank-driven {@link IconTile} badge: medal for the
 * podium, cup below) over a bordered {@link SurfaceListCard} of ranked rows (top-3
 * wear place medals). Both the weekly "Weekly league" and the global "Top learners"
 * cards map their data into this, so they render IDENTICALLY (teacher 2026-07-17 "2
 * identical sections"); only the per-context `trailing` slot (rank-delta caret vs follow)
 * and the emergent badge differ. Presentational + props-only; containers own the fetch.
 *
 * @param props - {@link LeaderboardListCardProps}
 */
export const LeaderboardListCard = ({
    bare = false,
    title,
    onSeeMore,
    seeMoreLabel,
    standing,
    topSlot,
    rows,
    selfRow,
    ellipsisLabel,
    meLabel,
    className,
}: LeaderboardListCardProps) => {
    /** Render one row (shared by the ranked list and the pinned self-row). */
    const renderRow = (row: LeaderboardRow) => {
        const displayName = row.isMe && row.username && meLabel
            ? `${row.username} · ${meLabel}`
            : (row.username ?? "")
        const identity = (
            <UserCell
                username={displayName}
                avatar={row.avatar ?? undefined}
                isOwnRow={row.isMe }
            />
        )
        return (
            <SurfaceListCardItem key={row.key} withVerdict={row.verdict}>
                <div className="flex items-center gap-3">
                    {/* top-3 → place medal (🥇🥈🥉); rank 4+ → plain number. Number matches the
                        medal's w-6 CENTERED slot (teacher 2026-07-17 "4 and 5 still misaligned") at the same
                        text-sm foreground as the name (same-row same-size, `visual-hierarchy`). */}
                    {row.rank <= 3 ? (
                        <span className="flex w-6 shrink-0 items-center justify-center">
                            {placeMedalIcon(row.rank)}
                        </span>
                    ) : (
                        <span className="flex w-6 shrink-0 items-center justify-center text-sm text-foreground">
                            {row.rank}
                        </span>
                    )}
                    {row.profileHref ? (
                        <Link
                            href={row.profileHref}
                            className="flex min-w-0 flex-1 items-center text-foreground no-underline transition-opacity hover:opacity-60"
                        >
                            {identity}
                        </Link>
                    ) : (
                        <div className="flex min-w-0 flex-1 items-center">{identity}</div>
                    )}
                    {/* value = meta → always muted + right-aligned tabular so the XP column
                        lines up across rows (teacher 2026-07-17: accent moves to the NAME, value
                        stays muted). */}
                    <Typography
                        type="body-sm"
                        color="muted"
                        className="shrink-0 text-right tabular-nums"
                    >
                        {row.valueLabel}
                    </Typography>
                    {row.trailing ? (
                        <div className="flex shrink-0 items-center">{row.trailing}</div>
                    ) : null}
                </div>
            </SurfaceListCardItem>
        )
    }

    const contentItems = [
        ...(standing
            ? [() => (
                <div className="flex items-center gap-3">
                    <IconTile icon={rankBadgeIcon(standing.rank)} tone="neutral" size="sm" />
                    <div className="flex min-w-0 flex-col">
                        <Typography type="body-sm" weight="bold" truncate>
                            {standing.primary}
                        </Typography>
                        {standing.secondary ? (
                            <Typography type="body-xs" color="muted">
                                {standing.secondary}
                            </Typography>
                        ) : null}
                    </div>
                </div>
            )]
            : []),
        ...(topSlot ? [() => <>{topSlot}</>] : []),
        ...(rows.length > 0 || selfRow
            ? [() => (
                <SurfaceListCard bordered>
                    {rows.map(renderRow)}
                    {selfRow ? (
                        <>
                            <SurfaceListCardItem>
                                <div className="flex min-h-8 items-center gap-3">
                                    <span className="flex w-6 shrink-0 items-center justify-center text-base leading-none tracking-widest text-muted">
                                        ⋯
                                    </span>
                                    <Typography type="body-sm" color="muted">
                                        {ellipsisLabel}
                                    </Typography>
                                </div>
                            </SurfaceListCardItem>
                            {renderRow(selfRow)}
                        </>
                    ) : null}
                </SurfaceListCard>
            )]
            : []),
    ]

    // bare → the page owns the frame (PageHeader); dashboard cards keep the LabeledCard
    if (bare) {
        return (
            <div className={cn("flex flex-col gap-3", className)}>
                {contentItems.map((Item, index) => (
                    <Item key={index} />
                ))}
            </div>
        )
    }

    return (
        <LabeledCard
            identity={{ tier: "block", component: "LeaderboardListCard" }}
            // `title` is only ever omitted in `bare` mode, which already returned above —
            // the fallback here is a type-safety guard, not a real state either caller hits.
            label={title ?? ""}
            onSeeMore={onSeeMore}
            seeMoreLabel={seeMoreLabel}
        >
            <StackV
                gap={3}
                principle="sibling-stack"
                explain="Standing, optional podium, and cohort list are peer sections in one leaderboard — not block-boundary, because they stay inside one card group."
                items={contentItems}
            />
        </LabeledCard>
    )
}

"use client"

import React from "react"
import {
    Typography,
    cn,
} from "@heroui/react"
import {
    UserAvatar,
} from "@/components/blocks/identity/UserAvatar"
import {
    RankDeltaCaret,
} from "@/components/blocks/profile/RankDeltaCaret"
/** One podium finisher (top-3). */
export interface PodiumEntry {
    /** 1-based rank (1 · 2 · 3). */
    rank: number
    /** Display username (null → dash). */
    username: string | null
    /** Avatar URL (null → generated fallback). */
    avatar: string | null
    /** Pre-formatted points label (e.g. "1420 pts"). */
    pointsLabel: React.ReactNode
    /** True when this finisher is the viewer → ring-accent avatar + accent name + label. */
    isMe?: boolean
    /**
     * Rank movement vs last week (`>0` climbed, `<0` dropped, `0`/`null` unchanged) —
     * shown as a `▴▾N` caret ABOVE the avatar when there's real movement. Omit for a
     * board that has no weekly baseline (e.g. the all-time global tab).
     */
    rankDelta?: number | null
}

/** Props for the {@link Podium} block. */
export interface PodiumProps {
    /** Top finishers best→worst; at most 3 are shown. */
    entries: Array<PodiumEntry>
    /** Optional "you" label appended to the viewer's finisher (e.g. `t("...you")`). */
    meLabel?: React.ReactNode
}

/**
 * Top-3 leaderboard podium — the classic winners' dais (2nd · 1st · 3rd, the
 * champion centered and raised) that gives a global board its "who's winning"
 * moment. Presentational + props-only; the board owns the data. Accent lives
 * only on the champion's step (a single focal point, not a flood —
 * `accent-system`).
 *
 * @param props - {@link PodiumProps}
 */
export const Podium = ({
    entries,
    meLabel}: PodiumProps) => {
    const top = entries.slice(0, 3)
    // visual order: runner-up · champion · third — champion centered + raised
    const ordered = [top[1], top[0], top[2]].filter(Boolean) as Array<PodiumEntry>

    return (
        <div className={"flex items-end justify-center gap-3"}>
            {ordered.map((entry) => {
                const isChampion = entry.rank === 1
                return (
                    <div key={entry.rank} className="flex flex-col items-center gap-2">
                        {/* rank movement above the avatar — only when it actually moved */}
                        {entry.rankDelta ? (
                            <RankDeltaCaret delta={entry.rankDelta} />
                        ) : null}
                        <UserAvatar
                            // the viewer's own avatar is ringed (accent-system §3 "mine"
                            // = ring + value accent, NOT a filled step)
                            className={cn(
                                "shrink-0",
                                isChampion ? "size-14" : "size-12",
                                entry.isMe && "ring-2 ring-accent ring-offset-2 ring-offset-surface",
                            )}
                            username={entry.username ?? ""}
                            avatar={entry.avatar}
                            seed={entry.username ?? String(entry.rank)}
                        />
                        <div className="flex w-20 flex-col items-center">
                            <Typography
                                type="body-sm"
                                weight="medium"
                                truncate
                                className={cn("max-w-full", entry.isMe && "text-accent-soft-foreground")}
                            >
                                {entry.username ?? "—"}
                                {entry.isMe && meLabel ? <> · {meLabel}</> : null}
                            </Typography>
                            <Typography type="body-xs" color="muted">
                                {entry.pointsLabel}
                            </Typography>
                        </div>
                        {/* the dais step — champion raised, marked by a ring + accent
                            number (NOT an accent fill: accent-system §5 + the
                            LeaderboardPodium ruling — the winner's platform is not tinted) */}
                        <div
                            className={cn(
                                "flex w-20 items-center justify-center rounded-t-2xl font-bold",
                                isChampion
                                    ? "h-16 bg-surface text-accent ring-2 ring-inset ring-accent"
                                    : "h-10 bg-surface-secondary text-foreground",
                            )}
                        >
                            {entry.rank}
                        </div>
                    </div>
                )
            })}
        </div>
    )
}

