                </Typography>
                {meta ? (
                    <Typography type="body-sm" color="muted">
                        {meta}
                    </Typography>
                ) : null}
            </div>
        </div>

        {progress ? (
            /* canonical goal-gradient meter (ProgressMeter) — label above + accent fill */
            <ProgressMeter
                value={Math.min(1, Math.max(0, progress.ratio)) * 100}
                max={100}
                label={progress.label}
            />
