"use client"

import { UploadSimpleIcon as CloudArrowUpIcon } from "@phosphor-icons/react"
import React, { useCallback } from "react"
import { cn } from "@heroui/react"
import { useDropzone } from "react-dropzone"

/**
 * Props for Dropzone component.
 */
export interface DropzoneProps {
    /** Helper text shown below dropzone area. */
    hint: string
    /** Current selected file. */
    file: File | null
    /** Validation error text to render below hint. */
    errorMessage?: string
    /** Accepted mime types for uploaded file. */
    acceptedMimeTypes: Array<string>
    /** Maximum file size in bytes. */
    maxSizeInBytes: number
    /** Callback fired when file changes. */
    onChange: (file: File | null) => void
    /** Callback fired when dropzone loses focus. */
    onBlur?: () => void
}

/**
 * Dropzone file input with drag and drop interaction.
 * @param {DropzoneProps} props Dropzone display and validation props.
 */
export const Dropzone = ({
    hint,
    file,
    errorMessage,
    acceptedMimeTypes,
    maxSizeInBytes,
    onChange,
    onBlur}: DropzoneProps) => {
    const onDrop = useCallback((acceptedFiles: Array<File>) => {
        onChange(acceptedFiles[0] ?? null)
    }, [onChange])

    const { getRootProps, getInputProps, isDragActive } = useDropzone({
        onDrop,
        onFileDialogCancel: () => onBlur?.(),
        accept: acceptedMimeTypes.reduce<Record<string, Array<string>>>((result, type) => {
            result[type] = []
            return result
        }, {}),
        maxSize: maxSizeInBytes,
        multiple: false,
    })

    return (
        <div className={"flex flex-col gap-2"}>
            <div
                {...getRootProps()}
                className={cn(
                    "cursor-pointer rounded-large border border-dashed  bg-surface border-2 rounded-3xl p-2 transition-colors",
                    isDragActive ? "border-accent bg-accent-soft" : "",
                    errorMessage ? "border-danger" : "",
                )}
            >
                <input {...getInputProps({ onBlur })} />
                <div className="flex flex-col items-center gap-2 text-center">
                    <CloudArrowUpIcon className="size-6 text-muted" />
                    <div className="text-sm">
                        {file?.name ?? hint}
                    </div>
                </div>
            </div>
            {errorMessage ? (
                <div className="text-sm text-danger-soft-foreground">{errorMessage}</div>
            ) : null}
        </div>
    )
}

"use client"

import React from "react"
import { InputOTP, Label, Typography } from "@heroui/react"
/**
 * Props for the {@link OtpInput} block.
 *
 * A controlled one-time-code field (2FA / email verification) built on HeroUI
 * {@link InputOTP}. Tier-3 presentational — the value and every state arrive via
 * props; the block owns no state, store, or fetch.
 */
export interface OtpInputProps {
    /**
     * Number of code slots to render (also the `maxLength` of the underlying
     * input). Default `6` — the common 2FA / email-verification length.
     */
    length?: number
    /**
     * Current code value (controlled). A string of the digits entered so far;
     * its length must not exceed {@link length}.
     */
    value: string
    /**
     * Fires with the full string on every change. Wire it to the caller's state
     * setter — the block never mutates the value itself.
     */
    onChange: (value: string) => void
    /**
     * When `true`, paints the slots in the error style and reveals
     * {@link errorMessage} (if provided) below the field.
     */
    isInvalid?: boolean
    /**
     * Error line shown under the field while {@link isInvalid} is `true`. Prefer
     * a message that says how to fix it ("Code is incorrect, check your email again"),
     * not just "wrong". Rendered `body-xs` in the danger token.
     */
    errorMessage?: React.ReactNode
    /**
     * Auto-focuses the first slot on mount — handy when the field is the only
     * action on a verification screen. Default `false`.
     */
    autoFocus?: boolean
    /**
     * Optional label rendered above the slots (e.g. "Verification code"). Omit for a
     * bare field.
     */
    label?: React.ReactNode
}

/**
 * OtpInput is a controlled one-time-code field for 2FA and email verification,
 * built on HeroUI {@link InputOTP}. It renders {@link length} individual slots
 * (default `6`) driven by a single `value` string, an optional {@link label}
 * above, and an optional {@link errorMessage} below that only appears while
 * {@link isInvalid} is `true`.
 *
 * Tier-3 presentational block: props-only, no store, no SWR, no side-effects —
 * the caller threads `value`/`onChange` and every visual state.
 *
 * @param props - {@link OtpInputProps}
 *
 * @example
 * <OtpInput
 *   label="Verification code"
 *   value={code}
 *   onChange={setCode}
 *   isInvalid={hasError}
 *   errorMessage="Code is incorrect, check your email again."
 * />
 *
 * @see Story: .storybook/stories/blocks/form/OtpInput/OtpInput.stories
 */
export const OtpInput = ({
    length = 6,
    value,
    onChange,
    isInvalid,
    errorMessage,
    autoFocus,
    label}: OtpInputProps) => {
    return (
        <div className={"flex flex-col gap-2"}>
            {/* Optional field label above the slots */}
            {label != null ? <Label>{label}</Label> : null}

            {/* HeroUI InputOTP: `maxLength` = slot count; value/onChange are
                threaded straight through (controlled). One Slot per index. */}
            <InputOTP
                maxLength={length}
                value={value}
                onChange={onChange}
                isInvalid={isInvalid}
                autoFocus={autoFocus}
            >
                <InputOTP.Group>
                    {Array.from({ length }, (_, index) => (
                        <InputOTP.Slot key={index} index={index} />
                    ))}
                </InputOTP.Group>
            </InputOTP>

            {/* Error line — only while invalid, mirrors the TextField error slot */}
            {isInvalid && errorMessage != null ? (
                <Typography type="body-xs" className="text-danger-soft-foreground">
                    {errorMessage}
                </Typography>
            ) : null}
        </div>
    )
}

