import React from "react"
import { Button, Calendar, DateField, DatePicker, Label } from "@heroui/react"
import type { DateValue } from "@internationalized/date"

/** One selectable time slot in a {@link SchedulePicker}. */
export interface SchedulePickerSlot {
    /** Stable id — the select payload passed to `onSlotChange` and the React key. */
    id: string
    /** Human-readable label shown on the slot button (e.g. "09:00 - 10:00"). */
    label: string
    /** When true the slot is dimmed and cannot be chosen (e.g. already booked). */
    isDisabled?: boolean
}

/**
 * Props for the {@link SchedulePicker} block.
 *
 * Tier-3 presentational — controlled, props-only, no store/SWR/fetch. Both the
 * selected date and the selected slot are owned by the parent; every callback is
 * safe to leave as a no-op.
 */
export interface SchedulePickerProps {
    /**
     * The currently selected date, as an `@internationalized/date` value (the
     * REAL HeroUI `DatePicker` value type — a `CalendarDate`/`DateValue`, not a
     * native `Date`). `null` when nothing is picked yet.
     */
    dateValue: DateValue | null
    /**
     * Fired with the newly picked date (or `null` when cleared). The value is a
     * `DateValue`; call `.toString()` on it to persist an ISO `YYYY-MM-DD` string.
     */
    onDateChange: (value: DateValue | null) => void
    /**
     * The bookable time slots for the chosen date. Rendered as a single-select
     * grid of buttons; disabled slots are dimmed and non-interactive.
     */
    availableSlots: Array<SchedulePickerSlot>
    /** Id of the currently selected slot, or `undefined` when none is chosen. */
    selectedSlotId?: string
    /** Fired with the chosen slot id when a slot button is pressed. */
    onSlotChange: (id: string) => void
    /**
     * Optional lower bound — dates before this are dimmed and unselectable in the
     * calendar. Use it to forbid booking in the past (e.g. `today(getLocalTimeZone())`).
     */
    minDate?: DateValue
    /** Heading rendered above the time-slot grid. Defaults to "Choose a time slot". */
    slotsLabel?: string
}

/**
 * SchedulePicker pairs a HeroUI {@link DatePicker} (with an inline
 * {@link Calendar} popover — the real `DateField` + `Calendar` composition) with a
 * single-select grid of time-slot buttons. It is the booking control for a
 * mock-interview: pick the day, then pick a free slot on that day.
 *
 * The DATE half uses the canonical HeroUI date primitive as-is, so its value is a
 * genuine `@internationalized/date` `DateValue` (not a native `Date`). The richer,
 * bespoke half is the TIME-SLOT grid: each slot is a real HeroUI `<Button>` —
 * `secondary` when selected, hollow `ghost` otherwise (never `primary`, so a
 * selected slot never competes with the page's one accent CTA), disabled slots
 * dimmed via `isDisabled`. `role="group"` + `aria-pressed` per button make it a
 * proper single-select toggle group.
 *
 * Tier-3 presentational block: props-only, controlled, no store, no SWR, no
 * side-effects.
 *
 * @param props - {@link SchedulePickerProps}
 *
 * @example
 * <SchedulePicker
 *   dateValue={date}
 *   onDateChange={setDate}
 *   minDate={today(getLocalTimeZone())}
 *   availableSlots={[
 *     { id: "0900", label: "09:00 - 10:00" },
 *     { id: "1030", label: "10:30 - 11:30", isDisabled: true },
 *   ]}
 *   selectedSlotId={slotId}
 *   onSlotChange={setSlotId}
 * />
 *
 * @see Story: .storybook/stories/blocks/form/SchedulePicker/SchedulePicker.stories
 */
export const SchedulePicker = ({
    dateValue,
    onDateChange,
    availableSlots,
    selectedSlotId,
    onSlotChange,
    minDate,
    slotsLabel = "Choose a time slot"}: SchedulePickerProps) => {
    return (
        <div className={"flex flex-col gap-6"}>
            {/* DATE half — canonical HeroUI DatePicker + DateField + Calendar popover */}
            <DatePicker
                aria-label="Choose an interview date"
                minValue={minDate}
                value={dateValue}
                onChange={onDateChange}
            >
                <Label>Choose a date</Label>
                <DateField.Group fullWidth variant="secondary">
                    <DateField.Input>
                        {(segment) => <DateField.Segment segment={segment} />}
                    </DateField.Input>
                    <DateField.Suffix>
                        <DatePicker.Trigger>
                            <DatePicker.TriggerIndicator />
                        </DatePicker.Trigger>
                    </DateField.Suffix>
                </DateField.Group>
                <DatePicker.Popover>
                    <Calendar aria-label="Calendar for choosing an interview date">
                        <Calendar.Header>
                            <Calendar.YearPickerTrigger>
                                <Calendar.YearPickerTriggerHeading />
                                <Calendar.YearPickerTriggerIndicator />
                            </Calendar.YearPickerTrigger>
                            <Calendar.NavButton slot="previous" />
                            <Calendar.NavButton slot="next" />
                        </Calendar.Header>
                        <Calendar.Grid>
                            <Calendar.GridHeader>
                                {(day) => <Calendar.HeaderCell>{day}</Calendar.HeaderCell>}
                            </Calendar.GridHeader>
                            <Calendar.GridBody>
                                {(date) => <Calendar.Cell date={date} />}
                            </Calendar.GridBody>
                        </Calendar.Grid>
                        <Calendar.YearPickerGrid>
                            <Calendar.YearPickerGridBody>
                                {({ year }) => <Calendar.YearPickerCell year={year} />}
                            </Calendar.YearPickerGridBody>
                        </Calendar.YearPickerGrid>
                    </Calendar>
                </DatePicker.Popover>
            </DatePicker>

            {/* TIME-SLOT half — single-select grid of toggle buttons */}
            <div className="flex flex-col gap-2">
                <Label>{slotsLabel}</Label>
                <div
                    role="group"
                    aria-label={slotsLabel}
                    className="grid grid-cols-2 gap-2 @app-sm:grid-cols-3"
                >
                    {availableSlots.map((slot) => {
                        const selected = slot.id === selectedSlotId
                        return (
                            <Button
                                key={slot.id}
                                size="sm"
                                className="w-full justify-center"
                                variant={selected ? "secondary" : "ghost"}
                                isDisabled={slot.isDisabled}
                                aria-pressed={selected}
                                onPress={() => onSlotChange(slot.id)}
                            >
                                {slot.label}
                            </Button>
                        )
                    })}
                </div>
            </div>
        </div>
    )
}

"use client"

import { MagnifyingGlassIcon } from "@phosphor-icons/react"
import React from "react"
import { ComboBox, Input, ListBox, ListBoxItem, Spinner, Typography } from "@heroui/react"
/** One suggestion row in a {@link SearchAutocomplete} dropdown. */
export interface SearchAutocompleteItem {
    /** Stable id — the select payload passed to `onSelect` and the React key. */
    id: string
    /** Primary label shown on the suggestion row (e.g. a course or tag name). */
    label: string
    /** Optional secondary line, rendered small and muted below the label. */
    description?: string
}

/**
 * Props for the {@link SearchAutocomplete} block.
 *
 * Tier-3 presentational — controlled, props-only, no store/SWR/fetch. The parent
 * owns both the typed query and the suggestion list (e.g. an Elasticsearch-backed
 * query), so this block stays generic. Every callback is safe as a no-op.
 */
export interface SearchAutocompleteProps {
    /**
     * The suggestions to render in the dropdown. The parent is responsible for
     * filtering/fetching them from the query — this block does NOT filter locally.
     */
    items: Array<SearchAutocompleteItem>
    /** Current text in the search field (controlled). */
    inputValue: string
    /** Fired with the new query on every keystroke. */
    onInputChange: (value: string) => void
    /** Fired with the chosen suggestion's id when a row is selected. */
    onSelect: (id: string) => void
    /** Placeholder for the empty field. Defaults to "Search courses, topics...". */
    placeholder?: string
    /**
     * When true, a spinner replaces the suggestion list — use it while the parent
     * is fetching results for the current query.
     */
    isLoading?: boolean
    /** Message shown when there are no suggestions. Defaults to "No suggestions". */
    emptyLabel?: string
}

/**
 * SearchAutocomplete is a suggest-as-you-type search field built on the canonical
 * HeroUI {@link ComboBox} (its real free-text anatomy: `ComboBox.InputGroup` with
 * a HeroUI {@link Input}, plus a `ComboBox.Popover` wrapping a {@link ListBox} of
 * {@link ListBoxItem} rows). The ComboBox is driven in controlled mode via
 * `inputValue`/`onInputChange` and reports the picked row through
 * `onSelectionChange`; filtering is delegated to the parent (`items` are rendered
 * as-is), keeping this reusable for any data source.
 *
 * Each row shows the item `label` and, when present, a muted `description` line.
 * The dropdown stays open on an empty collection (`allowsEmptyCollection`) so the
 * loading spinner and the empty message are visible — both rendered through the
 * ListBox `renderEmptyState` slot.
 *
 * Tier-3 presentational block: props-only, controlled, no store, no SWR, no
 * side-effects.
 *
 * @param props - {@link SearchAutocompleteProps}
 *
 * @example
 * <SearchAutocomplete
 *   items={suggestions}
 *   inputValue={query}
 *   onInputChange={setQuery}
 *   onSelect={(id) => router.push(`/courses/${id}`)}
 *   isLoading={isFetching}
 * />
 *
 * @see Story: .storybook/stories/blocks/form/SearchAutocomplete/SearchAutocomplete.stories
 */
export const SearchAutocomplete = ({
    items,
    inputValue,
    onInputChange,
    onSelect,
    placeholder = "Search courses, topics...",
    isLoading = false,
    emptyLabel = "No suggestions"}: SearchAutocompleteProps) => {
    // ComboBox reports the picked key; forward its id to the parent (ignore null,
    // which fires when the selection is cleared).
    const onSelectionChange = (key: React.Key | null) => {
        if (key !== null) {
            onSelect(String(key))
        }
    }

    return (
        <ComboBox
            aria-label={placeholder}
            className={"w-full @app-sm:max-w-sm"}
            variant="secondary"
            allowsEmptyCollection
            items={items}
            inputValue={inputValue}
            onInputChange={onInputChange}
            onSelectionChange={onSelectionChange}
        >
            <ComboBox.InputGroup className="relative">
                <Input
                    type="search"
                    placeholder={placeholder}
                    // leading icon rides in the padding; the RAC Input owns the value
                    className="pl-9"
                />
                <MagnifyingGlassIcon className="text-muted pointer-events-none absolute left-3 top-1/2 size-5 -translate-y-1/2" />
            </ComboBox.InputGroup>
            <ComboBox.Popover>
                <ListBox
                    // empty the collection while loading so `renderEmptyState` shows
                    // the spinner instead of a stale list
                    items={isLoading ? [] : items}
                    className="max-h-72 overflow-auto p-1"
                    renderEmptyState={() =>
                        isLoading ? (
                            <div className="flex items-center justify-center gap-2 px-3 py-6">
                                <Spinner size="sm" />
                                <Typography type="body-sm" color="muted">
                                    Searching...
                                </Typography>
                            </div>
                        ) : (
                            <div className="px-3 py-6 text-center">
                                <Typography type="body-sm" color="muted">
                                    {emptyLabel}
                                </Typography>
                            </div>
                        )
                    }
                >
                    {(item: SearchAutocompleteItem) => (
                        <ListBoxItem
                            id={item.id}
                            textValue={item.label}
                            className="flex flex-col items-start"
                        >
                            <Typography type="body-sm">{item.label}</Typography>
                            {item.description ? (
                                <Typography type="body-xs" color="muted">
                                    {item.description}
                                </Typography>
                            ) : null}
                        </ListBoxItem>
                    )}
                </ListBox>
            </ComboBox.Popover>
        </ComboBox>
    )
}

import { MagnifyingGlassIcon } from "@phosphor-icons/react"
import React, {
    useCallback,
    useEffect,
    useMemo,
    useRef,
    useState,
    type ComponentProps,
} from "react"
import { Input, TextField, cn } from "@heroui/react"
import { AnimatePresence, motion } from "framer-motion"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** One autocomplete suggestion shown in the dropdown. */
export interface SearchInputSuggestion {
    /** Stable id (used as the list key + select payload). */
    id: string
    /** Human-readable label shown in the dropdown row. */
    label: string
}

/** HeroUI {@link Input} surface variant accepted by {@link _SearchInput}. */
type SearchInputVariant = NonNullable<ComponentProps<typeof Input>["variant"]>

/** Props for {@link _SearchInput} — presentational; the fallback placeholder already resolved. */
export interface SearchInputProps extends WithClassNames<undefined> {
    /** Current search query (controlled). */
    value: string
    /** Fired with the new query on every keystroke. */
    onValueChange: (value: string) => void
    /** Placeholder text; already resolved (caller's override, or the generic fallback). */
    placeholder: string
    /** HeroUI input surface variant; `secondary` uses a muted field background. */
    variant?: SearchInputVariant
    /**
     * Optional typeahead suggestions. When provided together with
     * {@link SearchInputProps.onSelectSuggestion}, a HeroUI-style listbox dropdown
     * renders under the field while it is focused and the query is non-empty. The
     * parent owns the data source, so this component stays generic and reusable.
     */
    suggestions?: Array<SearchInputSuggestion>
    /** Fired with the chosen suggestion; enables the dropdown when set. */
    onSelectSuggestion?: (suggestion: SearchInputSuggestion) => void
}

/**
 * Generic, reusable search input with an optional autocomplete dropdown.
 *
 * Presentational + controlled: the parent owns the value and (optionally) the
 * suggestion list. With suggestions + {@link SearchInputProps.onSelectSuggestion}
 * it behaves as a typeahead — a HeroUI-grade animated listbox with full keyboard
 * navigation (↑/↓ to move, Enter to choose, Esc to dismiss). Without them it is a
 * plain search field. Debouncing is the caller's concern, keeping this reusable.
 * @see Story: .storybook/stories/blocks/form/SearchInput/SearchInput.stories
 */
export const _SearchInput = ({
    value,
    onValueChange,
    placeholder,
    className,
    variant,
    suggestions,
    onSelectSuggestion,
}: SearchInputProps) => {
    // track focus so the dropdown only shows while the field is active
    const [focused, setFocused] = useState(false)
    // index of the keyboard-highlighted row (-1 = none highlighted yet)
    const [activeIndex, setActiveIndex] = useState(-1)

    // the dropdown is only available when the caller opted into suggestions
    const hasSuggestions = typeof onSelectSuggestion === "function"
    const items = suggestions ?? []
    const open = hasSuggestions
        && focused
        && value.trim().length > 0
        && items.length > 0

    // reset the keyboard highlight whenever the dropdown closes or the list changes,
    // so a fresh open always starts with nothing pre-selected (Google/HeroUI behavior)
    useEffect(() => {
        setActiveIndex(-1)
    }, [open, items.length, value])

    // commit a suggestion + drop the keyboard highlight
    const selectAt = useCallback(
        (index: number) => {
            const suggestion = items[index]
            if (suggestion && onSelectSuggestion) {
                onSelectSuggestion(suggestion)
                setActiveIndex(-1)
            }
        },
        [items, onSelectSuggestion],
    )

    // arrow keys move the highlight; Enter chooses it; Escape dismisses the list
    const onKeyDown = useCallback(
        (event: React.KeyboardEvent<HTMLInputElement>) => {
            if (!open) {
                return
            }
            switch (event.key) {
            case "ArrowDown":
                // move down, wrapping back to the top past the last row
                event.preventDefault()
                setActiveIndex((prev) => (prev + 1) % items.length)
                break
            case "ArrowUp":
                // move up, wrapping to the bottom before the first row
                event.preventDefault()
                setActiveIndex((prev) => (prev <= 0 ? items.length - 1 : prev - 1))
                break
            case "Enter":
                // only intercept Enter when a row is highlighted, else let the form submit/search run
                if (activeIndex >= 0) {
                    event.preventDefault()
                    selectAt(activeIndex)
                }
                break
            case "Escape":
                // close the dropdown without losing what was typed
                event.preventDefault()
                setFocused(false)
                break
            default:
                break
            }
        },
        [open, items.length, activeIndex, selectAt],
    )

    return (
        <div className={cn("relative w-full @app-sm:max-w-sm", className)}>
            <TextField aria-label={placeholder} className="w-full">
                <div className="relative">
                    <MagnifyingGlassIcon className="text-muted pointer-events-none absolute left-3 top-1/2 h-5 w-5 -translate-y-1/2" />
                    <Input
                        type="search"
                        variant={variant}
                        placeholder={placeholder}
                        className="pl-9 w-full"
                        value={value}
                        onChange={(event) => onValueChange(event.target.value)}
                        onFocus={() => setFocused(true)}
                        onBlur={() => setFocused(false)}
                        onKeyDown={onKeyDown}
                    />
                </div>
            </TextField>
            <AnimatePresence>
                {open ? (
                    <motion.ul
                        className="bg-surface border-divider/60 absolute z-30 mt-2 max-h-72 w-full overflow-y-auto rounded-2xl border p-2 shadow-xl"
                        initial={{ opacity: 0, y: -6, scale: 0.98 }}
                        animate={{ opacity: 1, y: 0, scale: 1 }}
                        exit={{ opacity: 0, y: -6, scale: 0.98 }}
                        transition={{ duration: 0.14, ease: "easeOut" }}
                    >
                        {items.map((suggestion, index) => (
                            <SearchInputSuggestionRow
                                key={suggestion.id}
                                suggestion={suggestion}
                                query={value}
                                active={index === activeIndex}
                                onHover={() => setActiveIndex(index)}
                                onSelect={() => selectAt(index)}
                            />
                        ))}
                    </motion.ul>
                ) : null}
            </AnimatePresence>
        </div>
    )
}

/** Props for {@link SearchInputSuggestionRow}. */
interface SearchInputSuggestionRowProps {
    /** The suggestion this row represents. */
    suggestion: SearchInputSuggestion
    /** The current query, used to bold the matching part. */
    query: string
    /** Whether this row is the keyboard-highlighted one. */
    active: boolean
    /** Fired when the pointer enters the row (syncs the keyboard highlight). */
    onHover: () => void
    /** Fired with this suggestion when the row is chosen. */
    onSelect: () => void
}

/**
 * One dropdown row, styled as a HeroUI listbox item (rounded, hover/active fill).
 * Uses `onMouseDown` (which fires before the input's `blur`) so the selection is
 * registered before the dropdown closes.
 *
 * @param props - {@link SearchInputSuggestionRowProps}
 */
const SearchInputSuggestionRow = ({
    suggestion,
    query,
    active,
    onHover,
    onSelect,
}: SearchInputSuggestionRowProps) => {
    const rowRef = useRef<HTMLButtonElement>(null)

    // keep the keyboard-highlighted row scrolled into view as it moves
    useEffect(() => {
        if (active) {
            rowRef.current?.scrollIntoView({ block: "nearest" })
        }
    }, [active])

    // split the label around the (case-insensitive) typed text to bold the match
    const segments = useMemo(() => {
        const normalized = query.trim().toLowerCase()
        const index = normalized.length > 0
            ? suggestion.label.toLowerCase().indexOf(normalized)
            : -1
        if (index < 0) {
            return {
                before: suggestion.label,
                match: "",
                after: "",
            }
        }
        return {
            before: suggestion.label.slice(0, index),
            match: suggestion.label.slice(index, index + normalized.length),
            after: suggestion.label.slice(index + normalized.length),
        }
    }, [suggestion.label, query])

    // mousedown (not click) so it runs before the input blur closes the dropdown
    const onMouseDown = useCallback(
        (event: React.MouseEvent) => {
            event.preventDefault()
            onSelect()
        },
        [onSelect],
    )

    return (
        <li>
            <button
                ref={rowRef}
                type="button"
                className={cn(
                    "flex w-full items-center gap-2 rounded-xl px-3 py-2 text-left text-sm transition-colors",
                    active ? "bg-accent-soft" : "hover:bg-accent-soft",
                )}
                onMouseDown={onMouseDown}
                onMouseEnter={onHover}
            >
                <MagnifyingGlassIcon className="text-muted h-5 w-5 shrink-0" />
                <span className="min-w-0 flex-1 truncate">
                    <span className="font-semibold">{segments.before}</span>
                    <span className="text-muted font-normal">{segments.match}</span>
                    <span className="font-semibold">{segments.after}</span>
                </span>
            </button>
        </li>
    )
}

"use client"

import React from "react"
import { Typography, cn } from "@heroui/react"

/** The kind of a diff line: an addition, a deletion, or unchanged context. */
export type DiffLineType = "add" | "del" | "ctx"

/** One pre-parsed line of a diff. The caller does the diffing; this block only renders. */
export interface DiffLine {
    /** Whether the line was added, removed, or is unchanged context. */
    type: DiffLineType
    /** The raw text content of the line (without the leading +/-/space marker). */
    content: string
    /** Line number in the OLD file. Omit for pure additions. */
    oldNumber?: number
    /** Line number in the NEW file. Omit for pure deletions. */
    newNumber?: number
}

/** A contiguous group of diff lines, optionally introduced by a hunk header. */
export interface DiffHunk {
    /** Optional hunk header (e.g. "@@ -1,4 +1,5 @@" or a section label). */
    header?: string
    /** The pre-parsed lines that make up this hunk. */
    lines: DiffLine[]
}

/** How the diff is laid out. */
export type DiffViewerVariant = "unified" | "split"

/**
 * Props for the {@link DiffViewer} block.
 *
 * Tier-3 presentational: props-only, no store/SWR/fetch, and no diff ALGORITHM —
 * the caller supplies already-parsed hunks. Used for grading feedback that
 * compares student code against a suggested fix.
 */
export interface DiffViewerProps {
    /** Optional filename shown in the header bar above the diff (e.g. "src/auth.ts"). */
    filename?: string
    /** The pre-parsed hunks to render, in order. */
    hunks: DiffHunk[]
    /**
     * Layout variant. `"unified"` (default) stacks all lines in a single column;
     * `"split"` places the old file on the left and the new file on the right.
     */
    variant?: DiffViewerVariant
}

/** type → row background + text color classes (tokens only). */
const LINE_TONE: Record<DiffLineType, string> = {
    add: "bg-success-soft text-success-soft-foreground",
    del: "bg-danger-soft text-danger-soft-foreground",
    ctx: "text-foreground",
}

/** type → the leading marker glyph in the unified gutter. */
const LINE_MARKER: Record<DiffLineType, string> = {
    add: "+",
    del: "-",
    ctx: " ",
}

/** Props for {@link NumberCell}. */
interface NumberCellProps {
    /** Line number to show; omit / undefined renders an empty gutter cell. */
    value?: number
}

/** A monospace line-number cell in the gutter (right-aligned, non-selectable). */
const NumberCell = ({ value }: NumberCellProps) => (
    <span className="w-10 shrink-0 select-none pr-2 text-right tabular-nums text-muted-foreground">
        {value ?? ""}
    </span>
)

/** Props for {@link UnifiedRow}. */
interface UnifiedRowProps {
    /** Pre-parsed diff line to render. */
    line: DiffLine
}

/** One rendered line in the UNIFIED layout: [old #][new #][marker][content]. */
const UnifiedRow = ({ line }: UnifiedRowProps) => (
    <div className={cn("flex items-start", LINE_TONE[line.type])}>
        <NumberCell value={line.oldNumber} />
        <NumberCell value={line.newNumber} />
        <span className="w-4 shrink-0 select-none text-center">
            {LINE_MARKER[line.type]}
        </span>
        <span className="whitespace-pre pr-4">{line.content}</span>
    </div>
)

/** Props for {@link SplitCell}. */
interface SplitCellProps {
    /** Line for this side, or `null` for a blank filler cell. */
    line: DiffLine | null
    /** Which file side this cell represents. */
    side: "old" | "new"
}

/** One side of the SPLIT layout: a single line number + content, or a blank filler row. */
const SplitCell = ({ line, side }: SplitCellProps) => (
    <div
        className={cn(
            "flex items-start",
            // A filler cell (no line on this side) stays neutral; a real line gets its tone.
            line ? LINE_TONE[line.type] : "text-foreground",
        )}
    >
        <NumberCell value={side === "old" ? line?.oldNumber : line?.newNumber} />
        <span className="whitespace-pre pr-4">{line ? line.content : ""}</span>
    </div>
)

/**
 * DiffViewer renders a code diff for grading feedback — student code versus a
 * suggested fix. It accepts PRE-PARSED hunks (no diff algorithm lives here) and
 * shows a filename header bar, a line-number gutter, and token-colored line
 * backgrounds: additions use `bg-success-soft`, deletions `bg-danger-soft`, and
 * context stays neutral. Long lines never break the page — the code area scrolls
 * horizontally inside its own `overflow-x-auto` container.
 *
 * `variant="unified"` (default) stacks every line in one column with +/-/space
 * markers. `variant="split"` places the old file on the left and the new file on
 * the right; each source line lands on its own side while context appears on both.
 *
 * Tier-3 presentational block: props-only, no store, no SWR, no side-effects.
 *
 * @param props - {@link DiffViewerProps}
 *
 * @example
 * <DiffViewer
 *     filename="src/auth.ts"
 *     hunks={[{ header: "@@ -1,3 +1,4 @@", lines: [
 *         { type: "ctx", content: "function login() {", oldNumber: 1, newNumber: 1 },
 *         { type: "del", content: "  return true", oldNumber: 2 },
 *         { type: "add", content: "  return verify(token)", newNumber: 2 },
 *     ] }]}
 * />
 * @see Story: .storybook/stories/blocks/grading/DiffViewer/DiffViewer.stories
 */
export const DiffViewer = ({
    filename,
    hunks,
    variant = "unified"}: DiffViewerProps) => {
    return (
        <div
            className={cn(
                "overflow-hidden rounded-xl border border-default bg-surface")}
        >
            {/* Filename header bar — sits above the scrollable code area */}
            {filename ? (
                <div className="border-b border-default bg-default px-4 py-2">
                    <Typography type="body-sm" weight="medium" className="font-mono">
                        {filename}
                    </Typography>
                </div>
            ) : null}

            {/* Horizontal-scroll container so long lines never break the page */}
            <div className="overflow-x-auto">
                <div className="min-w-fit py-1 font-mono text-xs leading-relaxed">
                    {hunks.map((hunk, hunkIndex) => (
                        <div key={hunkIndex}>
                            {/* Optional hunk header — muted separator row */}
                            {hunk.header ? (
                                <div className="whitespace-pre bg-default px-4 py-1 text-muted-foreground">
                                    {hunk.header}
                                </div>
                            ) : null}

                            {variant === "split"
                                ? hunk.lines.map((line, lineIndex) => (
                                    <div
                                        key={lineIndex}
                                        className="grid grid-cols-2 divide-x divide-default"
                                    >
                                        {/* Old side hides pure additions; new side hides pure deletions */}
                                        <SplitCell
                                            line={line.type === "add" ? null : line}
                                            side="old"
                                        />
                                        <SplitCell
                                            line={line.type === "del" ? null : line}
                                            side="new"
                                        />
                                    </div>
                                ))
                                : hunk.lines.map((line, lineIndex) => (
                                    <UnifiedRow key={lineIndex} line={line} />
                                ))}
                        </div>
                    ))}
                </div>
            </div>
        </div>
    )
}

import { CaretDownIcon, LockIcon, SparkleIcon, WarningCircleIcon, WarningIcon } from "@phosphor-icons/react"
import React, { useMemo, useState } from "react"
import {
