        </Chip>
    )

    if (!ok && errorMessage) {
        return (
            <Tooltip>
                <Tooltip.Trigger className="shrink-0 cursor-default">
                    {chip}
                </Tooltip.Trigger>
                <Tooltip.Content>{errorMessage}</Tooltip.Content>
            </Tooltip>
        )
    }

    return <span className="shrink-0">{chip}</span>
}

/**
 * A model served by the `local` provider runs on StarCi GPU hardware by
 * definition, so the provider alone decides the mark.
 */
const showSelfHostMark = (model: AiGradableModel) =>
    model.provider === ModelProvider.Local

/** Dropdown row width — popover must be bounded or `truncate` never fires. */
const DROPDOWN_POPOVER_CLASS = "w-80 max-w-[calc(100vw-2rem)]"
const DROPDOWN_ITEM_ROW_CLASS = "w-full min-w-0 overflow-hidden"

/**
 * HeroUI's `Select.Indicator` chevron, replicated 1:1 (same 16×16 viewBox + path)
 * so the `isDropdown` trigger's caret is IDENTICAL to the Select dropdowns beside
 * it — `IconChevronDown` is a HeroUI internal, not exported, so we inline its SVG.
 */
const FieldChevronDown = () => (
    <svg aria-hidden="true" fill="none" viewBox="0 0 16 16" className="size-4">
        <path
            clipRule="evenodd"
            fillRule="evenodd"
            fill="currentColor"
            d="M2.97 5.47a.75.75 0 0 1 1.06 0L8 9.44l3.97-3.97a.75.75 0 1 1 1.06 1.06l-4.5 4.5a.75.75 0 0 1-1.06 0l-4.5-4.5a.75.75 0 0 1 0-1.06"
        />
    </svg>
)
const MODEL_ROW_TRIGGER_CLASS = "block w-full min-w-0"

/** Props for {@link ModelRowLayout}. */
interface ModelRowLayoutProps {
    leading?: React.ReactNode
    name: string
    nameSuffix?: React.ReactNode
    isSelected?: boolean
    muted?: boolean
    trailing: React.ReactNode
}

/** Model row — name truncates on the left, chips stay pinned on the right. */
const ModelRowLayout = ({
    leading,
    name,
    nameSuffix,
    isSelected,
    muted,
    trailing,
}: ModelRowLayoutProps) => (
    <div
        className={cn(
            "grid w-full grid-cols-[minmax(0,1fr)_auto] items-center gap-2",
            muted && "text-muted",
        )}
    >
        <span className="flex min-w-0 items-center gap-2 overflow-hidden">
            {leading}
            <span
                className={cn("min-w-0 truncate", isSelected && "text-accent-soft-foreground")}
                title={name}
            >
                {name}
            </span>
            {nameSuffix}
        </span>
        <span className="flex shrink-0 items-center justify-end gap-2">{trailing}</span>
    </div>
)

/** Props for {@link GradeModelDropdown}. */
export type GradeModelDropdownProps = WithClassNames<undefined> & {
    /** Enabled models the user can pick from (from the `aiModels` catalog). */
    models: Array<AiGradableModel>
    /** The current lane + model selection. */
    selection: GradeModelSelection
    /** Whether higher-tier models are unlocked for this user (paid OR enrolled). */
    canPremium: boolean
    /** Disables the whole control (e.g. while a grade is in flight). */
    isDisabled?: boolean
    /** Show the "Auto" lane entry on top. Default true. */
    showAutoLane?: boolean
    /** Recommended minimum category. Any model BELOW it is flagged WARNING. */
    floor?: AiModelCategory
    /** Only show models suited for this task (chatting / grading). */
    task?: AiModelTask
    /** Popover placement. Default "bottom start"; pass "top start" for a bottom-anchored composer. */
    placement?: "bottom start" | "top start"
    /** Render the trigger as a standard bordered field-style dropdown button. */
    isDropdown?: boolean
    /** Render the trigger as a real `Button` (`variant="tertiary"`). */
    isButton?: boolean
    /** `isButton` only — stretch the trigger `Button` to the full width of its container. */
    isButtonFullWidth?: boolean
    /** Fired with the new selection when the user picks an option. */
    onSelect: (selection: GradeModelSelection) => void
    /** Fired when a locked (unlock-required) model is pressed — route to plans. */
    onUpgrade: () => void
    /** Live per-model health (dot + latency chip on each row); empty until the BE ships it. */
    latency: Map<string, ModelHealth>
    /** Already-localized "Auto" lane title (used as both the entry label and the fallback trigger label). */
    autoLaneLabel: string
    /** Already-localized "pick a model" trigger fallback (Auto lane hidden, nothing picked yet). */
    pickModelLabel: string
    /** Already-localized model-search field placeholder/aria-label. */
    searchModelLabel: string
    /** Already-localized "no models match" empty-search row label. */
    searchModelEmptyLabel: string
    /** Already-localized tier-filter aria-label. */
    filterTierLabel: string
    /** Already-localized "All" tier-filter option label. */
    filterAllLabel: string
    /** Already-localized tier label per category (for the inline tier filter + tooltips). */
    tierLabels: Record<AiModelCategory, string>
    /** Already-localized "model unavailable" tooltip text. */
    modelUnavailableLabel: string
    /** Already-localized "subscribe to unlock" tooltip text. */
    subscribeToGradeLabel: string
    /** Already-localized below-floor warning tooltip text. */
    belowFloorWarningLabel: string
    /** Already-localized off-task warning tooltip text. */
    offTaskWarningLabel: string
    /** Already-localized "hide hidden models" toggle label. */
    hideHiddenModelsLabel: string
    /** Already-localized, count-bound "show N hidden models" toggle label. */
    showHiddenModelsLabel: (count: number) => string
    /** Already-localized, ms-bound live-latency chip label. */
    latencyLabel: (ms: number) => string
    /** Already-localized "down" health-chip label. */
    downLabel: string
}

/**
 * Shared lane + model picker (grading, AI lab, any model-select surface).
 *
 * Renders the "Auto" lane plus every catalog model (tagged with its cost
 * category chip). Per model:
 * - no working key → DISABLED (warning, not selectable).
 * - Balanced / Premium / Frontier without an unlock → LOCKED (routes to plans).
 * - below the `floor` → SELECTABLE but flagged WARNING (may be inaccurate).
 * - otherwise → normal selectable.
 *
 * @param props - {@link GradeModelDropdownProps}
 */
export const _GradeModelDropdown = ({
    models,
    selection,
    canPremium,
    isDisabled = false,
    showAutoLane = true,
    floor,
    task,
    placement = "bottom start",
    isDropdown,
    isButton = false,
    isButtonFullWidth = false,
    onSelect,
    onUpgrade,
    latency,
    autoLaneLabel,
    pickModelLabel,
    searchModelLabel,
    searchModelEmptyLabel,
    filterTierLabel,
    filterAllLabel,
    tierLabels,
    modelUnavailableLabel,
    subscribeToGradeLabel,
    belowFloorWarningLabel,
    offTaskWarningLabel,
    hideHiddenModelsLabel,
    showHiddenModelsLabel,
    latencyLabel,
    downLabel,
    className,
}: GradeModelDropdownProps) => {
    // controlled open so selecting Auto can close the popover on press.
    const [isOpen, setIsOpen] = useState(false)
    const [query, setQuery] = useState("")
    const normalizedQuery = query.trim().toLowerCase()
    // single inline facet: tier.
    const [tierFilter, setTierFilter] = useState<AiModelCategory | "all">("all")
    // down (unavailable) + off-task models are HIDDEN by default; `showHidden` reveals them.
    const [showHidden, setShowHidden] = useState(false)
    const { visibleModels, hiddenCount } = useMemo(() => {
        const visible: Array<AiGradableModel> = []
        let hidden = 0
        for (const model of models) {
            if (normalizedQuery
                && !model.model.toLowerCase().includes(normalizedQuery)) {
                continue
            }
            if (tierFilter !== "all" && model.category !== tierFilter) {
                continue
            }
            const offTask = Boolean(task
                && model.supportedTasks?.length
                && !model.supportedTasks.includes(task))
            if (!model.available || offTask) {
                hidden += 1
                if (!showHidden) {
                    continue
                }
            }
            visible.push(model)
        }
        return { visibleModels: visible, hiddenCount: hidden }
    }, [models, normalizedQuery, tierFilter, task, showHidden])
    // tiers present in the catalog → the inline tier filter only offers real buckets.
    const tierChips = useMemo(() => {
        const present = new Set(models.map((model) => model.category))
        return TIER_FILTERS.filter((tier) => tier === "all" || present.has(tier))
    }, [models])
    // a pinned model shows its name; otherwise the Auto label (or "pick a model"
    // when the Auto lane is hidden and nothing is picked yet)
    const triggerLabel = selection.model
        ?? (showAutoLane ? autoLaneLabel : pickModelLabel)

    return (
        <Dropdown
            isOpen={isOpen}
            onOpenChange={(open) => {
                setIsOpen(open)
                if (!open) {
                    setQuery("")
                    setTierFilter("all")
                    setShowHidden(false)
                }
            }}
        >
            {isButton ? (
                <DropdownTrigger
                    isDisabled={isDisabled}
                    className={cn("cursor-pointer", isButtonFullWidth && "block w-full", className)}
                >
                    <Button variant="tertiary" size="sm" fullWidth={isButtonFullWidth}>
                        <SparkleIcon aria-hidden className="size-4 shrink-0" />
                        <span className={cn("truncate", isButtonFullWidth ? "min-w-0 flex-1 text-left" : "max-w-40")}>
                            {triggerLabel}
                        </span>
                    </Button>
                </DropdownTrigger>
            ) : isDropdown ? (
                <DropdownTrigger
                    isDisabled={isDisabled}
                    className={cn(
                        "relative flex! min-h-9 w-full cursor-pointer items-center rounded-field border border-[color:var(--field-border)] bg-field py-2 pe-7 ps-3 text-sm text-field-foreground shadow-field transform-none!",
                        "hover:bg-field-hover hover:border-[color:var(--field-border-hover)]",
                        "data-[hovered=true]:bg-field-hover data-[hovered=true]:border-[color:var(--field-border-hover)]",
                        "data-[focus-visible=true]:border-[color:var(--field-border-focus)]",
                        className,
                    )}
                >
                    <span className="flex min-w-0 items-center gap-2 overflow-hidden">
                        <SparkleIcon className="size-4 shrink-0" />
                        <span className="truncate">{triggerLabel}</span>
                    </span>
                    <span
                        className={cn(
                            "absolute inset-y-0 end-2 my-auto flex shrink-0 items-center justify-center text-field-placeholder transition duration-150",
                            isOpen && "rotate-180",
                        )}
                    >
                        <FieldChevronDown />
                    </span>
                </DropdownTrigger>
            ) : (
                <DropdownTrigger
                    isDisabled={isDisabled}
                    className={cn("min-w-0 max-w-full cursor-pointer", className)}
                >
                    <div className="flex w-full min-w-0 items-center justify-between gap-2">
                        <span className="flex min-w-0 items-center gap-2 overflow-hidden">
                            <SparkleIcon className="size-4 shrink-0" />
                            <span className="truncate">{triggerLabel}</span>
                        </span>
                        <CaretDownIcon weight="bold" className="size-4 shrink-0" />
                    </div>
                </DropdownTrigger>
            )}
            <DropdownPopover
                placement={placement}
                className={DROPDOWN_POPOVER_CLASS}
            >
                <div className="flex w-full min-w-0 flex-col">
                    {/* Auto lane — above search + scroll so the default is always one click away. */}
                    {showAutoLane ? (
                        <>
                            <DropdownMenu aria-label={autoLaneLabel}>
                                <DropdownSection>
                                    <DropdownItem
                                        key="auto"
                                        textValue={autoLaneLabel}
                                        onPress={() => {
                                            onSelect({
                                                model: null,
                                                provider: null,
                                            })
                                            setIsOpen(false)
                                        }}
                                    >
                                        <div
                                            className={cn(
                                                "flex items-center gap-2",
                                                !selection.model && "text-accent-soft-foreground",
                                            )}
                                        >
                                            <SparkleIcon className="size-4 shrink-0" />
                                            <span>{autoLaneLabel}</span>
                                        </div>
                                    </DropdownItem>
                                </DropdownSection>
                                <Separator />
                            </DropdownMenu>
                        </>
                    ) : null}
                    {/* Search → inline tier filter → list, separated by whitespace only
                    (no divider, no funnel panel). down + off-task hidden by default. */}
                    <div
                        className="px-2"
                        onKeyDownCapture={(event) => event.stopPropagation()}
                    >
                        <SearchField
                            variant="secondary"
                            aria-label={searchModelLabel}
                        >
                            <SearchField.Group>
                                <SearchField.SearchIcon />
                                <SearchField.Input
                                    placeholder={searchModelLabel}
                                    value={query}
                                    onChange={(event) => setQuery(event.target.value)}
                                />
                                {query ? (
                                    <SearchField.ClearButton onPress={() => setQuery("")} />
                                ) : null}
                            </SearchField.Group>
                        </SearchField>
                    </div>
                    {/* tier filter — FlexWrapButtonRadio inside popover surface */}
                    {tierChips.length > 1 ? (
                        <div className="px-2 pt-2">
                            <FlexWrapButtonRadio
                                ariaLabel={filterTierLabel}
                                value={tierFilter}
                                onChange={setTierFilter}
                                items={tierChips.map((tier) => ({
                                    value: tier,
                                    content: tier === "all"
                                        ? filterAllLabel
                                        : tierLabels[tier],
                                }))}
                            />
                        </div>
                    ) : null}
                    <ScrollShadow
                        hideScrollBar
                        className="max-h-72 w-full min-w-0"
                    >
                        <DropdownMenu
                            aria-label={pickModelLabel}
                            className="w-full min-w-0"
                        >
                            {/* One entry per catalog model. Below-floor = warning (selectable,
                        risky); Balanced/Premium/Frontier = locked without an unlock. */}
                            <DropdownSection>
                                {visibleModels.length === 0 ? (
                                    <DropdownItem
                                        key="no-results"
                                        textValue={searchModelEmptyLabel}
                                        onPress={() => undefined}
                                    >
                                        <span className="text-muted">{searchModelEmptyLabel}</span>
                                    </DropdownItem>
                                ) : null}
                                {visibleModels.map((model) => {
                                    const key = `${model.provider}:${model.model}`
                                    const isSelected = selection.model === model.model
                                        && selection.provider === model.provider
                                    const categoryChip = <AiCategoryChip category={model.category} />
                                    // live health (right of the category chip); null until probe data arrives
                                    const health = latency.get(model.model)
                                    const healthChip = health
                                        ? (
                                            <ModelHealthChip
                                                ok={health.ok}
                                                latencyMs={health.latencyMs}
                                                errorMessage={health.errorMessage}
                                                latencyLabel={latencyLabel(health.latencyMs)}
                                                downLabel={downLabel}
                                            />
                                        )
                                        : null
                                    const selfHostMark = showSelfHostMark(model) ? <SelfHostGpuMark /> : null
                                    const requiresPlan = PLAN_CATEGORIES.includes(model.category)
                                    // below the recommended floor → flag danger (grading: Free is
                                    // below Economy). No floor → never flagged (chatbot runs Free).
                                    const belowFloor = floor !== undefined
                                        && CATEGORY_ORDER.indexOf(model.category) < CATEGORY_ORDER.indexOf(floor)
                                    // not suited for this picker's task → amber warning
                                    const offTask = Boolean(task
                                        && model.supportedTasks?.length
                                        && !model.supportedTasks.includes(task))
                                    if (!model.available) {
                                        return (
                                            <DropdownItem
                                                key={key}
                                                textValue={model.model}
                                                className={DROPDOWN_ITEM_ROW_CLASS}
                                                onPress={() => undefined}
                                            >
                                                <Tooltip>
                                                    <Tooltip.Trigger className={MODEL_ROW_TRIGGER_CLASS}>
                                                        <ModelRowLayout
                                                            muted
                                                            name={model.model}
                                                            nameSuffix={selfHostMark}
                                                            leading={<WarningCircleIcon className="size-5 shrink-0" />}
                                                            trailing={<>{healthChip}{categoryChip}</>}
                                                        />
                                                    </Tooltip.Trigger>
                                                    <Tooltip.Content>{modelUnavailableLabel}</Tooltip.Content>
                                                </Tooltip>
                                            </DropdownItem>
                                        )
                                    }
                                    if (requiresPlan && !canPremium) {
                                        return (
                                            <DropdownItem
                                                key={key}
                                                textValue={model.model}
                                                className={DROPDOWN_ITEM_ROW_CLASS}
                                                onPress={onUpgrade}
                                            >
                                                <Tooltip>
                                                    <Tooltip.Trigger className={MODEL_ROW_TRIGGER_CLASS}>
                                                        <ModelRowLayout
                                                            muted
                                                            name={model.model}
                                                            nameSuffix={selfHostMark}
                                                            leading={<LockIcon className="size-5 shrink-0" />}
                                                            trailing={<>{healthChip}{categoryChip}</>}
                                                        />
                                                    </Tooltip.Trigger>
                                                    <Tooltip.Content>
                                                        <Typography type="body-sm">{subscribeToGradeLabel}</Typography>
                                                    </Tooltip.Content>
                                                </Tooltip>
                                            </DropdownItem>
                                        )
                                    }
                                    if (belowFloor || offTask) {
                                        return (
                                            <DropdownItem
                                                key={key}
                                                textValue={model.model}
                                                className={DROPDOWN_ITEM_ROW_CLASS}
                                                onPress={() => onSelect({
                                                    model: model.model,
                                                    provider: model.provider,
                                                })}
                                            >
                                                <Tooltip>
                                                    <Tooltip.Trigger className={MODEL_ROW_TRIGGER_CLASS}>
                                                        <ModelRowLayout
                                                            isSelected={isSelected}
                                                            name={model.model}
                                                            nameSuffix={selfHostMark}
                                                            leading={<WarningIcon className="size-5 shrink-0 text-warning-soft-foreground" />}
                                                            trailing={<>{healthChip}{categoryChip}</>}
                                                        />
                                                    </Tooltip.Trigger>
                                                    <Tooltip.Content>
                                                        <Typography type="body-sm" className="text-warning-soft-foreground">
                                                            {belowFloor
                                                                ? belowFloorWarningLabel
                                                                : offTaskWarningLabel}
                                                        </Typography>
                                                    </Tooltip.Content>
                                                </Tooltip>
                                            </DropdownItem>
                                        )
                                    }
                                    return (
                                        <DropdownItem
                                            key={key}
                                            textValue={model.model}
                                            className={DROPDOWN_ITEM_ROW_CLASS}
                                            onPress={() => onSelect({
                                                model: model.model,
                                                provider: model.provider,
                                            })}
                                        >
                                            <ModelRowLayout
                                                isSelected={isSelected}
                                                name={model.model}
                                                nameSuffix={selfHostMark}
                                                trailing={<>{healthChip}{categoryChip}</>}
                                            />
                                        </DropdownItem>
                                    )
                                })}
                            </DropdownSection>
                        </DropdownMenu>
                    </ScrollShadow>
                    {/* escape hatch — reveal the down / off-task models hidden by default */}
                    {hiddenCount > 0 ? (
                        <button
                            type="button"
                            onClick={() => setShowHidden((open) => !open)}
                            className="cursor-pointer px-3 pb-2 pt-1 text-start text-xs text-muted transition-colors hover:text-foreground"
                        >
                            {showHidden
                                ? hideHiddenModelsLabel
                                : showHiddenModelsLabel(hiddenCount)}
                        </button>
                    ) : null}
                </div>
            </DropdownPopover>
        </Dropdown>
    )
}

"use client"

import React from "react"
import { Button } from "@heroui/react"
import { CameraIcon } from "@phosphor-icons/react"
import { UserAvatar } from "@/components/blocks/identity/UserAvatar"

/** Props for {@link AvatarUploadButton}. */
export interface AvatarUploadButtonProps {
    /** Currently shown avatar URL (the saved image or a freshly-picked preview). */
    avatar?: string | null
    /** Display name; drives the avatar fallback initials + image alt text. */
    displayName?: string | null
    /** Stable identity used to seed the generated default avatar (email preferred). */
    seed?: string | null
    /** Accessible label for the icon-only trigger (e.g. "Change avatar"). */
    label: string
    /** Fired when the user activates the trigger to pick a new avatar. */
    onPress: () => void
}

/**
 * Circular avatar trigger that opens an avatar picker. Shows the current (or
 * preview) face inside a round frame and dims it with a centred camera icon on
 * hover/focus, hinting that the image is editable.
 *
 * Owns the full visual treatment (circular clip, hover-dim overlay, camera icon,
 * focus ring) so feature code only places it and wires {@link AvatarUploadButtonProps.onPress}.
 * Props-only — no store or data access; the caller supplies the avatar + identity.
 *
 * @param props - {@link AvatarUploadButtonProps}
 *
 * @see Story: .storybook/stories/blocks/identity/AvatarUploadButton/AvatarUploadButton.stories
 */
export const AvatarUploadButton = ({
    avatar,
    displayName,
    seed,
    label,
    onPress}: AvatarUploadButtonProps) => (
    <Button
        isIconOnly
        variant="ghost"
        onPress={onPress}
        aria-label={label}
        className={"group relative size-20 shrink-0 overflow-hidden rounded-full p-0"}
    >
        <UserAvatar
            username={displayName}
            avatar={avatar}
            seed={seed}
            size="lg"
            className="size-20 text-2xl"
        />
        <span className="absolute inset-0 flex items-center justify-center rounded-full bg-black/40 opacity-0 transition-opacity group-hover:opacity-100 group-focus-visible:opacity-100">
            <CameraIcon aria-hidden focusable="false" className="size-6 text-white" />
        </span>
    </Button>
)

"use client"

import React, {
    useState,
} from "react"
import {
    publicEnv,
} from "@/resources/env/public"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Props for {@link BadgeImage}. */
export interface BadgeImageProps extends WithClassNames<undefined> {
    /**
     * MinIO object key (no leading slash), e.g. `badges/league/gold.png`. The
     * public URL is built from `publicEnv().minio`. When the object does not exist
     * yet (instructor hasn't uploaded the art), the image 404s and {@link fallback}
     * is shown instead — so the web upgrades automatically as art is uploaded.
     */
    objectKey: string
    /** Square render size in px (default 24). */
    size?: number
    /** Alt text for the badge. */
    alt: string
    /** Rendered while the MinIO image is missing / fails to load. */
    fallback: React.ReactNode
}

/**
 * Renders a badge image straight from MinIO, falling back to {@link fallback}
 * (e.g. a placeholder icon) when the object isn't uploaded yet. Lets the team draw
 * + upload real badge art incrementally without the UI ever showing a broken image.
 * @param props - {@link BadgeImageProps}
 */
export const BadgeImage = ({
    objectKey,
    size = 24,
    alt,
    fallback,
    className,
}: BadgeImageProps) => {
    // flips to true once the MinIO object fails to load (missing / not uploaded)
    const [failed, setFailed] = useState(false)

    // no real art yet → show the placeholder fallback
    if (failed) {
        return <>{fallback}</>
    }

    // public MinIO URL: <url>/<bucket>/<objectKey>
    const { url, bucket } = publicEnv().minio
    const src = `${url}/${bucket}/${objectKey}`
    return (
        <img
            src={src}
            alt={alt}
            width={size}
            height={size}
            loading="lazy"
            className={className}
            onError={() => setFailed(true)}
        />
    )
}

import React from "react"
import { Logo } from "@/components/blocks/identity/Logo"

/** Closed size tokens for {@link BrandLogo}. */
export type BrandLogoSize = "sm" | "md" | "lg"

const SIZE_CLASS: Record<BrandLogoSize, string> = {
    sm: "h-9 w-auto",
    md: "h-10 w-auto",
    lg: "h-14 w-auto",
}

/** Props for the {@link BrandLogo} block. */
export type BrandLogoProps = {
    /** Height preset — sm (36px), md (40px), lg (56px). */
    size?: BrandLogoSize
}

/**
 * BrandLogo — the StarCi brand mark: the favicon "S" mark ({@link Logo}), the
 * circuit-traced "S" on a dark rounded square (no wordmark, no flame). Thin
 * placement wrapper around {@link Logo}.
 *
 * Kept as the shared identity entry point so callers (navbar, footer, splash)
 * don't need to change. Presentational only — wrap it in a link/button where it
 * needs to act. Square (1:1): default `sm` → a 36px icon.
 */
export const BrandLogo = ({ size = "sm" }: BrandLogoProps) => {
    return <Logo className={SIZE_CLASS[size]} />
}

"use client"

import React, { useEffect, useState } from "react"
import type { ReactNode } from "react"
import { cn } from "@heroui/react"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Visual tone of the tile (drives the tinted background + icon colour). */
export type IconTileTone = "accent" | "success" | "warning" | "danger" | "neutral"

/** Size of the tile. */
export type IconTileSize = "sm" | "md" | "lg"

/** Props for the {@link IconTile} block. */
export interface IconTileProps extends WithClassNames<undefined> {
    /** The icon (phosphor `*Icon`) — fallback when no {@link IconTileProps.src}. */
    icon: ReactNode
    /**
     * Optional cover image. When set, it FILLS the tile (`object-cover`, centered —
     * a 16:9 source is cropped to the square frame) instead of the icon; falls back
     * to {@link IconTileProps.icon} when absent/empty.
     */
    src?: string | null
    /** Alt text for the cover image (decorative tile — usually the entity title). */
    alt?: string
    /** Tinted background + icon colour. Defaults to "accent". */
    tone?: IconTileTone
    /** Tile size. Defaults to "md" (64px). */
    size?: IconTileSize
}

/** tone → tinted background + icon colour. */
const TONE: Record<IconTileTone, string> = {
    accent: "bg-accent-soft text-accent-soft-foreground",
    success: "bg-success-soft text-success-soft-foreground",
    warning: "bg-warning-soft text-warning-soft-foreground",
    danger: "bg-danger-soft text-danger-soft-foreground",
    neutral: "bg-default text-muted",
}

/** size → tile box + auto icon size + radius. */
const SIZE: Record<IconTileSize, string> = {
    sm: "size-12 rounded-xl [&_svg]:size-6",
    md: "size-16 rounded-2xl [&_svg]:size-8",
    lg: "size-20 rounded-2xl [&_svg]:size-10",
}

/**
 * A framed icon tile — a soft tinted square (`bg-{tone}/20`) with the icon
 * centered inside, used as the avatar of a *thing* (course, project, section…)
 * to give it breathing room and a consistent identity. The icon auto-sizes and
 * inherits the tone colour; pass it bare. Pure/props-only; owns its look.
 *
 * @param props - {@link IconTileProps}
 *
 * @see Story: .storybook/stories/blocks/identity/IconTile/IconTile.stories
 */
export const IconTile = ({
    icon,
    src,
    alt = "",
    tone = "accent",
    size = "md",
    className,
}: IconTileProps) => {
    // a broken cover URL (404 / unsynced asset) falls back to the icon instead of a
    // broken-image glyph; reset when the src changes.
    const [failed, setFailed] = useState(false)
    useEffect(() => setFailed(false), [src])
    const showImage = Boolean(src) && !failed

    return (
        <div
            aria-hidden
            className={cn(
                "flex shrink-0 items-center justify-center overflow-hidden",
                SIZE[size],
                // skip the tint when a cover image fills the tile
                showImage ? null : TONE[tone],
                className,
            )}
        >
            {showImage ? (
                <img
                    src={src ?? undefined}
                    alt={alt}
                    className="size-full object-cover"
                    onError={() => setFailed(true)}
                />
            ) : (
                icon
            )}
        </div>
    )
}

