import { querySearchCourseContent } from "@/modules/api/graphql/queries/query-search-course-content"
import { defaultChallengesListSorts, queryChallenges } from "@/modules/api/graphql/queries/query-challenges"
import type { SearchCourseContentItem } from "@/modules/api/graphql/queries/types/search-course-content"
import { ChatToolResult } from "@/components/blocks/learn/ChatToolResult"
import { EntityResultRow } from "@/components/blocks/learn/EntityResultRow"
import { SurfaceListCard, SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { useContentAiChatScopeStore } from "@/hooks/zustand/contentAiChatScope/store"

/** Props for {@link ContentAiChat}. */
export type ContentAiChatProps = WithClassNames<undefined>

/** Starter questions shown in the empty chat WITH A LESSON OPEN (keys under `contentAi.suggestions`). */
const SUGGESTION_KEYS = ["summarize", "hardest", "example"] as const

/** Scoped quick-asks shown when a lesson passage is selected (keys under `contentAi.selectionSuggestions`). */
const SELECTION_SUGGESTION_KEYS = ["explain", "example", "simplify"] as const

/**
 * The kind an in-chat "find X" intent resolves to.
 *
 * NOTE there is no `milestone` here on purpose: capstone tasks are not something
 * a learner looks up mid-lesson. They hang off the COURSE (not any content), the
 * personal-project surface is enrolled-only, and there is exactly one of it
 * reachable from the rail — so every capstone hit was noise (and, for a trial
 * viewer, a locked row). The backend still indexes and serves the kind for other
 * consumers (e.g. the mind-map node drawer); the chat just never asks for it.
 */
type ContentIntentKind = "content" | "challenge" | "flashcard"

/**
 * The retrieval "skills" the chat exposes — the ONLY tool-shaped capability it
 * has, and the reason they are surfaced as chips + a composer menu rather than a
 * slash grammar: each one runs the `searchCourseContent` RAG search and answers
 * with a PICKABLE list that navigates somewhere real.
 *
 * The old `/` palette also carried `summarize`/`explain`/`example`, which merely
 * sent a preset question and streamed plain prose back — those are not tools, so
 * they now live purely as empty-state suggestion chips ({@link SUGGESTION_KEYS})
 * and the slash grammar is gone entirely: learners here are beginners, often on a
 * phone, and a two-level `<verb> <noun>` grammar was a power-user affordance most
 * never discovered. Typing "find challenges…" already routes here via
 * {@link detectContentIntent}.
 */
interface RetrievalSkill {
    /** i18n token — label at `contentAi.commands.<token>`. */
    token: string
    /** Corpus this skill searches (`all` = every kind, the mixed "related" list). */
    kind: ContentIntentKind | "all"
    /** Leading icon (signals the result kind at a glance). */
    Icon: typeof CardsIcon
}
const RETRIEVAL_SKILLS: ReadonlyArray<RetrievalSkill> = [
    { token: "challenges", kind: "challenge", Icon: PuzzlePieceIcon },
    { token: "flashcards", kind: "flashcard", Icon: CardsIcon },
    { token: "lessons", kind: "content", Icon: BookOpenIcon },
    { token: "related", kind: "all", Icon: SparkleIcon },
]

/**
 * Which retrieval chips lead the EMPTY state, per scope.
 *
 * Course scope leads with `lessons` because with no lesson open the first useful
 * move is finding one; lesson scope has no reason to offer it (you are already in
 * one) and leads with the practice that follows the reading instead.
 */
const EMPTY_STATE_SKILLS: Record<ChatContextScope, ReadonlyArray<string>> = {
    content: ["challenges", "flashcards"],
    course: ["lessons", "challenges", "flashcards"],
    // a capstone task, a challenge, a quiz deck, and a foundation each read like a
    // single lesson — lead with the practice that follows the reading, not "find a
    // lesson" (you are in one)
    task: ["challenges", "flashcards"],
    challenge: ["challenges", "flashcards"],
    quiz: ["challenges", "flashcards"],
    foundation: ["challenges", "flashcards"],
    // no course at all (e.g. opened from the dashboard) → every retrieval skill
    // here searches a COURSE's content, so there is nothing to offer
    global: [],
}

/**
 * Label for a retrieval chip, worded for the scope it will actually search.
 *
 * The labels used to be fixed lesson-wording ("Find challenges related to THIS LESSON")
 * and rendered in both scopes, so on a lesson-less surface the chat offered to
 * search a lesson that was not open — and answered with hits from unrelated
 * modules. The search itself was always course-wide; only the promise was wrong.
 */
const SCOPE_LABEL_SUFFIX: Record<ChatContextScope, string> = {
    content: "OfLesson",
    course: "InCourse",
    task: "OfTask",
    challenge: "OfChallenge",
    quiz: "OfQuiz",
    foundation: "OfFoundation",
    // never actually resolved: EMPTY_STATE_SKILLS.global is empty and the
    // mid-conversation skill menu hides itself in global scope (no course to
    // search) — present only so this Record stays exhaustive over ChatContextScope.
    global: "InCourse",
}
const retrievalLabelKey = (token: string, scope: ChatContextScope): string =>
    `contentAi.commands.${token}${SCOPE_LABEL_SUFFIX[scope]}`

/**
 * Which grounding the next question runs against — surfaced to the learner as the
 * context pill above the composer so it is never a mystery what the AI is reading.
 * `content` is the DEFAULT whenever a lesson is open; `course` is both the
 * automatic fallback on a lesson-less surface (flashcards, mind-map, leaderboard)
 * and an explicit widening the learner can pick while reading. `global` is the
 * NEW fallback when there is no anchor at all — no lesson, task, challenge,
 * quiz, foundation, OR course (e.g. the chat opened from the dashboard): the
 * next question is sent anchorless, and the backend treats that as a
 * course-less, app-wide conversation.
 */
type ChatContextScope = "content" | "course" | "task" | "challenge" | "quiz" | "foundation" | "global"

/** A find-verb that signals the learner wants a LIST of course content, not a chat answer. */
const CONTENT_INTENT_VERB_RE = /(tìm|find|gợi ý|liệt kê|list|show|kiếm)/i // vn-ok: matches what the learner types, in either app locale

/** Kind noun → the corpus kind to search. */
const CONTENT_INTENT_KINDS: Array<{ re: RegExp, kind: ContentIntentKind }> = [
    { re: /(flashcard|thẻ)/i, kind: "flashcard" }, // vn-ok: learner input, either locale
    { re: /(thử thách|challenge|bài tập)/i, kind: "challenge" }, // vn-ok: learner input, either locale
    { re: /(bài học|bài|lesson|nội dung)/i, kind: "content" }, // vn-ok: learner input, either locale
]

/**
 * Detect an in-chat "find <kind> for this" intent — requires BOTH a find-verb
 * and a kind noun so a normal question ("summarize this lesson") never hijacks the chat
 * into a search. Returns the kind to render, or null for a normal answer.
 * MVP intent lives client-side; the BE classifier + persisted tool turn is phase 2.
 */
const detectContentIntent = (text: string): ContentIntentKind | null => {
    if (!CONTENT_INTENT_VERB_RE.test(text)) {
        return null
    }
    return CONTENT_INTENT_KINDS.find((entry) => entry.re.test(text))?.kind ?? null
}

/** Per-kind header presentation for the in-chat tool-result widget (`all` = the
 * mixed "related content" list from the `/related` command). */
const TOOL_RESULT_META: Record<ContentIntentKind | "all", { labelKey: string, Icon: typeof CardsIcon }> = {
    flashcard: { labelKey: "entityResult.kindFlashcard", Icon: CardsIcon },
    content: { labelKey: "entityResult.kindContent", Icon: BookOpenIcon },
    challenge: { labelKey: "entityResult.kindChallenge", Icon: PuzzlePieceIcon },
    all: { labelKey: "contentAi.toolResult.relatedLabel", Icon: SparkleIcon },
}

/** Corpus kinds the chat's "everything related" skill spans — capstone tasks excluded (see {@link ContentIntentKind}). */
const RELATED_KINDS: ReadonlyArray<string> = ["content", "code", "challenge", "flashcard"]

/** Number of rows the in-chat tool result shows before "see all". */
const TOOL_RESULT_LIMIT = 5

/**
 * The open lesson's OWN challenges, shaped as tool-result rows.
 *
 * A challenge hangs off exactly one content (FK `content_id`), so while a lesson
 * is open "this lesson's own challenges" is an exact list, not a similarity guess — this
 * reads the challenges-by-content query instead of RAG. Never locked: the learner
 * is already reading the parent lesson, so they can open its challenges.
 *
 * @param contentId - The open lesson.
 * @param contentTitle - Its title, used as each row's breadcrumb.
 * @returns Up to {@link TOOL_RESULT_LIMIT} rows (empty when the lesson has none).
 */
const loadContentChallenges = async (
    contentId: string,
    contentTitle: string | null,
): Promise<Array<SearchCourseContentItem>> => {
    const res = await queryChallenges({
        request: {
            contentId,
            filters: {
                pageNumber: 0,
                limit: TOOL_RESULT_LIMIT,
                sorts: defaultChallengesListSorts,
            },
        },
    })
    const rows = res.data?.challenges?.data?.data ?? []
    return rows.map((challenge) => ({
        kind: "challenge",
        title: challenge.title,
        breadcrumb: contentTitle,
        snippet: challenge.description ?? "",
        // a direct relation, not a similarity ranking — score is only used for
        // ordering RAG hits, and these arrive already ordered by `sortIndex`
        score: 1,
        moduleId: null,
        contentId,
        deckId: null,
        taskId: null,
        isLocked: false,
    }))
}

/** Extract the visible `<display>…</display>` part of a message (hides `<context>` from the UI). */
const DISPLAY_RE = /<display>([\s\S]*?)<\/display>/
const displayText = (content: string): string => {
    const match = content.match(DISPLAY_RE)
    return match ? match[1].trim() : content
}

/** Which in-panel view is showing. Conversations + settings + search are all
 * in-panel (not separate overlays) so they never z-fight the chat popover they
 * live inside. */
type PanelView = "chat" | "conversations" | "settings" | "search"

/** One turn in the content-AI conversation. */
interface ChatMessage {
    /** Author of the turn. */
    role: ChatRole
    /** The message text (assistant content may be markdown). */
    content: string
    /** Whether this assistant turn is an AI-quota-exhausted error (shows an upgrade CTA). */
    isQuotaError?: boolean
    /**
     * In-chat tool result (generative-UI part) — when the learner asks to FIND
     * content ("find flashcards for this section"), this assistant turn renders a
     * pickable {@link ChatToolResult} list instead of streamed text.
     */
    toolResult?: {
        /** Which corpus the results belong to (drives the header label/icon);
         *  `all` = the mixed "related content" list from the `/related` command. */
        kind: ContentIntentKind | "all"
        /** The query that produced them (feeds the "see all" full-search view). */
        query: string
        /** The matched sources (already sliced to {@link TOOL_RESULT_LIMIT}). */
        items: Array<SearchCourseContentItem>
        /** True while the RAG search is in flight (renders skeleton rows). */
        isLoading: boolean
    }
}

/**
 * Content-AI chat thread + composer (the body of the ask-AI popover/drawer).
 * A lesson can hold MANY named conversations (e.g. one about nginx, one about
 * kafka): the thread is a **session** persisted server-side (scoped to the
 * learner's enrollment), switchable + searchable via the in-panel conversations
 * view. Recent turns are replayed as short-term memory on each question; the
 * answer **streams** token-by-token over the `/content_ai` socket on the free
 * model (self-hosted Qwen — no AI credit).
 *
 * @param props - {@link ContentAiChatProps}
 */
export const ContentAiChat = ({ className }: ContentAiChatProps) => {
    const t = useTranslations()
    const router = useRouter()
    const locale = useLocale()
    const contentId = useAppSelector((state) => state.content.id)
    const contentEntity = useAppSelector((state) => state.content.entity)
    const course = useAppSelector((state) => state.course.entity)
    // grounding ids for the non-lesson scopes (capstone task, challenge, quiz,
    // foundation) — the route/outline populate these via redux
    // (milestone.selectedTaskId is set by MilestoneOutline/PersonalProject;
    // challenge.id by ChallengePage; foundation.foundationId by
    // useSyncReduxFoundationId). Absent → the scope falls back to course.
    const taskId = useAppSelector((state) => state.milestone.selectedTaskId)
    const challengeId = useAppSelector((state) => state.challenge.id)
    // TODO: the flashcard-quiz deck id is not held in redux (it lives only in the
    // quiz/review route params + component props — see QuizSession/FlashcardReviewer),
    // so quiz scope stays plumbed-but-dormant until a slice/selector exposes it.
    const quizId: string | undefined = undefined
    const foundationId = useAppSelector((state) => state.foundation.foundationId)
    const { ask, abort } = useContentAiStream()
    const { close: closeChat } = useContentAiChatOverlayState()
    const [messages, setMessages] = useState<Array<ChatMessage>>([])
    const [input, setInput] = useState("")
    // whether the composer's retrieval-skill menu is open (the ⌥ button) — the
    // mid-conversation way to reach the skills once the empty-state chips are gone
    const [isSkillMenuOpen, setSkillMenuOpen] = useState(false)
    // explicit "ask the whole course instead" widening while a lesson IS open;
    // ignored (and reset) when there is no lesson to narrow back to.
    // Lives in a store, not local state: the scope PILL renders in the panel
    // header (rail + drawer), so the host has to read the same value this body
    // grounds on — otherwise the header could claim a scope the next question
    // does not use.
    const { prefersCourseScope, resetScope } = useContentAiChatScopeStore()
    const [isStreaming, setIsStreaming] = useState(false)
    // lesson passage the learner highlighted to ask about (set by ContentAiSelectionAsk).
    // `forceNewThread` is that same component's explicit "New thread" pick (vs.
    // its default "Ask in this chat") — consumed once by `onSend` below, then reset.
    const { selection, selectionContext, forceNewThread, setSelection, setForceNewThread } = useContentAiSelection()

    // which conversation (session) is open + which in-panel view is showing
    const [currentSessionId, setCurrentSessionId] = useState<string | null>(null)
    const [view, setView] = useState<PanelView>("chat")
    const [searchTerm, setSearchTerm] = useState("")
    // "Archived" toggle — folds archived conversations into the history list
    // (born-archived selection chats + anything manually archived). Default off.
    const [showArchived, setShowArchived] = useState(false)
    // inline-rename state: which history row is being renamed + its draft title
    const [renamingSessionId, setRenamingSessionId] = useState<string | null>(null)
    const [renameDraft, setRenameDraft] = useState("")

    // "Search course content" (search view) — debounced so typing never fires an
    // embedding call per keystroke (unlike the plain-ILIKE conversations search above)
    const [contentSearchQuery, setContentSearchQuery] = useState("")
    const [debouncedContentSearchQuery, setDebouncedContentSearchQuery] = useState("")
    useEffect(() => {
        const timer = setTimeout(() => setDebouncedContentSearchQuery(contentSearchQuery), 400)
        return () => clearTimeout(timer)
    }, [contentSearchQuery])
    const contentSearchSwr = useQuerySearchCourseContentSwr(
        course?.id ?? null,
        debouncedContentSearchQuery,
        view === "search",
    )

    // every available model — the picker shows them all (Free is the chatbot's
    // normal lane here, NOT flagged danger; higher tiers gate on the unlock)
    const aiModelsSwr = useQueryAiModelsSwr()
    const models = useMemo(
        () => (aiModelsSwr.data?.aiModels?.data?.gradableModels ?? [])
            .filter((model) => model.available),
        [aiModelsSwr.data],
    )
    const myAiSettingsSwr = useQueryMyAiSettingsSwr()
    // unlocked (paid OR enrolled) → may pin higher-tier models
    const canPremium = Boolean(myAiSettingsSwr.data?.canPremium)
    const { selectedModel, setSelectedModel } = useContentAiSelectedModel()
    // default = Auto (no concrete model pinned); a picked model runs on that model
    const modelSelection = useMemo<GradeModelSelection>(() => {
        if (!selectedModel) {
            return {
                model: null,
                provider: null,
            }
        }
        const found = models.find((model) => model.model === selectedModel)
        return {
            model: selectedModel,
            provider: found?.provider ?? null,
        }
    }, [selectedModel, models])

    // ACTIVE SCOPE — what the NEXT question grounds on. A lesson grounds on itself
    // unless the learner widened to the course; with no lesson open the surface
    // picks the next grounding it has (capstone task → foundation → whole course
    // → `global`, when there is no course at all). This is now a PER-ASK value,
    // not a thread identity: the chat is app-wide, so navigating to a different
    // surface changes what the NEXT question sends, but never resets or switches
    // the conversation itself (see the mount-once init effect below).
    const scope: ChatContextScope = prefersCourseScope
        ? "course"
        : contentId
            ? "content"
            : taskId
                ? "task"
                : challengeId
                    ? "challenge"
                    : quizId
                        ? "quiz"
                        : foundationId
                            ? "foundation"
                            : course?.id
                                ? "course"
                                : "global"
    const isContentScope = scope === "content"
    // what the next question actually grounds on — exactly one id per scope
    // (all undefined in `global` scope: an intentionally anchorless ask)
    const askContentId = scope === "content" ? contentId : undefined
    const askTaskId = scope === "task" ? taskId : undefined
    const askChallengeId = scope === "challenge" ? challengeId : undefined
    const askQuizId = scope === "quiz" ? quizId : undefined
    const askFoundationId = scope === "foundation" ? foundationId : undefined
    const askCourseId = scope === "course" ? course?.id : undefined

    // recent conversations for the header (auto-select most recent + current title).
    // Each surface lists ITS OWN sessions: the active scope + its single anchor go
    // to the query, so a lesson lists that lesson's, a task that task's, a
    // foundation that foundation's, and the course surface the whole-course ones.
    const sessionsSwr = useQueryContentAiSessionsSwr(
        askContentId,
        undefined,
        askCourseId,
        scope,
        askTaskId,
        askFoundationId,
        askChallengeId,
        askQuizId,
    )
    // the conversations view list is paginated/infinite (mirror followers infinite)
    const sessionsInfinite = useQueryContentAiSessionsInfiniteSwr(
        askContentId,
        searchTerm,
        view === "conversations",
        askCourseId,
        showArchived,
        scope,
        askTaskId,
        askFoundationId,
        askChallengeId,
        askQuizId,
    )
    // saved turns of the OPEN conversation
    const historySwr = useQueryContentAiHistorySwr(currentSessionId ?? undefined)
    const createSwr = useMutateCreateContentAiSessionSwr()
    const deleteSwr = useMutateClearContentAiHistorySwr()
    const renameSwr = useMutateRenameContentAiSessionSwr()
    const archiveSwr = useMutateSetContentAiSessionArchivedSwr()
    const touchSwr = useMutateTouchContentAiSessionSwr()

    const hydratedRef = useRef<string | undefined>(undefined)
    // which surface-scope the auto-select effect has already resumed a session for
    // (guards it from re-firing on unrelated re-renders / streamed tokens)
    // whether the initial-conversation resolution (deep link > challenge/task's
    // remembered session > this surface's most-recent one) has already run for
    // this mount — guards the two effects below from re-firing on navigation or
    // on unrelated re-renders. Replaces the old per-surface-key ref: the chat is
    // now APP-WIDE, so there is no longer a "which surface resumed" question,
    // only a one-time "has THIS mount resolved its starting conversation yet".
    const initializedRef = useRef(false)
    const prevContentIdRef = useRef<string | undefined>(undefined)
    // thread scroll container — auto-follow the answer to the bottom as it
    // streams, scrolling ONLY this region (never the page)
    const scrollRef = useRef<HTMLDivElement>(null)
    // whether the user is pinned to the bottom; false once they scroll up to
    // re-read, so streaming does not drag them back down
    const stickToBottomRef = useRef<boolean>(true)

    // ── APP-WIDE CHAT: mount-once initialization ─────────────────────────────
    // This used to reset the WHOLE thread on every surface change (a new lesson,
    // task, challenge, quiz, foundation, or course — even just widening a lesson
    // to the course) or on a changed passage selection: one session PER SURFACE,
    // so moving pages wiped the thread and the effect below resumed that
    // surface's own most-recent session. The chat is now APP-WIDE — the active
    // conversation follows the learner across pages — so none of that resetting
    // may run on navigation any more. What is left below runs exactly ONCE, when
    // the panel first mounts (each open of the rail/drawer is a fresh mount:
    // there is no cross-open persistence here, only cross-PAGE continuity while
    // the panel stays open). Switching or starting a conversation afterward is
    // entirely the learner's own call, via the conversations list / "New
    // conversation" / the selection quote's explicit "New thread" action.
    useEffect(() => {
        abort()
        setInput("")
        setIsStreaming(false)
        setView("chat")
        setSearchTerm("")
        setContentSearchQuery("")
        setDebouncedContentSearchQuery("")
        resetScope()
        setSkillMenuOpen(false)
        hydratedRef.current = undefined
        setMessages([])
        setCurrentSessionId(null)
        initializedRef.current = false
        // mount-only, deliberately: see the note above — this must NOT re-run
        // when the learner navigates to a different surface.
    }, [])

    /** Jump to a search result's real surface (content/challenge/flashcard/milestone), then close the panel. */
    const onSelectSearchResult = useCallback(
        (item: SearchCourseContentItem) => {
            const displayId = course?.displayId
            if (!displayId) {
                return
            }
            const learn = pathConfig().locale(locale).course(displayId).learn()
            const href = item.kind === "flashcard" && item.deckId
                ? learn.flashcards().review(item.deckId).build()
                : item.kind === "milestone" && item.taskId
                    ? learn.personalProject(item.taskId).build()
                    : item.moduleId && item.contentId
                        ? learn.module(item.moduleId).content(item.contentId).build()
                        : null
            if (!href) {
                return
            }
            closeChat()
            router.push(href)
        },
        [course?.displayId, locale, router, closeChat],
    )

    // DEEP-LINK: `?chatSession=<uuid>` (paired with `?openChat=true`, opened by
    // InnerLayout) restores that exact conversation on load — read ONCE from the
    // URL and pinned so the initial-resolution effect below does not override it.
    // One-shot for the WHOLE mount now (not per-surface): the chat is app-wide, so
    // a deep-linked conversation stays active across later navigation instead of
    // being replaced the moment the learner moves to a different surface.
    const deepLinkAppliedRef = useRef(false)
    useEffect(() => {
        if (deepLinkAppliedRef.current) {
            return
        }
        deepLinkAppliedRef.current = true
        const deepLinkSessionId = new URLSearchParams(window.location.search).get("chatSession")
        if (!deepLinkSessionId) {
            return
        }
        setCurrentSessionId(deepLinkSessionId)
        // mark this mount as resolved so the effect below skips it, and let the
        // deep-linked conversation's turns hydrate from the server
        initializedRef.current = true
        hydratedRef.current = undefined
    }, [])

    // Resolve the INITIAL conversation once per mount (see the mount-once init
    // effect above): the current challenge/task's REMEMBERED conversation, if it
    // has one > this surface's most-recent conversation (the old per-scope
    // default — still how the panel resumes on a normal first open) > nothing.
    // Guarded by `initializedRef` so it runs exactly once; a later navigation or
    // a later passage selection must NOT re-trigger it — that would be the old
    // per-surface locking behavior this feature removes.
    useEffect(() => {
        if (initializedRef.current) {
            return
        }
        // an explicit "New thread" pick (ContentAiSelectionAsk) starts its own
        // fresh side-thread on purpose — never auto-resume a surface session into
        // it. Plain "Ask in this chat" (the default) falls through to the SAME
        // most-recent-conversation lookup as a normal open, so opening the chat
        // fresh from a quote still lands in the conversation the learner was
        // actually having, not an empty one.
        if (selection && forceNewThread) {
            initializedRef.current = true
            return
        }
        // TODO(BE contentAiSessionId): once the backend adds `contentAiSessionId`
        // to ChallengeEntity / MilestoneTaskEntity, read it here, e.g.:
        //   const challengeEntity = useAppSelector((state) => state.challenge.entity)
        //   const taskDetail = useAppSelector((state) => state.milestone.selectedTaskDetail)
        //   const rememberedSessionId = scope === "challenge"
        //       ? challengeEntity?.contentAiSessionId
        //       : scope === "task"
        //           ? taskDetail?.contentAiSessionId
        //           : undefined
        // so landing on a challenge/task that already has a remembered
        // conversation resumes THAT one, instead of falling through to the
        // most-recent lookup below.
        const rememberedSessionId: string | undefined = undefined
        if (rememberedSessionId) {
            setCurrentSessionId(rememberedSessionId)
            initializedRef.current = true
            return
        }
        // opening a chat bumps its recency server-side (touchSession), so
        // "most recent" = the last conversation the user read in this scope
        // (persisted in the DB, not the browser).
        if (sessionsSwr.data === undefined) {
            return
        }
        setCurrentSessionId(sessionsSwr.data[0]?.id ?? null)
        initializedRef.current = true
    }, [selection, forceNewThread, sessionsSwr.data])

    // clear a stale selected passage only when the content ACTUALLY changes
    useEffect(() => {
        if (prevContentIdRef.current !== undefined && prevContentIdRef.current !== contentId) {
            setSelection(null)
        }
        prevContentIdRef.current = contentId
    }, [contentId, setSelection])

    // hydrate the thread from the server once the open session's turns load
    useEffect(() => {
        if (!currentSessionId || hydratedRef.current === currentSessionId || !historySwr.data) {
            return
        }
        setMessages(historySwr.data.map((turn) => ({
            role: turn.role as ChatRole,
            content: turn.content,
        })))
        hydratedRef.current = currentSessionId
    }, [currentSessionId, historySwr.data])

    // keep the latest content in view as messages append / the answer streams.
    // scroll ONLY the thread container (scrollIntoView would walk up and yank the
    // whole lesson page / popover). a user's own send always scrolls; an assistant
    // delta only follows when the user is still pinned to the bottom.
    useEffect(() => {
        const el = scrollRef.current
        if (!el) {
            return
        }
        const last = messages[messages.length - 1]
        if (last?.role === "user" || stickToBottomRef.current) {
            el.scrollTop = el.scrollHeight
            stickToBottomRef.current = true
        }
    }, [messages])

    // track whether the user is near the bottom so streaming does not drag them
    // down while they scroll up to re-read earlier turns
    const handleThreadScroll = useCallback(() => {
        const el = scrollRef.current
        if (!el) {
            return
        }
        stickToBottomRef.current =
            el.scrollHeight - el.scrollTop - el.clientHeight < 80
    }, [])

    /** Append a delta to the trailing assistant bubble as the answer streams in. */
    const appendToAssistant = useCallback((delta: string) => {
        setMessages((prev) => {
            const next = [...prev]
            const last = next[next.length - 1]
            if (last && last.role === "assistant") {
                next[next.length - 1] = { ...last, content: last.content + delta }
            }
            return next
        })
    }, [])

    /**
     * Run an in-chat "find content" intent: append a tool-result assistant turn,
     * then fill it. Client-side MVP — the BE intent classifier + persisted tool
     * turn is phase 2 (this turn is not saved yet).
     *
     * Two data paths, because they answer two different questions:
     * - **Challenges while a lesson is open** come from the challenges-OF-THIS-CONTENT
     *   query, not RAG. A challenge belongs to exactly one lesson (FK `content_id`),
     *   so "this lesson's own challenges" has an EXACT, complete answer; semantic search
     *   could rank this lesson's own challenges below another lesson's, or miss them.
     * - **Everything else** is a semantic question ("what in this course relates to
     *   what I'm reading") → course-wide RAG.
     */
    const runContentIntent = useCallback(async (raw: string, kind: ContentIntentKind | "all") => {
        const courseId = course?.id
        if (!courseId) {
            return
        }
        setMessages((prev) => [
            ...prev,
            { role: "user", content: raw },
            { role: "assistant", content: "", toolResult: { kind, query: raw, items: [], isLoading: true } },
        ])
        setInput("")
        // ground the RAG search on the LESSON'S OWN topic, not the literal chat
        // phrase — "find related flashcards" carries no topical signal (embeds
        // near nothing), so the search must run on what the learner is actually
        // reading (mirrors RelatedContentList's query={content.title}, the
        // pattern the eval measured at 93.8% recall@6).
        const groundedQuery = contentEntity?.title || raw
        let items: Array<SearchCourseContentItem> = []
        try {
            if (kind === "challenge" && contentId) {
                items = await loadContentChallenges(contentId, contentEntity?.title ?? null)
            } else {
                // scope the retrieval to the kinds we actually render: the backend takes
                // ONE top-k across every kind, so an unscoped topical query comes back
                // content-dominated and the old client-side filter emptied the list.
                const kinds = kind === "all"
                    ? [...RELATED_KINDS]
                    : kind === "content"
                        ? ["content", "code"]
                        : [kind]
                const res = await querySearchCourseContent({ courseId, searchQuery: groundedQuery, kinds })
                const all = res.data?.searchCourseContent?.data?.results ?? []
                items = all
                    // defensive: the backend serves capstone hits to other consumers,
                    // and the chat never shows them (see ContentIntentKind)
                    .filter((item) => item.kind !== "milestone")
                    .slice(0, TOOL_RESULT_LIMIT)
            }
        } catch {
            items = []
        }
        setMessages((prev) => {
            const next = [...prev]
            const last = next[next.length - 1]
            if (last?.role === "assistant" && last.toolResult) {
                next[next.length - 1] = { ...last, toolResult: { ...last.toolResult, items, isLoading: false } }
            }
            return next
        })
    }, [course?.id, contentEntity?.title, contentId])

    /** Send a question, creating a conversation lazily on the first message. */
    const onSend = useCallback(async (preset?: string) => {
        const raw = (preset ?? input).trim()
        // `global` scope is a legitimate ANCHORLESS ask (no lesson, task,
        // challenge, quiz, foundation, or course) — it is no longer treated as a
        // "missing grounding" that silently swallows the send.
        if (!raw || isStreaming) {
            return
        }
        // an in-chat "find <kind>" ask renders a pickable list, not a streamed
        // answer (skipped while a passage is selected — that path is "explain this")
        const intentKind = selection ? null : detectContentIntent(raw)
        if (intentKind && course?.id) {
            void runContentIntent(raw, intentKind)
            return
        }
        // an explicit "New thread" pick on a quoted passage (ContentAiSelectionAsk)
        // always forks a fresh conversation, even while another one is already
        // active. Everything else — including the default "Ask in this chat" pick
        // — appends into whatever conversation is currently open, lazily starting
        // one (a plain, non-archived conversation) only if none is.
        let sessionId = forceNewThread ? null : currentSessionId
        if (!sessionId) {
            const created = await createSwr
                .trigger({
                    contentId: askContentId,
                    taskId: askTaskId,
                    challengeId: askChallengeId,
                    quizId: askQuizId,
                    foundationId: askFoundationId,
                    courseId: askCourseId,
                    // born-archived ONLY for an explicit fork — the old "every
                    // selection starts its own hidden side-thread" default is gone
                    // now that a quote appends into the active conversation instead.
                    archived: forceNewThread ? true : undefined,
                })
                .catch(() => undefined)
            sessionId = created?.data?.id ?? null
            if (!sessionId) {
                // creating the conversation failed (offline, or the server rejected
                // the request) — surface it instead of a silent no-op, so a dead
                // "Explain this passage" / send is never a mystery. Show the question
                // the learner sent + a one-line error under it.
                setMessages((prev) => [
                    ...prev,
                    { role: "user", content: raw },
                    { role: "assistant", content: `⚠️ ${t("contentAi.sendFailed")}` },
                ])
                return
            }
            setCurrentSessionId(sessionId)
            hydratedRef.current = sessionId
        }
        if (forceNewThread) {
            // consumed — later turns in this now-active thread must not keep
            // forking a new one each time
            setForceNewThread(false)
        }
        // when a passage is selected, wrap the turn so the UI shows only the
        // question (<display>) while the model also gets the hidden <context>: the
        // selected passage + its surrounding paragraph/section. A weak/degraded model
        // otherwise under-uses the passage and replies "please send me the specific passage", so
        // the context ends with an explicit directive that the passage IS provided
        // and must be answered directly — never asked for again.
        const content = selection
            ? `<display>${raw}</display>\n<context>${selectionContext ?? `Đoạn được chọn: «${selection}»`}\nLƯU Ý: đoạn được chọn đã có ngay trên đây — hãy giải thích/trả lời TRỰC TIẾP về nó dựa trên nội dung bài và kiến thức của bạn; TUYỆT ĐỐI không yêu cầu người học gửi hay nêu lại đoạn văn.</context>` // vn-ok: tutor prompt in the learner's language
            : raw
        const history = messages.map((message) => ({
            role: message.role,
            content: message.content,
        }))
        setMessages((prev) => [
            ...prev,
            { role: "user", content },
            { role: "assistant", content: "" },
        ])
        setInput("")
        // KEEP the selection sticky: clearing it here would hide the quoted
        // passage before the answer even streams back. It stays pinned (its input
        // + quick-asks remain) so a follow-up can still reference it; the learner
        // dismisses it explicitly with the quote's ✕ when they are done with it.
        setIsStreaming(true)
        ask({
            sessionId,
            contentId: askContentId,
            taskId: askTaskId,
            challengeId: askChallengeId,
            quizId: askQuizId,
            foundationId: askFoundationId,
            courseId: askCourseId,
            question: content,
            history,
            model: modelSelection.model,
            provider: modelSelection.provider,
            onDelta: appendToAssistant,
            onDone: (error) => {
                setIsStreaming(false)
                void sessionsSwr.mutate()
                void sessionsInfinite.mutate()
                if (!error) {
                    return
                }
                setMessages((prev) => {
                    const next = [...prev]
                    const last = next[next.length - 1]
                    if (last && last.role === "assistant" && last.content === "") {
                        next[next.length - 1] = {
                            ...last,
                            content: `⚠️ ${error}`,
                            isQuotaError: error.startsWith("AI quota exhausted"),
                        }
                    }
                    return next
                })
            },
        })
    }, [t, input, askContentId, askTaskId, askChallengeId, askQuizId, askFoundationId, askCourseId, isStreaming, currentSessionId, createSwr, selection, selectionContext, forceNewThread, setForceNewThread, messages, ask, appendToAssistant, setSelection, sessionsSwr, sessionsInfinite, modelSelection, runContentIntent, course?.id])

    /** Start a fresh conversation (created lazily on the first message). */
    const onNewConversation = useCallback(() => {
        abort()
        setMessages([])
        setInput("")
        setIsStreaming(false)
        setCurrentSessionId(null)
        hydratedRef.current = undefined
        setView("chat")
    }, [abort])

    /** Open an existing conversation (re-opening the current one just returns to it). */
    const onSwitchConversation = useCallback((sessionId: string) => {
        // re-selecting the ALREADY-open conversation → just go back to the thread.
        // Do NOT wipe messages: setCurrentSessionId(sameId) is a no-op, so the
        // hydrate effect (keyed on currentSessionId + historySwr.data — both
        // unchanged) would never re-fire to restore them → the thread goes blank.
        if (sessionId === currentSessionId) {
            setView("chat")
            return
        }
        abort()
        setMessages([])
        setInput("")
        setIsStreaming(false)
        hydratedRef.current = undefined
        setCurrentSessionId(sessionId)
        // mark it just-opened server-side so reload reopens THIS conversation,
        // then revalidate the list so it reflects the new recency order
        void touchSwr.trigger({ sessionId }).then(() => sessionsSwr.mutate())
        setView("chat")
    }, [abort, touchSwr, sessionsSwr, currentSessionId])

    /** Delete a conversation; if it was open, drop back to a fresh thread. */
    const onDeleteConversation = useCallback(async (sessionId: string) => {
        await deleteSwr.trigger({ sessionId }).catch(() => undefined)
        void sessionsSwr.mutate()
        void sessionsInfinite.mutate()
        if (sessionId === currentSessionId) {
            setMessages([])
            setCurrentSessionId(null)
            hydratedRef.current = undefined
        }
    }, [deleteSwr, sessionsSwr, sessionsInfinite, currentSessionId])

    /** Archive a conversation (drops from the default list, stays searchable);
     *  if it was open, drop back to a fresh thread. */
    const onArchiveConversation = useCallback(async (sessionId: string) => {
        await archiveSwr.trigger({ sessionId, archived: true }).catch(() => undefined)
        void sessionsSwr.mutate()
        void sessionsInfinite.mutate()
        if (sessionId === currentSessionId) {
            setMessages([])
            setCurrentSessionId(null)
            hydratedRef.current = undefined
        }
    }, [archiveSwr, sessionsSwr, sessionsInfinite, currentSessionId])

    /** Open the inline rename editor for a row, seeded with its current title. */
    const onStartRename = useCallback((sessionId: string, currentTitle: string | null) => {
        setRenamingSessionId(sessionId)
        setRenameDraft(currentTitle ?? "")
    }, [])

    /** Commit the inline rename (blank title resets to auto-titling); revalidate the lists. */
    const onCommitRename = useCallback(async () => {
        const sessionId = renamingSessionId
        if (!sessionId) {
            return
        }
        setRenamingSessionId(null)
        await renameSwr.trigger({ sessionId, title: renameDraft.trim() }).catch(() => undefined)
        void sessionsSwr.mutate()
        void sessionsInfinite.mutate()
    }, [renamingSessionId, renameDraft, renameSwr, sessionsSwr, sessionsInfinite])

    const trimmedSearch = searchTerm.trim()
    // flatten the infinite pages; a short last page means there are no more
    const infiniteItems = (sessionsInfinite.data ?? []).flat()
    const lastSessionsPage = sessionsInfinite.data?.[sessionsInfinite.data.length - 1]
    const hasMoreSessions = !!lastSessionsPage && lastSessionsPage.length === CONTENT_AI_SESSIONS_PAGE_LIMIT
    // search is course-wide on the server. In LESSON scope narrow the displayed rows
    // back to this lesson (cross-lesson navigation is a later enhancement); in COURSE
    // scope keep every row — there is no lesson to narrow to, and filtering on an
    // absent contentId would silently empty the whole result list.
    const drawerSessions = trimmedSearch && isContentScope
        ? infiniteItems.filter((session) => session.originContentId === contentId)
        : infiniteItems
    // co-located skeleton flag for the conversations list (first load, nothing in hand yet)
    const isConversationsSkeleton = sessionsInfinite.data === undefined

    // the model picker (shared block — composer + settings view). Auto = free
    // chain; a pinned model runs Premium when unlocked. No `floor` → Free is the
    // chatbot's normal lane (not flagged danger).
    const modelPicker = (placement: "top start" | "bottom start") => (
        <GradeModelDropdown
            className="min-w-0 max-w-full"
            models={models}
            task={AiModelTask.Chatting}
            selection={modelSelection}
            canPremium={canPremium}
            placement={placement}
            onSelect={(selection) => setSelectedModel(selection.model)}
            onUpgrade={() =>
                router.push(`${pathConfig().locale(locale).profile().build()}/ai-subscription`)}
        />
    )

    /** Run one retrieval skill (chip or ⌥ menu row) — same RAG list either way. */
    const runRetrievalSkill = useCallback((skill: RetrievalSkill) => {
        setSkillMenuOpen(false)
        if (!course?.id) {
            return
        }
        // the label IS the question that lands in the thread, so it has to be the
        // scoped one — this is what put "Find challenges related to this lesson" in the
        // transcript on a surface with no lesson open
        void runContentIntent(t(retrievalLabelKey(skill.token, scope)), skill.kind)
    }, [course?.id, runContentIntent, scope, t])

    /** Plain input — parent composer/quote box owns fill + padding; this is just where you type
     *  (no HeroUI field chrome, so it never nests a second border/ring inside the box). */
    const chatInputField = () => (
        <input
            type="text"
            aria-label={t("contentAi.placeholder")}
            className="w-full bg-transparent text-sm text-foreground outline-none placeholder:text-muted"
            placeholder={t("contentAi.placeholder")}
            value={input}
            onChange={(event) => setInput(event.target.value)}
            onKeyDown={(event) => {
                // plain composer: Enter sends. A retrieval ask needs no special
                // grammar — `detectContentIntent` picks "find challenges…" out of
                // ordinary typing inside `onSend`.
                if (event.key === "Enter") {
                    event.preventDefault()
                    void onSend()
                }
                if (event.key === "Escape" && isSkillMenuOpen) {
                    event.preventDefault()
                    setSkillMenuOpen(false)
                }
            }}
        />
    )

    /** Render an in-chat tool-result turn: an intro line + the pickable widget
     *  (or a quiet text fallback when the search came back empty). */
    const renderToolResult = (tr: NonNullable<ChatMessage["toolResult"]>) => {
        const meta = TOOL_RESULT_META[tr.kind]
        const Icon = meta.Icon
        if (!tr.isLoading && tr.items.length === 0) {
            return (
                <div className="flex flex-col gap-2">
                    <Typography type="body-sm">{t("contentAi.toolResult.intro")}</Typography>
                    <Typography type="body-sm" color="muted">{t("contentAi.toolResult.empty")}</Typography>
                </div>
            )
        }
        return (
            <div className="flex flex-col gap-2">
                <Typography type="body-sm">{t("contentAi.toolResult.intro")}</Typography>
                <ChatToolResult
                    items={tr.items}
                    isLoading={tr.isLoading}
                    label={t(meta.labelKey)}
                    icon={<Icon className="size-4" aria-hidden focusable="false" />}
                    onSelect={onSelectSearchResult}
                    onViewAll={() => {
                        setContentSearchQuery(tr.query)
                        setDebouncedContentSearchQuery(tr.query)
                        setView("search")
                    }}
                    viewAllLabel={t("contentAi.toolResult.viewAll")}
                />
            </div>
        )
    }

    // ── conversations view ────────────────────────────────────────────────
    if (view === "conversations") {
        return (
            <div className={cn("flex h-full flex-col gap-3", className)}>
                {/* back — link sm, icon + label both muted */}
                <button
                    type="button"
                    className="group flex w-fit cursor-pointer items-center gap-2 text-sm text-muted transition-colors hover:text-foreground"
                    onClick={() => setView("chat")}
                >
                    <ArrowLeftIcon className="size-4" />
                    <span className="underline-offset-4 decoration-[var(--separator-tertiary)] group-hover:underline">{t("contentAi.conversations")}</span>
                </button>
                {/* search + add (add sits right next to search) */}
                <div className="flex items-center gap-2">
                    <SearchInput
                        variant="secondary"
                        value={searchTerm}
                        onValueChange={setSearchTerm}
                        placeholder={t("contentAi.searchConversations")}
                        className="!max-w-none min-w-0 flex-1"
                    />
                    <Button
                        isIconOnly
                        size="sm"
                        variant="tertiary"
                        aria-label={t("contentAi.newConversation")}
                        onPress={onNewConversation}
                    >
                        <PlusIcon className="size-5" />
                    </Button>
                </div>
                {/* fold archived conversations into the list — born-archived selection
                    chats + anything the learner manually archived (search always spans
                    archived regardless, so this only affects plain browsing) */}
                <label className="flex cursor-pointer items-center justify-between gap-2">
                    <Typography type="body-sm" color="muted">{t("contentAi.showArchived")}</Typography>
                    <Switch
                        className="shrink-0"
                        isSelected={showArchived}
                        onChange={setShowArchived}
                        aria-label={t("contentAi.showArchived")}
                    >
                        <Switch.Content>
                            <Switch.Control>
                                <Switch.Thumb />
                            </Switch.Control>
                        </Switch.Content>
                    </Switch>
                </label>
                {/* list — self-bounded ScrollShadow + infinite scroll (mirror OutlineRail + followers infinite) */}
                <ScrollShadow hideScrollBar className="-mx-1 max-h-[55vh] min-h-0 min-w-0 flex-1 overflow-y-auto px-1">
                    {sessionsInfinite.error ? (
                        <AsyncContentError title={t("contentAi.noConversations")} />
                    ) : !isConversationsSkeleton && drawerSessions.length === 0 ? (
                        <AsyncContentEmpty title={t("contentAi.noConversations")} />
                    ) : (
                        <SurfaceListCard bordered>
                            {isConversationsSkeleton
                                ? Array.from({ length: 3 }, (_unused, row) => (
                                    <SurfaceListCardItem key={row}>
                                        <div className="flex items-center gap-2">
                                            <div className="flex min-w-0 flex-1 flex-col gap-0">
                                                <Skeleton.Typography type="body-sm" width="2/3" />
                                                <Skeleton.Typography type="body-xs" width="1/2" />
                                            </div>
                                            {/* matches the row's ⋯ overflow-menu trigger (size-sm icon button) */}
                                            <Skeleton className="size-8 shrink-0 rounded-xl" />
                                        </div>
                                    </SurfaceListCardItem>
                                ))
                                : drawerSessions.map((session) => (
                                    <SurfaceListCardItem key={session.id}>
                                        <div
                                            className={cn(
                                                "group flex items-center gap-2",
                                                session.id === currentSessionId && "text-accent-soft-foreground",
                                            )}
                                        >
                                            {renamingSessionId === session.id ? (
                                                // inline rename — replaces the title row while editing;
                                                // Enter / blur commits, Escape cancels
                                                <input
                                                    type="text"
                                                    autoFocus
                                                    aria-label={t("contentAi.renameConversation")}
                                                    className="min-w-0 flex-1 border-b border-default bg-transparent py-1 text-sm text-foreground outline-none focus:border-accent"
                                                    value={renameDraft}
                                                    onChange={(event) => setRenameDraft(event.target.value)}
                                                    onBlur={() => void onCommitRename()}
                                                    onKeyDown={(event) => {
                                                        if (event.key === "Enter") {
                                                            event.preventDefault()
                                                            void onCommitRename()
                                                        }
                                                        if (event.key === "Escape") {
                                                            event.preventDefault()
                                                            setRenamingSessionId(null)
                                                        }
                                                    }}
                                                />
                                            ) : (
                                                <button
                                                    type="button"
                                                    className="flex min-w-0 flex-1 cursor-pointer flex-col text-left"
                                                    onClick={() => onSwitchConversation(session.id)}
                                                >
                                                    <Typography type="body-sm" className="truncate">
                                                        {session.title ?? t("contentAi.untitled")}
                                                    </Typography>
                                                    {/* WHERE this conversation was had + how long it ran.
                                                        Sessions split per lesson, so without the source a
                                                        learner sees a pile of fragments with no idea which
                                                        belongs where. The snippet only replaces it while
                                                        SEARCHING — that is the one moment it earns the row,
                                                        by showing which line matched. */}
                                                    <Typography type="body-xs" color="muted" className="truncate">
                                                        {/* content rows carry their lesson title; course rows read
                                                            "Whole course"; task/foundation rows have no origin title (null),
                                                            so they fall back to just the turn count rather than a
                                                            misleading course-wide label. */}
                                                        {searchTerm.trim() && session.snippet
                                                            ? displayText(session.snippet)
                                                            : session.originContentTitle
                                                                ? `${session.originContentTitle} · ${t("contentAi.turnsCount", { count: session.messageCount })}`
                                                                : session.scope === "course"
                                                                    ? `${t("contentAi.context.courseWide")} · ${t("contentAi.turnsCount", { count: session.messageCount })}`
                                                                    : t("contentAi.turnsCount", { count: session.messageCount })}
                                                    </Typography>
                                                </button>
                                            )}
                                            {/* overflow menu ⋯ — Rename · Archive · Delete (hidden while
                                                this row is being renamed) */}
                                            {renamingSessionId === session.id ? null : (
                                                <Dropdown>
                                                    <DropdownTrigger className="shrink-0 cursor-pointer">
                                                        <Button
                                                            isIconOnly
                                                            size="sm"
                                                            variant="tertiary"
                                                            aria-label={t("contentAi.conversationActions")}
                                                        >
                                                            <DotsThreeVerticalIcon weight="bold" className="size-5" />
                                                        </Button>
                                                    </DropdownTrigger>
                                                    <DropdownPopover placement="bottom end" className="min-w-44">
                                                        <DropdownMenu aria-label={t("contentAi.conversationActions")}>
                                                            <DropdownSection>
                                                                <DropdownItem
                                                                    key="rename"
                                                                    onPress={() => onStartRename(session.id, session.title)}
                                                                >
                                                                    <div className="flex items-center gap-2">
                                                                        <PencilSimpleIcon className="size-4 shrink-0" />
                                                                        <span className="text-sm">{t("contentAi.renameConversation")}</span>
                                                                    </div>
                                                                </DropdownItem>
                                                                <DropdownItem
                                                                    key="archive"
                                                                    onPress={() => void onArchiveConversation(session.id)}
                                                                >
                                                                    <div className="flex items-center gap-2">
                                                                        <ArchiveIcon className="size-4 shrink-0" />
                                                                        <span className="text-sm">{t("contentAi.archiveConversation")}</span>
                                                                    </div>
                                                                </DropdownItem>
                                                                <DropdownItem
                                                                    key="delete"
                                                                    className="text-danger-soft-foreground"
                                                                    onPress={() => void onDeleteConversation(session.id)}
                                                                >
                                                                    <div className="flex items-center gap-2">
                                                                        <TrashIcon className="size-4 shrink-0" />
                                                                        <span className="text-sm">{t("contentAi.deleteConversation")}</span>
                                                                    </div>
                                                                </DropdownItem>
                                                            </DropdownSection>
                                                        </DropdownMenu>
                                                    </DropdownPopover>
                                                </Dropdown>
                                            )}
                                        </div>
                                    </SurfaceListCardItem>
                                ))}
                        </SurfaceListCard>
                    )}
                    {/* grow on scroll instead of a "load more" button */}
                    <InfiniteScrollSentinel
                        onReach={() => sessionsInfinite.setSize((size) => size + 1)}
                        disabled={!hasMoreSessions || sessionsInfinite.isValidating}
                    />
                    {sessionsInfinite.isValidating && sessionsInfinite.data !== undefined ? (
                        <Typography type="body-xs" color="muted" className="px-1 py-2 text-center">
                            {t("common.loading")}
                        </Typography>
                    ) : null}
                </ScrollShadow>
            </div>
        )
    }

    // ── search view ("Search course content") ──────────────────────────────────
    if (view === "search") {
        // same exclusion as the in-chat skills: the chat never surfaces capstone
        // tasks, so its own "see all" view must not either (see ContentIntentKind)
        const results = (contentSearchSwr.data ?? []).filter((item) => item.kind !== "milestone")
        // co-located skeleton flag for the search-result list (first load, nothing in hand yet)
        const isSearchSkeleton = contentSearchSwr.isLoading && debouncedContentSearchQuery.trim().length > 0
        return (
            <div className={cn("flex h-full flex-col gap-3", className)}>
                <button
                    type="button"
                    className="group flex w-fit cursor-pointer items-center gap-2 text-sm text-muted transition-colors hover:text-foreground"
                    onClick={() => setView("chat")}
                >
                    <ArrowLeftIcon className="size-4" />
                    <span className="underline-offset-4 decoration-[var(--separator-tertiary)] group-hover:underline">{t("contentAi.searchContent")}</span>
                </button>
                <SearchInput
                    value={contentSearchQuery}
                    onValueChange={setContentSearchQuery}
                    placeholder={t("contentAi.searchContentPlaceholder")}
                />
                <ScrollShadow hideScrollBar className="max-h-[55vh] min-h-0 flex-1 overflow-y-auto">
                    {contentSearchSwr.error ? (
                        <AsyncContentError title={t("contentAi.searchContentEmpty")} />
                    ) : !isSearchSkeleton && debouncedContentSearchQuery.trim().length > 0 && results.length === 0 ? (
                        <AsyncContentEmpty title={t("contentAi.searchContentEmpty")} />
                    ) : debouncedContentSearchQuery.trim().length === 0 ? (
                        <Typography type="body-sm" color="muted">
                            {t("contentAi.searchContentHint")}
                        </Typography>
                    ) : (
                        <div className="flex flex-col overflow-hidden rounded-2xl border border-default">
                            {isSearchSkeleton
                                ? Array.from({ length: 3 }, (_unused, row) => (
                                    // _EntityResultRow has no isSkeleton prop — mirrored inline here,
                                    // right where the real row sits (see missingSkeletonSupport)
                                    <div key={row} className="flex flex-col gap-2 px-4 py-3">
                                        <Skeleton.Typography type="body-sm" width="2/3" />
                                        <Skeleton.Typography type="body-xs" width="1/2" />
                                    </div>
                                ))
                                : results.map((item, index) => (
                                    <EntityResultRow
                                        key={`${item.kind}-${item.contentId ?? item.deckId ?? item.taskId ?? index}`}
                                        item={item}
                                        showKindChip
                                        showSnippet
                                        onSelect={onSelectSearchResult}
                                    />
                                ))}
                        </div>
                    )}
                </ScrollShadow>
            </div>
        )
    }

    // ── chat view ─────────────────────────────────────────────────────────
    return (
        <div className={cn("flex h-full flex-col gap-3", className)}>
            {/* conversation switcher — quiet go-there link (foreground + hover underline),
                opens the conversations view. Not accent: it's a secondary nav link, not a
                primary/selected signal. Paired with the search icon — both are "find
                something" actions (history = find a past chat; search = find course content). */}
            <div className="flex items-center gap-2">
                <Link
                    onPress={() => setView("conversations")}
                    className="flex min-w-0 flex-1 cursor-pointer items-center gap-2 text-sm font-medium text-foreground underline-offset-4 decoration-[var(--separator-tertiary)] hover:underline"
                >
                    <ChatsCircleIcon className="size-5 shrink-0" />
                    <span className="min-w-0 flex-1 truncate text-left">
                        {t("contentAi.chatHistory")}
                    </span>
                    <CaretDownIcon weight="bold" className="size-4 shrink-0" />
                </Link>
            </div>

            {/* selected passage — pinned at the TOP of the rail (the dedicated
                selection view): the excerpt this side-thread is about, plus the
                born-archived note. Its quick-asks + input live at the bottom. */}
            {selection ? (
                <div className="flex flex-col gap-2 rounded-xl border border-warning bg-warning-soft px-3 py-2">
                    <div className="flex items-start gap-2">
                        <QuotesIcon className="size-4 shrink-0 text-warning-soft-foreground" />
                        <Typography type="body-sm" className="line-clamp-2 flex-1 text-warning-soft-foreground" weight="medium">
                            {selection}
                        </Typography>
                        <CloseButton
                            aria-label={t("contentAi.clearSelection")}
                            className="shrink-0 text-warning-soft-foreground hover:bg-warning-soft"
                            onPress={() => setSelection(null)}
                        />
                    </div>
                    <Typography type="body-xs" color="muted">
                        {/* the note follows which action ContentAiSelectionAsk's
                            learner picked: "New thread" still forks a hidden
                            born-archived side-conversation (the old default); the
                            new default, "Ask in this chat", just appends into
                            whatever conversation is already open. */}
                        {forceNewThread ? t("contentAi.selectionArchivedNote") : t("contentAi.selectionAppendedNote")}
                    </Typography>
                </div>
            ) : null}

            {/* thread — self-bounded scroll region (scroll shadow on the messages,
                not the popover); composer stays fixed below */}
            <ScrollShadow ref={scrollRef} onScroll={handleThreadScroll} hideScrollBar className="max-h-[55vh] min-h-0 flex-1 overflow-y-auto">
                <div className="flex flex-col gap-3">
                    {messages.length === 0 && !selection ? (
                        <div className="flex flex-col gap-2">
                            <Typography type="body-sm" color="muted">
                                {isContentScope
                                    ? t("contentAi.hint")
                                    : scope === "global"
                                        ? t("contentAi.globalHint")
                                        : t("contentAi.courseHint")}
                            </Typography>
                            {/* summarize / hardest / example only make sense against an
                                OPEN lesson — there is no "this lesson" to summarise for a
                                task / foundation / course, so those scopes offer retrieval only */}
                            {isContentScope ? SUGGESTION_KEYS.map((key) => (
                                <Button
                                    key={key}
                                    variant="secondary"
                                    size="sm"
                                    className="justify-start text-start"
                                    onPress={() => onSend(t(`contentAi.suggestions.${key}`))}
                                >
                                    {t(`contentAi.suggestions.${key}`)}
                                </Button>
                            )) : null}
                            {/* retrieval skills — available in BOTH scopes (the search is
                                course-wide either way), but the LABEL follows the scope so
                                a lesson-less surface never offers "of this lesson" */}
                            {RETRIEVAL_SKILLS
                                .filter((skill) => EMPTY_STATE_SKILLS[scope].includes(skill.token))
                                .map((skill) => {
                                    const SkillIcon = skill.Icon
                                    return (
                                        <Button
                                            key={skill.token}
                                            variant="secondary"
                                            size="sm"
                                            className="justify-start text-start"
                                            onPress={() => runRetrievalSkill(skill)}
                                        >
                                            <SkillIcon aria-hidden focusable="false" className="size-4 shrink-0 text-muted" />
                                            {t(retrievalLabelKey(skill.token, scope))}
                                        </Button>
                                    )
                                })}
                        </div>
                    ) : (
                        messages.map((message, index) => (
                            <ChatBubble key={index} role={message.role}>
                                {message.role === "assistant" ? (
                                    message.toolResult ? (
                                        renderToolResult(message.toolResult)
                                    ) : message.content === "" ? (
                                        <Typography type="body-sm" color="muted">
                                            {t("contentAi.thinking")}
                                        </Typography>
                                    ) : message.isQuotaError ? (
                                        <div className="flex flex-col gap-2">
                                            <MarkdownContent markdown={message.content} />
                                            <Button
                                                variant="primary"
                                                size="sm"
                                                className="self-start"
                                                onPress={() => router.push(
                                                    `${pathConfig().locale(locale).profile().build()}/ai-subscription`,
                                                )}
                                            >
                                                {t("contentAi.upgrade")}
                                                <ArrowRightIcon aria-hidden focusable="false" className="size-4" />
                                            </Button>
                                        </div>
                                    ) : (
                                        <MarkdownContent markdown={message.content} />
                                    )
                                ) : (
                                    <Typography type="body-sm">
                                        {displayText(message.content)}
                                    </Typography>
                                )}
                            </ChatBubble>
                        ))
                    )}
                </div>
            </ScrollShadow>

            {/* selected-passage quick-asks + input (the excerpt itself is pinned at
                the TOP of the rail). Quick-asks show only before the first turn. */}
            {selection ? (
                <div className="flex flex-col gap-2 rounded-xl border border-default bg-transparent px-3 py-2 focus-within:ring-2 focus-within:ring-accent">
                    {messages.length === 0 ? (
                        <div className="flex flex-col gap-2">
                            {SELECTION_SUGGESTION_KEYS.map((key) => (
                                <Button
                                    key={key}
                                    variant="secondary"
                                    size="sm"
                                    className="justify-start text-start"
                                    onPress={() => onSend(t(`contentAi.selectionSuggestions.${key}`))}
                                >
                                    {t(`contentAi.selectionSuggestions.${key}`)}
                                </Button>
                            ))}
                        </div>
                    ) : null}
                    {chatInputField()}
                </div>
            ) : null}

            {/* retrieval-skill menu — the ⌥ composer button opens it. This replaces the
                old "/" grammar: same capabilities, but TAPPABLE (works on a phone) and
                reachable MID-conversation, once the empty-state chips are gone. Hidden
                in `global` scope: every skill here searches a COURSE's content, and a
                global conversation has none. */}
            {isSkillMenuOpen && scope !== "global" ? (
                <div
                    role="listbox"
                    aria-label={t("contentAi.commands.aria")}
                    className="flex flex-col overflow-hidden rounded-2xl border border-default bg-surface"
                >
                    <div className="px-3 pb-1 pt-2">
                        <Typography type="body-xs" color="muted">{t("contentAi.commands.hint")}</Typography>
                    </div>
                    <ScrollShadow hideScrollBar className="max-h-64 min-h-0 overflow-y-auto p-1">
                        {RETRIEVAL_SKILLS.map((skill) => {
                            const SkillIcon = skill.Icon
                            return (
                                <Button
                                    key={skill.token}
                                    variant="ghost"
                                    className="h-auto w-full justify-start gap-3 px-3 py-2 text-start"
                                    onPress={() => runRetrievalSkill(skill)}
                                >
                                    <SkillIcon className="size-4 shrink-0 text-muted" aria-hidden focusable="false" />
                                    <span className="min-w-0 flex-1 truncate text-sm font-medium text-foreground">
                                        {t(retrievalLabelKey(skill.token, scope))}
                                    </span>
                                </Button>
                            )
                        })}
                    </ScrollShadow>
                </div>
            ) : null}

            {/* The CONTEXT PILL used to live here, above the composer. It moved into
                the panel HEADER (`ContentAiScopePill`, rendered by the rail + drawer):
                the header already named the same thing as a plain title, so the panel
                stated its context twice, two screen-heights apart. */}

            {/* composer — input lives in quote block while a passage is selected */}
            <div className="flex flex-col gap-2 rounded-2xl bg-default px-3 py-2 focus-within:ring-2 focus-within:ring-accent">
                {!selection ? chatInputField() : null}
                <div className="flex w-full items-center justify-between gap-2">
                    <div className="min-w-0 overflow-hidden">
                        {modelPicker("top start")}
                    </div>
                    <div className="flex shrink-0 items-center gap-2">
                        {/* retrieval skills, mid-conversation — the tappable replacement
                            for the removed "/" grammar. Hidden in `global` scope (no
                            course to search — see the menu above). */}
                        {scope !== "global" ? (
                            <Button
                                isIconOnly
                                size="sm"
                                variant="tertiary"
                                aria-label={t("contentAi.commands.aria")}
                                aria-expanded={isSkillMenuOpen}
                                onPress={() => setSkillMenuOpen((previous) => !previous)}
                            >
                                <MagnifyingGlassIcon className="size-5" />
                            </Button>
                        ) : null}
                        <Button
                            isIconOnly
                            size="sm"
                            variant="primary"
                            isPending={isStreaming}
                            aria-label={t("contentAi.send")}
                            onPress={() => void onSend()}
                        >
                            <PaperPlaneTiltIcon className="size-5" />
                        </Button>
                    </div>
                </div>
            </div>
        </div>
    )
}

"use client"

import React, { useCallback, useEffect, useRef, useState } from "react"
import {
    Button,
    cn,
} from "@heroui/react"
import { SparkleIcon } from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { useSmViewpoint } from "@/hooks/reuseables/useSmViewpoint"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { useContentAiChatOverlayState } from "@/hooks/zustand/overlay/hooks"
import { useContentAiChatModeStore } from "@/hooks/zustand/contentAiChatMode/store"
import { FloatingActionButton } from "@/components/blocks/buttons/FloatingActionButton"

/** localStorage key for the FAB's persisted vertical position (px from viewport bottom). */
const STORAGE_KEY = "contentAiFabBottom"
/** Default distance from the viewport bottom (px). */
const DEFAULT_BOTTOM = 96
/** Lowest the FAB may sit (px from bottom) — keeps it clear of the very edge. */
const MIN_BOTTOM = 16
/** Pixels the pointer must travel before a press counts as a drag (not a click). */
const DRAG_THRESHOLD = 6
/** Headroom kept below the top edge so the FAB never drags off-screen (px). */
const TOP_GUARD = 80

/** Props for {@link ContentAiFab}. */
export type ContentAiFabProps = WithClassNames<undefined>

/**
 * Floating "ask StarCi AI" button — the TRIGGER for the app-wide chat, mounted
 * ONCE by `InnerLayout` so it is reachable from EVERY route, not just a course's
 * learn surface: with a lesson open it grounds on that lesson, with a course but
 * no lesson it grounds on the course, and with no course at all (e.g. the
 * dashboard) it opens a `global`, anchorless conversation — see the scope ladder
 * in {@link import("@/components/blocks/learn/ContentAiChat").ContentAiChat}.
 * The panel is presented per the learner's persisted choice
 * ({@link useContentAiChatModeStore}), switchable in the panel header:
 * - **rail** — a resizable right-edge side panel that reflows the app column
 *   (see `InnerLayout`'s split); the FAB here is only the draggable toggle,
 *   hidden while the rail is open (the rail carries its close).
 * - **drawer** — the slide-in {@link import("@/components/overlays/drawers/ContentAiChatDrawer").ContentAiChatDrawer}
 *   (rendered globally); the FAB is its trigger.
 *
 * MOBILE always uses the drawer regardless of the preference. Open-state lives in
 * the shared overlay store (`contentAiChat` key).
 *
 * @param props - {@link ContentAiFabProps}
 */
export const ContentAiFab = ({ className }: ContentAiFabProps) => {
    const t = useTranslations()
    const { isOpen, setOpen, open } = useContentAiChatOverlayState()
    const { mode } = useContentAiChatModeStore()
    const { isMobile } = useSmViewpoint()
    // a phone is always the drawer — a side rail is too cramped there.
    const effectiveMode = isMobile ? "drawer" : mode

    // vertical position of the FAB (px from viewport bottom); restored from localStorage on mount
    const [bottom, setBottom] = useState<number>(DEFAULT_BOTTOM)
    useEffect(() => {
        // localStorage is client-only; read once after mount to seed the persisted position
        const saved = window.localStorage.getItem(STORAGE_KEY)
        if (saved !== null && !Number.isNaN(Number(saved))) {
            setBottom(Number(saved))
        }
    }, [])

    // drag bookkeeping: a press opens the panel ONLY when it did not become a drag
    const draggingRef = useRef(false)
    const startRef = useRef<{ pointerY: number; bottom: number } | null>(null)

    // remember where the drag began so we can offset from it
    const onPointerDown = useCallback(
        (event: React.PointerEvent) => {
            startRef.current = { pointerY: event.clientY, bottom }
            draggingRef.current = false
            event.currentTarget.setPointerCapture?.(event.pointerId)
        },
        [bottom],
    )

    // move the FAB up/down with the pointer, clamped to the viewport; mark it a drag past the threshold
    const onPointerMove = useCallback((event: React.PointerEvent) => {
        const start = startRef.current
        if (!start) {
            return
        }
        // dragging UP (smaller clientY) should RAISE the bubble → larger `bottom`
        const delta = start.pointerY - event.clientY
        if (Math.abs(delta) > DRAG_THRESHOLD) {
            draggingRef.current = true
        }
        const maxBottom = window.innerHeight - TOP_GUARD
        setBottom(Math.min(Math.max(start.bottom + delta, MIN_BOTTOM), maxBottom))
    }, [])

    // end the gesture; persist the new position only if it was actually a drag
    const onPointerUp = useCallback(
        (event: React.PointerEvent) => {
            if (startRef.current && draggingRef.current) {
                window.localStorage.setItem(STORAGE_KEY, String(bottom))
            }
            startRef.current = null
            event.currentTarget.releasePointerCapture?.(event.pointerId)
        },
        [bottom],
    )

    // a real press (not a drag) opens the panel; swallow the click that fires at the
    // end of a drag-release.
    const onOpen = useCallback(() => {
        if (draggingRef.current) {
            draggingRef.current = false
            return
        }
        setOpen(true)
    }, [setOpen])

    // No course-required gate any more: with no course at all (dashboard,
    // profile, …) the chat just opens `global`-scoped instead of hiding itself —
    // see the scope ladder in `ContentAiChat`.

    // DRAWER — the panel is the global ContentAiChatDrawer; here just the FAB trigger.
    if (effectiveMode === "drawer") {
        return (
            <FloatingActionButton
                onPress={open}
                ariaLabel={t("contentAi.ask")}
                className={className}
            >
                {/* sparkle = AI intent; the wrapped isIconOnly button sizes the svg */}
                <SparkleIcon />
            </FloatingActionButton>
        )
    }

    // RAIL — the resizable rail is rendered by the learn shell (rightRail) when open.
    // The FAB is the draggable toggle, hidden while the rail is open (the rail closes itself).
    if (isOpen) {
        return null
    }

    return (
        <Button
            isIconOnly
            variant="primary"
            aria-label={t("contentAi.ask")}
            aria-expanded={isOpen}
            onPointerDown={onPointerDown}
            onPointerMove={onPointerMove}
            onPointerUp={onPointerUp}
            onPress={onOpen}
            style={{ bottom }}
            className={cn(
                "fixed right-[calc(var(--app-rail-w,0px)+1rem)] z-40 mb-[env(safe-area-inset-bottom)] touch-none rounded-full shadow-lg",
                className,
            )}
        >
            {/* sparkle = AI intent; the isIconOnly button sizes the svg itself */}
            <SparkleIcon />
        </Button>
    )
}

"use client"

import React, { useCallback, useEffect, useState } from "react"
import { createPortal } from "react-dom"
import { Button } from "@heroui/react"
import { ChatCircleIcon, SparkleIcon } from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import {
    useContentAiChatOverlayState,
    useContentAiSelection,
} from "@/hooks/zustand/overlay/hooks"
import { useSelectionHintStore } from "./hintStore"

/**
 * Marker attribute for any readable text region a selection may be asked about —
 * lesson body, foundation body, task brief, challenge brief. Selection only counts
 * when it lands inside an element carrying `[data-ai-selectable]` (no longer bound
 * to the single `#lesson-article` id, so the feature works on every reading surface).
 */
const SELECTABLE_SELECTOR = "[data-ai-selectable]"
/** Ignore trivially short selections (clicks, single words barely worth asking about). */
const MIN_CHARS = 3
/** Cap the stored passage so a huge selection doesn't bloat the prompt / bubble. */
const MAX_CHARS = 600
/** Cap the surrounding-paragraph context fed to the model. */
const MAX_CONTEXT = 700

/** Block elements that count as the "containing paragraph" of a selection. */
const BLOCK_SELECTOR = "p, li, blockquote, td, th, pre, h1, h2, h3, h4, h5, h6"
/** Heading elements used to resolve the section a selection sits under. */
const HEADING_SELECTOR = "h1, h2, h3, h4, h5, h6, [data-toc-label]"

/** Floating button anchor (viewport coords) + the selected passage + its context. */
interface SelectionAnchor {
    /** Horizontal center of the selection, in viewport px. */
    x: number
    /** Top of the selection, in viewport px (the button sits above it). */
    y: number
    /** The trimmed, capped selected text. */
    text: string
    /** Hidden grounding sent to the model: the passage + its containing paragraph + section. */
    context: string
}

/** Resolve the block element (paragraph/list-item/…) containing a selection node. */
const containingBlock = (node: Node | null): Element | null => {
    const start = node?.nodeType === Node.TEXT_NODE ? node.parentElement : (node as Element | null)
    return start?.closest?.(BLOCK_SELECTOR) ?? null
}

/** Resolve the nearest AI-selectable reading region containing a selection node. */
const containingSelectable = (node: Node | null): Element | null => {
    const start = node?.nodeType === Node.TEXT_NODE ? node.parentElement : (node as Element | null)
    return start?.closest?.(SELECTABLE_SELECTOR) ?? null
}

/** Clean text of a heading element (prefer the anchor-free toc label). */
const headingText = (el: Element): string =>
    (el.getAttribute("data-toc-label") ?? el.textContent ?? "").trim()

/** The nearest section heading appearing BEFORE a block within the reading region. */
const nearestHeading = (block: Element | null, region: Element): string | null => {
    if (!block) {
        return null
    }
    let found: Element | null = null
    for (const heading of Array.from(region.querySelectorAll(HEADING_SELECTOR))) {
        // heading precedes the block → it's a candidate section for the selection
        if (heading.compareDocumentPosition(block) & Node.DOCUMENT_POSITION_FOLLOWING) {
            found = heading
        }
    }
    return found ? headingText(found) : null
}

/** Build the hidden `<context>` grounding string from the selection + surroundings. */
const buildSelectionContext = (text: string, paragraph: string, heading: string | null): string => {
    const parts = [`Selected passage: «${text}»`]
    if (paragraph && paragraph !== text) {
        parts.push(`Within paragraph: «${paragraph}»`)
    }
    if (heading) {
        parts.push(`Under section: «${heading}»`)
    }
    return parts.join(". ")
}

/**
 * "Ask AI about this passage" floating action — the entry point for the
 * selection-anchored content-AI flow. Watches for a text selection INSIDE any
 * readable region marked `[data-ai-selectable]` (lesson body, foundation body,
 * task brief, challenge brief); when one settles it shows a small button
 * above the highlight. Pressing it stashes the passage in the overlay store and
 * opens the ask-AI chat ({@link import("./../ContentAiChat").ContentAiChat} reads
 * the passage to scope the next question). Mounted once by the learn layout,
 * alongside {@link import("./../ContentAiFab").ContentAiFab}.
 */
export const ContentAiSelectionAsk = () => {
    const t = useTranslations()
    const { open } = useContentAiChatOverlayState()
    const { setSelection } = useContentAiSelection()
    const [anchor, setAnchor] = useState<SelectionAnchor | null>(null)
    // portal target only exists on the client
    const [mounted, setMounted] = useState(false)
    useEffect(() => setMounted(true), [])

    // first-discovery flag: the button wears a "New" tag until the learner uses
    // it once (or dismisses the inline tip) — see hintStore / SelectionHintCallout
    const seen = useSelectionHintStore((state) => state.seen)
    const hydrate = useSelectionHintStore((state) => state.hydrate)
    const markSeen = useSelectionHintStore((state) => state.markSeen)
    useEffect(() => hydrate(), [hydrate])

    // recompute the button anchor when a selection settles inside a selectable region
    const onSettle = useCallback(() => {
        const selection = window.getSelection()
        if (!selection || selection.isCollapsed || selection.rangeCount === 0) {
            setAnchor(null)
            return
        }
        const range = selection.getRangeAt(0)
        // the selection must land inside a marked reading region ([data-ai-selectable])
        const region = containingSelectable(range.commonAncestorContainer)
        if (!region) {
            setAnchor(null)
            return
        }
        const text = selection.toString().trim()
        if (text.length < MIN_CHARS) {
            setAnchor(null)
            return
        }
        const rect = range.getBoundingClientRect()
        if (rect.width === 0 && rect.height === 0) {
            setAnchor(null)
            return
        }
        // capture the surrounding paragraph + section so a SHORT selection still
        // gives the model enough to reason about (sent hidden, not shown in the UI)
        const block = containingBlock(range.commonAncestorContainer)
        const paragraph = (block?.textContent ?? "").trim().slice(0, MAX_CONTEXT)
        const heading = nearestHeading(block, region)
        const cappedText = text.slice(0, MAX_CHARS)
        setAnchor({
            x: rect.left + rect.width / 2,
            y: rect.top,
            text: cappedText,
            context: buildSelectionContext(cappedText, paragraph, heading),
        })
    }, [])

    useEffect(() => {
        // show on settle (mouse/touch release); hide when the selection collapses
        // (click elsewhere) or the page scrolls (the anchor would drift)
        const onSelectionChange = () => {
            const selection = window.getSelection()
            if (!selection || selection.isCollapsed) {
                setAnchor(null)
            }
        }
        const onScroll = () => setAnchor(null)
        document.addEventListener("mouseup", onSettle)
        document.addEventListener("touchend", onSettle)
        document.addEventListener("selectionchange", onSelectionChange)
        window.addEventListener("scroll", onScroll, true)
        window.addEventListener("resize", onScroll)
        return () => {
            document.removeEventListener("mouseup", onSettle)
            document.removeEventListener("touchend", onSettle)
            document.removeEventListener("selectionchange", onSelectionChange)
            window.removeEventListener("scroll", onScroll, true)
            window.removeEventListener("resize", onScroll)
        }
    }, [onSettle])

    /**
     * Stash the passage + the learner's choice, then open the chat.
     * `forceNewThread=false` ("Ask in this chat", the default/primary action) —
     * `ContentAiChat` appends the quoted question into whichever conversation is
     * already active (or starts a plain new one if none is). `forceNewThread=true`
     * ("New thread") always forks a fresh born-archived side-conversation, even
     * over an already-active one — the app-wide chat's escape hatch for "this is
     * a quick tangent, don't drop it into my real conversation".
     */
    const onAsk = useCallback((forceNewThread: boolean) => {
        if (!anchor) {
            return
        }
        setSelection(anchor.text, anchor.context, forceNewThread)
        markSeen()
        open()
        window.getSelection()?.removeAllRanges()
        setAnchor(null)
    }, [anchor, setSelection, markSeen, open])

    if (!mounted || !anchor) {
        return null
    }

    return createPortal(
        // non-interactive positioning wrapper; onMouseDown only prevents the browser from collapsing
        // the text selection before the real (keyboard-accessible) Buttons' press fires
        // eslint-disable-next-line jsx-a11y/no-static-element-interactions -- see reason above
        <div
            // keep the selection alive when pressing a button (mousedown would
            // otherwise collapse it before the click fires)
            onMouseDown={(event) => event.preventDefault()}
            className="z-[70] flex flex-col gap-1"
            style={{
                position: "fixed",
                left: anchor.x,
                top: Math.max(8, anchor.y - 8),
                transform: "translate(-50%, -100%)",
            }}
        >
            {/* PRIMARY — appends into whatever conversation is already active (the
                app-wide default); SECONDARY — explicitly forks a fresh, hidden
                side-thread for this quote instead. */}
            <Button size="sm" variant="primary" onPress={() => onAsk(false)} className="shadow-lg">
                <SparkleIcon className="size-4" />
                {t("contentAi.askInThisChat")}
                {!seen ? (
                    <span className="rounded-full bg-surface px-2 py-0 text-[11px] font-medium text-accent-soft-foreground">
                        {t("contentAi.new")}
                    </span>
                ) : null}
            </Button>
            <Button size="sm" variant="secondary" onPress={() => onAsk(true)} className="shadow-lg">
                <ChatCircleIcon className="size-4" />
                {t("contentAi.newThread")}
            </Button>
        </div>,
        document.body,
    )
}

import { InputTextarea } from "@/components/atoms/forms"
import React, { useState } from "react"
import { Avatar } from "@/components/atoms/display/Avatar"
import { Button } from "@/components/atoms/buttons/Button"

import { InputButtonLike } from "@/components/composites/buttons/InputButtonLike"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * BLOCK — `ContentCommentComposer`: the textarea + submit control for new
 * comments, replies, and edits — ONE component, three call shapes, ported
 * verbatim from real `src`'s `CommentComposer`. See the component's own file
 * header for why `variant="primary"` (real `Discussion` is frameless — no
 * card ever wraps this field) and why the avatar-led row is top-level only.
 *
 * LEAVES by STRUCTURE (§14d.2). Collapsed-pill vs expanded-field is a real
 * node swap => separate leaves. Avatar present/absent is also a node swap
 * (top-level vs reply/edit) => its own leaf.
 */

/** Minimal identity for the avatar-led top-level composer. */
export interface ContentCommentComposerViewer {
    username: string
    avatarUrl?: string
}

/** Props for {@link ContentCommentComposer}. */
export interface ContentCommentComposerProps {
    /** Called with the trimmed body when the reader submits a non-empty comment. */
    onSubmit: (body: string) => void
    /** Placeholder text for the field. */
    placeholder?: string
    /** Submit button label. */
    submitLabel?: string
    /** Optional cancel handler — renders a cancel button when provided (reply/edit). */
    onCancel?: () => void
    /** Initial field value (editing an existing comment). */
    initialValue?: string
    /** `true` -> submit is disabled and shows its busy affordance. */
    isPending?: boolean
    /**
 * Set -> the composer is avatar-led (top-level only; reply/edit omit this).
 * `null` -> signed-out top-level composer, no avatar.
 */
    currentUser?: ContentCommentComposerViewer | null
    /**
 * `true` -> starts collapsed as a slim avatar + placeholder pill, expands to
 * the full field on click (the top-level composer pattern). Reply/edit
 * composers omit this and render expanded.
 */
    collapsible?: boolean
    /** Accessible name for the field. */
    ariaLabel: string
    /** Where this sits inside its parent (placement only, e.g. `flex-1` beside a `ThreadConnector`). */
    classNames?: Array<AllowedClassName>
}

/**
 * The comment/reply/edit composer. See the file header for the full contract.
 *
 * @param props - {@link ContentCommentComposerProps}
 */
const ContentCommentComposer = ({
    onSubmit: onSubmitAction,
    placeholder = "Ask a question or share your thoughts…",
    submitLabel = "Post",
    onCancel: onCancelAction,
    initialValue,
    isPending = false,
    currentUser,
    collapsible = false,
    ariaLabel,
    classNames,
}: ContentCommentComposerProps) => {
    const [body, setBody] = useState(initialValue ?? "")
    // collapsible composers start closed; reply/edit always render expanded
    const [expanded, setExpanded] = useState(!collapsible)
    const trimmed = body.trim()

    const onSubmit = () => {
        if (!trimmed) {
            return
        }
        onSubmitAction(trimmed)
        setBody("")
        if (collapsible) {
            setExpanded(false)
        }
    }

    const onCancel = () => {
        setBody("")
        if (collapsible) {
            setExpanded(false)
        }
        onCancelAction?.()
    }

    // collapsed pill: avatar + placeholder, the whole row opens the composer
    if (collapsible && !expanded) {
        return (
            <StackH identity={{ tier: "block", component: "ContentCommentComposer" }}
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                align="center"

                items={[
                    ...(currentUser ? [() => (
                        <Avatar src={currentUser.avatarUrl} name={currentUser.username} seed={currentUser.username} size="sm" />
                    )] : []),
                    () => (
                        <div className="min-w-0 flex-1">
                            <InputButtonLike
                                placeholder={placeholder}
                                ariaLabel={ariaLabel}
                                onPress={() => setExpanded(true)}
                            />
                        </div>
                    ),
                ]}
            />
        )
    }

    const buttonRow = (
        <>
            <Button
                label={submitLabel}
                size="sm"
                onPress={onSubmit}
                isDisabled={!trimmed}
                isPending={isPending}

            />
            {onCancelAction || collapsible ? (
                <Button
                    label="Cancel"
                    variant="tertiary"
                    size="sm"
                    onPress={onCancel}
                    isDisabled={isPending}

                />
            ) : null}
        </>
    )

    const fieldColumn = (
        <>
            <InputTextarea
                value={body}
                onValueChange={setBody}
                placeholder={placeholder}
                ariaLabel={ariaLabel}
                rows={3}
                variant="primary"

            />
            <StackH gap={3} items={[() => buttonRow]} />
        </>
    )

    const composerRow = (
        <>
            {currentUser ? (
                <Avatar src={currentUser.avatarUrl} name={currentUser.username} seed={currentUser.username} size="sm" />
            ) : null}
            <StackV gap={3} classNames={["min-w-0", "flex-1"]} items={[() => fieldColumn]} />
        </>
    )

    return (
        <StackH identity={{ tier: "block", component: "ContentCommentComposer" }} gap={4} principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            align="start" classNames={classNames} items={[() => composerRow]}  />
    )
}

export { ContentCommentComposer }

import React, { useState } from "react"
import { SealCheckIcon } from "@phosphor-icons/react"
import { ThreadConnector } from "@/components/atoms/display/ThreadConnector"
import { Typography } from "@/components/atoms/text/Typography"
import { IdentityContentRow } from "@/components/composites/lists/IdentityContentRow"
import { StackH, StackV } from "@/components/frames/Stack"
import { ContentCommentComposer, type ContentCommentComposerViewer } from "@/components/blocks/learn/ContentCommentComposer"
import { ReactionButton, type ReactionType, type ReactionCount } from "@/components/blocks/learn/ReactionButton"

/**
 * BLOCK — `ContentCommentThread`: one threaded comment — author, reaction,
 * reply/edit/delete actions, and its recursively-rendered replies. Ported
 * verbatim from real `src`'s `CommentItem`. See the component's own file
 * header for the massive gap this fills against the earlier flat-list cut.
 *
 * 📐 LEAVES by STRUCTURE (§14d.2). Owner-only actions appearing, the body
 * swapping for an edit composer or a deleted placeholder, and the reply
 * subtree expanding each add/remove real nodes ⇒ separate leaves.
 */

/** Minimal identity for a comment's author. */
export interface ContentCommentAuthor {
    id: string
    username: string
    avatarUrl?: string
}

/** One comment (or, at `depth > 0`, one reply). */
export interface ContentCommentNode {
    /** Stable id — also what reply/edit/delete/react target. */
    id: string
    author: ContentCommentAuthor
    /** Already-formatted relative time, e.g. "2 hours ago". */
    createdTimeAgo: string
    /** `true` → a founder badge rides beside the author name. */
    isFounderAuthor?: boolean
    /** `true` → the body was edited after posting; shows a quiet "(edited)" marker. */
    isEdited?: boolean
    /** `true` → the body is replaced with a "removed" placeholder; no actions render. */
    isDeleted?: boolean
    /** The comment text (ignored when `isDeleted`). */
    body: string
    /** Total replies under this comment (drives the "view replies" toggle). */
    replyCount: number
    /** The viewer's own reaction on this comment, or `null`. */
    myReaction: ReactionType | null
    /** Per-emotion reaction counts on this comment. */
    reactionCounts?: ReadonlyArray<ReactionCount>
}

/** Callbacks shared down the comment tree — same shape at every depth. */
export interface ContentCommentThreadCallbacks {
    onReply: (parentId: string, body: string) => void
    onEdit: (commentId: string, body: string) => void
    onDelete: (commentId: string) => void
    onReactComment: (commentId: string, type: ReactionType | null) => void
    /** Lazily load a parent's replies — fired the first time its subtree expands. */
    onLoadReplies: (parentId: string) => void
}

/** Props for the module-scope {@link CommentByline} helper. */
interface CommentBylineProps {
    username: string
    isFounderAuthor?: boolean
    createdTimeAgo: string
    isEdited?: boolean
}

/**
 * `IdentityContentRow.byline` — a component reference (COMPOSITE-8), not a
 * built element. Kept at MODULE scope (not defined inline inside
 * `ContentCommentThread`'s body) and fed only read-only per-comment fields as
 * props, so passing a fresh wrapping arrow each render never risks remounting
 * anything stateful — there is no state in this leaf to lose.
 */
const CommentByline = ({ username, isFounderAuthor, createdTimeAgo, isEdited }: CommentBylineProps) => (
    <StackH
        gap={2}
        principle="separator-dot"
        explain="Places a middle-dot separator between short meta peers so the items read as one inline list."
        align="center"
        items={[
            () => (
                <StackH
                    gap={2}
                    principle="icon-text"
                    explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
                    align="center"
                    items={[
                        () => <Typography size="sm" weight="medium" text={username} />,
                        ...(isFounderAuthor ? [() => (
                            <SealCheckIcon weight="fill" aria-label="Founder" className="size-3.5 shrink-0 text-accent-soft-foreground" />
                        )] : []),
                    ]}
                />
            ),
            () => <Typography size="xs" color="muted" text={createdTimeAgo} />,
            ...(isEdited ? [() => (
                <Typography size="xs" color="muted" text="(edited)" />
            )] : []),
        ]}
    />
)

/** Props for {@link ContentCommentThread}. */
export interface ContentCommentThreadProps extends ContentCommentThreadCallbacks {
    /** The comment to render. */
    comment: ContentCommentNode
    /** Current viewer id — drives owner-only edit/delete; null when signed out. */
    currentUserId: string | null
    /**
     * Current viewer identity for the reply composer's own avatar (Facebook-style
     * nested reply) — `null`/omitted → reply composer renders with no avatar. Real
     * `CommentComposer` never shows one at all; this is a deliberate divergence, not
     * a `src` port.
     */
    currentUser?: ContentCommentComposerViewer | null
    /** Nesting depth — 0 for a top-level comment, `depth + 1` for each reply. */
    depth: number
    /** Already-loaded replies, keyed by parent id (empty until `onLoadReplies` resolves). */
    repliesByParent: Record<string, ReadonlyArray<ContentCommentNode>>
}

/**
 * One threaded comment. See the file header for the full contract.
 *
 * @param props - {@link ContentCommentThreadProps}
 */
const ContentCommentThread = ({
    comment,
    currentUserId,
    currentUser,
    depth,
    repliesByParent,
    onReply,
    onEdit,
    onDelete,
    onReactComment,
    onLoadReplies,
}: ContentCommentThreadProps) => {
    const [replying, setReplying] = useState(false)
    const [editing, setEditing] = useState(false)
    const [expanded, setExpanded] = useState(false)

    const isOwner = currentUserId !== null && currentUserId === comment.author.id
    const replies = repliesByParent[comment.id] ?? []

    const toggleReplies = () => {
        const next = !expanded
        setExpanded(next)
        if (next) {
            onLoadReplies(comment.id)
        }
    }

    // action row: reaction + reply + owner edit/delete. `isButton`, NOT `isLink` — real
    // src's own action links carry no underline at all, only a resting→hover COLOR
    // shift, which isLink's underline treatment would misrepresent.
    const actionRow = (
        <>
            <ReactionButton
                myReaction={comment.myReaction}
                counts={comment.reactionCounts}
                onReact={(type) => onReactComment(comment.id, type)}


            />
            <Typography
                size="xs"
                weight="medium"
                color="muted"
                isButton
                hoverColor="default"
                text="Reply"
                onPress={() => setReplying((prev) => !prev)}

            />
            {isOwner ? (
                <>
                    <Typography
                        size="xs"
                        weight="medium"
                        color="muted"
                        isButton
                        hoverColor="default"
                        text="Edit"
                        onPress={() => setEditing(true)}

                    />
                    <Typography
                        size="xs"
                        weight="medium"
                        color="muted"
                        isButton
                        hoverColor="danger"
                        text="Delete"
                        onPress={() => onDelete(comment.id)}

                    />
                </>
            ) : null}
        </>
    )

    const bodyAndActions = (
        <>
            {/* body, edit form, or deleted placeholder */}
            {comment.isDeleted ? (
                <Typography size="sm" color="muted" isItalic text="[Comment removed]" />
            ) : editing ? (
                <ContentCommentComposer
                    initialValue={comment.body}
                    submitLabel="Save"
                    ariaLabel="Edit comment"
                    onCancel={() => setEditing(false)}
                    onSubmit={(body) => {
                        onEdit(comment.id, body)
                        setEditing(false)
                    }}

                />
            ) : (
                <Typography size="sm" preserveWhitespace text={comment.body} />
            )}

            {!comment.isDeleted && !editing ? (
                <StackH gap={4} principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                    at="sm" align="center" items={[() => actionRow]}  />
            ) : null}
        </>
    )

    const threadBody = (
        <>
            <StackV gap={2} items={[() => bodyAndActions]} />

            {/* reply composer — `ThreadConnector` draws the Facebook-style curved
                guide from this comment down into the reply's own avatar;
                `currentUser` is what gives the composer an avatar to connect TO
                in the first place (see its own file header). */}
            {replying ? (
                <StackH
                    gap={2}
                    principle="icon-text"
                    explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
                    align="start"

                    items={[
                        () => <ThreadConnector />,
                        () => (
                            <ContentCommentComposer
                                placeholder="Write a reply..."
                                submitLabel="Reply"
                                ariaLabel="Write a reply"
                                currentUser={currentUser}
                                classNames={["min-w-0", "flex-1"]}
                                onCancel={() => setReplying(false)}
                                onSubmit={(body) => {
                                    onReply(comment.id, body)
                                    setReplying(false)
                                    setExpanded(true)
                                    onLoadReplies(comment.id)
                                }}

                            />
                        ),
                    ]}
                />
            ) : null}

            {/* replies toggle + recursive subtree */}
            {comment.replyCount > 0 ? (
                <Typography
                    size="xs"
                    weight="medium"
                    color="accent"
                    isLink
                    underlineOnHover
                    text={expanded ? "Hide replies" : `View ${comment.replyCount} replies`}
                    onPress={toggleReplies}

                />
            ) : null}

            {expanded && replies.length > 0 ? (
                <StackV
                    gap={4}

                    items={replies.map((reply) => () => (
                        <ContentCommentThread
                            comment={reply}
                            currentUserId={currentUserId}
                            currentUser={currentUser}
                            depth={depth + 1}
                            repliesByParent={repliesByParent}
                            onReply={onReply}
                            onEdit={onEdit}
                            onDelete={onDelete}
                            onReactComment={onReactComment}
                            onLoadReplies={onLoadReplies}

                        />
                    ))}
                />
            ) : null}
        </>
    )

    return (
        // `IdentityContentRow` (composite) owns the avatar+byline+column shape — both
        // its seams are `tight` ON PURPOSE, a denser standalone treatment, NOT a
        // `src`-fidelity port (see the composite's own file header). `nested` draws the
        // reply indent guide via the `Stack` frame prop.
        <IdentityContentRow
            avatarSrc={comment.author.avatarUrl}
            avatarName={comment.author.username}
            avatarSeed={comment.author.id}
            avatarSize="sm"
            nested={depth > 0}


            byline={() => (
                <CommentByline
                    username={comment.author.username}
                    isFounderAuthor={comment.isFounderAuthor}
                    createdTimeAgo={comment.createdTimeAgo}
                    isEdited={comment.isEdited}
                />
            )}
            // `body` is the former `children` slot (COMPOSITE-8) — a component
            // reference, not a built node. `threadBody` (StackV wrapping
            // bodyAndActions + reply composer + replies subtree) is already
            // computed above per the current render's state, so the wrapper here
            // only needs to hand it back.
            body={() => (
                /* `grouped` — separates [body+actions, tight together] from whatever
                    comes after a reply composer/toggle/subtree: the seam right before
                    a reply composer appears needs more
                    room than the tight identity block above it (also where the
                    Facebook-style connector line will run). */
                <StackV gap={4} items={[() => threadBody]} />
            )}
        />
    )
}

export { ContentCommentThread }

import React from "react"
import { ChatsCircleIcon, WarningCircleIcon } from "@phosphor-icons/react"
import { Button } from "@/components/atoms/buttons/Button"
import { Typography } from "@/components/atoms/text/Typography"
import { EmptyState } from "@/components/composites/feedback/EmptyState"
import { StackV } from "@/components/frames/Stack"
import { ContentCommentComposer, type ContentCommentComposerViewer } from "@/components/blocks/learn/ContentCommentComposer"
import { ContentCommentThread, type ContentCommentNode, type ContentCommentThreadCallbacks } from "@/components/blocks/learn/ContentCommentThread"

/**
 * `ContentDiscussion` — talk about this lesson: a label + archive line, an
 * avatar-led collapsible composer, and the threaded comment list, frameless on
 * the page canvas. The empty state is drawn on purpose — no comments yet is an
 * invitation. The composer never hides, and an error replaces the list only.
 * Comment count, archive line, and `hasMore` are states of `Full`; empty, error,
 * and the loading mirror are each their own leaf.
 */

/** Props for {@link ContentDiscussion}. */
export interface ContentDiscussionProps extends ContentCommentThreadCallbacks {
    /** Section label, localized by the caller — e.g. "Discussion" (the block appends "· {total}"). */
    label: string
    /** Current viewer id — drives owner-only edit/delete down the whole tree; null when signed out. */
    currentUserId: string | null
    /** Current viewer identity for the composer's avatar; null when signed out. */
    currentUser?: ContentCommentComposerViewer | null
    /** Top-level comments, newest first. EMPTY -> the invitation is drawn instead. */
    comments: Array<ContentCommentNode>
    /** Total top-level comment count (drives the label + the archive line). */
    total: number
    /** Replies keyed by parent comment id (lazily populated by the caller). */
    repliesByParent: Record<string, ReadonlyArray<ContentCommentNode>>
    /** Post a new top-level comment. */
    onSubmitComment: (body: string) => void
    /** `true` -> more top-level comment pages remain to load. */
    hasMore?: boolean
    /** `true` -> the next page is currently loading. */
    isLoadingMore?: boolean
    /** Load the next page of top-level comments. */
    onLoadMore?: () => void
    /**
 * Set -> the comment list could not be loaded. The message replaces the
 * LIST only: the composer stays, because a failed read did not remove
 * the ability to write.
 */
    errorMessage?: string
    /** `true` -> two placeholder threads mirror the real row shape while the first page loads. */
    isSkeleton?: boolean
}

/** Two placeholder rows so the mirror has the same shape as a short thread. */
const SKELETON_ROWS: Array<ContentCommentNode> = [
    { id: "s1", author: { id: "s1", username: "" }, createdTimeAgo: "", body: "", replyCount: 0, myReaction: null },
    { id: "s2", author: { id: "s2", username: "" }, createdTimeAgo: "", body: "", replyCount: 0, myReaction: null },
]

/**
 * Lesson discussion. See the file header for the full contract.
 *
 * @param props - {@link ContentDiscussionProps}
 */
const ContentDiscussion = ({
    label,
    currentUserId,
    currentUser,
    comments,
    total,
    repliesByParent,
    onSubmitComment,
    onReply,
    onEdit,
    onDelete,
    onReactComment,
    onLoadReplies,
    hasMore = false,
    isLoadingMore = false,
    onLoadMore,
    errorMessage,
    isSkeleton = false,
}: ContentDiscussionProps) => {
    // real (not fabricated) count of currently-loaded top-level comments that already
    // have at least one reply — under-counts before "load more" is exhausted, same
    // tradeoff real `Discussion` documents for its own archive line
    const answeredCount = comments.filter((comment) => comment.replyCount > 0).length

    // no icon here: a chat-bubble icon needs an ASSOCIATION step to read as
    // "discussion" (not a universal symbol like [ok]/(locked)), and the label text already
    // carries the full fact on its own.
    const labelLines = (
        <>
            {isSkeleton ? (
                <Typography weight="medium" isSkeleton />
            ) : (
                <Typography weight="medium" text={`${label} · ${total}`} />
            )}
            {isSkeleton || total > 0 ? (
                <Typography
                    size="xs"
                    color="muted"
                    isSkeleton={isSkeleton}
                    text={`${answeredCount}/${total} questions answered, accumulated over time`}

                />
            ) : null}
        </>
    )

    const discussionHeader = (
        <>
            <StackV gap={2} isSkeleton={isSkeleton} items={[() => labelLines]} />
            <ContentCommentComposer
                onSubmit={onSubmitComment}
                currentUser={currentUser}
                collapsible
                ariaLabel="Write a comment"


            />
        </>
    )

    const commentList = (
        <>
            {(isSkeleton ? SKELETON_ROWS : comments).map((comment) => (
                <ContentCommentThread
                    key={comment.id}
                    comment={comment}
                    currentUserId={currentUserId}
                    currentUser={currentUser}
                    depth={0}
                    repliesByParent={repliesByParent}
                    onReply={onReply}
                    onEdit={onEdit}
                    onDelete={onDelete}
                    onReactComment={onReactComment}
                    onLoadReplies={onLoadReplies}

                />
            ))}
            {!isSkeleton && hasMore ? (
                <Button
                    variant="ghost"
                    size="sm"
                    classNames={["self-center"]}
                    label={isLoadingMore ? "Loading…" : "Show more comments"}
                    isDisabled={isLoadingMore}
                    onPress={onLoadMore}
                />
            ) : null}
        </>
    )

    const discussionBody = (
        <>
            {/* These 3 seams match the real-src `Discussion/index.tsx:98-114` exactly:
 [label+archive]<->composer = grouped (gap-3) · [icon+label]<->archive-line
 = tight (gap-1) · icon<->label = related (gap-2). */}
            <StackV gap={4} isSkeleton={isSkeleton} items={[() => discussionHeader]} />

            {errorMessage != null ? (
                <EmptyState
                    icon={WarningCircleIcon}
                    title={errorMessage}

                />
            ) : !isSkeleton && comments.length === 0 ? (
                // Nobody has written yet. This is an INVITATION, so it is drawn —
                // hiding the section would hide the invitation with it.
                <EmptyState
                    icon={ChatsCircleIcon}
                    title="No discussion yet"
                    description="Ask the first question about this lesson"

                />
            ) : (
                <StackV gap={4} isSkeleton={isSkeleton} items={[() => commentList]} />
            )}
        </>
    )

    return (
        <div>
            <StackV gap={4} isSkeleton={isSkeleton} items={[() => discussionBody]} />
        </div>
    )
}

export { ContentDiscussion }

"use client"

import React, {
    useMemo,
} from "react"
import {
    useTranslations,
} from "next-intl"
import { AccordionSkeleton } from "@/components/blocks/skeleton/AccordionSkeleton"
import { SkeletonText } from "@/components/blocks/skeleton/SkeletonText"
import type {
    WithClassNames,
} from "@/modules/types/base/class-name"

/** Number of placeholder modules shown while the content-map loads. */
const SKELETON_MODULE_COUNT = 3

/** Props for {@link ContentMapSkeleton}. */
export type ContentMapSkeletonProps = WithClassNames<undefined>

/**
 * Loading placeholder for {@link import("../").ContentMap}: mirrors the
 * {@link OutlineRail} accordion — collapsed module rows (title bar + indicator)
 * with only the first expanded to show its lesson lines — via
 * {@link AccordionSkeleton}, matching its sibling {@link MilestoneOutlineSkeleton}
 * so the rail does not jump when the outline arrives.
 *
 * @param props - {@link ContentMapSkeletonProps}
 */
export const ContentMapSkeleton = ({ className }: ContentMapSkeletonProps) => {
    const t = useTranslations()
    const items = useMemo(
        () => Array.from({ length: SKELETON_MODULE_COUNT }, (_, index) => ({
            ariaLabel: t("module.aria", { index: index + 1 }),
            expanded: index === 0,
            titleSize: "base" as const,
            showIndicator: true,
        })),
        [t],
    )
    const renderExpandedBody = useMemo(
        () => () => (
            <div className="flex flex-col gap-2">
                <SkeletonText size="sm" className="w-3/4" />
                <SkeletonText size="xs" className="w-full" />
                <SkeletonText size="xs" className="w-3/4" />
            </div>
        ),
        [],
    )
    return (
        <AccordionSkeleton
            className={className}
            items={items}
            renderExpandedBody={renderExpandedBody}
        />
    )
}

"use client"

import React, {
    useCallback,
    useEffect,
    useMemo,
    useState,
} from "react"
import {
    Typography,
} from "@heroui/react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import {
    pathConfig,
} from "@/resources/path"
import { useAppSelector } from "@/redux/hooks"
import { useQueryMyCourseOutlineSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyCourseOutlineSwr"
import { OutlineRail } from "@/components/blocks/navigation/OutlineRail"
import type { OutlineRailGroup } from "@/components/blocks/navigation/OutlineRail"
import type { MyCourseOutlineModule } from "@/modules/api/graphql/queries/types/my-course-outline"

/**
 * Filter modules + their lessons by a lower-cased query (module title match keeps
 * all its lessons; otherwise only matching lessons survive). Empty query → unchanged.
 *
 * @param modules - The course's modules.
 * @param query - Lower-cased trimmed search query.
 * @returns The filtered modules.
 */
const filterModules = (
    modules: Array<MyCourseOutlineModule>,
    query: string,
): Array<MyCourseOutlineModule> => {
    if (!query) {
        return modules
    }
    const result: Array<MyCourseOutlineModule> = []
    for (const module of modules) {
        const moduleMatches = module.title.toLowerCase().includes(query)
        const lessons = moduleMatches
            ? module.lessons
            : module.lessons.filter((lesson) => lesson.title.toLowerCase().includes(query))
        if (moduleMatches || lessons.length > 0) {
            result.push({ ...module, lessons })
        }
    }
    return result
}

/**
 * Content-map rail — the lean docs-style course navigation tree shown to the left
 * while reading (module → lesson, read/premium markers, a progress header with a
 * "continue" action). A thin data wrapper: owns the `myCourseOutline` SWR + Redux
 * selection + routing + the controlled search/expand state, and renders the shared
 * {@link OutlineRail} block (which owns the look it shares with the personal-project
 * milestone rail).
 *
 * Positioning (sticky / width / scroll) is owned by the learn shell's
 * {@link FillAvailable} wrapper on desktop and the mobile drawer on small screens.
 */
export const ContentMap = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const courseId = useAppSelector((state) => state.course.id)
    const displayId = useAppSelector((state) => state.course.displayId)
    const activeContentId = useAppSelector((state) => state.content.id)

    const outlineSwr = useQueryMyCourseOutlineSwr(courseId ?? null)
    const outline = outlineSwr.data

    const [search, setSearch] = useState("")
    const query = search.trim().toLowerCase()
    const modules = useMemo(
        () => (outline ? filterModules(outline.modules, query) : []),
        [outline, query],
    )

    /** Module owning the active lesson — expanded on first paint. */
    const activeModuleId = useMemo(() => {
        if (!outline || !activeContentId) {
            return undefined
        }
        return outline.modules.find((module) =>
            module.lessons.some((lesson) => lesson.id === activeContentId))?.id
    }, [outline, activeContentId])

    /**
     * Expanded modules (controlled) — only the open module shows its read-progress
     * bar; collapsed ones show a compact "n/m" count instead. The active lesson's
     * module auto-opens; a search opens every matching module so hits are visible.
     */
    const [expandedKeys, setExpandedKeys] = useState<Set<string>>(new Set())
    useEffect(() => {
        if (!activeModuleId) {
            return
        }
        setExpandedKeys((prev) => prev.has(activeModuleId) ? prev : new Set(prev).add(activeModuleId))
    }, [activeModuleId])
    useEffect(() => {
        if (query) {
            setExpandedKeys(new Set(modules.map((module) => module.id)))
        }
    }, [query, modules])

    const progress = outline?.progress
    const currentTask = outline?.currentTask

    /**
     * Route for the "continue" button from `currentTask`. Lessons route straight to
     * their content; challenges route to the owning lesson's challenges tab. Milestone
     * tasks have no rail route yet → null (button hidden).
     */
    const continueHref = useMemo(() => {
        if (!outline || !currentTask || !displayId) {
            return null
        }
        const base = (moduleId: string, contentId: string) =>
            pathConfig().locale(locale).course(displayId).learn().module(moduleId).content(contentId).build()
        if (currentTask.kind === "lesson") {
            const owner = outline.modules.find((module) =>
                module.lessons.some((lesson) => lesson.id === currentTask.id))
            return owner ? base(owner.id, currentTask.id) : null
        }
        if (currentTask.kind === "challenge") {
            for (const module of outline.modules) {
                const lesson = module.lessons.find((item) =>
                    item.challenges.some((challenge) => challenge.id === currentTask.id))
                if (lesson) {
                    return `${base(module.id, lesson.id)}?tab=challenges`
                }
            }
        }
        return null
    }, [outline, currentTask, displayId, locale])

    /** Jump to the viewer's current task. */
    const onContinue = useCallback(() => {
        if (continueHref) {
            router.push(continueHref)
        }
    }, [continueHref, router])

    /** Navigate to the chosen lesson within its module. */
    const onSelectLesson = useCallback(
        (lessonId: string, moduleId: string) => {
            if (!displayId) {
                return
            }
            router.push(
                pathConfig().locale(locale).course(displayId).learn().module(moduleId).content(lessonId).build(),
            )
        },
        [router, locale, displayId],
    )

    /** Navigate to the dedicated module page (title press — caret still toggles). */
    const onOpenModule = useCallback(
        (moduleId: string) => {
            if (!displayId) {
                return
            }
            router.push(
                pathConfig().locale(locale).course(displayId).learn().module(moduleId).build(),
            )
        },
        [router, locale, displayId],
    )

    /** modules → milestone-agnostic rail groups (read markers, minutes meta). */
    const groups = useMemo<Array<OutlineRailGroup>>(
        () => modules.map((module) => {
            const readCount = module.lessons.filter((lesson) => lesson.isRead).length
            return {
                id: module.id,
                title: module.title,
                progress: { done: readCount, total: module.lessons.length },
                collapsedCountLabel: t("courseContents.moduleLessons", {
                    read: readCount,
                    total: module.lessons.length,
                }),
                onTitlePress: () => onOpenModule(module.id),
                items: module.lessons.map((lesson) => ({
                    id: lesson.id,
                    title: lesson.title,
                    isActive: lesson.id === activeContentId,
                    isRead: lesson.isRead,
                    isPremium: lesson.isPremium,
                    meta: (
                        <Typography type="body-xs" color="muted">
                            {t("content.minutesShort", { minutes: lesson.minutesRead })}
                        </Typography>
                    ),
                    onPress: () => onSelectLesson(lesson.id, module.id),
                })),
            }
        }),
        [modules, activeContentId, onSelectLesson, onOpenModule, t],
    )

    return (
        <OutlineRail
            header={progress ? {
                label: t("courseContents.progress"),
                progress: { done: progress.lessonsRead, total: progress.lessonsTotal },
                countLabel: t("courseContents.contentCount", {
                    read: progress.lessonsRead,
                    total: progress.lessonsTotal,
                }),
                // only when you've navigated AWAY from your current task — hide it while
                // you're already reading that task (the button would just point at this page).
                continue: continueHref && currentTask?.id !== activeContentId ? {
                    label: t("courseContents.resume"),
                    onPress: onContinue,
                } : undefined,
            } : undefined}
            search={{
                value: search,
                onChange: setSearch,
                placeholder: t("courseContents.searchPlaceholder"),
                ariaLabel: t("courseContents.searchAria"),
            }}
            groups={groups}
            expandedKeys={expandedKeys}
            onExpandedChange={setExpandedKeys}
            isSkeleton={!outlineSwr.data && !outlineSwr.error}
            async={{
                isEmpty: !outline,
                emptyTitle: t("courseContents.empty"),
                errorTitle: t("courseContents.error"),
                error: !outlineSwr.data ? outlineSwr.error : undefined,
                onRetry: () => { void outlineSwr.mutate() },
                retryLabel: t("courseContents.retry"),
                noMatchLabel: t("courseContents.noMatch"),
            }}
        />
    )
}

export default ContentMap

import React from "react"
import { LockSimpleIcon } from "@phosphor-icons/react"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { Typography } from "@/components/atoms/text/Typography"
import { StackV } from "@/components/frames/Stack"

/**
 * `ContentRelatedList` — what else in this course is worth reading after this
 * lesson: a quiet list, never a call to action. Self-hides with nothing related
 * — no card, no label, no empty state (the opposite of `ContentDiscussion`).
 * `breadcrumb` shows a course trail above the title; `isLocked` adds a quiet
 * lock line below. Row count is a state of `Full`; hidden, `isSkeleton`, and a
 * locked row are each their own leaf.
 */

/** One related lesson — plain data, the block builds the row. */
export interface ContentRelatedItem {
    /** Stable React key. */
    key: string
    /** Lesson title. */
    title: string
    /** Course trail this result belongs to, e.g. "Containerization · Docker". Omitted → no line above the title. */
    breadcrumb?: string
    /** `true` → the viewer must enrol to open this result; a quiet lock line replaces any snippet. */
    isLocked?: boolean
    /** Where the row navigates. */
    href: string
}

/** Props for {@link ContentRelatedList}. */
export interface ContentRelatedListProps {
    /**
     * The related lessons. EMPTY → the block renders nothing at all, which is the
     * ordinary case for a course with one lesson on a subject.
     */
    items: Array<ContentRelatedItem>
    /**
     * Section label, localized by the caller (blocks carry no i18n) — e.g.
     * "You might also want to read".
     */
    label: string
    /** Accessible text for the lock line, e.g. "Enroll to unlock". */
    enrollToOpenLabel?: string
    /**
     * `true` → the list draws its own row mirror. Kept even though the block
     * self-hides when empty: during the fetch we do not yet KNOW it is empty, and
     * hiding first then appearing would push the page down under the reader.
     */
    isSkeleton?: boolean
}

/**
 * One related-lesson row's content — extracted because it depends on the loop
 * variable (`item`) and so cannot be hoisted to a module-level const.
 */
const relatedItemBody = (item: ContentRelatedItem, enrollToOpenLabel: string) => (
    <>
        {item.breadcrumb ? (
            <Typography size="xs" color="muted" truncate text={item.breadcrumb} />
        ) : null}
        <Typography
            size="sm"
            weight="medium"
            truncate
            text={item.title}
            underlineOnGroupHover

        />
        {item.isLocked ? (
            <Typography size="xs" color="warning" prefixIcon={LockSimpleIcon} text={enrollToOpenLabel} />
        ) : null}
    </>
)

/**
 * Related-reading list under a lesson. See the file header for the full contract.
 *
 * @param props - {@link ContentRelatedListProps}
 */
const ContentRelatedList = ({
    items,
    label,
    enrollToOpenLabel = "Enroll to unlock",
    isSkeleton = false,
}: ContentRelatedListProps) => {
    // Nothing related ⇒ draw nothing. Deliberately BEFORE the skeleton check is
    // false: while loading we do not know yet, so the mirror still shows.
    if (!isSkeleton && items.length === 0) {
        return null
    }

    const rows: Array<SurfaceCardListItem> = items.map((item) => ({
        key: item.key,
        href: item.href,
        // Row-as-link: hover underlines the title itself, never a full-row fill —
        // matches the real row's own affordance (no accent, no arrow).
        hover: "underline",
        content: () => (
            <StackV gap={2} isSkeleton={isSkeleton} items={[() => relatedItemBody(item, enrollToOpenLabel)]} />
        ),
    }))

    return (
        <div>
            <SurfaceCardList
                label={label}
                items={rows}
                isSkeleton={isSkeleton}

            />
        </div>
    )
}

export { ContentRelatedList }

/** CTA label — a design CONSTANT, not opened to the caller (§14d.1). */
export const CTA_LABEL = "Continue"

/** Data shared by both members — ALL DATA props, no presentation props. */
export interface ContinueCardDataProps {
    /** Name of the thing in progress (course / chapter / lesson / interview session). */
    title: string
    /** Secondary line under the title — shows when there is NO `meta`/`timeLeft`. */
    subtitle?: string
    /** Current progress. `ProgressMeter` only appears when this prop is present. */
    value?: number
    /** The 100% mark. Default `100`. */
    max?: number
    /** Neutral meta fragments, joined by a dot (e.g. `["Question 7 / 8", "Middle"]`). */
    meta?: Array<string>
    /** Time left — ALWAYS renders as a chip, so the same kind of information always takes the same shape. */
    timeLeft?: string
    /** `true` → the `timeLeft` chip switches to `warning` tone. Only the TONE changes, not the element type. */
    urgent?: boolean
    /** Press handler. */
    onPress?: () => void
    /**
     * Navigation target — ONLY `.Item` can use it (its CTA is `LinkSeeMore`, a real link).
     *
     * ⚠️ `.Hero` does NOT accept it: its CTA is `Button`, and the Button atom
     * **has no `href`** (it's a button, not a link). The old version dodged this by
     * hand-rolling a `<Link>` styled to look like a button — exactly the drift being
     * cleaned up here, so it's dropped. `.Hero` navigates via `onPress` (the caller
     * does its own router-push); opening `href` for the button is work for the ATOM
     * tier, not a patch here.
     */
    href?: string
    /**
     * `true` → mirror shimmer INSTEAD of waiting for data. Applies to BOTH members
     * (`.Hero`/`.Item`) since both share `ContinueCardDataProps`.
     *
     * The flag FLOWS DOWN to the atom wherever an atom already has `isSkeleton`
     * (`Typography` for the title, `Button` for `.Hero`'s CTA, `SurfaceCard` for the card face).
     *
     * ⚠️ THREE spots in this tree have NO atom to take the flag, and the
     * scaffold/atom holding them sit OUTSIDE the 4 files touched this round (do not touch):
     *   • the meta/subtitle row goes through scaffold `ListMeta` — no `isSkeleton` yet;
     *   • `ProgressMeter` (scaffold) — no `isSkeleton` yet;
     *   • `.Item`'s CTA goes through atom `LinkSeeMore` — no `isSkeleton` yet.
     * Those three spots are TEXT/SHAPE rendered directly by CardBody/`.Item` (calling
     * the scaffold/atom straight, no layer in between), so they build their own
     * shimmer bar RIGHT HERE per the §12c rule, instead of branching off to build a
     * parallel skeleton tree for the whole `ContinueCard`.
     */
    isSkeleton?: boolean
    /** The part name of THIS card itself (§11a). */
}

/** Props for {@link ContinueCardHero}. */
export type ContinueCardHeroProps = ContinueCardDataProps

/** Props for {@link ContinueCardItem}. */
export type ContinueCardItemProps = ContinueCardDataProps

import React from "react"
import { PageHeader } from "@/components/composites/layout/Page"
import { type SkeletonProps } from "@/components/frames/_slot"
import { Breadcrumbs } from "@/components/atoms/navigation/Breadcrumbs"
import { Typography } from "@/components/atoms/text/Typography"

/**
 * `CourseBrief` — the course-identity cluster atop a page. It takes crumb DATA
 * (`breadcrumbItems`) and builds the `Breadcrumbs` atom itself, so a screen
 * never holds the `PageHeader` frame or the atom directly. Meta is a muted text
 * strip joined by `·`, not a chip. The two leaves lose a node; a long trail only
 * changes the crumb count, so it is a state.
 */

/** One breadcrumb link — plain data, the block builds the atom from it. */
export interface CourseBriefCrumb {
    /** React key. */
    key: string
    /** Display label. */
    label: string
    /** Has a handler → crumb is pressable; the last crumb (current page) leaves it out. */
    onPress?: () => void
}

/** Props for {@link CourseBrief}. */
export interface CourseBriefBaseProps {
    /** Breadcrumb trail as DATA — the block builds `Breadcrumbs` itself. */
    breadcrumbItems?: Array<CourseBriefCrumb>
    /** Course name. */
    title: string
    /** One-sentence course description. */
    description?: string
    /**
     * ⛔ NO pre-formatted `meta` string prop.
     * Passing `meta="8 modules · ~14h · 2,481 learners"` is **breaking the
     * structure**: the caller ends up deciding the join, units, and separator —
     * the block loses ownership of its own shape. Below are separate NUMBER
     * fields; the block joins them itself into a muted strip separated by `·`.
     */
    moduleCount?: number
    /** Total learning hours (rounded) — the block adds `~` and the "hours" word itself. */
    hours?: number
    /** Number of enrolled learners — the block formats the thousands separator itself. */
    learnerCount?: number
    /**
     * `true` → the cluster switches to a mirror shimmer INSTEAD OF waiting for
     * data — the flag FLOWS DOWN to the actual text-rendering atoms/frames
     * (`PageHeader`/`Breadcrumbs`/`Typography`), not a parallel skeleton tree
     * (§12c). `PageHeader` owns `isSkeleton` itself now (it swaps
     * `title`/`description` to shimmer internally), so this block just
     * forwards the flag straight through.
     */
    isSkeleton?: boolean
}

/**
 * Course identity cluster at the top of a page. See the file header for the
 * full contract.
 *
 * @param props - {@link CourseBriefBaseProps}
 */
const CourseBriefBase = ({
    breadcrumbItems,
    title,
    description,
    moduleCount,
    hours,
    learnerCount,
    isSkeleton = false,
}: CourseBriefBaseProps) => {
    // Meta strip joined by the BLOCK from NUMBERS — units, separators, thousands
    // grouping are all presentation; the caller doesn't touch this (§14d.1).
    const metaParts = [
        moduleCount != null ? `${moduleCount} modules` : null,
        hours != null ? `~${hours} hours` : null,
        learnerCount != null ? `${learnerCount.toLocaleString("vi-VN")} learners` : null,
    ].filter(Boolean)

    return (
        // Identity hold: PageHeader does not accept CallerIdentity (ledger PageHeader gap).
        <PageHeader
            isSkeleton={isSkeleton}
            breadcrumb={
                breadcrumbItems?.length
                    ? ({ isSkeleton: skeleton }: SkeletonProps) => (
                        // Hold: no hug-width frame for breadcrumb measure (`w-fit` parent placement).
                        <div className="w-fit">
                            {/* collapse: below @app-sm or trail ≥ 4 crumbs → back-link (the old
                        capability of ResponsiveBreadcrumb, now a prop of the Breadcrumbs atom). */}
                            <Breadcrumbs
                                collapseOnMobile
                                collapseFrom={4}
                                items={breadcrumbItems ?? []}
                                isSkeleton={skeleton}
                            />
                        </div>
                    )
                    : undefined
            }
            title={title}
            description={description}
            meta={
                metaParts.length > 0
                    ? () => (
                        <Typography size="xs" color="muted" text={metaParts.join(" · ")} />
                    )
                    : undefined
            }
        />
    )
}

/** `CourseBrief.*` — single-component namespace ⇒ only `.Base`. */
export { CourseBriefBase as CourseBrief }

import React from "react"
import { Breadcrumbs } from "@/components/atoms/navigation/Breadcrumbs"
import { PageHeader } from "@/components/composites/layout/Page"

/**
 * BLOCK — `CourseQaHeader`: the PAGE-IDENTITY cluster at the top of a course
 * Q&A screen — trail, title, description, nothing else.
 *
 * SIBLING OF `LeaderboardHeader`/`FoundationsHeader`, NOT A COPY. Every ported
 * screen wraps `PageHeader` in its own domain-named block rather than the
 * screen touching the composite directly (rule 1). This board carries no meta
 * row for the same reason `LeaderboardHeader` doesn't: the facts (question
 * count, filter, sort) live in the honest-strip/toolbar below, not the header.
 */

/** One breadcrumb link — plain data, the block builds the atom from it. */
export interface CourseQaHeaderCrumb {
    /** Stable React key. */
    key: string
    /** Display label. */
    label: string
    /** Has a handler → the crumb is pressable; the current page leaves it out. */
    onPress?: () => void
}

/** Props for {@link CourseQaHeader}. */
export interface CourseQaHeaderProps {
    /** Breadcrumb trail as DATA — the block builds `Breadcrumbs` itself. */
    breadcrumbItems?: Array<CourseQaHeaderCrumb>
    /** Page title, e.g. "Q&A". */
    title: string
    /** One-sentence description of what this Q&A board is for. */
    description?: string
    /**
     * `true` → every composed atom switches to its own shimmer. The flag FLOWS
     * DOWN into the real atoms rather than building a parallel skeleton tree
     * (§12c), so the shimmer keeps the exact box of the thing it replaces.
     */
    isSkeleton?: boolean
}

/**
 * Course Q&A page identity — trail, title, description. See the file header
 * for why this stays a thin sibling of `LeaderboardHeader`/`FoundationsHeader`
 * rather than a fresh idea.
 *
 * @param props - {@link CourseQaHeaderProps}
 */
const CourseQaHeader = ({
    breadcrumbItems,
    title,
    description,
    isSkeleton = false,
}: CourseQaHeaderProps) => {
    return (
        // Identity hold: PageHeader does not accept CallerIdentity (ledger PageHeader gap).
        <PageHeader
            isSkeleton={isSkeleton}
            breadcrumb={() =>
                isSkeleton || breadcrumbItems?.length ? (
                    // Hold: no hug-width frame for breadcrumb measure (`w-fit` parent placement).
                    <div className="w-fit">
                        <Breadcrumbs
                            collapseOnMobile
                            collapseFrom={4}
                            items={breadcrumbItems ?? []}
                            isSkeleton={isSkeleton}
                        />
                    </div>
                ) : undefined
            }
            title={title}
            description={description}
        />
    )
}

export { CourseQaHeader }

import React from "react"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Avatar } from "@/components/atoms/display/Avatar"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { StackV, StackH } from "@/components/frames/Stack"

/**
 * One placeholder row for the Loading branch — avatar + 2 text bars +
 * chip-pill row + status dot, ported verbatim from the real
 * `CourseQaSkeleton.tsx` shape (*1).
 *
 * `align="start"` on the outer row (instead of the real file's `mt-2` on the
 * dot) top-aligns all three children without a child pushing its own margin
 * (§10a — the padding gate only allows a parent's `gap`/surface `padding` to
 * own a seam).
 */
export const SkeletonQuestionRow = () => {
    return (
        <StackH
            identity={{ tier: "block", component: "SkeletonQuestionRow" }}
            gap={4}
            principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            align="start"
            items={[
                () => (
                    <Avatar isSkeleton size="sm" />
                ),
                () => (
                    <StackV
                        gap={2}
                        classNames={["min-w-0", "flex-1"]}
                        principle="sibling-stack"
                        explain="Same-kind peer stack of asker line, preview, and chip row — not group-boundary, because these are repeating row sections rather than labelled groups."
                        items={[
                            // asker + time line
                            () => <Typography size="xs" isSkeleton />,
                            // two-line preview
                            () => (
                                <StackV
                                    gap={2}
                                    principle="sibling-stack"
                                    explain="Same-kind peer stack of preview shimmer lines — not group-boundary, because both lines are repeating skeleton peers rather than labelled section groups."
                                    items={[
                                        () => <Typography size="sm" isSkeleton />,
                                        () => <Typography size="sm" isSkeleton />,
                                    ]}
                                />
                            ),
                            // chip-pill row — ONE chip (status, the classification axis) + the scope
                            // as a plain shimmer bar, matching the real row's own text-inline treatment
                            // (eslint `starci-fe/no-adjacent-chip`, *7 below).
                            () => (
                                <StackH
                                    gap={3}
                                    principle="chip-row"
                                    explain="Status chip and scope shimmer share one wrapping meta row — not flex-action, because neither peer is a control."
                                    items={[
                                        () => <Typography size="xs" isSkeleton />,
                                        () => <Chip isSkeleton />,
                                    ]}
                                />
                            ),
                        ]}
                    />
                ),
                // status dot — no home atom (*3), same escape hatch `Pagination` uses for its own shimmer squares
                () => <Skeleton className="size-2 shrink-0 rounded-full" />,
            ]}
        />
    )
}

import React from "react"
import type { CourseQuestionNode } from "@/modules/api/graphql/queries/types/course-questions"
import { QaQuestionThread } from "@/components/blocks/learn/QaQuestionThread"
import { MagnifyingGlassIcon } from "@phosphor-icons/react"
import { Pagination } from "@/components/atoms/navigation/Pagination"
import {
    AsyncContent,
    type AsyncContentEmptyProps,
    type AsyncContentErrorProps,
} from "@/components/composites/async/AsyncContent"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { StackV } from "@/components/frames/Stack"
import { SkeletonQuestionRow } from "./SkeletonQuestionRow"

/** One asker — plain data, the row builds the avatar + name from it. */
export interface CourseQaQuestionAuthor {
    /** Stable id — used to detect "this is the viewer's own question". */
    id: string
    /** Display name (or username fallback), already resolved by the caller. */
    displayName: string
    /** Avatar image; absent -> the atom's own generated/initials fallback chain. */
    avatarUrl?: string
}

/** Where a question was asked — drives the scope chip's own label (§14d.1). */
export type CourseQaQuestionScope =
    | { kind: "lesson", lessonTitle: string }
    | { kind: "general" }

/** One question row — plain DATA; the block builds the wording/chips/dot. */
export interface CourseQaQuestionItem {
    /** Stable id — the React key, and how "own question" is detected. */
    id: string
    /** Who asked it. */
    author: CourseQaQuestionAuthor
    /** Already-formatted relative time, e.g. "2 hours ago" (no i18n layer at this tier). */
    createdTimeAgo: string
    /** `true` -> a pin glyph rides beside the asker's name. */
    isPinned?: boolean
    /** `true` -> a founder-verified glyph rides beside the asker's name. */
    isFounderAuthor?: boolean
    /** One/two-line preview of the question body. */
    preview: string
    /** Which lesson (or "general/course-wide") this question belongs to. */
    scope: CourseQaQuestionScope
    /** How many answers this question has. `0` => unanswered. */
    replyCount: number
    /** `true` -> the (at least one) answer came from the course founder. */
    answeredByFounder?: boolean
}

/** The signed-in viewer's own identity — threaded through for the `QaQuestionThread` swap (*2/*6). */
export interface CourseQaCurrentUser {
    username: string
    avatar?: string
}

/** Props for {@link CourseQaQuestionList}. */
export interface CourseQaQuestionListProps {
    /** The current page's questions, in display order. */
    questions: ReadonlyArray<CourseQuestionNode>
    /** `true` while this list's own fetch is in flight (feeds the Loading leaf). */
    isLoading: boolean
    /** Truthy -> the fetch failed (feeds the Error leaf, outranks loading/empty). */
    error?: unknown
    /** Retry the failed fetch. Omit -> the error message carries no action. */
    onRetry?: () => void
    /** 1-based current page. */
    page: number
    /** Total page count. */
    totalPages: number
    /** Fired with the 1-based page the viewer picked. */
    onPageChange: (page: number) => void
    /** Signed-in viewer's id (drives the "You" swap, *6); `null` when signed out. */
    currentUserId: string | null
    /** Signed-in viewer's identity — pass-through for the `QaQuestionThread` swap (*2). */
    currentUser: CourseQaCurrentUser | null
    /** Fired after an answer is posted/edited/deleted — pass-through for the `QaQuestionThread` swap (*2). */
    onAnswered?: () => void
    /** Accessible name for the pager region (*4). */
    pagerAriaLabel: string
    /** External skeleton override, distinct from `isLoading` (*5). */
    isSkeleton?: boolean
}

/**
 * `CourseQaQuestionList` — the course-wide Q&A roll-up region: the async
 * lifecycle (loading -> error -> search-empty -> content) around a flush divide-y
 * question list plus a pager. The Content leaf renders one `QaQuestionThread`
 * per question — collapsed until pressed, then the full conversation inline.
 * Four leaves: `Loading`, `Error`, `Empty` (filter matched
 * nothing; true zero-ever is `CourseQaInvite` a layer up), `Content`.
 */

/** How many placeholder rows mirror the list while the first page loads — matches `CourseQaSkeleton.tsx`. */
const SKELETON_ROW_COUNT = 4

const ERROR_TITLE = "Couldn't load the question list"
const RETRY_LABEL = "Retry"
const EMPTY_TITLE = "No questions match the current filter"
const EMPTY_DESCRIPTION = "Try a different filter or search term."

/** The Loading branch's rows — see *1 for why these are NOT `SurfaceCardList.isSkeleton`. */
const skeletonItems = (): Array<SurfaceCardListItem> =>
    Array.from({ length: SKELETON_ROW_COUNT }, (_unused, index) => ({
        key: `skeleton-${index}`,
        content: () => <SkeletonQuestionRow />,
    }))

/** The Content branch's real rows — each a {@link QaQuestionThread}. */
const questionItems = (
    questions: ReadonlyArray<CourseQuestionNode>,
    currentUserId: string | null,
    currentUser: CourseQaCurrentUser | null,
    onAnswered?: () => void,
): Array<SurfaceCardListItem> =>
    questions.map((question) => ({
        key: question.id,
        content: () => (
            <QaQuestionThread
                question={question}
                currentUserId={currentUserId}
                currentUser={currentUser}
                onAnswered={onAnswered}
            />
        ),
    }))

/**
 * The course-wide Q&A roll-up list. See the file header for the full contract,
 * the GAP note on `QaQuestionThread` (*2), and the remaining judgement calls.
 *
 * @param props - {@link CourseQaQuestionListProps}
 */
const CourseQaQuestionList = ({
    questions,
    isLoading,
    error,
    onRetry,
    page,
    totalPages,
    onPageChange,
    currentUserId,
    currentUser,
    onAnswered,
    pagerAriaLabel,
    isSkeleton = false,
}: CourseQaQuestionListProps) => {
    const emptyContent: AsyncContentEmptyProps = {
        icon: MagnifyingGlassIcon,
        title: EMPTY_TITLE,
        description: EMPTY_DESCRIPTION,

    }

    const errorContent: AsyncContentErrorProps = {
        title: ERROR_TITLE,
        onRetry,
        retryLabel: RETRY_LABEL,

    }

    return (
        <AsyncContent
            // *5 — an external override (`isSkeleton`) converges on the same Loading
            // branch as the list's own fetch flag (`isLoading`).
            isLoading={isSkeleton || isLoading}
            skeleton={() => (
                <SurfaceCardList
                    identity={{ tier: "block", component: "CourseQaQuestionList" }}
                    items={skeletonItems()}
                />
            )}
            isEmpty={questions.length === 0}
            emptyContent={emptyContent}
            error={error}
            errorContent={errorContent}
            content={() => (
                <StackV
                    identity={{ tier: "block", component: "CourseQaQuestionList" }}
                    principle="sibling-stack"
                    explain="Question list and pager are same-kind peers in the roll-up column — not group-boundary, because they are repeating list sections rather than nested groups."
                    items={[
                        () => (
                            <SurfaceCardList
                                items={questionItems(questions, currentUserId, currentUser, onAnswered)}
                            />
                        ),
                        ...(totalPages > 1
                            ? [
                                // *4 — `Pagination` hard-codes its own aria-label; a wrapping
                                // <nav> is how the caller's `pagerAriaLabel` still names the region.
                                () => (
                                    <nav aria-label={pagerAriaLabel}>
                                        <Pagination
                                            currentPage={page}
                                            totalPages={totalPages}
                                            onPageChange={onPageChange}
                                        />
                                    </nav>
                                ),
                            ]
                            : []),
                    ]}
                />
            )}
        />
    )
}

export { CourseQaQuestionList }

import { GithubLogoIcon } from "@phosphor-icons/react"
import { Callout } from "@/components/composites/feedback/Callout"
import { Alert } from "@/components/atoms/feedback/Alert"

/**
 * `CourseTeamGate` — a nudge to join the course's GitHub team. The backend
 * scopes the team by `is_enrolled = true`, so the block self-hides for trial
 * viewers and for anyone already in the team. Two leaves — shown vs. hidden (a
 * node vs. an empty tree); the two hiding reasons produce the same empty tree,
 * so they are states of the hidden leaf.
 */

/** Props for {@link CourseTeamGate}. */
export interface CourseTeamGateProps {
    /**
     * Whether the learner has PAID for the course. Only paid learners have a team to
     * join (see header). Not known yet (query hasn't returned) → pass `false` so it
     * doesn't flicker.
     */
    isEnrolled: boolean
    /** Whether they're already in the GitHub team. `true` → the block self-hides. */
    isInTeam: boolean
    /** Fires when the join-team button is pressed. */
    onJoin?: () => void
    /**
     * `true` → render the shimmer mirror INSTEAD of waiting on `isEnrolled`/`isInTeam`
     * (not knowing yet means we can't decide whether to SELF-HIDE — the mirror must
     * show to hold the slot in the loading tree).
     *
     * ⚠️ `Callout` (the frame this block still uses on the live branch) does
     * NOT have `isSkeleton` yet and sits OUTSIDE the 4 files touched this pass, so the
     * flag can't be forwarded through it. But `Callout` is just a thin wrapper
     * over the `Alert` atom — and THAT atom already has `isSkeleton` (§12c). The
     * skeleton branch below calls `Alert` DIRECTLY (same `status`/`icon` that
     * `Callout` will use on the live branch) instead of hand-rolling a parallel
     * warning box.
     */
    isSkeleton?: boolean
}

/**
 * A non-blocking warning: the learner has paid but hasn't joined the course's
 * GitHub team yet (some labs need repo access). Self-hides when it doesn't apply.
 *
 * @param props - {@link CourseTeamGateProps}
 */
const CourseTeamGateBase = ({
    isEnrolled,
    isInTeam,
    onJoin,
    isSkeleton = false,
}: CourseTeamGateProps) => {
    // Loading: `isEnrolled`/`isInTeam` haven't come back yet, so we can't decide
    // whether to self-hide — show the `Alert` atom's mirror (see the
    // `isSkeleton` doc above for why it calls the atom directly instead of
    // `Callout`).
    if (isSkeleton) {
        return (
            <Alert
                isSkeleton
                status="warning"
                icon={GithubLogoIcon}
            />
        )
    }

    // SELF-HIDE — the block owns its own show condition; the screen doesn't need to ask.
    if (!isEnrolled || isInTeam) {
        return null
    }

    return (
        <Callout
            status="warning"
            icon={GithubLogoIcon}
            title="You haven't joined the course's GitHub team yet"
            description="Some labs need repo access — tap to join."
            actionLabel="Join team"
            onAction={onJoin}
        />
    )
}

/** `CourseTeamGate.*` — a single-component namespace ⇒ only has `.Base`. */
export { CourseTeamGateBase as CourseTeamGate }

"use client"

import React, { useCallback } from "react"
import { ArrowRightIcon, LockIcon } from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { usePaymentOverlayState } from "@/hooks/zustand/overlay/hooks"
import { PaymentFlow } from "@/modules/types/payment"
import { useAppSelector } from "@/redux/hooks"
import { useQueryCoursePricePreviewSwr } from "@/hooks/swr/api/graphql/queries/useQueryCoursePricePreviewSwr"
import { AsyncContentError } from "@/components/composites/async/AsyncContent"
import { PriceTagInline } from "@/components/blocks/commerce/PriceTag"
import { PhaseScarcityNote } from "@/components/blocks/commerce/PhaseScarcityNote"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Button } from "@/components/atoms/buttons/Button"
import { Typography } from "@/components/atoms/text/Typography"
import { Box } from "@/components/frames/Box"
import { StackV } from "@/components/frames/Stack"

/** The conversion card's own surface: a bounded, floating sheet no frame names. */
const CARD_SURFACE = "flex w-full max-w-[480px] flex-col items-center gap-3 rounded-3xl bg-surface px-7 py-8 text-center shadow-surface"

/**
 * Fade band over the teaser's tail. It fades into the preview's OWN card token
 * (`bg-surface`), not the page canvas — the teaser content is bg-surface cards, so
 * fading to `background` cut them off mid-card. Same band height as LessonReader's
 * locked-body fade — canonical value, not re-tuned here.
 */
const TEASER_FADE = "absolute inset-x-0 bottom-0 h-72 bg-gradient-to-b from-transparent via-surface/70 to-surface"

interface EnrollCardProps {
    title: string
    description: string
    priceRegion: () => React.ReactNode
    scarcity?: () => React.ReactNode
    ctaLabel: string
    onEnroll: () => void
}

const EnrollCard = ({ title, description, priceRegion, scarcity, ctaLabel, onEnroll }: EnrollCardProps) => (
    <Box className={CARD_SURFACE}>
        <StackV
            gap={4}
            principle="card-caption"
            explain="Holds caption text under card media so the caption stays attached to the image above it."
            align="center"
            items={[
                () => <IconTile icon={<LockIcon aria-hidden focusable="false" />} tone="accent" size="sm" />,
                () => <Typography size="h4" weight="bold" text={title} />,
                () => (
                    <Box className="max-w-[400px]">
                        <Typography size="sm" color="muted" text={description} />
                    </Box>
                ),
                priceRegion,
                ...(scarcity ? [scarcity] : []),
                () => (
                    <Box className="w-full max-w-[300px]">
                        <Button
                            label={ctaLabel}
                            variant="primary"
                            size="lg"
                            suffixIcon={ArrowRightIcon}
                            onPress={onEnroll}
                            classNames={["w-full"]}
                        />
                    </Box>
                ),
            ]}
        />
    </Box>
)

/** Props for {@link EnrollGate}. */
export interface EnrollGateProps {
    /** Title — e.g. "Unlock Personal project" (the surface name folded in by the caller). */
    title: string
    /** One-line reason the surface needs enrollment. */
    description: string
    /**
     * Optional MOCK teaser of the gated surface (representative, non-interactive
     * content — NOT real gated data). When provided, the gate reads Medium-style:
     * the preview is rendered `aria-hidden` behind a bottom fade, with the enroll
     * card floating over the faded tail — so the learner SEES what's inside before
     * the CTA. Omit → just the centred enroll card (no teaser).
     */
    preview?: React.ReactNode
}

/**
 * Course-surface enroll gate: shown in place of an enrollment-required learn surface
 * (personal-project, mock-interview, flashcards, module) when the viewer is in trial
 * mode (not enrolled). Instead of a dead grey card, it renders a conversion CARD —
 * lock identity + outcome copy + the loyalty-aware {@link PriceTag} + scarcity + a
 * single enroll CTA (mirrors {@link import("../../LessonReader/PremiumPaywall").PremiumPaywall},
 * SAME price source/render as the payment modal). With a {@link EnrollGateProps.preview}
 * it upgrades to a Medium-style teaser: a faded mock of the surface behind the card.
 * The single action enrolls via the shared {@link PaymentFlow.CourseEnroll} modal.
 *
 * Only the PRICE waits on a fetch — the lock, copy and CTA render straight away.
 *
 * @param props - {@link EnrollGateProps}
 */
export const EnrollGate = ({ title, description, preview }: EnrollGateProps) => {
    const t = useTranslations()
    const { open } = usePaymentOverlayState()
    const courseId = useAppSelector((state) => state.course.entity?.id)

    // loyalty-aware price preview — SAME query/render as PaymentModal + PremiumPaywall
    const priceSwr = useQueryCoursePricePreviewSwr(courseId ?? null)
    const price = priceSwr.data
    const isPriceSkeleton = Boolean(courseId) && !priceSwr.data && !priceSwr.error

    /** Open the shared payment modal in the course-enroll flow. */
    const onEnroll = useCallback(
        () => open({ flow: PaymentFlow.CourseEnroll }),
        [open],
    )

    // error beats a stale loading flag (BLOCK-8 order)
    const priceRegion = () => {
        if (priceSwr.error) {
            return <AsyncContentError title={t("payment.priceError")} />
        }
        if (isPriceSkeleton) {
            return <Skeleton className="h-7 w-32 rounded-xl" />
        }
        return price?.discountedPriceVnd != null ? (
            <PriceTagInline
                discounted={price.discountedPriceVnd}
                original={price.originalPriceVnd}
               
                breakdown={{
                    phase: price.phasePriceVnd,
                    loyaltyPercent: price.discountPercent,
                }}
            />
        ) : null
    }

    const scarcity = price
        ? () => (
            <PhaseScarcityNote
                currentPhase={price.currentPhase}
                seatsRemaining={price.seatsRemainingInCurrentPhase}
                nextPhasePriceVnd={price.nextPhasePriceVnd}
            />
        )
        : undefined

    // no teaser → just the centred enroll card.
    // Asymmetric page inset {x:5,y:6} has no padding principle token; a StackV
    // that also carried gap={1} was padding-plus-gap with no honest owner — Box
    // keeps the same inset without a false seam token.
    if (!preview) {
        return (
            <Box
                identity={{ tier: "block", component: "EnrollGate" }}
                className="flex justify-center px-5 py-6"
            >
                <EnrollCard
                    title={title}
                    description={description}
                    priceRegion={priceRegion}
                    scarcity={scarcity}
                    ctaLabel={t("enrollGate.cta")}
                    onEnroll={onEnroll}
                />
            </Box>
        )
    }

    // teaser → the FULL real preview (no height cap — mirrors LessonReader, which renders
    // the whole real body and only fades its tail, never truncates early), with the enroll
    // card floating over the faded tail. The stack, the fade and the overlap are positional
    // values no frame names, so they stay literals on Box.
    return (
        <Box identity={{ tier: "block", component: "EnrollGate" }} className="relative">
            <Box className="pointer-events-none relative" aria-hidden>
                {preview}
                <Box className={TEASER_FADE} />
            </Box>
            <Box className="relative z-10 -mt-32 flex justify-center px-4 pb-6">
                <EnrollCard
                    title={title}
                    description={description}
                    priceRegion={priceRegion}
                    scarcity={scarcity}
                    ctaLabel={t("enrollGate.cta")}
                    onEnroll={onEnroll}
                />
            </Box>
        </Box>
    )
}

import React from "react"
import { Typography } from "@/components/atoms/text/Typography"
import { Chip, type ChipTone } from "@/components/atoms/chips/Chip"
import { LockSimpleIcon } from "@phosphor-icons/react"
import type { SearchCourseContentItem } from "@/modules/api/graphql/queries/types/search-course-content"

/**
 * Per-kind presentation of a RAG search hit: when a kind chip is enabled, its
 * label key + Chip tone. `code` shares the lesson's presentation (it resolves to
 * a content page). Unknown kinds fall back to `content`.
 */
export const KIND_META = {
    content: { chip: "kindContent", color: "success" as ChipTone },
    code: { chip: "kindContent", color: "success" as ChipTone },
    challenge: { chip: "kindChallenge", color: "warning" as ChipTone },
    flashcard: { chip: "kindFlashcard", color: "accent" as ChipTone },
    milestone: { chip: "kindMilestone", color: "default" as ChipTone },
} as const

type KnownKind = keyof typeof KIND_META

/** Resolve a hit's kind to its presentation, defaulting unknown kinds to content. */
export const metaForKind = (kind: string): (typeof KIND_META)[KnownKind] =>
    KIND_META[kind as KnownKind] ?? KIND_META.content

/** Props for {@link _EntityResultRow} — presentational; labels already resolved. */
export interface EntityResultRowProps {
    /** The RAG search hit to render (content/challenge/flashcard/milestone). */
    item: SearchCourseContentItem
    /** Fired when the row is clicked — the caller owns navigation. */
    onSelect: (item: SearchCourseContentItem) => void
    /** Show a kind chip above the title (chat tool-result). Default off (quiet related-content list). */
    showKindChip?: boolean
    /** Show a one-line snippet under the title as context. Default off. */
    showSnippet?: boolean
    /** Already-localized kind-chip label (only rendered when `showKindChip` is set). */
    kindLabel: string
    /** Already-localized "Enrol to open" line, shown when `item.isLocked`. */
    enrollToOpenLabel: string
}

/**
 * One pickable RAG result row — the shared row shape behind the content-AI
 * search view, the passive "related content" list, and the in-chat tool-result
 * widget. A nav go-there link: the whole row navigates on click, so hover
 * underlines the TITLE (never a background fill), and the row carries
 * `cursor-pointer`. Kind appearance uses the house `Chip` tone; placement is
 * intrinsic (`w-fit` on the atom).
 *
 * @param props - {@link EntityResultRowProps}
 */
export const _EntityResultRow = ({
    item,
    onSelect,
    showKindChip = false,
    showSnippet = false,
    kindLabel,
    enrollToOpenLabel,
}: EntityResultRowProps) => {
    const meta = metaForKind(item.kind)
    return (
        <button
            type="button"
            onClick={() => onSelect(item)}
            className="group relative flex w-full cursor-pointer flex-col gap-2 px-4 py-3 text-left after:absolute after:bottom-0 after:left-0 after:h-px after:w-full after:bg-surface-foreground/6 after:content-[''] last:after:hidden"
        >
            {showKindChip ? (
                <Chip tone={meta.color} text={kindLabel} />
            ) : item.breadcrumb ? (
                <Typography size="xs" color="muted" truncate text={item.breadcrumb} />
            ) : null}
            <Typography
                size="sm"
                weight="medium"
                truncate
                underlineOnGroupHover
                text={item.title}
            />
            {showSnippet && item.snippet ? (
                <Typography size="xs" color="muted" truncate text={item.snippet} />
            ) : null}
            {item.isLocked ? (
                <span className="flex items-center gap-1 text-warning-soft-foreground">
                    <LockSimpleIcon aria-hidden focusable="false" className="size-3.5 shrink-0" />
                    <Typography size="xs" text={enrollToOpenLabel} />
                </span>
            ) : null}
        </button>
    )
}

import React from "react"
import { CardsIcon, LightningIcon } from "@phosphor-icons/react"
import { Tabs, type TabItem } from "@/components/atoms/navigation/Tabs"

/**
 * `FlashcardModeSwitch` — study the deck, or drill yourself. Same shape as
 * `ContentModeNav` (a row, a `Tabs` atom, no skeleton) but owns a different
 * vocabulary: practice modes rather than reading modes. The screen stops
 * rendering it once a session starts, since a mid-session switch would throw the
 * run away. Selected mode is data — one leaf, two states; there is no skeleton
 * prop.
 */

/** The two ways to work a deck. */
export type FlashcardMode = "study" | "quiz"

/**
 * Label + icon per mode. The BLOCK owns this table — it is the vocabulary of the
 * flashcards pane, and a caller that could pass it would own the wording.
 */
const MODE_LABEL: Record<FlashcardMode, string> = {
    study: "Study cards",
    quiz: "Quick quiz",
}

const MODE_ICON: Record<FlashcardMode, TabItem["icon"]> = {
    study: CardsIcon,
    quiz: LightningIcon,
}

/** Props for {@link FlashcardModeSwitch}. */
export interface FlashcardModeSwitchProps {
    /** Which mode the learner is in now. */
    mode: FlashcardMode
    /** Fired with the mode the learner picked. */
    onModeChange: (mode: FlashcardMode) => void
    /**
     * Accessible name for the row, localized by the caller (blocks carry no
     * i18n). Without it a screen reader hears two loose tabs.
     */
    ariaLabel: string
}

/**
 * The flashcards mode row. See the file header for the full contract.
 *
 * @param props - {@link FlashcardModeSwitchProps}
 */
const FlashcardModeSwitch = ({
    mode,
    onModeChange,
    ariaLabel,
}: FlashcardModeSwitchProps) => {
    const items: Array<TabItem> = (Object.keys(MODE_LABEL) as Array<FlashcardMode>).map((key) => ({
        key,
        label: MODE_LABEL[key],
        icon: MODE_ICON[key],
    }))

    return (
        <div>
            <Tabs
                items={items}
                selectedKey={mode}
                onSelectionChange={(key) => onModeChange(key as FlashcardMode)}
                ariaLabel={ariaLabel}

            />
        </div>
    )
}

export { FlashcardModeSwitch }

import React from "react"
import { type SkeletonProps } from "@/components/frames/_slot"
import { LockIcon, CaretLeftIcon, CaretRightIcon } from "@phosphor-icons/react"
import { Button } from "@/components/atoms/buttons/Button"
import { Chip } from "@/components/atoms/chips/Chip"
import { GlyphMark } from "@/components/atoms/display/GlyphMark"
import { ChipGroup, type ChipGroupItem } from "@/components/composites/chips/ChipGroup"
import { Typography } from "@/components/atoms/text/Typography"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { MarkdownContent } from "@/components/composites/viewers/MarkdownContent"
import { RatingBar, type RatingOption } from "@/components/blocks/learn/RatingBar"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * `FlashcardStudyCard` — one card of a review run, shared by both due-review and
 * deck-review. Composes `SurfaceCard`, `MarkdownContent`, `Chip`/`ChipGroup`,
 * `Button`, and the shared `RatingBar`; only the locked-premium notice is
 * hand-rolled. One chip per meta row (`starci-fe/no-adjacent-chip`): `levelLabel`
 * takes the lone chip, `tags` ride `ChipGroup`. Three leaves: `revealed` swaps
 * question-only for answer body, and within revealed `isLocked` swaps the answer
 * for a lock notice; `levelLabel`/`tags`/`explanation` stay states. Prev/next
 * never gate on grading.
 */

/** Props for {@link FlashcardStudyCard}. */
export interface FlashcardStudyCardProps {
    /** The question, as authored markdown. */
    question: string
    /** Seniority/difficulty this card targets, e.g. "Middle" — already localized. */
    levelLabel?: string
    /** Free-form tags on the card, e.g. topic labels. Rendered as a truncating row. */
    tags?: Array<string>
    /** `true` → the answer body (or the lock notice) is shown under the question. */
    revealed: boolean
    /** Fired when the learner asks to see the answer. */
    onReveal: () => void
    /** The answer, as authored markdown. Shown only once `revealed` and not `isLocked`. */
    answer?: string
    /** Optional reasoning under the answer, as authored markdown. */
    explanation?: string
    /**
     * `true` → this card's answer is premium content the learner has not bought.
     * Only meaningful once `revealed`: the question always shows, but revealing
     * swaps in a lock notice + unlock CTA instead of the real answer.
     */
    isLocked?: boolean
    /** Fired when the learner takes the way through the lock. Required when `isLocked` can be true. */
    onUnlock?: () => void
    /** Recall grades offered once the real answer is showing. */
    ratingOptions: Array<RatingOption>
    /** Fired with the grade the learner picked. */
    onRate: (grade: number) => void
    /** `true` → a grade is in flight; `RatingBar` owns the busy affordance. */
    isRatingPending?: boolean
    /** `true` → this is the first card of the run; the previous control is disabled. */
    isFirst: boolean
    /** `true` → this is the last card of the run; the next control is disabled. */
    isLast: boolean
    /** Fired to step back a card, regardless of whether this one was graded. */
    onPrev: () => void
    /** Fired to step forward a card, regardless of whether this one was graded. */
    onNext: () => void
    /** `true` → the card draws its own mirror instead of the real content. */
    isSkeleton?: boolean
}

/**
 * One review card. See the file header for the full contract, in particular why
 * this has exactly three leaves and why prev/next never gate on grading.
 *
 * @param props - {@link FlashcardStudyCardProps}
 */
const FlashcardStudyCard = ({
    question,
    levelLabel,
    tags,
    revealed,
    onReveal,
    answer,
    explanation,
    isLocked = false,
    onUnlock,
    ratingOptions,
    onRate,
    isRatingPending = false,
    isFirst,
    isLast,
    onPrev,
    onNext,
    isSkeleton = false,
}: FlashcardStudyCardProps) => {
    const hasMeta = levelLabel != null || (tags != null && tags.length > 0)
    const tagItems: Array<ChipGroupItem> = (tags ?? []).map((tag) => ({ key: tag, text: tag }))

    const metaRow = hasMeta ? (
        <StackH
            gap={3}
            principle="chip-row"
            explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
            at="sm"
            align="center"
            isSkeleton={isSkeleton}
            items={[
                ...(levelLabel != null ? [({ isSkeleton }: SkeletonProps) => <Chip isSkeleton={isSkeleton} tone="default" text={levelLabel} />] : []),
                ...(tagItems.length > 0
                    ? [
                        ({ isSkeleton }: SkeletonProps) => (
                            <ChipGroup
                                items={tagItems}
                                isSkeleton={isSkeleton}

                            />
                        ),
                    ]
                    : []),
            ]}
        />
    ) : null

    // The one hand-rolled part of this block (see file header): no existing
    // composite draws a lock message sized for ONE card face that still has a
    // question and nav controls around it — `EmptyState` fills a whole
    // pane, which is the wrong weight here.
    const lockNotice = (
        <StackV
            gap={3}
            principle="sibling-stack"
            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => (
                    <StackH
                        gap={3}
                        principle="identity"
                        explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                        align="center"
                        isSkeleton={isSkeleton}
                        items={[
                            // GlyphMark owns size-5 + regular weight; prior `weight="bold"` was
                            // incorrect at this scale (bold is only for glyphs smaller than size-5).
                            () => <GlyphMark icon={LockIcon} tone="muted" />,
                            ({ isSkeleton }: SkeletonProps) => (
                                <StackV
                                    gap={1}
                                    isSkeleton={isSkeleton}
                                    items={[
                                        ({ isSkeleton }: SkeletonProps) => <Typography size="sm" weight="medium" isSkeleton={isSkeleton} text="Answer locked" />,
                                        ({ isSkeleton }: SkeletonProps) => <Typography size="xs" color="muted" isSkeleton={isSkeleton} text="Upgrade to Premium to see this card's answer and explanation" />,
                                    ]}
                                />
                            ),
                        ]}
                    />
                ),
                ({ isSkeleton }: SkeletonProps) => <Button isSkeleton={isSkeleton} label="Unlock this card" variant="primary" onPress={onUnlock} />,
            ]}
        />
    )

    const answerBody = (
        <StackV
            gap={6}
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => (
                    <StackV
                        gap={3}
                        isSkeleton={isSkeleton}
                        items={[
                            ({ isSkeleton }: SkeletonProps) => <Typography size="xs" color="muted" isSkeleton={isSkeleton} text="Answer" />,
                            () => (
                                <MarkdownContent
                                    source={answer ?? ""}
                                    measure="compact"

                                />
                            ),
                        ]}
                    />
                ),
                ...(explanation != null
                    ? [
                        ({ isSkeleton }: SkeletonProps) => (
                            <StackV
                                gap={3}
                                isSkeleton={isSkeleton}
                                items={[
                                    ({ isSkeleton }: SkeletonProps) => <Typography size="xs" color="muted" isSkeleton={isSkeleton} text="Explanation" />,
                                    () => (
                                        <MarkdownContent
                                            source={explanation}
                                            measure="compact"

                                        />
                                    ),
                                ]}
                            />
                        ),
                    ]
                    : []),
                // The recall grade, not the run's right/wrong — same shared block
                // and same reasoning as `QuizRecapList`'s use of it.
                ({ isSkeleton }: SkeletonProps) => (
                    <RatingBar
                        options={ratingOptions}
                        onRate={onRate}
                        ariaLabel="Choose recall level"
                        isPending={isRatingPending}
                        isSkeleton={isSkeleton}

                    />
                ),
            ]}
        />
    )

    // Prev/next live beside reveal but never gate on it — see file header.
    const navRow = (
        <StackH
            gap={3}
            principle="flex-action"
            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
            justify="between"
            align="center"
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => (
                    <Button
                        isSkeleton={isSkeleton}
                        isIconOnly
                        prefixIcon={CaretLeftIcon}
                        ariaLabel="Previous card"
                        variant="tertiary"
                        isDisabled={isFirst}
                        onPress={onPrev}

                    />
                ),
                ...(!revealed ? [({ isSkeleton }: SkeletonProps) => <Button isSkeleton={isSkeleton} label="Show answer" variant="primary" onPress={onReveal} />] : []),
                ({ isSkeleton }: SkeletonProps) => (
                    <Button
                        isSkeleton={isSkeleton}
                        isIconOnly
                        prefixIcon={CaretRightIcon}
                        ariaLabel="Next card"
                        variant="tertiary"
                        isDisabled={isLast}
                        onPress={onNext}

                    />
                ),
            ]}
        />
    )

    const cardBody = (
        <>
            {metaRow}
            <MarkdownContent
                source={question}
                measure="compact"

            />
            {revealed ? (isLocked ? lockNotice : answerBody) : null}
            {navRow}
        </>
    )

    return (
        <div>
            <SurfaceCard
                isSkeleton={isSkeleton}

                body={() => <StackV gap={6} isSkeleton={isSkeleton} items={[() => cardBody]} />}
            />
        </div>
    )
}

export { FlashcardStudyCard }

import React from "react"
import { Breadcrumbs } from "@/components/atoms/navigation/Breadcrumbs"
import { PageHeader } from "@/components/composites/layout/Page"

/**
 * `FoundationCategoryHeader` — the Foundations-hub identity cluster: a breadcrumb
 * trail above a title and description, nothing more. Sibling of `ContentHeader`
 * but thinner — a Foundations category carries no read state, reading time, or
 * outcomes, so it stops at the description. The breadcrumb slot is optional and
 * simply drops out when absent.
 */

/** One breadcrumb link — plain data, the block builds the atom from it. */
export interface FoundationCategoryHeaderCrumb {
    /** Stable React key. */
    key: string
    /** Display label. */
    label: string
    /** Has a handler → the crumb is pressable; the current page leaves it out. */
    onPress?: () => void
}

/** Props for {@link FoundationCategoryHeader}. */
export interface FoundationCategoryHeaderProps {
    /**
     * Breadcrumb trail as DATA — the block builds `Breadcrumbs` itself. Empty
     * or omitted (and not loading) → the whole breadcrumb slot is left out: a
     * root category reached directly has nothing above it to trail through.
     */
    breadcrumbItems?: Array<FoundationCategoryHeaderCrumb>
    /** Category title. */
    title: string
    /** One-sentence summary of the category. */
    description?: string
    /**
     * `true` → every composed atom switches to its own shimmer. The flag FLOWS
     * DOWN into the real atoms rather than building a parallel skeleton tree
     * (§12c), so the shimmer keeps the exact box of the thing it replaces.
     */
    isSkeleton?: boolean
}

/**
 * Foundations-hub identity cluster: trail, title, description. See the file
 * header for why this stops short of `ContentHeader`'s meta row and outcomes
 * card, and why it still earns its own layer above `PageHeader`.
 *
 * @param props - {@link FoundationCategoryHeaderProps}
 */
const FoundationCategoryHeader = ({
    breadcrumbItems,
    title,
    description,
    isSkeleton = false,
}: FoundationCategoryHeaderProps) => {
    return (
        // Identity hold: PageHeader does not accept CallerIdentity (ledger PageHeader gap).
        <PageHeader
            isSkeleton={isSkeleton}
            breadcrumb={() =>
                isSkeleton || breadcrumbItems?.length ? (
                    // Hold: no hug-width frame for breadcrumb measure (`w-fit` parent placement).
                    <div className="w-fit">
                        <Breadcrumbs
                            collapseOnMobile
                            collapseFrom={4}
                            items={breadcrumbItems ?? []}
                            isSkeleton={isSkeleton}
                        />
                    </div>
                ) : undefined
            }
            title={title}
            description={description}
        />
    )
}

export { FoundationCategoryHeader }

import React from "react"
import { CaretRightIcon, MagnifyingGlassIcon } from "@phosphor-icons/react"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { EmptyState } from "@/components/composites/feedback/EmptyState"
import { Image } from "@/components/atoms/media/Image"
import { Pagination } from "@/components/atoms/navigation/Pagination"
import { StackV } from "@/components/frames/Stack"

/**
 * `FoundationCategoryList` — the Foundations content library's browse-and-drill-in
 * list: joined rows with a thumbnail, title, one-line description and a trailing
 * caret, plus a pager once there is more than one page. Loading swaps row content
 * to shimmer; the `Empty` state replaces the rows with an `EmptyState` (worded by
 * whether a search query drove the empty result), both bounded inside the same
 * `SurfaceCardList` surface.
 */

/** One category row — plain data; the block resolves the thumbnail chain and builds the wording. */
export interface FoundationCategoryListItem {
    /** Stable id — also what `onSelectCategory` fires with. */
    id: string
    /** Category title. */
    title: string
    /** One-line summary, shown as the row's subtitle. */
    description?: string
    /** Underlying tech/brand mark — rides as the `Image` atom's `fallbackSrc` (see file header). */
    logoSrc?: string
    /** Dedicated category thumbnail — wins over `logoSrc` when present (see file header). */
    thumbnailUrl?: string
}

/** Page state for the list's own pager — omit entirely when the caller has only one page. */
export interface FoundationCategoryListPagination {
    /** 1-based current page. */
    currentPage: number
    /** Total page count. */
    totalPages: number
    /** Fired with the 1-based page the reader picked. */
    onPageChange: (pageNumber: number) => void
}

/** Props for {@link FoundationCategoryList}. */
export interface FoundationCategoryListProps {
    /** The current page's categories, in display order. */
    categories: Array<FoundationCategoryListItem>
    /**
     * Current search text driving which empty reason applies when `categories`
     * is empty (see file header, judgement 2). Not rendered as a field by this
     * block — the search input itself is `FoundationCategorySearchBar`'s job.
     */
    searchQuery?: string
    /** Fired with a category's id on ANY row press. */
    onSelectCategory: (id: string) => void
    /** Page nav state. Omit → no pager, even with a full page of rows. */
    pagination?: FoundationCategoryListPagination
    /**
     * `true` → the list draws its own row mirror. `categories` empty while
     * loading (§12c) → guesses 3 rows, this composite's siblings' SSOT convention.
     */
    isSkeleton?: boolean
}

/** The library-itself-is-empty title — no search was involved, so no "try another word" hint applies. Ported verbatim from `foundations.emptyCategories`. */
const LIBRARY_EMPTY_TITLE = "No Foundations topics yet."

/** Placeholder rows for the guessed skeleton count (§12c) — never carry a press handler or a thumbnail. */
const SKELETON_CATEGORIES: Array<FoundationCategoryListItem> = Array.from({ length: 3 }, (_unused, index) => ({
    id: `skeleton-${index}`,
    title: "",
}))

/**
 * Resolves the thumbnail-priority chain (see file header, judgement 1) into the
 * `Image` atom's own `src`/`fallbackSrc` pair — a naming decision, not a second
 * rendering path.
 */
const resolveThumbnail = (category: FoundationCategoryListItem): { src?: string; fallbackSrc?: string } =>
    category.logoSrc
        ? { src: category.logoSrc, fallbackSrc: category.thumbnailUrl }
        : { src: category.thumbnailUrl, fallbackSrc: undefined }

const NoCategoriesEmptyState = ({ hasQuery, searchQuery }: { hasQuery: boolean; searchQuery?: string }) => (
    <EmptyState
        icon={hasQuery ? MagnifyingGlassIcon : undefined}
        title={hasQuery ? `No topics match "${searchQuery?.trim()}".` : LIBRARY_EMPTY_TITLE}
    />
)

/**
 * The Foundations library's browse-and-drill-in list. See the file header for
 * the thumbnail-priority chain, the two empty reasons, and why loading stays a
 * state of the same leaf rather than earning its own.
 *
 * @param props - {@link FoundationCategoryListProps}
 */
const FoundationCategoryList = ({
    categories,
    searchQuery,
    onSelectCategory,
    pagination,
    isSkeleton = false,
}: FoundationCategoryListProps) => {
    // Empty while loading (no real categories yet) → guess 3 rows, keeping the
    // right shape for when real data lands (§8). Once real `categories` exist,
    // keep the EXACT row count already there.
    const usingPlaceholders = isSkeleton && categories.length === 0
    const source = usingPlaceholders ? SKELETON_CATEGORIES : categories

    const rows: Array<SurfaceCardListItem> = source.map((category) => {
        const { src, fallbackSrc } = resolveThumbnail(category)
        return {
            key: category.id,
            leading: () => (
                <div className="size-10 shrink-0">
                    <Image
                        src={src}
                        fallbackSrc={fallbackSrc}
                        alt={category.title}
                        ratio="square"
                        radius="md"
                        isSkeleton={isSkeleton}

                    />
                </div>
            ),
            title: category.title,
            subtitle: category.description,
            // Every real row navigates — a constant of this domain, never conditional
            // (see file header, judgement 3).
            trailingIcon: CaretRightIcon,
            // Placeholder rows never become press targets — nothing underneath can act
            // yet, and a clickable shimmer row would be a false affordance.
            onPress: usingPlaceholders ? undefined : () => onSelectCategory(category.id),
        }
    })

    // Which of the two empty reasons applies (see file header, judgement 2) —
    // never during the skeleton branch, where "empty" just means "not loaded yet".
    const hasQuery = (searchQuery?.trim().length ?? 0) > 0
    const emptyState = !isSkeleton && categories.length === 0
        ? () => <NoCategoriesEmptyState hasQuery={hasQuery} searchQuery={searchQuery} />
        : undefined

    // Nothing to page through during the first fetch or an empty result (see
    // file header, judgement on the pager).
    const showPager = !isSkeleton && categories.length > 0 && pagination != null

    return (
        <StackV identity={{ tier: "block", component: "FoundationCategoryList" }}
            gap={4}
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <SurfaceCardList

                        isSkeleton={isSkeleton}
                        items={rows}
                        emptyState={emptyState}
                    />
                ),
                ...(showPager
                    ? [
                        () => (
                            <div>
                                <Pagination
                                    currentPage={pagination.currentPage}
                                    totalPages={pagination.totalPages}
                                    onPageChange={pagination.onPageChange}

                                />
                            </div>
                        ),
                    ]
                    : []),
            ]}
        />
    )
}

export { FoundationCategoryList }

import React from "react"
import { Chip } from "@/components/atoms/chips/Chip"
import { Breadcrumbs } from "@/components/atoms/navigation/Breadcrumbs"
import { Typography } from "@/components/atoms/text/Typography"
import { EnumChip, type EnumChipEntry } from "@/components/composites/chips/EnumChip"
import { PageHeader } from "@/components/composites/layout/Page"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * `FoundationHeader` — the identity cluster at the top of a foundation resource's
 * page: breadcrumb trail, title, description, and a meta row carrying the
 * resource's kind, its recommended flag, its tags, and its author attribution.
 * Two chips (kind and "recommended") both classify the resource. Every optional
 * part — recommended chip, tag row, author line, skeleton — is a data condition
 * on the same trail → title → description → meta shape.
 */

/** Resource kind of a foundation item — mirrors `src`'s `FoundationKind` enum (closed to 3 values). */
export enum FoundationKind {
    /** An external hyperlink (e.g. official docs, article on another site). */
    ExternalLink = "external_link",
    /** An embedded or linked video resource. */
    Video = "video",
    /** A document or written guide, rendered as markdown. */
    Document = "document",
}

/**
 * Kind → chip presentation. EXHAUSTIVE `Record` (not `Partial`, unlike the
 * type `EnumChip` itself accepts): the enum is closed to 3 values, so the
 * compiler must refuse a build that adds a kind and forgets its entry here.
 * The block owns this table (§14d.1: no caller-supplied color/label).
 */
const KIND_MAP: Record<FoundationKind, EnumChipEntry> = {
    [FoundationKind.ExternalLink]: { color: "accent", label: "External link" },
    [FoundationKind.Video]: { color: "accent", label: "Video" },
    [FoundationKind.Document]: { color: "accent", label: "Article" },
}

/** One breadcrumb link — plain data, the block builds the atom from it. */
export interface FoundationHeaderCrumb {
    /** Stable React key. */
    key: string
    /** Display label. */
    label: string
    /** Has a handler → the crumb is pressable; the current page leaves it out. */
    onPress?: () => void
}

/** One topic tag on a foundation resource — plain data, the block builds the chip. */
export interface FoundationHeaderTag {
    /** Stable React key. */
    key: string
    /** Display label. */
    label: string
}

/** Props for {@link FoundationHeader}. */
export interface FoundationHeaderProps {
    /** Breadcrumb trail as DATA — the block builds `Breadcrumbs` itself. A foundation resource is always reached through its category, so the trail is always required (same call `ModuleHeader` makes for its own always-present trail). */
    breadcrumbItems: Array<FoundationHeaderCrumb>
    /** Resource title. */
    title: string
    /** One-sentence summary of the resource. */
    description?: string
    /** Resource kind — the ONE required classifying fact, drives the `EnumChip` tone + label. */
    kind: FoundationKind
    /** `true` → the resource is editorially highlighted; renders a second, success-toned chip beside the kind chip. */
    isRecommended?: boolean
    /** Topic tags. Empty or omitted → no tag chips render. */
    tags?: Array<FoundationHeaderTag>
    /** Author or source attribution — the block adds "Author: — itself. Omit or empty → no author line. */
    author?: string
    /**
     * `true` → every composed atom switches to its own shimmer. The flag FLOWS
     * DOWN into the real atoms rather than building a parallel skeleton tree
     * (§12c).
     */
    isSkeleton?: boolean
}

/**
 * The foundation-resource identity cluster at the top of a resource's own
 * page. See the file header for the full contract and why this is a sibling
 * of `ContentHeader`/`ModuleHeader`/`CourseBrief` rather than an edit of any
 * of them.
 *
 * @param props - {@link FoundationHeaderProps}
 */
const FoundationHeader = ({
    breadcrumbItems,
    title,
    description,
    kind,
    isRecommended = false,
    tags,
    author,
    isSkeleton = false,
}: FoundationHeaderProps) => {
    const hasTags = (tags?.length ?? 0) > 0
    const hasAuthor = author != null && author.trim().length > 0

    return (
        // Identity hold: PageHeader does not accept CallerIdentity (ledger PageHeader gap).
        <PageHeader
            isSkeleton={isSkeleton}
            breadcrumb={() => (
                // Hold: no hug-width frame for breadcrumb measure (`w-fit` parent placement).
                <div className="w-fit">
                    <Breadcrumbs
                        collapseOnMobile
                        collapseFrom={4}
                        items={breadcrumbItems}
                        isSkeleton={isSkeleton}
                    />
                </div>
            )}
            title={title}
            description={description}
            meta={() =>
                <StackV
                    principle="sibling-stack"
                    explain="Chip row and author line are same-kind peers in the meta cluster — not group-boundary, because they are repeating meta sections rather than nested groups."
                    isSkeleton={isSkeleton}
                    items={[
                        () => (
                            <StackH
                                principle="chip-row"
                                explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                at="sm"
                                isSkeleton={isSkeleton}
                                items={[
                                    () => (
                                        <EnumChip
                                            value={isSkeleton ? FoundationKind.Document : kind}
                                            map={KIND_MAP}
                                            isSkeleton={isSkeleton}
                                        />
                                    ),
                                    ...(isSkeleton
                                        ? [() => <Chip isSkeleton />]
                                        : isRecommended
                                            ? [() => <Chip tone="success" text="Recommended" />]
                                            : []),
                                    ...(isSkeleton
                                        ? [() => <Chip isSkeleton />, () => <Chip isSkeleton />]
                                        : hasTags
                                            ? (tags ?? []).map((tag) => () => <Chip text={tag.label} />)
                                            : []),
                                ]}
                            />
                        ),
                        ...(isSkeleton ? [() => (
                            <Typography size="xs" color="muted" isSkeleton />
                        )] : hasAuthor ? [() => (
                            <Typography
                                size="xs"
                                color="muted"
                                text={`Author: ${author}`}
                            />
                        )] : []),
                    ]}
                />
            }
        />
    )
}

export { FoundationHeader }

import React from "react"
import { CaretRightIcon, MagnifyingGlassIcon, StackIcon } from "@phosphor-icons/react"
import { IconTile } from "@/components/atoms/display/IconTile"
import { Chip } from "@/components/atoms/chips/Chip"
import { EnumChip, type EnumChipEntry } from "@/components/composites/chips/EnumChip"
import {
    AsyncContent,
    type AsyncContentEmptyProps,
    type AsyncContentErrorProps,
} from "@/components/composites/async/AsyncContent"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { Pagination } from "@/components/atoms/navigation/Pagination"
import { Cluster } from "@/components/frames/Cluster"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"
import { StackV } from "@/components/frames/Stack"

/**
 * `FoundationResourceList` — the resource browse list: numbered rows of
 * supplementary material the learner can search and page through. Composes
 * `AsyncContent` (error/loading/empty/content switch), `SurfaceCardList` (bounded
 * rows + loading mirror), `IconTile` (cover image falling back to a glyph),
 * `EnumChip`/`Chip`, and `Pagination`; the block owns the numbering, kind labels,
 * recommended text, and the "no resources yet" vs `no matches for "X"` wording.
 */

/** The kind of resource a row points at — drives the kind chip's label/color. */
export type FoundationKindEnum = "article" | "video" | "exercise" | "reference"

/** One resource row — plain DATA; the block builds the numbering, chips and caret. */
export interface FoundationResourceItem {
    /** Stable id — the React key. */
    id: string
    /** Resource title — the block prefixes it with its position ("1. …"). */
    title: string
    /** One-line blurb under the title. */
    description?: string
    /** Cover thumbnail. Falls back to a `StackIcon` glyph — see file header. */
    thumbnailUrl?: string
    /** Drives the kind chip via {@link KIND_CHIP_MAP}. */
    kind: FoundationKindEnum
    /** `true` → an extra "Recommended" chip rides beside the kind chip. */
    isRecommended?: boolean
    /** Fired when the row is pressed. */
    onPress: () => void
}

/** Props for {@link FoundationResourceList}. */
export interface FoundationResourceListProps {
    /** The current page's resources, in display order. REQUIRED — see file header §R0. */
    resources: Array<FoundationResourceItem>
    /** `true` → the list's own fetch is in flight; own LEAF (see file header). */
    isLoading: boolean
    /** Truthy → the list falls to its error message; own LEAF (beats loading/empty). */
    error?: unknown
    /** Current search text, if the list is filtered. Decides which empty message shows. */
    searchQuery?: string
    /** 1-based current page. */
    currentPage: number
    /** Total page count. */
    totalPages: number
    /** Fired with the 1-based page the viewer picked. */
    onPageChange: (pageNumber: number) => void
    /** Accessible name for the list region — the block has no visible heading of its own. */
    ariaLabel?: string
}

/** kind → chip label/color — the block's own vocabulary (§14d.1), never handed in by a caller. */
const KIND_CHIP_MAP: Record<FoundationKindEnum, EnumChipEntry> = {
    article: { label: "Article" },
    video: { label: "Video", color: "accent" },
    exercise: { label: "Exercise", color: "warning" },
    reference: { label: "Reference", color: "success" },
}

/** The block's own wording for the recommended chip. */
const RECOMMENDED_LABEL = "Recommended"

const ERROR_TITLE = "Could not load the resource list"
const EMPTY_TITLE_NO_QUERY = "No resources here yet"
const EMPTY_DESCRIPTION_WITH_QUERY = "Try a different keyword."

/** How many placeholder rows mirror the list while `resources` hasn't landed yet. */
const SKELETON_ROW_COUNT = 4

/** One row's kind chip + optional recommended chip, in that order. */
const resourceMeta = (resource: FoundationResourceItem) => {
    const chips: Array<ComponentTypeWithSkeleton> = [
        () => <EnumChip value={resource.kind} map={KIND_CHIP_MAP} />,
        ...(resource.isRecommended ? [() => <Chip tone="accent" text={RECOMMENDED_LABEL} />] : []),
    ]
    return <Cluster gap={3} items={chips} />
}

/** Placeholder rows for the loading mirror — no data, no press handler (§12c). */
const skeletonRows = (): Array<SurfaceCardListItem> =>
    Array.from({ length: SKELETON_ROW_COUNT }, (_unused, index) => ({
        key: `skeleton-${index}`,
        leading: () => <IconTile isSkeleton size="sm" />,
        title: "",
        subtitle: "",
    }))

/** One real row: numbered title, blurb, thumbnail-or-glyph, kind+recommended chips, caret. */
const resourceRow = (resource: FoundationResourceItem, position: number): SurfaceCardListItem => ({
    key: resource.id,
    leading: () => (
        <IconTile
            src={resource.thumbnailUrl}
            icon={StackIcon}
            size="sm"

        />
    ),
    // The block owns the numbering (§14d.1) — see file header for why it is
    // LOCAL to the current page rather than a running count across pages.
    title: `${position}. ${resource.title}`,
    subtitle: resource.description,
    meta: () => resourceMeta(resource),
    trailingIcon: CaretRightIcon,
    onPress: resource.onPress,
})

/**
 * The resource browse list. See the file header for the full contract, the
 * leaf boundary reasoning, and the judgement calls (local numbering, pager
 * placement, no retry action, `ariaLabel` as the region's only name).
 *
 * @param props - {@link FoundationResourceListProps}
 */
const FoundationResourceList = ({
    resources,
    isLoading,
    error,
    searchQuery,
    currentPage,
    totalPages,
    onPageChange,
    ariaLabel,
}: FoundationResourceListProps) => {
    const hasQuery = Boolean(searchQuery && searchQuery.trim().length > 0)

    const emptyContent: AsyncContentEmptyProps = hasQuery
        ? {
            icon: MagnifyingGlassIcon,
            title: `No resources found matching "${searchQuery}"`,
            description: EMPTY_DESCRIPTION_WITH_QUERY,

        }
        : {
            title: EMPTY_TITLE_NO_QUERY,

        }

    const errorContent: AsyncContentErrorProps = {
        title: ERROR_TITLE,

    }

    const rows: Array<SurfaceCardListItem> = resources.map((resource, index) => resourceRow(resource, index + 1))

    return (
        <div aria-label={ariaLabel} role={ariaLabel ? "region" : undefined}>
            <AsyncContent
                isLoading={isLoading}
                skeleton={() => (
                    <SurfaceCardList
                        items={skeletonRows()}
                        isSkeleton

                    />
                )}
                isEmpty={resources.length === 0}
                emptyContent={emptyContent}
                error={error}
                errorContent={errorContent}

                content={() => (
                    <StackV
                        gap={3}

                        items={[
                            () => <SurfaceCardList items={rows} />,
                            () => (
                                <div>
                                    <Pagination
                                        currentPage={currentPage}
                                        totalPages={totalPages}
                                        onPageChange={onPageChange}

                                    />
                                </div>
                            ),
                        ]}
                    />
                )}
            />
        </div>
    )
}

export { FoundationResourceList }

import { SearchAutocomplete, type SearchAutocompleteItem } from "@/components/atoms/forms/SearchAutocomplete"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH } from "@/components/frames/Stack"

/**
 * BLOCK — `FoundationSearchBar`: the search row — debounced-typeahead field
 * left, a live match count right, one `StackH` seam apart. See the component
 * file header for why this is a SIBLING of `FoundationCategorySearchBar`
 * (not a reach past it) and for the independent-count-loading axis that makes
 * it a distinct block rather than the same one reused.
 *
 * 📐 ONE LEAF (§14d.2). `isSkeleton`, `isCountLoading`, an empty vs. populated
 * suggestion list, and every value `resultCount` can take (unknown / zero / N)
 * are all DATA on the same fixed structure — no node appears or disappears —
 * so they are STATES inside the single `Default` leaf, not leaves of their own.
 */

/** One autocomplete suggestion row (id + label only — the generic shape this bar needs). */
export interface FoundationSearchSuggestion {
    /** Stable id — the payload `onSelectSuggestion` fires with. */
    id: string
    /** Display label for the suggestion row. */
    label: string
}

/** Props for {@link FoundationSearchBar}. */
export interface FoundationSearchBarProps {
    /** Current text in the search field (controlled, debounced upstream by the screen). */
    query: string
    /** Fired with the new query on every keystroke. */
    onQueryChange: (query: string) => void
    /** Suggestions for the current query, best match first. */
    suggestions: Array<FoundationSearchSuggestion>
    /** Fired with the chosen suggestion's id. */
    onSelectSuggestion: (id: string) => void
    /** Placeholder for the empty field. Defaults to "Search...". */
    placeholder?: string
    /**
     * How many results the current query matched. `undefined` means the count
     * itself is not known yet (first paint, before the count read has ever
     * answered) — distinct from a real `0`, which renders.
     */
    resultCount?: number
    /**
     * `true` while the count is (re-)fetching on ITS OWN SWR read — independent
     * of `suggestions`/the field, which may already be interactive. Only the
     * count slot shimmers.
     */
    isCountLoading?: boolean
    /** Renders the field's + count's resting skeleton mirrors instead of the real controls. */
    isSkeleton?: boolean
}

/** Count wording — this block's own vocabulary, never handed in by the caller. */
const resultCountLabel = (count: number): string => (count === 0 ? "No documents yet" : `${count} documents`)

/**
 * The search row: typeahead field left, live match count right. See the file
 * header for why this is a sibling of `FoundationCategorySearchBar` rather
 * than a reach past it, and why the count's three data conditions stay one leaf.
 *
 * @param props - {@link FoundationSearchBarProps}
 */
const FoundationSearchBar = ({
    query,
    onQueryChange,
    suggestions,
    onSelectSuggestion,
    placeholder = "Search documents...",
    resultCount,
    isCountLoading = false,
    isSkeleton = false,
}: FoundationSearchBarProps) => {
    // Domain suggestion → the atom's generic item shape (no `description` line:
    // this bar's rows carry only a bare label).
    const items: Array<SearchAutocompleteItem> = suggestions.map((suggestion) => ({
        id: suggestion.id,
        label: suggestion.label,
    }))

    return (
        <StackH
            gap={3}
            justify="between"
            principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            isSkeleton={isSkeleton}
            identity={{ tier: "block", component: "FoundationSearchBar" }}
            items={[
                () => (
                    <SearchAutocomplete
                        items={items}
                        inputValue={query}
                        onInputChange={onQueryChange}
                        onSelect={onSelectSuggestion}
                        placeholder={placeholder}
                        isSkeleton={isSkeleton}
                    />
                ),
                ...(isSkeleton || isCountLoading
                    ? [
                        () => (
                            <Typography
                                size="sm"
                                color="muted"
                                isSkeleton
                            />
                        ),
                    ]
                    : resultCount !== undefined
                        ? [
                            () => (
                                <Typography
                                    size="sm"
                                    color="muted"
                                    tabularNums
                                    text={resultCountLabel(resultCount)}
                                />
                            ),
                        ]
