/**
 * `LeaderboardCategoryNav` — the mobile chip row for switching which XP category
 * the leaderboard is sorted by (the `variant="chips"` half of `LeaderboardCategoryRail`;
 * the desktop `ListBox` rail lives in the learn-shell `leftRail` slot). Picking a
 * category re-sorts the same board — a facet toggle, not navigation — so it wraps
 * `Button.RadioGroup`. Which category is selected and each XP count are data on the
 * same chip row.
 */

/** The XP categories the leaderboard can be sorted by — mirrors the src's ranking keys. */
export type LeaderboardCategoryKey = "total" | "challenge" | "reading" | "milestone"

/** Label per category. The BLOCK owns this table — see file header. */
const CATEGORY_LABEL: Record<LeaderboardCategoryKey, string> = {
    total: "Total points",
    challenge: "Challenge",
    reading: "Reading",
    milestone: "Milestone",
}

/** Icon per category — same glyphs the desktop rail uses, so switching layout reads as ONE control. */
const CATEGORY_ICON: Record<LeaderboardCategoryKey, TypographyIcon> = {
    total: TrophyIcon,
    challenge: PuzzlePieceIcon,
    reading: BookOpenIcon,
    milestone: FlagIcon,
}

/** One category the nav offers — TYPED DOMAIN DATA only, never a formatted label. */
export interface LeaderboardCategoryOption {
    /** Which category this entry is. */
    key: LeaderboardCategoryKey
    /** Viewer's XP in this category — the number the block turns into "{xp} pts". */
    xp: number
}

/** Props for {@link LeaderboardCategoryNav}. */
export interface LeaderboardCategoryNavProps {
    /** Categories offered, in display order. */
    items: Array<LeaderboardCategoryOption>
    /** Which category the board is sorted by right now. */
    selected: LeaderboardCategoryKey
    /** Fired with the category the reader picked — the caller re-sorts the board, this block never does. */
    onSelect: (key: LeaderboardCategoryKey) => void
    /** Accessible name for the row, localized by the caller (blocks carry no i18n). */
    ariaLabel: string
    /**
     * @deprecated pass `classNames` instead — a free string cannot be constrained.
     * Kept only for `LeaderboardPage`'s `@app-lg:hidden`: a responsive visibility
     * toggle, not a positioning class, so it falls outside `AllowedClassName`
     * and could not be converted.
     */
    className?: string
}

/**
 * The mobile category chip row. See the file header for why this is only HALF of the src
 * `LeaderboardCategoryRail` (the desktop `ListBox` half lives in a shared layout slot, out
 * of scope) and why it reuses `Button.RadioGroup` rather than a hand-rolled scroll strip.
 *
 * @param props - {@link LeaderboardCategoryNavProps}
 */
const LeaderboardCategoryNav = ({
    items,
    selected,
    onSelect,
    ariaLabel,
    className,
}: LeaderboardCategoryNavProps) => (
    <div className={className}>
        <div>
            <ButtonRadioGroup
                ariaLabel={ariaLabel}
                value={selected}
                onChange={onSelect}
                items={items.map((item) => ({
                    value: item.key,
                    content: (
                        <Typography
                            size="sm"
                            prefixIcon={CATEGORY_ICON[item.key]}
                            text={`${CATEGORY_LABEL[item.key]} · ${item.xp} points`}

                        />
                    ),
                }))}
            />
        </div>
    </div>
)

export { LeaderboardCategoryNav }

"use client"

import React from "react"
import { Label, ListBox, Typography, cn } from "@heroui/react"
import { useTranslations } from "next-intl"
import { usePathname, useRouter, useSearchParams } from "next/navigation"
import {
    BookOpenIcon,
    FlagIcon,
    PuzzlePieceIcon,
    TrophyIcon,
} from "@phosphor-icons/react"
import type { Icon } from "@phosphor-icons/react"
import {
    categoryMyXp,
    parseCategoryParam,
    type LeaderboardCategoryKey,
} from "@/modules/utils/leaderboard"
import { useLeaderboardSwr } from "@/hooks/swr/api/graphql/queries/useLeaderboardSwr"

/** One row in the category rail. */
interface RailItem {
    key: LeaderboardCategoryKey
    icon: Icon
    label: string
    /** Viewer's XP in this category. */
    xp: number
    /** Optional muted caption ("9 lessons · ×3" / "Coming soon"). */
    caption?: string
    disabled?: boolean
}

/** Props for {@link LeaderboardCategoryRail}. */
export interface LeaderboardCategoryRailProps {
    /**
     * `rail` — the sidebar-style vertical list (desktop left rail, in the learn
     * shell's `leftRail` slot). `chips` — a horizontal scroll of pills above the
     * board (mobile, where the rail is hidden).
     */
    variant: "rail" | "chips"
}

/**
 * The XP-category selector — doubles as the viewer's XP composition (each row shows
 * *your* XP in that category) and the board's sort control. Self-contained: reads
 * the shared leaderboard fetch + drives the selection through the `?category=` URL
 * param, so it works from the left rail (a different layout slot than the board)
 * with no shared React state. `total` is the canonical ranking; `coding` is
 * disabled until the backend scores it per-course.
 *
 * @param props - {@link LeaderboardCategoryRailProps}
 */
export const LeaderboardCategoryRail = ({ variant }: LeaderboardCategoryRailProps) => {
    const t = useTranslations()
    const router = useRouter()
    const pathname = usePathname()
    const searchParams = useSearchParams()
    const { data } = useLeaderboardSwr()
    const myRank = data?.myRank ?? null

    const selected = parseCategoryParam(searchParams.get("category"))
    const onSelect = (key: LeaderboardCategoryKey) => {
        // merge into the existing query (preserve other params, joined with `&`)
        const params = new URLSearchParams(searchParams.toString())
        params.set("category", key)
        router.replace(`${pathname}?${params.toString()}`, { scroll: false })
    }

    const items: Array<RailItem> = [
        {
            key: "total",
            icon: TrophyIcon,
            label: t("leaderboard.categories.total"),
            xp: categoryMyXp(myRank, "total"),
        },
        {
            key: "challenge",
            icon: PuzzlePieceIcon,
            label: t("leaderboard.categories.challenge"),
            xp: categoryMyXp(myRank, "challenge"),
            caption: t("leaderboard.categories.captionChallenge", { count: myRank?.completedChallenges ?? 0 }),
        },
        {
            key: "reading",
            icon: BookOpenIcon,
            label: t("leaderboard.categories.reading"),
            xp: categoryMyXp(myRank, "reading"),
            caption: t("leaderboard.categories.captionReading", { count: myRank?.lessonsRead ?? 0 }),
        },
        {
            key: "milestone",
            icon: FlagIcon,
            label: t("leaderboard.categories.milestone"),
            xp: categoryMyXp(myRank, "milestone"),
            caption: t("leaderboard.categories.captionMilestone", { count: myRank?.milestoneProgress ?? 0 }),
        },
    ]

    // mobile: a horizontal scroll of category chips above the board
    if (variant === "chips") {
        return (
            <div className="-mx-1 flex gap-2 overflow-x-auto px-1 pb-1">
                {items.map((item) => {
                    const isSelected = item.key === selected
                    return (
                        <button
                            key={item.key}
                            type="button"
                            disabled={item.disabled}
                            onClick={() => onSelect(item.key)}
                            className={cn(
                                "flex shrink-0 cursor-pointer items-center gap-2 rounded-full border px-3 py-2 text-sm transition-colors",
                                isSelected ? "border-accent bg-accent-soft text-accent-soft-foreground" : "border-default text-muted hover:bg-default",
                                item.disabled && "cursor-not-allowed opacity-55",
                            )}
                        >
                            {/* icon inherits the button's text colour (muted / accent-soft
                                when selected) — same colour as the label, per the teacher's note. */}
                            <item.icon aria-hidden focusable="false" className="size-4 shrink-0" />
                            <span>{item.label}</span>
                            {!item.disabled ? (
                                <span className="font-medium">{t("leaderboard.xp", { xp: item.xp })}</span>
                            ) : null}
                        </button>
                    )
                })}
            </div>
        )
    }

    // desktop: vertical sidebar-style list (lives in the shell's left rail slot)
    return (
        <div className="flex flex-col gap-3 overflow-y-auto p-6">
            <Label>{t("leaderboard.categories.label")}</Label>
            <ListBox
                aria-label={t("leaderboard.categories.label")}
                selectionMode="single"
                disallowEmptySelection
                selectedKeys={[selected]}
                onSelectionChange={(keys) => {
                    // controlled single-select → drive the URL from the chosen key
                    const key = [...keys][0] as LeaderboardCategoryKey | undefined
                    if (key) {
                        onSelect(key)
                    }
                }}
                className="gap-1 p-0"
            >
                {items.map((item) => (
                    <ListBox.Item
                        key={item.key}
                        id={item.key}
                        textValue={item.label}
                        isDisabled={item.disabled}
                        className="cursor-pointer rounded-2xl px-3 py-2 data-[disabled=true]:cursor-not-allowed data-[hovered=true]:bg-default-100 data-[selected=true]:bg-accent-soft data-[disabled=true]:opacity-55"
                    >
                        <div className="flex items-center gap-3">
                            {/* icon = SAME colour as the label (per the teacher's note): foreground normally,
                                accent-soft when this category is the selected one. */}
                            <item.icon
                                aria-hidden
                                focusable="false"
                                className={cn(
                                    "size-5 shrink-0",
                                    item.key === selected ? "text-accent-soft-foreground" : "text-foreground",
                                )}
                            />
                            <div className="flex min-w-0 flex-1 flex-col gap-0">
                                <Typography
                                    type="body-sm"
                                    weight="medium"
                                    className={cn("line-clamp-1", item.key === selected && "text-accent-soft-foreground")}
                                >
                                    {item.label}
                                </Typography>
                                {item.caption ? (
                                    <Typography type="body-xs" color="muted" className="line-clamp-1">
                                        {item.caption}
                                    </Typography>
                                ) : null}
                            </div>
                            <Typography
                                type="body-sm"
                                weight="medium"
                                className={cn("shrink-0", item.key === selected ? "text-accent-soft-foreground" : "text-muted")}
                            >
                                {item.disabled ? "—" : t("leaderboard.xp", { xp: item.xp })}
                            </Typography>
                        </div>
                    </ListBox.Item>
                ))}
            </ListBox>
        </div>
    )
}

export default LeaderboardCategoryRail

import React from "react"
import { Breadcrumbs } from "@/components/atoms/navigation/Breadcrumbs"
import { PageHeader } from "@/components/composites/layout/Page"

/**
 * `LeaderboardHeader` — the page-identity cluster at the top of the leaderboard
 * screen: trail, title, subtitle, nothing else. Wraps `PageHeader` in a
 * domain-named block; it carries no meta chips because rank and score live in the
 * list below. A missing subtitle is a data condition on the same three-part cluster.
 */

/** One breadcrumb link — plain data, the block builds the atom from it. */
export interface LeaderboardHeaderCrumb {
    /** Stable React key. */
    key: string
    /** Display label. */
    label: string
    /** Has a handler → the crumb is pressable; the current page leaves it out. */
    onPress?: () => void
}

/** Props for {@link LeaderboardHeader}. */
export interface LeaderboardHeaderProps {
    /** Breadcrumb trail as DATA — the block builds `Breadcrumbs` itself. */
    breadcrumbItems: Array<LeaderboardHeaderCrumb>
    /** Page title, e.g. "Leaderboard". */
    title: string
    /** One-sentence subtitle explaining what the ranking measures. */
    description?: string
    /**
     * `true` → every composed atom switches to its own shimmer. The flag FLOWS
     * DOWN into the real atoms rather than building a parallel skeleton tree
     * (§12c), so the shimmer keeps the exact box of the thing it replaces.
     */
    isSkeleton?: boolean
}

/**
 * Leaderboard page identity — trail, title, subtitle. See the file header for
 * why this stays a thin sibling of `ContentHeader`/`ModuleHeader` rather than
 * the screen calling `PageHeader` directly.
 *
 * @param props - {@link LeaderboardHeaderProps}
 */
const LeaderboardHeader = ({
    breadcrumbItems,
    title,
    description,
    isSkeleton = false,
}: LeaderboardHeaderProps) => {
    return (
        // Identity hold: PageHeader does not accept CallerIdentity (ledger PageHeader gap).
        <PageHeader
            isSkeleton={isSkeleton}
            breadcrumb={() =>
                isSkeleton || breadcrumbItems.length ? (
                    // Hold: no hug-width frame for breadcrumb measure (`w-fit` parent placement).
                    <div className="w-fit">
                        <Breadcrumbs
                            collapseOnMobile
                            collapseFrom={4}
                            items={breadcrumbItems}
                            isSkeleton={isSkeleton}
                        />
                    </div>
                ) : undefined
            }
            title={title}
            description={description}
        />
    )
}

export { LeaderboardHeader }

import React from "react"
import { ArrowClockwiseIcon } from "@phosphor-icons/react"
import { Button } from "@/components/atoms/buttons/Button"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH } from "@/components/frames/Stack"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"

/**
 * `LeaderboardToolbar` — the strip above the ranking: "ranked by X" on the left, a
 * quiet last-updated fact beside it, a plain refresh button on the right. It sits
 * outside the board's async region, hence its own block. Hand-composed from atoms —
 * no composite draws this "label · muted timestamp · secondary button" shape. Owns
 * the "Ranked by …" template and the relative-time phrasing built from a plain
 * `updatedAt: Date`. Whether the timestamp has landed and whether a refresh is in
 * flight are states on the same three-slot row.
 */

/** Props for {@link LeaderboardToolbar}. */
export interface LeaderboardToolbarProps {
    /** What the ranking is sorted by, e.g. "this week's XP". The block builds the sentence around it. */
    categoryLabel: string
    /** When the board last refreshed. Omitted → nothing has loaded yet, so no timestamp is claimed. */
    updatedAt?: Date
    /** Fired when the reader asks for a fresh ranking. */
    onRefresh: () => void
    /** `true` → a refresh is in flight; the button carries its own busy skin and locks the press. */
    isRefreshing?: boolean
    /** Localized trigger word for the refresh button, e.g. "Refresh" (blocks carry no i18n). */
    refreshLabel: string
    /** Extra classes on the row, from the closed atom/frame union. */
    classNames?: Array<AllowedClassName>
}

/**
 * Vietnamese relative-time wording — this block's own vocabulary, built from a
 * plain `Date` so the caller never hands over a pre-formatted string.
 */
const formatUpdatedAt = (updatedAt: Date): string => {
    const diffMinutes = Math.floor((Date.now() - updatedAt.getTime()) / 60_000)
    if (diffMinutes < 1) return "Just updated"
    if (diffMinutes < 60) return `Updated ${diffMinutes} minutes ago`
    const diffHours = Math.floor(diffMinutes / 60)
    if (diffHours < 24) return `Updated ${diffHours} hours ago`
    const diffDays = Math.floor(diffHours / 24)
    return `Updated ${diffDays} days ago`
}

/**
 * The leaderboard's chrome strip. See the file header for why it is
 * hand-composed and why it stays one leaf.
 *
 * @param props - {@link LeaderboardToolbarProps}
 */
const LeaderboardToolbar = ({
    categoryLabel,
    updatedAt,
    onRefresh,
    isRefreshing = false,
    refreshLabel,
    classNames,
}: LeaderboardToolbarProps) => (
    <StackH
        gap={3}
        principle="flex-action"
        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
        align="center"
        classNames={classNames}

        items={[
            () => (
                <Typography
                    size="sm"
                    weight="medium"
                    text={`Ranked by ${categoryLabel}`}

                />
            ),
            // no icon here — §5a.2: a clock needs an ASSOCIATION step to read as "time"
            // (not a universal symbol like ✓/🔒), and the text already carries the fact.
            ...(updatedAt != null ? [() => (
                <Typography
                    size="xs"
                    color="muted"
                    text={formatUpdatedAt(updatedAt)}

                />
            )] : []),
            // Pushes the refresh button to the row's trailing edge without a second
            // nested track — same spacer idiom `WorkSessionHeader` already uses.
            () => <span aria-hidden className="flex-1" />,
            () => (
                <Button
                    label={refreshLabel}
                    variant="secondary"
                    size="sm"
                    prefixIcon={ArrowClockwiseIcon}
                    isPending={isRefreshing}
                    onPress={onRefresh}
                />
            ),
        ]}
    />
)

export { LeaderboardToolbar }

"use client"

import {
    ListBulletsIcon,
    ListIcon,
} from "@phosphor-icons/react"
import React, { useEffect, useState } from "react"
import { Button, Drawer, ScrollShadow } from "@heroui/react"
import { useTranslations } from "next-intl"
import { useRouter, useSelectedLayoutSegments } from "next/navigation"
import { ContentMap } from "@/components/blocks/learn/ContentMap"
import {
    useSidebarNavItems,
} from "@/hooks/useSidebarNavItems"
import { SidebarNavItem } from "@/components/blocks/navigation/SidebarNavItem"
import { SidebarNavAccordionGroup } from "@/components/blocks/navigation/SidebarNavAccordionGroup"

/** Props for {@link LearnMobileBar}. */
export type LearnMobileBarProps = Record<string, never>
/**
 * Mobile toolbar for the course-learn pages (hidden from `lg` up).
 *
 * Container: surfaces the two sidebars that are hidden on small screens as
 * slide-in drawers — the course nav (left) and the module outline (right). The
 * nav rows reuse the {@link SidebarNavItem} block (always expanded here) and
 * self-route via the shared select handler. Each drawer is controlled by local
 * open state. `"use client"` for the interactive triggers + shared nav hook.
 * @param props - {@link LearnMobileBarProps}
 */
export const LearnMobileBar = () => {
    const t = useTranslations()
    const router = useRouter()
    // shared course-nav entries (same list the desktop sidebar renders)
    const { items, selectedTab, onSelect } = useSidebarNavItems()
    // the module-outline (ContentMap) drawer only makes sense on the content reader
    // routes; on other surfaces (flashcards / leaderboard / foundations…) it would
    // open the wrong tree, so the outline trigger + drawer are hidden there.
    const segments = useSelectedLayoutSegments()
    const isContentRoute = segments.includes("modules") || segments[0] === "content"
    // open state for the left (course menu) drawer
    const [isMenuOpen, setMenuOpen] = useState(false)
    // open state for the right (module outline) drawer
    const [isOutlineOpen, setOutlineOpen] = useState(false)

    // rows self-dispatch their tab + navigation; collapse the drawer whenever the
    // active tab changes so the user lands back on the content
    useEffect(() => {
        setMenuOpen(false)
    }, [selectedTab])

    return (
        // fixed FOOTER bar (mirrors LearnMobileTabBar's own bottom placement — every
        // learn page's mobile chrome lives in the SAME footer zone, whether it renders
        // this simple drawer trigger or the reader's full tab bar); mobile/tablet only
        <div className={"fixed bottom-0 left-0 right-[var(--app-rail-w,0px)] z-40 flex h-16 items-center gap-3 border-t bg-background/90 px-3 backdrop-blur-xl @app-lg:hidden"}>
            {/* trigger: open the course navigation drawer */}
            <Button variant="ghost" size="sm" onPress={() => setMenuOpen(true)}>
                <ListIcon className="size-5" />
                {t("nav.courseMenu")}
            </Button>
            {/* trigger: open the module outline drawer — content reader routes only */}
            {isContentRoute ? (
                <Button variant="ghost" size="sm" onPress={() => setOutlineOpen(true)}>
                    <ListBulletsIcon className="size-5" />
                    {t("nav.contentOutline")}
                </Button>
            ) : null}

            {/* left drawer — course-learn navigation list */}
            <Drawer>
                <Drawer.Backdrop isOpen={isMenuOpen} onOpenChange={setMenuOpen}>
                    <Drawer.Content placement="left">
                        <Drawer.Dialog className="p-0">
                            <div className="p-3">
                                <Drawer.CloseTrigger />
                                <Drawer.Header>
                                    <Drawer.Heading>{t("nav.courseMenu")}</Drawer.Heading>
                                </Drawer.Header>
                            </div>
                            <div className="border-b" />
                            <Drawer.Body className="p-3">
                                <div className="flex flex-col gap-3">
                                    {items.map((item) => (
                                        item.children ? (
                                            <SidebarNavAccordionGroup
                                                key={item.value}
                                                icon={item.icon}
                                                label={item.label}
                                                items={item.children.map((child) => ({
                                                    value: child.value,
                                                    label: child.label,
                                                    isActive: child.isActive,
                                                    onPress: () => {
                                                        setMenuOpen(false)
                                                        router.push(child.url)
                                                    },
                                                }))}
                                            />
                                        ) : (
                                            <SidebarNavItem
                                                key={item.value}
                                                icon={<item.icon className="size-5 shrink-0" />}
                                                label={item.label}
                                                isActive={selectedTab === item.tab}
                                                onPress={() => onSelect(item)}
                                            />
                                        )
                                    ))}
                                </div>
                            </Drawer.Body>
                        </Drawer.Dialog>
                    </Drawer.Content>
                </Drawer.Backdrop>
            </Drawer>

            {/* right drawer — module + content outline (content reader routes only) */}
            {isContentRoute ? (
                <Drawer>
                    <Drawer.Backdrop isOpen={isOutlineOpen} onOpenChange={setOutlineOpen}>
                        <Drawer.Content placement="right">
                            <Drawer.Dialog className="p-0">
                                <div className="p-3">
                                    <Drawer.CloseTrigger />
                                    <Drawer.Header>
                                        <Drawer.Heading>{t("nav.contentOutline")}</Drawer.Heading>
                                    </Drawer.Header>
                                </div>
                                <div className="border-b" />
                                <Drawer.Body className="p-0">
                                    <ScrollShadow hideScrollBar className="h-full overflow-y-auto">
                                        <ContentMap />
                                    </ScrollShadow>
                                </Drawer.Body>
                            </Drawer.Dialog>
                        </Drawer.Content>
                    </Drawer.Backdrop>
                </Drawer>
            ) : null}
        </div>
    )
}

"use client"

import {
    BookOpenIcon,
    ListIcon,
    ListBulletsIcon,
} from "@phosphor-icons/react"
import React, { useEffect } from "react"
import { cn } from "@heroui/react"
import { useTranslations } from "next-intl"
import { ContentMap } from "@/components/blocks/learn/ContentMap"
import { OnThisPage } from "@/components/blocks/learn/OnThisPage"
import { useTableOfContents } from "@/components/blocks/learn/OnThisPage/hooks/useTableOfContents"
import { useSidebarNavItems } from "@/hooks/useSidebarNavItems"
import { SidebarNavItem } from "@/components/blocks/navigation/SidebarNavItem"
import { useAppDispatch, useAppSelector } from "@/redux/hooks"
import { setMobileView, type MobileLearnView } from "@/redux/slices/sidebar"

/**
 * Mobile bottom-tab bar for the lesson reader (hidden from `lg` up).
 *
 * The desktop 4-column layout (course-nav · content-map · content · on-this-page)
 * has no room on phones, so this collapses it into an app-style bottom-tab: one
 * full-screen view at a time, thumb-reachable. Three tabs —
 *  - **Contents**: course-nav rows ({@link SidebarNavItem}) + the {@link ContentMap}
 *    lesson list (both are "navigation");
 *  - **Lesson**: the content itself (the reader is rendered by the shell — this
 *    tab just closes the overlays);
 *  - **On this page**: the {@link OnThisPage} outline (self-hides → tab omitted when
 *    the lesson has no headings).
 *
 * Selecting a new lesson lands the reader back on the content view. State lives in
 * the `sidebar` slice (`mobileView`) so the shell can mount the matching view.
 */
export const LearnMobileTabBar = () => {
    const t = useTranslations()
    const dispatch = useAppDispatch()
    const view = useAppSelector((state) => state.sidebar.mobileView)
    const contentId = useAppSelector((state) => state.content.id)
    const { items, selectedTab, onSelect } = useSidebarNavItems()
    // mirror OnThisPage's self-hide: no headings → no "on this page" tab
    const { headings } = useTableOfContents(contentId)
    const hasToc = headings.length > 0

    // opening a new lesson (from the map) lands the reader back on the content
    useEffect(() => {
        dispatch(setMobileView("content"))
    }, [contentId, dispatch])

    // never strand the user on an "On this page" tab that just vanished
    useEffect(() => {
        if (view === "toc" && !hasToc) {
            dispatch(setMobileView("content"))
        }
    }, [view, hasToc, dispatch])

    const tabs: Array<{ key: MobileLearnView; icon: typeof ListIcon; label: string }> = [
        { key: "map", icon: ListIcon, label: t("learnTabs.contents") },
        { key: "content", icon: BookOpenIcon, label: t("learnTabs.lesson") },
        ...(hasToc
            ? [{ key: "toc" as const, icon: ListBulletsIcon, label: t("learnTabs.onThisPage") }]
            : []),
    ]

    return (
        <>
            {/* full-screen "Contents" overlay — course-nav + the lesson list */}
            {view === "map" && (
                <div className="fixed top-16 bottom-16 left-0 right-[var(--app-rail-w,0px)] z-30 overflow-y-auto bg-background @app-lg:hidden">
                    <div className="flex flex-col gap-3 p-6">
                        {items.map((item) => (
                            <SidebarNavItem
                                key={item.value}
                                icon={<item.icon className="size-5 shrink-0" />}
                                label={item.label}
                                isActive={selectedTab === item.tab}
                                onPress={() => onSelect(item)}
                            />
                        ))}
                    </div>
                    <div className="border-t" />
                    <ContentMap />
                </div>
            )}

            {/* full-screen "On this page" overlay — the lesson outline + actions */}
            {view === "toc" && hasToc && (
                <div className="fixed top-16 bottom-16 left-0 right-[var(--app-rail-w,0px)] z-30 overflow-y-auto bg-background @app-lg:hidden">
                    <OnThisPage mobile />
                </div>
            )}

            {/* the bottom-tab bar itself */}
            <nav
                role="tablist"
                aria-label={t("learnTabs.contents")}
                className="fixed bottom-0 left-0 right-[var(--app-rail-w,0px)] z-40 flex h-16 border-t bg-background/90 backdrop-blur-xl @app-lg:hidden"
            >
                {tabs.map((tab) => {
                    const isActive = view === tab.key
                    return (
                        <button
                            key={tab.key}
                            type="button"
                            role="tab"
                            aria-selected={isActive}
                            onClick={() => dispatch(setMobileView(tab.key))}
                            className={cn(
                                "flex flex-1 flex-col items-center justify-center gap-2 outline-none",
                                "focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-inset",
                                isActive ? "text-accent-soft-foreground" : "text-muted",
                            )}
                        >
                            <tab.icon className="size-5" />
                            <span className="text-xs">{tab.label}</span>
                        </button>
                    )
                })}
            </nav>
        </>
    )
}

