"use client"

import React, {
    useCallback,
    useEffect,
    useMemo,
    useState,
} from "react"
import {
    useRouter,
} from "next/navigation"
import {
    useLocale,
} from "next-intl"
import {
    useTranslations,
} from "next-intl"
import {
    pathConfig,
} from "@/resources/path"
import {
    MilestoneIndexStrip,
} from "./MilestoneIndexStrip"
import { useQueryMilestonesSwr } from "@/hooks/swr/api/graphql/queries/useQueryMilestonesSwr"
import { useQueryMilestoneTaskProgressSwr } from "@/hooks/swr/api/graphql/queries/useQueryMilestoneTaskProgressSwr"
import { useAppSelector, useAppDispatch } from "@/redux/hooks"
import { setSelectedTaskId } from "@/redux/slices/milestone"
import { OutlineRail } from "@/components/blocks/navigation/OutlineRail"
import type { OutlineRailGroup } from "@/components/blocks/navigation/OutlineRail"
import type { MilestoneEntity } from "@/modules/types/entities/milestone"
import { buildMilestoneTaskProgressLookup, isPersonalProjectTaskActionUnlocked } from "@/components/utils/task-lookup"

/**
 * Props for {@link MilestoneOutline}.
 */
type MilestoneOutlineProps = {
    /** Collapsed mode: render a slim numbered index instead of the full list. */
    collapsed?: boolean
}

/**
 * Filter milestones + their tasks by a lower-cased query (milestone title match keeps
 * all its tasks; otherwise only matching tasks survive). Empty query → unchanged.
 */
const filterMilestones = (
    milestones: Array<MilestoneEntity>,
    query: string,
): Array<MilestoneEntity> => {
    if (!query) {
        return milestones
    }
    const result: Array<MilestoneEntity> = []
    for (const milestone of milestones) {
        const matches = (milestone.title ?? "").toLowerCase().includes(query)
        const tasks = matches
            ? (milestone.tasks ?? [])
            : (milestone.tasks ?? []).filter((task) => task.title.toLowerCase().includes(query))
        if (matches || tasks.length > 0) {
            result.push({ ...milestone, tasks })
        }
    }
    return result
}

/**
 * Milestone navigation rail for the personal-project capstone — rendered through
 * the SAME shared {@link OutlineRail} block as the course content-map, so the two
 * rails look identical (progress header + "Go to current lesson" continue, search, and
 * milestone → task rows). This is a thin data wrapper: owns the milestones/progress
 * SWR singletons, the Redux task selection + unlock logic, and the controlled
 * search/expand state; it maps milestones→groups and tasks→rows for the block.
 *
 * `collapsed` keeps the slim numbered {@link MilestoneIndexStrip} for the rail's
 * collapse handle. `"use client"` for hooks.
 * @param props - optional collapsed flag
 */
export const MilestoneOutline = ({ collapsed = false }: MilestoneOutlineProps) => {
    const t = useTranslations()
    const milestonesSwr = useQueryMilestonesSwr()
    const progressSwr = useQueryMilestoneTaskProgressSwr()
    const dispatch = useAppDispatch()
    const router = useRouter()
    const locale = useLocale()
    const courseDisplayId = useAppSelector((state) => state.course.displayId)
    const milestoneEntities = useAppSelector((state) => state.milestone.entities)
    const selectedTaskId = useAppSelector((state) => state.milestone.selectedTaskId)

    /** Milestones sorted by their display order. */
    const milestones = useMemo(
        () => [...milestoneEntities].sort((prev, next) => prev.sortIndex - next.sortIndex),
        [milestoneEntities],
    )

    /** Build a map of taskId -> progress item for quick lookup. */
    const progressMap = useMemo(
        () => buildMilestoneTaskProgressLookup(
            progressSwr.data?.milestoneTaskProgress?.data?.completionTasks,
        ),
        [progressSwr.data],
    )
    const currentTaskId = progressSwr.data?.milestoneTaskProgress?.data?.currentTask?.id

    /** Whether a task is unlocked (all previous tasks completed or it's the current task). */
    const isTaskUnlocked = useCallback(
        (taskId: string) => isPersonalProjectTaskActionUnlocked(taskId, progressMap, currentTaskId),
        [progressMap, currentTaskId],
    )

    /** Select a task: store the id in redux and route to its learn page. */
    const onSelectTask = useCallback(
        (taskId: string) => {
            dispatch(setSelectedTaskId(taskId))
            router.push(
                pathConfig().locale(locale).course(courseDisplayId).learn().personalProject(taskId).build(),
            )
        },
        [dispatch, router, locale, courseDisplayId],
    )

    /** Milestone that owns the currently selected task. */
    const activeMilestoneId = useMemo(() => {
        if (!selectedTaskId) {
            return undefined
        }
        const owner = milestones.find((milestone) =>
            (milestone.tasks ?? []).some((task) => task.id === selectedTaskId))
        return owner ? String(owner.id) : undefined
    }, [milestones, selectedTaskId])

    // ---- collapsed rail (slim numbered index) -------------------------------
    /** Collapsed-rail press: jump to the first task of the chosen milestone. */
    const onSelectMilestone = useCallback(
        (milestoneId: string) => {
            const milestone = milestones.find((entity) => String(entity.id) === milestoneId)
            const firstTask = (milestone?.tasks ?? [])
                .slice()
                .sort((prev, next) => prev.sortIndex - next.sortIndex)[0]
            if (firstTask) {
                onSelectTask(firstTask.id)
            }
        },
        [milestones, onSelectTask],
    )

    // ---- search + controlled expand (mirrors ContentMap) --------------------
    const [search, setSearch] = useState("")
    const query = search.trim().toLowerCase()
    const filteredMilestones = useMemo(
        () => filterMilestones(milestones, query),
        [milestones, query],
    )

    const [expandedKeys, setExpandedKeys] = useState<Set<string>>(new Set())
    useEffect(() => {
        if (!activeMilestoneId) {
            return
        }
        setExpandedKeys((prev) => prev.has(activeMilestoneId) ? prev : new Set(prev).add(activeMilestoneId))
    }, [activeMilestoneId])
    useEffect(() => {
        if (query) {
            setExpandedKeys(new Set(filteredMilestones.map((milestone) => String(milestone.id))))
        }
    }, [query, filteredMilestones])

    // ---- header progress (tasks done / total across all milestones) ---------
    const taskTotals = useMemo(() => {
        let done = 0
        let total = 0
        for (const milestone of milestones) {
            for (const task of milestone.tasks ?? []) {
                total += 1
                if (progressMap.get(task.id)?.completed) {
                    done += 1
                }
            }
        }
        return { done, total }
    }, [milestones, progressMap])

    // ---- milestones → rail groups -------------------------------------------
    const groups = useMemo<Array<OutlineRailGroup>>(
        () => filteredMilestones.map((milestone) => {
            const tasks = (milestone.tasks ?? [])
                .slice()
                .sort((prev, next) => prev.sortIndex - next.sortIndex)
            const doneCount = tasks.filter((task) => progressMap.get(task.id)?.completed).length
            return {
                id: String(milestone.id),
                title: `${milestone.sortIndex}. ${milestone.title || "Milestone"}`,
                progress: { done: doneCount, total: tasks.length },
                collapsedCountLabel: t("courseContents.moduleLessons", {
                    read: doneCount,
                    total: tasks.length,
                }),
                items: tasks.map((task) => ({
                    id: task.id,
                    title: `${task.sortIndex}. ${task.title}`,
                    isActive: selectedTaskId === task.id,
                    isRead: progressMap.get(task.id)?.completed ?? false,
                    isLocked: !isTaskUnlocked(task.id),
                    isPremium: false,
                    onPress: () => onSelectTask(task.id),
                })),
            }
        }),
        [filteredMilestones, progressMap, selectedTaskId, isTaskUnlocked, onSelectTask, t],
    )

    // loading gate: prefer cached redux milestones (SWR hydrates into entities)
    const hasData = milestones.length > 0
    const isLoading = !hasData && !milestonesSwr.error && (milestonesSwr.isLoading || !milestonesSwr.data)
    const isEmpty = !hasData && !milestonesSwr.isLoading && !!milestonesSwr.data && !milestonesSwr.error

    // collapsed rail: only the slim numbered index (clicking a number jumps to that milestone)
    if (collapsed) {
        return (
            <div className="@app-lg:min-h-0 @app-lg:flex-1 @app-lg:overflow-y-auto">
                <MilestoneIndexStrip
                    milestones={milestones}
                    activeMilestoneId={activeMilestoneId}
                    onSelectMilestone={onSelectMilestone}
                />
            </div>
        )
    }

    return (
        <OutlineRail
            className="@app-lg:min-h-0 @app-lg:flex-1"
            header={taskTotals.total > 0 ? {
                label: t("courseContents.progress"),
                progress: { done: taskTotals.done, total: taskTotals.total },
                countLabel: t("courseContents.contentCount", {
                    read: taskTotals.done,
                    total: taskTotals.total,
                }),
                continue: currentTaskId && currentTaskId !== selectedTaskId ? {
                    label: t("task.previewLockedGoToCurrentTaskButton"),
                    onPress: () => onSelectTask(currentTaskId),
                } : undefined,
            } : undefined}
            search={{
                value: search,
                onChange: setSearch,
                placeholder: t("finalProject.page.searchTaskPlaceholder"),
                ariaLabel: t("finalProject.page.searchTaskPlaceholder"),
            }}
            groups={groups}
            expandedKeys={expandedKeys}
            onExpandedChange={setExpandedKeys}
            isSkeleton={isLoading}
            async={{
                isEmpty,
                emptyTitle: t("courseContents.empty"),
                errorTitle: t("task.loadErrorTitle"),
                error: !hasData ? milestonesSwr.error : undefined,
                onRetry: () => { void milestonesSwr.mutate() },
                retryLabel: t("courseContents.retry"),
                noMatchLabel: t("courseContents.noMatch"),
            }}
        />
    )
}

import React from "react"
import { CheckCircleIcon, ArrowRightIcon } from "@phosphor-icons/react"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { Typography } from "@/components/atoms/text/Typography"
import { Button } from "@/components/atoms/buttons/Button"
import { StackV } from "@/components/frames/Stack"

/**
 * BLOCK — `MilestoneUpNextCard`: the passed-attempt handoff to the NEXT
 * unlocked milestone task on a capstone track. Distinct from the challenge
 * flow (no such fixed handoff exists there) — see the component file header.
 *
 * 📐 TWO LEAVES (§14d.2). `showCheck` and `isSkeleton` only toggle a glyph or
 * mirror the existing shape — neither changes what is composed, so both are
 * STATES of `Default`. `isHighlight` is different: it adds/removes the
 * highlight streak, a real DOM node, so its two values are the `Default`
 * (highlighted, the milestone screen's original shape) and `Plain` (reused by
 * `ContentPage`'s mobile/tablet nudge — see that component's file header for
 * why the default doesn't fit there) leaves.
 */

/** Props for {@link MilestoneUpNextCard}. */
export interface MilestoneUpNextCardProps {
    /** Small label above the title, e.g. "Next task". */
    eyebrow: string
    /** `true` → a check glyph sits beside the eyebrow, marking the attempt just passed. */
    showCheck?: boolean
    /** Name of the next unlocked milestone task. */
    title: string
    /** One line describing what the next task asks for. */
    description: string
    /** CTA label, e.g. "Start task 3". */
    ctaLabel: string
    /** Press the CTA. */
    onPress?: () => void
    /** `true` → the card face carries the highlight streak (the ONE focal action on its screen). @default true */
    isHighlight?: boolean
    /** `true` → every composed atom mirrors as shimmer. */
    isSkeleton?: boolean
}

/**
 * The single "what's next" highlight card shown right after a passed
 * milestone attempt, handing off to the next unlocked task on the track.
 *
 * @param props - {@link MilestoneUpNextCardProps}
 */
const MilestoneUpNextCard = ({
    eyebrow,
    showCheck = false,
    title,
    description,
    ctaLabel,
    onPress,
    isHighlight = true,
    isSkeleton = false,
}: MilestoneUpNextCardProps) => (
    <SurfaceCard
        identity={{ tier: "block", component: "MilestoneUpNextCard" }}
        isHighlight={isHighlight}
        isSkeleton={isSkeleton}
        body={() => (
            <StackV
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={[
                    // Back INSIDE the card face (not `SurfaceCard.label`,
                    // which sits OUTSIDE/above it) — a plain atom call, not raw CSS, so no
                    // shape-tier violation either way; this is a visual placement call.
                    () => (
                        <Typography
                            size="xs"
                            color="muted"
                            prefixIcon={showCheck ? CheckCircleIcon : undefined}
                            isSkeleton={isSkeleton}
                            text={eyebrow}

                        />
                    ),
                    // Real `UpNextCard` leaves `type` unset on its title
                    // Typography, which defaults to HeroUI's `type="body"` = `text-base`
                    // (verify `typography.css` `.typography--body`). `weight="semibold"`
                    // folds to `"medium"` at body
                    // scale, not `"bold"`.
                    () => (
                        <Typography
                            size="base"
                            weight="medium"
                            isSkeleton={isSkeleton}
                            text={title}

                        />
                    ),
                    () => (
                        <Typography
                            size="sm"
                            color="muted"
                            isSkeleton={isSkeleton}
                            text={description}

                        />
                    ),
                    () => (
                        <Button
                            isSkeleton={isSkeleton}
                            variant="primary"
                            size="sm"
                            label={ctaLabel}
                            suffixIcon={ArrowRightIcon}
                            iconSlide
                            onPress={onPress}
                            classNames={["w-fit", "shrink-0"]}

                        />
                    ),
                ]}
            />
        )}
    />
)

export { MilestoneUpNextCard }

import React from "react"
import { ArrowRightIcon } from "@phosphor-icons/react"
import { Button } from "@/components/atoms/buttons/Button"
import { Typography } from "@/components/atoms/text/Typography"
import { Box } from "@/components/frames/Box"

/**
 * `MindMapContinueButton` — the single floating "what's next" action over the
 * course mind-map. `resumeHref` swaps the whole node from a pressable `Button`
 * (with arrow) to an inert `Typography` note — two different atoms — so "resume
 * available" and "all done" are separate shapes; `isSkeleton` is its own too. The
 * real component renders nothing for a guest whose progress has not resolved.
 */

/** Label the block writes itself (§14d.1) — not opened to the caller. */
const CONTINUE_LABEL = "Continue"
/** Quiet confirmation once every lesson/challenge on the map has been read. */
const ALL_DONE_LABEL = "You've completed everything"

/** Props for {@link MindMapContinueButton}. */
export interface MindMapContinueButtonProps {
    /**
 * Href of the viewer's next unread lesson/challenge, or `null` when none
 * resolves. Non-null is the single source of truth for "show the resume
 * pill" — see the file header for why it outranks {@link allContentDone}.
 */
    resumeHref: string | null
    /**
 * `true` -> the viewer has read everything the map has to offer. Only
 * consulted when {@link resumeHref} is `null`; ignored otherwise.
 */
    allContentDone: boolean
    /**
 * Fired on a resume press. Optional: the button itself only renders while
 * {@link resumeHref} is set, so a caller mid-wiring still sees the true shape.
 */
    onResume?: () => void
    /**
 * Accessible name for the resume action, localized by the caller (blocks
 * carry no i18n) — richer than the visible "Continue" label alone, since a
 * screen reader hears it with no page context around it.
 */
    continueAriaLabel: string
    /** `true` -> the block shows its loading shimmer instead of either leaf. */
    isSkeleton?: boolean
}

/**
 * The map's one primary action. See the file header for the three-way
 * precedence and why the two real leaves are two different atoms.
 *
 * @param props - {@link MindMapContinueButtonProps}
 */
const MindMapContinueButton = ({
    resumeHref,
    allContentDone,
    onResume,
    continueAriaLabel,
    isSkeleton = false,
}: MindMapContinueButtonProps) => {
    if (isSkeleton) {
        return (
            <Button
                isSkeleton
                size="lg"
                label={CONTINUE_LABEL}
            />
        )
    }

    if (resumeHref != null) {
        return (
            <Button
                variant="primary"
                size="lg"
                label={CONTINUE_LABEL}
                suffixIcon={ArrowRightIcon}
                iconSlide
                ariaLabel={continueAriaLabel}
                onPress={onResume}
                isElevated
            />
        )
    }

    if (allContentDone) {
        return (
            // TODO(atom): heavy skin-shape (rounded-full + border + bg + shadow — raised pill)
            // should become an atom/composite (Chip/Button/SurfaceCard) — a frame cannot own it,
            // wrap with Box + principles for now.
            <Box
                principle="control-pad" className="rounded-full border border-default bg-surface px-3 py-2 shadow-lg"
                explain="Control hit-area inset — not row-pad, because this pads a single interactive control rather than a full content row."
            >
                <Typography
                    size="sm"
                    weight="semibold"
                    color="success"
                    text={ALL_DONE_LABEL}
                />
            </Box>
        )
    }

    // Neither a resolved resume target nor a confirmed "all done" — e.g. a guest
    // whose progress has not loaded into a verdict either way. There is nothing
    // true this block can claim yet, so it renders nothing rather than guessing.
    return null
}

export { MindMapContinueButton }

import React from "react"
import { ArrowRightIcon } from "@phosphor-icons/react"
import { Button } from "@/components/atoms/buttons/Button"

/**
 * `MockInterviewAnswerAction` — the one control that submits the candidate's
 * current answer and advances the live interview. Exists as a one-node block so the
 * screen tier need not import a bare `Button` directly; it holds the
 * `isLastQuestion` decision and wording the button alone cannot own. `isLastQuestion`
 * / `isDisabled` / `isPending` flip the same button's label and press-ability.
 */

/** Props for {@link MockInterviewAnswerAction}. */
export interface MockInterviewAnswerActionProps {
    /** `true` → this is the run's final question; swaps the label to the finishing wording. */
    isLastQuestion: boolean
    /** Fired when the candidate submits the current answer. */
    onSubmit: () => void
    /** `true` → the caller has decided this press cannot fire right now (e.g. a blank answer, or the interviewer still mid-turn). */
    isDisabled?: boolean
    /** `true` → the submit request is in flight. */
    isPending?: boolean
}

/**
 * The live interview's one submit action. See the file header for why this
 * exists as its own block instead of a bare `Button` in the screen tree.
 *
 * @param props - {@link MockInterviewAnswerActionProps}
 */
const MockInterviewAnswerAction = ({
    isLastQuestion,
    onSubmit,
    isDisabled = false,
