        onPress={onSubmit}
        isDisabled={isDisabled}
        isPending={isPending}
        classNames={["self-center"]}

    />
)

export { MockInterviewAnswerAction }

import React from "react"
import { type SkeletonProps } from "@/components/frames/_slot"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { ArrowRightIcon, CheckCircleIcon, WarningCircleIcon, XCircleIcon } from "@phosphor-icons/react"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { Button } from "@/components/atoms/buttons/Button"
import { SurfaceCard, SurfaceCardCrossList, type SurfaceCardCrossListItem } from "@/components/composites/cards/SurfaceCard"
import { Callout, type CalloutIcon } from "@/components/composites/feedback/Callout"
import { MarkdownContent } from "@/components/composites/viewers/MarkdownContent"
import { StackH, StackV } from "@/components/frames/Stack"
import { ScoreRow } from "./ScoreRow"

/**
 * `MockInterviewScorecard` — read-only render of one graded mock-interview run:
 * a verdict banner (`Callout`), hand-laid `ProgressMeter` rows for the score and
 * attribute breakdowns, and strengths/gaps via `SurfaceCard.CrossList`. Every
 * optional section — byline, attribute breakdown, strengths, gaps, follow-up,
 * weak-area tag, retry — is a state of one shape. Per-question model-answer review
 * is out of scope (no primitive for it yet).
 */

/** Pass / borderline / fail — reuses the interview verdict vocabulary verbatim from the BE contract. */
export type MockInterviewVerdict = "pass" | "borderline" | "fail"

/** One row of the score breakdown — a phase (design mode) or a question ordinal (Q&A mode), already display-labeled by the caller. */
export interface MockInterviewScoreRow {
    /** Stable React key. */
    key: string
    /** Display label — a resolved phase name or a question ordinal ("Question 1"), already localized/resolved by the caller. */
    label: string
    /** Points earned for this phase/question. */
    score: number
    /** Points available for this phase/question. */
    max: number
}

/** One row of the attribute breakdown (communication, structured thinking …), 0–100. */
export interface MockInterviewAttributeScoreRow {
    /** Stable React key. */
    key: string
    /** Display label, already localized/resolved by the caller. */
    label: string
    /** 0–100. */
    score: number
}

/** Props for {@link MockInterviewScorecard}. */
export interface MockInterviewScorecardProps {
    /** Pass / borderline / fail — drives the verdict callout's tone, icon and wording. */
    verdict: MockInterviewVerdict
    /** Overall score, 0–100. */
    overallScore: number
    /** Per-phase or per-question score breakdown, in display order. Section self-hides when empty (and `isSkeleton` is off). */
    phaseOrQuestionScores: Array<MockInterviewScoreRow>
    /** Per-attribute score breakdown, in display order. Section self-hides when empty. */
    attributeScores: Array<MockInterviewAttributeScoreRow>
    /** Concrete things done right, as markdown. Section self-hides when empty. */
    strengths: Array<string>
    /** Concrete gaps framed as "what to add", as markdown. Section self-hides when empty. */
    gaps: Array<string>
    /** A follow-up an interviewer would ask next, as markdown. Omit -> the section does not render. */
    followUpQuestion?: string | null
    /** The weakest area, already resolved by the caller (which phase/attribute counts as "weak enough to push" is a screen-level call, not this block's). Omit -> the primary CTA reads generically. */
    weakAreaLabel?: string
    /** Fired when the learner takes the primary CTA — go study the weak area. */
    onStudyWeakArea: () => void
    /** Fired when the learner picks the capstone hand-off CTA. */
    onCapstone: () => void
    /** Fired when the learner wants to run the interview again. Omit -> the retry action does not render (e.g. a read-only history detail). */
    onRetry?: () => void
    /** The system/prompt this run interviewed on, shown as a header line when known. */
    promptTitle?: string
    /** When this attempt was graded, already formatted/localized by the caller (e.g. "Jul 28, 2026 · 14:32"). Omit for a live, just-finished session. */
    createdAt?: string
    /** `true` -> every part this block renders itself mirrors as shimmer. */
    isSkeleton?: boolean
}

/** Verdict -> callout tone. */
const VERDICT_STATUS: Record<MockInterviewVerdict, "success" | "warning" | "danger"> = {
    pass: "success",
    borderline: "warning",
    fail: "danger",
}

/** Verdict -> callout indicator icon. */
const VERDICT_ICON: Record<MockInterviewVerdict, CalloutIcon> = {
    pass: CheckCircleIcon,
    borderline: WarningCircleIcon,
    fail: XCircleIcon,
}

/** Verdict -> the block's own wording (§14d.1 — a caller passes the enum, never a formatted string). */
const VERDICT_LABEL: Record<MockInterviewVerdict, string> = {
    pass: "Pass",
    borderline: "Borderline",
    fail: "Fail",
}

/** Placeholder row count while `isSkeleton` and the real breakdown length isn't known yet. */
const SKELETON_SCORE_ROWS = 3
const SKELETON_ATTRIBUTE_ROWS = 3

/**
 * The graded-run scorecard. See the file header for the full contract, the
 * scope cut (no per-question review this pass), and why every optional
 * section stays a STATE of this one leaf.
 *
 * @param props - {@link MockInterviewScorecardProps}
 */
const MockInterviewScorecard = ({
    verdict,
    overallScore,
    phaseOrQuestionScores,
    attributeScores,
    strengths,
    gaps,
    followUpQuestion,
    weakAreaLabel,
    onStudyWeakArea,
    onCapstone,
    onRetry,
    promptTitle,
    createdAt,
    isSkeleton = false,
}: MockInterviewScorecardProps) => {
    const hasByline = isSkeleton || promptTitle != null || createdAt != null
    const hasScoreRows = isSkeleton || phaseOrQuestionScores.length > 0
    const hasAttributeRows = isSkeleton || attributeScores.length > 0
    const hasStrengths = isSkeleton || strengths.length > 0
    const hasGaps = isSkeleton || gaps.length > 0
    const hasFollowUp = isSkeleton || Boolean(followUpQuestion)

    const strengthItems: Array<SurfaceCardCrossListItem> = strengths.map((strength, index) => ({
        key: `strength-${index}`,
        mark: "check",
        tone: "success",
        text: strength,
    }))

    const gapItems: Array<SurfaceCardCrossListItem> = gaps.map((gap, index) => ({
        key: `gap-${index}`,
        mark: "cross",
        tone: "danger",
        text: gap,
    }))

    const primaryCtaLabel = weakAreaLabel ? `Review: ${weakAreaLabel}` : "Review your weak areas"

    const bylineRow = hasByline ? (
        <StackH
            gap={4}
            justify="between"
            at="sm"
            principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            isSkeleton={isSkeleton}
            items={[
                () => (isSkeleton ? (
                    <Typography size="sm" weight="medium" isSkeleton />
                ) : promptTitle != null ? (
                    <Typography size="sm" weight="medium" text={promptTitle} />
                ) : null),
                () => (isSkeleton ? (
                    <Typography size="xs" color="muted" isSkeleton classNames={["w-1/3"]} />
                ) : createdAt != null ? (
                    <Typography size="xs" color="muted" text={createdAt} />
                ) : null),
            ]}
        />
    ) : null

    const scoreBreakdownBody = (
        <>
            {(isSkeleton
                ? Array.from({ length: SKELETON_SCORE_ROWS }, (_, index) => ({
                    key: `score-skeleton-${index}`,
                    label: "",
                    score: 0,
                    max: 100,
                }))
                : phaseOrQuestionScores
            ).map((row) => (
                <ScoreRow
                    key={row.key}
                    label={row.label}
                    score={row.score}
                    max={row.max}
                    isSkeleton={isSkeleton}
                />
            ))}
        </>
    )

    const attributeBreakdownBody = (
        <>
            {(isSkeleton
                ? Array.from({ length: SKELETON_ATTRIBUTE_ROWS }, (_, index) => ({
                    key: `attribute-skeleton-${index}`,
                    label: "",
                    score: 0,
                    max: 100,
                }))
                : attributeScores.map((row) => ({ ...row, max: 100 }))
            ).map((row) => (
                <ScoreRow
                    key={row.key}
                    label={row.label}
                    score={row.score}
                    max={row.max}
                    isSkeleton={isSkeleton}
                />
            ))}
        </>
    )

    const strengthsBody = (
        <>
            <Typography size="sm" weight="medium" text="Strengths" />
            <SurfaceCardCrossList items={strengthItems} isSkeleton={isSkeleton} />
        </>
    )

    const gapsBody = (
        <>
            <Typography size="sm" weight="medium" text="Areas to improve" />
            <SurfaceCardCrossList items={gapItems} isSkeleton={isSkeleton} />
        </>
    )

    const weakAreaRow = weakAreaLabel != null && !isSkeleton ? (
        <StackH
            gap={2}
            align="center"
            principle="icon-text"
            explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => <Typography size="xs" color="muted" text="Weakest:" isSkeleton={isSkeleton} />,
                ({ isSkeleton }: SkeletonProps) => <Chip tone="warning" text={weakAreaLabel} isSkeleton={isSkeleton} />,
            ]}
        />
    ) : null

    const ctaButtonRow = (
        <StackH
            gap={4}
            at="sm"
            principle="flex-action"
            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <Button
                        isSkeleton={isSkeleton}
                        variant="primary"
                        size="lg"
                        label={primaryCtaLabel}
                        suffixIcon={ArrowRightIcon}
                        iconSlide
                        onPress={onStudyWeakArea}

                    />
                ),
                () => (
                    <Button
                        isSkeleton={isSkeleton}
                        variant="secondary"
                        size="lg"
                        label="Work on personal project"
                        onPress={onCapstone}

                    />
                ),
                ...(onRetry != null || isSkeleton ? [() => (
                    <Button
                        isSkeleton={isSkeleton}
                        variant="ghost"
                        size="lg"
                        label="Retry interview"
                        onPress={onRetry}

                    />
                )] : []),
            ]}
        />
    )

    const ctaSection = (
        <>
            {weakAreaRow}
            {ctaButtonRow}
        </>
    )

    const scorecardBody = (
        <>
            {bylineRow}

            {/* Verdict banner. `Callout` has no `isSkeleton` of its own (a message
 frame, not a data-bearing one) — a bare bar stands in, in the same slot. */}
            {isSkeleton ? (
                <Skeleton className="h-20 w-full rounded-2xl" />
            ) : (
                <Callout
                    status={VERDICT_STATUS[verdict]}
                    icon={VERDICT_ICON[verdict]}
                    title={`${overallScore}/100 · ${VERDICT_LABEL[verdict]}`}

                />
            )}

            {hasScoreRows ? (
                <SurfaceCard
                    label="Score by section"


                    body={() => <StackV gap={4} isSkeleton={isSkeleton} items={[() => scoreBreakdownBody]} />}
                />
            ) : null}

            {hasAttributeRows ? (
                <SurfaceCard
                    label="Score by criterion"


                    body={() => <StackV gap={4} isSkeleton={isSkeleton} items={[() => attributeBreakdownBody]} />}
                />
            ) : null}

            {hasStrengths ? (
                <StackV gap={3} isSkeleton={isSkeleton} items={[() => strengthsBody]} />
            ) : null}

            {hasGaps ? (
                <StackV gap={3} isSkeleton={isSkeleton} items={[() => gapsBody]} />
            ) : null}

            {/* no icon here — §5a.2: a chat-bubble needs an ASSOCIATION step to read as
 "a question" (not a universal symbol like [ok]/(locked)), and the card's own
 label="Follow-up question" already carries the fact. */}
            {hasFollowUp ? (
                <SurfaceCard
                    label="Follow-up question"


                    body={() => (
                        <MarkdownContent
                            source={followUpQuestion ?? ""}
                            measure="compact"
                            flow="embedded"
                            emphasis="italic"
                            isSkeleton={isSkeleton}
                        />
                    )}
                />
            ) : null}

            <StackV gap={3} isSkeleton={isSkeleton} items={[() => ctaSection]} />
        </>
    )

    return (
        <div>
            <StackV gap={6} isSkeleton={isSkeleton} items={[() => scorecardBody]} />
        </div>
    )
}

export { MockInterviewScorecard }

import { InputText } from "@/components/atoms/forms"
import React from "react"
import { type SkeletonProps } from "@/components/frames/_slot"
import { FlowArrowIcon, PlayIcon } from "@phosphor-icons/react"
import { Avatar } from "@/components/atoms/display/Avatar"
import { Typography } from "@/components/atoms/text/Typography"

import { Button } from "@/components/atoms/buttons/Button"
import { ButtonRadioGroup } from "@/components/composites/buttons/ButtonRadioGroup"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { Callout } from "@/components/composites/feedback/Callout"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * `MockInterviewSetup` — the green-room card: who is interviewing, what to call
 * this run, how hard it should be, and the button(s) that start it. Sibling of
 * `QuizSetup` (same resumable-banner-leads-the-form shape). Two start buttons are
 * two different interviews — Q&A always exists; Design shows only when the caller
 * sets `isDesignAvailable`. The persona row is built from `Avatar` + `Typography`
 * (the second line is a role, not a handle). The "Customize" deep-config body is a
 * separate, deferred leaf.
 */

/** How hard the interviewer's questions run. The block owns the label (§14d.1). */
export type MockInterviewTier = "junior" | "mid" | "senior"

const TIER_LABEL: Record<MockInterviewTier, string> = {
    junior: "Junior",
    mid: "Mid-level",
    senior: "Senior",
}

/** Which start action is in flight, so the busy affordance lands on the right button. */
export type MockInterviewStartMode = "qna" | "design"

/** The interviewer greeting the candidate. */
export interface MockInterviewPersona {
    /** Interviewer's display name. */
    name: string
    /** Role line under the name, e.g. "Senior Backend @ a digital bank" — NOT a handle. */
    role: string
    /** Uploaded avatar URL. Absent → `Avatar`'s own generated/initials fallback. */
    avatarSrc?: string
}

/** A run the candidate left unfinished. */
export interface MockInterviewResumable {
    /** What the run was called when it was started. */
    name: string
    /** Where the run left off, already worded by the caller — e.g. "Left off at question 3". */
    progressLabel: string
    /** Fired when the candidate picks the run back up. */
    onResume: () => void
}

/** Props for {@link MockInterviewSetup}. */
export interface MockInterviewSetupProps {
    /** Section label, localized by the caller — e.g. "Prepare for the interview". */
    label: string
    /** The interviewer greeting the candidate. */
    persona: MockInterviewPersona
    /** Current run name. */
    sessionName: string
    /** Fired as the candidate types a name. */
    onSessionNameChange: (value: string) => void
    /** Chosen difficulty. */
    tier: MockInterviewTier
    /** Fired when the candidate picks a tier. */
    onTierChange: (tier: MockInterviewTier) => void
    /**
     * `true` → this is a System-Design course, so the Design-mode start button
     * renders beside the Q&A one. The CALLER decides this (course kind lives on
     * the screen); the block never infers it.
     */
    isDesignAvailable: boolean
    /** Fired when the candidate starts the Q&A round. Always available. */
    onStartQna: () => void
    /** Fired when the candidate starts the Design round. Required once `isDesignAvailable` is set. */
    onStartDesign?: () => void
    /** A run left unfinished. Present → the resume banner leads the card. */
    resumable?: MockInterviewResumable
    /** Which start action is currently in flight — drives which button shows its own spinner. */
    startingMode?: MockInterviewStartMode
    /** `true` → a start is in flight; both start buttons lock while one of them runs. */
    isPending?: boolean
    /** Set → the last start attempt failed. Reported beside the action row that failed. */
    errorMessage?: string
    /** `true` → the card draws its own mirror while the setup data loads. */
    isSkeleton?: boolean
}

/**
 * The interview green-room card. See the file header for the full contract.
 *
 * @param props - {@link MockInterviewSetupProps}
 */
const MockInterviewSetup = ({
    label,
    persona,
    sessionName,
    onSessionNameChange,
    tier,
    onTierChange,
    isDesignAvailable,
    onStartQna,
    onStartDesign,
    resumable,
    startingMode,
    isPending = false,
    errorMessage,
    isSkeleton = false,
}: MockInterviewSetupProps) => {
    const showDesignStart = isDesignAvailable && onStartDesign != null

    // A candidate who left mid-interview almost always means to come back.
    // Making them scroll past a start button to find their own session is
    // how a run gets abandoned twice — same reasoning as `QuizSetup`.
    const resumeBanner = resumable != null ? (
        <Callout
            title={resumable.name}
            description={resumable.progressLabel}
            actionLabel="Continue"
            onAction={resumable.onResume}

        />
    ) : null

    const personaDetails = (
        <>
            <Typography
                size="sm"
                weight="medium"
                isSkeleton={isSkeleton}
                text={persona.name}

            />
            <Typography
                size="xs"
                color="muted"
                isSkeleton={isSkeleton}
                text={persona.role}

            />
        </>
    )

    // Interviewer identity — built from Avatar + Typography directly (not
    // `UserCell`): the second line is a ROLE, not an `@handle`.
    const identityRow = (
        <StackH
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <div>
                        <Avatar
                            name={persona.name}
                            src={persona.avatarSrc}
                            seed={persona.name}
                            size="md"
                            isSkeleton={isSkeleton}

                        />
                    </div>
                ),
                ({ isSkeleton }: SkeletonProps) => <StackV gap={1} isSkeleton={isSkeleton} items={[() => personaDetails]} />,
            ]}
        />
    )

    const sessionNameField = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => <Typography isSkeleton={isSkeleton} size="sm" weight="medium" text="Session name" />,
                () => (
                    <InputText
                        value={sessionName}
                        onValueChange={onSessionNameChange}
                        placeholder="e.g. Round 1 - Backend"
                        ariaLabel="Session name"
                        isSkeleton={isSkeleton}

                    />
                ),
            ]}
        />
    )

    const tierField = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => <Typography isSkeleton={isSkeleton} size="sm" weight="medium" text="Level" />,
                () => (
                    <ButtonRadioGroup
                        ariaLabel="Interview level"
                        value={tier}
                        onChange={onTierChange}

                        items={(Object.keys(TIER_LABEL) as Array<MockInterviewTier>).map((key) => ({
                            value: key,
                            content: TIER_LABEL[key],
                        }))}
                    />
                ),
            ]}
        />
    )

    const actionsRow = (
        <StackH
            gap={3}
            principle="flex-action"
            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
            justify="end"
            isSkeleton={isSkeleton}
            items={[
                ...(showDesignStart ? [({ isSkeleton }: SkeletonProps) => (
                    <Button
                        isSkeleton={isSkeleton}
                        label="Start Design"
                        variant="secondary"
                        prefixIcon={FlowArrowIcon}
                        onPress={onStartDesign}
                        isPending={isPending && startingMode === "design"}
                        isDisabled={isPending && startingMode !== "design"}

                    />
                )] : []),
                ({ isSkeleton }: SkeletonProps) => (
                    <Button
                        isSkeleton={isSkeleton}
                        label="Start Q&A"
                        variant="primary"
                        prefixIcon={PlayIcon}
                        onPress={onStartQna}
                        isPending={isPending && startingMode === "qna"}
                        isDisabled={isPending && startingMode !== "qna"}

                    />
                ),
            ]}
        />
    )

    // The error sits WITH the action row that failed. At the top of the
    // card it would read as a problem with the whole form.
    const footer = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                ...(errorMessage != null ? [() => (
                    <Callout
                        status="danger"
                        title={errorMessage}

                    />
                )] : []),
                () => actionsRow,
            ]}
        />
    )

    const setupBody = (
        <>
            {resumeBanner}
            {identityRow}
            {sessionNameField}
            {tierField}
            {footer}
        </>
    )

    return (
        <div>
            <SurfaceCard
                label={label}
                isSkeleton={isSkeleton}

                body={({ isSkeleton }: SkeletonProps) => <StackV gap={6} isSkeleton={isSkeleton} items={[() => setupBody]} />}
            />
        </div>
    )
}

export { MockInterviewSetup }

import React from "react"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { PuzzlePieceIcon } from "@phosphor-icons/react"
import { SurfaceCardList } from "@/components/composites/cards/SurfaceCard"
import { VariantChipDifficulty, type Difficulty } from "@/components/blocks/learn/VariantChip"

/**
 * `ModuleChallengeList` — every challenge across this module's lessons, flattened
 * into one solve-me list. Distinct from a lesson list: a challenge row means "go
 * solve", shows the same `PuzzlePieceIcon` recoloured by solved state (no
 * in-progress state), and a press opens the owning lesson's Challenges tab (there
 * is no standalone challenge route). Solved/unsolved and all four difficulty steps
 * are states of one `SurfaceCardList` → rows tree.
 */

/** One challenge row — plain DATA, the block builds the row shape itself. */
export interface ModuleChallengeItem {
    /** Stable React key — the challenge's own id. */
    id: string
    /** Challenge title. */
    title: string
    /** Difficulty tier — the block builds `VariantChipDifficulty` itself. */
    difficulty: Difficulty
    /** Whether this challenge has been solved — decides the icon color and the subtitle. */
    completed: boolean
    /** The LESSON this challenge belongs to — where a press actually navigates. */
    lessonId: string
}

/** Props for {@link ModuleChallengeList}. */
export interface ModuleChallengeListProps {
    /** The challenges, flattened across every lesson in the module. */
    challenges: Array<ModuleChallengeItem>
    /**
     * Fired with the OWNING LESSON's id (not the challenge id) — a challenge is
     * solved inside its lesson's Challenges tab, there is no standalone
     * challenge route to send the learner to.
     */
    onSelectChallenge: (lessonId: string) => void
    /**
     * `true` → mirror shimmer instead of waiting on `challenges`. The flag flows
     * straight into `SurfaceCardList` (keeps the row box/divider, only the text
     * shimmers) and into `VariantChipDifficulty`. The leading icon color is
     * chosen directly by this block (no atom in between, see the file header),
     * so — same as `KeepGoingPath` — it hand-rolls a single shimmer dot in its
     * place rather than branching off a second row shape.
     *
     * Empty while loading (`challenges.length === 0`) guesses **3** rows,
     * matching this pass's convention for repeating lists.
     */
    isSkeleton?: boolean
}

/**
 * Icon color by solved state — the block owns this table (mirrors
 * `KeepGoingPath`'s `CONTENT_LEADING`, one entry instead of three because a
 * challenge has no "in progress" state, only solved / not yet).
 */
const CHALLENGE_LEADING_CLASS: Record<"completed" | "todo", string> = {
    completed: "size-5 text-success-soft-foreground",
    todo: "size-5 text-foreground",
}

/** Placeholder DATA for the 3 guessed rows when `challenges` is empty while loading (§12c). */
const SKELETON_CHALLENGES: Array<ModuleChallengeItem> = Array.from({ length: 3 }, (_unused, index) => ({
    id: `skeleton-${index}`,
    title: "",
    difficulty: "beginner",
    completed: false,
    lessonId: "",
}))

/**
 * Every challenge across this module's lessons, flattened into one solve-me
 * list. See the file header for the full contract and why this is not merged
 * with a lesson list.
 *
 * @param props - {@link ModuleChallengeListProps}
 */
const ModuleChallengeList = ({
    challenges,
    onSelectChallenge,
    isSkeleton = false,
}: ModuleChallengeListProps) => {
    // Empty while loading (no real challenges yet) → guess 3 rows, keeping the
    // right shape for when real data arrives (§8). Once real `challenges` exist,
    // keep the EXACT row count already there.
    const rows = isSkeleton && challenges.length === 0 ? SKELETON_CHALLENGES : challenges

    return (
        <SurfaceCardList identity={{ tier: "block", component: "ModuleChallengeList" }}

            isSkeleton={isSkeleton}
            items={rows.map((challenge) => ({
                key: challenge.id,
                leading: () => (isSkeleton ? (
                    // The color is chosen DIRECTLY by this block (no atom in between) —
                    // hand-roll a single shimmer dot in place of the puzzle icon.
                    <Skeleton className="size-5 shrink-0 rounded-full" />
                ) : (
                    <PuzzlePieceIcon
                        aria-hidden
                        focusable="false"
                        className={CHALLENGE_LEADING_CLASS[challenge.completed ? "completed" : "todo"]}
                    />
                )),
                title: challenge.title,
                // Only a SOLVED challenge earns the subtitle — an unsolved row says
                // nothing extra, the difficulty chip is already the row's other fact.
                subtitle: challenge.completed ? "Completed" : undefined,
                onPress: () => onSelectChallenge(challenge.lessonId),
                // Meta holds EXACTLY ONE thing: difficulty. The shape is owned by
                // DESIGN — this block doesn't reshape the chip (§14d.1). The flag
                // flows straight down into the `VariantChipDifficulty` atom.
                meta: () => (
                    <VariantChipDifficulty
                        difficulty={challenge.difficulty}
                        isSkeleton={isSkeleton}

                    />
                ),
            }))}
        />
    )
}

export { ModuleChallengeList }

import React from "react"
import { ArrowRightIcon } from "@phosphor-icons/react"
import { StackH, StackV } from "@/components/frames/Stack"
import { Typography } from "@/components/atoms/text/Typography"
import { Button } from "@/components/atoms/buttons/Button"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"

/**
 * `ModuleContinueBand` — the flat "resume + progress" cluster that opens both
 * course-home and module-home. A flat cluster, not a card (distinct from
 * `ContinueLearning` / `ContinueCardHero`). `resumeLessonTitle` presence drops two
 * nodes together (the title and the resume button), so "resume available" vs "all
 * done" are separate shapes; `isSkeleton` is its own too. Which numbers show in the
 * meter/sentence are data states inside the resume-available shape.
 */

/** Resume label — a block-owned wording constant (§14d.1), not a caller prop. */
const RESUME_LABEL = "Continue learning"
/** Eyebrow shown while a lesson still waits to be resumed. */
const EYEBROW_CONTINUE = "Keep learning"
/** Eyebrow shown once nothing is left to resume — the whole title/button row drops out with it. */
const EYEBROW_ALL_DONE = "You have finished this content"

/** Props for {@link ModuleContinueBand}. */
export interface ModuleContinueBandProps {
    /**
     * Title of the next unread lesson. `undefined` means every lesson is
     * already read — the block switches to its "all done" eyebrow and drops
     * the title line and the resume button together.
     */
    resumeLessonTitle?: string
    /** Lessons already read / total lessons in scope (module or course). */
    lessonsRead: number
    lessonsTotal: number
    /** Challenges already completed / total challenges in scope. */
    challengesDone: number
    challengesTotal: number
    /**
     * Press "Continue learning". Optional: the button itself only renders when
     * {@link ModuleContinueBandProps.resumeLessonTitle} is set (content-driven
     * omission), never withheld because this handler is missing.
     */
    onResume?: () => void
    /** `true` → every composed atom swaps to its own shimmer. */
    isSkeleton?: boolean
    /** Anatomy tag for THIS block itself — lets the screen badge it as ONE node (§11a.1). */
}

/**
 * Flat "resume + progress" band: eyebrow + resume title + resume button on one
 * row, a progress meter, then the stat sentence the block writes itself.
 *
 * @param props - {@link ModuleContinueBandProps}
 */
const ModuleContinueBand = ({
    resumeLessonTitle,
    lessonsRead,
    lessonsTotal,
    challengesDone,
    challengesTotal,
    onResume,
    isSkeleton = false,
}: ModuleContinueBandProps) => {
    // Loading state doesn't know which branch it will land in yet, so it always
    // shows the fuller "still has a lesson to resume" shape (see file header).
    const showResumeRow = isSkeleton || resumeLessonTitle !== undefined

    const eyebrowAndTitle = (
        <StackV
            gap={1}
            classNames={["min-w-0"]}
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <Typography
                        size="xs"
                        color="muted"
                        isSkeleton={isSkeleton}
                        text={showResumeRow ? EYEBROW_CONTINUE : EYEBROW_ALL_DONE}

                    />
                ),
                ...(showResumeRow ? [() => (
                    <Typography
                        size="base"
                        weight="semibold"
                        truncate
                        isSkeleton={isSkeleton}
                        text={resumeLessonTitle}

                    />
                )] : []),
            ]}
        />
    )

    const headerRow = (
        <StackH
            gap={4}
            principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            justify="between"
            align="start"
            isSkeleton={isSkeleton}
            items={[
                () => eyebrowAndTitle,
                ...(showResumeRow ? [() => (
                    <Button
                        isSkeleton={isSkeleton}
                        variant="primary"
                        size="lg"
                        label={RESUME_LABEL}
                        suffixIcon={ArrowRightIcon}
                        onPress={onResume}
                        classNames={["shrink-0"]}

                    />
                )] : []),
            ]}
        />
    )

    const progress = (
        <ProgressMeter
            value={lessonsRead}
            max={lessonsTotal}
            label="Completed"
            showValue
            isSkeleton={isSkeleton}
        />
    )

    const statLine = (
        <Typography
            size="xs"
            color="muted"
            isSkeleton={isSkeleton}
            text={`Read ${lessonsRead}/${lessonsTotal} lessons · Completed ${challengesDone}/${challengesTotal} challenges`}

        />
    )

    return (
        <StackV identity={{ tier: "block", component: "ModuleContinueBand" }}
            gap={4}
            isSkeleton={isSkeleton}
            items={[
                () => headerRow,
                () => progress,
                () => statLine,
            ]}
        />
    )
}

export { ModuleContinueBand }

import React from "react"
import { ClockIcon, PuzzlePieceIcon, StackIcon } from "@phosphor-icons/react"
import { CourseContentTier } from "@/modules/types/enums/course-content-tier"
import { Chip } from "@/components/atoms/chips/Chip"
import { Breadcrumbs } from "@/components/atoms/navigation/Breadcrumbs"
import { EnumChip, type EnumChipEntry } from "@/components/composites/chips/EnumChip"
import { HighlightChip } from "@/components/composites/chips/HighlightChip"
import { PageHeader } from "@/components/composites/layout/Page"
import { StackH } from "@/components/frames/Stack"

/**
 * `ModuleHeader` — the module-identity cluster at the top of a module's page,
 * answering "what is this module, and how big is it". Sibling of `ContentHeader`
 * and `CourseBrief`: places identity into `PageHeader`, but carries a module's tier
 * plus three `HighlightChip` counts (lessons, minutes, challenges) — the counts are
 * the headline figures, so they keep their chip shape while `tier` classifies the
 * module. Which chips draw stays states of one shape; losing the whole meta row
 * drops a `PageHeader` region and earns its own shape.
 */

/** Tier → chip presentation. The block owns this table (§14d.1: no caller-supplied color/label). */
const TIER_MAP: Record<CourseContentTier, EnumChipEntry> = {
    [CourseContentTier.Foundation]: { color: "success", label: "Foundation" },
    [CourseContentTier.Intermediate]: { color: "warning", label: "Intermediate" },
    [CourseContentTier.Advanced]: { color: "danger", label: "Advanced" },
}

/** One breadcrumb link — plain data, the block builds the atom from it. */
export interface ModuleHeaderCrumb {
    /** Stable React key. */
    key: string
    /** Display label. */
    label: string
    /** Has a handler → the crumb is pressable; the current page leaves it out. */
    onPress?: () => void
}

/** Props for {@link ModuleHeader}. */
export interface ModuleHeaderProps {
    /** Breadcrumb trail as DATA — the block builds `Breadcrumbs` itself. A module is always reached through its course, so the trail is always required (no "no breadcrumb" case, same call `ContentHeader` makes). */
    breadcrumbItems: Array<ModuleHeaderCrumb>
    /** Module title. */
    title: string
    /** One-sentence summary of the module. */
    description?: string
    /** Learning tier — the ONE classifying fact, drives the `EnumChip` tone + label. Omit → no tier chip. */
    tier?: CourseContentTier
    /** How many lessons this module has — the block adds "lessons" itself. Omit or `0` → no chip. */
    lessonCount?: number
    /** Total reading/study minutes across the module — the block adds "minutes of study" itself. Omit or `0` → no chip. */
    minutesTotal?: number
    /** How many challenges hang off this module — the block adds "challenges" itself. Omit or `0` → no chip. */
    challengeCount?: number
    /**
     * `true` → every composed atom switches to its own shimmer. The flag FLOWS
     * DOWN into the real atoms rather than building a parallel skeleton tree
     * (§12c).
     */
    isSkeleton?: boolean
}

/**
 * The module identity cluster at the top of a module's own page. See the file
 * header for the full contract and why this is a sibling of `ContentHeader`/
 * `CourseBrief` rather than an edit of either.
 *
 * @param props - {@link ModuleHeaderProps}
 */
const ModuleHeader = ({
    breadcrumbItems,
    title,
    description,
    tier,
    lessonCount,
    minutesTotal,
    challengeCount,
    isSkeleton = false,
}: ModuleHeaderProps) => {
    const hasLessons = (lessonCount ?? 0) > 0
    const hasMinutes = (minutesTotal ?? 0) > 0
    const hasChallenges = (challengeCount ?? 0) > 0
    // The meta row only exists once it has something to show — otherwise `PageHeader`
    // gets `undefined` and drops the whole slot instead of an empty row with nothing in it.
    const hasMeta = isSkeleton || tier != null || hasLessons || hasMinutes || hasChallenges

    const metaRow = hasMeta ? (
        <StackH
            gap={3}
            align="center"
            at="sm"
            principle="chip-row"
            explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
            isSkeleton={isSkeleton}

            items={[
                () => (isSkeleton ? (
                    <EnumChip
                        value={CourseContentTier.Foundation}
                        map={TIER_MAP}
                        isSkeleton

                    />
                ) : tier != null ? (
                    <EnumChip value={tier} map={TIER_MAP} />
                ) : null),
                () => (isSkeleton ? (
                    <span>
                        <Chip isSkeleton icon={StackIcon} />
                    </span>
                ) : hasLessons ? (
                    <span>
                        <HighlightChip
                            icon={StackIcon}
                            value={lessonCount}
                            label="lessons"
                        />
                    </span>
                ) : null),
                () => (isSkeleton ? (
                    <span>
                        <Chip isSkeleton icon={ClockIcon} />
                    </span>
                ) : hasMinutes ? (
                    <span>
                        <HighlightChip
                            icon={ClockIcon}
                            value={minutesTotal}
                            label="minutes"
                        />
                    </span>
                ) : null),
                () => (isSkeleton ? (
                    <span>
                        <Chip isSkeleton icon={PuzzlePieceIcon} />
                    </span>
                ) : hasChallenges ? (
                    <span>
                        <HighlightChip
                            icon={PuzzlePieceIcon}
                            value={challengeCount}
                            label="challenges"
                        />
                    </span>
                ) : null),
            ]}
        />
    ) : undefined

    return (
        // Identity hold: PageHeader does not accept CallerIdentity (ledger PageHeader gap).
        <PageHeader
            isSkeleton={isSkeleton}
            breadcrumb={() => (
                // Hold: no hug-width frame for breadcrumb measure (`w-fit` parent placement).
                <div className="w-fit">
                    <Breadcrumbs
                        collapseOnMobile
                        collapseFrom={4}
                        items={breadcrumbItems}
                        isSkeleton={isSkeleton}
                    />
                </div>
            )}
            title={title}
            description={description}
            meta={() => metaRow}
        />
    )
}

export { ModuleHeader }

"use client"

import React, { useCallback } from "react"
import { Label } from "@heroui/react"
import { useTranslations } from "next-intl"
import { ActionToolbar } from "@/components/blocks/learn/lesson/ContentBody/ActionToolbar"
import { useAppSelector } from "@/redux/hooks"
import { useShareOverlayState } from "@/hooks/zustand/overlay/hooks"
import { useMutateToggleFavoriteSwr } from "@/hooks/swr/api/graphql/mutations/useMutateToggleFavoriteSwr"
import { useQueryContentStatusSwr } from "@/hooks/swr/api/graphql/queries/useQueryContentStatusSwr"
import { useGraphQLWithToast } from "@/modules/toast/hooks"

/** Props for {@link ContentActions}. */
export type ContentActionsProps = Record<string, never>
/**
 * Right-rail content actions: bookmark/save, share and fullscreen for the content
 * currently open (moved out of the inline interaction bar). Self-contained — owns
 * the favorite mutation + the share / fullscreen overlay state and composes the
 * presentational {@link ActionToolbar}. Hidden until a content is open.
 *
 * @param props - {@link ContentActionsProps}
 */
export const ContentActions = () => {
    const t = useTranslations()
    const runGraphQL = useGraphQLWithToast()
    const contentId = useAppSelector((state) => state.content.id)
    const isPremium = useAppSelector((state) => state.content.entity?.isPremium)
    const statusSwr = useQueryContentStatusSwr()
    const favoriteSwr = useMutateToggleFavoriteSwr()
    const shareOverlay = useShareOverlayState()

    /** Toggle the favorite/bookmark flag, then re-fetch the content status. */
    const onToggleFavorite = useCallback(async () => {
        if (!contentId) {
            return
        }
        await runGraphQL(
            async () => {
                const envelope = await favoriteSwr.trigger({
                    contentId,
                    isFavorite: !statusSwr.data?.isFavorite,
                })
                if (!envelope?.success) {
                    throw new Error("Toggle favorite failed")
                }
                void statusSwr.mutate()
                return envelope
            },
            { showSuccessToast: true },
        )
    }, [contentId, favoriteSwr, statusSwr, runGraphQL])

    /** Open the share overlay. */
    const onShare = useCallback(() => shareOverlay.setOpen(true), [shareOverlay])

    if (!contentId) {
        return null
    }

    return (
        <div className={"flex flex-col gap-3"}>
            <Label>{t("contentActions.title")}</Label>
            <ActionToolbar
                isFavorite={Boolean(statusSwr.data?.isFavorite)}
                isShareVisible={!isPremium}
                isFavoritePending={favoriteSwr.isMutating}
                onToggleFavorite={onToggleFavorite}
                onShare={onShare}
            />
        </div>
    )
}

"use client"

import React from "react"
import useSWR from "swr"
import { useTranslations } from "next-intl"
import { usePathname, useRouter } from "next/navigation"
import { ArrowRightIcon } from "@phosphor-icons/react"
import { GraphQLHeadersKey } from "@/modules/api/graphql/types"
import { queryChallenges } from "@/modules/api/graphql/queries/query-challenges"
import { DifficultyChip } from "@/components/blocks/chips/DifficultyChip"
import { LabeledList } from "@/components/blocks/lists/LabeledList"
import { Button } from "@/components/atoms/buttons/Button"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH } from "@/components/frames/Stack"
import { toDifficulty } from "@/modules/utils/difficulty"
import { useAppDispatch, useAppSelector } from "@/redux/hooks"
import { ContentTab, setContentTab } from "@/redux/slices/tabs"
import { useQueryContentSwr } from "@/hooks/swr/api/graphql/queries/useQueryContentSwr"
import { usePremiumGateOverlayState } from "@/hooks/zustand/overlay/hooks"

/** Placeholder challenge rows shown while the lesson's challenges load. */
const SKELETON_ROWS = 3

/**
 * Right-rail "practice this lesson" panel: the challenges attached to the lesson
 * currently being read, with a primary CTA that opens the lesson's Challenges tab.
 * Closes the read → review → practice loop next to the on-this-page outline.
 *
 * Uses its OWN read-only SWR for `challenges({ contentId })` (NOT the tab-coupled
 * {@link import("@/hooks").useQueryChallengesSwr}, which gates on the active tab and
 * writes Redux). Self-hides once settled with no challenges, so it never leaves an
 * empty box.
 *
 * The label and the CTA are static i18n — known before the query returns — so only
 * the CHALLENGE ROWS rest, inside the same `LabeledList` the loaded rows use.
 */
export const LessonChallenges = () => {
    const t = useTranslations()
    const dispatch = useAppDispatch()
    const router = useRouter()
    const pathname = usePathname()
    const courseId = useAppSelector((state) => state.course.entity?.id)
    const contentId = useAppSelector((state) => state.content.id)
    const { data: content } = useQueryContentSwr()
    const { open: openPremiumGate } = usePremiumGateOverlayState()

    // challenges of THIS lesson; key null until both ids hydrate
    const { data, isLoading } = useSWR(
        courseId && contentId ? ["lesson-challenges", courseId, contentId] : null,
        async () => {
            const response = await queryChallenges({
                request: {
                    contentId: contentId as string,
                    // omit pageNumber/limit → server defaults (mirrors the proven
                    // tab hook); avoids an off-by-one page that would return empty
                    filters: { sorts: [] },
                },
                headers: { [GraphQLHeadersKey.XCourseId]: courseId as string },
            })
            return response.data?.challenges?.data?.data ?? null
        },
    )

    const challenges = data ?? []

    // open the lesson's Challenges tab in place (same content route)
    const onPractice = () => {
        if (content?.isPremium) {
            openPremiumGate()
            return
        }
        dispatch(setContentTab(ContentTab.Challenges))
        router.replace(`${pathname}?tab=${ContentTab.Challenges}`)
    }

    const isSkeleton = isLoading && !data
    if (!isSkeleton && challenges.length === 0) {
        return null
    }

    return (
        <LabeledList
            label={t("lessonRail.challenges.title")}
            action={(
                <Button
                    label={t("lessonRail.challenges.practice")}
                    size="sm"
                    variant="primary"
                    suffixIcon={ArrowRightIcon}
                    onPress={onPractice}
                    classNames={["self-start"]}
                />
            )}
        >
            {isSkeleton
                ? Array.from({ length: SKELETON_ROWS }, (_row, index) => (
                    <Typography key={index} size="sm" color="muted" isSkeleton />
                ))
                : challenges.map((challenge) => (
                    <StackH
                        key={challenge.id}
                        gap={3}
                        principle="chip-row"
                        explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                        align="center"
                        justify="between"
                        items={[
                            () => <Typography size="sm" color="muted" truncate text={challenge.title} />,
                            ...(challenge.difficulty
                                ? [() => <DifficultyChip difficulty={toDifficulty(challenge.difficulty)} />]
                                : []),
                        ]}
                    />
                ))}
        </LabeledList>
    )
}

"use client"

import React from "react"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { useQuerySearchCourseContentSwr } from "@/hooks/swr/api/graphql/queries/useQuerySearchCourseContentSwr"
import { LabeledList } from "@/components/blocks/lists/LabeledList"
import { Button } from "@/components/atoms/buttons/Button"
import { Typography } from "@/components/atoms/text/Typography"
import { useAppSelector } from "@/redux/hooks"
import { pathConfig } from "@/resources/path"

/** Placeholder deck rows shown while the RAG search is in flight. */
const SKELETON_ROWS = 3

/**
 * Right-rail "review this lesson" panel: flashcard decks RAG-related to the
 * lesson currently being read (`searchCourseContent`, filtered to
 * `kind: "flashcard"` — the `flashcard_deck_contents` M2M this used to read
 * from was dropped; deck↔lesson association is RAG-derived now, same as
 * `RelatedContentList`), with a primary CTA into the Flashcards page to start
 * a spaced-repetition session.
 *
 * Reads the active course + content title from Redux and self-hides once the
 * search settles with no related decks, so it never leaves an empty box in the
 * rail. The label and the CTA are static i18n — known before the search returns —
 * so only the DECK ROWS shimmer, inside the same `LabeledList` the loaded rows
 * use (`loading-and-skeleton.md`).
 */
export const LessonFlashcards = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const courseId = useAppSelector((state) => state.course.entity?.id)
    const courseDisplayId = useAppSelector((state) => state.course.displayId)
    const contentTitle = useAppSelector((state) => state.content.entity?.title)

    const swr = useQuerySearchCourseContentSwr(
        courseId ?? null,
        contentTitle ?? "",
        Boolean(courseId && contentTitle),
    )

    // dedupe by deck — the RAG search can surface several cards from the same deck
    const decks = Array.from(
        new Map(
            (swr.data ?? [])
                .filter((item) => item.kind === "flashcard" && item.deckId)
                .map((item) => [item.deckId as string, { id: item.deckId as string, title: item.title }]),
        ).values(),
    )

    // open the Flashcards page for this course (deck is chosen there)
    const onReview = () => {
        if (!courseDisplayId) {
            return
        }
        router.push(
            pathConfig().locale(locale).course(courseDisplayId).learn().flashcards().build(),
        )
    }

    const isSkeleton = swr.isLoading
    // settled with nothing related → the panel self-hides rather than showing an empty box
    if (!isSkeleton && decks.length === 0) {
        return null
    }

    return (
        <LabeledList
            label={t("lessonRail.flashcards.title")}
            action={(
                <Button
                    label={t("lessonRail.flashcards.review")}
                    size="sm"
                    variant="secondary"
                    onPress={onReview}
                />
            )}
        >
            {isSkeleton
                ? Array.from({ length: SKELETON_ROWS }, (_row, index) => (
                    <Typography key={index} size="sm" color="muted" isSkeleton />
                ))
                : decks.map((deck) => (
                    <Typography key={deck.id} size="sm" color="muted" truncate text={deck.title} />
                ))}
        </LabeledList>
    )
}

"use client"

import {
    useCallback,
    useEffect,
    useState,
} from "react"

/** A single entry in the "on this page" outline. */
export interface TocHeading {
    /** Anchor id of the heading element (matches the rendered `id`). */
    id: string
    /** Plain-text label shown in the outline. */
    text: string
    /** Heading depth (2 or 3) used to indent the row. */
    level: number
}

/** Result of {@link useTableOfContents}. */
export interface UseTableOfContentsResult {
    /** The ordered headings discovered in the active lesson body. */
    headings: Array<TocHeading>
    /** Id of the heading currently in view (scroll-spy), or undefined. */
    activeId?: string
    /** Smooth-scroll the article to the given heading id and mark it active. */
    onJump: (id: string) => void
}

/** Id of the lesson article container the outline scans within. */
const ARTICLE_ID = "lesson-article"

/**
 * Builds the "on this page" outline for the active lesson by scanning the rendered
 * article (`#lesson-article [data-toc]`) for heading anchors, then tracks which
 * heading is in view (scroll-spy) and exposes a smooth-scroll jump.
 *
 * DOM-driven (not data-driven) so it works for any rendered body — markdown
 * headings are tagged with `id` + `data-toc` by the shared `MarkdownContent`
 * renderer. Re-scans whenever `rescanKey` changes (lesson navigation / language
 * switch) and while the article subtree mutates (async markdown render).
 *
 * @param rescanKey - A value that changes when the active lesson changes (its id),
 *   forcing a re-scan. Pass `undefined` when no lesson is active.
 * @returns {@link UseTableOfContentsResult} headings, the active id, and a jumper.
 */
export const useTableOfContents = (rescanKey: string | undefined): UseTableOfContentsResult => {
    const [headings, setHeadings] = useState<Array<TocHeading>>([])
    const [activeId, setActiveId] = useState<string | undefined>(undefined)

    // scan the rendered article for heading anchors; re-run on lesson change +
    // while the article subtree mutates (markdown renders client-side, async).
    useEffect(() => {
        let frame = 0

        const scan = () => {
            const container = document.getElementById(ARTICLE_ID)
            if (!container) {
                setHeadings([])
                return
            }
            const nodes = Array.from(container.querySelectorAll<HTMLElement>("[data-toc]"))
            const next = nodes
                .filter((node) => node.id)
                .map((node) => ({
                    id: node.id,
                    // prefer the clean data-toc-label (set by MarkdownContent) so the hover
                    // anchor "#" / inline code in the heading never leaks into the outline.
                    text: node.dataset.tocLabel ?? node.textContent?.trim() ?? "",
                    level: Number(node.dataset.tocLevel ?? "2"),
                }))
            setHeadings(next)
        }

        // coalesce mutation bursts into a single scan per frame.
        const schedule = () => {
            if (frame) {
                return
            }
            frame = requestAnimationFrame(() => {
                frame = 0
                scan()
            })
        }

        // Observe a STABLE root (document.body) instead of polling a fixed number
        // of frames for #lesson-article. On a hard reload the article mounts only
        // after the SWR fetch + markdown render resolves, which can exceed any
        // fixed timeout — the old 60-frame poll then gave up with an empty outline
        // and never re-scanned. body always exists, so we reliably catch both the
        // article mounting and its async heading render, on hard reload AND SPA nav.
        scan()
        const observer = new MutationObserver(schedule)
        observer.observe(document.body, { childList: true, subtree: true })

        return () => {
            if (frame) {
                cancelAnimationFrame(frame)
            }
            observer.disconnect()
        }
    }, [rescanKey])

    // scroll-spy: mark the top-most heading currently in the viewport band.
    useEffect(() => {
        if (headings.length === 0) {
            setActiveId(undefined)
            return
        }
        const elements = headings
            .map((heading) => document.getElementById(heading.id))
            .filter((element): element is HTMLElement => Boolean(element))
        if (elements.length === 0) {
            return
        }
        const observer = new IntersectionObserver(
            (entries) => {
                const visible = entries
                    .filter((entry) => entry.isIntersecting)
                    .sort((a, b) => a.boundingClientRect.top - b.boundingClientRect.top)
                if (visible[0]?.target.id) {
                    setActiveId(visible[0].target.id)
                }
            },
            {
                // bias the active band just under the sticky navbar
                rootMargin: "-72px 0px -70% 0px",
                threshold: 0,
            },
        )
        elements.forEach((element) => observer.observe(element))
        return () => observer.disconnect()
    }, [headings])

    const onJump = useCallback((id: string) => {
        const element = document.getElementById(id)
        if (element) {
            element.scrollIntoView({ behavior: "smooth", block: "start" })
            setActiveId(id)
        }
    }, [])

    return {
        headings,
        activeId,
        onJump,
    }
}

"use client"

import React from "react"
import {
    Label,
    Link,
    ScrollShadow,
    cn,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import {
    useTableOfContents,
} from "./hooks/useTableOfContents"
import {
    LessonFlashcards,
} from "./LessonFlashcards"
import {
    LessonChallenges,
} from "./LessonChallenges"
import {
    ContentActions,
} from "./ContentActions"
import { useAppSelector } from "@/redux/hooks"
import { ContentTab } from "@/redux/slices/tabs"

/** Props for {@link OnThisPage}. */
export interface OnThisPageProps {
    /**
     * Render as a full-width mobile panel (the bottom-tab "On this page" view):
     * drops the hidden/sticky/width rail chrome and keeps just the body. Default
     * `false` = the desktop right rail.
     */
    mobile?: boolean
}

/**
 * "On this page" rail — the docs-style right outline of the lesson currently
 * being read: the in-article headings with anchor-jump + scroll-spy.
 *
 * Container: reads the active lesson id from Redux (re-scan key) and derives its
 * outline from the rendered article via {@link useTableOfContents}. Self-sizing —
 * renders nothing when the active body has no headings (module overview, code /
 * sandbox tabs, short lessons), so the content reclaims the full width.
 *
 * @param props - {@link OnThisPageProps}
 */
export const OnThisPage = ({ mobile = false }: OnThisPageProps) => {
    const t = useTranslations()
    const contentId = useAppSelector((state) => state.content.id)
    const contentTab = useAppSelector((state) => state.tabs.contentTab)
    const { headings, activeId, onJump } = useTableOfContents(contentId)

    // The rail is the per-lesson sidebar (outline + actions + review + practice), so it shows
    // whenever a lesson is open — NOT only when the body has headings. Earlier it self-hid on
    // `headings.length === 0`, which wrongly dropped the WHOLE rail (incl. actions/review/practice)
    // on the Challenges tab (a card list with no headings) → the layout jumped. Now we hide only
    // when no lesson is open (e.g. module overview) so there is nothing to host.
    if (!contentId) {
        return null
    }

    // shared body: the outline + the per-lesson action/review/practice blocks
    const body = (
        <>
            {/* in-article outline — only when the active body has headings (the prose Content
                tab). The Challenges tab body is a card list with none, so the outline is omitted
                while the rest of the rail stays put. */}
            {headings.length > 0 && (
                <nav className="flex flex-col gap-3">
                    <Label>{t("onThisPage.title")}</Label>
                    <div className="flex flex-col gap-2">
                        {headings.map((heading) => (
                            <Link
                                key={heading.id}
                                onPress={() => onJump(heading.id)}
                                className={cn("cursor-pointer text-start",
                                    heading.level >= 3 && "pl-3",
                                    heading.id === activeId ? "text-accent-soft-foreground" : "text-muted",
                                )}
                            >
                                {heading.text}
                            </Link>
                        ))}
                    </div>
                </nav>
            )}

            {/* content actions (bookmark / share / fullscreen) — moved from the inline bar */}
            <ContentActions />

            {/* "review this lesson" — flashcard decks linked to this content */}
            <LessonFlashcards />

            {/* "practice this lesson" — challenges of this content (closes the loop). Hidden ON
                the Challenges tab, where the body already lists them (avoid the duplicate). */}
            {contentTab !== ContentTab.Challenges && <LessonChallenges />}
        </>
    )

    // mobile bottom-tab "On this page" view: full-width panel, no rail chrome
    if (mobile) {
        return <div className={"flex flex-col gap-6 p-6"}>{body}</div>
    }

    return (
        <aside
            className={cn(
                "hidden w-64 shrink-0 @app-lg:ml-8 @app-lg:block @app-lg:sticky @app-lg:top-16 @app-lg:self-start @app-lg:max-h-[calc(100dvh-4rem)]")}
        >
            {/* ScrollShadow owns the overflow + fades the top/bottom edges so a long
                outline reads as scrollable (the rail often overflows the viewport). */}
            <ScrollShadow hideScrollBar className="@app-lg:max-h-[calc(100dvh-4rem)] @app-lg:overflow-y-auto">
                <div className="flex flex-col gap-6 p-6 pl-0">{body}</div>
            </ScrollShadow>
        </aside>
    )
}

export default OnThisPage

import React from "react"
import { GithubLogoIcon } from "@phosphor-icons/react"
import { PageHeader } from "@/components/composites/layout/Page"
import { Breadcrumbs, type BreadcrumbItem } from "@/components/atoms/navigation/Breadcrumbs"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { AsyncContent, type AsyncContentEmptyProps } from "@/components/composites/async/AsyncContent"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { Grid } from "@/components/frames/Grid"
import { StackV } from "@/components/frames/Stack"
import { ContinueCardHero, ContinueCardItem } from "@/components/blocks/learn/ContinueCard"

/**
 * `PersonalProjectDashboard` — the capstone landing overview ("where am I + what's
 * next"), shown when the personal-project route carries no `taskId`: breadcrumb →
 * title/description/GitHub-status header, over a continue hero + completion meter,
 * over the current milestone's tasks as a two-column grid.
 *
 * Shapes:
 *   • `Full` — a next task exists, so the continue hero renders; GitHub connected
 *     vs not are states inside it.
 *   • `AllDone` — no `currentTask`, so the hero is gone, replaced by an "all done" line.
 *   • `Loading` — `AsyncContent` falls to the shimmer mirror.
 *   • `Empty` — `AsyncContent` falls to the empty message; the header is unaffected.
 */

/** One breadcrumb link above the dashboard title — plain data, the block builds the atom. */
export interface PersonalProjectDashboardCrumb {
    /** Stable React key. */
    key: string
    /** Display label. */
    label: string
    /** Has a handler → the crumb is pressable; the current page leaves it out. */
    onPress?: () => void
}

/** GitHub connection status fed into the header's status chip. */
export interface PersonalProjectGithubStatus {
    /** `true` → the chip renders in its connected (success) tone. */
    isConnected: boolean
    /**
     * Already-formatted display text — `"owner/repo · branch"` when connected, or
     * the "not connected" copy otherwise. Parsing the raw GitHub URL is the
     * caller's job (business logic, not presentation); the block only reacts to
     * `isConnected` for the chip's tone/icon.
     */
    label: string
}

/** The task currently in progress, fed into the continue hero. */
export interface PersonalProjectCurrentTask {
    /** 1-based position inside its milestone — the block prefixes it onto the title. */
    sortIndex: number
    /** Task title, WITHOUT the index prefix. */
    title: string
}

/** Where one keep-going task stands — the block owns the subtitle wording per state. */
export type PersonalProjectTaskSubtitleState = "active" | "done" | "locked" | "todo"

/** One task row in the keep-going grid — plain data, the block builds the tile. */
export interface PersonalProjectDashboardTask {
    /** Stable React key + the id handed back to `onSelectTask`. */
    id: string
    /** 1-based position inside the milestone — the block prefixes it onto the title. */
    sortIndex: number
    /** Task title, WITHOUT the index prefix. */
    title: string
    /** Which subtitle line this row shows — see {@link PersonalProjectTaskSubtitleState}. */
    subtitleState: PersonalProjectTaskSubtitleState
}

/** Aggregate KPIs across the whole capstone, shown under the completion meter. */
export interface PersonalProjectStats {
    /** Tasks completed so far. */
    done: number
    /** Tasks in the whole project. */
    total: number
    /** Total submit attempts across every task. */
    attempts: number
    /**
     * Already-formatted average score, e.g. `"18/20"` or `"—"` with no scored
     * attempts yet — computing the fraction is arithmetic the caller already
     * has to do to pick the "—" fallback, so it stays one string, same as
     * `ContentLanguage.label`.
     */
    avgLabel: string
}

/** Props for {@link PersonalProjectDashboard}. */
export interface PersonalProjectDashboardProps {
    /** Breadcrumb trail as DATA — the block builds `Breadcrumbs` itself. */
    breadcrumbItems?: Array<PersonalProjectDashboardCrumb>
    /** Dashboard title, e.g. "Personal Project". */
    title: string
    /** One-line description under the title. */
    description?: string
    /** GitHub connection status shown as a chip in the header's meta row. */
    githubStatus: PersonalProjectGithubStatus
    /** The next task to work on. Omit once every task is completed. */
    currentTask?: PersonalProjectCurrentTask
    /** Fired when the learner presses the continue hero's CTA. */
    onContinue: () => void
    /** The current milestone's name — the block prefixes "Continue ·" onto it. */
    milestoneLabel?: string
    /** The current milestone's tasks, in display order. */
    tasks: Array<PersonalProjectDashboardTask>
    /** Fired with a task's id when its tile is pressed. */
    onSelectTask: (taskId: string) => void
    /** Aggregate KPIs — see {@link PersonalProjectStats}. */
    stats: PersonalProjectStats
    /**
     * `true` while the milestone/progress fetch is running (no cache yet) — the
     * continue hero + progress stats + keep-going grid fall to their shimmer
     * mirror. The header (trail/title/description) is unaffected: it never
     * waits on this fetch.
     */
    isLoading?: boolean
    /**
     * `true` → the course has no milestones/tasks configured at all. Only takes
     * effect once `isLoading` is false.
     */
    isEmpty?: boolean
    /**
     * `true` → the header's own dynamic part (the GitHub chip) mirrors instead
     * of waiting on data — independent of `isLoading`, since that chip's data
     * comes off the enrollment record, not the milestone fetch.
     */
    isSkeleton?: boolean
}

/** Block-owned constant — the one classifying fact of the continue hero's subtitle. */
const NEXT_TASK_SUBTITLE = "Next task"

/** Block-owned constant — shown instead of the hero once every task is done. */
const ALL_DONE_TEXT = "You've completed every task in your personal project"

/** Block-owned constant — the completion meter's own label. */
const PROGRESS_LABEL = "Completion progress"

/** Block-owned constant — the keep-going grid's heading prefix. */
const KEEP_GOING_PREFIX = "Continue"

/** Block-owned wording per {@link PersonalProjectTaskSubtitleState} — the caller only sends the enum. */
const TASK_SUBTITLE: Record<PersonalProjectTaskSubtitleState, string> = {
    active: "Next task",
    done: "Completed",
    locked: "Locked",
    todo: "Not started",
}

/** Block-owned empty-state copy — the course has no capstone tasks configured yet. */
const EMPTY_STATE: AsyncContentEmptyProps = {
    title: "No tasks yet",
    description: "This course's personal project has no milestones/tasks set up yet.",
}

/** Placeholder shape guessed while loading (§12c) — mirrors `src`'s 4-row skeleton. */
const SKELETON_TASKS: Array<PersonalProjectDashboardTask> = Array.from({ length: 4 }, (_unused, index) => ({
    id: `skeleton-${index}`,
    sortIndex: index + 1,
    title: "",
    subtitleState: "todo",
}))

/** Assembles the milestone-name prefix the same way `KeepGoingPath` assembles its own heading. */
const keepGoingLabel = (milestoneLabel: string | undefined) =>
    milestoneLabel ? `${KEEP_GOING_PREFIX} · ${milestoneLabel}` : KEEP_GOING_PREFIX

/** Assembles the block-owned stats sentence under the completion meter. */
const statsLine = (stats: PersonalProjectStats) =>
    `${stats.done}/${stats.total} tasks completed · ${stats.attempts} submissions · average score ${stats.avgLabel}`

/** Props for the internal {@link Body} — the two async leaves, real or their shimmer guess. */
interface BodyProps {
    currentTask?: PersonalProjectCurrentTask
    onContinue: () => void
    milestoneLabel?: string
    tasks: Array<PersonalProjectDashboardTask>
    onSelectTask: (taskId: string) => void
    stats: PersonalProjectStats
    isSkeleton: boolean
}

/**
 * `ContinueHero+ProgressStats` and `KeepGoingGrid` — built ONCE and reused for
 * both the real content branch and the loading mirror (guessed data + forced
 * `isSkeleton`), so the two never drift into two hand-kept shapes.
 */
const Body = ({
    currentTask,
    onContinue,
    milestoneLabel,
    tasks,
    onSelectTask,
    stats,
    isSkeleton,
}: BodyProps) => {
    const heroSection = (
        <StackV
            gap={4}
            isSkeleton={isSkeleton}

            items={[
                () => (isSkeleton || currentTask ? (
                    <ContinueCardHero
                        title={currentTask ? `${currentTask.sortIndex}. ${currentTask.title}` : ""}
                        subtitle={NEXT_TASK_SUBTITLE}
                        isSkeleton={isSkeleton}
                        onPress={onContinue}


                    />
                ) : (
                    <Typography weight="semibold" text={ALL_DONE_TEXT} />
                )),
                () => (
                    <ProgressMeter
                        value={stats.done}
                        max={stats.total || 1}
                        label={PROGRESS_LABEL}
                        showValue
                        isSkeleton={isSkeleton}

                    />
                ),
                () => (
                    <Typography
                        size="xs"
                        color="muted"
                        isSkeleton={isSkeleton}
                        classNames={isSkeleton ? ["w-3/4"] : undefined}
                        text={statsLine(stats)}

                    />
                ),
            ]}
        />
    )

    return (
        <StackV
            gap={6}
            principle="block-boundary"
            explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
            isSkeleton={isSkeleton}

            items={[
                () => heroSection,
                () => (
                    <SurfaceCard
                        label={keepGoingLabel(milestoneLabel)}
                        isSkeleton={isSkeleton}


                        body={() => (
                            <Grid
                                columns={{ base: 1, sm: 2 }}
                                principle="content-row"
                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."

                                items={tasks.map((task) => ({
                                    key: task.id,
                                    content: () => (
                                        <ContinueCardItem
                                            title={`${task.sortIndex}. ${task.title}`}
                                            subtitle={TASK_SUBTITLE[task.subtitleState]}
                                            isSkeleton={isSkeleton}
                                            onPress={() => onSelectTask(task.id)}


                                        />
                                    ),
                                }))}
                            />
                        )}
                    />
                ),
            ]}
        />
    )
}

/**
 * The capstone landing overview. See the file header for the full contract.
 *
 * @param props - {@link PersonalProjectDashboardProps}
 */
const PersonalProjectDashboard = ({
    breadcrumbItems,
    title,
    description,
    githubStatus,
    currentTask,
    onContinue,
    milestoneLabel,
    tasks,
    onSelectTask,
    stats,
    isLoading = false,
    isEmpty = false,
    isSkeleton = false,
}: PersonalProjectDashboardProps) => {
    const crumbs: Array<BreadcrumbItem> = (breadcrumbItems ?? []).map((crumb) => ({
        key: crumb.key,
        label: crumb.label,
        onPress: crumb.onPress,
    }))

    const header = (
        <PageHeader

            isSkeleton={isSkeleton}
            breadcrumb={() =>
                isSkeleton || crumbs.length ? (
                    <div className="w-fit">
                        <Breadcrumbs collapseOnMobile items={crumbs} isSkeleton={isSkeleton} />
                    </div>
                ) : undefined
            }
            title={title}
            description={description}
            meta={() =>
                isSkeleton ? (
                    <Chip isSkeleton />
                ) : (
                    <Chip
                        tone={githubStatus.isConnected ? "success" : "default"}
                        icon={GithubLogoIcon}
                        text={githubStatus.label}
                    />
                )
            }
        />
    )

    const asyncBody = (
        <AsyncContent
            isLoading={isLoading}
            skeleton={() => (
                <Body
                    currentTask={{ sortIndex: 1, title: "" }}
                    onContinue={onContinue}
                    milestoneLabel={milestoneLabel}
                    tasks={SKELETON_TASKS}
                    onSelectTask={onSelectTask}
                    stats={{ done: 0, total: 0, attempts: 0, avgLabel: "" }}
                    isSkeleton

                />
            )}
            isEmpty={isEmpty}
            emptyContent={EMPTY_STATE}
            content={() => (
                <Body
                    currentTask={currentTask}
                    onContinue={onContinue}
                    milestoneLabel={milestoneLabel}
                    tasks={tasks}
                    onSelectTask={onSelectTask}
                    stats={stats}
                    isSkeleton={false}

                />
            )}
        />
    )

    return (
        <div>
            <StackV
                gap={6}
                isSkeleton={isSkeleton}

                items={[
                    () => header,
                    () => asyncBody,
                ]}
            />
        </div>
    )
}

