import { ExtendedTabs } from "@/components/blocks/navigation/ExtendedTabs"
import { TabsCard } from "@/components/blocks/navigation/TabsCard"
import { SelectableCardGroup } from "@/components/blocks/navigation/SelectableCardGroup"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { Typography as HouseTypography } from "@/components/atoms/text/Typography"
import { AsyncContentEmpty } from "@/components/composites/async/AsyncContent"
import { MarkdownContent } from "@/components/blocks/rendering/MarkdownContent"
import { RagSourceGraph } from "@/components/blocks/rendering/RagSourceGraph"
import { GithubIcon } from "@/components/svg/GithubIcon"
import { RagPlaygroundSourceKind, RAG_SAMPLES } from "./source"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** One retrieved source chunk backing an answer (mirrors the socket `rag:citations` shape). */
interface PlaygroundRagWorkspaceSource {
    /** File path (or synthetic label) the chunk came from. */
    filePath: string
    /** Truncated excerpt of the chunk's content. */
    snippet: string
    /** Retrieval score (0-1), when the local retriever reports one. */
    score?: number
}

/** One asked-and-(possibly-still-)answering turn in the local Q&A thread. */
interface PlaygroundTurn {
    /** The `runId` correlating this turn to its streamed `rag:answer`/`rag:citations`. */
    id: string
    question: string
    answerText: string
    sources: Array<PlaygroundRagWorkspaceSource>
    done: boolean
    asking: boolean
}

/** Which view a turn's sources section renders — the plain citation list, or a graph of question→source edges. */
type SourcesViewMode = "doc" | "graph"

/** All four import kinds — the agent now resolves sample (built-in catalog) and github (REST) too, not just inline code. */
type WorkspaceImportKind = RagPlaygroundSourceKind

/** Flat chat input — the composer pill owns fill/padding; Input is just where you type. */
const FLAT_CHAT_INPUT_CLASS =
    "w-full !rounded-none border-0 !bg-transparent !p-0 !shadow-none ring-0 focus:ring-0 hover:!bg-transparent focus:!bg-transparent data-[hovered=true]:!bg-transparent data-[focused=true]:!bg-transparent"

/** Props for the {@link PlaygroundRagWorkspace} feature. */
export interface PlaygroundRagWorkspaceProps extends WithClassNames<undefined> {
    /** Latest streamed answer chunk from the agent (`state.ragAnswer`), or `null`. */
    ragAnswer: { runId: string; text: string; done: boolean } | null
    /** Latest citations from the agent (`state.ragCitations`), or `null`. */
    ragCitations: { runId: string; sources: Array<PlaygroundRagWorkspaceSource> } | null
    /** Emit `rag:index` — ask the connected agent to index a source (the parent owns the socket). */
    sendRagIndex: (source: { kind: string; code?: string; fileName?: string; githubUrl?: string; sampleId?: string }) => void
    /** Emit `rag:ask` — ask the connected agent a question over the indexed code, correlated by `runId`. */
    sendRagAsk: (runId: string, question: string) => void
}

/**
 * Machine-backed RAG workspace — the RIGHT pane of a `kind: "rag"`
 * {@link import("@/components/blocks/learn/PlaygroundRagSession").PlaygroundRagSession}.
 * A chat UX (import → ask → streamed answer bubbles → citations with a per-turn
 * "Docs / Diagram" source toggle) that runs over the Playground BYOM socket —
 * the learner's own local Ollama, relayed by the paired CLI agent. This is the
 * app's ONLY RAG surface (the old server-side marketing demo was removed).
 *
 * Purely presentational over the socket: the parent `PlaygroundRagSession` owns
 * the `usePlaygroundByomSocketIo` hook and passes the streamed `ragAnswer` /
 * `ragCitations` down plus the `sendRagIndex` / `sendRagAsk` emitters. This
 * component holds only the local composer + turn-thread state, folding each
 * streamed chunk into the matching turn by `runId`.
 *
 * Import supports all four sources — paste / upload (inline code), a built-in
 * sample from the static {@link RAG_SAMPLES} catalog, or a public GitHub repo:
 * the agent resolves sample id → local catalog code and github URL → repo files
 * (via the GitHub REST API) before chunking + embedding.
 *
 * @param props - See {@link PlaygroundRagWorkspaceProps}.
 *
 * @see Story: .storybook/stories/features/learn/Playground/PlaygroundRagWorkspace/PlaygroundRagWorkspace.stories
 */
export const PlaygroundRagWorkspace = ({
    ragAnswer,
    ragCitations,
    sendRagIndex,
    sendRagAsk,
    className,
}: PlaygroundRagWorkspaceProps) => {
    const t = useTranslations()

    // ── import ────────────────────────────────────────────────────────────
    const [importKind, setImportKind] = useState<WorkspaceImportKind>(RagPlaygroundSourceKind.Paste)
    const [pasteCode, setPasteCode] = useState("")
    const [uploadFileName, setUploadFileName] = useState<string>()
    const [uploadCode, setUploadCode] = useState("")
    const [githubUrl, setGithubUrl] = useState("")
    // built-in catalog is a static id+label list (the agent owns the code and
    // resolves the chosen id locally on index) — pre-select the first so the
    // Sample tab is never empty.
    const [selectedSampleId, setSelectedSampleId] = useState<string>(RAG_SAMPLES[0].id)
    const [imported, setImported] = useState(false)

    // ── chat ──────────────────────────────────────────────────────────────
    const [question, setQuestion] = useState("")
    const [turns, setTurns] = useState<Array<PlaygroundTurn>>([])
    const [sourcesModeByTurn, setSourcesModeByTurn] = useState<Record<string, SourcesViewMode>>({})
    // monotonic fallback id when crypto.randomUUID is unavailable.
    const runCounterRef = useRef(0)

    const canImport = (() => {
        switch (importKind) {
        case RagPlaygroundSourceKind.Paste:
            return pasteCode.trim().length > 0
        case RagPlaygroundSourceKind.Upload:
            return uploadCode.trim().length > 0
        case RagPlaygroundSourceKind.Sample:
            return selectedSampleId != null
        case RagPlaygroundSourceKind.Github:
            return githubUrl.trim().length > 0
        default:
            return false
        }
    })()

    // a turn is still streaming while its last entry isn't done → block a new ask.
    const busy = turns.length > 0 && !turns[turns.length - 1].done

    // fold each streamed answer chunk into the matching turn (by runId).
    useEffect(() => {
        if (!ragAnswer) {
            return
        }
        setTurns((prev) => prev.map((turn) => (
            turn.id === ragAnswer.runId
                ? { ...turn, answerText: ragAnswer.text, done: ragAnswer.done, asking: false }
                : turn
        )))
    }, [ragAnswer])

    // attach citations to the matching turn (by runId).
    useEffect(() => {
        if (!ragCitations) {
            return
        }
        setTurns((prev) => prev.map((turn) => (
            turn.id === ragCitations.runId ? { ...turn, sources: ragCitations.sources } : turn
        )))
    }, [ragCitations])

    const onFileChange = (file?: File) => {
        if (!file) {
            return
        }
        setUploadFileName(file.name)
        const reader = new FileReader()
        reader.onload = () => setUploadCode(String(reader.result ?? ""))
        reader.readAsText(file)
    }

    const onImport = () => {
        if (!canImport) {
            return
        }
        switch (importKind) {
        case RagPlaygroundSourceKind.Paste:
            sendRagIndex({ kind: RagPlaygroundSourceKind.Paste, code: pasteCode })
            break
        case RagPlaygroundSourceKind.Upload:
            sendRagIndex({ kind: RagPlaygroundSourceKind.Upload, code: uploadCode, fileName: uploadFileName })
            break
        case RagPlaygroundSourceKind.Sample:
            sendRagIndex({ kind: RagPlaygroundSourceKind.Sample, sampleId: selectedSampleId })
            break
        case RagPlaygroundSourceKind.Github:
            sendRagIndex({ kind: RagPlaygroundSourceKind.Github, githubUrl: githubUrl.trim() })
            break
        }
        setImported(true)
        setTurns([])
        setSourcesModeByTurn({})
    }

    const onAsk = () => {
        const trimmed = question.trim()
        if (!trimmed || !imported || busy) {
            return
        }
        setQuestion("")
        const runId =
            typeof crypto !== "undefined" && crypto.randomUUID
                ? crypto.randomUUID()
                : `pending-${(runCounterRef.current += 1)}`
        setTurns((prev) => [
            ...prev,
            { id: runId, question: trimmed, answerText: "", sources: [], done: false, asking: true },
        ])
        sendRagAsk(runId, trimmed)
    }

    const IMPORT_TABS = [
        {
            key: RagPlaygroundSourceKind.Paste,
            label: t("ragPlayground.import.tabs.paste"),
            icon: <CodeIcon aria-hidden focusable="false" className="size-4" />,
        },
        {
            key: RagPlaygroundSourceKind.Upload,
            label: t("ragPlayground.import.tabs.upload"),
            icon: <FileArrowUpIcon aria-hidden focusable="false" className="size-4" />,
        },
        {
            key: RagPlaygroundSourceKind.Sample,
            label: t("ragPlayground.import.tabs.sample"),
            icon: <StackIcon aria-hidden focusable="false" className="size-4" />,
        },
        {
            key: RagPlaygroundSourceKind.Github,
            label: t("ragPlayground.import.tabs.github"),
            icon: <GithubIcon aria-hidden className="size-4" />,
        },
    ]

    return (
        <div className={cn("flex h-full flex-col", className)}>
            {/* ── import strip ── */}
            <div className="flex flex-col gap-3 border-b border-default px-4 py-3">
                <TabsCard
                    leftTabs={{
                        items: IMPORT_TABS,
                        selectedKey: importKind,
                        ariaLabel: t("ragPlayground.import.tabsAria"),
                        onSelectionChange: (key) => setImportKind(key as WorkspaceImportKind),
                    }}
                />
                {importKind === RagPlaygroundSourceKind.Paste ? (
                    <TextField aria-label={t("ragPlayground.import.pastePlaceholder")}>
                        <TextArea
                            rows={5}
                            className="font-mono text-sm"
                            placeholder={t("ragPlayground.import.pastePlaceholder")}
                            value={pasteCode}
                            onChange={(event) => setPasteCode(event.target.value)}
                        />
                    </TextField>
                ) : null}
                {importKind === RagPlaygroundSourceKind.Upload ? (
                    <div className="flex flex-col gap-2">
                        <label
                            htmlFor="playground-rag-workspace-upload"
                            className="flex cursor-pointer flex-col items-center justify-center gap-2 rounded-xl border border-dashed border-default bg-surface px-4 py-6 text-center transition-colors hover:bg-default"
                        >
                            <FileArrowUpIcon aria-hidden focusable="false" className="size-6 text-muted" />
                            <Typography type="body-sm" color="muted">
                                {uploadFileName ?? t("ragPlayground.import.uploadHint")}
                            </Typography>
                        </label>
                        <input
                            id="playground-rag-workspace-upload"
                            type="file"
                            accept=".ts,.tsx,.js,.jsx,.py,.go,.java,.cs,.rb,.php,.rs,.cpp,.c,.h,.md,.txt,.json,.yaml,.yml"
                            className="hidden"
                            onChange={(event) => onFileChange(event.target.files?.[0])}
                        />
                    </div>
                ) : null}
                {importKind === RagPlaygroundSourceKind.Sample ? (
                    <div className="flex flex-col gap-2">
                        <Typography type="body-xs" color="muted">
                            {t("ragPlayground.import.sampleHint")}
                        </Typography>
                        <SelectableCardGroup
                            ariaLabel={t("ragPlayground.import.samplePicker.ariaLabel")}
                            items={RAG_SAMPLES.map((sample) => ({
                                value: sample.id,
                                label: sample.label,
                            }))}
                            value={selectedSampleId}
                            onChange={setSelectedSampleId}
                            columns={1}
                        />
                    </div>
                ) : null}
                {importKind === RagPlaygroundSourceKind.Github ? (
                    <div className="flex flex-col gap-2">
                        <Typography type="body-xs" color="muted">
                            {t("ragPlayground.import.githubHint")}
                        </Typography>
                        <TextField aria-label={t("ragPlayground.import.githubPlaceholder")}>
                            <Input
                                placeholder={t("ragPlayground.import.githubPlaceholder")}
                                value={githubUrl}
                                onChange={(event) => setGithubUrl(event.target.value)}
                            />
                        </TextField>
                    </div>
                ) : null}
                <Button
                    variant="primary"
                    size="sm"
                    isDisabled={!canImport}
                    onPress={onImport}
                >
                    {t("ragPlayground.import.cta")}
                </Button>
            </div>

            {/* ── turns thread ── */}
            <ScrollShadow
                hideScrollBar
                className="flex flex-1 flex-col gap-4 overflow-y-auto px-4 py-4"
            >
                {!imported ? (
                    <AsyncContentEmpty
                        icon={CodeIcon}
                        title={t("playground.ragWorkspace.emptyNoImportTitle")}
                    />
                ) : turns.length === 0 ? (
                    <AsyncContentEmpty
                        icon={SparkleIcon}
                        title={t("playground.ragWorkspace.emptyReadyTitle")}
                    />
                ) : (
                    turns.map((turn) => (
                        <div key={turn.id} className="flex flex-col gap-2">
                            <div className="self-end rounded-2xl bg-accent px-4 py-2">
                                <Typography type="body-sm" className="text-accent-foreground">
                                    {turn.question}
                                </Typography>
                            </div>
                            <div className="rounded-2xl border border-default bg-surface px-4 py-3">
                                {turn.answerText ? (
                                    <MarkdownContent markdown={turn.answerText} />
                                ) : !turn.done ? (
                                    <div className="flex items-center gap-2">
                                        <span className="size-2 animate-pulse rounded-full bg-muted" />
                                        <Typography type="body-sm" color="muted">
                                            {t("ragPlayground.chat.thinking")}
                                        </Typography>
                                    </div>
                                ) : null}
                                {turn.sources.length > 0 ? (
                                    <div className="mt-3 flex flex-col gap-2 border-t border-default pt-3">
                                        <div className="flex items-center justify-between gap-2">
                                            <Typography type="body-xs" color="muted">
                                                {t("ragPlayground.chat.sources")}
                                            </Typography>
                                            <ExtendedTabs
                                                size="sm"
                                                selectedKey={sourcesModeByTurn[turn.id] ?? "doc"}
                                                onSelectionChange={(key) => setSourcesModeByTurn((prev) => ({
                                                    ...prev,
                                                    [turn.id]: key as SourcesViewMode,
                                                }))}
                                            >
                                                <Tabs.ListContainer>
                                                    <Tabs.List aria-label={t("ragPlayground.chat.sources")}>
                                                        <Tabs.Tab id="doc">
                                                            {t("ragPlayground.chat.sourcesModeDoc")}
                                                            <Tabs.Indicator />
                                                        </Tabs.Tab>
                                                        <Tabs.Tab id="graph">
                                                            {t("ragPlayground.chat.sourcesModeGraph")}
                                                            <Tabs.Indicator />
                                                        </Tabs.Tab>
                                                    </Tabs.List>
                                                </Tabs.ListContainer>
                                            </ExtendedTabs>
                                        </div>
                                        {(sourcesModeByTurn[turn.id] ?? "doc") === "graph" ? (
                                            <RagSourceGraph question={turn.question} sources={turn.sources} />
                                        ) : (
                                            <SurfaceCardList
                                                variant="nested"
                                                items={turn.sources.map((source, index): SurfaceCardListItem => ({
                                                    key: `${turn.id}-${index}`,
                                                    // monospace is data chrome for source paths — lives inside
                                                    // free-form content (not a SurfaceCard classNames door).
                                                    content: () => (
                                                        <div className="font-mono">
                                                            <HouseTypography size="sm" truncate text={source.filePath} />
                                                            <HouseTypography size="xs" color="muted" truncate text={source.snippet} />
                                                        </div>
                                                    ),
                                                }))}
                                            />
                                        )}
                                    </div>
                                ) : null}
                            </div>
                        </div>
                    ))
                )}
            </ScrollShadow>

            {/* ── composer, pinned at the bottom ── */}
            <div className="border-t border-default px-4 py-3">
                <div className={cn(
                    "flex flex-col gap-2 rounded-2xl bg-default px-3 py-2 focus-within:ring-2 focus-within:ring-accent",
                    !imported && "opacity-60",
                )}
                >
                    <TextField
                        aria-label={t("ragPlayground.chat.placeholder")}
                        className="w-full"
                        isDisabled={!imported}
                    >
                        <Input
                            className={FLAT_CHAT_INPUT_CLASS}
                            placeholder={t("ragPlayground.chat.placeholder")}
                            value={question}
                            onChange={(event) => setQuestion(event.target.value)}
                            onKeyDown={(event) => {
                                if (event.key === "Enter") {
                                    event.preventDefault()
                                    onAsk()
                                }
                            }}
                        />
                    </TextField>
                    <div className="flex w-full items-center justify-end gap-2">
                        <Button
                            isIconOnly
                            size="sm"
                            variant="primary"
                            isDisabled={!imported || busy || !question.trim()}
                            aria-label={t("ragPlayground.chat.send")}
                            onPress={onAsk}
                        >
                            <PaperPlaneTiltIcon aria-hidden focusable="false" className="size-5" />
                        </Button>
                    </div>
                </div>
            </div>
        </div>
    )
}

import React from "react"
import { CircleDashedIcon, CubeIcon, PlugsIcon } from "@phosphor-icons/react"
import { Chip, type ChipTone } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { SurfaceCardAccordion, type SurfaceCardAccordionItem } from "@/components/composites/cards/SurfaceCard"
import { EmptyState } from "@/components/composites/feedback/EmptyState"
import { ListRow } from "@/components/composites/lists/List"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * `PlaygroundResourcePanel` — the right pane of the playground screen, the live
 * workspace: nothing until the paired machine reports in, then the resource
 * snapshot the socket sent, grouped by kind. Reuses `SurfaceCard.Accordion`,
 * `List.Row`, and `EmptyState` rather than inventing its own. Status uses `Chip`,
 * not `EnumChip`, because it is free-form CLI text ("Up 2 hours", "Exited (0)"): a
 * `toneForStatus` heuristic degrades to neutral on anything unrecognized. One shape,
 * three states (not-connected, connected-empty, connected-with-resources) — a header
 * row over a body region whose fill changes.
 */

/** Whether the playground's paired machine is reachable right now. */
export type PlaygroundConnectionState = "notConnected" | "connected"

/** One resource line as the socket reports it — flat, ungrouped, free-form status text. */
export interface PlaygroundResourceEntry {
    /** What kind of resource this is (`"Container"`, `"Image"`, `"Pod"`...) — the block's own group key. */
    kind: string
    /** The resource's name/id as the agent reports it — assumed unique within its `kind`. */
    name: string
    /** Free-form status text straight from the CLI (`"Up 2 hours"`, `"Exited (0)"`...). */
    status: string
}

/** Props for {@link PlaygroundResourcePanel}. */
export interface PlaygroundResourcePanelProps {
    /** Whether the paired machine is reachable right now. */
    connection: PlaygroundConnectionState
    /**
     * The flat resource snapshot as the socket reports it. Ignored while
     * `connection === "notConnected"`. Empty while connected means the machine
     * paired but hasn't reported a snapshot yet.
     */
    resources: Array<PlaygroundResourceEntry>
}

/** The panel's own fixed header wording — see the file header for why this isn't a prop. */
const PANEL_LABEL = "Resources"

/** One resource kind bucket, in first-seen order. */
interface PlaygroundResourceGroup {
    kind: string
    resources: Array<PlaygroundResourceEntry>
}

/**
 * Buckets the flat snapshot by `kind`, preserving each kind's FIRST-SEEN order —
 * see the file header for why there's no hardcoded kind priority table.
 */
const groupByKind = (resources: ReadonlyArray<PlaygroundResourceEntry>): Array<PlaygroundResourceGroup> => {
    const order: Array<string> = []
    const byKind = new Map<string, Array<PlaygroundResourceEntry>>()
    for (const resource of resources) {
        if (!byKind.has(resource.kind)) {
            byKind.set(resource.kind, [])
            order.push(resource.kind)
        }
        byKind.get(resource.kind)?.push(resource)
    }
    return order.map((kind) => ({ kind, resources: byKind.get(kind) ?? [] }))
}

/** First letter uppercased only — the kind arrives as one word from the agent (`"container"`, `"pod"`...). */
const titleCaseKind = (kind: string): string => (kind.length === 0 ? kind : kind[0].toUpperCase() + kind.slice(1))

// Checked in this ORDER: a status can contain more than one signal word (e.g.
// "unhealthy" contains "healthy"), so the negative buckets are matched first —
// see the file header for why this heuristic exists instead of a closed enum.
const DANGER_STATUS = /\b(exited|dead|error|failed?|crash(ed)?|unhealthy|stopped)\b/i
const WARNING_STATUS = /\b(restarting|creating|pending|paused|starting|stopping|degraded)\b/i
const SUCCESS_STATUS = /\b(running|ready|active|healthy|up)\b/i

/** Free-form CLI status text → chip tone. Unrecognized text degrades to `"default"`, never throws. */
const toneForStatus = (status: string): ChipTone => {
    if (DANGER_STATUS.test(status)) return "danger"
    if (WARNING_STATUS.test(status)) return "warning"
    if (SUCCESS_STATUS.test(status)) return "success"
    return "default"
}

/** Builds one kind group's accordion row: trigger = kind + count, panel = one `List.Row` per resource. */
const groupToAccordionItem = (group: PlaygroundResourceGroup): SurfaceCardAccordionItem => ({
    id: group.kind,
    title: titleCaseKind(group.kind),
    titleEnd: () => (
        <Chip
            tone="default"
            text={String(group.resources.length)}

        />
    ),
    body: () => (
        <StackV
            gap={1}
            principle="sibling-stack"
            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."

            items={group.resources.map((resource, index) => () => (
                <ListRow
                    title={resource.name}
                    meta={() => (
                        <Chip
                            tone={toneForStatus(resource.status)}
                            text={resource.status}

                        />
                    )}
                    divider={index < group.resources.length - 1}

                />
            ))}
        />
    ),
})

/**
 * The playground's live-workspace pane. See the file header for the full
 * contract (grouping, the status heuristic, and the one-leaf/three-state call).
 *
 * @param props - {@link PlaygroundResourcePanelProps}
 */
const PlaygroundResourcePanel = ({
    connection,
    resources,
}: PlaygroundResourcePanelProps) => {
    const isConnected = connection === "connected"
    const hasResources = isConnected && resources.length > 0

    const groups = hasResources ? groupByKind(resources) : []

    const body = !isConnected ? (
        <EmptyState
            icon={PlugsIcon}
            title="Not paired yet"
            description="Pair a machine to see the resources running in your workspace."

        />
    ) : !hasResources ? (
        <EmptyState
            icon={CircleDashedIcon}
            title="Waiting for data"
            description="Machine paired — waiting for the first resource snapshot."

        />
    ) : (
        <SurfaceCardAccordion
            items={groups.map((group) => groupToAccordionItem(group))}
            allowsMultipleExpanded
            defaultExpandedKeys={new Set(groups.map((group) => group.kind))}


        />
    )

    const headerRow = (
        <StackH
            gap={3}
            principle="value-row"
            explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
            justify="between"
            align="center"

            items={[
                () => (
                    <Typography
                        size="sm"
                        weight="medium"
                        prefixIcon={CubeIcon}
                        text={PANEL_LABEL}

                    />
                ),
                // A count of zero (or no snapshot at all) is not news — see `ContentModeNav`'s
                // "a count of zero is not news" convention — so it only appears once there's
                // something real to count.
                ...(hasResources ? [() => (
                    <Typography
                        size="xs"
                        color="muted"
                        tabularNums
                        text={String(resources.length)}

                    />
                )] : []),
            ]}
        />
    )

    return (
        <StackV identity={{ tier: "block", component: "PlaygroundResourcePanel" }}
            gap={4}

            items={[
                () => headerRow,
                () => body,
            ]}
        />
    )
}

export { PlaygroundResourcePanel }

import React from "react"
import { LinkBack } from "@/components/atoms/navigation/Link"
import { PageHeader } from "@/components/composites/layout/Page"

/**
 * `PlaygroundSetupHeader` — the identity cluster at the top of the playground Setup
 * screen: a way back to the playground hub, the exercise title, and its one-line
 * intro. Sibling of `ContentHeader` / `CourseBrief` but carries no meta cluster —
 * a playground exercise has no read state, outcomes, or counts. The single hop back
 * is a `LinkBack` placed directly in `PageHeader.breadcrumb`. One shape:
 * `isSkeleton` swaps `title`/`description` to their shimmer mirror in the same
 * slots; the back link never waits on the fetch, so it gets no skeleton.
 */

/** Props for {@link PlaygroundSetupHeader}. */
export interface PlaygroundSetupHeaderProps {
    /** Label on the back link, e.g. "Playground" — the hub this exercise was opened from. */
    breadcrumbLabel: string
    /** Fired when the back link is pressed — the caller owns the routing. */
    onBack: () => void
    /** Exercise title. */
    title: string
    /** One-line intro to the exercise. */
    description?: string
    /**
     * `true` → title/description switch to their shimmer mirror while the
     * exercise is loading. The flag flows down into the real text atoms
     * rather than a parallel skeleton tree (§12c); the back link stays live
     * (see file header).
     */
    isSkeleton?: boolean
}

/**
 * Identity cluster at the top of the playground Setup screen. See the file
 * header for the full contract.
 *
 * @param props - {@link PlaygroundSetupHeaderProps}
 */
const PlaygroundSetupHeader = ({
    breadcrumbLabel,
    onBack,
    title,
    description,
    isSkeleton = false,
}: PlaygroundSetupHeaderProps) => {
    return (
        <div>
            <PageHeader

                isSkeleton={isSkeleton}
                breadcrumb={() => (
                    <div className="w-fit">
                        <LinkBack label={breadcrumbLabel} onPress={onBack} />
                    </div>
                )}
                title={title}
                description={description}
            />
        </div>
    )
}

export { PlaygroundSetupHeader }

import React from "react"
import { Typography } from "@/components/atoms/text/Typography"
import { Divider } from "@/components/atoms/display/Divider"
import { StackV, StackH } from "@/components/frames/Stack"

/** Props for the local {@link CommandSkeleton} mirror. */
interface CommandSkeletonProps {
    /** How many placeholder code lines to draw. Defaults to 1. */
    lines?: number
}

/**
 * Placeholder mirror of the code-block chrome `MarkdownContent`'s `pre` renderer
 * draws (border, header divider, lang label) — see file header for why this
 * block owns it instead of `MarkdownContent` shipping an `isSkeleton`.
 */
export const CommandSkeleton = ({ lines = 1 }: CommandSkeletonProps) => (
    <div className="overflow-hidden rounded-2xl border border-default bg-default/30">
        <StackH
            gap={1}
            align="center"
            justify="between"
            padding={{ x: 4, y: 3 }}
            principle="control-pad"
            explain="Control hit-area inset — not row-pad, because this pads a single interactive control rather than a full content row."
            body={() => <Typography size="xs" isSkeleton classNames={["w-1/4"]} />}
        />
        <Divider />
        <StackV
            gap={3}
            padding={4}
            principle="cell-pad"
            explain="Tight cell inset — not card-padding, because this sits inside a dense table or list cell rather than a card body."
            body={() => (
                <StackV
                    gap={3}
                    principle="sibling-stack"
                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                    items={Array.from({ length: lines }, (_unused, index) => () => (
                        <Typography size="xs" isSkeleton classNames={[index === lines - 1 ? "w-1/2" : "w-3/4"]} />
                    ))}
                />
            )}
        />
    </div>
)

import React from "react"
import { Typography } from "@/components/atoms/text/Typography"
import { StackV, StackH } from "@/components/frames/Stack"
import { type PlaygroundSetupOs } from "../types"

const OS_ORDER: ReadonlyArray<PlaygroundSetupOs> = ["mac", "win", "linux"]

// Depends on the loop variable, so it cannot be hoisted to a const above the
// return — a small named helper instead, in the style this file already uses.
const renderOsTabSkeleton = (key: PlaygroundSetupOs) => (
    <StackV
        key={key}
        gap={2}
        align="center"
        principle="title-subtitle"
        explain="Title over supporting line — not label-field, because neither line is a form control label."
        items={[
            () => <Typography size="sm" isSkeleton classNames={["w-1/3"]} />,
            () => <Typography size="xs" isSkeleton classNames={["w-1/3"]} />,
        ]}
    />
)

/** Placeholder mirror of the OS tab row — label+underline bar per OS, matching `Tabs`'s own `secondary` skeleton shape. */
export const OsTabsSkeleton = () => (
    <StackH gap={3} items={OS_ORDER.map((key) => () => renderOsTabSkeleton(key))} />
)

import React, { useState } from "react"
import { type SkeletonProps } from "@/components/frames/_slot"
import type { ReactNode } from "react"
import { Tabs } from "@heroui/react"
import {
    ArrowClockwiseIcon,
    ArrowsClockwiseIcon,
} from "@phosphor-icons/react"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { EnumChip, type EnumChipEntry } from "@/components/composites/chips/EnumChip"
import { MarkdownContent } from "@/components/composites/viewers/MarkdownContent"
import { TabsExtended } from "@/components/atoms/navigation/Tabs"
import { Button } from "@/components/atoms/buttons/Button"
import { Callout } from "@/components/composites/feedback/Callout"
import { ConfirmDialog } from "@/components/composites/feedback/ConfirmDialog"
import { Typography } from "@/components/atoms/text/Typography"
import { StackV, StackH } from "@/components/frames/Stack"
import { CommandSkeleton } from "./CommandSkeleton"
import { OsTabsSkeleton } from "./OsTabsSkeleton"
import { type PlaygroundSetupOs, type PlaygroundSetupStepsProps } from "./types"

export type { PlaygroundSetupOs, PlaygroundSetupFlavor, PlaygroundSetupStepsProps } from "./types"

/**
 * BLOCK — `PlaygroundSetupSteps`: the ordered setup guide for a playground — pair
 * the local agent, install the engine (an OS-tabbed guide), and — Ollama flavor
 * only — pull the VRAM-sized models. Each step carries its own status chip,
 * why-it-matters line, runnable command(s), and re-check action.
 *
 * TWO LEAVES, ONE PER `flavor` (§14d.2 — see the component's file header for why
 * this differs from `ChallengeBrief`'s single "one leaf, N optional sections"):
 * `flavor` is chosen once per PLAYGROUND KIND, not per render, so a caller wired
 * to `"infra"` never even carries the model-readiness props the third step
 * needs — the third `SurfaceCard` is a structural fact of the ollama leaf, not a
 * data condition that could show up on the infra one.
 */

/** One `SurfaceCard` step, built by this block before render — named per §"every data shape has a name". */
interface StepEntry {
    key: string
    title: string
    status: StepStatus
    body: ReactNode
}

/** Fixed platform-wide embedding model — see file header: unlike the generation model, this never varies by device. */
const EMBEDDING_MODEL_NAME = "bge-m3"

const OS_ORDER: ReadonlyArray<PlaygroundSetupOs> = ["mac", "win", "linux"]
const OS_LABEL: Record<PlaygroundSetupOs, string> = { mac: "macOS", win: "Windows", linux: "Linux" }

/** The two-value readiness enum driving every step's trailing chip. */
type StepStatus = "ready" | "pending"

/** status → chip label/color — fixed Vietnamese copy this block owns (§14d.1), matching `PlaygroundReadinessChecklist`'s table. */
const STEP_STATUS_MAP: Record<StepStatus, EnumChipEntry> = {
    ready: { label: "Ready", color: "success" },
    pending: { label: "Not done", color: "default" },
}

/** Wraps a shell command in a fenced ```bash block for `MarkdownContent`. */
const bashBlock = (command: string): string => "```bash\n" + command + "\n```"

/**
 * The playground setup guide. See the file header for the reuse check, the
 * two-leaves-per-flavor call, and the skeleton-mirror judgement calls.
 *
 * @param props - {@link PlaygroundSetupStepsProps}
 */
const PlaygroundSetupSteps = ({
    flavor,
    engineName,
    osGuides,
    pairCommand,
    pairingCodeSecondsLeft = null,
    pairingCodeExpired = false,
    onRefreshPairingCode,
    isRefreshingPairingCode = false,
    agentReady,
    engineReady,
    genModelReady = false,
    embedModelReady = false,
    recommendedGenModel,
    deviceKnown = true,
    engineDetail,
    onVerify,
    isSkeleton = false,
}: PlaygroundSetupStepsProps) => {
    const [os, setOs] = useState<PlaygroundSetupOs>("mac")
    const [isRotateConfirmOpen, setRotateConfirmOpen] = useState(false)

    // Rotating a code nobody's agent holds yet is free; rotating a code the connected
    // agent depends on is disruptive, so THAT path confirms first (see file header).
    const onRotateClick = () => {
        if (!onRefreshPairingCode) return
        if (agentReady) {
            setRotateConfirmOpen(true)
        } else {
            onRefreshPairingCode()
        }
    }
    const onConfirmRotate = () => {
        onRefreshPairingCode?.()
        setRotateConfirmOpen(false)
    }

    // Shared by every step (see PROPS doc on `onVerify`) — built once as functions, not a
    // single JSX element re-used across positions, so each step gets its own element instance.
    const renderVerifyButton = (): ReactNode => {
        if (isSkeleton) return <Button isSkeleton size="sm" />
        if (!onVerify) return null
        return (
            <Button
                label="Check again"
                variant="tertiary"
                size="sm"
                prefixIcon={ArrowClockwiseIcon}
                onPress={onVerify}

            />
        )
    }
    const renderRotateButton = (): ReactNode => {
        if (isSkeleton) return <Button isSkeleton size="sm" />
        if (!onRefreshPairingCode) return null
        return (
            <Button
                label="Get new code"
                variant="tertiary"
                size="sm"
                prefixIcon={ArrowsClockwiseIcon}
                onPress={onRotateClick}
                isPending={isRefreshingPairingCode}

            />
        )
    }

    const pairingCodeNote: ReactNode = pairingCodeExpired
        ? (
            <Typography
                size="xs"
                color="danger"
                text="The pairing code has expired — get a new code to continue."

            />
        )
        : pairingCodeSecondsLeft != null
            ? (
                <Typography
                    size="xs"
                    color="muted"
                    text={`Code valid for ${pairingCodeSecondsLeft} more seconds`}

                />
            )
            : null

    const pairStepBody: ReactNode = (
        <StackV
            gap={3}
            principle="sibling-stack"
            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <Typography
                        size="sm"
                        color="muted"
                        isSkeleton={isSkeleton}
                        text="The local agent is the bridge that lets Playground control your machine — skip this step and every command in the following steps fails to run."

                    />
                ),
                () => (isSkeleton
                    ? <CommandSkeleton />
                    : <MarkdownContent source={bashBlock(pairCommand)} measure="compact" />),
                ...(!isSkeleton ? [() => pairingCodeNote] : []),
                ({ isSkeleton }: SkeletonProps) => (
                    <StackH
                        gap={3}
                        at="sm"
                        principle="flex-action"
                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                        isSkeleton={isSkeleton}
                        items={[
                            () => renderVerifyButton(),
                            () => renderRotateButton(),
                        ]}
                    />
                ),
            ]}
        />
    )

    const engineLabel = engineName ?? "engine"
    const osTabsRow: ReactNode = isSkeleton ? (
        <OsTabsSkeleton />
    ) : (
        <div>
            <TabsExtended
                variant="secondary"
                size="sm"
                selectedKey={os}
                onSelectionChange={(key) => setOs(key as PlaygroundSetupOs)}

            >
                <Tabs.ListContainer>
                    <Tabs.List aria-label="Choose operating system">
                        {OS_ORDER.map((key) => (
                            <Tabs.Tab key={key} id={key}>
                                <span>{OS_LABEL[key]}</span>
                                <Tabs.Indicator />
                            </Tabs.Tab>
                        ))}
                    </Tabs.List>
                </Tabs.ListContainer>
                {/* react-aria's useTab always computes an `aria-controls` id — this row shows no
                    panel content of its own (the guide below is a SEPARATE markdown render), so
                    these stay empty/`sr-only`, same convention as `Toolbar`/`Tabs` atom. */}
                {OS_ORDER.map((key) => (
                    <Tabs.Panel key={key} id={key} className="sr-only">{null}</Tabs.Panel>
                ))}
            </TabsExtended>
        </div>
    )

    const engineStepBody: ReactNode = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <Typography
                        size="sm"
                        color="muted"
                        isSkeleton={isSkeleton}
                        text={`${engineLabel} is where the model actually runs on your machine — once installed, Playground can handle local AI tasks.`}

                    />
                ),
                () => osTabsRow,
                () => (isSkeleton
                    ? <CommandSkeleton lines={3} />
                    : <MarkdownContent source={osGuides[os]} measure="compact" />),
                ...(!isSkeleton && engineReady && engineDetail ? [() => (
                    <Callout
                        status="success"
                        title={`${engineLabel} is ready`}
                        description={engineDetail}


                    />
                )] : []),
                ({ isSkeleton }: SkeletonProps) => <StackH gap={3} isSkeleton={isSkeleton} items={[() => renderVerifyButton()]} />,
            ]}
        />
    )

    const genModelCommand = recommendedGenModel != null ? bashBlock(`ollama pull ${recommendedGenModel}`) : null
    const embedModelCommand = bashBlock(`ollama pull ${EMBEDDING_MODEL_NAME}`)
    const modelsReady = genModelReady && embedModelReady

    const genModelSection = genModelCommand != null ? (
        <StackV
            gap={2}
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => (
                    <Typography
                        isSkeleton={isSkeleton}
                        size="xs"
                        color="muted"
                        text={`Model sinh — ${recommendedGenModel}`}

                    />
                ),
                () => <MarkdownContent source={genModelCommand} measure="compact" />,
            ]}
        />
    ) : null

    const embedModelSection = (
        <StackV
            gap={2}
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => (
                    <Typography
                        isSkeleton={isSkeleton}
                        size="xs"
                        color="muted"
                        text={`Model embedding — ${EMBEDDING_MODEL_NAME}`}

                    />
                ),
                () => <MarkdownContent source={embedModelCommand} measure="compact" />,
            ]}
        />
    )

    const modelsCommandsSection = (
        <StackV
            gap={4}
            isSkeleton={isSkeleton}
            items={[
                () => genModelSection,
                () => embedModelSection,
            ]}
        />
    )

    const modelsSkeletonCommands = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                () => <CommandSkeleton />,
                () => <CommandSkeleton />,
            ]}
        />
    )

    const modelsStepBody: ReactNode = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <Typography
                        size="sm"
                        color="muted"
                        isSkeleton={isSkeleton}
                        text="Models need to be pulled to your machine before use — the right size for your VRAM keeps things running smoothly, without freezing or running out of memory."

                    />
                ),
                () => (isSkeleton ? (
                    modelsSkeletonCommands
                ) : deviceKnown === false ? (
                    <Callout
                        status="warning"
                        title="Device configuration not detected yet"
                        description="Finish installing the engine, then press Check again — Playground will detect your VRAM and suggest the right model size."


                    />
                ) : modelsReady ? (
                    <Callout
                        status="success"
                        title="All models are ready"
                        description="Both the text-generation model and the embedding model are already downloaded on your machine."


                    />
                ) : (
                    modelsCommandsSection
                )),
                ({ isSkeleton }: SkeletonProps) => <StackH gap={3} isSkeleton={isSkeleton} items={[() => renderVerifyButton()]} />,
            ]}
        />
    )

    const agentStatus: StepStatus = agentReady ? "ready" : "pending"
    const engineStatus: StepStatus = engineReady ? "ready" : "pending"
    const modelsStatus: StepStatus = modelsReady ? "ready" : "pending"

    const steps: Array<StepEntry> = [
        { key: "pair", title: "1. Pair local agent", status: agentStatus, body: pairStepBody },
        { key: "engine", title: `2. Install ${engineLabel}`, status: engineStatus, body: engineStepBody },
    ]
    if (flavor === "ollama") {
        steps.push({ key: "models", title: "3. Pull models for your device", status: modelsStatus, body: modelsStepBody })
    }

    // Depends on the loop variable, so it cannot be hoisted to a const above the
    // return — a small named helper instead, in the style this file already uses.
    const renderStep = (step: StepEntry) => (
        <SurfaceCard
            key={step.key}
            label={step.title}
            action={() => (
                <EnumChip
                    value={step.status}
                    map={STEP_STATUS_MAP}
                    isSkeleton={isSkeleton}

                />
            )}
            isSkeleton={isSkeleton}


            body={() => step.body}
        />
    )

    const rotateConfirm = onRefreshPairingCode ? (
        <ConfirmDialog
            isOpen={isRotateConfirmOpen}
            onOpenChange={setRotateConfirmOpen}
            title="Get a new code while the agent is connected?"
            description="The agent is currently using the old code to hold its connection — getting a new code will break the current session until you paste the new code into the agent."
            confirmLabel="Get new code"
            cancelLabel="Not now"
            onConfirm={onConfirmRotate}
            isConfirming={isRefreshingPairingCode}

        />
    ) : null

    return (
        <StackV
            identity={{ tier: "block", component: "PlaygroundSetupSteps" }}
            gap={4}
            isSkeleton={isSkeleton}
            items={[
                ...steps.map((step) => () => renderStep(step)),
                () => rotateConfirm,
            ]}
        />
    )
}

export { PlaygroundSetupSteps }

import React from "react"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { CheckCircleIcon } from "@phosphor-icons/react"
import { MarkdownContent } from "@/components/composites/viewers/MarkdownContent"
import { EmptyState } from "@/components/composites/feedback/EmptyState"
import { Typography } from "@/components/atoms/text/Typography"
import { Button } from "@/components/atoms/buttons/Button"
import { Spinner } from "@/components/atoms/display/Spinner"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * `PlaygroundStepGuide` — the left pane of a playground run: read the current step,
 * run its command on your own machine, ask the agent to verify it. Three shapes:
 *   • `Step` — a step with a command fence; `verifyState` moves through its four
 *     data states inside the one action slot.
 *   • `StepNoCommand` — a read-only explainer step with `commandHint` missing, so the
 *     second `MarkdownContent` node is gone.
 *   • `Complete` — `step` is `undefined`, so the pane is replaced end to end by `EmptyState`.
 */

/** Fenced-code wrapper so the command reuses `MarkdownContent`'s own code-block skin. */
const commandFence = (command: string) => "```bash\n" + command + "\n```"

/** One step's authored content. */
export interface PlaygroundStep {
    /** Step heading, e.g. "Step 2 · Build image". */
    title: string
    /** Instructions body, markdown — what to do and why. */
    body: string
    /** The exact shell command to run. Omitted → a read-only explainer step with no command fence. */
    commandHint?: string
}

/** Where the verify action stands right now. */
export type PlaygroundStepVerifyState =
    | "waitingForConnection"
    | "ready"
    | "pending"
    | "missed"

/** Props for {@link PlaygroundStepGuide}. */
export interface PlaygroundStepGuideProps {
    /** The step being read. `undefined` → every step is done, render the completion leaf. */
    step?: PlaygroundStep
    /** State of the verify action for the current step. Ignored once `step` is `undefined`. */
    verifyState: PlaygroundStepVerifyState
    /** Fired when the learner presses `Verify` (from `ready` or to retry from `missed`). */
    onVerify: () => void
    /** Fired from the completion leaf's back-to-hub action. */
    onLeaveComplete: () => void
    /**
     * `true` → shimmer the step-reading shape, DISTINCT from `step` being
     * `undefined` (which means "run complete", a real business state, not a
     * loading one — see `step`'s own doc).
     */
    isSkeleton?: boolean
}

/**
 * The step-reading pane. See the file header for the leaf/state split and why
 * the pending state draws its own spinner instead of `Button`'s.
 *
 * @param props - {@link PlaygroundStepGuideProps}
 */
const PlaygroundStepGuide = ({
    step,
    verifyState,
    onVerify,
    onLeaveComplete,
    isSkeleton = false,
}: PlaygroundStepGuideProps) => {
    if (isSkeleton) {
        const loadingStep = (
            <>
                <Skeleton className="h-6 w-48 rounded" />
                <StackV
                    gap={2}
                    isSkeleton={isSkeleton}
                    items={[
                        () => <Skeleton className="h-4 w-full rounded" />,
                        () => <Skeleton className="h-4 w-2/3 rounded" />,
                    ]}
                />
                <Skeleton className="h-9 w-36 rounded-xl" />
            </>
        )
        return (
            <div>
                <StackV gap={6} isSkeleton={isSkeleton} items={[() => loadingStep]} />
            </div>
        )
    }
    if (step == null) {
        return (
            <div>
                <EmptyState
                    icon={CheckCircleIcon}
                    tone="neutral"
                    title="All steps completed!"
                    description="You've made it through this playground path. Head back to the hub to pick the next exercise."
                    body={() => (
                        <Button
                            label="Back to Playground hub"
                            variant="secondary"
                            onPress={onLeaveComplete}
                        />
                    )}
                />
            </div>
        )
    }

    // Manual spinner, not `Button`'s own `isPending` skin — see the file header
    // for why an open-ended remote check gets a status row instead of a parked
    // button.
    const verifyPendingStatus = (
        <StackH
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                () => <Spinner size="sm" tone="accent" />,
                () => <Typography size="sm" color="muted" text="Checking…" />,
            ]}
        />
    )

    const verifyControls = (
        <StackV
            gap={2}
            isSkeleton={isSkeleton}
            items={[
                ...(verifyState === "waitingForConnection" ? [() => (
                    <Typography
                        size="sm"
                        color="muted"
                        text="Waiting for a connection to your learning machine…"

                    />
                )] : []),
                ...(verifyState === "ready" || verifyState === "missed" ? [() => (
                    <Button
                        label="Verify this step"
                        variant="primary"
                        onPress={onVerify}

                    />
                )] : []),
                ...(verifyState === "pending" ? [() => verifyPendingStatus] : []),
                ...(verifyState === "missed" ? [() => (
                    <Typography
                        size="xs"
                        color="danger"
                        text="Didn't see the expected result yet — rerun the command and verify again."

                    />
                )] : []),
            ]}
        />
    )

    const commandSection = step.commandHint != null ? (
        <StackV
            gap={2}
            isSkeleton={isSkeleton}
            items={[
                () => <Typography size="xs" weight="medium" color="muted" text="Command to run" />,
                () => (
                    <MarkdownContent
                        source={commandFence(step.commandHint ?? "")}
                        measure="compact"

                    />
                ),
            ]}
        />
    ) : null

    const guideBody = (
        <>
            <Typography size="h4" weight="bold" text={step.title} />
            <MarkdownContent source={step.body} measure="reading" />
            {commandSection}
            {verifyControls}
        </>
    )

    return (
        <div>
            <StackV gap={6} isSkeleton={isSkeleton} items={[() => guideBody]} />
        </div>
    )
}

export { PlaygroundStepGuide }

import type { ReactNode } from "react"
import { cn } from "@heroui/react"

/**
 * BLOCK — `QaChatBubble`: the one surface every message in a Q&A
 * conversation renders inside — accent+right for the viewer's own message,
 * neutral+left for anyone else's. `rounded-2xl`, the documented chat
 * exception to the usual card `rounded-3xl`.
 */

/** Props for {@link QaChatBubble}. */
export interface QaChatBubbleProps {
    /** `"user"` → the viewer's own message (accent, tail on the right). `"assistant"` → anyone else's (neutral, tail on the left). */
    role: "user" | "assistant"
    /** Bubble content — typically a compact {@link import("@/components/composites/viewers/MarkdownContent").MarkdownContent}. */
    children: ReactNode
    /** `true` → the bubble draws a shimmer block instead of `children`. */
    isSkeleton?: boolean
}

/**
 * The one message-bubble surface a `QaQuestionThread` conversation renders,
 * tinted and tailed toward the viewer's own side or the other party's.
 *
 * @param props - {@link QaChatBubbleProps}
 */
const QaChatBubble = ({ role, children, isSkeleton = false }: QaChatBubbleProps) => (
    <div

        className={cn(
            "min-w-0 rounded-2xl px-3 py-3",
            role === "user"
                ? "rounded-tr-md bg-accent-soft text-accent-soft-foreground"
                : "rounded-tl-md bg-default text-foreground",
            isSkeleton && "h-10 w-40 animate-pulse",
        )}
    >
        {!isSkeleton ? children : null}
    </div>
)

export { QaChatBubble }

"use client"

import React from "react"
import { Chip, cn } from "@heroui/react"
import {
    ChatCircleIcon,
    PushPinIcon,
    SealCheckIcon,
} from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { getTimeAgoLabel, getTimeAgoMessage } from "@/modules/dayjs"
import { UserAvatar } from "@/components/blocks/identity/UserAvatar"
import { MarkdownContent } from "@/components/blocks/rendering/MarkdownContent"
import type { CourseQuestionNode } from "@/modules/api/graphql/queries/types/course-questions"

/** Props for {@link QaInboxRow}. */
export interface QaInboxRowProps {
    /** The question to preview. */
    question: CourseQuestionNode
    /** Open the full conversation (expands the thread inline). */
    onOpen: () => void
}

/**
 * One collapsed row in the course-Q&A social inbox: the asker (avatar + name +
 * founder badge + relative time), a two-line preview of the question, a scope tag
 * (a static "Lesson: …" / "General" tag), an answered/unanswered status badge, the reply
 * count, and a status dot for scanning the list at a glance. The WHOLE row is a
 * single press target that opens the conversation — the lesson-funnel link lives on
 * the question bubble inside the opened thread, so the collapsed row stays a clean,
 * unambiguous button (no nested interactive controls).
 *
 * Presentational: all data arrives via props; opening is delegated to `onOpen`.
 *
 * @param props - {@link QaInboxRowProps}
 */
export const QaInboxRow = ({ question, onOpen }: QaInboxRowProps) => {
    const t = useTranslations()
    const displayName = question.author.displayName || question.author.username
    const isAnswered = question.replyCount > 0

    return (
        <div
            role="button"
            tabIndex={0}
            onClick={onOpen}
            onKeyDown={(event) => {
                if (event.key === "Enter" || event.key === " ") {
                    event.preventDefault()
                    onOpen()
                }
            }}
            className="flex w-full cursor-pointer items-start gap-3 p-3 text-left outline-none transition-colors hover:bg-default focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-accent"
        >
            <UserAvatar
                size="sm"
                username={question.author.username}
                avatar={question.author.avatar}
                seed={question.author.username}
                className="shrink-0"
            />

            <div className="flex min-w-0 flex-1 flex-col gap-1">
                {/* asker + relative time */}
                <div className="flex flex-wrap items-center gap-2 text-xs text-muted">
                    {question.isPinned ? (
                        <PushPinIcon
                            weight="fill"
                            aria-label={t("courseQa.pinned")}
                            className="size-3.5 shrink-0 text-accent-soft-foreground"
                        />
                    ) : null}
                    <span className="font-medium text-foreground">{displayName}</span>
                    {question.isFounderAuthor ? (
                        <SealCheckIcon
                            weight="fill"
                            aria-label={t("courseQa.founderBadge")}
                            className="size-3.5 shrink-0 text-accent-soft-foreground"
                        />
                    ) : null}
                    <span>· {getTimeAgoLabel(getTimeAgoMessage(question.createdAt), t)}</span>
                </div>

                {/* two-line preview */}
                <MarkdownContent
                    markdown={question.body}
                    density="compact"
                    flow="embedded"
                    previewLines={2}
                />

                {/* scope tag + status + reply count */}
                <div className="flex flex-wrap items-center gap-2">
                    <Chip size="sm" variant="soft" className="bg-default text-muted">
                        {question.contentId
                            ? t("courseQa.lessonTag", { title: question.contentTitle ?? "" })
                            : t("courseQa.generalTag")}
                    </Chip>

                    {isAnswered ? (
                        <Chip size="sm" variant="soft" color="success" className="gap-1">
                            {question.answeredByFounder ? (
                                <SealCheckIcon weight="fill" aria-hidden className="size-3.5 shrink-0" />
                            ) : null}
                            {question.answeredByFounder
                                ? t("courseQa.answeredByFounder")
                                : t("courseQa.statusAnswered")}
                        </Chip>
                    ) : (
                        <Chip size="sm" variant="soft" className="bg-default text-muted">
                            {t("courseQa.statusUnanswered")}
                        </Chip>
                    )}

                    {isAnswered ? (
                        <span className="inline-flex items-center gap-1 text-xs text-muted">
                            <ChatCircleIcon aria-hidden className="size-4" />
                            {t("courseQa.replyCount", { count: question.replyCount })}
                        </span>
                    ) : null}
                </div>
            </div>

            {/* status dot — scan the list without opening each thread */}
            <span
                aria-hidden
                className={cn(
                    "mt-2 size-2 shrink-0 rounded-full",
                    isAnswered ? "bg-success" : "bg-warning",
                )}
            />
        </div>
    )
}

"use client"

import React, { useState } from "react"
import { Chip, Link, Spinner, cn } from "@heroui/react"
import { CheckCircleIcon, SealCheckIcon } from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { getTimeAgoLabel, getTimeAgoMessage } from "@/modules/dayjs"
import { ChatBubble } from "@/components/blocks/feed/ChatBubble"
import { MarkdownContent } from "@/components/blocks/rendering/MarkdownContent"
import { ReactionBar } from "@/components/blocks/community/Discussion/ReactionBar"
import { CommentComposer } from "@/components/blocks/community/Discussion/CommentComposer"
import type { ReactionType, CommentNode } from "@/modules/api/graphql/queries/types/discussion"
import type { CommentItemCallbacks } from "@/components/blocks/community/Discussion/CommentItem"
/** Props for {@link QaMessageBubble}. */
export interface QaMessageBubbleProps extends CommentItemCallbacks {
    /** The answer/reply to render. */
    comment: CommentNode
    /** Current viewer id — drives own-bubble alignment + owner edit/delete; null when unknown. */
    currentUserId: string | null
    /** Current viewer identity for the reply composer avatar; null when signed out. */
    currentUser: { username: string, avatar?: string } | null
    /** Loaded reply subtrees, keyed by parent comment id (lazily populated by the container). */
    repliesByParent: Record<string, Array<CommentNode>>
    /**
     * When this bubble is a flattened reply-to-reply, the display name of the author it
     * answers — shown as a small `↳ replying to {name}` tag so threading survives without indent.
     */
    replyToName?: string | null
    /**
     * Whether the viewer may accept this answer — true only for a DIRECT answer when the
     * viewer is the asker. Nested replies are never acceptable, so they leave this off.
     */
    canAccept?: boolean
    /** Accept (or clear) this answer as the accepted one. */
    onAcceptAnswer?: (commentId: string, accepted: boolean) => void
}

/**
 * One answer (or nested reply) in a course-Q&A conversation, rendered as a chat
 * bubble: the viewer's own messages align right on an accent tint, everyone else
 * (peers + founder) aligns left on the surface tint — reusing the canonical
 * {@link ChatBubble}. Identity (name · founder badge · relative time · edited) sits
 * in a header line above the bubble rather than inside it, since {@link ChatBubble}
 * is a plain two-role primitive; the founder is marked in that header, not by
 * recolouring the bubble.
 *
 * Behaviour mirrors the per-lesson {@link import("@/components/blocks/community/Discussion/CommentItem").CommentItem}
 * — 6-emotion {@link ReactionBar}, reply/edit/delete, and lazily-loaded nested replies —
 * so an answer keeps every interaction it had as a forum row. Nested replies are
 * FLATTENED (rendered as sibling bubbles carrying a `↳ replying to {name}` tag) instead of
 * indented, so deep threads never squeeze the bubbles narrower.
 *
 * @param props - {@link QaMessageBubbleProps}
 */
export const QaMessageBubble = ({
    comment,
    currentUserId,
    currentUser,
    repliesByParent,
    replyToName,
    canAccept = false,
    onAcceptAnswer,
    onReply,
    onEdit,
    onDelete,
    onReactComment,
    onLoadReplies}: QaMessageBubbleProps) => {
    const t = useTranslations()
    // transient per-bubble UI state (mirrors CommentItem)
    const [replying, setReplying] = useState(false)
    const [editing, setEditing] = useState(false)
    const [expanded, setExpanded] = useState(false)

    const isMine = currentUserId !== null && currentUserId === comment.author.id
    const isOwner = isMine
    // the container sets the key (even to an empty array) once a load resolves, so
    // its presence — not a local flag — tells us the subtree finished loading
    const repliesLoaded = comment.id in repliesByParent
    const replies = repliesByParent[comment.id] ?? []
    const displayName = isMine ? t("courseQa.you") : comment.author.username

    // expand/collapse the reply subtree, loading it on first expand
    const toggleReplies = () => {
        const next = !expanded
        setExpanded(next)
        if (next && !repliesLoaded) {
            onLoadReplies(comment.id)
        }
    }

    return (
        <div className={cn("flex w-full", isMine ? "justify-end" : "justify-start")}>
            <div className={cn("flex min-w-0 max-w-[92%] flex-col gap-1", isMine && "items-end")}>
                {/* reply-to tag (flattened threading) */}
                {replyToName ? (
                    <span className="rounded-lg bg-accent-soft px-2 py-1 text-xs text-accent-soft-foreground">
                        {t("courseQa.replyingTo", { name: replyToName })}
                    </span>
                ) : null}

                {/* accepted-answer badge — this reply is the chosen answer */}
                {comment.isAcceptedAnswer ? (
                    <Chip size="sm" variant="soft" color="success" className="gap-1">
                        <CheckCircleIcon weight="fill" aria-hidden className="size-3.5 shrink-0" />
                        {t("courseQa.acceptedAnswer")}
                    </Chip>
                ) : null}

                {/* identity header: name (+ founder) + relative time + edited flag */}
                <div className="flex flex-wrap items-center gap-2 px-1 text-xs text-muted">
                    <span className="font-medium text-foreground">{displayName}</span>
                    {comment.isFounderAuthor ? (
                        <span className="inline-flex items-center gap-1 text-accent-soft-foreground">
                            <SealCheckIcon weight="fill" aria-hidden className="size-3.5 shrink-0" />
                            {t("courseQa.founderBadge")}
                        </span>
                    ) : null}
                    <span>{getTimeAgoLabel(getTimeAgoMessage(comment.createdAt), t)}</span>
                    {comment.editedAt ? <span>{t("discussion.edited")}</span> : null}
                </div>

                {/* body: bubble, edit form, or deleted placeholder */}
                {comment.isDeleted ? (
                    <ChatBubble role={isMine ? "user" : "assistant"}>
                        <span className="text-sm italic text-muted">{t("discussion.deletedPlaceholder")}</span>
                    </ChatBubble>
                ) : editing ? (
                    <CommentComposer
                        initialValue={comment.body}
                        submitLabel={t("common.save")}
                        onCancel={() => setEditing(false)}
                        onSubmit={(body) => {
                            onEdit(comment.id, body)
                            setEditing(false)
                        }}
                    />
                ) : (
                    <ChatBubble role={isMine ? "user" : "assistant"}>
                        <MarkdownContent markdown={comment.body} density="compact" flow="embedded" />
                    </ChatBubble>
                )}

                {/* action row: reactions + reply + owner edit/delete */}
                {!comment.isDeleted && !editing ? (
                    <div className={cn("flex flex-wrap items-center gap-3 px-1", isMine && "flex-row-reverse")}>
                        <ReactionBar
                            summary={comment.reactions}
                            onReact={(type: ReactionType | null) => onReactComment(comment.id, type)}
                        />
                        <Link
                            className="cursor-pointer text-xs font-medium text-muted hover:text-foreground"
                            onPress={() => setReplying((prev) => !prev)}
                        >
                            {t("discussion.reply")}
                        </Link>
                        {isOwner ? (
                            <>
                                <Link
                                    className="cursor-pointer text-xs font-medium text-muted hover:text-foreground"
                                    onPress={() => setEditing(true)}
                                >
                                    {t("common.edit")}
                                </Link>
                                <Link
                                    className="cursor-pointer text-xs font-medium text-muted hover:text-danger-soft-foreground"
                                    onPress={() => onDelete(comment.id)}
                                >
                                    {t("common.delete")}
                                </Link>
                            </>
                        ) : null}
                        {/* asker-only: accept this direct answer as THE answer (toggle) */}
                        {canAccept ? (
                            <Link
                                className="cursor-pointer text-xs font-medium text-success-soft-foreground hover:underline underline-offset-4"
                                onPress={() => onAcceptAnswer?.(comment.id, !comment.isAcceptedAnswer)}
                            >
                                {comment.isAcceptedAnswer ? t("courseQa.unaccept") : t("courseQa.accept")}
                            </Link>
                        ) : null}
                    </div>
                ) : null}

                {/* reply composer */}
                {replying ? (
                    <CommentComposer
                        placeholder={t("discussion.replyPlaceholder")}
                        submitLabel={t("discussion.reply")}
                        currentUser={currentUser}
                        onCancel={() => setReplying(false)}
                        onSubmit={(body) => {
                            onReply(comment.id, body)
                            setReplying(false)
                            // surface the new reply immediately by expanding + reloading the subtree
                            setExpanded(true)
                            onLoadReplies(comment.id)
                        }}
                    />
                ) : null}

                {/* replies toggle */}
                {comment.replyCount > 0 ? (
                    <Link
                        className="cursor-pointer self-start px-1 text-xs font-medium text-accent-soft-foreground hover:underline underline-offset-4 decoration-[var(--separator-tertiary)]"
                        onPress={toggleReplies}
                    >
                        {expanded
                            ? t("discussion.hideReplies")
                            : t("discussion.viewReplies", { count: comment.replyCount })}
                    </Link>
                ) : null}

                {/* flattened reply subtree — each reply is a sibling bubble carrying a reply-to tag */}
                {expanded ? (
                    !repliesLoaded ? (
                        <div className="flex w-full justify-center py-1">
                            <Spinner size="sm" />
                        </div>
                    ) : replies.length > 0 ? (
                        <div className="flex w-full flex-col gap-3">
                            {replies.map((reply) => (
                                <QaMessageBubble
                                    key={reply.id}
                                    comment={reply}
                                    currentUserId={currentUserId}
                                    currentUser={currentUser}
                                    repliesByParent={repliesByParent}
                                    replyToName={displayName}
                                    onReply={onReply}
                                    onEdit={onEdit}
                                    onDelete={onDelete}
                                    onReactComment={onReactComment}
                                    onLoadReplies={onLoadReplies}
                                />
                            ))}
                        </div>
                    ) : null
                ) : null}
            </div>
        </div>
    )
}

"use client"

import React, { useCallback, useMemo, useState } from "react"
import { Chip, Link, Spinner, cn } from "@heroui/react"
import { PushPinIcon, SealCheckIcon } from "@phosphor-icons/react"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { getTimeAgoLabel, getTimeAgoMessage } from "@/modules/dayjs"
import type { CourseQuestionNode } from "@/modules/api/graphql/queries/types/course-questions"
import { ChatBubble } from "@/components/blocks/feed/ChatBubble"
import { Composer } from "@/components/blocks/feed/Composer"
import { MarkdownContent } from "@/components/blocks/rendering/MarkdownContent"
import { ReactionBar } from "@/components/blocks/community/Discussion/ReactionBar"
import { QaInboxRow } from "../QaInboxRow"
import { QaConversationHeader, type QaConversationHeaderPerson } from "../QaConversationHeader"
import { QaMessageBubble } from "../QaMessageBubble"
import { useQuestionAnswers } from "@/hooks/swr/api/graphql/queries/useQuestionAnswersSwr"
import { useMutateSetFollowSwr } from "@/hooks/swr/api/graphql/mutations/useMutateSetFollowSwr"
import { pathConfig } from "@/resources/path"
import { useAppSelector } from "@/redux/hooks"

/** Props for {@link QaQuestionThread}. */
export interface QaQuestionThreadProps {
    /** The question to render. */
    question: CourseQuestionNode
    /** Current viewer id (drives own-bubble alignment + owner-only actions); null when unknown. */
    currentUserId: string | null
    /** Current viewer identity for the answer composer avatar; null when signed out. */
    currentUser: { username: string, avatar?: string } | null
    /** Called after an answer is posted/edited/deleted — bumps the parent roll-up's aggregates. */
    onAnswered?: () => void
}

/**
 * One course-Q&A conversation. Collapsed, it is a social {@link QaInboxRow} (asker,
 * preview, scope tag, answered/unanswered status, reply count, status dot). Pressing
 * it expands the FULL conversation inline: a {@link QaConversationHeader} (asker +
 * who-joined-in avatar group), the question itself rendered as the first chat bubble
 * (with its lesson-funnel tag + status), then every answer as a {@link QaMessageBubble}
 * — the viewer's own messages align right, peers + founder align left — and a
 * bottom {@link Composer} to add an answer. This is the ONLY place to answer a
 * course-general question (it has no lesson page of its own).
 *
 * Owns the expand state + the answer thread's data/persistence (via
 * {@link useQuestionAnswers}, gated on `expanded` so nothing fetches until opened).
 *
 * @param props - {@link QaQuestionThreadProps}
 */
export const QaQuestionThread = ({ question, currentUserId, currentUser, onAnswered}: QaQuestionThreadProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    // display id (slug) builds the lesson route the question's tag links to
    const displayId = useAppSelector((state) => state.course.displayId)

    // answer-thread toggle; the answers are gated on `expanded` inside the facade hook,
    // so opening the conversation the first time is what triggers the fetch
    const [expanded, setExpanded] = useState(false)
    // draft + in-flight guard for the bottom "add an answer" composer
    const [answerDraft, setAnswerDraft] = useState("")
    const [isPostingAnswer, setIsPostingAnswer] = useState(false)

    const {
        answers,
        isLoadingAnswers,
        answerRepliesByParent,
        onReply,
        onEdit,
        onDelete,
        onReactComment,
        onReactQuestion,
        onAcceptAnswer,
        onLoadReplies,
    } = useQuestionAnswers(question.id, expanded, onAnswered)

    const isMineQuestion = currentUserId !== null && currentUserId === question.author.id
    const questionName = isMineQuestion ? t("courseQa.you") : (question.author.displayName || question.author.username)

    // follow the asker — local optimistic state seeded from the server flag; only the
    // viewer's own toggle mutates it, so no re-sync on list refetch is needed
    const { trigger: triggerSetFollow, isMutating: isFollowPending } = useMutateSetFollowSwr()
    const [isFollowingAsker, setIsFollowingAsker] = useState(question.author.isFollowedByMe)
    // never follow yourself; hide the control when signed out or on your own question
    const canFollowAsker = currentUserId !== null && currentUserId !== question.author.id
    const onToggleFollow = useCallback(async () => {
        const next = !isFollowingAsker
        const result = await triggerSetFollow({ userId: question.author.id, follow: next })
        // commit only on a confirmed success (mirrors the league board's follow flow)
        if (result?.data?.setFollow?.success) {
            setIsFollowingAsker(next)
        }
    }, [isFollowingAsker, triggerSetFollow, question.author.id])

    // distinct answerers → the "who joined in" avatar group in the header
    const participants = useMemo<Array<QaConversationHeaderPerson>>(() => {
        const seen = new Set<string>()
        const list: Array<QaConversationHeaderPerson> = []
        for (const answer of answers) {
            if (!seen.has(answer.author.id)) {
                seen.add(answer.author.id)
                list.push({
                    id: answer.author.id,
                    displayName: answer.author.username,
                    avatarUrl: answer.author.avatar ?? undefined,
                })
            }
        }
        return list
    }, [answers])

    /**
     * Route to the source lesson — the funnel back into the course content. A no-op
     * for a course-general question (no `contentId`/`moduleId` to route to).
     */
    const goToLesson = useCallback(() => {
        if (!displayId || !question.contentId || !question.moduleId) {
            return
        }
        router.push(
            pathConfig()
                .locale(locale)
                .course(displayId)
                .learn()
                .module(question.moduleId)
                .content(question.contentId)
                .build(),
        )
    }, [displayId, locale, router, question.contentId, question.moduleId])

    /** Post a new top-level answer via the bottom composer, then clear the draft. */
    const submitAnswer = useCallback(async () => {
        const body = answerDraft.trim()
        if (!body) {
            return
        }
        setIsPostingAnswer(true)
        try {
            await onReply(question.id, body)
            setAnswerDraft("")
        } finally {
            setIsPostingAnswer(false)
        }
    }, [answerDraft, onReply, question.id])

    // collapsed — a flush social inbox row inside the parent's SurfaceListCard
    if (!expanded) {
        return (
            <QaInboxRow
                question={question}
                onOpen={() => setExpanded(true)}
            />
        )
    }

    // expanded — the full conversation, rendered inline in place of the row
    return (
        <div className={"flex flex-col gap-4 p-3"}>
            <QaConversationHeader
                asker={{
                    id: question.author.id,
                    displayName: question.author.displayName || question.author.username,
                    avatarUrl: question.author.avatar ?? undefined,
                }}
                isFounderAsker={question.isFounderAuthor}
                participants={participants}
                replyCount={question.replyCount}
                onCollapse={() => setExpanded(false)}
                canFollow={canFollowAsker}
                isFollowing={isFollowingAsker}
                onToggleFollow={() => { void onToggleFollow() }}
                isFollowPending={isFollowPending}
            />

            <div className="flex flex-col gap-4">
                {/* the question itself, as the first bubble of the conversation */}
                <div className={cn("flex w-full", isMineQuestion ? "justify-end" : "justify-start")}>
                    <div className={cn("flex min-w-0 max-w-[92%] flex-col gap-1", isMineQuestion && "items-end")}>
                        <div className="flex flex-wrap items-center gap-2 px-1 text-xs text-muted">
                            <span className="font-medium text-foreground">{questionName}</span>
                            {question.isFounderAuthor ? (
                                <span className="inline-flex items-center gap-1 text-accent-soft-foreground">
                                    <SealCheckIcon weight="fill" aria-hidden className="size-3.5 shrink-0" />
                                    {t("courseQa.founderBadge")}
                                </span>
                            ) : null}
                            {question.isPinned ? (
                                <span className="inline-flex items-center gap-1 text-accent-soft-foreground">
                                    <PushPinIcon weight="fill" aria-hidden className="size-3.5 shrink-0" />
                                    {t("courseQa.pinned")}
                                </span>
                            ) : null}
                            <span>{getTimeAgoLabel(getTimeAgoMessage(question.createdAt), t)}</span>
                        </div>

                        <ChatBubble role={isMineQuestion ? "user" : "assistant"}>
                            <MarkdownContent markdown={question.body} density="compact" flow="embedded" />
                        </ChatBubble>

                        {/* lesson-funnel tag (course content) + answered/unanswered status */}
                        <div className={cn("flex flex-wrap items-center gap-2 px-1", isMineQuestion && "flex-row-reverse")}>
                            {question.contentId ? (
                                <Link onPress={goToLesson} className="cursor-pointer no-underline">
                                    <Chip
                                        size="sm"
                                        variant="soft"
                                        className="bg-default text-muted transition-colors hover:text-foreground"
                                    >
                                        {t("courseQa.lessonTag", { title: question.contentTitle ?? "" })}
                                    </Chip>
                                </Link>
                            ) : (
                                <Chip size="sm" variant="soft" className="bg-default text-muted">
                                    {t("courseQa.generalTag")}
                                </Chip>
                            )}
                            {question.replyCount > 0 ? (
                                <Chip size="sm" variant="soft" color="success" className="gap-1">
                                    {question.answeredByFounder ? (
                                        <SealCheckIcon weight="fill" aria-hidden className="size-3.5 shrink-0" />
                                    ) : null}
                                    {question.answeredByFounder
                                        ? t("courseQa.answeredByFounder")
                                        : t("courseQa.statusAnswered")}
                                </Chip>
                            ) : (
                                <Chip size="sm" variant="soft" className="bg-default text-muted">
                                    {t("courseQa.statusUnanswered")}
                                </Chip>
                            )}
                            {/* react to the question itself (6-emotion) — the question is a comment */}
                            <ReactionBar
                                summary={question.reactions}
                                onReact={(type) => { void onReactQuestion(type) }}
                            />
                        </div>
                    </div>
                </div>

                {/* answers — each a chat bubble; own messages right, peers + founder left */}
                {isLoadingAnswers && answers.length === 0 ? (
                    <div className="flex justify-center py-2">
                        <Spinner size="sm" />
                    </div>
                ) : (
                    answers.map((answer) => (
                        <QaMessageBubble
                            key={answer.id}
                            comment={answer}
                            currentUserId={currentUserId}
                            currentUser={currentUser}
                            repliesByParent={answerRepliesByParent}
                            // only the asker may accept, and only a DIRECT answer (this map)
                            canAccept={isMineQuestion}
                            onAcceptAnswer={(commentId, accepted) => { void onAcceptAnswer(commentId, accepted) }}
                            onReply={(parentId, body) => { void onReply(parentId, body) }}
                            onEdit={(commentId, body) => { void onEdit(commentId, body) }}
                            onDelete={(commentId) => { void onDelete(commentId) }}
                            onReactComment={(commentId, type) => { void onReactComment(commentId, type) }}
                            onLoadReplies={onLoadReplies}
                        />
                    ))
                )}
            </div>

            {/* bottom composer — add an answer as a chat message */}
            <Composer
                value={answerDraft}
                onChange={setAnswerDraft}
                onSubmit={() => { void submitAnswer() }}
                isSubmitting={isPostingAnswer}
                avatarSrc={currentUser?.avatar}
                placeholder={t("discussion.replyPlaceholder")}
                submitLabel={t("discussion.reply")}
            />
        </div>
    )
}

import { HeartIcon } from "@phosphor-icons/react"
import { cn } from "@heroui/react"
import { Typography } from "@/components/atoms/text/Typography"

/**
 * BLOCK — `QaReactionBar`: the like-and-count control under a message
 * bubble. Renders one heart toggle rather than the full six-reaction picker
 * — see the component's own file header for why.
 */

/** Mirrors `QaQuestionThread`'s own `QaReactionType` (kept local — see that file's ASSUMED CONTRACTS note). */
export type QaReactionType = "like" | "love" | "haha" | "wow" | "sad" | "angry"

/** Props for {@link QaReactionBar}. */
export interface QaReactionBarProps {
    /** Total reactions on the message. */
    count: number
    /** The viewer's own reaction, or `null` if they haven't reacted. */
    myReaction: QaReactionType | null
    /** Fires with the new reaction (`"like"` to react, `null` to clear). */
    onReact: (type: QaReactionType | null) => void
    /** `true` → renders a shimmer mirror instead of the live control. */
    isSkeleton?: boolean
}

/**
 * One like-and-count toggle under a message bubble.
 *
 * @param props - {@link QaReactionBarProps}
 */
const QaReactionBar = ({
    count,
    myReaction,
    onReact,
    isSkeleton = false,
}: QaReactionBarProps) => {
    const hasReacted = myReaction != null

    if (isSkeleton) {
        return (
            <span

                className="inline-block h-5 w-10 animate-pulse rounded-full bg-default"
            />
        )
    }

    return (
        <button
            type="button"

            onClick={() => onReact(hasReacted ? null : "like")}
            aria-pressed={hasReacted}
            aria-label={hasReacted ? "Unlike" : "Like"}
            className={cn(
                // inset-exception: pill geometry, the same px-2 py-1 HeroUI ships in chip.css
                "inline-flex items-center gap-1 rounded-full px-2 py-1 transition-colors hover:bg-default",
                hasReacted && "text-danger-soft-foreground",
            )}
        >
            <HeartIcon weight={hasReacted ? "fill" : "regular"} aria-hidden focusable="false" className="size-3.5 shrink-0" />
            {count > 0 ? (
                <Typography size="xs" text={String(count)} />
            ) : null}
        </button>
    )
}

export { QaReactionBar }

import React from "react"
import {
    Checkbox as HeroCheckbox,
    CheckboxGroup as HeroCheckboxGroup,
    Radio as HeroRadio,
    RadioGroup as HeroRadioGroup,
} from "@heroui/react"
import { CheckCircleIcon, XCircleIcon } from "@phosphor-icons/react"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"
import { Button } from "@/components/atoms/buttons/Button"
import { Typography } from "@/components/atoms/text/Typography"
import { StatusChip } from "@/components/blocks/chips/StatusChip"
import { SectionCard } from "@/components/blocks/cards/SectionCard"
import { StackV } from "@/components/frames/Stack"

/**
 * How many options the learner may pick at once:
 * - `"single"` → radio semantics (exactly one), rendered with HeroUI `RadioGroup`.
 * - `"multiple"` → checkbox semantics (zero or more), rendered with HeroUI `CheckboxGroup`.
 */
export type QuizSelectionMode = "single" | "multiple"

/**
 * One selectable answer of a {@link QuizCard}.
 */
export interface QuizOption {
    /** Stable identity of the option — the value surfaced through `selectedIds` / `onSelectionChange`. */
    id: string
    /** The answer body shown on the row (plain text or a richer `ReactNode`). */
    label: React.ReactNode
    /**
     * Whether this option is a correct answer. Consumed ONLY after `isSubmitted`
     * to paint the per-option success / danger states — ignored before submit so
     * the answer key never leaks early.
     */
    isCorrect?: boolean
}

/**
 * Props for the {@link QuizCard} block.
 *
 * A multiple-choice question card for graded assessments — a question, a list of
 * selectable option rows, an optional check action, and a post-answer explanation.
 * Tier-3 presentational: selection is fully CONTROLLED by the caller
 * (`selectedIds` + `onSelectionChange`) and every callback may be a no-op.
 *
 * Does not take `className` (BLOCK-4) — no live call site forwards one today; a
 * caller that needs a specific placement composes a frame (`StackV`/`StackH`/…)
 * around the card, or passes `classNames` for POSITION only (closed union, same
 * vocabulary `SectionCard`/`MetricCard` already take).
 */
export interface QuizCardProps {
    /**
     * The question prompt (plain text or a richer `ReactNode` — e.g. a code
     * snippet). Rendered prominently above the options.
     */
    question: React.ReactNode
    /**
     * The selectable answers, in display order. Each carries an `id`, a `label`,
     * and an optional `isCorrect` flag used only once `isSubmitted` is `true`.
     */
    options: QuizOption[]
    /**
     * Whether the learner may pick one (`"single"`, radio) or several
     * (`"multiple"`, checkbox) options. Defaults to `"single"`.
     */
    selectionMode?: QuizSelectionMode
    /**
     * The currently selected option ids (CONTROLLED). For `"single"` mode this
     * holds at most one id; for `"multiple"` it holds every picked id.
     */
    selectedIds: string[]
    /**
     * Fired when the selection changes, with the NEXT full list of selected ids.
     * A no-op is valid (e.g. a static, read-only preview).
     */
    onSelectionChange: (ids: string[]) => void
    /**
     * Whether the answer has been submitted. When `true` the options lock
     * (read-only) and each row reveals its correct / incorrect state; the submit
     * action and the pre-answer affordances disappear. Defaults to `false`.
     */
    isSubmitted?: boolean
    /**
     * Fired when the learner presses the submit/check button. Omit it (together
     * with driving `isSubmitted` yourself) to hide the built-in action entirely.
     */
    onSubmit?: () => void
    /**
     * Label for the submit/check button. Defaults to `"Check answer"`. Ignored
     * when `onSubmit` is not provided or once `isSubmitted` is `true`.
     */
    submitLabel?: React.ReactNode
    /**
     * Optional explanation revealed AFTER submit (plain text or a richer
     * `ReactNode`). Shown only while `isSubmitted` is `true`.
     */
    explanation?: React.ReactNode
    /**
     * Optional 1-based position of the question within its quiz. When set, a
     * "Question {n}" chip is shown above the question.
     */
    questionIndex?: number
    /**
     * Where this card sits inside its parent. Appearance is not passable — it
     * is already a prop.
     */
    classNames?: Array<AllowedClassName>
}

/** The mutually-exclusive visual state a single option row can be in. */
type OptionVisualState =
    | "default"
    | "selected"
    | "correct"
    | "incorrect"
    | "correctUnselected"

/**
 * Per-state row classes. Tokens only — correct uses `bg-success-soft` /
 * `text-success-soft-foreground`, incorrect uses the danger-soft pairing, and
 * `correctUnselected` is a subtle success OUTLINE (no soft fill) so a missed
 * correct answer reads as a hint, not an achievement.
 */
const ROW_CLASSES: Record<OptionVisualState, string> = {
    default: "border border-default bg-surface",
    selected: "border border-accent bg-accent-soft text-accent-soft-foreground",
    correct: "border border-success-soft-foreground bg-success-soft text-success-soft-foreground",
    incorrect: "border border-danger-soft-foreground bg-danger-soft text-danger-soft-foreground",
    correctUnselected: "border border-success-soft-foreground bg-surface text-success-soft-foreground",
}

/**
 * Resolves the visual state of one option from the current selection + submit
 * status. Before submit only default / selected are possible (the answer key
 * stays hidden); after submit the success / danger states are revealed.
 */
const resolveOptionState = (
    option: QuizOption,
    isSelected: boolean,
    isSubmitted: boolean,
): OptionVisualState => {
    if (!isSubmitted) {
        return isSelected ? "selected" : "default"
    }
    if (option.isCorrect) {
        return isSelected ? "correct" : "correctUnselected"
    }
    return isSelected ? "incorrect" : "default"
}

/**
 * The trailing result glyph for a post-submit row: a success check on correct
 * answers, a danger cross on a wrongly-picked answer, nothing otherwise.
 */
const OptionResultIcon = ({ state }: { state: OptionVisualState }) => {
    if (state === "correct" || state === "correctUnselected") {
        return (
            <CheckCircleIcon
                aria-hidden
                focusable="false"
                weight="fill"
                className="size-5 shrink-0 text-success-soft-foreground"
            />
        )
    }
    if (state === "incorrect") {
        return (
            <XCircleIcon
                aria-hidden
                focusable="false"
                weight="fill"
                className="size-5 shrink-0 text-danger-soft-foreground"
            />
        )
    }
    return null
}

/** Shared row shell class for every option (spacing + rounded frame + transition). */
const ROW_BASE = "rounded-2xl px-4 py-3 transition-colors"

/** Row shell + its per-state skin. Two static strings — no `cn()` needed to join them. */
const rowClassName = (state: OptionVisualState) => `${ROW_BASE} ${ROW_CLASSES[state]}`

/**
 * QuizCard is a self-framed, multiple-choice question block built on
 * {@link SectionCard}. It stacks an optional "Question {n}" chip, the question, a set
 * of selectable option rows, an optional submit action, and a post-answer
 * explanation. `selectionMode` switches between HeroUI `RadioGroup` (single) and
 * `CheckboxGroup` (multiple) — both with proper group + option ARIA.
 *
 * Before submit, rows show only default / selected (accent) styling so the answer
 * key never leaks. Once `isSubmitted` is `true` the group turns read-only and
 * each row reveals its state: correct → success-soft + check, wrongly-picked →
 * danger-soft + cross, missed-correct → a subtle success outline.
 *
 * Tier-3 presentational: props-only, no store, no SWR, no side-effects; selection
 * is CONTROLLED by the caller and every callback may be a no-op.
 *
 * `missingVocabulary` — the option group stays on raw HeroUI `Radio` /
 * `RadioGroup` / `Checkbox` / `CheckboxGroup` rather than the design system's own
 * `ChoiceRadio` / `ChoiceCheckbox` or `ChoiceRadioGroup`
 * (`composites/form/ChoiceRadioGroup`): neither takes a `ReactNode` option label,
 * neither carries a per-option CORRECTNESS skin (selected / correct / incorrect /
 * correct-but-unselected) with a trailing result glyph, and there is no checkbox
 * equivalent of `ChoiceRadioGroup` at all. Same documented gap
 * `SurfaceCard.SelectableGroup` already carries (`composites/cards/SurfaceCard`:
 * "Calls HeroUI Radio/RadioGroup directly … known drift"). This is a MINIMAL
 * local wrapper for that gap, not a new shared component — the leaves themselves
 * are untouched. Likewise the post-submit explanation panel stays a local
 * `rounded-2xl bg-surface-secondary` surface: no atom/composite renders a
 * neutral panel without alert semantics (`blocks/feedback/Callout` forces a
 * status tint + a required title).
 *
 * @param props - {@link QuizCardProps}
 *
 * @example
 * <QuizCard>
 *   questionIndex={1}
 *   question="Which HTTP status reports a resource that doesn't exist?"
 *   options={[
 *     { id: "a", label: "200 OK" },
 *     { id: "b", label: "404 Not Found", isCorrect: true },
 *   ]}
 *   selectedIds={selectedIds}
 *   onSelectionChange={setSelectedIds}
 *   onSubmit={handleSubmit}
 * />
 * @see Story: .storybook/stories/blocks/learn/QuizCard/QuizCard.stories
 */
export const QuizCard = ({
    question,
    options,
    selectionMode = "single",
    selectedIds,
    onSelectionChange,
    isSubmitted = false,
    onSubmit,
    submitLabel = "Check answer",
    explanation,
    questionIndex,
    classNames,
}: QuizCardProps) => {
    // Option rows — RadioGroup (single) or CheckboxGroup (multiple). Locked
    // read-only after submit so the revealed state can't be edited while staying
    // visually un-dimmed (unlike isDisabled). See the file header's
    // `missingVocabulary` note for why this stays on raw HeroUI components.
    const optionsGroup = selectionMode === "single" ? (
        <HeroRadioGroup
            aria-label="Answer options"
            value={selectedIds[0] ?? ""}
            onChange={(value) => onSelectionChange(value ? [value] : [])}
            isReadOnly={isSubmitted}
            className="flex flex-col gap-2"
        >
            {options.map((option) => {
                const isSelected = selectedIds.includes(option.id)
                const state = resolveOptionState(option, isSelected, isSubmitted)
                return (
                    <HeroRadio key={option.id} value={option.id} className={rowClassName(state)}>
                        <HeroRadio.Content className="w-full">
                            <HeroRadio.Control>
                                <HeroRadio.Indicator />
                            </HeroRadio.Control>
                            <span className="min-w-0 flex-1">{option.label}</span>
                            <OptionResultIcon state={state} />
                        </HeroRadio.Content>
                    </HeroRadio>
                )
            })}
        </HeroRadioGroup>
    ) : (
        <HeroCheckboxGroup
            aria-label="Answer options"
            value={selectedIds}
            onChange={onSelectionChange}
            isReadOnly={isSubmitted}
            className="flex flex-col gap-2"
        >
            {options.map((option) => {
                const isSelected = selectedIds.includes(option.id)
                const state = resolveOptionState(option, isSelected, isSubmitted)
                return (
                    <HeroCheckbox key={option.id} value={option.id} className={rowClassName(state)}>
                        <HeroCheckbox.Content className="w-full">
                            <HeroCheckbox.Control>
                                <HeroCheckbox.Indicator />
                            </HeroCheckbox.Control>
                            <span className="min-w-0 flex-1">{option.label}</span>
                            <OptionResultIcon state={state} />
                        </HeroCheckbox.Content>
                    </HeroCheckbox>
                )
            })}
        </HeroCheckboxGroup>
    )

    return (
        <SectionCard
            identity={{ tier: "block", component: "QuizCard" }}
            classNames={classNames}
        >
            <StackV
                gap={5}
                items={[
                    // Question header: optional index chip + the prompt
                    () => (
                        <StackV
                            gap={3}
                            items={[
                                ...(typeof questionIndex === "number"
                                    ? [() => <StatusChip tone="accent">{`Question ${questionIndex}`}</StatusChip>]
                                    : []),
                                () => <Typography size="base" weight="semibold" text={question} />,
                            ]}
                        />
                    ),
                    () => optionsGroup,
                    // Submit action — hidden once the answer is in or when no handler
                    ...(onSubmit && !isSubmitted
                        ? [() => (
                            <Button
                                label={submitLabel}
                                variant="primary"
                                size="sm"
                                onPress={onSubmit}
                                isDisabled={selectedIds.length === 0}
                                classNames={["w-fit"]}
                            />
                        )]
                        : []),
                    // Explanation — revealed only after submit
                    ...(isSubmitted && explanation
                        ? [() => (
                            <div className="rounded-2xl bg-surface-secondary">
                                <StackV
                                    gap={1}
                                    padding={{ x: 5, y: 4 }}
                                    principle="row-pad"
                                    explain="Row content inset — not cell-pad, because this pads a horizontal content row rather than a dense table cell."
                                    body={() => (
                                        <StackV
                                            gap={2}
                                            principle="title-subtitle"
                                            explain="Title over supporting line — not label-field, because neither line is a form control label."
                                            items={[
                                                () => <Typography size="sm" weight="semibold" text="Explanation" />,
                                                () => <Typography size="sm" color="muted" text={explanation} />,
                                            ]}
                                        />
                                    )}
                                />
                            </div>
                        )]
                        : []),
                ]}
            />
        </SectionCard>
    )
}

import React from "react"
import type { ReactNode } from "react"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { MarkdownContent } from "@/components/composites/viewers/MarkdownContent"
import { RatingBar, type RatingOption } from "@/components/blocks/buttons/RatingBar"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * `QuizRecapList` — the run is over: go back over what you answered and say how well
 * you actually knew each one. This learner-supplied grade is not the run's verdict —
 * a card can be marked correct yet be one the learner wants back tomorrow (the
 * `CorrectButShaky` case), which the spaced-repetition schedule needs. Already-graded
 * cards keep their rating bar — nothing locks after a tap, so a changed mind still
 * counts. Card count and which are rated are states of one shape; finishing changes
 * only the counter line.
 */

/** One answered card in the recap. */
export interface QuizRecapCard {
    /** Stable React key. */
    key: string
    /** The question, as authored markdown. */
    question: string
    /** The expected answer, as authored markdown. */
    expectedAnswer: string
    /** What the learner typed during the run. */
    givenAnswer?: string
    /** How the run judged it. */
    wasCorrect: boolean
    /** The learner's own recall grade, once they have given one. */
    rating?: number
}

interface QuizRecapListOwnProps {
    /** Recall grades offered per card. */
    ratingOptions: Array<RatingOption>
    /** Fired with the card key and the grade the learner picked. */
    onRate: (cardKey: string, grade: number) => void
    /** Accessible name for each card's rating group, localized by the caller. */
    ratingAriaLabel: string
    /** Card count to shimmer while `isSkeleton` (no real `cards` yet). Defaults to `3`. */
    skeletonCount?: number
}

/**
 * Props for {@link QuizRecapList}. `cards` is REQUIRED unless `isSkeleton`
 * (§12b) — a shimmer recap has no real cards to show yet.
 */
export type QuizRecapListProps = QuizRecapListOwnProps &
    (
        | { isSkeleton: true; cards?: Array<QuizRecapCard> }
        | { isSkeleton?: false; cards: Array<QuizRecapCard> }
    )

/**
 * One recap card's content — verdict chip, question, given/expected answers,
 * rating bar. Extracted to a helper (rather than hoisted to a const) because
 * it depends on the loop variable `card` from the `.map()` that calls it.
 */
const recapCardBody = (
    card: QuizRecapCard,
    ratingOptions: Array<RatingOption>,
    onRate: (cardKey: string, grade: number) => void,
    ratingAriaLabel: string,
): ReactNode => (
    <StackV
        gap={6}
        principle="block-boundary"
        explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
        items={[
            () => (
                <StackH
                    gap={3}
                    principle="chip-row"
                    explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                    align="center"

                    items={[
                        () => (
                            <Chip
                                tone={card.wasCorrect ? "success" : "danger"}
                                text={card.wasCorrect ? "Correct" : "Incorrect"}

                            />
                        ),
                    ]}
                />
            ),
            () => (
                <MarkdownContent
                    source={card.question}
                    measure="compact"

                />
            ),
            ...(card.givenAnswer != null ? [() => (
                <StackV
                    gap={3}

                    items={[
                        () => <Typography size="xs" color="muted" text="Your answer" />,
                        () => <Typography size="sm" text={card.givenAnswer} />,
                    ]}
                />
            )] : []),
            () => (
                <StackV
                    gap={3}

                    items={[
                        () => <Typography size="xs" color="muted" text="Expected answer" />,
                        () => (
                            <MarkdownContent
                                source={card.expectedAnswer}
                                measure="compact"

                            />
                        ),
                    ]}
                />
            ),
            // Stays put after a tap. A learner going back over a run changes
            // their mind, and removing the control would make the first tap
            // final without ever saying so.
            () => (
                <RatingBar
                    options={ratingOptions}
                    onRate={(grade) => onRate(card.key, grade)}
                    ariaLabel={ratingAriaLabel}


                />
            ),
        ]}
    />
)

/**
 * The end-of-run recap. See the file header for the full contract.
 *
 * @param props - {@link QuizRecapListProps}
 */
const QuizRecapList = ({
    cards,
    ratingOptions,
    onRate,
    ratingAriaLabel,
    isSkeleton = false,
    skeletonCount = 3,
}: QuizRecapListProps) => {
    if (isSkeleton) {
        const skeletonCardBody = (
            <>
                <Skeleton className="h-5 w-16 rounded-full" />
                <Skeleton className="h-4 w-full rounded" />
                <Skeleton className="h-4 w-2/3 rounded" />
            </>
        )
        const skeletonCards = Array.from({ length: skeletonCount }, (_unused, index) => (
            <SurfaceCard
                key={index}

                body={() => <StackV gap={6} isSkeleton={isSkeleton} items={[() => skeletonCardBody]} />}
            />
        ))
        const loadingBody = (
            <>
                <Skeleton className="h-3.5 w-40 rounded" />
                {skeletonCards}
            </>
        )
        return (
            <div>
                <StackV gap={6} isSkeleton={isSkeleton} items={[() => loadingBody]} />
            </div>
        )
    }
    const unrated = (cards ?? []).filter((card) => card.rating == null).length

    const recapCards = (cards ?? []).map((card) => (
        <SurfaceCard
            key={card.key}

            body={() => recapCardBody(card, ratingOptions, onRate, ratingAriaLabel)}
        />
    ))

    const recapBody = (
        <>
            {/* Counted, not celebrated. The recap is work; the learner is here to finish
                it, not to be congratulated for starting it. */}
            <Typography
                size="sm"
                color="muted"
                text={unrated > 0 ? `${unrated}/${(cards ?? []).length} cards left to self-grade` : `All ${(cards ?? []).length} cards self-graded`}

            />
            {recapCards}
        </>
    )

    return (
        <div>
            <StackV gap={6} isSkeleton={isSkeleton} items={[() => recapBody]} />
        </div>
    )
}

export { QuizRecapList }

import { InputText } from "@/components/atoms/forms"
import React from "react"
import { type SkeletonProps } from "@/components/frames/_slot"
import { PlayIcon } from "@phosphor-icons/react"
import { Button } from "@/components/atoms/buttons/Button"
import { ButtonRadioGroup } from "@/components/composites/buttons/ButtonRadioGroup"

import { Typography } from "@/components/atoms/text/Typography"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { Callout } from "@/components/composites/feedback/Callout"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * `QuizSetup` — choose the shape of a drill (length, seniority, name), then
 * start it. The block owns the domain wording and the lengths behind it: the
 * learner picks "quick" or "deep" and the block turns that into 5 or 10 cards,
 * saying so on the button. A run already in progress takes priority — the resume
 * strip leads the card above the form. A failed draw is reported next to the
 * button that failed.
 */

/** How long a drill runs. */
export type QuizLength = "quick" | "deep"

/** Seniority the questions aim at. */
export type QuizLevel = "junior" | "middle" | "senior" | "staff"

/** Card count per length. The BLOCK owns this — it is the judgement, not a prop. */
const LENGTH_CARDS: Record<QuizLength, number> = { quick: 5, deep: 10 }

const LENGTH_LABEL: Record<QuizLength, string> = { quick: "Quick", deep: "Deep" }

const LEVEL_LABEL: Record<QuizLevel, string> = {
    junior: "Junior",
    middle: "Middle",
    senior: "Senior",
    staff: "Staff",
}

/** A run the learner left unfinished. */
export interface QuizResumable {
    /** What the run was called when it was started. */
    name: string
    /** How many cards were answered already. */
    answered: number
    /** How many cards the run has in total. */
    total: number
    /** Fired when the learner picks the run back up. */
    onResume: () => void
}

/** Props for {@link QuizSetup}. */
export interface QuizSetupProps {
    /** Section label, localized by the caller — e.g. "Set up session". */
    label: string
    /** Current run name. */
    name: string
    /** Fired as the learner types a name. */
    onNameChange: (value: string) => void
    /** Chosen length. */
    length: QuizLength
    /** Fired when the learner picks a length. */
    onLengthChange: (length: QuizLength) => void
    /** Chosen seniority. */
    level: QuizLevel
    /** Fired when the learner picks a seniority. */
    onLevelChange: (level: QuizLevel) => void
    /** Fired when the learner starts the run. */
    onStart: () => void
    /** A run left unfinished. Present → the resume strip leads the card. */
    resumable?: QuizResumable
    /** `true` → the draw is in flight; the start button owns the busy affordance. */
    isPending?: boolean
    /** Set → the draw failed. Reported beside the action that failed. */
    errorMessage?: string
    /** `true` → the card draws its own mirror while the setup data loads. */
    isSkeleton?: boolean
}

/**
 * The drill setup form. See the file header for the full contract.
 *
 * @param props - {@link QuizSetupProps}
 */
const QuizSetup = ({
    label,
    name,
    onNameChange,
    length,
    onLengthChange,
    level,
    onLevelChange,
    onStart,
    resumable,
    isPending = false,
    errorMessage,
    isSkeleton = false,
}: QuizSetupProps) => {
    const nameField = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => <Typography size="sm" weight="medium" isSkeleton={isSkeleton} text="Session name" />,
                ({ isSkeleton }: SkeletonProps) => (
                    <InputText
                        value={name}
                        onValueChange={onNameChange}
                        placeholder="e.g. review Docker before the interview"
                        ariaLabel="Session name"
                        isSkeleton={isSkeleton}

                    />
                ),
            ]}
        />
    )

    const lengthField = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => <Typography size="sm" weight="medium" isSkeleton={isSkeleton} text="Length" />,
                () => (
                    <ButtonRadioGroup
                        ariaLabel="Session length"
                        value={length}
                        onChange={onLengthChange}

                        items={(Object.keys(LENGTH_LABEL) as Array<QuizLength>).map((key) => ({
                            value: key,
                            content: `${LENGTH_LABEL[key]} · ${LENGTH_CARDS[key]} questions`,
                        }))}
                    />
                ),
            ]}
        />
    )

    const levelField = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => <Typography size="sm" weight="medium" isSkeleton={isSkeleton} text="Level" />,
                () => (
                    <ButtonRadioGroup
                        ariaLabel="Question level"
                        value={level}
                        onChange={onLevelChange}

                        items={(Object.keys(LEVEL_LABEL) as Array<QuizLevel>).map((key) => ({
                            value: key,
                            content: LEVEL_LABEL[key],
                        }))}
                    />
                ),
            ]}
        />
    )

    const submitRow = (
        <StackH
            gap={3}
            principle="flex-action"
            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
            justify="end"
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => (
                    <Button
                        label={`Start · ${LENGTH_CARDS[length]} questions`}
                        variant="primary"
                        prefixIcon={PlayIcon}
                        onPress={onStart}
                        isPending={isPending}
                        isSkeleton={isSkeleton}

                    />
                ),
            ]}
        />
    )

    // The error sits WITH the action that failed. At the top of the card it
    // would read as a problem with the whole form.
    const actionField = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                ...(errorMessage != null ? [() => (
                    <Callout
                        status="danger"
                        title={errorMessage}

                    />
                )] : []),
                () => submitRow,
            ]}
        />
    )

    const formBody = (
        <>
            {resumable != null ? (
                // A learner who left mid-run almost always means to come back. Making
                // them scroll past a start button to find their own session is how one
                // run gets abandoned twice.
                <Callout
                    title={resumable.name}
                    description={`In progress · ${resumable.answered}/${resumable.total} questions`}
                    actionLabel="Continue"
                    onAction={resumable.onResume}

                />
            ) : null}

            {nameField}
            {lengthField}
            {levelField}
            {actionField}
        </>
    )

    return (
        <div>
            <SurfaceCard
                label={label}
                isSkeleton={isSkeleton}

                body={() => <StackV gap={6} isSkeleton={isSkeleton} items={[() => formBody]} />}
            />
        </div>
    )
}

export { QuizSetup }

import { cn } from "@heroui/react"
import { REACTION_BY_TYPE, type ReactionType } from "../types"

/** Props for the {@link ReactionGlyph} helper below. */
interface ReactionGlyphProps {
    type: ReactionType
    size: "xs" | "sm" | "md"
    className?: string
}

const REACTION_GLYPH_CLS: Record<ReactionGlyphProps["size"], string> = {
    xs: "size-4",
    sm: "size-5",
    md: "size-7",
}

/** Real Fluent Emoji SVG for a reaction (`public/reactions/<type>.svg` — same asset `src` serves). */
export const ReactionGlyph = ({ type, size, className }: ReactionGlyphProps) => (
    <img
        src={`/reactions/${type}.svg`}
        alt={REACTION_BY_TYPE[type].label}
        aria-hidden
        draggable={false}
        className={cn("inline-block select-none", REACTION_GLYPH_CLS[size], className)}
    />
)

import React, { useState } from "react"
import { type SkeletonProps } from "@/components/frames/_slot"
import { Button as HeroButton, Popover as HeroPopover } from "@heroui/react"
import { Typography } from "@/components/atoms/text/Typography"
import { ReactionPicker } from "@/components/atoms/feedback/ReactionPicker"
import { StackH } from "@/components/frames/Stack"
import { ReactionGlyph } from "./ReactionGlyph"
import { REACTION_BY_TYPE, type ReactionButtonProps, type ReactionType } from "./types"

export type { ReactionType, ReactionCount, ReactionButtonProps } from "./types"

/**
 * BLOCK — `ReactionButton`: the Facebook-style six-emotion reaction control —
 * pill trigger + Popover picker + compact summary. Shared verbatim between
 * `ContentReaction` (the lesson-level reaction) and each comment row in
 * `ContentDiscussion`'s thread — the SAME control real `src`'s `ReactionBar`
 * is, reused between `InteractionBar` and `CommentItem`.
 *
 * LEAF by STRUCTURE (§14d.2). Which emotion is picked and whether the
 * summary is empty keep the same two-part shape => states. The caller
 * flipping `isSkeleton` is its own leaf.
 */

/**
 * The reaction trigger + picker + summary. See the file header for the full contract.
 *
 * @param props - {@link ReactionButtonProps}
 */
const ReactionButton = ({
    myReaction = null,
    counts = [],
    onReact,
    isPending = false,
    isSkeleton = false,
}: ReactionButtonProps) => {
    // controlled so the popover closes as soon as an emotion is picked — mirrors real ReactionBar
    const [isOpen, setIsOpen] = useState(false)

    const total = counts.reduce((sum, entry) => sum + entry.count, 0)
    // busiest emotions first, top 3 — same cap real ReactionBar uses for the stacked summary
    const topReactions = counts
        .slice()
        .sort((prev, next) => next.count - prev.count)
        .slice(0, 3)
        .map((entry) => REACTION_BY_TYPE[entry.type])

    const onPick = (type: ReactionType) => {
        setIsOpen(false)
        onReact(myReaction === type ? null : type)
    }

    if (isSkeleton) {
        return <span className="inline-block h-8 w-28 animate-pulse rounded-full bg-default" />
    }

    // compact summary: stacked top emojis + total — dropped entirely at zero
    const summaryRow = total > 0 ? (
        <StackH
            gap={3}
            principle="value-row"
            explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
            align="center"
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <span className="flex items-center -space-x-1">
                        {topReactions.map((reaction) => (
                            <ReactionGlyph key={reaction.type} type={reaction.type} size="sm" />
                        ))}
                    </span>
                ),
                ({ isSkeleton }: SkeletonProps) => <Typography isSkeleton={isSkeleton} size="sm" text={String(total)} />,
            ]}
        />
    ) : null

    const triggerAndSummary = (
        <>
            {/* trigger: opens the 6-emotion picker; shows the viewer's own pick once set */}
            <HeroPopover isOpen={isOpen} onOpenChange={setIsOpen}>
                <HeroPopover.Trigger>
                    <HeroButton
                        variant="tertiary"
                        isDisabled={isPending}
                        className="rounded-full"

                    >
                        <ReactionGlyph type={myReaction ?? "like"} size="sm" />
                        <span className="text-sm">
                            {myReaction ? REACTION_BY_TYPE[myReaction].label : "React"}
                        </span>
                    </HeroButton>
                </HeroPopover.Trigger>
                {/* TODO(atom): heavy skin-shape (rounded-full + px-2 py-1 pill) — a frame cannot own it,
 wrap with a hand-set data-principle for now. `className` sits on `HeroPopover.Content`
 itself (the vendor's OWN rendered surface, react-aria `Popover`), not a raw <div>
 we author, so `Box` can't wrap it (moving the shape down onto an inner wrapping
 Box would leave the real popover surface with its default non-pill radius showing
 behind it — a visible shape regression). `data-principle` on `Content` directly is
 type-safe (forwarded through `DOMAttributes`), so tagged in place instead. Needs a
 dedicated pill-popover atom/composite to own this shape. Same declared shape
 as `QaReactionBar.tsx`'s trigger.
 inset-exception: pill geometry, the same px-2 py-1 HeroUI ships in chip.css. */}
                <HeroPopover.Content data-principle="pill-pad" className="overflow-visible rounded-full px-2 py-1">
                    <ReactionPicker
                        items={Object.values(REACTION_BY_TYPE).map((reaction) => ({ key: reaction.type, imgSrc: `/reactions/${reaction.type}.svg`, label: reaction.label }))}
                        activeKey={myReaction}
                        onSelect={(key) => onPick(key as ReactionType)}
                    />
                </HeroPopover.Content>
            </HeroPopover>

            {summaryRow}
        </>
    )

    return (
        <StackH gap={3} principle="flex-action"
            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
            align="center" isSkeleton={isSkeleton} items={[() => triggerAndSummary]}  />
    )
}

export { ReactionButton }

/** The six reactions, in the fixed display order real `src` uses. */
export type ReactionType = "like" | "love" | "haha" | "wow" | "sad" | "angry"

/** One reaction kind's fixed vocabulary — the block's own table (§14d.1), never caller-supplied. */
interface ReactionDescriptor {
    type: ReactionType
    /** Native emoji glyph — `alt` text for the real SVG asset. */
    emoji: string
    /** Accessible + summary label, matches `src/messages/vi.json`'s `discussion.reactions.*`. */
    label: string
}

/** Public export `REACTIONS` for this module. */
export const REACTIONS: ReadonlyArray<ReactionDescriptor> = [
    { type: "like", emoji: "👍", label: "Like" },
    { type: "love", emoji: "❤️", label: "Love" },
    { type: "haha", emoji: "😂", label: "Haha" },
    { type: "wow", emoji: "😮", label: "Wow" },
    { type: "sad", emoji: "😢", label: "Sad" },
    { type: "angry", emoji: "😡", label: "Angry" },
]

/** Public export `REACTION_BY_TYPE` for this module. */
export const REACTION_BY_TYPE: Record<ReactionType, ReactionDescriptor> = REACTIONS.reduce(
    (acc, descriptor) => { acc[descriptor.type] = descriptor; return acc },
    {} as Record<ReactionType, ReactionDescriptor>,
)

/** How many times each reaction was picked — one entry per emotion actually present. */
export interface ReactionCount {
    type: ReactionType
    count: number
}

/** Props for {@link ReactionButton}. */
export interface ReactionButtonProps {
    /** The viewer's own reaction, or `null`/omitted if they haven't reacted. */
    myReaction?: ReactionType | null
    /** Per-emotion counts. Empty/omitted → the summary is not drawn at all. */
    counts?: ReadonlyArray<ReactionCount>
    /** Fired with the picked emotion, or `null` to remove the current one. */
    onReact: (type: ReactionType | null) => void
    /** `true` → the reaction is in flight. The trigger owns the busy affordance. */
    isPending?: boolean
    /** `true` → the trigger + summary switch to their own shimmer. */
    isSkeleton?: boolean
}

