import React from "react"
import { ArrowRightIcon } from "@phosphor-icons/react"
import { Callout } from "@/components/composites/feedback/Callout"
import { Alert } from "@/components/atoms/feedback/Alert"
import { Button } from "@/components/atoms/buttons/Button"

/**
 * `TrialEnrollBanner` — the ambient "you're on a trial" nudge, reused across every
 * free surface a trial learner can reach (foundations resource page and grid, and
 * leaderboard). A caller-resolved `isVisible` drives shown vs hidden; it renders
 * both a title and a description, and `isSkeleton` covers the enrollment check still
 * being in flight. Three leaves: "shown"/"hidden" differ in structure (a node vs an
 * empty tree), and the skeleton (two text bars, no CTA) is a third structure.
 */

/** Props for {@link TrialEnrollBanner}. */
export interface TrialEnrollBannerProps {
    /**
     * `true` → the caller has resolved the learner as a known trial learner
     * (not yet enrolled) and wants the nudge shown. `false` covers BOTH
     * "enrolled" and "not yet known" — either way the banner renders nothing
     * (the "not yet known" window instead goes through {@link isSkeleton}).
     */
    isVisible: boolean
    /** Fired when the learner taps the CTA (caller owns opening the enroll flow). */
    onEnroll: () => void
    /**
     * `true` → the enrollment check that feeds `isVisible` is still in flight.
     * Reserves the banner's shape without shimmering the copy (fixed, not
     * fetched) and without a CTA (nothing to press before the check lands).
     * Wins over `isVisible`.
     */
    isSkeleton?: boolean
}

/**
 * The trial → enroll ambient nudge. See the file header for the self-gating
 * condition, the consolidation history, and why `isSkeleton` is a separate
 * window from `isVisible = false`.
 *
 * @param props - {@link TrialEnrollBannerProps}
 */
const TrialEnrollBanner = ({
    isVisible,
    onEnroll,
    isSkeleton = false,
}: TrialEnrollBannerProps) => {
    if (isSkeleton) {
        // `Callout` has no `isSkeleton` of its own (§12c gap, same one
        // `CourseTeamGate` already documents) — its `title`/`description` slots
        // render inside `<p>` (`Alert.Title`/`Alert.Description`), which cannot
        // legally contain the `<div>` a hand-built `Typography isSkeleton` bar
        // emits (real hydration error, caught live in this exact leaf). `Alert`
        // itself DOES own `isSkeleton` and draws two safe `<div>` bars straight
        // inside its content region — call it directly, same precedent as
        // `CourseTeamGate.tsx`.
        // Identity hold: Alert/Callout do not accept CallerIdentity (PageHeader gap family).
        return (
            <Alert
                isSkeleton
                status="accent"
            />
        )
    }

    // SELF-HIDE — the block owns its own show condition; the screen doesn't need to ask.
    if (!isVisible) {
        return null
    }

    // Identity hold: Callout does not accept CallerIdentity.
    return (
        <Callout
            status="accent"
            title="You're on a trial"
            description="Unlock the full course and build proof of work employers can see on your profile."
            body={() => (
                <Button
                    label="Unlock the course"
                    variant="primary"
                    size="sm"
                    suffixIcon={ArrowRightIcon}
                    iconSlide
                    onPress={onEnroll}
                />
            )}
        />
    )
}

export { TrialEnrollBanner }

"use client"

import React, {
    useCallback,
} from "react"
import {
    useTranslations,
} from "next-intl"
import { Callout } from "@/components/composites/feedback/Callout"
import { Box } from "@/components/frames/Box"
import { useAppSelector } from "@/redux/hooks"
import { usePaymentOverlayState } from "@/hooks/zustand/overlay/hooks"
import { PaymentFlow } from "@/modules/types/payment"

/** Props for {@link TrialEnrollHook}. */
export type TrialEnrollHookProps = Record<string, never>
/**
 * A thin, self-gating "you're on a trial → unlock the course" banner for the
 * FREE learn surfaces (leaderboard, foundations, flashcard study) — the ambient
 * arm of the conversion spine ([[layout-must-funnel-to-courses]]). Renders NOTHING
 * once the status query settles as enrolled (or before it settles), so a paid
 * learner never sees it and it never flashes. Outcome-framed (build real job
 * proof), one line, non-interruptive — not a popup, not repeated. Reads the
 * course off Redux; opens the shared enroll payment flow.
 *
 * @param props - optional className (placement only).
 */
export const TrialEnrollHook = () => {
    const t = useTranslations()
    const enrolled = useAppSelector((state) => state.user.enrolled)
    const enrollKnown = useAppSelector((state) => state.user.enrollKnown)
    const { open } = usePaymentOverlayState()

    /** Open the shared payment modal in the course-enroll flow. */
    const onEnroll = useCallback(
        () => open({
            flow: PaymentFlow.CourseEnroll,
        }),
        [open],
    )

    // only a settled trial (logged-in, not purchased) sees the hook
    if (!enrollKnown || enrolled) {
        return null
    }

    return (
        <Box identity={{ tier: "block", component: "TrialEnrollHook" }}>
            <Callout
                status="accent"
                title={t("enrollGate.hookTitle")}
                description={t("enrollGate.hookDesc")}
                actionLabel={t("enrollGate.hookCta")}
                onAction={onEnroll}
            />
        </Box>
    )
}

import React from "react"
import { Chip } from "@/components/atoms/chips/Chip"
import { capitalize, DIFFICULTY_COLOR, type VariantChipDifficultyProps } from "../types"

/**
 * `VariantChipDifficulty` — a color dot by tier + a difficulty word (GitHub
 * language-dot style). A thin wrapper over the `Chip` atom; color comes from
 * {@link DIFFICULTY_COLOR}.
 *
 * The shape is ALWAYS a pill — the atom's default, and design doesn't expose a
 * shape axis to the caller (see the ⛔ note at the top of this file).
 *
 * @param props - {@link VariantChipDifficultyProps}
 */
export const VariantChipDifficulty = ({
    difficulty,
    classNames,
    isSkeleton,
}: VariantChipDifficultyProps) => {
    // Part name so the anatomy tree can call out exactly what this design builds —
    // the tree reads off the DOM, so without a name the story reveals nothing
    // about what it's made of.
    // The label must be the NAMESPACE name (`Chip`) because readers look it
    // up by story name.
    // Two branches because the atom's `isSkeleton` is a disjoint union (when
    // skeleton, `text` isn't required): passing a single `boolean | undefined`
    // into one call site wouldn't type-check. The skeleton branch STILL keeps
    // `dotClassName` so the atom sizes the box correctly while leaving room for
    // the dot.
    const chip = isSkeleton ? (
        <Chip
            isSkeleton
            dotClassName={DIFFICULTY_COLOR[difficulty]}
            classNames={classNames}
        />
    ) : (
        <Chip
            dotClassName={DIFFICULTY_COLOR[difficulty]}
            text={capitalize(difficulty)}
            classNames={classNames}
        />
    )
    // Part name goes on the span that WRAPS the chip itself — NOT through
    // `AnatomyOverlay`.
    //
    // The overlay emits an `inset-0` span sitting NEXT TO the chip rather than
    // wrapping it, so `Dot`/`Label` (inside the chip) walking up the ancestor
    // chain never reach `VariantChipDifficulty` → the anatomy tree flattens
    // wrong, with the two atoms jumping up to sit level with design. The tree
    // is inferred from the DOM, so the name
    // must sit on the node that ACTUALLY contains the children.
    return chip
}

/** The supported difficulty levels a piece of content can be tagged with. */
export type Difficulty = "beginner" | "intermediate" | "advanced" | "insane"

/**
 * Dot color scale by difficulty tier — the SSOT for this ramp, import it, don't
 * redeclare it.
 *
 * Uses a sequential Tailwind palette ramp (hotter = harder) INSTEAD OF the 5
 * semantic tokens (`accent`/`success`/`warning`/`danger`/`default`): difficulty is
 * a **TIER**, not a **STATE** — forcing 4 tiers into semantic tokens would collide
 * on `danger` twice.
 */
export const DIFFICULTY_COLOR: Record<Difficulty, string> = {
    beginner: "text-emerald-500",
    intermediate: "text-amber-500",
    advanced: "text-orange-500",
    insane: "text-rose-500",
}

/** Props for {@link VariantChipDifficulty}. */
export interface VariantChipDifficultyProps {
    /** Difficulty tier — decides BOTH the label AND the dot color. The one axis. */
    difficulty: Difficulty
    /**
     * Extra classes on the wrapper. A closed union, not a free string: this
     * value is handed straight to `Chip`'s own closed `classNames` union, so an
     * unconstrained string here would only fail one tier down.
     */
    classNames?: Array<import("@/components/atoms/_allowed-class-name").AllowedClassName>
    /** `true` → shimmer bar mirroring the exact dot+label shape (the atom draws it itself). */
    isSkeleton?: boolean
    /** Dev/spec: overlay anatomy labels on this chip. */
}

/** Title-case a difficulty key for the default label. */
export const capitalize = (value: Difficulty): string => value.charAt(0).toUpperCase() + value.slice(1)

"use client"

import {
    CaretDownIcon,
    LockIcon,
    SparkleIcon,
} from "@phosphor-icons/react"
import React from "react"
import { Dropdown, DropdownItem, DropdownMenu, DropdownPopover, DropdownSection, DropdownTrigger, Tooltip } from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import type {
    AiLabModelSelection,
} from "../types"
import { AiModelCategory } from "@/modules/api/graphql/queries/query-ai-models"
import { type AiGradableModel } from "@/modules/api/graphql/queries/types/ai-models"
import { AiCategoryChip } from "@/components/blocks/chips/AiCategoryChip"

/** Props for {@link LaneModelPicker}. */
export type LaneModelPickerProps = {
    /** Enabled models the user can pick from (from the `aiModels` catalog). */
    models: Array<AiGradableModel>
    /** The current lane + model selection. */
    selection: AiLabModelSelection
    /** Whether the Premium lane (specific models) is unlocked for this user. */
    canPremium: boolean
    /** Disables the whole control (e.g. while a run is in flight). */
    isDisabled?: boolean
    /** Fired with the new selection when the user picks an option. */
    onSelect: (selection: AiLabModelSelection) => void
    /** Fired when a locked (subscription-required) model is pressed — route to AI settings. */
    onUpgrade: () => void
}

/**
 * Lane + model picker for an AI Lab run.
 *
 * Presentational: renders the free "Auto" lane plus every catalog model (each tagged
 * with its cost category chip) and forwards the chosen {@link AiLabModelSelection}.
 * Premium models are locked unless `canPremium`. Mirrors the challenge panel's
 * `GradeModelDropdown` but uses the local selection type.
 * @param props - {@link LaneModelPickerProps}
 */
export const LaneModelPicker = ({
    models,
    selection,
    canPremium,
    isDisabled = false,
    onSelect,
    onUpgrade}: LaneModelPickerProps) => {
    const t = useTranslations()
    const isAuto = selection.model === null
    const triggerLabel = isAuto
        ? t("aiSettings.lanes.auto.title")
        : selection.model

    return (
        <Dropdown>
            <DropdownTrigger
                isDisabled={isDisabled}
                className={"cursor-pointer"}
            >
                <div className="flex items-center gap-2">
                    <SparkleIcon className="size-5" />
                    <span className="max-w-40 truncate">{triggerLabel}</span>
                    <CaretDownIcon weight="bold" className="size-4" />
                </div>
            </DropdownTrigger>
            <DropdownPopover
                placement="bottom start"
                className="min-w-64"
            >
                <DropdownMenu aria-label={t("aiSettings.pickModel")}>
                    {/* Auto lane — balancer picks a complimentary model, free of charge */}
                    <DropdownSection>
                        <DropdownItem
                            key="auto"
                            onPress={() => onSelect({
                                model: null,
                                provider: null,
                            })}
                        >
                            <div className="flex items-center gap-2">
                                <span>{t("aiSettings.lanes.auto.title")}</span>
                            </div>
                        </DropdownItem>
                    </DropdownSection>
                    {/* One entry per catalog model, with a category chip. Free + Economy
                        models run without a plan; Balanced + Premium are locked without a
                        subscription (pressing routes to AI settings). */}
                    <DropdownSection className="border-t border-divider pt-1 mt-1">
                        {models.map((model) => {
                            const key = `${model.provider}:${model.model}`
                            const categoryChip = <AiCategoryChip category={model.category} />
                            // Free + Economy are usable without a plan; Balanced + Premium
                            // require a paid subscription.
                            const requiresPlan = model.category === AiModelCategory.Medium
                                || model.category === AiModelCategory.High
                            if (!model.available) {
                                return (
                                    <DropdownItem
                                        key={key}
                                        textValue={model.model}
                                        onPress={() => undefined}
                                    >
                                        <Tooltip>
                                            <Tooltip.Trigger>
                                                <div className="flex w-full items-center justify-between gap-2 text-muted">
                                                    <span className="flex min-w-0 items-center gap-2">
                                                        <LockIcon className="size-5 shrink-0" />
                                                        <span className="truncate">{model.model}</span>
                                                    </span>
                                                    {categoryChip}
                                                </div>
                                            </Tooltip.Trigger>
                                            <Tooltip.Content>{t("aiSettings.modelUnavailable")}</Tooltip.Content>
                                        </Tooltip>
                                    </DropdownItem>
                                )
                            }
                            if (requiresPlan && !canPremium) {
                                return (
                                    <DropdownItem
                                        key={key}
                                        textValue={model.model}
                                        onPress={onUpgrade}
                                    >
                                        <Tooltip>
                                            <Tooltip.Trigger>
                                                <div className="flex w-full items-center justify-between gap-2 text-muted">
                                                    <span className="flex min-w-0 items-center gap-2">
                                                        <LockIcon className="size-5 shrink-0" />
                                                        <span className="truncate">{model.model}</span>
                                                    </span>
                                                    {categoryChip}
                                                </div>
                                            </Tooltip.Trigger>
                                            <Tooltip.Content>{t("aiSettings.subscribeToGrade")}</Tooltip.Content>
                                        </Tooltip>
                                    </DropdownItem>
                                )
                            }
                            return (
                                <DropdownItem
                                    key={key}
                                    textValue={model.model}
                                    onPress={() => onSelect({
                                        model: model.model,
                                        provider: model.provider,
                                    })}
                                >
                                    <div className="flex items-center justify-between gap-2">
                                        <span className="truncate">{model.model}</span>
                                        {categoryChip}
                                    </div>
                                </DropdownItem>
                            )
                        })}
                    </DropdownSection>
                </DropdownMenu>
            </DropdownPopover>
        </Dropdown>
    )
}

"use client"

import React from "react"
import {
    useTranslations,
} from "next-intl"
import type {
    AiLabParamsForm,
} from "../types"

/** Props for {@link ParamControls}. */
export type ParamControlsProps = {
    /** Current generation params. */
    params: AiLabParamsForm
    /** Disables all inputs (e.g. while a run is in flight). */
    isDisabled?: boolean
    /** Fired with the patched params when any field changes. */
    onChange: (params: AiLabParamsForm) => void
}

/** One labelled numeric param input row. */
interface ParamFieldProps {
    /** Label shown above the input. */
    label: string
    /** DOM id for the input. */
    id: string
    /** Current numeric value. */
    value: number
    /** Smallest allowed value. */
    min: number
    /** Largest allowed value. */
    max: number
    /** Step increment. */
    step: number
    /** Disables the input. */
    isDisabled: boolean
    /** Fired with the parsed number on change. */
    onChange: (value: number) => void
}

/** A single numeric param input, styled to match the codebase's plain-input convention. */
const ParamField = ({
    label,
    id,
    value,
    min,
    max,
    step,
    isDisabled,
    onChange,
}: ParamFieldProps) => (
    <div className="flex flex-col gap-2">
        <label
            htmlFor={id}
            className="text-sm text-muted"
        >
            {label}
        </label>
        <input
            id={id}
            type="number"
            min={min}
            max={max}
            step={step}
            value={Number.isFinite(value) ? value : ""}
            disabled={isDisabled}
            onChange={(event) => onChange(Number(event.target.value))}
            className="w-full rounded-2xl border border-default bg-background px-4 py-2 text-sm text-foreground focus:border-accent focus:outline-none disabled:opacity-50"
        />
    </div>
)

/**
 * Three numeric inputs for the generation params (temperature / top-p / max tokens).
 *
 * Presentational — the parent owns the {@link AiLabParamsForm} state and receives a
 * full patched object on every change.
 * @param props - {@link ParamControlsProps}
 */
export const ParamControls = ({
    params,
    isDisabled = false,
    onChange}: ParamControlsProps) => {
    const t = useTranslations()
    return (
        <div className={"grid grid-cols-1 gap-3 @app-sm:grid-cols-3"}>
            <ParamField
                id="ai-lab-temperature"
                label={t("aiLab.playground.temperature")}
                value={params.temperature}
                min={0}
                max={2}
                step={0.1}
                isDisabled={isDisabled}
                onChange={(temperature) => onChange({ ...params, temperature })}
            />
            <ParamField
                id="ai-lab-top-p"
                label={t("aiLab.playground.topP")}
                value={params.topP}
                min={0}
                max={1}
                step={0.05}
                isDisabled={isDisabled}
                onChange={(topP) => onChange({ ...params, topP })}
            />
            <ParamField
                id="ai-lab-max-tokens"
                label={t("aiLab.playground.maxTokens")}
                value={params.maxTokens}
                min={1}
                max={32000}
                step={1}
                isDisabled={isDisabled}
                onChange={(maxTokens) => onChange({ ...params, maxTokens })}
            />
        </div>
    )
}

