import { useQueryAiModelsSwr } from "@/hooks/swr/api/graphql/queries/useQueryAiModelsSwr"
import { useQueryMyAiQuotaSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyAiQuotaSwr"
import { useQueryMyAiSettingsSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyAiSettingsSwr"
import { useQueryMyAiLabRunsSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyAiLabRunsSwr"
import { AiLabRunStatus } from "@/hooks/socketio/types/ai-lab"
import { MarkdownContent } from "@/components/blocks/rendering/MarkdownContent"
import { useGraphQLWithToast } from "@/modules/toast/hooks"

/** Props for {@link PromptPlayground}. */
export type PromptPlaygroundProps = {
    /** The playground bound to this lesson. */
    playground: AiLabPlaygroundData
}

/** Default param values used when the playground does not seed them. */
const FALLBACK_PARAMS: AiLabParamsForm = {
    temperature: 0.7,
    topP: 1,
    maxTokens: 1024,
}

/** Build the param form from the playground defaults (falling back per field). */
const buildDefaultParams = (playground: AiLabPlaygroundData): AiLabParamsForm => ({
    temperature: playground.defaultParams?.temperature ?? FALLBACK_PARAMS.temperature,
    topP: playground.defaultParams?.topP ?? FALLBACK_PARAMS.topP,
    maxTokens: playground.defaultParams?.maxTokens ?? FALLBACK_PARAMS.maxTokens,
})

/**
 * Prompt playground surface: system + user prompt inputs, generation params, a lane/model
 * picker, and a Run/Abort control. The streamed response is read live from the Redux
 * `aiLabRunById` map via {@link useAiLabRunStreamSocketIo}; cache hits render inline.
 *
 * Container: owns the editable prompt/param/selection state and the run mutation, then
 * subscribes to the `/ai_lab` token stream for non-cached runs.
 * @param props - {@link PromptPlaygroundProps}
 */
export const PromptPlayground = ({ playground}: PromptPlaygroundProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const runGraphQL = useGraphQLWithToast()

    // Editable prompt + param + lane state, seeded from the playground defaults.
    const [systemPrompt, setSystemPrompt] = useState(playground.defaultSystemPrompt ?? "")
    const [userPrompt, setUserPrompt] = useState(playground.defaultUserPrompt ?? "")
    const [params, setParams] = useState<AiLabParamsForm>(() => buildDefaultParams(playground))
    const [selection, setSelection] = useState<AiLabModelSelection>({
        model: null,
        provider: null,
    })

    // The run currently being tracked (set after the mutation returns a streaming run id).
    const [runId, setRunId] = useState<string | undefined>(undefined)
    // Inline output when the run was served from cache (no socket stream).
    const [cachedOutput, setCachedOutput] = useState<string | null>(null)
    // Window budget hint returned by the last run.
    const [quotaExhausted, setQuotaExhausted] = useState(false)

    const runPromptSwr = useMutateRunPlaygroundPromptSwr()
    const { run, subscribe, abort, reset } = useAiLabRunStreamSocketIo(runId)

    // Lane/model catalog + entitlement for the picker.
    const aiModelsSwr = useQueryAiModelsSwr()
    const aiSettingsSwr = useQueryMyAiSettingsSwr()
    const canPremium = Boolean(aiSettingsSwr.data?.canPremium)
    const aiQuotaSwr = useQueryMyAiQuotaSwr()
    const runsSwr = useQueryMyAiLabRunsSwr(playground.id)

    const gradableModels = useMemo<Array<AiGradableModel>>(
        () => aiModelsSwr.data?.aiModels?.data?.gradableModels ?? [],
        [aiModelsSwr.data],
    )

    /** Route to AI settings so the user can subscribe or add a BYOK key. */
    const onGoToAiSettings = useCallback(
        () => {
            router.push(`/${locale}/profile/settings/ai-settings`)
        },
        [router, locale],
    )

    // The run is streaming while the socket has a live, not-yet-done entry for it.
    const isStreaming = Boolean(run && !run.done)
    const isPending = runPromptSwr.isMutating || isStreaming

    /** Submit the prompt: fire the mutation, then either render the cache hit or subscribe to the stream. */
    const onRun = useCallback(
        async () => {
            if (!userPrompt.trim()) {
                return
            }
            // Reset prior run state before starting a new one.
            if (runId) {
                reset(runId)
            }
            setRunId(undefined)
            setCachedOutput(null)
            // The run payload captured from the mutation so the success path can drive streaming.
            let result: GraphQLResponse<RunPlaygroundPromptData> | undefined
            const ok = await runGraphQL<RunPlaygroundPromptData>(
                async () => {
                    const response = await runPromptSwr.trigger({
                        playgroundId: playground.id,
                        systemPrompt: systemPrompt.trim() || undefined,
                        userPrompt: userPrompt.trim(),
                        params: {
                            temperature: params.temperature,
                            topP: params.topP,
                            maxTokens: params.maxTokens,
                        },
                        selectedModel: selection.model ?? undefined,
                        selectedModelProvider: selection.provider ?? undefined,
                    })
                    result = response.data?.runPlaygroundPrompt
                    if (!result?.success || !result.data) {
                        throw new Error(result?.message ?? response.error?.message)
                    }
                    return result
                },
                { showSuccessToast: false },
            )
            if (!ok || !result?.data) {
                return
            }
            const { runId: nextRunId, status, cachedOutput: nextCachedOutput, quotaExhausted: exhausted } =
                result.data
            setQuotaExhausted(exhausted)
            // Cache hit: the output is returned inline, never streamed over the socket.
            if (status === AiLabRunStatus.Cached) {
                setCachedOutput(nextCachedOutput ?? "")
                setRunId(nextRunId)
                return
            }
            // Live run: track it and subscribe to the token stream.
            setRunId(nextRunId)
            subscribe(nextRunId)
        },
        [
            userPrompt,
            runId,
            reset,
            runGraphQL,
            runPromptSwr,
            playground.id,
            systemPrompt,
            params,
            selection,
            subscribe,
        ],
    )

    /** Abort the in-flight stream. */
    const onAbort = useCallback(
        () => {
            if (runId) {
                abort(runId)
            }
        },
        [runId, abort],
    )

    /** Restore the prompts/params to the playground defaults and drop the tracked run. */
    const onReset = useCallback(
        () => {
            setSystemPrompt(playground.defaultSystemPrompt ?? "")
            setUserPrompt(playground.defaultUserPrompt ?? "")
            setParams(buildDefaultParams(playground))
            setSelection({ model: null, provider: null })
            setCachedOutput(null)
            if (runId) {
                reset(runId)
            }
            setRunId(undefined)
        },
        [playground, runId, reset],
    )

    // Output to render: cache hit text, otherwise the accumulated stream.
    const outputText = cachedOutput ?? run?.output ?? ""
    const isCached = cachedOutput !== null
    const isFailed = run?.status === AiLabRunStatus.Failed
    const promptTokens = run?.promptTokens
    const completionTokens = run?.completionTokens
    const priorRuns = runsSwr.data ?? []

    return (
        <div className={"flex flex-col gap-6"}>
            <div className="flex flex-col gap-2">
                <h3 className="text-lg font-semibold">{t("aiLab.playground.title")}</h3>
                <p className="text-sm text-muted">{t("aiLab.playground.description")}</p>
            </div>

            {/* System prompt */}
            <div className="flex flex-col gap-2">
                <label
                    htmlFor="ai-lab-system-prompt"
                    className="text-sm text-muted"
                >
                    {t("aiLab.playground.systemPrompt")}
                </label>
                <textarea
                    id="ai-lab-system-prompt"
                    rows={3}
                    value={systemPrompt}
                    disabled={isPending}
                    onChange={(event) => setSystemPrompt(event.target.value)}
                    placeholder={t("aiLab.playground.systemPromptPlaceholder")}
                    className="w-full resize-y rounded-2xl border border-default bg-background px-4 py-3 text-sm text-foreground focus:border-accent focus:outline-none disabled:opacity-50"
                />
            </div>

            {/* User prompt */}
            <div className="flex flex-col gap-2">
                <label
                    htmlFor="ai-lab-user-prompt"
                    className="text-sm text-muted"
                >
                    {t("aiLab.playground.userPrompt")}
                </label>
                <textarea
                    id="ai-lab-user-prompt"
                    rows={5}
                    value={userPrompt}
                    disabled={isPending}
                    onChange={(event) => setUserPrompt(event.target.value)}
                    placeholder={t("aiLab.playground.userPromptPlaceholder")}
                    className="w-full resize-y rounded-2xl border border-default bg-background px-4 py-3 text-sm text-foreground focus:border-accent focus:outline-none disabled:opacity-50"
                />
            </div>

            {/* Params */}
            <div className="flex flex-col gap-2">
                <span className="text-sm text-muted">{t("aiLab.playground.params")}</span>
                <ParamControls
                    params={params}
                    isDisabled={isPending}
                    onChange={setParams}
                />
            </div>

            {/* Lane/model + actions */}
            <div className="flex flex-wrap items-center justify-between gap-3">
                <div className="flex items-center gap-2">
                    <span className="text-sm text-muted">{t("aiLab.playground.model")}:</span>
                    <LaneModelPicker
                        models={gradableModels}
                        selection={selection}
                        canPremium={canPremium}
                        isDisabled={isPending}
                        onSelect={setSelection}
                        onUpgrade={onGoToAiSettings}
                    />
                    <GradeCreditCaption
                        creditUsage={aiQuotaSwr.data}
                        hasPinnedModel={Boolean(selection.model)}
                        autoCreditCost={undefined}
                    />
                </div>
                <div className="flex items-center gap-2">
                    <Button
                        variant="tertiary"
                        size="sm"
                        isDisabled={isPending}
                        onPress={onReset}
                    >
                        {t("aiLab.playground.resetToDefault")}
                    </Button>
                    {isStreaming ? (
                        <Button
                            variant="danger"
                            size="sm"
                            onPress={onAbort}
                        >
                            {t("aiLab.playground.abort")}
                        </Button>
                    ) : null}
                    <Button
                        variant="primary"
                        size="sm"
                        isPending={isPending}
                        isDisabled={!userPrompt.trim()}
                        onPress={onRun}
                    >
                        {t("aiLab.playground.run")}
                    </Button>
                </div>
            </div>

            {/* Quota exhausted nudge → BYOK */}
            {quotaExhausted ? (
                <div className="flex flex-wrap items-center justify-between gap-2 rounded-2xl border border-warning/30 bg-warning-soft p-3">
                    <span className="text-sm">
                        {t("aiLab.playground.quotaExhausted")} {t("aiLab.playground.byokNudge")}
                    </span>
                    <Button
                        variant="secondary"
                        size="sm"
                        onPress={onGoToAiSettings}
                    >
                        {t("aiLab.playground.goToAiSettings")}
                    </Button>
                </div>
            ) : null}

            {/* Output pane */}
            <div className="flex flex-col gap-2">
                <div className="flex items-center gap-2">
                    <span className="text-sm text-muted">{t("aiLab.playground.output")}</span>
                    {isCached ? (
                        <Chip
                            size="sm"
                            color="default"
                            variant="soft"
                        >
                            {t("aiLab.playground.cached")}
                        </Chip>
                    ) : null}
                    {isStreaming ? <Spinner size="sm" /> : null}
                </div>
                <div className="min-h-24 rounded-3xl border border-default bg-surface p-4">
                    {isFailed ? (
                        <span className="text-sm text-danger-soft-foreground">
                            {run?.errorMessage ?? t("aiLab.playground.failed")}
                        </span>
                    ) : outputText ? (
                        <MarkdownContent markdown={outputText} />
                    ) : (
                        <span className="text-sm text-muted">{t("aiLab.playground.outputEmpty")}</span>
                    )}
                </div>
                {(promptTokens != null || completionTokens != null) ? (
                    <span className="text-xs text-muted">
                        {t("aiLab.playground.tokens", {
                            prompt: promptTokens ?? 0,
                            completion: completionTokens ?? 0,
                        })}
                    </span>
                ) : null}
            </div>

            {/* Prior runs */}
            {priorRuns.length > 0 ? (
                <div className="flex flex-col gap-2">
                    <span className="text-sm text-muted">{t("aiLab.playground.runHistory")}</span>
                    <SurfaceListCard bordered>
                        {priorRuns.map((priorRun) => (
                            <SurfaceListCardItem key={priorRun.id}>
                                <div className="flex items-center justify-between gap-3">
                                    <span className="min-w-0 truncate text-sm">{priorRun.userPrompt}</span>
                                    <Chip
                                        size="sm"
                                        color={priorRun.status === AiLabRunStatus.Failed ? "danger" : "default"}
                                        variant="soft"
                                    >
                                        {t(`aiLab.status.${priorRun.status}`)}
                                    </Chip>
                                </div>
                            </SurfaceListCardItem>
                        ))}
                    </SurfaceListCard>
                </div>
            ) : null}
        </div>
    )
}

"use client"

import React from "react"
import {
    PromptPlayground,
} from "./PromptPlayground"
import { useAppSelector } from "@/redux/hooks"
import { useQueryAiLabPlaygroundSwr } from "@/hooks/swr/api/graphql/queries/useQueryAiLabPlaygroundSwr"

/** Props for the AI Lab tab body. */
export type AiLabBodyProps = Record<string, never>
/** Known AI Lab playground kinds (mirrors backend `AiLabPlaygroundKind`). */
const PLAYGROUND_KIND = {
    Prompt: "prompt",
    Rag: "rag",
    Comparison: "comparison",
} as const

/**
 * AI Lab tab body: resolves the lesson's playground from SWR, then renders the matching
 * surface by `kind` (prompt → {@link PromptPlayground}; rag / comparison → placeholder).
 * Reads `content` from Redux to scope the playground query.
 * @param props - Optional wrapper styling props.
 */
export const AiLab = () => {
    const content = useAppSelector((state) => state.content.entity)
    const playgroundSwr = useQueryAiLabPlaygroundSwr(content?.id)
    const playground = playgroundSwr.data

    if (!playground) {
        return null
    }

    return (
        <div className={"flex flex-col gap-6"}>
            {playground.kind === PLAYGROUND_KIND.Prompt ? (
                <PromptPlayground playground={playground} />
            ) : (
                // RAG / comparison playgrounds are P1/P2 — fall back to the prompt surface,
                // which still drives a single prompt run against the configured model.
                <PromptPlayground playground={playground} />
            )}
        </div>
    )
}

import type { ModelProvider } from "@/modules/api/graphql/queries/query-my-ai-settings"

/**
 * A concrete model the user picked in the AI Lab.
 *
 * Mirrors the challenge panel's selection shape but lives locally so the AI Lab
 * surfaces do not import modal-internal types.
 */
export interface AiLabModelSelection {
    /** Concrete model name; null on the Auto lane (balancer chooses). */
    model: string | null
    /** Provider serving {@link model}; null on the Auto lane. */
    provider: ModelProvider | null
}

/** Generation params edited by the param controls (kept as numbers for the inputs). */
export interface AiLabParamsForm {
    /** Sampling temperature. */
    temperature: number
    /** Nucleus sampling top-p. */
    topP: number
    /** Max output tokens. */
    maxTokens: number
}

"use client"

import {
    TrophyIcon,
    FlameIcon,
    LightbulbIcon,
    CircleIcon,
    CircleNotchIcon,
    CheckCircleIcon,
    XCircleIcon,
    PlayIcon,
    ArrowClockwiseIcon,
    EyeIcon,
    type Icon,
} from "@phosphor-icons/react"
import React, { useMemo } from "react"
import { Button, cn } from "@heroui/react"
import { useTranslations } from "next-intl"
import { useParams } from "next/navigation"
import { useRouter } from "@/i18n/navigation"
import { ChallengeDifficulty } from "@/modules/types/enums/challenge-difficulty"
import { type ChallengeEntity } from "@/modules/types/entities/challenge"
import type { ChallengeProgressStatus } from "@/modules/api/graphql/queries/types/challenge-submission-progress"
import { DifficultyChip } from "@/components/blocks/chips/DifficultyChip"
import { toDifficulty } from "@/modules/utils/difficulty"
import { useAppSelector } from "@/redux/hooks"
import { MarkdownContent } from "@/components/blocks/rendering/MarkdownContent"

/** i18n key for each difficulty tier label (covers all 5 BE tiers). */
const DIFFICULTY_LABEL_KEY: Record<ChallengeDifficulty, string> = {
    [ChallengeDifficulty.Easy]: "challenge.difficulty.easy",
    [ChallengeDifficulty.Medium]: "challenge.difficulty.medium",
    [ChallengeDifficulty.Hard]: "challenge.difficulty.hard",
    [ChallengeDifficulty.Insane]: "challenge.difficulty.insane",
    [ChallengeDifficulty.Expert]: "challenge.difficulty.expert",
}

/** Status → eyebrow chip (icon + label color). */
const STATUS_META: Record<ChallengeProgressStatus, { labelKey: string; className: string; icon: Icon }> = {
    notStarted: { labelKey: "challenge.status.notStarted", className: "text-muted", icon: CircleIcon },
    inProgress: { labelKey: "challenge.status.inProgress", className: "text-warning-soft-foreground", icon: CircleNotchIcon },
    failed: { labelKey: "challenge.status.failed", className: "text-danger-soft-foreground", icon: XCircleIcon },
    completed: { labelKey: "challenge.status.completed", className: "text-success-soft-foreground", icon: CheckCircleIcon },
}

/** Status → primary action label + icon (resume semantics). */
const CTA_META: Record<ChallengeProgressStatus, { labelKey: string; icon: Icon }> = {
    notStarted: { labelKey: "challenge.cta.start", icon: FlameIcon },
    inProgress: { labelKey: "challenge.cta.continue", icon: PlayIcon },
    failed: { labelKey: "challenge.cta.retry", icon: ArrowClockwiseIcon },
    completed: { labelKey: "challenge.cta.review", icon: EyeIcon },
}

/** Props for {@link ChallengeCard}. */
export interface ChallengeCardProps {
    /** Challenge row displayed in content tab. */
    challenge: ChallengeEntity
}

/**
 * One challenge in the "Challenges" tab — a single card (bounded object): puzzle
 * eyebrow + status chip → title → difficulty/score/hint chips → clamped description
 * → footer (attempts + best score on the left, status-driven primary action on the
 * right). The card is a static surface — only the footer button navigates.
 * @param {ChallengeCardProps} props Challenge card props.
 */
export const ChallengeCard = ({ challenge}: ChallengeCardProps) => {
    const t = useTranslations()
    const router = useRouter()
    const params = useParams()
    // Per-challenge progress, populated by `useQueryChallengeSubmissionProgressSwr`.
    const completionTasks = useAppSelector((state) => state.challenge.completionTasks)
    const progress = useMemo(
        () => completionTasks.find((completionTask) => completionTask.id === challenge.id) ?? null,
        [completionTasks, challenge.id],
    )
    const status: ChallengeProgressStatus = progress?.status ?? "notStarted"
    const statusMeta = STATUS_META[status]
    const ctaMeta = CTA_META[status]
    const StatusIcon = statusMeta.icon
    const CtaIcon = ctaMeta.icon

    // Footer-left progress line: attempts + best score, or "not attempted yet".
    const maxScore = progress?.maxScore ?? challenge.score
    const attemptsLine = useMemo(() => {
        const attempts = progress?.numAttempts ?? 0
        if (attempts <= 0) {
            return t("challenge.attempts.none")
        }
        const base = t("challenge.attempts.some", { count: attempts })
        if (progress?.lastScore == null) {
            return base
        }
        return `${base} · ${t("challenge.attempts.bestScore", { score: progress.lastScore, maxScore })}`
    }, [progress?.numAttempts, progress?.lastScore, maxScore, t])

    const openChallenge = () => {
        const courseId = params.courseId as string
        const moduleId = params.moduleId as string
        const contentId = params.contentId as string
        router.push(`/courses/${courseId}/learn/content/modules/${moduleId}/contents/${contentId}/challenges/${challenge.id}`)
    }

    return (
        // each challenge is its OWN distinct card (surface fill + border on a plain div so
        // the utilities aren't overridden by HeroUI Card's unlayered styles). The card itself
        // is static (NOT clickable, no hover/cursor) — only the footer "Do" button navigates.
        // Completed rows are de-emphasized.
        <div className={cn("rounded-3xl border border-default bg-surface p-4", status === "completed" && "opacity-80")}>
            <div className="flex flex-col gap-3">
                <div>
                    <div className="flex items-center justify-between gap-2 mb-2">
                        {/* quiet eyebrow — the challenge number is a low-key label, not a heading;
                            the title below is the meaningful line. No motif icon (it lives once on
                            the section's LabeledCard label). */}
                        <span className="text-xs text-muted">
                            {t("challenge.number", { index: challenge.sortIndex })}
                        </span>
                        <span className={cn("inline-flex items-center gap-2 text-xs", statusMeta.className)}>
                            <StatusIcon className="size-4 shrink-0" />
                            {t(statusMeta.labelKey)}
                        </span>
                    </div>
                    <div className="font-medium">{challenge.title}</div>
                </div>
                <div className="flex items-center gap-2 flex-wrap">
                    {/* the difficulty ramp lives in ONE place (`DifficultyChip`); this row used to
                        tint a generic chip from a second, raw-Tailwind palette of its own */}
                    <DifficultyChip
                        difficulty={toDifficulty(challenge.difficulty)}
                        label={t(DIFFICULTY_LABEL_KEY[challenge.difficulty] ?? "challenge.difficulty.easy")}
                    />
                    <span className="inline-flex items-center gap-1 text-xs text-muted">
                        <TrophyIcon className="size-4 shrink-0" />
                        {challenge.score}
                    </span>
                    {challenge.hint ? (
                        <span className="inline-flex items-center gap-1 text-xs text-muted">
                            <LightbulbIcon className="size-4 shrink-0" />
                            {t("challenge.hintTag")}
                        </span>
                    ) : null}
                </div>
                {challenge.description ? (
                    <MarkdownContent
                        markdown={challenge.description}
                        density="caption"
                        tone="muted"
                        flow="embedded"
                        previewLines={2}
                    />
                ) : null}
                <div className="flex items-center justify-between gap-2">
                    <span className="inline-flex items-center gap-2 text-xs text-muted">
                        <ArrowClockwiseIcon className="size-4 shrink-0" />
                        {attemptsLine}
                    </span>
                    <Button onPress={openChallenge}>
                        <CtaIcon className="size-5" />
                        {t(ctaMeta.labelKey)}
                    </Button>
                </div>
            </div>
        </div>
    )
}

"use client"

import React, { useMemo } from "react"
import { Pagination } from "@heroui/react"
import { useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { ChallengeCard } from "./ChallengeCard"
import { ChallengeCardSkeleton } from "./ChallengeCardSkeleton"
import _ from "lodash"
import { useAppDispatch, useAppSelector } from "@/redux/hooks"
import { WithClassNames } from "@/modules/types/base/class-name"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { UpNextCard } from "@/components/blocks/learn/UpNextCard"
import { useQueryChallengesSwr } from "@/hooks/swr/api/graphql/queries/useQueryChallengesSwr"
import { setChallengePageNumber } from "@/redux/slices/challenge"
import { useLessonNavigation } from "../hooks/useLessonNavigation"

/** Props for {@link ChallengeBody}. */
export type ChallengeBodyProps = WithClassNames<undefined>

/** Content tab body listing the lesson's challenges, paginated. */
export const ChallengeBody = () => {
    const t = useTranslations()
    const router = useRouter()
    const dispatch = useAppDispatch()
    const queryChallengesSwr = useQueryChallengesSwr()
    const challenges = useAppSelector((state) => state.challenge.entities)
    const count = useAppSelector((state) => state.challenge.count)
    // completion handoff: when the learner has PASSED every challenge of THIS lesson,
    // the natural next rung is the NEXT lesson (within the learn-content track).
    const completionTasks = useAppSelector((state) => state.challenge.completionTasks)
    const content = useAppSelector((state) => state.content.entity)
    const { next } = useLessonNavigation()
    const allChallengesPassed = useMemo(
        () => {
            const contentChallenges = content?.challenges ?? []
            return contentChallenges.length > 0
                && contentChallenges.every(
                    (challenge) => completionTasks.find((task) => task.id === challenge.id)?.completed === true,
                )
        },
        [content?.challenges, completionTasks],
    )
    const limit = useAppSelector((state) => state.challenge.limit)
    const pageNumber = useAppSelector((state) => state.challenge.pageNumber)
    // gate on first-load only (NOT isValidating) — a background revalidate on page
    // change keeps the current cards on screen instead of flashing the skeleton
    const isLoading = queryChallengesSwr.isLoading
    // surface fetch failures (e.g. the FE↔BE schema drift that broke this tab) as a
    // distinct error+retry state instead of an indistinguishable "no challenges" empty
    const error = queryChallengesSwr.error
    const isEmpty = !isLoading && !error && !challenges?.length
    const pageSize = limit ?? 10
    const totalPages = useMemo(() => {
        if (count == null || count <= 0) {
            return 0
        }
        return Math.max(1, Math.ceil(count / pageSize))
    }, [count, pageSize])
    const pageNumbers = useMemo(
        () => Array.from({ length: totalPages }, (_, index) => index + 1),
        [totalPages],
    )
    const currentPage = pageNumber ?? 1
    // frameless ONLY once real cards render (each ChallengeCard self-frames); while
    // loading/empty/erroring there is no bounded surface, so LabeledCard's own Card
    // must frame it — otherwise the section's label would also disappear along with
    // the frame (AsyncContent used to sit OUTSIDE LabeledCard entirely).
    const hasChallenges = !isLoading && !error && !isEmpty

    return (
        <LabeledCard
            identity={{ tier: "block", component: "ChallengeBody" }}
            label={t("challenge.count", { count: count ?? 0 })}
            frameless={hasChallenges}

        >
            <AsyncContent
                isLoading={isLoading}
                skeleton={(
                    <div className="flex flex-col gap-3">
                        <ChallengeCardSkeleton />
                        <ChallengeCardSkeleton />
                    </div>
                )}
                isEmpty={isEmpty}
                emptyContent={{ title: t("challenge.empty") }}
                error={error}
                errorContent={{
                    title: t("challenge.errorTitle"),
                    description: t("challenge.errorDescription"),
                    onRetry: () => queryChallengesSwr.mutate(),
                    retryLabel: t("challenge.retry"),
                }}
            >
                <div className="flex flex-col gap-6">
                    <div className="flex flex-col gap-3">
                        {
                            _.cloneDeep(challenges)
                                ?.sort((prev, next) => prev.sortIndex - next.sortIndex)
                                .map((challenge) => <ChallengeCard key={challenge.id} challenge={challenge} />)
                        }
                    </div>
                    {count ? (
                        <Pagination
                            aria-label={t("common.pagination.navAria")}
                            className="justify-start"
                            size="sm"
                        >
                            <Pagination.Content className="flex flex-wrap justify-start gap-1">
                                <Pagination.Item>
                                    <Pagination.Previous
                                        aria-label={t("common.pagination.previous")}
                                        isDisabled={currentPage <= 1}
                                        onPress={() => dispatch(setChallengePageNumber(currentPage - 1))}
                                        className="cursor-pointer rounded-medium transition-colors hover:bg-default"
                                    >
                                        <Pagination.PreviousIcon />
                                    </Pagination.Previous>
                                </Pagination.Item>
                                {pageNumbers.map((pageNumber) => (
                                    <Pagination.Item key={pageNumber}>
                                        <Pagination.Link
                                            isActive={pageNumber === currentPage}
                                            onPress={() => dispatch(setChallengePageNumber(pageNumber))}
                                            className="cursor-pointer rounded-medium transition-colors hover:bg-default data-[active=true]:hover:bg-accent"
                                        >
                                            {pageNumber}
                                        </Pagination.Link>
                                    </Pagination.Item>
                                ))}
                                <Pagination.Item>
                                    <Pagination.Next
                                        aria-label={t("common.pagination.next")}
                                        isDisabled={currentPage >= totalPages}
                                        onPress={() => dispatch(setChallengePageNumber(currentPage + 1))}
                                        className="cursor-pointer rounded-medium transition-colors hover:bg-default"
                                    >
                                        <Pagination.NextIcon />
                                    </Pagination.Next>
                                </Pagination.Item>
                            </Pagination.Content>
                        </Pagination>
                    ) : null}
                    {/* passed every challenge of this lesson → hand off to the next lesson */}
                    {allChallengesPassed && next ? (
                        <UpNextCard
                            showCheck
                            eyebrow={t("content.upNext.challengesDoneEyebrow")}
                            title={t("content.upNext.nextLessonTitle", { title: next.title })}
                            description={t("content.upNext.nextLessonDesc")}
                            ctaLabel={t("content.upNext.nextLessonCta")}
                            onPress={() => router.push(next.href)}
                        />
                    ) : null}
                </div>
            </AsyncContent>
        </LabeledCard>
    )
}

