"use client"

import React, { useCallback } from "react"
import useSWR from "swr"
import { useAppSelector } from "@/redux/hooks"
import { InteractionBar } from "@/components/blocks/community/Discussion/InteractionBar"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { GraphQLHeadersKey, type GraphQLHeaders } from "@/modules/api/graphql/types"
import { mutateReactToContent } from "@/modules/api/graphql/mutations/mutation-react-to-content"
import { queryContentReactions } from "@/modules/api/graphql/queries/query-content-reactions"
import { ReactionType } from "@/modules/api/graphql/queries/types/discussion"
/**
 * Reaction footer for a lesson — the emotion picker + view count that belongs to
 * the CONTENT, rendered at the foot of the reading card (border-t divider) in the style of
 * Medium / Substack, not as an orphan strip between cards.
 *
 * Owns its own reaction summary SWR keyed identically to {@link import("./index").ContentDiscussion}
 * (`["content-discussion-reactions", contentId]`) so the two share one cache/request;
 * the discussion container keeps the realtime socket and revalidates this shared key
 * on `ContentReactionChanged`, so this bar live-updates without a second subscription.
 */
export const ContentReactionBar = () => {
    const contentId = useAppSelector((state) => state.content.entity?.id)
    // the enrolled-guard on the reactions resolver requires the X-Course-Id header
    const courseId = useAppSelector((state) => state.course.entity?.id)

    const courseHeaders: GraphQLHeaders | undefined = courseId
        ? { [GraphQLHeadersKey.XCourseId]: courseId }
        : undefined

    // shared key with ContentDiscussion → SWR dedupes to one request + one cache entry
    const reactionsSwr = useSWR(
        contentId && courseId ? ["content-discussion-reactions", contentId] : null,
        async () => {
            const response = await queryContentReactions({
                request: { contentId: contentId as string },
                headers: courseHeaders,
            })
            return response.data?.contentReactions.data
        },
    )

    const onReact = useCallback(async (type: ReactionType | null) => {
        if (!contentId || !courseId) {
            return
        }
        await mutateReactToContent({
            request: { contentId, type },
            headers: courseHeaders,
        })
        void reactionsSwr.mutate()
    }, [contentId, courseId, courseHeaders, reactionsSwr])

    // mirror the discussion guard: nothing to react to until both ids resolve
    if (!contentId || !courseId) {
        return null
    }

    // 2026-07-12: InteractionBar has no loading branch of its own, so rendering
    // it with `summary=undefined` while the fetch is in flight reads as "0
    // reactions" — then the real count pops in a beat later. Mirror the row
    // (pill trigger + view count) until the summary actually resolves.
    if (reactionsSwr.isLoading && !reactionsSwr.data) {
        return (
            <div>
                <div className="flex items-center justify-between gap-3">
                    <Skeleton className="h-8 w-24 rounded-full" />
                    <Skeleton className="h-4 w-10 rounded" />
                </div>
            </div>
        )
    }

    return (
        <InteractionBar
            summary={reactionsSwr.data ?? undefined}
            onReact={onReact}
            viewCount={reactionsSwr.data?.viewCount}
        />
    )
}

"use client"

import React, {
    useCallback,
    useEffect,
    useRef,
    useState,
} from "react"
import useSWR from "swr"
import useSWRInfinite from "swr/infinite"
import { useLocale } from "next-intl"
import { useAppSelector } from "@/redux/hooks"
import { Discussion } from "@/components/blocks/community/Discussion"
import { GraphQLHeadersKey, type GraphQLHeaders } from "@/modules/api/graphql/types"
import { mutateCreateComment } from "@/modules/api/graphql/mutations/mutation-create-comment"
import { mutateDeleteComment } from "@/modules/api/graphql/mutations/mutation-delete-comment"
import { mutateReactToComment } from "@/modules/api/graphql/mutations/mutation-react-to-comment"
import { mutateUpdateComment } from "@/modules/api/graphql/mutations/mutation-update-comment"
import { queryContentComments } from "@/modules/api/graphql/queries/query-content-comments"
import { queryContentReactions } from "@/modules/api/graphql/queries/query-content-reactions"
import { ReactionType, type CommentNode } from "@/modules/api/graphql/queries/types/discussion"
import { contentDiscussionSocketIoEventEmitter } from "@/hooks/socketio/useContentDiscussionSocketIoLifecycle"
import { PublicationEvent } from "@/hooks/socketio/enums/publication-event"
import { SubscriptionEvent } from "@/hooks/socketio/enums/subscription-event"
import { useContentDiscussionSocketIo } from "@/hooks/socketio/useContentDiscussionSocketIo"
import { type SubscribeContentDiscussionSocketIoPayload } from "@/hooks/socketio/types/content-discussion"

/** Page size for a parent's replies (loaded in one shot per parent). */
const REPLIES_LIMIT = 50

/** Page size for the paginated top-level comment list ("load more"). */
const COMMENTS_PAGE_SIZE = 10

/** Server → client discussion events this container reacts to (revalidate on any). */
const DISCUSSION_EVENTS: ReadonlyArray<SubscriptionEvent> = [
    SubscriptionEvent.CommentCreated,
    SubscriptionEvent.CommentUpdated,
    SubscriptionEvent.CommentDeleted,
    SubscriptionEvent.ContentReactionChanged,
    SubscriptionEvent.CommentReactionChanged,
]

/**
 * Container for the lesson-content threaded comments.
 *
 * Owns the comment data hooks (local SWR), the realtime socket subscription (for BOTH
 * comment and reaction events), and all comment persistence callbacks; renders the
 * presentational {@link Discussion} (comments only — frameless). Rendered below the reading
 * card by {@link LessonReader}. The reaction picker itself lives in the reading-card footer
 * ({@link ContentReactionBar}); this container only keeps the reaction SWR alive so socket
 * events refresh that bar via the shared cache key. `"use client"` for hooks + socket.
 */
export const ContentDiscussion = () => {
    const locale = useLocale()
    const contentId = useAppSelector((state) => state.content.entity?.id)
    const currentUser = useAppSelector((state) => state.user.user)
    const currentUserId = currentUser?.id ?? null
    // the enrolled-guard on every discussion resolver requires the X-Course-Id header
    const courseId = useAppSelector((state) => state.course.entity?.id)
    const socket = useContentDiscussionSocketIo()

    // course header sent on every discussion call so GraphQLMustEnrolledGuard passes
    const courseHeaders: GraphQLHeaders | undefined = courseId
        ? {
            [GraphQLHeadersKey.XCourseId]: courseId,
        }
        : undefined

    // replies loaded on demand, keyed by parent comment id
    const [repliesByParent, setRepliesByParent] = useState<Record<string, Array<CommentNode>>>({})
    // track which parents have replies loaded so realtime can refresh exactly those
    const loadedParentsRef = useRef<Set<string>>(new Set())

    // content-level reaction summary — kept here ONLY to revalidate on realtime
    // ContentReactionChanged events; the reaction bar itself ({@link ContentReactionBar},
    // rendered in the reading-card footer) holds an SWR with this SAME key, so a
    // socket-driven mutate() here refreshes the bar through the shared cache.
    const reactionsSwr = useSWR(
        contentId && courseId ? ["content-discussion-reactions", contentId] : null,
        async () => {
            const response = await queryContentReactions({
                request: {
                    contentId: contentId as string,
                },
                headers: courseHeaders,
            })
            return response.data?.contentReactions.data
        },
    )

    // top-level comments, paginated for "load more"; each page is one API call
    const commentsSwr = useSWRInfinite(
        (pageIndex, previousPageData) => {
            // need both content + course (header) before any call (else the guard 400s)
            if (!contentId || !courseId) {
                return null
            }
            // stop paginating once a page comes back empty (reached the end)
            if (previousPageData && (previousPageData.comments?.length ?? 0) === 0) {
                return null
            }
            // 1-based page in the key tuple
            return ["content-discussion-comments", contentId, pageIndex + 1] as const
        },
        async ([, , page]) => {
            const response = await queryContentComments({
                request: {
                    contentId: contentId as string,
                    page,
                    limit: COMMENTS_PAGE_SIZE,
                },
                headers: courseHeaders,
            })
            return response.data?.contentComments.data
        },
    )

    // flatten loaded pages into a single comment list; total comes from the first page
    const commentPages = commentsSwr.data ?? []
    const comments = commentPages.flatMap((page) => page?.comments ?? [])
    const total = commentPages[0]?.total ?? 0
    // more remain while we have not yet accumulated the reported total
    const hasMore = comments.length < total
    // the last requested page is still resolving
    const isLoadingMore = commentsSwr.isValidating
        && commentsSwr.data !== undefined
        && typeof commentsSwr.data[commentsSwr.size - 1] === "undefined"

    // fetch a parent's replies and cache them in state
    const loadReplies = useCallback(async (parentId: string) => {
        if (!contentId || !courseId) {
            return
        }
        const response = await queryContentComments({
            request: {
                contentId,
                parentCommentId: parentId,
                limit: REPLIES_LIMIT,
            },
            headers: courseHeaders,
        })
        const replies = response.data?.contentComments.data?.comments ?? []
        // remember this parent so realtime updates can refresh it later
        loadedParentsRef.current.add(parentId)
        setRepliesByParent((prev) => ({
            ...prev,
            [parentId]: replies,
        }))
    }, [contentId, courseId, courseHeaders])

    // re-fetch every already-loaded reply subtree (used after a realtime event)
    const reloadLoadedReplies = useCallback(() => {
        loadedParentsRef.current.forEach((parentId) => {
            void loadReplies(parentId)
        })
    }, [loadReplies])

    // single revalidation entry point for any discussion change
    const revalidateAll = useCallback(() => {
        void reactionsSwr.mutate()
        void commentsSwr.mutate()
        reloadLoadedReplies()
    }, [reactionsSwr, commentsSwr, reloadLoadedReplies])

    // join the content's discussion room (and re-join on reconnect)
    useEffect(() => {
        if (!contentId || !courseId) {
            return
        }
        const subscribe = () => {
            const payload: SubscribeContentDiscussionSocketIoPayload = {
                data: {
                    contentId,
                },
                locale,
            }
            socket.emit(PublicationEvent.SubscribeContentDiscussion, payload)
        }
        // subscribe now if already connected, and again on every (re)connect
        if (socket.connected) {
            subscribe()
        }
        socket.on("connect", subscribe)
        return () => {
            socket.off("connect", subscribe)
        }
    }, [socket, contentId, courseId, locale])

    // refetch affected data whenever a realtime event arrives for this content
    useEffect(() => {
        if (!contentId || !courseId) {
            return
        }
        const handler = (message: { data?: { contentId?: string } }) => {
            // ignore events for other contents sharing the same socket
            if (message?.data?.contentId !== contentId) {
                return
            }
            revalidateAll()
        }
        DISCUSSION_EVENTS.forEach((event) => contentDiscussionSocketIoEventEmitter.on(event, handler))
        return () => {
            DISCUSSION_EVENTS.forEach((event) => contentDiscussionSocketIoEventEmitter.off(event, handler))
        }
    }, [contentId, courseId, revalidateAll])

    // --- persistence callbacks (optimistic-free: mutate then revalidate) ---

    const onSubmitComment = useCallback(async (body: string) => {
        if (!contentId || !courseId) {
            return
        }
        await mutateCreateComment({
            request: {
                contentId,
                body,
            },
            headers: courseHeaders,
        })
        void commentsSwr.mutate()
    }, [contentId, courseId, courseHeaders, commentsSwr])

    const onReply = useCallback(async (parentId: string, body: string) => {
        if (!contentId || !courseId) {
            return
        }
        await mutateCreateComment({
            request: {
                contentId,
                parentCommentId: parentId,
                body,
            },
            headers: courseHeaders,
        })
        // reply count + the subtree both changed
        void commentsSwr.mutate()
        void loadReplies(parentId)
    }, [contentId, courseId, courseHeaders, commentsSwr, loadReplies])

    const onEdit = useCallback(async (commentId: string, body: string) => {
        if (!courseId) {
            return
        }
        await mutateUpdateComment({
            request: {
                commentId,
                body,
            },
            headers: courseHeaders,
        })
        revalidateAll()
    }, [courseId, courseHeaders, revalidateAll])

    const onDelete = useCallback(async (commentId: string) => {
        if (!courseId) {
            return
        }
        await mutateDeleteComment({
            request: {
                commentId,
            },
            headers: courseHeaders,
        })
        revalidateAll()
    }, [courseId, courseHeaders, revalidateAll])

    const onReactComment = useCallback(async (commentId: string, type: ReactionType | null) => {
        if (!courseId) {
            return
        }
        await mutateReactToComment({
            request: {
                commentId,
                type,
            },
            headers: courseHeaders,
        })
        revalidateAll()
    }, [courseId, courseHeaders, revalidateAll])

    const onLoadReplies = useCallback((parentId: string) => {
        void loadReplies(parentId)
    }, [loadReplies])

    // hide the whole section until both content id and course id are available —
    // course id is required by the GraphQLMustEnrolledGuard on every discussion resolver
    if (!contentId || !courseId) {
        return null
    }

    return (
        <Discussion
            // discussion data
            currentUserId={currentUserId}
            currentUser={currentUser ? { username: currentUser.username, avatar: currentUser.avatar } : null}
            comments={comments}
            total={total}
            isLoading={commentsSwr.isLoading}
            repliesByParent={repliesByParent}
            onSubmitComment={onSubmitComment}
            onReply={onReply}
            onEdit={onEdit}
            onDelete={onDelete}
            onReactComment={onReactComment}
            onLoadReplies={onLoadReplies}
            hasMore={hasMore}
            isLoadingMore={isLoadingMore}
            onLoadMore={() => void commentsSwr.setSize(commentsSwr.size + 1)}
        />
    )
}

/** Folder-matching alias (export-matches-folder) — keep `ContentDiscussion` as the public name. */
export { ContentDiscussion as Discussion }

"use client"

import React, {
    useMemo,
} from "react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    ContentBodySkeleton,
} from "../../ContentBodySkeleton"
import {
    useAutoMarkContentRead,
} from "../useAutoMarkContentRead"
import { MarkdownContent } from "@/components/blocks/rendering/MarkdownContent"
import { useAppSelector } from "@/redux/hooks"
import { listContentBodyLangs, pickContentBodyByLang, resolveContentBody } from "@/modules/types/entities/content-body"
import { resolveActiveProgrammingLang } from "@/modules/types/utils/programming-language"
import { ScrollArea } from "@/components/frames/ScrollArea"
import { StackV } from "@/components/frames/Stack"
import { useQueryContentStatusSwr } from "@/hooks/swr/api/graphql/queries/useQueryContentStatusSwr"
import { useQueryContentSwr } from "@/hooks/swr/api/graphql/queries/useQueryContentSwr"

/**
 * SCHEMA V2 content body. Shares the toolbar / favorite / mark-as-read behaviour with the
 * legacy body; the body itself is the V2 entry point and will render the per-language
 * `@starci/replace` payload once that format lands. For now it renders the resolved markdown.
 */
export const ContentBodyV2 = () => {
    const t = useTranslations()
    const locale = useLocale()
    const queryContentSwr = useQueryContentSwr()
    const contentFromRedux = useAppSelector((state) => state.content.entity)
    const routeContentId = useAppSelector((state) => state.content.id)
    const contentSnapshot = contentFromRedux ?? queryContentSwr.data
    const content =
        contentSnapshot?.id && routeContentId && contentSnapshot.id === routeContentId
            ? contentSnapshot
            : undefined
    const queryContentStatusSwr = useQueryContentStatusSwr()
    const isSkeleton = queryContentSwr.isLoading && !content

    // SCHEMA V2 lesson body: all languages fetched up-front as `bodies`; a tab switches which one
    // is rendered, resolved to the active locale.
    const langs = useMemo(
        () => listContentBodyLangs(content?.bodies),
        [content?.bodies],
    )
    const selectedLang = useAppSelector((state) => state.content.selectedProgrammingLang)
    const activeLang = useMemo(
        () => resolveActiveProgrammingLang(selectedLang, langs),
        [
            selectedLang,
            langs,
        ],
    )
    const activeBody = useMemo(
        () => resolveContentBody(pickContentBodyByLang(content?.bodies, activeLang), locale),
        [content?.bodies, activeLang, locale],
    )

    // Auto mark-as-read on scroll: silent progress tick at the bottom sentinel,
    // dwell-gated XP + feed grant. Returns the ref for the sentinel element below.
    const sentinelRef = useAutoMarkContentRead({
        contentId: content?.id,
        isRead: queryContentStatusSwr.data?.isRead,
        isLoading: isSkeleton,
    })

    if (isSkeleton) {
        return <ContentBodySkeleton variant="v2" />
    }

    return (
        <ScrollArea
            identity={{ tier: "block", component: "ContentBodyV2" }}
            axis="x"
            body={() => (
                <StackV
                    gap={6}
                    items={[
                        // the per-language switcher lives in the tab toolbar (LessonReader →
                        // ContentTabBar rightSlot); this body just renders the active language.
                        () => <MarkdownContent reading markdown={activeBody || t("content.empty")} />,
                        // Mark-as-read sentinel only — reactions + comments render OUTSIDE this
                        // reading card, as their own blocks. Hidden for premium (paywall follows).
                        // A zero-height measurement target, not a shape: it has nothing to compose.
                        ...(contentFromRedux?.isPremium
                            ? []
                            : [() => <div ref={sentinelRef} className="h-1" />]),
                    ]}
                />
            )}
        />
    )
}

"use client"

import { ClockIcon, FlameIcon } from "@phosphor-icons/react"
import _ from "lodash"
import React, {
    useMemo,
} from "react"
import {
    Typography,
} from "@heroui/react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import {
    ReadBadge,
} from "../ReadBadge"
import { Chip } from "@/components/atoms/chips/Chip"
import { CheckListCard, CheckListItem } from "@/components/blocks/cards/CheckListCard"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { ResponsiveBreadcrumb } from "@/components/blocks/navigation/ResponsiveBreadcrumb"
import type { ResponsiveBreadcrumbItem } from "@/components/blocks/navigation/ResponsiveBreadcrumb"
import { useAppSelector } from "@/redux/hooks"
import { getContentChallengeCount } from "@/modules/types/entities/content"
import { pathConfig } from "@/resources/path"

/**
 * Title, description and meta-chip row (reading time, challenges, read state)
 * for the loaded content view.
 *
 * Self-contained section (single-use): reads the content entity + read state
 * from redux; the container renders `<ContentHeader />` with no props.
 */
export const ContentHeader = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const content = useAppSelector((state) => state.content.entity)
    const course = useAppSelector((state) => state.course.entity)
    const courseDisplayId = useAppSelector((state) => state.course.displayId)
    const title = content?.title
    const description = content?.description
    const minutesRead = content?.minutesRead ?? 0

    /** Tier-1 breadcrumb (Home › Courses › <course> › Module) — lives in the PageHeader
     *  breadcrumb slot so the whole header is one unit (moved out of the route layout). */
    const breadcrumbItems = useMemo<Array<ResponsiveBreadcrumbItem>>(() => [
        { key: "home", label: t("nav.home"), onPress: () => router.push(pathConfig().locale().build()) },
        { key: "courses", label: t("nav.courses"), onPress: () => router.push(pathConfig().locale(locale).course().build()) },
        { key: "course", label: course?.title || t("nav.courses"), onPress: () => router.push(pathConfig().locale(locale).course(courseDisplayId).build()) },
        { key: "modules", label: t("modules.title"), onPress: () => router.push(pathConfig().locale(locale).course(courseDisplayId).learn().content().build()) },
    ], [t, locale, router, course?.title, courseDisplayId])

    /** Challenge count for the meta chip, tolerant of a missing entity. */
    const challengeCount = useMemo(
        () => getContentChallengeCount(content ?? {}),
        [content],
    )

    /** "What you'll learn" bullets, ordered (mount `# outcomes`); empty → callout hidden. */
    const outcomes = useMemo(
        () => _.sortBy(content?.outcomes ?? [], (outcome) => outcome.sortIndex),
        [content],
    )

    return (
        // header proper (title+desc+meta) → outcomes = header → content boundary = gap-10 (page-heading debt)
        <div className="flex flex-col gap-10">
            {/* header (tier 1/2) via the shared PageHeader block for cross-page consistency:
                title (H3) + description + a quiet meta-chip row (read state · time · challenges). */}
            <PageHeader
                breadcrumb={<ResponsiveBreadcrumb items={breadcrumbItems} />}
                title={title}
                description={description || undefined}
                meta={(
                    <div className="flex flex-wrap items-center gap-2">
                        <ReadBadge />
                        <Chip
                            tone="default"
                            icon={ClockIcon}
                            text={t("content.minutesRead", { minutes: minutesRead })}
                        />
                        <Typography type="body-xs" color="muted" className="flex items-center gap-1">
                            <FlameIcon className="size-4" />
                            {t("content.challengeCount", { count: challengeCount })}
                        </Typography>
                    </div>
                )}
            />
            {/* "What you'll learn" — first CONTENT block, gap-10 below the header above */}
            {outcomes.length > 0 ? (
                <LabeledCard frameless label={t("content.outcomes")}>
                    {/* shared check-list card (same as course value-props / challenge outputs) */}
                    <CheckListCard>
                        {outcomes.map((outcome) => (
                            <CheckListItem key={outcome.id}>
                                <Typography type="body-sm">{outcome.text}</Typography>
                            </CheckListItem>
                        ))}
                    </CheckListCard>
                </LabeledCard>
            ) : null}
        </div>
    )
}

"use client"

import React, { useMemo, useState } from "react"
import { Accordion } from "@heroui/react"
import { useTranslations } from "next-intl"
import { MarkdownContent } from "@/components/blocks/rendering/MarkdownContent"
import { StatusChip } from "@/components/blocks/chips/StatusChip"
import { useAppSelector } from "@/redux/hooks"
import { ProgrammingLanguageTabs } from "@/components/blocks/navigation/ProgrammingLanguageTabs"
import { ProgrammingLanguageTabsVariant } from "@/components/blocks/navigation/ProgrammingLanguageTabs/enums/programming-language-tabs-variant"

/** One captured E2E flow (shape mirrors the seeded content.e2eFlows jsonb). */
interface E2eFlow {
    id: string
    title: string
    lang?: string
    status: string
    /** Full proof markdown (commands, real output, conclusion) from .e2e/<lang>/flow-*.md. */
    markdown?: string
}

/**
 * E2eBody — the "E2E" tab. Renders each lesson's recorded Playwright proof
 * (`.e2e/<lang>/flow-*.md`) as read-only markdown: per-flow status badge, title
 * and the full proof (commands + real output + conclusion). When flows carry
 * multiple languages (websocket / file-upload run all four stacks) a language
 * filter is shown so learners can read each stack's real run.
 */
export const E2eBody = (): React.JSX.Element => {
    const t = useTranslations()
    const content = useAppSelector((state) => state.content.entity)
    const flows = (content?.e2eFlows as Array<E2eFlow> | null | undefined) ?? []

    const langs = useMemo(() => {
        const set = new Set(flows.map((f) => f.lang ?? "agnostic"))
        return Array.from(set)
    }, [flows])
    const hasLangFilter = langs.length > 1
    const [activeLang, setActiveLang] = useState<string>(langs[0] ?? "agnostic")

    const visible = hasLangFilter
        ? flows.filter((f) => (f.lang ?? "agnostic") === activeLang)
        : flows
    const passed = visible.filter((f) => f.status === "passed").length

    if (flows.length === 0) {
        return (
            <div className="py-10 text-center text-sm text-default-500">
                {t("content.e2e.empty")}
            </div>
        )
    }

    return (
        <div className="mx-auto flex max-w-3xl flex-col gap-6">
            <div className="flex flex-col gap-2">
                <p className="text-sm font-semibold">{t("content.e2e.title")}</p>
                <p className="text-sm text-default-500">
                    {t("content.e2e.passedCount", { passed, total: visible.length })}
                </p>
            </div>

            {hasLangFilter && (
                <ProgrammingLanguageTabs
                    variant={ProgrammingLanguageTabsVariant.Secondary}
                    availableLangs={langs}
                    selectedLang={activeLang}
                    onSelectLang={setActiveLang}
                    ariaLabel={t("content.e2e.languagesAria")}
                    surfaceBorder={false}
                />
            )}

            <Accordion variant="surface">
                {visible.map((flow) => {
                    const ok = flow.status === "passed"
                    return (
                        <Accordion.Item
                            key={`${flow.lang ?? "agnostic"}-${flow.id}`}
                            aria-label={flow.title}
                        >
                            <Accordion.Heading>
                                <Accordion.Trigger>
                                    <span className="flex items-center gap-2 text-start">
                                        <StatusChip tone={ok ? "success" : "danger"}>
                                            {ok ? t("content.e2e.statusPass") : t("content.e2e.statusFail")}
                                        </StatusChip>
                                        <span className="text-sm font-medium">{flow.title}</span>
                                    </span>
                                </Accordion.Trigger>
                            </Accordion.Heading>
                            <Accordion.Panel>
                                <Accordion.Body>
                                    {flow.markdown && <MarkdownContent markdown={flow.markdown} />}
                                </Accordion.Body>
                            </Accordion.Panel>
                        </Accordion.Item>
                    )
                })}
            </Accordion>
        </div>
    )
}

