"use client"

import React, {
    useMemo,
} from "react"
import { useTranslations } from "next-intl"
import {
    TaskSkeleton,
} from "./TaskSkeleton"
import {
    TaskLockedAlert,
} from "./TaskLockedAlert"
import {
    TaskBrief,
} from "./TaskBrief"
import {
    TaskCriteriaList,
} from "./TaskCriteriaList"
import {
    TaskCodeImplementations,
} from "./TaskCodeImplementations"
import { useAppSelector } from "@/redux/hooks"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { RichText } from "@/components/composites/viewers/RichText"
import { Typography } from "@/components/atoms/text/Typography"
import { StackV } from "@/components/frames/Stack"
import { useQueryMilestoneTaskSwr } from "@/hooks/swr/api/graphql/queries/useQueryMilestoneTaskSwr"
import { RelatedContentList } from "@/components/blocks/learn/RelatedContentList"

/**
 * Milestone task BRIEF column (left side of the split workspace).
 *
 * Reads the active task from redux and renders the reading content: title (H3) +
 * description, then the per-language brief (and the legacy public criteria /
 * implementation guides for old tasks that have no SCHEMA V2 brief). The
 * submission + evaluate + result actions live in the persistent right panel
 * ({@link import("./TaskSubmissionPanel").TaskSubmissionPanel}) — this column only
 * swaps per task; the panel persists across milestones. `"use client"` for redux.
 *
 * DEBT: `TaskSkeleton` still describes this column's shape a second time. Folding it
 * in means the whole reading column rests as itself, which is worth doing once the
 * sections below (`TaskBrief`, `TaskCriteriaList`) each carry their own resting state.
 */
export const Task = () => {
    const t = useTranslations()
    const milestoneTaskQuery = useQueryMilestoneTaskSwr()
    const milestoneEntities = useAppSelector((state) => state.milestone.entities)
    const selectedTaskDetail = useAppSelector((state) => state.milestone.selectedTaskDetail)
    const selectedTaskId = useAppSelector((state) => state.milestone.selectedTaskId)
    const course = useAppSelector((state) => state.course.entity)

    const taskFromMilestones = useMemo(() => {
        if (!selectedTaskId) return undefined
        for (const milestone of milestoneEntities) {
            const found = milestone.tasks?.find((task) => task.id === selectedTaskId)
            if (found) return found
        }
        return undefined
    }, [milestoneEntities, selectedTaskId])

    const displayTask = useMemo(() => {
        if (!selectedTaskId) return undefined
        if (selectedTaskDetail?.id === selectedTaskId) {
            return selectedTaskDetail
        }
        return taskFromMilestones
    }, [selectedTaskId, selectedTaskDetail, taskFromMilestones])

    const isSkeleton = !displayTask || milestoneTaskQuery.isLoading || !selectedTaskId
    if (isSkeleton) {
        return <TaskSkeleton />
    }

    // SCHEMA V2 tasks (with briefs) keep their rubric internal — the legacy public
    // criteria + codeImplementations show only for old tasks, under ONE labelled card
    // (frameless: the criteria accordion and the implementation guide frame themselves).
    const hasBriefs = (displayTask.briefs?.length ?? 0) > 0
    const showsRelated = Boolean(course?.id && course.displayId && displayTask.title)

    return (
        // tier-2 header (title H3 + desc) stands alone; the brief renders itself as the
        // "Guide" LabeledCard (TaskBrief), so each section here is its own labelled block.
        <StackV
            identity={{ tier: "block", component: "Task" }}
            gap={6}
            items={[
                () => (
                    <StackV
                        gap={3}
                        items={[
                            () => <Typography size="h3" weight="bold" text={displayTask.title} />,
                            ...(displayTask.description
                                ? [() => <RichText text={displayTask.description!} size="body-sm" color="muted" />]
                                : []),
                        ]}
                    />
                ),
                () => <TaskLockedAlert />,
                () => <TaskBrief />,
                ...(hasBriefs ? [] : [() => (
                    <LabeledCard label={t("task.criteriaTitle")} frameless>
                        <StackV
                            gap={5}
                            items={[
                                () => <TaskCriteriaList />,
                                () => <TaskCodeImplementations />,
                            ]}
                        />
                    </LabeledCard>
                )]),
                // quiet, self-hiding "read before you build" — the query is built from the
                // task's own title+description, no typing. Reading column only; the
                // submit/evaluate panel on the right is untouched.
                ...(showsRelated ? [() => (
                    <RelatedContentList
                        courseId={course!.id}
                        courseDisplayId={course!.displayId!}
                        query={`${displayTask.title} ${displayTask.description ?? ""}`}
                        excludeId={displayTask.id}
                        label={t("task.relatedContent.label")}
                    />
                )] : []),
            ]}
        />
    )
}

"use client"

import React from "react"
import { cn, Typography } from "@heroui/react"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Props for {@link ListRow}. */
export interface ListRowProps extends WithClassNames<undefined> {
    /**
     * Optional leading node rendered before the text column, kept at its
     * intrinsic size (icon or avatar). Does not shrink.
     */
    leading?: React.ReactNode
    /**
     * Primary line of the row. Rendered as medium-weight foreground text and
     * truncated to a single line when it overflows.
     */
    title: React.ReactNode
    /**
     * Optional secondary line shown beneath the title in muted, smaller text and
     * truncated to a single line.
     */
    subtitle?: React.ReactNode
    /**
     * Optional right-aligned metadata (chips / counts / timestamps) rendered
     * before the trailing node.
     */
    meta?: React.ReactNode
    /**
     * Optional far-right node, typically a chevron or inline action, rendered
     * after the meta content.
     */
    trailing?: React.ReactNode
    /**
     * When true, adds a bottom border so consecutive same-type rows read as a
     * separated list. Omit on the final row of a group.
     */
    divider?: boolean
    /**
     * Optional press handler. When provided (or {@link ListRowProps.href} is
     * set) the row becomes interactive with a hover surface and is keyboard /
     * screen-reader accessible.
     */
    onPress?: () => void
    /**
     * Optional link target. When provided the row renders as an anchor so the
     * whole row navigates on click.
     */
    href?: string
}

/**
 * Generic GitHub-style list row designed to live inside a
 * {@link import("@/components/blocks/cards/SectionCard").SectionCard}. Lays out an optional
 * leading icon/avatar, a title + optional subtitle text column, and a
 * right-aligned meta + trailing cluster. Purely presentational: text and
 * handlers arrive via props so the row stays store-free and reusable.
 *
 * @param props - {@link ListRowProps}
 */
export const ListRow = ({
    leading,
    title,
    subtitle,
    meta,
    trailing,
    divider = false,
    onPress,
    href,
    className,
}: ListRowProps) => {
    const isPressable = Boolean(onPress || href)

    const content = (
        <>
            {leading ? <div className="shrink-0">{leading}</div> : null}
            <div className="flex min-w-0 flex-col gap-0">
                <Typography type="body-sm" weight="medium" truncate>
                    {title}
                </Typography>
                {subtitle ? (
                    <Typography type="body-xs" color="muted" truncate>
                        {subtitle}
                    </Typography>
                ) : null}
            </div>
            {meta || trailing ? (
                <div className="ml-auto flex shrink-0 items-center gap-2">
                    {meta}
                    {trailing}
                </div>
            ) : null}
        </>
    )

    const baseClassName = cn(
        "flex min-w-0 items-center gap-3 py-2",
        divider && "border-b border-separator",
        isPressable &&
            "rounded-2xl transition-colors hover:bg-surface-secondary focus-visible:bg-surface-secondary focus-visible:outline-none",
        className,
    )

    if (href) {
        return (
            <a href={href} onClick={onPress} className={baseClassName}>
                {content}
            </a>
        )
    }

    if (onPress) {
        return (
            <div
                role="button"
                tabIndex={0}
                onClick={onPress}
                onKeyDown={(event) => {
                    if (event.key === "Enter" || event.key === " ") {
                        event.preventDefault()
                        onPress()
                    }
                }}
                className={cn(baseClassName, "cursor-pointer")}
            >
                {content}
            </div>
        )
    }

    return <div className={baseClassName}>{content}</div>
}

"use client"

import React, {
    useEffect,
    useState,
} from "react"
import {
    useTranslations,
} from "next-intl"
import { Card, CardContent } from "@heroui/react"
import type { QueryActiveAdvertisementData, AdvertisementImageMedia, AdvertisementVideoMedia, AdvertisementCarouselMedia } from "@/modules/api/graphql/queries/types/active-advertisement"
import { AdvertisementMediaType } from "@/modules/api/graphql/queries/types/active-advertisement"

/** Props for {@link AdBanner}. */
export interface AdBannerProps {
    /** The active advertisement to render. */
    ad: QueryActiveAdvertisementData
}

/** Default carousel auto-advance interval (ms) when the ad omits one. */
const DEFAULT_CAROUSEL_INTERVAL = 4000

/**
 * Renders a single advertisement banner, branching on `mediaType`
 * (image / video / carousel). The whole card is ONE pressable target linking
 * to `ad.linkUrl` in a new tab (media + title + CTA all share the same
 * click-target — no duplicate affordances); a "Sponsored" tag shows for paid
 * slots. `"use client"` for the carousel timer + video element.
 * @param props - the active ad
 */
export const AdBanner = ({
    ad}: AdBannerProps) => {
    const t = useTranslations()

    // carousel slide index (only used when mediaType === carousel)
    const [slide, setSlide] = useState(0)
    const carousel = ad.mediaType === AdvertisementMediaType.Carousel
        ? (ad.media as AdvertisementCarouselMedia)
        : null

    // auto-advance the carousel; cleared on unmount / when the ad changes
    useEffect(
        () => {
            if (!carousel || carousel.slides.length <= 1) {
                return
            }
            const interval = setInterval(
                () => setSlide((current) => (current + 1) % carousel.slides.length),
                carousel.intervalMs ?? DEFAULT_CAROUSEL_INTERVAL,
            )
            return () => clearInterval(interval)
        },
        [
            carousel,
        ],
    )

    /** The media area — one branch per media kind. */
    const renderMedia = () => {
        switch (ad.mediaType) {
        case AdvertisementMediaType.Image: {
            const media = ad.media as AdvertisementImageMedia
            return (
                <img
                    src={media.url}
                    alt={ad.title}
                    className="aspect-video w-full rounded-medium object-cover"
                />
            )
        }
        case AdvertisementMediaType.Video: {
            const media = ad.media as AdvertisementVideoMedia
            return (
                <video
                    src={media.url}
                    poster={media.poster}
                    autoPlay={media.autoplay}
                    loop={media.loop}
                    // autoplay only works muted; default muted on unless told otherwise
                    muted={media.muted ?? media.autoplay ?? true}
                    playsInline
                    controls={!media.autoplay}
                    className="aspect-video w-full rounded-medium object-cover"
                />
            )
        }
        case AdvertisementMediaType.Carousel: {
            const media = ad.media as AdvertisementCarouselMedia
            const current = media.slides[slide] ?? media.slides[0]
            return (
                <div className="relative">
                    <img
                        src={current?.url}
                        alt={ad.title}
                        className="aspect-video w-full rounded-medium object-cover"
                    />
                    {/* slide dots */}
                    {media.slides.length > 1 ? (
                        <div className="absolute inset-x-0 bottom-2 flex justify-center gap-2">
                            {media.slides.map((item, index) => (
                                <span
                                    key={item.url}
                                    className={`size-1.5 rounded-full ${
                                        index === slide ? "bg-white" : "bg-white/50"
                                    }`}
                                />
                            ))}
                        </div>
                    ) : null}
                </div>
            )
        }
        default:
            return null
        }
    }

    return (
        <Card className={""}>
            {/* whole card = ONE pressable target → ad.linkUrl (no nested
                affordances competing for the same destination) */}
            <a
                href={ad.linkUrl}
                target="_blank"
                rel="noopener noreferrer"
                className="block"
            >
                <CardContent className="flex flex-col gap-3">
                    {/* "Sponsored" / "Ad" tag row */}
                    <div className="flex items-center justify-between">
                        <span className="text-xs uppercase tracking-wide text-muted">
                            {ad.sponsorName
                                ? t("dashboard.sponsoredBy", {
                                    sponsor: ad.sponsorName,
                                })
                                : t("dashboard.sponsored")}
                        </span>
                    </div>

                    {renderMedia()}

                    <div className="text-sm font-semibold text-foreground">
                        {ad.title}
                    </div>

                    {/* presentational CTA affordance only — the anchor above
                        already owns the click, so this is not a real
                        (nested) interactive control */}
                    {ad.ctaText ? (
                        <span className="block w-full rounded-medium border border-default px-4 py-2 text-center text-sm font-medium text-foreground">
                            {ad.ctaText}
                        </span>
                    ) : null}
                </CardContent>
            </a>
        </Card>
    )
}

import React from "react"
import { Typography } from "@heroui/react"
import { CaretRightIcon } from "@phosphor-icons/react"

/** Props for the {@link ArchitectureFlow} block. */
export interface ArchitectureFlowProps {
    /** Ordered node labels rendered as boxes joined by caret connectors (left → right). */
    nodes: ReadonlyArray<string>
}

/**
 * A compact, coded mini-architecture diagram: labelled node boxes joined by caret
 * connectors — a representative system flow (e.g. `Client → Fanout → Cache → DB`).
 * Pure CSS, no image. Wraps on narrow widths. Tier-3 block — owns styling, content
 * via props. Use to visualise "the real systems you build" without screenshots.
 *
 * @param props - {@link ArchitectureFlowProps}
 */
export const ArchitectureFlow = ({ nodes}: ArchitectureFlowProps) => {
    return (
        <div className={"flex flex-wrap items-center gap-2"}>
            {nodes.map((node, index) => (
                <React.Fragment key={`${node}-${index}`}>
                    {index > 0 ? (
                        <CaretRightIcon aria-hidden focusable="false" className="size-3 shrink-0 text-muted" />
                    ) : null}
                    <span className="rounded-md border border-default bg-default px-2 py-1">
                        <Typography type="code" className="text-xs">
                            {node}
                        </Typography>
                    </span>
                </React.Fragment>
            ))}
        </div>
    )
}

