import React, { useEffect, useState } from "react"
import { type SkeletonProps } from "@/components/frames/_slot"
import {
    Button as HeroButton,
    Dropdown,
    Kbd,
    Label,
    Popover,
    PopoverContent,
} from "@heroui/react"
import {
    BellIcon,
    ChecksIcon,
    CircleIcon,
    MagnifyingGlassIcon,
    ShoppingCartIcon,
    SidebarSimpleIcon,
    UserIcon,
} from "@phosphor-icons/react"
import { NavbarLanguageMenu } from "./NavbarLanguageMenu"
import { NavbarThemeSwitch } from "./NavbarThemeSwitch"
import type { NavbarLanguageOption } from "./types"
import { Logo } from "@/components/atoms/display/Logo"
import { Avatar } from "@/components/atoms/display/Avatar"
import { Badge } from "@/components/atoms/display/Badge"
import { Divider } from "@/components/atoms/display/Divider"
import { UserCell } from "@/components/composites/lists/UserCell"
import { Typography } from "@/components/atoms/text/Typography"
import { Button, type IconComponent } from "@/components/atoms/buttons/Button"
import { ButtonRadioGroup } from "@/components/composites/buttons/ButtonRadioGroup"
import { InputButtonLike } from "@/components/composites/buttons/InputButtonLike"
import { AsyncContent } from "@/components/composites/async/AsyncContent"
import { ListRow } from "@/components/composites/lists/List"
import { DrawerShell } from "@/components/composites/layout/DrawerShell"
import { HideAbove } from "@/components/frames/HideAbove"
import { NavbarFrame } from "@/components/frames/NavbarFrame"
import { ScrollArea } from "@/components/frames/ScrollArea"
import { ShowFrom } from "@/components/frames/ShowFrom"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * `Navbar` — the sticky top app bar. Two structural leaves: the desktop row
 * (route pills + inline language/theme) and the mobile collapsed row (icon bar
 * + drawer trigger) are different compositions. Signed-in vs guest, empty vs
 * busy badges, and drawer open vs closed are data, so they are states inside
 * the matching leaf. Both leaves render the same component (the `@app-md:`
 * rules live in its className), so the mobile leaf pins a narrow
 * `renderClassName` frame to force the collapsed row into view.
 */

/** One top-level desktop/mobile route entry. */
export interface NavLinkItem {
    /** Stable id — also the value reported to the desktop pill group. */
    id: string
    /** Visible label, already localized by the caller. */
    label: string
    /** Whether this entry matches the current route. */
    isActive?: boolean
    /** Fired when the entry is picked (desktop pill or mobile drawer row). */
    onPress: () => void
}

export type { NavbarLanguageOption }

/** One row in the notification popover's list. */
export interface NavbarNotificationItem {
    /** Stable id. */
    id: string
    /** Primary line, already resolved/translated by the caller. */
    title: string
    /** Optional secondary line. */
    subtitle?: string
    /** Already-formatted relative time (e.g. "3 hours ago") — locale math is app wiring. */
    timeLabel: string
    /** `false` renders the unread dot leading the row. */
    isRead: boolean
}

/** Notification bell data + the callbacks its popover fires. */
export interface NavbarNotificationsData {
    /** Drives the bell's count badge; `0` hides it. */
    unreadCount: number
    /** Most-recent page, newest first. */
    items: Array<NavbarNotificationItem>
    /** `true` while the FIRST page is loading (no cache yet). */
    isLoading: boolean
    /** Already-translated error message; `null`/absent → no error branch. */
    error?: string | null
    /** Fired when a row is pressed (mark-read + navigate is the caller's job). */
    onItemPress: (item: NavbarNotificationItem) => void
    /** Fired by the header's bulk action. */
    onMarkAllRead: () => void
    /** Fired by the footer's deep-link action. */
    onSeeAll: () => void
    /** Fired by the error branch's retry button. */
    onRetry: () => void
}

/** The signed-in viewer, as far as the account menu's header row needs to know. */
export interface NavbarAccountUser {
    /** Drives the avatar fallback + the header row's primary line. */
    username: string
    /** Shown as the header row's secondary `@handle` line. */
    email?: string
    /** Uploaded avatar URL; `Avatar`'s own fallback chain covers the rest. */
    avatarUrl?: string | null
}

/** One row of the account dropdown's action list — covers BOTH the guest rows
 * (sign in / sign up) and the authed rows (dashboard / profile / sign out); the
 * caller decides which set to hand in via {@link NavbarAccountData.isAuthed}. */
export interface NavbarAccountMenuItem {
    /** Stable id. */
    id: string
    /** Visible label, already localized. */
    label: string
    /** Leading glyph, atom-scale (`size-5`) as this block owns the icon column. */
    icon?: IconComponent
    /** `true` → renders in the destructive tone (e.g. "Sign out"). */
    isDanger?: boolean
    /** Fired when the row is pressed. */
    onPress: () => void
}

/** Account menu data + the one state flag its header/list branch on. */
export interface NavbarAccountData {
    /** `true` → header shows {@link NavbarAccountData.user}; `false` → the guest prompt. */
    isAuthed: boolean
    /** Present only when {@link NavbarAccountData.isAuthed}. */
    user?: NavbarAccountUser
    /** `true` while the shared "who am I" query has not resolved yet. */
    isLoading: boolean
    /** The action rows below the header (see {@link NavbarAccountMenuItem}). */
    menuItems: Array<NavbarAccountMenuItem>
}

/** Props for {@link Navbar}. */
export interface NavbarProps {
    /** Fired when the brand mark is pressed — routing "home" is the caller's call. */
    onLogoPress: () => void
    /** Route entries — the ONE source both the desktop pills and the mobile drawer read. */
    navItems: Array<NavLinkItem>

    /** Placeholder text for the desktop search field; doubles as the mobile icon's aria-label. */
    searchPlaceholder: string
    /** Already-formatted shortcut hint (e.g. `"Ctrl K"`, `"⌘K"`) — OS detection is app wiring. */
    shortcutLabel: string
    /** Fired when the search trigger (field or icon) is pressed, or Ctrl/Cmd+K is hit. */
    onSearchPress: () => void

    /** Selectable locales. */
    languages: Array<NavbarLanguageOption>
    /** Currently active locale — must match one entry's `code`. */
    activeLocale: string
    /** Fired with the newly picked locale code. */
    onLocaleChange: (code: string) => void

    /** Dark-mode on/off (controlled). */
    isDarkMode: boolean
    /** Fired with the new on/off state. */
    onThemeToggle: (isDark: boolean) => void

    /** Items currently in the cart; `0` hides the count badge. */
    cartCount: number
    /** Fired when the cart icon is pressed. */
    onCartPress: () => void

    /** Notification bell data + callbacks. */
    notifications: NavbarNotificationsData
    /** Account menu data + callbacks. */
    account: NavbarAccountData

    /** Whether the mobile navigation drawer is open. Controlled by the caller. */
    isMobileDrawerOpen: boolean
    /** Fired on backdrop click / Escape / the close button / a row navigating away. */
    onMobileDrawerOpenChange: (isOpen: boolean) => void
}

interface ShortcutHintProps {
    shortcutLabel: string
}
const ShortcutHint = ({ shortcutLabel }: ShortcutHintProps) => (
    <Kbd><Kbd.Content>{shortcutLabel}</Kbd.Content></Kbd>
)

/**
 * The sticky top app bar. See the file header for the full reuse ledger and the
 * judgement calls this port makes.
 *
 * @param props - {@link NavbarProps}
 */
const Navbar = ({
    onLogoPress,
    navItems,
    searchPlaceholder,
    shortcutLabel,
    onSearchPress,
    languages,
    activeLocale,
    onLocaleChange,
    isDarkMode,
    onThemeToggle,
    cartCount,
    onCartPress,
    notifications,
    account,
    isMobileDrawerOpen,
    onMobileDrawerOpenChange,
}: NavbarProps) => {
    const [isNotificationsOpen, setNotificationsOpen] = useState(false)
    const [isAccountOpen, setAccountOpen] = useState(false)

    // Ctrl/Cmd+K — carried over from the real component (see file header): it only
    // ever calls a prop this block already owns, so it is not new app wiring.
    useEffect(() => {
        const onKeyDown = (event: KeyboardEvent) => {
            const isK = event.key?.toLowerCase() === "k"
            if (!isK || !(event.ctrlKey || event.metaKey)) return
            event.preventDefault()
            onSearchPress()
        }
        window.addEventListener("keydown", onKeyDown)
        return () => window.removeEventListener("keydown", onKeyDown)
    }, [onSearchPress])

    const activeNavId = navItems.find((item) => item.isActive)?.id ?? ""

    const notificationSkeletonRows = [0, 1, 2].map((row) => (
        <ListRow key={row} title="" isSkeleton />
    ))

    const notificationRows = notifications.items.map((item, index) => (
        <ListRow
            key={item.id}
            leading={!item.isRead ? (
                ({ isSkeleton }: SkeletonProps) =>
                    isSkeleton ? null : <CircleIcon weight="fill" aria-hidden focusable="false" className="size-2 text-accent-soft-foreground" />
            ) : undefined}
            title={item.title}
            subtitle={item.subtitle}
            meta={() => <Typography size="xs" color="muted" text={item.timeLabel} />}
            onPress={() => notifications.onItemPress(item)}
            divider={index < notifications.items.length - 1}
        />
    ))

    const accountMenuHeader = (
        <AsyncContent
            isLoading={account.isLoading}
            skeleton={() => <UserCell username="" isSkeleton />}
            content={() => (account.isAuthed && account.user ? (
                <UserCell
                    username={account.user.username}
                    avatar={account.user.avatarUrl}
                    handle={account.user.email}
                />
            ) : (
                <StackH
                    principle="icon-text"
                    explain="Avatar beside its guest prompt — not name-handle, because this pairs a glyph with instructional text rather than a name/handle identity."
                    items={[
                        () => <Avatar icon={UserIcon} fallback="icon" />,
                        () => <Typography size="sm" color="muted" text="Sign in to save your learning progress" />,
                    ]}
                />
            ))}
        />
    )

    const mobileNavRows = navItems.map((item) => (
        <Button
            key={item.id}
            variant={item.isActive ? "secondary" : "ghost"}
            align="start"
            label={item.label}
            onPress={() => {
                item.onPress()
                onMobileDrawerOpenChange(false)
            }}
        />
    ))

    return (
        <NavbarFrame
            identity={{ tier: "block", component: "Navbar" }}
            primary={() => (
                <StackH
                    principle="block-boundary"
                    explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                    items={[
                        () => (
                            <StackH
                                principle="flex-action"
                                explain="Groups brand mark and desktop route pills on one horizontal peer row so they share a single hit baseline."
                                items={[
                                    () => (
                                        <span
                                            role="button"
                                            tabIndex={0}
                                            aria-label="StarCi Academy"
                                            onClick={onLogoPress}
                                            onKeyDown={(event) => {
                                                if (event.key === "Enter" || event.key === " ") onLogoPress()
                                            }}
                                            className="inline-flex cursor-pointer"
                                        >
                                            <Logo />
                                        </span>
                                    ),
                                    () => (
                                        <ShowFrom
                                            at="md"
                                            body={() => (
                                                <ButtonRadioGroup
                                                    items={navItems.map((item) => ({
                                                        value: item.id,
                                                        content: <Typography size="sm" text={item.label} />,
                                                    }))}
                                                    value={activeNavId}
                                                    onChange={(id) => navItems.find((item) => item.id === id)?.onPress()}
                                                    ariaLabel="Main navigation"
                                                />
                                            )}
                                        />
                                    ),
                                ]}
                            />
                        ),
                        () => (
                            <StackH
                                principle="flex-action"
                                explain="Groups search, locale, theme, cart, account, and mobile menu triggers on one horizontal peer row so they share a single hit baseline."
                                items={[
                                    () => (
                                        <ShowFrom
                                            at="md"
                                            body={() => (
                                                <InputButtonLike
                                                    placeholder={searchPlaceholder}
                                                    icon={MagnifyingGlassIcon}
                                                    suffix={() => <ShortcutHint shortcutLabel={shortcutLabel} />}
                                                    onPress={onSearchPress}
                                                />
                                            )}
                                        />
                                    ),
                                    () => (
                                        <HideAbove
                                            at="md"
                                            body={() => (
                                                <Button
                                                    isIconOnly
                                                    variant="ghost"
                                                    prefixIcon={MagnifyingGlassIcon}
                                                    ariaLabel={searchPlaceholder}
                                                    onPress={onSearchPress}
                                                />
                                            )}
                                        />
                                    ),
                                    () => (
                                        <ShowFrom
                                            at="md"
                                            body={() => (
                                                <StackH
                                                    principle="flex-action"
                                                    explain="Groups language and theme controls on one horizontal peer row so they share a single hit baseline."
                                                    items={[
                                                        () => (
                                                            <NavbarLanguageMenu
                                                                languages={languages}
                                                                activeLocale={activeLocale}
                                                                onLocaleChange={onLocaleChange}
                                                            />
                                                        ),
                                                        () => (
                                                            <NavbarThemeSwitch
                                                                isDarkMode={isDarkMode}
                                                                onThemeToggle={onThemeToggle}
                                                            />
                                                        ),
                                                    ]}
                                                />
                                            )}
                                        />
                                    ),
                                    () => (
                                        <HeroButton
                                            isIconOnly
                                            variant="tertiary"
                                            className="rounded-full"
                                            aria-label="Cart"
                                            onPress={onCartPress}
                                        >
                                            <Badge color="accent" count={cartCount}>
                                                <ShoppingCartIcon className="size-5" />
                                            </Badge>
                                        </HeroButton>
                                    ),
                                    ...(account.isAuthed
                                        ? [
                                            () => (
                                                <Popover isOpen={isNotificationsOpen} onOpenChange={setNotificationsOpen}>
                                                    <HeroButton
                                                        isIconOnly
                                                        variant="tertiary"
                                                        className="rounded-full"
                                                        aria-label="Notifications"
                                                    >
                                                        <Badge color="danger" count={notifications.unreadCount}>
                                                            <BellIcon className="size-5" />
                                                        </Badge>
                                                    </HeroButton>
                                                    <PopoverContent placement="bottom right" className="w-[360px]">
                                                        {/* inset-exception: vendor popover body padding, wider than tall, not a surface inset */}
                                                        <StackV
                                                            principle="control-pad"
                                                            explain="Control hit-area inset — not row-pad, because this pads a single interactive control rather than a full content row."
                                                            items={[
                                                                () => (
                                                                    <StackH
                                                                        principle="sibling-stack"
                                                                        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                                                        items={[
                                                                            () => <Typography size="sm" weight="bold" text="Notifications" />,
                                                                            ...(notifications.unreadCount > 0
                                                                                ? [
                                                                                    () => (
                                                                                        <Button
                                                                                            isIconOnly
                                                                                            variant="ghost"
                                                                                            size="sm"
                                                                                            prefixIcon={ChecksIcon}
                                                                                            ariaLabel="Mark all as read"
                                                                                            onPress={notifications.onMarkAllRead}
                                                                                        />
                                                                                    ),
                                                                                ]
                                                                                : []),
                                                                        ]}
                                                                    />
                                                                ),
                                                                () => (
                                                                    <AsyncContent
                                                                        isLoading={notifications.isLoading && notifications.items.length === 0}
                                                                        skeleton={() => (
                                                                            <StackV
                                                                                principle="sibling-stack"
                                                                                explain="Same-kind peer stack of notification skeleton rows — not group-boundary, because rows are repeating siblings rather than section groups."
                                                                                items={[() => notificationSkeletonRows]}
                                                                            />
                                                                        )}
                                                                        isEmpty={notifications.items.length === 0}
                                                                        emptyContent={{ title: "No notifications yet" }}
                                                                        error={notifications.error}
                                                                        errorContent={{
                                                                            title: notifications.error ?? "",
                                                                            onRetry: notifications.onRetry,
                                                                            retryLabel: "Try again",
                                                                        }}
                                                                        content={() => (
                                                                            <ScrollArea
                                                                                axis="y"
                                                                                principle="flex-fill"
                                                                                explain="Owns local vertical overflow for the notification list so long threads do not grow the popover past the viewport."
                                                                                body={() => (
                                                                                    <StackV
                                                                                        principle="sibling-stack"
                                                                                        explain="Same-kind peer stack of notification rows — not group-boundary, because rows are repeating siblings rather than section groups."
                                                                                        items={[() => notificationRows]}
                                                                                    />
                                                                                )}
                                                                            />
                                                                        )}
                                                                    />
                                                                ),
                                                                () => (
                                                                    <Button
                                                                        variant="ghost"
                                                                        size="sm"
                                                                        label="See all"
                                                                        onPress={notifications.onSeeAll}
                                                                    />
                                                                ),
                                                            ]}
                                                        />
                                                    </PopoverContent>
                                                </Popover>
                                            ),
                                        ]
                                        : []),
                                    () => (
                                        <Dropdown isOpen={isAccountOpen} onOpenChange={setAccountOpen}>
                                            <HeroButton
                                                isIconOnly
                                                variant="tertiary"
                                                className="rounded-full"
                                                aria-label="Account"
                                            >
                                                {account.isAuthed ? (
                                                    <Avatar
                                                        size="sm"
                                                        name={account.user?.username}
                                                        src={account.user?.avatarUrl ?? undefined}
                                                        seed={account.user?.email ?? account.user?.username}
                                                    />
                                                ) : (
                                                    <UserIcon className="size-5" />
                                                )}
                                            </HeroButton>
                                            <Dropdown.Popover placement="bottom right" className="w-[300px]">
                                                <StackV
                                                    principle="cell-pad"
                                                    explain="Tight cell inset — not card-padding, because this sits inside a dense table or list cell rather than a card body."
                                                    body={() => accountMenuHeader}
                                                />
                                                <Divider />
                                                <Dropdown.Menu aria-label="Account">
                                                    <Dropdown.Section>
                                                        {account.menuItems.map((item) => {
                                                            const Icon = item.icon
                                                            return (
                                                                <Dropdown.Item
                                                                    key={item.id}
                                                                    id={item.id}
                                                                    textValue={item.label}
                                                                    className={item.isDanger ? "text-danger-soft-foreground" : undefined}
                                                                    onPress={item.onPress}
                                                                >
                                                                    {Icon ? <Icon className="size-5" /> : null}
                                                                    <Label className={item.isDanger ? "text-danger-soft-foreground" : undefined}>{item.label}</Label>
                                                                </Dropdown.Item>
                                                            )
                                                        })}
                                                    </Dropdown.Section>
                                                </Dropdown.Menu>
                                            </Dropdown.Popover>
                                        </Dropdown>
                                    ),
                                    () => (
                                        <HideAbove
                                            at="md"
                                            body={() => (
                                                <Button
                                                    isIconOnly
                                                    variant="ghost"
                                                    prefixIcon={SidebarSimpleIcon}
                                                    ariaLabel="Open mobile menu"
                                                    onPress={() => onMobileDrawerOpenChange(true)}
                                                />
                                            )}
                                        />
                                    ),
                                ]}
                            />
                        ),
                    ]}
                />
            )}
            secondary={() => (
                /* mobile navigation drawer — the ONE local (non-overlay-store) drawer this run's
                    contract calls for; every other overlay in this system opens through the global
                    store (see canon Rule 13), this one is controlled straight by the caller. */
                <DrawerShell
                    isOpen={isMobileDrawerOpen}
                    onOpenChange={onMobileDrawerOpenChange}
                    placement="right"
                    title="Mobile menu"
                    body={() => (
                        <StackV
                            principle="group-boundary"
                            explain="Separates mobile route list from language/theme controls so each region keeps its own seam owner — not sibling-stack, because these are distinct section roles rather than repeating peers."
                            items={[
                                () => (
                                    <StackV
                                        principle="sibling-stack"
                                        explain="Same-kind peer stack of mobile route rows — not group-boundary, because rows are repeating siblings rather than section groups."
                                        items={[() => mobileNavRows]}
                                    />
                                ),
                                () => <Divider />,
                                () => (
                                    <StackV
                                        principle="sibling-stack"
                                        explain="Same-kind peer stack of language and theme rows — not group-boundary, because these are repeating preference peers rather than section groups."
                                        items={[
                                            () => (
                                                <StackH
                                                    principle="sibling-stack"
                                                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                                    items={[
                                                        () => <Typography size="sm" text="Language" />,
                                                        () => (
                                                            <NavbarLanguageMenu
                                                                languages={languages}
                                                                activeLocale={activeLocale}
                                                                onLocaleChange={onLocaleChange}
                                                            />
                                                        ),
                                                    ]}
                                                />
                                            ),
                                            () => (
                                                <StackH
                                                    principle="sibling-stack"
                                                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                                    items={[
                                                        () => <Typography size="sm" text="Theme" />,
                                                        () => (
                                                            <NavbarThemeSwitch
                                                                isDarkMode={isDarkMode}
                                                                onThemeToggle={onThemeToggle}
                                                            />
                                                        ),
                                                    ]}
                                                />
                                            ),
                                        ]}
                                    />
                                ),
                            ]}
                        />
                    )}
                />
            )}
        />
    )
}

export { Navbar }

"use client"

import React, {
    useEffect,
    useRef,
} from "react"
import type {
    ReactNode,
} from "react"
import {
    Accordion,
    Button,
    Input,
    Label,
    ScrollShadow,
    TextField,
    Typography,
    cn,
} from "@heroui/react"
import {
    ArrowRightIcon,
} from "@phosphor-icons/react"
import type {
    WithClassNames,
} from "@/modules/types/base/class-name"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { ContentMapRow } from "@/components/blocks/navigation/ContentMapRow"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"

/**
 * Placeholder group count the co-located skeleton mirrors while `isSkeleton`
 * is set — the real HeroUI `Accordion` and `ContentMapRow` below take no
 * `isSkeleton` of their own (missingSkeletonSupport), so this swaps in the
 * canonical `Skeleton.Accordion` piece right where the real tree sits.
 */
const SKELETON_GROUP_COUNT = 3

/** One selectable row inside an {@link OutlineRailGroup}. */
export interface OutlineRailItem {
    /** Stable id (accordion item key / scroll target). */
    id: string
    /** Row title (the row's accessible name). */
    title: string
    /** Highlights the row as the one currently open (accent tint). */
    isActive: boolean
    /** Read / completed — green check, highest-priority marker. */
    isRead: boolean
    /** Locked — the viewer cannot open it yet. */
    isLocked?: boolean
    /** Premium / VIP — star (shown when not locked). */
    isPremium?: boolean
    /** Optional right-aligned meta (e.g. minutes, score). */
    meta?: ReactNode
    /** Fired when the row is pressed (navigation handled by the caller). */
    onPress: () => void
}

/** One collapsible group (module / milestone) of {@link OutlineRailItem}s. */
export interface OutlineRailGroup {
    /** Stable id used as the accordion key + expand state. */
    id: string
    /** Group title (truncated + native tooltip). */
    title: string
    /** Group progress — expanded → a `ProgressMeter`; collapsed → {@link collapsedCountLabel}. */
    progress: { done: number; total: number }
    /** Pre-formatted "n/m" label shown when the group is collapsed. */
    collapsedCountLabel: string
    /** Rows in the group. */
    items: Array<OutlineRailItem>
}

/** The rail header — the rail's progress + one primary action. */
export interface OutlineRailHeader {
    /** Label for the overall-progress row (e.g. "Progress"). */
    label: ReactNode
    /** Overall progress driving the header meter. */
    progress: { done: number; total: number }
    /** Pre-formatted overall count (e.g. "2/12 lessons"). */
    countLabel: ReactNode
    /** Optional primary "continue / resume" action. */
    continue?: { label: ReactNode; onPress: () => void }
}

/** Controlled search box state for the rail. */
export interface OutlineRailSearch {
    /** Current query. */
    value: string
    /** Query change handler. */
    onChange: (value: string) => void
    /** Placeholder text. */
    placeholder: string
    /** Accessible label. */
    ariaLabel: string
}

/**
 * The list region's error / empty wiring. The loading state is no longer
 * carried here — it is the top-level {@link OutlineRailProps.isSkeleton},
 * which the list region mirrors co-located in place (no caller-supplied
 * `skeleton` tree).
 */
export interface OutlineRailAsync {
    /** Empty gate (no data at all). Ignored while {@link OutlineRailProps.isSkeleton} is set. */
    isEmpty: boolean
    /** Empty-state title. */
    emptyTitle: string
    /** Error-state title. */
    errorTitle: string
    /** Error to surface (prefer stale data once loaded; beats both skeleton and empty). */
    error?: unknown
    /** Retry handler. */
    onRetry: () => void
    /** Retry button label. */
    retryLabel: string
    /** Shown when a search filters everything out (groups present but empty). */
    noMatchLabel: string
}

/** Props for the {@link OutlineRail} block. */
export interface OutlineRailProps extends WithClassNames<undefined> {
    /** Progress header + continue action. Omit to hide the header (e.g. while loading). */
    header?: OutlineRailHeader
    /** Controlled search field. */
    search: OutlineRailSearch
    /** Ordered groups → rows. */
    groups: Array<OutlineRailGroup>
    /** Controlled expanded group ids. */
    expandedKeys: Set<string>
    /** Fires with the next expanded id set. */
    onExpandedChange: (keys: Set<string>) => void
    /**
     * First load, nothing in hand → the list region shimmers in place
     * (co-located: `Skeleton.Accordion` swaps in for the real `Accordion`
     * right where it sits — `missingSkeletonSupport`, `loading-and-skeleton.md`).
     * Owned by the caller's first-load formula, e.g. `!data && !error`.
     */
    isSkeleton?: boolean
    /** Error / empty wiring for the list region. */
    async: OutlineRailAsync
}

/**
 * The shared docs-style navigation rail (UI 2.0): a pinned progress header with a
 * single "continue" action, a client-side search field, then a scroll region of
 * collapsible groups → compact {@link ContentMapRow} rows. One progress bar at a
 * time — the open group shows a `ProgressMeter`, collapsed groups show a muted
 * "n/m" count.
 *
 * Props-only / fully controlled: the consuming feature owns the data, the search
 * value, the expanded-set (auto-open the active group, open matches on search),
 * and every string (i18n). Both the course content-map and the personal-project
 * milestone rail render through this one block, so they stay identical.
 *
 * Positioning (sticky / width / scroll height) is supplied by the caller via
 * `className`, so the same rail serves the desktop rail and the mobile drawer.
 *
 * @param props - {@link OutlineRailProps}
 * @see Story: .storybook/stories/blocks/navigation/OutlineRail/OutlineRail.stories
 */
export const OutlineRail = ({
    header,
    search,
    groups,
    expandedKeys,
    onExpandedChange,
    isSkeleton = false,
    async,
    className,
}: OutlineRailProps) => {
    /** Active row — scrolled into view when it changes / the list hydrates. */
    const activeRowRef = useRef<HTMLDivElement>(null)
    const activeItemId = groups
        .flatMap((group) => group.items)
        .find((item) => item.isActive)?.id
    useEffect(() => {
        activeRowRef.current?.scrollIntoView({ block: "nearest" })
    }, [activeItemId])

    return (
        <div className={cn("relative flex min-h-0 min-w-0 flex-col gap-3 p-6", className)}>
            {/* progress header — the "continue" action floats at the bottom (see below) */}
            {header ? (
                <div className="flex flex-col gap-2">
                    <div className="flex items-center justify-between gap-2">
                        <Label>{header.label}</Label>
                        <Typography type="body-xs" color="muted">
                            {header.countLabel}
                        </Typography>
                    </div>
                    <ProgressMeter value={header.progress.done} max={header.progress.total} />
                </div>
            ) : null}

            {/* client-side search over the visible tree */}
            <TextField>
                <Input
                    aria-label={search.ariaLabel}
                    value={search.value}
                    onChange={(event) => search.onChange(event.target.value)}
                    placeholder={search.placeholder}
                />
            </TextField>

            {/* only the list scrolls — soft fade, header + search stay pinned. Extra bottom
                padding when the floating action is present so the last row clears it. */}
            <ScrollShadow hideScrollBar className={cn("-mx-1 min-h-0 min-w-0 flex-1 overflow-x-hidden overflow-y-auto px-1", header?.continue && "pb-20")}>
                {/* error beats a stale skeleton flag; empty only once settled (loading-and-skeleton.md §1) */}
                {async.error ? (
                    <AsyncContentError
                        title={async.errorTitle}
                        onRetry={async.onRetry}
                        retryLabel={async.retryLabel}
                    />
                ) : !isSkeleton && async.isEmpty ? (
                    <AsyncContentEmpty title={async.emptyTitle} />
                ) : isSkeleton ? (
                    // the real `Accordion` (HeroUI) and `ContentMapRow` below take no `isSkeleton`
                    // of their own — mirrored right here with the canonical `Skeleton.Accordion`
                    // piece instead of a caller-supplied parallel skeleton tree (missingSkeletonSupport).
                    <Skeleton.Accordion className="w-full" items={SKELETON_GROUP_COUNT} />
                ) : groups.length > 0 ? (
                    <Accordion
                        variant="default"
                        className="min-w-0 w-full"
                        expandedKeys={expandedKeys}
                        onExpandedChange={(keys) => onExpandedChange(new Set([...keys].map(String)))}
                    >
                        {groups.map((group) => {
                            const isExpanded = expandedKeys.has(group.id)
                            return (
                                <Accordion.Item
                                    key={group.id}
                                    id={group.id}
                                    aria-label={group.title}
                                    className="min-w-0"
                                >
                                    <Accordion.Heading className="min-w-0">
                                        <Accordion.Trigger className="min-w-0 w-full max-w-full px-0 py-2 hover:bg-transparent">
                                            {/* title truncates to one line; count/bar on the line below */}
                                            <div className="flex w-full min-w-0 items-center gap-2 overflow-hidden">
                                                <div className="flex min-w-0 flex-1 flex-col overflow-hidden">
                                                    <Typography
                                                        type="body"
                                                        weight="semibold"
                                                        truncate
                                                        title={group.title}
                                                        className="w-full min-w-0"
                                                    >
                                                        {group.title}
                                                    </Typography>
                                                    {isExpanded ? (
                                                        <ProgressMeter
                                                            value={group.progress.done}
                                                            max={group.progress.total || 1}
                                                        />
                                                    ) : (
                                                        <Typography type="body-xs" color="muted">
                                                            {group.collapsedCountLabel}
                                                        </Typography>
                                                    )}
                                                </div>
                                                <Accordion.Indicator className="shrink-0" />
                                            </div>
                                        </Accordion.Trigger>
                                    </Accordion.Heading>
                                    <Accordion.Panel>
                                        <Accordion.Body className="px-0 pb-3">
                                            <div className="flex flex-col gap-0">
                                                {group.items.map((item) => (
                                                    <div
                                                        key={item.id}
                                                        ref={item.isActive ? activeRowRef : undefined}
                                                    >
                                                        <ContentMapRow
                                                            title={item.title}
                                                            isActive={item.isActive}
                                                            isRead={item.isRead}
                                                            isLocked={item.isLocked}
                                                            isPremium={item.isPremium ?? false}
                                                            onPress={item.onPress}
                                                            meta={item.meta}
                                                        />
                                                    </div>
                                                ))}
                                            </div>
                                        </Accordion.Body>
                                    </Accordion.Panel>
                                </Accordion.Item>
                            )
                        })}
                    </Accordion>
                ) : (
                    <Typography type="body-sm" color="muted" align="center">
                        {async.noMatchLabel}
                    </Typography>
                )}
            </ScrollShadow>

            {/* the rail's one primary action — a frosted bottom bar so it stays reachable
                while the list scrolls behind it (was a static top button). The bar (px-6 py-3)
                is a click-through blur layer; only the full-width button catches the press. */}
            {header?.continue ? (
                <div className="pointer-events-none absolute inset-x-0 bottom-0 bg-background/80 px-6 py-3 backdrop-blur-md">
                    <Button
                        variant="primary"
                        size="lg"
                        onPress={header.continue.onPress}
                        className="pointer-events-auto w-full"
                    >
                        {header.continue.label}
                        <ArrowRightIcon aria-hidden focusable="false" className="size-5" />
                    </Button>
                </div>
            ) : null}
        </div>
    )
}

export default OutlineRail

import React, { useCallback, useMemo } from "react"
import { Pagination as HeroPagination, cn } from "@heroui/react"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Props for {@link _Pagination} — presentational; every aria-label already resolved. */
export interface PaginationProps extends WithClassNames<undefined> {
    /** 1-based current page. */
    currentPage: number
    /** Total number of pages (>= 1). */
    totalPages: number
    /** Fired with a 1-based page number when the user changes page. */
    onPageChange: (pageNumber: number) => void
    /** Already-localized aria-label for the pagination nav landmark. */
    navAriaLabel: string
    /** Already-localized "Previous page" aria-label. */
    previousAriaLabel: string
    /** Already-localized "Next page" aria-label. */
    nextAriaLabel: string
}

/**
 * Generic, reusable page-based pagination control.
 *
 * Presentational + controlled: renders page links + prev/next from the supplied
 * page state and delegates navigation via `onPageChange`. The parent owns paging
 * (client-side or server-driven), so this stays reusable across any list.
 *
 * @param props - {@link PaginationProps}
 * @see Story: .storybook/stories/blocks/navigation/Pagination/Pagination.stories
 */
export const _Pagination = ({
    currentPage,
    totalPages,
    onPageChange,
    navAriaLabel,
    previousAriaLabel,
    nextAriaLabel,
    className,
}: PaginationProps) => {
    /** All 1-based page numbers to render (lists using this control are small). */
    const pageNumbers = useMemo(
        () => Array.from({ length: totalPages }, (_, index) => index + 1),
        [totalPages],
    )

    /** Go to the previous page, clamped to the first page. */
    const onPrevious = useCallback(
        () => onPageChange(Math.max(1, currentPage - 1)),
        [currentPage, onPageChange],
    )

    /** Go to the next page, clamped to the last page. */
    const onNext = useCallback(
        () => onPageChange(Math.min(totalPages, currentPage + 1)),
        [currentPage, totalPages, onPageChange],
    )

    return (
        <div className={cn("mt-6 flex justify-center", className)}>
            <HeroPagination aria-label={navAriaLabel} size="sm">
                <HeroPagination.Content className="flex flex-wrap justify-center gap-1">
                    <HeroPagination.Item>
                        <HeroPagination.Previous
                            aria-label={previousAriaLabel}
                            isDisabled={currentPage <= 1}
                            onPress={onPrevious}
                        >
                            <HeroPagination.PreviousIcon />
                        </HeroPagination.Previous>
                    </HeroPagination.Item>
                    {pageNumbers.map((pageNumber) => (
                        <PaginationLink
                            key={pageNumber}
                            pageNumber={pageNumber}
                            isActive={pageNumber === currentPage}
                            onPageChange={onPageChange}
                        />
                    ))}
                    <HeroPagination.Item>
                        <HeroPagination.Next
                            aria-label={nextAriaLabel}
                            isDisabled={currentPage >= totalPages}
                            onPress={onNext}
                        >
                            <HeroPagination.NextIcon />
                        </HeroPagination.Next>
                    </HeroPagination.Item>
                </HeroPagination.Content>
            </HeroPagination>
        </div>
    )
}

/** Props for {@link PaginationLink}. */
interface PaginationLinkProps {
    /** 1-based page number this link targets. */
    pageNumber: number
    /** Whether this link is the active page. */
    isActive: boolean
    /** Fired with this link's page number on press. */
    onPageChange: (pageNumber: number) => void
}

/**
 * A single page link; isolates its press handler so no inline arrow lives in the map.
 *
 * @param props - {@link PaginationLinkProps}
 */
const PaginationLink = ({
    pageNumber,
    isActive,
    onPageChange,
}: PaginationLinkProps) => {
    /** Navigate to this link's page. */
    const onPress = useCallback(
        () => onPageChange(pageNumber),
        [pageNumber, onPageChange],
    )
    return (
        <HeroPagination.Item>
            <HeroPagination.Link isActive={isActive} onPress={onPress}>
                {pageNumber}
            </HeroPagination.Link>
        </HeroPagination.Item>
    )
}

import React from "react"
import {
    CodeIcon,
    FileTextIcon,
    HouseIcon,
    PulseIcon,
    PuzzlePieceIcon,
    RocketIcon,
} from "@phosphor-icons/react"
import {
    TabsExtended,
    TabsIndicator,
    TabsList,
    TabsListContainer,
    TabsTab,
    type IconComponent,
} from "@/components/atoms/navigation/Tabs"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH } from "@/components/frames/Stack"

/**
 * `ProfileTabsBar` — the public-profile route strip (overview / projects /
 * challenges / skills / cv / activity). Draws the already-gated tab list the
 * caller hands it and reports a pick back via `onTabChange`; visibility gating
 * stays upstream. Uses `TabsExtended` (composing the `Tabs.*` children
 * directly) so one region (icon) can stay visible while another (label + owner
 * marker) drops below `@app-md`. One leaf: which tabs show, which is active,
 * and which carries the "· hidden" marker are data.
 */

/** Every public-profile destination this strip can offer — ported from the real `ProfileTab`. */
export type ProfileTab = "overview" | "projects" | "challenges" | "skills" | "cv" | "activity"

/** Tab → label. Block-owned wording (§14d.1), ported verbatim from `publicProfile.tabs.*`. */
const TAB_LABEL: Record<ProfileTab, string> = {
    overview: "Overview",
    projects: "Projects",
    challenges: "Challenges",
    skills: "Skills",
    cv: "CV",
    activity: "Activity",
}

/** Tab → icon. Ported 1:1 from the real `TAB_ICONS` table. */
const TAB_ICON: Record<ProfileTab, IconComponent> = {
    overview: HouseIcon,
    projects: RocketIcon,
    challenges: PuzzlePieceIcon,
    skills: CodeIcon,
    cv: FileTextIcon,
    activity: PulseIcon,
}

/**
 * Glyph scale for a `text-sm` (14px) label — same §5a pairing `TabsBase` already
 * uses for its own icon column, ported here since this block hand-composes the
 * tab's inside instead of going through that atom's `items`.
 */
const TAB_ICON_CLASS = "size-3.5"
const TAB_ICON_WEIGHT = "bold" as const

/** The owner-only marker riding beside a hidden section tab's label. */
const HIDDEN_MARKER = "· hidden"

/** Props for {@link ProfileTabsBar}. */
export interface ProfileTabsBarProps {
    /** Which destination's route is being viewed now. */
    activeTab: ProfileTab
    /**
     * Destinations to render, in display order — ALREADY gated by the caller
     * (owner sees every tab; a visitor never receives a tab their
     * `sectionVisibility`/`hasPublicCv` withheld). This block draws exactly this
     * list, nothing more.
     */
    visibleTabs: ReadonlyArray<ProfileTab>
    /** Fired with the tab the visitor picked. The screen decides how to navigate. */
    onTabChange: (tab: ProfileTab) => void
    /**
     * Section tabs (a subset of {@link visibleTabs}) the OWNER has switched off
     * for other visitors — rendered with a "· hidden" marker beside the label so the
     * owner can tell at a glance. Omit (or leave empty) for a visitor's own view.
     */
    hiddenTabs?: ReadonlyArray<ProfileTab>
    /** Accessible name for the tab list, localized by the caller (blocks carry no i18n). */
    ariaLabel: string
}

/**
 * The profile's route-derived tab strip. See the file header for why the gating
 * computation and routing stay out of this block, and why `TabsExtended` (not
 * `TabsBase`) composes it.
 *
 * @param props - {@link ProfileTabsBarProps}
 */
const ProfileTabsBar = ({
    activeTab,
    visibleTabs,
    onTabChange,
    hiddenTabs,
    ariaLabel,
}: ProfileTabsBarProps) => {
    // TabsExtended size md already owns full-width stretch — no wrapper host.
    return (
        <TabsExtended
            selectedKey={activeTab}
            onSelectionChange={(key) => onTabChange(key as ProfileTab)}
        >
            <TabsListContainer>
                <TabsList aria-label={ariaLabel}>
                    {visibleTabs.map((tabId) => {
                        const Icon = TAB_ICON[tabId]
                        const isHidden = hiddenTabs?.includes(tabId) ?? false
                        return (
                            <TabsTab
                                key={tabId}
                                id={tabId}
                            >
                                <StackH
                                    gap={2}
                                    principle="icon-text"
                                    explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
                                    align="center"
                                    items={[
                                        () => <Icon aria-hidden focusable="false" className={TAB_ICON_CLASS} weight={TAB_ICON_WEIGHT} />,
                                        // Icon-only below @app-md — label (and its marker) only
                                        // from a tablet-wide profile strip up.
                                        () => (
                                            <span className="hidden @app-md:inline">
                                                <Typography size="sm" text={TAB_LABEL[tabId]} />
                                                {isHidden ? (
                                                    <>
                                                        {" "}
                                                        <Typography size="sm" color="muted" text={HIDDEN_MARKER} />
                                                    </>
                                                ) : null}
                                            </span>
                                        ),
                                    ]}
                                />
                                <TabsIndicator />
                            </TabsTab>
                        )
                    })}
                </TabsList>
            </TabsListContainer>
        </TabsExtended>
    )
}

export { ProfileTabsBar }

