                className,
            )}
        >
            {icon}
            {!collapsed ? (
                <Typography
                    type="body-sm"
                    className={cn("min-w-0 flex-1", isActive ? "text-accent-soft-foreground" : undefined)}
                    weight={isActive ? "medium" : "normal"}
