import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { FlameIcon, GithubLogoIcon, GlobeIcon, LinkedinLogoIcon, MapPinIcon } from "@phosphor-icons/react"
import { Tabs, type TabItem } from "@/components/atoms/navigation/Tabs"
import { Typography, type TypographyIcon } from "@/components/atoms/text/Typography"
import { Chip } from "@/components/atoms/chips/Chip"
import { Button } from "@/components/atoms/buttons/Button"
import { IconTile } from "@/components/atoms/display/IconTile"
import { AvatarGroup, type AvatarGroupItem } from "@/components/composites/lists/AvatarGroup"
import { InlineIconLabel } from "@/components/composites/text/InlineIconLabel"
import { ProgressBar } from "@/components/atoms/display/Progress"
import { SurfaceCard, SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"
import { Container } from "@/components/frames/Container"
import { Box } from "@/components/frames/Box"
import { StackV, StackH } from "@/components/frames/Stack"
import { Grid, type GridItem } from "@/components/frames/Grid"
import { RailShell } from "@/components/frames/RailShell"
import type { CallerIdentity } from "@/components/frames/_identity"

/**
 * BLOCK — `ProfileLoadingState`: the public-profile first-load skeleton. It
 * takes no data props (see the component's own file header) so it has exactly
 * ONE leaf and ONE state — there is no prop to vary it by.
 *
 * `annotate` (flat map, not a nested `parts` tree) is the right shape here for
 * the same reason `ContinueCard`'s own `Skeleton` leaf uses it: every text/pill/
 * progress/tile spot renders through an atom's OWN `isSkeleton` branch, so the
 * DOM this leaf produces really is flat repeats of a handful of part names
 * (`Typography`, `Chip`, `Button`, `IconTile`, `Avatar`, `Skeleton`…), not a
 * meaningfully nested composition tree.
 *
 * The outer split (identity rail beside the overview column) is `RailShell` —
 * the same leading-rail-beside-a-growing-body khung `SettingsLayout` composes
 * through, column-first on narrow screens and a row from `@app-md`.
 */

/** Props for {@link ProfileLoadingState}. Pure skeleton — no data props (see file header). */
export interface ProfileLoadingStateProps {
    /**
 * Caller identity to wear on this block's root instead of its own — pass this
 * when a `block`/`layout`/`overlay`/`page` component (BLOCK-2: never draws a shape
 * of its own) is using this block AS its root element, instead of wrapping it in a
 * raw `<div data-tier=… data-component=…>`. See `_identity.ts`. Omitted -> this root
 * (a `StackV` track) keeps emitting its own underlying `data-tier="frame"
 * data-component="Flex"`, same as any other unbadged `StackV` instance.
 */
    identity?: CallerIdentity
}

/** Placeholder tab-strip items — 5 tabs (overview/projects/challenges/skills/activity), never read: `Tabs isSkeleton` never renders a label. */
const TAB_ITEMS: Array<TabItem> = [0, 1, 2, 3, 4].map((i) => ({ key: `tab-${i}`, label: "" }))

/** Placeholder medal-strip members — `AvatarGroup` needs `items` even while skeleton (its shimmer mirrors `items.length` slots). */
const MEDAL_ITEMS: Array<AvatarGroupItem> = [0, 1, 2, 3, 4].map((i) => ({ key: `medal-${i}` }))

/** One meta row's stable key + the icon its loaded counterpart would show — github / linkedin / website, mirrors `ProfileHero`'s own `SOCIAL_META`. */
const META_ROWS: ReadonlyArray<{ key: string; icon: TypographyIcon }> = [
    { key: "meta-github", icon: GithubLogoIcon },
    { key: "meta-linkedin", icon: LinkedinLogoIcon },
    { key: "meta-website", icon: GlobeIcon },
]

/**
 * The public-profile first-load skeleton. See the file header for why the
 * section order is hard-coded and why two spots fall back to a raw HeroUI
 * `Skeleton` (documented `couldNotFix` gaps — see the PR notes: a 128px avatar
 * and a heatmap-shaped rectangle have no matching atom to stand in for them).
 *
 * @param props - {@link ProfileLoadingStateProps}
 */
export const ProfileLoadingState = ({ identity }: ProfileLoadingStateProps) => {
    // Free-form rows built here (not by `SurfaceCardList`'s own `isSkeleton`, §12c):
    // the courses/readiness rows carry BESPOKE content (an IconTile, a progress
    // bar), not the composite's fixed leading/title/subtitle slots, so each row
    // passes `content` and stays untouched by the list's own shimmer branch.
    const readinessTrack = (
        <>
            <Typography size="sm" isSkeleton />
            <ProgressBar isSkeleton />
            <ProgressBar isSkeleton />
        </>
    )

    const readinessItems: Array<SurfaceCardListItem> = [
        {
            key: "readiness-track",
            content: () => <StackV gap={4} items={[() => readinessTrack]} />,
        },
    ]

    const courseItems: Array<SurfaceCardListItem> = [0, 1].map((i) => {
        const progressHeader = (
            <>
                <Typography size="sm" isSkeleton />
                <Typography size="xs" isSkeleton classNames={["w-1/4", "shrink-0"]} />
            </>
        )
        const courseDetails = (
            <>
                <StackH gap={3} principle="value-row"
                    explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
                    justify="between" items={[() => progressHeader]}  />
                <ProgressBar isSkeleton />
            </>
        )
        const courseRow = (
            <>
                <IconTile isSkeleton size="sm" />
                <StackV gap={3} classNames={["min-w-0", "flex-1"]} items={[() => courseDetails]} />
            </>
        )
        return {
            key: `course-${i}`,
            content: () => <StackH gap={4} items={[() => courseRow]} />,
        }
    })

    const skillItems: Array<GridItem> = [0, 1].map((i) => {
        const statCardBody = (
            <>
                <Typography size="h3" isSkeleton classNames={["w-1/4"]} />
                <Typography size="sm" isSkeleton classNames={["w-2/3"]} />
                <Typography size="xs" isSkeleton classNames={["w-1/3"]} />
            </>
        )
        const skillCard = (
            <>
                <Typography size="h4" isSkeleton />
                <SurfaceCard
                    padding={4}
                    body={() => <StackV gap={3} items={[() => statCardBody]} />}
                />
            </>
        )
        return {
            key: `skill-${i}`,
            content: () => <StackV gap={4} items={[() => skillCard]} />,
        }
    })

    // ── identity column — bare, no card face (matches `ProfileHeroSkeleton`) ──

    // rank-framed avatar + rank pill — 128px avatar has no matching `Avatar`
    // preset (sm/md/lg cap at 48px), so this spot builds its own shimmer.
    // WARNING️ couldNotFix (no-heroui-outside-vocabulary): no atom offers a 128px
    // circular shimmer, so this stays a raw HeroUI `Skeleton`.
    const rankAvatarRow = (
        <>
            <Skeleton className="size-32 rounded-full" />
            <Chip isSkeleton />
        </>
    )

    // name (h3) + role title + @handle — one unit of meaning, flush
    const nameBlock = (
        <>
            <Typography size="h3" isSkeleton classNames={["w-3/4"]} />
            <Typography size="sm" isSkeleton />
            <Typography size="sm" isSkeleton classNames={["w-1/3"]} />
        </>
    )

    // location · preferred work mode — `InlineIconLabel` is the sanctioned
    // "leading icon + inline text" composite (mirrors `ProfileHero`'s own use
    // of it for this exact row).
    const locationRow = (
        <>
            <InlineIconLabel icon={MapPinIcon} isSkeleton size="sm" skeletonWidth="w-1/3" />
            <Chip isSkeleton />
        </>
    )

    // follower / following line
    const followRow = (
        <>
            <Typography size="sm" isSkeleton classNames={["w-1/3"]} />
            <Typography size="sm" isSkeleton classNames={["w-1/3"]} />
        </>
    )

    // action cluster — two full-width buttons
    const actionButtons = (
        <>
            <Button isSkeleton classNames={["w-full"]} />
            <Button isSkeleton classNames={["w-full"]} />
        </>
    )

    // meta: github · linkedin · website — leading icon + text rows, each one `InlineIconLabel`.
    const metaRows = META_ROWS.map((row) => (
        <InlineIconLabel key={row.key} icon={row.icon} isSkeleton size="sm" skeletonWidth="w-1/2" />
    ))

    const identityColumnBody = (
        <>
            <StackV gap={2} principle="title-subtitle"
                explain="Title over supporting line — not label-field, because neither line is a form control label."
                align="start" items={[() => rankAvatarRow]}  />
            <StackV gap={1} items={[() => nameBlock]} />

            {/* short bio */}
            <Typography size="sm" isSkeleton classNames={["w-2/3"]} />

            <StackH gap={3} principle="chip-row"
                explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                at="sm" items={[() => locationRow]}  />
            <StackH gap={4} items={[() => followRow]} />

            {/* earned-badge medal strip — `AvatarGroup` already owns the overlap look */}
            <AvatarGroup items={MEDAL_ITEMS} size="sm" isSkeleton />

            <StackV gap={3} items={[() => actionButtons]} />
            <StackV gap={4} items={[() => metaRows]} />
        </>
    )

    // ── overview body — the four sections, in the real screen's own order ──

    const readinessCard = (
        <>
            <Typography size="h3" isSkeleton classNames={["w-1/4"]} />
            <Typography size="sm" isSkeleton classNames={["w-2/3"]} />
            <Typography size="xs" isSkeleton classNames={["w-1/3"]} />
        </>
    )
    const readinessGroup = (
        <>
            <SurfaceCard
                padding={4}
                body={() => <StackV gap={3} items={[() => readinessCard]} />}
            />
            <SurfaceCardList
                items={readinessItems}
            />
        </>
    )
    // job readiness — headline metric card + a tracked-goal row
    const readinessSection = (
        <>
            <Typography size="h4" isSkeleton />
            <StackV gap={4} items={[() => readinessGroup]} />
        </>
    )

    // courses — icon tile + title/percent + progress rows
    const coursesSection = (
        <>
            <Typography size="h4" isSkeleton />
            <SurfaceCardList
                items={courseItems}
            />
        </>
    )

    // contributions — heatmap grid + streak line
    // WARNING️ couldNotFix (no-heroui-outside-vocabulary): no atom offers an
    // arbitrary-sized rounded rectangle shimmer, so the heatmap placeholder
    // stays a raw HeroUI `Skeleton`.
    const contributionGroup = (
        <>
            <Skeleton className="h-40 w-full rounded-xl" />
            <InlineIconLabel icon={FlameIcon} isSkeleton size="sm" skeletonWidth="w-1/2" />
        </>
    )
    const contributionsSection = (
        <>
            <Typography size="h4" isSkeleton />
            <StackV gap={4} items={[() => contributionGroup]} />
        </>
    )

    const overviewSections = (
        <>
            <StackV gap={4} items={[() => readinessSection]} />
            <StackV gap={4} items={[() => coursesSection]} />
            <StackV gap={4} items={[() => contributionsSection]} />
            {/* skills — 2-col grid of stat cards */}
            <Grid columns={{ base: 1, md: 2 }} principle="block-boundary"
                explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                items={skillItems}  />
        </>
    )

    // outer split: identity rail first (mobile), row from `@app-md` — `RailShell`,
    // the same leading-rail-beside-a-growing-body khung `SettingsLayout` composes
    // through instead of a hand-rolled `StackV` + breakpoint className (that raw
    // shape is exactly what `no-raw-shape-at-sentence-tier` forbids here).
    const identityRail: ComponentTypeWithSkeleton = () => (
        <StackV gap={4} items={[() => identityColumnBody]} />
    )

    const overviewContent: ComponentTypeWithSkeleton = () => (
        <StackV gap={6} items={[() => overviewSections]} />
    )

    const overviewBody = <RailShell principle="layout-split"
        explain="Major layout split — not block-boundary, because this separates primary page regions rather than adjacent blocks."
        rail={identityRail} body={overviewContent} at="md"  />

    return (
        // WARNING️ couldNotFix (require-identity-root / no-raw-shape-at-sentence-tier):
        // the previous root also carried `aria-busy="true"` and
        // `aria-label="Loading profile"` on a raw `<div>`. No frame in
        // `components/frames/` forwards arbitrary ARIA attributes (`Flex`/`Stack`/
        // `Box` all destructure a closed prop list with no `...rest` passthrough),
        // so moving the root onto `StackV` drops those two attributes — flagged
        // rather than silently lost; adding `aria-*` passthrough to `Flex` is out
        // of this file's scope.
        // gap={1} (0px) between tabs and body was intentional no-seam — a StackV
        // frame was redundant; Box carries identity only.
        <Box
            className="w-full"
            identity={identity}
        >
            {/* tab strip — full-bleed row under the navbar, same footprint as `ProfileTabsBar`.
 `px-6 py-3` is a one-off placement wrapper (a full-width strip flush under a sticky
 navbar, not a repeating list nor a generic card seam), same allowance `ContinueCard`
 uses for its own content wrapper — both padding digits (6, 3) are on the §10c scale.
 Carried via `Container`'s own `padding` prop (house-scale {{ x: 6, y: 4 }} = `px-6 py-3`)
 instead of a raw div — no `patterns.mjs` token names this asymmetric shape yet. */}
            <Container
                size="full"
                padding={{ x: 6, y: 4 }}
                body={() => (
                    <Tabs
                        items={TAB_ITEMS}
                        selectedKey={TAB_ITEMS[0].key}
                        onSelectionChange={() => {}}
                        ariaLabel="Profile sections loading"
                        variant="secondary"
                        isSkeleton
                    />
                )}
            />
            <Container size="lg" padding={6} body={() => overviewBody} />
        </Box>
    )
}

"use client"

import React, { useCallback, useMemo } from "react"
import { Tabs } from "@heroui/react"
import {
    HouseIcon,
    PuzzlePieceIcon,
    RocketIcon,
    CodeIcon,
    FileTextIcon,
    PulseIcon,
} from "@phosphor-icons/react"
import { useTranslations, useLocale } from "next-intl"
import { usePathname, useRouter } from "next/navigation"
import type { SectionVisibility } from "@/modules/types/entities/user"
import { PROFILE_TABS } from "@/modules/types/entities/profile"
import type { ProfileTab } from "@/modules/types/entities/profile"
import { ExtendedTabs } from "@/components/blocks/navigation/ExtendedTabs"
import { pathConfig } from "@/resources/path"

/**
 * The section tabs gated by `sectionVisibility` (Overview + CV are never gated —
 * Overview always shows, CV keeps its own `hasPublicCv` gate).
 */
const SECTION_TABS: ReadonlyArray<keyof SectionVisibility> = [
    "projects",
    "challenges",
    "skills",
    "activity",
]

/** Whether a tab is one of the visibility-gated section tabs. */
const isSectionTab = (tabId: ProfileTab): tabId is keyof SectionVisibility =>
    (SECTION_TABS as ReadonlyArray<ProfileTab>).includes(tabId)

/** Leading icon shown on each profile tab, keyed by tab id. */
const TAB_ICONS: Record<ProfileTab, typeof HouseIcon> = {
    overview: HouseIcon,
    challenges: PuzzlePieceIcon,
    projects: RocketIcon,
    skills: CodeIcon,
    cv: FileTextIcon,
    activity: PulseIcon,
}

/** Props for {@link ProfileTabsBar}. */
export interface ProfileTabsBarProps {
    /** The viewed user's canonical username (drives every tab's href). */
    username: string
    /** Whether the viewer is the profile owner — shows the "CV" tab even without a public CV. */
    isSelf: boolean
    /** Whether the viewed user has a PUBLIC CV — shows the "CV" tab to visitors too. */
    hasPublicCv: boolean
    /**
     * The viewed user's per-section visibility (all default true). A section tab is
     * withheld from VISITORS when its flag is false; the owner ({@link isSelf}) always
     * sees every tab (with a "· hidden" marker on hidden ones). Absent = all visible.
     */
    sectionVisibility?: SectionVisibility
}

/**
 * Build the href for a profile tab. Every tab nests under `/profile/<username>`,
 * INCLUDING "cv" — the public, read-only CV view (`/profile/<username>/cv`). The
 * owner's private editor stays reachable from the "Edit CV" button inside
 * that view (the always-own `/profile/cv` gallery).
 */
const tabHref = (locale: string, username: string, tabId: ProfileTab): string => {
    const profile = pathConfig().locale(locale).profile(username)
    switch (tabId) {
    case "overview":
        return profile.overview().build()
    case "projects":
        return profile.projects().build()
    case "challenges":
        return profile.challenges().build()
    case "skills":
        return profile.skills().build()
    case "activity":
        return profile.activity().build()
    case "cv":
        return profile.cv().build()
    }
}

/**
 * Full-width tab strip for the profile page. The page registers it as the global
 * Navbar's bottom layer ({@link useRegisterNavbarBottomLayer}); the Navbar renders
 * it flush under its primary row and owns the single bottom border + sticky, so
 * this strip carries no border / sticky / bg of its own. Uses the native HeroUI
 * secondary Tabs (foreground text on the selected tab + an accent underline
 * indicator).
 *
 * Each tab is a real nested route (`/profile/<username>/<tab>`, bare = overview) —
 * the active tab is derived from the URL pathname and switching a tab
 * `router.push`es its href, mirroring the `pathname === href` + `router.push`
 * pattern `SettingsLayout` already uses for its own route-derived nav. No store,
 * no `?tab=` query param: the URL alone is the source of truth, so the open tab
 * is shareable / bookmarkable / back-forward friendly for free.
 *
 * @param props - {@link ProfileTabsBarProps}
 */
export const ProfileTabsBar = ({ username, isSelf, hasPublicCv, sectionVisibility}: ProfileTabsBarProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const pathname = usePathname()
    // Whether a SECTION tab is hidden for the current viewer: false flag + visitor.
    // The owner (isSelf) always sees it (just marked "· hidden"); an absent flag = visible.
    const isSectionHidden = useCallback(
        (tabId: ProfileTab): boolean =>
            !isSelf && isSectionTab(tabId) && sectionVisibility?.[tabId] === false,
        [isSelf, sectionVisibility],
    )
    // Tab gating, combined:
    //  • "cv" shows for the owner (always) or when the viewed user has a PUBLIC CV.
    //  • a section tab (projects/challenges/skills/activity) is withheld from VISITORS
    //    when its sectionVisibility flag is false. Overview is never gated.
    const visibleTabs = useMemo(
        () => PROFILE_TABS.filter((tabId) => {
            if (tabId === "cv") {
                return isSelf || hasPublicCv
            }
            return !isSectionHidden(tabId)
        }),
        [isSelf, hasPublicCv, isSectionHidden],
    )

    // active tab = the tab whose path is a PREFIX of the current pathname (so a
    // nested sub-route like `/challenges/<courseId>/<id>` still lights up its tab).
    // "overview" is the bare `/profile/<username>` path — a prefix of everything —
    // so it's only the FALLBACK when no deeper tab matches.
    const activeTab = useMemo<ProfileTab>(() => {
        const match = visibleTabs
            .filter((tabId) => tabId !== "overview")
            .find((tabId) => {
                const href = tabHref(locale, username, tabId)
                return pathname === href || pathname.startsWith(`${href}/`)
            })
        return match ?? "overview"
    }, [visibleTabs, pathname, locale, username])

    return (
        // Rendered as the Navbar's bottom layer — no border / sticky / bg of its
        // own; the Navbar root owns the single bottom border and the sticky.
        <div className={"w-full"}>
            <div className="w-full px-6">
                <ExtendedTabs
                    selectedKey={activeTab}
                    onSelectionChange={(key) => router.push(tabHref(locale, username, key as ProfileTab))}
                >
                    <Tabs.ListContainer>
                        <Tabs.List aria-label={t("publicProfile.title")}>
                            {visibleTabs.map((tabId) => {
                                const TabIcon = TAB_ICONS[tabId]
                                return (
                                    <Tabs.Tab
                                        key={tabId}
                                        id={tabId}
                                        aria-controls={`profile-panel-${tabId}`}
                                    >
                                        <span className="flex items-center gap-2">
                                            <TabIcon
                                                aria-hidden
                                                focusable="false"
                                                className="size-5 shrink-0"
                                            />
                                            {/* mobile = icon only; label shows from md up */}
                                            <span className="hidden @app-md:inline">
                                                {t(`publicProfile.tabs.${tabId}`)}
                                                {/* owner-only marker on a section hidden from
                                                    visitors (visitors never see the tab at all) */}
                                                {isSelf && isSectionTab(tabId) && sectionVisibility?.[tabId] === false ? (
                                                    <span className="ml-1 text-foreground-500">
                                                        {t("publicProfile.tabHidden")}
                                                    </span>
                                                ) : null}
                                            </span>
                                        </span>
                                        <Tabs.Indicator />
                                    </Tabs.Tab>
                                )
                            })}
                        </Tabs.List>
                    </Tabs.ListContainer>
                </ExtendedTabs>
            </div>
        </div>
    )
}

"use client"

import React from "react"
/** Props for {@link RankBadge}. */
export interface RankBadgeProps {
    /** Display label for the rank (already localised, e.g. "Senior"). */
    label: string
    /** Hex colour encoding the rank tier (grey → bronze → silver → gold). */
    color: string
}

/**
 * Seniority rank pill — a coloured dot + the rank label (Beginner → Senior),
 * tinted by the rank's tier colour. Presentational: the caller resolves the
 * user's rank → `{ label, color }` (e.g. via `getRank`) and passes it in.
 *
 * NO border: a soft 10%-tint fill of the rank colour with the dot + label in the
 * full colour (a chip is one colour family, not an outline). `color` is a runtime
 * hex, so the fill uses `color-mix(... 10%, transparent)` (format-agnostic) — the
 * inline-style equivalent of `bg-[color]/10`.
 *
 * @param props - {@link RankBadgeProps}
 */
export const RankBadge = ({
    label,
    color}: RankBadgeProps) => {
    return (
        <span
            className={"inline-flex w-fit items-center gap-2 rounded-full px-2 py-0 text-xs font-medium"}
            style={{
                backgroundColor: `color-mix(in srgb, ${color} 10%, transparent)`,
                color,
            }}
        >
            <span
                className="size-2 rounded-full"
                style={{
                    backgroundColor: color,
                }}
            />
            {label}
        </span>
    )
}

"use client"

import React from "react"
import {
    CaretUpIcon,
    CaretDownIcon,
} from "@phosphor-icons/react"
import {
    cn,
} from "@heroui/react"
import type {
    WithClassNames,
} from "@/modules/types/base/class-name"

/** Props for {@link RankDeltaCaret}. */
export interface RankDeltaCaretProps extends WithClassNames<undefined> {
    /**
     * Rank movement vs the previous period (`lastRank - currentRank`): positive
     * = climbed N places (▲ green), negative = dropped (▼ red), 0 = unchanged
     * (muted dash), null = no baseline (renders nothing).
     */
    delta: number | null
}

/**
 * The rank-movement caret shown at the end of a leaderboard row: a green up
 * arrow + count when the user climbed, a red down arrow + count when they
 * dropped, a muted dash when unchanged, and nothing when there's no baseline.
 * Reused by the weekly-league board + the global leaderboard.
 *
 * @param props - {@link RankDeltaCaretProps}
 */
export const RankDeltaCaret = ({
    delta,
    className,
}: RankDeltaCaretProps) => {
    // no last-period baseline → an EMPTY SPACER that still reserves the column width
    // (the caller's `className` carries the `w-8`), so a #1 row with no movement keeps
    // the value/delta columns aligned with the rows below it instead of letting the
    // value slide right into the empty slot (the teacher, 2026-07-17: "the green ones need to line up").
    if (delta === null) {
        return <span className={cn(className)} aria-hidden />
    }
    // unchanged → a muted dash so the column still aligns
    if (delta === 0) {
        return (
            <span className={cn("text-xs text-muted", className)}>
                —
            </span>
        )
    }
    const climbed = delta > 0
    return (
        <span
            className={cn(
                "flex items-center gap-0 text-xs font-medium",
                climbed ? "text-success-soft-foreground" : "text-danger-soft-foreground",
                className,
            )}
        >
            {climbed ? (
                <CaretUpIcon className="size-3.5" />
            ) : (
                <CaretDownIcon className="size-3.5" />
            )}
            {Math.abs(delta)}
        </span>
    )
}

"use client"

import React, { useEffect, useRef, useState } from "react"
import { codeToHtml } from "shiki"
import { cn } from "@heroui/react"
import { SnippetIcon } from "@/components/blocks/identity/SnippetIcon"

/** Props for {@link CodeToHtml}. */
export interface CodeToHtmlProps {
    /** Source code to highlight. */
    code: string
    /** Shiki language id (e.g. `bash`, `ts`). */
    language: string
    /** Shiki theme id resolved from the app theme. */
    theme: string
    /**
     * Surface treatment (both variants are `rounded-3xl` — a code block is
     * card-like). Default (`false`) = RECESSED well (`border border-default
     * bg-background`) — the correct look when the block sits ON a reading surface /
     * card (a bg-background inset reads as darker than the surface around it). Set
     * `true` for a RAISED card (`bg-surface shadow-surface`, NO border — shadow
     * does the lifting, axis-1 §16/§32) when the block sits on the page CANVAS
     * (`bg-background`), so it "floats up" instead of blending canvas-on-canvas.
     * Only opt in where the container is the bare canvas.
     */
    elevated?: boolean
}

/**
 * Converts a code block to highlighted HTML using Shiki.
 *
 * Presentational: runs Shiki in a `useEffect` and stores the resulting HTML in local state;
 * no business logic. Marked `"use client"` for the browser-side highlighter.
 *
 * PERF: highlighting is LAZY — only run Shiki when the block scrolls near the viewport
 * (IntersectionObserver). A long article with 20+ blocks won't highlight all at once on load
 * (Shiki/WASM is heavy); off-screen blocks show raw code (`<pre>`) until scrolled into view.
 * @param props - {@link CodeToHtmlProps}
 * @see Story: .storybook/stories/blocks/rendering/MarkdownContent/CodeToHtml/CodeToHtml.stories
 */
export const CodeToHtml = ({ code, language, theme, elevated = false }: CodeToHtmlProps) => {
    const containerRef = useRef<HTMLDivElement>(null)
    /** Whether the block has entered (near) the viewport yet — only then do we highlight. */
    const [isVisible, setIsVisible] = useState(false)
    /** Highlighted HTML; `null` keeps the raw `<pre>` fallback. */
    const [html, setHtml] = useState<string | null>(null)

    useEffect(() => {
        const el = containerRef.current
        if (!el || isVisible) {
            return
        }
        const observer = new IntersectionObserver(
            (entries) => {
                if (entries[0]?.isIntersecting) {
                    setIsVisible(true)
                    observer.disconnect()
                }
            },
            // rootMargin: start highlighting 300px before the block enters the screen.
            { rootMargin: "300px" },
        )
        observer.observe(el)
        return () => observer.disconnect()
    }, [isVisible])

    // Run Shiki via useEffect (no SWR) directly client-side once the block is visible.
    // Changing code/language/theme must re-highlight. `cancelled` blocks setState after unmount /
    // when deps change mid-flight (avoids writing stale HTML over newer HTML).
    useEffect(() => {
        if (!isVisible) {
            return
        }
        let cancelled = false
        codeToHtml(code, { lang: language, theme })
            .then((out) => {
                if (!cancelled) {
                    setHtml(out)
                }
            })
            .catch((error) => {
                // Shiki error (lang/theme/WASM…): keep the raw `<pre>` fallback + log for debugging.
                console.error("CodeToHtml: shiki highlight failed", error)
            })
        return () => {
            cancelled = true
        }
    }, [isVisible, code, language, theme])

    return (
        <div
            ref={containerRef}
            className={cn(
                // BOTH variants = rounded-3xl (a code block is card-like → 3xl
                // regardless of treatment, instructor's call, 2026-07-18). Only bg/shadow differ:
                // raised card ON canvas (`bg-surface shadow`, NO border — shadow
                // lifts, axis-1 §16/§32) vs recessed well ON a surface (`bg-background`
                // inset + border, so it doesn't fill-on-fill the surface around it).
                "w-full max-w-full overflow-hidden rounded-3xl",
                elevated
                    ? "bg-surface shadow-surface"
                    : "border border-default bg-background",
            )}
        >
            {/* slim header: language label (left) + copy (right) — orients long lessons with many snippets */}
            <div className="flex items-center justify-between border-b border-default px-3 py-2">
                <span className="font-mono text-xs uppercase text-muted">{language}</span>
                <SnippetIcon copyString={code} />
            </div>
            {html ? (
                <div
                    className="p-3 text-sm [&_code]:!whitespace-pre-wrap [&_code]:!break-words [&_pre]:!whitespace-pre-wrap [&_pre]:!break-words [&_pre]:!bg-transparent [&_pre]:!p-0"
                    dangerouslySetInnerHTML={{ __html: html }}
                />
            ) : (
                /* Fallback: always show raw code while Shiki hasn't finished / on error (avoids an empty box). */
                <pre className="p-3 text-sm whitespace-pre-wrap break-words">
                    <code>{code}</code>
                </pre>
            )}
        </div>
    )
}

"use client"

import React, { useMemo } from "react"
/** Props for {@link LayoutWidget}. */
export interface LayoutWidgetProps {
    /** Raw HTML layout-mockup source authored inside a ```layout fence. */
    html: string
}

/**
 * Strips active content from author-supplied HTML before it is injected via
 * `dangerouslySetInnerHTML`. Removes `<script>`/`<iframe>` elements, inline `on*=`
 * event-handler attributes, and `javascript:` URLs so a layout mockup can only paint
 * static markup. Deliberately minimal (no new dependency) — the input is trusted-author
 * lesson content, this is a defense-in-depth scrub, not a full sanitizer.
 * @param html - Raw HTML string from the fenced `layout` block.
 * @returns Sanitized HTML safe to render inline.
 */
const sanitizeLayoutHtml = (html: string): string =>
    html
        // Drop <script>…</script> blocks entirely (including their content).
        .replace(/<script\b[^>]*>[\s\S]*?<\/script\s*>/gi, "")
        // Drop any stray opening/closing <script> tags left without a pair.
        .replace(/<\/?script\b[^>]*>/gi, "")
        // Drop <iframe>…</iframe> blocks and any stray iframe tags.
        .replace(/<iframe\b[^>]*>[\s\S]*?<\/iframe\s*>/gi, "")
        .replace(/<\/?iframe\b[^>]*>/gi, "")
        // Strip inline event-handler attributes (onclick=, onload=, …), quoted or bare.
        .replace(/\son[a-z]+\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]+)/gi, "")
        // Neutralize javascript: URLs in any remaining attribute value.
        .replace(/javascript:/gi, "")

/**
 * Renders an author-embedded HTML layout mockup inline within lesson markdown.
 *
 * Presentational: sanitizes the supplied HTML (see {@link sanitizeLayoutHtml}) and paints it
 * via `dangerouslySetInnerHTML` inside a bordered, rounded surface that works in light and
 * dark mode. `not-prose` keeps the prose typography from leaking into the mockup. Marked
 * `"use client"` so it pairs with the client-rendered markdown tree.
 * @param props - {@link LayoutWidgetProps}
 */
export const LayoutWidget = ({ html}: LayoutWidgetProps) => {
    // Memoize the scrub so re-renders don't re-run the regex passes over the same source.
    const safeHtml = useMemo(() => sanitizeLayoutHtml(html), [html])
    return (
        <div
            className={"not-prose overflow-hidden rounded-xl border border-default bg-surface"}
            dangerouslySetInnerHTML={{ __html: safeHtml }}
        />
    )
}

import React from "react"
import { cn, Table } from "@heroui/react"
import {
    flattenMarkdownTableHeaderChildren,
    isMarkdownHeaderTableRowNode,
} from "./utils"
import type { WithClassNames } from "@/modules/types/base/class-name"

/**
 * Builds a HeroUI header column from a rendered `th`/`Table.Column` or body `Table.Cell`.
 * @param column - Rendered header cell from markdown.
 * @param index - Zero-based column index in the header row.
 * @returns A `Table.Column` with `isRowHeader` on the first column (HeroUI requirement).
 */
const toMarkdownHeaderColumn = (column: React.ReactNode, index: number): React.ReactNode => {
    if (!React.isValidElement<{ children?: React.ReactNode }>(column)) {
        return column
    }
    return (
        <Table.Column key={`md-th-${index}`} isRowHeader={index === 0}>
            {column.props.children}
        </Table.Column>
    )
}

/** Props for markdown table row/cell parts (optional HAST `node` when `passNode` is on). */
interface MarkdownTablePartProps extends WithClassNames<undefined> {
    /** Rendered cell content. */
    children?: React.ReactNode
    /** HAST element for the markdown row (requires `passNode` on `ReactMarkdown`). */
    node?: unknown
}

/**
 * Header row: columns must be direct children of `Table.Header` (fragment, not `Table.Row`).
 * Body row: wrapped in HeroUI `Table.Row`.
 */
export const MarkdownTableRow = ({ children, node, className }: MarkdownTablePartProps) => {
    if (isMarkdownHeaderTableRowNode(node)) {
        return <>{children}</>
    }

    return <Table.Row className={cn(className)}>{children}</Table.Row>
}

/**
 * Maps markdown `thead` to HeroUI `Table.Header`.
 * Rebuilds columns with `isRowHeader` on the first column (required by HeroUI / React Aria).
 * Renders a screen-reader-only column when the header row is empty so the table still mounts.
 */
export const MarkdownTableHead = ({ children, className }: MarkdownTablePartProps) => {
    const columns = flattenMarkdownTableHeaderChildren(children)

    return (
        <Table.Header className={cn(className)}>
            {columns.length === 0 ? (
                <Table.Column isRowHeader className="sr-only">
                    {" "}
                </Table.Column>
            ) : (
                columns.map((column, index) => toMarkdownHeaderColumn(column, index))
            )}
        </Table.Header>
    )
}

/** Props for {@link MarkdownTable}. */
export interface MarkdownTableProps extends WithClassNames<undefined> {
    /** Rendered `thead` / `tbody` from react-markdown. */
    children?: React.ReactNode
    /** Accessible name for `Table.Content`. */
    ariaLabel: string
}

/**
 * Wraps GFM tables in HeroUI `Table` and ensures a header row exists with `isRowHeader`.
 * Some markdown tables only emit `tbody`; the first body row is promoted to `thead` in that case.
 * @param props - {@link MarkdownTableProps}
 */
export const MarkdownTable = ({ children, ariaLabel, className }: MarkdownTableProps) => {
    const parts = React.Children.toArray(children)
    const hasThead = parts.some(
        (child) => React.isValidElement(child) && child.type === MarkdownTableHead,
    )
    const tbodyIndex = parts.findIndex(
        (child) => React.isValidElement(child) && child.type === MarkdownTableBody,
    )

    let content: React.ReactNode
    if (hasThead) {
        content = children
    } else if (tbodyIndex < 0) {
        content = (
            <>
                <MarkdownTableHead />
                {children}
            </>
        )
    } else {
        const tbody = parts[tbodyIndex] as React.ReactElement<{ children?: React.ReactNode }>
        const bodyRows = React.Children.toArray(tbody.props.children)
        const [firstRow, ...restRows] = bodyRows
        content = (
            <>
                {parts.slice(0, tbodyIndex)}
                <MarkdownTableHead>{firstRow}</MarkdownTableHead>
                <MarkdownTableBody>{restRows}</MarkdownTableBody>
                {parts.slice(tbodyIndex + 1)}
            </>
        )
    }

    // The HeroUI table-root is a CSS grid; its inner scroll-container's min-width doesn't
    // propagate, so a wide table forces the whole reading column past the viewport (page stops
    // shrinking). Wrap in a PLAIN BLOCK x-scroll box — a block scroll container has min-content
    // 0, so the column shrinks and the table scrolls inside instead of blocking the layout.
    return (
        <div className="max-w-full overflow-x-auto">
            <Table variant="primary" className={cn(className)}>
                <Table.ScrollContainer>
                    <Table.Content aria-label={ariaLabel}>
                        {content}
                    </Table.Content>
                </Table.ScrollContainer>
            </Table>
        </div>
    )
}

/** Maps markdown `tbody` to HeroUI `Table.Body`. */
export const MarkdownTableBody = ({ children, className }: MarkdownTablePartProps) => (
    <Table.Body className={cn(className)}>{children}</Table.Body>
)

/** Maps markdown `th` to HeroUI `Table.Column`. */
export const MarkdownTableColumn = ({ children, className }: MarkdownTablePartProps) => (
    <Table.Column className={cn(className)}>{children}</Table.Column>
)

import { MagnifyingGlassPlusIcon } from "@phosphor-icons/react"
import React, { useState } from "react"
import { Modal } from "@heroui/react"

/** Props for {@link _MermaidDiagram} — presentational; the rendered SVG already resolved. */
export interface MermaidDiagramProps {
    /** Rendered SVG markup, or `null` while the diagram is still compiling. */
    svg: string | null
    /** Translated loading text while the diagram is rendering. */
    loadingLabel: string
    /** Translated accessible label for the click-to-zoom trigger. */
    expandLabel: string
    /** Figure caption paragraph that follows the diagram (e.g. "Figure 1: ..."), if any. */
    caption?: string
    /** Translated generic caption shown when the diagram has no authored caption. */
    fallbackLabel: string
}

/**
 * Renders a mermaid diagram's already-compiled SVG, with a click-to-zoom
 * full-screen preview.
 *
 * Presentational: the connected half owns the SWR-cached `mermaid.render()`
 * call; this component only toggles the full-screen preview (`useState`,
 * UI-local) and lays the SVG out. Marked `"use client"` via the connected
 * half — this file itself needs no browser API.
 * @param props - {@link MermaidDiagramProps}
 */
export const _MermaidDiagram = ({ svg, loadingLabel, expandLabel, caption, fallbackLabel }: MermaidDiagramProps) => {
    // Local open flag for the full-screen preview dialog (per-diagram, not a global modal).
    const [isOpen, setOpen] = useState(false)
    // Authored caption wins; otherwise show a generic figure label.
    const figureCaption = caption ?? fallbackLabel

    return (
        <figure className="rounded-xl border border-default bg-background p-3">
            {svg ? (
                <>
                    {/* Clickable inline diagram — opens the full-screen preview on press. */}
                    <button
                        type="button"
                        aria-label={expandLabel}
                        title={expandLabel}
                        onClick={() => setOpen(true)}
                        className="group relative block w-full cursor-zoom-in"
                    >
                        {/* mermaid stamps an inline `style="max-width:Npx"` on the <svg> that
                            outranks our `max-w-full` class, so a wide diagram would otherwise push
                            the reading column past the viewport. Wrap it in an x-scroll box. */}
                        <div
                            className="overflow-x-auto [&_svg]:h-auto [&_svg]:!w-auto [&_svg]:!max-w-none"
                            dangerouslySetInnerHTML={{ __html: svg }}
                        />
                        {/* Hover affordance hinting the diagram can be enlarged. */}
                        <span className="pointer-events-none absolute right-2 top-2 rounded-medium bg-default/60 p-2 text-muted opacity-0 transition-opacity group-hover:opacity-100">
                            <MagnifyingGlassPlusIcon className="size-5" />
                        </span>
                    </button>
                    {/* Authored caption ("Figure N: …") as a real figcaption — the source paragraph
                        is stripped upstream so it isn't shown twice. Generic fallback stays modal-only. */}
                    {caption ? (
                        <figcaption className="mt-2 text-center text-sm italic text-muted">
                            {caption}
                        </figcaption>
                    ) : null}
                    <Modal isOpen={isOpen} onOpenChange={setOpen}>
                        <Modal.Backdrop>
                            <Modal.Container size="full">
                                <Modal.Dialog>
                                    <Modal.CloseTrigger />
                                    <Modal.Body data-principle="card-padding" className="p-4">
                                        {/* Full-screen figure: diagram scaled to fill, caption beneath. */}
                                        <figure className="flex h-full flex-col items-center justify-center gap-2">
                                            <div className="flex w-full flex-1 items-center justify-center overflow-auto">
                                                <div
                                                    className="[&_svg]:h-auto [&_svg]:w-full [&_svg]:max-w-full"
                                                    dangerouslySetInnerHTML={{ __html: svg }}
                                                />
                                            </div>
                                            <figcaption className="text-center text-sm italic text-muted">
                                                {figureCaption}
                                            </figcaption>
                                        </figure>
                                    </Modal.Body>
                                </Modal.Dialog>
                            </Modal.Container>
                        </Modal.Backdrop>
                    </Modal>
                </>
            ) : (
                <div className="text-sm text-muted">{loadingLabel}</div>
            )}
        </figure>
    )
}

import React from "react"
import { cn, Spinner } from "@heroui/react"
import { heroUiMdxComponents } from "../mdxComponents"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Compiled MDX module exposes its content as the default export. */
export type MdxContentComponent = React.ComponentType<{
    components?: Record<string, React.ElementType>
    className?: string
}>

/** Props for {@link _RenderReactComponent} — presentational; the compiled MDX component already resolved. */
export interface RenderReactComponentProps extends WithClassNames<undefined> {
    /** JSX/MDX source (shown verbatim on a compile error). */
    code: string
    /** The compiled MDX component, or `null` while compiling. */
    Content: MdxContentComponent | null
    /** `true` → the compile failed; falls back to showing `code` verbatim. */
    hasError: boolean
}

/**
 * Renders a ` ```mdx ` snippet as a REAL React tree — render ONLY, no tabs.
 *
 * Presentational: the connected half owns the (browser-only) `evaluate()`
 * compile, cached per-source via SWR; this component only picks the
 * error / loading / compiled branch. On a compile error the raw snippet is
 * shown verbatim (safe fallback) instead of crashing.
 * @param props - {@link RenderReactComponentProps}
 */
export const _RenderReactComponent = ({ code, Content, hasError, className }: RenderReactComponentProps) => {
    if (hasError) {
        return (
            <pre className={cn("not-prose overflow-auto rounded-xl border border-danger/40 bg-default/40 p-3 font-mono text-xs text-muted", className)}>
                {code}
            </pre>
        )
    }
    if (!Content) {
        return <Spinner size="sm" aria-label="Rendering" className={cn(className)} />
    }
    return <Content components={heroUiMdxComponents} className={className} />
}

"use client"

import React from "react"
import { CodePreviewTabs } from "../CodePreviewTabs"

interface TabPaneProps {
    kind: "code" | "preview"
    children?: React.ReactNode
}

/**
 * One pane inside a `:::tab` block: the source code (`:::code` → ` ```tsx ` Shiki) or the live
 * demo (`:::preview` → ` ```mdx ` render). It only renders its children (the fence rendered by the
 * normal `pre` handler); {@link TabsBlock} identifies which pane is which by the original directive
 * tag name (`tabcode`/`tabpreview`), not by this prop.
 */

export const TabPane = (
    { children }: TabPaneProps,
) => <>{children}</>

/** The hast node react-markdown threads onto every element renderer via the `node` prop. */
interface NodeProp {
    node?: { tagName?: string }
}

/** Props for {@link TabsBlock}. */
interface TabsBlockProps {
    children?: React.ReactNode
}

/**
 * Renders a `:::tab` block as **[ Preview | Code ]** tabs via the shared {@link CodePreviewTabs}.
 *
 * Use this (not a single ` ```mdx `) when the real code has logic/imports that can't be evaluated:
 * the `:::code` pane shows the FULL code (Shiki, not rendered) and the `:::preview` pane shows a
 * separate renderable demo.
 *
 * Panes are matched by the original directive tag name carried on each child's `node` prop
 * (`tabcode` / `tabpreview`) — order-independent. NOTE: the children TabsBlock receives are the
 * `tabcode`/`tabpreview` element renderers themselves, whose own props are only `{ node, children }`;
 * the `kind` lives on the `TabPane` they *return*, so it is NOT visible here — match on `node.tagName`.
 * @param props.children - The `:::code` / `:::preview` pane elements.
 */
export const TabsBlock = ({ children }: TabsBlockProps) => {
    let previewNode: React.ReactNode = null
    let codeNode: React.ReactNode = null
    React.Children.forEach(children, (child) => {
        if (!React.isValidElement(child)) {
            return
        }
        const tagName = (child.props as NodeProp).node?.tagName
        if (tagName === "tabpreview") {
            previewNode = child
        } else if (tagName === "tabcode") {
            codeNode = child
        }
    })

    if (previewNode == null && codeNode == null) {
        return <>{children}</>
    }
    return <CodePreviewTabs preview={previewNode} code={codeNode} />
}

import React, { useMemo } from "react"
import ReactMarkdown from "react-markdown"
import remarkGfm from "remark-gfm"
import remarkDirective from "remark-directive"
import { cn } from "@heroui/react"
import type { Components } from "react-markdown"
// Re-export the colocated sub-renderers so the reuseable barrel surface stays identical.
export * from "./CodeToHtml"
export * from "./LayoutWidget"
export * from "./MermaidDiagram"

/**
 * Recursively rewrites `:::muted` directives (container/leaf/text, parsed by `remark-directive`)
 * into custom hast tags the renderer map styles as small muted text. Container/leaf → block-level
 * `mutedblock`; inline `:muted[…]` → `mutedtext`. Directives with any other name are left untouched
 * (and dropped by the hast conversion since they have no handler).
 * @param node - Current mdast node being walked.
 */
const applyMutedDirective = (node: { type?: string, name?: string, data?: Record<string, unknown>, children?: Array<unknown> }): void => {
    if (
        (node.type === "containerDirective" || node.type === "leafDirective" || node.type === "textDirective")
        && node.name === "muted"
    ) {
        const data = node.data || (node.data = {})
        data.hName = node.type === "textDirective" ? "mutedtext" : "mutedblock"
        data.hProperties = {}
    }
    if (Array.isArray(node.children)) {
        for (const child of node.children) {
            applyMutedDirective(child as Parameters<typeof applyMutedDirective>[0])
        }
    }
}

/** remark transformer: turn `:::muted` directives into styled custom tags. */
const remarkMuted = () => (tree: unknown): void => {
    applyMutedDirective(tree as Parameters<typeof applyMutedDirective>[0])
}

/**
 * Recursively rewrites the `:::tab` / `:::code` / `:::preview` container directives into custom hast
 * tags the renderer map turns into a [Preview|Code] tabs block (see TabsBlock): `tab`→`tabblock`,
 * `code`→`tabcode`, `preview`→`tabpreview`. Each pane's child fence (` ```tsx ` / ` ```mdx `) still
 * renders through the normal `pre` handler. Other directive names are left untouched.
 *
 * Note: container nesting needs MORE colons on the outer fence — `::::tab` wraps `:::code` /
 * `:::preview`.
 * @param node - Current mdast node being walked.
 */
const applyTabDirective = (node: { type?: string, name?: string, data?: Record<string, unknown>, children?: Array<unknown> }): void => {
    if (node.type === "containerDirective") {
        const tag = node.name === "tab"
            ? "tabblock"
            : node.name === "code"
                ? "tabcode"
                : node.name === "preview"
                    ? "tabpreview"
                    : null
        if (tag) {
            const data = node.data || (node.data = {})
            data.hName = tag
            data.hProperties = {}
        }
    }
    if (Array.isArray(node.children)) {
        for (const child of node.children) {
            applyTabDirective(child as Parameters<typeof applyTabDirective>[0])
        }
    }
}

/** remark transformer: turn `::::tab`/`:::code`/`:::preview` directives into tabs-block tags. */
const remarkTab = () => (tree: unknown): void => {
    applyTabDirective(tree as Parameters<typeof applyTabDirective>[0])
}

/**
 * Recursively collects the raw text of a directive subtree, preserving line breaks so each
 * authored line (one keyword per line) can be split back out into a separate chip.
 * @param node - Current mdast node.
 */
const collectDirectiveText = (node: { type?: string, value?: string, children?: Array<unknown> }): string => {
    if (node.type === "text") {
        return node.value ?? ""
    }
    if (node.type === "break") {
        return "\n"
    }
    if (Array.isArray(node.children)) {
        return node.children
            .map((child) => collectDirectiveText(child as Parameters<typeof collectDirectiveText>[0]))
            .join("\n")
    }
    return ""
}

/**
 * Rewrites the `:::chip` container directive into a custom `chipblock` tag (see map.tsx),
 * carrying its keywords (one per authored line) as a newline-split, `|`-joined `items` prop so the
 * renderer can render each as its own Chip. Other directive names are left untouched.
 * @param node - Current mdast node being walked.
 */
const applyChipDirective = (node: { type?: string, name?: string, data?: Record<string, unknown>, children?: Array<unknown> }): void => {
    if (node.type === "containerDirective" && node.name === "chip") {
        const items = collectDirectiveText(node)
            .split(/[\n·]+/)
            .map((line) => line.trim())
            .filter((line) => line.length > 0)
        const data = node.data || (node.data = {})
        data.hName = "chipblock"
        data.hProperties = {
            items: items.join("|"),
        }
    }
    if (Array.isArray(node.children)) {
        for (const child of node.children) {
            applyChipDirective(child as Parameters<typeof applyChipDirective>[0])
        }
    }
}

/** remark transformer: turn `:::chip` directives into a chips-row tag. */
const remarkChip = () => (tree: unknown): void => {
    applyChipDirective(tree as Parameters<typeof applyChipDirective>[0])
}

/**
 * Recursively rewrites the `::::accordion` / `:::panel` container directives into custom hast tags the
 * renderer map turns into a HeroUI Accordion (see map.tsx): `accordion`→`accordionblock`; each
 * `:::panel{title="…"}`→`accordionpanel` carrying its `title` attribute. Inner panel content
 * (bullets, code fences) still renders through the normal handlers.
 *
 * Note: nesting needs MORE colons on the outer fence — `::::accordion` wraps `:::panel`.
 * @param node - Current mdast node being walked.
 */
const applyAccordionDirective = (node: { type?: string, name?: string, attributes?: Record<string, string>, data?: Record<string, unknown>, children?: Array<unknown> }): void => {
    if (node.type === "containerDirective") {
        if (node.name === "accordion") {
            const data = node.data || (node.data = {})
            data.hName = "accordionblock"
            data.hProperties = {}
        } else if (node.name === "panel") {
            const data = node.data || (node.data = {})
            data.hName = "accordionpanel"
            data.hProperties = {
                title: node.attributes?.title ?? "",
            }
        }
    }
    if (Array.isArray(node.children)) {
        for (const child of node.children) {
            applyAccordionDirective(child as Parameters<typeof applyAccordionDirective>[0])
        }
    }
}

/** remark transformer: turn `::::accordion`/`:::panel` directives into accordion tags. */
const remarkAccordion = () => (tree: unknown): void => {
    applyAccordionDirective(tree as Parameters<typeof applyAccordionDirective>[0])
}

/**
 * True for a `:::muted` directive node — already tagged `hName: "mutedblock"` by
 * {@link remarkMuted}. Its OWN content shape then decides how {@link groupArcSections}
 * handles it — see {@link isSelfContainedLeadBoldMuted} / {@link isBareLabelMuted}.
 * @param node - Current mdast node.
 */
const isMutedLabelNode = (node: { data?: { hName?: unknown } }): boolean => node.data?.hName === "mutedblock"

/**
 * True for the actual authoring idiom found in the card catalog: ONE paragraph
 * that OPENS with a `**bold**` span and keeps going as prose on the same line/block
 * (`**Solution** — NestJS provides three hooks...`) — label and body live in the SAME
 * mdast paragraph node. Two places this shape shows up: as a bare top-level
 * paragraph, OR (the actual catalog convention) as the sole child of a `:::muted`
 * directive — see {@link isSelfContainedLeadBoldMuted}.
 * @param node - Current mdast node.
 */
const isLeadBoldParagraph = (node: { type?: string, children?: Array<{ type?: string }> }): boolean =>
    node.type === "paragraph"
    && Array.isArray(node.children)
    && node.children.length > 0
    && node.children[0]?.type === "strong"

/**
 * True when a `:::muted` directive's ENTIRE content is one {@link isLeadBoldParagraph}
 * — the real catalog shape (`:::muted\n**Solution** — NestJS provides...\n:::`),
 * where the directive is a pointless extra wrapper around an already-self-contained
 * section. {@link groupArcSections} unwraps it (tags the inner paragraph directly)
 * instead of double-wrapping, which is what caused the infinite recursion this fixes
 * — re-processing a wrapper whose only child is still `hName: "mutedblock"` kept
 * re-matching {@link isMutedLabelNode} forever.
 * @param node - Current mdast node (already confirmed a muted label via {@link isMutedLabelNode}).
 */
const isSelfContainedLeadBoldMuted = (node: { children?: Array<{ type?: string, children?: Array<{ type?: string }> }> }): boolean =>
    Array.isArray(node.children) && node.children.length === 1 && isLeadBoldParagraph(node.children[0])

/**
 * True when a `:::muted` directive's ENTIRE content is ONE short inline node (the
 * doc-documented shape: `:::muted\n<Label>\n:::\n<body>` — label alone, body
 * follows as an external sibling). {@link groupArcSections} wraps this shape and
 * absorbs the following siblings as its body, unlike {@link isSelfContainedLeadBoldMuted}
 * which already has its body inside.
 * @param node - Current mdast node (already confirmed a muted label via {@link isMutedLabelNode}).
 */
const isBareLabelMuted = (node: { children?: Array<{ type?: string, children?: Array<unknown> }> }): boolean => {
    const only = node.children?.[0]
    return Array.isArray(node.children) && node.children.length === 1
        && only?.type === "paragraph"
        && Array.isArray(only.children) && only.children.length === 1
}

/**
 * Turns each Interview Arc section into one `arcsection` node so the renderer
 * (`map.tsx`) can box/collapse a whole "label + body" unit instead of rendering it
 * as flat, undifferentiated siblings/prose. Three authoring shapes exist in the card
 * catalog and are handled differently:
 * - `:::muted` wrapping a lead-bold paragraph (see {@link isSelfContainedLeadBoldMuted},
 *   the actual catalog convention) — the directive is unwrapped; its inner paragraph
 *   is retagged directly.
 * - Bare `:::muted` label (see {@link isBareLabelMuted}, the shape documented in
 *   `.claude/docs/rules/flashcard-answer.md` §2) — wrapped, absorbing every sibling
 *   that follows up to the next label as its body.
 * - Bare lead-bold paragraph, no `:::muted` at all — retagged in place.
 * Every node this function tags or wraps is added to `skip` so the second pass never
 * re-descends into it — re-visiting a `hName: "mutedblock"` node nested one level
 * inside its own freshly-created wrapper is what caused unbounded recursion before
 * this fix (a single-child wrapper around a still-muted-tagged node kept re-matching
 * and re-wrapping itself forever). Each `arcsection` carries its position (`index`,
 * 0-based) so the renderer can keep the first two sections (TL;DR / mechanism) always
 * expanded and collapse the rest behind a chip — the fixed order documented in
 * `.claude/docs/rules/flashcard-answer.md` §2.
 * @param node - Current mdast node being walked.
 */
const groupArcSections = (node: { children?: Array<Record<string, unknown>> }): void => {
    if (!Array.isArray(node.children)) {
        return
    }
    const grouped: Array<Record<string, unknown>> = []
    let current: { type: string, children: Array<unknown>, data: Record<string, unknown> } | null = null
    let sectionIndex = 0
    const skip = new Set<unknown>()
    for (const child of node.children) {
        if (isMutedLabelNode(child as Parameters<typeof isMutedLabelNode>[0])) {
            if (isSelfContainedLeadBoldMuted(child as Parameters<typeof isSelfContainedLeadBoldMuted>[0])) {
                const inner = (child.children as Array<Record<string, unknown>>)[0]
                const data = (inner.data as Record<string, unknown>) || (inner.data = {})
                data.hName = "arcsection"
                data.hProperties = { index: sectionIndex }
                sectionIndex += 1
                current = null
                grouped.push(inner)
                skip.add(inner)
            } else if (isBareLabelMuted(child as Parameters<typeof isBareLabelMuted>[0])) {
                current = {
                    type: "arcSection",
                    children: [child],
                    data: { hName: "arcsection", hProperties: { index: sectionIndex } },
                }
                sectionIndex += 1
                grouped.push(current)
                skip.add(current)
            } else {
                // muted content that's neither shape (multi-paragraph, code block…) —
                // tag the directive itself as one section, keep its children as-is.
                const data = (child.data as Record<string, unknown>) || (child.data = {})
                data.hName = "arcsection"
                data.hProperties = { index: sectionIndex }
                sectionIndex += 1
                current = null
                grouped.push(child)
                skip.add(child)
            }
        } else if (isLeadBoldParagraph(child as Parameters<typeof isLeadBoldParagraph>[0])) {
            const data = (child.data as Record<string, unknown>) || (child.data = {})
            data.hName = "arcsection"
            data.hProperties = { index: sectionIndex }
            sectionIndex += 1
            current = null
            grouped.push(child)
            skip.add(child)
        } else if (current) {
            current.children.push(child)
        } else {
            grouped.push(child)
        }
    }
    node.children = grouped
    for (const child of node.children) {
        if (skip.has(child)) {
            continue
        }
        groupArcSections(child as Parameters<typeof groupArcSections>[0])
    }
}

/** remark transformer: box each Interview Arc label + its following body into one `arcsection`. */
const remarkArcSections = () => (tree: unknown): void => {
    groupArcSections(tree as Parameters<typeof groupArcSections>[0])
}

/**
 * Module-level constant — NOT recreated every render. If `remarkPlugins={[...]}` were inline, each
 * MarkdownContent re-render would hand ReactMarkdown a new array → re-parse the whole markdown.
 */
const REMARK_PLUGINS = [remarkGfm, remarkDirective, remarkMuted, remarkTab, remarkChip, remarkAccordion]
// Opt-in variant (flashcard/mock-interview answers, see `arcSections` prop) — same
// stable module-level array so ReactMarkdown never sees a fresh array identity.
const REMARK_PLUGINS_ARC = [...REMARK_PLUGINS, remarkArcSections]

// Matches each ```mermaid fence and the figure caption paragraph that follows it.
// Group 1 = diagram source; group 2 = the first non-blank line after the fence.
const MERMAID_CAPTION_REGEX = /```mermaid[ \t]*\r?\n([\s\S]*?)\r?\n```[ \t]*\r?\n+[ \t]*([^\r\n]+)/g

/**
 * Cuts off a trailing ```mermaid fence that hasn't been closed yet — markdown fed in
 * progressively (the mock-interview typewriter reveal, an AI stream) walks THROUGH every
 * partial length of the diagram source one tick at a time, and `mermaid.render()` throws
 * "Syntax error in text" for every one of those incomplete snapshots. Since a reveal only
 * ever GROWS the text, at most the LAST fence can be unterminated — any earlier one
 * already has content (and therefore its closing fence) after it.
 * @param markdown - Raw markdown source, possibly mid-reveal.
 * @returns `markdown` unchanged, or truncated right before an unterminated trailing mermaid fence.
 */
export const holdBackIncompleteMermaidFence = (markdown: string): string => {
    const lines = markdown.split("\n")
    let lastOpenLine = -1
    for (let i = 0; i < lines.length; i++) {
        if (/^```mermaid[ \t]*$/.test(lines[i].trimEnd())) {
            lastOpenLine = i
        }
    }
    if (lastOpenLine === -1) {
        return markdown
    }
    const isClosed = lines.slice(lastOpenLine + 1).some((line) => line.trim() === "```")
    return isClosed ? markdown : lines.slice(0, lastOpenLine).join("\n").trimEnd()
}

/**
 * Scans markdown for mermaid blocks and pairs each with the caption paragraph that
 * immediately follows it (a figure-caption line, Vietnamese or English), keyed by trimmed source.
 * @param markdown - Raw markdown source.
 * @returns Caption text keyed by trimmed mermaid source.
 */
export const extractMermaidCaptions = (markdown: string): Record<string, string> => {
    const captions: Record<string, string> = {}
    // Reset lastIndex defensively since the regex is module-scoped + global.
    MERMAID_CAPTION_REGEX.lastIndex = 0
    for (let match = MERMAID_CAPTION_REGEX.exec(markdown); match; match = MERMAID_CAPTION_REGEX.exec(markdown)) {
        const code = match[1].trim()
        // Strip surrounding italic markers authors wrap captions in (*...*).
        const caption = match[2].trim().replace(/^\*+|\*+$/g, "").trim()
        // Only adopt lines that read as figure captions, not following prose.
        if (/^(Hình|Figure)\b/i.test(caption)) { // vn-ok: matches the VI figure word in lesson prose
            captions[code] = caption
        }
    }
    return captions
}

/**
 * Removes each mermaid figure-caption paragraph ("Figure N: …", either language) from the source
 * so it isn't rendered twice — the diagram now shows it as a real `<figcaption>`. Non-caption
 * paragraphs after a fence are left intact.
 * @param markdown - Raw markdown source.
 * @returns Markdown with figure-caption paragraphs stripped.
 */
const stripMermaidCaptions = (markdown: string): string => {
    MERMAID_CAPTION_REGEX.lastIndex = 0
    return markdown.replace(MERMAID_CAPTION_REGEX, (match: string, _code: string, caption: string) => {
        const clean = caption.trim().replace(/^\*+|\*+$/g, "").trim()
        if (/^(Hình|Figure)\b/i.test(clean)) { // vn-ok: matches the VI figure word in lesson prose
            // keep the fence + the blank line(s) after it, drop only the caption text
            return match.slice(0, match.lastIndexOf(caption))
        }
        return match
    })
}

/**
 * Strips Anki-style cloze markers `{{cN::term}}` (or `{{cN::term::distractorA,
 * distractorB}}` — the optional trailing group is the quiz's curated
 * confuser set, dropped entirely here) down to just the term, so a flashcard
 * answer renders cleanly everywhere (reviewer / due / quiz full answer). The
 * `cN::` prefix makes the pattern distinctive — it never collides with
 * template braces like `{{ user.name }}` in lesson code samples.
 * @param markdown - Raw markdown that may carry cloze markers.
 */
const stripClozeMarkers = (markdown: string): string =>
    markdown.replace(/\{\{c\d+::([\s\S]*?)(?:::[\s\S]*?)?\}\}/g, "$1")

/** Intrinsic type scale on the prose root (independent of {@link MarkdownContentProps.reading}). */
export type MarkdownDensity = "default" | "compact" | "caption"

/** Foreground colour role on the prose root. */
export type MarkdownTone = "default" | "muted"

/** Whether paragraphs keep document rhythm or sit flush as an embedded passenger. */
export type MarkdownFlow = "document" | "embedded"

/** Italic emphasis on the whole prose root. */
export type MarkdownEmphasis = "normal" | "italic"

/** Clamp each paragraph to this many visible lines (preview / list snip). */
export type MarkdownPreviewLines = 1 | 2

/** Props for {@link _MarkdownContent} — presentational; the renderer map already resolved. */
export interface MarkdownContentProps {
    /** Markdown source string. */
    markdown: string
    /**
     * Reading-grade typography for full lesson articles: 16px body, looser line
     * rhythm and a stronger heading ladder. Off by default (compact scale used in
     * cards, chat, flashcards and modals).
     */
    reading?: boolean
    /**
     * Boxes each Interview Arc label (`:::muted` / standalone-bold paragraph) together
     * with its following body into one collapsible `arcsection` — see `map.tsx`.
     * Opt-in (default off) so lesson/challenge content using the same `:::muted`
     * shape for unrelated callouts (e.g. "Input"/"Output") is unaffected. Only the
     * flashcard/mock-interview answer (FlipCard back face) turns this on.
     */
    arcSections?: boolean
    /** Intrinsic type scale on the prose root. Defaults to `"default"`. */
    density?: MarkdownDensity
    /** Foreground colour role on the prose root. Defaults to `"default"`. */
    tone?: MarkdownTone
    /** Document rhythm vs flush embedded paragraphs. Defaults to `"document"`. */
    flow?: MarkdownFlow
    /** Italic emphasis on the prose root. Defaults to `"normal"`. */
    emphasis?: MarkdownEmphasis
    /** Clamp each paragraph to 1 or 2 visible lines (omit for no clamp). */
    previewLines?: MarkdownPreviewLines
    /** The element-renderer map, already resolved (theme + i18n baked in). */
    components: Components
}

/**
 * Renders markdown with GFM and shared typography aligned with the app theme.
 *
 * Presentational: the connected half resolves the active theme/translator into
 * the `components` renderer map; this file only runs the pure markdown-source
 * transforms (hold-back-incomplete-fence, strip captions/cloze) and renders
 * `ReactMarkdown`. Marked `"use client"` via the connected half.
 * @see Story: .storybook/stories/blocks/rendering/MarkdownContent/MarkdownContent.stories
 * @param props - {@link MarkdownContentProps}
 */
export const _MarkdownContent = ({
    markdown,
    reading = false,
    arcSections = false,
    density = "default",
    tone = "default",
    flow = "document",
    emphasis = "normal",
    previewLines,
    components,
}: MarkdownContentProps) => {
    // hold back an unterminated trailing mermaid fence FIRST — markdown streamed in
    // progressively (typewriter reveal, AI token stream) walks through every partial
    // length of a diagram's source, and parsing those mid-fence snapshots is what
    // throws mermaid's "Syntax error in text". The rest of the pipeline only ever
    // sees a diagram once its fence is fully closed.
    const stableMarkdown = useMemo(() => holdBackIncompleteMermaidFence(markdown), [markdown])
    // Strip mermaid figure-captions (rendered as `<figcaption>`) + cloze markers (rendered plain).
    const renderedMarkdown = useMemo(
        () => stripClozeMarkers(stripMermaidCaptions(stableMarkdown)),
        [stableMarkdown],
    )
    return (
        <div
            className={cn(
                "min-w-0 text-foreground",
                // Reading lessons: NO uniform space-y — each block renderer carries its own
                // asymmetric margin (more above headings than below) for a real section rhythm.
                // Compact (cards / chat / flashcards) keeps the tight uniform rhythm.
                reading
                    ? "text-base leading-7 [&>*:first-child]:mt-0 [&>*:last-child]:mb-0"
                    : "space-y-2 text-sm leading-relaxed",
                // Presentation axes (contract D) — mirror composites/viewers/MarkdownContent.
                density === "compact" && "text-sm",
                density === "caption" && "text-xs",
                tone === "muted" && "text-muted",
                flow === "embedded" && "[&_p]:m-0",
                emphasis === "italic" && "italic",
                previewLines === 1 && "[&_p]:line-clamp-1",
                previewLines === 2 && "[&_p]:line-clamp-2",
            )}
        >
            <ReactMarkdown
                remarkPlugins={arcSections ? REMARK_PLUGINS_ARC : REMARK_PLUGINS}
                components={components}
            >
                {renderedMarkdown}
            </ReactMarkdown>
        </div>
    )
}

import React from "react"
import type { Components } from "react-markdown"
import { isInlineCode } from "react-shiki"
import * as HeroUI from "@heroui/react"
import { CaretDownIcon } from "@phosphor-icons/react"
import {
    MarkdownTable,
    MarkdownTableBody,
    MarkdownTableColumn,
    MarkdownTableHead,
    MarkdownTableRow,
} from "./MarkdownTableParts"
import { CodeToHtml } from "./CodeToHtml"
import { LayoutWidget } from "./LayoutWidget"
import { MermaidDiagram } from "./MermaidDiagram"
import { RenderReactComponent } from "./RenderReactComponent"
import { TabsBlock, TabPane } from "./TabsBlock"
import { Link as IntlLink } from "@/i18n/navigation"
import type { MarkdownRenderersParams } from "./types"

// Named handles used by the markdown element renderers below.
const { Link, Table } = HeroUI

// Tailwind size class per the old HeroUI `Text` `size` token. HeroUI v3.0.5 renamed
// `Text` → `Typography` and its root no longer accepts `size`/`elementType`, so prose
// blocks render through this tiny local helper instead — keeping visuals pixel-identical
// and decoupled from the renamed component.
const PROSE_SIZE: Record<string, string> = {
    xs: "text-xs",
    sm: "text-sm",
    base: "text-base",
    lg: "text-lg",
    xl: "text-xl",
    "2xl": "text-2xl",
}

/**
 * Minimal prose text node: renders `elementType` with a size class plus extra classes.
 * Drop-in for the former HeroUI `<Text elementType size className>` used by the markdown
 * heading/paragraph/list renderers.
 * @param props.elementType - HTML element/tag to render (default `div`).
 * @param props.size - Size token mapped to a Tailwind text-size class (default `sm`).
 * @param props.className - Extra classes appended after the size class.
 * @param props.children - Inline content.
 */
interface ProseTextProps {
    elementType?: React.ElementType
    size?: keyof typeof PROSE_SIZE
    className?: string
    children?: React.ReactNode
}

const ProseText = ({
    elementType: As = "div",
    size = "sm",
    className,
    children,
}: ProseTextProps) => React.createElement(
    As,
    { className: [PROSE_SIZE[size], className].filter(Boolean).join(" ") },
    children,
)

/** Props for markdown renderers that only forward `children`. */
interface MarkdownChildrenProps {
    children?: React.ReactNode
}

/** Props for {@link ArcSection}. */
interface ArcSectionProps {
    index?: number
    children?: React.ReactNode
}

/** Props for the `:::chip` block renderer. */
interface ChipBlockProps {
    items?: string
}

/** Props for the `:::panel` accordion item renderer. */
interface AccordionPanelProps {
    title?: string
    children?: React.ReactNode
}

/**
 * Recursively flattens a React children tree to its plain-text content — used to
 * derive a stable heading slug (and the "on this page" outline label) from the
 * rendered heading nodes.
 * @param node - The React node to read text from.
 * @returns The concatenated text content.
 */
const getNodeText = (node: React.ReactNode): string => {
    if (node === null || node === undefined || typeof node === "boolean") {
        return ""
    }
    if (typeof node === "string" || typeof node === "number") {
        return String(node)
    }
    if (Array.isArray(node)) {
        return node.map(getNodeText).join("")
    }
    if (React.isValidElement(node)) {
        return getNodeText((node.props as { children?: React.ReactNode }).children)
    }
    return ""
}

/**
 * Slugify heading text into a URL-safe anchor id (diacritics stripped, Vietnamese
 * Vietnamese d-with-stroke folded to `d`, non-alphanumerics collapsed to single hyphens). Deterministic so the
 * rendered heading id and any "on this page" outline reading it from the DOM agree.
 * @param text - The raw heading text.
 * @returns The anchor slug.
 */
const slugify = (text: string): string =>
    text
        .normalize("NFKD")
        .replace(/[̀-ͯ]/g, "")
        .replace(/[đĐ]/g, "d") // vn-ok: slug transliteration of the VI letter
        .toLowerCase()
        .trim()
        .replace(/[^a-z0-9]+/g, "-")
        .replace(/^-+|-+$/g, "")

/**
 * Heading renderer factory: renders a section heading carrying a slug `id` +
 * `data-toc` markers so an "on this page" rail can scan the rendered article
 * (`#lesson-article [data-toc]`) and anchor-scroll to it. `scroll-mt-20` clears
 * the sticky navbar when jumped to.
 * @param level - The heading depth surfaced in the outline (2 or 3).
 * @param sizeClass - The prose size class keeping the visual identical to {@link ProseText}.
 */
const buildTocHeading = (level: 2 | 3 | 4, sizeClass: string, marginClass: string, anchorLabel: string) =>
    ({ children }: MarkdownChildrenProps) => {
        // real heading tag (not a div) so the body keeps semantic outline for SEO
        const Tag = `h${level}` as "h2" | "h3" | "h4"
        const text = getNodeText(children)
        const id = slugify(text)
        return (
            <Tag
                id={id}
                data-toc=""
                data-toc-level={level}
                // clean label for the "on this page" rail — read instead of textContent so the
                // hover anchor (#) and any inline code in the heading never leak into the outline.
                data-toc-label={text}
                className={`group ${marginClass} ${sizeClass} scroll-mt-20 font-semibold`.trim()}
            >
                {children}
                {/* Hover anchor (#) — copy/share a deep link to the section (reading only). */}
                {anchorLabel ? (
                    <a
                        href={`#${id}`}
                        aria-label={anchorLabel}
                        className="ml-2 text-muted no-underline opacity-0 transition-opacity group-hover:opacity-100"
                    >
                        #
                    </a>
                ) : null}
            </Tag>
        )
    }

/**
 * One "Interview Arc" section (see `remarkArcSections` in `./index`): the label
 * (`children[0]`, already rendered by `mutedblock`/the `p` fake-heading case) boxed
 * with its body. The first two sections in authoring order (TL;DR, mechanism — see
 * `.claude/docs/rules/flashcard-answer.md` §2) stay always-expanded and divider-
 * separated; the rest start collapsed behind a label chip so a 4-5 section answer
 * doesn't read as one long crammed scroll. `stopPropagation` on the chip because
 * `FlipCard`'s whole face is a click-to-flip target — an un-stopped click would flip
 * the card back to front instead of expanding the section.
 * @param props.index - 0-based position among arc sections in this answer.
 * @param props.children - `[label, ...body]`, as grouped by the remark transform.
 */
const ArcSection = ({ index, children }: ArcSectionProps) => {
    const position = index ?? 0
    const isCore = position < 2
    const [expanded, setExpanded] = React.useState(isCore)
    // the label is `children[0]` (a `<strong>` for the lead-bold-paragraph shape, or
    // the whole `mutedblock` div for the `:::muted` shape) — force it onto its own
    // line as a small MUTED "eyebrow" (teacher, 2026-07-12: label = `text-xs text-muted`,
    // no per-section colour — the section labels are authored inconsistently so a
    // colour-by-label map rendered wrong; a uniform muted label reads cleaner).
    // `!` = guaranteed win over whatever colour/size the label's own renderer gave it.
    const boxClassName = `[&>*:first-child]:!block [&>*:first-child]:!text-muted [&>*:first-child]:!text-xs [&>*:first-child]:!font-medium [&>*:first-child]:!mb-1 border-l-2 border-default pl-3 ${position > 0 ? "mt-3" : ""}`
    if (expanded) {
        // the lead-bold-paragraph shape keeps its " — " separator right after the
        // label text — drop it now that the label sits on its own line above.
        const list = React.Children.toArray(children)
        if (typeof list[1] === "string") {
            list[1] = (list[1] as string).replace(/^\s*[—-]\s*/, "")
        }
        return <div className={boxClassName}>{list}</div>
    }
    const label = React.Children.toArray(children)[0]
    return (
        <button
            type="button"
            onClick={(event) => {
                event.stopPropagation()
                setExpanded(true)
            }}
            className="mr-2 mt-2 inline-flex items-center gap-1 rounded-full bg-default px-2 py-1 text-xs text-muted transition-colors hover:bg-default/80"
        >
            {getNodeText(label)}
            <CaretDownIcon weight="bold" className="size-4" />
        </button>
    )
}

/**
 * Builds the element-renderer map handed to `ReactMarkdown` so headings, tables, code
 * blocks, mermaid diagrams and inline elements use the app's HeroUI typography.
 *
 * Vertical rhythm is owned by the single `space-y` wrapper in {@link MarkdownContent}; block
 * renderers here stay margin-free and only carry size/weight/colour tokens.
 * @param params - {@link MarkdownRenderersParams} theme flag + translator + mermaid captions.
 * @returns A `Components` map keyed by markdown element name.
 */
export const buildMarkdownRenderers = ({
    isDark,
    t,
    mermaidCaptions,
    reading = false,
    plain = false,
    codeElevated = false,
}: MarkdownRenderersParams): Components => {
    // Long-form lessons read the larger scale; cards / chat / modals keep the compact one.
    const bodySize = reading ? "base" : "sm"
    const h2Size = reading ? PROSE_SIZE["2xl"] : PROSE_SIZE.lg
    const h3Size = reading ? PROSE_SIZE.xl : PROSE_SIZE.base
    // Reading-only asymmetric rhythm: a heading carries MORE space above than below so it
    // reads as a new section binding to the text under it (Tailwind-prose style). Compact
    // mode leaves block renderers margin-free and relies on the wrapper's uniform space-y.
    const h2Margin = reading ? "mt-10 mb-3" : ""
    const h3Margin = reading ? "mt-8 mb-3" : ""
    const blockMy = reading ? "my-4" : ""
    // Heading deep-link anchor only in reading mode (cards / chat have no shareable url).
    const anchorLabel = reading ? t("markdown.headingAnchor") : ""
    return ({
        h1: ({ children }) => (
            <ProseText elementType="h1" size={reading ? "2xl" : "xl"} className={reading ? "mb-4 font-semibold" : "font-semibold"}>{children}</ProseText>
        ),
        h2: buildTocHeading(2, h2Size, h2Margin, anchorLabel),
        h3: buildTocHeading(3, h3Size, h3Margin, anchorLabel),
        // TOC caps at 3 levels (h2/h3/h4). Reading h4 goes through the TOC factory (id + data-toc
        // + anchor) so 2.1.x sub-sections show in the rail; compact (cards/chat, no TOC) stays muted.
        h4: reading
            ? buildTocHeading(4, PROSE_SIZE.base, "mt-6 mb-2", anchorLabel)
            : ({ children }) => <ProseText elementType="h4" size="sm" className="font-semibold text-muted">{children}</ProseText>,
        // h5 stays a readable heading in the article (foreground + weight in reading) but is NOT in
        // the TOC — deeper than 3 levels (e.g. 2.1.3.2 → h5) would over-nest the outline rail.
        h5: ({ children }) => (
            reading
                ? <ProseText elementType="h5" size="sm" className="mt-4 mb-2 font-semibold">{children}</ProseText>
                : <ProseText elementType="h5" size="sm" className="font-semibold text-muted">{children}</ProseText>
        ),
        h6: ({ children }) => (
            reading
                ? <ProseText elementType="h6" size="sm" className="mt-4 mb-2 font-semibold text-muted">{children}</ProseText>
                : <ProseText elementType="h6" size="xs" className="font-semibold text-muted">{children}</ProseText>
        ),
        // Custom `:::muted` directive tags (see remarkMuted in ./index): small, muted label text.
        // `[&_*]:text-muted` forces the muted colour onto any inner `<p>` the container wraps.
        mutedblock: ({ children }: MarkdownChildrenProps) => (
            <ProseText elementType="div" size="sm" className="font-semibold text-muted [&_*]:text-muted">{children}</ProseText>
        ),
        mutedtext: ({ children }: MarkdownChildrenProps) => (
            <ProseText elementType="span" size="sm" className="font-semibold text-muted">{children}</ProseText>
        ),
        // `:::muted`/bold-label + its body, boxed as one Interview Arc section — opt-in via
        // `MarkdownContent`'s `arcSections` prop (see remarkArcSections in ./index).
        arcsection: ArcSection,
        // Custom `:::chip` directive tag (see remarkChip in ./index): a wrapped row of soft chips,
        // one per authored keyword line. `items` is the `|`-joined keyword list.
        chipblock: ({ items }: ChipBlockProps) => (
            <span data-principle="sibling-stack" className="my-2 flex flex-wrap gap-2">
                {String(items ?? "").split("|").filter(Boolean).map((keyword, index) => (
                    <HeroUI.Chip key={index} size="sm" variant="soft" color="default">{keyword}</HeroUI.Chip>
                ))}
            </span>
        ),
        // :::tab → [ Preview | Code ] tabs; code/preview panes carry `kind` so TabsBlock can match them.
        tabblock: ({ children }: MarkdownChildrenProps) => <TabsBlock>{children}</TabsBlock>,
        tabcode: ({ children }: MarkdownChildrenProps) => <TabPane kind="code">{children}</TabPane>,
        tabpreview: ({ children }: MarkdownChildrenProps) => <TabPane kind="preview">{children}</TabPane>,
        // ::::accordion / :::panel{title} → HeroUI collapsible accordion (see remarkAccordion in ./index).
        // Matches the `LabeledAccordionCard` skin (accordion.md §3e): `variant="default"` keeps the item
        // separator FULL-BLEED (`left-0 w-full`; surface would inset it to 3%), with the light hairline
        // `--separator` re-point so dividers read the same as the SurfaceListCard family. Default bakes no
        // bg/radius, so add `bg-surface rounded-3xl` here; `border` delineates it as a nested surface
        // (reading column / step card) where a shadow can vanish in dark mode.
        accordionblock: ({ children }: MarkdownChildrenProps) => (
            <HeroUI.Accordion
                variant="default"
                style={{ "--separator": "color-mix(in oklab, var(--surface-foreground) 6%, transparent)" } as React.CSSProperties}
                className={`${reading ? "my-4" : "my-2"} overflow-hidden rounded-3xl border border-default bg-surface`}
            >{children}</HeroUI.Accordion>
        ),
        accordionpanel: ({ title, children }: AccordionPanelProps) => (
            <HeroUI.Accordion.Item aria-label={String(title ?? "")}>
                <HeroUI.Accordion.Heading>
                    <HeroUI.Accordion.Trigger>
                        <div className="flex w-full items-center justify-between gap-3 text-start">
                            <span className={reading ? "text-base font-semibold" : "text-sm font-semibold"}>{title}</span>
                            <HeroUI.Accordion.Indicator />
                        </div>
                    </HeroUI.Accordion.Trigger>
                </HeroUI.Accordion.Heading>
                <HeroUI.Accordion.Panel>
                    <HeroUI.Accordion.Body>
                        <div className="space-y-2">{children}</div>
                    </HeroUI.Accordion.Body>
                </HeroUI.Accordion.Panel>
            </HeroUI.Accordion.Item>
        ),
        table: ({ children }) => (
            <MarkdownTable ariaLabel={t("markdown.tableAriaLabel")} className={blockMy}>
                {children}
            </MarkdownTable>
        ),
        thead: MarkdownTableHead,
        img: ({ src, alt }) => (
            // Markdown `![caption](src)`: a non-empty alt doubles as a real figure caption;
            // an empty alt renders a bare (decorative) image.
            alt ? (
                <figure className={reading ? "my-4" : undefined}>
                    <img src={src} alt={alt} className="w-full rounded-xl border border-default" />
                    <figcaption className="mt-2 text-center text-sm italic text-muted">{alt}</figcaption>
                </figure>
            ) : (
                <img src={src} alt="" className={`${reading ? "my-4 " : ""}w-full rounded-xl border border-default`} />
            )
        ),
        tbody: MarkdownTableBody,
        th: MarkdownTableColumn,
        td: ({ children }) => <Table.Cell>{children}</Table.Cell>,
        tr: MarkdownTableRow,
        code: (
            { children, node }
        ) => {
            const code = String(children).trim()
            const isInline = node ? isInlineCode(node) : undefined
            if (!isInline) {
                return children
            }
            // plain mode: inline code renders as its raw text (no mono/background) —
            // teacher, 2026-07-17: "render it raw" for flashcard + mock interview.
            if (plain) {
                return <>{code}</>
            }
            // Neutral inline code (GitHub/Stripe-style): subtle surface + foreground text, NOT
            // the brand accent — accent is reserved for links so a keyword-dense paragraph stays calm.
            return (
                <code className="rounded-md bg-default px-1 py-0 font-mono text-sm text-foreground [overflow-wrap:anywhere]">
                    {code}
                </code>
            )
        },
        pre: ({ children }) => {
            const child = React.Children.only(children) as React.ReactElement
            const className = (child.props as { className?: string }).className || ""
            const match = /language-(\w+)/.exec(className)
            const lang = match?.[1] || "bash"
            const code = String((child.props as { children?: React.ReactNode }).children || "").replace(/\n$/, "")
            if (lang.toLowerCase() === "mermaid") {
                return (
                    <div className={blockMy}>
                        <MermaidDiagram
                            code={code}
                            theme={isDark ? "dark" : "default"}
                            loadingLabel={t("markdown.mermaidRendering")}
                            expandLabel={t("markdown.mermaidExpand")}
                            caption={mermaidCaptions[code.trim()]}
                            fallbackLabel={t("markdown.mermaidFigureLabel")}
                        />
                    </div>
                )
            }
            // ```mdx fence → live HeroUI render (render-only; tabs come from a :::tab block).
            if (lang.toLowerCase() === "mdx") {
                return <RenderReactComponent code={code} />
            }
            if (lang.toLowerCase() === "layout") {
                return <LayoutWidget html={code} />
            }
            return (
                <div className={blockMy}>
                    <CodeToHtml
                        code={code}
                        language={lang}
                        theme={isDark
                            ? "material-theme-darker"
                            : "material-theme-lighter"}
                        elevated={codeElevated}
                    />
                </div>
            )
        },
        blockquote: ({ children }) => (
            <blockquote className={`${reading ? "my-4 " : ""}space-y-2 rounded-r-xl border-l-2 border-accent bg-default/40 px-4 py-2 text-muted`}>
                {children}
            </blockquote>
        ),
        // Bold = weight only — no colour jump — so a keyword-heavy paragraph doesn't flicker.
        // plain mode drops the weight/italic entirely → raw text (teacher, 2026-07-17: "render it raw").
        strong: ({ children }) => (plain ? <>{children}</> : <strong className="font-semibold">{children}</strong>),
        em: ({ children }) => (plain ? <>{children}</> : <em className="italic">{children}</em>),
        hr: () => <hr className={`${reading ? "my-6 " : ""}border-default`} />,
        ol: ({ children }) => <ol className={`${reading ? "my-4 " : ""}list-decimal space-y-2 pl-5 marker:text-muted`}>{children}</ol>,
        ul: ({ children }) => <ul className={`${reading ? "my-4 " : ""}list-disc space-y-2 pl-5 marker:text-muted`}>{children}</ul>,
        li: ({ children }) => (
            <ProseText elementType="li" size={bodySize} className="space-y-2 leading-relaxed">{children}</ProseText>
        ),
        p: ({ children, node }) => {
            // a paragraph whose ENTIRE content is one `**bold**` span is a common
            // "fake heading" authoring idiom (e.g. flashcard answers structured
            // "**Direct answer** ...", "**Why** ...") — read it as a section
            // LABEL (muted, small), not a normal bold sentence, so it lines up
            // with the surrounding UI labels ("Question"/"Answer" are
            // `body-xs muted`) instead of standing out as loud black bold.
            const soleChild = node?.children?.length === 1 ? node.children[0] : null
            const isStandaloneLabel = Boolean(
                soleChild && "tagName" in soleChild && soleChild.tagName === "strong",
            )
            if (isStandaloneLabel) {
                return <div className="text-sm text-muted">{children}</div>
            }
            return (
                <ProseText elementType="div" size={bodySize} className={reading ? "mb-4 leading-relaxed" : "leading-relaxed"}>{children}</ProseText>
            )
        },
        a: ({ href, children }) => {
        // plain mode: strip the link chrome (accent + underline) → raw text (teacher, 2026-07-17).
            if (plain) {
                return <>{children}</>
            }
            // Internal links (e.g. related-problem `/practice/<slug>`) navigate in-app
            // (same tab, locale-aware) via the next-intl Link; external links open a new tab.
            const isInternal = typeof href === "string" && href.startsWith("/")
            if (isInternal) {
                return (
                    <IntlLink href={href} className="!inline text-accent-soft-foreground underline underline-offset-4 decoration-[var(--separator-tertiary)]">
                        {children}
                    </IntlLink>
                )
            }
            return (
                <Link href={href} target="_blank" className="!inline text-accent-soft-foreground underline underline-offset-4 decoration-[var(--separator-tertiary)]">
                    {children}
                </Link>
            )
        },
    } as Components)
}

import type {
    useTranslations,
} from "next-intl"

/** Translator returned by next-intl's `useTranslations`, passed to the renderers factory. */
export type MarkdownTranslator = ReturnType<typeof useTranslations>

/** Params for {@link buildMarkdownRenderers} — theme + translator drive the code blocks. */
export interface MarkdownRenderersParams {
    /** True when the app theme is dark; selects mermaid/shiki themes. */
    isDark: boolean
    /** Translator for table aria labels and diagram loading text. */
    t: MarkdownTranslator
    /** Figure captions keyed by trimmed mermaid source, paired from the following paragraph. */
    mermaidCaptions: Record<string, string>
    /**
     * Reading-grade typography: when true, body/headings render at the larger
     * long-form scale (16px body, stronger heading ladder) for full lesson
     * articles. Defaults to the compact scale used in cards / chat / modals.
     */
    reading?: boolean
    /**
     * Plain-text mode: strip INLINE markdown decoration to unstyled text — inline
     * `code` (no mono/background), `strong` (no bold), `em` (no italic) and links
     * (no accent/underline) render as their raw text. Block structure is KEPT
     * (paragraphs, lists, tables, fenced code blocks, mermaid, and the `:::muted`
     * arc-section labels). Opt-in for the flashcard + mock-interview surfaces where
     * authored content carries stray inline markdown that shouldn't be styled (teacher,
     * 2026-07-17: "render it raw"). Cloze `{{cN::}}` is untouched (handled upstream).
     */
    plain?: boolean
    /**
     * Render fenced code blocks as RAISED cards (`bg-surface` + shadow) instead
     * of the default recessed wells (`bg-background`). Opt-in for surfaces that
     * render markdown directly on the page CANVAS (e.g. the Playground left pane),
     * where a `bg-background` code well would blend canvas-on-canvas. Forwarded to
     * {@link CodeToHtml}'s `elevated` prop. Defaults off (lesson/card content keeps
     * the recessed well that reads correctly on a surface).
     */
    codeElevated?: boolean
