    /**
     * Renders a trailing COMPACT close (×) — click it to remove the token
     * outright (no re-pick flow). Own compact scale (size-6 hit, size-4
     * glyph), like a chip's cancel-×, not the button-scale edit affordance.
     */
    onRemove?: () => void
    /** Accessible label for the remove (×) button. Falls back to "Remove". */
    removeLabel?: string
    /** Disables both affordances and dims the token. */
    isDisabled?: boolean
    /** `true` → render the skeleton mirror (row frame + placeholder bars). */
    isSkeleton?: boolean
}

/**
 * Generic selected-item token: a bordered `rounded-2xl` row holding an
 * optional leading icon + label, with an optional trailing remove (×) and/or
 * edit ("Change"-style) affordance. Compact — one line, no wrapping content.
 * Presentational; the only callbacks it takes are the two trailing
 * affordances.
 *
 * @param props - {@link RemovableTokenProps}
 */
/** Source-level tier metadata — see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "RemovableToken" } as const

/** A bordered row token showing a label with optional remove (x) and edit affordances. */
export const RemovableToken = ({
    label,
    icon: Icon,
    onEdit,
    editLabel = "Change",
    onRemove,
    removeLabel = "Remove",
    isDisabled = false,
    
    isSkeleton = false}: RemovableTokenProps) => {
    // One render path: the row's own frame stays identical whether loading or not;
    // only the trailing affordance's CONTENT differs (a shimmer pill vs the real
    // edit/remove controls) — `Button`/`Typography` each draw their own shimmer,
    // this composite only decides which parts show and how many (COMPOSITE-10).
    const trailing = isSkeleton ? (
        <span className="shrink-0"><Button isSkeleton size="sm" /></span>
    ) : onEdit || onRemove ? (
        <StackH
            gap={3}
            classNames={["shrink-0"]}
            items={[
                ...(onEdit
                    ? [() => (
                        <Button variant="tertiary" size="sm" isDisabled={isDisabled} onPress={onEdit} prefixIcon={XIcon} label={editLabel} />
                    )]
                    : []),
                ...(onRemove
                    ? [() => (
                        // Compact chip-scale close × (NOT the button-scale edit
                        // affordance above) — a real <button> for a11y.
                        <button
                            type="button"
                            aria-label={removeLabel}
                            disabled={isDisabled}
                            onClick={onRemove}
                            className="inline-flex size-6 shrink-0 cursor-pointer items-center justify-center rounded-full text-muted outline-none transition hover:bg-default hover:text-foreground focus-visible:ring-2 focus-visible:ring-accent disabled:cursor-not-allowed [&_svg]:size-4"
                        >
                            <XIcon aria-hidden focusable="false" />
                        </button>
                    )]
                    : []),
            ]}
        />
    ) : null

    return (
        <div
            aria-disabled={isDisabled}
            className={cn(
                "flex items-center justify-between gap-3 rounded-2xl border border-default px-3 py-3",
                isDisabled && "opacity-50")}
            data-tier="composite"
            data-component="RemovableToken"
            data-principle="cell-pad"
        >
            <StackH
                gap={3}
                classNames={["min-w-0"]}
                items={[
                    ...(Icon
                        ? [() => (
                            // COMPOSITE owns the size (§4) — the atom's own scale, not the
                            // caller's. A component reference can still be called during
                            // `isSkeleton` (it's static chrome, not loaded data), so it
                            // always renders — no shimmer needed for it either way.
                            <span aria-hidden className="inline-flex shrink-0 [&_svg]:size-4">
                                <Icon />
                            </span>
                        )]
                        : []),
                    () => (
                        <Typography
                            size="sm"
                            weight="medium"
                            truncate
                            isSkeleton={isSkeleton}
                            text={label}
                        />
                    ),
                ]}
            />
            {trailing}
        </div>
    )
}

import { cn } from "@heroui/react"
import { Typography } from "@/components/atoms/text/Typography"
import { Divider } from "@/components/atoms/display/Divider"
import { SnippetIcon } from "@/components/atoms/display/SnippetIcon"
import { StackH, StackV } from "@/components/frames/Stack"
import { GAP_CLASS, type AllowedGap } from "@/components/frames/_spacing"

/**
 * ─────────────────────────────────────────────────────────────────────────────
 * COMPOSITE TIER (§13) — `KeyValue.*`: the LABEL–VALUE pair COMPOSITE.
 *
 * | Member | Shape | Content channel |
 * |---|---|---|
 * | `.Row`  | ONE label–value pair | data props (`label`/`value`/`hint`) |
 * | `.List` | N pairs stacked vertically | **`items` DATA — children FORBIDDEN** (§13b) |
 *
 * Use for spec tables, order summaries, invoices — anywhere "one name, one number"
 * repeats into a block.
 *
 * COMPOSITE API LAW:
 *   • The composite carries NO domain content and **does NOT format** money/dates/units —
 *     the consumer passes an ALREADY-formatted `string` into `value` (`"1,200,000 ₫"`).
 *     `label`/`value` are `string`, never `ReactNode` (COMPOSITE-8, "the same trap one
 *     level in") — the row wraps each in `Typography` itself, which is what lets it
 *     shimmer either one while `isSkeleton`.
 *   • The composite does NOT grow functionality (no self-computed totals): `emphasis` is
 *     only a visual STRESS for a total row, the number is still supplied by the consumer.
 *   • `.List` is a repeated list ⇒ `items` is REQUIRED, children are forbidden.
 *
 * COMPOSE (§13c): text goes ENTIRELY through the `Typography.*` atom (§9 — no scattered
 * `text-*`/`font-*`), rules go through the `Divider` atom. The composite only handles
 * LAYOUT + the spacing scale.
 *
 * §10 — the gap scale is ENFORCED BY TYPE ({@link AllowedGap}): only `1..8`, the
 * composite doesn't accept arbitrary numbers so it can't drift off the scale.
 * ─────────────────────────────────────────────────────────────────────────────
 */


/** Source-level tier metadata — see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "KeyValue" } as const

// ─────────────────────────────────────────────────────────────────────────────
// .Row — ONE label–value pair
// ─────────────────────────────────────────────────────────────────────────────

/** Props every {@link KeyValueRow} carries regardless of loading state. */
interface KeyValueRowOwnProps {
    /**
     * Sub-line below the label (explanation/unit/condition) — muted, smaller size.
     * A plain `string`: the row wraps it in `Typography` itself (COMPOSITE-8) — a
     * built node here would already be called and unable to shimmer.
     */
    hint?: string
    /** `true` → a TOTAL row: label goes to foreground medium, value goes to base size + bold. */
    emphasis?: boolean
    /** `true` → draws a SEPARATOR line below the row (seam between this row and the next). */
    divider?: boolean
    /** Gap between the row's content and the `divider` line (§10). Default `4` (`gap-3`). */
    gap?: AllowedGap
    /**
     * `true` → renders a one-tap {@link SnippetIcon} copy affordance beside the
     * value, copying the row's `value` string to the clipboard. Additive:
     * default `false`, so an existing row with no `copyable` renders exactly as
     * before. The affordance is skipped entirely while `isSkeleton` — there is
     * nothing real yet to copy, so the row decides not to draw it rather than
     * shimmer a control with no value behind it (COMPOSITE-10).
     */
    copyable?: boolean
}

/**
 * Props for {@link KeyValueRow}. `label`/`value` are REQUIRED unless `isSkeleton`
 * (§12b) — a shimmer row has no real pair to show yet.
 */
export type KeyValueRowProps = KeyValueRowOwnProps &
    (
        | { isSkeleton: true; label?: string; value?: string }
        | { isSkeleton?: false; label: string; value: string }
    )

/**
 * One label–value row: label (+`hint`) sits left, value sits right, `tabular-nums`
 * keeps the digits aligned in a column when rows stack (§3). `emphasis` is the
 * STRESS level for a total row.
 *
 * @param props - {@link KeyValueRowProps}
 */
const KeyValueRow = ({
    label,
    value,
    hint,
    emphasis = false,
    divider = false,
    gap = 4,
    copyable = false,
    isSkeleton = false,
}: KeyValueRowProps) => {
    // COMPOSITE-10: ONE render path — same two-column `StackH`, same label+hint
    // `StackV` cluster, in both states. Every piece of text goes through
    // `Typography`'s own `isSkeleton` (§12c: the atom draws its own bar, sized to
    // its own value) — there is no second, hand-built skeleton pair to keep in
    // sync with this one.
    // Label column: label + hint form a TIGHT cluster (§10b `tight` = gap-1) — the
    // same "a label continuing into its hint" shape the registry names `title-subtitle`.
    const pairContent = [
        () => (
            <StackV
                gap={2}
                classNames={["min-w-0"]}
                principle="title-subtitle"
                explain="Title over supporting line — not label-field, because neither line is a form control label."
                items={[
                    () => (
                        <span>
                            <Typography size="sm"
                                text={label}
                                color={isSkeleton ? undefined : (emphasis ? undefined : "muted")}
                                weight={isSkeleton ? undefined : (emphasis ? "medium" : undefined)}
                                isSkeleton={isSkeleton}
                                classNames={isSkeleton ? ["w-1/3"] : undefined}
                            />
                        </span>
                    ),
                    ...(hint != null
                        ? [() => (
                            <span>
                                <Typography size="xs"
                                    text={hint}
                                    color={isSkeleton ? undefined : "muted"}
                                    isSkeleton={isSkeleton}
                                    classNames={isSkeleton ? ["w-1/4"] : undefined}
                                />
                            </span>
                        )]
                        : []),
                ]}
            />
        ),
        () => (
            <span
                className={cn("flex shrink-0 items-center", copyable && !isSkeleton && "gap-2")}
                data-principle={copyable && !isSkeleton ? "flex-action" : undefined}
            >
                <span>
                    {emphasis ? (
                        <Typography text={value} weight={isSkeleton ? undefined : "bold"} tabularNums={!isSkeleton} isSkeleton={isSkeleton} classNames={isSkeleton ? ["w-1/4"] : undefined} />
                    ) : (
                        <Typography size="sm" text={value} weight={isSkeleton ? undefined : "medium"} tabularNums={!isSkeleton} isSkeleton={isSkeleton} classNames={isSkeleton ? ["w-1/4"] : undefined} />
                    )}
                </span>
                {copyable && !isSkeleton ? (
                    <span>
                        {/* `value` is guaranteed a real string whenever `!isSkeleton` (the
                            discriminated union above) — the `?? ""` only satisfies narrowing
                            across the destructure and is never seen. */}
                        <SnippetIcon copyString={value ?? ""} />
                    </span>
                ) : null}
            </span>
        ),
    ]
    const row = (
        <StackH
            align="start"
            justify="between"
            gap={3}
            principle="value-row"
            explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
            items={pairContent}
        />
    )
    if (!divider) {
        return row
    }
    return (
        <div className={cn("flex flex-col", GAP_CLASS[gap])}>
            {row}
            <span className="block">
                <Divider variant="tertiary" />
            </span>
        </div>
    )
}

// ─────────────────────────────────────────────────────────────────────────────
// .List — N pairs stacked vertically (repeated list ⇒ items)
// ─────────────────────────────────────────────────────────────────────────────

/** ONE row in {@link KeyValueList} — described as DATA, not JSX. */
export interface KeyValueListItem {
    /** React key. */
    key: string
    /** Label (left side). `string` — the row wraps it in `Typography` itself. */
    label: string
    /** Value (right side) — an already-formatted `string` (COMPOSITE-8). */
    value: string
    /** Sub-line below the label. Plain `string` — see {@link KeyValueRowOwnProps.hint}. */
    hint?: string
    /** `true` → a TOTAL row (visual emphasis). */
    emphasis?: boolean
    /** `true` → this row gets the {@link KeyValueRowOwnProps.copyable} copy affordance. */
    copyable?: boolean
}

/** Props for {@link KeyValueList}. */
export interface KeyValueListProps {
    /** The rows, in reading order. REQUIRED — a repeated list = data (§13b). */
    items: ReadonlyArray<KeyValueListItem>
    /** Gap between rows, ENFORCED by the §10 scale. Default `4` (`gap-3`, vertical rows). */
    gap?: AllowedGap
    /** `true` → draws a separator line BETWEEN rows (the last row has none). */
    divider?: boolean
    /**
     * `true` → render `skeletonRows` placeholder rows instead of `items` (same
     * contract as `List.Labeled`'s own `isSkeleton`/`skeletonRows` pair).
     */
    isSkeleton?: boolean
    /** Placeholder row count while `isSkeleton`. Defaults to `3`. */
    skeletonRows?: number
}

/**
 * A column of {@link KeyValueRow} rows built from `items`. The separator line (if
 * enabled) is decided by the LIST — the LAST row has none, so the seam always sits
 * BETWEEN two rows instead of leaving a stray line dangling at the bottom. The gap
 * around each row-and-line shares the list's `gap` ⇒ the rhythm above/below the line
 * is always even (§10a: one seam, one owner).
 *
 * @param props - {@link KeyValueListProps}
 */
const KeyValueList = ({
    items,
    gap = 4,
    divider = false,
    isSkeleton = false,
    skeletonRows = 3,
}: KeyValueListProps) => (
    <div
        className={cn("flex flex-col", GAP_CLASS[gap])}
        data-tier="composite"
        data-component="KeyValueList"
    >
        {isSkeleton
            ? Array.from({ length: skeletonRows }, (_unused, index) => (
                <KeyValueRow key={index} isSkeleton divider={divider && index < skeletonRows - 1} gap={gap} />
            ))
            : items.map(({ key, ...item }, index) => (
                <KeyValueRow
                    key={key}
                    {...item}
                    divider={divider && index < items.length - 1}
                    gap={gap}
                />
            ))}
    </div>
)

/**
 * `KeyValue.*` — the label–value pair composite (COMPOSITE tier §13). `Row` (one pair) ·
 * `List` (N pairs, `items`). Visual variants = PROP (`emphasis`/`divider`), §6b.
 */
export { KeyValueRow, KeyValueList }

import React from "react"
import { cn } from "@heroui/react"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * ─────────────────────────────────────────────────────────────────────────────
 * STORYBOOK-LOCAL DESIGN SPEC — `Page.*`, the ONE page-chrome frame namespace
 * (teacher's call, 2026-07-25, canon §13a). Sibling frames that used to live as loose
 * folders (`PageHeader` · `StickyBottomBar`) are now MEMBERS of one namespace
 * — same tier (frame / layout), same family (chrome of a ROUTE: what sits above
 * the content and pinned under it), one import.
 *
 * FRAME API LAW (§13b):
 * - `PageBottomBar` is a WRAPPER frame -> named slots `body`/`actions` (a bar
 *   is a horizontal row, so `header`/`footer` would be a lie).
 * - `PageHeader` is NOT a generic wrapper — it already owns semantic slots
 *   (`breadcrumb`/`title`/`description`/`actions`/`meta`) and deliberately
 *   takes no `children`.
 * - No repeating list here, so no `items` member (§13b list clause N/A).
 * - Namespace only — no bare component export.
 *
 * Behaviour/skin of every member is carried over VERBATIM from its old folder;
 * this is an API refactor, not a visual one. Synced to `src` later. No
 * `@/components` imports (design-spec ports stay self-contained).
 *
 * HISTORY — `.Container` was moved to `Container` (`@/components/frames/Container/Container`)
 * on 2026-07-26: the old frame had no `mx-auto`, no `max-w`, only right padding —
 * a half-baked version of the "content width" concept that `Container` already
 * does correctly (§13c: a duplicate frame gets deleted).
 *
 * COMPOSITE-8 — both `PageHeader` and `PageBottomBar` own an `isSkeleton` of
 * their own, so every slot they render is a COMPONENT reference
 * (`ComponentType<{ isSkeleton?: boolean }>`), never a pre-built node: the
 * frame calls it itself so it can forward `isSkeleton` into it. Text the
 * frame renders directly through `Typography` (`title`/`description`) is a
 * plain `string` instead — the frame wraps it in the atom itself.
 * ─────────────────────────────────────────────────────────────────────────────
 */

/** Source-level tier metadata — see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "Page" } as const

// ─────────────────────────────────────────────────────────────────────────────
// .Header — the breadcrumb/title/description/actions/meta block (was `PageHeader`)
// ─────────────────────────────────────────────────────────────────────────────

/** Props {@link PageHeader} carries regardless of loading state. */
interface PageHeaderOwnProps {

    /**
     * Optional supporting description placed directly below the title. The
     * frame renders it through `Typography` itself (`text-sm`, muted tone) and
     * forwards `isSkeleton`, so this is plain text (COMPOSITE-8), not a
     * pre-built node. Omit when the title is self-explanatory.
     */
    description?: string
    /**
     * Optional breadcrumb row rendered above the title row, as a COMPONENT
     * reference (COMPOSITE-8) — the frame calls it itself. Typically a
     * `<Breadcrumbs>` house atom or a `LinkBack`. Omitted entirely while
     * loading (a route rarely needs it before data lands).
     */
    breadcrumb?: ComponentTypeWithSkeleton
    /**
     * Optional right-aligned slot for action controls, as a COMPONENT
     * reference — the frame calls it and renders it `shrink-0` so it never
     * compresses the title column. Omitted entirely while loading.
     */
    actions?: ComponentTypeWithSkeleton
    /**
     * Optional meta row placed BELOW the title/description — typically a row
     * of stat/meta chips ("24 Modules · 87 Content items …") — as a
     * COMPONENT reference. Rendered `gap-3` from the title block. While
     * loading, the frame draws its OWN 2-chip placeholder instead of calling
     * this (COMPOSITE-10: the frame decides how many, not this slot). Omit
     * when the header carries no stats.
     */
    meta?: ComponentTypeWithSkeleton
    /**
     * Title scale. `"page"` (default) = `Typography.Heading` level 3 — a route's
     * OWN page title. `"compact"` = body-size bold, for a header that labels a
     * PANE/PHASE inside an existing page shell.
     */
    size?: "page" | "compact"
    /**
     * Where this sits inside its parent. Appearance is not passable — it is already a prop.
     */
    classNames?: Array<AllowedClassName>
}

/**
 * Props for {@link PageHeader}. `title` is REQUIRED unless `isSkeleton` (§12b) —
 * a shimmer header has no real title to show yet.
 */
export type PageHeaderProps = PageHeaderOwnProps &
    (
        | {
            isSkeleton: true
            /** Primary page or section title. See the live variant's doc for the full contract. */
            title?: string
        }
        | {
            isSkeleton?: false
            /**
             * Primary page or section title. Rendered at `text-xl font-medium` in the
             * foreground tone through `Typography` (COMPOSITE-8: the frame builds it
             * itself, so this is plain text).
             */
            title: string
        }
    )

/**
 * Page/section header frame. Renders an optional breadcrumb row above a flex
 * row that places a stacked title + description on the left and optional action
 * controls on the right.
 *
 * This frame carries no card wrapper — the caller places it directly inside
 * a `Container` or wraps it in a `SectionCard` when a framed surface
 * is required.
 *
 * @param props - See {@link PageHeaderProps}.
 */
const Header = ({
    title,
    description,
    breadcrumb: Breadcrumb,
    actions: Actions,
    meta: Meta,
    size = "page",
    isSkeleton = false,
    classNames}: PageHeaderProps) => {
    // ONE render path (§12c) — every part this frame would render anyway stays,
    // each handed `isSkeleton`; the atoms draw their own shimmer. While loading, the
    // real shape (breadcrumb/description/meta presence) isn't known yet, so the
    // composite makes the same shape call the old hand-split branch made: assume a
    // description line and a 2-chip meta row, skip breadcrumb/actions (a route
    // rarely needs those before data lands).
    const showDescription = isSkeleton || description != null
    const showMeta = isSkeleton || Meta != null

    // Left column: stacked title and optional description
    const titleBlock = (
        <>
            {size === "compact" ? (
                <Typography weight="bold" isSkeleton={isSkeleton} text={title} />
            ) : (
                <Typography size="h3" weight="bold" isSkeleton={isSkeleton} text={title} />
            )}
            {showDescription ? (
                // clamp to 2 lines on mobile (keep the header short on a phone); full on sm+
                // — a viewport-width decision, so the wrapper owns it, not the atom.
                <div className={isSkeleton ? undefined : "line-clamp-2 @app-sm:line-clamp-none"}>
                    <Typography
                        size="sm"
                        color="muted"
                        isSkeleton={isSkeleton}
                        text={description}
                    />
                </div>
            ) : null}
        </>
    )
    // Main row: title+description stack on the left, actions pinned to the right
    const titleRow = (
        <StackH
            align="start"
            justify="between"
            gap={4}
            principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            items={[
                () => <StackV gap={3} classNames={["min-w-0"]} items={[() => titleBlock]} />,
                // Right slot: shrink-0 prevents action buttons from being squeezed.
                // Omitted while loading — the shape of the action row isn't known yet.
                ...(!isSkeleton && Actions ? [() => (
                    <div className="shrink-0"><Actions isSkeleton={isSkeleton} /></div>
                )] : []),
            ]}
        />
    )
    const headerBody = (
        <>
            {/* Breadcrumb row — rendered only when provided and loaded, sits above the main title row */}
            {!isSkeleton && Breadcrumb ? (
                <div><Breadcrumb isSkeleton={isSkeleton} /></div>
            ) : null}
            {titleRow}
            {/* Meta row: stat/meta chips below the title block (gap={4} from outer). While
                loading, 2 `Chip` placeholders stand in — the composite decides the count,
                the atom draws its own pill shimmer (no hand-rolled bar). */}
            {showMeta ? (
                isSkeleton ? (
                    <StackH
                        gap={3}
                        align="stretch"
                        principle="chip-row"
                        explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                        items={[
                            () => <Chip isSkeleton />,
                            () => <Chip isSkeleton />,
                        ]}
                    />
                ) : (
                    <div>{Meta ? <Meta isSkeleton={isSkeleton} /> : null}</div>
                )
            ) : null}
        </>
    )
    return (
        // outer gap={4}: breadcrumb <-> title-block <-> meta (different header tiers);
        // title <-> description stay a related gap={3} pair inside the title block.
        <StackV gap={4} classNames={classNames} items={[() => headerBody]} />
    )
}

// ─────────────────────────────────────────────────────────────────────────────
// .BottomBar — the viewport-pinned action bar (was `StickyBottomBar`)
// ─────────────────────────────────────────────────────────────────────────────

/** Props for {@link PageBottomBar}. */
export interface PageBottomBarProps {
    /**
     * Leading content of the bar — typically a price — as a COMPONENT
     * reference (COMPOSITE-8): the frame calls it itself so it can forward
     * `isSkeleton`.
     */
    body?: ComponentTypeWithSkeleton
    /**
     * Trailing control(s) — the primary CTA — as a COMPONENT reference. When
     * BOTH `body` and `actions` are given the frame lays out the row itself
     * (`justify-between`, `shrink-0` on the actions) so callers stop
     * hand-rolling that flex row.
     */
    actions?: ComponentTypeWithSkeleton
    /** Shorthand for {@link PageBottomBarProps.body} — same component-reference contract. */
    /**
     * `true` -> forwarded into whichever of `body`/`actions` renders, so a bar
     * whose price/CTA is not known yet (e.g. still loading enrollment status)
     * can shimmer instead of showing stale content.
     */
    isSkeleton?: boolean
    /**
     * Where this sits inside its parent. Appearance is not passable — it is already a prop.
     */
    classNames?: Array<AllowedClassName>
}

/**
 * A fixed bottom action bar pinned to the viewport edge — owns the chrome
 * (fixed position, top divider, surface background, safe padding) so features
 * just drop a price + CTA inside. Typically `@app-md:hidden` for a mobile sticky
 * enroll/checkout bar.
 *
 * A bar is a horizontal row, so its named slots are `body` (leading) +
 * `actions` (trailing) rather than the vertical `header`/`body`/`footer` trio.
 * With only one of them the content renders RAW, so a full-width button or a
 * two-button decision row keeps its own sizing (`flex-1`, `w-full`).
 *
 * @param props - {@link PageBottomBarProps}
 */
const BottomBar = ({
    body,
    actions,
    isSkeleton = false,
    classNames}: PageBottomBarProps) => {
    const Main = body
    const Actions = actions
    const chrome = "fixed bottom-0 left-0 right-[var(--app-rail-w,0px)] z-40 border-t border-separator bg-background px-6 py-3"

    // Only ONE side supplied -> render it raw: the caller's own width strategy
    // (`w-full` CTA, two `flex-1` buttons) must not be boxed by a shrink-0 wrapper.
    if (Main == null || Actions == null) {
        const Only = Main ?? Actions
        return (
            <div className={cn(chrome, classNames)} data-tier="composite" data-component="PageBottomBar">
