 * rendered heading id and any "on this page" outline reading it from the DOM agree.
 * @param text - The raw heading text.
 * @returns The anchor slug.
 */
const slugify = (text: string): string =>
    text
        .normalize("NFKD")
        .replace(/[̀-ͯ]/g, "")
        .replace(/[đĐ]/g, "d") // vn-ok: slug transliteration of the VI letter
        .toLowerCase()
        .trim()
        .replace(/[^a-z0-9]+/g, "-")
        .replace(/^-+|-+$/g, "")

/**
 * Heading renderer factory: renders a section heading carrying a slug `id` +
 * `data-toc` markers so an "on this page" rail can scan the rendered article
 * (`[data-toc]`) and anchor-scroll to it. `scroll-mt-20` clears a sticky navbar
 * when jumped to. The hover `#` deep-link only renders in reading measure — cards
 * / chat / modals have no shareable url for it.
 * @param config - {@link TocHeadingConfig}
 */
const buildTocHeading = ({ level, sizeClass, marginClass, showAnchor }: TocHeadingConfig) =>
    ({ children }: MarkdownNodeProps) => {
        const Tag = `h${level}` as "h2" | "h3" | "h4"
        const text = getNodeText(children)
        const id = slugify(text)
        return (
            <Tag
                id={id}
                data-toc=""
                data-toc-level={level}
                data-toc-label={text}
                className={cn("group scroll-mt-20 font-semibold", marginClass, sizeClass)}
            >
                {children}
                {showAnchor ? (
                    <a
                        href={`#${id}`}
                        aria-label={HEADING_ANCHOR_LABEL}
                        className="ml-2 text-muted no-underline opacity-0 transition-opacity group-hover:opacity-100"
                    >
                        #
                    </a>
                ) : null}
            </Tag>
        )
    }

/** Params for {@link buildMarkdownRenderers}. */
export interface MarkdownRenderersParams {
    /** True when the Storybook toolbar theme is dark; selects mermaid/Shiki themes. */
    isDark: boolean
    /** Reading-grade typography (bigger type, generous rhythm) vs the compact scale. */
    reading: boolean
    /** Figure captions keyed by trimmed mermaid source, paired from the following paragraph. */
    mermaidCaptions: Record<string, string>
}

/**
 * Builds the element-renderer map handed to `ReactMarkdown`. See the file header
 * for scope; each renderer stays margin-free in compact measure (the wrapper in
 * `MarkdownContent.tsx` owns the uniform rhythm there) and carries its own
 * asymmetric margin in reading measure.
 * @param params - {@link MarkdownRenderersParams}
 */
export const buildMarkdownRenderers = ({ isDark, reading, mermaidCaptions }: MarkdownRenderersParams) => {
    const blockMy = reading ? "my-4" : "my-3"
    // Link text rides the same body scale as the surrounding prose.
    const linkSize = reading ? "base" : "sm"

    return {
        h1: ({ children }: MarkdownNodeProps) => (
            <h1 className={cn("font-semibold text-foreground", reading ? "mt-8 mb-3 text-2xl" : "mt-6 mb-2 text-xl")}>{children}</h1>
        ),
        h2: buildTocHeading({
            level: 2,
            sizeClass: reading ? "text-xl" : "text-lg",
            marginClass: reading ? "mt-8 mb-3" : "mt-6 mb-2",
            showAnchor: reading,
        }),
        h3: buildTocHeading({
            level: 3,
            sizeClass: reading ? "text-lg" : "text-base",
            marginClass: reading ? "mt-6 mb-2" : "mt-4 mb-2",
            showAnchor: reading,
        }),
        h4: buildTocHeading({
            level: 4,
            sizeClass: reading ? "text-base" : "text-sm",
            marginClass: reading ? "mt-6 mb-2" : "mt-4 mb-2",
            showAnchor: reading,
        }),
        p: ({ children }: MarkdownNodeProps) => (
            <p className={cn("text-foreground", reading ? "my-3 text-base leading-7" : "my-2 text-sm leading-6")}>{children}</p>
        ),
        ul: ({ children }: MarkdownNodeProps) => (
            <ul className={cn("list-disc pl-6", reading ? "my-3 space-y-1" : "my-2 space-y-1")}>{children}</ul>
        ),
        ol: ({ children }: MarkdownNodeProps) => (
            <ol className={cn("list-decimal pl-6", reading ? "my-3 space-y-1" : "my-2 space-y-1")}>{children}</ol>
        ),
        li: ({ children }: MarkdownNodeProps) => (
            <li className={cn("text-foreground", reading ? "text-base leading-7" : "text-sm leading-6")}>{children}</li>
        ),
        strong: ({ children }: MarkdownNodeProps) => (
            <strong className="font-semibold text-foreground">{children}</strong>
        ),
        em: ({ children }: MarkdownNodeProps) => <em className="italic">{children}</em>,
        // Internal (`/`-prefixed) links stay in the same tab; anything else is external and opens a
        // new tab. Reuses the `Typography` atom's `isLink` branch (HeroUI `Link` + a11y) rather than
        // hand-rolling an `<a>` — the atom already owns exactly this link skin everywhere else.
        a: ({ href, children }: MarkdownLinkProps) => {
            const isInternal = typeof href === "string" && href.startsWith("/")
            return (
                <Typography
                    size={linkSize}
                    isLink
                    href={href}
                    target={isInternal ? undefined : "_blank"}
                    rel={isInternal ? undefined : "noopener noreferrer"}
                    text={children}
                />
            )
        },
        blockquote: ({ children }: MarkdownNodeProps) => (
            <blockquote className={cn("border-l-2 border-default pl-3 text-muted", reading ? "my-4" : "my-3")}>{children}</blockquote>
        ),
        hr: () => <hr className={cn("border-default", reading ? "my-8" : "my-6")} />,
        // Markdown `![caption](src)`: a non-empty alt doubles as a real figure caption; an empty
        // alt renders a bare (decorative) image — same rule `src` uses.
        img: ({ src, alt }: MarkdownImageProps) => (
            alt ? (
                <figure className={blockMy}>
                    <img src={src} alt={alt} className="w-full rounded-2xl" />
                    <figcaption className="mt-2 text-center text-sm italic text-muted">{alt}</figcaption>
                </figure>
            ) : (
                <img src={src} alt="" className={cn("w-full rounded-2xl", blockMy)} />
            )
        ),
        // GFM table -> house `TableRoot` compound (see the file header on `MarkdownTableParts.tsx`
        // for why this is NOT the config-driven `composites/data/Table`). The block-rhythm margin
        // (COMPOSITE-4: `MarkdownTable` takes no `className`) is owned here, by the plain wrapping
        // `<div>` — margin is a seam between two blocks, not a prop of either one.
        table: ({ children }: MarkdownNodeProps) => (
            <div className={blockMy}>
                <MarkdownTable ariaLabel={TABLE_ARIA_LABEL}>{children}</MarkdownTable>
            </div>
        ),
        thead: MarkdownTableHead,
        tbody: MarkdownTableBody,
        tr: MarkdownTableRow,
        th: MarkdownTableColumn,
        td: MarkdownTableCell,
        // A fenced block's inner `code` carries `language-*`; anything else is inline.
        // react-markdown still passes `className`; rename to `fenceClass` at this boundary.
        code: ({ children, className }: MarkdownCodeRuntimeProps) => {
            const fenceClass = className
            if (fenceClass?.startsWith("language-")) {
                return children
            }
            return (
                // inset-exception: inline-code geometry, wider than tall by nature, not a surface inset
                // (same shape as `RichText`'s inline `<code>` — see `RichText.tsx`)
                <Box as="code" principle="control-pad" className="rounded-md bg-default px-1 py-0 font-mono text-sm text-foreground [overflow-wrap:anywhere]"
                    explain="Control hit-area inset — not row-pad, because this pads a single interactive control rather than a full content row.">
                    {children}
                </Box>
            )
        },
        // Fenced block dispatch: `mermaid` -> diagram, everything else -> Shiki.
        pre: ({ children }: MarkdownNodeProps) => {
            const child = React.Children.only(children) as React.ReactElement<MarkdownCodeRuntimeProps>
            const fenceClass = child.props.className
            const lang = /language-(\w+)/.exec(fenceClass ?? "")?.[1] ?? "text"
            const code = String(child.props.children ?? "").replace(/\n$/, "")
            // Block-rhythm margin (COMPOSITE-4: neither viewer takes `className`) owned by the
            // plain wrapping `<div>` — margin is a seam between two blocks, not either one's prop.
            if (lang.toLowerCase() === "mermaid") {
                return (
                    <div className={blockMy}>
                        <MermaidDiagram
                            code={code}
                            theme={isDark ? "dark" : "default"}
                            loadingLabel={MERMAID_LOADING_LABEL}
                            expandLabel={MERMAID_EXPAND_LABEL}
                            caption={mermaidCaptions[code.trim()]}
                            fallbackLabel={MERMAID_FALLBACK_LABEL}
                        />
                    </div>
                )
            }
            return (
                <div className={blockMy}>
                    <CodeToHtml
                        code={code}
                        language={lang}
                        theme={isDark ? "material-theme-darker" : "material-theme-lighter"}

                    />
                </div>
            )
        },
        // Custom `:::muted` directive tags (see `remarkMuted` in `MarkdownContent.tsx`): small,
        // muted label text. `[&_*]:text-muted` forces the muted colour onto any inner `<p>`.
        mutedblock: ({ children }: MarkdownNodeProps) => (
            <div className="text-sm font-semibold text-muted [&_*]:text-muted">{children}</div>
        ),
        mutedtext: ({ children }: MarkdownNodeProps) => (
            <span className="text-sm font-semibold text-muted">{children}</span>
        ),
        // Custom `:::chip` directive tag: a wrapped row of chips, one per authored keyword line.
        // Reuses the `Chip` ATOM (soft/neutral) rather than HeroUI `Chip` directly.
        chipblock: ({ items }: MarkdownChipBlockProps) => (
            <div className="my-2">
                <StackH
                    as="span"
                    at="sm"
                    gap={3}
                    principle="chip-row"
                    explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                    items={String(items ?? "").split("|").filter(Boolean).map((keyword) => () => (
                        <Chip tone="default" text={keyword} />
                    ))}
                />
            </div>
        ),
        // :::tab -> [ Preview | Code ] tabs; code/preview panes carry `kind` so `TabsBlock` matches them.
        tabblock: ({ children }: MarkdownNodeProps) => <TabsBlock>{children}</TabsBlock>,
        tabcode: ({ children }: MarkdownNodeProps) => <TabPane kind="code">{children}</TabPane>,
        tabpreview: ({ children }: MarkdownNodeProps) => <TabPane kind="preview">{children}</TabPane>,
        // ::::accordion / :::panel{title} -> house `AccordionTree` compound (incremental panels from
        // react-markdown — not the data-driven Disclosure `Accordion` atom). `variant="default"`
        // keeps the item separator FULL-BLEED, with the light hairline `--separator` re-point so
        // dividers read the same as the `SurfaceListCard` family; `border` delineates it as a
        // nested surface.
        accordionblock: ({ children }: MarkdownNodeProps) => (
            // `AccordionTree` omits `className` (atom door is closed); border/rhythm sit on the
            // wrapping seam so COMPOSITE-4 stays clean while the nested-surface look is preserved.
            <div className={cn("overflow-hidden border border-default bg-surface", blockMy)}>
                <AccordionTree
                    variant="default"
                    separatorTone="subtle"
                >
                    {children}
                </AccordionTree>
            </div>
        ),
        accordionpanel: ({ title, children }: MarkdownPanelProps) => (
            <AccordionTreeItem aria-label={String(title ?? "")}>
                <AccordionTreeHeading>
                    <AccordionTreeTrigger>
                        <div className="text-start">
                            <StackH
                                gap={4}
                                principle="content-row"
                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                justify="between"
                                items={[
                                    () => <span className={reading ? "text-base font-semibold" : "text-sm font-semibold"}>{title}</span>,
                                    () => <AccordionTreeIndicator />,
                                ]}
                            />
                        </div>
                    </AccordionTreeTrigger>
                </AccordionTreeHeading>
                <AccordionTreePanel>
                    <AccordionTreeBody>
                        <div className="space-y-2">{children}</div>
                    </AccordionTreeBody>
                </AccordionTreePanel>
            </AccordionTreeItem>
        ),
    }
}

import React from "react"
import type { ReactNode } from "react"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"
import { Divider } from "@/components/atoms/display/Divider"
import { type AllowedGap, type LayoutAlign, type LayoutJustify, type PaddingValue, type Responsive } from "@/components/frames/_spacing"
import { Flex } from "@/components/frames/Flex"
import type { ResponsiveRowSwitch } from "@/components/frames/ResponsiveRow"
import type { PrincipleToken, ExplainReason } from "@/components/frames/_principles"
import type { CallerIdentity } from "@/components/frames/_identity"

/**
 * ─────────────────────────────────────────────────────────────────────────────
 * LAYOUT (frame) -- `Stack.*`: the base one-axis track. Two members = two AXES,
 * the only real shapes a stack has:
 *   • `StackV` -- stacks VERTICALLY (column).
 *   • `StackH` -- stacks HORIZONTALLY (row); only this axis takes `at` (FRAME-10:
 *     the container step it wraps below, never a bare boolean).
 *
 * FRAME API LAW (§13b): a stack WRAPS arbitrary content -- it is not a repeating
 * list -- so `children` is the road (there is no `header`/`body`/`footer` trio to
 * name: a track has exactly ONE slot, its content). `items` would be wrong here;
 * see `Cluster`/`Grid` for the repeat-list frames of this folder.
 *
 * WHY THIS FRAME EXISTS: `gap` is typed {@link Responsive}<{@link AllowedGap}> -- a
 * CLOSED index into the house gap table. Off-scale (`gap-4.5`, `gap-[13px]`) cannot even
 * be typed, so the scale is enforced by the COMPILER instead of by review.
 * `gap` is REQUIRED for the same reason: an implicit default would let the seam
 * be chosen by accident, and §10a says a seam has exactly one deliberate owner.
 *
 * §13 boundaries respected: no domain content, no feature behaviour -- the track
 * only decides direction / gap / alignment / an optional rule between children.
 * `divider` COMPOSES the existing `Divider` atom (§13c: a frame never
 * hand-rolls what an atom already owns).
 * ─────────────────────────────────────────────────────────────────────────────
 */

/** Props shared by both axes of {@link Stack}. */
export interface StackBaseProps {
    /**
     * Seam between children on the house gap scale.
     * Optional when `principle` is a gap-owning token — the principle resolves the class.
     * Still required when there is no gap principle (Flex enforces at render via ownership).
     */
    gap?: Responsive<AllowedGap>
    /** Cross-axis alignment (`V` → horizontal, `H` → vertical). */
    align?: LayoutAlign
    /** Main-axis distribution (`V` → vertical, `H` → horizontal). */
    justify?: LayoutJustify
    /** `true` → inserts `Divider` BETWEEN children (never before the first / after the last). */
    divider?: boolean
    /**
     * Space INSIDE the track, same scale as `gap`.
     *
     * 2026-07-27: forwarded down to `Flex` so a stack that also needs padding no longer
     * has to DROP to `Flex` and lose `divider` plus the axis semantics. That drop was the
     * one remaining reason to reach past this frame, and a way out that costs less than the
     * proper road always wins -- the same force that produced 227 hand-written
     * `flex flex-col gap-4` in the first place.
     */
    padding?: Responsive<PaddingValue>
    /**
     * `true` → a left guide border + matching indent (`pl-3`, `@app-sm:pl-6`),
     * for a track that is ONE LEVEL DEEPER than its caller (a threaded reply,
     * a nested tree row) -- the frame owns the exact classes so no block ever
     * hand-writes `border-l`/`pl-*` itself (teacher 2026-07-28). Same vocabulary
     * as `SurfaceCard`'s own `variant="nested"` (border marks "inside a
     * parent", not a fresh outer face) -- this is that same idea for a track.
     */
    nested?: boolean
    /**
     * The HTML element to render, forwarded to `Flex`. Defaults to `div`.
     *
     * Added 2026-07-29 for the same reason `padding` was: a stack that also needed a real tag
     * (`section`, `figure`, `span`) had to DROP to hand-written classes and lose the axis
     * semantics along the way. Three call-sites sat outside the frame tier for exactly that.
     */
    as?: "div" | "section" | "figure" | "span" | "li"
    /**
     * `true` → the track hugs its content (`inline-flex`) instead of taking the whole line.
     * Measured on the same content: the block box came out 503px, the inline box 136px.
     */
    inline?: boolean
    /**
     * Anatomy tag for THIS frame itself -- so the PARENT can badge it as ONE node (§11a.1).
     * Missing this prop means the `layouts`-tier frame is used but the panel cannot see it.
     */
    /** A SINGLE buildable child -- an uncalled `ComponentType<{isSkeleton?}>` the track renders itself. Use `items` for several. */
    body?: ComponentTypeWithSkeleton
    /**
     * The stacked content as BUILDABLE items -- each an uncalled `ComponentType<{isSkeleton?}>`
     * the track renders itself, so it can thread `isSkeleton` down and interleave dividers. Preferred
     * over `body`: a frame that can BUILD its children can shimmer them (one tree, no hand-mirror).
     * Wins over `body` when both are passed.
     */
    items?: Array<ComponentTypeWithSkeleton>
    /** `true` → the track passes `isSkeleton` to every `items` component so the whole column shimmers. */
    isSkeleton?: boolean
    /**
     * Where this sits inside its parent. Appearance is not passable -- it is already a prop.
     */
    classNames?: Array<AllowedClassName>
    /**
     * The layout pattern this track's seam realises - forwarded straight to the `Flex` this
     * track renders through, the same way `gap`/`align`/`justify` are. See `Flex`'s own
     * `pattern` doc for the full contract. Query as `[data-principle="token"]`.
     */
    principle?: PrincipleToken
    /**
     * Why this layer exists - one sentence, emitted as `data-explain` beside the token.
     * A reason, never a restatement of `principle`. Forwarded to `Flex`.
     */
    explain?: ExplainReason
    /**
     * Caller identity to wear on this track's root instead of `Stack`'s own -- pass this when a
     * `block`/`layout`/`overlay`/`page` component (BLOCK-2: never draws a shape of its own) is
     * using this track AS its root element, instead of wrapping it in a raw `<div data-tier=...
     * data-component=...>`. Forwarded straight to `Flex`, which is what actually renders the DOM
     * (see `Flex`'s own `identity` doc). See `_identity.ts`. Omitted → this track keeps
     * emitting `data-tier="frame" data-component="Flex"`, unchanged.
     */
    identity?: CallerIdentity
}

/** Props for {@link StackV} -- a vertical track (no row-only prop to add). */
export type StackVProps = StackBaseProps

/** Props for {@link StackH} -- a horizontal track. */
export interface StackHProps extends StackBaseProps {
    /**
     * Container step the row switches from wrapped to single-line at (FRAME-10). Below `at`
     * children flow onto a new line when the row runs out of width; at `at` and above the row
     * stays single-line. ROW-ONLY: a column already grows without bound, so this is meaningless
     * on `StackV` and is not offered there. Left out, the row never wraps -- same behaviour the
     * old `wrap={false}` default had.
     */
    at?: ResponsiveRowSwitch
}

/**
 * Interleaves `Divider` between children -- NOT around them: N children get
 * N−1 rules. The atom carries its own `` (part name `Line`), so the
 * frame adds no wrapper element and the DOM is identical with badges on or off.
 *
 * On a ROW the rule is vertical and gets `self-stretch`: `align-self` overrides
 * the track's `items-*`, so the line spans the row's full height even when the
 * row is `items-center`.
 */
const interleaveDividers = (children: ReactNode, axis: "vertical" | "horizontal") => {
    const nodes = React.Children.toArray(children)
    // `axis` = the TRACK's direction; a rule always runs ACROSS it.
    const ruleOrientation = axis === "vertical" ? "horizontal" : "vertical"
    return nodes.flatMap((child, index) =>
        index === 0
            ? [child]
            : [
                <Divider
                    key={`stack-divider-${index}`}
                    orientation={ruleOrientation}
                    classNames={ruleOrientation === "vertical" ? ["self-stretch"] : undefined}
                />,
                child,
            ],
    )
}

/**
 * Vertical track -- the default way to stack anything down a column.
 *
 * @param props - {@link StackVProps}
 */
const StackV = ({
    as: Tag,
    inline,
    gap,
    align = "stretch",
    justify,
    divider = false,
    nested = false,
    body,
    items,
    isSkeleton,
    padding,
    classNames,
    principle,
    explain,
    identity}: StackVProps) => {
    // `items` (buildable) wins over legacy `body`: the track renders each item itself, threading
    // `isSkeleton`, so it can shimmer the whole column and interleave dividers on the real children.
    const content = (items ?? (body ? [body] : [])).map((Item, index) => <Item key={index} isSkeleton={isSkeleton} />)
    // Strict contract: when `principle` is set it owns the full CSS — do not forward
    // gap/padding/align/justify/classNames/inline/nested from the caller.
    if (principle) {
        return (
            <Flex
                as={Tag}
                direction="col"
                principle={principle}
                explain={explain}
                identity={identity}
                body={divider ? interleaveDividers(content, "vertical") : content}
            />
        )
    }
    return (
        <Flex
            as={Tag}
            inline={inline}
            direction="col"
            gap={gap}
            padding={padding}
            align={align}
            justify={justify}
            nested={nested}
            classNames={classNames}
            identity={identity}
            body={divider ? interleaveDividers(content, "vertical") : content}
        />
    )
}

const StackH = ({
    as: Tag,
    inline,
    gap,
    align = "center",
    justify,
    at,
    divider = false,
    nested = false,
    body,
    items,
    isSkeleton,
    padding,
    classNames,
    principle,
    explain,
    identity}: StackHProps) => {
    const content = (items ?? (body ? [body] : [])).map((Item, index) => <Item key={index} isSkeleton={isSkeleton} />)
    if (principle) {
        return (
            <Flex
                as={Tag}
                direction="row"
                principle={principle}
                explain={explain}
                identity={identity}
                // `at` is a named width switch (FRAME-10), not a free CSS boolean — still forwarded.
                at={at}
                body={divider ? interleaveDividers(content, "horizontal") : content}
            />
        )
    }
    return (
        <Flex
            as={Tag}
            inline={inline}
            direction="row"
            gap={gap}
            padding={padding}
            align={align}
            justify={justify}
            at={at}
            nested={nested}
            classNames={classNames}
            identity={identity}
            body={divider ? interleaveDividers(content, "horizontal") : content}
        />
    )
}

export { StackV, StackH }

/**
 * Source-level tier marker -- lets a gate read the tier without guessing from the folder path.
 *
 * Shaped as a record, not the single `{ tier, name }` most frame files export: this file has
 * TWO public components, not one, and neither is more "the" component this file names. See
 * `Flex`'s own `meta` note for the DOM side of this -- `StackV`/`StackH` render no element
 * of their own (100% delegated to `Flex`), so `data-component` on a rendered Stack instance
 * reads `"Flex"`, not `"StackV"`/`"StackH"`; this export is the source-level identity, which a
 * gate can still read even though the DOM cannot show it.
 */
export const meta = {
    StackV: { tier: "frame", name: "StackV" },
    StackH: { tier: "frame", name: "StackH" },
} as const

"use client"

import React from "react"
import { useRouter } from "@/i18n/navigation"
import { InlineLink } from "@/components/atoms/navigation/Link"
import { Typography } from "@/components/atoms/text/Typography"
import { StackV } from "@/components/frames/Stack"

/** A single footer link: an internal `path` (locale-aware push) OR an external
 *  `href` (mailto / off-site) — exactly one is set. */
export interface FooterNavLink {
    /** Stable React key. */
    key: string
    /** Visible label. */
    label: string
    /** Internal route, locale-aware — pushed through the i18n router. */
    path?: string
    /** External / mailto href — rendered as a plain anchor press. */
    href?: string
}

/** Props for {@link FooterNavColumn}. */
export interface FooterNavColumnProps {
    /** Quiet column heading (e.g. "Explore", "Support"). */
    title: string
    /** Links stacked under the heading. */
    links: ReadonlyArray<FooterNavLink>
}

/**
 * FooterNavColumn — one quiet column of the global {@link Footer}: a small muted
 * heading over a vertical stack of links. Internal links (`path`) route through
 * the locale-aware router; external / mailto links (`href`) open via `onPress`.
 *
 * Kept as a layout helper for callers that still want the connected column
 * shape; the live {@link Footer} now composes the starci `FooterLinkColumn`.
 */
export const FooterNavColumn = ({
    title,
    links,
}: FooterNavColumnProps) => {
    const router = useRouter()

    const rows = links.map((link) => () => (
        <InlineLink
            key={link.key}
            label={link.label}
            size="sm"
            onPress={() => {
                if (link.href) {
                    window.location.href = link.href
                    return
                }
                if (link.path) {
                    router.push(link.path)
                }
            }}
        />
    ))

    return (
        <StackV
            identity={{ tier: "layout", component: "FooterNavColumn" }}
            principle="label-field"
            explain="Column title over its link list — not title-subtitle, because the title names the group of controls below rather than continuing in one voice."
            items={[
                () => <Typography size="sm" weight="bold" text={title} />,
                () => (
                    <StackV
                        principle="sibling-stack"
                        explain="Same-kind peer stack of link rows — not group-boundary, because these are repeating siblings rather than section groups."
                        items={rows}
                    />
                ),
            ]}
        />
    )
}

"use client"

import React, { PropsWithChildren, ReactNode } from "react"
import { cn } from "@heroui/react"
import { LearnSidebar } from "@/components/blocks/learn/LearnSidebar"
import { LearnMobileBar } from "@/components/blocks/learn/LearnMobileBar"
import { LearnMobileTabBar } from "@/components/blocks/learn/LearnMobileTabBar"
import { LearnPanelToggles } from "@/components/blocks/learn/LearnPanelToggles"

/** Props for {@link _LearnShellLayout}. */
export interface LearnShellLayoutProps extends PropsWithChildren {
    /**
     * The route's persistent left content rail (the course content-map), rendered
     * by the route layout between the course-nav icon rail and the content. Owns
     * its own width + sticky behavior; always visible (no collapse).
     */
    leftRail?: ReactNode
    /**
     * The route's right rail (on-this-page outline / milestone rail), rendered by
     * the route layout and slotted in here. When omitted the content spans full
     * width.
     */
    rightRail?: ReactNode
    /**
     * Whether the right rail exposes the desktop collapse handle + divider (used
     * by the redux-driven milestone rail). On-this-page rails self-size, so they
     * leave this off. Defaults to `false`.
     */
    showRightCollapse?: boolean
    /**
     * Opt out of the shell's canonical `p-6` content padding for full-bleed routes
     * (e.g. the mind-map canvas, which fills the viewport edge-to-edge). Every
     * other learn page reads as a padded reading column, so the shell owns that
     * `p-6` once here instead of each feature re-declaring it. Defaults to `false`.
     */
    fullBleed?: boolean
    /**
     * Force the simple course-nav drawer bar on mobile even when a {@link LearnShellLayoutProps.leftRail}
     * is present. The reader's {@link LearnMobileTabBar} is content-specific (it
     * folds the content-map + on-this-page into bottom tabs); a non-reader left
     * rail (e.g. the leaderboard category rail, which hides on mobile and offers a
     * chip row in-page instead) opts into the plain bar. Defaults to `false`.
     */
    simpleMobileBar?: boolean
}

/**
 * Shell for the course-learn pages: the left course-nav rail, the mobile toolbar,
 * the desktop right-rail collapse handle, and the content column. Composes the
 * left rail ({@link LearnSidebar}) as a self-sizing, collapse-in-place flex
 * sibling (the {@link import("@/components/blocks").CollapsibleSidebar} block owns
 * its own width animation + persistence) beside the content. The route layout
 * supplies its own right rail (module outline on lesson routes, milestone rail on
 * personal-project) through {@link LearnShellLayoutProps.rightRail}; that rail keeps its
 * existing redux-driven `rightCollapsed` behavior, exposed via the right collapse
 * handle in {@link LearnPanelToggles}.
 *
 * @param props - {@link LearnShellLayoutProps}
 */
export const _LearnShellLayout = ({
    children,
    leftRail,
    rightRail,
    showRightCollapse = false,
    fullBleed = false,
    simpleMobileBar = false,
}: LearnShellLayoutProps) => {
    // the reader's bottom-tab bar only fits a content-map left rail; other left rails use the plain bar
    const useTabBar = Boolean(leftRail) && !simpleMobileBar
    return (
        // single column on mobile/tablet; a horizontal flow from lg up so the
        // content-map rail (left) and the optional right rail sit beside content
        <div className={cn("flex w-full flex-col items-start @app-lg:flex-row")}>
            {/* desktop course-nav icon rail — sticks under the 4rem navbar, viewport-tall;
                the block owns its own scroll, divider, width animation + collapse. */}
            <aside className="hidden shrink-0 @app-lg:sticky @app-lg:top-16 @app-lg:block @app-lg:h-[calc(100dvh-4rem)]">
                <LearnSidebar />
            </aside>
            {/* persistent left content-map rail (course content tree) supplied by the layout */}
            {leftRail}
            {/* content column; the shell owns the canonical p-6 reading-column padding
                for every learn page (features supply only max-w + mx-auto + gap), except
                full-bleed routes (mind-map canvas). Also anchors the collapse handle +
                right border for the redux-driven (milestone) rail that opts into it */}
            <div className={cn("min-h-0 w-full min-w-0 flex-1 @app-lg:w-auto", !fullBleed && "p-6", "@max-app-lg:pb-16", rightRail && "@app-lg:pr-0 @app-lg:pb-0", showRightCollapse && "relative @app-lg:border-r")}>
                {showRightCollapse && <LearnPanelToggles />}
                {/* mobile chrome: BOTH bars now live in the same fixed FOOTER zone (the
                    reader's 4-column layout folds into a bottom-tab bar; every other
                    learn tab gets the plain course-nav drawer trigger) — content gets
                    @max-app-lg:pb-16 regardless of which bar renders, so it's never covered. */}
                {useTabBar ? <LearnMobileTabBar /> : <LearnMobileBar />}
                {children}
            </div>
            {/* right rail supplied by the layout (on-this-page outline / milestone rail) */}
            {rightRail}
        </div>
    )
}

export default _LearnShellLayout

"use client"
import React, { PropsWithChildren } from "react"
import { useTranslations } from "next-intl"
import { useSelectedLayoutSegments, useSearchParams } from "next/navigation"
import { Spinner } from "@/components/atoms/display/Spinner"
import { _LearnShellLayout } from "./component"
import { ContentMap } from "@/components/blocks/learn/ContentMap"
import { MilestoneOutline } from "@/components/blocks/learn/MilestoneOutline"
import { LeaderboardCategoryRail } from "@/components/blocks/learn/LeaderboardCategoryRail"
import { OnThisPage } from "@/components/blocks/learn/OnThisPage"
import { ContentAiSelectionAsk } from "@/components/blocks/learn/ContentAiSelectionAsk"
import { EnrollGate } from "@/components/blocks/learn/EnrollGate"
import { PersonalProjectGatePreview } from "@/components/blocks/learn/personal-project/PersonalProjectGatePreview"
import { GithubLinkGate } from "@/components/blocks/auth/GithubLinkGate"
import { ResizableRail } from "@/components/blocks/layout/ResizableRail"
import { FillAvailable } from "@/components/frames/FillAvailable"
import { useQueryCourseSwr } from "@/hooks/swr/api/graphql/queries/useQueryCourseSwr"
import { useQueryCourseEnrollmentStatusSwr } from "@/hooks/swr/api/graphql/queries/useQueryCourseEnrollmentStatusSwr"
import { useAppSelector } from "@/redux/hooks"

/**
 * Learn surfaces that require enrollment. Only the capstone (personal-project) is gated:
 * it's the enrolled-only hands-on outcome. Trial viewers ("Try for free") may freely browse the
 * rest — flashcards (non-premium), leaderboard, foundations, content + mind-map — so those
 * are NOT gated. Keyed by `segments[0]`.
 */
const ENROLL_REQUIRED_SURFACES: ReadonlySet<string> = new Set([
    "personal-project",
])

/** i18n key for each gated surface's display name (folded into the gate title). */
const SURFACE_LABEL_KEY: Record<string, string> = {
    "personal-project": "finalProject.title",
}

/** Per-surface MOCK teaser rendered behind the enroll card (Medium-style gate). */
const SURFACE_PREVIEW: Record<string, React.ReactNode> = {
    "personal-project": <PersonalProjectGatePreview />,
}

/** Learn course shell: left/right rails, enroll gate, and full-bleed work surfaces. */
export const LearnShellLayout = ({ children }: PropsWithChildren) => {
    const t = useTranslations()
    // load the active course here so EVERY learn tab has `course.entity` on a cold refresh
    // (the displayId is synced from the URL by a global effect). Tabs like personal-project
    // have no other loader, and downstream queries (milestones, etc.) gate on `course.id`.
    useQueryCourseSwr()
    // enrollment status drives the enroll-gate on hands-on surfaces (populates state.user.enrolled).
    const enrollmentSwr = useQueryCourseEnrollmentStatusSwr()
    const enrolled = useAppSelector((state) => state.user.enrolled)
    // `enrolled` defaults to false, so only trust it once the status query has settled —
    // otherwise an enrolled viewer would flash the gate on cold load.
    const enrollKnown = Boolean(enrollmentSwr.data) || Boolean(enrollmentSwr.error)
    // which learn sub-route is active. Docs-style layout:
    //  - "modules" (module list / detail / content) → content-map on the LEFT (persistent)
    //    + an on-this-page outline on the RIGHT (self-hides when the body has no headings).
    //  - "personal-project" → its milestone rail on the LEFT too (same place as the content-map),
    //    so the capstone reads like every other learn tab; no right rail.
    // every other tab (mind-map, foundations, headhuntings, practice, leaderboard, starci-ai)
    // has no side rails, so its content spans the full width.
    // lessons now live UNDER the content home (`/learn/content/modules/...`), so the
    // immediate child segment is "content" for BOTH the dashboard home and the reader.
    // Use the full segment list: `includes("modules")` flags the reader/module routes,
    // while `segments[0]` flags the top-level tabs (content / personal-project / mind-map).
    const segments = useSelectedLayoutSegments()
    const searchParams = useSearchParams()
    const isModules = segments.includes("modules")
    // the course-content home (`/learn/content`) + the lesson reader (`/content/modules/...`)
    // both share the content-map rail on the LEFT: the full module → lesson tree lives in
    // the rail (its one home), and the dashboard body shows continue + progress + the
    // current-module path instead of re-drawing the whole tree.
    const isContent = segments[0] === "content"
    const isPersonalProject = segments[0] === "personal-project"
    // the flashcards surface goes RAIL-LESS entirely (per concepts/when-rail: drop the 2nd rail
    // for the whole Flashcards/Review surface). The deck list lives IN the pane (study overview) and the
    // mode switch is in-pane on desktop too. `isFlashcards` only drives the mobile-bar choice.
    const isFlashcards = segments[0] === "flashcards"
    // the "Quick quiz" surface goes full-bleed ONLY during a live run (a focused work
    // surface: its own `WorkSessionHeader` band IS the header) — detected off the
    // dedicated resumable route (`flashcards/quiz/sessions/[sessionId]`), same
    // pattern as the mock-interview's `isMockInterviewInterviewRoute` below.
    const isFlashcardQuizLive = isFlashcards && segments[1] === "quiz" && segments[2] === "sessions"
    // "Study cards"/"Due review" live session goes full-bleed ONLY during a live session
    // — same idiom, detected off the dedicated resumable route
    // (`flashcards/review/sessions/[sessionId]`, 2026-07-11 correction: "card review UI matches study"). This ONE route now serves BOTH FlashcardReviewer
    // (single-deck) and DueReview (cross-deck) — the old deck-scoped route
    // (`review/decks/[deckId]/sessions/[sessionId]`) was consolidated away; the
    // bare `.../review` overview route (no `sessions` segment) is just the
    // resolve-only shim — stays centered, never full-bleed. Correction
    // 2026-07-12: the gate still checked the DELETED deck-scoped shape and
    // never matched the real route, so the shell kept applying its `p-6`
    // reading-column padding ON TOP of the surface's own full-bleed padding
    // (teacher: "drop padding-6 here", pointed at DevTools showing the shell's
    // `p-6 @max-app-lg:pb-16` wrapper still active on a live review session).
    const isFlashcardReviewLive = isFlashcards && segments[1] === "review" && segments[2] === "sessions"
    // the mind-map is a full-bleed interactive canvas (fills the viewport edge-to-edge),
    // so it opts out of the shell's canonical p-6 reading-column padding.
    const isMindMap = segments[0] === "mind-map"
    // the mock interview goes full-bleed ONLY during the live `interview` phase (a focused
    // work surface: conversation + tool workspace). setup/grading/scorecard stay centered.
    // The active phase is mirrored into the URL (`?phase=interview`) by MockInterviewSession
    // so the shell can drop the course rails + reading padding for that phase only.
    const isMockInterview = segments[0] === "mock-interview"
    // the dedicated resumable route (`mock-interview/interview/[sessionId]`) is
    // ALWAYS the live work surface — detected straight off the path segment so
    // there is no `?phase=interview` round-trip to wait on before the shell
    // drops its rails. Additive: the legacy `?phase=interview` query-param
    // mirror (still written by MockInterviewSession once mounted) keeps working
    // for the same route too.
    const isMockInterviewInterviewRoute = isMockInterview && segments[1] === "interview"
    const isMockInterviewLive = isMockInterviewInterviewRoute || (isMockInterview && searchParams.get("phase") === "interview")
    // a live quiz / interview grades a recruiter-facing signal → the AI chat is a
    // cheat channel there and gets suppressed (mirrors the same gate in InnerLayout,
    // which also kills a rail the learner left open before navigating in).
    const isAssessmentLive = isFlashcardQuizLive || isMockInterviewLive
    // ONLY the session (`…/playground/<slug>/session`) is a full-bleed work
    // surface (step guide + terminal/resources tabs), same reasoning as the live
    // mock-interview route. The exercise's SETUP page (`…/playground/<slug>`) and
    // the hub list (`…/playground`) are reading surfaces — install + pair
    // guidance, progress, machine status — so they keep the normal reading column.
    const isPlaygroundSession = segments[0] === "playground" && segments[2] === "session"
    // the leaderboard shows its XP-category selector as a sidebar (like the content
    // page) on the LEFT; the board reads the selection from the `?category=` URL param.
    const isLeaderboard = segments[0] === "leaderboard"
    // a single challenge (`…/contents/<id>/challenges/<id>`) KEEPS the course-tree rail (the
    // learner still navigates the course while solving), but its body is a tabbed single column
    // (Brief / Submit), so it needs no on-this-page outline. Only the right rail is dropped.
    const isChallenge = segments.includes("challenges")

    // persistent left rail (always visible on desktop): the width is drag-resizable
    // (persisted) via ResizableRail; sticky under the navbar and a flex column bounded to
    // the viewport so the rail pins its header/search and scrolls ONLY the list. Hidden
    // below lg (mobile opens it in the LearnMobileBar drawer).
    const railClass = "hidden shrink-0 @app-lg:flex @app-lg:flex-col @app-lg:sticky @app-lg:top-16 @app-lg:self-start @app-lg:h-[calc(100dvh-4rem)]"

    // left rail: course content-map while reading lessons AND on the content home;
    // milestone outline for the capstone.
    const leftRail = (isModules || isContent) ? (
        <ResizableRail
            className={railClass}
            storageKey="starci.learn.contentMap.width"
            defaultWidth={320}
            minWidth={256}
            maxWidth={560}
            ariaLabel={t("courseContents.resizeRail")}
        >
            <FillAvailable at="lg" body={() => <ContentMap />} />
        </ResizableRail>
    ) : isPersonalProject ? (
        <ResizableRail
            className={railClass}
            storageKey="starci.learn.milestoneMap.width"
            defaultWidth={320}
            minWidth={256}
            maxWidth={560}
            ariaLabel={t("courseContents.resizeRail")}
        >
            <FillAvailable at="lg" body={() => <MilestoneOutline />} />
        </ResizableRail>
    ) : isLeaderboard ? (
        <ResizableRail
            className={railClass}
            storageKey="starci.learn.leaderboardRail.width"
            defaultWidth={300}
            minWidth={240}
            maxWidth={420}
            ariaLabel={t("leaderboard.categories.label")}
        >
            <FillAvailable at="lg" body={() => <LeaderboardCategoryRail variant="rail" />} />
        </ResizableRail>
    ) : undefined
    // right rail: on-this-page for the LESSON READER only (a real "contents/<id>" route) —
    // the module SHELL page (`/content/modules/<moduleId>`, no `contents` segment) is its own
    // dashboard (mirrors the course-content home, which also has no right rail) and would
    // otherwise inherit a stale TOC from whatever lesson was read last (OnThisPage self-hides
    // on `!contentId`, not on route — the module shell has no active content of its own).
    const isLessonReader = isModules && segments.includes("contents")
    const rightRail = (isLessonReader && !isChallenge) ? (
        <OnThisPage />
    ) : undefined

    // The content-AI chat rail is NOT a learn concern any more: it docks beside the
    // whole app from `InnerLayout`, so the learn right-rail slot is free to keep
    // serving the surface's own outline again.

    // enroll-gate: a trial viewer hitting a hands-on surface sees the enroll CTA, not a broken
    // page. Only gate once enrollment is KNOWN (enrolled defaults false → would flash otherwise);
    // while it resolves, hold the surface (and its enrollment-bound hooks) back behind a spinner.
    const surface = segments[0]
    const isEnrollRequired = Boolean(surface) && ENROLL_REQUIRED_SURFACES.has(surface as string)
    const showSurface = !isEnrollRequired || (enrollKnown && enrolled)
    const isGated = isEnrollRequired && enrollKnown && !enrolled
    const gateLabelKey = surface ? SURFACE_LABEL_KEY[surface] : undefined

    const content = showSurface
        ? children
        : isGated
            ? (
                <EnrollGate
                    title={t("enrollGate.title", { surface: gateLabelKey ? t(gateLabelKey) : "" })}
                    description={t("enrollGate.description")}
                    preview={surface ? SURFACE_PREVIEW[surface] : undefined}
                />
            )
            : (
                <div className="flex justify-center py-12">
                    <Spinner />
                </div>
            )

    return (
        <>
            {/* soft prompt: nudge learners with no linked GitHub to connect once per session */}
            <GithubLinkGate />
            {/* The floating "ask StarCi AI" mascot button now mounts ONCE, globally,
                from `InnerLayout` (app-wide chat, reachable outside a course too) —
                `InnerLayout` applies the same `isAssessmentLive` suppression during a
                live quiz / mock-interview (a course-grounded AI beside a
                recruiter-facing signal is a cheat channel). Chat returns after the
                session, on the scorecard, for "review weak tags". */}
            {/* "ask AI about this passage" button on lesson-article text selection */}
            {!isAssessmentLive ? <ContentAiSelectionAsk /> : null}
            <_LearnShellLayout
                leftRail={showSurface ? leftRail : undefined}
                rightRail={showSurface ? rightRail : undefined}
                fullBleed={isMindMap || isMockInterviewLive || isPlaygroundSession || isFlashcardQuizLive || isFlashcardReviewLive}
                simpleMobileBar={isLeaderboard || isFlashcards}
            >
                {content}
            </_LearnShellLayout>
        </>
    )
}

import type { IconComponent } from "@/types"
import type { SidebarTab } from "@/redux/slices/sidebar"

/**
 * Which labelled cluster a sidebar row belongs to — grouping by ROLE so the
 * hierarchy reads (the required spine vs. the aids vs. the meta surfaces):
 * - `path`     — the mandatory learning spine (course content → capstone).
 * - `practice` — the aids that orbit the spine (review, interview, reference).
 * - `track`    — the meta surfaces (orientation + motivation).
 */
export type LearnNavGroup = "path" | "practice" | "track"

/**
 * A trailing status badge on a sidebar row: a due-card count (`due`) or the
 * viewer's leaderboard rank (`rank`). Only shown when the value is meaningful.
 */
export interface LearnNavBadge {
    /** Which badge style to render. */
    tone: "due" | "rank"
    /** The value (due-card count, or 1-based rank). */
    value: number
}

/**
 * One child destination of a {@link LearnNavItem} that expands (accordion)
 * instead of routing directly — a small fixed cluster (e.g. Playground's
 * Docker/Kubernetes/RAG) that doesn't warrant its own flat rows.
 */
export interface LearnNavChild {
    /** Stable list key. */
    value: string
    /** Visible label. */
    label: string
    /** Navigation target this child routes to when pressed. */
    url: string
    /** Whether this exact URL is the current route (accent fill). */
    isActive?: boolean
}

/**
 * One row in the course-learn sidebar navigation.
 */
export interface LearnNavItem {
    /** Visible label. */
    label: string
    /** Stable list key. */
    value: string
    /** Sidebar tab enum value this row activates. */
    tab: SidebarTab
    /** Icon component rendered before the label. */
    icon: IconComponent
    /** Which labelled group this row sits in. */
    group: LearnNavGroup
    /** Navigation target the row routes to when pressed. Omitted when {@link children} is set (the row expands instead of routing). */
    url?: string
    /** Whether this surface is locked for the viewer (enroll-required + not enrolled). */
    locked?: boolean
    /** Optional trailing status badge (due count / rank). Suppressed while locked. */
    badge?: LearnNavBadge
    /** When set, this row renders as an expandable accordion of these destinations instead of routing directly. */
    children?: Array<LearnNavChild>
}

"use client"

import React, { useCallback } from "react"
import {
    Dropdown,
    Label,
} from "@heroui/react"
import {
    SquaresFourIcon,
    UserIcon,
    FileTextIcon,
    GearIcon,
    SignOutIcon,
} from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { pathConfig } from "@/resources/path"
import { useAccountMenuOverlayState } from "@/hooks/zustand/overlay/hooks"
import { useMutateSignOutSwr } from "@/hooks/swr/api/graphql/mutations/useMutateSignOutSwr"

/** Props for {@link AccountMenuAuthed}. */
export type AccountMenuAuthedProps = Record<string, never>
/**
 * Account dropdown menu for SIGNED-IN viewers: a primary section (Dashboard ·
 * Profile · Settings) and a separated destructive section (Sign out, danger).
 * Self-contained — owns navigation (closes the menu then pushes) and the sign-out
 * mutation; takes no data props.
 *
 * @param props - optional className (placement only).
 */
export const AccountMenuAuthed = () => {
    const t = useTranslations()
    const router = useRouter()
    const { close } = useAccountMenuOverlayState()
    const signOut = useMutateSignOutSwr()

    /** Close the menu, then navigate. */
    const go = useCallback(
        (path: string) => {
            close()
            router.push(path)
        },
        [close, router],
    )

    /** Close the menu, then sign out. */
    const onLogout = useCallback(
        async () => {
            close()
            await signOut.trigger()
        },
        [close, signOut],
    )

    return (
        <Dropdown.Menu>
            <Dropdown.Section>
                <Dropdown.Item
                    id="dashboard"
                    textValue={t("nav.dashboard")}
                    onPress={() => go(pathConfig().locale().dashboard().build())}
                >
                    <SquaresFourIcon className="size-5" />
                    <Label>{t("nav.dashboard")}</Label>
                </Dropdown.Item>
                <Dropdown.Item
                    id="profile"
                    textValue={t("nav.profile")}
                    onPress={() => go(pathConfig().locale().profile().build())}
                >
                    <UserIcon className="size-5" />
                    <Label>{t("nav.profile")}</Label>
                </Dropdown.Item>
                <Dropdown.Item
                    id="cv"
                    textValue={t("cv.title")}
                    onPress={() => go(pathConfig().locale().profile().cv().build())}
                >
                    <FileTextIcon className="size-5" />
                    <Label>{t("cv.title")}</Label>
                </Dropdown.Item>
                <Dropdown.Item
                    id="settings"
                    textValue={t("profileSettings.title")}
                    onPress={() => go(pathConfig().locale().profile().settings().build())}
                >
                    <GearIcon className="size-5" />
                    <Label>{t("profileSettings.title")}</Label>
                </Dropdown.Item>
            </Dropdown.Section>
            <Dropdown.Section>
                <Dropdown.Item
                    id="logout"
                    textValue={t("nav.logout")}
                    className="text-danger-soft-foreground"
                    onPress={onLogout}
                >
                    <SignOutIcon className="size-5" />
                    <Label className="text-danger-soft-foreground">{t("nav.logout")}</Label>
                </Dropdown.Item>
            </Dropdown.Section>
        </Dropdown.Menu>
    )
}

"use client"

import React, { useCallback } from "react"
import {
    Dropdown,
    Label,
} from "@heroui/react"
import {
    SignInIcon,
    UserPlusIcon,
} from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { AuthenticationModalTab } from "@/redux/slices/tabs"
import { useAppDispatch } from "@/redux/hooks"
import { setAuthenticationModalTab } from "@/redux/slices/tabs"
import { useAccountMenuOverlayState, useAuthenticationOverlayState } from "@/hooks/zustand/overlay/hooks"

/** Props for {@link AccountMenuGuest}. */
export type AccountMenuGuestProps = Record<string, never>
/**
 * Account dropdown menu for SIGNED-OUT viewers: sign in + sign up, each opening
 * the authentication modal on its tab. Self-contained — dispatches the auth tab,
 * closes the menu, and opens the overlay; takes no data props.
 *
 * @param props - optional className (placement only).
 */
export const AccountMenuGuest = () => {
    const t = useTranslations()
    const dispatch = useAppDispatch()
    const { close } = useAccountMenuOverlayState()
    const { open: openAuthentication } = useAuthenticationOverlayState()

    /** Open the auth modal on the chosen tab, then close this dropdown. */
    const onAuth = useCallback(
        (tab: AuthenticationModalTab) => {
            dispatch(setAuthenticationModalTab(tab))
            close()
            openAuthentication()
        },
        [dispatch, close, openAuthentication],
    )

    return (
        <Dropdown.Menu>
            <Dropdown.Section>
                <Dropdown.Item
                    id="sign-in"
                    textValue={t("auth.signIn.submit")}
                    onPress={() => onAuth(AuthenticationModalTab.SignIn)}
                >
                    <SignInIcon className="size-5" />
                    <Label>{t("auth.signIn.submit")}</Label>
                </Dropdown.Item>
                <Dropdown.Item
                    id="sign-up"
                    textValue={t("auth.signUp.submit")}
                    onPress={() => onAuth(AuthenticationModalTab.SignUp)}
                >
                    <UserPlusIcon className="size-5" />
                    <Label>{t("auth.signUp.submit")}</Label>
                </Dropdown.Item>
