import { useNavbarBottomLayerStore } from "@/hooks/zustand/navbarBottomLayer/store"
import { useSearchOverlayState } from "@/hooks/zustand/overlay/hooks"

/**
 * Props for {@link Navbar}.
 */
export type NavbarProps = Record<string, never>
/**
 * Navbar — top application navigation bar.
 *
 * Container: owns the Ctrl/Cmd+K search shortcut + the mobile drawer state and
 * composes the logo, nav links, search trigger (full field on desktop, icon on
 * mobile), the standalone language dropdown, the theme switch, notifications,
 * the account menu, and a mobile expand button that opens a navigation drawer.
 * `"use client"` for hooks + keyboard handling.
 * @param props - optional root class name (placement only)
 */
export const Navbar = () => {
    const t = useTranslations()
    const router = useRouter()
    const { open: openSearch } = useSearchOverlayState()
    const [isDrawerOpen, setDrawerOpen] = useState(false)
    // optional second layer (e.g. profile tabs) a page registered into the navbar
    const bottomLayer = useNavbarBottomLayerStore((state) => state.bottomLayer)

    // register the global Ctrl/Cmd+K shortcut to open the search overlay
    useEffect(() => {
        const onKeyDown = (event: KeyboardEvent) => {
            // some keydown events (IME composition, autofill) fire with no `key`
            const isK = event.key?.toLowerCase() === "k"
            if (!isK) return
            if (!(event.ctrlKey || event.metaKey)) return
            event.preventDefault()
            openSearch()
        }
        window.addEventListener("keydown", onKeyDown)
        return () => window.removeEventListener("keydown", onKeyDown)
    }, [openSearch])

    // mobile drawer nav entries (same source of truth as desktop NavLinks, plus cart)
    const mobileNavItems = useNavbarItems({ includeCart: true })

    return (
        <nav className={"sticky top-0 z-50 border-b border-separator bg-background"}>
            {/* primary row — fixed 4rem tall; the nav root owns the single bottom border */}
            <div className="flex h-16 min-h-16 w-full items-center justify-between gap-3 px-3">
                <div className="flex items-center gap-6">
                    <Logo className="justify-start" />
                    <NavLinks />
                </div>

                <div className="flex items-center justify-end gap-2">
                    {/* desktop: full input-style search; mobile: just an icon */}
                    {/* the search field is the navbar's own placement call — a fixed measure that
                        only appears once there is room for it */}
                    <Box className="hidden w-[260px] @app-md:flex">
                        <SearchButton />
                    </Box>
                    <Button
                        isIconOnly
                        variant="tertiary"
                        aria-label={t("search.label")}
                        className="@app-md:hidden"
                        onPress={openSearch}
                    >
                        <SearchIcon className="size-5" />
                    </Button>
                    {/* desktop: language + theme inline; on mobile they move into the drawer */}
                    <div className="hidden items-center gap-2 @app-md:flex">
                        <LanguageDropdown />
                        <DarkLightModeSwitch />
                    </div>
                    <CartButton />
                    <NotificationBell />
                    <AccountMenuDropdown />
                    {/* mobile: expand icon → navigation drawer */}
                    <Button
                        isIconOnly
                        variant="ghost"
                        aria-label={t("nav.mobileMenu")}
                        className="@app-md:hidden"
                        onPress={() => setDrawerOpen(true)}
                    >
                        <MenuIcon className="size-5" />
                    </Button>
                </div>
            </div>

            {/* page-registered secondary layer (e.g. profile tabs). It sits flush
                under the primary row with NO divider of its own — the nav root's
                single border-b falls under whichever layer is last (single → row,
                bottomLayer → this), so there is always exactly one navbar border. */}
            {bottomLayer ? <div className="w-full">{bottomLayer}</div> : null}

            {/* mobile navigation drawer (opened by the expand icon) */}
            <Drawer>
                <Drawer.Backdrop isOpen={isDrawerOpen} onOpenChange={setDrawerOpen}>
                    <Drawer.Content placement="right">
                        <Drawer.Dialog className="flex h-full flex-col">
                            <Drawer.CloseTrigger />
                            <Drawer.Header>
                                <Drawer.Heading>{t("nav.mobileMenu")}</Drawer.Heading>
                            </Drawer.Header>
                            <Drawer.Body className="flex flex-col gap-6">
                                <div className="flex flex-col gap-2">
                                    {mobileNavItems.map((item) => (
                                        <Button
                                            key={item.path}
                                            variant={item.isActive ? "secondary" : "ghost"}
                                            fullWidth
                                            className="justify-start"
                                            onPress={() => {
                                                router.push(item.path)
                                                setDrawerOpen(false)
                                            }}
                                        >
                                            {item.label}
                                        </Button>
                                    ))}
                                </div>
                                {/* controls hidden from the mobile bar live here: language + theme */}
                                <div className="flex flex-col gap-3">
                                    <div className="flex items-center justify-between gap-3">
                                        <Typography type="body-sm">
                                            {t("nav.toggleLanguage")}
                                        </Typography>
                                        <LanguageDropdown />
                                    </div>
                                    <div className="flex items-center justify-between gap-3">
                                        <Typography type="body-sm">
                                            {t("nav.appearance")}
                                        </Typography>
                                        <DarkLightModeSwitch />
                                    </div>
                                </div>
                            </Drawer.Body>
                        </Drawer.Dialog>
                    </Drawer.Content>
                </Drawer.Backdrop>
            </Drawer>
        </nav>
    )
}

/**
 * One top-level navigation entry rendered in the desktop navbar.
 */
export interface NavbarItem {
    /** Visible label. */
    label: string
    /** Navigation target path. */
    path: string
    /** Whether this entry matches the active route. */
    isActive: boolean
}

import {
    useMemo,
} from "react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    usePathname,
} from "@/i18n/navigation"
import {
    pathConfig,
} from "@/resources/path"
import type {
    NavbarItem,
} from "./types/navbar"

/**
 * Shared source of truth for the navbar's top-level nav entries.
 *
 * Desktop `NavLinks` and the mobile drawer both render off this same list so
 * adding/renaming a route only has one place to update. Pass
 * `includeCart: true` for the mobile drawer, which also surfaces the cart
 * entry that the desktop bar renders separately via `CartButton`.
 * @param options.includeCart - append a "cart" entry (mobile drawer only)
 */
export const useNavbarItems = ({ includeCart = false }: { includeCart?: boolean } = {}) => {
    const t = useTranslations()
    const locale = useLocale()
    const pathname = usePathname()

    return useMemo<Array<NavbarItem>>(() => {
        const items: Array<NavbarItem> = [
            {
                label: t("nav.home"),
                path: pathConfig().locale().home().build(),
                isActive: pathname === "/" || pathname === pathConfig().locale().home().build(),
            },
            {
                label: t("nav.courses"),
                path: pathConfig().locale().course().build(),
                isActive: pathname.startsWith(pathConfig().locale(locale).course().build()),
            },
            {
                label: t("nav.contact"),
                path: pathConfig().locale().contact().build(),
                isActive: pathname.startsWith(pathConfig().locale(locale).contact().build()),
            },
        ]
        if (includeCart) {
            items.push({
                label: t("cart.title"),
                path: pathConfig().locale().cart().build(),
                isActive: pathname.startsWith(pathConfig().locale(locale).cart().build()),
            })
        }
        return items
    }, [includeCart, locale, pathname, t])
}

import React from "react"
import {
    PersonalProjectDashboard,
    type PersonalProjectDashboardProps,
} from "@/components/blocks/learn/PersonalProjectDashboard"
import {
    PersonalProjectTaskPage,
    type PersonalProjectTaskPageProps,
} from "@/components/pages/PersonalProjectTaskPage"
import {
    PersonalProjectResultScreen,
    type PersonalProjectResultScreenProps,
} from "@/components/blocks/learn/PersonalProjectResultScreen"

/**
 * `_PersonalProjectWorkspaceLayout` — the SRC TWIN of `.storybook/components/starci/
 * pages/PersonalProjectWorkspace/PersonalProjectWorkspace.tsx`. Presentational:
 * typed props, already resolved; no fetch/store/i18n (that's the connected half,
 * `./index.tsx`).
 *
 * SCREEN — the personal-project route group's own content switch. See the
 * blueprint's file header for the full RULE 12 investigation (why this is a
 * `pages/` screen, not a `layouts/` wrapper) and for why this file is a thin
 * dispatch rather than a rebuild of any content.
 *
 * THREE LEAVES, one per `view` — a STRUCTURAL fork (which of three disjoint
 * screens mounts), not a data state of one shape: `Dashboard` (`/personal-
 * project`), `Task` (`/personal-project/tasks/[taskId]`), `Result`
 * (`…/result`). Each leaf hands the real, untouched prop surface of the screen
 * it dispatches to straight through — this file invents no data shape of its
 * own. Each leaf renders the CONNECTED child export (`PersonalProjectDashboard`,
 * `PersonalProjectTaskPage`, `PersonalProjectResultScreen`), which in these twins
 * happen to be presentational (the children own no data of their own).
 */

/** Props for {@link _PersonalProjectWorkspaceLayout} — see the file header for the `view` split. */
export type PersonalProjectWorkspaceLayoutProps =
    | ({ view: "dashboard" } & PersonalProjectDashboardProps)
    | ({ view: "task" } & PersonalProjectTaskPageProps)
    | ({ view: "result" } & PersonalProjectResultScreenProps)

/**
 * The personal-project route group's content switch. See the file header for
 * why this screen exists and why it owns none of its own DOM.
 *
 * @param props - {@link PersonalProjectWorkspaceLayoutProps}
 */
const _PersonalProjectWorkspaceLayout = (props: PersonalProjectWorkspaceLayoutProps) => {
    // No wrapper div (BLOCK-2): each of the three leaves below is this
    // screen's own root for the branch it renders. None of the three yet
    // accepts the `identity` prop from `_identity.ts` (`PersonalProjectDashboard`,
    // `PersonalProjectTaskPage`, `PersonalProjectResultScreen` all still draw
    // their OWN `data-tier="block"`/`"page"` on their own root) and none is
    // wrapped in a sibling frame here to carry this screen's identity instead
    // — so this screen currently renders with no `data-tier="page"
    // data-component="PersonalProjectWorkspace"` node of its own anywhere in
    // the tree, rather than re-adding the raw div BLOCK-2 forbids.
    if (props.view === "dashboard") return <PersonalProjectDashboard {...props} />
    if (props.view === "task") return <PersonalProjectTaskPage {...props} />
    return <PersonalProjectResultScreen {...props} />
}

export { _PersonalProjectWorkspaceLayout }

import React from "react"
import { ArrowRightIcon, ShoppingCartIcon } from "@phosphor-icons/react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { DrawerShell } from "@/components/composites/layout/DrawerShell"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"
import { Button } from "@/components/atoms/buttons/Button"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH, StackV } from "@/components/frames/Stack"
import { SurfaceListCard } from "@/components/blocks/cards/SurfaceListCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { PriceTagInline } from "@/components/blocks/commerce/PriceTag"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"
import { CartLine } from "@/components/blocks/commerce/CartLine"
import type { CartItemEntity } from "@/modules/api/graphql/queries/types/my-cart"
import type { CoursesCheckoutPreviewLine } from "@/modules/api/graphql/queries/types/courses-checkout-preview"

/** All display text, already localized by the connected `MiniCartDrawer`; a story passes i18n keys. */
export interface MiniCartDrawerLabels {
    /** `"${cart.title} · ${cart.itemsCount}"`, already interpolated with `count`. */
    header: string
    emptyTitle: string
    emptyDescription: string
    browseCourses: string
    errorTitle: string
    retry: string
    /** `cart.comboActive`/`cart.comboStart`, already picked+interpolated for the current `bundlePercent`. */
    comboLabel: string
    /** `cart.bundleBonus`, already interpolated — only shown while `bundlePercent > 0`. */
    bundleBonusChip: string
    /** `cart.comboNextHint`/`cart.comboMaxHint`, already picked+interpolated for `nextTierPercent`. */
    comboHint: string
    total: string
    /** `cart.savings`, already interpolated — only shown while `savingsVnd > 0`. */
    savings: string
    /** `cart.installmentHint`, already interpolated — only shown while `cheapestMonthlyVnd` is set. */
    installmentHint: string
    checkout: string
    viewFullCart: string
}

/** Props for {@link _MiniCartDrawer} — presentational; all data resolved, no fetch/store/i18n. */
export interface MiniCartDrawerProps {
    isOpen: boolean
    onOpenChange: (open: boolean) => void
    /** Slide-in edge. `true` on mobile → bottom sheet. */
    isMobile: boolean
    /** First load, nothing in hand → the cart-list zone shimmers in place (co-located). */
    isSkeleton?: boolean
    /** Settled with zero lines → the empty message replaces the list. */
    isEmpty?: boolean
    /** Truthy → the cart-list zone falls to the error message (beats loading + empty). */
    error?: unknown
    onRetry?: () => void
    onBrowseCourses?: () => void
    items?: Array<CartItemEntity>
    /** courseId → the real checkout-preview line, for per-line pricing. */
    previewByCourse?: Map<string, CoursesCheckoutPreviewLine>
    isMutating?: boolean
    onRemove: (courseId: string) => void
    /** Combo-meter fill (0..3). */
    itemCount?: number
    /** Whether the current bundle tier is above zero — gates the bonus chip. */
    bundlePercent?: number
    /** First load of the checkout preview, cart already settled → the footer summary shimmers. */
    isPreviewSkeleton?: boolean
    /** The real checkout preview — total/savings/installments. `undefined` while pending or on error. */
    preview?: { totalChargedVnd: number; totalListVnd: number; savingsVnd: number }
    /** `true` → the preview fetch settled with an error; falls back to `fallbackTotalVnd`. */
    previewError?: boolean
    /** Sum of entity display prices — shown only when the preview failed to load. */
    fallbackTotalVnd?: number
    /** Cheapest installment monthly amount, already formatted. `null` → no installment plans exist. */
    cheapestMonthlyLabel?: string | null
    onCheckout?: () => void
    onViewFullCart?: () => void
    labels: MiniCartDrawerLabels
}

/**
 * Mini-cart drawer — the presentational half of {@link _MiniCartDrawer}'s connected
 * `MiniCartDrawer` (`index.tsx`): the slide-out cart confirmation + combo meter,
 * right on desktop / bottom-sheet on mobile. Composed on `DrawerShell` (the shared
 * panel-scaffold composite): a bordered `SurfaceListCard` reusing {@link CartLine}
 * (the SAME row the `/cart` page uses), a bundle-discount `ProgressMeter`, and a
 * footer with the real charged total + saving, a primary "Checkout" and a text
 * link to the full cart page. `error`/`isEmpty` fall to the shared
 * `AsyncContentError` / `AsyncContentEmpty` composites; otherwise the tree renders
 * with `isSkeleton` threaded down so the shimmer mirrors the loaded shape
 * (loading-and-skeleton.md). See `tiers/split.md` — the connected `index.tsx` owns
 * the fetch, the stores, and the i18n.
 *
 * @param props - {@link MiniCartDrawerProps}
 */
export const _MiniCartDrawer = ({
    isOpen,
    onOpenChange,
    isMobile,
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    onBrowseCourses,
    items = [],
    previewByCourse,
    isMutating = false,
    onRemove,
    itemCount = 0,
    bundlePercent = 0,
    isPreviewSkeleton = false,
    preview,
    previewError = false,
    fallbackTotalVnd = 0,
    cheapestMonthlyLabel = null,
    onCheckout,
    onViewFullCart,
    labels,
}: MiniCartDrawerProps) => {
    const comboLabelRow = [
        () => <Typography size="sm" weight="medium" isSkeleton={isSkeleton} text={labels.comboLabel} />,
        ...(isSkeleton
            ? [() => <Chip isSkeleton tone="accent" />]
            : bundlePercent > 0
                ? [() => <Chip tone="accent" text={labels.bundleBonusChip} />]
                : []),
    ]
    const comboMeterItems = [
        () => (
            <StackH
                gap={3}
                principle="flex-action"
                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                align="center"
                justify="between"
                items={comboLabelRow}
            />
        ),
        () => <ProgressMeter value={itemCount} max={3} isSkeleton={isSkeleton} />,
        () => <Typography size="xs" color="muted" isSkeleton={isSkeleton} text={labels.comboHint} />,
    ]
    const comboMeterSection: ComponentTypeWithSkeleton = () => (
        <StackV gap={3} items={comboMeterItems} />
    )

    // Line list — reuses the SAME `CartLine` as the `/cart` page. `bordered`: this
    // list is NESTED inside the drawer surface, where `shadow-surface` renders
    // invisible against the parent (dark mode) — nested cards need a border to
    // delineate (`card.md` §surface-in-surface). The `/cart` PAGE keeps it
    // un-bordered (top-level on `bg-background`, shadow shows). `CartLine` has no
    // co-located skeleton of its own, so the loading rows are mirrored by hand,
    // same shape (leading tile · two text lines · trailing action).
    const cartLineSkeletonItems = [
        () => <Skeleton className="size-12 shrink-0 rounded-xl" />,
        () => (
            <StackV
                gap={3}
                classNames={["min-w-0", "flex-1"]}
                items={[
                    () => <Skeleton className="h-4 w-1/2 rounded-lg" />,
                    () => <Skeleton className="h-4 w-24 rounded-lg" />,
                ]}
            />
        ),
        () => <Skeleton className="size-9 shrink-0 rounded-lg" />,
    ]
    const cartListSection: ComponentTypeWithSkeleton = () => (
        <SurfaceListCard bordered>
            {isSkeleton
                ? Array.from({ length: 2 }).map((_row, index) => (
                    <StackH
                        key={index}
                        gap={1}
                        principle="card-padding"
                        explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome."
                        padding={5}
                        body={() => (
                            <StackH
                                gap={4}
                                principle="content-row"
                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                align="center"
                                items={cartLineSkeletonItems}
                            />
                        )}
                    />
                ))
                : items.map((item) => (
                    <CartLine
                        key={item.id}
                        item={item}
                        previewLine={previewByCourse?.get(item.courseId)}
                        onRemove={onRemove}
                        isMutating={isMutating}
                    />
                ))}
        </SurfaceListCard>
    )

    // Body — error → skeleton → empty → content (BLOCK-8): the empty and error
    // surfaces are the shared `AsyncContent*` composites dropped in as their own
    // states; otherwise the ONE tree renders, with `isSkeleton` threaded down so
    // the shimmer mirrors the loaded shape.
    const cartBody: ComponentTypeWithSkeleton = () => {
        if (error) {
            return <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retry} />
        }
        if (!isSkeleton && isEmpty) {
            return (
                <AsyncContentEmpty
                    icon={ShoppingCartIcon}
                    title={labels.emptyTitle}
                    description={labels.emptyDescription}
                    onRetry={onBrowseCourses}
                    retryLabel={labels.browseCourses}
                />
            )
        }
        return <StackV gap={6} isSkeleton={isSkeleton} items={[comboMeterSection, cartListSection]} />
    }

    const previewSkeletonTotalRow = [
        () => <Skeleton className="h-5 w-20 rounded-lg" />,
        () => <Skeleton className="h-7 w-32 rounded-lg" />,
    ]
    const totalPriceRow = [
        () => <Typography size="base" weight="semibold" text={labels.total} />,
        ...(preview
            ? [() => (
                <PriceTagInline
                    discounted={preview.totalChargedVnd}
                    original={preview.totalListVnd}
                    currency="VND"
                />
            )]
            // preview failed to load — fall back to the plain list
            // total (no bundle discount known) so the total is never blank.
            : previewError
                ? [() => <PriceTagInline discounted={fallbackTotalVnd} currency="VND" />]
                : []),
    ]
    const totalSummaryItems = [
        () => (
            <StackH
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                align="center"
                items={totalPriceRow}
            />
        ),
        ...(preview && preview.savingsVnd > 0
            ? [() => <Typography size="sm" color="success-soft" text={labels.savings} />]
            : []),
        ...(cheapestMonthlyLabel != null
            ? [() => <Typography size="xs" color="muted" text={labels.installmentHint} />]
            : []),
    ]
    const footerItems = [
        () => (
            isPreviewSkeleton ? (
                <StackH
                    gap={4}
                    principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                    align="center"
                    items={previewSkeletonTotalRow}
                />
            ) : (
                <StackV gap={2} items={totalSummaryItems} />
            )
        ),
        () => (
            <Button
                variant="primary"
                size="lg"
                suffixIcon={ArrowRightIcon}
                isDisabled={isMutating}
                onPress={onCheckout}
                label={labels.checkout}
                classNames={["w-full"]}
            />
        ),
        () => (
            <Button
                variant="tertiary"
                onPress={onViewFullCart}
                label={labels.viewFullCart}
                classNames={["w-full"]}
            />
        ),
    ]
    const footerSection: ComponentTypeWithSkeleton = () => (
        <StackV gap={4} items={footerItems} />
    )

    return (
        <DrawerShell
            isOpen={isOpen}
            onOpenChange={onOpenChange}
            placement={isMobile ? "bottom" : "right"}
            title={labels.header}
            dialogWidth="cart"
            footerVariant="stacked"
            isSkeleton={isSkeleton}
            body={cartBody}
            footer={items.length > 0 ? footerSection : undefined}
            identity={{ tier: "overlay", component: "MiniCartDrawer" }}
        />
    )
}

