import React from "react"
import { CheckIcon, CopyIcon, PlayIcon } from "@phosphor-icons/react"
import { Callout } from "@/components/composites/feedback/Callout"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Button } from "@/components/atoms/buttons/Button"
import { Typography } from "@/components/atoms/text/Typography"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"

/** All display text for {@link _CurlTester}, already localized by the connected `CurlTester`. */
export interface CurlTesterLabels {
    /** Caption above the curl command box. */
    commandLabel: string
    /** Copy-button label before a copy. */
    copy: string
    /** Copy-button label right after a successful copy. */
    copied: string
    /** "Run" button label. */
    run: string
}

/** Props for {@link _CurlTester} — presentational; all data resolved, no fetch/store/i18n. */
export interface CurlTesterProps {
    /** The curl command to display and copy — already built by the connected half from the public GraphQL endpoint. */
    curlCommand: string
    /** True right after a successful copy — swaps the copy button's icon/label briefly. */
    copied: boolean
    onCopy: () => void
    /** True while the whitelisted query is in flight — the co-located result box shows a shimmer instead of collapsing or being replaced by a second tree. */
    running: boolean
    onRun: () => void
    /** Pretty-printed JSON of the last successful run; `null` before any run, or after a failed one. */
    result: string | null
    /** Message of the last failed run; `null` once a run succeeds or before any run has fired. */
    errorText: string | null
    labels: CurlTesterLabels
}

/**
 * `_CurlTester` — the presentational half of {@link import("./index").CurlTester}: an
 * MVP-scoped "Try it yourself" panel that whitelists ONLY the public `systemHealthStatus`
 * query (no free-form query input, no mutation ever reachable here). Shows the curl command
 * hitting the real `/graphql` endpoint (copy-able) plus a "Run" button.
 *
 * The result region is a single CO-LOCATED box (`loading-and-skeleton.md`): while
 * {@link CurlTesterProps.running} it renders `Skeleton.Paragraph` in place of the JSON, in
 * the SAME rounded/padded box the settled response renders in — one tree, not a hand-kept
 * parallel skeleton, so the box never collapses or jumps on resolve. Takes already-resolved
 * text and state; owns no fetch, no i18n (that lives in the connected `./index.tsx` — see
 * `tiers/split.md`).
 *
 * @param props - {@link CurlTesterProps}
 */
export const _CurlTester = ({
    curlCommand,
    copied,
    onCopy,
    running,
    onRun,
    result,
    errorText,
    labels,
}: CurlTesterProps) => (
    <StackV
        gap={3}
        identity={{ tier: "block", component: "CurlTester" }}
        principle="sibling-stack"
        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
        items={[
            () => (
                <StackV gap={2} principle="title-subtitle"
                    explain="Title over supporting line — not label-field, because neither line is a form control label."
                    items={[
                        () => (
                            <StackH gap={2} justify="between" align="center" principle="icon-text"
                                explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
                                items={[
                                    () => <Typography size="xs" color="muted" text={labels.commandLabel} />,
                                    () => (
                                        <Button
                                            variant="tertiary"
                                            size="sm"
                                            prefixIcon={copied ? CheckIcon : CopyIcon}
                                            label={copied ? labels.copied : labels.copy}
                                            onPress={onCopy}
                                        />
                                    ),
                                ]} />
                        ),
                        () => (
                            <Box principle="cell-pad" className="overflow-x-auto rounded-xl bg-default p-3"
                                explain="Tight cell inset — not card-padding, because this sits inside a dense table or list cell rather than a card body.">
                                <Typography size="code" text={curlCommand} preserveWhitespace />
                            </Box>
                        ),
                    ]} />
            ),
            () => (
                <Button
                    variant="primary"
                    size="sm"
                    prefixIcon={PlayIcon}
                    label={labels.run}
                    onPress={onRun}
                    isPending={running}
                    classNames={["self-start"]}
                />
            ),
            ...(errorText ? [() => <Callout status="danger" title={errorText} />] : []),
            // Co-located result box (no isEmpty/error branch was ever wired here — the legacy
            // AsyncContent usage only ever toggled loading vs. content, loading-and-skeleton.md
            // §1). Same box for both states; `Box`/`Typography` carry no `isSkeleton` shape for a
            // multi-line JSON blob, so the swap is hand-mirrored right where it sits rather than
            // threaded through a leaf prop.
            ...(running || result ? [() => (
                <Box principle="cell-pad" className="overflow-x-auto rounded-xl bg-default p-3"
                    explain="Tight cell inset — not card-padding, because this sits inside a dense table or list cell rather than a card body.">
                    {running ? <Skeleton.Paragraph lines={4} /> : <Typography size="code" text={result ?? ""} preserveWhitespace />}
                </Box>
            )] : []),
        ]}
    />
)

"use client"

import React, { useState } from "react"
import { useTranslations } from "next-intl"
import { publicEnv } from "@/resources/env/public"
import { querySystemHealthStatus } from "@/modules/api/graphql/queries/query-system-health-status"
import { _CurlTester } from "./component"

/**
 * The RAW GraphQL body sent to `/graphql` — the SAME query the "Run" button
 * below fires client-side. Kept as one literal so the displayed curl command
 * and the actual request can never drift apart.
 */
const QUERY_BODY = `query SystemHealthStatus {
  systemHealthStatus {
    success
    message
    error
    data {
      components {
        name
        status
        latencyMs
        message
        checkedAt
      }
    }
  }
}`

/** Builds the copy-able curl command hitting the real public GraphQL endpoint. */
const buildCurlCommand = (): string => {
    const endpoint = publicEnv().api.graphql
    const body = JSON.stringify({ query: QUERY_BODY })
    return `curl -X POST ${endpoint} \\\n  -H "Content-Type: application/json" \\\n  -d '${body}'`
}

/**
 * "Try it yourself" panel — an MVP-scoped API explorer that whitelists ONLY
 * the public `systemHealthStatus` query (no free-form query input, no
 * mutation ever reachable here). The CONNECTED half (`tiers/split.md`): builds
 * the curl command, owns the copy/run/result/error state (reusing
 * `querySystemHealthStatus` — the same function the live poll uses, not a new
 * fetch layer), resolves every label, and hands them to the presentational
 * {@link _CurlTester}.
 */
export const CurlTester = () => {
    const t = useTranslations("architecture")
    const [copied, setCopied] = useState(false)
    const [running, setRunning] = useState(false)
    const [result, setResult] = useState<string | null>(null)
    const [errorText, setErrorText] = useState<string | null>(null)

    const curlCommand = buildCurlCommand()

    const onCopy = async () => {
        await navigator.clipboard.writeText(curlCommand)
        setCopied(true)
        window.setTimeout(() => setCopied(false), 1500)
    }

    const onRun = async () => {
        setRunning(true)
        setErrorText(null)
        try {
            const response = await querySystemHealthStatus({})
            setResult(JSON.stringify(response.data, null, 2))
        } catch (error) {
            setErrorText(error instanceof Error ? error.message : String(error))
            setResult(null)
        } finally {
            setRunning(false)
        }
    }

    return (
        <_CurlTester
            curlCommand={curlCommand}
            copied={copied}
            onCopy={onCopy}
            running={running}
            onRun={onRun}
            result={result}
            errorText={errorText}
            labels={{
                commandLabel: t("curl.commandLabel"),
                copy: t("curl.copy"),
                copied: t("curl.copied"),
                run: t("curl.run"),
            }}
        />
    )
}

import React from "react"
import { cn } from "@heroui/react"
import { ArrowsDownUpIcon, CpuIcon, MemoryIcon } from "@phosphor-icons/react"
import type { ComponentMetrics } from "@/modules/api/graphql/queries/types/system-health-status"
import { formatBytesPerSecond, formatCpuPercent, formatMemory } from "@/modules/utils/architecture-metrics"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Props for {@link MetricsInline}. */
export interface MetricsInlineProps extends WithClassNames<undefined> {
    /** Live resource metrics for this component, or `null`/`undefined` when
     *  there's no local container to measure (or no sample yet) — renders
     *  nothing rather than a fake placeholder. */
    metrics: ComponentMetrics | null | undefined
}

/**
 * A compact CPU / memory / network readout for one component, shared by
 * {@link import("../ArchitectureRail").ArchitectureRail} (rail row) and
 * {@link import("../NodeDissectionPanel").NodeDissectionPanel} (detail panel) —
 * same "flex-wrap of small icon+text chips" treatment `panel.latency` already
 * uses. Every field is independently gated on being non-null: a component
 * with only, say, `cpuPercent` known shows just that one chip, never a `0`/
 * "N/A" filler for the others. Renders nothing at all when every field is null.
 *
 * @param props - {@link MetricsInlineProps}
 */
export const MetricsInline = ({ metrics, className }: MetricsInlineProps) => {
    const cpu = formatCpuPercent(metrics?.cpuPercent)
    const memory = formatMemory(metrics?.memoryUsedBytes, metrics?.memoryLimitBytes)
    const network = metrics
        ? [formatBytesPerSecond(metrics.networkRxBytesPerSec), formatBytesPerSecond(metrics.networkTxBytesPerSec)]
        : [null, null]
    const [rx, tx] = network

    if (cpu == null && memory == null && rx == null && tx == null) return null

    return (
        <span className={cn("flex flex-wrap items-center gap-x-3 gap-y-1", className)}>
            {cpu != null ? (
                <span data-principle="icon-text" className="inline-flex items-center gap-1 tabular-nums">
                    <CpuIcon aria-hidden focusable="false" className="size-3 shrink-0" />
                    {cpu}
                </span>
            ) : null}
            {memory != null ? (
                <span data-principle="icon-text" className="inline-flex items-center gap-1 tabular-nums">
                    <MemoryIcon aria-hidden focusable="false" className="size-3 shrink-0" />
                    {memory}
                </span>
            ) : null}
            {rx != null || tx != null ? (
                <span data-principle="icon-text" className="inline-flex items-center gap-1 tabular-nums">
                    <ArrowsDownUpIcon aria-hidden focusable="false" className="size-3 shrink-0" />
                    {rx != null ? `↓ ${rx}` : null}
                    {rx != null && tx != null ? " " : null}
                    {tx != null ? `↑ ${tx}` : null}
                </span>
            ) : null}
        </span>
    )
}

