import React from "react"
import type { Key } from "react"
import { ListIcon, SquaresFourIcon } from "@phosphor-icons/react"
import {
    AsyncContentEmpty,
    AsyncContentError,
    type AsyncContentEmptyProps,
    type AsyncContentErrorProps,
} from "@/components/composites/async/AsyncContent"
import { Breadcrumbs } from "@/components/atoms/navigation/Breadcrumbs"
import { Typography } from "@/components/atoms/text/Typography"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { Container } from "@/components/frames/Container"
import { Cluster } from "@/components/frames/Cluster"
import { Grid, type GridItem } from "@/components/frames/Grid"
import { StackH, StackV } from "@/components/frames/Stack"
import { SearchInput } from "@/components/blocks/form/SearchInput"
import { TabsCard } from "@/components/blocks/navigation/TabsCard"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { Pagination } from "@/components/blocks/navigation/Pagination"
import { CourseCardSkeleton } from "@/components/blocks/cards/CourseCardSkeleton"
import { CatalogCourseCard } from "./CatalogCourseCard"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"
import type { CourseEntity } from "@/modules/types/entities/course"

/** Courses per page (3 columns × 3 rows on desktop). Re-exported so the connected `CourseCatalogPage` computes `totalPages` against the same constant. */
export const PAGE_SIZE = 9

/** How the catalog is laid out — a roomy card grid or a compact row list. */
export type CatalogView = "grid" | "line"

/** How many placeholder cards the co-located skeleton shows while the first load is in flight — same count either layout used to hand-build. */
const SKELETON_ITEM_COUNT = 6

/** Every already-translated string the presentational tree renders, resolved by the connected `CourseCatalogPage`. */
export interface CourseCatalogLabels {
    /** Breadcrumb root crumb label. */
    navHome: string
    /** Breadcrumb current crumb label. */
    navCourses: string
    /** Page title. */
    title: string
    /** Search field placeholder. */
    searchPlaceholder: string
    /** Accessible name for the grid/line view-toggle tab group. */
    viewAria: string
    /** Accessible label for the grid-view icon tab. */
    viewGrid: string
    /** Accessible label for the line-view icon tab. */
    viewLine: string
}

/** Props for {@link _CourseCatalogPage} — presentational; every value already resolved by the connected `CourseCatalogPage`. */
export interface CourseCatalogPageProps {
    /** First load, nothing in hand yet → the card grid/list shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with zero courses for the current search → the empty message. */
    isEmpty?: boolean
    /** Truthy → the error message (beats a stale loading flag). The connected file passes its settled fetch error. */
    error?: unknown
    /** Props for the error message — forwarded straight to `AsyncContentError`. */
    errorContent?: AsyncContentErrorProps
    /** Props for the empty message — forwarded straight to `AsyncContentEmpty` (the connected file switches between the plain-empty and filtered-empty copy). */
    emptyContent?: AsyncContentEmptyProps
    /** The current page of courses, already ordered (curated learning-path order). */
    list: ReadonlyArray<CourseEntity>
    /** grid ⇆ line layout, persisted by the connected file. */
    view: CatalogView
    /** Fired when the view toggle changes. */
    onChangeView: (next: CatalogView) => void
    /** Live search text (immediate, not debounced — drives the field). */
    query: string
    /** Fired on every keystroke in the search field. */
    onQueryChange: (next: string) => void
    /** Already-localized result-count line, e.g. "12 courses" — omitted while there is nothing to count yet (mirrors the pre-split behaviour of showing nothing, not a skeleton, for this line). */
    countLabel?: string
    /** Fired when the breadcrumb "Home" crumb is pressed. */
    onNavigateHome: () => void
    /** 1-based current page. */
    currentPage: number
    /** Total pages (>= 1). */
    totalPages: number
    /** Fired with a 1-based page number when the user changes page. */
    onPageChange: (pageNumber: number) => void
    labels: CourseCatalogLabels
}

/**
 * Loading placeholder for ONE compact "line" catalog row — mirrors
 * {@link CatalogCourseCard}'s `layout="line"` shape (thumbnail, title + one
 * description line, a price line, and a two-button action row) so the
 * catalog's line view does not jump when data resolves. Co-located right here
 * (not a separate hand-kept file) since `CatalogCourseCard` takes no
 * `isSkeleton` prop of its own to thread through (`loading-and-skeleton.md`).
 */
const CatalogLineCardSkeleton = () => (
    <SurfaceCard
        identity={{ tier: "block", component: "CatalogLineCardSkeleton" }}
        body={() => (
            <StackH
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={[
                    () => (
                        <Skeleton className="hidden aspect-video w-36 shrink-0 rounded-2xl @app-sm:block" />
                    ),
                    () => (
                        <StackV
                            gap={2}
                            principle="title-subtitle"
                            explain="Title over supporting line — not label-field, because neither line is a form control label."
                            classNames={["min-w-0", "flex-1"]}
                            items={[
                                () => <Skeleton.Typography type="h6" width="1/2" />,
                                () => <Skeleton.Typography type="body-sm" width="3/4" />,
                            ]}
                        />
                    ),
                    () => (
                        <StackV
                            gap={2}
                            principle="title-subtitle"
                            explain="Title over supporting line — not label-field, because neither line is a form control label."
                            align="end"
                            classNames={["shrink-0"]}
                            items={[
                                () => <Skeleton.Typography type="body-sm" width="1/2" />,
                                () => (
                                    <StackH
                                        gap={2}
                                        classNames={["w-full"]}
                                        items={[
                                            () => <Skeleton.Button width="flex-1" />,
                                            () => <Skeleton.Button width="flex-1" />,
                                        ]}
                                    />
                                ),
                            ]}
                        />
                    ),
                ]}
            />
        )}
    />
)

/**
 * Featured courses catalog — the presentational half of `CourseCatalogPage`
 * (`design/storybook/architecture/tiers/split.md`). Left-aligned header
 * (breadcrumb → title), a search row (result count + grid⇆line toggle), the
 * ES-backed course grid/list, and a pager that stays visible across every
 * state. Only the grid/list region is async-gated, in the fixed order
 * error → skeleton → empty → content (`loading-and-skeleton.md`): `error`
 * falls to the shared `AsyncContentError` frame, `isEmpty` to
 * `AsyncContentEmpty`, and otherwise the ONE real grid/list tree renders —
 * `isSkeleton` swaps each card for its co-located placeholder in place,
 * instead of a hand-built parallel skeleton tree swapped in wholesale.
 *
 * `CatalogCourseCard` (and the `CourseCard` block underneath it) carries no
 * `isSkeleton` prop of its own — it is a sibling component with its own
 * `index.tsx`, out of this split's scope — so the loading placeholder per
 * card is the existing `CourseCardSkeleton` (grid) / the co-located
 * `CatalogLineCardSkeleton` (line), mirrored right where the real card sits.
 *
 * @param props - {@link CourseCatalogPageProps}
 */
export const _CourseCatalogPage = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    errorContent,
    emptyContent,
    list,
    view,
    onChangeView,
    query,
    onQueryChange,
    countLabel,
    onNavigateHome,
    currentPage,
    totalPages,
    onPageChange,
    labels,
}: CourseCatalogPageProps) => {
    // ── the grid/list region only — the header, search row, and pager stay put across
    // every state, exactly as the retired `AsyncContent` wrapper only ever wrapped this
    // region (BLOCK-8's error → skeleton → empty → content order, scoped to this region).
    const renderCatalogRegion = (): React.ReactNode => {
        if (error && errorContent) {
            return <AsyncContentError {...errorContent} />
        }
        if (!isSkeleton && isEmpty) {
            return emptyContent ? <AsyncContentEmpty {...emptyContent} /> : null
        }

        const cardItems: Array<{ key: string; Content: ComponentTypeWithSkeleton }> = isSkeleton
            ? Array.from({ length: SKELETON_ITEM_COUNT }, (_unused, index) => ({
                key: `pending-${index}`,
                Content: view === "grid"
                    ? () => <CourseCardSkeleton />
                    : () => <CatalogLineCardSkeleton />,
            }))
            : list.map((course) => ({
                key: course.id,
                Content: () => <CatalogCourseCard course={course} layout={view} />,
            }))

        if (view === "grid") {
            const gridItems: Array<GridItem> = cardItems.map(({ key, Content }) => ({ key, content: Content }))
            return (
                <Grid
                    items={gridItems}
                    columns={{ base: 1, md: 2, lg: 3 }}
                    principle="sibling-stack"
                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                    isSkeleton={isSkeleton}
                />
            )
        }
        return (
            <StackV
                gap={3}
                principle="sibling-stack"
                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                items={cardItems.map(({ Content }) => Content)}
                isSkeleton={isSkeleton}
            />
        )
    }

    return (
        <Container
            identity={{ tier: "block", component: "CourseCatalogPage" }}
            size="xl"
            padding={6}
            body={() => (
                <StackV
                    gap={6}
                    principle="block-boundary"
                    explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                    items={[
                        () => (
                            <PageHeader
                                breadcrumb={(
                                    <Breadcrumbs
                                        items={[
                                            { key: "home", label: labels.navHome, onPress: onNavigateHome },
                                            { key: "courses", label: labels.navCourses },
                                        ]}
                                    />
                                )}
                                title={labels.title}
                            />
                        ),
                        () => (
                            <Cluster
                                gap={3}
                                principle="flex-action"
                                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                justify="between"
                                align="center"
                                items={[
                                    () => <SearchInput value={query} onValueChange={onQueryChange} placeholder={labels.searchPlaceholder} />,
                                    () => (
                                        <StackH
                                            gap={3}
                                            classNames={["shrink-0"]}
                                            items={[
                                                ...(countLabel != null ? [() => <Typography size="sm" color="muted" text={countLabel} />] : []),
                                                () => (
                                                    <TabsCard
                                                        variant="primary"
                                                        leftTabs={{
                                                            selectedKey: view,
                                                            ariaLabel: labels.viewAria,
                                                            onSelectionChange: (key: Key) => onChangeView(String(key) as CatalogView),
                                                            items: [
                                                                {
                                                                    key: "grid",
                                                                    label: (
                                                                        <SquaresFourIcon
                                                                            className="size-5"
                                                                            aria-label={labels.viewGrid}
                                                                            focusable="false"
                                                                        />
                                                                    ),
                                                                },
                                                                {
                                                                    key: "line",
                                                                    label: (
                                                                        <ListIcon
                                                                            className="size-5"
                                                                            aria-label={labels.viewLine}
                                                                            focusable="false"
                                                                        />
                                                                    ),
                                                                },
                                                            ],
                                                        }}
                                                    />
                                                ),
                                            ]}
                                        />
                                    ),
                                ]}
                            />
                        ),
                        () => renderCatalogRegion(),
                        () => (
                            // Always rendered (even a single page) so the catalog's page-boundary UI
                            // is stable as the course count grows — per the teacher's call, do not
                            // hide it at ≤ PAGE_SIZE. Every page number shown (no windowing), matching
                            // the pre-split pager exactly.
                            <Pagination
                                className="mt-0 justify-start"
                                currentPage={currentPage}
                                totalPages={totalPages}
                                onPageChange={onPageChange}
                            />
                        ),
                    ]}
                />
            )}
        />
    )
}

import React from "react"
import {
    ArrowRightIcon,
    CheckCircleIcon,
    CircleIcon,
    ClockIcon,
    LockIcon,
    PlayIcon,
    StackIcon,
    UsersIcon,
} from "@phosphor-icons/react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { HighlightChip } from "@/components/composites/chips/HighlightChip"
import { PageHeader } from "@/components/composites/layout/Page"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"
import { Button } from "@/components/atoms/buttons/Button"
import { Typography } from "@/components/atoms/text/Typography"
import { Container } from "@/components/frames/Container"
import { StackH, StackV } from "@/components/frames/Stack"
import { DifficultyChip, type Difficulty } from "@/components/blocks/chips/DifficultyChip"
import { GithubTeamGate } from "@/components/blocks/auth/GithubTeamGate"
import { LearnBreadcrumb } from "@/components/blocks/learn/LearnBreadcrumb"
import { LearnNudges } from "@/components/blocks/learn/LearnNudges"
import { TrialConversionStrip } from "@/components/blocks/commerce/TrialConversionStrip"

/** One lesson row on the "keep going" path — leading state icon · title · minutes-read · difficulty + premium-lock. */
export interface CourseContentsLesson {
    /** Stable id (React key + reader deep-link target). */
    id: string
    /** Lesson title — the row's primary line. */
    title: string
    /** Already-localized "N min read" caption — the row's subtitle. */
    minutesReadText: string
    /** Where the viewer stands on this lesson: the highlighted next one, an already-read one, or untouched. */
    state: "active" | "read" | "unread"
    /** Difficulty tier (resolved from the raw string by the connected file); omitted → no difficulty chip. */
    difficulty?: Difficulty
    /** `true` → a premium lesson the trial viewer can't open yet → a trailing lock. */
    isPremium: boolean
    /** Open this lesson in the reader. */
    onPress: () => void
}

/** Catalog meta figures for the header chips — identity facts the progress stat line does NOT carry. */
export interface CourseContentsMeta {
    /** Chapter/module count. */
    moduleCount: number
    /** Already-formatted study-hours figure (e.g. `"~3"`). */
    hoursText: string
    /** Already-formatted learner count; omitted → the learners chip is skipped. */
    learnersText?: string
}

/** All display text, already localized by the connected {@link CourseContents}; a story passes i18n keys. */
export interface CourseContentsLabels {
    emptyTitle: string
    errorTitle: string
    retry: string
    /** Meta-chip labels. */
    metaModulesLabel: string
    metaHoursLabel: string
    metaLearnersLabel: string
    /** Continue-cluster eyebrow — the connected file picks capstone / continue / all-done. */
    eyebrow: string
    /** Primary resume-button label — the connected file picks capstone vs normal. */
    resumeButton: string
    /** Meter label. */
    completion: string
    /** Full "lessons · challenges" stat line — the connected file interpolates + joins it. */
    progressStat: string
    /** Keep-going kicker; the presentational file appends `· <module title>`. */
    keepGoing: string
    /** Premium-lock accessible name. */
    premiumLabel: string
}

/** Props for {@link _CourseContents} — presentational; all data resolved, no fetch/store/i18n. */
export interface CourseContentsProps {
    /** Async status, owned by the connected file. */
    isLoading?: boolean
    error?: unknown
    onRetry?: () => void
    /** `true` (after loading) → no outline → the empty state. */
    isEmpty?: boolean
    /** Course title — the page heading. */
    title: string
    /** One-line course description under the title. */
    description?: string
    /** Header catalog meta; omitted → the meta chip row is skipped. */
    meta?: CourseContentsMeta
    /** Present ONLY for a not-yet-enrolled learner (the connected file owns that gate) → the conversion strip renders. */
    trialStrip?: {
        courseId: string
        freeLessonsRemaining: number
    }
    /** Resume target's title; omitted → no continue title line. */
    resumeTitle?: string
    /** Open the resume target; omitted → no resume button (all done). */
    onResume?: () => void
    /** Overall completion percent (0-100) for the meter. */
    completionPercent: number
    /** The current module's title — the keep-going heading. */
    moduleTitle?: string
    /** The current module's lessons = the keep-going path. Empty → the path is skipped. */
    lessons: Array<CourseContentsLesson>
    labels: CourseContentsLabels
}

/** state → leading icon on the lesson row (the frame forces `size-5`). */
const STATE_ICON = {
    active: PlayIcon,
    read: CheckCircleIcon,
    unread: CircleIcon,
} as const

/**
 * Placeholder rows for the keep-going path while loading. ONE tree — the resting
 * state is the SAME `SurfaceCardList` shimmered, never a hand-mirrored copy that drifts.
 */
const SKELETON_LESSON_ROWS: Array<SurfaceCardListItem> = Array.from({ length: 4 }, (_unused, index) => ({
    key: `skeleton-lesson-${index}`,
    title: "Lesson",
    subtitle: "min read",
    leadingIcon: CircleIcon,
}))

/** Breadcrumb slot for the header — a connected child that self-fetches its crumbs (split.md). */
const BreadcrumbSlot: ComponentTypeWithSkeleton = () => <LearnBreadcrumb />

interface CourseContentsMetaChipsProps {
    meta: CourseContentsMeta
    labels: Pick<CourseContentsLabels, "metaModulesLabel" | "metaHoursLabel" | "metaLearnersLabel">
}

const CourseContentsMetaChips = ({ meta, labels }: CourseContentsMetaChipsProps) => (
    <StackH
        gap={3}
        items={[
            () => <HighlightChip icon={StackIcon} value={meta.moduleCount} label={labels.metaModulesLabel} />,
            () => <HighlightChip icon={ClockIcon} value={meta.hoursText} label={labels.metaHoursLabel} />,
            ...(meta.learnersText
                ? [() => <HighlightChip icon={UsersIcon} value={meta.learnersText!} label={labels.metaLearnersLabel} />]
                : []),
        ]}
    />
)

/**
 * Course-content home — the presentational half of {@link CourseContents}, composed on the
 * tier-correct storybook vocabulary (`Container` / `PageHeader` / `HighlightChip` / `ProgressMeter` /
 * `SurfaceCardList`). Layout: breadcrumb → header (title + description + catalog meta) → GitHub-team
 * warning → trial conversion strip (gated by the connected file) → continue cluster (eyebrow + resume
 * title + Resume button, one honest completion meter, the lessons·challenges stat line) → contextual
 * nudges → keep-going path (the current module's lessons as rows). The self-fetching children
 * (`GithubTeamGate` / `TrialConversionStrip` / `LearnNudges` / `LearnBreadcrumb`) are rendered as-is —
 * a presentational screen may render connected children (split.md). The connected `index.tsx` owns the
 * fetch and i18n.
 *
 * @param props - {@link CourseContentsProps}
 */
export const _CourseContents = ({
    isLoading = false,
    error,
    onRetry,
    isEmpty = false,
    title,
    description,
    meta,
    trialStrip,
    resumeTitle,
    onResume,
    completionPercent,
    moduleTitle,
    lessons,
    labels,
}: CourseContentsProps) => {
    const metaSlot: ComponentTypeWithSkeleton | undefined = meta
        ? () => <CourseContentsMetaChips meta={meta} labels={labels} />
        : undefined

    // Keep-going path rows — each lesson as a fixed SurfaceCardList row: leading state icon, title,
    // minutes-read subtitle, and a difficulty + premium-lock meta slot.
    const lessonRows: Array<SurfaceCardListItem> = lessons.map((lesson) => {
        const { difficulty, isPremium } = lesson
        const metaSlot = difficulty != null || isPremium
            ? () => (
                <StackH
                    gap={3}
                    items={[
                        ...(difficulty != null ? [() => <DifficultyChip difficulty={difficulty} />] : []),
                        ...(isPremium ? [() => (
                            <LockIcon
                                aria-label={labels.premiumLabel}
                                focusable="false"
                                className="size-5 text-muted"
                            />
                        )] : []),
                    ]}
                />
            )
            : undefined
        return {
            key: lesson.id,
            title: lesson.title,
            subtitle: lesson.minutesReadText,
            leadingIcon: STATE_ICON[lesson.state],
            leadingIconColor: lesson.state === "active" ? "accent" : lesson.state === "read" ? "success" : undefined,
            onPress: lesson.onPress,
            meta: metaSlot,
        }
    })

    // ONE tree — the resting state is this SAME spine with `isSkeleton` threaded into every
    // shimmer-capable part, never a hand-mirrored copy. `spine(true)` is the loading branch,
    // `spine(false)` the content branch; they cannot drift because they are the same code.
    const spine = (isSkeleton: boolean) => (
        <Container
            identity={{ tier: "page", component: "CourseContents" }}
            size="md"
            principle="center-measure"
            explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport."
            body={() => (
                <StackV
                    gap={7}
                    principle="layout-split"
                    explain="Major layout split — not block-boundary, because this separates primary page regions rather than adjacent blocks."
                    items={[
                        // Header — its OWN tier, gap-10 (page band) from the content cluster below.
                        () => (
                            <PageHeader
                                breadcrumb={BreadcrumbSlot}
                                title={title}
                                description={description}
                                meta={metaSlot}
                                isSkeleton={isSkeleton}
                            />
                        ),
                        // Content cluster: GitHub-team warning · trial strip · continue · nudges · path.
                        // The connected children (GithubTeamGate · TrialConversionStrip · LearnNudges)
                        // own THEIR resting shape — they self-fetch and shimmer themselves.
                        () => (
                            <StackV
                                gap={6}
                                principle="block-boundary"
                                explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                                items={[
                                    () => <GithubTeamGate />,
                                    ...(trialStrip ? [() => (
                                        <TrialConversionStrip
                                            courseId={trialStrip.courseId}
                                            freeLessonsRemaining={trialStrip.freeLessonsRemaining}
                                        />
                                    )] : []),
                                    // Continue + progress — flat (no card face), the honest unified meter.
                                    () => (
                                        <StackV
                                            gap={4}
                                            principle="card-caption"
                                            explain="Holds caption text under card media so the caption stays attached to the image above it."
                                            items={[
                                                () => (
                                                    <StackH
                                                        align="start"
                                                        justify="between"
                                                        gap={4}
                                                        principle="content-row"
                                                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                        items={[
                                                            () => (
                                                                <StackV
                                                                    gap={1}
                                                                    classNames={["min-w-0"]}
                                                                    items={[
                                                                        () => <Typography size="xs" color="muted" isSkeleton={isSkeleton} text={labels.eyebrow} />,
                                                                        ...(isSkeleton || resumeTitle ? [() => (
                                                                            <Typography size="base" weight="semibold" truncate isSkeleton={isSkeleton} text={resumeTitle} />
                                                                        )] : []),
                                                                    ]}
                                                                />
                                                            ),
                                                            // Button carries no `isSkeleton` — a resting screen shows no CTA yet.
                                                            ...(!isSkeleton && onResume ? [() => (
                                                                <Button
                                                                    label={labels.resumeButton}
                                                                    variant="primary"
                                                                    size="lg"
                                                                    suffixIcon={ArrowRightIcon}
                                                                    iconSlide
                                                                    onPress={onResume}
                                                                    classNames={["shrink-0"]}
                                                                />
                                                            )] : []),
                                                        ]}
                                                    />
                                                ),
                                                () => (
                                                    <ProgressMeter
                                                        value={completionPercent}
                                                        max={100}
                                                        label={labels.completion}
                                                        showValue
                                                        isSkeleton={isSkeleton}
                                                    />
                                                ),
                                                () => <Typography size="xs" color="muted" isSkeleton={isSkeleton} text={labels.progressStat} />,
                                            ]}
                                        />
                                    ),
                                    // Contextual nudges — aids that orbit the spine; each self-hides at 0.
                                    () => <LearnNudges />,
                                    // Keep-going path — the current module's lessons (the full tree lives
                                    // in the left content-map rail, so the body never re-draws it).
                                    // While loading it shimmers the SAME list with placeholder rows.
                                    ...((isSkeleton || lessons.length > 0) ? [() => (
                                        <StackV
                                            gap={4}
                                            items={[
                                                () => (
                                                    <Typography
                                                        size="sm"
                                                        weight="semibold"
                                                        color="muted"
                                                        isSkeleton={isSkeleton}
                                                        text={`${labels.keepGoing} · ${moduleTitle ?? ""}`}
                                                    />
                                                ),
                                                () => <SurfaceCardList items={isSkeleton ? SKELETON_LESSON_ROWS : lessonRows} isSkeleton={isSkeleton} />,
                                            ]}
                                        />
                                    )] : []),
                                ]}
                            />
                        ),
                    ]}
                />
            )}
        />
    )

    // error → skeleton → empty → content (BLOCK-8): the empty and error surfaces are the shared
    // `AsyncContent*` frames dropped in as their own states; otherwise the ONE spine renders, with
    // `isLoading` flowing in as the co-located shimmer flag (loading-and-skeleton.md §6).
    const inner = error
        ? <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retry} />
        : (!isLoading && isEmpty)
            ? <AsyncContentEmpty title={labels.emptyTitle} />
            : spine(isLoading)

    return inner
}

