import React from "react"
import {
    CaretRightIcon,
} from "@phosphor-icons/react"
import {
    useTranslations,
} from "next-intl"
import _ from "lodash"
import { StatusChip } from "@/components/blocks/chips/StatusChip"
import { MarkdownContent } from "@/components/blocks/rendering/MarkdownContent"
import { CourseContentTier } from "@/modules/types/enums/course-content-tier"
import { type ModuleEntity } from "@/modules/types/entities/module"
import {
    AccordionTreeBody,
    AccordionTreeHeading,
    AccordionTreeItem,
    AccordionTreePanel,
    AccordionTreeTrigger,
} from "@/components/atoms/navigation/AccordionTree"
import { Typography } from "@/components/atoms/text/Typography"
import { Cluster } from "@/components/frames/Cluster"
import { StackH, StackV } from "@/components/frames/Stack"

/** Chip tone per learning tier (foundation → advanced reads easy → hard). */
const TIER_TONE: Record<CourseContentTier, "success" | "warning" | "danger"> = {
    [CourseContentTier.Foundation]: "success",
    [CourseContentTier.Intermediate]: "warning",
    [CourseContentTier.Advanced]: "danger",
}

/** Props for {@link ModuleAccordionItem}. */
export interface ModuleAccordionItemProps {
    /** The module to render as one accordion row (list-item data prop). */
    module: ModuleEntity
}

/**
 * One curriculum module as an accordion row: title + tier badge + premium lock in
 * the trigger; lesson/minute meta + description + free preview bullets in the
 * panel. List-item (rendered in a `.map`), so it takes the `module` data prop.
 *
 * @param props - {@link ModuleAccordionItemProps}
 */
export const ModuleAccordionItem = ({ module }: ModuleAccordionItemProps) => {
    const t = useTranslations()

    const contents = module.contents ?? []
    const minutes = contents.reduce((sum, content) => sum + (content.minutesRead ?? 0), 0)
    const lessonCount = module.numContents || contents.length
    const previews = _.cloneDeep(module.previewContents ?? []).sort(
        (a, b) => a.sortIndex - b.sortIndex,
    )
    const contentTier = module.contentTier

    return (
        <AccordionTreeItem aria-label={module.title}>
            <AccordionTreeHeading>
                <AccordionTreeTrigger>
                    <StackH gap={4} principle="content-row"
                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                        classNames={["min-w-0", "flex-1"]} justify="between" align="center" items={[
                            () => (
                                <Typography
                                    size="sm"
                                    weight="medium"
                                    truncate
                                    classNames={["min-w-0"]}
                                    text={module.title}
                                />
                            ),
                            () => (
                                <Cluster
                                    gap={3}
                                    principle="chip-row"
                                    explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                    classNames={["shrink-0"]}
                                    items={[
                                        ...(contentTier ? [() => (
                                            <StatusChip tone={TIER_TONE[contentTier]}>
                                                {t(`courseLanding.tier.${contentTier}`)}
                                            </StatusChip>
                                        )] : []),
                                        ...(previews.length > 0 ? [() => (
                                            <StatusChip tone="neutral">
                                                {t("courseLanding.previewCount", { count: previews.length })}
                                            </StatusChip>
                                        )] : []),
                                    ]}
                                />
                            ),
                        ]} />
                </AccordionTreeTrigger>
            </AccordionTreeHeading>
            <AccordionTreePanel>
                <AccordionTreeBody>
                    <StackV gap={4} principle="card-caption"
                        explain="Holds caption text under card media so the caption stays attached to the image above it."
                        items={[
                            () => (
                                <Typography
                                    size="xs"
                                    color="muted"
                                    text={t("courseLanding.moduleMeta", { lessons: lessonCount, minutes })}
                                />
                            ),
                            () => (module.description ? (
                                <MarkdownContent markdown={module.description} />
                            ) : null),
                            () => (previews.length > 0 ? (
                                <StackV gap={2} principle="sibling-stack"
                                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                    items={previews.map((preview) => () => (
                                        <StackH key={preview.id} gap={3} principle="identity"
                                            explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                                            align="start" items={[
                                                () => <CaretRightIcon aria-hidden focusable="false" className="size-4 shrink-0 text-muted" />,
                                                () => (
                                                    <Typography size="sm" color="muted" text={preview.text} />
                                                ),
                                            ]} />
                                    ))}
                                />
                            ) : null),
                        ]} />
                </AccordionTreeBody>
            </AccordionTreePanel>
        </AccordionTreeItem>
    )
}

import React from "react"
import type { ReactNode } from "react"
import {
    ListChecksIcon,
} from "@phosphor-icons/react"
import { AccordionTree } from "@/components/atoms/navigation/AccordionTree"
import {
    ModuleAccordionItem,
} from "./ModuleAccordionItem"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { type ModuleEntity } from "@/modules/types/entities/module"

/** Number of placeholder rows the co-located skeleton shows (mirrors the old `Skeleton.Accordion items={3}`). */
const SKELETON_ITEM_COUNT = 3

/** All display text, already localized by the connected {@link import("./index").CourseCurriculum}; a story passes i18n keys. */
export interface CourseCurriculumLabels {
    /** Section label shown OUTSIDE the card (`LabeledCard.label`). */
    curriculum: string
    /** Settled with a fetch error — the error state's title. */
    errorTitle: string
    /** Retry-button label on the error state. */
    retry: string
    /** Settled with zero modules — the empty state's title. */
    emptyTitle: string
    /** Settled with zero modules — the empty state's description. */
    emptyDescription: string
}

/** Props for {@link _CourseCurriculum} — presentational; all data resolved, no fetch/store/i18n. */
export interface CourseCurriculumProps {
    /** First load, nothing in hand → the co-located skeleton shimmers in place. Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with zero modules → the empty state. */
    isEmpty?: boolean
    /** Truthy → the error message (beats loading + empty). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retries the failed course query. */
    onRetry?: () => void
    /** Every module, already sorted by `sortIndex`. */
    modules: Array<ModuleEntity>
    labels: CourseCurriculumLabels
}

/**
 * `_CourseCurriculum` — the presentational half of {@link import("./index").CourseCurriculum}
 * (`tiers/split.md`): every module as an accordion row (tier badge, premium lock, lesson/minute
 * meta, free preview bullets) so a prospect can scan exactly what's inside. `ModuleAccordionItem`
 * takes no `isSkeleton` prop of its own — it is not a leaf built to mirror itself
 * (`loading-and-skeleton.md` §1's stated exception) — so the loading accordion swaps in the
 * co-located `Skeleton.Accordion` at the same tree position instead of threading a flag through it.
 *
 * @param props - {@link CourseCurriculumProps}
 */
export const _CourseCurriculum = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    modules,
    labels,
}: CourseCurriculumProps) => {
    // frameless ONLY once the accordion itself self-frames (surface variant, real modules in hand);
    // every other branch (error / empty / loading) has no bounded surface of its own, so LabeledCard's
    // own Card must frame it — otherwise the message/skeleton renders bare on the page background.
    const frameless = !isSkeleton && !error && modules.length > 0

    // error beats a stale loading flag; empty only once settled (BLOCK-8). Both message branches come
    // from the shared `AsyncContent*` frames, not hand-written JSX (loading-and-skeleton.md §6).
    let body: ReactNode
    if (error) {
        body = <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retry} />
    } else if (!isSkeleton && isEmpty) {
        body = (
            <AsyncContentEmpty
                icon={ListChecksIcon}
                title={labels.emptyTitle}
                description={labels.emptyDescription}
            />
        )
    } else if (isSkeleton) {
        body = <Skeleton.Accordion items={SKELETON_ITEM_COUNT} />
    } else {
        // Accordion Card: the surface accordion sits directly on the page background
        // (frameless, NOT nested inside a Card → avoids a flat surface-in-surface) + a card border.
        // Ref elements/card.md §3 + draft accordion-card-surface-on-standalone-pages.
        body = (
            <AccordionTree variant="surface">
                {modules.map((module) => (
                    <ModuleAccordionItem key={module.id} module={module} />
                ))}
            </AccordionTree>
        )
    }

    return (
        <LabeledCard
            identity={{ tier: "block", component: "CourseCurriculum" }}
            label={labels.curriculum}
            frameless={frameless}
        >
            {body}
        </LabeledCard>
    )
}

"use client"

import React, {
    useMemo,
} from "react"
import {
    useTranslations,
} from "next-intl"
import _ from "lodash"
import { useQueryCourseSwr } from "@/hooks/swr/api/graphql/queries/useQueryCourseSwr"
import { useAppSelector } from "@/redux/hooks"
import { _CourseCurriculum } from "./component"

/**
 * Curriculum section (connected half, `tiers/split.md`): fetches the course, reads its modules from
 * redux, computes the async decisions (`isSkeleton` from the first-load formula, `isEmpty` from the
 * resolved list), resolves every label, and hands them to the presentational
 * {@link _CourseCurriculum}.
 */
export const CourseCurriculum = () => {
    const t = useTranslations()
    const { isLoading, error, mutate } = useQueryCourseSwr()
    const rawModules = useAppSelector((state) => state.course.entity?.modules)

    const modules = useMemo(
        () => _.cloneDeep(rawModules ?? []).sort((a, b) => a.sortIndex - b.sortIndex),
        [rawModules],
    )

    return (
        <_CourseCurriculum
            // first load, nothing in hand → shimmer (loading-and-skeleton.md §2)
            isSkeleton={isLoading && modules.length === 0}
            // settled with no modules → the empty message
            isEmpty={modules.length === 0}
            error={error}
            onRetry={() => { void mutate() }}
            modules={modules}
            labels={{
                curriculum: t("courseLanding.curriculum"),
                errorTitle: t("courseLanding.errorTitle"),
                retry: t("courseLanding.retry"),
                emptyTitle: t("courseLanding.empty.curriculum.title"),
                emptyDescription: t("courseLanding.empty.curriculum.hint"),
            }}
        />
    )
}

import React from "react"
import { QuestionIcon } from "@phosphor-icons/react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { LabeledAccordionCard } from "@/components/blocks/cards/LabeledAccordionCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { MarkdownContent } from "@/components/blocks/rendering/MarkdownContent"
import type { QnaEntity } from "@/modules/types/entities/qna"
import type { CallerIdentity } from "@/components/frames/_identity"

/** This block's own identity, handed down to whichever card is standing in as its root (BLOCK-2). */
const IDENTITY: CallerIdentity = { tier: "block", component: "CourseFaq" }

/** All display text, already localized by the connected `CourseFaq`; a story passes i18n keys. */
export interface CourseFaqLabels {
    /** Section label — rendered by `LabeledCard` on every branch and by `LabeledAccordionCard` once content is showing. */
    label: string
    errorTitle: string
    retry: string
    emptyTitle: string
    emptyDescription: string
}

/** Props for {@link _CourseFaq} — presentational; all data resolved, no fetch/store/i18n. */
export interface CourseFaqProps {
    /**
     * First load, nothing in hand → the loading branch shimmers in place. Owned by the connected
     * file (loading-and-skeleton.md's first-load formula). `LabeledCard`/`LabeledAccordionCard`
     * carry no `isSkeleton` of their own — see `missingSkeletonSupport` — so this swaps in
     * `Skeleton.Accordion` right where the accordion would sit, still co-located (not a parallel
     * skeleton tree/file).
     */
    isSkeleton?: boolean
    /** Settled with zero Q&A entries → the empty message (beats content, loses to loading). */
    isEmpty?: boolean
    /** Truthy → the error message (beats loading + empty). The connected file passes its fetch error. */
    error?: unknown
    /** Retry handler, paired with `labels.retry` on the error branch. */
    onRetry?: () => void
    /** Q&A entries, already sorted by `sortIndex`; ignored while `isSkeleton`. */
    qnas?: Array<QnaEntity>
    labels: CourseFaqLabels
}

/**
 * FAQ section: the course Q&A pairs as an accordion (markdown answers) — removes a common
 * objection before the buy decision. Presentational half of {@link import("./index").CourseFaq}:
 * error beats a stale loading flag, empty only once settled. `LabeledAccordionCard` (the content
 * branch) owns its accordion frame + label itself, so unlike most blocks this does not thread a
 * single tree with `isSkeleton` — `LabeledCard`/`LabeledAccordionCard` take no `isSkeleton` prop
 * (`missingSkeletonSupport`), so the loading branch mirrors the shape with `Skeleton.Accordion`
 * inline instead, framed the same way the error/empty branches are. See `tiers/split.md` — the
 * connected `index.tsx` owns the fetch and i18n.
 *
 * @param props - {@link CourseFaqProps}
 */
const _CourseFaq = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    qnas = [],
    labels,
}: CourseFaqProps) => {
    // error beats a stale loading flag; empty only once settled (BLOCK-8 order: error → loading → empty → content).
    const body = (() => {
        if (error) {
            return (
                <LabeledCard label={labels.label} identity={IDENTITY}>
                    <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retry} />
                </LabeledCard>
            )
        }
        if (isSkeleton) {
            return (
                <LabeledCard label={labels.label} identity={IDENTITY}>
                    <Skeleton.Accordion items={3} />
                </LabeledCard>
            )
        }
        if (isEmpty) {
            return (
                <LabeledCard label={labels.label} identity={IDENTITY}>
                    <AsyncContentEmpty
                        icon={QuestionIcon}
                        title={labels.emptyTitle}
                        description={labels.emptyDescription}
                    />
                </LabeledCard>
            )
        }

        // content — the accordion card IS the frame + owns its own label (LabeledAccordionCard).
        // WARNING LabeledAccordionCard takes no `identity` prop (unlike LabeledCard) and there is no
        // sibling frame here to carry it instead — this branch's root stays unowned (unownedRoot).
        return (
            <LabeledAccordionCard
                label={labels.label}
                items={qnas.map((qna) => ({
                    id: qna.id,
                    title: qna.question,
                    body: () => <MarkdownContent markdown={qna.answer} />,
                }))}
            />
        )
    })()

    return body
}

export { _CourseFaq }

