    const t = useTranslations()
    const { active } = usePricingRows()
    const { isEnrolled, onEnroll, onContinueLearning } = useCourseEnrollment()
    const courseId = useAppSelector((state) => state.course.entity?.id)
    // viewer's loyalty price (matches the rail / catalog) — fall back to phase price.
    const { data: preview, isLoading: previewLoading } = useQueryCoursePricePreviewSwr(courseId ?? null)
    const hasLoyalty = preview != null && preview.discountPercent > 0
    // same jump as CoursePricingRail (2026-07-12): don't flash the static price
    // before the loyalty preview resolves — skeleton the price line instead.
    const previewPending = previewLoading && !preview

    return (
        <StickyBottomBar>
            <StackH gap={4} principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                justify="between" align="center" items={[
                    () => (previewPending ? (
                        <Skeleton.Typography type="body" width="1/4" />
                    ) : hasLoyalty && preview ? (
                        <PriceTagInline
                            discounted={preview.discountedPriceVnd}
                            original={preview.originalPriceVnd}

                        />
                    ) : active ? (
                        <PriceTagInline
                            discounted={active.priceVnd}
                            original={active.listPriceVnd}

                        />
                    ) : null),
                    () => (isEnrolled ? (
                        <Button variant="primary" onPress={onContinueLearning}>
                            <GraduationCapIcon className="size-5" />
                            {t("course.continueLearning")}
                        </Button>
                    ) : (
                        <Button variant="primary" onPress={onEnroll}>
                            {t("course.enroll")}
                            <ArrowRightIcon className="size-5" />
                        </Button>
                    )),
                ]} />
        </StickyBottomBar>
    )
}

import React from "react"
import { ListBulletsIcon } from "@phosphor-icons/react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { CheckListCard, CheckListItem } from "@/components/blocks/cards/CheckListCard"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { Typography } from "@/components/atoms/text/Typography"

/** How many placeholder rows the co-located skeleton shows. */
const SKELETON_ROW_COUNT = 3

/** One prerequisite row, already sorted/resolved by the connected `CoursePrerequisites`. */
export interface CoursePrerequisiteItem {
    id: string
    text: string
}

/** All display text, already localized by the connected `CoursePrerequisites`; a story passes i18n keys. */
export interface CoursePrerequisitesLabels {
    /** Section label, rendered above the card by `LabeledCard`. */
    label: string
    errorTitle: string
    retry: string
    emptyTitle: string
    emptyDescription: string
}

/** Props for {@link _CoursePrerequisites} — presentational; all data resolved, no fetch/store/i18n. */
export interface CoursePrerequisitesProps {
    /** First load, nothing in hand → the whole tree shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with an empty list → the empty message. */
    isEmpty?: boolean
    /** Truthy → the error message (beats loading + empty). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler — paired with `labels.retry` to show a retry button on the error branch. */
    onRetry?: () => void
    /** The prerequisite rows, already sorted by `sortIndex`. */
    items?: Array<CoursePrerequisiteItem>
    labels: CoursePrerequisitesLabels
}

/**
 * "Before you start" section — the presentational half of {@link CoursePrerequisites}: the course
 * prerequisites as a neutral bullet list (informational, NOT a warning alert; prerequisites are
 * things you need beforehand, not achievements, so rows carry no tick). Four states in the fixed
 * order error → loading → empty → content: `error` falls to the shared `AsyncContentError` frame,
 * `isEmpty` to `AsyncContentEmpty`, and otherwise the ONE real tree renders with `isSkeleton`
 * threaded to every leaf so the shimmer mirrors the loaded shape (loading-and-skeleton.md). See
 * `tiers/split.md` — the connected `index.tsx` owns the fetch, redux read, and i18n.
 *
 * @param props - {@link CoursePrerequisitesProps}
 */
export const _CoursePrerequisites = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    items = [],
    labels,
}: CoursePrerequisitesProps) => {
    // error beats a stale loading flag; empty only once settled (loading-and-skeleton.md §1)
    if (error) {
        return (
            <LabeledCard
                label={labels.label}
                frameless
                identity={{ tier: "block", component: "CoursePrerequisites" }}
            >
                <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retry} />
            </LabeledCard>
        )
    }
    if (!isSkeleton && isEmpty) {
        return (
            <LabeledCard
                label={labels.label}
                frameless
                identity={{ tier: "block", component: "CoursePrerequisites" }}
            >
                <AsyncContentEmpty
                    icon={ListBulletsIcon}
                    title={labels.emptyTitle}
                    description={labels.emptyDescription}
                />
            </LabeledCard>
        )
    }

    // while shimmering, placeholder rows keep the SAME CheckListCard/CheckListItem shape as the
    // resolved list, at the same fixed count the old hand-built skeleton mirrored (loading-and-skeleton.md §2)
    const rows = isSkeleton
        ? Array.from({ length: SKELETON_ROW_COUNT }, (_unused, index) => ({ id: `pending-${index}`, text: "" }))
        : items

    return (
        <LabeledCard
            label={labels.label}
            frameless
            identity={{ tier: "block", component: "CoursePrerequisites" }}
        >
            <CheckListCard>
                {rows.map((item) => (
                    <CheckListItem key={item.id} showCheck={false}>
                        <Typography size="sm" text={item.text} isSkeleton={isSkeleton} />
                    </CheckListItem>
                ))}
            </CheckListCard>
        </LabeledCard>
    )
}

"use client"

import React, {
    useMemo,
} from "react"
import {
    useTranslations,
} from "next-intl"
import _ from "lodash"
import { useQueryCourseSwr } from "@/hooks/swr/api/graphql/queries/useQueryCourseSwr"
import { useAppSelector } from "@/redux/hooks"
import { _CoursePrerequisites } from "./component"

/**
 * "Before you start" section — the CONNECTED half: it reads the course SWR flags + the redux
 * entity, sorts the prerequisite rows, resolves every label, and hands them to the
 * presentational {@link _CoursePrerequisites}. See `tiers/split.md`.
 */
export const CoursePrerequisites = () => {
    const t = useTranslations()
    const { isLoading, error, mutate } = useQueryCourseSwr()
    const rawItems = useAppSelector((state) => state.course.entity?.prerequisites)

    const items = useMemo(
        () => _.cloneDeep(rawItems ?? []).sort((a, b) => a.sortIndex - b.sortIndex),
        [rawItems],
    )

    return (
        <_CoursePrerequisites
            // first load, nothing in hand → shimmer; settled (items in hand) stops it (loading-and-skeleton.md §2)
            isSkeleton={isLoading && items.length === 0}
            isEmpty={items.length === 0}
            error={error}
            onRetry={() => mutate()}
            items={items}
            labels={{
                label: t("courseLanding.prerequisites"),
                errorTitle: t("courseLanding.errorTitle"),
                retry: t("courseLanding.retry"),
                emptyTitle: t("courseLanding.empty.prerequisites.title"),
                emptyDescription: t("courseLanding.empty.prerequisites.hint"),
            }}
        />
    )
}

