"use client"

import React from "react"
import { CheckCircleIcon, CircleIcon } from "@phosphor-icons/react"
import { AsyncContentError } from "@/components/composites/async/AsyncContent"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import type { CallerIdentity } from "@/components/frames/_identity"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Box } from "@/components/frames/Box"
import { Button } from "@/components/atoms/buttons/Button"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"

/** How many placeholder rows the co-located skeleton shows while the checklist is loading. */
const SKELETON_ROW_COUNT = 5

/** This block's own identity (BLOCK-2/split.md) — handed down to whichever root-capable frame renders as its root, per branch. See `_identity.ts`. */
const IDENTITY: CallerIdentity = { tier: "block", component: "DailyQuest" }

const DailyQuestClaimState = ({
    isSkeleton,
    claimed,
    allDone,
    isClaiming,
    onClaim,
    labels,
}: Pick<DailyQuestProps, "isSkeleton" | "claimed" | "allDone" | "isClaiming" | "onClaim" | "labels">) => (
    isSkeleton ? (
        <Typography isSkeleton size="xs" />
    ) : claimed ? (
        <Chip tone="success" text={labels.claimed} classNames={["self-start"]} />
    ) : allDone ? (
        <Button
            variant="primary"
            size="sm"
            classNames={["self-start"]}
            isPending={isClaiming}
            onPress={onClaim}
            label={labels.claim}
        />
    ) : (
        <Typography size="xs" color="muted" text={labels.completePrompt} />
    )
)

/** One resolved daily-quest task row, already localized by the connected `DailyQuest`. */
export interface DailyQuestTask {
    /** Stable row key — also names which task this is (mirrors BE `DailyQuestKey`). */
    key: string
    /** Already-translated task label, e.g. "Read a lesson". */
    title: string
    /** How many of the action the viewer has done today. */
    current: number
    /** How many are required today to complete this task. */
    target: number
}

/** All display text, already localized (and reward-count interpolated) by the connected `DailyQuest`. */
export interface DailyQuestLabels {
    /** Card header title, e.g. "Today's quest". */
    title: string
    /** Error-branch title. */
    loadError: string
    /** Error-branch retry button label. */
    retry: string
    /** "Reward claimed" chip label, shown once claimed. */
    claimed: string
    /** Claim button label — already interpolated with the reward count. */
    claim: string
    /** "Complete all N tasks to claim" prompt — already interpolated with the reward count. */
    completePrompt: string
}

/** Props for {@link _DailyQuest} — presentational; all data resolved, no fetch/store/i18n. */
export interface DailyQuestProps {
    /** First load, nothing in hand → the checklist (and the claim-state line below the card) shimmers in place. Owned by the connected file. */
    isSkeleton?: boolean
    /** Truthy → the error message (beats loading). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler — paired with `labels.retry` to show a retry button on the error branch. */
    onRetry?: () => void
    /** Today's reward already claimed. */
    claimed?: boolean
    /** Every required task has hit its target — enables the claim action. */
    allDone?: boolean
    /** Fires the claim mutation. */
    onClaim?: () => void
    /** True while the claim mutation is in flight — locks the claim button. */
    isClaiming?: boolean
    /** Today's checklist, in display order. */
    tasks?: Array<DailyQuestTask>
    labels: DailyQuestLabels
}

/**
 * "Today's quest" content — today's daily-quest checklist (read content · pass
 * challenge · review flashcards …), each row showing today's progress, plus a claim
 * action below the card that grants the reward once enough tasks are done. Content
 * only (the parent {@link import("@/components/blocks").LabeledCard} that this block
 * itself renders frames it) — the presentational half of `DailyQuest`. Two states in
 * the fixed order error → content (BLOCK-8): `error` falls to the shared
 * `AsyncContentError` frame (there is no genuine empty state — the quest set is
 * fixed, never a variable-length list that can be zero-length); otherwise the
 * checklist renders — while shimmering, `Skeleton.ListRow` placeholders keep the
 * SAME `LabeledCard` → `SurfaceCardList` shape so the box neither shrinks nor jumps
 * when data arrives. See `tiers/split.md` — the connected `index.tsx` owns the fetch
 * and i18n.
 *
 * @param props - {@link DailyQuestProps}
 */
export const _DailyQuest = ({
    isSkeleton = false,
    error,
    onRetry,
    claimed = false,
    allDone = false,
    onClaim,
    isClaiming = false,
    tasks = [],
    labels,
}: DailyQuestProps) => {
    if (error) {
        return <AsyncContentError title={labels.loadError} onRetry={onRetry} retryLabel={labels.retry} />
    }

    const skeletonItems: Array<SurfaceCardListItem> = Array.from(
        { length: SKELETON_ROW_COUNT },
        (_unused, index) => ({
            key: `skeleton-${index}`,
            content: () => (
                <Box
                    principle="cell-pad"
                    explain="Tight cell inset — not card-padding, because this sits inside a dense table or list cell rather than a card body."
                >
                    <Skeleton.ListRow withSubtitle={false} withTrailing />
                </Box>
            ),
        }),
    )

    const taskItems: Array<SurfaceCardListItem> = tasks.map((task) => {
        const done = task.current >= task.target
        return {
            key: task.key,
            leading: done
                ? () => (
                    <CheckCircleIcon
                        aria-hidden
                        focusable="false"
                        className="size-5 shrink-0 text-success-soft-foreground"
                    />
                )
                : () => (
                    <CircleIcon
                        aria-hidden
                        focusable="false"
                        className="size-5 shrink-0 text-foreground"
                    />
                ),
            // `title` is plain text — the done/todo colour rides on the leading icon alone
            // (icon.md §6: icon+title shared colour by state, icon half of the pair).
            title: task.title,
            meta: () => (
                <Typography size="xs" color="muted" text={`${task.current}/${task.target}`} />
            ),
        }
    })

    return (
        <LabeledCard
            identity={IDENTITY}
            label={labels.title}
            frameless
            description={() => (
                <DailyQuestClaimState
                    isSkeleton={isSkeleton}
                    claimed={claimed}
                    allDone={allDone}
                    isClaiming={isClaiming}
                    onClaim={onClaim}
                    labels={labels}
                />
            )}
        >
            <SurfaceCardList items={isSkeleton ? skeletonItems : taskItems} />
        </LabeledCard>
    )
}

"use client"

import React, {
    useCallback,
} from "react"
import {
    useTranslations,
} from "next-intl"
import {
    useSWRConfig,
} from "swr"
import { useQueryMyDailyQuestSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyDailyQuestSwr"
import { useMutateClaimDailyQuestRewardSwr } from "@/hooks/swr/api/graphql/mutations/useMutateClaimDailyQuestRewardSwr"
import { useGraphQLWithToast } from "@/modules/toast/hooks"
import { _DailyQuest, type DailyQuestTask } from "./component"

/**
 * "Today's quest" — the CONNECTED half: self-fetches the daily-quest leaf query,
 * resolves every task's translated title plus the reward-interpolated claim/prompt
 * copy, and hands the result to the presentational {@link _DailyQuest}. Claiming
 * refetches the quest + the reward wallet chip. See `tiers/split.md`.
 */
export const DailyQuest = () => {
    const t = useTranslations()
    const { mutate: globalMutate } = useSWRConfig()
    const runGraphQL = useGraphQLWithToast()
    const {
        data,
        error,
        mutate,
    } = useQueryMyDailyQuestSwr()
    const { trigger, isMutating } = useMutateClaimDailyQuestRewardSwr()

    /** Claim today's reward, then refresh the quest + the reward-balance chip. */
    const onClaim = useCallback(
        async () => {
            const ok = await runGraphQL(async () => {
                const result = await trigger()
                return result.data!.claimDailyQuestReward
            })
            if (ok) {
                await mutate()
                // reward balance changed → refresh the identity standing chip
                await globalMutate(["QUERY_MY_REWARD_WALLET_SWR"])
            }
        },
        [
            runGraphQL,
            trigger,
            mutate,
            globalMutate,
        ],
    )

    // each task's title is a dynamic i18n key — resolved here, next to the fetch
    // (tiers/split.md: t() lives in the connected file, never below it).
    const tasks: Array<DailyQuestTask> = (data?.tasks ?? []).map((task) => ({
        key: task.key,
        title: t(`DashboardPage.dailyQuest.tasks.${task.key}`),
        current: task.current,
        target: task.target,
    }))

    return (
        <_DailyQuest
            // first load, nothing in hand → shimmer; settled (data OR error) stops it (loading-and-skeleton.md)
            isSkeleton={!data && !error}
            // only a settled fetch error (nothing in hand) reaches the block
            error={!data ? error : undefined}
            onRetry={() => { void mutate() }}
            claimed={data?.claimed}
            allDone={data?.allDone}
            onClaim={() => { void onClaim() }}
            isClaiming={isMutating}
            tasks={tasks}
            labels={{
                title: t("DashboardPage.dailyQuest.title"),
                loadError: t("DashboardPage.loadError"),
                retry: t("DashboardPage.retry"),
                claimed: t("DashboardPage.dailyQuest.claimed"),
                claim: t("DashboardPage.dailyQuest.claim", { count: data?.reward ?? 0 }),
                completePrompt: t("DashboardPage.dailyQuest.completePrompt", { count: data?.reward ?? 0 }),
            }}
        />
    )
}

import React from "react"
import { IconLabelValueRow } from "@/components/composites/lists/IconLabelValueRow"
import type { TypographyIcon } from "@/components/atoms/text/Typography"
import { StackV } from "@/components/frames/Stack"

/**
 * One glanceable stat row (`icon + label + value`) — streak / AI credit / reward each
 * fetch on their OWN SWR leaf, so each row carries its own first-load `isSkeleton` and
 * settled `isEmpty` rather than the block sharing a single flag (loading-and-skeleton.md
 * §2). Rendered through the co-located {@link IconLabelValueRow} composite, which already
 * owns the icon/label/value shimmer — there is no separate skeleton tree to hand-keep.
 */
export interface IdentityStatRow {
    /** First load, nothing in hand yet → the row shimmers in place. */
    isSkeleton?: boolean
    /** Settled with nothing to show → the row hides itself (mirrors the legacy branch, which rendered no message here either). */
    isEmpty?: boolean
    /** Leading glyph — a Phosphor icon COMPONENT reference, never built JSX. */
    icon: TypographyIcon
    /** Already-translated row label (e.g. "Streak"). Resolved regardless of `isSkeleton`/`isEmpty` — it never depends on the fetch. */
    label: string
    /** Already-translated/formatted value (e.g. "3 days"). Ignored while `isSkeleton`. */
    value: string
}

/** Props for {@link _IdentityStats} — presentational; all data resolved, no fetch/store/i18n. */
export type IdentityStatsProps = {
    /** Current streak row. */
    streak: IdentityStatRow
    /** Remaining weekly AI credit row. */
    credit: IdentityStatRow
    /** Reward wallet balance row. */
    reward: IdentityStatRow
}

/**
 * Renders one row, or hides it once settled with nothing to show — the same
 * error → skeleton → empty → content priority the legacy `AsyncContent` branch used,
 * minus the message branches this region never configured (neither `emptyContent` nor
 * `errorContent` was ever passed on the old block, so nothing is shown here either;
 * only the co-located shimmer changed).
 */
const renderRow = (row: IdentityStatRow, key: string) => {
    if (!row.isSkeleton && row.isEmpty) {
        return null
    }
    return (
        <IconLabelValueRow
            key={key}
            icon={row.icon}
            label={row.label}
            value={row.value}
            isSkeleton={row.isSkeleton}
        />
    )
}

/**
 * `_IdentityStats` — the presentational half of {@link import("./index").IdentityStats}:
 * viewer "standing" stat rows for the identity column (current streak, remaining weekly
 * AI credit, reward balance). Each row is its own async leaf — `isSkeleton` is threaded
 * straight into {@link IconLabelValueRow}, which draws its own shimmer, so there is no
 * hand-kept parallel skeleton tree (loading-and-skeleton.md). Owns no fetch, no store, no
 * i18n (that lives in the connected `./index.tsx` — see `tiers/split.md`).
 *
 * @param props - {@link IdentityStatsProps}
 */
export const _IdentityStats = ({
    streak,
    credit,
    reward,
}: IdentityStatsProps) => (
    <StackV
        identity={{ tier: "block", component: "IdentityStats" }}
        gap={2}
        items={[
            () => renderRow(streak, "streak"),
            () => renderRow(credit, "credit"),
            () => renderRow(reward, "reward"),
        ]}
    />
)

