import React from "react"
import type {
    Key,
} from "react"
import {
    AsyncContentEmpty,
    AsyncContentError,
} from "@/components/composites/async/AsyncContent"
import {
    SurfaceListCard,
    SurfaceListCardItem,
} from "@/components/blocks/cards/SurfaceListCard"
import {
    TabsCard,
    type TabsCardItem,
} from "@/components/blocks/navigation/TabsCard"
import { ActivityFeed } from "@/components/blocks/feed/ActivityFeed"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Button } from "@/components/atoms/buttons/Button"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH, StackV } from "@/components/frames/Stack"
import type { CallerIdentity } from "@/components/frames/_identity"
import { TrendingContents } from "../TrendingContents"
import type { QueryMyFeedItemData } from "@/modules/api/graphql/queries/types/my-feed"
import type { ReactionType } from "@/modules/api/graphql/queries/types/discussion"

/** Placeholder day groups, and rows per group, the co-located feed skeleton shows. */
const SKELETON_GROUP_COUNT = 2
const SKELETON_ROW_COUNT = 3

/**
 * One placeholder day-group of feed rows — a date label above a joined card of
 * `[avatar · two text lines]` rows. `ActivityFeed` carries no `isSkeleton` of its
 * own, so this hand-mirrors its shape right where it sits, instead of pulling in a
 * separate skeleton tree (loading-and-skeleton.md; `missingSkeletonSupport`).
 */
const FeedSkeletonGroup = () => (
    <StackV gap={3} principle="sibling-stack"
        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
        items={[
            () => <Typography size="xs" color="muted" isSkeleton classNames={["w-1/4"]} />,
            () => (
                <SurfaceListCard>
                    {Array.from({ length: SKELETON_ROW_COUNT }, (_row, index) => (
                        <SurfaceListCardItem key={index}>
                            <StackH gap={2} principle="icon-text"
                                explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
                                align="start" items={[
                                    () => <Skeleton className="size-9 shrink-0 rounded-full" />,
                                    () => (
                                        <StackV gap={1} principle="name-handle"
                                            explain="Display name with handle — not title-subtitle, because the second line is an identity handle rather than a subtitle."
                                            classNames={["min-w-0", "flex-1"]} items={[
                                                () => <Typography size="sm" isSkeleton classNames={["w-3/4"]} />,
                                                () => <Typography size="xs" isSkeleton classNames={["w-1/4"]} />,
                                            ]} />
                                    ),
                                ]} />
                        </SurfaceListCardItem>
                    ))}
                </SurfaceListCard>
            ),
        ]} />
)

/** All display text, already localized by the connected `FeedTabs`; a story passes i18n keys. */
export interface FeedTabsLabels {
    /** Accessible name for the audience scope tab strip ("For you" / "Following"). */
    scopeTabsAria: string
    /** Accessible name for the category filter chip strip. */
    filterTabsAria: string
    /** Empty-branch title when a category filter matched nothing. */
    emptyFilteredTitle: string
    /** Action label that clears the category filter back to "all". */
    emptyFilteredCta: string
    /** Empty-branch title when the whole scope has nothing yet. */
    emptyPlatformTitle: string
    /** Empty-branch description under {@link FeedTabsLabels.emptyPlatformTitle}. */
    emptyPlatformDescription: string
    /** Action label that sends an empty-feed visitor into the course catalog. */
    emptyPlatformCta: string
    /** Error-branch title — shared by the full error branch and the inline load-more retry. */
    errorTitle: string
    /** Retry button label — shared by the error branch and the inline load-more retry. */
    retryLabel: string
    /** "Load more" button label under the feed. */
    loadMoreLabel: string
}

/** Props for {@link _FeedTabs} — presentational; all data resolved, no fetch/store/i18n. */
export interface FeedTabsProps {
    /** First load, nothing in hand → the feed region shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with a resolved page that carries zero items → the empty branch. */
    isEmpty?: boolean
    /** Truthy → the error branch (beats loading + empty). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler — refetches the feed. Paired with `labels.retryLabel`; also drives the inline load-more retry. */
    onRetry?: () => void
    /** `true` while a category filter narrower than "all" is active — picks which empty message shows. */
    isFilteredEmpty?: boolean
    /** Audience-scope tab strip ("For you" / "Following"), already resolved (i18n'd labels). */
    scopeTabs: Array<TabsCardItem>
    /** Currently selected scope tab key. */
    selectedScopeKey: string
    /** Fired with the newly selected scope tab key. */
    onScopeChange: (key: Key) => void
    /** Category filter chip strip, already resolved (i18n'd labels + icons). */
    filterTabs: Array<TabsCardItem>
    /** Currently selected filter chip key. */
    selectedFilterKey: string
    /** Fired with the newly selected filter chip key. */
    onFilterChange: (key: Key) => void
    /** Clears the active category filter back to "all". */
    onResetFilter: () => void
    /** Sends a platform-empty visitor into the course catalog. */
    onBrowseCourses: () => void
    /** The flattened, newest-first feed page. */
    items: Array<QueryMyFeedItemData>
    /** Resolve a global id to a press handler that navigates to the entity, or `undefined` when unroutable. */
    onResolve: (globalId: string | null | undefined) => (() => void) | undefined
    /** React handler forwarded to each feed item. */
    onReact: (activityId: string, type: ReactionType | null) => void
    /** `true` iff the last loaded page still carries a next cursor. */
    hasMore: boolean
    /** `true` while a "load more" page is in flight. */
    isLoadingMore: boolean
    /** Requests the next page. */
    onLoadMore: () => void
    /**
     * `true` → a "load more" page failed while existing items stayed on screen; shows
     * an inline retry instead of falling back to the full error branch.
     */
    hasLoadMoreError?: boolean
    labels: FeedTabsLabels
}

/**
 * Explore feed (ContentBody-style `TabsCard` pattern) — the presentational half of
 * {@link import("./index").FeedTabs}, composed on the tier-correct vocabulary
 * (`TabsCard` / `ActivityFeed` / `SurfaceListCard`). CARD 1 = "Trending this week"
 * (self-fetching, always rendered, self-hides when nothing trends). Below it, a
 * double-tabs toolbar (audience scope left, category filter right) always renders;
 * only the activity stream it governs runs the fixed order error → loading → empty →
 * content: `error` falls to the shared `AsyncContentError` frame, `isEmpty` to
 * `AsyncContentEmpty` (filtered vs platform), and otherwise the feed renders with
 * `isSkeleton` threaded to every leaf that supports it so the shimmer mirrors the
 * loaded shape (loading-and-skeleton.md). See `tiers/split.md` — the connected
 * `index.tsx` owns the fetch, the tab/filter state, and i18n.
 *
 * @param props - {@link FeedTabsProps}
 */
export const _FeedTabs = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    isFilteredEmpty = false,
    scopeTabs,
    selectedScopeKey,
    onScopeChange,
    filterTabs,
    selectedFilterKey,
    onFilterChange,
    onResetFilter,
    onBrowseCourses,
    items,
    onResolve,
    onReact,
    hasMore,
    isLoadingMore,
    onLoadMore,
    hasLoadMoreError = false,
    labels,
}: FeedTabsProps) => {
    const identity: CallerIdentity = { tier: "block", component: "FeedTabs" }

    // Hoisted so outer gap-only / named frames are not scanned as owning nested decisions.
    const feedStreamItems = [
        ...(isSkeleton
            ? Array.from({ length: SKELETON_GROUP_COUNT }, () => () => <FeedSkeletonGroup />)
            : [() => <ActivityFeed items={items} onResolve={onResolve} onReact={onReact} />]),
        ...(!isSkeleton && hasMore ? [() => (
            <StackV gap={3} principle="sibling-stack"
                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                align="center" items={[
                    () => (
                        <Button
                            variant="secondary"
                            size="sm"
                            isPending={isLoadingMore}
                            label={labels.loadMoreLabel}
                            onPress={onLoadMore}
                        />
                    ),
                    ...(hasLoadMoreError && !isLoadingMore ? [() => (
                        <StackH gap={2} principle="icon-text"
                            explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
                            items={[
                                () => <Typography size="xs" color="danger" text={labels.errorTitle} />,
                                () => <Button variant="tertiary" size="sm" label={labels.retryLabel} onPress={onRetry} />,
                            ]} />
                    )] : []),
                ]} />
        )] : []),
    ]

    const tabsZoneItems = [
        () => (
            <TabsCard
                leftTabs={{
                    items: scopeTabs,
                    selectedKey: selectedScopeKey,
                    ariaLabel: labels.scopeTabsAria,
                    onSelectionChange: onScopeChange,
                }}
                rightTabs={{
                    items: filterTabs,
                    selectedKey: selectedFilterKey,
                    ariaLabel: labels.filterTabsAria,
                    onSelectionChange: onFilterChange,
                }}
            />
        ),
        () => {
            // error beats a stale loading flag; empty only once settled
            if (error) {
                return <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retryLabel} />
            }
            if (!isSkeleton && isEmpty) {
                // two distinct reasons need two distinct empties: filtered-empty
                // offers a way back to "all"; platform-empty invites into courses.
                return isFilteredEmpty ? (
                    <AsyncContentEmpty
                        title={labels.emptyFilteredTitle}
                        action={() => (
                            <Button variant="secondary" size="sm" label={labels.emptyFilteredCta} onPress={onResetFilter} />
                        )}
                    />
                ) : (
                    <AsyncContentEmpty
                        title={labels.emptyPlatformTitle}
                        description={labels.emptyPlatformDescription}
                        action={() => (
                            <Button variant="secondary" size="sm" label={labels.emptyPlatformCta} onPress={onBrowseCourses} />
                        )}
                    />
                )
            }

            // the feed lives DIRECTLY in the zone — do NOT wrap it in an outer
            // Card (each day is already a labeled-list-card; an outer Card
            // would nest card-in-card inside the big zone)
            return <StackV gap={6} principle="block-boundary"
                explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                items={feedStreamItems}  />
        },
    ]

    return (
        <StackV gap={6} principle="block-boundary"
            explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
            identity={identity} items={[
            // CARD 1 — "Trending this week": platform-wide trending discovery (own
            // query, NOT scope-dependent) → shown on both scopes; self-hides when
            // nothing trends.
                () => <TrendingContents />,
                // CARD 2 — TabsCard pattern (like the lesson ContentBody): the double-tabs
                // toolbar floats OUTSIDE, above the card; the card holds the activity
                // stream the tabs govern.
                () => (
                    <StackV gap={3} principle="sibling-stack"
                        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                        items={tabsZoneItems}  />
                ),
            ]} />
    )
}

"use client"

import React, {
    useCallback,
    useMemo,
    useState,
} from "react"
import type {
    Key,
} from "react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import {
    BookOpenIcon,
    ListBulletsIcon,
    MedalIcon,
    UsersIcon,
} from "@phosphor-icons/react"
import {
    _FeedTabs,
} from "./component"
import type {
    TabsCardItem,
} from "@/components/blocks/navigation/TabsCard"
import { useQueryMyFeedSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyFeedSwr"
import { useMutateReactActivitySwr } from "@/hooks/swr/api/graphql/mutations/useMutateReactActivitySwr"
import { MyFeedTab, MyFeedCategory } from "@/modules/api/graphql/queries/types/my-feed"
import { queryResolveRoute } from "@/modules/api/graphql/queries/query-resolve-route"
import type { ReactionType } from "@/modules/api/graphql/queries/types/discussion"

/**
 * Explore feed (ContentBody-style `TabsCard` pattern) — the CONNECTED half: fetches
 * the cursor-paginated feed (SWR), holds the audience-scope + category-filter state,
 * reacts to activities, resolves entity routes, and resolves every label via `t()`,
 * handing them to the presentational {@link _FeedTabs}. See `tiers/split.md`.
 */
export const FeedTabs = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const [tab, setTab] = useState<MyFeedTab>(MyFeedTab.ForYou)
    /** Active filter chip — narrows the feed to a slice of activity types. */
    const [category, setCategory] = useState<MyFeedCategory>(MyFeedCategory.All)

    // cursor-paginated feed for the active scope + filter (array of pages)
    const {
        data: pages,
        size,
        setSize,
        isLoading,
        isValidating,
        error,
        mutate,
    } = useQueryMyFeedSwr(tab, category)
    const { trigger: reactActivity } = useMutateReactActivitySwr()

    /** React to a feed activity, then revalidate so counts/my-reaction refresh. */
    const onReact = useCallback(
        async (activityId: string, type: ReactionType | null) => {
            await reactActivity({ activityId, type })
            await mutate()
        },
        [
            reactActivity,
            mutate,
        ],
    )

    /** Audience-scope tabs (left group). */
    const scopeTabs = useMemo<Array<TabsCardItem>>(
        () => [
            { key: MyFeedTab.ForYou, label: t("DashboardPage.tabs.forYou") },
            { key: MyFeedTab.Following, label: t("DashboardPage.tabs.following") },
        ],
        [t],
    )

    /** Single-select category filter chips (right group), shown under the scope tabs. */
    const filterTabs = useMemo<Array<TabsCardItem>>(
        () => [
            { key: MyFeedCategory.All, label: t("DashboardPage.feedFilter.all"), Icon: ListBulletsIcon },
            { key: MyFeedCategory.Courses, label: t("DashboardPage.feedFilter.courses"), Icon: BookOpenIcon },
            { key: MyFeedCategory.Achievements, label: t("DashboardPage.feedFilter.achievements"), Icon: MedalIcon },
            { key: MyFeedCategory.People, label: t("DashboardPage.feedFilter.people"), Icon: UsersIcon },
        ].map(({ key, label, Icon }) => ({
            key,
            label,
            icon: <Icon aria-hidden focusable="false" className="size-5 shrink-0" />,
        })),
        [t],
    )

    // flatten pages → one newest-first list
    const items = useMemo(
        () => (pages ?? []).flatMap((page) => page.items),
        [pages],
    )
    const hasMore = Boolean(pages?.[pages.length - 1]?.nextCursor)
    const isLoadingMore = isValidating && (pages?.length ?? 0) < size

    /** Resolve an entity's route via the index, then navigate (no-op if unroutable). */
    const onResolve = useCallback(
        (globalId: string | null | undefined): (() => void) | undefined => {
            if (!globalId) {
                return undefined
            }
            return () => {
                void (async () => {
                    const response = await queryResolveRoute({ request: { globalId } })
                    const path = response.data?.resolveRoute?.data?.path
                    if (path) {
                        router.push(`/${locale}${path}`)
                    }
                })()
            }
        },
        [
            locale,
            router,
        ],
    )

    return (
        <_FeedTabs
            // first load, nothing in hand → shimmer; settled (data OR error) stops it (loading-and-skeleton.md)
            isSkeleton={isLoading && items.length === 0}
            // error beats loading + empty; only a settled fetch error (nothing in hand) reaches the block
            error={items.length === 0 ? error : undefined}
            onRetry={() => { void mutate() }}
            // settled with a resolved page that carries zero items
            isEmpty={items.length === 0}
            isFilteredEmpty={category !== MyFeedCategory.All}
            scopeTabs={scopeTabs}
            selectedScopeKey={tab}
            onScopeChange={(key: Key) => setTab(key as MyFeedTab)}
            filterTabs={filterTabs}
            selectedFilterKey={category}
            onFilterChange={(key: Key) => setCategory(key as MyFeedCategory)}
            onResetFilter={() => setCategory(MyFeedCategory.All)}
            onBrowseCourses={() => router.push(`/${locale}/courses`)}
            items={items}
            onResolve={onResolve}
            onReact={onReact}
            hasMore={hasMore}
            isLoadingMore={isLoadingMore}
            onLoadMore={() => setSize(size + 1)}
            // load-more failure (page 2+) doesn't clear existing items — the presentational
            // half shows an inline retry instead of falling back to the full error branch
            hasLoadMoreError={Boolean(error) && items.length > 0}
            labels={{
                scopeTabsAria: t("DashboardPage.feedTabsAria"),
                filterTabsAria: t("DashboardPage.feedFilterAria"),
                emptyFilteredTitle: t("DashboardPage.feedEmptyFiltered.title"),
                emptyFilteredCta: t("DashboardPage.feedEmptyFiltered.cta"),
                emptyPlatformTitle: t("DashboardPage.feedEmptyPlatform.title"),
                emptyPlatformDescription: t("DashboardPage.feedEmptyPlatform.description"),
                emptyPlatformCta: t("DashboardPage.feedEmptyPlatform.cta"),
                errorTitle: t("DashboardPage.feedError"),
                retryLabel: t("DashboardPage.feedRetry"),
                loadMoreLabel: t("DashboardPage.loadMore"),
            }}
        />
    )
}

import React from "react"
import { CardsIcon as LayersIcon } from "@phosphor-icons/react"
import { Button } from "@/components/atoms/buttons/Button"
import { Typography } from "@/components/atoms/text/Typography"
import type { SkeletonProps } from "@/components/frames/_slot"
import { Box } from "@/components/frames/Box"
import { Split } from "@/components/frames/Split"

/** Already-localized text for {@link _FlashcardReview}; the connected `FlashcardReview` interpolates `dueCount`. */
export interface FlashcardReviewLabels {
    /** "N flashcards due today" row label. */
    due: string
    /** CTA button label, e.g. "Review 3". */
    startWithCount: string
}

/** Props for {@link _FlashcardReview} — presentational; all data resolved, no fetch/store/i18n. */
export interface FlashcardReviewProps {
    /** First load, nothing in hand → the row shimmers in place (co-located). Owned by the connected `FlashcardReview`. */
    isSkeleton?: boolean
    /**
     * Settled with nothing to nudge about — zero cards due, or the fetch failed — so
     * the widget self-hides. The two are folded together deliberately: this SECONDARY
     * widget has no error message of its own, the same self-hide contract the old
     * `AsyncContent` had whenever `errorContent`/`emptyContent` were left unpassed.
     */
    isEmpty?: boolean
    /** Navigates into the dedicated review page. */
    onStartReview?: () => void
    labels: FlashcardReviewLabels
}

/**
 * Centre-column "flashcards due today" nudge — the presentational half of
 * {@link FlashcardReview}. Renders ONE row (icon + due-count label <-> "start
 * review" CTA), with `isSkeleton` threaded to both sides of the {@link Split}
 * so the shimmer mirrors the loaded shape (loading-and-skeleton.md).
 * Settled-and-empty (or a failed fetch) self-hides instead of showing a
 * message — this is a SECONDARY nudge, not a region with its own empty/error
 * voice. See `tiers/split.md` — the connected `FlashcardReview` owns the fetch
 * and resolves i18n.
 *
 * @param props - {@link FlashcardReviewProps}
 */
export const _FlashcardReview = ({
    isSkeleton = false,
    isEmpty = false,
    onStartReview,
    labels,
}: FlashcardReviewProps) => {
    // settled (not skeleton) + nothing to show → self-hide (no error/empty voice for this nudge)
    if (!isSkeleton && isEmpty) {
        return null
    }
    return (
        <Box principle="cell-pad" className="p-3"
            explain="Tight cell inset — not card-padding, because this sits inside a dense table or list cell rather than a card body."
            identity={{ tier: "block", component: "FlashcardReview" }}>
            <Split
                gap={3}
                isSkeleton={isSkeleton}
                start={({ isSkeleton }: SkeletonProps) => (
                    <Typography
                        size="sm"
                        weight="medium"
                        prefixIcon={LayersIcon}
                        truncate
                        text={labels.due}
                        isSkeleton={isSkeleton}
                    />
                )}
                end={({ isSkeleton }: SkeletonProps) => (
                    <Button
                        variant="primary"
                        size="sm"
                        label={labels.startWithCount}
                        onPress={onStartReview}
                        isSkeleton={isSkeleton}
                    />
                )}
            />
        </Box>
    )
}

"use client"

import React from "react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import {
    pathConfig,
} from "@/resources/path"
import { useQueryMyDueFlashcardsSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyDueFlashcardsSwr"
import { _FlashcardReview } from "./component"

/**
 * Centre-column "flashcards due today" nudge — the CONNECTED half. Surfaces
 * the SM-2 spaced-repetition backlog (`dueCount`) right on the home surface
 * with a primary CTA into the dedicated review page. Self-fetches its own
 * leaf query, resolves every label, and hands them to the presentational
 * {@link _FlashcardReview}. See `tiers/split.md`.
 */
export const FlashcardReview = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const { data, error, isLoading } = useQueryMyDueFlashcardsSwr()

    const dueCount = data?.dueCount ?? 0

    return (
        <_FlashcardReview
            // first load, nothing in hand → shimmer; settled (data OR error) stops it (loading-and-skeleton.md)
            isSkeleton={isLoading && !data}
            // SECONDARY widget, no error voice of its own: nothing due, still loading (no
            // cache), or the fetch failed → self-hide (same condition the old `AsyncContent`
            // `isEmpty` folded `error` into, since no `errorContent` was ever passed).
            isEmpty={!!error || !data || dueCount === 0}
            onStartReview={() => router.push(
                pathConfig().locale(locale).review().build(),
            )}
            labels={{
                due: t("flashcardReview.due", { count: dueCount }),
                startWithCount: t("flashcardReview.startWithCount", { count: dueCount }),
            }}
        />
    )
}

"use client"

import React, {
    useCallback,
    useMemo,
} from "react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import {
    pathConfig,
} from "@/resources/path"
import { useAppSelector } from "@/redux/hooks"
import { RankDeltaCaret } from "@/components/blocks/profile/RankDeltaCaret"
import {
    LeaderboardListCard,
    LeaderboardRow,
} from "@/components/blocks/dashboard/LeaderboardListCard"
import type { QueryMyLeagueData } from "@/modules/api/graphql/queries/types/league"

/** How many top-of-cohort rows to show before truncating (no inner scroll). */
const TOP_ROWS = 5

/** Props for {@link LeagueCardContent}. */
export interface LeagueCardContentProps {
    /** The resolved (non-null) weekly-league standing — supplied by the container. */
    data: QueryMyLeagueData
    /** Kept for API compatibility with the container; the card is always framed now. */
    framed?: boolean
}

/**
 * DashboardPage "Weekly League" card — maps the resolved weekly-league data into the shared
 * {@link LeaderboardListCard} (standing header with a rank-driven medal/cup badge, then
 * the top cohort as a medal-ranked list with a rank-movement caret per row). Renders
 * identically to the global {@link import("../../TopLearners").TopLearners} card; only
 * the trailing slot (caret vs follow) differs (instructor's call, 2026-07-17, "two identical sections").
 *
 * @param props - {@link LeagueCardContentProps}
 */
export const LeagueCardContent = ({
    data}: LeagueCardContentProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const me = useAppSelector((state) => state.user.user)

    /** Open the full leaderboard/league page (see-more link in the card header). */
    const onSeeMore = useCallback(
        () => router.push(pathConfig().locale(locale).league().build()),
        [router, locale],
    )

    /** Hours/days left until the weekly reset (computed from `weekEndAt`). */
    const countdown = useMemo(
        () => {
            const remaining = Math.max(0, new Date(data.weekEndAt).getTime() - Date.now())
            return {
                days: Math.floor(remaining / 86_400_000),
                hours: Math.floor((remaining % 86_400_000) / 3_600_000),
            }
        },
        [data],
    )

    const total = data.entries.length
    const isMine = (username: string | null) => Boolean(me?.username) && username === me?.username

    const myEntry = me?.username
        ? data.entries.find((entry) => entry.username === me.username)
        : undefined
    const myPercent = myEntry ? Math.max(1, Math.ceil((myEntry.rank / total) * 100)) : null

    // top slice INCLUDING the viewer in place; a pinned self-row follows when the
    // viewer sits below it.
    const topRows = data.entries.slice(0, TOP_ROWS)
    const viewerInTop = myEntry
        ? topRows.some((entry) => entry.userGlobalId === myEntry.userGlobalId)
        : true
    const showSelfRow = Boolean(myEntry) && !viewerInTop
    const hiddenBetween = showSelfRow && myEntry
        ? Math.max(0, myEntry.rank - topRows.length - 1)
        : 0

    /** Map a cohort entry → a normalised {@link LeaderboardRow} (caret trailing + movement band). */
    const toRow = (entry: typeof data.entries[number]): LeaderboardRow => {
        // band = weekly rank MOVEMENT (mirrors the ▴▾ `RankDeltaCaret`), NOT the cohort
        // promote/demote zone — a per-row signal that ALWAYS shows (no cohort-size gate,
        // so a small seed cohort still renders it): climbed → success, dropped → danger,
        // unchanged / no last-week baseline → no band (instructor's call, 2026-07-17: the DashboardPage
        // preview always shows it; unlike the /league page, which uses the promote/demote zone instead).
        const delta = entry.rankDelta ?? 0
        return {
            key: entry.userGlobalId,
            rank: entry.rank,
            username: entry.username,
            avatar: entry.avatar,
            valueLabel: t("DashboardPage.league.points", { count: entry.weekPoints }),
            isMe: isMine(entry.username),
            profileHref: pathConfig().locale(locale).profile(entry.username ?? undefined).build(),
            trailing: <RankDeltaCaret delta={entry.rankDelta} className="w-8 justify-end" />,
            verdict: delta !== 0
                ? { enable: true, variant: delta > 0 ? "success" : "danger" }
                : undefined,
        }
    }

    return (
        <LeaderboardListCard
            title={t("DashboardPage.league.title")}
            onSeeMore={onSeeMore}
            seeMoreLabel={t("DashboardPage.league.seeMore")}
            standing={myEntry && myPercent !== null ? {
                rank: myEntry.rank,
                primary: t("DashboardPage.myProfile.rankLine", {
                    rank: myEntry.rank,
                    percent: myPercent,
                }),
                secondary: (
                    <>
                        {t("DashboardPage.league.points", { count: myEntry.weekPoints })}
                        {` · ${t("DashboardPage.league.resetIn", {
                            days: countdown.days,
                            hours: countdown.hours,
                        })}`}
                    </>
                ),
            } : undefined}
            rows={topRows.map(toRow)}
            selfRow={showSelfRow && myEntry ? toRow(myEntry) : undefined}
            ellipsisLabel={hiddenBetween > 0
                ? t("DashboardPage.league.othersCount", { count: hiddenBetween })
                : undefined}
            meLabel={t("DashboardPage.league.you")}
        />
    )
}

"use client"

import React from "react"
import { AsyncContentEmpty } from "@/components/composites/async/AsyncContent"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import {
    SurfaceListCard,
    SurfaceListCardItem,
} from "@/components/blocks/cards/SurfaceListCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import {
    LeaderboardListCard,
    type LeaderboardRow,
    type LeaderboardStanding,
} from "@/components/blocks/dashboard/LeaderboardListCard"
import { RankDeltaCaret } from "@/components/blocks/profile/RankDeltaCaret"
import { StackH, StackV } from "@/components/frames/Stack"
import type {
    WithClassNames,
} from "@/modules/types/base/class-name"

/** Number of placeholder cohort rows the co-located skeleton shows (mirrors the capped top rows). */
const SKELETON_ROWS = 5

/**
 * One resolved cohort entry, already mapped + translated by the connected {@link
 * import("./index").LeagueCard} — the presentational half turns it into a {@link LeaderboardRow}.
 */
export interface LeagueCardEntry {
    /** React key + stable id. */
    userGlobalId: string
    /** 1-based rank — ≤3 renders a place medal, else the number. */
    rank: number
    /** Display username (null → dash). */
    username: string | null
    /** Avatar URL (null → generated fallback). */
    avatar?: string | null
    /** Rank movement vs last week (mirrors the ▴▾ {@link RankDeltaCaret}). */
    rankDelta: number | null
    /** True → highlight as the viewer (accent name + `meLabel` suffix). */
    isMe: boolean
    /** Profile link target. */
    profileHref: string
    /** Already-translated "N pts" label for this entry. */
    pointsLabel: string
}

/** Props for {@link _LeagueCard} — presentational; all data/text resolved, no fetch/store/i18n. */
export interface LeagueCardProps extends WithClassNames<undefined> {
    /** First load, nothing in hand → the whole tree shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with no cohort placement → the empty message. */
    isEmpty?: boolean
    /**
     * Kept for API compatibility with the container; the card is always framed
     * (a `LabeledCard`, via {@link LeaderboardListCard}) now.
     */
    framed?: boolean
    /** League title (already translated). */
    title: string
    /**
     * Help text for the title's tooltip (already translated) — currently unused: the
     * label row has no slot for a decoration once `label` became plain text. Kept for
     * API compatibility until a real "labelAdornment" slot exists.
     */
    titleHelp: string
    /** "See more" handler (opens the full board). */
    onSeeMore?: () => void
    /** "See more" label (already translated). */
    seeMoreLabel?: string
    /** The viewer's own standing header line (omit when they have no rank). Text pre-resolved. */
    standing?: LeaderboardStanding
    /** Top-of-cohort entries (already sliced by the container). */
    entries?: Array<LeagueCardEntry>
    /** Pinned self-row when the viewer sits below the shown slice. */
    selfEntry?: LeagueCardEntry
    /** Ellipsis label above the pinned self-row (already translated). */
    ellipsisLabel?: string
    /** "You" suffix appended to the viewer's own row name (already translated). */
    meLabel?: string
    /** Empty-state title (already translated). */
    emptyTitle: string
    /** Empty-state description (already translated). */
    emptyDescription: string
}

/** Map one resolved {@link LeagueCardEntry} → a {@link LeaderboardRow} (caret trailing + movement band). */
const toRow = (entry: LeagueCardEntry): LeaderboardRow => ({
    key: entry.userGlobalId,
    rank: entry.rank,
    username: entry.username,
    avatar: entry.avatar,
    valueLabel: entry.pointsLabel,
    isMe: entry.isMe,
    profileHref: entry.profileHref,
    trailing: <RankDeltaCaret delta={entry.rankDelta} className="w-8 justify-end" />,
    verdict: entry.rankDelta
        ? { enable: true, variant: entry.rankDelta > 0 ? "success" : "danger" }
        : undefined,
})

/**
 * DashboardPage "Weekly League" card — the presentational half of {@link import("./index").LeagueCard}.
 * Renders identically to the global {@link import("../TopLearners").TopLearners} card through the
 * shared {@link LeaderboardListCard}; only the trailing slot (caret vs follow) differs (instructor's
 * call, 2026-07-17, "two identical sections").
 *
 * {@link LeaderboardListCard} takes no `isSkeleton` of its own (it owns the label + standing header
 * + row list as one opaque block), so the LOADING branch mirrors its exact structure by hand, right
 * at this call site — the same `LabeledCard` label, standing header, and bordered `SurfaceListCard`
 * rows, with `Skeleton.*` swapped in for every content node (`loading-and-skeleton.md` §3/§6). This
 * is co-located (one file, one call site), not a separate skeleton component to keep in sync.
 *
 * @param props - {@link LeagueCardProps}
 */
export const _LeagueCard = ({
    isSkeleton = false,
    isEmpty = false,
    title,
    onSeeMore,
    seeMoreLabel,
    standing,
    entries = [],
    selfEntry,
    ellipsisLabel,
    meLabel,
    emptyTitle,
    emptyDescription,
}: LeagueCardProps) => {
    // settled with no cohort placement (BLOCK-8) → translated empty state (join hint), not self-hide
    if (!isSkeleton && isEmpty) {
        return <AsyncContentEmpty title={emptyTitle} description={emptyDescription} />
    }

    if (isSkeleton) {
        return (
            <LabeledCard

                // `label` is plain text now (never a built element), and `title` is already
                // known statically (translated up front, not fetched) — showing it for real
                // instead of shimmering it is strictly more correct, not just a workaround.
                label={title}
            >
                <StackV
                    gap={3}
                    principle="sibling-stack"
                    explain="Skeleton standing header and cohort rows are peer sections in one league card — not block-boundary."
                    items={[
                        () => (
                            <StackH gap={4} principle="content-row"
                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                align="center" items={[
                                    () => <Skeleton className="size-12 shrink-0 rounded-xl" />,
                                    () => (
                                        <StackV gap={2} principle="title-subtitle"
                                            explain="Title over supporting line — not label-field, because neither line is a form control label."
                                            classNames={["min-w-0", "flex-1"]} items={[
                                                () => <Skeleton.Typography type="body-sm" width="1/2" />,
                                                () => <Skeleton.Typography type="body-xs" width="1/3" />,
                                            ]} />
                                    ),
                                ]} />
                        ),
                        () => (
                            <SurfaceListCard bordered>
                                {Array.from({ length: SKELETON_ROWS }, (_row, index) => (
                                    <SurfaceListCardItem key={index}>
                                        <StackH gap={4} principle="content-row"
                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                            align="center" items={[
                                                () => <Skeleton className="h-3 w-6 shrink-0 rounded-sm" />,
                                                () => <Skeleton.Avatar size="sm" />,
                                                () => <Skeleton.Typography type="body-sm" width="1/2" className="min-w-0 flex-1" />,
                                                () => <Skeleton className="h-3 w-10 shrink-0 rounded-sm" />,
                                                () => <Skeleton className="h-4 w-8 shrink-0 rounded-sm" />,
                                            ]} />
                                    </SurfaceListCardItem>
                                ))}
                            </SurfaceListCard>
                        ),
                    ]}
                />
            </LabeledCard>
        )
    }

    return (
        <LeaderboardListCard

            // `title` forwards into `LabeledCard.label`, plain text now (never a built
            // element) — the `InfoTooltip` decoration has no slot to ride any more
            // (mirrors the same drop in `LeagueCardContent`); `titleHelp` is unused here
            // pending a real "labelAdornment"-style slot on `LabeledCard`.
            title={title}
            onSeeMore={onSeeMore}
            seeMoreLabel={seeMoreLabel}
            standing={standing}
            rows={entries.map(toRow)}
            selfRow={selfEntry ? toRow(selfEntry) : undefined}
            ellipsisLabel={ellipsisLabel}
            meLabel={meLabel}
        />
    )
}

"use client"

import React, { useCallback, useMemo } from "react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import {
    pathConfig,
} from "@/resources/path"
import { useAppSelector } from "@/redux/hooks"
import { useQueryMyLeagueSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyLeagueSwr"
import type { QueryMyLeagueEntryData } from "@/modules/api/graphql/queries/types/league"
import {
    _LeagueCard,
    type LeagueCardEntry,
} from "./component"

/** How many top-of-cohort rows to show before truncating (no inner scroll). */
const TOP_ROWS = 5

/** Props for {@link LeagueCard}. */
export interface LeagueCardProps {
    /**
     * When true, render the league inside a `LabeledCard` (title as a Label OUTSIDE
     * the card) instead of the flat inline heading — used on the DashboardPage Community
     * tab so it matches the other LabeledCard sections. Defaults to the flat layout
     * (the standalone /league page). Kept for API compatibility with `_LeagueCard`;
     * the card is always framed now.
     */
    framed?: boolean
}

/** Resolve one query entry into the display-ready {@link LeagueCardEntry} the presentational half renders. */
const toEntry = (
    entry: QueryMyLeagueEntryData,
    locale: string,
    meUsername: string | undefined,
    pointsLabel: string,
): LeagueCardEntry => ({
    userGlobalId: entry.userGlobalId,
    rank: entry.rank,
    username: entry.username,
    avatar: entry.avatar,
    rankDelta: entry.rankDelta,
    isMe: Boolean(meUsername) && entry.username === meUsername,
    profileHref: pathConfig().locale(locale).profile(entry.username ?? undefined).build(),
    pointsLabel,
})

/**
 * Compact weekly-league card for the DashboardPage — the CONNECTED half: self-fetches the
 * league leaf query, computes the async decisions and every derived value (standing,
 * top rows, the pinned self-row), resolves all i18n, and hands them to the
 * presentational {@link _LeagueCard}. `isSkeleton` uses the nullish form so the shimmer
 * holds until data actually arrives (and never on a falsy-but-valid value). See
 * `tiers/split.md`.
 * @param props - {@link LeagueCardProps}
 */
export const LeagueCard = ({
    framed = false}: LeagueCardProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const me = useAppSelector((state) => state.user.user)
    const { data, isLoading } = useQueryMyLeagueSwr()

    // first load, nothing in hand → shimmer (same condition the pre-split `AsyncContent` used)
    const isSkeleton = data === null || data === undefined || isLoading
    // not yet placed in a cohort → translated empty state (join hint), not self-hide
    const isEmpty = data === null || data === undefined || data.entries.length === 0

    /** Open the full leaderboard/league page (see-more link in the card header). */
    const onSeeMore = useCallback(
        () => router.push(pathConfig().locale(locale).league().build()),
        [router, locale],
    )

    const total = data?.entries.length ?? 0
    const myEntry = data && me?.username
        ? data.entries.find((entry) => entry.username === me.username)
        : undefined
    const myPercent = myEntry ? Math.max(1, Math.ceil((myEntry.rank / total) * 100)) : null

    // top slice INCLUDING the viewer in place; a pinned self-row follows when the
    // viewer sits below it.
    const topRows = data ? data.entries.slice(0, TOP_ROWS) : []
    const viewerInTop = myEntry
        ? topRows.some((entry) => entry.userGlobalId === myEntry.userGlobalId)
        : true
    const showSelfRow = Boolean(myEntry) && !viewerInTop
    const hiddenBetween = showSelfRow && myEntry
        ? Math.max(0, myEntry.rank - topRows.length - 1)
        : 0

    /** Hours/days left until the weekly reset (computed from `weekEndAt`). */
    const countdown = useMemo(
        () => {
            if (!data) {
                return { days: 0, hours: 0 }
            }
            const remaining = Math.max(0, new Date(data.weekEndAt).getTime() - Date.now())
            return {
                days: Math.floor(remaining / 86_400_000),
                hours: Math.floor((remaining % 86_400_000) / 3_600_000),
            }
        },
        [data],
    )

    /** "N pts" label for one entry's weekly points, already translated. */
    const pointsLabel = useCallback(
        (weekPoints: number) => t("DashboardPage.league.points", { count: weekPoints }),
        [t],
    )

    return (
        <_LeagueCard
            framed={framed}
            isSkeleton={isSkeleton}
            isEmpty={isEmpty}
            title={t("DashboardPage.league.title")}
            titleHelp={t("DashboardPage.league.help")}
            onSeeMore={onSeeMore}
            seeMoreLabel={t("DashboardPage.league.seeMore")}
            standing={myEntry && myPercent !== null ? {
                rank: myEntry.rank,
                primary: t("DashboardPage.myProfile.rankLine", {
                    rank: myEntry.rank,
                    percent: myPercent,
                }),
                secondary: `${pointsLabel(myEntry.weekPoints)} · ${t("DashboardPage.league.resetIn", {
                    days: countdown.days,
                    hours: countdown.hours,
                })}`,
            } : undefined}
            entries={topRows.map((entry) => toEntry(entry, locale, me?.username, pointsLabel(entry.weekPoints)))}
            selfEntry={showSelfRow && myEntry ? toEntry(myEntry, locale, me?.username, pointsLabel(myEntry.weekPoints)) : undefined}
            ellipsisLabel={hiddenBetween > 0
                ? t("DashboardPage.league.othersCount", { count: hiddenBetween })
                : undefined}
            meLabel={t("DashboardPage.league.you")}
            emptyTitle={t("DashboardPage.league.emptyTitle")}
            emptyDescription={t("DashboardPage.league.emptyDescription")}
        />
    )
}

export default LeagueCard

"use client"

import React from "react"
import {
    Icon,
} from "@iconify/react"
import {
    BadgeImage,
} from "@/components/blocks/identity/BadgeImage"
import { StackH } from "@/components/frames/Stack"

/**
 * Weekly-league tiers, lowest → highest. Mirrors the backend `LeagueTier` enum.
 * Names are picked so each maps to a *distinct, multicolor* `fluent-emoji-flat`
 * icon (medals → medal → gem → trophy → crown), escalating prestige.
 */
export enum LeagueTier {
    /** Entry tier. */
    Bronze = "bronze",
    /** Second tier. */
    Silver = "silver",
    /** Third tier. */
    Gold = "gold",
    /** Fourth tier. */
    Platinum = "platinum",
    /** Fifth tier. */
    Diamond = "diamond",
    /** Sixth tier. */
    Champion = "champion",
    /** Top tier. */
    Legend = "legend",
}

/**
 * Per-tier `fluent-emoji-flat` icon name (multicolor, no recolor needed) +
 * display label. The Iconify set ships gold/silver/bronze medals natively, so the
 * tier ladder reads as real metal/gem/crown art instead of one recolored shape.
 */
interface TierVisual {
    /** Iconify icon id (`fluent-emoji-flat:*`). */
    icon: string
    /** Human label shown next to the badge. */
    label: string
}

/** Tier → icon + label map. */
const TIER_VISUAL: Record<LeagueTier, TierVisual> = {
    [LeagueTier.Bronze]: {
        icon: "fluent-emoji-flat:3rd-place-medal",
        label: "Bronze",
    },
    [LeagueTier.Silver]: {
        icon: "fluent-emoji-flat:2nd-place-medal",
        label: "Silver",
    },
    [LeagueTier.Gold]: {
        icon: "fluent-emoji-flat:1st-place-medal",
        label: "Gold",
    },
    [LeagueTier.Platinum]: {
        icon: "fluent-emoji-flat:sports-medal",
        label: "Platinum",
    },
    [LeagueTier.Diamond]: {
        icon: "fluent-emoji-flat:gem-stone",
        label: "Diamond",
    },
    [LeagueTier.Champion]: {
        icon: "fluent-emoji-flat:trophy",
        label: "Champion",
    },
    [LeagueTier.Legend]: {
        icon: "fluent-emoji-flat:crown",
        label: "Legend",
    },
}

/** Props for {@link LeagueTierBadge}. */
export interface LeagueTierBadgeProps {
    /** Which tier to render. */
    tier: LeagueTier
    /** Icon size in px (default 24). */
    size?: number
    /** Show the tier name next to the icon. */
    showLabel?: boolean
}

/**
 * Renders a weekly-league tier as its multicolor `fluent-emoji-flat` badge,
 * optionally with the tier name. Pure presentational — drives off {@link LeagueTier}.
 * @param props - {@link LeagueTierBadgeProps}
 */
export const LeagueTierBadge = ({
    tier,
    size = 24,
    showLabel = false}: LeagueTierBadgeProps) => {
    // resolve the icon + label for this tier
    const visual = TIER_VISUAL[tier]
    return (
        <div className={"shrink-0"}>
            <StackH
                principle="identity"
                explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                items={[
                    () => (
                        // real art from MinIO (badges/league/<tier>.png) once uploaded; until
                        // then fall back to the multicolor fluent-emoji placeholder
                        <BadgeImage
                            objectKey={`badges/league/${tier}.png`}
                            size={size}
                            alt={visual.label}
                            fallback={(
                                <Icon
                                    icon={visual.icon}
                                    width={size}
                                    height={size}
                                    aria-label={visual.label}
                                />
                            )}
                        />
                    ),
                    ...(showLabel ? [() => (
                        <span className="text-sm font-medium text-foreground">
                            {visual.label}
                        </span>
                    )] : []),
                ]}
            />
        </div>
    )
}

import React from "react"
import { ArrowRightIcon, ChartLineUpIcon } from "@phosphor-icons/react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"
import { StatPair } from "@/components/composites/stats/StatPair"
import { Button } from "@/components/atoms/buttons/Button"
import { Chip, type ChipTone } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH, StackV } from "@/components/frames/Stack"
import type { UserJobReadinessBand } from "@/modules/api/graphql/queries/types/user-job-readiness"

/** Readiness band -> the `Chip` tone that reads correctly. */
const BAND_CHIP_TONE: Record<UserJobReadinessBand, ChipTone> = {
    needsWork: "default",
    building: "warning",
    jobReady: "success",
}

/** All display text, already localized by the connected `JobReadinessWidget`; a story passes i18n keys. */
export interface JobReadinessWidgetLabels {
    /** Error-branch title. */
    errorTitle: string
    /** Error-branch retry button label. */
    retry: string
    /** Empty-branch title — no purchased-course track has a snapshot yet. */
    emptyTitle: string
    /** Empty-branch supporting line. */
    emptyDescription: string
    /** "Capstone project" pillar-meter label. */
    trackCapstone: string
    /** "Mock interview" pillar-meter label. */
    trackInterview: string
    /** "CV" pillar-meter label. */
    trackCv: string
}

/** Props for {@link _JobReadinessWidget} — presentational; all data resolved, no fetch/store/i18n. */
export interface JobReadinessWidgetProps {
    /** First load, nothing in hand → the whole widget shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with no strongest track (no purchased course has a snapshot yet) → the empty message. */
    isEmpty?: boolean
    /** Truthy → the error message (beats loading + empty). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler — paired with `labels.retry` to show a retry button on the error branch. */
    onRetry?: () => void
    /** Strongest track's course title (its own depth card, never blended with other tracks). */
    courseTitle?: string
    /** Strongest track's own depth score (0–100). */
    depthScore?: number
    /** Strongest track's readiness band — drives the chip's tone. */
    band?: UserJobReadinessBand
    /** Already-translated band label (e.g. "Building"), paired with {@link band}. */
    bandLabel?: string
    /** Already-translated + interpolated foundation-percentile sentence. `undefined` → the row is skipped (course has no ranked percentile yet). */
    foundationPercentileText?: string
    /** Strongest track's capstone score, or `null` when not attempted (row omitted once settled). */
    capstoneScore?: number | null
    /** Strongest track's mock-interview score, or `null` when not attempted (row omitted once settled). */
    interviewScore?: number | null
    /** Strongest track's CV-review score, or `null` when not attempted (row omitted once settled). */
    cvScore?: number | null
    /** Fired when the single CTA is pressed — jumps to whichever pillar is still missing. */
    onCtaPress?: () => void
    /** Already-translated CTA label, paired with {@link onCtaPress}. `undefined` → every pillar is already attempted, no CTA renders. */
    ctaLabel?: string
    /** Every display string, already resolved by the connected file. */
    labels: JobReadinessWidgetLabels
}

/**
 * DashboardPage "My job readiness" self-widget — the presentational half of
 * {@link import("./index").JobReadinessWidget}: the growth-loop nudge for the
 * viewer's OWN job-readiness snapshot — a headline (strongest track's depth +
 * band, plus the global foundation percentile), its capstone/interview/CV
 * pillar bars (each rendered only when attempted), and a single CTA aimed at
 * whichever pillar is still missing (capstone → mock interview → CV).
 *
 * Deliberately never suggests buying another course to raise a score (see
 * `.workflows/00-INDEX.md` fairness model + WF-06 copy discipline) — the CTA
 * only ever points at completing real work on the track the learner already
 * owns. Content only — the parent `LabeledCard` supplies the frame.
 *
 * Three states in the fixed order error → loading → empty → content
 * (BLOCK-8): `error` falls to the shared `AsyncContentError` frame, `isEmpty`
 * to `AsyncContentEmpty`, and otherwise the one tree renders with
 * `isSkeleton` threaded to every leaf so the shimmer mirrors the loaded shape
 * (loading-and-skeleton.md). See `tiers/split.md` — the connected
 * `index.tsx` owns the fetch and i18n.
 *
 * @param props - {@link JobReadinessWidgetProps}
 */
export const _JobReadinessWidget = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    courseTitle,
    depthScore,
    band,
    bandLabel,
    foundationPercentileText,
    capstoneScore = null,
    interviewScore = null,
    cvScore = null,
    onCtaPress,
    ctaLabel,
    labels,
}: JobReadinessWidgetProps) => {
    // error beats a stale loading flag; empty only once settled (BLOCK-8) — the empty and error
    // surfaces are the shared `AsyncContent*` frames, not hand-written JSX (loading-and-skeleton.md §6).
    if (error) {
        return <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retry} />
    }
    if (!isSkeleton && isEmpty) {
        return <AsyncContentEmpty icon={ChartLineUpIcon} title={labels.emptyTitle} description={labels.emptyDescription} />
    }

    // Each row is a DATA condition — a pillar with no score, or a foundation percentile that was
    // never ranked, is omitted rather than zero-filled — except while shimmering, when every row
    // renders as a placeholder (same row component, same count shape, loading-and-skeleton.md §1).
    const showFoundation = isSkeleton || foundationPercentileText !== undefined
    const showCapstone = isSkeleton || capstoneScore !== null
    const showInterview = isSkeleton || interviewScore !== null
    const showCv = isSkeleton || cvScore !== null
    const showCta = isSkeleton || (onCtaPress !== undefined && ctaLabel !== undefined)

    // Hoisted so the outer gap={4} column is gap-only (no nested `at` false-positive).
    // Step 4 vertical peers (score row · meters · CTA) have no fitting token — see ledger.
    const widgetItems = [
        () => (
            <StackH gap={4} principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                at="sm" items={[
                    () => (isSkeleton
                        ? <StatPair isSkeleton />
                        : <StatPair value={String(depthScore ?? 0)} label={courseTitle ?? ""} />),
                    () => (isSkeleton
                        ? <Chip isSkeleton />
                        : <Chip tone={band ? BAND_CHIP_TONE[band] : "default"} text={bandLabel ?? ""} />),
                ]} />
        ),
        ...(showFoundation ? [() => (
            <Typography size="xs" color="muted" isSkeleton={isSkeleton} text={foundationPercentileText} />
        )] : []),
        ...(showCapstone ? [() => (
            isSkeleton
                ? <ProgressMeter isSkeleton showValue label={labels.trackCapstone} />
                : <ProgressMeter value={capstoneScore ?? 0} max={100} showValue label={labels.trackCapstone} />
        )] : []),
        ...(showInterview ? [() => (
            isSkeleton
                ? <ProgressMeter isSkeleton showValue label={labels.trackInterview} />
                : <ProgressMeter value={interviewScore ?? 0} max={100} showValue label={labels.trackInterview} />
        )] : []),
        ...(showCv ? [() => (
            isSkeleton
                ? <ProgressMeter isSkeleton showValue label={labels.trackCv} />
                : <ProgressMeter value={cvScore ?? 0} max={100} showValue label={labels.trackCv} />
        )] : []),
        ...(showCta ? [() => (
            isSkeleton
                ? <Button isSkeleton variant="primary" classNames={["self-start"]} />
                : <Button variant="primary" classNames={["self-start"]} label={ctaLabel ?? ""} suffixIcon={ArrowRightIcon} onPress={onCtaPress} />
        )] : []),
    ]

    return (
        <StackV
            gap={4}
            isSkeleton={isSkeleton}
            identity={{ tier: "block", component: "JobReadinessWidget" }}
            items={widgetItems}
        />
    )
}

"use client"

import React from "react"
import { BriefcaseIcon } from "@phosphor-icons/react"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import type { UserJobReadinessTrack } from "@/modules/api/graphql/queries/types/user-job-readiness"
import { useQueryMyJobReadinessSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyJobReadinessSwr"
import { pathConfig } from "@/resources/path"
import { _JobReadinessWidget } from "./component"

/** Which pillar to nudge the learner to complete next, for a given track. */
type MissingPillar = "capstone" | "interview" | "cv" | null

/**
 * Picks the single most-impactful missing pillar for a track, in the order a
 * learner would naturally tackle them: finish the capstone first, then the
 * mock interview, then the CV tied to this track's course. Returns `null`
 * once every pillar has at least an attempt — never re-suggests a pillar
 * that already has a score, and never suggests buying another course.
 *
 * @param track - the strongest track to inspect (its own `cvScore`, never blended)
 */
const missingPillarOf = (track: UserJobReadinessTrack): MissingPillar => {
    if (track.capstoneScore === null) return "capstone"
    if (track.interviewScore === null) return "interview"
    if (track.cvScore === null) return "cv"
    return null
}

/**
 * DashboardPage "My job readiness" self-widget — the CONNECTED half: self-fetches
 * the viewer's job-readiness snapshot via `myJobReadiness`, picks the
 * strongest track, resolves the single missing-pillar CTA's route + label,
 * and hands every resolved value to the presentational
 * {@link _JobReadinessWidget}. See `tiers/split.md`.
 */
export const JobReadinessWidget = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const { data, isLoading, error, mutate } = useQueryMyJobReadinessSwr()

    const tracks = data?.tracks ?? []
    const strongestTrack = tracks[0]
    const missingPillar = strongestTrack ? missingPillarOf(strongestTrack) : null

    const ctaHref = strongestTrack
        ? missingPillar === "capstone"
            ? pathConfig().locale(locale).course(strongestTrack.courseSlug).learn().personalProject().build()
            : missingPillar === "interview"
                ? pathConfig().locale(locale).course(strongestTrack.courseSlug).learn().mockInterview().build()
                : missingPillar === "cv"
                    // CV is a USER-level tool (not course-scoped) — `/learn/cv` never
                    // existed as a route (dead builder in pathConfig, unused elsewhere).
                    ? pathConfig().locale(locale).profile().cv().build()
                    : null
        : null

    const ctaLabel = missingPillar === "capstone"
        ? t("jobReadiness.ctaCapstone")
        : missingPillar === "interview"
            ? t("jobReadiness.ctaInterview")
            : missingPillar === "cv"
                ? t("jobReadiness.ctaCv")
                : null

    const codingPercentile = data?.foundation.codingPercentile

    return (
        <_JobReadinessWidget
            // first-load formula (loading-and-skeleton.md §2): nothing to show yet
            isSkeleton={isLoading && tracks.length === 0}
            isEmpty={tracks.length === 0}
            // only surface the error slot when there is no cached track to fall back to
            error={tracks.length === 0 ? error : undefined}
            onRetry={() => { void mutate() }}
            courseTitle={strongestTrack?.courseTitle}
            depthScore={strongestTrack?.depthScore ?? undefined}
            band={strongestTrack?.band}
            bandLabel={strongestTrack ? t(`jobReadiness.band.${strongestTrack.band}`) : undefined}
            foundationPercentileText={codingPercentile !== null && codingPercentile !== undefined
                ? t("jobReadiness.foundationPercentile", { percent: codingPercentile })
                : undefined}
            capstoneScore={strongestTrack?.capstoneScore}
            interviewScore={strongestTrack?.interviewScore}
            cvScore={strongestTrack?.cvScore}
            onCtaPress={ctaHref ? () => router.push(ctaHref) : undefined}
            ctaLabel={ctaLabel ?? undefined}
            labels={{
                errorTitle: t("jobReadiness.error"),
                retry: t("DashboardPage.retry"),
                emptyTitle: t("jobReadiness.myEmpty"),
                emptyDescription: t("jobReadiness.emptyHint"),
                trackCapstone: t("jobReadiness.trackCapstone"),
                trackInterview: t("jobReadiness.trackInterview"),
                trackCv: t("jobReadiness.trackCv"),
            }}
        />
    )
}

/** Icon used by the parent `LabeledCard` for this widget's section label. */
export const JobReadinessWidgetIcon = BriefcaseIcon

"use client"

import React from "react"
import {
    cn,
} from "@heroui/react"
import type {
    WithClassNames,
} from "@/modules/types/base/class-name"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { StackH } from "@/components/frames/Stack"

/** Representative week columns shown (the real grid is ~53, draggable past the viewport). */
const WEEK_COLUMNS = 26

/** Rows per week column (Sun→Sat). */
const WEEK_ROWS = 7

/** Year-switcher button placeholders (current + 2 back). */
const YEAR_BUTTONS = 3

/**
 * Loading placeholder for {@link import("../").OverviewContributions}: mirrors the
 * {@link import("@/components/blocks/profile/ContributionCalendarView").ContributionCalendarView}
 * heatmap — header (count + year switcher), the 7×N cell grid, and the Less→More
 * legend — at the same cell size / gaps so the box does not jump when data resolves.
 *
 * @param props - {@link OverviewContributionsSkeleton}
 */
export const OverviewContributionsSkeleton = ({ className }: WithClassNames<undefined>) => {
    return (
        <div className={cn("flex flex-col gap-3", className)}>
            {/* header: count text (left) + year switcher (right) */}
            <StackH gap={4} principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                justify="between" align="center" items={[
                    () => <Skeleton.Typography type="body-sm" width="1/3" />,
                    () => (
                        <StackH gap={3} principle="flex-action"
                            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                            align="center" items={
                                Array.from({ length: YEAR_BUTTONS }, (_, index) => () => (
                                    <Skeleton key={index} className="h-5 w-10 rounded-medium" />
                                ))
                            } />
                    ),
                ]} />

            {/* grid: weekday label column + N week columns of 7 cells — gap-[3px] is calendar cell pitch, not a house seam */}
            <div className="flex gap-[3px] overflow-hidden">
                <div className="w-8 shrink-0" />
                {Array.from({ length: WEEK_COLUMNS }).map((_, columnIndex) => (
                    <div key={columnIndex} className="flex shrink-0 flex-col gap-[3px]">
                        {Array.from({ length: WEEK_ROWS }).map((_cell, rowIndex) => (
                            <Skeleton key={rowIndex} className="size-3 shrink-0 rounded-sm" />
                        ))}
                    </div>
                ))}
            </div>

            {/* legend: Less → More (5 cells, right-aligned) */}
            <StackH gap={3} principle="chip-row"
                explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                justify="end" align="center" items={
                    Array.from({ length: 5 }, (_, index) => () => (
                        <Skeleton key={index} className="size-3 shrink-0 rounded-sm" />
                    ))
                } />
        </div>
    )
}

import React from "react"
import { AsyncContentError } from "@/components/composites/async/AsyncContent"
import { ContributionCalendarView } from "@/components/blocks/profile/ContributionCalendarView"
import { StackV } from "@/components/frames/Stack"
import type { CallerIdentity } from "@/components/frames/_identity"
import type { QueryMyContributionDayData } from "@/modules/api/graphql/queries/types/my-dashboard"

/** This block's own identity (BLOCK-2/split.md) — handed down to the track standing in as its root. See `_identity.ts`. */
const IDENTITY: CallerIdentity = { tier: "block", component: "OverviewContributions" }

/** All display text, already localized by the connected `OverviewContributions`; a story passes i18n keys. */
export interface OverviewContributionsLabels {
    errorTitle: string
    retry: string
}

/** Props for {@link _OverviewContributions} — presentational; all data resolved, no fetch/store/i18n. */
export interface OverviewContributionsProps {
    /** First load, nothing in hand → the header/grid/legend shimmer in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Truthy → the error message (beats loading). The connected file only passes its settled fetch error (no cached days left to show). */
    error?: unknown
    /** Retry handler — paired with `labels.retry`. */
    onRetry?: () => void
    /** Active contribution days for the selected year (oldest first); ignored while `isSkeleton`. */
    days?: Array<QueryMyContributionDayData>
    /** The year currently shown. */
    year: number
    /** Called with the picked year when the user flips the year switcher. */
    onYearChange: (year: number) => void
    labels: OverviewContributionsLabels
}

/**
 * DashboardPage contribution heatmap (GitHub-style) for the signed-in viewer — the presentational half
 * of {@link import("./index").OverviewContributions}. Content only (the parent
 * {@link import("@/components/blocks").LabeledCard} frames it). Two states in the fixed order
 * error → content (BLOCK-8; there is no genuine empty state — a zero-activity year still renders a
 * real, mostly-blank calendar, so `days.length === 0` is not "nothing to show"): `error` falls to
 * the shared `AsyncContentError` frame.
 *
 * {@link ContributionCalendarView} carries no `isSkeleton` prop of its own (`missingSkeletonSupport`
 * — it is a sibling component, not owned by this split), so while shimmering this swaps in a
 * minimal `Skeleton.*` mirror of its header (count line + year switcher) / grid / legend right here,
 * still co-located with the real tree instead of a separate skeleton file (`loading-and-skeleton.md`).
 * See `tiers/split.md` — the connected `index.tsx` owns the fetch and i18n.
 *
 * @param props - {@link OverviewContributionsProps}
 */
export const _OverviewContributions = ({
    isSkeleton = false,
    error,
    onRetry,
    days = [],
    year,
    onYearChange,
    labels,
}: OverviewContributionsProps) => {
    if (error) {
        return <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retry} />
    }

    // The calendar owns its own resting state, so this block hands the flag down instead
    // of keeping a second description of the same shape (`loading-and-skeleton.md`).
    return (
        <StackV
            gap={4}
            identity={IDENTITY}
            body={() => (
                <ContributionCalendarView
                    isSkeleton={isSkeleton}
                    days={days}
                    year={year}
                    onYearChange={onYearChange}
                />
            )}
        />
    )
}

"use client"

import React, {
    useState,
} from "react"
import {
    useTranslations,
} from "next-intl"
import { useQueryMyContributionCalendarSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyContributionCalendarSwr"
import { _OverviewContributions } from "./component"

/**
 * DashboardPage contribution heatmap (GitHub-style) for the signed-in viewer — the CONNECTED half: it
 * self-fetches its own contribution leaf query (re-keyed on the selected year), computes the
 * first-load skeleton flag and the settled error, and hands them to the presentational
 * {@link import("./component")._OverviewContributions}. See `tiers/split.md`.
 */
export const OverviewContributions = () => {
    const t = useTranslations()
    const [year, setYear] = useState(() => new Date().getFullYear())
    const { data, isLoading, error, mutate } = useQueryMyContributionCalendarSwr(year)
    const days = data ?? []

    return (
        <_OverviewContributions
            // unchanged from the legacy AsyncContent path: first load, no days in hand yet
            isSkeleton={isLoading && days.length === 0}
            // only surface the error slot when there is no cached day to fall back to
            error={days.length === 0 ? error : undefined}
            onRetry={() => { void mutate() }}
            days={days}
            year={year}
            onYearChange={setYear}
            labels={{
                errorTitle: t("DashboardPage.loadError"),
                retry: t("DashboardPage.retry"),
            }}
        />
    )
}

"use client"

import React, {
    useCallback,
} from "react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import {
    pathConfig,
} from "@/resources/path"
import {
    ContinueLearning,
} from "../ContinueLearning"
import {
    DailyQuest,
} from "../DailyQuest"
import {
    StreakStrip,
} from "../StreakStrip"
import {
    StreakFreezeCard,
} from "../StreakFreezeCard"
import {
    WeeklyGoals,
} from "../WeeklyGoals"
import {
    WeeklyChallengeCard,
} from "../WeeklyChallengeCard"
import {
    OverviewContributions,
} from "./OverviewContributions"
import {
    ChangelogList,
} from "../ChangelogList"
import {
    JobReadinessWidget,
} from "./JobReadinessWidget"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"

/** Props for {@link OverviewTab}. */
export type OverviewTabProps = Record<string, never>
/**
 * DashboardPage "Overview" tab — the cockpit, every section framed by a `LabeledCard`
 * (label outside + card, mirroring the profile page): "Continue learning" (next action),
 * "Streak" (streak), "Weekly goals" (weekly goals), "My readiness" (own
 * job-readiness + a CTA at the missing pillar), the weekly-challenge event, then
 * the contribution heatmap. Each child self-fetches + owns its states.
 * @param props - optional root class name (placement only)
 */
export const OverviewTab = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()

    /** Open the weekly-KPI editor page. */
    const onSeeMoreGoals = useCallback(
        () => router.push(pathConfig().locale(locale).kpi().build()),
        [router, locale],
    )

    return (
        <div className={"flex flex-col gap-6"}>
            {/* frameless: resume items are themselves cards → no card-in-card */}
            <LabeledCard
                label={t("DashboardPage.sections.continue")}
                frameless
            >
                <ContinueLearning />
            </LabeledCard>
            {/* DailyQuest self-frames (LabeledCard label + flush list + claim prompt as description) */}
            <DailyQuest />
            <LabeledCard
                label={t("DashboardPage.sections.streak")}
            >
                <StreakStrip />
            </LabeledCard>
            {/* streak-freeze inventory — self-framed card (buy/owned/full states), reads myWeeklyStats */}
            <StreakFreezeCard />
            <LabeledCard
                label={t("DashboardPage.sections.goals")}
                onSeeMore={onSeeMoreGoals}
                seeMoreLabel={t("DashboardPage.kpi.edit")}
            >
                <WeeklyGoals />
            </LabeledCard>
            <LabeledCard
                label={t("jobReadiness.myTitle")}
            >
                <JobReadinessWidget />
            </LabeledCard>
            {/* weekly-challenge event — self-titled card (self-hides when none) */}
            <WeeklyChallengeCard />
            <LabeledCard
                label={t("DashboardPage.contributions.heading")}
            >
                <OverviewContributions />
            </LabeledCard>
            {/* platform news — moved here from the Community tab (Community = people/competition) */}
            <ChangelogList framed />
        </div>
    )
}

"use client"

import React, {
    useCallback,
    useMemo,
} from "react"
import {
    Chip,
    ListBox,
} from "@heroui/react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import { useRouter } from "next/navigation"
import {
    GraduationCapIcon,
    CardsIcon,
    CodeIcon,
    TrophyIcon,
    BookmarkSimpleIcon,
    GiftIcon,
    ArticleIcon,
    BriefcaseIcon,
    UsersThreeIcon,
} from "@phosphor-icons/react"
import {
    pathConfig,
} from "@/resources/path"
import { LabeledList } from "@/components/blocks/lists/LabeledList"
import { useAppSelector } from "@/redux/hooks"
import { useQueryMyRewardWalletSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyRewardWalletSwr"
import { useQueryMyDueFlashcardsSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyDueFlashcardsSwr"

/** Props for {@link QuickActions}. */
export type QuickActionsProps = Record<string, never>
/**
 * Left-rail "quick access" list — one-tap shortcuts to the surfaces a learner
 * reaches for most (catalog, practice, bookmarks, own profile). Pure navigation;
 * self-reads the viewer's username from redux for the profile-scoped links. Rows
 * are flush-left (aligned with the heading + the identity stats above), not the
 * indented HeroUI ListBox. `"use client"` for the redux read.
 * @param props - optional className for the root element.
 */
export const QuickActions = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const username = useAppSelector((state) => state.user.user?.username)
    // spendable reward balance — surfaced as a chip on the rewards shortcut
    const { data: wallet } = useQueryMyRewardWalletSwr()
    // due-card count — a live "N due" nudge on the review shortcut
    const { data: dueFlashcards } = useQueryMyDueFlashcardsSwr()
    const dueCount = dueFlashcards?.dueCount ?? 0

    /** The shortcut rows (icon + label + destination), ordered by everyday frequency. */
    const actions = useMemo(
        () => [
            {
                key: "courses",
                Icon: GraduationCapIcon,
                href: pathConfig().locale(locale).course().build(),
            },
            {
                key: "review",
                Icon: CardsIcon,
                href: pathConfig().locale(locale).review().build(),
            },
            {
                key: "practice",
                Icon: CodeIcon,
                href: pathConfig().locale(locale).practice().build(),
            },
            {
                key: "league",
                Icon: TrophyIcon,
                href: pathConfig().locale(locale).league().build(),
            },
            {
                key: "bookmarks",
                Icon: BookmarkSimpleIcon,
                // bookmarks live under the viewer's own profile
                href: username
                    ? pathConfig().locale(locale).profile(username).bookmarks().build()
                    : pathConfig().locale(locale).course().build(),
            },
            {
                key: "rewards",
                Icon: GiftIcon,
                href: pathConfig().locale(locale).rewards().build(),
            },
            {
                key: "blog",
                Icon: ArticleIcon,
                href: pathConfig().locale(locale).blog().build(),
            },
            {
                key: "talents",
                Icon: UsersThreeIcon,
                href: pathConfig().locale(locale).talents().build(),
            },
            {
                key: "jobs",
                Icon: BriefcaseIcon,
                href: pathConfig().locale(locale).jobs().build(),
            },
        ],
        [
            locale,
            username,
        ],
    )

    // nav-on-activate: ListBox with no selection → onAction fires the item id; we
    // route to its href (Next client nav). Using the NATIVE HeroUI ListBox chrome
    // (react-aria) instead of hand-rolling a Link + hover class — the row highlight
    // (`data-[hovered=true]:bg-default`) is the component's own hover fill.
    const onAction = useCallback(
        (key: React.Key) => {
            const action = actions.find((item) => item.key === key)
            if (action) {
                router.push(action.href)
            }
        },
        [actions, router],
    )

    return (
        <LabeledList label={t("DashboardPage.quickActions")}>
            <ListBox
                aria-label={t("DashboardPage.quickActions")}
                selectionMode="none"
                onAction={onAction}
                className="p-0"
            >
                {actions.map(({
                    key,
                    Icon,
                }) => (
                    <ListBox.Item
                        key={key}
                        id={key}
                        textValue={t(`DashboardPage.actions.${key}`)}
                        // icon + label share the row's `text-foreground` (icon.md §leading:
                        // leading icon same colour as its title, not a stray `text-muted`);
                        // hover fill is native ListBox chrome, no hand-rolled hover class.
                        // content-row: leading icon · label · trailing chip (retuned gap-3→gap-4).
                        className="flex cursor-pointer items-center gap-4 rounded-large px-2 py-2 text-foreground outline-none data-[focus-visible=true]:ring-2 data-[focus-visible=true]:ring-accent data-[hovered=true]:bg-default" data-principle="content-row"
                    >
                        <Icon aria-hidden focusable="false" className="size-5 shrink-0" />
                        <span className="min-w-0 flex-1 truncate text-sm">
                            {t(`DashboardPage.actions.${key}`)}
                        </span>
                        {key === "rewards" && wallet ? (
                            <Chip className="shrink-0" size="sm" variant="soft" color="warning">
                                <Chip.Label>
                                    {t("DashboardPage.rewardBalance", { count: wallet.balance })}
                                </Chip.Label>
                            </Chip>
                        ) : null}
                        {key === "review" && dueCount > 0 ? (
                            // "due" = a backlog nudge → warning (amber), NOT accent
                            // (accent is reserved for brand/CTA). Matches the DeckList/StudyRail/QuizSession convention.
                            <Chip className="shrink-0" size="sm" variant="soft" color="warning">
                                <Chip.Label>
                                    {t("DashboardPage.dueCount", { count: dueCount })}
                                </Chip.Label>
                            </Chip>
                        ) : null}
                    </ListBox.Item>
                ))}
            </ListBox>
        </LabeledList>
    )
}

import React from "react"
import { BookOpenIcon } from "@phosphor-icons/react"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { AsyncContentError } from "@/components/composites/async/AsyncContent"
import { Typography } from "@/components/atoms/text/Typography"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { SurfaceListCard, SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { PriceTagInline } from "@/components/blocks/commerce/PriceTag"
import { StackH, StackV } from "@/components/frames/Stack"

/** How many placeholder rows the co-located skeleton shows. */
const SKELETON_ROW_COUNT = 3

/** One recommended (not-yet-enrolled) course row, already resolved by the connected half. */
export interface RecommendedCoursesItem {
    /** Public display id — also the row's React key. */
    displayId: string
    title: string
    description: string | null
    thumbnailUrl: string | null
    /** Deep link into the course detail page, already locale-prefixed. */
    href: string
    /** Price the viewer actually pays (their loyalty discount already applied). */
    discountedPriceVnd: number
    originalPriceVnd: number
    /** `true` when the viewer's loyalty discount applies (`discountPercent > 0`). */
    discounted: boolean
    /** Already-translated "why this discount" line; omitted when there's no discount or no reason. */
    reasonText?: string
}

/** All display text, already localized by the connected `RecommendedCourses`. */
export interface RecommendedCoursesLabels {
    /** Section title above the card. */
    title: string
    /** Error-branch title. */
    loadErrorTitle: string
    /** Error-branch retry button label. */
    retry: string
}

/** Props for {@link _RecommendedCourses} — presentational; all data resolved, no fetch/store/i18n. */
export interface RecommendedCoursesProps extends WithClassNames<undefined> {
    /** First load, nothing in hand → the list rows shimmer in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with zero recommendations → the whole section hides (nothing left to recommend). */
    isEmpty?: boolean
    /** Truthy → the error message (beats the empty hide). The connected file only forwards a settled error with nothing in hand. */
    error?: unknown
    /** Retry handler for the error branch. */
    onRetry?: () => void
    /** Recommended courses, in display order. */
    items?: Array<RecommendedCoursesItem>
    labels: RecommendedCoursesLabels
}

/**
 * "Courses for you" — the presentational half of {@link RecommendedCourses}: courses the viewer has
 * NOT bought yet, each priced with their engagement-based loyalty discount (an exclusive offer for
 * diligent / multi-course learners; the discounted price is the price actually charged). One framed
 * `LabeledCard` with a flat row per course — the TITLE is the link into the course (not a whole-card
 * press, matching "my courses"). Hides entirely once settled with zero recommendations — this block
 * never had an empty-state message, only a genuine fetch failure gets one.
 *
 * `error` falls to the shared `AsyncContentError` frame; otherwise the list renders with `isSkeleton`
 * threaded to every leaf that supports it (`loading-and-skeleton.md`). `IconTile` and `PriceTag`
 * carry no `isSkeleton` of their own, so their skeleton row is a hand-mirrored `Skeleton.*` pair sized
 * to their real boxes, right where they sit (still co-located — not a parallel tree). See
 * `tiers/split.md` — the connected `index.tsx` owns the fetch, the hrefs, and every translated string.
 *
 * @param props - {@link RecommendedCoursesProps}
 */
export const _RecommendedCourses = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    items = [],
    labels,
}: RecommendedCoursesProps) => {
    // settled, no error, nothing left to recommend → hide the whole section (the original contract
    // never rendered an empty-state message here, only a genuine fetch failure gets one).
    if (!isSkeleton && !error && isEmpty) {
        return null
    }

    // `frameless` mirrors the loaded list — self-framed as a `SurfaceListCard` — skipping the outer
    // `Card` only once real rows are showing, matching `MyCoursesProgress`.
    const hasItems = !isSkeleton && !error && items.length > 0

    return (
        <LabeledCard
            label={labels.title}

            frameless={hasItems}
            identity={{ tier: "block", component: "RecommendedCourses" }}
        >
            {error ? (
                <AsyncContentError title={labels.loadErrorTitle} onRetry={onRetry} retryLabel={labels.retry} />
            ) : (
                <SurfaceListCard>
                    {isSkeleton
                        ? Array.from({ length: SKELETON_ROW_COUNT }, (_unused, index) => (
                            <SurfaceListCardItem key={index}>
                                <StackH gap={3} items={[
                                    // IconTile has no isSkeleton of its own — hand-mirrored, sized to its "sm" box.
                                    () => <Skeleton className="size-12 shrink-0 rounded-xl" />,
                                    () => (
                                        <StackV gap={2} classNames={["min-w-0", "flex-1"]} items={[
                                            () => <Typography size="sm" weight="medium" isSkeleton />,
                                            // PriceTag has no isSkeleton of its own — hand-mirrored to its box.
                                            () => <Skeleton.Typography type="body-xs" width="1/4" />,
                                        ]} />
                                    ),
                                ]} />
                            </SurfaceListCardItem>
                        ))
                        : items.map((course) => (
                            <SurfaceListCardItem key={course.displayId} href={course.href} hover="underline">
                                <StackH gap={3} items={[
                                    () => (
                                        <IconTile
                                            size="sm"
                                            src={course.thumbnailUrl}
                                            alt={course.title}
                                            icon={<BookOpenIcon aria-hidden focusable="false" />}
                                        />
                                    ),
                                    () => (
                                        <StackV gap={1} classNames={["min-w-0", "flex-1"]} items={[
                                            // whole-row link → title underlines on CARD hover (group), matching "my courses" CourseRow.
                                            () => (
                                                <Typography
                                                    size="sm"
                                                    weight="medium"
                                                    truncate
                                                    underlineOnGroupHover
                                                    text={course.title}
                                                />
                                            ),
                                            ...(course.description ? [() => (
                                                <Typography size="xs" color="muted" truncate text={course.description} />
                                            )] : []),
                                            () => (
                                                <PriceTagInline
                                                    discounted={course.discountedPriceVnd}
                                                    original={course.discounted ? course.originalPriceVnd : null}

                                                />
                                            ),
                                            ...(course.reasonText ? [() => (
                                                <Typography size="xs" color="accent-soft" text={course.reasonText} />
                                            )] : []),
                                        ]} />
                                    ),
                                ]} />
                            </SurfaceListCardItem>
                        ))}
                </SurfaceListCard>
            )}
        </LabeledCard>
    )
}

"use client"

import React from "react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    pathConfig,
} from "@/resources/path"
import { useQueryRecommendedCoursesSwr } from "@/hooks/swr/api/graphql/queries/useQueryRecommendedCoursesSwr"
import { _RecommendedCourses, type RecommendedCoursesItem } from "./component"

/** Props for {@link RecommendedCourses}. */
export type RecommendedCoursesProps = Record<string, never>
/**
 * "Courses for you" — the CONNECTED half: self-fetches the viewer's recommended
 * (not-enrolled) courses, builds each course's locale-prefixed deep link and its
 * already-translated discount-reason line, and hands them to the presentational
 * {@link _RecommendedCourses}. See `tiers/split.md`.
 * @param props - optional className for the root element.
 */
export const RecommendedCourses = () => {
    const t = useTranslations()
    const locale = useLocale()
    const { data, isLoading, error, mutate } = useQueryRecommendedCoursesSwr()
    const items = data?.items ?? []

    const resolvedItems: Array<RecommendedCoursesItem> = items.map((course) => {
        const discounted = course.discountPercent > 0
        return {
            displayId: course.displayId,
            title: course.title,
            description: course.description,
            thumbnailUrl: course.thumbnailUrl,
            href: pathConfig().locale(locale).course(course.displayId).build(),
            discountedPriceVnd: course.discountedPriceVnd,
            originalPriceVnd: course.originalPriceVnd,
            discounted,
            reasonText: discounted && course.discountReason !== "none"
                ? t(`DashboardPage.recommended.reason.${course.discountReason}`, { count: course.enrolledCount })
                : undefined,
        }
    })

    return (
        <_RecommendedCourses
            // first load, nothing in hand → shimmer (loading-and-skeleton.md's dominant idiom)
            isSkeleton={isLoading && items.length === 0}
            // settled with zero recommendations → the block hides itself
            isEmpty={items.length === 0}
            // only a settled fetch error with nothing in hand reaches the block — a background
            // revalidation failure never interrupts an already-loaded list
            error={items.length === 0 ? error : undefined}
            onRetry={() => { void mutate() }}
            items={resolvedItems}
            labels={{
                title: t("DashboardPage.recommended.title"),
                loadErrorTitle: t("DashboardPage.loadError"),
                retry: t("DashboardPage.retry"),
            }}
        />
    )
}

import React from "react"
import {
    SnowflakeIcon,
} from "@phosphor-icons/react"
import { AsyncContentError } from "@/components/composites/async/AsyncContent"
import { SectionCard } from "@/components/blocks/cards/SectionCard"
import { Button } from "@/components/atoms/buttons/Button"
import { Typography } from "@/components/atoms/text/Typography"

/** Maximum number of streak freezes a user may own. */
export const MAX_FREEZES = 3

/** Points cost of one streak freeze. */
export const FREEZE_COST = 100

/** All display text, already localized by the connected `StreakFreezeCard`; a story passes i18n keys. */
export interface StreakFreezeCardLabels {
    title: string
    errorTitle: string
    retry: string
    /** Already interpolated with the owned count and {@link MAX_FREEZES} (e.g. "2 of 3"). */
    owned: string
    explainer: string
    /** Already interpolated with {@link FREEZE_COST} (e.g. "Buy for 100 points"). */
    buy: string
    full: string
}

/** Props for {@link _StreakFreezeCard} — presentational; all data resolved, no fetch/store/i18n. */
export interface StreakFreezeCardProps {
    /** First load, nothing in hand → the whole card shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with no data (signed out / genuinely unavailable) → the card self-hides. */
    isEmpty?: boolean
    /**
     * Truthy → the error message (beats loading + empty). The connected file only passes its
     * settled fetch error when there is no cached data left to fall back to.
     */
    error?: unknown
    /** Retry handler — paired with `labels.retry`. */
    onRetry?: () => void
    /** How many freezes the viewer currently owns. */
    owned?: number
    /** `true` while the purchase mutation is in flight. */
    buying?: boolean
    /** Fired when the learner presses "Buy". */
    onBuy?: () => void
    labels: StreakFreezeCardLabels
}

/**
 * Right-rail "streak freeze" card — the presentational half of {@link StreakFreezeCard}. A freeze
 * keeps the daily streak alive when the viewer misses a single day; shows how many they own (of
 * {@link MAX_FREEZES}) and a "buy for {@link FREEZE_COST} points" trigger. Four states in the fixed
 * order error → loading → empty → content (BLOCK-8): a settled `error` falls to the shared
 * `AsyncContentError` frame with no card shell around it (a stale card beats a scary error, but an
 * error replaces the card rather than living inside it); `isEmpty` self-hides entirely (no
 * `emptyContent` — matches the sibling right-rail widgets); otherwise the owned line, explainer, and
 * buy button render inside `SectionCard`, with `isSkeleton` threaded to every leaf so the shimmer
 * mirrors the loaded shape. See `tiers/split.md` — the connected `index.tsx` owns the fetch, the
 * `buyStreakFreeze` mutation, and i18n.
 *
 * @param props - {@link StreakFreezeCardProps}
 */
export const _StreakFreezeCard = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    owned = 0,
    buying = false,
    onBuy,
    labels,
}: StreakFreezeCardProps) => {
    // error → skeleton → empty → content (BLOCK-8): error beats a stale loading flag.
    if (error) {
        return <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retry} />
    }
    if (!isSkeleton && isEmpty) {
        return null
    }

    const full = owned >= MAX_FREEZES

    return (
        <SectionCard
            icon={() => <SnowflakeIcon className="size-5 text-accent-soft-foreground" />}
            title={labels.title}
        >
            <Typography
                size="sm"
                weight="medium"
                text={labels.owned}
                isSkeleton={isSkeleton}
            />
            <Typography
                size="xs"
                color="muted"
                text={labels.explainer}
                isSkeleton={isSkeleton}
                classNames={isSkeleton ? ["w-full"] : undefined}
            />
            {isSkeleton ? (
                <Button isSkeleton variant="tertiary" size="sm" />
            ) : (
                <Button
                    variant="tertiary"
                    size="sm"
                    isDisabled={full || buying}
                    isPending={buying}
                    label={full ? labels.full : labels.buy}
                    onPress={onBuy}
                />
            )}
        </SectionCard>
    )
}

"use client"

import React, {
    useCallback,
    useState,
} from "react"
import {
    useTranslations,
} from "next-intl"
import { useMutateRedeemRewardSwr } from "@/hooks/swr/api/graphql/mutations/useMutateRedeemRewardSwr"
import { useQueryMyWeeklyStatsSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyWeeklyStatsSwr"
import { useGraphQLWithToast } from "@/modules/toast/hooks"
import { _StreakFreezeCard, FREEZE_COST, MAX_FREEZES } from "./component"

/**
 * Right-rail "streak freeze" card — the CONNECTED half: self-fetches `myWeeklyStats`, owns the
 * `buyStreakFreeze` mutation (toasting the result) and revalidates the shared leaf query on success,
 * and resolves every label (incl. interpolation) before handing them to the presentational
 * {@link _StreakFreezeCard}. See `tiers/split.md`.
 */
export const StreakFreezeCard = () => {
    const t = useTranslations()
    const {
        data,
        error,
        mutate,
    } = useQueryMyWeeklyStatsSwr()
    const { trigger: triggerRedeem } = useMutateRedeemRewardSwr()
    const runGraphQL = useGraphQLWithToast()
    // whether a purchase is currently in flight
    const [buying, setBuying] = useState(false)

    /** Buy one freeze, toast the result, then revalidate the weekly stats. */
    const onBuy = useCallback(
        async () => {
            setBuying(true)
            try {
                const ok = await runGraphQL(async () => {
                    const result = await triggerRedeem({
                        rewardKey: "streakFreeze",
                    })
                    return result.data!.redeemReward
                })
                if (ok) {
                    await mutate()
                }
            } finally {
                setBuying(false)
            }
        },
        [
            triggerRedeem,
            mutate,
            runGraphQL,
        ],
    )

    const owned = data?.streakFreezes ?? 0

    return (
        <_StreakFreezeCard
            // first load, nothing in hand → shimmer; settled (data OR error) stops it (loading-and-skeleton.md)
            isSkeleton={!data && !error}
            // settled with no data (signed out / genuinely no stats) → self-hide
            isEmpty={!data}
            // only surface the error slot when there is no cached data to fall back to (a stale
            // card beats a scary error on a transient blip)
            error={!data ? error : undefined}
            onRetry={() => { void mutate() }}
            owned={owned}
            buying={buying}
            onBuy={() => void onBuy()}
            labels={{
                title: t("streakFreeze.title"),
                errorTitle: t("DashboardPage.loadError"),
                retry: t("DashboardPage.retry"),
                owned: t("streakFreeze.owned", {
                    count: owned,
                    max: MAX_FREEZES,
                }),
                explainer: t("streakFreeze.explainer"),
                buy: t("streakFreeze.buy", {
                    cost: FREEZE_COST,
                }),
                full: t("streakFreeze.full"),
            }}
        />
    )
}

import React from "react"
import { CircleIcon, FlameIcon } from "@phosphor-icons/react"
import { AsyncContentError } from "@/components/composites/async/AsyncContent"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"
import { InfoTooltip } from "@/components/blocks/feedback/InfoTooltip"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Button } from "@/components/atoms/buttons/Button"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH, StackV } from "@/components/frames/Stack"
import { Cluster } from "@/components/frames/Cluster"
import { Split } from "@/components/frames/Split"
import type { CallerIdentity } from "@/components/frames/_identity"

/** How many placeholder day-dots the co-located skeleton shows (last 7 days, always seven). */
const SKELETON_DAY_COUNT = 7

/** This block's own identity (BLOCK-2/split.md) — handed down to the root `StackV`. See `_identity.ts`. */
const IDENTITY: CallerIdentity = { tier: "block", component: "StreakStrip" }

/** One of the last 7 days, already resolved by the connected `StreakStrip` (locale formatting is i18n — it stays in `index.tsx`). */
export interface StreakStripDay {
    /** ISO date (`YYYY-MM-DD`) — used only as the React key. */
    date: string
    /** Whether the learner was active this day. */
    active: boolean
    /** Already-locale-formatted full date, shown as the dot's native tooltip. */
    title: string
    /** Already-locale-formatted narrow weekday label under the dot. */
    weekday: string
}

/** All display text, already localized by the connected `StreakStrip`; a story passes i18n keys. */
export interface StreakStripLabels {
    /** Error-branch title. */
    errorTitle: string
    /** Error-branch retry button label. */
    retry: string
    /** `InfoTooltip` heading over the current-streak readout. */
    streakLabel: string
    /** `InfoTooltip` explanation under {@link StreakStripLabels.streakLabel}. */
    streakHelp: string
    /** Current-streak sentence, already interpolated with the day count. */
    current: string
    /** Longest-streak chip label, already interpolated with the day count. */
    longest: string
    /** "No streak yet" message shown when there is nothing to show off. */
    empty: string
    /** Daily-goal CTA label — shared by the empty state and the idle-today nudge. */
    dailyGoalCta: string
    /** Idle-today nudge sentence ("keep the streak alive"). */
    dailyGoalNudge: string
}

/** Props for {@link _StreakStrip} — presentational; all data resolved, no fetch/store/i18n. */
export interface StreakStripProps {
    /** First load, nothing in hand → the whole strip shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Truthy → the error message (beats loading). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler — paired with `labels.retry` to show a retry button on the error branch. */
    onRetry?: () => void
    /** Current streak length, in days. */
    streak?: number
    /** Longest streak ever reached, in days. */
    /** The last 7 days, oldest first. */
    days?: Array<StreakStripDay>
    /** Fired by both daily-goal CTAs (empty state + idle-today nudge) — jumps to the course list. */
    onLearn?: () => void
    labels: StreakStripLabels
}

/**
 * "Learning streak" content — the presentational half of {@link StreakStrip}: the last-7-days dot
 * strip plus current/longest streak, and a daily-goal nudge when today is still idle. Content only
 * (the parent {@link import("@/components/blocks").LabeledCard} frames it). Two states in the fixed
 * order error → content (BLOCK-8): `error` falls to the shared `AsyncContentError` frame — there is
 * no genuine empty-fetch state, only the domain "no streak yet" message that renders inline, in place
 * of the flame/chip cluster, once settled; otherwise the strip renders with `isSkeleton` threaded to
 * every leaf so the shimmer mirrors the loaded shape. The day dot (`CircleIcon`) and the streak
 * readout (`InfoTooltip`) carry no `isSkeleton` of their own, so each is mirrored right where it sits
 * with a bare `Skeleton`/`Skeleton.Typography` (loading-and-skeleton.md §1). See `tiers/split.md` —
 * the connected `index.tsx` owns the fetch, the router, and the locale-formatted day labels.
 *
 * @param props - {@link StreakStripProps}
 */
export const _StreakStrip = ({
    isSkeleton = false,
    error,
    onRetry,
    streak = 0,
    days = [],
    onLearn,
    labels,
}: StreakStripProps) => {
    if (error) {
        return <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retry} />
    }

    // "has anything to show off" — a real streak day, or a currently-running streak. The flame/chip
    // cluster renders optimistically while shimmering (the eventual value isn't known yet); once
    // settled, a learner with nothing yet sees the empty message + CTA instead.
    const hasActivity = streak > 0 || days.some((day) => day.active)
    const showActiveCluster = isSkeleton || hasActivity
    const activeToday = days.at(-1)?.active === true
    const showNudge = !isSkeleton && hasActivity && !activeToday

    // day-dot column — while shimmering, 7 placeholder columns keep the SAME shape (loading-and-skeleton.md
    // §1: same leaf, same count). `CircleIcon` has no `isSkeleton` of its own, so the mirror sits right
    // here, co-located, rather than in a parallel tree.
    const dayItems: Array<ComponentTypeWithSkeleton> = isSkeleton
        ? Array.from({ length: SKELETON_DAY_COUNT }, () => () => (
            <StackV gap={3} principle="sibling-stack"
                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                align="center" items={[
                    () => <Skeleton className="size-6 shrink-0 rounded-full" />,
                    () => <Typography isSkeleton size="xs" />,
                ]} />
        ))
        : days.map((day) => () => (
            <StackV gap={3} principle="sibling-stack"
                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                align="center" items={[
                    () => (
                    // No `title`: the dot is `aria-hidden`, so a tooltip string on it would be
                    // announced to nobody — the weekday label below carries the meaning.
                        <CircleIcon
                            aria-hidden
                            focusable="false"
                            weight="fill"
                            className={day.active ? "size-6 shrink-0 text-accent/80" : "size-6 shrink-0 text-muted/20"}
                        />
                    ),
                    () => <Typography size="xs" color="muted" text={day.weekday} />,
                ]} />
        ))

    return (
        <StackV gap={4} isSkeleton={isSkeleton} identity={IDENTITY} items={[
            () => (
                <Split gap={4} isSkeleton={isSkeleton}
                    start={() => <Cluster gap={3} isSkeleton={isSkeleton} items={dayItems} />}
                    end={() => (
                        showActiveCluster ? (
                            <StackH gap={3} isSkeleton={isSkeleton} items={[
                                () => (
                                    isSkeleton
                                        ? <Skeleton className="size-5 shrink-0 rounded-full" />
                                        : <FlameIcon aria-hidden focusable="false" className="size-5 shrink-0 text-accent-soft-foreground" />
                                ),
                                () => (
                                    isSkeleton
                                        ? <Skeleton.Typography type="body-sm" width="1/4" />
                                        : (
                                            <InfoTooltip className="text-sm font-medium" title={labels.streakLabel} description={labels.streakHelp}>
                                                {labels.current}
                                            </InfoTooltip>
                                        )
                                ),
                                () => <Chip isSkeleton={isSkeleton} tone="accent" text={labels.longest} />,
                            ]} />
                        ) : (
                            <StackH gap={4} items={[
                                () => <Typography size="sm" color="muted" text={labels.empty} />,
                                () => <Button variant="primary" size="sm" onPress={onLearn} label={labels.dailyGoalCta} />,
                            ]} />
                        )
                    )}
                />
            ),
            ...(showNudge ? [() => (
                <Split gap={4}
                    start={() => <Typography size="sm" weight="medium" text={labels.dailyGoalNudge} />}
                    end={() => <Button variant="primary" size="sm" onPress={onLearn} label={labels.dailyGoalCta} />}
                />
            )] : []),
        ]} />
    )
}

"use client"

import React from "react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import {
    pathConfig,
} from "@/resources/path"
import { useQueryMyWeeklyStatsSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyWeeklyStatsSwr"
import { _StreakStrip, type StreakStripDay } from "./component"

/**
 * "Learning streak" — the CONNECTED half: self-fetches the weekly-stats leaf query, resolves each
 * of the last 7 days into a locale-formatted dot label (native tooltip date + narrow weekday), and
 * hands the result to the presentational {@link _StreakStrip}. See `tiers/split.md`.
 */
export const StreakStrip = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const {
        data: weekly,
        error,
        mutate,
    } = useQueryMyWeeklyStatsSwr()

    const streak = weekly?.streak ?? 0
    const longest = weekly?.longestStreak ?? 0

    // locale-dependent formatting is i18n — it stays here, next to the fetch (tiers/split.md),
    // so `_StreakStrip` only ever renders already-resolved strings.
    const days: Array<StreakStripDay> = (weekly?.days ?? []).map((day) => {
        const date = new Date(`${day.date}T00:00:00Z`)
        return {
            date: day.date,
            active: day.active,
            title: date.toLocaleDateString(locale),
            weekday: date.toLocaleDateString(locale, { weekday: "narrow" }),
        }
    })

    /** Navigate to the courses list so the viewer can start some content. */
    const onLearn = () => {
        router.push(pathConfig().locale(locale).course().build())
    }

    return (
        <_StreakStrip
            // first load, nothing in hand → shimmer; settled (data OR error) stops it (loading-and-skeleton.md)
            isSkeleton={!weekly && !error}
            error={error}
            onRetry={() => { void mutate() }}
            streak={streak}
            days={days}
            onLearn={onLearn}
            labels={{
                errorTitle: t("DashboardPage.streak.error"),
                retry: t("DashboardPage.streak.retry"),
                streakLabel: t("DashboardPage.streakLabel"),
                streakHelp: t("DashboardPage.streak.help"),
                current: t("DashboardPage.streak.current", { count: streak }),
                longest: t("DashboardPage.streak.longest", { count: longest }),
                empty: t("DashboardPage.streak.empty"),
                dailyGoalCta: t("DashboardPage.dailyGoal.cta"),
                dailyGoalNudge: t("DashboardPage.dailyGoal.nudge"),
            }}
        />
    )
}

import React from "react"
import { TrophyIcon } from "@phosphor-icons/react"
import { AsyncContentEmpty } from "@/components/composites/async/AsyncContent"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { SurfaceListCard, SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import {
    LeaderboardListCard,
    type LeaderboardRow,
    type LeaderboardStanding,
} from "@/components/blocks/dashboard/LeaderboardListCard"
import { StackH, StackV } from "@/components/frames/Stack"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** How many placeholder rows the co-located skeleton mirror shows (mirrors {@link import("./index").TOP_N}). */
const SKELETON_ROW_COUNT = 5

/** All display text, already localized by the connected {@link import("./index").TopLearners}; a story passes i18n keys. */
export interface TopLearnersLabels {
    title: string
    seeMoreLabel: string
    noLeadersTitle: string
    noLeadersDescription: string
    meLabel: string
}

/** Props for {@link _TopLearners} — presentational; all data resolved, no fetch/store/i18n. */
export interface TopLearnersProps extends WithClassNames<undefined> {
    /** First load, nothing in hand → the whole tree shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with no leaderboard entries → the empty message. */
    isEmpty?: boolean
    /** Opens the full leaderboard page. */
    onSeeMore?: () => void
    /** The viewer's own standing header line (rank-driven medal/cup badge). Omitted on a rankless viewer. */
    standing?: LeaderboardStanding
    /** The ranked rows (top-N slice), already mapped with their trailing follow control. */
    rows?: Array<LeaderboardRow>
    /** Pinned self-row when the viewer sits below the shown slice. */
    selfRow?: LeaderboardRow
    /** Ellipsis label above the pinned self-row (e.g. "41 more people"). */
    ellipsisLabel?: React.ReactNode
    labels: TopLearnersLabels
}

/**
 * DashboardPage "Top Learners" card — the presentational half of {@link import("./index").TopLearners}.
 * Maps the global leaderboard into the shared `LeaderboardListCard` (standing header with a
 * rank-driven medal/cup badge over a medal-ranked list). Renders IDENTICALLY to the weekly
 * "League" `LeagueCardContent`; only the trailing slot differs — a quiet `FollowButton` per
 * stranger row, built by the connected file into each row's `trailing`.
 *
 * `LeaderboardListCard` takes no `isSkeleton` of its own, so the loading state is mirrored right
 * here, co-located at the SAME call site — the label + standing header + `SurfaceListCard` rows,
 * matching the real card's shape 1:1 so nothing jumps when it resolves (loading-and-skeleton.md).
 * error → skeleton → empty → content (BLOCK-8): error beats a stale loading flag; empty only once
 * settled. See `tiers/split.md` — the connected `index.tsx` owns the fetch, the follow mutation,
 * and every translated string.
 *
 * @param props - {@link TopLearnersProps}
 */
export const _TopLearners = ({
    isSkeleton = false,
    isEmpty = false,
    onSeeMore,
    standing,
    rows = [],
    selfRow,
    ellipsisLabel,
    labels,
    className,
}: TopLearnersProps) => {
    if (!isSkeleton && isEmpty) {
        return (
            <AsyncContentEmpty
                identity={{ tier: "block", component: "TopLearners" }}
                icon={TrophyIcon}
                title={labels.noLeadersTitle}
                description={labels.noLeadersDescription}
            />
        )
    }

    if (isSkeleton) {
        // Hoisted so outer sibling-stack is not scanned as owning nested align decisions.
        const skeletonItems = [
            () => <Skeleton.Typography type="body-sm" width="1/3" />,
            () => (
                <StackH gap={3} principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                    align="center" items={[
                        () => <Skeleton className="size-12 shrink-0 rounded-xl" />,
                        () => (
                            <StackV gap={1} principle="name-handle"
                                explain="Display name with handle — not title-subtitle, because the second line is an identity handle rather than a subtitle."
                                classNames={["min-w-0", "flex-1"]} items={[
                                    () => <Skeleton.Typography type="body-sm" width="1/2" />,
                                    () => <Skeleton.Typography type="body-xs" width="1/3" />,
                                ]} />
                        ),
                    ]} />
            ),
            () => (
                <SurfaceListCard bordered>
                    {Array.from({ length: SKELETON_ROW_COUNT }, (_row, index) => (
                        <SurfaceListCardItem key={index}>
                            <StackH gap={3} principle="content-row"
                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                align="center" items={[
                                    () => <Skeleton className="h-3 w-6 shrink-0 rounded-sm" />,
                                    () => <Skeleton.Avatar size="sm" />,
                                    () => <Skeleton.Typography type="body-sm" width="1/2" className="min-w-0 flex-1" />,
                                    () => <Skeleton className="h-3 w-10 shrink-0 rounded-sm" />,
                                    () => <Skeleton className="h-8 w-24 shrink-0 rounded-xl" />,
                                ]} />
                        </SurfaceListCardItem>
                    ))}
                </SurfaceListCard>
            ),
        ]
        return (
            <StackV
                gap={3}
                principle="sibling-stack"
                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                identity={{ tier: "block", component: "TopLearners" }}
                items={skeletonItems}
            />
        )
    }

    return (
        <LeaderboardListCard
            className={className}
            title={labels.title}
            onSeeMore={onSeeMore}
            seeMoreLabel={labels.seeMoreLabel}
            standing={standing}
            rows={rows}
            selfRow={selfRow}
            ellipsisLabel={ellipsisLabel}
            meLabel={labels.meLabel}
        />
    )
}

"use client"

import React, {
    useCallback,
    useState,
} from "react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import {
    FollowButton,
} from "@/components/blocks/community/FollowButton"
import {
    pathConfig,
} from "@/resources/path"
import {
    fromGlobalId,
} from "@/modules/utils/globalId"
import type { LeaderboardRow } from "@/components/blocks/dashboard/LeaderboardListCard"
import { useMutateSetFollowSwr } from "@/hooks/swr/api/graphql/mutations/useMutateSetFollowSwr"
import { useQueryGlobalLeaderboardSwr } from "@/hooks/swr/api/graphql/queries/useQueryGlobalLeaderboardSwr"
import { useAppSelector } from "@/redux/hooks"
import { _TopLearners } from "./component"

/** How many leaders to show. */
export const TOP_N = 5

/** Props for {@link TopLearners}. */
export type TopLearnersProps = Record<string, never>
/**
 * DashboardPage "Top Learners" card — the CONNECTED half: fetches the global leaderboard, owns the
 * follow mutation (rows stay presentational), resolves the viewer's rank-relative slice (top-N +
 * pinned self-row), and hands the resolved shape + every translated label to the presentational
 * {@link _TopLearners}. See `tiers/split.md`.
 *
 * @param props - optional root class name (placement only)
 */
export const TopLearners = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const { data, isLoading } = useQueryGlobalLeaderboardSwr()
    const me = useAppSelector((state) => state.user.user)
    // owns the follow mutation; FollowButton rows stay presentational
    const { trigger: triggerSetFollow } = useMutateSetFollowSwr()
    // globalIds the viewer follows from this card (optimistic) + in-flight set
    const [followed, setFollowed] = useState<Set<string>>(new Set())
    const [pending, setPending] = useState<Set<string>>(new Set())

    const isMine = (username: string | null) => Boolean(me?.username) && username === me?.username

    /**
     * Toggle follow/unfollow. The leaderboard exposes each user as an OPAQUE global
     * id, but `setFollow` wants the raw `users.id` — decode it first. Flips the row
     * optimistically on success.
     */
    const onToggleFollow = useCallback(
        async (globalId: string) => {
            const rawId = fromGlobalId(globalId)?.id ?? globalId
            const currentlyFollowing = followed.has(globalId)
            setPending((current) => new Set(current).add(globalId))
            try {
                const result = await triggerSetFollow({
                    userId: rawId,
                    follow: !currentlyFollowing,
                })
                if (result?.data?.setFollow?.success) {
                    setFollowed((current) => {
                        const next = new Set(current)
                        if (currentlyFollowing) {
                            next.delete(globalId)
                        } else {
                            next.add(globalId)
                        }
                        return next
                    })
                }
            } finally {
                setPending((current) => {
                    const next = new Set(current)
                    next.delete(globalId)
                    return next
                })
            }
        },
        [followed, triggerSetFollow],
    )

    // first load, nothing in hand → shimmer (loading-and-skeleton.md §2)
    const isSkeleton = data === null || data === undefined || isLoading
    // empty (after load) when the board has no entries
    const isEmpty = !data || data.entries.length === 0

    /** Open the full leaderboard page. */
    const onSeeMore = useCallback(
        () => router.push(pathConfig().locale(locale).league().build()),
        [router, locale],
    )

    // viewer below the shown slice → pin a self-row after an ellipsis
    const shown = data ? data.entries.slice(0, TOP_N) : []
    const viewerInTop = shown.some((entry) => isMine(entry.username))
    const showSelfRow = Boolean(data) && !viewerInTop

    /** Map a leaderboard entry → a normalised {@link LeaderboardRow} (follow trailing). */
    const toRow = (entry: NonNullable<typeof data>["entries"][number]): LeaderboardRow => {
        const mine = isMine(entry.username)
        return {
            key: entry.userGlobalId,
            rank: entry.rank,
            username: entry.username,
            avatar: entry.avatar,
            valueLabel: t("DashboardPage.league.points", { count: entry.points }),
            isMe: mine,
            profileHref: pathConfig().locale(locale).profile(entry.username ?? undefined).build(),
            trailing: mine ? undefined : (
                <FollowButton
                    quiet
                    following={followed.has(entry.userGlobalId)}
                    isPending={pending.has(entry.userGlobalId)}
                    onToggle={() => void onToggleFollow(entry.userGlobalId)}
                />
            ),
        }
    }

    // standing header + self row + ellipsis are only meaningful once `data` has settled
    const standing = data ? {
        rank: data.myRank,
        primary: t("DashboardPage.league.globalRankLine", { rank: data.myRank }),
        secondary: t("DashboardPage.league.points", { count: data.myPoints }),
    } : undefined

    const selfRow: LeaderboardRow | undefined = data && showSelfRow ? {
        key: "self",
        rank: data.myRank,
        username: me?.username ?? null,
        avatar: me?.avatar,
        valueLabel: t("DashboardPage.league.points", { count: data.myPoints }),
        isMe: true,
    } : undefined

    const ellipsisLabel = data && data.myRank - TOP_N - 1 > 0
        ? t("DashboardPage.league.othersCount", { count: data.myRank - TOP_N - 1 })
        : undefined

    return (
        <_TopLearners
            isSkeleton={isSkeleton}
            isEmpty={isEmpty}
            onSeeMore={onSeeMore}
            standing={standing}
            rows={shown.map(toRow)}
            selfRow={selfRow}
            ellipsisLabel={ellipsisLabel}
            labels={{
                title: t("DashboardPage.community.topLearners.title"),
                seeMoreLabel: t("DashboardPage.community.topLearners.seeMore"),
                noLeadersTitle: t("DashboardPage.community.topLearners.noLeadersTitle"),
                noLeadersDescription: t("DashboardPage.community.topLearners.noLeadersDescription"),
                meLabel: t("DashboardPage.league.you"),
            }}
        />
    )
}

