import React from "react"
import {
    VideoCameraIcon,
} from "@phosphor-icons/react"
import { AsyncContentError } from "@/components/composites/async/AsyncContent"
import { SectionCard } from "@/components/blocks/cards/SectionCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Box } from "@/components/frames/Box"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { Typography } from "@/components/atoms/text/Typography"

/** How many upcoming sessions to list (the soonest plus a few more). */
export const MAX_ROWS = 3

/** One resolved upcoming-livestream row, already localized by the connected `UpcomingLivestreamCard`. */
export interface UpcomingLivestreamCardSession {
    /** Stable row key — a course can carry more than one upcoming session. */
    key: string
    /** Row title — the session title, falling back to the course title. */
    title: string
    /** Row subtitle — the course title, shown only when the title above is the session's own. */
    subtitle?: string
    /** Already-formatted relative countdown ("in Nd Nh" / "in Nh Nm" / "now"). */
    relativeLabel: string
    /** Already-formatted absolute date, in the viewer's locale. */
    dateLabel: string
    /** Course page to navigate to on press. */
    href: string
}

/** All display text, already localized by the connected `UpcomingLivestreamCard`. */
export interface UpcomingLivestreamCardLabels {
    /** Card header title. */
    title: string
    /** Error-branch title. */
    errorTitle: string
    /** Error-branch retry button label. */
    retry: string
}

/** Props for {@link _UpcomingLivestreamCard} — presentational; all data resolved, no fetch/store/i18n. */
export interface UpcomingLivestreamCardProps {
    /** First load, nothing in hand → the whole row list shimmers in place. Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with nothing upcoming → the card hides itself entirely (no emptyContent — matches the sibling right-rail widgets, e.g. `WhoToFollow`). */
    isEmpty?: boolean
    /** Truthy → the error message (beats loading + empty). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler — paired with `labels.retry` to show a retry button on the error branch. */
    onRetry?: () => void
    /** The soonest few sessions, already sorted, capped, and formatted. */
    sessions?: Array<UpcomingLivestreamCardSession>
    labels: UpcomingLivestreamCardLabels
}

/**
 * Right-rail card surfacing the viewer's next live sessions across enrolled courses
 * (soonest first), so a scheduled stream is visible from the home surface instead of
 * buried in a course page — the presentational half of `UpcomingLivestreamCard`. The
 * soonest session leads with a relative countdown ("in Nd Nh"); a short list of the
 * next few follows. Three states in the fixed order error → loading → empty →
 * content (BLOCK-8): `error` falls to the shared `AsyncContentError` frame, `isEmpty`
 * hides the card (no emptyContent, matching the sibling right-rail widgets that
 * self-hide rather than render an empty state), and otherwise the row list renders —
 * while shimmering, `Skeleton.ListRow` placeholders keep the SAME `SectionCard` +
 * `SurfaceCardList` shape so the box neither shrinks nor jumps when data arrives
 * (loading-and-skeleton.md). See `tiers/split.md` — the connected `index.tsx` owns
 * the fetch and i18n.
 *
 * @param props - {@link UpcomingLivestreamCardProps}
 */
export const _UpcomingLivestreamCard = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    sessions = [],
    labels,
}: UpcomingLivestreamCardProps) => {
    if (error) {
        return <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retry} />
    }
    if (!isSkeleton && isEmpty) {
        return null
    }

    const skeletonItems: Array<SurfaceCardListItem> = Array.from(
        { length: MAX_ROWS },
        (_unused, index) => ({
            key: `skeleton-${index}`,
            content: () => (
                <Box
                    principle="row-pad"
                    explain="Row content inset — not cell-pad, because this pads a horizontal content row rather than a dense table cell."
                >
                    <Skeleton.ListRow withSubtitle />
                </Box>
            ),
        }),
    )

    const sessionItems: Array<SurfaceCardListItem> = sessions.map((session) => ({
        key: session.key,
        leading: () => <IconTile icon={<VideoCameraIcon />} tone="accent" size="sm" />,
        title: session.title,
        subtitle: session.subtitle,
        meta: () => (
            <Typography
                size="xs"
                weight="medium"
                color="accent-soft"
                text={`${session.relativeLabel} · ${session.dateLabel}`}
            />
        ),
        href: session.href,
    }))

    return (
        <SectionCard
            icon={() => <VideoCameraIcon className="size-5 text-accent-soft-foreground" />}
            title={labels.title}
        >
            <SurfaceCardList
                variant="nested"
                items={isSkeleton ? skeletonItems : sessionItems}
            />
        </SectionCard>
    )
}

"use client"

import React, {
    useMemo,
} from "react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    pathConfig,
} from "@/resources/path"
import { useQueryMyUpcomingLivestreamsSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyUpcomingLivestreamsSwr"
import {
    _UpcomingLivestreamCard,
    MAX_ROWS,
    type UpcomingLivestreamCardSession,
} from "./component"

/**
 * Right-rail card surfacing the viewer's next live sessions across enrolled
 * courses (soonest first) — the CONNECTED half. Self-fetches its own leaf query,
 * resolves the relative countdown + locale date for each row, and hands the
 * result to the presentational `_UpcomingLivestreamCard`. See `tiers/split.md`.
 */
export const UpcomingLivestreamCard = () => {
    const t = useTranslations()
    const locale = useLocale()
    const { data, isLoading, error, mutate } = useQueryMyUpcomingLivestreamsSwr()

    /** The soonest few sessions, sorted defensively by start time. */
    const sessions = useMemo(
        () => {
            return [...(data ?? [])]
                .sort(
                    (a, b) => new Date(a.nextStartAt).getTime()
                        - new Date(b.nextStartAt).getTime(),
                )
                .slice(0, MAX_ROWS)
        },
        [
            data,
        ],
    )

    /**
     * A short relative label until `iso` ("in Nd Nh" / "in Nh Nm" / "now"). Past
     * timestamps collapse to "now" since the list only holds upcoming sessions.
     */
    const relativeLabel = (iso: string) => {
        const remaining = new Date(iso).getTime() - Date.now()
        if (remaining <= 0) {
            return t("DashboardPage.upcomingLive.now")
        }
        const days = Math.floor(remaining / 86_400_000)
        const hours = Math.floor((remaining % 86_400_000) / 3_600_000)
        const minutes = Math.floor((remaining % 3_600_000) / 60_000)
        if (days > 0) {
            return t("DashboardPage.upcomingLive.inDays", {
                days,
                hours,
            })
        }
        if (hours > 0) {
            return t("DashboardPage.upcomingLive.inHours", {
                hours,
                minutes,
            })
        }
        return t("DashboardPage.upcomingLive.inMinutes", {
            minutes,
        })
    }

    /** Sessions resolved into the presentational row shape (relative + absolute labels, course link). */
    const sessionRows: Array<UpcomingLivestreamCardSession> = sessions.map((session) => ({
        key: `${session.courseGlobalId}-${session.nextStartAt}`,
        title: session.sessionTitle ?? session.courseTitle,
        subtitle: session.sessionTitle ? session.courseTitle : undefined,
        relativeLabel: relativeLabel(session.nextStartAt),
        dateLabel: new Date(session.nextStartAt).toLocaleDateString(locale),
        href: pathConfig().locale(locale).course(session.courseDisplayId).build(),
    }))

    return (
        <_UpcomingLivestreamCard
            // first load, nothing in hand → shimmer; settled (data OR error) stops it (loading-and-skeleton.md)
            isSkeleton={data === undefined && isLoading}
            isEmpty={sessions.length === 0}
            // only a settled fetch error (nothing in hand) reaches the block
            error={data === undefined ? error : undefined}
            onRetry={() => { void mutate() }}
            sessions={sessionRows}
            labels={{
                title: t("DashboardPage.upcomingLive.title"),
                errorTitle: t("DashboardPage.loadError"),
                retry: t("DashboardPage.retry"),
            }}
        />
    )
}

"use client"

import React from "react"
import {
    useTranslations,
} from "next-intl"
import type {
    WithClassNames,
} from "@/modules/types/base/class-name"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { SurfaceListCard, SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import { StackH, StackV } from "@/components/frames/Stack"

/** Recent-finisher rows shown while the weekly challenge loads. */
const SKELETON_ROW_COUNT = 3

/** Props for {@link WeeklyChallengeCardSkeleton}. */
export type WeeklyChallengeCardSkeletonProps = WithClassNames<undefined>

/**
 * Loading placeholder for {@link import("../").WeeklyChallengeCard}: mirrors the real
 * "Weekly challenge" card — the same `LabeledCard` (label + flame) wrapping the title,
 * the countdown + status row, the passer count, and a short finisher list — so the
 * card does not pop in / jump when the weekly-challenge query resolves.
 *
 * @param props - {@link WeeklyChallengeCardSkeletonProps}
 */
export const WeeklyChallengeCardSkeleton = () => {
    const t = useTranslations()
    return (
        <LabeledCard
            label={t("weeklyChallenge.title")}

        >
            <StackV gap={3} principle="sibling-stack"
                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                items={[
                    () => <Skeleton.Typography type="body-sm" width="2/3" />,
                    () => (
                        <StackH gap={4} principle="content-row"
                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                            justify="between" align="center" items={[
                                () => <Skeleton.Typography type="body-xs" width="1/3" />,
                                () => <Skeleton className="h-6 w-16 shrink-0 rounded-full" />,
                            ]} />
                    ),
                    () => <Skeleton.Typography type="body-xs" width="1/4" />,
                    () => (
                        <SurfaceListCard bordered>
                            {Array.from({ length: SKELETON_ROW_COUNT }).map((_row, index) => (
                                <SurfaceListCardItem key={index}>
                                    <StackH gap={4} principle="content-row"
                                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                        align="center" items={[
                                            () => <Skeleton.Avatar size="sm" />,
                                            () => <Skeleton.Typography type="body-sm" width="1/2" className="min-w-0 flex-1" />,
                                            () => <Skeleton className="h-3 w-12 shrink-0 rounded-sm" />,
                                        ]} />
                                </SurfaceListCardItem>
                            ))}
                        </SurfaceListCard>
                    ),
                ]} />
        </LabeledCard>
    )
}

import React from "react"
import {
    AsyncContentEmpty,
    AsyncContentError,
} from "@/components/composites/async/AsyncContent"
import {
    Button,
} from "@/components/atoms/buttons/Button"
import {
    Chip,
} from "@/components/atoms/chips/Chip"
import {
    Typography,
} from "@/components/atoms/text/Typography"
import {
    Skeleton,
} from "@/components/blocks/skeleton/Skeleton"
import {
    LabeledCard,
} from "@/components/blocks/cards/LabeledCard"
import {
    SurfaceListCard,
    SurfaceListCardItem,
    SurfaceListCardRow,
} from "@/components/blocks/cards/SurfaceListCard"
import {
    UserAvatar,
} from "@/components/blocks/identity/UserAvatar"
import {
    EntityToken,
} from "@/components/blocks/entity/EntityToken"
import {
    StackH,
    StackV,
} from "@/components/frames/Stack"
import type {
    WithClassNames,
} from "@/modules/types/base/class-name"

/** How many placeholder finisher rows the co-located skeleton shows while shimmering. */
const SKELETON_ROW_COUNT = 3

/** All display text, already localized by the connected `WeeklyChallengeCard`; a story passes i18n keys. */
export interface WeeklyChallengeCardLabels {
    /** Section title, shown outside the card in every state. */
    title: string
    errorTitle: string
    retry: string
    emptyTitle: string
    emptyDescription: string
    /** "Ends in {days}d {hours}h" — already interpolated. Set whenever real data is in hand. */
    endsIn?: string
    passed: string
    /** "Claim +{count} coins" — already interpolated with the reward amount. */
    claimReward: string
    tryNow: string
    /** "{count} learners passed" — already interpolated. */
    passedCount: string
}

/** One leaderboard row, already localized by the connected file (the "x ago" label). */
export interface WeeklyChallengeCardLeaderboardEntry {
    username: string
    avatar: string | null
    relativeLabel: string
}

/** Props for {@link _WeeklyChallengeCard} — presentational; all data resolved, no fetch/store/i18n. */
export interface WeeklyChallengeCardProps extends WithClassNames<undefined> {
    /** First load, nothing in hand → the whole tree shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with no active event → the empty message, still inside the labeled card frame. */
    isEmpty?: boolean
    /** Truthy → the error message (beats loading + empty). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler — paired with `labels.retry` on the error branch. */
    onRetry?: () => void
    /** Opaque id of the featured challenge (routes the title/CTA tokens). */
    challengeGlobalId?: string | null
    /** Title of the featured challenge — raw content, not translated. */
    challengeTitle?: string
    /** Whether the viewer already passed this week's challenge. */
    viewerPassed?: boolean
    /** Whether the viewer already claimed the reward for passing. */
    claimed?: boolean
    /** `true` while the claim mutation is in flight (spinner replaces the claim button's glyph). */
    isClaiming?: boolean
    onClaim?: () => void
    /** Recent finishers, already sliced and localized by the connected file. */
    leaderboard?: Array<WeeklyChallengeCardLeaderboardEntry>
    labels: WeeklyChallengeCardLabels
}

/**
 * "This week's challenge" section — the presentational half of {@link import("./index").WeeklyChallengeCard}:
 * title (routable), a live countdown, the viewer's pass status, total pass count, and a short
 * leaderboard of recent finishers. Owns its own `LabeledCard` frame (label outside), which STAYS
 * MOUNTED across every state — the error and empty messages render INSIDE it instead of the section
 * self-hiding, so the DashboardPage slot never disappears entirely. Three states in the fixed order
 * error → loading → empty → content: `error` falls to the shared `AsyncContentError` frame, `isEmpty`
 * to `AsyncContentEmpty`, and otherwise the real tree renders with `isSkeleton` threaded to every leaf
 * that supports it (loading-and-skeleton.md). `EntityToken`/`UserAvatar`/`SurfaceListCardRow` take no
 * `isSkeleton` of their own, so the leaderboard rows are mirrored with `Skeleton.*` pieces in place
 * while shimmering instead (see `missingSkeletonSupport`). See `tiers/split.md` — the connected
 * `index.tsx` owns the fetch and i18n.
 *
 * @param props - {@link WeeklyChallengeCardProps}
 */
export const _WeeklyChallengeCard = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    challengeGlobalId,
    challengeTitle,
    viewerPassed = false,
    claimed = false,
    isClaiming = false,
    onClaim,
    leaderboard = [],
    labels,
}: WeeklyChallengeCardProps) => {
    /** The card's body — error beats a stale loading flag; empty only once settled (BLOCK-8). */
    const body = () => {
        if (error) {
            return (
                <AsyncContentError
                    title={labels.errorTitle}
                    onRetry={onRetry}
                    retryLabel={labels.retry}
                />
            )
        }
        if (!isSkeleton && isEmpty) {
            return (
                <AsyncContentEmpty
                    title={labels.emptyTitle}
                    description={labels.emptyDescription}
                />
            )
        }

        // ROWS — while shimmering, placeholder rows keep the SAME count shape (loading-and-skeleton.md
        // §1). `SurfaceListCardRow` wraps a plain (non-skeleton-aware) `Typography` internally and
        // `UserAvatar` takes no `isSkeleton` either, so the placeholder rows are built from
        // `SurfaceListCardItem` + `Skeleton.*` pieces sized to match the real row instead.
        const showLeaderboard = isSkeleton || leaderboard.length > 0

        // Hoisted so outer sibling-stack is not scanned as owning nested justify.
        const challengeItems = [
            () => (isSkeleton
                ? <Skeleton.Typography type="body-sm" width="2/3" />
                : <EntityToken globalId={challengeGlobalId} label={challengeTitle ?? ""} />),
            () => (
                <StackH gap={3} principle="flex-action"
                    explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                    justify="between" items={[
                        () => (
                            <Typography
                                size="xs"
                                color="muted"
                                text={labels.endsIn ?? ""}
                                isSkeleton={isSkeleton}
                                classNames={isSkeleton ? ["w-1/3"] : undefined}
                            />
                        ),
                        () => (isSkeleton
                            ? <Skeleton className="h-6 w-16 shrink-0 rounded-full" />
                            : viewerPassed
                                ? (claimed
                                    ? <Chip tone="success" text={labels.passed} />
                                    : (
                                        <Button
                                            variant="primary"
                                            size="sm"
                                            isPending={isClaiming}
                                            onPress={onClaim}
                                            label={labels.claimReward}
                                        />
                                    ))
                                : <EntityToken globalId={challengeGlobalId} label={labels.tryNow} />),
                    ]} />
            ),
            () => (
                <Typography
                    size="xs"
                    color="muted"
                    text={labels.passedCount}
                    isSkeleton={isSkeleton}
                    classNames={isSkeleton ? ["w-1/4"] : undefined}
                />
            ),
            ...(showLeaderboard ? [() => (
                <SurfaceListCard bordered>
                    {isSkeleton
                        ? Array.from({ length: SKELETON_ROW_COUNT }, (_row, index) => (
                            <SurfaceListCardItem key={index}>
                                <StackH gap={3} principle="content-row"
                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                    items={[
                                        () => <Skeleton className="size-6 shrink-0 rounded-full" />,
                                        () => <Skeleton.Typography type="body-sm" width="1/2" className="min-w-0 flex-1" />,
                                        () => <Skeleton className="h-3 w-12 shrink-0 rounded-sm" />,
                                    ]} />
                            </SurfaceListCardItem>
                        ))
                        : leaderboard.map((entry) => (
                            <SurfaceListCardRow
                                key={entry.username}
                                leading={() => (
                                    <UserAvatar
                                        className="size-6 shrink-0"
                                        username={entry.username}
                                        avatar={entry.avatar}
                                        seed={entry.username}
                                    />
                                )}
                                title={entry.username}
                                trailing={() => (
                                    <Typography
                                        size="xs"
                                        color="muted"
                                        text={entry.relativeLabel}
                                        classNames={["shrink-0"]}
                                    />
                                )}
                            />
                        ))}
                </SurfaceListCard>
            )] : []),
        ]

        return (
            <StackV gap={3} principle="sibling-stack"
                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                items={challengeItems}  />
        )
    }

    return (
        <LabeledCard
            identity={{ tier: "block", component: "WeeklyChallengeCard" }}
            label={labels.title}

        >
            {body()}
        </LabeledCard>
    )
}

"use client"

import React, {
    useMemo,
    useState,
} from "react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import { useQueryWeeklyChallengeSwr } from "@/hooks/swr/api/graphql/queries/useQueryWeeklyChallengeSwr"
import { useMutateClaimWeeklyChallengeRewardSwr } from "@/hooks/swr/api/graphql/mutations/useMutateClaimWeeklyChallengeRewardSwr"
import { useGraphQLWithToast } from "@/modules/toast/hooks"
import { _WeeklyChallengeCard } from "./component"

/** How many leaderboard rows to show before truncating. */
const TOP_ROWS = 5

/** Props for {@link WeeklyChallengeCard}. */
export type WeeklyChallengeCardProps = Record<string, never>
/**
 * "This week's challenge" section — the CONNECTED half: it self-fetches the featured
 * weekly-challenge event, computes the countdown/claim state and every "x ago" label, resolves
 * every display string (incl. interpolation), and hands them to the presentational
 * {@link _WeeklyChallengeCard}. See `design/storybook/architecture/split.md`.
 *
 * @param props - optional className for the root element.
 */
export const WeeklyChallengeCard = () => {
    const t = useTranslations()
    const locale = useLocale()
    const challengeSwr = useQueryWeeklyChallengeSwr()
    const { data } = challengeSwr
    const { trigger: triggerClaimReward } = useMutateClaimWeeklyChallengeRewardSwr()
    const runGraphQL = useGraphQLWithToast()
    const [isClaiming, setIsClaiming] = useState(false)

    /** Claim the weekly-challenge coin reward, then revalidate. */
    const onClaim = async () => {
        setIsClaiming(true)
        try {
            const ok = await runGraphQL(async () => {
                const result = await triggerClaimReward()
                const env = result?.data?.claimWeeklyChallengeReward
                if (!env) {
                    throw new Error(t("weeklyChallenge.claimError"))
                }
                return env
            })
            if (ok) {
                await challengeSwr.mutate()
            }
        } finally {
            setIsClaiming(false)
        }
    }

    /** Days/hours left until the event closes (computed from `weekEndAt`). */
    const countdown = useMemo(
        () => {
            if (!data) {
                return null
            }
            const remaining = Math.max(
                0,
                new Date(data.weekEndAt).getTime() - Date.now(),
            )
            return {
                days: Math.floor(remaining / 86_400_000),
                hours: Math.floor((remaining % 86_400_000) / 3_600_000),
            }
        },
        [
            data,
        ],
    )

    /** Locale-aware relative-time formatter for the "passed N ago" labels. */
    const relativeFormatter = useMemo(
        () => new Intl.RelativeTimeFormat(locale, { numeric: "auto" }),
        [
            locale,
        ],
    )

    /** Render a coarse "x ago" label for an ISO timestamp. */
    const formatRelative = (iso: string) => {
        const diffMs = new Date(iso).getTime() - Date.now()
        const minutes = Math.round(diffMs / 60_000)
        if (Math.abs(minutes) < 60) {
            return relativeFormatter.format(minutes, "minute")
        }
        const hours = Math.round(minutes / 60)
        if (Math.abs(hours) < 24) {
            return relativeFormatter.format(hours, "hour")
        }
        return relativeFormatter.format(Math.round(hours / 24), "day")
    }

    // recent finishers — sliced + localized here, so the presentational half never resolves i18n
    const leaderboard = (data?.leaderboard.slice(0, TOP_ROWS) ?? []).map((entry) => ({
        username: entry.username,
        avatar: entry.avatar,
        relativeLabel: formatRelative(entry.passedAt),
    }))

    return (
        <_WeeklyChallengeCard
            // first load, nothing in hand → shimmer; settled (data OR error) stops it (loading-and-skeleton.md)
            isSkeleton={challengeSwr.isLoading && !data}
            // error beats loading + empty; only a settled fetch error (nothing in hand) reaches the block
            error={!data ? challengeSwr.error : undefined}
            onRetry={() => { void challengeSwr.mutate() }}
            // settled with no active event
            isEmpty={!data}
            challengeGlobalId={data?.challengeGlobalId}
            challengeTitle={data?.title}
            viewerPassed={data?.viewerPassed}
            claimed={data?.claimed}
            isClaiming={isClaiming}
            onClaim={() => { void onClaim() }}
            leaderboard={leaderboard}
            labels={{
                title: t("weeklyChallenge.title"),
                errorTitle: t("weeklyChallenge.errorTitle"),
                retry: t("weeklyChallenge.retry"),
                emptyTitle: t("weeklyChallenge.emptyTitle"),
                emptyDescription: t("weeklyChallenge.emptyDescription"),
                endsIn: countdown ? t("weeklyChallenge.endsIn", {
                    days: countdown.days,
                    hours: countdown.hours,
                }) : undefined,
                passed: t("weeklyChallenge.passed"),
                claimReward: t("weeklyChallenge.claimReward", {
                    count: data?.coinReward ?? 0,
                }),
                tryNow: t("weeklyChallenge.tryNow"),
                passedCount: t("weeklyChallenge.passedCount", {
                    count: data?.passedCount ?? 0,
                }),
            }}
        />
    )
}

import React from "react"
import { AsyncContentError } from "@/components/composites/async/AsyncContent"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"
import { StatGridCard, type StatGridCardItem } from "@/components/composites/stats/StatGridCard"
import { Typography } from "@/components/atoms/text/Typography"
import { StackV } from "@/components/frames/Stack"
import { KPI_ICON_MAP } from "@/modules/utils/weekly-goals-map"
import type { KpiKey } from "@/modules/api/graphql/queries/types/my-kpis"

/** One weekly-metric row, already resolved by the connected {@link import("./index").WeeklyGoals}. */
export interface WeeklyGoalsItem {
    /** Which weekly metric this row is. */
    key: KpiKey
    /** Already-localized metric label. */
    label: string
    /** This week's value so far. */
    current: number
    /** Effective target — the learner's custom goal, or the sensible default. */
    target: number
    /** Already-localized coin-reward hint; omitted when no target is set server-side. */
    coinRewardText?: string
    /** `true` → this metric's reward can be claimed right now. */
    canClaim: boolean
}

/** All display text, already localized by the connected `WeeklyGoals`; a story passes i18n keys. */
export interface WeeklyGoalsLabels {
    /** Title on the error branch. */
    errorTitle: string
    /** Retry-button label, paired with `onRetry`. */
    retry: string
}

/** Props for {@link _WeeklyGoals} — presentational; all data resolved, no fetch/store/i18n. */
export interface WeeklyGoalsProps {
    /** First load, nothing in hand → the whole tree shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Truthy → the error message (beats a stale loading flag). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler, paired with `labels.retry` to show a retry button on the error branch. */
    onRetry?: () => void
    /** All six weekly metrics, in display order. No empty state — this is always the fixed six-metric set. */
    items: Array<WeeklyGoalsItem>
    /** The composite summary sentence (percent/completed/total, plus the reset countdown when known), already interpolated. */
    summaryText?: string
    labels: WeeklyGoalsLabels
}

/**
 * One metric cell's content: a `ProgressMeter` carrying the icon+label / ratio row in its own
 * `leading`/`trailing` slots (same idiom as the sibling `AiQuotaCard` block), then an optional
 * coin-reward hint below it.
 */
const renderGoalCell = (item: WeeklyGoalsItem, isSkeleton: boolean) => (
    <StackV gap={3} principle="sibling-stack"
        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
        isSkeleton={isSkeleton} items={[
        // ATOM GAP: `ProgressMeter`'s discriminated `isSkeleton` union needs a literal branch
        // to narrow at compile time — a runtime boolean can't satisfy it directly.
            () => (isSkeleton
                ? (
                    <ProgressMeter
                        isSkeleton
                        leading={() => <Typography size="sm" prefixIcon={KPI_ICON_MAP[item.key]} isSkeleton text={item.label} />}
                        trailing={() => <Typography size="xs" color="muted" tabularNums isSkeleton text={`${item.current}/${item.target}`} />}
                    />
                )
                : (
                    <ProgressMeter
                        value={item.current}
                        max={item.target > 0 ? item.target : 1}
                        color="accent"
                        leading={() => <Typography size="sm" prefixIcon={KPI_ICON_MAP[item.key]} text={item.label} />}
                        trailing={() => <Typography size="xs" color="muted" tabularNums text={`${item.current}/${item.target}`} />}
                    />
                )),
            // coin-reward hint — only once a REAL target is set server-side, and never while
            // shimmering (unknown yet whether this row will show one — same as the loaded shape
            // it mirrors, `WeeklyGoalsProps.items` never carries a reward while `isSkeleton`).
            ...(!isSkeleton && item.coinRewardText ? [() => (
                <Typography
                    size="xs"
                    color={item.canClaim ? "accent-soft" : "muted"}
                    text={item.coinRewardText}
                />
            )] : []),
        ]} />
)

/**
 * "Weekly goals" content — the presentational half of {@link import("./index").WeeklyGoals}: the
 * composite weekly-goal summary + a per-metric breakdown (lessons / study-days / challenges /
 * coding / flashcards / milestones), each with a progress meter against its effective target.
 * Content only — the caller's `LabeledCard` frames it.
 *
 * `error` beats a stale loading flag (BLOCK-8): it falls to the shared `AsyncContentError` frame,
 * otherwise the fixed six-metric tree renders with `isSkeleton` threaded to every leaf so the
 * shimmer mirrors the loaded shape (loading-and-skeleton.md). No `isEmpty` state — `items` is
 * always the fixed six-metric set, so there is nothing to be empty. See `tiers/split.md` — the
 * connected `index.tsx` owns the fetch and i18n.
 *
 * @param props - {@link WeeklyGoalsProps}
 */
export const _WeeklyGoals = ({
    isSkeleton = false,
    error,
    onRetry,
    items,
    summaryText,
    labels,
}: WeeklyGoalsProps) => {
    if (error) {
        return <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retry} />
    }

    const gridItems: Array<StatGridCardItem> = items.map((item) => ({
        key: item.key,
        content: () => renderGoalCell(item, isSkeleton),
    }))

    return (
        <StackV gap={3} isSkeleton={isSkeleton} identity={{ tier: "block", component: "WeeklyGoals" }} items={[
            () => <Typography size="sm" weight="medium" isSkeleton={isSkeleton} text={summaryText} />,
            () => <StatGridCard items={gridItems} />,
        ]} />
    )
}

"use client"

import React, {
    useMemo,
} from "react"
import {
    useTranslations,
} from "next-intl"
import {
    _WeeklyGoals,
    type WeeklyGoalsItem,
} from "./component"
import {
    DEFAULT_KPI_TARGETS,
    KPI_ORDER,
} from "@/modules/utils/weekly-goals-map"
import { useQueryMyKpisSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyKpisSwr"
import type { KpiKey, QueryKpiItemData } from "@/modules/api/graphql/queries/types/my-kpis"

/**
 * "Weekly goals" content — the CONNECTED half of {@link _WeeklyGoals}: self-fetches the
 * viewer's weekly KPI snapshot, folds it against the sensible per-metric defaults so the
 * summary + meters always track this week's activity (even before a custom goal is set),
 * resolves every label, and hands the resolved rows to the presentational `_WeeklyGoals`.
 * Content only — the parent {@link import("@/components/blocks").LabeledCard} frames it.
 * See `tiers/split.md`.
 */
export const WeeklyGoals = () => {
    const t = useTranslations()
    const {
        data: kpis,
        error,
        mutate,
    } = useQueryMyKpisSwr()

    /** Index KPI items by key for O(1) lookup while building rows in display order. */
    const itemByKey = useMemo(
        () => {
            const map = new Map<KpiKey, QueryKpiItemData>()
            for (const item of kpis?.items ?? []) {
                map.set(item.key, item)
            }
            return map
        },
        [
            kpis,
        ],
    )

    /** Days/hours left until the weekly reset (computed from `resetAt`). Mirrors WeeklyBoard. */
    const countdown = useMemo(
        () => {
            if (!kpis) {
                return null
            }
            const remaining = Math.max(0, new Date(kpis.resetAt).getTime() - Date.now())
            return {
                days: Math.floor(remaining / 86_400_000),
                hours: Math.floor((remaining % 86_400_000) / 3_600_000),
            }
        },
        [kpis],
    )

    // composite over EFFECTIVE targets (custom OR default) so the summary + meters
    // always track this week's activity, even before a custom goal is set.
    const composite = useMemo(() => {
        let completed = 0
        let sumCurrent = 0
        let sumTarget = 0
        for (const key of KPI_ORDER) {
            const item = itemByKey.get(key)
            const current = item?.current ?? 0
            const target = item?.target ?? DEFAULT_KPI_TARGETS[key]
            sumTarget += target
            sumCurrent += Math.min(current, target)
            if (current >= target) {
                completed += 1
            }
        }
        return {
            completed,
            total: KPI_ORDER.length,
            percent: sumTarget > 0 ? Math.round((sumCurrent / sumTarget) * 100) : 0,
        }
    }, [itemByKey])

    const items: Array<WeeklyGoalsItem> = KPI_ORDER.map((key) => {
        const item = itemByKey.get(key)
        const current = item?.current ?? 0
        // effective target = the learner's custom goal, or a sensible default
        // (so the meter tracks this week's activity out of the box)
        const target = item?.target ?? DEFAULT_KPI_TARGETS[key]
        return {
            key,
            label: t(`DashboardPage.kpi.labels.${key}`),
            current,
            target,
            // only once a REAL target is set server-side (the client-only default above
            // doesn't persist a floor/reward)
            coinRewardText: item?.coinReward != null
                ? t("DashboardPage.kpi.coinReward", { count: item.coinReward })
                : undefined,
            canClaim: item?.canClaim ?? false,
        }
    })

    const summaryText = `${t("DashboardPage.kpi.summary", {
        percent: composite.percent,
        completed: composite.completed,
        total: composite.total,
    })}${countdown
        ? ` · ${t("DashboardPage.kpi.resetIn", {
            days: countdown.days,
            hours: countdown.hours,
        })}`
        : ""}`

    return (
        <_WeeklyGoals
            // first load, nothing in hand → shimmer; settled (data OR error) stops it (loading-and-skeleton.md)
            isSkeleton={!kpis && !error}
            error={error}
            onRetry={() => { void mutate() }}
            items={items}
            summaryText={summaryText}
            labels={{
                errorTitle: t("DashboardPage.loadError"),
                retry: t("DashboardPage.retry"),
            }}
        />
    )
}

