import React from "react"
import { CaretLeftIcon, CaretRightIcon } from "@phosphor-icons/react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { Button } from "@/components/atoms/buttons/Button"
import { Chip, type ChipTone } from "@/components/atoms/chips/Chip"
import { Spinner } from "@/components/atoms/display/Spinner"
import { Typography } from "@/components/atoms/text/Typography"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Box } from "@/components/frames/Box"
import { Cluster } from "@/components/frames/Cluster"
import { Container } from "@/components/frames/Container"
import { StackH, StackV } from "@/components/frames/Stack"
import { MarkdownContent } from "@/components/blocks/rendering/MarkdownContent"
import { WorkSessionHeader } from "@/components/blocks/navigation/WorkSessionHeader"
import { FlipCard } from "@/components/blocks/cards/FlipCard"
import { RatingBar, type RatingOption } from "@/components/blocks/buttons/RatingBar"
import type { QueryMyDueFlashcardData } from "@/modules/api/graphql/queries/types/my-due-flashcards"

/** HeroUI Chip color per quiz seniority level (mirrors `FlashcardReviewer`). */
const LEVEL_COLOR: Record<string, ChipTone> = {
    junior: "success",
    middle: "warning",
    senior: "danger",
    staff: "accent",
}

/** How many segments the header's progress meter mirrors while shimmering. */
const HEADER_SKELETON_SEGMENT_COUNT = 6

/** How many placeholder chips the level/tag row mirrors while shimmering. */
const SKELETON_CHIP_COUNT = 2

/**
 * A card as rendered in this session — the live "due" shape (carries
 * `nextIntervals`, used for the RatingBar's day-preview hints) OR a card
 * resolved status-agnostically by id during resume (no `nextIntervals` — see
 * `resumeCardsByIdSwr` in the connected `DueReview`). `RatingBar`'s `hint` is
 * already optional, so a card without `nextIntervals` just renders without
 * the preview.
 */
export type DueReviewCard = Omit<QueryMyDueFlashcardData, "nextIntervals"> & {
    nextIntervals?: QueryMyDueFlashcardData["nextIntervals"]
}

/** All display text, already localized by the connected `DueReview`; a story passes i18n keys. */
export interface DueReviewLabels {
    exit: string
    modeTitle: string
    /** Already interpolated for whichever branch is currently rendering (active card OR the finished batch). */
    counter: string
    finish: string
    savingLabel: string
    errorTitle: string
    emptyTitle: string
    emptyDescription: string
    questionLabel: string
    answerLabel: string
    rateHint: string
    rateAria: string
    showAnswer: string
    previous: string
    next: string
}

/** Props for {@link _DueReview} — presentational; all data resolved, no fetch/store/i18n. */
export interface DueReviewProps {
    /** First load, nothing in hand → the whole tree shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with an empty due queue → the empty message. */
    isEmpty?: boolean
    /** Truthy → the error message (beats loading + empty). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler for the error branch. */
    onRetry?: () => void
    /** Leave the session and return to the flashcards home. */
    onBack: () => void

    /** The batch just finished (explicit "Finish" or ran past the last card) — renders the transient "saving" hand-off instead of the reviewer. */
    done: boolean

    /** The card currently shown. Absent only while `isSkeleton`/`done`. */
    card?: DueReviewCard
    /** Already-resolved label for `card.level` (e.g. "Junior") — undefined when the card has no level. */
    levelLabel?: string
    /** Whether the current card's answer is revealed. */
    revealed: boolean
    /** Reveal the current card's answer. */
    onReveal: () => void
    /** True while a grade is in flight — disables the rating bar. */
    reviewing: boolean
    /** SM-2 grade options for the current card, already localized. */
    ratingOptions: Array<RatingOption>
    /** Grade the current card. */
    onRate: (grade: number) => void

    /** 0-indexed position of the card currently viewed. */
    currentIndex: number
    /** Size of the batch being reviewed. */
    totalCount: number
    /** 0-indexed positions graded this session — drives the header's per-segment green. */
    gradedIndexes: ReadonlyArray<number>
    isFirst: boolean
    isLast: boolean
    /** Free-nav jump to any step. */
    onSegmentClick: (position: number) => void
    /** Step back to re-see an earlier card (no re-grade). */
    onPrev: () => void
    /** Step forward without grading. */
    onNext: () => void
    /** End the session now, regardless of position. */
    onFinish: () => void

    labels: DueReviewLabels
}

/**
 * The spaced-repetition (SM-2) review session over the viewer's due cards, drawn
 * across every enrolled course — the presentational half of {@link DueReview}.
 * Four states in the fixed order error → skeleton → empty → content: `error`
 * falls to the shared `AsyncContentError` frame, `isEmpty` to `AsyncContentEmpty`,
 * and otherwise the ONE session tree renders with `isSkeleton` threaded to every
 * leaf that supports it. `WorkSessionHeader`/`FlipCard`/`RatingBar` carry no
 * `isSkeleton` of their own, so their loading state is mirrored minimally with
 * `Skeleton.*`/skeleton-mode atoms right where each sits (loading-and-skeleton.md
 * §1). See `tiers/split.md` — the connected `index.tsx` owns the fetch, the
 * session/resume state machine, and all i18n.
 *
 * @param props - {@link DueReviewProps}
 */
export const _DueReview = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    onBack,
    done,
    card,
    levelLabel,
    revealed,
    onReveal,
    reviewing,
    ratingOptions,
    onRate,
    currentIndex,
    totalCount,
    gradedIndexes,
    isFirst,
    isLast,
    onSegmentClick,
    onPrev,
    onNext,
    onFinish,
    labels,
}: DueReviewProps) => {
    // error beats a stale skeleton flag; empty only once settled (loading-and-skeleton.md §1)
    if (error) {
        return <AsyncContentError title={labels.errorTitle} onRetry={onRetry} />
    }
    if (!isSkeleton && isEmpty) {
        return <AsyncContentEmpty title={labels.emptyTitle} description={labels.emptyDescription} />
    }

    // ── header band — WorkSessionHeader has no `isSkeleton` of its own, so the
    // loading state is a minimal inline mirror, right at this same spot (NOT a
    // separately authored parallel tree) — loading-and-skeleton.md §1.
    const header = isSkeleton ? (
        <Box className="sticky top-16 z-10 border-b border-default bg-surface">
            <StackH
                gap={1}
                padding={{ base: { x: 5, y: 3 }, sm: { x: 6, y: 3 } }}
                principle="pill-pad"
                explain="Pill/chip inset — not control-pad, because this pads a compact badge shape rather than a form control."
                items={[() => (
                    <StackH
                        gap={4}
                        principle="content-row"
                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                        align="center"
                        divider
                        classNames={["w-full"]}
                        items={[
                            () => <Skeleton className="h-4 w-16 rounded" />,
                            () => (
                                <span className="hidden h-5 w-px shrink-0 bg-default @app-sm:block" aria-hidden />
                            ),
                            () => <Skeleton className="hidden h-4 w-24 rounded @app-sm:block" />,
                            () => (
                                <span className="hidden h-5 w-px shrink-0 bg-default @app-sm:block" aria-hidden />
                            ),
                            () => <Skeleton className="h-4 w-20 rounded" />,
                        ]}
                    />
                )]}
            />
            <Box principle="pill-pad" className="px-4 pb-2 @app-sm:px-6"
                explain="Pill/chip inset — not control-pad, because this pads a compact badge shape rather than a form control.">
                <StackH
                    gap={2}
                    classNames={["w-full"]}
                    items={Array.from({ length: HEADER_SKELETON_SEGMENT_COUNT }, (_unused, index) => () => (
                        <Skeleton key={index} className="h-1 flex-1 rounded-full" />
                    ))}
                />
            </Box>
        </Box>
    ) : done ? (
        <WorkSessionHeader
            backLabel={labels.exit}
            onBack={onBack}
            title={labels.modeTitle}
            counter={labels.counter}
            current={totalCount}
            total={totalCount}
        />
    ) : (
        // shared header: WorkSessionHeader (current card's OWN deck as identity +
        // counter + progress segments), same shell as FlashcardReviewer/QuizSession
        // (teacher, 2026-07-11: "sync the UI, both should render the navbar" + "render
        // which deck ... whether it's currently due or not"). Identity changes PER CARD here (a due batch
        // spans multiple decks). `title` disambiguates this mode from FlashcardReviewer/QuizSession
        // sharing the exact same shell (teacher, 2026-07-12: "these two pages are identical"). No confirm
        // modal on back (teacher, 2026-07-09: "why isn't there an early-finish, go-back option"): each
        // grade is saved immediately via `reviewFlashcard`, AND the batch/position itself is persisted
        // too — leaving mid-run loses nothing, resumes exactly where it left off.
        <WorkSessionHeader
            backLabel={labels.exit}
            onBack={onBack}
            title={labels.modeTitle}
            identity={card ? { name: card.deckTitle } : undefined}
            counter={labels.counter}
            // `current` = the VIEWED card (→ accent/pink follows what you're looking at); the
            // green/done state is per-card via `doneSet` so a card graded out of order (free-nav
            // jump-ahead → grade → jump-back) still reads green regardless of the cursor.
            current={currentIndex}
            total={totalCount}
            doneSet={gradedIndexes}
            onSegmentClick={onSegmentClick}
            onFinish={onFinish}
            finishLabel={labels.finish}
        />
    )

    // ── level/tag chip row under the question — placeholder pair while shimmering
    // (SAME row shape, fixed count), the real per-card chips otherwise.
    const chipItems = isSkeleton
        ? Array.from({ length: SKELETON_CHIP_COUNT }, () => () => <Chip isSkeleton tone="default" />)
        : card && (card.level || card.tags.length > 0)
            ? [
                ...(card.level ? [() => <Chip tone={LEVEL_COLOR[card.level as string] ?? "default"} text={levelLabel} />] : []),
                ...card.tags.map((tag) => () => <Chip tone="default" text={tag} />),
            ]
            : []

    // ── body — centered column under the header
    const body = isSkeleton ? (
        <Container size="md" padding={1} body={() => (
            <StackV gap={6} items={[
                () => <Cluster gap={3} items={chipItems} />,
                // the flashcard — FlipCard's LabeledCard (label OUTSIDE + Card)
                () => (
                    <StackV gap={4} items={[
                        () => <Typography isSkeleton size="xs" classNames={["w-1/4"]} />,
                        () => (
                            <SurfaceCard isSkeleton body={() => (
                                <StackV gap={4} items={[
                                    () => <Typography isSkeleton size="base" classNames={["w-3/4"]} />,
                                    () => <Typography isSkeleton size="base" classNames={["w-2/3"]} />,
                                ]} />
                            )} />
                        ),
                    ]} />
                ),
                // reveal control flanked by prev/next carets
                () => (
                    <Cluster gap={3} items={[
                        () => <Button isSkeleton size="sm" />,
                        () => <Button isSkeleton isIconOnly size="sm" />,
                        () => <Button isSkeleton isIconOnly size="sm" />,
                    ]} />
                ),
            ]} />
        )} />
    ) : done ? (
        // transient hand-off only — the connected file's "finish" effect
        // `router.replace`s into the dedicated `.../result` route once the completion
        // mutation resolves, so this branch never has a real end state to render — just
        // the "saving" interim until that navigation lands. KEEP the same
        // `WorkSessionHeader` chrome the just-finished ACTIVE phase used.
        <Container size="md" padding={1} body={() => (
            <StackV gap={4} align="center" principle="card-caption"
                explain="Holds caption text under card media so the caption stays attached to the image above it."
                classNames={["w-full"]} items={[
                    () => <Spinner size="lg" />,
                    () => <Typography size="sm" color="muted" text={labels.savingLabel} />,
                ]} />
        )} />
    ) : (
        <Container size="md" padding={1} body={() => (
            <StackV gap={6} items={[
                () => (
                    // the flip card: prompt → answer; the level/tag chips ride under the
                    // QUESTION via `belowFront` (teacher, 2026-07-13: "chips gap-3 below the
                    // question" + "due should render the chip label the same as the deck side")
                    // — same per-card level+tag chips as `FlashcardReviewer`.
                    <FlipCard
                        revealed={revealed}
                        questionLabel={labels.questionLabel}
                        answerLabel={labels.answerLabel}
                        front={() => <MarkdownContent plain markdown={card?.front ?? ""} />}
                        belowFront={chipItems.length > 0 ? () => <Cluster gap={3} items={chipItems} /> : undefined}
                        back={() => <MarkdownContent plain markdown={card?.back ?? ""} arcSections />}
                    />
                ),
                // reveal first, then grade recall (which advances)
                () => (
                    revealed ? (
                        <StackV gap={4} items={[
                            () => <Typography size="sm" weight="medium" text={labels.rateHint} />,
                            () => <RatingBar options={ratingOptions} onRate={onRate} ariaLabel={labels.rateAria} isPending={reviewing} />,
                        ]} />
                    ) : (
                        // "Show answer" (primary) · "Next"/"Previous" ICON-ONLY (caret, no text)
                        // — mirrors `FlashcardReviewer` exactly.
                        <Cluster gap={3} items={[
                            () => <Button variant="primary" size="sm" label={labels.showAnswer} onPress={onReveal} />,
                            () => (
                                <Button
                                    variant="secondary"
                                    size="sm"
                                    isIconOnly
                                    prefixIcon={CaretLeftIcon}
                                    ariaLabel={labels.previous}
                                    isDisabled={isFirst}
                                    onPress={onPrev}
                                />
                            ),
                            () => (
                                <Button
                                    variant="secondary"
                                    size="sm"
                                    isIconOnly
                                    prefixIcon={CaretRightIcon}
                                    ariaLabel={labels.next}
                                    isDisabled={isLast}
                                    onPress={onNext}
                                />
                            ),
                        ]} />
                    )
                ),
            ]} />
        )} />
    )

    const bodyShell = (
        <Box principle="page-pad" className="px-4 pb-6 pt-10 @app-sm:px-6"
            explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface."
        >{body}</Box>
    )

    return (
        <StackV gap={1} identity={{ tier: "block", component: "DueReview" }} items={[
            () => header,
            () => bodyShell,
        ]} />
    )
}

"use client"

import React, { useCallback, useEffect, useMemo, useRef, useState } from "react"
import useSWR, { useSWRConfig } from "swr"
import { useTranslations } from "next-intl"
import { usePathname, useRouter } from "next/navigation"
import { DUE_REVIEW_LIMIT, SM2_GRADES } from "@/modules/utils/flashcards"
import { _DueReview, type DueReviewCard, type DueReviewLabels } from "./component"
import { mutateReviewFlashcard } from "@/modules/api/graphql/mutations/mutation-review-flashcard"
import { queryMyDueFlashcards } from "@/modules/api/graphql/queries/query-my-due-flashcards"
import { GraphQLHeadersKey, type GraphQLHeaders } from "@/modules/api/graphql/types"
import { useQueryFlashcardCardsByIdsSwr } from "@/hooks/swr/api/graphql/queries/useQueryFlashcardCardsByIdsSwr"
import { useMutateStartFlashcardDueReviewSessionSwr } from "@/hooks/swr/api/graphql/mutations/useMutateStartFlashcardDueReviewSessionSwr"
import { useMutateSyncFlashcardDueReviewSessionProgressSwr } from "@/hooks/swr/api/graphql/mutations/useMutateSyncFlashcardDueReviewSessionProgressSwr"
import { useMutateCompleteFlashcardDueReviewSessionSwr } from "@/hooks/swr/api/graphql/mutations/useMutateCompleteFlashcardDueReviewSessionSwr"
import { useQueryMyInProgressFlashcardDueReviewSessionSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyInProgressFlashcardDueReviewSessionSwr"
import { useQueryMyFlashcardReviewSessionBySessionIdSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyFlashcardReviewSessionBySessionIdSwr"
import { useGraphQLWithToast } from "@/modules/toast/hooks"
import { useAppSelector } from "@/redux/hooks"

/** Props for {@link DueReview}. */
export interface DueReviewProps {
    /** Leave the session and return to the flashcards home. */
    onExit: () => void
    /**
     * Present when reached via the dedicated `flashcards/review/sessions/[sessionId]`
     * route — this component then hydrates straight from THAT session (no
     * resolve-or-start call) instead of resolving one itself. Absent when
     * reached via the bare `review?session=due` route (teacher's 2026-07-11
     * correction: "due review should also create a new session" — that bare route is now a
     * RESOLVE-ONLY shim: it resolves-or-starts a session then `router.push`es
     * into the sessioned URL (teacher: keep the history entry, don't use `.replace`),
     * mirroring `FlashcardReviewer`'s own idiom).
     * Mirrors `FlashcardReviewerProps.sessionId`.
     */
    sessionId?: string
}

/**
 * The spaced-repetition (SM-2) review session over the viewer's due cards, drawn
 * across every enrolled course — the CONNECTED half: it fetches the due queue,
 * runs the resolve-or-start/resume state machine, resolves every label (incl.
 * interpolation), and hands them to the presentational {@link _DueReview}. The
 * due count is the page's primary loop, so this is the main entry from the home
 * hero. See `tiers/split.md`.
 * @param props - {@link DueReviewProps}
 */
export const DueReview = ({ onExit, sessionId }: DueReviewProps) => {
    const t = useTranslations()
    const router = useRouter()
    const pathname = usePathname()
    const runGraphQL = useGraphQLWithToast()
    const { mutate: globalMutate } = useSWRConfig()
    // scope the due queue to THIS course; shared SWR key with the hero (DueReviewHero)
    const courseId = useAppSelector((state) => state.course.entity?.id)
    const dueKey = useMemo(
        () => ["my-due-flashcards", courseId ?? null, DUE_REVIEW_LIMIT] as const,
        [courseId],
    )
    // index of the card currently shown + whether its answer is revealed
    const [currentIndex, setCurrentIndex] = useState(0)
    const [revealed, setRevealed] = useState(false)
    // true while a grade is in flight (blocks the rating bar)
    const [reviewing, setReviewing] = useState(false)
    // how many cards were graded this session (shown in the summary)
    const [reviewedCount, setReviewedCount] = useState(0)
    // WHICH card positions have been graded this session (0-indexed, order-
    // independent) — drives the progress bar's per-segment green so a card
    // graded out of order (free-nav jump ahead → grade → jump back) still
    // reads green (2026-07-12, teacher: free-nav "both before and after"). A Set for
    // O(1) membership; persisted as an array via `gradedIndexes` sync so a
    // resume rehydrates it.
    const [gradedIndexes, setGradedIndexes] = useState<Set<number>>(() => new Set())
    // explicit "Finish" — end the session now regardless of position, distinct
    // from reaching the last card. Feeds `done` below.
    const [finished, setFinished] = useState(false)

    // the due queue (count + first batch of cards), shared key with the hero
    const { data, isLoading, error, mutate } = useSWR(dueKey, async () => {
        const response = await queryMyDueFlashcards({ request: { courseId, limit: DUE_REVIEW_LIMIT } })
        return response.data?.myDueFlashcards.data ?? null
    })

    const cards = data?.cards ?? []

    // session-persistence (mirrors QuizSession's/FlashcardReviewer's resumable-session
    // idiom, scoped cross-deck by enrollment only — no deckId, unlike the single-deck
    // reviewer): each rating is already saved immediately via `reviewFlashcard` (safe),
    // but WHICH batch/position within it was not persisted, so leaving mid-batch used
    // to lose the in-batch progress. `startFlashcardDueReviewSession` /
    // `syncFlashcardDueReviewSessionProgress` / `completeFlashcardDueReviewSession`
    // wrap that sequence with a resumable cursor, now with its OWN resumable URL too
    // (teacher's 2026-07-11 correction: "due review should also create a new session" — parity with
    // `FlashcardReviewer`'s own 2026-07-11 correction; superseding the earlier same-day
    // "silently, no new UI/route" note).
    const courseHeaders = useMemo<GraphQLHeaders | undefined>(
        () => (courseId ? { [GraphQLHeadersKey.XCourseId]: courseId } : undefined),
        [courseId],
    )
    const runStartSession = useMutateStartFlashcardDueReviewSessionSwr()
    const runSyncSession = useMutateSyncFlashcardDueReviewSessionProgressSwr()
    const runCompleteSession = useMutateCompleteFlashcardDueReviewSessionSwr()
    // no-`sessionId` shim route only: MRU "is there a resumable draw at all"
    // lookup, used to resolve-or-start before a sessioned URL exists yet.
    const inProgressSessionSwr = useQueryMyInProgressFlashcardDueReviewSessionSwr(courseId)
    // sessioned route: resolve THIS EXACT session by id (not an MRU guess) —
    // mirrors the identical fix in `FlashcardReviewer` (2026-07-12: "this one
    // glitches too"). The old code reused `inProgressSessionSwr` here too and
    // manually checked `resumeData.sessionId === sessionId` as a workaround for
    // using the wrong query.
    const sessionByIdSwr = useQueryMyFlashcardReviewSessionBySessionIdSwr(sessionId, courseId)
    // whichever of the two above is the resumable-session SOURCE OF TRUTH for
    // this render — by-id when we have a concrete sessionId, MRU otherwise.
    const resumableSessionData = sessionId ? sessionByIdSwr.data : inProgressSessionSwr.data
    const resumableSessionLoading = sessionId ? sessionByIdSwr.isLoading : inProgressSessionSwr.isLoading
    // status-agnostic re-fetch of the resumable session's OWN cards, by exact id —
    // NOT filtered by "due today" like `cards` above. Feeds `applyResume` below: a
    // card already graded THIS run gets rescheduled (SM-2) and drops out of the due
    // queue instantly, so matching purely against `cards` silently lost it on resume
    // (misaligning `currentIndex`, or failing resume outright once enough cards had
    // been graded — 2026-07-12, teacher: "why is it rendering this page" → traced to a
    // reload-after-grading orphaning the session). `nextIntervals` isn't part of this
    // shape (only the live due query carries it) — `applyResume` falls back to
    // `undefined` for a card resolved this way, which `RatingBar`'s optional `hint`
    // already renders as "no preview" instead of crashing.
    const resumeCardIds = resumableSessionData?.cardIds ?? []
    const resumeCardsByIdSwr = useQueryFlashcardCardsByIdsSwr(resumeCardIds, courseId)
    // when a resumable session is found, the fetched due batch is reordered/filtered
    // to match its persisted `cardIds` (never re-drawn) — null while resuming didn't
    // apply (fresh draw, or no resumable session), in which case the raw fetched
    // `cards` above is used as-is. `nextIntervals` optional (not `QueryMyDueFlashcardData`'s
    // own required field) — see `resumeCardsByIdSwr` comment above.
    const [resumedCards, setResumedCards] = useState<Array<DueReviewCard> | null>(null)
    // server-issued id for the current batch — set once on start OR resume
    const sessionIdRef = useRef<string | null>(null)
    // guards the one-shot resolve-or-start effect to run its work at most once
    // per mount (prevents a duplicate `start` call on re-render).
    const resolveAttemptedRef = useRef(false)
    // STATE, separate from the ref above — `isSkeleton` below reads THIS, so the
    // shimmer stays up until the resumed cards/cursor are ACTUALLY applied, not
    // just until the underlying query settled (2026-07-12 fix: closes a 1-frame
    // flash — card 1 appears, then jumps to the real resume position). Stays
    // false on the redirect-away paths (fresh session / no-sessionId shim) — the
    // shimmer correctly holds through the navigation.
    const [resolveApplied, setResolveApplied] = useState(false)
    // guards the one-shot completion call on reaching `done`
    const completedRef = useRef(false)

    const effectiveCards = resumedCards ?? cards
    const card = effectiveCards[currentIndex]
    // complete when the learner explicitly ends it ("Finish") OR steps past
    // the last card. With free navigation "past the last card" is no longer the
    // only finish path, so the explicit `finished` flag is the primary one.
    const done = effectiveCards.length > 0 && (finished || currentIndex >= effectiveCards.length)

    /**
     * Hydrate from an in-progress session's persisted batch/cursor; false if none
     * of its cards resolve. Looks up the LIVE due queue FIRST (carries
     * `nextIntervals`), falling back to the status-agnostic by-id fetch
     * (`resumeCardsByIdSwr`) for a card already graded this run — grading
     * reschedules a card (SM-2) OUT of "due" immediately, so a due-only lookup
     * silently dropped it, corrupting the resumed order/cursor (2026-07-12 fix).
     */
    const applyResume = useCallback(
        (resumeData: { sessionId: string, cardIds: Array<string>, currentIndex: number, reviewedCount: number, gradedIndexes?: Array<number> }): boolean => {
            const dueById = new Map(cards.map((dueCard) => [dueCard.cardId, dueCard]))
            const byId = new Map((resumeCardsByIdSwr.data ?? []).map((idCard) => [idCard.cardId, idCard]))
            const ordered = resumeData.cardIds
                .map((cardId): DueReviewCard | undefined => dueById.get(cardId) ?? byId.get(cardId))
                .filter((resolvedCard): resolvedCard is DueReviewCard => Boolean(resolvedCard))
            if (ordered.length === 0) {
                return false
            }
            sessionIdRef.current = resumeData.sessionId
            setResumedCards(ordered)
            setResolveApplied(true)
            // every card in the batch was already graded (`reviewedCount` reaches
            // the batch size) but `status` never flipped to "completed" — the
            // earlier completion call never landed (2026-07-12, same root cause
            // traced in `QuizSession`: "already submitted but F5 goes back to the last question"). Clamping
            // `currentIndex` to `ordered.length - 1` here would ALWAYS re-show the
            // last card (an index at the last position can't tell "about to
            // answer" from "just answered" apart) — set it to the FULL length
            // instead so `done` computes true immediately and the "finish" effect
            // below retries completion, instead of clamping into the last card
            // every time this session gets revisited.
            setCurrentIndex(
                resumeData.reviewedCount >= ordered.length
                    ? ordered.length
                    : Math.min(resumeData.currentIndex, ordered.length - 1),
            )
            setReviewedCount(resumeData.reviewedCount)
            // rehydrate the graded-set from the resumed session; fall back to
            // "first N contiguous" when the backend didn't send it (older row
            // synced before `gradedIndexes` existed) so green isn't lost.
            setGradedIndexes(
                resumeData.gradedIndexes && resumeData.gradedIndexes.length > 0
                    ? new Set(resumeData.gradedIndexes)
                    : new Set(Array.from({ length: resumeData.reviewedCount }, (_, i) => i)),
            )
            completedRef.current = false
            return true
        },
        [cards, resumeCardsByIdSwr.data],
    )

    // start a fresh session over the batch just drawn, then redirect into its
    // sessioned URL — mirrors `FlashcardReviewer`'s own `startSessionAndRedirect`.
    // Routed through `runGraphQL` (toast on failure, no success toast) instead of a
    // silent catch (teacher, 2026-07-11: "FE shouldn't swallow errors, use runGraphQL").
    // the bare `.../review` base, with any existing `/sessions/<id>` segment
    // stripped — so redirecting into a session NEVER appends a second
    // `/sessions/...` when we're already on a sessioned URL (the revisit-crash:
    // `.../sessions/A//sessions/B`). Reached via either route, this resolves to
    // the same base.
    const reviewBasePath = pathname.replace(/\/sessions\/[^/]+\/?$/, "")

    const startSessionAndRedirect = useCallback(async () => {
        if (!courseId) {
            return
        }
        const ok = await runGraphQL(
            async () => {
                const started = await runStartSession.trigger({
                    request: { courseId, cardIds: cards.map((dueCard) => dueCard.cardId) },
                    headers: courseHeaders as GraphQLHeaders,
                })
                const response = started.data?.startFlashcardDueReviewSession
                if (response?.data?.sessionId) {
                    sessionIdRef.current = response.data.sessionId
                }
                return response ?? { success: false, message: t("flashcard.review.error") }
            },
            { showSuccessToast: false },
        )
        if (ok && sessionIdRef.current) {
            router.replace(`${reviewBasePath}/sessions/${sessionIdRef.current}`)
        }
    }, [courseId, cards, courseHeaders, runStartSession, runGraphQL, router, reviewBasePath, t])

    // resolve-or-start, once the batch + the in-progress query have both settled — TWO
    // routes into this component (mirrors `FlashcardReviewer`'s own 2026-07-11 shim):
    // (a) reached via the dedicated `review/sessions/[sessionId]` route (`sessionId`
    //     prop set) → hydrate straight from THAT session; a stale/invalid id falls
    //     back to (b) instead of getting stuck.
    // (b) reached via the bare `review?session=due` route (`sessionId` absent) →
    //     resume the caller's existing draw if one exists, otherwise start a fresh
    //     one, THEN redirect into the sessioned URL.
    useEffect(() => {
        if (
            resolveAttemptedRef.current
            || !courseId
            || cards.length === 0
            || resumableSessionLoading
            // there IS a session to resume — wait for its status-agnostic by-id
            // cards to settle too, so `applyResume` can fall back to them for an
            // already-graded card the due queue no longer carries (see
            // `resumeCardsByIdSwr` above).
            || (resumableSessionData && resumeCardsByIdSwr.isLoading)
        ) {
            return
        }
        resolveAttemptedRef.current = true
        const resumeData = resumableSessionData

        if (sessionId) {
            // `resumableSessionData` was resolved BY id when `sessionId` is set
            // (see `sessionByIdSwr` above) — no need to re-check `.sessionId`.
            if (resumeData && applyResume(resumeData)) {
                return
            }
            // stale/invalid session id — start a fresh one and correct the URL
            void startSessionAndRedirect()
            return
        }

        if (resumeData && applyResume(resumeData)) {
            router.replace(`${reviewBasePath}/sessions/${resumeData.sessionId}`)
            return
        }
        void startSessionAndRedirect()
    }, [
        sessionId,
        courseId,
        cards,
        resumableSessionLoading,
        resumableSessionData,
        resumeCardsByIdSwr.isLoading,
        applyResume,
        startSessionAndRedirect,
        router,
        reviewBasePath,
    ])

    // finish: record the finished batch once (guarded), best-effort — a failed
    // complete call only means the row stays "in_progress" (still resumable),
    // it never blocks the learner from leaving. Routed through `runGraphQL`
    // (teacher, 2026-07-11: "FE shouldn't swallow errors, use runGraphQL") instead of a
    // silent catch.
    useEffect(() => {
        if (!done || completedRef.current || !sessionIdRef.current) {
            return
        }
        completedRef.current = true
        const completingSessionId = sessionIdRef.current
        void (async () => {
            await runGraphQL(
                async () => {
                    const result = await runCompleteSession.trigger({
                        request: { sessionId: completingSessionId, reviewedCount, xpEarned: 0 },
                        headers: courseHeaders as GraphQLHeaders,
                    })
                    return (
                        result.data?.completeFlashcardDueReviewSession ?? {
                            success: false,
                            message: t("flashcard.review.error"),
                        }
                    )
                },
                { showSuccessToast: false },
            )
            // whether it succeeded or the toast surfaced a failure, drop the
            // saving state and hand off to the dedicated result route (reads
            // events directly by sessionId, independent of the session row's
            // status — "done" is now answered by the URL, not re-derived
            // client-side; see `.../result/page.tsx` doc for the root cause).
            // the due count changed — refresh the queue so the home hero reads correctly
            // whenever the learner navigates back there.
            void globalMutate(dueKey)
            router.replace(`${reviewBasePath}/sessions/${completingSessionId}/result`)
        })()
    }, [done, reviewedCount, runCompleteSession, courseHeaders, runGraphQL, t, router, reviewBasePath, globalMutate, dueKey])

    // SM-2 grade buttons for the current card: localized label + next-interval
    // preview ("4 days") computed server-side from the card's current state
    const ratingOptions = useMemo(() => {
        const intervals = card?.nextIntervals
        // map a grade to its previewed next-interval in days
        const daysForGrade = (grade: number): number | undefined => {
            if (!intervals) {
                return undefined
            }
            return [intervals.again, intervals.hard, intervals.good, intervals.easy][grade]
        }
        return SM2_GRADES.map((grade) => {
            const days = daysForGrade(grade.grade)
            return {
                grade: grade.grade,
                label: t(grade.labelKey),
                hint: days === undefined ? undefined : t("flashcard.review.intervalDays", { count: days }),
            }
        })
    }, [t, card])

    // grade the current card, reschedule it (SM-2), then advance to the next
    // presentational callback contract is sync — fire-and-forget from the click via void.
    const onRate = useCallback(
        async (grade: number) => {
            if (!card) {
                return
            }
            setReviewing(true)
            // a success toast per card would be noise — only surface failures
            const ok = await runGraphQL(
                async () => {
                    const response = await mutateReviewFlashcard({
                        // thread the live session id so the review event links to
                        // this session — powers the per-session stats aggregate.
                        request: { cardId: card.cardId, grade, sessionId: sessionIdRef.current ?? undefined },
                    })
                    return (
                        response.data?.reviewFlashcard ?? {
                            success: false,
                            message: t("flashcard.review.error"),
                        }
                    )
                },
                { showSuccessToast: false },
            )
            setReviewing(false)
            if (ok) {
                // mark THIS position graded (set dedupes a re-grade) — the source
                // of truth for both the per-segment green and the reviewed count.
                const nextGraded = new Set(gradedIndexes).add(currentIndex)
                const nextReviewedCount = nextGraded.size
                const nextIndex = currentIndex + 1
                setGradedIndexes(nextGraded)
                setReviewedCount(nextReviewedCount)
                setRevealed(false)
                setCurrentIndex(nextIndex)
                // best-effort, fire-and-forget persistence for resume — never blocks
                // advancing to the next card; still routed through `runGraphQL`
                // (toast on failure, no success toast) rather than a silent catch
                // (teacher, 2026-07-11: "FE shouldn't swallow errors, use runGraphQL").
                if (sessionIdRef.current) {
                    const syncingSessionId = sessionIdRef.current
                    void runGraphQL(
                        async () => {
                            const result = await runSyncSession.trigger({
                                request: {
                                    sessionId: syncingSessionId,
                                    currentIndex: nextIndex,
                                    reviewedCount: nextReviewedCount,
                                    gradedIndexes: Array.from(nextGraded),
                                    xpEarned: 0,
                                },
                                headers: courseHeaders as GraphQLHeaders,
                            })
                            return (
                                result.data?.syncFlashcardDueReviewSessionProgress ?? {
                                    success: false,
                                    message: t("flashcard.review.error"),
                                }
                            )
                        },
                        { showSuccessToast: false },
                    ).then(() => {
                        // invalidate the Hub's "Review in progress" (ContinueCard) cache —
                        // it reads THIS exact key, and nothing else was invalidating it
                        // per-grade (only on completion, see the `done` effect below) —
                        // so a revisit to the Hub mid-session showed a stale currentIndex
                        // from whenever that card first mounted, not the position just
                        // synced here (2026-07-12, teacher: "pressing the back button returns to 2 while it's
                        // actually at 5" — the DB was correct the whole time; only this cache
                        // was stale, verified directly against Postgres).
                        if (courseId) {
                            void globalMutate(["QUERY_MY_IN_PROGRESS_FLASHCARD_DUE_REVIEW_SESSION_SWR", courseId])
                        }
                    })
                }
            }
        },
        [card, runGraphQL, t, currentIndex, gradedIndexes, runSyncSession, courseHeaders, courseId, globalMutate],
    )
    // step back to re-see an earlier card (question side; no re-grade) — mirrors
    // `FlashcardReviewer`'s own `goPrev` (teacher: sync the UI, both session types should
    // have a "Previous" button, due-review was previously missing this button).
    const isFirst = currentIndex === 0
    const isLast = currentIndex >= effectiveCards.length - 1
    const goPrev = useCallback(() => {
        setRevealed(false)
        setCurrentIndex((index) => Math.max(index - 1, 0))
    }, [])
    // "Next" — explicit, symmetric counterpart to "Previous": browse forward
    // WITHOUT grading (mirrors `FlashcardReviewer`'s own `goNext`, teacher,
    // 2026-07-12: "next prev" flanking the primary "Show answer" CTA).
    const goNext = useCallback(() => {
        setRevealed(false)
        setCurrentIndex((index) => Math.min(index + 1, effectiveCards.length - 1))
    }, [effectiveCards.length])
    // jump straight to ANY step from the progress-segment bar — free navigation,
    // "both before and after, even ones not reached yet can be clicked" (2026-07-12). No re-grade; the
    // card's graded/green state is independent of which one you're viewing.
    const goToIndex = useCallback((position: number) => {
        setRevealed(false)
        setCurrentIndex(position)
    }, [])
    // end the session now → the completion effect (`done`) fires + navigates to
    // results. Distinct from "Exit" (back-link: leave, keep resumable).
    const onFinish = useCallback(() => setFinished(true), [])
    const onReveal = useCallback(() => setRevealed(true), [])

    // first load, nothing in hand → shimmer (loading-and-skeleton.md §2); also holds through the
    // due-review resolve-or-start/resume state machine (forced skeleton while the bare
    // `?session=due` shim resolves-or-starts a session and redirects, and — once the batch has
    // loaded — until the resumed cursor has actually been APPLIED, not just until its underlying
    // query settled, closing a 1-frame flash: card 1 appears, then jumps to the real resume position).
    const isSkeleton = (isLoading && !data) || (!sessionId && cards.length > 0) || (Boolean(sessionId) && cards.length > 0 && !resolveApplied)
    const isEmpty = cards.length === 0

    const levelLabel = card?.level ? t(`flashcard.level.${card.level}`) : undefined

    const labels: DueReviewLabels = {
        exit: t("flashcard.exit"),
        modeTitle: t("flashcard.mode.due"),
        counter: t("flashcard.cardProgress", {
            current: done ? effectiveCards.length : currentIndex + 1,
            total: effectiveCards.length,
        }),
        finish: t("flashcard.finish"),
        savingLabel: t("flashcard.review.stats.savingLabel"),
        // NB: keeps the pre-existing (mismatched) copy verbatim — "No flashcards for this course
        // yet." doubling as the due-queue error title predates this split, unchanged here.
        errorTitle: t("flashcard.empty"),
        emptyTitle: t("flashcard.due.allCaught"),
        emptyDescription: t("flashcard.due.allCaughtHint"),
        questionLabel: t("flashcard.questionLabel"),
        answerLabel: t("flashcard.answerLabel"),
        rateHint: t("flashcard.review.rateHint"),
        rateAria: t("flashcard.review.rateAria"),
        showAnswer: t("flashcard.showAnswer"),
        previous: t("flashcard.previous"),
        next: t("flashcard.next"),
    }

    return (
        <_DueReview
            isSkeleton={isSkeleton}
            isEmpty={isEmpty}
            error={error}
            onRetry={() => { void mutate() }}
            onBack={onExit}
            done={done}
            card={card}
            levelLabel={levelLabel}
            revealed={revealed}
            onReveal={onReveal}
            reviewing={reviewing}
            ratingOptions={ratingOptions}
            onRate={(grade) => { void onRate(grade) }}
            currentIndex={currentIndex}
            totalCount={effectiveCards.length}
            gradedIndexes={Array.from(gradedIndexes)}
            isFirst={isFirst}
            isLast={isLast}
            onSegmentClick={goToIndex}
            onPrev={goPrev}
            onNext={goNext}
            onFinish={onFinish}
            labels={labels}
        />
    )
}

import React from "react"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { StackH, StackV } from "@/components/frames/Stack"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Props for {@link FlashcardDeckListSkeleton}. */
export interface FlashcardDeckListSkeletonProps extends WithClassNames<undefined> {
    /** Number of placeholder deck cards to render. Defaults to `3`. */
    count?: number
}

/**
 * Loading placeholder for {@link FlashcardDeckList}. Mirrors the real deck cards:
 * a title row with a difficulty chip, a short description preview, and a footer
 * row with the card count and the study button.
 * @param props - {@link FlashcardDeckListSkeletonProps}
 */
export const FlashcardDeckListSkeleton = ({
    count = 3,
    className,
}: FlashcardDeckListSkeletonProps) => {
    return (
        <div className={className}>
            <StackV
                gap={4}
                items={Array.from({ length: Math.max(count, 1) }, () => () => (
                    <SurfaceCard
                        padding={5}
                        body={() => (
                            <StackV
                                gap={3}
                                principle="sibling-stack"
                                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                items={[
                                    () => (
                                        <StackH
                                            gap={4}
                                            principle="content-row"
                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                            justify="between"
                                            align="center"
                                            items={[
                                                () => <Skeleton.Typography type="body" width="1/2" />,
                                                () => <Skeleton.Chip />,
                                            ]}
                                        />
                                    ),
                                    () => <Skeleton.Typography type="body-sm" width="3/4" />,
                                    () => (
                                        <StackH
                                            gap={4}
                                            principle="content-row"
                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                            justify="between"
                                            align="center"
                                            items={[
                                                () => <Skeleton.Typography type="body-xs" width="1/4" />,
                                                () => <Skeleton.Button />,
                                            ]}
                                        />
                                    ),
                                ]}
                            />
                        )}
                    />
                ))}
            />
        </div>
    )
}

import { InputSearch } from "@/components/atoms/forms"
import React from "react"
import { ListIcon, SquaresFourIcon } from "@phosphor-icons/react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { SurfaceListCard, SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import { TabsCard } from "@/components/blocks/navigation/TabsCard"
import { Typography } from "@/components/atoms/text/Typography"
import { Button } from "@/components/atoms/buttons/Button"
import { Chip, type ChipTone } from "@/components/atoms/chips/Chip"
import { Divider } from "@/components/atoms/display/Divider"

import { Pagination } from "@/components/atoms/navigation/Pagination"
import { Box } from "@/components/frames/Box"
import { Grid } from "@/components/frames/Grid"
import { StackH, StackV } from "@/components/frames/Stack"
import { FlashcardReviewModeModal } from "../FlashcardReviewModeModal"
import { ChallengeDifficulty } from "@/modules/types/enums/challenge-difficulty"
import { type FlashcardDeckEntity } from "@/modules/types/entities/flashcard-deck"
import type { FlashcardReviewMode } from "@/modules/api/graphql/mutations/types/start-flashcard-review-session"

/**
 * `_FlashcardDeckList` — the SRC TWIN of the presentational deck-picker. Presentational:
 * typed props, already resolved (paginated/filtered decks, interpolated labels); no
 * fetch/store/i18n (that lives in the connected `./index.tsx`, see `tiers/split.md`).
 *
 * Four states in the fixed order error → skeleton → empty → content
 * (`loading-and-skeleton.md`): `error` falls to the shared `AsyncContentError` frame,
 * settled-empty (`!isSkeleton && isEmpty`) to `AsyncContentEmpty`, and otherwise the ONE
 * real tree renders with `isSkeleton` threaded to every leaf so the shimmer mirrors the
 * loaded shape — a grid/line of placeholder deck rows, same row component, same count.
 */

/** How the deck list is laid out — a roomy card grid or a compact row list. */
export type DeckView = "grid" | "line"

/** Placeholder rows shown while the FIRST load is shimmering (mirrors the old `FlashcardDeckListSkeleton` default). */
const SKELETON_ROW_COUNT = 3

/** Chip tone per difficulty tier — a pure rendering concern, not data or i18n. */
const DIFFICULTY_TONE: Record<ChallengeDifficulty, ChipTone> = {
    [ChallengeDifficulty.Easy]: "success",
    [ChallengeDifficulty.Medium]: "warning",
    [ChallengeDifficulty.Hard]: "danger",
    [ChallengeDifficulty.Insane]: "danger",
    [ChallengeDifficulty.Expert]: "danger",
}

/** All display text, already localized by the connected `FlashcardDeckList`; per-row values arrive as small resolver functions (count/plural interpolation the block itself doesn't have the values for at label-build time). */
export interface FlashcardDeckListLabels {
    errorTitle: string
    emptyTitle: string
    searchPlaceholder: string
    /** "Found N decks" — pre-interpolated with the current filtered count. */
    foundCount: string
    /** "No deck matches \"…\"" — pre-interpolated with the current query. */
    searchEmptyMessage: string
    viewAria: string
    viewGrid: string
    viewLine: string
    /** Default CTA label — overridden per-call by `ctaLabel` when the caller passes one. */
    study: string
    difficultyLabel: (difficulty: ChallengeDifficulty) => string
    dueLabel: (count: number) => string
    masteredLabel: (mastered: number, total: number) => string
    cardCountLabel: (count: number) => string
}

/** Props for {@link _FlashcardDeckList}. */
export interface FlashcardDeckListProps {
    /** First load, nothing in hand → the whole tree shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with zero decks in the course → the empty message. */
    isEmpty?: boolean
    /** Truthy → the error message (beats skeleton + empty). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler for the error branch. */
    onRetry?: () => void
    /** Show the per-viewer spaced-repetition chrome (due chip + mastery meter). */
    showProgress?: boolean
    /** CTA label on each deck card. Falls back to `labels.study`. */
    ctaLabel?: string
    /** Decks for the CURRENT page, already search-filtered and paginated. */
    pagedDecks?: Array<FlashcardDeckEntity>
    /** Search-filtered deck count (before pagination) — drives the "found" label and the search-empty branch. */
    filteredCount?: number
    /** Live search query. */
    query: string
    onQueryChange: (value: string) => void
    /** Grid vs line layout. */
    view: DeckView
    onViewChange: (view: DeckView) => void
    /** 1-based current page. */
    page: number
    totalPages?: number
    onPageChange: (page: number) => void
    /** "Study" pressed on a deck row/card. */
    onPressStart: (deck: FlashcardDeckEntity) => void
    /** The deck whose review-mode modal is open, or `null`/omitted when closed. */
    modalDeck?: FlashcardDeckEntity | null
    onModalClose: () => void
    onModalStart: (mode: FlashcardReviewMode) => void
    /** True while the picked mode is being persisted (drives the modal's "Start" spinner). */
    isModalPending?: boolean
    labels: FlashcardDeckListLabels
}

/**
 * Lists the flashcard decks of the active course as a topic picker, shared by both the
 * study and quiz tabs. See the file header for the four-state contract and
 * `tiers/split.md` for the presentational/connected split.
 *
 * @param props - {@link FlashcardDeckListProps}
 */
export const _FlashcardDeckList = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    showProgress = true,
    ctaLabel,
    pagedDecks = [],
    filteredCount = 0,
    query,
    onQueryChange,
    view,
    onViewChange,
    page,
    totalPages = 1,
    onPageChange,
    onPressStart,
    modalDeck,
    onModalClose,
    onModalStart,
    isModalPending = false,
    labels,
}: FlashcardDeckListProps) => {
    // error beats a stale skeleton flag; empty only once settled (loading-and-skeleton.md).
    if (error) {
        return <AsyncContentError title={labels.errorTitle} onRetry={onRetry} />
    }
    if (!isSkeleton && isEmpty) {
        return <AsyncContentEmpty title={labels.emptyTitle} />
    }

    /** Difficulty chip — shared by both views. Always renders (also while shimmering, mirrors the old skeleton's fixed chip slot). */
    const difficultyChip = (deck: FlashcardDeckEntity | undefined) => (
        <Chip
            tone={deck ? DIFFICULTY_TONE[deck.difficulty] : "default"}
            isSkeleton={isSkeleton}
            text={deck ? labels.difficultyLabel(deck.difficulty) : ""}
        />
    )
    /** Due chip (per-viewer, study only) — omitted while shimmering, the real count is indeterminate until data lands. */
    const dueChip = (deck: FlashcardDeckEntity | undefined) => {
        if (isSkeleton || !showProgress || !deck?.dueCount) {
            return null
        }
        return <Chip tone="warning" text={labels.dueLabel(deck.dueCount)} />
    }
    /** The "Study" CTA — the only action on a deck row/card. */
    const cta = (deck: FlashcardDeckEntity | undefined) => (
        <Button
            variant="primary"
            size="sm"
            isSkeleton={isSkeleton}
            label={ctaLabel ?? labels.study}
            onPress={deck ? () => onPressStart(deck) : undefined}
        />
    )

    /** GRID card body: title + chips, description, mastery + divider, footer (count + CTA) — stacked. */
    const deckGridCardBody = (deck: FlashcardDeckEntity | undefined) => {
        const total = deck?.cards?.length ?? 0
        const mastered = deck?.masteredCount ?? 0
        return (
            <StackV gap={3} principle="sibling-stack"
                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                items={[
                    () => (
                        <StackH gap={3} justify="between" align="start" items={[
                            () => (
                                <Typography
                                    size="sm"
                                    weight="medium"
                                    lineClamp={2}
                                    isSkeleton={isSkeleton}
                                    text={deck?.title}
                                    classNames={["min-w-0", "flex-1"]}
                                />
                            ),
                            () => (
                                <StackH gap={3} principle="chip-row"
                                    explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                    align="center" classNames={["shrink-0"]} items={[
                                        () => dueChip(deck),
                                        () => difficultyChip(deck),
                                    ]} />
                            ),
                        ]} />
                    ),
                    // description — always shown while shimmering (mirrors the old skeleton's fixed line);
                    // once loaded, only when the deck actually carries one.
                    ...(isSkeleton || deck?.description ? [
                        () => (
                            <Typography size="xs" color="muted" lineClamp={2} isSkeleton={isSkeleton} text={deck?.description} />
                        ),
                    ] : []),
                    // per-viewer mastery — count + a plain divider (study only, never while shimmering:
                    // the old skeleton never carried this row either).
                    ...(!isSkeleton && showProgress && total > 0 ? [
                        () => (
                            <StackV gap={3} principle="sibling-stack"
                                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                items={[
                                    () => <Typography size="xs" color="muted" text={labels.masteredLabel(mastered, total)} />,
                                    () => <Divider />,
                                ]} />
                        ),
                    ] : []),
                    () => (
                        <StackH gap={3} principle="flex-action"
                            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                            justify="between" align="center" items={[
                                () => <Typography size="xs" color="muted" isSkeleton={isSkeleton} text={labels.cardCountLabel(total)} />,
                                () => cta(deck),
                            ]} />
                    ),
                ]} />
        )
    }

    /** LINE row body: one compact horizontal row — title, chips, mastery-or-count, CTA. */
    const deckLineRowBody = (deck: FlashcardDeckEntity | undefined) => {
        const total = deck?.cards?.length ?? 0
        const mastered = deck?.masteredCount ?? 0
        const showMastered = !isSkeleton && showProgress && total > 0
        return (
            <StackH gap={4} principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                align="center" items={[
                    () => (
                        <Typography
                            size="sm"
                            weight="medium"
                            truncate
                            isSkeleton={isSkeleton}
                            text={deck?.title}
                            classNames={["min-w-0", "flex-1"]}
                        />
                    ),
                    () => dueChip(deck),
                    () => difficultyChip(deck),
                    () => (
                        <Typography
                            size="xs"
                            color="muted"
                            isSkeleton={isSkeleton}
                            classNames={["shrink-0"]}
                            text={showMastered ? labels.masteredLabel(mastered, total) : labels.cardCountLabel(total)}
                        />
                    ),
                    () => cta(deck),
                ]} />
        )
    }

    // rows: while shimmering, placeholder rows keep the SAME row/card component and the SAME
    // count shape as the old `FlashcardDeckListSkeleton` default; otherwise the current page's decks.
    const rows: Array<FlashcardDeckEntity | undefined> = isSkeleton
        ? Array.from({ length: SKELETON_ROW_COUNT }, () => undefined)
        : pagedDecks

    const showSearchEmpty = !isSkeleton && filteredCount === 0
    const showPager = !isSkeleton && totalPages > 1

    // Peer deck cards at gap={4} (12px) — content-row owns the step-4 seam.
    const gridItems = rows.map((deck, index) => ({
        key: deck?.id ?? `pending-${index}`,
        content: () => <SurfaceCard isSkeleton={isSkeleton} body={() => deckGridCardBody(deck)} />,
    }))
    const gridView = (
        <Grid
            columns={{ base: 1, sm: 2 }}
            principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            items={gridItems}
        />
    )

    const lineView = (
        <SurfaceListCard bordered>
            {rows.map((deck, index) => (
                <SurfaceListCardItem key={deck?.id ?? `pending-${index}`}>
                    {deckLineRowBody(deck)}
                </SurfaceListCardItem>
            ))}
        </SurfaceListCard>
    )

    return (
        <>
            {/* one modal instance, driven by `modalDeck` — the picked mode + resolve-or-start
            live in the connected file (this component only renders what it's handed). */}
            {modalDeck ? (
                <FlashcardReviewModeModal
                    isOpen={Boolean(modalDeck)}
                    onClose={onModalClose}
                    deckTitle={modalDeck.title}
                    totalCount={modalDeck.cards?.length ?? 0}
                    dueCount={modalDeck.dueCount ?? 0}
                    isPending={isModalPending}
                    onStart={onModalStart}
                />
            ) : null}
            {(() => {
                // Hoisted so the outer gap-only column is not scanned as owning nested
                // justify/at from its children (check-pattern-coverage opens to `>`).
                const deckListColumnItems = [
                    () => (
                        // search row: filter input (left) + result count & view toggle (right).
                        <StackH gap={4} principle="content-row"
                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                            at="sm" justify="between" align="center" items={[
                                () => (
                                    <Box className="w-full @app-sm:max-w-sm">
                                        <InputSearch
                                            value={query}
                                            onValueChange={onQueryChange}
                                            isSkeleton={isSkeleton}
                                            ariaLabel={labels.searchPlaceholder}
                                            placeholder={labels.searchPlaceholder}
                                        />
                                    </Box>
                                ),
                                () => (
                                    <StackH gap={4} principle="flex-action"
                                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                        align="center" classNames={["shrink-0"]} items={[
                                            () => (
                                                <Typography
                                                    size="sm"
                                                    color="muted"
                                                    isSkeleton={isSkeleton}
                                                    text={labels.foundCount}
                                                    classNames={isSkeleton ? ["w-1/4"] : undefined}
                                                />
                                            ),
                                            // grid ⇆ line layout toggle (icon-only; persistence lives in the connected file).
                                            // Chrome control over local view state, not fetched data — it does not shimmer.
                                            () => (
                                                <TabsCard
                                                    variant="primary"
                                                    leftTabs={{
                                                        selectedKey: view,
                                                        ariaLabel: labels.viewAria,
                                                        onSelectionChange: (key) => onViewChange(String(key) as DeckView),
                                                        items: [
                                                            {
                                                                key: "grid",
                                                                label: (
                                                                    <SquaresFourIcon
                                                                        className="size-5"
                                                                        aria-label={labels.viewGrid}
                                                                        focusable="false"
                                                                    />
                                                                ),
                                                            },
                                                            {
                                                                key: "line",
                                                                label: (
                                                                    <ListIcon
                                                                        className="size-5"
                                                                        aria-label={labels.viewLine}
                                                                        focusable="false"
                                                                    />
                                                                ),
                                                            },
                                                        ],
                                                    }}
                                                />
                                            ),
                                        ]} />
                                ),
                            ]} />
                    ),
                    () => (
                        showSearchEmpty ? (
                            <Typography size="sm" color="muted" text={labels.searchEmptyMessage} />
                        ) : (
                            <StackV gap={4} items={[
                                () => (view === "grid" ? gridView : lineView),
                                ...(showPager ? [
                                    () => <Pagination currentPage={page} totalPages={totalPages} onPageChange={onPageChange} />,
                                ] : []),
                            ]} />
                        )
                    ),
                ]
                return <StackV gap={4} items={deckListColumnItems} />
            })()}
        </>
    )
}

"use client"

import React, { useCallback, useEffect, useMemo, useState } from "react"
import useSWR from "swr"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { _FlashcardDeckList, type DeckView } from "./component"
import { queryFlashcardDecksByCourse } from "@/modules/api/graphql/queries/query-flashcard-decks-by-course"
import { type FlashcardDeckEntity } from "@/modules/types/entities/flashcard-deck"
import { useAppSelector } from "@/redux/hooks"
import { pathConfig } from "@/resources/path"
import { useStartFlashcardReviewSession } from "@/hooks/useStartFlashcardReviewSession"
import type { FlashcardReviewMode } from "@/modules/api/graphql/mutations/types/start-flashcard-review-session"

/** Decks shown per page in the topic list before the pager kicks in. */
const DECKS_PER_PAGE = 10

/** localStorage key persisting the chosen deck view across sessions. */
const VIEW_STORAGE_KEY = "starci.flashcard.deckView"

/** Props for {@link FlashcardDeckList}. */
export interface FlashcardDeckListProps {
    /** Called with the chosen deck id when the learner opens a deck. */
    onSelectDeck: (deckId: string) => void
    /** CTA label on each deck card. Defaults to the study label. */
    ctaLabel?: string
    /** Show the per-viewer spaced-repetition chrome (due chip + mastery meter).
     * The quiz tab passes `false` — SR state is irrelevant when picking a
     * topic to drill aloud. Defaults to `true`. */
    showProgress?: boolean
}

/**
 * Lists the flashcard decks owned by the active course as a topic picker, shared
 * by both the study and quiz tabs — the CONNECTED half: it fetches the decks,
 * owns the search/pager/view UI state, resolves every label, and hands them to
 * the presentational {@link _FlashcardDeckList}. See `tiers/split.md`.
 *
 * @param props - {@link FlashcardDeckListProps}
 */
export const FlashcardDeckList = ({
    onSelectDeck,
    ctaLabel,
    showProgress = true,
}: FlashcardDeckListProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    // read the owning course id from the store — no prop drilling needed
    const courseId = useAppSelector((state) => state.course.entity?.id)
    const displayId = useAppSelector((state) => state.course.displayId)
    // eager resolve-or-start (teacher 2026-07-11: "pressing Study should show
    // isPending on the study button itself ... once the session is created,
    // router push into the same page as quick study") — only meaningful in the study ("Study cards") context; a
    // hypothetical future reuse with `showProgress={false}` (picking a deck for
    // something OTHER than a review session) falls back to `onSelectDeck`.
    const { start: startReview, startingDeckId } = useStartFlashcardReviewSession(courseId)
    // deck whose review-mode modal is open (teacher 2026-07-13: "Study" opens a modal to choose
    // full/forgotten-only before entering), null = closed. Held as the whole deck so the modal
    // reads its title + total + dueCount without a re-fetch.
    const [modeDeck, setModeDeck] = useState<FlashcardDeckEntity | null>(null)
    // live search query filtering decks by title/description
    const [query, setQuery] = useState("")
    // 1-based page for the client-side deck pager
    const [page, setPage] = useState(1)
    // grid (default) vs line layout; hydrated from localStorage after mount (SSR-safe)
    const [view, setView] = useState<DeckView>("grid")
    useEffect(() => {
        const saved = window.localStorage.getItem(VIEW_STORAGE_KEY)
        if (saved === "grid" || saved === "line") {
            setView(saved)
        }
    }, [])
    const onChangeView = useCallback((next: DeckView) => {
        setView(next)
        try {
            window.localStorage.setItem(VIEW_STORAGE_KEY, next)
        } catch {
            // storage unavailable (private mode) — view simply won't persist
        }
    }, [])

    // fetch the decks for this course; null key suspends until the course hydrates
    const { data, isLoading, error, mutate } = useSWR(
        courseId ? ["flashcard-decks-by-course", courseId] : null,
        async () => {
            const response = await queryFlashcardDecksByCourse({
                request: { courseId: courseId as string },
            })
            return response.data?.flashcardDecksByCourse.data ?? null
        },
    )

    const decks = data ?? []

    // decks in display order, narrowed by the (case-insensitive) search query
    const filteredDecks = useMemo(() => {
        const sorted = [...decks].sort((prev, next) => prev.sortIndex - next.sortIndex)
        const normalized = query.trim().toLowerCase()
        if (!normalized) {
            return sorted
        }
        return sorted.filter((deck) => {
            const haystack = `${deck.title ?? ""} ${deck.description ?? ""}`.toLowerCase()
            return haystack.includes(normalized)
        })
    }, [decks, query])

    // paginate the filtered decks client-side
    const totalPages = Math.max(1, Math.ceil(filteredDecks.length / DECKS_PER_PAGE))
    // a new search shrinks the list — snap back to the first page
    useEffect(() => {
        setPage(1)
    }, [query])
    const pagedDecks = filteredDecks.slice((page - 1) * DECKS_PER_PAGE, page * DECKS_PER_PAGE)

    /** "Study" pressed → open the mode modal (study context), or fall straight
     *  through to `onSelectDeck` for a non-study reuse (`showProgress={false}`). */
    const onPressStart = useCallback(
        (deck: FlashcardDeckEntity) => {
            if (!showProgress || !displayId) {
                onSelectDeck(deck.id)
                return
            }
            setModeDeck(deck)
        },
        [showProgress, displayId, onSelectDeck],
    )
    /** Chosen a mode in the modal → resolve-or-start with that scope, then
     *  `router.push` into the live session (mirrors the old eager idiom, now
     *  gated behind the modal's "Start"). */
    const onStartWithMode = useCallback(
        async (mode: FlashcardReviewMode) => {
            if (!modeDeck || !displayId) {
                return
            }
            const cardIds = (modeDeck.cards ?? []).map((deckCard) => deckCard.id)
            const sessionId = await startReview(modeDeck.id, cardIds, mode)
            if (sessionId) {
                setModeDeck(null)
                router.push(
                    pathConfig().locale(locale).course(displayId).learn().flashcards().due(sessionId).build(),
                )
            }
        },
        [modeDeck, displayId, startReview, router, locale],
    )
    /** Modal close — blocked while ITS OWN deck is mid-start (mirrors the old inline check). */
    const onModalClose = useCallback(() => {
        if (!modeDeck || startingDeckId !== modeDeck.id) {
            setModeDeck(null)
        }
    }, [modeDeck, startingDeckId])

    return (
        <_FlashcardDeckList
            // first load, nothing in hand → shimmer (loading-and-skeleton.md); same formula as before
            isSkeleton={(isLoading || !courseId) && decks.length === 0}
            isEmpty={decks.length === 0}
            // only a settled fetch error (no cached decks to fall back on) reaches the block
            error={decks.length === 0 ? error : undefined}
            onRetry={() => { void mutate() }}
            showProgress={showProgress}
            ctaLabel={ctaLabel}
            pagedDecks={pagedDecks}
            filteredCount={filteredDecks.length}
            query={query}
            onQueryChange={setQuery}
            view={view}
            onViewChange={onChangeView}
            page={page}
            totalPages={totalPages}
            onPageChange={setPage}
            onPressStart={onPressStart}
            modalDeck={modeDeck}
            onModalClose={onModalClose}
            onModalStart={(mode) => { void onStartWithMode(mode) }}
            isModalPending={modeDeck != null && startingDeckId === modeDeck.id}
            labels={{
                errorTitle: t("flashcard.empty"),
                emptyTitle: t("flashcard.empty"),
                searchPlaceholder: t("flashcard.searchPlaceholder"),
                foundCount: t("flashcard.deck.found", { count: filteredDecks.length }),
                searchEmptyMessage: t("flashcard.searchEmpty", { query: query.trim() }),
                viewAria: t("flashcard.deck.viewAria"),
                viewGrid: t("flashcard.deck.viewGrid"),
                viewLine: t("flashcard.deck.viewLine"),
                study: t("flashcard.study"),
                difficultyLabel: (difficulty) => t(`flashcard.difficulty.${difficulty}`),
                dueLabel: (count) => t("flashcard.deck.due", { count }),
                masteredLabel: (mastered, total) => t("flashcard.deck.mastered", { mastered, total }),
                cardCountLabel: (count) => t("flashcard.cardCount", { count }),
            }}
        />
    )
}

"use client"

import React from "react"
import { useTranslations } from "next-intl"
import { useFlashcardNav, type FlashcardMode } from "@/hooks/useFlashcardNav"
import { TabsCard } from "@/components/blocks/navigation/TabsCard"

/** Props for {@link FlashcardMobileNav}. */
export type FlashcardMobileNavProps = Record<string, never>
/**
 * Mobile (`<lg`) fallback for the flashcards LEFT RAIL — which is hidden on
 * small screens. Surfaces the mode switch (Study / Quiz) the rail owns,
 * driving the URL via {@link useFlashcardNav} so the rail (desktop) and this
 * bar (mobile) stay in sync. Rendered `@app-lg:hidden` above the work pane.
 *
 * The horizontal deck-chip picker this bar used to ALSO surface (a mobile
 * form of the rail's deck list) was removed (teacher, 2026-07-09: "remove this
 * on mobile") — `FlashcardDeckList` already gives the overview a proper
 * deck picker, so the chip row was a redundant second way to jump decks.
 * @param props - {@link FlashcardMobileNavProps}
 */
export const FlashcardMobileNav = () => {
    const t = useTranslations()
    const { mode, goMode } = useFlashcardNav()

    return (
        <div className={"flex flex-col gap-3 @app-lg:hidden"}>
            {/* page-FEATURE switch (mirrors the desktop rail's own mode control, see
                FlashcardsPage/index.tsx) → TabsCard variant="primary"
                (fe/components/tabs.md §0b, corrected 2026-07-09). */}
            <TabsCard
                variant="primary"
                leftTabs={{
                    items: [
                        { key: "study", label: t("flashcard.mode.study") },
                        { key: "quiz", label: t("flashcard.mode.quiz") },
                    ],
                    selectedKey: mode,
                    ariaLabel: t("flashcard.title"),
                    onSelectionChange: (key) => goMode(key as FlashcardMode),
                }}
            />
        </div>
    )
}

import React from "react"
import { Card, CardContent } from "@heroui/react"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { SurfaceListCard, SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import { Container } from "@/components/frames/Container"
import { Grid } from "@/components/frames/Grid"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * Loading placeholder for {@link import("./index").FlashcardQuizResult} — mirrors its
 * REAL layout tree: HERO = 3 `MetricCard` tiles (`Skeleton.Metric`), then the
 * per-card breakdown (`LabeledCard` label → `SurfaceListCard` of status-dot · title ·
 * score-chip rows), then the weak-tags recap card (label → framed card of link rows),
 * so the surface never collapses or jumps when the session query resolves. Used on
 * the revisit-by-URL path (skeleton → result).
 */
export const FlashcardQuizResultSkeleton = () => {
    return (
        <Container
            size="md"
            padding={1}
            body={() => (
                <StackV
                    gap={6}
                    items={[
                        () => (
                            // teacher-hold: flashcards-remain-quiz-result-metric-grid-gap4-no-token —
                            // peer metric tiles at preserved step 4; no card-grid token.
                            <Grid
                                principle="content-row"
                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                columns={{ base: 1, sm: 3 }}
                                items={[
                                    { key: "metric-1", content: () => <Skeleton.Metric /> },
                                    { key: "metric-2", content: () => <Skeleton.Metric /> },
                                    { key: "metric-3", content: () => <Skeleton.Metric /> },
                                ]}
                            />
                        ),
                        () => (
                            <StackV
                                as="section"
                                gap={4}
                                principle="label-field"
                                explain="Form label above its field — not title-subtitle, because the upper line labels an input rather than a heading pair."
                                items={[
                                    () => <Skeleton className="h-[14px] w-40 rounded" />,
                                    () => (
                                        <SurfaceListCard>
                                            {Array.from({ length: 5 }).map((_unused, index) => (
                                                <SurfaceListCardItem key={index}>
                                                    <StackH
                                                        gap={4}
                                                        principle="content-row"
                                                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                        align="center"
                                                        items={[
                                                            () => <Skeleton className="size-2.5 shrink-0 rounded-full" />,
                                                            () => (
                                                                <Skeleton.Typography
                                                                    type="body-sm"
                                                                    width="1/2"
                                                                    className="min-w-0 flex-1"
                                                                />
                                                            ),
                                                            () => <Skeleton className="h-5 w-12 shrink-0 rounded-full" />,
                                                        ]}
                                                    />
                                                </SurfaceListCardItem>
                                            ))}
                                        </SurfaceListCard>
                                    ),
                                ]}
                            />
                        ),
                        () => (
                            <StackV
                                as="section"
                                gap={4}
                                principle="label-field"
                                explain="Form label above its field — not title-subtitle, because the upper line labels an input rather than a heading pair."
                                items={[
                                    () => <Skeleton className="h-[14px] w-40 rounded" />,
                                    () => (
                                        <Card>
                                            <CardContent>
                                                <StackV
                                                    gap={3}
                                                    principle="sibling-stack"
                                                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                                    items={Array.from({ length: 3 }).map((_unused, index) => () => (
                                                        <Skeleton key={index} className="h-16 w-full rounded-xl" />
                                                    ))}
                                                />
                                            </CardContent>
                                        </Card>
                                    ),
                                ]}
                            />
                        ),
                    ]}
                />
            )}
        />
    )
}

import React from "react"
import { CheckCircleIcon } from "@phosphor-icons/react"
import type { QuizSessionReadinessData, QuizSessionWeakTagData } from "@/modules/api/graphql/mutations/types/complete-flashcard-quiz-session"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { MetricCard } from "@/components/composites/stats/MetricCard"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import type { SkeletonProps } from "@/components/frames/_slot"
import { Button } from "@/components/atoms/buttons/Button"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { BackLink } from "@/components/blocks/navigation/BackLink"
import { RelatedContentList } from "@/components/blocks/learn/RelatedContentList"
import { Container } from "@/components/frames/Container"
import { StackV } from "@/components/frames/Stack"
import { Grid } from "@/components/frames/Grid"
import { RecapEnrollUpsell, RecapReadinessCallout, RecapWeakTagsCard } from "./recapBlocks"

/** How many placeholder rows the per-card breakdown shows on the FIRST load (outer `isSkeleton`, results count unknown yet). */
const SKELETON_ROW_COUNT = 5

/** One already-resolved per-card breakdown row — status tone + aria label + score chip text, built by the connected {@link import("./index").FlashcardQuizResult}. */
export interface FlashcardQuizResultPerCardRow {
    /** Stable React key (`${cardId}-${index}`). */
    key: string
    /** Card front text, or the already-translated fallback when the card text hasn't resolved. */
    title: string
    /** Pass/partial/fail tone for the status dot + score chip. */
    tone: "success" | "warning" | "danger"
    /** Already-translated aria-label for the status dot ("Fully correct" / "Partially correct" / "Incorrect"). */
    statusLabel: string
    /** Already-translated "n/m" score chip text. */
    scoreLabel: string
}

/** Props for {@link _FlashcardQuizResult} — presentational; all data resolved, no fetch/store/i18n. */
export interface FlashcardQuizResultProps {
    /** First load, nothing in hand → the whole tree shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with no session to show (not found / not owned) → the empty message. */
    isEmpty?: boolean
    /** Truthy → the error message (beats loading + empty). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler for the error branch — re-runs the session fetch. */
    onRetry?: () => void
    /** Returns to the flashcards overview — the empty-branch action AND the closing CTA. */
    onBack: () => void

    breadcrumbLabel: string
    headerTitle: string
    headerDescription: string
    /** Shared title for both the error branch and the not-found empty branch (same text on both, existing behaviour). */
    fallbackTitle: string
    backToReviewLabel: string

    /** Final coverage (0..1), or `null` on a session with nothing to judge yet. */
    coverage?: number | null
    xpEarned?: number
    fullyCorrectCount?: number
    cardCount?: number
    coverageLabel: string
    xpLabel: string
    fullyCorrectLabel: string

    /** Whether today's daily XP cap clamped the grant (live path only). */
    dailyCapReached?: boolean
    dailyCapReachedLabel: string

    /** Whether the persisted session has any per-card results to break down. */
    hasPerCardResults?: boolean
    /** The per-card card-text fetch's own first-load flag (a NESTED async region, independent of the outer session load). */
    isPerCardSkeleton?: boolean
    /** Row count for the per-card skeleton once the outer session HAS resolved (`min(results.length, 5)`). */
    perCardSkeletonCount?: number
    perCardRows?: Array<FlashcardQuizResultPerCardRow>
    perCardHeading: string

    enrolled?: boolean
    enrollKnown?: boolean

    /** Top-3 weakest tags (state "empty" when none qualify). */
    topWeakTags?: Array<QuizSessionWeakTagData>
    /** Tags beyond the top-3, scrolled inside the same card. */
    overflowWeakTags?: Array<QuizSessionWeakTagData>
    /** Resolves a weak tag to its lesson route, or `null` when the mapping was ambiguous. */
    resolveTagHref?: (tag: QuizSessionWeakTagData) => string | null
    genericContinueHref?: string

    studyHeading: string
    /** Course id for the RAG "study this" child block. */
    courseId: string
    /** Course display id — needed for the same child's deep links. */
    courseDisplayId: string

    /** AI Mock Interview readiness (live path only, enrolled-only). */
    readiness?: QuizSessionReadinessData | null
    mockInterviewHref?: string
}

/** Status-dot tone → the class it paints (§4/§5: a bare decorative dot, sized+coloured once). */
const STATUS_DOT_CLASS: Record<"success" | "warning" | "danger", string> = {
    success: "size-2.5 shrink-0 rounded-full bg-success",
    warning: "size-2.5 shrink-0 rounded-full bg-warning",
    danger: "size-2.5 shrink-0 rounded-full bg-danger",
}

/**
 * A per-card breakdown row's leading status dot — colour carries the pass/partial/fail
 * tone, but never ALONE: `role="img"` + `aria-label` carry the same meaning for a
 * screen reader.
 */
const StatusDot = ({ tone, label }: StatusDotProps) => (
    <span className={STATUS_DOT_CLASS[tone]} role="img" aria-label={label} />
)

/**
 * The URL-addressable RESULT surface for a finished "Quick quiz" run — the presentational
 * half of {@link import("./index").FlashcardQuizResult}. Mirrors
 * {@link import("../QuizSession/FlashcardQuizStats").FlashcardQuizStats}'s shell: a centered
 * `Container size="md"` column of canonical blocks — HERO = three metric tiles
 * (coverage · XP · fully-correct), the per-card cloze breakdown, the most-forgotten
 * tags, and a self-hiding RAG "study this" list keyed off those tags.
 *
 * Three states in the fixed order error → empty → content (`tiers/split.md`,
 * `loading-and-skeleton.md` §1): `error` falls to the shared `AsyncContentError` frame,
 * `isEmpty` to `AsyncContentEmpty`, and otherwise the ONE real tree renders with
 * `isSkeleton` threaded to every leaf that supports it. `PageHeader`/`BackLink` carry no
 * `isSkeleton` of their own (`missingSkeletonSupport`) but need none here — they render
 * static, already-translated chrome text, not fetched data, so they stay unconditional
 * across every branch (the original design's own choice, preserved). `RecapEnrollUpsell`
 * / `RecapWeakTagsCard` / `RecapReadinessCallout` / `RelatedContentList` also carry no
 * `isSkeleton` (`missingSkeletonSupport`) and, same as the original parallel skeleton
 * never drew them while loading, are gated behind `!isSkeleton` instead of mirrored.
 * `SurfaceCardList`'s `leading`/`meta` row slots do not auto-forward `isSkeleton`
 * (`missingSkeletonSupport`) — the per-card rows are built as two different item
 * arrays (skeleton vs real, `StatusDot`/bare `Skeleton` swapped in directly), the same
 * shape `FlashcardQuizStats` already uses for its own gap rows.
 *
 * See `tiers/split.md` — the connected `index.tsx` owns the two fetches (session +
 * per-card text), the redux enrollment reads, and every i18n string.
 *
 * @param props - {@link FlashcardQuizResultProps}
 */
export const _FlashcardQuizResult = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    onBack,
    breadcrumbLabel,
    headerTitle,
    headerDescription,
    fallbackTitle,
    backToReviewLabel,
    coverage = null,
    xpEarned = 0,
    fullyCorrectCount = 0,
    cardCount = 0,
    coverageLabel,
    xpLabel,
    fullyCorrectLabel,
    dailyCapReached = false,
    dailyCapReachedLabel,
    hasPerCardResults = false,
    isPerCardSkeleton = false,
    perCardSkeletonCount = 0,
    perCardRows = [],
    perCardHeading,
    enrolled = false,
    enrollKnown = false,
    topWeakTags = [],
    overflowWeakTags = [],
    resolveTagHref = () => null,
    genericContinueHref = "",
    studyHeading,
    courseId,
    courseDisplayId,
    readiness = null,
    mockInterviewHref = "",
}: FlashcardQuizResultProps) => {
    const coverageValue = coverage != null ? `${Math.round(coverage * 100)}%` : "—"
    const xpValue = `+${xpEarned}`
    const fullyCorrectValue = `${fullyCorrectCount}/${cardCount}`

    const header = () => (
        <PageHeader
            breadcrumb={<BackLink label={breadcrumbLabel} onPress={onBack} />}
            title={headerTitle}
            description={headerDescription}
        />
    )

    const body = () => {
        // error beats a stale loading flag; the not-found empty branch only reads once
        // settled — the shared `AsyncContent*` frames, not hand-written JSX (loading-and-skeleton.md §6).
        if (error) {
            return (
                <AsyncContentError
                    title={fallbackTitle}
                    onRetry={onRetry}
                    retryLabel={backToReviewLabel}
                />
            )
        }
        if (!isSkeleton && isEmpty) {
            return (
                <AsyncContentEmpty
                    icon={CheckCircleIcon}
                    title={fallbackTitle}
                    action={() => (
                        <Button size="sm" variant="primary" onPress={onBack} label={backToReviewLabel} />
                    )}
                />
            )
        }

        const showPerCard = isSkeleton || hasPerCardResults
        const perCardListSkeleton = isSkeleton || isPerCardSkeleton
        const perCardItems: Array<SurfaceCardListItem> = perCardListSkeleton
            ? Array.from({ length: isSkeleton ? SKELETON_ROW_COUNT : perCardSkeletonCount }, (_unused, index) => ({
                key: `pending-${index}`,
                leading: () => <Skeleton className="size-2.5 shrink-0 rounded-full" />,
                meta: () => <Chip isSkeleton />,
            }))
            : perCardRows.map((row) => ({
                key: row.key,
                title: row.title,
                leading: () => <StatusDot tone={row.tone} label={row.statusLabel} />,
                meta: () => <Chip tone={row.tone} text={row.scoreLabel} />,
            }))

        const showUpsell = !isSkeleton && enrollKnown && !enrolled
        const weakTagsPrimary = enrollKnown && enrolled
        const showStudyList = !isSkeleton && topWeakTags.length > 0
        const showReadiness = !isSkeleton && enrollKnown && enrolled && readiness != null

        return (
            <StackV gap={6} principle="block-boundary"
                explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                items={[
                // HERO — three authoritative metric tiles (outcome first).
                    () => (
                    // teacher-hold: flashcards-remain-quiz-result-metric-grid-gap4-no-token —
                    // peer metric tiles at preserved step 4; no card-grid token.
                        <Grid
                            principle="content-row"
                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                            columns={{ base: 1, sm: 3 }}
                            isSkeleton={isSkeleton}
                            items={[
                                {
                                    key: "coverage",
                                    content: ({ isSkeleton: cellSkeleton }: SkeletonProps) => (
                                        cellSkeleton
                                            ? <MetricCard isSkeleton />
                                            : <MetricCard value={coverageValue} label={coverageLabel} />
                                    ),
                                },
                                {
                                    key: "xp",
                                    content: ({ isSkeleton: cellSkeleton }: SkeletonProps) => (
                                        cellSkeleton
                                            ? <MetricCard isSkeleton />
                                            : <MetricCard value={xpValue} label={xpLabel} />
                                    ),
                                },
                                {
                                    key: "fullyCorrect",
                                    content: ({ isSkeleton: cellSkeleton }: SkeletonProps) => (
                                        cellSkeleton
                                            ? <MetricCard isSkeleton />
                                            : <MetricCard value={fullyCorrectValue} label={fullyCorrectLabel} />
                                    ),
                                },
                            ]}
                        />
                    ),
                    ...(!isSkeleton && dailyCapReached ? [() => (
                        <Typography size="xs" color="muted" text={dailyCapReachedLabel} />
                    )] : []),

                    // PER-CARD breakdown — a NESTED async region (its own card-text fetch),
                    // so it carries its own `isPerCardSkeleton` on top of the outer one.
                    ...(showPerCard ? [() => (
                        <SurfaceCardList
                            label={perCardHeading}
                            isSkeleton={perCardListSkeleton}
                            items={perCardItems}
                        />
                    )] : []),

                    // enroll upsell (trial only) — the result's PRIMARY action for a trial
                    // viewer, framed as a reward for the momentum just built.
                    ...(showUpsell ? [() => <RecapEnrollUpsell />] : []),

                    // weak-tags demand-bridge: PRIMARY when enrolled, a smaller secondary
                    // link under the upsell when trial.
                    ...(!isSkeleton ? [() => (
                        <RecapWeakTagsCard
                            weakTags={topWeakTags}
                            overflowWeakTags={overflowWeakTags}
                            resolveTagHref={resolveTagHref}
                            genericHref={genericContinueHref}
                            primary={weakTagsPrimary}
                        />
                    )] : []),

                    // quiet, self-hiding "study this too" — RAG search keyed off the same
                    // weak tags (no typing); auto-hides when there are none.
                    ...(showStudyList ? [() => (
                        <RelatedContentList
                            courseId={courseId}
                            courseDisplayId={courseDisplayId}
                            query={topWeakTags.map((tag) => tag.tag).join(" ")}
                            label={studyHeading}
                        />
                    )] : []),

                    // AI Mock Interview readiness — live-only (query-absent), enrolled-only.
                    ...(showReadiness ? [() => (
                        <RecapReadinessCallout
                            readiness={readiness as QuizSessionReadinessData}
                            mockInterviewHref={mockInterviewHref}
                        />
                    )] : []),

                    // onward path — never a dead end, even with no weak tags.
                    ...(!isSkeleton ? [() => (
                        <Button variant="tertiary" onPress={onBack} label={backToReviewLabel} classNames={["self-center"]} />
                    )] : []),
                ]} />
        )
    }

    return (
        <Container
            identity={{ tier: "block", component: "FlashcardQuizResult" }}
            size="md"
            padding={{ base: { x: 5, y: 6 }, sm: { x: 6 } }}
            body={() => <StackV gap={6} principle="block-boundary"
                explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                items={[header, body]} />}
        />
    )
}

type StatusDotProps = { tone: "success" | "warning" | "danger"; label: string }

"use client"

import React, { useMemo } from "react"
import { useLocale, useTranslations } from "next-intl"
import { type QuizSessionReadinessData, type QuizSessionWeakTagData } from "@/modules/api/graphql/mutations/types/complete-flashcard-quiz-session"
import type { MyFlashcardQuizSessionBySessionIdData } from "@/modules/api/graphql/queries/types/my-flashcard-quiz-session-by-session-id"
import { pathConfig } from "@/resources/path"
import { useAppSelector } from "@/redux/hooks"
import { useQueryMyFlashcardQuizSessionBySessionIdSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyFlashcardQuizSessionBySessionIdSwr"
import { useQueryFlashcardCardsByIdsSwr } from "@/hooks/swr/api/graphql/queries/useQueryFlashcardCardsByIdsSwr"
import { _FlashcardQuizResult, type FlashcardQuizResultPerCardRow } from "./component"

/**
 * The live end-of-run payload handed straight to {@link FlashcardQuizResult} on the
 * natural-completion path — the just-finished session assembled from local run state
 * + the `completeFlashcardQuizSession` response. When present, the by-id session query
 * is SKIPPED (no redundant re-fetch, no stale in-progress cache read) and the
 * query-absent `readiness` signal is shown. Absent → the URL-revisit path, which
 * fetches the persisted snapshot by id.
 */
export interface FlashcardQuizResultLiveExtras {
    /** The just-finished session snapshot (same shape the by-id query returns). */
    data: MyFlashcardQuizSessionBySessionIdData
    /** AI Mock Interview readiness — query-absent, live-only (hidden on URL revisit). */
    readiness: QuizSessionReadinessData | null
    /** Whether today's daily XP cap clamped the grant (transparency note). */
    dailyCapReached: boolean
}

/** Props for {@link FlashcardQuizResult}. */
export interface FlashcardQuizResultProps {
    /** The finished "Quick quiz" session to recap. */
    sessionId: string
    /** Owning course id (uuid) — enrollment-guard header + RAG search scope. */
    courseId: string
    /** Owning course slug — needed to build deep links from the study list. */
    courseDisplayId: string
    /** Returns to the flashcards overview (the single onward path — no dead end). */
    onBack: () => void
    /** Present on the LIVE end-of-run path — see {@link FlashcardQuizResultLiveExtras}. */
    live?: FlashcardQuizResultLiveExtras
}

/** Per-card outcome bucket — drives the status dot tone + aria label (never color-only). */
type PerCardStatus = "ok" | "partial" | "none"

/** Classify a card's cloze breakdown into a status bucket. */
const classify = (correctBlanks: number, totalBlanks: number): PerCardStatus => {
    if (totalBlanks > 0 && correctBlanks >= totalBlanks) {
        return "ok"
    }
    return correctBlanks > 0 ? "partial" : "none"
}

/** Status bucket → the presentational tone (chip/dot colour). */
const TONE_BY_STATUS: Record<PerCardStatus, "success" | "warning" | "danger"> = {
    ok: "success",
    partial: "warning",
    none: "danger",
}

/**
 * The URL-addressable RESULT surface for a finished "Quick quiz" run — the CONNECTED
 * half: resolves the session (live hand-off or by-id revisit), re-hydrates the
 * per-card text, reads the enrollment flags, builds every deep link, and resolves
 * every i18n string, handing it all to the presentational {@link _FlashcardQuizResult}.
 * See `design/storybook/architecture/split.md`.
 *
 * @param props - {@link FlashcardQuizResultProps}
 */
export const FlashcardQuizResult = ({
    sessionId,
    courseId,
    courseDisplayId,
    onBack,
    live,
}: FlashcardQuizResultProps) => {
    const t = useTranslations()
    const locale = useLocale()
    // trial vs enrolled — gates the enroll upsell (trial) + the AI Mock Interview
    // readiness cross-link (enrolled). Populated globally by `learn/layout.tsx`.
    const enrolled = useAppSelector((state) => state.user.enrolled)
    const enrollKnown = useAppSelector((state) => state.user.enrollKnown)

    // live path hands the data in directly (no fetch); revisit path resolves by id.
    const sessionSwr = useQueryMyFlashcardQuizSessionBySessionIdSwr(live ? undefined : sessionId, courseId)
    const data = live?.data ?? sessionSwr.data

    // first load, nothing in hand (loading-and-skeleton.md §2) — a background
    // revalidation never re-flashes the skeleton over content already on screen.
    const isSkeleton = !data && !sessionSwr.error
    const isEmpty = !isSkeleton && !data

    // per-card breakdown needs the card TEXT — the persisted `results` carry only
    // blank counts by id, so re-hydrate the text (both paths, one code path). A
    // NESTED async region: its own first-load flag, independent of the session's.
    const resultCardIds = useMemo(() => (data?.results ?? []).map((result) => result.cardId), [data])
    const cardsSwr = useQueryFlashcardCardsByIdsSwr(resultCardIds, courseId)
    const cardById = useMemo(
        () => new Map((cardsSwr.data ?? []).map((card) => [card.cardId, card])),
        [cardsSwr.data],
    )
    const isPerCardSkeleton = !cardsSwr.data && !cardsSwr.error

    const perCardRows: Array<FlashcardQuizResultPerCardRow> = useMemo(() => {
        if (!data) {
            return []
        }
        return data.results.map((result, index) => {
            const status = classify(result.correctBlanks, result.totalBlanks)
            const card = cardById.get(result.cardId)
            return {
                key: `${result.cardId}-${index}`,
                title: card?.front ?? t("flashcard.quiz.result.cardFallback", { index: index + 1 }),
                tone: TONE_BY_STATUS[status],
                statusLabel: t(`flashcard.quiz.result.cardStatus.${status}`),
                scoreLabel: t("flashcard.quiz.result.cardScore", {
                    correct: result.correctBlanks,
                    total: result.totalBlanks,
                }),
            }
        })
    }, [data, cardById, t])

    // deep-link builders for the weak-tags demand-bridge + the readiness cross-link —
    // independent of `data` (only need locale/courseDisplayId), so no guard needed.
    const learn = pathConfig().locale(locale).course(courseDisplayId).learn()
    const genericContinueHref = learn.module().build()
    const mockInterviewHref = learn.mockInterview().build()
    // resolves a weak tag straight to its lesson when the deck→lesson mapping was
    // unambiguous; `null` → the presentational half falls back to `genericContinueHref`.
    const resolveTagHref = (tag: QuizSessionWeakTagData): string | null => (
        tag.moduleId && tag.contentId
            ? learn.module(tag.moduleId).content(tag.contentId).build()
            : tag.moduleId
                ? learn.module(tag.moduleId).build()
                : null
    )
    const topWeakTags = data?.weakTags.slice(0, 3) ?? []
    const overflowWeakTags = data?.weakTags.slice(3) ?? []

    return (
        <_FlashcardQuizResult
            isSkeleton={isSkeleton}
            isEmpty={isEmpty}
            error={!data ? sessionSwr.error : undefined}
            onRetry={() => { void sessionSwr.mutate() }}
            onBack={onBack}
            breadcrumbLabel={t("flashcard.title")}
            headerTitle={t("flashcard.quiz.result.title")}
            headerDescription={t("flashcard.quiz.result.subtitle")}
            fallbackTitle={t("flashcard.quiz.result.fallback")}
            backToReviewLabel={t("flashcard.quiz.result.backToReview")}
            coverage={data?.coverage ?? null}
            xpEarned={data?.xpEarned ?? 0}
            fullyCorrectCount={data?.fullyCorrectCount ?? 0}
            cardCount={data?.cardCount ?? 0}
            coverageLabel={t("flashcard.quiz.result.coverageLabel")}
            xpLabel={t("flashcard.quiz.result.xpLabel")}
            fullyCorrectLabel={t("flashcard.quiz.result.fullyCorrectLabel")}
            dailyCapReached={Boolean(live?.dailyCapReached)}
            dailyCapReachedLabel={t("flashcard.quiz.dailyCapReached")}
            hasPerCardResults={Boolean(data && data.results.length > 0)}
            isPerCardSkeleton={isPerCardSkeleton}
            perCardSkeletonCount={data ? Math.min(data.results.length, 5) : 0}
            perCardRows={perCardRows}
            perCardHeading={t("flashcard.quiz.result.perCardHeading")}
            enrolled={enrolled}
            enrollKnown={enrollKnown}
            topWeakTags={topWeakTags}
            overflowWeakTags={overflowWeakTags}
            resolveTagHref={resolveTagHref}
            genericContinueHref={genericContinueHref}
            studyHeading={t("flashcard.quiz.result.studyHeading")}
            courseId={courseId}
            courseDisplayId={courseDisplayId}
            readiness={live?.readiness ?? null}
            mockInterviewHref={mockInterviewHref}
        />
    )
}

"use client"

import React, { useCallback } from "react"
import { Button, ScrollShadow, Typography } from "@heroui/react"
import { ArrowRightIcon, FlameIcon, LockIcon, MicrophoneStageIcon } from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { type QuizSessionReadinessData, type QuizSessionWeakTagData } from "@/modules/api/graphql/mutations/types/complete-flashcard-quiz-session"
import { Callout } from "@/components/composites/feedback/Callout"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { SurfaceListCardRow } from "@/components/blocks/cards/SurfaceListCard"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"
import { usePaymentOverlayState } from "@/hooks/zustand/overlay/hooks"
import { PaymentFlow } from "@/modules/types/payment"

/**
 * Shared "Quick quiz" recap/result blocks — LIFTED out of `QuizSession` so BOTH the
 * live end-of-run recap and the URL-addressable {@link import("./index").FlashcardQuizResult}
 * surface render the exact same components instead of duplicating them. Each block
 * is a self-contained conversion node (enroll upsell, weak-tags demand bridge, AI
 * Mock Interview readiness cross-link).
 */

/**
 * Recap Zone E — the enroll upsell shown ONLY to trial viewers, as the result's
 * PRIMARY action. Reads as an earned reward for the streak/XP the learner just
 * built — not a blocking paywall. Opens the shared course-enroll payment overlay.
 */
export const RecapEnrollUpsell = () => {
    const t = useTranslations()
    const { open } = usePaymentOverlayState()

    const onEnroll = useCallback(
        () => open({ flow: PaymentFlow.CourseEnroll }),
        [open],
    )

    return (
        <Box principle="page-pad" className="rounded-2xl border border-default bg-default px-6 py-8 text-center"
            explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface.">
            <StackV gap={4} align="center" items={[
                () => <IconTile icon={<FlameIcon aria-hidden focusable="false" />} tone="accent" size="sm" />,
                () => (
                    <StackV gap={2} principle="title-subtitle"
                        explain="Title over supporting line — not label-field, because neither line is a form control label."
                        items={[
                            () => (
                                <Typography type="h4" weight="semibold">
                                    {t("flashcard.quiz.upsellTitle")}
                                </Typography>
                            ),
                            () => (
                                <Typography type="body-sm" color="muted">
                                    {t("flashcard.quiz.upsellDescription")}
                                </Typography>
                            ),
                        ]} />
                ),
                () => (
                    <Button
                        variant="primary"
                        size="lg"
                        className="mt-1 w-full max-w-xs"
                        onPress={onEnroll}
                    >
                        {t("flashcard.quiz.upsellCta")}
                        <ArrowRightIcon aria-hidden focusable="false" className="size-5" />
                    </Button>
                ),
            ]} />
        </Box>
    )
}

/** Props for {@link RecapWeakTagsCard}. */
export interface RecapWeakTagsCardProps {
    /** Top-3 weakest tags to always show (empty when nothing qualifies — state "empty"). */
    weakTags: Array<QuizSessionWeakTagData>
    /** Any tags beyond the top-3 — scrolled INSIDE this same card, never truncated silently
     *  and never a separate drawer (state "overflow"). */
    overflowWeakTags: Array<QuizSessionWeakTagData>
    /** Resolves a weak tag to its lesson route, or `null` when the deck→lesson mapping was
     *  ambiguous (falls back to `genericHref` for that row). */
    resolveTagHref: (tag: QuizSessionWeakTagData) => string | null
    /** Generic "continue learning" destination — the empty-state CTA AND the fallback for
     *  any weak tag whose lesson mapping was ambiguous. */
    genericHref: string
    /** Whether this card is the result's PRIMARY demand-bridge (enrolled viewers) or a
     *  smaller secondary link (trial viewers, where Zone E takes the primary slot instead). */
    primary: boolean
}

/** One weak-tag row: tag label + coverage + a "review this lesson" link. */
const WeakTagRow = ({
    tag,
    href,
}: WeakTagRowProps) => {
    const t = useTranslations()
    const router = useRouter()
    return (
        <SurfaceListCardRow
            title={tag.tag}
            subtitle={t("flashcard.quiz.weakTagCoverage", { percent: Math.round(tag.coverage * 100) })}
            trailing={() => (
                <StackH gap={2} principle="icon-text"
                    explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
                    align="center" classNames={["shrink-0"]} items={[
                        () => <span className="text-sm font-medium text-accent-soft-foreground">{t("flashcard.quiz.reviewLesson")}</span>,
                        () => (
                            <ArrowRightIcon
                                aria-hidden
                                focusable="false"
                                className="size-4 transition-transform group-hover:translate-x-1"
                            />
                        ),
                    ]} />
            )}
            hover="underline"
            onPress={() => router.push(href)}
        />
    )
}

/**
 * Recap Zone C — the demand-bridge from "just played" to "go learn". Ranks the
 * session's weakest tags and links each straight back to the lesson that covers
 * it; falls back to a generic "keep learning" CTA when there's no weak-tag data
 * yet (first session, or the mapping was ambiguous). Overflow past the top-3
 * scrolls inside the same card via `ScrollShadow` — never a drawer.
 */
export const RecapWeakTagsCard = ({
    weakTags,
    overflowWeakTags,
    resolveTagHref,
    genericHref,
    primary,
}: RecapWeakTagsCardProps) => {
    const t = useTranslations()
    const router = useRouter()

    // no weak-tag data at all → the one, simple, generic bridge (state "empty"). When
    // this card IS the result's primary action (enrolled, no upsell competing), the CTA
    // is a full primary button; when it's demoted (trial), it's a standalone tertiary link.
    if (weakTags.length === 0) {
        return primary ? (
            <LabeledCard label={t("flashcard.quiz.weakTagsTitle")}>
                <StackV gap={4} items={[
                    () => (
                        <Typography type="body-sm" color="muted">
                            {t("flashcard.quiz.weakTagsEmpty")}
                        </Typography>
                    ),
                    () => (
                        <Button
                            variant="primary"
                            className="self-start"
                            onPress={() => router.push(genericHref)}
                        >
                            {t("flashcard.quiz.continueLearning")}
                            <ArrowRightIcon className="size-5" aria-hidden focusable="false" />
                        </Button>
                    ),
                ]} />
            </LabeledCard>
        ) : (
            <Button
                variant="tertiary"
                size="sm"
                className="self-start"
                onPress={() => router.push(genericHref)}
            >
                {t("flashcard.quiz.continueLearning")}
                <ArrowRightIcon className="size-4" aria-hidden focusable="false" />
            </Button>
        )
    }

    // secondary (trial) rendering: a smaller link-style row, not the full card — Zone E
    // (enroll upsell) is the primary action instead (state "mixed (trial)"). Standalone,
    // no primary beside it → tertiary.
    if (!primary) {
        const first = weakTags[0]
        const firstHref = resolveTagHref(first) ?? genericHref
        return (
            <Button
                variant="tertiary"
                size="sm"
                className="self-start"
                onPress={() => router.push(firstHref)}
            >
                {t("flashcard.quiz.weakTagSecondaryLink", { tag: first.tag })}
                <ArrowRightIcon className="size-4" aria-hidden focusable="false" />
            </Button>
        )
    }

    return (
        <LabeledCard label={t("flashcard.quiz.weakTagsTitle")}>
            <StackV gap={4} items={[
                () => (
                    <StackV gap={3} principle="sibling-stack"
                        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                        items={weakTags.map((tag) => () => (
                            <WeakTagRow key={tag.tag} tag={tag} href={resolveTagHref(tag) ?? genericHref} />
                        ))} />
                ),
                ...(overflowWeakTags.length > 0 ? [() => (
                    <ScrollShadow hideScrollBar className="max-h-40 overflow-y-auto">
                        <StackV gap={3} principle="sibling-stack"
                            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                            items={overflowWeakTags.map((tag) => () => (
                                <WeakTagRow key={tag.tag} tag={tag} href={resolveTagHref(tag) ?? genericHref} />
                            ))} />
                    </ScrollShadow>
                )] : []),
            ]} />
        </LabeledCard>
    )
}

/** Props for {@link RecapReadinessCallout}. */
export interface RecapReadinessCalloutProps {
    /** The readiness signal returned by `completeFlashcardQuizSession`. */
    readiness: QuizSessionReadinessData
    /** Route to the AI Mock Interview surface (only navigated to once unlocked). */
    mockInterviewHref: string
}

/**
 * Recap Zone D — the cross-link toward the AI Mock Interview (StarCi's actual
 * AI-graded, credit-costing differentiator), so a learner who finishes "Quick
 * quiz" feeling good is pointed at it instead of never hearing it exists.
 * Locked state stays visible (transparent about the threshold) rather than hiding.
 */
export const RecapReadinessCallout = ({ readiness, mockInterviewHref }: RecapReadinessCalloutProps) => {
    const t = useTranslations()
    const router = useRouter()

    if (!readiness.unlocked) {
        return (
            <Callout
                status="default"
                icon={LockIcon}
                title={t("flashcard.quiz.readinessLockedTitle")}
                description={t("flashcard.quiz.readinessLockedDescription", {
                    currentAvg: readiness.currentAvg,
                    threshold: readiness.threshold,
                })}
            />
        )
    }

    return (
        <Callout
            status="success"
            icon={MicrophoneStageIcon}
            title={t("flashcard.quiz.readinessUnlockedTitle")}
            description={t("flashcard.quiz.readinessUnlockedDescription")}
            actionLabel={t("flashcard.quiz.readinessUnlockedCta")}
            onAction={() => router.push(mockInterviewHref)}
        />
    )
}

type WeakTagRowProps = {
    tag: QuizSessionWeakTagData
    href: string
}

"use client"

import { InputSearch } from "@/components/atoms/forms"
import React, { useMemo, useState } from "react"
import { CardsIcon, ClockCounterClockwiseIcon, ClockIcon } from "@phosphor-icons/react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { SurfaceListCard, SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import { LabeledAccordionCard } from "@/components/blocks/cards/LabeledAccordionCard"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { TabsCard } from "@/components/blocks/navigation/TabsCard"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"
import { Box } from "@/components/frames/Box"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Button } from "@/components/atoms/buttons/Button"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"

import { StackV, StackH } from "@/components/frames/Stack"
import type { QueryFlashcardReviewHistoryItem } from "@/modules/api/graphql/queries/types/my-flashcard-review-history"
import { groupByTimeBucket } from "@/modules/utils/history-buckets"

/** This component's own `data-tier`/`data-component` identity (split.md — "identity is `data-tier` + `data-component`"). */
const IDENTITY = { tier: "block", component: "FlashcardReviewHistory" } as const

/** How the run list is grouped: by deck (accordion) or by time bucket. */
export type FlashcardReviewHistoryGroupMode = "deck" | "time"

/** How many placeholder rows the co-located skeleton shows while the first page loads. */
const SKELETON_ROW_COUNT = 4

/** The completion bar reads success at/above this reviewed-ratio, else warning. */
const STRONG_COMPLETION_RATIO = 0.8

/**
 * All display text, already localized by the connected `FlashcardReviewHistory`; a story
 * passes i18n keys. A few members are FUNCTIONS rather than plain strings — `cardCount` /
 * `xp` / `deckRunCount` / `timeBucket` / `runCount` interpolate PER ROW or PER GROUP, so a
 * single resolved string (the shape every other label in this system takes) cannot carry
 * them; the connected file still owns every `t()` call, it just hands down a resolver
 * instead of a value.
 */
export interface FlashcardReviewHistoryLabels {
    errorTitle: string
    retry: string
    emptyTitle: string
    emptyDescription: string
    emptyAction: string
    searchPlaceholder: string
    groupByDeck: string
    groupByTime: string
    filterEmpty: string
    loadMore: string
    /** Per-row "reviewed/total" caption. */
    cardCount: (reviewedCount: number, cardCount: number) => string
    /** Per-row XP chip text. */
    xp: (xpEarned: number) => string
    /** "N runs" — used both for the search result count and per-deck-group count. */
    deckRunCount: (count: number) => string
    /** Resolves a {@link TimeBucketKey} into its heading. */
    timeBucket: (key: string) => string
    /** "N runs" caption trailing a time-bucket heading. */
    runCount: (count: number) => string
}

/** Props for {@link _FlashcardReviewHistory} — presentational; all data resolved, no fetch/store/i18n. */
export interface FlashcardReviewHistoryProps {
    /** Runs fetched so far (accumulated across "load more" pages), `updatedAt DESC`. */
    items: Array<QueryFlashcardReviewHistoryItem>
    /** Total run count across every page — gates the "load more" button. */
    totalCount: number
    /** First load, nothing in hand → the whole tree shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with zero runs at all → the empty message. */
    isEmpty?: boolean
    /** Truthy → the error message (beats loading + empty). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler — paired with `labels.retry` to show a retry button on the error branch. */
    onRetry?: () => void
    /** Fetches the next offset-paginated page. */
    onLoadMore: () => void
    /** True while a "load more" page is in flight — disables the load-more button. */
    isLoadingMore?: boolean
    /** Formats an ISO timestamp in the viewer's locale (medium date style) — resolved by the connected file so this stays store-free. */
    formatDate: (iso: string) => string
    /** Deep-links a run's deck into its reviewer. */
    onOpenDeck: (deckId: string) => void
    /** Jumps the overview tab strip back to the study overview (empty-state action). */
    onStartReview?: () => void
    labels: FlashcardReviewHistoryLabels
}

/**
 * "Study cards" run history — the presentational half of {@link FlashcardReviewHistory}, composed
 * on the tier-correct vocabulary (`InputSearch` / `TabsCard` / `LabeledAccordionCard` /
 * `LabeledCard` / `SurfaceListCard` / `ProgressMeter`). Three states in the fixed order
 * error → skeleton → empty → content (`loading-and-skeleton.md`): `error` falls to the shared
 * `AsyncContentError` frame, `isEmpty` (once settled) to `AsyncContentEmpty`, and otherwise the
 * ONE toolbar+list tree renders with `isSkeleton` threaded to every leaf that carries it.
 *
 * `TabsCard` / `LabeledAccordionCard` / `LabeledCard` / `ProgressMeter` carry no `isSkeleton` of
 * their own (missingSkeletonSupport) — their loading state is mirrored MINIMALLY, right where
 * they sit, with `Skeleton.*` instead of a parallel tree elsewhere in the file.
 *
 * @param props - {@link FlashcardReviewHistoryProps}
 */
export const _FlashcardReviewHistory = ({
    items,
    totalCount,
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    onLoadMore,
    isLoadingMore = false,
    formatDate,
    onOpenDeck,
    onStartReview,
    labels,
}: FlashcardReviewHistoryProps) => {
    const [query, setQuery] = useState("")
    const [groupMode, setGroupMode] = useState<FlashcardReviewHistoryGroupMode>("deck")

    // search filters the loaded runs by deck title (client-side over already-fetched
    // items — no BE change; the deck title is already in the response).
    const searchedItems = useMemo(() => {
        const needle = query.trim().toLowerCase()
        if (!needle) {
            return items
        }
        return items.filter((item) => item.deckTitle.toLowerCase().includes(needle))
    }, [items, query])

    // group runs by deck — the same deck reviewed multiple times otherwise scatters
    // across the flat timeline. `items` is already `updatedAt DESC` and `Map` preserves
    // first-seen order, so a group's position = its MOST RECENT run — no re-sort needed.
    const groupedByDeck = useMemo(() => {
        const groups = new Map<string, { deckId: string, deckTitle: string, items: Array<QueryFlashcardReviewHistoryItem> }>()
        for (const item of searchedItems) {
            const existing = groups.get(item.deckId)
            if (existing) {
                existing.items.push(item)
            } else {
                groups.set(item.deckId, { deckId: item.deckId, deckTitle: item.deckTitle, items: [item] })
            }
        }
        return Array.from(groups.values())
    }, [searchedItems])

    const timeBuckets = useMemo(
        () => groupByTimeBucket(searchedItems, (item) => item.updatedAt),
        [searchedItems],
    )

    // error beats a stale loading flag; empty only once settled (loading-and-skeleton.md §1).
    if (error) {
        return <AsyncContentError identity={IDENTITY} title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retry} />
    }
    if (!isSkeleton && isEmpty) {
        return (
            <AsyncContentEmpty
                identity={IDENTITY}
                icon={ClockCounterClockwiseIcon}
                title={labels.emptyTitle}
                description={labels.emptyDescription}
                action={onStartReview ? () => (
                    <Button label={labels.emptyAction} variant="secondary" size="sm" onPress={onStartReview} />
                ) : undefined}
            />
        )
    }

    /** Shared row body — `showDeck` puts the deck title on the primary line (time
     *  grouping, where the deck isn't the group header), else the date leads. */
    const runRow = (item: QueryFlashcardReviewHistoryItem, showDeck: boolean) => {
        const ratio = item.cardCount > 0 ? item.reviewedCount / item.cardCount : 0
        const cardCountLabel = labels.cardCount(item.reviewedCount, item.cardCount)
        return (
            <StackH gap={3} items={[
                () => (
                    <StackV gap={1} classNames={["min-w-0", "flex-1"]} items={[
                        () => <Typography size="sm" truncate text={showDeck ? item.deckTitle : formatDate(item.updatedAt)} />,
                        () => <Typography size="xs" color="muted" truncate text={showDeck ? `${formatDate(item.updatedAt)} · ${cardCountLabel}` : cardCountLabel} />,
                        () => (
                            <Box className="max-w-[220px]">
                                <ProgressMeter
                                    value={item.reviewedCount}
                                    max={Math.max(item.cardCount, 1)}
                                    color={ratio >= STRONG_COMPLETION_RATIO ? "success" : "warning"}
                                />
                            </Box>
                        ),
                    ]} />
                ),
                ...(item.xpEarned > 0 ? [() => (
                    <Chip tone="warning" text={labels.xp(item.xpEarned)} classNames={["shrink-0"]} />
                )] : []),
            ]} />
        )
    }

    // Toolbar: search decks (left) + run count and grouping toggle (right). `TabsCard`
    // carries no `isSkeleton` of its own — its loading state mirrors it inline with a bare
    // `Skeleton`, right where it sits (missingSkeletonSupport), instead of a parallel tree.
    const toolbar = (
        <StackH gap={4} principle="content-row" justify="between" at="sm"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            items={[
                () => (
                    <Box className="w-full">
                        <InputSearch
                            isSkeleton={isSkeleton}
                            ariaLabel={labels.searchPlaceholder}
                            placeholder={labels.searchPlaceholder}
                            value={query}
                            onValueChange={setQuery}
                        />
                    </Box>
                ),
                () => (
                    <StackH gap={3} classNames={["shrink-0"]} items={[
                        () => <Typography size="sm" color="muted" isSkeleton={isSkeleton} text={labels.deckRunCount(searchedItems.length)} />,
                        () => (isSkeleton ? (
                            <Skeleton className="h-9 w-16 rounded-medium" />
                        ) : (
                            <TabsCard
                                variant="primary"
                                leftTabs={{
                                    selectedKey: groupMode,
                                    ariaLabel: labels.groupByDeck,
                                    onSelectionChange: (key) => setGroupMode(String(key) as FlashcardReviewHistoryGroupMode),
                                    items: [
                                        {
                                            key: "deck",
                                            label: <CardsIcon className="size-5" aria-label={labels.groupByDeck} focusable="false" />,
                                        },
                                        {
                                            key: "time",
                                            label: <ClockIcon className="size-5" aria-label={labels.groupByTime} focusable="false" />,
                                        },
                                    ],
                                }}
                            />
                        )),
                    ]} />
                ),
            ]} />
    )

    // Flat placeholder rows — the loading state's list shape, regardless of `groupMode`
    // (the real grouped shape isn't known yet). `SurfaceListCard`/`SurfaceListCardItem` are
    // reused as-is (their own chrome carries no data), only the row CONTENT swaps to `Skeleton.*`.
    const listSkeleton = (
        <SurfaceListCard>
            {Array.from({ length: SKELETON_ROW_COUNT }, (_unused, index) => (
                <SurfaceListCardItem key={index}>
                    <StackH gap={3} items={[
                        () => (
                            <StackV gap={1} classNames={["min-w-0", "flex-1"]} items={[
                                () => <Skeleton.Typography type="body-sm" width="1/2" />,
                                () => <Skeleton.Typography type="body-xs" width="1/3" />,
                                () => <Skeleton.ProgressBar className="max-w-[220px]" />,
                            ]} />
                        ),
                        () => <Skeleton className="h-6 w-12 shrink-0 rounded-full" />,
                    ]} />
                </SurfaceListCardItem>
            ))}
        </SurfaceListCard>
    )

    const body = isSkeleton ? listSkeleton : searchedItems.length === 0 ? (
        <SurfaceCard body={() => <Typography size="sm" color="muted" align="center" text={labels.filterEmpty} />} />
    ) : groupMode === "deck" ? (
        // group=deck — NO `label` (the toolbar's group toggle is the heading); "N runs"
        // rides in the header via `titleEnd`, panel = that deck's runs.
        <LabeledAccordionCard
            items={groupedByDeck.map((group) => ({
                id: group.deckId,
                title: group.deckTitle,
                titleEnd: () => (
                    <Typography size="xs" color="muted" classNames={["shrink-0"]} text={labels.deckRunCount(group.items.length)} />
                ),
                body: () => (
                    <StackV gap={1} items={group.items.map((item) => () => (
                        <Box key={item.id} principle="control-pad" className="rounded-lg px-3 py-2 text-left transition-colors hover:bg-default"
                            explain="Control hit-area inset — not row-pad, because this pads a single interactive control rather than a full content row.">
                            <button
                                type="button"
                                onClick={() => onOpenDeck(item.deckId)}
                                className="w-full text-left"
                            >
                                {runRow(item, false)}
                            </button>
                        </Box>
                    ))} />
                ),
            }))}
        />
    ) : (
        // group=time — each non-empty bucket is a `LabeledCard frameless` (time window =
        // label OUTSIDE + run count via `labelEnd`; content is itself a `SurfaceListCard`
        // → frameless avoids card-in-card).
        <StackV gap={3} items={timeBuckets.map((bucket) => () => (
            <LabeledCard
                frameless
                subtleLabel
                label={labels.timeBucket(bucket.key)}
                labelEnd={labels.runCount(bucket.items.length)}
            >
                <SurfaceListCard>
                    {bucket.items.map((item) => (
                        <SurfaceListCardItem key={item.id} onPress={() => onOpenDeck(item.deckId)}>
                            {runRow(item, true)}
                        </SurfaceListCardItem>
                    ))}
                </SurfaceListCard>
            </LabeledCard>
        ))} />
    )

    const showLoadMore = !isSkeleton && items.length < totalCount

    return (
        <StackV gap={3} identity={IDENTITY} items={[
            () => toolbar,
            () => body,
            ...(showLoadMore ? [() => (
                <Button
                    variant="secondary"
                    size="sm"
                    classNames={["self-center"]}
                    isDisabled={isLoadingMore}
                    onPress={onLoadMore}
                    label={labels.loadMore}
                />
            )] : []),
        ]} />
    )
}

"use client"

import React, { useEffect, useRef, useState } from "react"
import useSWR from "swr"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { queryMyFlashcardReviewHistory } from "@/modules/api/graphql/queries/query-my-flashcard-review-history"
import type { QueryFlashcardReviewHistoryItem } from "@/modules/api/graphql/queries/types/my-flashcard-review-history"
import { useAppSelector } from "@/redux/hooks"
import { pathConfig } from "@/resources/path"
import { _FlashcardReviewHistory } from "./component"

/** History items fetched per "load more" page. */
const PAGE_SIZE = 10

/** Props for {@link FlashcardReviewHistory}. */
export interface FlashcardReviewHistoryProps {
    /** Course whose "Study cards" review session history to list. */
    courseId: string
    /** Jumps the overview tab strip back to the study overview — wired from
     *  `FlashcardsPage` so the empty state's action can start reviewing without
     *  this component owning the tab switcher itself. */
    onStartReview?: () => void
}

/**
 * "Study cards" run history — the study overview's "History" tab. The CONNECTED half: it
 * accumulates offset-paginated pages, resolves every label (incl. per-row/per-group
 * interpolation), and hands them to the presentational {@link _FlashcardReviewHistory}. See
 * `design/storybook/architecture/split.md`.
 *
 * @param props - {@link FlashcardReviewHistoryProps}
 */
export const FlashcardReviewHistory = ({ courseId, onStartReview }: FlashcardReviewHistoryProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const displayId = useAppSelector((state) => state.course.displayId)

    const [offset, setOffset] = useState(0)
    const [items, setItems] = useState<Array<QueryFlashcardReviewHistoryItem>>([])
    const [totalCount, setTotalCount] = useState(0)

    const historySwr = useSWR(
        ["flashcard-review-history", courseId, offset],
        async () => {
            const response = await queryMyFlashcardReviewHistory({
                request: { courseId, limit: PAGE_SIZE, offset },
            })
            return response.data?.myFlashcardReviewHistory.data ?? null
        },
    )

    // accumulate pages as `offset` advances ("load more"); a fresh `courseId`
    // resets the accumulator (guarded by the effect below).
    useEffect(() => {
        const data = historySwr.data
        if (!data) {
            return
        }
        setItems((previous) => (offset === 0 ? data.items : [...previous, ...data.items]))
        setTotalCount(data.totalCount)
    }, [historySwr.data, offset])

    // course changed → start the accumulator over. Guarded against firing on
    // mere MOUNT (the teacher, 2026-07-13: "switch tabs and everything's gone" — this tab is
    // unmounted/remounted by the parent's tab switch; an unguarded version fires on every
    // remount too since `courseId` is "new" to a fresh effect subscription, wiping the
    // `items` this same render's data-effect had JUST populated from SWR's still-warm
    // cache — a real state-loss bug, not just a data problem).
    const previousCourseIdRef = useRef(courseId)
    useEffect(() => {
        if (previousCourseIdRef.current === courseId) {
            return
        }
        previousCourseIdRef.current = courseId
        setOffset(0)
        setItems([])
    }, [courseId])

    const formatDate = (iso: string) =>
        new Intl.DateTimeFormat(locale, { dateStyle: "medium" }).format(new Date(iso))

    const goToDeck = (deckId: string) => router.push(
        pathConfig().locale(locale).course(displayId).learn().flashcards().review(deckId).build(),
    )

    return (
        <_FlashcardReviewHistory
            items={items}
            totalCount={totalCount}
            // first load, nothing in hand → shimmer; settled (data OR error) stops it (loading-and-skeleton.md §2)
            isSkeleton={historySwr.isLoading && items.length === 0}
            // settled with zero runs at all
            isEmpty={items.length === 0}
            // error beats loading + empty; only a settled fetch error (nothing cached) reaches the block
            error={items.length === 0 ? historySwr.error : undefined}
            onRetry={() => { void historySwr.mutate() }}
            onLoadMore={() => setOffset((previous) => previous + PAGE_SIZE)}
            isLoadingMore={historySwr.isLoading}
            formatDate={formatDate}
            onOpenDeck={goToDeck}
            onStartReview={onStartReview}
            labels={{
                errorTitle: t("flashcard.review.historyError"),
                retry: t("flashcard.review.retry"),
                emptyTitle: t("flashcard.review.historyEmptyTitle"),
                emptyDescription: t("flashcard.review.historyEmptyDescription"),
                emptyAction: t("flashcard.review.historyEmptyAction"),
                searchPlaceholder: t("flashcard.review.historySearchPlaceholder"),
                groupByDeck: t("flashcard.review.historyGroupByDeck"),
                groupByTime: t("flashcard.review.historyGroupByTime"),
                filterEmpty: t("flashcard.review.historyFilterEmpty"),
                loadMore: t("flashcard.review.historyLoadMore"),
                cardCount: (reviewedCount, cardCount) => t("flashcard.review.historyCardCount", { reviewedCount, cardCount }),
                xp: (xpEarned) => t("flashcard.quiz.xpToast", { xp: xpEarned }),
                deckRunCount: (count) => t("flashcard.review.historyDeckRunCount", { count }),
                timeBucket: (key) => t(`flashcard.timeBucket.${key}`),
                runCount: (count) => t("flashcard.runCount", { count }),
            }}
        />
    )
}

"use client"

import React, { useEffect, useState } from "react"
import { ArrowRightIcon, CardsIcon, ClockCountdownIcon } from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { Button } from "@/components/atoms/buttons/Button"
import { Typography } from "@/components/atoms/text/Typography"
import { ModalShell } from "@/components/composites/layout/ModalShell"
import { SurfaceListCard, SurfaceListCardRow } from "@/components/blocks/cards/SurfaceListCard"
import { StackV } from "@/components/frames/Stack"
import type { FlashcardReviewMode } from "@/modules/api/graphql/mutations/types/start-flashcard-review-session"

/** Props for {@link FlashcardReviewModeModal}. */
export interface FlashcardReviewModeModalProps {
    /** Open when true. */
    isOpen: boolean
    /** Close handler (backdrop / Escape / Cancel). */
    onClose: () => void
    /** Deck title shown in the header (which deck is being started). */
    deckTitle: string
    /** Total cards in the deck — the "Review all" badge count. */
    totalCount: number
    /** Cards currently due in the deck — the "Only cards due" badge count. */
    dueCount: number
    /** Fires with the chosen mode when "Start" is pressed. */
    onStart: (mode: FlashcardReviewMode) => void
    /** True while the session persists (drives the "Start" spinner). */
    isPending: boolean
}

/**
 * The deck-review MODE picker (instructor 2026-07-13 "mode-picker modal, full or
 * forgotten"). Opened by `FlashcardDeckList`'s "Study" CTA before a session starts.
 * SELECT-then-CONFIRM (instructor 2026-07-13 round 3 — reverted the direct-press
 * round 2): rows only mark a choice; a separate "Start" button below confirms
 * and actually starts (spinner there until the session persists). "Review all"
 * runs the whole deck; "Only cards due" runs only the cards past due / never
 * learned (the deck's `dueCount`), and dims + auto-resets the picker back to
 * "full" when nothing is due. These are SELECT rows (they pick a mode, they do
 * not navigate) → an UNSELECTED row hovers to the block's NATIVE `bg-default`
 * fill (mode 3, `principles/hover-style-matches-clickable-nature`); a hovered
 * row must NOT reuse the selected row's `bg-accent-soft` (instructor 2026-07-18: an
 * accent-soft hover reads identical to the picked row above — the clash makes a
 * hovered row look selected; reverts the 2026-07-17 accent-soft "preview"). The
 * SELECTED row keeps `hover:bg-accent-soft` so it does not flicker to bg-default
 * on hover (same idiom as `SubmissionResultHistoryDrawer`). Selection signal is
 * the accent icon+title text. `SurfaceListCard bordered` — this list is NESTED
 * inside the modal surface, so it needs a real border rather than the
 * (invisible-in-dark) `shadow-surface` top-level default (`components/card.md`
 * §"surface-in-surface / nested").
 * Selected-row signal (instructor 2026-07-13 round 4, dropped the `CheckCircleIcon`
 * tried in round 3): the row itself tints `bg-accent-soft` via `SurfaceListCardRow`'s
 * `selected` prop, and — instructor 2026-07-17 — BOTH the leading icon and the title
 * turn `text-accent-soft-foreground` when selected (they stay the SAME colour,
 * `components/icon.md` §6 "icon shares color with the text next to it"). The title colour rides a
 * `<span>` node rather than `titleClassName` (that escape hatch is lint-forbidden,
 * `no-modal-title-classname`); un-selected rows keep `text-foreground`.
 * @param props - {@link FlashcardReviewModeModalProps}
 */
export const FlashcardReviewModeModal = ({
    isOpen,
    onClose,
    deckTitle,
    totalCount,
    dueCount,
    onStart,
    isPending,
}: FlashcardReviewModeModalProps) => {
    const t = useTranslations()
    const [mode, setMode] = useState<FlashcardReviewMode>("full")
    // nothing due → "due" is not a real choice; force the picker back to "full"
    // whenever the modal (re)opens for a caught-up deck.
    const dueDisabled = dueCount <= 0
    useEffect(() => {
        if (isOpen && dueDisabled) {
            setMode("full")
        }
    }, [isOpen, dueDisabled])

    return (
        <ModalShell
            identity={{ tier: "page", component: "FlashcardReviewModeModal" }}
            isOpen={isOpen}
            onOpenChange={(open) => { if (!open && !isPending) onClose() }}
            title={t("flashcard.mode.title")}
            size="sm"
            body={() => (
                <StackV gap={5} principle="group-boundary"
                    explain="Section group spacing — not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
                    items={[
                        () => (
                            <Typography size="sm" color="muted" text={t("flashcard.mode.subtitle", { deck: deckTitle })} />
                        ),
                        () => (
                            <SurfaceListCard bordered>
                                <SurfaceListCardRow
                                    // UNSELECTED → block-native bg-default hover (distinct from the accent-soft
                                    // selected tint, no clash). SELECTED → keep hover:bg-accent-soft so the picked
                                    // row does NOT flicker to bg-default on hover (same idiom as
                                    // SubmissionResultHistoryDrawer). Selection signal = accent icon + the row's
                                    // own `selected` bg-accent-soft tint (icon.md §6); `title` is plain text now
                                    // (never a built element), and `titleClassName` stays lint-forbidden, so the
                                    // per-mode colour rides on the icon + row tint alone.
                                    className={mode === "full" ? "hover:bg-accent-soft" : undefined}
                                    leading={() => (
                                        <CardsIcon
                                            className={mode === "full" ? "size-6 text-accent-soft-foreground" : "size-6 text-foreground"}
                                            aria-hidden
                                            focusable="false"
                                        />
                                    )}
                                    title={t("flashcard.mode.fullLabel")}
                                    subtitle={t("flashcard.mode.fullDescription")}
                                    selected={mode === "full"}
                                    isDisabled={isPending}
                                    onPress={() => setMode("full")}
                                    meta={() => (
                                        <Typography
                                            size="xs"
                                            weight="medium"
                                            color="muted"
                                            noWrap
                                            text={t("flashcard.mode.fullBadge", { count: totalCount })}
                                        />
                                    )}
                                />
                                <SurfaceListCardRow
                                    className={mode === "due" ? "hover:bg-accent-soft" : undefined}
                                    leading={() => (
                                        <ClockCountdownIcon
                                            className={mode === "due" ? "size-6 text-accent-soft-foreground" : "size-6 text-foreground"}
                                            aria-hidden
                                            focusable="false"
                                        />
                                    )}
                                    title={t("flashcard.mode.dueLabel")}
                                    subtitle={t("flashcard.mode.dueDescription")}
                                    selected={mode === "due"}
                                    isDisabled={isPending || dueDisabled}
                                    onPress={() => setMode("due")}
                                    meta={() => (
                                        <Typography
                                            size="xs"
                                            weight="medium"
                                            color={dueDisabled ? "muted" : "warning"}
                                            noWrap
                                            text={dueDisabled
                                                ? t("flashcard.mode.dueBadgeEmpty")
                                                : t("flashcard.mode.dueBadge", { count: dueCount })}
                                        />
                                    )}
                                />
                            </SurfaceListCard>
                        ),
                    ]} />
            )}
            footer={() => (
                <>
                    <Button
                        variant="tertiary"
                        isDisabled={isPending}
                        label={t("common.cancel")}
                        onPress={onClose}
                    />
                    <Button
                        variant="primary"
                        isPending={isPending}
                        label={t("flashcard.mode.start")}
                        suffixIcon={isPending ? undefined : ArrowRightIcon}
                        onPress={() => onStart(mode)}
                    />
                </>
            )}
        />
    )
}

import React, { type ComponentType } from "react"
import type { ReactNode } from "react"
import { ArrowRightIcon, ChartLineUpIcon } from "@phosphor-icons/react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { SectionCard } from "@/components/blocks/cards/SectionCard"
import { SurfaceListCard, SurfaceListCardRow } from "@/components/blocks/cards/SurfaceListCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { VerdictHeroCard, type VerdictHeroBand } from "@/components/blocks/stats/VerdictHeroCard"
import { RelatedContentList } from "@/components/blocks/learn/RelatedContentList"
import { Button } from "@/components/atoms/buttons/Button"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"

/** Retention band BY VALUE — drives `VerdictHeroCard`'s color + every retention chip here. */
export const retentionColorOf = (percent: number): VerdictHeroBand =>
    percent < 50 ? "danger" : percent < 75 ? "warning" : "success"

/** Below this many lifetime reviews the aggregates are noise — mirrors
 *  `FlashcardStatsStrip`'s own `RETENTION_MIN_REVIEWS` gate constant. */
export const RETENTION_MIN_REVIEWS = 5

/** Healthy-memory retention mark the hero meter aims at (`stats-insight-redesign`
 *  proposal — FE-side constant; the BE intentionally has no such column). */
export const RETENTION_TARGET = 85

/** How many placeholder rows the co-located skeleton shows for the weak-topics list. */
const WEAK_TOPIC_SKELETON_ROW_COUNT = 4

/** One worst-first weak topic — chip text already resolved (interpolated) by the connected half. */
export interface FlashcardReviewWeakTag {
    /** Topic/tag name. */
    tag: string
    /** Retention percentage for this tag. */
    retention: number
    /** Already-translated `"{retention}% recall"` chip text. */
    chipLabel: string
}

/** All display text, already localized by the connected `FlashcardReviewStats`; a story passes i18n keys. */
export interface FlashcardReviewStatsLabels {
    errorTitle: string
    retry: string
    emptyTitle: string
    emptyDescription: string
    emptyAction: string
    memoryHealthLabel: string
    /** Rich verdict sentence (embeds a `<b>`) — already picked BY BAND and resolved. */
    verdict: ReactNode
    /** Evidence caption under the verdict — already interpolated (retention/target). */
    sub: string
    /** CTA label — already picked BY BAND ("ease off new cards" vs "review weakest deck"). */
    cta: string
    /** "Well-learned cards (mature)" + its caption, already joined with a line break. */
    matureSplitLabel: ComponentType
    /** "New cards (young)" + its caption, already joined with a line break. */
    youngSplitLabel: ComponentType
    weakTopicMapLabel: string
    studyHeading: string
}

/** Props for {@link _FlashcardReviewStats} — presentational; all data resolved, no fetch/store/i18n. */
export interface FlashcardReviewStatsProps {
    /** First load, nothing in hand → the whole tree shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with fewer than `RETENTION_MIN_REVIEWS` lifetime reviews → the empty message. */
    isEmpty?: boolean
    /** Truthy → the error message (beats loading + empty). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler — paired with `labels.retry` to show a retry button on the error branch. */
    onRetry?: () => void
    /** Jumps the overview tab strip back to the study overview (empty-state action). */
    onStartReview?: () => void
    /** Course-scoped lifetime retention — the hero card's headline value. */
    retentionRate?: number
    matureRetention?: number
    youngRetention?: number
    /** Every attempted tag, already ranked worst-first, chip text pre-resolved. */
    weakTags?: Array<FlashcardReviewWeakTag>
    /** Deck to drill from a CTA — the lowest-retention deck, else the top leech card's own deck. */
    weakestDeckId?: string | null
    /** Already-resolved "Review \"{tag}\" (weakest)" CTA — `undefined` hides the button (no deck to drill). */
    weakTopicDrillCta?: string
    /** Already-resolved "Overall average is …" caption — `undefined` hides the caption. */
    weakTopicAvgCaption?: string
    /** Opens a deck's reviewer — the single onward action every row/CTA here shares. */
    onOpenDeck: (deckId: string) => void
    /** Course id for the RAG study-suggestions child. */
    courseId: string
    /** Course display id — omitted (as in a story) → the self-fetching study zone is skipped. */
    displayId?: string
    labels: FlashcardReviewStatsLabels
}

/**
 * "Study Cards" aggregate stats — the presentational half of {@link FlashcardReviewStats},
 * insight-first (verdict → evidence → action, `stats-canonical-fold`): (1) memory-health hero
 * (mature/young split vs target), (2) full weak-topic map worst-first, (3) passive RAG study
 * suggestions. Four states in the fixed order error → loading → empty → content: `error` falls
 * to the shared `AsyncContentError` frame, `isEmpty` to `AsyncContentEmpty`, and otherwise the
 * tree renders with `isSkeleton` threaded to every leaf that supports it
 * (loading-and-skeleton.md). `VerdictHeroCard`/`SectionCard`/`LabeledCard`/`SurfaceListCard`
 * carry no `isSkeleton` of their own — the hero zone swaps to a hand-mirrored `Skeleton.*` tree
 * in the SAME position while shimmering (its headline `value` is a plain number, not a slot a
 * shimmer can sit in); the weak-topic rows instead feed `Skeleton`/atom-`isSkeleton` content
 * straight through `SurfaceListCardRow`'s own `title`/`meta` slots. See `tiers/split.md` — the
 * connected `index.tsx` owns the fetch, the band decision, and i18n.
 *
 * @param props - {@link FlashcardReviewStatsProps}
 */
export const _FlashcardReviewStats = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    onStartReview,
    retentionRate = 0,
    matureRetention = 0,
    youngRetention = 0,
    weakTags = [],
    weakestDeckId = null,
    weakTopicDrillCta,
    weakTopicAvgCaption,
    onOpenDeck,
    courseId,
    displayId,
    labels,
}: FlashcardReviewStatsProps) => {
    // error → skeleton → empty → content (BLOCK-8): error beats a stale loading flag; the empty
    // and error surfaces are the shared `AsyncContent*` frames, not hand-written JSX (§6).
    if (error) {
        return (
            <AsyncContentError
                identity={{ tier: "page", component: "FlashcardReviewStats" }}
                title={labels.errorTitle}
                onRetry={onRetry}
                retryLabel={labels.retry}
            />
        )
    }
    if (!isSkeleton && isEmpty) {
        return (
            <AsyncContentEmpty
                identity={{ tier: "page", component: "FlashcardReviewStats" }}
                icon={ChartLineUpIcon}
                title={labels.emptyTitle}
                description={labels.emptyDescription}
                action={onStartReview ? () => (
                    <Button label={labels.emptyAction} variant="secondary" size="sm" onPress={onStartReview} />
                ) : undefined}
            />
        )
    }

    // band drives VerdictHeroCard's color coding — computed presentationally from the same
    // value the connected half already used (via the same pure function) to pick its text keys.
    const band = retentionColorOf(retentionRate)

    // ZONE 2 rows — `title`/`meta` are buildable slots now (never a pre-rendered element), so a
    // shimmering placeholder can no longer smuggle a `Typography isSkeleton` through `title`; it
    // hand-mirrors the row's own `p-3` + meta-pushed-right shape instead (the row itself has no
    // `isSkeleton`). Otherwise every attempted tag worst-first.
    const gapRows = isSkeleton
        ? Array.from({ length: WEAK_TOPIC_SKELETON_ROW_COUNT }, (_unused, index) => (
            <Box key={`pending-${index}`} principle="cell-pad" className="p-3"
                explain="Tight cell inset — not card-padding, because this sits inside a dense table or list cell rather than a card body.">
                <StackH gap={4} principle="content-row" align="center"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                    items={[
                        () => <Skeleton.Typography type="body-sm" width="1/3" />,
                        () => (
                            <Box principle="push-end" className="ml-auto shrink-0"
                                explain="Pushes this peer to the trailing edge so trailing meta stays right-aligned in the row.">
                                <Skeleton.Chip />
                            </Box>
                        ),
                    ]} />
            </Box>
        ))
        : weakTags.map((tagStat) => (
            <SurfaceListCardRow
                key={tagStat.tag}
                title={tagStat.tag}
                meta={() => <Chip tone={retentionColorOf(tagStat.retention)} text={tagStat.chipLabel} />}
            />
        ))
    const showGap = isSkeleton || gapRows.length > 0
    // action row (drill CTA + avg caption) shows while shimmering (placeholder) or once either
    // resolved string is present.
    const showActionRow = isSkeleton || Boolean(weakTopicDrillCta) || Boolean(weakTopicAvgCaption)

    return (
        <StackV identity={{ tier: "page", component: "FlashcardReviewStats" }} gap={6} items={[
            // ZONE 1 — "Memory health" hero (◎ vs target). `VerdictHeroCard` has no `isSkeleton`
            // of its own — while shimmering this swaps to a hand-mirrored `Skeleton.*` tree in
            // the exact same position instead (missingSkeletonSupport).
            () => (
                <LabeledCard label={labels.memoryHealthLabel} frameless>
                    {isSkeleton ? (
                        <SectionCard>
                            <StackV gap={4} principle="sibling-stack"
                                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                items={[
                                    () => (
                                        <StackH gap={3} principle="value-row" align="baseline"
                                            explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
                                            items={[
                                                () => <Skeleton className="h-9 w-20 rounded" />,
                                                () => <Skeleton className="h-[14px] w-6 rounded" />,
                                            ]} />
                                    ),
                                    () => <Skeleton.Typography type="body-sm" width="3/4" />,
                                    () => <Skeleton.Typography type="body-xs" width="1/2" />,
                                    () => <Skeleton.ProgressBar />,
                                    () => (
                                        <Box className="overflow-hidden rounded-2xl border border-default">
                                            <StackH gap={1} principle="name-handle" align="stretch" divider
                                                explain="Display name with handle — not title-subtitle, because the second line is an identity handle rather than a subtitle."
                                                items={[
                                                    () => (
                                                        <Box principle="card-padding" className="flex-1 p-4"
                                                            explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
                                                            <StackV gap={2} principle="title-subtitle"
                                                                explain="Title over supporting line — not label-field, because neither line is a form control label."
                                                                items={[
                                                                    () => <Skeleton.Typography type="body-xs" width="2/3" />,
                                                                    () => <Skeleton className="h-5 w-14 rounded" />,
                                                                ]} />
                                                        </Box>
                                                    ),
                                                    () => (
                                                        <Box principle="card-padding" className="flex-1 p-4"
                                                            explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
                                                            <StackV gap={2} principle="title-subtitle"
                                                                explain="Title over supporting line — not label-field, because neither line is a form control label."
                                                                items={[
                                                                    () => <Skeleton.Typography type="body-xs" width="2/3" />,
                                                                    () => <Skeleton className="h-5 w-14 rounded" />,
                                                                ]} />
                                                        </Box>
                                                    ),
                                                ]} />
                                        </Box>
                                    ),
                                    () => <Skeleton.Button width="w-40" />,
                                ]} />
                        </SectionCard>
                    ) : (
                        <VerdictHeroCard
                            value={retentionRate}
                            unit="%"
                            band={band}
                            verdict={labels.verdict}
                            sub={labels.sub}
                            meter={{ value: retentionRate, max: 100, target: RETENTION_TARGET }}
                            splits={[
                                {
                                    label: labels.matureSplitLabel,
                                    value: `${matureRetention}%`,
                                    band: retentionColorOf(matureRetention),
                                },
                                {
                                    label: labels.youngSplitLabel,
                                    value: `${youngRetention}%`,
                                    band: retentionColorOf(youngRetention),
                                },
                            ]}
                            action={weakestDeckId ? () => (
                                <Button
                                    variant="primary"
                                    size="sm"
                                    suffixIcon={ArrowRightIcon}
                                    label={labels.cta}
                                    onPress={() => onOpenDeck(weakestDeckId)}
                                />
                            ) : undefined}
                        />
                    )}
                </LabeledCard>
            ),

            // ZONE 2 — "Weak points by topic" (▽ split by tag, → drill CTA). FULL worst-first
            // list. Card's main content is a LIST → a labeled list-surface-card (LabeledCard
            // frameless → SurfaceListCard); the drill CTA + avg caption live OUTSIDE the card
            // (buttons never inside a list card).
            ...(showGap ? [() => (
                <StackV gap={4} items={[
                    () => (
                        <LabeledCard label={labels.weakTopicMapLabel} frameless>
                            <SurfaceListCard>{gapRows}</SurfaceListCard>
                        </LabeledCard>
                    ),
                    ...(showActionRow ? [() => (
                        <StackV gap={3} items={[
                            ...(isSkeleton ? [() => (
                                <Skeleton.Button width="w-44" className="self-start" />
                            )] : weakTopicDrillCta && weakestDeckId ? [() => (
                                <Button
                                    variant="primary"
                                    size="sm"
                                    suffixIcon={ArrowRightIcon}
                                    label={weakTopicDrillCta}
                                    onPress={() => onOpenDeck(weakestDeckId)}
                                    classNames={["self-start"]}
                                />
                            )] : []),
                            ...(isSkeleton ? [() => (
                                <Skeleton.Typography type="body-xs" width="2/3" />
                            )] : weakTopicAvgCaption ? [() => (
                                <Typography size="xs" color="muted" text={weakTopicAvgCaption} />
                            )] : []),
                        ]} />
                    )] : []),
                ]} />
            )] : []),

            // ZONE 3 — passive RAG "Study suggestions": weak tags → course-wide content search
            // (self-hiding when there's nothing weak / no match). Needs the slug for result
            // deep links, so it waits on `displayId`; hidden while shimmering (it fetches its
            // own state).
            ...(!isSkeleton && displayId ? [() => (
                <RelatedContentList
                    courseId={courseId}
                    courseDisplayId={displayId}
                    query={weakTags.map((tagStat) => tagStat.tag).join(" ")}
                    label={labels.studyHeading}
                />
            )] : []),
        ]} />
    )
}

"use client"

import React from "react"
import useSWR from "swr"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { queryMyFlashcardReviewStats } from "@/modules/api/graphql/queries/query-my-flashcard-review-stats"
import { queryMyFlashcardStats } from "@/modules/api/graphql/queries/query-my-flashcard-stats"
import { useAppSelector } from "@/redux/hooks"
import { pathConfig } from "@/resources/path"
import { _FlashcardReviewStats, RETENTION_MIN_REVIEWS, RETENTION_TARGET, retentionColorOf } from "./component"

/** Props for {@link FlashcardReviewStats}. */
export interface FlashcardReviewStatsProps {
    /** Course whose aggregate "Study Cards" review stats to show. */
    courseId: string
    /** Jumps the overview tab strip back to the study overview (empty-state action). */
    onStartReview?: () => void
}

/**
 * "Study Cards" aggregate stats — the CONNECTED half: fetches the course-scoped review stats +
 * the lifetime gate signal, computes the verdict band and every i18n string (incl.
 * interpolation), and hands them to the presentational {@link _FlashcardReviewStats}. See
 * `design/storybook/architecture/tiers/split.md`.
 *
 * @param props - {@link FlashcardReviewStatsProps}
 */
export const FlashcardReviewStats = ({ courseId, onStartReview }: FlashcardReviewStatsProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const displayId = useAppSelector((state) => state.course.displayId)

    const statsSwr = useSWR(
        ["flashcard-review-stats", courseId],
        async () => {
            const response = await queryMyFlashcardReviewStats({ request: { courseId } })
            return response.data?.myFlashcardReviewStats.data ?? null
        },
    )
    // lifetime review count — reused only for the loading gate (matches the old
    // `&& !a.data && !b.data` shape: a resolved-lifetime/pending-stats tick must not briefly
    // render "no data yet" over a course that actually has reviews).
    const lifetimeSwr = useSWR(
        ["my-flashcard-stats"],
        async () => {
            const response = await queryMyFlashcardStats({})
            return response.data?.myFlashcardStats.data ?? null
        },
    )

    // first load, nothing in hand from EITHER source → shimmer (loading-and-skeleton.md §2)
    const isSkeleton = (statsSwr.isLoading && !statsSwr.data) || (lifetimeSwr.isLoading && !lifetimeSwr.data)
    const stats = statsSwr.data
    // COURSE-SCOPED floor + headline (2026-07-17 fix): `reviewedTotal`/`courseRetention` count
    // only THIS course, never the per-user lifetime projection.
    const totalReviewed = stats?.reviewedTotal ?? 0
    const retentionRate = stats?.courseRetention ?? 0
    const weakTags = stats?.weakTags ?? []
    const weakestTag = weakTags[0] ?? null
    const leechFocus = stats?.leechFocus ?? []
    const matureRetention = stats?.matureRetention ?? 0
    const youngRetention = stats?.youngRetention ?? 0
    // deck to drill from a CTA: the lowest-retention deck, else the top leech card's own deck —
    // the ONE onward action every zone/row shares.
    const weakestDeckId = stats?.deckRetention?.[0]?.deckId ?? leechFocus[0]?.deckId ?? null
    /** Open a deck's reviewer. */
    const openDeck = (deckId: string) => router.push(
        pathConfig().locale(locale).course(displayId).learn().flashcards().review(deckId).build(),
    )

    // Overall average over the FULL worst-first list, for the "the average conceals topic X" caption.
    const weakTagAvg = weakTags.length > 0
        ? Math.round(weakTags.reduce((sum, tag) => sum + tag.retention, 0) / weakTags.length)
        : 0

    // Verdict sentence/caption/CTA chosen BY BAND: danger→overload, warning→leaking, success→healthy.
    const band = retentionColorOf(retentionRate)
    const verdictKey = band === "danger"
        ? "flashcard.review.verdictOverloadSentence"
        : band === "warning"
            ? "flashcard.review.verdictLeakingSentence"
            : "flashcard.review.verdictHealthySentence"
    const captionKey = band === "danger"
        ? "flashcard.review.verdictOverloadCaption"
        : band === "warning"
            ? "flashcard.review.verdictLeakingCaption"
            : "flashcard.review.verdictHealthyCaption"
    // "Reduce new cards" only fits the overloaded case; other bands drill the weakest deck.
    const ctaKey = band === "danger" ? "flashcard.review.reduceNewCardsCta" : "flashcard.review.reviewWeakestCta"

    return (
        <_FlashcardReviewStats
            isSkeleton={isSkeleton}
            isEmpty={totalReviewed < RETENTION_MIN_REVIEWS}
            error={!stats ? statsSwr.error : undefined}
            onRetry={() => { void statsSwr.mutate() }}
            onStartReview={onStartReview}
            retentionRate={retentionRate}
            matureRetention={matureRetention}
            youngRetention={youngRetention}
            weakTags={weakTags.map((tag) => ({
                tag: tag.tag,
                retention: tag.retention,
                chipLabel: t("flashcard.review.deckRetentionChip", { retention: tag.retention }),
            }))}
            weakestDeckId={weakestDeckId}
            weakTopicDrillCta={weakestDeckId && weakestTag
                ? t("flashcard.review.weakTopicDrillCta", { tag: weakestTag.tag })
                : undefined}
            weakTopicAvgCaption={weakestTag
                ? t("flashcard.review.weakTopicAvgCaption", {
                    avg: weakTagAvg,
                    tag: weakestTag.tag,
                    low: weakestTag.retention,
                })
                : undefined}
            onOpenDeck={openDeck}
            courseId={courseId}
            displayId={displayId}
            labels={{
                errorTitle: t("flashcard.review.statsError"),
                retry: t("flashcard.review.retry"),
                emptyTitle: t("flashcard.review.statsEmptyTitle"),
                emptyDescription: t("flashcard.review.statsEmptyDescription"),
                emptyAction: t("flashcard.review.historyEmptyAction"),
                memoryHealthLabel: t("flashcard.review.memoryHealthLabel"),
                verdict: t.rich(verdictKey, {
                    b: (chunks) => <b>{chunks}</b>,
                }),
                sub: t(captionKey, {
                    retention: retentionRate,
                    target: RETENTION_TARGET,
                }),
                cta: t(ctaKey),
                matureSplitLabel: () => (
                    <>
                        {t("flashcard.review.matureSplitLabel")}
                        <br />
                        {t("flashcard.review.matureSplitCaption")}
                    </>
                ),
                youngSplitLabel: () => (
                    <>
                        {t("flashcard.review.youngSplitLabel")}
                        <br />
                        {t("flashcard.review.youngSplitCaption")}
                    </>
                ),
                weakTopicMapLabel: t("flashcard.review.weakTopicMapLabel"),
                studyHeading: t("flashcard.review.stats.studyHeading"),
            }}
        />
    )
}

