import React from "react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { ConsultantCard, type ConsultantCardConsultant } from "@/components/blocks/consultant/ConsultantCard"
import { Grid, type GridItem } from "@/components/frames/Grid"

/** Placeholder card count while the first load is in flight. */
const SKELETON_CARD_COUNT = 3

/** Resting tiles hand this as `onOpen` — `ConsultantCard.isSkeleton` refuses presses, so it never fires. */
const NOOP = () => {}

/** All display text, already localized by the connected `HeadhuntingCompanyConsultants`; a story passes i18n keys. */
export interface HeadhuntingCompanyConsultantsLabels {
    /** Title shown once settled with zero consultants for the active company. */
    emptyTitle: string
    /** Title shown once the loader queries settle with an error. */
    errorTitle: string
    /** Retry button label, paired with {@link HeadhuntingCompanyConsultantsProps.onRetry}. */
    retry: string
}

/** Props for {@link _HeadhuntingCompanyConsultants} — presentational; all data resolved, no fetch/store/i18n. */
export interface HeadhuntingCompanyConsultantsProps {
    /** First load, nothing in hand → the grid shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with zero consultants for the active company → the empty message. */
    isEmpty?: boolean
    /** Truthy → the error message (beats loading + empty). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retries both loader queries (companies + consultants). */
    onRetry?: () => void
    /** Consultants for the active company, already filtered + sorted. */
    consultants: Array<ConsultantCardConsultant>
    /** Fired with the pressed consultant's id — the connected half owns what opening means. */
    onOpenConsultant: (id: string) => void
    labels: HeadhuntingCompanyConsultantsLabels
}

/**
 * `_HeadhuntingCompanyConsultants` — grid of consultant cards for one
 * headhunting company; the presentational half of {@link
 * import("./index").HeadhuntingCompanyConsultants}. Three states in the fixed
 * order error → empty → content: `error` falls to the shared
 * `AsyncContentError` composite, settled `isEmpty` to `AsyncContentEmpty`,
 * otherwise the responsive card grid renders.
 *
 * While shimmering the grid maps over the SAME {@link ConsultantCard} with its
 * own `isSkeleton` — one description of a tile, so the resting shape cannot
 * drift from the loaded one (`loading-and-skeleton.md`). See `tiers/split.md` —
 * the connected `index.tsx` owns the fetch, the redux reads, and every `t()`.
 *
 * @param props - {@link HeadhuntingCompanyConsultantsProps}
 */
export const _HeadhuntingCompanyConsultants = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    consultants,
    onOpenConsultant,
    labels,
}: HeadhuntingCompanyConsultantsProps) => {
    // error beats a stale loading flag; empty only once settled (BLOCK-8) — the
    // empty/error surfaces are the shared `AsyncContent*` composites, not
    // hand-written JSX (loading-and-skeleton.md §6).
    if (error) {
        return <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retry} />
    }
    if (!isSkeleton && isEmpty) {
        return <AsyncContentEmpty title={labels.emptyTitle} />
    }

    const items: Array<GridItem> = isSkeleton
        ? Array.from({ length: SKELETON_CARD_COUNT }, (_unused, index) => ({
            key: `pending-${index}`,
            content: () => (
                <ConsultantCard
                    consultant={{ id: `pending-${index}`, fullName: "" }}
                    onOpen={NOOP}
                    isSkeleton
                />
            ),
        }))
        : consultants.map((consultant) => ({
            key: consultant.id,
            content: () => <ConsultantCard consultant={consultant} onOpen={onOpenConsultant} />,
        }))

    return (
        <Grid
            identity={{ tier: "block", component: "HeadhuntingCompanyConsultants" }}
            columns={{ base: 1, sm: 2, lg: 3 }}
            principle="sibling-stack"
            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
            items={items}
        />
    )
}

"use client"

import React, { useCallback, useMemo, useState } from "react"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import {
    ChatCircleDotsIcon,
    EnvelopeSimpleIcon,
    LinkedinLogoIcon,
    PhoneIcon,
} from "@phosphor-icons/react"
import { useAppSelector } from "@/redux/hooks"
import { useQueryHeadhunterCompaniesSwr } from "@/hooks/swr/api/graphql/queries/useQueryHeadhunterCompaniesSwr"
import { useQueryHeadhuntersSwr } from "@/hooks/swr/api/graphql/queries/useQueryHeadhuntersSwr"
import { pathConfig } from "@/resources/path"
import { ModalShell } from "@/components/composites/layout/ModalShell"
import {
    ConsultantProfileBody,
    type ConsultantProfileBodyContactLink,
} from "@/components/blocks/consultant/ConsultantProfileBody"
import type { ConsultantCardConsultant } from "@/components/blocks/consultant/ConsultantCard"
import { _HeadhuntingCompanyConsultants } from "./component"

/**
 * `HeadhuntingCompanyConsultants` — the CONNECTED half: grid of consultant
 * cards for one headhunting company. Self-contained section (single-use): it
 * reads all consultants and the active company id from the `headhunter` redux
 * slice (synced by the parent hook), computes the skeleton/empty/error state,
 * and hands them to the presentational {@link _HeadhuntingCompanyConsultants}
 * — so the container renders `<HeadhuntingCompanyConsultants />` with no
 * props. See `design/storybook/architecture/split.md`.
 *
 * Pressing a tile opens that consultant's profile MODAL, and the modal lives
 * HERE rather than inside the card. The card is one tile: it reports a press
 * and nothing else. Owning the open state one level up is what lets a single
 * `ConsultantCard` serve this page and the directory page, whose press means
 * something different (it selects into redux).
 */
export const HeadhuntingCompanyConsultants = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const consultants = useAppSelector((state) => state.headhunter.entities)
    const companyId = useAppSelector((state) => state.headhunter.companyId)
    const courseDisplayId = useAppSelector((state) => state.course.displayId)
    // read the loader queries' error/retry so a failed query surfaces error+retry
    // rather than a perpetual skeleton (Redux stays `undefined` on failure). SWR
    // dedupes with the container's own calls.
    const { error: companiesError, mutate: mutateCompanies } = useQueryHeadhunterCompaniesSwr()
    const { error: consultantsError, mutate: mutateConsultants } = useQueryHeadhuntersSwr()
    const error = companiesError ?? consultantsError

    /** Which consultant's profile is open; `null` = the modal is closed. */
    const [openedId, setOpenedId] = useState<string | null>(null)

    const companyConsultants = useMemo(() => {
        if (!consultants?.length || !companyId) {
            return []
        }
        return consultants
            .filter((entry) => (entry.company?.id ?? entry.companyId) === companyId)
            .sort((a, b) => a.sortIndex - b.sortIndex)
    }, [companyId, consultants])

    /** The tile's own shape — the card names exactly the fields it draws. */
    const cardConsultants = useMemo<Array<ConsultantCardConsultant>>(
        () => companyConsultants.map((entry) => ({
            id: entry.id,
            fullName: entry.fullName,
            jobTitle: entry.jobTitle ?? undefined,
            companyTitle: entry.company?.title ?? undefined,
            description: entry.description ?? undefined,
            avatarUrl: entry.avatarUrl ?? undefined,
        })),
        [companyConsultants],
    )

    const opened = useMemo(
        () => companyConsultants.find((entry) => entry.id === openedId) ?? null,
        [companyConsultants, openedId],
    )
    const openedCompanyTitle = opened?.company?.title ?? ""

    // real contact rows — only meaningful once unlocked (the BE nulls these
    // fields server-side while locked, so an absent field simply drops its row)
    const contactLinks = useMemo<Array<ConsultantProfileBodyContactLink>>(() => {
        if (!opened?.contactUnlocked) {
            return []
        }
        const rows: Array<ConsultantProfileBodyContactLink> = []
        if (opened.email) {
            rows.push({ key: "email", label: opened.email, href: `mailto:${opened.email}`, icon: EnvelopeSimpleIcon })
        }
        if (opened.phoneNumber) {
            rows.push({ key: "phone", label: opened.phoneNumber, href: `tel:${opened.phoneNumber}`, icon: PhoneIcon })
        }
        if (opened.zaloNumber) {
            rows.push({
                key: "zalo",
                label: `${t("headhuntings.zalo")}: ${opened.zaloNumber}`,
                href: `https://zalo.me/${opened.zaloNumber}`,
                icon: ChatCircleDotsIcon,
            })
        }
        if (opened.linkedinUrl) {
            rows.push({ key: "linkedin", label: t("headhuntings.linkedin"), href: opened.linkedinUrl, icon: LinkedinLogoIcon })
        }
        return rows
    }, [opened, t])

    /** Navigate to the consultant's company page (from inside the profile modal). */
    const onOpenCompany = useCallback(() => {
        const targetId = opened?.company?.id ?? opened?.companyId
        if (!targetId || !courseDisplayId) {
            return
        }
        setOpenedId(null)
        router.push(
            pathConfig()
                .locale(locale)
                .course(courseDisplayId)
                .headhuntingCompanies(targetId)
                .build(),
        )
    }, [courseDisplayId, locale, opened, router])

    /** Send the viewer to their own CV gallery to raise their score + unlock contact. */
    const onImproveCv = useCallback(() => {
        setOpenedId(null)
        router.push(pathConfig().locale(locale).profile().cv().build())
    }, [locale, router])

    return (
        <>
            <_HeadhuntingCompanyConsultants
                // first load, nothing in hand → shimmer; settled (data OR error) stops it (loading-and-skeleton.md)
                isSkeleton={!consultants}
                isEmpty={companyConsultants.length === 0}
                error={error}
                onRetry={() => {
                    void mutateCompanies()
                    void mutateConsultants()
                }}
                consultants={cardConsultants}
                onOpenConsultant={setOpenedId}
                labels={{
                    emptyTitle: t("headhuntings.empty"),
                    errorTitle: t("headhuntings.error"),
                    retry: t("common.retry"),
                }}
            />

            <ModalShell
                isOpen={Boolean(opened)}
                onOpenChange={(next) => { if (!next) { setOpenedId(null) } }}
                title={t("headhuntings.modalTitle")}
                scroll="inside"
                body={() => opened ? (
                    <ConsultantProfileBody
                        consultant={{
                            fullName: opened.fullName,
                            jobTitle: opened.jobTitle ?? undefined,
                            companyTitle: openedCompanyTitle || undefined,
                            description: opened.description ?? undefined,
                            avatarUrl: opened.avatarUrl ?? undefined,
                            contactUnlocked: opened.contactUnlocked,
                            contactLinks,
                        }}
                        onOpenCompany={openedCompanyTitle ? onOpenCompany : undefined}
                        onImproveCv={onImproveCv}
                        lockedTitle={t("headhuntings.contactLockedTitle")}
                        lockedDescription={t("headhuntings.contactLocked", { score: opened.cvScoreUnlockThreshold })}
                        lockedCtaLabel={t("headhuntings.improveCv")}
                    />
                ) : null}
            />
        </>
    )
}

"use client"

import React from "react"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { ConsultantCard } from "@/components/blocks/consultant/ConsultantCard"
import { Grid } from "@/components/frames/Grid"
import { StackH, StackV } from "@/components/frames/Stack"

/** Resting tiles hand this as `onOpen` — `ConsultantCard.isSkeleton` refuses presses, so it never fires. */
const NOOP = () => {}

/**
 * Skeleton placeholder shown while the headhunting company detail loads — mirrors
 * the real page tree: a breadcrumb row, the company profile block (logo + title +
 * description), then the responsive consultants grid.
 */
export const HeadhuntingCompanyLoadingState = () => (
    <StackV gap={6} principle="block-boundary"
        explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
        items={[
        // breadcrumb row
            () => <Skeleton.Breadcrumbs count={3} />,

            // company profile block (logo · title · description) — mirrors @app-md:flex-row
            () => (
                <StackH gap={4} principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                    at="md" align="start" items={[
                        () => <Skeleton className="h-16 w-40 shrink-0 rounded-2xl" />,
                        () => (
                            <StackV gap={4} principle="content-row"
                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                classNames={["flex-1"]} items={[
                                    () => <Skeleton.Typography type="h3" width="1/2" />,
                                    () => <Skeleton.Paragraph lines={2} />,
                                ]} />
                        ),
                    ]} />
            ),

            // consultants grid — the REAL tile at rest, so it cannot drift from the loaded one
            () => (
                <Grid
                    columns={{ base: 1, md: 2, lg: 3 }}
                    principle="group-boundary"
                    explain="Section group spacing — not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
                    items={[0, 1, 2].map((index) => ({
                        key: String(index),
                        content: () => (
                            <ConsultantCard
                                consultant={{ id: `pending-${index}`, fullName: "" }}
                                onOpen={NOOP}
                                isSkeleton
                            />
                        ),
                    }))}
                />
            ),
        ]} />
)

"use client"

import React, { useMemo } from "react"
import { Link, Typography } from "@heroui/react"
import { useTranslations } from "next-intl"
import type { HeadhuntingCompanyContactLink } from "@/modules/types/entities/headhunting"
import { buildHeadhuntingCompanyContactLinks } from "@/modules/utils/careers/headhunting"
import { useAppSelector } from "@/redux/hooks"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * Company profile block: logo, title, description, and contact links.
 *
 * Self-contained section (single-use): reads the active company from the Redux
 * singleton itself and derives its contact links, so the container just renders
 * `<HeadhuntingCompanyProfile />`.
 */
export const HeadhuntingCompanyProfile = () => {
    const t = useTranslations()
    const company = useAppSelector((state) => state.headhunter.company)

    const contactLinks = useMemo(
        (): Array<HeadhuntingCompanyContactLink> => buildHeadhuntingCompanyContactLinks(company),
        [company],
    )

    if (!company) {
        return null
    }

    return (
        <StackH identity={{ tier: "page", component: "HeadhuntingCompanyProfile" }} gap={4} principle="content-row" at="md" align="start"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            items={[
                () => (company.logoUrl ? (
                    <img
                        src={company.logoUrl}
                        alt={company.title}
                        className="h-16 w-auto max-w-[200px] object-contain"
                    />
                ) : null),
                () => (
                    <StackV gap={4} principle="content-row" classNames={["flex-1"]}
                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                        items={[
                            () => <Typography type="h3" weight="bold">{company.title}</Typography>,
                            () => (company.description ? (
                                <Typography type="body-sm" color="muted">{company.description}</Typography>
                            ) : null),
                            () => (contactLinks.length > 0 ? (
                                <ul data-principle="sibling-stack" className="flex flex-col gap-2">
                                    {contactLinks.map((link) => (
                                        <StackH key={link.labelKey} as="li" gap={3} principle="identity" at="sm" align="center"
                                            explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                                            items={[
                                                () => (
                                                    <Typography type="body-sm" weight="medium" color="muted">
                                                        {t(link.labelKey)}:
                                                    </Typography>
                                                ),
                                                () => (link.href ? (
                                                    <Link
                                                        href={link.href}
                                                        target="_blank"
                                                        rel="noopener noreferrer"
                                                        className="text-accent-soft-foreground"
                                                    >
                                                        {link.value}
                                                    </Link>
                                                ) : (
                                                    <Typography type="body-sm">{link.value}</Typography>
                                                )),
                                            ]} />
                                    ))}
                                </ul>
                            ) : null),
                        ]} />
                ),
            ]} />
    )
}

"use client"

import React from "react"
import { Typography } from "@heroui/react"
import { useTranslations } from "next-intl"
import { HeadhuntingCompanyBreadcrumbs } from "./HeadhuntingCompanyBreadcrumbs"
import { HeadhuntingCompanyConsultants } from "./HeadhuntingCompanyConsultants"
import { HeadhuntingCompanyProfile } from "./HeadhuntingCompanyProfile"
import { HeadhuntingCompanyLoadingState } from "./HeadhuntingCompanyLoadingState"
import { useHeadhuntingCompanyDetail } from "@/hooks/headhunting"
import { AsyncContentError } from "@/components/composites/async/AsyncContent"
import { Box } from "@/components/frames/Box"
import { StackV } from "@/components/frames/Stack"

/** Props for {@link HeadhuntingCompanyPage}. */
export type HeadhuntingCompanyPageProps = Record<string, never>
/**
 * Headhunting company detail: company profile and the consultants at that company.
 * Container — owns data + breadcrumb orchestration via hooks; renders presentational children.
 * @param props - {@link HeadhuntingCompanyPageProps}
 */
export const HeadhuntingCompanyPage = () => {
    const t = useTranslations()
    const {
        companyId,
        company,
        companies,
        error,
        retry,
    } = useHeadhuntingCompanyDetail()

    // an errored query never lands in Redux, so `companies` stays undefined — the
    // loading gate below would otherwise spin forever; surface a retry instead
    if (error && !companies) {
        return (
            <AsyncContentError
                title={t("headhuntings.error")}
                onRetry={retry}
                retryLabel={t("common.retry")}
            />
        )
    }

    if (!companies) {
        return <HeadhuntingCompanyLoadingState />
    }

    if (!company && companyId) {
        return (
            <div>
                <Typography type="body-sm" color="muted">{t("headhuntings.companyNotFound")}</Typography>
            </div>
        )
    }

    return (
        <Box>
            <StackV gap={6} principle="block-boundary"
                explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                items={[
                    HeadhuntingCompanyBreadcrumbs,
                    HeadhuntingCompanyProfile,
                    HeadhuntingCompanyConsultants,
                ]} />
        </Box>
    )
}

"use client"

import React, {
    useCallback,
    useState,
} from "react"
import {
    Button,
    Card,
    CardContent,
    Chip,
    Spinner,
    TextField,
    Typography,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import {
    SettingsBreadcrumb,
} from "@/components/blocks/settings/SettingsBreadcrumb"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { Callout } from "@/components/composites/feedback/Callout"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { useQueryMyInstallmentPlansSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyInstallmentPlansSwr"
import { useMutatePayNextInstallmentSwr } from "@/hooks/swr/api/graphql/mutations/useMutatePayNextInstallmentSwr"
import type { InstallmentPlanItem } from "@/modules/api/graphql/queries/types/my-installment-plans"
import { PaymentType } from "@/modules/types/enums/payment-type"
import { useGraphQLWithToast } from "@/modules/toast/hooks"
import { submitCheckout } from "@/modules/payment/submit-checkout"
import { pathConfig } from "@/resources/path"
import { Cluster } from "@/components/frames/Cluster"
import { StackH, StackV } from "@/components/frames/Stack"

/** Format an integer VND amount as "1.275.000₫". */
const formatVnd = (amount: number): string => `${amount.toLocaleString("vi-VN")}₫`

/** Chip color per plan lifecycle status — semantic only, never accent. */
const STATUS_COLOR: Record<string, "success" | "warning" | "danger" | "muted"> = {
    Active: "success",
    Overdue: "warning",
    Defaulted: "danger",
    Completed: "muted",
}

/**
 * "My installment plans" — lists the viewer's non-completed installment
 * plans and lets them pay the current cycle.
 *
 * Two render shapes share one list (mirrors `Sessions` — per-plan `Card` with a
 * row action, not a `SurfaceListCard` since each plan is its own bounded object):
 * `Fixed` (fixed monthly amount + `ProgressMeter` "paid N/M installments") and
 * `FlexiblePool` (outstanding balance + an editable amount, floor-clamped to
 * this cycle's minimum). Paying opens the gateway checkout via the shared
 * `payNextInstallment` mutation, then revalidates the list. Mounted by
 * `/profile/settings/installments`.
 */
export const InstallmentPlansPage = () => {
    const t = useTranslations()
    const router = useRouter()
    const {
        data: plans,
        isLoading,
        error,
        mutate,
    } = useQueryMyInstallmentPlansSwr()
    const { trigger: triggerPayNextInstallment } = useMutatePayNextInstallmentSwr()
    const runGraphQL = useGraphQLWithToast()

    // the plan id currently being paid (drives the per-row spinner)
    const [payingId, setPayingId] = useState<string | null>(null)
    // FlexiblePool custom amounts, keyed by plan id — seeded lazily from minPaymentVnd
    const [customAmountByPlan, setCustomAmountByPlan] = useState<Record<string, number>>({})

    const planList = plans ?? []

    /** The amount to charge for a plan — the edited FlexiblePool value, else the minimum. */
    const amountFor = useCallback(
        (plan: InstallmentPlanItem) => customAmountByPlan[plan.id] ?? plan.minPaymentVnd,
        [customAmountByPlan],
    )

    /** Clamp a FlexiblePool amount edit to never go below this cycle's minimum. */
    const onAmountChange = useCallback(
        (plan: InstallmentPlanItem, raw: string) => {
            const digits = Number(raw.replace(/\D/g, ""))
            const clamped = Math.max(digits || 0, plan.minPaymentVnd)
            setCustomAmountByPlan((prev) => ({ ...prev, [plan.id]: clamped }))
        },
        [],
    )

    /** Pay a plan's current cycle (PayOS — the only gateway offered here), then refresh the list. */
    const onPay = useCallback(
        async (plan: InstallmentPlanItem) => {
            setPayingId(plan.id)
            try {
                let checkoutUrl = ""
                let checkoutFields: string | null | undefined
                const success = await runGraphQL(
                    async () => {
                        const amountVnd = plan.planType === "FlexiblePool" ? amountFor(plan) : undefined
                        const response = await triggerPayNextInstallment({
                            planId: plan.id,
                            paymentType: PaymentType.PayOS,
                            returnUrl: window.location.href,
                            cancelUrl: window.location.href,
                            amountVnd,
                        })
                        if (!response.data?.payNextInstallment) {
                            throw new Error(response.error?.message)
                        }
                        const data = response.data.payNextInstallment.data
                        checkoutUrl = data?.checkoutUrl ?? ""
                        checkoutFields = data?.checkoutFields
                        return response.data.payNextInstallment
                    },
                    {
                        showSuccessToast: false,
                        showErrorToast: true,
                    },
                )
                if (success && checkoutUrl) {
                    submitCheckout({ checkoutUrl, checkoutFields })
                }
            } finally {
                setPayingId(null)
            }
        },
        [runGraphQL, triggerPayNextInstallment, amountFor],
    )

    return (
        <StackV gap={7} principle="layout-split"
            explain="Major layout split — not block-boundary, because this separates primary page regions rather than adjacent blocks."
            items={[
                () => (
                    <PageHeader
                        breadcrumb={<SettingsBreadcrumb current={t("installmentPlans.title")} />}
                        title={t("installmentPlans.title")}
                        description={t("installmentPlans.subtitle")}
                    />
                ),

                () => (
                    <AsyncContent
                        isLoading={isLoading && !plans}
                        skeleton={(
                            <StackV gap={4} principle="content-row" explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title." items={[0, 1].map((row) => () => (
                                <Skeleton key={row} className="h-40 w-full rounded-2xl" />
                            ))} />
                        )}
                        isEmpty={planList.length === 0}
                        emptyContent={{
                            title: t("installmentPlans.empty"),
                            description: t("installmentPlans.emptyDesc"),
                            onRetry: () => router.push(pathConfig().locale().course().build()),
                            retryLabel: t("installmentPlans.emptyCta"),
                        }}
                        error={error}
                        errorContent={{
                            title: t("installmentPlans.empty"),
                            onRetry: () => { void mutate() },
                        }}
                    >
                        <StackV gap={4} principle="content-row" explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title." items={planList.map((plan) => () => {
                            const isFixed = plan.planType === "Fixed"
                            const isLocked = plan.status === "Defaulted"
                            const statusColor = STATUS_COLOR[plan.status] ?? "muted"
                            const isPaying = payingId === plan.id
                            return (
                                <Card key={plan.id}>
                                    <CardContent>
                                        <StackV gap={4} principle="content-row"
                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                            items={[
                                                () => (
                                                    <StackH gap={4} principle="content-row" justify="between" align="center"
                                                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                        items={[
                                                            () => (
                                                                <Chip
                                                                    size="sm"
                                                                    variant="soft"
                                                                    color={statusColor === "muted" ? "default" : statusColor}
                                                                >
                                                                    <Chip.Label>{t(`installmentPlans.status.${plan.status}`)}</Chip.Label>
                                                                </Chip>
                                                            ),
                                                            () => (
                                                                <Typography type="body-xs" color="muted">
                                                                    {isFixed
                                                                        ? t("installmentPlans.termMonths", { months: plan.months ?? 0 })
                                                                        : t("installmentPlans.flexiblePool")}
                                                                </Typography>
                                                            ),
                                                        ]} />
                                                ),

                                                () => (plan.courses.length > 0 ? (
                                                    <Cluster gap={3} principle="chip-row" explain="Lets chips share one wrapping row so related tags stay together without stacking as a column." items={plan.courses.map((course) => () => (
                                                        <Chip key={course.id} size="sm" variant="soft" color="default">
                                                            <Chip.Label>{course.title}</Chip.Label>
                                                        </Chip>
                                                    ))} />
                                                ) : null),

                                                () => (isFixed ? (
                                                    <>
                                                        <StackH gap={4} principle="content-row" explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title." justify="between" align="center" items={[() => (
                                                            <Typography type="body-sm" weight="semibold">
                                                                {formatVnd(plan.monthlyAmountVnd ?? 0)}
                                                                <Typography type="body-xs" color="muted" className="ml-1 inline">
                                                                    {t("installmentPlans.perCycle")}
                                                                </Typography>
                                                            </Typography>
                                                        )]} />
                                                        <ProgressMeter
                                                            value={plan.installmentsPaid ?? 0}
                                                            max={plan.months ?? 1}
                                                            label={t("installmentPlans.progress", {
                                                                paid: plan.installmentsPaid ?? 0,
                                                                months: plan.months ?? 0,
                                                            })}
                                                        />
                                                    </>
                                                ) : (
                                                    <>
                                                        <StackH gap={4} principle="content-row" justify="between" align="center"
                                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                            items={[
                                                                () => (
                                                                    <Typography type="body-sm" color="muted">
                                                                        {t("installmentPlans.remaining")}
                                                                    </Typography>
                                                                ),
                                                                () => (
                                                                    <Typography type="body-sm" weight="semibold">
                                                                        {formatVnd(plan.remainingVnd ?? 0)}
                                                                    </Typography>
                                                                ),
                                                            ]} />
                                                        <Typography type="body-xs" color="muted">
                                                            {t("installmentPlans.minPaymentFormula", {
                                                                percent: plan.minPaymentPercent ?? 0,
                                                                floor: formatVnd(plan.minPaymentFloorVnd ?? 0),
                                                            })}
                                                        </Typography>
                                                        <StackH gap={3} principle="identity" align="center"
                                                            explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                                                            items={[
                                                                () => (
                                                                    <TextField
                                                                        className="max-w-[160px]"
                                                                        value={amountFor(plan).toLocaleString("vi-VN")}
                                                                        onChange={(value) => onAmountChange(plan, value)}
                                                                        isDisabled={isPaying}
                                                                        aria-label={t("installmentPlans.amountLabel")}
                                                                    />
                                                                ),
                                                                () => (
                                                                    <Typography type="body-xs" color="muted">
                                                                        {t("installmentPlans.minLabel", { amount: formatVnd(plan.minPaymentVnd) })}
                                                                    </Typography>
                                                                ),
                                                            ]} />
                                                    </>
                                                )),

                                                () => (isLocked ? (
                                                    <Callout
                                                        status="danger"
                                                        title={t("installmentPlans.lockedTitle")}
                                                        description={t("installmentPlans.lockedDesc")}
                                                    />
                                                ) : null),

                                                () => (
                                                    <StackH gap={4} principle="content-row" justify="between" align="center"
                                                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                        items={[
                                                            () => (
                                                                <Typography type="body-xs" color="muted">
                                                                    {plan.nextDueAt
                                                                        ? t("installmentPlans.nextDue", { date: new Date(plan.nextDueAt).toLocaleDateString("vi-VN") })
                                                                        : ""}
                                                                </Typography>
                                                            ),
                                                            () => (
                                                                <Button
                                                                    variant={isLocked ? "danger" : "primary"}
                                                                    size="sm"
                                                                    isDisabled={isPaying}
                                                                    onPress={() => { void onPay(plan) }}
                                                                >
                                                                    {isPaying ? (
                                                                        <Spinner size="sm" color="current" />
                                                                    ) : isLocked ? (
                                                                        t("installmentPlans.unlock")
                                                                    ) : isFixed ? (
                                                                        t("installmentPlans.payThisCycle")
                                                                    ) : (
                                                                        t("installmentPlans.pay")
                                                                    )}
                                                                </Button>
                                                            ),
                                                        ]} />
                                                ),
                                            ]} />
                                    </CardContent>
                                </Card>
                            )
                        })} />
                    </AsyncContent>
                ),
            ]} />
    )
}

import React from "react"
import { ArrowRightIcon, BriefcaseIcon, BuildingsIcon, MapPinIcon } from "@phosphor-icons/react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { Callout } from "@/components/composites/feedback/Callout"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"
import { Button } from "@/components/atoms/buttons/Button"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { Container } from "@/components/frames/Container"
import { Cluster } from "@/components/frames/Cluster"
import { StackH, StackV } from "@/components/frames/Stack"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { MarkdownContent } from "@/components/blocks/rendering/MarkdownContent"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"

/** How many lines the description/requirements paragraphs shimmer while loading. */
const DESCRIPTION_SKELETON_LINES = 4
const REQUIREMENTS_SKELETON_LINES = 3

/** The posting company, already resolved (title/description text, no i18n). */
export interface JobDetailCompany {
    /** Company display name. */
    title: string
    /** Optional short company description (already truncated to 2 lines by the frame). */
    description?: string
    /** Cover logo — falls back to a building glyph when absent/broken. */
    logoUrl?: string | null
    /** Deep link to the company's (course-scoped) page — omitted when unresolvable. */
    href?: string
}

/** All display text, already localized by the connected `JobDetailPage`; a story passes i18n keys. */
export interface JobDetailLabels {
    /** Empty-state title — the `displayId` resolved to no posting. */
    notFound: string
    /** Error-state title on a settled fetch failure. */
    error: string
    /** Retry button label (paired with `onRetry`). */
    retry: string
    /** "Description" section heading. */
    descriptionLabel: string
    /** "Requirements" section heading. */
    requirementsLabel: string
    /** Expired-posting callout message. */
    expired: string
    /** Primary "Apply" CTA label (external-URL apply method). */
    apply: string
    /** "Apply via <email>" CTA label, already interpolated with the address — only meaningful when `canApplyByEmail`. */
    applyByEmail?: string
}

/** Props for {@link _JobDetailPage} — presentational; all data resolved, no fetch/store/i18n. */
export interface JobDetailPageProps {
    /** First load, nothing in hand → the whole tree shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with no posting for the given `displayId` → the not-found empty message. */
    isEmpty?: boolean
    /** Truthy → the error message (beats loading + empty). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler — paired with `labels.retry` to show a retry button on the error branch. */
    onRetry?: () => void
    /** Posting title. */
    title?: string
    /** Already-translated work-mode label (e.g. "Remote") — omitted when the posting carries no work mode. */
    workModeLabel?: string
    /** Already-translated employment-type label (e.g. "Full-time") — omitted when absent. */
    employmentTypeLabel?: string
    /** Free-text location — omitted when absent. */
    location?: string
    /** Already-translated "Posted X ago" sentence. */
    postedAgoLabel?: string
    /** The posting company. */
    company?: JobDetailCompany
    /** Already-formatted salary label (a range, a single figure, or "Negotiable"). */
    salaryLabel?: string
    /** Markdown job description. */
    description?: string
    /** Optional markdown requirements/qualifications. */
    requirements?: string
    /** `true` → the posting is past `expiresAt`; the Apply CTA is replaced with a closed-notice callout. */
    expired?: boolean
    /** `true` → the external-URL Apply CTA renders (posting's `applyMethod` is `ExternalUrl` and carries a URL). */
    canApplyExternal?: boolean
    /** `true` → the email Apply CTA renders (posting's `applyMethod` is `Email` and carries an address). */
    canApplyByEmail?: boolean
    /** Opens `applyUrl` in a new tab — only meaningful with `canApplyExternal`. */
    onApplyExternal?: () => void
    /** Hands off to the OS mail client — only meaningful with `canApplyByEmail`. */
    onApplyByEmail?: () => void
    labels: JobDetailLabels
}

/**
 * "Meta" chip/text row under the title: work-mode chip, employment-type chip, location, and
 * "posted X ago" — each shown only when its data resolved, EXCEPT while `isSkeleton`, when all
 * four render as generic placeholders (real shape unknown yet, so a plausible full row shimmers).
 */
const buildMetaItems = ({
    isSkeleton,
    workModeLabel,
    employmentTypeLabel,
    location,
    postedAgoLabel,
}: Pick<JobDetailPageProps, "isSkeleton" | "workModeLabel" | "employmentTypeLabel" | "location" | "postedAgoLabel">): Array<ComponentTypeWithSkeleton> => {
    if (isSkeleton) {
        return [
            () => <Chip tone="default" isSkeleton />,
            () => <Chip tone="accent" isSkeleton />,
            () => <Typography size="sm" color="muted" isSkeleton />,
        ]
    }
    return [
        ...(workModeLabel ? [() => <Chip tone="default" text={workModeLabel} />] : []),
        ...(employmentTypeLabel ? [() => <Chip tone="accent" text={employmentTypeLabel} />] : []),
        ...(location ? [() => <Typography size="sm" color="muted" prefixIcon={MapPinIcon} text={location} />] : []),
        ...(postedAgoLabel ? [() => <Typography size="sm" color="muted" text={postedAgoLabel} />] : []),
    ]
}

/**
 * `_JobDetailPage` — the presentational half of {@link import("./index").JobDetailPage}: full posting
 * (title, company, markdown description + requirements, salary, work-mode/employment-type chips)
 * and the apply CTA. Four states in the fixed order error → skeleton → empty → content
 * (`loading-and-skeleton.md`): `error` falls to the shared `AsyncContentError` frame, `isEmpty`
 * to `AsyncContentEmpty`, and otherwise the ONE tree renders with `isSkeleton` threaded to every
 * leaf that supports it. `PageHeader`/`IconTile`/`MarkdownContent` carry no `isSkeleton` prop of
 * their own, so their loading state is mirrored in place with `Skeleton.*` right where each sits.
 * See `tiers/split.md` — the connected `index.tsx` owns the fetch and i18n.
 *
 * @param props - {@link JobDetailPageProps}
 */
export const _JobDetailPage = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    title,
    workModeLabel,
    employmentTypeLabel,
    location,
    postedAgoLabel,
    company,
    salaryLabel,
    description,
    requirements,
    expired = false,
    canApplyExternal = false,
    canApplyByEmail = false,
    onApplyExternal,
    onApplyByEmail,
    labels,
}: JobDetailPageProps) => {
    // error beats a stale loading flag; empty only once settled (loading-and-skeleton.md §1)
    if (error) {
        return <AsyncContentError title={labels.error} onRetry={onRetry} retryLabel={labels.retry} />
    }
    if (!isSkeleton && isEmpty) {
        return <AsyncContentEmpty icon={BriefcaseIcon} title={labels.notFound} />
    }

    const metaItems = buildMetaItems({ isSkeleton, workModeLabel, employmentTypeLabel, location, postedAgoLabel })
    const showRequirements = isSkeleton || Boolean(requirements)
    const showCompanyDescription = isSkeleton || Boolean(company?.description)

    return (
        <Container
            body={() => (
                <StackV
                    gap={8}
                    items={[
                        // Title + meta chip row — PageHeader has no isSkeleton of its own, so its
                        // title slot is fed a co-located Skeleton.Typography while loading.
                        () => (
                            <PageHeader
                                title={isSkeleton ? <Skeleton.Typography type="h3" width="2/3" /> : title}
                                meta={<Cluster gap={3} items={metaItems} />}
                            />
                        ),

                        // Company card — logo tile (no isSkeleton of its own, mirrored in place),
                        // name (linked to the company page when resolvable), description, salary.
                        () => (
                            <SurfaceCard
                                body={() => (
                                    <StackH
                                        gap={3}
                                        principle="content-row"
                                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                        items={[
                                            () => (isSkeleton ? (
                                                <Skeleton className="size-16 shrink-0 rounded-2xl" />
                                            ) : (
                                                <IconTile
                                                    icon={<BuildingsIcon aria-hidden focusable="false" />}
                                                    src={company?.logoUrl}
                                                    alt={company?.title}
                                                    tone="neutral"
                                                    size="md"
                                                />
                                            )),
                                            () => {
                                                const companyHref = !isSkeleton ? company?.href : undefined
                                                return (
                                                    <StackV
                                                        gap={1}
                                                        classNames={["min-w-0", "flex-1"]}
                                                        items={[
                                                            () => (companyHref ? (
                                                                <Typography
                                                                    size="base"
                                                                    weight="semibold"
                                                                    isLink
                                                                    href={companyHref}
                                                                    underlineOnHover
                                                                    color="default"
                                                                    text={company?.title ?? ""}
                                                                />
                                                            ) : (
                                                                <Typography size="base" weight="semibold" isSkeleton={isSkeleton} text={company?.title ?? ""} />
                                                            )),
                                                            ...(showCompanyDescription ? [() => (
                                                                <Typography size="sm" color="muted" lineClamp={2} isSkeleton={isSkeleton} text={company?.description ?? ""} />
                                                            )] : []),
                                                        ]}
                                                    />
                                                )
                                            },
                                            () => <Typography size="h4" weight="bold" classNames={["shrink-0"]} isSkeleton={isSkeleton} text={salaryLabel ?? ""} />,
                                        ]}
                                    />
                                )}
                            />
                        ),

                        // Description + optional requirements — MarkdownContent has no isSkeleton of
                        // its own, so its loading state is a co-located Skeleton.Paragraph.
                        () => (
                            <StackV
                                gap={6}
                                items={[
                                    () => (
                                        <StackV
                                            gap={2}
                                            items={[
                                                () => <Typography size="base" weight="semibold" isSkeleton={isSkeleton} text={labels.descriptionLabel} />,
                                                () => (isSkeleton
                                                    ? <Skeleton.Paragraph lines={DESCRIPTION_SKELETON_LINES} />
                                                    : <MarkdownContent markdown={description ?? ""} />),
                                            ]}
                                        />
                                    ),
                                    ...(showRequirements ? [() => (
                                        <StackV
                                            gap={2}
                                            items={[
                                                () => <Typography size="base" weight="semibold" isSkeleton={isSkeleton} text={labels.requirementsLabel} />,
                                                () => (isSkeleton
                                                    ? <Skeleton.Paragraph lines={REQUIREMENTS_SKELETON_LINES} />
                                                    : <MarkdownContent markdown={requirements ?? ""} />),
                                            ]}
                                        />
                                    )] : []),
                                ]}
                            />
                        ),

                        // Apply CTA — a closed-notice callout once expired, otherwise the one CTA the
                        // posting's applyMethod resolves to. A generic button shimmer while loading,
                        // since expiry/method aren't known yet.
                        () => {
                            if (isSkeleton) {
                                return <Button isSkeleton size="lg" />
                            }
                            if (expired) {
                                return <Callout status="warning" title={labels.expired} />
                            }
                            if (canApplyExternal) {
                                return <Button variant="primary" size="lg" label={labels.apply} suffixIcon={ArrowRightIcon} onPress={onApplyExternal} />
                            }
                            if (canApplyByEmail && labels.applyByEmail) {
                                return <Button variant="primary" size="lg" label={labels.applyByEmail} suffixIcon={ArrowRightIcon} onPress={onApplyByEmail} />
                            }
                            return null
                        },
                    ]}
                />
            )}
        />
    )
}

