/** Step card for the static layout (mobile / reduced-motion fallback). */
/**
 * The 4-step list (ListBox) shared by both variants. `active` = the step currently selected;
 * clicking a step → `onSelect(index)` (pinned: scrolls to that step · static: sets active
 * directly). done (index < active) shows a green check; active = accent.
 */
const LoopStepList = ({ active, onSelect }: { active: number; onSelect: (index: number) => void }) => {
    const t = useTranslations()
    const activeKey = LANDING_LOOP_STEPS[active]
    return (
        <ListBox
            aria-label={t("landing.learnLoop.title")}
            selectionMode="single"
            disallowEmptySelection
            selectedKeys={[activeKey]}
            onSelectionChange={(keys) => {
                const key = [...keys][0]
                const index = LANDING_LOOP_STEPS.findIndex((step) => step === key)
                if (index >= 0) {
                    onSelect(index)
                }
            }}
            className="gap-1 p-0" data-principle="title-subtitle"
        >
            {LANDING_LOOP_STEPS.map((key, index) => {
                const selected = key === activeKey
                const done = index < active
                const stepColor = cn(
                    "transition-colors group-data-[hovered=true]:text-accent-soft-foreground",
                    done ? "text-success-soft-foreground" : selected ? "text-accent-soft-foreground" : "text-muted",
                )
                return (
                    <ListBox.Item
                        key={key}
                        id={key}
                        textValue={t(`landing.learnLoop.items.${key}.title`)}
                        className={cn(
                            "group cursor-pointer rounded-xl px-4 py-2 transition-colors data-[hovered=true]:bg-accent-soft",
                            selected && "bg-accent-soft",
                        )}
                    >
                        <StackH gap={4} principle="content-row" items={[
                            () => (
                                <span className={cn("[&>svg]:size-5", stepColor)}>
                                    {done ? (
                                        <CheckCircleIcon aria-hidden focusable="false" className="size-5" />
                                    ) : (
                                        STEP_ICONS[key]
                                    )}
                                </span>
                            ),
                            () => (
                                <Typography type="body" className={stepColor}>
                                    {t(`landing.learnLoop.items.${key}.title`)}
                                </Typography>
                            ),
                        ]} />
                    </ListBox.Item>
                )
            })}
        </ListBox>
    )
}

/** The visual panel that changes per step (crossfade) — shared by both variants. */
const LoopPanel = ({ activeKey }: { activeKey: string }) => (
    <div className="relative min-h-[320px]">
        <AnimatePresence mode="wait">
            <motion.div
                key={activeKey}
                initial={{ opacity: 0, y: 12 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -12 }}
                transition={{ duration: 0.25 }}
            >
                <StepVisual stepKey={activeKey} />
            </motion.div>
        </AnimatePresence>
    </div>
)

/** Heading shared by both variants (static + pinned). */
const LoopHeading = () => {
    const t = useTranslations()
    // CTA "jump in and try it" — scrolls down to the Tracks block (#courses) to pick a track + try a lesson.
    const onJumpIn = () => document.getElementById("courses")?.scrollIntoView({ behavior: "smooth" })
    return (
        <StackV align="center" gap={6} principle="block-boundary" items={[
            () => (
                <SectionHeading
                    eyebrow={t("landing.learnLoop.eyebrow")}
                    title={t("landing.learnLoop.title")}
                    intro={t("landing.learnLoop.intro")}
                />
            ),
            () => (
                <Button variant="primary" size="lg" onPress={onJumpIn}>
                    {t("landing.learnLoop.cta")}
                    <ArrowRightIcon aria-hidden focusable="false" className="size-5" />
                </Button>
            ),
        ]} />
    )
}

/**
 * CLICK-DRIVEN layout (mobile / reduced-motion / before mount) — a clickable list + a panel
 * that changes per step, NO scroll-hijack. Same list+panel as pinned, the only difference: clicking
 * a step sets active directly (no scrolling). Mobile: list on top · panel below (1 column).
 */
const LearnLoopStatic = ({ className }: LearnLoopScrollProps) => {
    const [active, setActive] = useState(0)
    return (
        <section className={cn("flex flex-col gap-16", className)}>
            <LoopHeading />
            <div className="grid grid-cols-1 items-center gap-x-12 gap-y-12 @app-lg:grid-cols-2 @app-lg:gap-y-20">
                <div>
                    <LoopStepList active={active} onSelect={setActive} />
                </div>
                <LoopPanel activeKey={LANDING_LOOP_STEPS[active]} />
            </div>
        </section>
    )
}

/**
 * PINNED variant (desktop) — split out so `useScroll`'s target ref is ALWAYS attached to
 * the rendered `<section>` (avoiding "Target ref defined but not hydrated" when the
 * fallback branch attaches no ref). Pins the block centered on screen; scrolling → active
 * step 01→04 + the right visual changes + a progress bar; scrolling past → `sticky` releases.
 * Clicking a step in the ListBox → scrolls to that step.
 */
const LearnLoopPinned = ({ className }: LearnLoopScrollProps) => {
    const sectionRef = useRef<HTMLDivElement>(null)
    const [active, setActive] = useState(0)

    const { scrollYProgress } = useScroll({
        target: sectionRef,
        offset: ["start start", "end end"],
    })
    useMotionValueEvent(scrollYProgress, "change", (value) => {
        const last = LANDING_LOOP_STEPS.length - 1
        const index = Math.min(last, Math.max(0, Math.round(value * last)))
        setActive(index)
    })

    /** Scrolls the window to the position matching step `index` (when the ListBox is clicked). */
    const jumpToStep = (index: number) => {
        const element = sectionRef.current
        if (!element) {
            return
        }
        const last = LANDING_LOOP_STEPS.length - 1
        const fraction = last > 0 ? index / last : 0
        const start = element.getBoundingClientRect().top + window.scrollY
        const distance = element.offsetHeight - window.innerHeight
        window.scrollTo({ top: start + fraction * distance, behavior: "smooth" })
    }

    const activeKey = LANDING_LOOP_STEPS[active]

    return (
        <section ref={sectionRef} className={cn("relative h-[360vh]", className)}>
            <div className="sticky top-0 flex h-screen flex-col justify-center gap-16 py-12">
                <LoopHeading />
                <div className="grid grid-cols-1 items-center gap-x-12 gap-y-12 @app-lg:grid-cols-2 @app-lg:gap-y-20">
                    {/* LEFT — the 4-step list (scroll drives active; click → scrolls to it). RIGHT — the visual that changes. */}
                    <div>
                        <LoopStepList active={active} onSelect={jumpToStep} />
                    </div>
                    <LoopPanel activeKey={activeKey} />
                </div>
            </div>
        </section>
    )
}

/**
 * "How you learn" section (the 4-step learning loop). Desktop (after mount, no reduced-motion) →
 * {@link LearnLoopPinned} (scroll-pinned, like ika.xyz). Mobile / reduced-motion /
 * before mount → {@link LearnLoopStatic} (4 static cards, no scroll-hijack + a11y).
 * Split into 2 variants so `useScroll` (inside Pinned) only runs once the `<section ref>` actually
 * renders — avoiding the "Target ref defined but not hydrated" error.
 *
 * @param props - optional className (placement only).
 */
export const LearnLoopScroll = ({ className }: LearnLoopScrollProps) => {
    const reduce = useReducedMotion()
    const { isDesktop } = useSmViewpoint()
    const [mounted, setMounted] = useState(false)

    useEffect(() => setMounted(true), [])

    if (!mounted || !isDesktop || reduce) {
        return <LearnLoopStatic className={className} />
    }
    return <LearnLoopPinned className={className} />
}

import React, { useEffect, useRef, useState } from "react"
import {
    BookOpenIcon,
    MedalIcon,
    StackIcon,
    UsersIcon,
    type Icon as PhosphorIcon,
} from "@phosphor-icons/react"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { Typography } from "@/components/atoms/text/Typography"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Box } from "@/components/frames/Box"

/** How long a figure counts up from 0 → its value (ms). */
const COUNT_DURATION = 1500

/** A stat cell's glyph — a COMPONENT REFERENCE (`icon={UsersIcon}`), never a built node. */
export type StatStripIcon = PhosphorIcon

/** The four public counters {@link _StatStrip} shows, already resolved by the connected `StatStrip` (real data, or its fallback on fetch error). */
export interface StatStripStats {
    totalLearners: number
    totalLessons: number
    totalCourses: number
    totalBadgesEarned: number
}

/** All display text, already localized by the connected `StatStrip`; a story passes i18n keys. */
export interface StatStripLabels {
    learners: string
    lessons: string
    courses: string
    badges: string
}

/** One entry of the fixed stat order — icon + which counter/label it reads. */
interface StatCellSpec {
    key: keyof StatStripStats
    icon: StatStripIcon
    labelKey: keyof StatStripLabels
}

/** Fixed reading order of the four cells — icon paired with its counter + label. */
const STAT_CELLS: ReadonlyArray<StatCellSpec> = [
    { key: "totalLearners", icon: UsersIcon, labelKey: "learners" },
    { key: "totalLessons", icon: BookOpenIcon, labelKey: "lessons" },
    { key: "totalCourses", icon: StackIcon, labelKey: "courses" },
    { key: "totalBadgesEarned", icon: MedalIcon, labelKey: "badges" },
]

/** Props for {@link _StatStrip} — presentational; all data/text resolved, no fetch/store/i18n. */
export type StatStripProps = WithClassNames<undefined> & {
    /** First load, nothing in hand → the whole strip shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** The four counters. Ignored while `isSkeleton` — each cell shows a placeholder instead of a real value. */
    stats: StatStripStats
    labels: StatStripLabels
    /**
     * Locale to format the count-up figures with (`Number.toLocaleString`). Passed as a
     * resolved prop rather than read via `useLocale()` here — `component.tsx` takes no
     * session of its own (`tiers/split.md`'s test: renderable from plain props alone).
     */
    locale: string
}

/**
 * Counts a number from 0 → `target` the first time it scrolls into view, eased
 * out via requestAnimationFrame. Respects `prefers-reduced-motion` (snaps to the
 * final figure, no animation). Returns the ref to attach + the current value.
 *
 * Skips entirely while `isSkeleton` — there is no real figure to animate toward
 * yet, and the effect re-fires on its own once `target`/`isSkeleton` change and
 * the real value arrives, so the count-up still plays exactly once.
 */
const useCountUp = (target: number, isSkeleton: boolean) => {
    const ref = useRef<HTMLDivElement>(null)
    const [value, setValue] = useState(0)

    useEffect(() => {
        if (isSkeleton) {
            return
        }
        const element = ref.current
        if (!element) {
            return
        }
        // reduced motion → show the final figure immediately
        if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
            setValue(target)
            return
        }
        let raf = 0
        const observer = new IntersectionObserver(
            ([entry]) => {
                if (!entry.isIntersecting) {
                    return
                }
                // fire once — the count-up should not replay on re-entry
                observer.disconnect()
                const start = performance.now()
                const tick = (now: number) => {
                    const progress = Math.min((now - start) / COUNT_DURATION, 1)
                    // ease-out cubic: fast then settling
                    const eased = 1 - Math.pow(1 - progress, 3)
                    setValue(Math.round(target * eased))
                    if (progress < 1) {
                        raf = requestAnimationFrame(tick)
                    }
                }
                raf = requestAnimationFrame(tick)
            },
            { threshold: 0.4 },
        )
        observer.observe(element)
        return () => {
            observer.disconnect()
            cancelAnimationFrame(raf)
        }
    }, [target, isSkeleton])

    return { ref, value }
}

/** Props for {@link StatCell}. */
interface StatCellProps {
    icon: StatStripIcon
    value: number
    label: string
    locale: string
    /** Co-located shimmer — same wrapper box, icon/number/label swapped for placeholders. */
    isSkeleton?: boolean
}

/**
 * One editorial stat — a small accent icon over a count-up number over a small
 * muted label, with a left divider on desktop so the four read as a flush strip.
 * `isSkeleton` threads straight to the icon glyph, the number, and the label so
 * the shimmer mirrors this exact box (`loading-and-skeleton.md` §1).
 */
const StatCell = ({ icon: Icon, value, label, locale, isSkeleton = false }: StatCellProps) => {
    const { ref, value: shown } = useCountUp(value, isSkeleton)

    return (
        <div
            ref={ref}
            data-principle="sibling-stack" className="flex flex-col items-center gap-2 px-4 @app-md:border-l @app-md:border-default @app-md:first:border-l-0"
        >
            {isSkeleton ? (
                <Skeleton className="size-6 rounded-full" />
            ) : (
                <span className="text-accent-soft-foreground [&>svg]:size-6">
                    <Icon aria-hidden focusable="false" />
                </span>
            )}
            {isSkeleton ? (
                <Skeleton className="h-11 w-20 rounded-lg" />
            ) : (
                <div className="text-4xl font-semibold tracking-tight tabular-nums text-foreground @app-md:text-5xl">
                    {shown.toLocaleString(locale)}
                </div>
            )}
            <Typography size="sm" color="muted" text={label} isSkeleton={isSkeleton} />
        </div>
    )
}

/**
 * Live platform proof strip — the presentational half of `StatStrip` — four
 * counters (learners / lessons / courses / badges) rendered EDITORIAL: a small
 * icon over a number that counts up from 0 over a small label, separated by
 * vertical dividers (no metric cards) so the figures carry it.
 *
 * ONE tree, `isSkeleton` threaded to every leaf (`loading-and-skeleton.md` §1) —
 * there is no separate hand-kept skeleton tree. This strip never showed a
 * dedicated error or empty message: on fetch error the connected `StatStrip`
 * substitutes fallback figures (99 for every counter) so the strip still
 * renders as normal content instead of hiding or apologising — so there is no
 * `AsyncContentError`/`AsyncContentEmpty` branch here to preserve.
 *
 * @param props - {@link StatStripProps}
 */
export const _StatStrip = ({ className, isSkeleton = false, stats, labels, locale }: StatStripProps) => (
    <Box identity={{ tier: "block", component: "StatStrip" }} className={className}>
        <div className="grid grid-cols-2 gap-y-8 @app-md:grid-cols-4 @app-md:gap-0">
            {STAT_CELLS.map(({ key, icon, labelKey }) => (
                <StatCell
                    key={key}
                    icon={icon}
                    value={stats[key]}
                    label={labels[labelKey]}
                    locale={locale}
                    isSkeleton={isSkeleton}
                />
            ))}
        </div>
    </Box>
)

"use client"

import React from "react"
import { useLocale, useTranslations } from "next-intl"
import { useQueryPlatformStatsSwr } from "@/hooks/swr/api/graphql/queries/useQueryPlatformStatsSwr"
import { _StatStrip } from "./component"
import type { StatStripStats } from "./component"

/** Fallback figures when the public stats query fails — show 99 for every counter
 * (teacher's choice) so the proof strip still renders instead of vanishing. */
const FALLBACK_STATS: StatStripStats = {
    totalLearners: 99,
    totalLessons: 99,
    totalCourses: 99,
    totalBadgesEarned: 99,
} as const

/** All-zero placeholder handed to `_StatStrip` while `isSkeleton` — never actually
 * shown (every cell renders a shimmer instead of its number), it only satisfies
 * the required `stats` shape while there is nothing real to hand down yet. */
const SKELETON_STATS: StatStripStats = {
    totalLearners: 0,
    totalLessons: 0,
    totalCourses: 0,
    totalBadgesEarned: 0,
} as const

/** Props for {@link StatStrip}. */
export type StatStripProps = Record<string, never>
/**
 * Live platform proof strip — the CONNECTED half of `StatStrip` (`tiers/split.md`):
 * fetches the public `platformStats` query, computes `isSkeleton` from the
 * first-load formula, resolves the fallback-on-error figures and every label, and
 * hands them to the presentational {@link _StatStrip}.
 *
 * @param props - {@link StatStripProps}
 */
export const StatStrip = () => {
    const t = useTranslations()
    const locale = useLocale()
    const { data, isLoading, error } = useQueryPlatformStatsSwr()

    // first load, nothing in hand → shimmer (loading-and-skeleton.md §2)
    const isSkeleton = isLoading && !data && !error
    // settled: real data, or 99-for-every-figure on error so the strip still renders
    const stats = isSkeleton ? SKELETON_STATS : (error ? FALLBACK_STATS : data ?? FALLBACK_STATS)

    return (
        <_StatStrip
            isSkeleton={isSkeleton}
            stats={stats}
            locale={locale}
            labels={{
                learners: t("landing.stats.learners"),
                lessons: t("landing.stats.lessons"),
                courses: t("landing.stats.courses"),
                badges: t("landing.stats.badges"),
            }}
        />
    )
}

