/** Props for {@link MockInterviewSession}. */
export interface MockInterviewSessionProps extends WithClassNames<undefined> {
    /** Course the interview systems are drawn from (enrolled-only, like the flashcard interview). */
    courseId: string
    /** Course display id, for building the scorecard's "study this" deep link. */
    courseDisplayId: string
    /**
     * Present when mounted from the dedicated `/mock-interview/interview/[sessionId]`
     * route — on mount, rehydrates that session from `myInProgressMockInterviewSession`
     * (24h TTL) and skips straight to the interview phase instead of showing the
     * green room. Falls back to normal setup when the session can't be resumed
     * (null / mismatched / expired).
     */
    resumeSessionId?: string
}

// "scorecard" was a 4th phase rendered inline here; the just-graded and the
// resume-finds-a-finished-session paths both now `router.replace` to the
// dedicated `.result()` route instead (2026-07-13) — see `finishAndGrade`'s
// own comment for why. `MockInterviewResult` renders the scorecard there.
/** The three screens {@link MockInterviewSession} itself still renders. */
type MockInterviewPhase = "setup" | "interview" | "grading"

/** The five canonical interview phases, in interview-driven order. */
const PHASES: ReadonlyArray<MockInterviewPhaseKey> = [
    "requirements",
    "estimation",
    "highLevel",
    "deepDive",
    "tradeoffs",
]

/** Auto lane (balancer picks) — the default grading selection. */
const AUTO_SELECTION: GradeModelSelection = {
    model: null,
    provider: null,
}

/** Mid-tier and above — the only categories offered for interview grading. */
const GRADE_CATEGORIES: ReadonlyArray<AiModelCategory> = [
    AiModelCategory.Medium,
    AiModelCategory.High,
]

/**
 * The ONE setup decision — a 3-notch difficulty tier. Collapses what used to be two
 * hardness knobs (prompt `difficulty` + rubric `level`) into a single axis: picking a
 * tier drives BOTH the server-side prompt draw AND the grading rubric's strictness.
 */
type MockInterviewTier = "so" | "trung" | "cao"

/** Tier → rubric level string sent to `startMockInterviewSession`/`gradeMockInterviewSession`. */
const TIER_CONFIG: Record<MockInterviewTier, { level: string }> = {
    so: { level: "junior" },
    trung: { level: "middle" },
    cao: { level: "senior" },
}

/** Reverse of {@link TIER_CONFIG}'s `level` — resolves a resumed session's server-stored
 *  level string back to its notch, so a resumed run's tier control reads correctly. */
const LEVEL_TO_TIER: Record<string, MockInterviewTier> = {
    junior: "so",
    middle: "trung",
    senior: "cao",
}

/** Tier notches, in ascending order — the {@link FlexWrapButtonRadio}'s fixed item order (setup's shared Level control). */
const TIERS: ReadonlyArray<MockInterviewTier> = ["so", "trung", "cao"]

/** Number of questions drawn for a `mode="qna"` session (mirrors the BE's default seed count). */
const QNA_QUESTION_COUNT = 5

/**
 * Setup's top-level config mode (Round 5) — "Auto" (default) is the flat,
 * sensible-default mock-exam run (random everything, feeds job-readiness);
 * "Custom" reveals the deliberate-practice controls below and does NOT
 * feed job-readiness (kept a clean signal from random runs only).
 */
type MockInterviewConfigMode = "auto" | "configurable"

/**
 * "Custom"'s question-count options, in ascending order. Kept as STRINGS
 * (not numbers) because {@link FlexWrapButtonRadio} is a `<T extends string>`
 * single-select — parsed back to a number only when building the request.
 */
const QUESTION_COUNT_OPTIONS: ReadonlyArray<"3" | "5" | "10"> = ["3", "5", "10"]

/** "Custom"'s per-question cognitive frames, in fixed display order. */
const KIND_OPTIONS: ReadonlyArray<MockInterviewKind> = ["theory", "reasoning", "scenario"]

/**
 * Pseudo-value for the kind picker's "All" button — pressed when NO kind filter is set
 * (`selectedKinds` empty). Lets the whole row be ONE canonical {@link FlexWrapButtonRadio}
 * (multi) like the Language picker, instead of a hand-rolled pill sitting beside the group.
 */
const KIND_ALL = "all" as const

/** Kind-picker value: a real kind, or the {@link KIND_ALL} "no filter" pseudo-value. */
type KindPickerValue = MockInterviewKind | typeof KIND_ALL

/**
 * How the candidate answers each question — FE-only (the backend never sees
 * this): "voice" shows only the mic control, "text" only the typing box,
 * "both" (default) shows both, mirroring the mic-icon-inside-the-textfield
 * composer already built for the qna screen.
 */
type MockInterviewAnswerMode = "voice" | "text" | "both"

/**
 * The prompt drawn for the current run, as returned by `startMockInterviewSession`.
 * `id`/`title` are consumed by the interviewer stream + grade request; `seedTopics`
 * additionally drives the `mode="qna"` question counter + each question's own
 * seed text + kind badge (empty for `mode="design"`).
 */
interface DrawnMockInterviewPrompt {
    id: string
    title: string
    seedTopics: Array<MockInterviewSeedTopic>
    /** Where the questions came from — `"interview-bank"` (authored prompts,
     *  delivered STATICALLY with no AI call) vs `"flashcard"` (AI-framed live). */
    source: string
}

/** Bank questions are pre-authored → the interviewer just READS them (no AI turn
 *  call to ask); only flashcard-seed sessions AI-frame a topic into a question. */
const isStaticBankPrompt = (prompt: DrawnMockInterviewPrompt | undefined): boolean =>
    prompt?.source === "interview-bank"

/**
 * Whether the CURRENT question has ANYTHING to submit from the code/whiteboard
 * workspace — `mode="design"` always does (its answer IS the architecture
 * diagram); `qna` only when this question ships given code (debug/review/
 * optimize). A plain theory/reasoning/scenario question has nothing to draw
 * or edit there — its answer is spoken/typed — so the workspace toggle is
 * disabled entirely rather than opening an empty, purposeless pane
 * (2026-07-09 feedback: a blank "Architecture diagram board" for a theory question).
 */
const questionHasWorkspaceTool = (isDesignMode: boolean, givenCodes: Array<{ lang: string, code: string }> | undefined): boolean =>
    isDesignMode || Boolean(givenCodes && givenCodes.length > 0)

/**
 * Normalize an authored `givenLang` string for the workspace editor's code state.
 * Given code is NOT restricted to the 4 `ProgrammingLanguage` implementation tracks —
 * a debug/review/optimize question can ship any content language authored in `.mount`
 * (`dockerfile`, `yaml`, `bash`, `nginx`, …), so this only lowercases/trims and
 * defaults to TypeScript when truly unset. It used to COERCE anything outside the
 * 4-enum list down to TypeScript (2026-07-17 fix — that silently mislabeled every
 * non-{ts,java,csharp,go} given code both in the language picker AND in the grading
 * transcript's `[Code lang=...]` tag, e.g. a Dockerfile question graded as if it
 * were TypeScript). `MockInterviewWorkspace`'s `languageExtensionFor` resolves
 * whatever string comes out of here to its own CodeMirror language extension,
 * falling back to plain text (no wrong-language highlighting) for anything it
 * doesn't recognize.
 */
const resolveGivenCodeLang = (lang: string | null | undefined): string => {
    const normalized = (lang ?? "").trim().toLowerCase()
    return normalized.length > 0 ? normalized : ProgrammingLanguage.TypeScript
}

/**
 * Resolve which authored language variant a debug/review/optimize question
 * opens on — reuses `resolveActiveProgrammingLang` (same helper `ChallengeView`
 * uses for its own 4-language step content): TypeScript wins if authored,
 * else whichever language IS authored, in `DEFAULT_PROGRAMMING_LANGUAGES`
 * order. Mock Interview has no cross-session "last picked language" memory
 * (unlike Challenge's `storedLang`, sourced from past submission history) —
 * each debug question just opens on the first authored language.
 */
const resolveOpeningGivenCode = (
    givenCodes: Array<{ lang: string, code: string }>,
): { lang: string, code: string } | null => {
    if (givenCodes.length === 0) {
        return null
    }
    const openLang = resolveActiveProgrammingLang(null, givenCodes.map((variant) => variant.lang))
    return givenCodes.find((variant) => variant.lang === openLang) ?? givenCodes[0]
}

/** Format elapsed seconds as mm:ss. */
const formatElapsed = (seconds: number): string => {
    const mm = Math.floor(seconds / 60)
    const ss = seconds % 60
    return `${String(mm).padStart(2, "0")}:${String(ss).padStart(2, "0")}`
}

/** Below this many seconds remaining, the HUD countdown turns warning-colored (session time limit, real urgency — not fake scarcity). */
const TIME_LIMIT_WARNING_SECONDS = 5 * 60

/**
 * Mock interview — two top-level MODES (2026-07-06 "mode split"): `qna` draws
 * N independent questions, each RANDOMLY assigned one of 3 cognitive frames
 * (theory/reasoning/scenario) at draw time — mixed within one session, "just
 * like a real interview" — badged per-question ("Question 2/5 · Scenario"); `design`
 * keeps the unchanged 5-phase system-design flow, reached from its own setup
 * button (System-Design courses only).
 *
 * Setup is flat (no per-control cards): a 3-notch tier (Junior/Mid/Senior) drives
 * both the random draw and the rubric's strictness; the prompt/questions are
 * only revealed once the session starts (like a real interview). The
 * right-pane workspace ({@link MockInterviewWorkspace}) renders straight to
 * whichever tool the current question needs (whiteboard for design, code for a
 * debug/review/optimize question) — its artifact is folded into the
 * transcript as a labeled synthetic candidate turn at grade time. The AI
 * interviewer's turns stream over the `/mock_interview` socket
 * (`useMockInterviewTurnStream`, one active stream at a time), grounded via
 * RAG on the current course. The end-of-session grade calls
 * `gradeMockInterviewSession`.
 * @param props - {@link MockInterviewSessionProps}
 */
export const MockInterviewSession = ({ courseId, courseDisplayId, resumeSessionId, className }: MockInterviewSessionProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const pathname = usePathname()
    const runGraphQL = useGraphQLWithToast()
    const searchParams = useSearchParams()
    const recognitionLang = locale === "vi" ? "vi-VN" : "en-US"

    // unified AI credit pool snapshot — re-checked (typed, no message-string guessing)
    // right after a grading failure so a quota-exhausted failure can be told apart
    // from any other failure and routed to the AI-subscription upsell (mirrors the
    // pattern ChallengeSubmissionPanel already uses via `resolveGradeCreditDisplay`).
    const aiQuotaSwr = useQueryMyAiQuotaSwr()

    const {
        supported,
        listening,
        transcript,
        interimTranscript,
        start,
        stop,
        reset,
    } = useSpeechRecognition({ lang: recognitionLang })

    // text-to-speech — the interviewer READS its question aloud (default on).
    // Kept in a ref so `askNextTurn` can speak/cancel without re-subscribing the
    // single in-flight socket stream when the toggle or locale changes.
    const tts = useSpeechSynthesis({ lang: recognitionLang })
    const ttsRef = useRef(tts)
    ttsRef.current = tts

    // grading-model catalog + entitlement (mid+ tiers unlock on paid OR enrolled)
    const aiModelsSwr = useQueryAiModelsSwr()
    const myAiSettingsSwr = useQueryMyAiSettingsSwr()
    const canPremium = Boolean(myAiSettingsSwr.data?.canPremium)
    const gradeModels = useMemo<Array<AiGradableModel>>(
        () => (aiModelsSwr.data?.aiModels?.data?.gradableModels ?? []).filter(
            (model) =>
                GRADE_CATEGORIES.includes(model.category)
                && (model.supportedTasks?.length
                    ? model.supportedTasks.includes(AiModelTask.Grading)
                    : true),
        ),
        [aiModelsSwr.data],
    )

    const turnStream = useMockInterviewTurnStream()
    const gradeSwr = useMutateGradeMockInterviewSessionSwr()
    const startSessionSwr = useMutateStartMockInterviewSessionSwr()
    // the viewer's resumable in-progress session for this course (24h TTL), if any —
    // read BOTH by the rehydrate effect below (when `resumeSessionId` is present) and
    // by the setup screen's "Resume session" card (always, so it can offer resuming even
    // when the learner just landed on the plain `/mock-interview` route).
    const inProgressSessionSwr = useQueryMyInProgressMockInterviewSessionSwr(courseId)
    const syncTurnsSwr = useMutateSyncMockInterviewSessionTurnsSwr()
    // `inProgressSessionSwr`'s query key is gated on `state.keycloak.authenticated`
    // (starts false, only flips true once the app's user-auth check succeeds), so while
    // that check is still in flight the query is DISABLED — SWR reports `isLoading: false`
    // for a disabled query, which looks identical to "fetched, no session" if the
    // rehydrate effect below only checked `isLoading`. Reuse `useQueryUserSwr` (the SAME
    // hook `SwrSideEffects` already calls once at the app root — SWR dedupes by key, so
    // this shares its cache/loading state instead of firing a second request) as the real
    // "has the auth check settled yet" signal. `state.keycloak.initialized` looks like it
    // should serve this — it does NOT: nothing in the app ever dispatches `setInitialized`,
    // so it is permanently `false` and must NOT be used as a gate (verified 2026-07-08 —
    // gating on it here previously made the rehydrate effect below never run at all).
    const authCheckSwr = useQueryUserSwr()

    const [phase, setPhase] = useState<MockInterviewPhase>("setup")
    // which setup tab is active ("Start" / "History" / "Stats") — setup phase only.
    // Seeded from `?tab=` so a shared/refreshed link lands back on the same tab (mirrors
    // the `?phase=` sync below, and `layouts/dashboard-hub.md`'s own "?tab= must be
    // shareable" precedent) — "begin" is the implicit default, never written to the URL.
    const [setupTab, setSetupTab] = useState<"begin" | "history" | "stats">(() => {
        const initial = searchParams.get("tab")
        return initial === "history" || initial === "stats" ? initial : "begin"
    })
    const [tier, setTier] = useState<MockInterviewTier>("trung")
    // learner-chosen name for this run, set at setup ("Customize session") — optional;
    // blank falls back to a TIME-BASED display name derived from `createdAt` once
    // the session exists (see `sessionDisplayName`), never random-generated.
    const [sessionName, setSessionName] = useState("")
    // programming languages selected at setup (MULTI-select, 2026-07-17) — each
    // code question authored across the 4 tracks is drawn in a RANDOM one of these;
    // a code question authored in none of them is skipped by the server and a
    // different one drawn instead. A non-track given-code question (e.g. dockerfile)
    // and every no-code question ignore this. Defaults to just TypeScript (parity
    // with the old single-select default); the candidate adds more to widen the draw.
    const [interviewLangs, setInterviewLangs] = useState<Array<ProgrammingLanguage>>([ProgrammingLanguage.TypeScript])
    // toggle a language in/out of the selected set, but NEVER let it empty — the
    // draw needs at least one language to serve code questions in (deselecting the
    // last one is a no-op rather than leaving zero).
    const toggleInterviewLang = useCallback((lang: ProgrammingLanguage) => {
        setInterviewLangs((previous) => {
            if (previous.includes(lang)) {
                return previous.length === 1 ? previous : previous.filter((value) => value !== lang)
            }
            return [...previous, lang]
        })
    }, [])
    // setup's "Auto" vs "Custom" toggle — see MockInterviewConfigMode.
    const [configMode, setConfigMode] = useState<MockInterviewConfigMode>("auto")
    // "Custom" only — question count (single-select, kept as a string — see QUESTION_COUNT_OPTIONS).
    const [questionCount, setQuestionCount] = useState<"3" | "5" | "10">("5")
    // "Custom" only — question type (multi-select; empty array reads as "All").
    const [selectedKinds, setSelectedKinds] = useState<Array<MockInterviewKind>>([])
    // "Custom" only — answer method, shapes the qna composer (voice-only/text-only/both).
    const [answerMode, setAnswerMode] = useState<MockInterviewAnswerMode>("both")
    // the TOP-LEVEL flow the current/last-started run is in — "qna" (default,
    // started from the primary CTA) draws N questions each randomly assigned
    // its own kind; "design" (started from its own button, System-Design
    // courses only) keeps the unchanged 5-phase flow.
    const [mode, setMode] = useState<MockInterviewMode>("qna")
    // the prompt drawn for the CURRENT run — only set once the session starts (by the
    // server), so it is never shown on the setup screen (revealed after "Start",
    // like a real exam)
    const [selectedPrompt, setSelectedPrompt] = useState<DrawnMockInterviewPrompt | undefined>(undefined)
    // set when the server-side draw itself fails — surfaced on the setup screen so the
    // candidate can retry without losing their tier/model picks
    const [startError, setStartError] = useState<string | null>(null)
    // which destructive-ish interview action is awaiting confirmation in the shared
    // confirm modal (replaces the old `window.confirm` alert): "leave" abandons the run
    // ungraded, "endEarly" grades with the answers given so far. null = modal closed.
    const [confirmAction, setConfirmAction] = useState<null | "leave" | "endEarly">(null)
    // which start CTA is drawing a session right now (so ONLY the pressed button shows the
    // pending spinner while the OTHER is disabled — both share one `startSessionSwr`, so a
    // bare `isMutating` would spin both). null = idle.
    const [startingMode, setStartingMode] = useState<MockInterviewMode | null>(null)
    // guards the rehydrate effect below to at most one resume attempt per mounted
    // instance, regardless of how many times `inProgressSessionSwr` re-renders/revalidates
    const resumeAttemptedRef = useRef(false)
    const [selection, setSelection] = useState<GradeModelSelection>(AUTO_SELECTION)
    // which of the 5 phases the interview is currently in (mode="design" only)
    const [phaseIndex, setPhaseIndex] = useState(0)
    // which seed question the interview is currently on (Q&A kinds only) — advances
    // over `selectedPrompt.seedTopics` the same way `phaseIndex` advances over `PHASES`
    const [questionIndex, setQuestionIndex] = useState(0)
    // the conversation so far — candidate turns captured via STT, interviewer turns streamed
    const [turns, setTurns] = useState<Array<MockInterviewTurn>>([])
    // set when grading throws/fails — surfaced back on the interview screen so nothing is lost
    const [gradeError, setGradeError] = useState<string | null>(null)
    // true when the LAST grading failure was specifically the AI credit pool being
    // exhausted — shown as a distinct upsell card instead of the generic error box
    const [gradeQuotaExceeded, setGradeQuotaExceeded] = useState(false)
    // client-generated run id (groups this session's attempt in history)
    const sessionId = useRef<string | null>(null)
    // "session time limit" (2026-07-08): server-authoritative ISO deadline for
    // this session's ask loop (createdAt + 1h), from startSession's/resume's
    // own response — the countdown below is DERIVED from this, never from a
    // local clock start; the server independently re-enforces the SAME
    // deadline at ask-time (see useMockInterviewTurnStream's SESSION_EXPIRED).
    const [deadlineAt, setDeadlineAt] = useState<string | null>(null)
    // true once the session has hit its 1-hour deadline (detected by the
    // client tick below reaching 0, OR by an ask coming back
    // `error==="SESSION_EXPIRED"` — whichever happens first) — drives the
    // one-shot auto-grade effect + the Grading screen's "time's up" banner.
    const [timedOut, setTimedOut] = useState(false)
    // guards the auto-grade-on-timeout effect to fire at most once
    const timedOutGradedRef = useRef(false)
    // seconds left until `deadlineAt` (updated by the same tick that checks
    // `timedOut`) — drives the HUD's countdown display; null until the
    // deadline is known (setup / grading / scorecard, or before the first tick).
    const [remainingSeconds, setRemainingSeconds] = useState<number | null>(null)
    // forces the setup screen's resume-card countdown to recompute every 30s —
    // a coarse, minutes-level tick (unlike the live interview's per-second
    // deadline tick above) is proportionate for a static "come back" card.
    const [, setResumeCountdownTick] = useState(0)
    // live text of the interviewer's turn currently streaming in ("" once started, null when idle)
    const [streamingText, setStreamingText] = useState<string | null>(null)
    // mirrors streamingText but read synchronously from the onDelta callback (avoids stale closures)
    const streamingRef = useRef<string>("")
    // true while an interviewer turn is in flight — gates submitAnswer/advancePhase/finishAndGrade
    // so a second `ask()` never overwrites the single in-flight stream tracked by the socket hook
    const [isAsking, setIsAsking] = useState(false)

    // right-pane workspace — which tool renders, driven ENTIRELY by the current
    // question (2026-07-09: dropped the candidate-facing Whiteboard/Code/Notes tab
    // bar + the Notes tool itself — "render the tool directly", no manual picking).
    // "design" always renders the whiteboard (its capstones are architecture
    // systems); "qna" renders code only for a debug/review/optimize question.
    const [workspaceTool, setWorkspaceTool] = useState<"whiteboard" | "code">("whiteboard")
    const diagramRef = useRef<{
        nodes: Array<MockInterviewDiagramNodeSnapshot>
        edges: Array<MockInterviewDiagramEdgeSnapshot>
    }>({ nodes: [], edges: [] })
    const [codeState, setCodeState] = useState<MockInterviewCodeState>(MOCK_INTERVIEW_CODE_STATE_DEFAULT)
    // mode="qna" only — the single answer field's typed draft. Voice input mirrors into
    // this same value (see the effect below) so typing/speaking land in ONE editable field
    // instead of the old mic-only flow with nowhere to type.
    const [answerDraft, setAnswerDraft] = useState("")
    // whether the CURRENT question has a workspace tool to show. Reset to
    // `questionHasWorkspaceTool(...)` at every question/phase transition — no
    // manual toggle anymore (2026-07-13, instructor: "whichever question needs the
    // tool must show it... otherwise render an empty card"): the right pane is ALWAYS visible,
    // it just renders the tool when this is true or an `EmptyState` when false.
    // Stays MOUNTED when true (never `hidden`) so an in-progress sketch/code
    // buffer is never lost.
    const [workspaceOpen, setWorkspaceOpen] = useState(false)
    // green room — whether the (collapsed-by-default) "Customize session" config is open.
    // Defaults sensible (Auto), so the pre-interview screen reads as a calm waiting
    // room, not a settings form; power users expand it to tune the run.
    const [configOpen, setConfigOpen] = useState(false)
    // whether the "no voice for this language installed" nudge is open — the browser's
    // TTS reads the interviewer's question aloud, but only pronounces the current locale
    // correctly if the OS has a matching voice installed (an OS-level resource the page
    // cannot install itself). Opened ONCE per interview when the gap is detected (see the
    // effect below); dismissing persists so it never nags again.
    const [voiceModalOpen, setVoiceModalOpen] = useState(false)
    // guards the nudge to at most once per mounted session (independent of the
    // persisted "dismissed forever" flag) so re-checks/re-renders don't reopen it
    const voiceNudgeShownRef = useRef(false)

    // the interviewer's presented identity for the room (FE-only) — StarCi, a fixed
    // brand persona (face + name), no seniority label. Tier scales questions, not this.
    const persona = personaFor()

    // "Practice system design" is only offered for a System-Design course — its
    // capstones are architecture systems, the only ones the unchanged 5-phase
    // script fits.
    // TODO: refine to "a module large enough for a design interview" once a
    // non-SD track has a capstone that size, rather than gating by track alone.
    const isDesignAvailable = courseDisplayId.includes("system-design")
    const currentPhase = PHASES[phaseIndex]
    const currentLevel = TIER_CONFIG[tier].level
    const isQna = mode === "qna"
    // the current question's own seed text + randomly-assigned kind (mode="qna" only)
    const currentSeedTopic = selectedPrompt?.seedTopics[questionIndex]
    const currentSeed = currentSeedTopic?.title ?? null
    const currentKind = currentSeedTopic?.kind
    const totalQuestions = selectedPrompt?.seedTopics.length ?? QNA_QUESTION_COUNT
    const isLastQuestion = questionIndex >= totalQuestions - 1
    // the single question card (mode="qna", Round 5) shows ONLY the interviewer's turn for
    // the CURRENT question — never the short seed-title preview, which used to render
    // ALONGSIDE the full generated question and read as a duplicate.
    const currentQuestionTurn = [...turns].reverse().find(
        (turn) => turn.role === "interviewer" && turn.questionIndex === questionIndex,
    )


    // mirror the finalized STT transcript into the single answer draft while listening,
    // so typing and voice both land in ONE editable field. Skipped on the
    // very first (empty) tick after `start()` resets the hook's own transcript, so a
    // manually-typed draft is never wiped the instant the mic is tapped.
    useEffect(() => {
        if (listening && transcript.length > 0) {
            setAnswerDraft(transcript)
        }
    }, [listening, transcript])

    // "session time limit" — tick every second while in the interview,
    // comparing against the SERVER-issued `deadlineAt` (never a local clock
    // start); flips `timedOut` once the deadline passes. A DEFENSIVE check
    // (the server independently re-enforces the same deadline at ask-time),
    // so a session with no in-flight ask at the exact moment of expiry still
    // ends promptly instead of waiting for the next `askNextTurn`.
    useEffect(() => {
        if (phase !== "interview" || !deadlineAt || timedOut) {
            return
        }
        const deadlineMs = new Date(deadlineAt).getTime()
        const tick = () => {
            const msLeft = deadlineMs - Date.now()
            if (msLeft <= 0) {
                setRemainingSeconds(0)
                setTimedOut(true)
                return
            }
            setRemainingSeconds(Math.ceil(msLeft / 1000))
        }
        tick()
        const id = window.setInterval(tick, 1000)
        return () => window.clearInterval(id)
    }, [phase, deadlineAt, timedOut])

    // resume-card countdown (setup screen) — coarse 30s tick, only while there's
    // an actual resumable session to show a deadline for. HONEST urgency: the
    // countdown is derived from the SAME server `deadlineAt` the live interview
    // enforces, never a fabricated number (principles/persuasion-psychology).
    useEffect(() => {
        if (phase !== "setup" || !inProgressSessionSwr.data) {
            return
        }
        const id = window.setInterval(() => setResumeCountdownTick((previous) => previous + 1), 30_000)
        return () => window.clearInterval(id)
    }, [phase, inProgressSessionSwr.data])

    // mirror the active phase into the URL (`?phase=interview`) so the learn shell + the
    // MockInterviewPage page shell can drop the course rails + centered padding for the LIVE
    // interview only (a full-bleed work surface); setup/grading/scorecard stay centered.
    // Guarded so it never loops: replaces only when the param differs from the current phase.
    useEffect(() => {
        const want = phase === "interview" ? "interview" : null
        if (searchParams.get("phase") === want) {
            return
        }
        const params = new URLSearchParams(searchParams.toString())
        if (want) {
            params.set("phase", want)
        } else {
            params.delete("phase")
        }
        const qs = params.toString()
        router.replace(qs ? `${pathname}?${qs}` : pathname, { scroll: false })
    }, [phase, pathname, searchParams, router])

    // mirror the setup tab into the URL (`?tab=history` / `?tab=stats`) — same technique
    // as the `phase` mirror above, so "History"/"Stats" are shareable/refresh-safe
    // links. "begin" (the default) is never written, keeping the common-case URL clean.
    useEffect(() => {
        const want = setupTab === "begin" ? null : setupTab
        if (searchParams.get("tab") === want) {
            return
        }
        const params = new URLSearchParams(searchParams.toString())
        if (want) {
            params.set("tab", want)
        } else {
            params.delete("tab")
        }
        const qs = params.toString()
        router.replace(qs ? `${pathname}?${qs}` : pathname, { scroll: false })
    }, [setupTab, pathname, searchParams, router])

    // nudge the candidate to install a matching TTS voice ONCE per interview, only
    // once the browser's voice list has actually loaded and confirms none matches the
    // current locale — the interviewer would otherwise read (e.g.) Vietnamese in an
    // English voice. Skipped entirely when TTS is off/unsupported, when a voice IS
    // present, or when the candidate previously dismissed it (persisted forever).
    useEffect(() => {
        if (phase !== "interview" || voiceNudgeShownRef.current) {
            return
        }
        if (!tts.supported || !tts.enabled || !tts.voicesLoaded || tts.hasLocaleVoice) {
            return
        }
        if (typeof window !== "undefined" && window.localStorage.getItem("starci.mockInterview.voiceNudgeDismissed") === "1") {
            voiceNudgeShownRef.current = true
            return
        }
        voiceNudgeShownRef.current = true
        setVoiceModalOpen(true)
    }, [phase, tts.supported, tts.enabled, tts.voicesLoaded, tts.hasLocaleVoice])

    // any close of the voice nudge (X / backdrop / dismiss / auto-close after a
    // successful re-check) persists "dismissed forever" so it never reopens.
    const closeVoiceModal = useCallback((open: boolean) => {
        setVoiceModalOpen(open)
        if (!open && typeof window !== "undefined") {
            window.localStorage.setItem("starci.mockInterview.voiceNudgeDismissed", "1")
        }
    }, [])

    // ask the interviewer for its next turn (opening line, a probe after an answer, a
    // phase-transition line for mode="design", or a fresh seed question for mode="qna")
    // and stream the reply into `turns` once it completes. Shared by
    // startSession/submitAnswer/advancePhase/submitQnaAnswer so there is exactly one
    // place that touches the single in-flight stream tracked by `useMockInterviewTurnStream`.
    const askNextTurn = useCallback(
        (params: {
            phase: MockInterviewPhaseKey
            latestAnswer: string
            history: Array<MockInterviewTurn>
            prompt: DrawnMockInterviewPrompt
            questionIndex: number
            currentSeed: string | null
            /**
             * Overrides the closure's `mode`/`isQna` for this ONE call — needed by the
             * resume-rehydrate effect, which calls `setMode(nextMode)` and immediately
             * asks the opening turn in the SAME synchronous pass: `setMode` doesn't take
             * effect until the next render, so without this override the ask would use
             * the STALE pre-resume `mode` (always "qna", the component's initial value)
             * even when resuming a "design" session.
             */
            modeOverride?: MockInterviewMode
        }) => {
            streamingRef.current = ""
            setIsAsking(true)
            setStreamingText("")
            // silence any previous spoken question before the next one streams in
            ttsRef.current.cancel()
            const effectiveMode = params.modeOverride ?? mode
            const effectiveIsQna = effectiveMode === "qna"
            // THIS question's own kind (mode="qna") — randomly assigned per-seed by
            // the server draw, read off the seed the ask is currently framed around.
            const askKind = effectiveIsQna ? params.prompt.seedTopics[params.questionIndex]?.kind : undefined
            turnStream.ask({
                sessionId: sessionId.current ?? "",
                courseId,
                promptId: params.prompt.id,
                promptTitle: params.prompt.title,
                phase: params.phase,
                history: params.history.map((turn) => ({ role: turn.role, content: turn.content })),
                latestAnswer: params.latestAnswer,
                model: selection.model,
                provider: selection.provider,
                level: currentLevel,
                mode: effectiveMode,
                kind: askKind,
                currentSeed: params.currentSeed,
                questionIndex: effectiveIsQna ? params.questionIndex : null,
                onDelta: (delta) => {
                    // accumulate in a ref (synchronous) so the onDone below always reads the
                    // full text, then mirror it into state for the live-streaming bubble
                    streamingRef.current += delta
                    setStreamingText(streamingRef.current)
                },
                onDone: (error) => {
                    setIsAsking(false)
                    setStreamingText(null)
                    // "session time limit" — the server rejected this ask because the
                    // 1-hour deadline already passed (catches the case where the
                    // client-side countdown tick was throttled/the tab was backgrounded);
                    // the dedicated timedOut effect takes it from here (auto-grade).
                    if (error === "SESSION_EXPIRED") {
                        setTimedOut(true)
                        return
                    }
                    const finalText = streamingRef.current.trim()
                    // append the completed interviewer turn only when the stream actually
                    // produced something — an aborted/errored stream leaves nothing behind
                    if (!error && finalText.length > 0) {
                        setTurns((previous) => [
                            ...previous,
                            {
                                role: "interviewer",
                                phase: params.phase,
                                content: finalText,
                                questionIndex: effectiveIsQna ? params.questionIndex : undefined,
                            },
                        ])
                        // the interviewer reads the finished question aloud (no-op if muted/unsupported)
                        ttsRef.current.speak(finalText)
                    }
                },
            })
        },
        [courseId, selection, currentLevel, mode, turnStream],
    )

    // reset the right-pane workspace (code buffer + which tool renders + open/closed)
    // for a topic change — a debug/review/optimize question ships GIVEN code → seed it
    // into the editable Code tool + surface it; a voice-only topic resets the code
    // buffer to the blank whiteboard default so the previous question's code never
    // lingers into — or is graded against — the next one. Shared by
    // `deliverStaticQuestion` (static-bank questions) AND `submitQnaAnswer`'s
    // AI-generated branch (`askNextTurn`), which previously left the workspace
    // untouched across a question change (2026-07-14 fix).
    const resetWorkspaceForTopic = useCallback((
        isDesignMode: boolean,
        topic: MockInterviewSeedTopic | undefined,
    ): void => {
        const openingGivenCode = resolveOpeningGivenCode(topic?.givenCodes ?? [])
        if (openingGivenCode) {
            setCodeState({ lang: resolveGivenCodeLang(openingGivenCode.lang), code: openingGivenCode.code })
            setWorkspaceTool("code")
        } else {
            setCodeState(MOCK_INTERVIEW_CODE_STATE_DEFAULT)
            setWorkspaceTool("whiteboard")
        }
        // this question either HAS a tool to submit from (open by default, no manual
        // step) or has NOTHING to submit there (the toggle is disabled — see the
        // header button — so there is no "candidate manually opened it" state to
        // preserve across questions anymore).
        setWorkspaceOpen(questionHasWorkspaceTool(isDesignMode, topic?.givenCodes))
    }, [])

    // deliver a PRE-AUTHORED interview-bank question with NO AI call — the
    // question is fully written in `.mount`, so the interviewer just reads it
    // (rendered as-is, incl. any folded diagram/code) and speaks it aloud (TTS).
    // Only grading needs AI; asking a static question does not.
    //
    // Does NOT call resetWorkspaceForTopic itself — both callers already reset the
    // workspace for this exact topic before invoking this function (submitQnaAnswer
    // resets once up front for whichever branch follows; the resume/rehydrate path
    // seeds it manually for the in-progress question). Calling it a third time here
    // was a harmless but redundant no-op (2026-07-14 cleanup).
    const deliverStaticQuestion = useCallback((index: number, prompt: DrawnMockInterviewPrompt) => {
        const topic = prompt.seedTopics[index]
        const questionText = topic?.title ?? ""
        if (questionText.length === 0) {
            return
        }
        const openingGivenCode = resolveOpeningGivenCode(topic?.givenCodes ?? [])
        ttsRef.current.cancel()
        setIsAsking(false)
        setStreamingText(null)
        setTurns((previous) => [
            ...previous,
            {
                role: "interviewer",
                phase: PHASES[0],
                content: questionText,
                questionIndex: index,
                artifactHint: openingGivenCode ? "code" : undefined,
            },
        ])
        ttsRef.current.speak(questionText)
    }, [])

    // ask the SERVER to draw a fresh prompt for the current tier and start a new run.
    // Re-drawing (rather than reusing the same prompt) is also how "Retry interview"
    // behaves — retrying asks the server for a fresh draw of the SAME mode/tier, never
    // the same prompt twice. The client never picks the prompt itself — it only asks
    // for one and stores the `sessionId` the server hands back, which
    // `gradeMockInterviewSession` later looks up server-side to trust the
    // stored prompt/level/mode instead of whatever the client echoes.
    //
    // Takes an explicit mode so the two setup entry points ("Start interview" →
    // qna, "Practice system design" → design) each start the RIGHT mode without
    // racing `setMode` — retry (no arg) reuses whichever mode the last run was in.
    const startSession = useCallback(async (nextMode: MockInterviewMode = mode) => {
        setStartError(null)
        setStartingMode(nextMode)
        setMode(nextMode)
        // "Auto" = random everything (all kinds, default question count) + counts
        // toward job-readiness. "Custom" sends the picked question count/kinds and
        // is EXCLUDED from job-readiness (kept a clean signal from random runs only).
        // mode="design" always counts (server forces it regardless of what's sent).
        const isConfigurable = nextMode === "qna" && configMode === "configurable"
        try {
            const response = await startSessionSwr.trigger({
                courseId,
                level: currentLevel,
                mode: nextMode,
                // multi-select language set (2026-07-17) — the server draws each code
                // question in a random member of this set. `lang` (first selected) is
                // sent alongside only to keep the deprecated single field populated (the
                // server stores it as the session row's representative `lang`); the server
                // ignores it whenever `langs` is present.
                lang: interviewLangs[0],
                langs: interviewLangs,
                questionCount: isConfigurable ? Number(questionCount) : undefined,
                kinds: isConfigurable && selectedKinds.length > 0 ? selectedKinds : undefined,
                countsToReadiness: !isConfigurable,
                name: sessionName.trim() || undefined,
            })
            const payload = response.data?.startMockInterviewSession
            if (!payload?.success || !payload.data) {
                setStartError(payload?.message ?? t("mockInterview.startFailed"))
                setStartingMode(null)
                return
            }
            const drawn: DrawnMockInterviewPrompt = {
                id: payload.data.promptId,
                title: payload.data.promptTitle,
                seedTopics: payload.data.seedTopics,
                source: payload.data.source,
            }
            sessionId.current = payload.data.sessionId
            setDeadlineAt(payload.data.deadlineAt)
            setTimedOut(false)
            timedOutGradedRef.current = false
            setSelectedPrompt(drawn)
            setTurns([])
            setPhaseIndex(0)
            setQuestionIndex(0)
            setGradeError(null)
            setGradeQuotaExceeded(false)
            diagramRef.current = { nodes: [], edges: [] }
            setCodeState(MOCK_INTERVIEW_CODE_STATE_DEFAULT)
            setAnswerDraft("")
            setWorkspaceTool("whiteboard")
            // design mode's whiteboard is always the tool; a qna question's own
            // given-code check (if any) runs right below via `deliverStaticQuestion`
            // and overrides this for question 0 when it applies.
            setWorkspaceOpen(nextMode === "design")
            // navigate to the dedicated, resumable `/interview/[sessionId]` route instead
            // of just flipping `phase` locally — that route's `MockInterviewSession`
            // instance rehydrates via `myInProgressMockInterviewSession` and (since a
            // freshly-drawn session has no synced turns yet) is the one that actually
            // asks the opening question, mirroring the block this replaced.
            //
            // CRITICAL: revalidate `myInProgressMockInterviewSession` BEFORE navigating.
            // The `/interview/[id]` route REMOUNTS this component, and its rehydrate effect
            // matches `data.sessionId === resumeSessionId(url)`. Without this, the remounted
            // effect reads the STALE SWR cache from the setup screen (the PREVIOUS in-progress
            // session, or null) → id mismatch → false "session expired" + fallback to setup.
            // Refetching now writes the just-created session into the shared SWR cache so the
            // remounted effect sees the right one. (SWR dedupes by key across the remount.)
            try {
                await inProgressSessionSwr.mutate()
            } catch {
                // best-effort — a failed revalidate just risks the mismatch above; navigation
                // still proceeds and the effect's own fetch may recover it on the next tick.
            }
            router.push(
                pathConfig()
                    .locale(locale)
                    .course(courseDisplayId)
                    .learn()
                    .mockInterview()
                    .interview(payload.data.sessionId)
                    .build(),
            )
        } catch {
            setStartError(t("mockInterview.startFailed"))
            setStartingMode(null)
        }
        // note: on SUCCESS we intentionally do NOT reset `startingMode` — the router.push
        // above navigates to `/interview/[id]`, unmounting this setup instance, so the
        // spinner naturally disappears with it (resetting here would flash the icon back
        // for a frame before the route swaps).
    }, [courseId, courseDisplayId, currentLevel, mode, configMode, interviewLangs, questionCount, selectedKinds, sessionName, startSessionSwr, inProgressSessionSwr, router, locale, t])

    // resume, on mount, when reached via the dedicated `/interview/[sessionId]` route —
    // waits for `inProgressSessionSwr` to settle, then either rehydrates straight into
    // the interview phase (skipping setup entirely) or falls back to setup with an
    // inline error. Runs at most ONCE per mounted instance (`resumeAttemptedRef`), same
    // shape as the block `startSession` used to run locally before it started
    // navigating here instead — a freshly-drawn session (no synced turns yet, since sync
    // only fires after a turn completes) is exactly when this is the one asking the
    // opening question; a GENUINE resume (turns already synced) just continues the
    // thread as-is.
    useEffect(() => {
        // `authCheckSwr.isLoading` covers the hard-refresh window where `authenticated` is
        // still false → `inProgressSessionSwr`'s query key is null → its `isLoading` reads
        // `false` (a disabled query looks "settled") even though the real fetch hasn't had
        // a chance to run yet.
        if (!resumeSessionId || resumeAttemptedRef.current || authCheckSwr.isLoading || inProgressSessionSwr.isLoading) {
            return
        }
        resumeAttemptedRef.current = true
        const data = inProgressSessionSwr.data
        if (!data || data.sessionId !== resumeSessionId) {
            // no longer `in_progress` — the session might still be valid, just
            // GRADED already (finished normally, or auto-graded on the 1-hour
            // timeout). Redirect to the dedicated result URL instead of fetching
            // the attempt here and rendering the scorecard inline: the result
            // route owns that fetch + the not-found fallback now (single source
            // of "is this really graded, or truly gone", 2026-07-13 — mirrors
            // `flashcards().quiz(sessionId).result()`'s own fix for this class of
            // bug, see `pathConfig`'s `.result()` doc).
            router.replace(
                pathConfig()
                    .locale(locale)
                    .course(courseDisplayId)
                    .learn()
                    .mockInterview()
                    .interview(resumeSessionId)
                    .result()
                    .build(),
            )
            return
        }
        const nextMode: MockInterviewMode = data.mode === "design" ? "design" : "qna"
        const nextTier = (data.level && LEVEL_TO_TIER[data.level]) || "trung"
        const seedTopics: Array<MockInterviewSeedTopic> = (data.seedQuestions ?? []).map((question) => ({
            cardId: question.cardId,
            kind: question.kind,
            title: question.title,
            givenCodes: question.givenCodes ?? [],
        }))
        const drawn: DrawnMockInterviewPrompt = {
            id: data.promptId,
            title: data.promptTitle,
            seedTopics,
            source: data.source,
        }
        const rehydratedTurns: Array<MockInterviewTurn> = (data.turns ?? []).map((turn) => ({
            role: turn.role as MockInterviewTurn["role"],
            phase: turn.phase as MockInterviewTurn["phase"],
            content: turn.content,
            questionIndex: turn.questionIndex,
            artifactHint: turn.artifactHint === "code" ? "code" : undefined,
        }))
        sessionId.current = resumeSessionId
        setDeadlineAt(data.deadlineAt)
        setTimedOut(false)
        timedOutGradedRef.current = false
        setMode(nextMode)
        setTier(nextTier)
        setSelectedPrompt(drawn)
        setTurns(rehydratedTurns)
        setQuestionIndex(data.questionIndex)
        setPhaseIndex(data.phaseIndex)
        setGradeError(null)
        setGradeQuotaExceeded(false)
        setStartError(null)
        diagramRef.current = { nodes: [], edges: [] }
        setCodeState(MOCK_INTERVIEW_CODE_STATE_DEFAULT)
        setAnswerDraft("")
        setWorkspaceTool("whiteboard")
        // re-seed the Code workspace for a debug/review/optimize question the
        // learner was ALREADY on when they left — `deliverStaticQuestion` below
        // only fires for a brand-new question (turns.length === 0), so a resume
        // mid-question would otherwise leave the given code out of the editor
        // even though the question text still asks to read/fix it.
        const currentTopic = nextMode === "qna" && isStaticBankPrompt(drawn) ? drawn.seedTopics[data.questionIndex] : undefined
        const currentGivenCode = resolveOpeningGivenCode(currentTopic?.givenCodes ?? [])
        if (currentGivenCode) {
            setCodeState({ lang: resolveGivenCodeLang(currentGivenCode.lang), code: currentGivenCode.code })
            setWorkspaceTool("code")
        }
        setWorkspaceOpen(questionHasWorkspaceTool(nextMode === "design", currentTopic?.givenCodes))
        setPhase("interview")
        if (rehydratedTurns.length === 0) {
            if (nextMode === "qna" && isStaticBankPrompt(drawn)) {
                deliverStaticQuestion(0, drawn)
            } else {
                askNextTurn({
                    phase: PHASES[0],
                    latestAnswer: "",
                    history: [],
                    prompt: drawn,
                    questionIndex: 0,
                    currentSeed: drawn.seedTopics[0]?.title ?? null,
                    modeOverride: nextMode,
                })
            }
        }
    }, [resumeSessionId, courseId, authCheckSwr.isLoading, inProgressSessionSwr.isLoading, inProgressSessionSwr.data, askNextTurn, deliverStaticQuestion, t, router, locale, courseDisplayId])

    // best-effort, fire-and-forget persistence of the transcript-so-far — fires whenever
    // the turn list (or the current question/phase pointer) changes while live, so it
    // covers every append site (interviewer turns from `askNextTurn`/`deliverStaticQuestion`,
    // candidate turns from `submitAnswer`/`submitQnaAnswer`) without sprinkling a trigger
    // call at each one. Never awaited by the caller; still routed through `runGraphQL`
    // (toast on failure, no success toast) rather than a silent catch (instructor 2026-07-11:
    // "FE shouldn't swallow errors, use runGraphQL") — a failed sync only degrades resumability
    // (`myInProgressMockInterviewSession`), it never blocks the live interview, but the
    // candidate should still see it.
    const syncTurnsTrigger = syncTurnsSwr.trigger
    useEffect(() => {
        if (phase !== "interview" || !sessionId.current || turns.length === 0) {
            return
        }
        const turnsForSync: Array<SyncMockInterviewTurnInput> = turns.map((turn) => ({
            role: turn.role,
            phase: turn.phase,
            content: turn.content,
            questionIndex: turn.questionIndex,
            artifactHint: turn.artifactHint,
        }))
        const syncingSessionId = sessionId.current
        void runGraphQL(
            async () => {
                const result = await syncTurnsTrigger({
                    sessionId: syncingSessionId,
                    turns: turnsForSync,
                    questionIndex,
                    phaseIndex,
                })
                return (
                    result.data?.syncMockInterviewSessionTurns ?? {
                        success: false,
                        message: t("mockInterview.syncError"),
                    }
                )
            },
            { showSuccessToast: false },
        )
        // `syncTurnsTrigger` (not the whole `syncTurnsSwr` object) is the dep — `useSWRMutation`
        // returns a freshly-constructed wrapper object on every render (only `trigger`/`reset`
        // are individually memoized), so depending on the object itself re-fires this effect on
        // every unrelated re-render during the live interview (streaming deltas, the once-a-second
        // elapsed timer) — spamming the sync mutation far more than "the transcript changed".
    }, [phase, turns, questionIndex, phaseIndex, syncTurnsTrigger, runGraphQL, t])

    // mode="design" only (Round 5) — record the current spoken answer as a candidate
    // turn, then ask the interviewer to probe/follow-up on it within the SAME phase,
    // then clear the mic buffer. A real system-design interview is a multi-turn
    // Socratic back-and-forth per phase, so this stays as-is. mode="qna" uses
    // `submitQnaAnswer` instead (one answer → straight to the next question).
    const submitAnswer = useCallback(() => {
        const answer = transcript.trim()
        if (answer.length === 0 || isAsking || !selectedPrompt) {
            return
        }
        if (listening) {
            stop()
        }
        const nextTurns: Array<MockInterviewTurn> = [
            ...turns,
            {
                role: "candidate",
                phase: currentPhase,
                content: answer,
                questionIndex: isQna ? questionIndex : undefined,
            },
        ]
        setTurns(nextTurns)
        reset()
        askNextTurn({
            phase: currentPhase,
            latestAnswer: answer,
            history: nextTurns,
            prompt: selectedPrompt,
            questionIndex,
            currentSeed,
        })
    }, [transcript, listening, stop, reset, currentPhase, turns, isAsking, selectedPrompt, questionIndex, currentSeed, isQna, askNextTurn])

    // mode="design" only — advance to the next of the 5 canonical phases, unchanged.
    const advancePhase = useCallback(() => {
        if (isAsking || !selectedPrompt) {
            return
        }
        setPhaseIndex((previous) => {
            const next = Math.min(previous + 1, PHASES.length - 1)
            if (next !== previous) {
                // let the interviewer proactively introduce the new phase (no fresh answer yet)
                askNextTurn({
                    phase: PHASES[next],
                    latestAnswer: "",
                    history: turns,
                    prompt: selectedPrompt,
                    questionIndex: 0,
                    currentSeed: null,
                })
            }
            return next
        })
    }, [isAsking, selectedPrompt, askNextTurn, turns])

    const finishAndGrade = useCallback(async (turnsOverride?: Array<MockInterviewTurn>) => {
        if (!selectedPrompt || isAsking) {
            return
        }
        // `turnsOverride` lets `submitQnaAnswer` grade the LAST question's answer
        // immediately — `setTurns` is async, so reading the `turns` state right after
        // calling it would miss the answer that was just recorded.
        const turnsToGrade = turnsOverride ?? turns
        setPhase("grading")
        setGradeError(null)
        setGradeQuotaExceeded(false)
        // fold each non-empty workspace artifact in as a labeled synthetic candidate
        // turn — kept FE-only (no new BE field) by reusing the existing transcript shape.
        // Every turn (recorded + synthetic) carries its `questionIndex` for Q&A kinds so
        // the server can group them into per-question `phaseScores`; omitted for design.
        const turnsForGrading: Array<MockInterviewTurnInput> = turnsToGrade.map((turn) => ({
            role: turn.role,
            phase: turn.phase,
            content: turn.content,
            questionIndex: turn.questionIndex,
        }))
        const syntheticQuestionIndex = isQna ? questionIndex : undefined
        const diagramText = serializeMockInterviewDiagram(diagramRef.current.nodes, diagramRef.current.edges)
        if (diagramText) {
            turnsForGrading.push({
                role: "candidate",
                phase: currentPhase,
                content: `[Whiteboard]\n${diagramText}`,
                questionIndex: syntheticQuestionIndex,
            })
        }
        // qna captures each question's code as its own per-question turn in
        // submitQnaAnswer (tagged with that question's index), so folding the shared
        // buffer again here would double-count it against the LAST question. Design
        // mode is a single "question" → the once-at-grade fold is correct there.
        if (!isQna && codeState.code.trim().length > 0) {
            turnsForGrading.push({
                role: "candidate",
                phase: currentPhase,
                content: `[Code lang=${codeState.lang}]\n${codeState.code}`,
                questionIndex: syntheticQuestionIndex,
            })
        }
        try {
            const response = await gradeSwr.trigger({
                courseId,
                promptId: selectedPrompt.id,
                promptTitle: selectedPrompt.title,
                level: currentLevel,
                turns: turnsForGrading,
                sessionId: sessionId.current ?? crypto.randomUUID(),
                selectedModel: selection.model ?? undefined,
                selectedModelProvider: selection.provider ?? undefined,
            })
            const payload = response.data?.gradeMockInterviewSession
            // typed backend failure (quota, substance gate, validation …) — surface the
            // message and stay in the interview so nothing recorded so far is lost
            if (!payload?.success || !payload.data) {
                // the mutation response has no typed error CODE to distinguish "quota
                // exhausted" from other failures — re-check the credit pool right after
                // the failure so the upsell card is based on the FRESH quota state, not
                // string-matching the BE's error message
                const freshQuota = await aiQuotaSwr.mutate()
                const overQuotaNow = Boolean(
                    freshQuota
                    && (freshQuota.credit.remaining5h < 1 || freshQuota.credit.remainingWeek < 1),
                )
                setGradeQuotaExceeded(overQuotaNow)
                setGradeError(payload?.message ?? t("mockInterview.gradingFailed"))
                setPhase("interview")
                return
            }
            // Navigate to the dedicated result route instead of computing/rendering
            // the scorecard inline here — `MockInterviewResult` re-fetches the just-
            // graded attempt fresh by session id, so "done" is answered by the URL,
            // not a local `phase` transition that would leave the URL stranded on
            // `/interview/[id]` (2026-07-13, mirrors flashcard quiz's own
            // `.result()` redirect — see `pathConfig`'s doc for root cause).
            router.replace(
                pathConfig()
                    .locale(locale)
                    .course(courseDisplayId)
                    .learn()
                    .mockInterview()
                    .interview(sessionId.current as string)
                    .result()
                    .build(),
            )
        } catch {
            // thrown (network/GraphQL) error — not a typed backend failure, so no fresh
            // quota re-check is meaningful here; treat as the generic failure
            setGradeQuotaExceeded(false)
            setGradeError(t("mockInterview.gradingFailed"))
            setPhase("interview")
        }
    }, [courseId, selectedPrompt, isAsking, currentLevel, turns, currentPhase, isQna, questionIndex, codeState, selection, gradeSwr, aiQuotaSwr, t, router, locale, courseDisplayId])

    // "session time limit" — react to `timedOut` (flipped by either the client
    // countdown tick or a server SESSION_EXPIRED ask rejection) by auto-grading
    // with whatever transcript exists so far — the candidate's answer in
    // progress (not yet submitted) is dropped, matching the "grade what's there,
    // drop the unfinished one" ruling (no grace period). Guarded to fire at most once.
    useEffect(() => {
        if (!timedOut || timedOutGradedRef.current || phase !== "interview") {
            return
        }
        timedOutGradedRef.current = true
        void finishAndGrade()
    }, [timedOut, phase, finishAndGrade])

    // mode="qna" only (Round 5) — "ask one question at a time": record the answer, then move STRAIGHT
    // to the next question (or straight to grading on the last one) — one combined
    // action instead of the old "submit answer" + separate "next question" buttons.
    // No same-question follow-up probe (that stays design-only, see `submitAnswer`).
    const submitQnaAnswer = useCallback(() => {
        const answer = answerDraft.trim()
        if (answer.length === 0 || isAsking || !selectedPrompt) {
            return
        }
        if (listening) {
            stop()
        }
        const nextTurns: Array<MockInterviewTurn> = [
            ...turns,
            { role: "candidate", phase: currentPhase, content: answer, questionIndex },
        ]
        // capture THIS question's edited code as its own candidate artifact turn,
        // tagged with THIS question's index, so a debug/review question's FIX is
        // graded against the right question (the shared code buffer is reset for the
        // next question's seed in deliverStaticQuestion). This is why finishAndGrade's
        // global code-fold is skipped for qna — code is captured here, per-question.
        if (codeState.code.trim().length > 0) {
            nextTurns.push({
                role: "candidate",
                phase: currentPhase,
                content: `[Code lang=${codeState.lang}]\n${codeState.code}`,
                questionIndex,
            })
        }
        setTurns(nextTurns)
        reset()
        setAnswerDraft("")
        if (isLastQuestion) {
            void finishAndGrade(nextTurns)
            return
        }
        const next = questionIndex + 1
        setQuestionIndex(next)
        // reset the right-pane workspace for the UPCOMING question before either
        // branch below — `deliverStaticQuestion` already resets it itself (via the
        // shared helper), but the AI-generated branch (`askNextTurn`) never touched
        // codeState/workspaceTool/workspaceOpen on a question change, so a debug
        // question's leftover code (or open pane) could linger into the next plain
        // theory/reasoning/scenario question. mode="qna" only → isDesignMode=false.
        resetWorkspaceForTopic(false, selectedPrompt.seedTopics[next])
        // static bank → read the next authored question (no AI); flashcard → AI-frame
        if (isStaticBankPrompt(selectedPrompt)) {
            deliverStaticQuestion(next, selectedPrompt)
        } else {
            askNextTurn({
                phase: currentPhase,
                latestAnswer: "",
                history: nextTurns,
                prompt: selectedPrompt,
                questionIndex: next,
                currentSeed: selectedPrompt.seedTopics[next]?.title ?? null,
            })
        }
    }, [answerDraft, isAsking, selectedPrompt, listening, stop, turns, currentPhase, questionIndex, reset, isLastQuestion, finishAndGrade, askNextTurn, deliverStaticQuestion, codeState, resetWorkspaceForTopic])

    // return to the mock-interview HOME route (the green room / setup). Since the live
    // interview + grading + scorecard now live on the dedicated `/interview/[sessionId]`
    // route, "back to setup" is a real NAVIGATION home — not a local `setPhase("setup")`,
    // which would leave the URL stranded on `/interview/[id]` (and re-trigger the resume
    // effect). The left-behind session stays `in_progress`, so home re-offers it via the
    // resume card.
    const goToMockInterviewHome = useCallback(() => {
        router.push(
            pathConfig()
                .locale(locale)
                .course(courseDisplayId)
                .learn()
                .mockInterview()
                .build(),
        )
    }, [router, locale, courseDisplayId])

    // open the leave-confirm modal (the actual leave runs from the modal's confirm — see
    // `performLeave`). Replaces the old blocking `window.confirm` alert.
    const leaveInterview = useCallback(() => setConfirmAction("leave"), [])

    // actually leave the interview mid-run (abandon, ungraded): hush the mic + any spoken
    // question, then navigate back to the green room home. Called only from the confirm modal.
    const performLeave = useCallback(() => {
        if (listening) {
            stop()
        }
        ttsRef.current.cancel()
        goToMockInterviewHome()
    }, [listening, stop, goToMockInterviewHome])

    // mirror the whiteboard's plain-object snapshot into a ref (read only at grade time)
    const handleDiagramChange = useCallback(
        (nodes: Array<MockInterviewDiagramNodeSnapshot>, edges: Array<MockInterviewDiagramEdgeSnapshot>) => {
            diagramRef.current = { nodes, edges }
        },
        [],
    )

    // ── the shared WORK-SURFACE HEADER BAND ────────────────────────────────
    // The full-bleed interview is a focused work surface, so it has NO PageHeader;
    // instead this one aligned top band IS its header — back-link ("Exit"), the
    // StarCi identity, the question/phase counter, the timer, and (Q&A) the tools
    // toggle, with a full-width progress meter as its bottom edge. One band spans
    // the whole surface so the two panes share an aligned top (fixes the old
    // ragged HUD-in-the-left-column look). Sticky under the navbar. Defined here
    // (not just above the `qna`/`design` returns) so `grading` can reuse the EXACT
    // same chrome as the just-finished interview instead of switching to a
    // headerless centered card (2026-07-12, mirrors the same correction made for
    // Flashcards Quiz/Review: "the point is don't drop black into red" — keep the active
    // phase's header through the brief loading hand-off, don't swap early).
    const renderWorkHeader = (opts: {
        counter: React.ReactNode
        total: number
        current: number
        rightSlot?: React.ReactNode
        onFinish?: () => void
        finishLabel?: React.ReactNode
    }) => {
        // "session time limit" — counts DOWN to the server deadline (never a
        // local clock start); turns warning-colored under 5 minutes left (real
        // urgency, backed by an actual server-enforced deadline).
        const timer = (
            <span
                className={cn(
                    remainingSeconds !== null && remainingSeconds <= TIME_LIMIT_WARNING_SECONDS && "text-warning-soft-foreground",
                )}
            >
                <StackH
                    as="span"
                    gap={2}
                    principle="icon-text"
                    align="center"
                    classNames={["shrink-0"]}
                    items={[
                        () => <ClockIcon className="size-4" aria-hidden focusable="false" />,
                        () => (
                            <Typography type="body-sm" weight="medium" className="tabular-nums">
                                {formatElapsed(remainingSeconds ?? 0)}
                            </Typography>
                        ),
                    ]}
                />
            </span>
        )
        return (
            <WorkSessionHeader
                backLabel={t("mockInterview.leaveInterview")}
                onBack={leaveInterview}
                title={t("mockInterview.title")}
                counter={opts.counter}
                total={opts.total}
                current={opts.current}
                onFinish={opts.onFinish}
                finishLabel={opts.finishLabel}
                rightSlot={
                    <StackH
                        as="span"
                        gap={4}
                        principle="content-row"
                        align="center"
                        classNames={["shrink-0"]}
                        items={[
                            () => timer,
                            ...(opts.rightSlot
                                ? [
                                    () => <span className="hidden h-5 w-px shrink-0 bg-default @app-sm:block" aria-hidden />,
                                    () => opts.rightSlot,
                                ]
                                : []),
                        ]}
                    />
                }
            />
        )
    }

    // ── RESUMING (dedicated /interview/[sessionId] route) ─────────────────
    // `resumeSessionId` always lands here in the "interview" phase eventually — the
    // rehydrate effect above flips `phase` once `authCheckSwr`/`inProgressSessionSwr`
    // settle, guarded by `resumeAttemptedRef` so it fires once. Until then `phase` is
    // still its initial "setup" value; without this gate the setup green-room screen
    // would flash for a frame before jumping to the live interview surface. Show a
    // skeleton that mirrors the FINAL interview surface instead of the wrong screen.
    if (resumeSessionId && phase === "setup" && !resumeAttemptedRef.current) {
        return <MockInterviewSessionSkeleton className={className} />
    }

    // ── SETUP · GREEN ROOM ───────────────────────────────────────────────
    if (phase === "setup") {
        // rough time-ahead estimate for the pre-interview line (~3 min per question)
        const estCount = configMode === "configurable" ? Number(questionCount) : QNA_QUESTION_COUNT
        const estMinutes = estCount * 3

        // "Resume session" — surfaces the viewer's resumable in-progress session (if any)
        // for this course, one card above the interview history so leaving mid-run never
        // reads as lost work. `value`/`max` mirror however progress is measured for that
        // session's mode elsewhere in this file: qna counts questions (same as the
        // question counter), design counts phases (same as `renderWorkHeader`'s counter).
        const resumeSession = inProgressSessionSwr.data
        const resumeCard = resumeSession ? (() => {
            const resumeMode: MockInterviewMode = resumeSession.mode === "design" ? "design" : "qna"
            const resumeTier = (resumeSession.level && LEVEL_TO_TIER[resumeSession.level]) || "trung"
            const resumeMax = resumeMode === "design"
                ? PHASES.length
                : (resumeSession.seedQuestions.length || QNA_QUESTION_COUNT)
            const resumeValue = resumeMode === "design" ? resumeSession.phaseIndex : resumeSession.questionIndex
            const progressLabel = resumeMode === "design"
                ? `${resumeSession.phaseIndex + 1}/${PHASES.length} · ${t(`mockInterview.phase.${PHASES[resumeSession.phaseIndex]}`)}`
                : t("mockInterview.questionCounter", { index: resumeSession.questionIndex + 1, total: resumeMax })
            // "session time limit" — HONEST urgency: minutes left derived from the
            // SAME server `deadlineAt` the live interview enforces (never a made-up
            // countdown). The 24h resume-window query doesn't itself check the 1h
            // ask-loop deadline, so a session past its OWN hour can still surface
            // here — `resumeExpired` branches the copy so it never reads as "still
            // answerable" when it isn't. Clicking through still works (the interview
            // screen's own deadline tick immediately auto-grades with whatever was
            // synced) — this is deliberately NOT hidden, just labeled honestly.
            const resumeRemainingMinutes = Math.max(0, Math.ceil((new Date(resumeSession.deadlineAt).getTime() - Date.now()) / 60_000))
            const resumeExpired = resumeRemainingMinutes <= 0
            const resumeUrgent = resumeExpired || resumeRemainingMinutes <= 15
            // session name — resume's own timestamp is `updatedAt` (no `createdAt` in
            // this query shape), the closest available server timestamp for the
            // time-based fallback (see `sessionDisplayName`). The former prompt-title
            // title moves into the subtitle so the drawn prompt is still visible.
            const resumeName = sessionDisplayName(resumeSession.name, resumeSession.updatedAt, t, locale)
            return (
                <ContinueCard
                    title={resumeName}
                    subtitle={`${resumeSession.promptTitle} · ${resumeExpired
                        ? t("mockInterview.resumeSubtitleExpired", {
                            progress: progressLabel,
                            tier: t(`mockInterview.tier.${resumeTier}`),
                        })
                        : t("mockInterview.resumeSubtitleWithDeadline", {
                            progress: progressLabel,
                            tier: t(`mockInterview.tier.${resumeTier}`),
                            minutes: resumeRemainingMinutes,
                        })}`}
                    urgent={resumeUrgent}
                    variant="hero"
                    value={resumeValue}
                    max={resumeMax}
                    ctaLabel={resumeExpired ? t("mockInterview.resumeCtaExpired") : t("mockInterview.resumeCta")}
                    onPress={() => router.push(pathConfig()
                        .locale(locale)
                        .course(courseDisplayId)
                        .learn()
                        .mockInterview()
                        .interview(resumeSession.sessionId)
                        .build())}
                />
            )
        })() : null

        return (
            <Box className={cn("w-full", className)}>
                <StackV
                    gap={6}
                    principle="block-boundary"
                    items={[
                        () => (
                            <TabsCard
                                variant="primary"
                                leftTabs={{
                                    items: [
                                        { key: "begin", label: t("mockInterview.setupTabBegin") },
                                        { key: "history", label: t("mockInterview.setupTabHistory") },
                                        { key: "stats", label: t("mockInterview.setupTabStats") },
                                    ],
                                    selectedKey: setupTab,
                                    ariaLabel: t("mockInterview.setupTabBegin"),
                                    onSelectionChange: (key) => setSetupTab(key as "begin" | "history" | "stats"),
                                }}
                            />
                        ),
                        () => (
                            <div className={cn(setupTab !== "history" && "hidden")}>
                                <MockInterviewHistory courseId={courseId} courseDisplayId={courseDisplayId} onStartInterview={() => setSetupTab("begin")} />
                            </div>
                        ),
                        () => (
                            <div className={cn(setupTab !== "stats" && "hidden")}>
                                <MockInterviewStats courseId={courseId} courseDisplayId={courseDisplayId} onStartInterview={() => setSetupTab("begin")} />
                            </div>
                        ),
                        ...(setupTab === "begin"
                            ? [
                                ...(resumeCard ? [() => resumeCard] : []),
                                () => <MockInterviewTrackSnapshot courseId={courseId} />,
                                () => (
                                    <Card>
                                        <StackH
                                            gap={4}
                                            principle="identity"
                                            align="center"
                                            items={[
                                                () => <img src={persona.avatarSrc} alt="" className="size-12 shrink-0 rounded-full object-cover" aria-hidden />,
                                                () => (
                                                    <StackV gap={1} principle="name-handle" classNames={["min-w-0"]} items={[
                                                        () => <Typography type="body" weight="medium" className="truncate">{persona.name}</Typography>,
                                                        () => <Typography type="body-xs" color="muted" className="truncate">{persona.role}</Typography>,
                                                    ]} />
                                                ),
                                            ]}
                                        />
                                        <StackV
                                            gap={2}
                                            principle="title-subtitle"
                                            items={[
                                                () => <Typography type="h4" weight="semibold">{t("mockInterview.aboutToBeInterviewed")}</Typography>,
                                                () => (
                                                    <Typography type="body-sm" color="muted">
                                                        {t("mockInterview.roomSummary", { count: estCount, tier: t(`mockInterview.tier.${tier}`), minutes: estMinutes })}
                                                    </Typography>
                                                ),
                                            ]}
                                        />
                                        <Cluster
                                            gap={4}
                                            principle="chip-row"
                                            align="center"
                                            items={[
                                                () => (
                                                    <Button
                                                        variant={resumeSession ? "secondary" : "primary"}
                                                        size="lg"
                                                        isPending={startingMode === "qna"}
                                                        isDisabled={startingMode !== null && startingMode !== "qna"}
                                                        onPress={() => void startSession("qna")}
                                                    >
                                                        {({ isPending }) => (
                                                            <>
                                                                {isPending ? (
                                                                    <Spinner size="sm" color="current" />
                                                                ) : (
                                                                    <DoorOpenIcon className="size-5" aria-hidden focusable="false" />
                                                                )}
                                                                {t("mockInterview.enterRoom")}
                                                            </>
                                                        )}
                                                    </Button>
                                                ),
                                                ...(isDesignAvailable
                                                    ? [() => (
                                                        <Button
                                                            variant="secondary"
                                                            size="lg"
                                                            isPending={startingMode === "design"}
                                                            isDisabled={startingMode !== null && startingMode !== "design"}
                                                            onPress={() => void startSession("design")}
                                                        >
                                                            {({ isPending }) => (
                                                                <>
                                                                    {isPending ? (
                                                                        <Spinner size="sm" color="current" />
                                                                    ) : (
                                                                        <PenNibIcon className="size-5" aria-hidden focusable="false" />
                                                                    )}
                                                                    {t("mockInterview.designModeCta")}
                                                                </>
                                                            )}
                                                        </Button>
                                                    )]
                                                    : []),
                                            ]}
                                        />
                                    </Card>
                                ),
                                () => (
                                    <StackV
                                        gap={4}
                                        items={[
                                            () => (
                                                <button
                                                    type="button"
                                                    onClick={() => setConfigOpen((previous) => !previous)}
                                                    aria-expanded={configOpen}
                                                    className="group w-fit cursor-pointer text-muted hover:text-foreground"
                                                >
                                                    <StackH
                                                        gap={3}
                                                        items={[
                                                            () => (
                                                                <CaretDownIcon
                                                                    className={cn("size-4 transition-transform", configOpen && "rotate-180")}
                                                                    weight="bold"
                                                                    aria-hidden
                                                                    focusable="false"
                                                                />
                                                            ),
                                                            () => (
                                                                <span className="text-sm">
                                                                    {t("mockInterview.customizeSession")}
                                                                </span>
                                                            ),
                                                        ]}
                                                    />
                                                </button>
                                            ),
                                            () => (configOpen ? (
                                                <LabeledCard
                                                    label={t("mockInterview.configTitle")}
                                                    labelEnd={configMode === "auto" ? t("mockInterview.autoCaption") : undefined}
                                                >
                                                    <StackV
                                                        gap={4}
                                                        items={[
                                                            () => (
                                                                <StackV gap={3} items={[
                                                                    () => <Label>{t("common.sessionNameLabel")}</Label>,
                                                                    () => (
                                                                        <TextField variant="secondary" className="w-full">
                                                                            <Input
                                                                                className="w-full"
                                                                                placeholder={t("common.sessionNamePlaceholder")}
                                                                                name="sessionName"
                                                                                value={sessionName}
                                                                                onChange={(event) => setSessionName(event.target.value)}
                                                                                maxLength={80}
                                                                            />
                                                                        </TextField>
                                                                    ),
                                                                ]} />
                                                            ),
                                                            () => (
                                                                <StackV gap={3} items={[
                                                                    () => <Label>{t("mockInterview.modeToggleLabel")}</Label>,
                                                                    () => (
                                                                        <FlexWrapButtonRadio
                                                                            ariaLabel={t("mockInterview.modeToggleLabel")}
                                                                            value={configMode}
                                                                            onChange={setConfigMode}
                                                                            items={[
                                                                                { value: "auto" as const, content: t("mockInterview.modeAuto") },
                                                                                { value: "configurable" as const, content: t("mockInterview.modeConfigurable") },
                                                                            ]}
                                                                        />
                                                                    ),
                                                                ]} />
                                                            ),
                                                            ...(configMode === "configurable"
                                                                ? [() => (
                                                                    <Box principle="cell-pad" className="rounded-3xl border border-default bg-transparent p-3">
                                                                        <StackV
                                                                            gap={4}
                                                                            items={[
                                                                                () => (
                                                                                    <StackV gap={3} items={[
                                                                                        () => <Label>{t("mockInterview.questionCountLabel")}</Label>,
                                                                                        () => (
                                                                                            <FlexWrapButtonRadio
                                                                                                ariaLabel={t("mockInterview.questionCountLabel")}
                                                                                                value={questionCount}
                                                                                                onChange={setQuestionCount}
                                                                                                items={QUESTION_COUNT_OPTIONS.map((count) => ({
                                                                                                    value: count,
                                                                                                    content: t("mockInterview.questionCountOption", { count }),
                                                                                                }))}
                                                                                            />
                                                                                        ),
                                                                                    ]} />
                                                                                ),
                                                                                () => (
                                                                                    <StackV gap={3} items={[
                                                                                        () => <Label>{t("mockInterview.kindPickerLabel")}</Label>,
                                                                                        () => (
                                                                                            <FlexWrapButtonRadio<KindPickerValue>
                                                                                                multiple
                                                                                                ariaLabel={t("mockInterview.kindPickerLabel")}
                                                                                                values={selectedKinds.length === 0 ? [KIND_ALL] : selectedKinds}
                                                                                                onToggle={(value) => {
                                                                                                    if (value === KIND_ALL) {
                                                                                                        setSelectedKinds([])
                                                                                                        return
                                                                                                    }
                                                                                                    setSelectedKinds((previous) => (previous.includes(value)
                                                                                                        ? previous.filter((entry) => entry !== value)
                                                                                                        : [...previous, value]))
                                                                                                }}
                                                                                                items={[
                                                                                                    { value: KIND_ALL, content: t("mockInterview.kindAll") },
                                                                                                    ...KIND_OPTIONS.map((kind) => ({
                                                                                                        value: kind,
                                                                                                        content: t(`mockInterview.kind.${kind}`),
                                                                                                    })),
                                                                                                ]}
                                                                                            />
                                                                                        ),
                                                                                    ]} />
                                                                                ),
                                                                                () => (
                                                                                    <StackV gap={3} items={[
                                                                                        () => <Label>{t("mockInterview.answerModeLabel")}</Label>,
                                                                                        () => (
                                                                                            <FlexWrapButtonRadio
                                                                                                ariaLabel={t("mockInterview.answerModeLabel")}
                                                                                                value={answerMode}
                                                                                                onChange={setAnswerMode}
                                                                                                items={(["voice", "text", "both"] as const).map((value) => ({
                                                                                                    value,
                                                                                                    content: t(`mockInterview.answerMode.${value}`),
                                                                                                }))}
                                                                                            />
                                                                                        ),
                                                                                    ]} />
                                                                                ),
                                                                            ]}
                                                                        />
                                                                    </Box>
                                                                )]
                                                                : []),
                                                            () => (
                                                                <StackV gap={3} items={[
                                                                    () => <Label>{t("mockInterview.tierLabel")}</Label>,
                                                                    () => (
                                                                        <FlexWrapButtonRadio
                                                                            ariaLabel={t("mockInterview.tierLabel")}
                                                                            value={tier}
                                                                            onChange={setTier}
                                                                            items={TIERS.map((value) => ({
                                                                                value,
                                                                                content: t(`mockInterview.tier.${value}`),
                                                                            }))}
                                                                        />
                                                                    ),
                                                                    () => (
                                                                        <Typography type="body-xs" color="muted">
                                                                            {t("mockInterview.tierCaption")}
                                                                        </Typography>
                                                                    ),
                                                                ]} />
                                                            ),
                                                            () => (
                                                                <StackV gap={3} items={[
                                                                    () => <Label>{t("mockInterview.langLabel")}</Label>,
                                                                    () => (
                                                                        <FlexWrapButtonRadio
                                                                            multiple
                                                                            ariaLabel={t("mockInterview.langLabel")}
                                                                            values={interviewLangs}
                                                                            onToggle={toggleInterviewLang}
                                                                            items={DEFAULT_PROGRAMMING_LANGUAGES.map((value) => ({
                                                                                value,
                                                                                content: getLanguageLabel(value),
                                                                            }))}
                                                                        />
                                                                    ),
                                                                    () => (
                                                                        <Typography type="body-xs" color="muted">
                                                                            {t("mockInterview.langCaption")}
                                                                        </Typography>
                                                                    ),
                                                                ]} />
                                                            ),
                                                            () => (
                                                                <StackV gap={3} items={[
                                                                    () => <Label>{t("mockInterview.modelLabel")}</Label>,
                                                                    () => (
                                                                        <Cluster
                                                                            gap={4}
                                                                            principle="chip-row"
                                                                            align="center"
                                                                            items={[
                                                                                () => (
                                                                                    <GradeModelDropdown
                                                                                        isButton
                                                                                        models={gradeModels}
                                                                                        selection={selection}
                                                                                        canPremium={canPremium}
                                                                                        task={AiModelTask.Grading}
                                                                                        floor={AiModelCategory.Medium}
                                                                                        showAutoLane
                                                                                        onSelect={setSelection}
                                                                                        onUpgrade={() => router.push(`/${locale}/profile/settings/ai-subscription`)}
                                                                                    />
                                                                                ),
                                                                                () => (
                                                                                    <GradeCreditCaption
                                                                                        creditUsage={aiQuotaSwr.data}
                                                                                        hasPinnedModel={Boolean(selection.model)}
                                                                                        autoCreditCost={undefined}
                                                                                    />
                                                                                ),
                                                                            ]}
                                                                        />
                                                                    ),
                                                                ]} />
                                                            ),
                                                        ]}
                                                    />
                                                </LabeledCard>
                                            ) : null),
                                        ]}
                                    />
                                ),
                                ...(startError
                                    ? [() => <Callout status="danger" title={startError} onClose={() => setStartError(null)} />]
                                    : []),
                            ]
                            : []),
                    ]}
                />
            </Box>
        )
    }

    // ── GRADING (debrief opening) ────────────────────────────────────────
    if (phase === "grading") {
        return (
            // KEEP the interview's own `WorkSessionHeader` chrome through this
            // brief grading hand-off (2026-07-12) — single segment, fully "done".
            // Route stays `fullBleed` through this phase (see `learn/layout.tsx`
            // `isMockInterviewLive`), so this screen owns its own page padding.
            <div className={cn("flex w-full flex-col", className)}>
                {renderWorkHeader({ counter: t("mockInterview.grading"), total: 1, current: 1 })}
                <Box principle="page-pad" className="p-6">
                    <Box principle="center-measure" className="mx-auto w-full max-w-3xl">
                        <StackV
                            gap={6}
                            principle="block-boundary"
                            items={[
                                ...(timedOut
                                    ? [() => <Callout status="warning" title={t("mockInterview.sessionExpiredBanner")} />]
                                    : []),
                                () => (
                                    <Card className="w-full items-center">
                                        <img src={persona.avatarSrc} alt="" className="size-12 shrink-0 rounded-full object-cover" aria-hidden />
                                        <StackV
                                            gap={3}
                                            principle="sibling-stack"
                                            align="center"
                                            items={[
                                                () => (
                                                    <Typography type="body" weight="medium" align="center">
                                                        {t("mockInterview.interviewerGrading", { name: persona.name })}
                                                    </Typography>
                                                ),
                                                () => <Spinner size="sm" />,
                                                () => (
                                                    <Typography type="body-sm" color="muted" align="center">
                                                        {t("mockInterview.gradingPending")}
                                                    </Typography>
                                                ),
                                            ]}
                                        />
                                    </Card>
                                ),
                            ]}
                        />
                    </Box>
                </Box>
            </div>
        )
    }

    // shared confirm modal for the two irreversible interview actions (leave / finish
    // early) — a real HeroUI `Modal` (via `ModalShell`), NOT a `window.confirm` alert.
    // Rendered inside BOTH interview returns (qna + design) so either pane can trigger it.
    const confirmCopy = confirmAction === "leave"
        ? {
            title: t("mockInterview.leaveInterview"),
            body: t("mockInterview.leaveConfirm"),
            cta: t("mockInterview.leaveInterview"),
            // abandon-ungraded is the destructive read → danger CTA
            ctaVariant: "danger" as const,
            onConfirm: performLeave,
        }
        : confirmAction === "endEarly"
            ? {
                title: t("mockInterview.finishEarlyTitle"),
                body: t("mockInterview.finishEarlyConfirm"),
                cta: t("mockInterview.finishEarlyCta"),
                // finishing to grade is a forward action (not destructive) → primary CTA
                ctaVariant: "primary" as const,
                onConfirm: () => void finishAndGrade(),
            }
            : null
    const confirmModalNode = (
        <ModalShell
            isOpen={confirmAction !== null}
            onOpenChange={(open) => {
                if (!open) {
                    setConfirmAction(null)
                }
            }}
            title={confirmCopy?.title}
            size="sm"
            body={() => (
                <Typography type="body-sm" color="muted">{confirmCopy?.body}</Typography>
            )}
            footer={() => (
                <>
                    <Button variant="tertiary" onPress={() => setConfirmAction(null)}>
                        {t("mockInterview.stayInInterview")}
                    </Button>
                    <Button
                        variant={confirmCopy?.ctaVariant ?? "primary"}
                        onPress={() => {
                            const run = confirmCopy?.onConfirm
                            setConfirmAction(null)
                            run?.()
                        }}
                    >
                        {confirmCopy?.cta}
                    </Button>
                </>
            )}
        />
    )

    // ── INTERVIEW, mode="qna" (Round 5 — "ask one question at a time"): 1 question, 1 answer box ──
    // Full-bleed work surface: a shared header band on top, then the conversation as
    // a centered readable column — which expands into a first-class RIGHT workspace
    // pane on demand (a code/whiteboard question auto-opens it). No ragged in-column
    // HUD, no floating open/close links (the toggle lives in the header band).
    if (isQna) {
        // the grade-error callouts are shared with the design branch below
        const errorCallout = gradeQuotaExceeded ? (
            <Callout
                status="warning"
                title={t("mockInterview.quotaExceededTitle")}
                description={t("mockInterview.quotaExceededDescription")}
                actionLabel={t("mockInterview.quotaExceededCta")}
                onAction={() => router.push(pathConfig().locale(locale).profile().aiSubscription().build())}
            />
        ) : gradeError ? (
            <Callout status="danger" title={gradeError} />
        ) : null

        return (
            // h-[calc(100dvh-4rem)]: lock to the viewport below the 4rem navbar — same
            // convention as the other fullBleed surfaces (MindMap, PlaygroundSession).
            // Needed so the 2-pane grid below can `flex-1` into the REMAINING height
            // (under the sticky WorkSessionHeader) instead of only being as tall as its
            // own content — otherwise the pane divider stops short of "full" (2026-07-13,
            // instructor: "that divider that stretches the full width").
            <div className={cn("flex h-[calc(100dvh-4rem)] w-full flex-col", className)}>
                <VoiceUnavailableModal
                    isOpen={voiceModalOpen}
                    onOpenChange={closeVoiceModal}
                    onRecheck={tts.recheckVoices}
                    hasLocaleVoice={tts.hasLocaleVoice}
                />
                {confirmModalNode}

                {renderWorkHeader({
                    counter: currentKind
                        ? t("mockInterview.questionCounterWithKind", {
                            index: questionIndex + 1,
                            total: totalQuestions,
                            kind: t(`mockInterview.kind.${currentKind}`),
                        })
                        : t("mockInterview.questionCounter", { index: questionIndex + 1, total: totalQuestions }),
                    total: totalQuestions,
                    current: questionIndex,
                    // grade before the last question (rarely needed — auto-finishes on the
                    // last) — pinned to the header's right edge (WorkSessionHeader's own
                    // "Finish" affordance) instead of a floating link under the mic.
                    onFinish: () => setConfirmAction("endEarly"),
                    finishLabel: t("mockInterview.finishEarly"),
                })}

                {/* body — 2-pane split (stacked on mobile). The container itself carries NO
                    horizontal padding: the LEFT pane keeps its own reading padding, but the RIGHT
                    workspace pane BLEEDS to the viewport's right/top/bottom edges and is separated
                    only by a LEFT border — a docked IDE-style tool panel, NOT a floating card
                    (2026-07-17, instructor: "full height and flush against the right edge, with a
                    border on the left"). Each pane
                    scrolls on its own at `lg` ([[full-bleed-work-surface]] "each pane scrolls independently");
                    on mobile the grid stacks and the whole body scrolls. */}
                <div className="grid min-h-0 flex-1 overflow-y-auto @app-lg:overflow-hidden @app-lg:grid-cols-[minmax(0,1fr)_minmax(0,1fr)]">
                    {/* LEFT — conversation reading column; retuned to page-pad (p-6). */}
                    <Box principle="page-pad" className="flex min-w-0 flex-col @app-lg:overflow-y-auto p-6">
                        <StackV
                            gap={6}
                            principle="block-boundary"
                            justify="center"
                            classNames={["min-w-0"]}
                            items={[
                                ...(errorCallout ? [() => errorCallout] : []),
                                () => (
                                    <InterviewerPresence
                                        persona={persona}
                                        speaking={isAsking}
                                        speakingLabel={t("mockInterview.interviewerSpeaking")}
                                        ttsSupported={tts.supported}
                                        ttsEnabled={tts.enabled}
                                        onToggleTts={() => tts.setEnabled(!tts.enabled)}
                                        muteLabel={t("mockInterview.muteInterviewer")}
                                        unmuteLabel={t("mockInterview.unmuteInterviewer")}
                                    >
                                        {isAsking ? (
                                            streamingText ? (
                                                <div className="text-sm font-medium text-foreground">
                                                    <MarkdownContent plain markdown={streamingText} />
                                                </div>
                                            ) : (
                                                <Spinner size="sm" />
                                            )
                                        ) : currentQuestionTurn ? (
                                            <div className="text-sm font-medium text-foreground">
                                                <MarkdownContent plain markdown={currentQuestionTurn.content} />
                                            </div>
                                        ) : (
                                            <Typography type="body-sm" color="muted">
                                                {t("mockInterview.interviewerPending")}
                                            </Typography>
                                        )}
                                    </InterviewerPresence>
                                ),
                                () => (
                                    <VoiceHero
                                        sttSupported={supported}
                                        listening={listening}
                                        interimTranscript={interimTranscript}
                                        value={answerDraft}
                                        onValueChange={setAnswerDraft}
                                        onToggleListen={() => (listening ? stop() : start())}
                                        answerMode={answerMode}
                                        labels={{
                                            pushToTalk: t("mockInterview.pushToTalk"),
                                            listening: t("mockInterview.listening"),
                                            typeInstead: t("mockInterview.typeInstead"),
                                            useVoice: t("mockInterview.useVoice"),
                                            placeholder: t("mockInterview.answerPlaceholder"),
                                        }}
                                    />
                                ),
                                () => (
                                    <Button
                                        variant="primary"
                                        size="lg"
                                        className="self-center"
                                        onPress={submitQnaAnswer}
                                        isDisabled={answerDraft.trim().length === 0 || isAsking}
                                    >
                                        {isLastQuestion ? t("mockInterview.answerAndFinish") : t("mockInterview.answerAndNext")}
                                        <ArrowRightIcon className="size-5" aria-hidden focusable="false" />
                                    </Button>
                                ),
                            ]}
                        />
                    </Box>

                    <Box principle="page-pad" className="flex min-h-[28rem] min-w-0 flex-col border-t border-default bg-surface p-6 @app-lg:min-h-0 @app-lg:border-t-0 @app-lg:border-l">
                        {workspaceOpen ? (
                            <MockInterviewWorkspace
                                className="min-h-0 flex-1"
                                tool={workspaceTool}
                                onDiagramChange={handleDiagramChange}
                                codeState={codeState}
                                onCodeStateChange={setCodeState}
                                givenCodeVariants={currentSeedTopic?.givenCodes ?? []}
                            />
                        ) : (
                            <div className="flex min-h-0 flex-1 items-center justify-center">
                                <EmptyState
                                    icon={PenNibIcon}
                                    title={t("mockInterview.workspace.emptyTitle")}
                                    description={t("mockInterview.workspace.emptyDescription")}
                                />
                            </div>
                        )}
                    </Box>
                </div>
            </div>
        )
    }

    // ── INTERVIEW, mode="design" (full-bleed 2-pane: conversation | tool workspace) ──
    // Same work-surface header band as Q&A; the 5-phase system-design flow is always
    // 2-pane (the whiteboard is used throughout), with the phase stepper as a status
    // list in the left pane.
    // `h-[calc(100dvh-4rem)]` + the grid's `flex-1 min-h-0 overflow-y-auto` mirror the
    // `qna` branch above (2026-07-17 — this branch never got the viewport-lock fix noted
    // in [[full-bleed-work-surface]]'s "NOT YET applied to the design branch"; now required so the
    // whiteboard's `h-full` below has a definite height to fill instead of collapsing).
    return (
        <div className={cn("flex h-[calc(100dvh-4rem)] w-full flex-col", className)}>
            <VoiceUnavailableModal
                isOpen={voiceModalOpen}
                onOpenChange={closeVoiceModal}
                onRecheck={tts.recheckVoices}
                hasLocaleVoice={tts.hasLocaleVoice}
            />
            {confirmModalNode}

            {renderWorkHeader({
                counter: (
                    <>
                        {`${phaseIndex + 1}/${PHASES.length} · `}
                        {t(`mockInterview.phase.${currentPhase}`)}
                    </>
                ),
                total: PHASES.length,
                current: phaseIndex,
            })}

            {/* body — 2-pane: conversation | docked workspace panel (same as qna: the workspace
                bleeds to the right/top/bottom edges, left border only — see the qna branch's note).
                Container carries no horizontal padding; the LEFT pane keeps its own. */}
            <div className="flex min-h-0 flex-1 flex-col overflow-y-auto @app-lg:grid @app-lg:grid-cols-[minmax(0,1fr)_minmax(0,1fr)] @app-lg:overflow-hidden">
                {/* LEFT — conversation + phase stepper + thread; retuned to page-pad (p-6). */}
                <Box principle="page-pad" className="flex min-w-0 flex-col @app-lg:overflow-y-auto p-6">
                    <StackV
                        gap={4}
                        classNames={["min-w-0"]}
                        items={[
                            () => (
                                <InterviewerPresence
                                    persona={persona}
                                    speaking={isAsking}
                                    speakingLabel={t("mockInterview.interviewerSpeaking")}
                                    ttsSupported={tts.supported}
                                    ttsEnabled={tts.enabled}
                                    onToggleTts={() => tts.setEnabled(!tts.enabled)}
                                    muteLabel={t("mockInterview.muteInterviewer")}
                                    unmuteLabel={t("mockInterview.unmuteInterviewer")}
                                />
                            ),
                            () => (
                                <ul data-principle="chip-row" className="flex flex-wrap gap-3">
                                    {PHASES.map((phaseKey, position) => {
                                        const done = position < phaseIndex
                                        const current = position === phaseIndex
                                        return (
                                            <li key={phaseKey} data-principle="control-pad" className="px-3 py-2">
                                                <StackH
                                                    gap={2}
                                                    principle="icon-text"
                                                    align="center"
                                                    items={[
                                                        () => (done ? (
                                                            <CheckCircleIcon className="size-5 shrink-0 text-success-soft-foreground" aria-hidden focusable="false" />
                                                        ) : (
                                                            <CircleIcon
                                                                className={cn("size-5 shrink-0", current ? "text-accent-soft-foreground" : "text-muted")}
                                                                aria-hidden
                                                                focusable="false"
                                                            />
                                                        )),
                                                        () => (
                                                            <Typography
                                                                type="body-sm"
                                                                className={cn(current ? "text-accent-soft-foreground" : done ? "text-foreground" : "text-muted")}
                                                                aria-current={current ? "step" : undefined}
                                                            >
                                                                {t(`mockInterview.phase.${phaseKey}`)}
                                                            </Typography>
                                                        ),
                                                    ]}
                                                />
                                            </li>
                                        )
                                    })}
                                </ul>
                            ),
                            () => (
                                <Box principle="card-padding" className="rounded-xl bg-default/40 p-4">
                                    <StackV
                                        gap={3}
                                        items={[
                                            () => (
                                                <Typography type="body-xs" weight="medium" color="muted">
                                                    {t("mockInterview.promptLabel")}
                                                </Typography>
                                            ),
                                            () => <Typography type="body" weight="medium">{selectedPrompt?.title}</Typography>,
                                        ]}
                                    />
                                </Box>
                            ),
                            ...(gradeQuotaExceeded
                                ? [() => (
                                    <Callout
                                        status="warning"
                                        title={t("mockInterview.quotaExceededTitle")}
                                        description={t("mockInterview.quotaExceededDescription")}
                                        actionLabel={t("mockInterview.quotaExceededCta")}
                                        onAction={() => router.push(pathConfig().locale(locale).profile().aiSubscription().build())}
                                    />
                                )]
                                : gradeError
                                    ? [() => <Callout status="danger" title={gradeError} />]
                                    : []),
                            () => (
                                <StackV
                                    gap={4}
                                    items={[
                                        () => (turns.length === 0 && !isAsking ? (
                                            <ChatBubble role="assistant">
                                                <Typography type="body-sm" color="muted">
                                                    {t("mockInterview.interviewerPending")}
                                                </Typography>
                                            </ChatBubble>
                                        ) : null),
                                        ...turns.map((turn, position) => () => (
                                            <ChatBubble key={position} role={turn.role === "candidate" ? "user" : "assistant"}>
                                                <div className="text-sm text-foreground">
                                                    <MarkdownContent plain markdown={turn.content} />
                                                </div>
                                            </ChatBubble>
                                        )),
                                        ...(isAsking
                                            ? [() => (
                                                <ChatBubble role="assistant">
                                                    {streamingText ? (
                                                        <div className="text-sm text-foreground">
                                                            <MarkdownContent plain markdown={streamingText} />
                                                        </div>
                                                    ) : (
                                                        <Spinner size="sm" />
                                                    )}
                                                </ChatBubble>
                                            )]
                                            : []),
                                    ]}
                                />
                            ),
                            () => (!supported ? (
                                <Box principle="card-padding" className="rounded-xl bg-default/40 p-4">
                                    <Typography type="body-sm" color="muted" align="center">
                                        {t("flashcard.interview.unsupported")}
                                    </Typography>
                                </Box>
                            ) : (
                                <StackV
                                    gap={4}
                                    items={[
                                        ...(transcript || interimTranscript
                                            ? [() => (
                                                <Box principle="card-padding" className="rounded-xl bg-default/40 p-4">
                                                    <Typography className="text-foreground">
                                                        {transcript} <span className="text-muted">{interimTranscript}</span>
                                                    </Typography>
                                                </Box>
                                            )]
                                            : []),
                                        () => (
                                            <Cluster
                                                gap={4}
                                                principle="chip-row"
                                                align="center"
                                                items={[
                                                    () => (
                                                        <Button
                                                            variant={listening ? "danger" : "secondary"}
                                                            onPress={() => (listening ? stop() : start())}
                                                        >
                                                            <MicrophoneIcon className="size-5" aria-hidden focusable="false" />
                                                            {listening ? t("flashcard.interview.stop") : t("flashcard.interview.record")}
                                                        </Button>
                                                    ),
                                                    () => (
                                                        <Button
                                                            variant="primary"
                                                            onPress={submitAnswer}
                                                            isDisabled={transcript.trim().length === 0 || listening || isAsking}
                                                        >
                                                            {t("mockInterview.sendAnswer")}
                                                        </Button>
                                                    ),
                                                    ...(listening
                                                        ? [() => (
                                                            <StackH
                                                                as="span"
                                                                gap={2}
                                                                principle="icon-text"
                                                                align="center"
                                                                items={[
                                                                    () => <span className="size-2 animate-pulse rounded-full bg-danger" />,
                                                                    () => (
                                                                        <Typography type="body-xs" className="text-danger-soft-foreground">
                                                                            {t("flashcard.interview.recording")}
                                                                        </Typography>
                                                                    ),
                                                                ]}
                                                            />
                                                        )]
                                                        : []),
                                                ]}
                                            />
                                        ),
                                    ]}
                                />
                            )),
                            () => (
                                <StackV
                                    gap={3}
                                    items={[
                                        () => (
                                            <Button
                                                variant="secondary"
                                                onPress={advancePhase}
                                                isDisabled={phaseIndex >= PHASES.length - 1 || isAsking}
                                            >
                                                {t("mockInterview.nextPhase")}
                                                <ArrowRightIcon className="size-4" aria-hidden focusable="false" />
                                            </Button>
                                        ),
                                        () => (
                                            <Button variant="primary" onPress={() => void finishAndGrade()} isDisabled={isAsking}>
                                                {t("mockInterview.finishAndGrade")}
                                            </Button>
                                        ),
                                    ]}
                                />
                            ),
                        ]}
                    />
                </Box>

                <Box principle="page-pad" className="flex min-h-[28rem] min-w-0 flex-col border-t border-default bg-surface p-6 @app-lg:min-h-0 @app-lg:border-t-0 @app-lg:border-l">
                    <MockInterviewWorkspace
                        className="min-h-0 flex-1"
                        tool={workspaceTool}
                        onDiagramChange={handleDiagramChange}
                        codeState={codeState}
                        onCodeStateChange={setCodeState}
                    />
                </Box>
            </div>
        </div>
    )
}

import React from "react"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { StackH, StackV } from "@/components/frames/Stack"
import type { WithClassNames } from "@/modules/types/base/class-name"

/**
 * Loading placeholder for the mock-interview green room's "You're about to be
 * interviewed" card — the only piece of {@link import("../index").MockInterviewPage}
 * visible before `courseId`/`courseDisplayId`/the enrollment check resolve.
 * Mirrors the real card 1:1: persona avatar + name/role, the title + "N questions ·
 * level X · ~Y minutes" meta line, and the primary CTA — so resolving never
 * collapses or jumps the surface.
 */
export const MockInterviewSetupSkeleton = ({ className }: WithClassNames<undefined> = {}) => {
    return (
        <div className={className}>
            <SurfaceCard
                padding={6}
                body={() => (
                    <StackV
                        gap={5}
                        principle="group-boundary"
                        explain="Section group spacing — not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
                        items={[
                            () => (
                                <StackH
                                    gap={3}
                                    principle="identity"
                                    explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                                    items={[
                                        () => <Skeleton.Avatar size="lg" />,
                                        () => (
                                            <StackV
                                                gap={2}
                                                principle="title-subtitle"
                                                explain="Title over supporting line — not label-field, because neither line is a form control label."
                                                classNames={["min-w-0"]}
                                                items={[
                                                    () => <Skeleton.Typography type="body" width="1/3" />,
                                                    () => <Skeleton.Typography type="body-xs" width="1/4" />,
                                                ]}
                                            />
                                        ),
                                    ]}
                                />
                            ),
                            () => (
                                <StackV
                                    gap={2}
                                    principle="title-subtitle"
                                    explain="Title over supporting line — not label-field, because neither line is a form control label."
                                    items={[
                                        () => <Skeleton.Typography type="h4" width="1/2" />,
                                        () => <Skeleton.Typography type="body-sm" width="2/3" />,
                                    ]}
                                />
                            ),
                            () => <Skeleton.Button width="w-48" />,
                        ]}
                    />
                )}
            />
        </div>
    )
}

"use client"

import React from "react"
import { Button, Typography } from "@heroui/react"
import { ArrowRightIcon, ChartLineUpIcon } from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { EmptyState } from "@/components/composites/feedback/EmptyState"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { SectionCard } from "@/components/blocks/cards/SectionCard"
import { RelatedContentList } from "@/components/blocks/learn/RelatedContentList"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"
import { VerdictHeroCard } from "@/components/blocks/stats/VerdictHeroCard"
import type { VerdictHeroBand } from "@/components/blocks/stats/VerdictHeroCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { StackH, StackV } from "@/components/frames/Stack"
import { FillAvailable } from "@/components/frames/FillAvailable"
import { useQueryMyMockInterviewStatsSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyMockInterviewStatsSwr"
import type { MockInterviewStatsBreakdownItem } from "@/modules/api/graphql/queries/types/my-mock-interview-stats"
import { ProgrammingLanguage } from "@/modules/types/enums/programming-language"

/** Props for {@link MockInterviewStats}. */
export interface MockInterviewStatsProps {
    /** Course whose aggregate mock-interview stats to show. */
    courseId: string
    /** Course display id, for the weakest-phase/kind CTA's deep link. */
    courseDisplayId: string
    /** Jumps the setup tab strip back to "Start" (empty-state action, and also the readiness hero's "practice more" CTA when not yet at {@link PASS_BAR}). */
    onStartInterview?: () => void
}

/** Every breakdown axis this surface folds a `MockInterviewStatsBreakdownItem` list by. */
type BreakdownAxis = "phase" | "kind" | "attribute" | "level" | "language"

/** Score bar color BY VALUE (not always accent) — mirrors `MockInterviewScorecard`'s own `scoreColorOf`. Used for the per-row breakdown meters and the trend bars (absolute 0-100 quality reads), NOT the readiness hero (that one is relative to {@link PASS_BAR} — see `readinessBandOf`). */
const scoreColorOf = (score: number, max: number): "success" | "warning" | "danger" => {
    const ratio = max > 0 ? score / max : 0
    return ratio < 0.5 ? "danger" : ratio < 0.75 ? "warning" : "success"
}

/** Every language {@link ProgrammingLanguage} covers — used to tell a real implementation-track language (translated) apart from a raw drawn-language string (fallback-capitalized), mirrors `MockInterviewWorkspace`'s own `KNOWN_PROGRAMMING_LANGS`. */
const KNOWN_PROGRAMMING_LANGS: ReadonlySet<string> = new Set(Object.values(ProgrammingLanguage))

/** No dedicated BE field yet for the interview "pass" line — a local const, same convention `MockInterviewScorecard`'s own `WEAK_PHASE_THRESHOLD` uses for a hardcoded interview-domain constant. */
const PASS_BAR = 70

/** Below this fraction of {@link PASS_BAR} the readiness hero reads as `"danger"` rather than `"warning"` — proportional (not a flat point gap) so the same margin scales with the bar itself. */
const READINESS_WARNING_RATIO = 0.8

/** Readiness band relative to {@link PASS_BAR} (NOT the absolute-quality {@link scoreColorOf} scale — a 64 there is "warning" purely because it's <75/100, whereas here it's "warning" because it's close-but-under the pass line). */
const readinessBandOf = (avgScore: number): VerdictHeroBand =>
    avgScore >= PASS_BAR ? "success" : avgScore >= PASS_BAR * READINESS_WARNING_RATIO ? "warning" : "danger"

/**
 * Mock-interview aggregate stats — the setup screen's "Stats" tab, condensed
 * per `stats-canonical-fold` (1 hero + 1 zone): a readiness hero (vs
 * {@link PASS_BAR}, "~N sessions to go" projected from the recent trend delta) +
 * the per-phase breakdown. Gated behind a minimum-attempts floor
 * (server-enforced via `insufficientData`) so a near-empty history never
 * reads as a broken dashboard of fabricated percentages.
 * @param props - {@link MockInterviewStatsProps}
 */
export const MockInterviewStats = ({ courseId, courseDisplayId, onStartInterview}: MockInterviewStatsProps) => {
    const t = useTranslations()

    const statsSwr = useQueryMyMockInterviewStatsSwr(courseId)
    const stats = statsSwr.data

    const axisLabel = (axis: BreakdownAxis, key: string): string => {
        switch (axis) {
        case "phase":
            return t(`mockInterview.phase.${key}`)
        case "kind":
            return t(`mockInterview.kind.${key}`)
        case "attribute":
            return t(`mockInterview.attribute.${key}`)
        case "level":
            // junior/middle/senior/staff — shared vocabulary, reuses the flashcard
            // module's own level labels rather than duplicating a 4th copy of them.
            return t(`flashcard.level.${key}`)
        case "language":
            // byLanguage keys are drawn from a question's ProgrammingLanguage (the
            // 4 implementation tracks); an unrecognized one still reads as a plain
            // label instead of a raw i18n key, mirrors MockInterviewWorkspace's own
            // displayLangLabel fallback.
            return KNOWN_PROGRAMMING_LANGS.has(key) ? t(`programmingLanguage.${key}`) : key.charAt(0).toUpperCase() + key.slice(1)
        }
    }

    const renderBreakdown = (
        items: ReadonlyArray<MockInterviewStatsBreakdownItem>,
        axis: BreakdownAxis,
        subtitleFor?: (item: MockInterviewStatsBreakdownItem) => React.ReactNode,
    ) => (
        <StackV
            gap={4}
            items={items.map((item) => () => (
                <StackH
                    gap={4}
                    principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                    classNames={["w-full"]}
                    items={[
                        () => (
                            <StackV
                                gap={1}
                                principle="name-handle"
                                explain="Display name with handle — not title-subtitle, because the second line is an identity handle rather than a subtitle."
                                classNames={["shrink-0"]}
                                items={[
                                    () => (
                                        <Typography type="body-sm" className="w-40">
                                            {axisLabel(axis, item.key)}
                                        </Typography>
                                    ),
                                    () => (
                                        <Typography type="body-xs" color="muted" className="w-40">
                                            {subtitleFor ? subtitleFor(item) : t("mockInterview.statsWeakRatioCaption", { weak: item.weakCount, total: item.attemptCount })}
                                        </Typography>
                                    ),
                                ]}
                            />
                        ),
                        () => (
                            <FillAvailable
                                at="base"
                                body={() => (
                                    <ProgressMeter
                                        value={Math.round(item.avgScore)}
                                        max={Math.round(item.avgMax) || 100}
                                        color={scoreColorOf(item.avgScore, item.avgMax)}
                                        showValue
                                    />
                                )}
                            />
                        ),
                    ]}
                />
            ))}
        />
    )

    return (
        <AsyncContent
            isLoading={statsSwr.isLoading && !stats}
            skeleton={(
                // MIRROR the loaded tree: ZONE 1 label + readiness verdict hero (value ·
                // verdict · trend sub · meter · CTA), ZONE 2 label + per-phase breakdown of
                // label/caption + ProgressMeter rows.
                <StackV
                    gap={6}
                    principle="block-boundary"
                    explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                    items={[
                        () => (
                            <StackV
                                gap={4}
                                items={[
                                    () => <Skeleton className="h-[14px] w-40 rounded" />,
                                    () => (
                                        <SectionCard>
                                            <StackH
                                                gap={3}
                                                principle="value-row"
                                                explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
                                                align="baseline"
                                                items={[
                                                    () => <Skeleton className="h-9 w-20 rounded" />,
                                                    () => <Skeleton className="h-[14px] w-8 rounded" />,
                                                ]}
                                            />
                                            <Skeleton.Typography type="body-sm" width="3/4" />
                                            <Skeleton.Typography type="body-xs" width="1/2" />
                                            <Skeleton.ProgressBar />
                                            <Skeleton.Button width="w-44" />
                                        </SectionCard>
                                    ),
                                ]}
                            />
                        ),
                        () => (
                            <StackV
                                gap={4}
                                items={[
                                    () => <Skeleton className="h-[14px] w-32 rounded" />,
                                    () => (
                                        <StackV
                                            gap={4}
                                            items={Array.from({ length: 4 }).map((_unused, index) => () => (
                                                <StackH
                                                    key={index}
                                                    gap={4}
                                                    principle="content-row"
                                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                    classNames={["w-full"]}
                                                    items={[
                                                        () => (
                                                            <StackV
                                                                gap={2}
                                                                principle="title-subtitle"
                                                                explain="Title over supporting line — not label-field, because neither line is a form control label."
                                                                classNames={["shrink-0"]}
                                                                items={[
                                                                    () => <Skeleton.Typography type="body-sm" width="2/3" />,
                                                                    () => <Skeleton.Typography type="body-xs" width="1/2" />,
                                                                ]}
                                                            />
                                                        ),
                                                        () => <Skeleton.ProgressBar className="flex-1" />,
                                                    ]}
                                                />
                                            ))}
                                        />
                                    ),
                                ]}
                            />
                        ),
                    ]}
                />
            )}
            error={!stats ? statsSwr.error : undefined}
            errorContent={{
                title: t("mockInterview.statsError"),
                onRetry: () => { void statsSwr.mutate() },
                retryLabel: t("mockInterview.promptsRetry"),
            }}
        >
            {!stats || stats.insufficientData ? (
                <EmptyState
                    icon={ChartLineUpIcon}
                    title={t("mockInterview.statsInsufficientTitle")}
                    description={t("mockInterview.statsInsufficientDescription")}
                    action={onStartInterview ? () => (
                        <Button size="sm" variant="secondary" onPress={onStartInterview}>
                            {t("mockInterview.begin")}
                        </Button>
                    ) : undefined}
                />
            ) : (
                <div>
                    <StackV
                        gap={6}
                        principle="block-boundary"
                        explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                        items={[
                            () => (
                                <LabeledCard
                                    label={t("mockInterview.statsReadinessLabel")}
                                    frameless
                                    description={() => (
                                        <Typography type="body-xs" color="muted">
                                            {t("mockInterview.statsModeSplitCaption", {
                                                qna: stats.modeSplit.qnaCount,
                                                design: stats.modeSplit.designCount,
                                            })}
                                        </Typography>
                                    )}
                                >
                                    {(() => {
                                        const avgScore = Math.round(
                                            stats.trend.reduce((sum, point) => sum + point.overallScore, 0) / Math.max(1, stats.trend.length),
                                        )
                                        const recentScores = stats.trend.slice(-3).map((point) => point.overallScore)
                                        const trendDelta = recentScores.length >= 2
                                            ? (recentScores[recentScores.length - 1] - recentScores[0]) / (recentScores.length - 1)
                                            : 0
                                        const sessionsNeeded = Math.max(1, trendDelta > 0 ? Math.ceil((PASS_BAR - avgScore) / trendDelta) : 1)
                                        const band = readinessBandOf(avgScore)
                                        return (
                                            <VerdictHeroCard
                                                value={avgScore}
                                                unit="/100"
                                                band={band}
                                                verdict={band === "success" ? t("mockInterview.statsVerdictPass") : t("mockInterview.statsReadinessAlmostSentence", { sessionsNeeded })}
                                                sub={t("mockInterview.statsReadinessTrendCaption", {
                                                    passBar: PASS_BAR,
                                                    count: recentScores.length,
                                                    scores: recentScores.join(" → "),
                                                })}
                                                meter={{ value: avgScore, max: 100, target: PASS_BAR }}
                                                action={band !== "success" && onStartInterview ? () => (
                                                    <Button variant="primary" size="sm" onPress={onStartInterview}>
                                                        {t("mockInterview.statsReadinessPracticeMoreCta", { count: sessionsNeeded })}
                                                        <ArrowRightIcon className="size-4" aria-hidden focusable="false" />
                                                    </Button>
                                                ) : undefined}
                                            />
                                        )
                                    })()}
                                </LabeledCard>
                            ),
                            ...(stats.byPhase.length > 0
                                ? [() => (
                                    <LabeledCard label={t("mockInterview.statsByPhaseTitle")}>
                                        {renderBreakdown(stats.byPhase, "phase")}
                                    </LabeledCard>
                                )]
                                : []),
                            () => (
                                <RelatedContentList
                                    courseId={courseId}
                                    courseDisplayId={courseDisplayId}
                                    query={[...stats.byPhase]
                                        .sort((a, b) => a.avgScore - b.avgScore)
                                        .slice(0, 3)
                                        .map((item) => axisLabel("phase", item.key))
                                        .join(" ")}
                                    label={t("mockInterview.statsStudyHeading")}
                                />
                            ),
                        ]}
                    />
                </div>
            )}
        </AsyncContent>
    )
}

"use client"

import React from "react"
import { Chip, Typography } from "@heroui/react"
import { useTranslations } from "next-intl"
import { StatPair } from "@/components/composites/stats/StatPair"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { useQueryMyJobReadinessSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyJobReadinessSwr"
import type { UserJobReadinessBand } from "@/modules/api/graphql/queries/types/user-job-readiness"

/** Props for {@link MockInterviewTrackSnapshot}. */
export interface MockInterviewTrackSnapshotProps {
    /** Course whose job-readiness track to show — filters the viewer's own `myJobReadiness.tracks`. */
    courseId: string
}

/** Maps a readiness band to the `Chip` color that reads correctly (mirrors {@link JobReadinessWidget}). */
const bandColorOf = (band: UserJobReadinessBand): "success" | "warning" | "default" =>
    band === "jobReady" ? "success" : band === "building" ? "warning" : "default"

/**
 * "Where you stand" snapshot for ONE course's job-readiness track — the interview
 * pillar's best score, plus the track's overall depth band. Shared between the
 * setup screen (before starting a new run) and the scorecard (right after grading)
 * so both read the exact same number (single source of render).
 *
 * Deliberately does NOT claim a rolling-5-average / delta-to-next-band number: the
 * `myJobReadiness` query only exposes `interviewScore` as a BEST-of score and `band`
 * as the track's blended composite (capstone + interview + cv), not an
 * interview-specific rolling window with a "one more run" delta. Showing a made-up
 * delta would misrepresent the real fairness mechanic (see `WF-09-interview-recent-window`)
 * — this renders only what the query actually returns.
 *
 * Self-hides when the viewer has never attempted this course's track at all (a
 * fresh learner with zero pillars shouldn't see a hollow snapshot before their
 * first attempt) — the setup screen and scorecard both gate rendering by null.
 *
 * @param props - {@link MockInterviewTrackSnapshotProps}
 */
export const MockInterviewTrackSnapshot = ({ courseId}: MockInterviewTrackSnapshotProps) => {
    const t = useTranslations()
    const readinessSwr = useQueryMyJobReadinessSwr()
    const data = readinessSwr.data
    const track = data?.tracks.find((candidate) => candidate.courseId === courseId)

    // 2026-07-12: this only mounts inside an already-rendered setup/scorecard
    // screen, so a bare `return null` while `readinessSwr` is still loading was
    // indistinguishable from "genuinely nothing to show" — it popped in above the
    // persona card / into the alert stack a beat after the screen had settled.
    if (readinessSwr.isLoading && !data) {
        return (
            <div className={"flex flex-wrap items-center gap-3 rounded-xl bg-default/40 p-4"}>
                <Skeleton.Typography type="h4" width="1/4" />
                <Skeleton className="h-6 w-20 rounded-full" />
            </div>
        )
    }

    // no track yet (never enrolled-scored anything) — nothing meaningful to show
    if (!track) {
        return null
    }
    // interview pillar never attempted — the snapshot has nothing interview-specific to say
    if (track.interviewScore === null) {
        return null
    }

    return (
        <div className={"flex flex-wrap items-center gap-3 rounded-xl bg-default/40 p-4"}>
            <StatPair value={String(track.interviewScore)} label={t("mockInterview.trackSnapshotLabel")} />
            <Chip size="md" variant="soft" color={bandColorOf(track.band)}>
                <Chip.Label>{t(`jobReadiness.band.${track.band}`)}</Chip.Label>
            </Chip>
            <Typography type="body-xs" color="muted">
                {t("mockInterview.trackSnapshotHint")}
            </Typography>
        </div>
    )
}

"use client"

import React from "react"
import {
    ListBox,
    Select,
    cn,
} from "@heroui/react"
import CodeMirror from "@uiw/react-codemirror"
import { java } from "@codemirror/lang-java"
import { javascript } from "@codemirror/lang-javascript"
import { StreamLanguage } from "@codemirror/language"
import type { Extension } from "@codemirror/state"
import { csharp } from "@codemirror/legacy-modes/mode/clike"
import { dockerFile } from "@codemirror/legacy-modes/mode/dockerfile"
import { go } from "@codemirror/legacy-modes/mode/go"
import { whiteLight } from "@uiw/codemirror-theme-white"
import { vscodeDark } from "@uiw/codemirror-theme-vscode"
import { useTheme } from "next-themes"
import { useTranslations } from "next-intl"
import { ProgrammingLanguage } from "@/modules/types/enums/programming-language"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { MockInterviewDiagram } from "../MockInterviewDiagram"
import type {
    MockInterviewDiagramEdgeSnapshot,
    MockInterviewDiagramNodeSnapshot,
} from "../MockInterviewDiagram"

/** Every language {@link ProgrammingLanguage} covers — used to tell an implementation-track
 *  language apart from an arbitrary content language (`dockerfile`, `yaml`, …) below. */
const KNOWN_PROGRAMMING_LANGS: ReadonlySet<string> = new Set(Object.values(ProgrammingLanguage))

/**
 * CodeMirror language extension for the workspace's given code — NOT restricted to
 * {@link ProgrammingLanguage} (a debug/review/optimize question can ship ANY content language
 * authored in `.mount`, e.g. `dockerfile`). TypeScript/Java use official `@codemirror/lang-*`
 * packages; Csharp/Go/Dockerfile have no first-party CM6 package, so they fall back to
 * `@codemirror/legacy-modes`' ported CM5 grammars (still solid token-level highlighting).
 * Anything else falls back to NO language extension (plain, still fully editable) rather than
 * silently mislabeling it as TypeScript (2026-07-17 fix — the prior default did exactly that).
 */
const languageExtensionFor = (lang: string): Array<Extension> => {
    switch (lang) {
    case ProgrammingLanguage.Java:
        return [java()]
    case ProgrammingLanguage.Csharp:
        return [StreamLanguage.define(csharp)]
    case ProgrammingLanguage.Go:
        return [StreamLanguage.define(go)]
    case "dockerfile":
        return [StreamLanguage.define(dockerFile)]
    case ProgrammingLanguage.TypeScript:
        return [javascript({ typescript: true })]
    default:
        return []
    }
}

/**
 * Which tool the {@link MockInterviewWorkspace} shows — driven ENTIRELY by the
 * current question, never by a candidate-facing switcher (2026-07-09 feedback:
 * a manual Whiteboard/Code/Notes tab bar read as "pointless" busywork). A
 * debug/review/optimize question (given code) renders straight to `"code"`; a
 * `mode="design"` phase renders straight to `"whiteboard"`.
 */
type MockInterviewTool = "whiteboard" | "code"

/** Controlled code-tab state (language + source), lifted so switching tabs never loses it. */
export interface MockInterviewCodeState {
    /**
     * Language the given code is authored in — a raw content-language string, NOT narrowed to
     * {@link ProgrammingLanguage} (that enum is the 4 CANDIDATE-CHOSEN implementation tracks;
     * a debug/review/optimize question's given code can be any authored language, e.g. `dockerfile`).
     */
    lang: string
    /** Code buffer. */
    code: string
}

/** Props for {@link MockInterviewWorkspace}. */
export interface MockInterviewWorkspaceProps extends WithClassNames<undefined> {
    /** Which tool renders — set by the caller from the current question, not by the candidate. */
    tool: MockInterviewTool
    /** Whiteboard change callback — mirrors {@link MockInterviewDiagram}'s `onChange` (read at grade time). */
    onDiagramChange: (
        nodes: Array<MockInterviewDiagramNodeSnapshot>,
        edges: Array<MockInterviewDiagramEdgeSnapshot>,
    ) => void
    /** Controlled code-tab state. */
    codeState: MockInterviewCodeState
    /** Fired with the next code-tab state. */
    onCodeStateChange: (next: MockInterviewCodeState) => void
    /**
     * Every authored language variant of the CURRENT question's given code —
     * switching the language `Select` looks up the matching variant here and
     * swaps `codeState.code` to it, client-side, no refetch (mirrors
     * `ChallengeView`'s own per-language step content). Empty when the
     * current question has no given code (`tool !== "code"`).
     */
    givenCodeVariants?: Array<{ lang: string, code: string }>
}

/** Default code-tab state — TypeScript, empty buffer. */
export const MOCK_INTERVIEW_CODE_STATE_DEFAULT: MockInterviewCodeState = {
    lang: ProgrammingLanguage.TypeScript,
    code: "",
}

/**
 * The mock interview's right-pane WORKSPACE — renders straight to the ONE tool
 * the current question needs (no candidate-facing switcher): the
 * {@link MockInterviewDiagram} xyflow canvas for a `mode="design"` phase, or a
 * CodeMirror code editor for a debug/review/optimize question's given code.
 *
 * Both stay MOUNTED (toggled with `hidden`, not conditionally rendered) so an
 * in-progress sketch survives a `qna` session moving between a code question
 * and a plain one.
 *
 * @param props - {@link MockInterviewWorkspaceProps}
 */
export const MockInterviewWorkspace = ({
    tool,
    onDiagramChange,
    codeState,
    onCodeStateChange,
    givenCodeVariants = [],
    className,
}: MockInterviewWorkspaceProps) => {
    const t = useTranslations()
    const { theme } = useTheme()

    // display label for a language — translated for the 4 real implementation tracks,
    // capitalized-as-authored for anything else (`dockerfile`, `yaml`, …) so an
    // uncommon content language reads as a normal label instead of a raw i18n key
    // (2026-07-17 fix — see `languageExtensionFor`'s doc for the same root cause).
    const displayLangLabel = (lang: string): string =>
        KNOWN_PROGRAMMING_LANGS.has(lang) ? t(`programmingLanguage.${lang}`) : lang.charAt(0).toUpperCase() + lang.slice(1)

    // only offer languages actually AUTHORED for this question (mirrors
    // ChallengeView only showing tabs for languages that exist).
    const availableLangs = givenCodeVariants.map((variant) => variant.lang)
    const languageItems = availableLangs.map((lang) => ({
        id: lang,
        title: displayLangLabel(lang),
    }))
    const selectedLanguageTitle = languageItems.find((item) => item.id === codeState.lang)?.title

    return (
        <div className={cn("flex h-full flex-col gap-3", className)}>
            <div className={cn("min-h-0 flex-1", tool !== "whiteboard" && "hidden")}>
                <MockInterviewDiagram className="h-full" onChange={onDiagramChange} />
            </div>

            {/* a REAL editor (CodeMirror) — a debug/review/optimize question seeds its given
                code here for the candidate to FIX in place (not a plain textarea): line numbers +
                syntax highlighting = editing, not narrating. Switched from Monaco (2026-07-17,
                instructor: "this code terminal looks kind of ugly" + pointed at react-codemirror's theme gallery) —
                CM6 ships a clean, tunable theme system (no VS-Code-IDE chrome to fight) and its
                content DOM disables the browser's native spellcheck by default, so the red
                squiggly-underline bug Monaco had doesn't exist here at all. NO own outer border /
                header fill anymore (2026-07-17): the parent pane is now ONE bordered surface with
                `p-6`, so the tool renders INSIDE it — just a plain language label/picker row above
                the editor (`gap-3`), the editor carrying its own themed background + rounded
                corners. */}
            <div className={cn("flex min-h-0 flex-1 flex-col gap-3", tool !== "code" && "hidden")}>
                <div className="flex items-center">
                    {languageItems.length > 1 ? (
                        <Select.Root<{ id: string }, "single">
                            aria-label={t("mockInterview.workspace.languageLabel")}
                            selectedKey={codeState.lang}
                            onSelectionChange={(key) => {
                                if (!key) {
                                    return
                                }
                                const nextLang = String(key)
                                // switching language swaps in that variant's OWN given code
                                // (client-side lookup, no refetch) — not just a re-label of
                                // the same buffer under a different syntax highlighter
                                const variant = givenCodeVariants.find((candidate) => candidate.lang === nextLang)
                                onCodeStateChange({ lang: nextLang, code: variant?.code ?? codeState.code })
                            }}
                        >
                            <Select.Trigger aria-label={t("mockInterview.workspace.languageLabel")} className="w-40">
                                <Select.Value>
                                    {() => <span>{selectedLanguageTitle}</span>}
                                </Select.Value>
                                <Select.Indicator />
                            </Select.Trigger>
                            <Select.Popover>
                                <ListBox.Root aria-label={t("mockInterview.workspace.languageLabel")} items={languageItems}>
                                    {(item) => (
                                        <ListBox.Item key={item.id} id={item.id} textValue={item.title}>
                                            <span>{item.title}</span>
                                        </ListBox.Item>
                                    )}
                                </ListBox.Root>
                            </Select.Popover>
                        </Select.Root>
                    ) : (
                        // exactly 1 authored variant — nothing to SWITCH between, so a picker
                        // would be pure chrome (and, before this fix, the very control that
                        // rendered an untranslated raw i18n key for a non-{ts,java,csharp,go}
                        // language like `dockerfile`). A plain label is honest about there
                        // being one fixed language for this question's given code.
                        <span className="text-sm font-medium text-muted">{displayLangLabel(codeState.lang)}</span>
                    )}
                </div>
                <div className="min-h-0 flex-1 overflow-hidden rounded-xl">
                    <CodeMirror
                        height="100%"
                        theme={theme === "dark" ? vscodeDark : whiteLight}
                        value={codeState.code}
                        extensions={languageExtensionFor(codeState.lang)}
                        onChange={(value) => onCodeStateChange({ ...codeState, code: value })}
                        style={{ height: "100%", fontSize: 14 }}
                    />
                </div>
            </div>
        </div>
    )
}

"use client"

import React, { useState } from "react"
import { TextArea, TextField, Typography, cn } from "@heroui/react"
import { MicrophoneIcon } from "@phosphor-icons/react"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"

/** How the candidate answers — mirrors the session's `answerMode` (FE-only). */
export type VoiceHeroAnswerMode = "voice" | "text" | "both"

/** Resolved (i18n'd) labels for {@link VoiceHero}. */
export interface VoiceHeroLabels {
    /** Prompt under the idle mic ("Press to answer"). */
    pushToTalk: string
    /** Prompt while listening ("Listening…"). */
    listening: string
    /** Link to switch from voice to typing ("type instead"). */
    typeInstead: string
    /** Link to switch from typing back to voice ("use voice"). */
    useVoice: string
    /** TextArea placeholder. */
    placeholder: string
}

/** Props for {@link VoiceHero}. */
export interface VoiceHeroProps {
    /** Whether speech-to-text is available (falls back to typing when false). */
    sttSupported: boolean
    /** Whether the mic is currently capturing. */
    listening: boolean
    /** In-flight (not-yet-final) transcribed words, shown muted after the draft. */
    interimTranscript: string
    /** The answer draft (voice + typing both land here — owned by the parent). */
    value: string
    /** Update the answer draft (typing). */
    onValueChange: (value: string) => void
    /** Start/stop the mic. */
    onToggleListen: () => void
    /** Which input affordances to show (from setup's "How to answer"). */
    answerMode: VoiceHeroAnswerMode
    /** Resolved labels. */
    labels: VoiceHeroLabels
}

/**
 * The VOICE-FIRST answer composer for the interview room — a big circular
 * push-to-talk mic as the hero (wired to the parent's speech-to-text), with the
 * live transcript building below it and a quiet "type instead" fallback to a text
 * box. Speaking is the signature act of an interview, so the mic leads; typing
 * is the secondary affordance (and the automatic one when the browser has no
 * speech recognition, or when setup picked text-only).
 *
 * @param props - {@link VoiceHeroProps}
 */
export const VoiceHero = ({
    sttSupported,
    listening,
    interimTranscript,
    value,
    onValueChange,
    onToggleListen,
    answerMode,
    labels}: VoiceHeroProps) => {
    // voice is the hero unless setup forced text-only or the browser can't do STT
    const textForced = answerMode === "text" || !sttSupported
    const canToggle = answerMode === "both" && sttSupported
    const [showText, setShowText] = useState(textForced)

    // typing box — used when forced (unsupported / text-only) or toggled to via "type instead"
    if (textForced || showText) {
        return (
            <div>
                <StackV
                    gap={3}
                    principle="sibling-stack"
                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                    classNames={["w-full"]}
                    items={[
                        () => (
                            <TextField variant="secondary" className="w-full">
                                <TextArea
                                    rows={4}
                                    value={value}
                                    onChange={(event) => onValueChange(event.target.value)}
                                    placeholder={labels.placeholder}
                                    className="resize-none"
                                    aria-label={labels.placeholder}
                                />
                            </TextField>
                        ),
                        ...(canToggle
                            ? [() => (
                                <button
                                    type="button"
                                    onClick={() => setShowText(false)}
                                    className="group w-fit cursor-pointer text-muted hover:text-foreground"
                                >
                                    {/* Icon+label at preserved 8px — icon-text is step 2 (4px). */}
                                    <StackH
                                        gap={3}
                                        items={[
                                            () => <MicrophoneIcon className="size-4" aria-hidden focusable="false" />,
                                            () => <span className="text-xs font-medium">{labels.useVoice}</span>,
                                        ]}
                                    />
                                </button>
                            )]
                            : []),
                    ]}
                />
            </div>
        )
    }

    // voice hero — big push-to-talk mic + live transcript
    return (
        <div className={""}>
            {/* Mic · prompt · transcript at preserved 12px — no vertical step-4 peer token. */}
            <StackV
                gap={4}
                classNames={["w-full"]}
                items={[
                    () => (
                        <div className="flex w-full flex-col items-center">
                            <button
                                type="button"
                                aria-label={listening ? labels.listening : labels.pushToTalk}
                                aria-pressed={listening}
                                onClick={onToggleListen}
                                className={cn(
                                    "flex size-20 cursor-pointer items-center justify-center rounded-full border-2 transition-colors",
                                    listening
                                        ? "animate-pulse border-danger bg-danger-soft text-danger-soft-foreground"
                                        : "border-accent bg-accent-soft text-accent-soft-foreground hover:bg-accent/15",
                                )}
                            >
                                <MicrophoneIcon className="size-9" aria-hidden focusable="false" />
                            </button>
                        </div>
                    ),
                    () => (
                        <Typography type="body-sm" color="muted" className={cn(listening && "text-danger-soft-foreground")} align="center">
                            {listening ? labels.listening : labels.pushToTalk}
                            {!listening && canToggle ? (
                                <>
                                    {" · "}
                                    <button
                                        type="button"
                                        onClick={() => setShowText(true)}
                                        className="cursor-pointer text-accent-soft-foreground hover:opacity-80"
                                    >
                                        {labels.typeInstead}
                                    </button>
                                </>
                            ) : null}
                        </Typography>
                    ),
                    ...(value || interimTranscript
                        ? [() => (
                            <Box principle="card-padding" className="w-full rounded-2xl bg-default/40 p-4"
                                explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
                                <Typography className="text-foreground">
                                    {value} <span className="text-muted">{interimTranscript}</span>
                                </Typography>
                            </Box>
                        )]
                        : []),
                ]}
            />
        </div>
    )
}

"use client"

import React from "react"
import { useTranslations } from "next-intl"
import { useSearchParams } from "next/navigation"
import { EnrollGate } from "@/components/blocks/learn/EnrollGate"
import { MockInterviewGatePreview } from "./MockInterviewGatePreview"
import { LearnBreadcrumb } from "@/components/blocks/learn/LearnBreadcrumb"
import { MockInterviewSession } from "./MockInterviewSession"
import { MockInterviewResult } from "./MockInterviewResult"
import { MockInterviewSetupSkeleton } from "./MockInterviewSetupSkeleton"
import { MockInterviewSessionSkeleton } from "./MockInterviewSessionSkeleton"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { Container } from "@/components/frames/Container"
import { StackV } from "@/components/frames/Stack"
import { useAppSelector } from "@/redux/hooks"
import { useQueryCourseEnrollmentStatusSwr } from "@/hooks/swr/api/graphql/queries/useQueryCourseEnrollmentStatusSwr"

/** Props for {@link MockInterviewPage}. */
export interface MockInterviewPageProps {
    /**
     * Present when reached via the dedicated `/mock-interview/interview/[sessionId]`
     * route — threaded straight through to {@link MockInterviewSession}, which
     * rehydrates that server-persisted session (24h TTL) instead of showing the
     * green room.
     */
    resumeSessionId?: string
    /** Present on the `/interview/[sessionId]/result` route — shows the graded debrief. */
    resultSessionId?: string
}

/**
 * Mock-interview feature shell: gates the surface behind enrollment (it spends AI
 * credits), and frames the {@link MockInterviewSession} state machine with the
 * standard learn header + breadcrumb.
 *
 * Two shapes, stated as two composed trees rather than one conditional class
 * string: the LIVE interview and the result debrief are full-bleed work surfaces
 * that own their own header, while the green room is a centred reading column.
 *
 * DEBT: `MockInterviewSetupSkeleton` / `MockInterviewSessionSkeleton` are still
 * separate descriptions of the two surfaces below. Folding them in means giving a
 * state machine its own resting state — a change worth reviewing on its own.
 *
 * @param props - {@link MockInterviewPageProps}
 */
export const MockInterviewPage = ({ resumeSessionId, resultSessionId }: MockInterviewPageProps) => {
    const t = useTranslations()
    const courseId = useAppSelector((state) => state.course.entity?.id)
    const courseDisplayId = useAppSelector((state) => state.course.displayId)
    // enrollment status is only ever FETCHED while authenticated (the query's key is
    // disabled otherwise — see `useQueryCourseEnrollmentStatusSwr`), so a guest's
    // `enrollmentSwr.data` stays `undefined` forever; without checking `authenticated`
    // below, `enrollmentResolved` would never flip and the surface would rest forever
    // instead of settling straight into the enroll gate.
    const authenticated = useAppSelector((state) => state.keycloak.authenticated)
    // enrolled-only (spends AI credits) — gate trial viewers behind an enroll CTA
    const enrollmentSwr = useQueryCourseEnrollmentStatusSwr()
    const isEnrolled = enrollmentSwr.data?.courseEnrollmentStatus?.data?.isEnrolled === true
    // during the LIVE interview phase the shell goes full-bleed (course rails dropped via
    // `?phase=interview`); drop the centred measure + page header here to match — the
    // interview is a focused work surface, not a centred reading column. A
    // `resumeSessionId` (the dedicated `/interview/[sessionId]` route) always lands
    // straight in the interview phase, so it counts as live immediately too — no
    // waiting on the query-param mirror to catch up after mount.
    const isLive = useSearchParams().get("phase") === "interview" || Boolean(resumeSessionId)
    // result: its own centred page (like the flashcard quiz result), NOT the full-bleed
    // live shell — but it owns its OWN PageHeader/BackLink internally
    // (`MockInterviewResult`), so it skips this shell's generic header the same way.
    const isResult = Boolean(resultSessionId)
    // resolved once the enrollment check has actually run (nullish, not `!enrollmentSwr.data` —
    // an `{isEnrolled: false}` payload is falsy but IS resolved) — gates the green room /
    // live surface behind its resting state instead of rendering nothing. Guests never
    // fire the query at all, so they resolve immediately (straight to the enroll gate).
    const isSkeleton = !(!authenticated || (enrollmentSwr.data !== undefined && !enrollmentSwr.isLoading))
    const ownsItsHeader = isLive || isResult

    const surface = () => {
        if (isSkeleton) {
            return ownsItsHeader ? <MockInterviewSessionSkeleton /> : <MockInterviewSetupSkeleton />
        }
        if (!isEnrolled) {
            return (
                <EnrollGate
                    title={t("mockInterview.gateTitle")}
                    description={t("mockInterview.gateDescription")}
                    preview={<MockInterviewGatePreview />}
                />
            )
        }
        if (!(courseId && courseDisplayId)) {
            return null
        }
        return resultSessionId ? (
            <MockInterviewResult
                key={courseId}
                sessionId={resultSessionId}
                courseId={courseId}
                courseDisplayId={courseDisplayId}
            />
        ) : (
            <MockInterviewSession
                key={courseId}
                courseId={courseId}
                courseDisplayId={courseDisplayId}
                resumeSessionId={resumeSessionId}
            />
        )
    }

    // full-bleed: the surface below owns its own header and measure
    if (ownsItsHeader) {
        return (
            <StackV
                identity={{ tier: "block", component: "MockInterviewPage" }}
                gap={1}
                body={surface}
            />
        )
    }

    return (
        <Container
            identity={{ tier: "block", component: "MockInterviewPage" }}
            size="md"
            padding={6}
            principle="page-pad"
            explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface."
            body={() => (
                <StackV
                    gap={7}
                    principle="layout-split"
                    explain="Major layout split — not block-boundary, because this separates primary page regions rather than adjacent blocks."
                    items={[
                        () => (
                            <PageHeader
                                breadcrumb={<LearnBreadcrumb current={t("mockInterview.title")} />}
                                title={t("mockInterview.title")}
                                description={t("mockInterview.subtitle")}
                            />
                        ),
                        surface,
                    ]}
                />
            )}
        />
    )
}

/** The 3-notch difficulty tier a run is conducted at (mirrors the session's `MockInterviewTier`). */
export type MockInterviewPersonaTier = "so" | "trung" | "cao"

/**
 * A presentational interviewer identity for the room — FE-only (the backend
 * returns no persona; the interviewer is a text/voice presence). StarCi is the
 * interviewer: a single fixed brand identity (name + face photo + a static role
 * label). The chosen tier still scales the QUESTIONS/rubric in the session, but
 * not this persona.
 */
export interface MockInterviewPersona {
    /** Display name — the brand itself is the interviewer (no fake human name). */
    name: string
    /** Static role label shown under the name (e.g. "Solution Architect"). */
    role: string
    /** One-letter monogram fallback for the avatar (used only if the photo fails to load). */
    monogram: string
    /** The interviewer's face — a real photo served from `public/`. */
    avatarSrc: string
}

/** The interviewer IS the brand — one recurring StarCi identity across the room. */
const PERSONA_NAME = "StarCi"

/** Static role label — kept in English (standard tech-industry title), same in both locales. */
const PERSONA_ROLE = "Solution Architect"

/** The brand face shown for the interviewer (public asset). */
const PERSONA_AVATAR = "/starci.jpg"

/**
 * Resolve the interviewer persona. StarCi is the interviewer — a single fixed
 * brand identity (name + face + role). The chosen tier still scales the
 * QUESTIONS/rubric (see the session), but the persona itself no longer changes
 * with it, so this takes no arguments.
 */
export const personaFor = (): MockInterviewPersona => ({
    name: PERSONA_NAME,
    role: PERSONA_ROLE,
    monogram: PERSONA_NAME.charAt(0),
    avatarSrc: PERSONA_AVATAR,
})

import type { MockInterviewAttemptItem } from "@/modules/api/graphql/queries/types/my-mock-interview-attempts"
import type { MockInterviewGradeResult } from "./types"

/** Narrows a loose wire-format verdict string to the local union, defaulting to "borderline". */
export const normalizeMockInterviewVerdict = (verdict: string): MockInterviewGradeResult["verdict"] =>
    (verdict === "pass" || verdict === "fail") ? verdict : "borderline"

/**
 * Maps a persisted mock-interview attempt (as returned by
 * `myMockInterviewAttempts`) into the same {@link MockInterviewGradeResult}
 * shape the live grading mutation returns — so
 * {@link import("./MockInterviewScorecard").MockInterviewScorecard} renders
 * both a just-finished session and a past attempt re-opened from history
 * through the SAME component (single source of render).
 *
 * @param attempt - one past attempt from `myMockInterviewAttempts`.
 * @returns the equivalent {@link MockInterviewGradeResult}.
 */
export const mapMockInterviewAttemptToGradeResult = (
    attempt: MockInterviewAttemptItem,
): MockInterviewGradeResult => ({
    overallScore: attempt.overallScore,
    verdict: normalizeMockInterviewVerdict(attempt.verdict),
    phaseScores: attempt.phaseScores.map((phaseScore) => ({
        phase: phaseScore.phase,
        score: phaseScore.score,
        max: phaseScore.max,
    })),
    attributeScores: attempt.attributeScores,
    strengths: attempt.strengths,
    gaps: attempt.gaps,
    followUpQuestion: attempt.followUpQuestion,
    matchedContentIds: attempt.matchedContentIds,
    // the history LIST query (myMockInterviewAttempts) does NOT select
    // questionReviews (heavy per-row), so a list-sourced attempt has it
    // undefined — default to [] so the scorecard's `.length`/.map never crash
    // (the by-session + fresh-finish paths carry the real array).
    questionReviews: attempt.questionReviews ?? [],
})

/**
 * BE contract types for the mock interview (Pha 1 scaffold).
 *
 * These describe the endpoints the FE is BUILT AGAINST but that the backend does
 * NOT expose yet — the feature is wired to them (typed) without faking any data
 * (see the TODO stubs in `index.tsx`). Implement the BE to this shape.
 */

/** The five canonical phases of a mock interview (interview-driven order). Only meaningful for `kind="design"`. */
export type MockInterviewPhaseKey =
    | "requirements"
    | "estimation"
    | "highLevel"
    | "deepDive"
    | "tradeoffs"

/**
 * The TOP-LEVEL flow a mock-interview session runs — "mode split" (2026-07-06).
 * `qna` draws N independent questions, each randomly assigned its own
 * {@link MockInterviewKind} at draw time (mixed within one session, "just like
 * a real interview"); `design` keeps the unchanged 5-phase capstone flow,
 * reached from its own setup entry point.
 */
export type MockInterviewMode = "qna" | "design"

/**
 * THIS QUESTION's cognitive frame — lives on each individual drawn seed
 * (`seedTopics[i].kind`), never on the whole session. Every question in a
 * `mode="qna"` session is randomly assigned one of these 3 kinds at draw
 * time, mixing kinds within a single run.
 */
export type MockInterviewKind = "theory" | "reasoning" | "scenario"

/** Where an interview prompt comes from — a curated course capstone, or an AI-generated classic. */
export type MockInterviewPromptSource = "capstone" | "classic"

/**
 * One selectable "system to design" in the setup prompt bank.
 * BE: a `mockInterviewPrompts(courseId)` query — curated from the course's 20 capstone
 * milestones (`milestone_tasks`, source `capstone`), plus AI-generated classics later
 * (source `classic`). Rubric is resolved server-side at grade time (never sent to client).
 */
export interface MockInterviewPromptSummary {
    /** Prompt id (passed to the interviewer + grade calls). */
    id: string
    /** System name shown in the picker (e.g. "Flash sale: atomic stock decrement"). */
    title: string
    /** Difficulty tier (mirrors the backend `ChallengeDifficulty`). */
    difficulty: string
    /** Curated capstone vs AI-generated classic. */
    source: MockInterviewPromptSource
}

/** Who authored one turn of the interview conversation. */
export type MockInterviewTurnRole = "interviewer" | "candidate"

/** One turn in the interview thread (candidate turns are captured client-side via STT). */
export interface MockInterviewTurn {
    /** Interviewer (AI, streamed from BE) or candidate (voice transcript). */
    role: MockInterviewTurnRole
    /** The phase this turn belongs to (kind="design" only — carries no meaning for Q&A kinds). */
    phase: MockInterviewPhaseKey
    /** Markdown content. */
    content: string
    /** Which seed question (0-based) this turn belongs to — Q&A kinds only, tags the turn for grading's per-question grouping. */
    questionIndex?: number
    /**
     * Set on an interviewer turn whose question shipped GIVEN code that was
     * seeded into the editable Code tool — the bubble shows a "code loaded into
     * the editor" chip instead of the code inline, pointing the candidate at the
     * tool to fix it in place.
     */
    artifactHint?: "code"
}

/**
 * Per-phase score in the scorecard. For `kind="design"` this is one of the 5
 * canonical {@link MockInterviewPhaseKey} values (i18n-resolved via
 * `mockInterview.phase.<key>`). For Q&A kinds the server instead sends a
 * ready-to-render label like `"Question 1"` — rendered AS-IS, no i18n lookup.
 */
export interface MockInterviewPhaseScore {
    /** Which phase (design), or a server-labeled question ("Question 1", "Question 2" …) for Q&A kinds. */
    phase: string
    /** Earned points for the phase/question. */
    score: number
    /** Max points for the phase/question. */
    max: number
}

/** A named evaluation attribute (communication, structured thinking …). */
export interface MockInterviewAttributeScore {
    /** Attribute key (i18n-resolved on the FE). */
    key: string
    /** 0–100. */
    score: number
}

/**
 * One per-question model-answer review — the anti-ChatGPT breakdown that compares
 * the candidate's OWN spoken answer against the seed flashcard's authored model
 * answer, for one `mode="qna"` question. Rendered on the scorecard so the learner
 * sees, per question, what a strong answer would have covered. Empty for a
 * `mode="design"` run (design scores by phase, not per question) and for attempts
 * graded before this field existed — the scorecard self-hides the section then.
 */
export interface MockInterviewQuestionReview {
    /** 0-based index of this question within the session. */
    questionIndex: number
    /** This question's cognitive frame ("theory" | "reasoning" | "scenario"), as drawn. */
    kind: string
    /** The interviewer's question text for this question. */
    question: string
    /** The candidate's own answer for this question. */
    candidateAnswer: string
    /** The seed flashcard's authored model answer (Markdown), or null when unavailable. */
    modelAnswer: string | null
    /** A one-line summary of what the candidate's answer was missing relative to the reference. */
    feedback: string
    /** Score assigned to this question. */
    score: number
    /** Maximum possible score for this question (always 100 for qna). */
    max: number
    /** Best-effort matched course content (lesson) id for this question, or null when no confident match exists. */
    matchedContentId: string | null
}

/**
 * The end-of-session grade for one interview run.
 * BE: a `gradeMockInterviewSession` mutation — grades the whole transcript (+ the
 * whiteboard graph, Pha 2) against the prompt's 5-phase rubric. Persists an attempt
 * grouped by a client-generated `sessionId` (mirrors `interview_attempts`).
 */
export interface MockInterviewGradeResult {
    /** Overall 0–100. */
    overallScore: number
    /** Pass / borderline / fail (reuses the interview verdict vocabulary). */
    verdict: "pass" | "borderline" | "fail"
    /** Per-phase breakdown. */
    phaseScores: Array<MockInterviewPhaseScore>
    /** Per-attribute breakdown (communication, structured thinking …). */
    attributeScores: Array<MockInterviewAttributeScore>
    /** Concrete things done right. */
    strengths: Array<string>
    /** Concrete gaps framed as "what to add". */
    gaps: Array<string>
    /** A follow-up an interviewer would ask next (nullable). */
    followUpQuestion: string | null
    /**
     * Content ids the RAG retrieval matched while grading this session (one flat list
     * for the WHOLE session — retrieval isn't phase-scoped). Empty when the course has
     * no RAG index, retrieval found nothing, or the attempt predates this field — never
     * treat empty as an error, and never fabricate a citation when it's empty.
     */
    matchedContentIds: Array<string>
    /**
     * Per-question model-answer review (the anti-ChatGPT breakdown), one entry per
     * `mode="qna"` question. Empty for a `mode="design"` run or an attempt graded
     * before this field existed — the scorecard self-hides the section then.
     */
    questionReviews: Array<MockInterviewQuestionReview>
}

"use client"

import React, {
    useState,
} from "react"
import { Button, Chip, Typography, Spinner } from "@heroui/react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    SettingsBreadcrumb,
} from "@/components/blocks/settings/SettingsBreadcrumb"
import {
    EntityToken,
} from "@/components/blocks/entity/EntityToken"
import { useQueryMyMilestoneTaskAttemptsSwr, MY_MILESTONE_TASK_ATTEMPTS_LIMIT } from "@/hooks/swr/api/graphql/queries/useQueryMyMilestoneTaskAttemptsSwr"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { ListRow } from "@/components/blocks/lists/ListRow"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { StackV } from "@/components/frames/Stack"

/** Props for {@link MyAttemptsPage}. */
export type MyAttemptsPageProps = Record<string, never>
/**
 * The learner's milestone-task attempts as a list — task, milestone, course,
 * pass/fail chip, score and date (failed attempts included). "Load more" grows
 * the page window via a single offset=0 query (`myMilestoneTaskAttempts`).
 *
 * @param props - optional root className.
 */
export const MyAttemptsPage = () => {
    const t = useTranslations()
    const locale = useLocale()

    /** How many pages have been requested (drives the growing window). */
    const [pageCount, setPageCount] = useState(1)

    const swr = useQueryMyMilestoneTaskAttemptsSwr(
        0,
        MY_MILESTONE_TASK_ATTEMPTS_LIMIT * pageCount,
    )
    const items = swr.data?.items ?? []
    const total = swr.data?.total ?? 0
    const hasMore = items.length < total

    const formatDate = (iso: string): string =>
        new Date(iso).toLocaleDateString(locale, {
            year: "numeric",
            month: "short",
            day: "numeric",
        })

    const listItems = [
        () => (
            <div className="flex flex-col gap-0">
                {items.map((item, index) => (
                    <ListRow
                        key={item.id}
                        title={item.taskTitle}
                        subtitle={item.milestoneTitle}
                        divider={index < items.length - 1}
                        meta={(
                            <>
                                <EntityToken
                                    globalId={item.courseGlobalId}
                                    label={item.courseTitle}
                                />
                                <Chip
                                    size="sm"
                                    variant="soft"
                                    color={item.passed ? "success" : "danger"}
                                >
                                    <Chip.Label>
                                        {item.passed
                                            ? t("profileSettings.learning.attempts.passed")
                                            : t("profileSettings.learning.attempts.failed")}
                                    </Chip.Label>
                                </Chip>
                                <Typography type="body-sm">
                                    {item.score}
                                </Typography>
                                <Typography type="body-xs" color="muted">
                                    {formatDate(item.attemptedAt)}
                                </Typography>
                            </>
                        )}
                    />
                ))}
            </div>
        ),
        ...(hasMore
            ? [() => (
                <div className="flex justify-center">
                    <Button
                        variant="ghost"
                        size="sm"
                        isDisabled={swr.isValidating}
                        onPress={() => setPageCount((count) => count + 1)}
                    >
                        {swr.isValidating ? (
                            <Spinner color="current" size="sm" />
                        ) : null}
                        {t("profileSettings.learning.loadMore")}
                    </Button>
                </div>
            )]
            : []),
    ]

    return (
        <div className={"flex flex-col gap-10"}>
            <PageHeader
