"use client"

import React from "react"
import { Chip, Skeleton } from "@heroui/react"
import { useLocale, useTranslations } from "next-intl"
import {
    ReceiptIcon,
    TicketIcon,
} from "@phosphor-icons/react"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import {
    SurfaceListCard,
    SurfaceListCardRow,
} from "@/components/blocks/cards/SurfaceListCard"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { useQueryMyRewardWalletSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyRewardWalletSwr"
import { useQueryMyVouchersSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyVouchersSwr"
import { pathConfig } from "@/resources/path"
import type { QueryMyVoucherData } from "@/modules/api/graphql/queries/types/my-vouchers"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"

/** Chip color per voucher lifecycle status. */
const STATUS_COLOR: Record<string, "accent" | "warning" | "default" | "danger"> = {
    unused: "accent",
    reserved: "warning",
    used: "default",
    expired: "danger",
}

/** Format a voucher's discount as a short label, e.g. "-10%" / "-50,000 VND". */
const discountLabel = (voucher: QueryMyVoucherData): string => (
    voucher.discountType === "percent"
        ? `-${voucher.value}%`
        // Dong suffix via code point — keeps the source free of Vietnamese letters.
        : `-${voucher.value.toLocaleString("vi-VN")}${String.fromCharCode(0x0111)}`
)

/** Props for {@link MyVouchers}. */
export type MyVouchersProps = Record<string, never>
/**
 * The Coin shop's "My wallet" tab: the viewer's minted vouchers (code, scope,
 * status, expiry) plus the redemption history. Self-fetches both — the
 * `myRewardWallet` key is shared with the header/catalog, so a redeem
 * elsewhere refreshes this list without a manual prop.
 *
 * @param props - optional className for the root element.
 */
export const MyVouchers = () => {
    const t = useTranslations()
    const locale = useLocale()
    const vouchersSwr = useQueryMyVouchersSwr()
    const walletSwr = useQueryMyRewardWalletSwr()

    return (
        <Box identity={{ tier: "page", component: "MyVouchers" }}>
            <StackV gap={6} principle="block-boundary"
                explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                items={[
                    () => (
                        <LabeledCard
                            label={t("rewards.myVouchers.title")}
                            frameless
                        >
                            <AsyncContent
                                isLoading={!vouchersSwr.data}
                                skeleton={(
                                    <div className="overflow-hidden rounded-3xl bg-surface shadow-surface">
                                        {Array.from({ length: 2 }).map((_, index) => (
                                            <Box key={index} principle="row-pad" className="px-4 py-4"
                                                explain="Row content inset — not cell-pad, because this pads a horizontal content row rather than a dense table cell.">
                                                <StackH gap={4} principle="content-row"
                                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                    align="center" items={[
                                                        () => <Skeleton className="size-12 shrink-0 rounded-xl" />,
                                                        () => (
                                                            <StackV gap={3} principle="sibling-stack"
                                                                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                                                classNames={["min-w-0", "flex-1"]} items={[
                                                                    () => <Skeleton className="h-4 w-1/3 rounded-lg" />,
                                                                    () => <Skeleton className="h-4 w-1/2 rounded-lg" />,
                                                                ]} />
                                                        ),
                                                    ]} />
                                            </Box>
                                        ))}
                                    </div>
                                )}
                                isEmpty={(vouchersSwr.data ?? []).length === 0}
                                emptyContent={{
                                    icon: <TicketIcon aria-hidden focusable="false" className="size-8 text-muted" />,
                                    title: t("rewards.myVouchers.empty"),
                                    description: t("rewards.myVouchers.emptyHint"),
                                }}
                                error={vouchersSwr.error}
                                errorContent={{
                                    title: t("rewards.myVouchers.error"),
                                    onRetry: () => void vouchersSwr.mutate(),
                                }}
                            >
                                <SurfaceListCard>
                                    {(vouchersSwr.data ?? []).map((voucher) => (
                                        <SurfaceListCardRow
                                            key={voucher.id}
                                            // `subtitle` is plain text now (never a built element), so the
                                            // course reference can no longer carry its own inline link — the
                                            // whole row becomes the link instead (`href` below), which is a
                                            // bigger, easier-to-hit target than the old inline text anyway.
                                            leading={() => (
                                                <IconTile
                                                    size="sm"
                                                    tone="accent"
                                                    icon={<TicketIcon aria-hidden focusable="false" />}
                                                />
                                            )}
                                            title={voucher.code}
                                            subtitle={
                                                voucher.courseId
                                                    ? t("rewards.myVouchers.scopeCourse", {
                                                        course: voucher.courseTitle ?? "",
                                                    }).replace(/<\/?link>/g, "")
                                                    : t("rewards.myVouchers.scopeAny")
                                            }
                                            href={voucher.courseDisplayId
                                                ? pathConfig().locale(locale).course(voucher.courseDisplayId).build()
                                                : undefined}
                                            meta={() => (
                                                <span className="text-sm font-medium text-foreground">
                                                    {discountLabel(voucher)}
                                                </span>
                                            )}
                                            trailing={() => (
                                                <Chip color={STATUS_COLOR[voucher.status] ?? "default"} variant="soft" size="sm">
                                                    <Chip.Label>
                                                        {t(`rewards.myVouchers.status.${voucher.status}`)}
                                                    </Chip.Label>
                                                </Chip>
                                            )}
                                        />
                                    ))}
                                </SurfaceListCard>
                            </AsyncContent>
                        </LabeledCard>
                    ),

                    () => (
                        <LabeledCard
                            label={t("rewards.redeemedTitle")}
                            frameless
                        >
                            <AsyncContent
                                isLoading={!walletSwr.data}
                                skeleton={(
                                    <div className="overflow-hidden rounded-3xl bg-surface shadow-surface">
                                        {Array.from({ length: 3 }).map((_, index) => (
                                            <Box key={index} principle="row-pad" className="px-4 py-4"
                                                explain="Row content inset — not cell-pad, because this pads a horizontal content row rather than a dense table cell.">
                                                <StackH gap={4} principle="content-row"
                                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                    justify="between" align="center" items={[
                                                        () => <Skeleton className="h-4 w-1/3 rounded-lg" />,
                                                        () => <Skeleton className="h-4 w-16 rounded-lg" />,
                                                    ]} />
                                            </Box>
                                        ))}
                                    </div>
                                )}
                                isEmpty={(walletSwr.data?.redemptions ?? []).length === 0}
                                emptyContent={{
                                    icon: <ReceiptIcon aria-hidden focusable="false" className="size-8 text-muted" />,
                                    title: t("rewards.noRedemptions"),
                                }}
                                error={walletSwr.error}
                                errorContent={{
                                    title: t("rewards.myVouchers.error"),
                                    onRetry: () => void walletSwr.mutate(),
                                }}
                            >
                                <SurfaceListCard>
                                    {(walletSwr.data?.redemptions ?? []).map((redemption, index) => (
                                        <SurfaceListCardRow
                                            key={`${redemption.rewardKey}-${redemption.createdAt}-${index}`}
                                            title={redemption.title}
                                            subtitle={new Date(redemption.createdAt).toLocaleDateString(locale)}
                                            meta={() => (
                                                <span className="text-xs text-muted">
                                                    {t(`rewards.status.${redemption.status}`)}
                                                </span>
                                            )}
                                            trailing={() => (
                                                <span className="text-sm font-medium text-foreground">
                                                    {t("rewards.cost", { count: redemption.cost })}
                                                </span>
                                            )}
                                        />
                                    ))}
                                </SurfaceListCard>
                            </AsyncContent>
                        </LabeledCard>
                    ),
                ]} />
        </Box>
    )
}

"use client"

import React, {
    useCallback,
    useState,
} from "react"
import type { ReactNode } from "react"
import {
    Button,
    Card,
    Chip,
    Input,
    Label,
    Skeleton,
    TextField,
    Typography,
} from "@heroui/react"
import { toast } from "@/modules/toast/toast"
import { useTranslations } from "next-intl"
import {
    CheckCircleIcon,
    CopyIcon,
    GiftIcon,
    LightningIcon,
    SnowflakeIcon,
    TShirtIcon,
    TicketIcon,
} from "@phosphor-icons/react"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { Callout } from "@/components/composites/feedback/Callout"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { ModalShell } from "@/components/composites/layout/ModalShell"
import { useMutateRedeemRewardSwr } from "@/hooks/swr/api/graphql/mutations/useMutateRedeemRewardSwr"
import { useQueryMyRewardWalletSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyRewardWalletSwr"
import { useQueryMyVouchersSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyVouchersSwr"
import { useQueryRewardsSwr } from "@/hooks/swr/api/graphql/queries/useQueryRewardsSwr"
import { useGraphQLWithToast } from "@/modules/toast/hooks"
import type { QueryRewardData } from "@/modules/api/graphql/queries/types/rewards"
import type { RedeemRewardAiCreditGrant } from "@/modules/api/graphql/mutations/types/redeem-reward"
import { Box } from "@/components/frames/Box"
import { Grid } from "@/components/frames/Grid"
import { StackH, StackV } from "@/components/frames/Stack"

/** Icon per catalog item, keyed by its stable reward key (falls back to a generic gift). */
const REWARD_ICON: Record<string, ReactNode> = {
    streakFreeze: <SnowflakeIcon aria-hidden focusable="false" className="size-5 text-accent-soft-foreground" />,
    aiCreditBoost: <LightningIcon aria-hidden focusable="false" className="size-5 text-accent-soft-foreground" />,
    voucher10: <TicketIcon aria-hidden focusable="false" className="size-5 text-accent-soft-foreground" />,
    tshirt: <TShirtIcon aria-hidden focusable="false" className="size-5 text-accent-soft-foreground" />,
}

/**
 * Coin-shop catalog grouped into user-facing SECTIONS by reward `kind` (instructor's
 * call, 2026-07-17, "split into more categories"). `aiCredit` + `digital` read as one
 * "speed up learning" bucket; `voucher` and `physical` each stand alone. Order = display
 * order. A reward whose `kind` matches no section is not shown in the grouped view —
 * every current kind is covered here; adding a new kind means adding a section.
 */
const REWARD_SECTIONS: ReadonlyArray<{ key: string, icon: ReactNode, kinds: ReadonlyArray<string> }> = [
    { key: "learn", icon: <LightningIcon aria-hidden focusable="false" className="size-5 text-accent-soft-foreground" />, kinds: ["aiCredit", "digital"] },
    { key: "voucher", icon: <TicketIcon aria-hidden focusable="false" className="size-5 text-accent-soft-foreground" />, kinds: ["voucher"] },
    { key: "physical", icon: <GiftIcon aria-hidden focusable="false" className="size-5 text-accent-soft-foreground" />, kinds: ["physical"] },
]

/** One redeem effect's takeaway shown right after redeeming (voucher code / AI-credit bump). */
type JustRedeemed =
    | { kind: "voucher", code: string }
    | { kind: "aiCredit", grant: RedeemRewardAiCreditGrant }

/** Shipping form fields (physical rewards only). */
interface ShippingForm {
    recipientName: string
    phone: string
    address: string
}

const EMPTY_SHIPPING: ShippingForm = {
    recipientName: "",
    phone: "",
    address: "",
}

/** Props for {@link RewardCatalog}. */
export type RewardCatalogProps = Record<string, never>
/**
 * The Coin shop's "Store" tab: the redeemable catalog grid. Self-fetches the
 * catalog + the viewer's balance (the wallet SWR key is shared with the header
 * and the "My Wallet" tab, so a redeem here refreshes both instantly). Physical
 * rewards expand an inline shipping form before redeeming; a `voucher`/`aiCredit`
 * redemption surfaces its takeaway (code to copy / bonus credit granted) in a
 * dismissible callout above the grid.
 *
 * @param props - optional className for the root element.
 */
export const RewardCatalog = () => {
    const t = useTranslations()
    const rewardsSwr = useQueryRewardsSwr()
    const walletSwr = useQueryMyRewardWalletSwr()
    const vouchersSwr = useQueryMyVouchersSwr()
    const { trigger: triggerRedeem } = useMutateRedeemRewardSwr()
    const runGraphQL = useGraphQLWithToast()

    /** The reward key currently being redeemed (single in-flight redeem). */
    const [redeeming, setRedeeming] = useState<string | null>(null)
    /** The physical reward whose shipping form is open (null = none). */
    const [shippingFor, setShippingFor] = useState<string | null>(null)
    const [ship, setShip] = useState<ShippingForm>(EMPTY_SHIPPING)
    /** The takeaway of the most recent voucher/aiCredit redemption, if any. */
    const [justRedeemed, setJustRedeemed] = useState<JustRedeemed | null>(null)
    /** A non-physical reward awaiting spend confirmation (Coin is real, redeem is irreversible). */
    const [confirming, setConfirming] = useState<QueryRewardData | null>(null)

    const balance = walletSwr.data?.balance ?? 0

    const onRedeem = useCallback(
        async (reward: QueryRewardData, shipping?: ShippingForm) => {
            setRedeeming(reward.key)
            try {
                let redeemed: { voucherCode?: string | null, aiCreditGranted?: RedeemRewardAiCreditGrant | null } | undefined
                const ok = await runGraphQL(async () => {
                    const result = await triggerRedeem({
                        rewardKey: reward.key,
                        ...shipping,
                    })
                    const wrapped = result.data!.redeemReward
                    redeemed = wrapped.data
                    return wrapped
                })
                if (ok) {
                    await walletSwr.mutate()
                    if (reward.kind === "voucher" && redeemed?.voucherCode) {
                        setJustRedeemed({ kind: "voucher", code: redeemed.voucherCode })
                        await vouchersSwr.mutate()
                    } else if (reward.kind === "aiCredit" && redeemed?.aiCreditGranted) {
                        setJustRedeemed({ kind: "aiCredit", grant: redeemed.aiCreditGranted })
                    }
                    // close + reset the shipping form on success
                    setShippingFor(null)
                    setShip(EMPTY_SHIPPING)
                }
            } finally {
                setRedeeming(null)
            }
        },
        [
            triggerRedeem,
            walletSwr,
            vouchersSwr,
            runGraphQL,
        ],
    )

    const onCopyCode = useCallback(
        async (code: string) => {
            try {
                await navigator.clipboard.writeText(code)
                toast.success(t("rewards.myVouchers.copied"))
            } catch {
                // clipboard blocked (permissions/http) → no-op, code is still selectable text
            }
        },
        [t],
    )

    return (
        <Box>
            <StackV gap={4} principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={[
                    () => (justRedeemed ? (
                        <Callout
                            status="accent"
                            icon={CheckCircleIcon}
                            title={
                                justRedeemed.kind === "voucher"
                                    ? t("rewards.justRedeemed.voucherTitle")
                                    : t("rewards.justRedeemed.aiCreditTitle")
                            }
                            description={
                                justRedeemed.kind === "voucher"
                                    ? undefined
                                    : t("rewards.justRedeemed.aiCreditDescription", {
                                        amount5h: justRedeemed.grant.amount5h,
                                        amountWeek: justRedeemed.grant.amountWeek,
                                    })
                            }
                            body={justRedeemed.kind === "voucher" ? () => (
                                <StackH gap={3} principle="flex-action"
                                    explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                    align="center" items={[
                                        () => <span className="font-mono font-medium text-foreground">{justRedeemed.code}</span>,
                                        () => (
                                            <Button
                                                variant="tertiary"
                                                size="sm"
                                                onPress={() => void onCopyCode(justRedeemed.code)}
                                            >
                                                <CopyIcon aria-hidden focusable="false" className="size-4" />
                                                {t("rewards.myVouchers.copy")}
                                            </Button>
                                        ),
                                    ]} />
                            ) : undefined}
                            onClose={() => setJustRedeemed(null)}
                            closeAriaLabel={t("rewards.justRedeemed.dismiss")}
                        />
                    ) : null),

                    () => (
                        <AsyncContent
                            isLoading={!rewardsSwr.data}
                            skeleton={(
                                <Grid
                                    columns={{ base: 1, sm: 2 }}
                                    principle="content-row"
                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                    items={Array.from({ length: 4 }).map((_, index) => ({
                                        key: String(index),
                                        content: () => (
                                            <Box principle="card-padding" className="rounded-3xl bg-surface p-4 shadow-surface"
                                                explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
                                                <StackV gap={4} principle="content-row"
                                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                    items={[
                                                        () => (
                                                            <StackH gap={4} principle="content-row"
                                                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                                align="center" items={[
                                                                    () => <Skeleton className="size-12 shrink-0 rounded-xl" />,
                                                                    () => <Skeleton className="h-4 w-1/2 rounded-lg" />,
                                                                ]} />
                                                        ),
                                                        () => <Skeleton className="h-4 w-full rounded-lg" />,
                                                        () => <Skeleton className="h-9 w-24 self-end rounded-lg" />,
                                                    ]} />
                                            </Box>
                                        ),
                                    }))}
                                />
                            )}
                            isEmpty={(rewardsSwr.data ?? []).length === 0}
                            emptyContent={{
                                icon: <GiftIcon aria-hidden focusable="false" className="size-8 text-muted" />,
                                title: t("rewards.catalogEmptyTitle"),
                                description: t("rewards.catalogEmptyDescription"),
                            }}
                            error={rewardsSwr.error}
                            errorContent={{
                                title: t("rewards.catalogError"),
                                onRetry: () => void rewardsSwr.mutate(),
                            }}
                        >
                            <StackV gap={6} principle="block-boundary" explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups." items={REWARD_SECTIONS.map((section) => () => {
                                const sectionItems = (rewardsSwr.data ?? []).filter((reward) => section.kinds.includes(reward.kind))
                                if (sectionItems.length === 0) {
                                    return null
                                }
                                return (
                                    <LabeledCard
                                        key={section.key}
                                        // `label` is plain text now (never a built element) — `LabeledCard`
                                        // has no leading-icon slot the way `SectionCard` does, so the
                                        // per-section icon has nowhere left to attach (flagged for a
                                        // follow-up: a real icon slot on `LabeledCard`, or switch this
                                        // section header to `SectionCard`).
                                        label={t(`rewards.section.${section.key}`)}
                                    >
                                        <Grid
                                            columns={{ base: 1, sm: 2 }}
                                            principle="content-row"
                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                            items={sectionItems.map((reward) => ({
                                                key: reward.key,
                                                content: () => {
                                                    const affordable = balance >= reward.cost
                                                    const isPhysical = reward.kind === "physical"
                                                    const formOpen = shippingFor === reward.key
                                                    const shipReady = Boolean(
                                                        ship.recipientName.trim()
                                && ship.phone.trim()
                                && ship.address.trim(),
                                                    )
                                                    return (
                                                        <Card>
                                                            <StackV gap={4} principle="content-row"
                                                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                                items={[
                                                                    () => (
                                                                        <StackH gap={4} principle="content-row"
                                                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                                            align="start" items={[
                                                                                () => (
                                                                                    <IconTile
                                                                                        size="sm"
                                                                                        tone="accent"
                                                                                        icon={REWARD_ICON[reward.key] ?? (
                                                                                            <GiftIcon aria-hidden focusable="false" className="size-5 text-accent-soft-foreground" />
                                                                                        )}
                                                                                    />
                                                                                ),
                                                                                () => (
                                                                                    <StackV gap={1} principle="name-handle"
                                                                                        explain="Display name with handle — not title-subtitle, because the second line is an identity handle rather than a subtitle."
                                                                                        classNames={["min-w-0", "flex-1"]} items={[
                                                                                            () => (
                                                                                                <span className="truncate text-sm font-semibold text-foreground">
                                                                                                    {reward.title}
                                                                                                </span>
                                                                                            ),
                                                                                            () => (
                                                                                                <span className="text-xs text-muted">
                                                                                                    {reward.description}
                                                                                                </span>
                                                                                            ),
                                                                                        ]} />
                                                                                ),
                                                                            ]} />
                                                                    ),
                                                                    () => (
                                                                        <StackH gap={4} principle="content-row" justify="between" align="center"
                                                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                                            items={[
                                                                                () => (
                                                                                    <Chip color="accent" variant="soft" size="sm">
                                                                                        <Chip.Label>
                                                                                            {t("rewards.cost", { count: reward.cost })}
                                                                                        </Chip.Label>
                                                                                    </Chip>
                                                                                ),
                                                                                () => (!formOpen ? (
                                                                                    <Button
                                                                                        variant="primary"
                                                                                        size="sm"
                                                                                        isDisabled={!affordable || redeeming !== null}
                                                                                        isPending={redeeming === reward.key}
                                                                                        onPress={() => {
                                                                                            if (isPhysical) {
                                                                                                setShippingFor(reward.key)
                                                                                            } else {
                                                                                                // Coin is real + redeem is irreversible — confirm
                                                                                                // before spending (mirrors the shipping form's own
                                                                                                // "Confirm redeem" step for physical rewards).
                                                                                                setConfirming(reward)
                                                                                            }
                                                                                        }}
                                                                                    >
                                                                                        {affordable
                                                                                            ? t("rewards.redeem")
                                                                                            : t("rewards.cannotAfford")}
                                                                                    </Button>
                                                                                ) : null),
                                                                            ]} />
                                                                    ),
                                                                    () => (formOpen ? (
                                                                        <StackV gap={3} principle="sibling-stack"
                                                                            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                                                            items={[
                                                                                () => (
                                                                                    <TextField variant="secondary">
                                                                                        <Label htmlFor={`reward-ship-name-${reward.key}`}>
                                                                                            {t("rewards.shipName")}
                                                                                        </Label>
                                                                                        <Input
                                                                                            id={`reward-ship-name-${reward.key}`}
                                                                                            value={ship.recipientName}
                                                                                            onChange={(event) => setShip((prev) => ({
                                                                                                ...prev,
                                                                                                recipientName: event.target.value,
                                                                                            }))}
                                                                                        />
                                                                                    </TextField>
                                                                                ),
                                                                                () => (
                                                                                    <TextField variant="secondary">
                                                                                        <Label htmlFor={`reward-ship-phone-${reward.key}`}>
                                                                                            {t("rewards.shipPhone")}
                                                                                        </Label>
                                                                                        <Input
                                                                                            id={`reward-ship-phone-${reward.key}`}
                                                                                            type="tel"
                                                                                            value={ship.phone}
                                                                                            onChange={(event) => setShip((prev) => ({
                                                                                                ...prev,
                                                                                                phone: event.target.value,
                                                                                            }))}
                                                                                        />
                                                                                    </TextField>
                                                                                ),
                                                                                () => (
                                                                                    <TextField variant="secondary">
                                                                                        <Label htmlFor={`reward-ship-address-${reward.key}`}>
                                                                                            {t("rewards.shipAddress")}
                                                                                        </Label>
                                                                                        <Input
                                                                                            id={`reward-ship-address-${reward.key}`}
                                                                                            value={ship.address}
                                                                                            onChange={(event) => setShip((prev) => ({
                                                                                                ...prev,
                                                                                                address: event.target.value,
                                                                                            }))}
                                                                                        />
                                                                                    </TextField>
                                                                                ),
                                                                                () => (
                                                                                    <StackH gap={3} principle="flex-action"
                                                                                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                                                                        align="center" items={[
                                                                                            () => (
                                                                                                <Button
                                                                                                    variant="primary"
                                                                                                    size="sm"
                                                                                                    isDisabled={!shipReady || redeeming !== null}
                                                                                                    isPending={redeeming === reward.key}
                                                                                                    onPress={() => void onRedeem(reward, ship)}
                                                                                                >
                                                                                                    {t("rewards.confirmRedeem")}
                                                                                                </Button>
                                                                                            ),
                                                                                            () => (
                                                                                                <Button
                                                                                                    variant="tertiary"
                                                                                                    size="sm"
                                                                                                    onPress={() => setShippingFor(null)}
                                                                                                >
                                                                                                    {t("rewards.cancel")}
                                                                                                </Button>
                                                                                            ),
                                                                                        ]} />
                                                                                ),
                                                                            ]} />
                                                                    ) : null),
                                                                ]} />
                                                        </Card>
                                                    )
                                                },
                                            }))}
                                        />
                                    </LabeledCard>
                                )
                            })} />
                        </AsyncContent>
                    ),

                    // spend confirmation for non-physical rewards — Coin is real + redeem is
                    // irreversible, so a single accidental tap must never fire it (mirrors the
                    // shipping form's own "Confirm redeem" step for physical rewards).
                    () => (
                        <ModalShell
                            isOpen={confirming !== null}
                            onOpenChange={(open) => {
                                if (!open) {
                                    setConfirming(null)
                                }
                            }}
                            title={t("rewards.confirmRedeem")}
                            size="sm"
                            body={() => (
                                <Typography type="body-sm" color="muted">
                                    {confirming
                                        ? t("rewards.confirmRedeemBody", { cost: confirming.cost, title: confirming.title })
                                        : null}
                                </Typography>
                            )}
                            footer={() => (
                                <>
                                    <Button variant="tertiary" onPress={() => setConfirming(null)}>
                                        {t("rewards.cancel")}
                                    </Button>
                                    <Button
                                        variant="primary"
                                        isPending={redeeming !== null}
                                        onPress={() => {
                                            const reward = confirming
                                            setConfirming(null)
                                            if (reward) {
                                                void onRedeem(reward)
                                            }
                                        }}
                                    >
                                        {t("rewards.confirmRedeem")}
                                    </Button>
                                </>
                            )}
                        />
                    ),
                ]} />
        </Box>
    )
}

"use client"

import React, { useState } from "react"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { CoinsIcon } from "@phosphor-icons/react"
import { HighlightChip } from "@/components/composites/chips/HighlightChip"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { ResponsiveBreadcrumb } from "@/components/blocks/navigation/ResponsiveBreadcrumb"
import { TabsCard } from "@/components/blocks/navigation/TabsCard"
import { useQueryMyRewardWalletSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyRewardWalletSwr"
import { useQueryMyVouchersSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyVouchersSwr"
import { pathConfig } from "@/resources/path"
import { MyVouchers } from "./MyVouchers"
import { RewardCatalog } from "./RewardCatalog"
import { Box } from "@/components/frames/Box"
import { StackV } from "@/components/frames/Stack"

/** The Coin shop's two tabs: buying new rewards vs owning/using them. */
enum RewardsTab {
    Shop = "shop",
    Wallet = "wallet",
}

/** Props for {@link RewardsPage}. */
export type RewardsPageProps = Record<string, never>
/**
 * The Coin shop: the viewer's spendable Coin balance in the header, a
 * "Store" tab (redeemable catalog) and a "My wallet" tab (minted vouchers +
 * redemption history). Tabs are local state — this page is not deep-linked
 * into from elsewhere, so URL state isn't needed. See `fe/features/rewards.md`
 * (canon) for the shell/CTA/state rationale.
 *
 * @param props - optional className for the root element.
 */
export const RewardsPage = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const walletSwr = useQueryMyRewardWalletSwr()
    const vouchersSwr = useQueryMyVouchersSwr()
    const [tab, setTab] = useState<RewardsTab>(RewardsTab.Shop)

    const balance = walletSwr.data?.balance ?? 0
    const unusedVoucherCount = (vouchersSwr.data ?? []).filter(
        (voucher) => voucher.status === "unused",
    ).length

    return (
        <div className={""}>
            <Box principle="center-measure" className="mx-auto w-full max-w-3xl p-6"
                explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport.">
                <StackV principle="layout-split"
                    explain="Major layout split — not block-boundary, because this separates primary page regions rather than adjacent blocks."
                    items={[
                        () => (
                            <PageHeader
                                breadcrumb={(
                                    <ResponsiveBreadcrumb
                                        items={[
                                            {
                                                key: "home",
                                                label: t("nav.home"),
                                                onPress: () => router.push(pathConfig().locale(locale).build()),
                                            },
                                            {
                                                key: "rewards",
                                                label: t("rewards.title"),
                                            },
                                        ]}
                                    />
                                )}
                                title={t("rewards.title")}
                                description={t("rewards.description")}
                                meta={(
                                    <HighlightChip
                                        tone="accent"
                                        icon={CoinsIcon}
                                        value={balance}
                                        label={t("rewards.balanceLabel")}
                                    />
                                )}
                            />
                        ),
                        () => (
                            <StackV principle="block-boundary"
                                explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                                items={[
                                    () => (
                                        <TabsCard
                                            leftTabs={{
                                                items: [
                                                    {
                                                        key: RewardsTab.Shop,
                                                        label: t("rewards.tabs.shop"),
                                                    },
                                                    {
                                                        key: RewardsTab.Wallet,
                                                        label: unusedVoucherCount > 0
                                                            ? t("rewards.tabs.walletWithCount", { count: unusedVoucherCount })
                                                            : t("rewards.tabs.wallet"),
                                                    },
                                                ],
                                                selectedKey: tab,
                                                ariaLabel: t("rewards.tabsAria"),
                                                onSelectionChange: (key) => setTab(key as RewardsTab),
                                            }}
                                        />
                                    ),
                                    () => (tab === RewardsTab.Shop ? <RewardCatalog /> : <MyVouchers />),
                                ]} />
                        ),
                    ]} />
            </Box>
        </div>
    )
}

"use client"

import {
    ShieldCheckIcon,
} from "@phosphor-icons/react"
import React, {
    useCallback,
    useState,
} from "react"
import {
    Button,
    Card,
    CardContent,
    Chip,
    Input,
    Label,
    Spinner,
    TextField,
    Typography,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import {
    SettingsBreadcrumb,
} from "@/components/blocks/settings/SettingsBreadcrumb"
import { useAppSelector } from "@/redux/hooks"
import { useQueryUserSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserSwr"
import { useMutateSetupTwoFactorSwr } from "@/hooks/swr/api/graphql/mutations/useMutateSetupTwoFactorSwr"
import { useMutateConfirmTwoFactorSwr } from "@/hooks/swr/api/graphql/mutations/useMutateConfirmTwoFactorSwr"
import { useMutateDisableTwoFactorSwr } from "@/hooks/swr/api/graphql/mutations/useMutateDisableTwoFactorSwr"
import type { SetupTwoFactorData } from "@/modules/api/graphql/mutations/types/two-factor"
import { QRCode } from "@/components/blocks/media/QRCode"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { Callout } from "@/components/composites/feedback/Callout"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { StackH, StackV } from "@/components/frames/Stack"

/** Inline status shown after a 2FA action. */
interface SecurityStatus {
    /** Whether the action succeeded or failed (drives the colour). */
    kind: "success" | "error"
    /** The message to show. */
    text: string
}

/**
 * SecurityPage feature container — configure app-level two-factor auth (TOTP).
 *
 * Reads the current 2FA flag from the signed-in user. Disabled → "Enable" runs
 * `setupTwoFactor`, shows the QR + secret, then `confirmTwoFactor` verifies a
 * code. Enabled → a code + `disableTwoFactor` turns it off. After each change it
 * refetches `me` so redux reflects the new state. Mounted by `/profile/security`.
 *
 * Note: this configures the second factor; enforcing it at a specific login flow
 * is a separate concern that is intentionally not wired yet.
 */
export const SecurityPage = () => {
    const t = useTranslations()
    const user = useAppSelector((state) => state.user.user)
    const {
        mutate: refreshUser,
        isLoading: userLoading,
    } = useQueryUserSwr()
    const {
        trigger: triggerSetup,
        isMutating: settingUp,
    } = useMutateSetupTwoFactorSwr()
    const {
        trigger: triggerConfirm,
        isMutating: confirming,
    } = useMutateConfirmTwoFactorSwr()
    const {
        trigger: triggerDisable,
        isMutating: disabling,
    } = useMutateDisableTwoFactorSwr()

    const enabled = Boolean(user?.twoFactorEnabled)
    // enrollment material from setupTwoFactor (QR + secret); null when not enrolling
    const [setup, setSetup] = useState<SetupTwoFactorData | null>(null)
    // the 6-digit code the user types to confirm or disable
    const [code, setCode] = useState("")
    const [status, setStatus] = useState<SecurityStatus | null>(null)


    /** Keep only digits + cap at 6 so the field always holds a clean code. */
    const onCodeChange = useCallback(
        (event: React.ChangeEvent<HTMLInputElement>) => {
            setCode(event.target.value.replace(/\D/g, "").slice(0, 6))
        },
        [],
    )

    /** Begin enrollment: fetch a secret + otpauth URI, then show the QR. */
    const onStartSetup = useCallback(
        async () => {
            setStatus(null)
            setCode("")
            try {
                const result = await triggerSetup()
                const payload = result?.data?.setupTwoFactor
                if (payload?.success && payload.data) {
                    setSetup(payload.data)
                } else {
                    setStatus({ kind: "error", text: payload?.message ?? t("security.error") })
                }
            } catch (error) {
                setStatus({ kind: "error", text: (error as Error)?.message ?? t("security.error") })
            }
        },
        [
            triggerSetup,
            t,
        ],
    )

    /** Verify the typed code against the pending secret and enable 2FA. */
    const onConfirm = useCallback(
        async () => {
            try {
                const result = await triggerConfirm({ code })
                const payload = result?.data?.confirmTwoFactor
                if (payload?.success) {
                    setSetup(null)
                    setCode("")
                    await refreshUser()
                    setStatus({ kind: "success", text: t("security.enabledToast") })
                } else {
                    setStatus({ kind: "error", text: payload?.message ?? t("security.invalidCode") })
                }
            } catch (error) {
                setStatus({ kind: "error", text: (error as Error)?.message ?? t("security.invalidCode") })
            }
        },
        [
            triggerConfirm,
            code,
            refreshUser,
            t,
        ],
    )

    /** Disable 2FA (a valid code is required while it is enabled). */
    const onDisable = useCallback(
        async () => {
            try {
                const result = await triggerDisable({ code })
                const payload = result?.data?.disableTwoFactor
                if (payload?.success) {
                    setCode("")
                    await refreshUser()
                    setStatus({ kind: "success", text: t("security.disabledToast") })
                } else {
                    setStatus({ kind: "error", text: payload?.message ?? t("security.invalidCode") })
                }
            } catch (error) {
                setStatus({ kind: "error", text: (error as Error)?.message ?? t("security.invalidCode") })
            }
        },
        [
            triggerDisable,
            code,
            refreshUser,
            t,
        ],
    )

    /** Abandon an in-progress enrollment. */
    const onCancelSetup = useCallback(
        () => {
            setSetup(null)
            setCode("")
            setStatus(null)
        },
        [],
    )

    // confirm / disable need a full 6-digit code
    const codeComplete = code.length === 6

    const statusRow = (
        <StackH
            gap={4}
            principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            align="center"
            items={[
                () => <ShieldCheckIcon aria-hidden className="size-5 text-accent-soft-foreground" />,
                () => (
                    <StackV
                        gap={1}
                        principle="name-handle"
                        explain="Display name with handle — not title-subtitle, because the second line is an identity handle rather than a subtitle."
                        classNames={["flex-1"]}
                        items={[
                            () => (
                                <Typography type="body-sm" weight="medium">
                                    {t("security.twoFactor")}
                                </Typography>
                            ),
                            () => (userLoading && !user ? (
                                <Skeleton.Typography type="body-xs" width="1/2" />
                            ) : (
                                <Typography type="body-xs" color="muted">
                                    {enabled ? t("security.enabledDesc") : t("security.disabledDesc")}
                                </Typography>
                            )),
                        ]}
                    />
                ),
                () => (userLoading && !user ? (
                    <Skeleton.Chip />
                ) : (
                    <Chip
                        color={enabled ? "success" : "default"}
                        variant="soft"
                        size="sm"
                    >
                        <Chip.Label>
                            {enabled ? t("security.enabledLabel") : t("security.disabledLabel")}
                        </Chip.Label>
                    </Chip>
                )),
            ]}
        />
    )

    return (
        <StackV
            gap={7}
            principle="layout-split"
            explain="Major layout split — not block-boundary, because this separates primary page regions rather than adjacent blocks."
            identity={{ tier: "block", component: "SecurityPage" }}
            items={[
                () => (
                    <PageHeader
                        breadcrumb={<SettingsBreadcrumb current={t("security.title")} />}
                        title={t("security.title")}
                        description={t("security.subtitle")}
                    />
                ),
                () => (
                    <StackV
                        gap={6}
                        principle="block-boundary"
                        explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                        items={[
                            () => (
                                <Card>
                                    <CardContent>
                                        <AsyncContent
                                            isLoading={userLoading && !user}
                                            skeleton={(
                                                <StackV
                                                    gap={4}
                                                    principle="content-row"
                                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                    items={[
                                                        () => statusRow,
                                                        () => <Skeleton.Button width="w-full" />,
                                                    ]}
                                                />
                                            )}
                                        >
                                            <StackV
                                                gap={4}
                                                principle="content-row"
                                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                items={[
                                                    () => statusRow,
                                                    ...(status ? [() => (
                                                        <Callout
                                                            status={status.kind === "success" ? "success" : "danger"}
                                                            title={status.text}
                                                        />
                                                    )] : []),
                                                    ...(enabled ? [() => (
                                                        <StackV
                                                            gap={4}
                                                            principle="label-field"
                                                            explain="Form label above its field — not title-subtitle, because the upper line labels an input rather than a heading pair."
                                                            items={[
                                                                () => (
                                                                    <TextField variant="secondary">
                                                                        <Label>{t("security.codeLabel")}</Label>
                                                                        <Input
                                                                            variant="secondary"
                                                                            inputMode="numeric"
                                                                            autoComplete="one-time-code"
                                                                            placeholder={t("security.codePlaceholder")}
                                                                            value={code}
                                                                            onChange={onCodeChange}
                                                                        />
                                                                    </TextField>
                                                                ),
                                                                () => (
                                                                    <Button
                                                                        variant="danger"
                                                                        isDisabled={!codeComplete || disabling}
                                                                        isPending={disabling}
                                                                        onPress={onDisable}
                                                                    >
                                                                        {({ isPending }) => (
                                                                            <>
                                                                                {isPending ? <Spinner color="current" size="sm" /> : null}
                                                                                {t("security.disable")}
                                                                            </>
                                                                        )}
                                                                    </Button>
                                                                ),
                                                            ]}
                                                        />
                                                    )] : setup ? [() => (
                                                        <StackV
                                                            gap={4}
                                                            principle="content-row"
                                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                            items={[
                                                                () => (
                                                                    <Typography type="body-sm" color="muted">
                                                                        {t("security.scanHint")}
                                                                    </Typography>
                                                                ),
                                                                () => (
                                                                    <StackV
                                                                        gap={4}
                                                                        principle="card-caption"
                                                                        explain="Holds caption text under card media so the caption stays attached to the image above it."
                                                                        align="center"
                                                                        items={[
                                                                            () => <QRCode size={180} data={setup.otpauthUrl} />,
                                                                            () => (
                                                                                <StackV
                                                                                    gap={3}
                                                                                    principle="sibling-stack"
                                                                                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                                                                    items={[
                                                                                        () => (
                                                                                            <Typography type="body-xs" color="muted" align="center">
                                                                                                {t("security.secretHint")}
                                                                                            </Typography>
                                                                                        ),
                                                                                        () => (
                                                                                            <Typography type="code" align="center" className="break-all">
                                                                                                {setup.secret}
                                                                                            </Typography>
                                                                                        ),
                                                                                    ]}
                                                                                />
                                                                            ),
                                                                        ]}
                                                                    />
                                                                ),
                                                                () => (
                                                                    <TextField variant="secondary">
                                                                        <Label>{t("security.codeLabel")}</Label>
                                                                        <Input
                                                                            variant="secondary"
                                                                            inputMode="numeric"
                                                                            autoComplete="one-time-code"
                                                                            placeholder={t("security.codePlaceholder")}
                                                                            value={code}
                                                                            onChange={onCodeChange}
                                                                        />
                                                                    </TextField>
                                                                ),
                                                                () => (
                                                                    <StackH
                                                                        gap={4}
                                                                        principle="flex-action"
                                                                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                                                        items={[
                                                                            () => (
                                                                                <Button
                                                                                    variant="primary"
                                                                                    fullWidth
                                                                                    isDisabled={!codeComplete || confirming}
                                                                                    isPending={confirming}
                                                                                    onPress={onConfirm}
                                                                                >
                                                                                    {({ isPending }) => (
                                                                                        <>
                                                                                            {isPending ? <Spinner color="current" size="sm" /> : null}
                                                                                            {t("security.confirm")}
                                                                                        </>
                                                                                    )}
                                                                                </Button>
                                                                            ),
                                                                            () => (
                                                                                <Button
                                                                                    variant="ghost"
                                                                                    onPress={onCancelSetup}
                                                                                >
                                                                                    {t("security.cancel")}
                                                                                </Button>
                                                                            ),
                                                                        ]}
                                                                    />
                                                                ),
                                                            ]}
                                                        />
                                                    )] : [() => (
                                                        <Button
                                                            variant="primary"
                                                            isDisabled={settingUp}
                                                            isPending={settingUp}
                                                            onPress={onStartSetup}
                                                        >
                                                            {({ isPending }) => (
                                                                <>
                                                                    {isPending ? <Spinner color="current" size="sm" /> : null}
                                                                    {t("security.enable")}
                                                                </>
                                                            )}
                                                        </Button>
                                                    )]),
                                                ]}
                                            />
                                        </AsyncContent>
                                    </CardContent>
                                </Card>
                            ),
                            () => (
                                <Typography type="body-xs" color="muted">
                                    {t("security.note")}
                                </Typography>
                            ),
                        ]}
                    />
                ),
            ]}
        />
    )
}

"use client"

import { ClockCountdownIcon as ClockCountdown } from "@phosphor-icons/react"
import React, {
    useCallback,
} from "react"
import {
    Card,
} from "@heroui/react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useSearchParams,
} from "next/navigation"
import {
    useRouter,
} from "@/i18n/navigation"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { pathConfig } from "@/resources/path"
import { Button } from "@/components/atoms/buttons/Button"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"

/** Props for {@link CheckoutExpired}. */
export interface CheckoutExpiredProps {
    /** Re-arm the poll window and re-check the payment status once more. */
    onRecheck: () => void
}

/**
 * Terminal state shown when the SePay checkout window elapses without the
 * payment landing (the transaction has moved — or will move — to `Unpaid` on
 * the BE, `transactions/business.md` "Pending → Unpaid"). Replaces the
 * otherwise-indefinite QR + waiting spinner with an explicit dead-end + two
 * ways forward: re-check once more (in case the bank transfer just settled) or
 * start a fresh checkout from the course page.
 *
 * Self-contained (mirrors the sibling panels): reads its own `courseId` param
 * and owns the "start over" navigation; the re-check + timer reset is handed in
 * from the container as `onRecheck`. `"use client"` for the params / i18n / nav
 * hooks and the buttons.
 *
 * @param props - the container's re-check handler.
 */
export const CheckoutExpired = ({ onRecheck }: CheckoutExpiredProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const searchParams = useSearchParams()
    const courseId = searchParams.get("courseId") || ""

    /** Go back to the course page to start a fresh checkout. */
    const onStartOver = useCallback(
        () => {
            router.push(pathConfig().locale(locale).course(courseId).build())
        },
        [
            router,
            locale,
            courseId,
        ],
    )

    return (
        <Box identity={{ tier: "page", component: "CheckoutExpired" }} principle="page-pad" className="flex min-h-[80vh] flex-col items-center justify-center p-4"
            explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface.">
            {/* Glass Card chrome stays on vendor Card until a house surface owns the frosted look. */}
            <Card className="w-full max-w-md bg-default/40 text-center backdrop-blur-md">
                <Box principle="card-padding" className="p-8"
                    explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
                    <Card.Content>
                        <StackV gap={6} principle="group-boundary" align="center"
                            explain="Section group spacing — not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
                            items={[
                                () => (
                                    <StackH gap={1} principle="identity" justify="center"
                                        explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                                        items={[
                                            () => <IconTile icon={<ClockCountdown aria-hidden focusable="false" />} tone="warning" size="lg" />,
                                        ]} />
                                ),
                                () => (
                                    <StackV gap={2} principle="title-subtitle" align="center"
                                        explain="Title over supporting line — not label-field, because neither line is a form control label."
                                        items={[
                                            () => <h1 className="text-2xl font-bold">{t("payment.sepay.expired.title")}</h1>,
                                            () => <p className="text-muted">{t("payment.sepay.expired.description")}</p>,
                                        ]} />
                                ),
                                () => (
                                    <StackV gap={4} principle="content-row" classNames={["w-full"]}
                                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                        items={[
                                            () => (
                                                <Button
                                                    variant="primary"
                                                    classNames={["w-full"]}
                                                    label={t("payment.sepay.expired.startOver")}
                                                    onPress={onStartOver}
                                                />
                                            ),
                                            () => (
                                                <Button
                                                    variant="secondary"
                                                    classNames={["w-full"]}
                                                    label={t("payment.sepay.expired.recheck")}
                                                    onPress={onRecheck}
                                                />
                                            ),
                                        ]} />
                                ),
                            ]} />
                    </Card.Content>
                </Box>
            </Card>
        </Box>
    )
}

"use client"

import { CopyIcon } from "@phosphor-icons/react"
import React from "react"
import { Button } from "@heroui/react"
/** Props for {@link DetailRow}. */
export interface DetailRowProps {
    /** Uppercase caption shown above the value. */
    label: string
    /** The value text rendered in the row. */
    value: string
    /** When true, render a copy-to-clipboard button. */
    showCopy?: boolean
    /** Text to copy when the button is pressed; falls back to `value`. */
    copyValue?: string
    /** When true, style the row as the primary/highlighted field. */
    isHighlighted?: boolean
    /** Copy handler invoked with the resolved text to copy. */
    onCopy?: (text: string) => void
}

/**
 * One label/value row in the SePay order summary, with optional copy button.
 *
 * Presentational (render-only): the container owns the clipboard logic and
 * passes it down via {@link DetailRowProps.onCopy}; `"use client"` only because
 * it renders the interactive HeroUI copy button.
 * @param props - the row label/value + copy + highlight flags
 */
export const DetailRow = ({
    label,
    value,
    showCopy = false,
    copyValue,
    isHighlighted = false,
    onCopy}: DetailRowProps) => {
    const textToCopy = copyValue ?? value
    return (
        <div className={"flex flex-col gap-2"}>
            <span className="text-xs font-semibold uppercase tracking-wide text-muted">
                {label}
            </span>
            <div
                className={`flex items-center justify-between rounded-xl border-1 p-3 ${
                    isHighlighted ? "border-primary/30 bg-primary/10" : "border-default-200 bg-default/40"
                }`}
            >
                <span
                    className={`font-mono ${isHighlighted ? "text-lg font-bold text-primary" : "text-sm"}`}
                >
                    {value}
                </span>
                {showCopy ? (
                    <Button
                        aria-label="Copy"
                        size="sm"
                        variant="ghost"
                        onPress={() => onCopy?.(textToCopy)}
                    >
                        <CopyIcon className="h-5 w-5" />
                    </Button>
                ) : null}
            </div>
        </div>
    )
}

"use client"

import React, {
    useCallback,
    useMemo,
} from "react"
import {
    Card,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import {
    useSearchParams,
} from "next/navigation"
import type {
    BankDetails,
} from "@/modules/types/sepay-checkout"
import {
    parseBankDetails,
} from "@/modules/utils/parse-bank-details"
import {
    DetailRow,
} from "../DetailRow"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * Right-hand panel: the price card plus the bank/account/amount/content rows.
 *
 * Self-contained section (single-use): reads its own checkout query params,
 * derives the destination bank from the QR url, and owns the clipboard copy
 * handler — so the checkout container only renders `<OrderSummary />` and the
 * logic lives next to where it is used. `"use client"` for the query-params /
 * i18n hooks and the interactive copy rows. The repeated rows are rendered via
 * the presentational {@link DetailRow} (list-style), which takes the local
 * `onCopy` handler as a prop.
 */
export const OrderSummary = () => {
    const t = useTranslations()
    const searchParams = useSearchParams()

    const amount = searchParams.get("amount") || ""
    const referenceId = searchParams.get("ref") || ""
    const courseTitle = searchParams.get("courseTitle") || ""
    const qrUrl = searchParams.get("qr") || ""

    /** Destination bank + account parsed once from the QR url. */
    const bankDetails = useMemo<BankDetails>(
        () => parseBankDetails(qrUrl),
        [
            qrUrl,
        ],
    )

    /** Copy the given text to the clipboard. */
    const onCopy = useCallback(
        (text: string) => {
            void navigator.clipboard.writeText(text)
        },
        [],
    )

    return (
        <StackV identity={{ tier: "page", component: "OrderSummary" }} principle="block-boundary"
            explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
            items={[
                () => (
                    <Card className="bg-default/40 backdrop-blur-md">
                        <Box principle="card-padding" className="p-6"
                            explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
                            <Card.Content>
                                <h3 className="mb-4 text-lg font-medium">{courseTitle}</h3>
                                <StackH principle="value-row"
                                    explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
                                    items={[
                                        () => (
                                            <span className="text-3xl font-bold text-primary">
                                                {Number(amount).toLocaleString("vi-VN")}
                                            </span>
                                        ),
                                        () => <span className="text-sm text-muted">VND</span>,
                                    ]} />
                            </Card.Content>
                        </Box>
                    </Card>
                ),

                () => (
                    <Card className="flex-grow bg-default/40 backdrop-blur-md">
                        <Box principle="card-padding" className="p-6"
                            explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
                            <Card.Content>
                                <StackV principle="content-row"
                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                    items={[
                                        () => <DetailRow label={t("payment.sepay.bank")} value={bankDetails.bank} />,
                                        () => (
                                            <DetailRow
                                                copyValue={bankDetails.account}
                                                label={t("payment.sepay.account")}
                                                showCopy
                                                value={bankDetails.account}
                                                onCopy={onCopy}
                                            />
                                        ),
                                        () => (
                                            <DetailRow
                                                copyValue={amount}
                                                label={t("payment.sepay.amount")}
                                                showCopy
                                                value={`${Number(amount).toLocaleString("vi-VN")} VND`}
                                                onCopy={onCopy}
                                            />
                                        ),
                                        () => (
                                            <DetailRow
                                                copyValue={referenceId}
                                                isHighlighted
                                                label={t("payment.sepay.content")}
                                                showCopy
                                                value={referenceId}
                                                onCopy={onCopy}
                                            />
                                        ),
                                    ]} />
                            </Card.Content>
                        </Box>
                    </Card>
                ),
            ]} />
    )
}

