"use client"

import React, {
    Suspense,
    useCallback,
    useEffect,
    useState,
} from "react"
import { Spinner } from "@/components/atoms/display/Spinner"
import {
    useLocale,
} from "next-intl"
import {
    useSearchParams,
} from "next/navigation"
import {
    useQueryCourseEnrollmentStatusSwr,
} from "@/hooks/swr/api/graphql/queries/useQueryCourseEnrollmentStatusSwr"
import {
    useRouter,
} from "@/i18n/navigation"
import {
    EnrolledSuccess,
} from "./EnrolledSuccess"
import {
    CheckoutExpired,
} from "./CheckoutExpired"
import {
    QrPanel,
} from "./QrPanel"
import {
    OrderSummary,
} from "./OrderSummary"
import { pathConfig } from "@/resources/path"
import { Box } from "@/components/frames/Box"
import { Grid } from "@/components/frames/Grid"

/** How often (ms) to re-poll the enrollment status while waiting for payment. */
const POLL_INTERVAL_MS = 5000
/** Delay (ms) before redirecting to the course once enrollment is confirmed. */
const REDIRECT_DELAY_MS = 2000
/**
 * How long (ms) to keep polling before treating the checkout as timed out.
 * There is no transaction-status query in the FE GraphQL layer (the only signal
 * is enrollment, which can never flip `true → false`), so once this window
 * elapses without enrollment we surface a terminal "expired" state rather than
 * spinning forever — matching the BE's `Pending → Unpaid` transition
 * (`transactions/business.md`). 15 minutes covers a slow bank transfer.
 */
const CHECKOUT_EXPIRY_MS = 15 * 60 * 1000

/**
 * SePay checkout container.
 *
 * Owns only the page-level concern: poll the course enrollment status via SWR
 * and redirect to the course once enrollment lands (showing the success screen
 * for a beat first). Each panel is self-contained — `QrPanel` and `OrderSummary`
 * read their own query params and own their own handlers — so this container
 * just composes them. `"use client"` because it runs effects + reads params.
 */
const SepayCheckoutPageContent = () => {
    const searchParams = useSearchParams()
    const locale = useLocale()
    const router = useRouter()

    const courseId = searchParams.get("courseId") || ""

    const {
        data: statusData,
        mutate: refreshStatus,
    } = useQueryCourseEnrollmentStatusSwr()
    const isEnrolled = statusData?.courseEnrollmentStatus?.data?.isEnrolled

    // once the checkout window elapses without enrollment, flip to the terminal
    // "expired" state (there is no tx-status query to observe `Unpaid` directly)
    const [isExpired, setIsExpired] = useState(false)

    // poll the enrollment status on a fixed interval while waiting for payment —
    // stops once we're enrolled (redirecting) or the checkout has expired, so we
    // don't keep hitting the API on a settled/dead checkout
    useEffect(
        () => {
            if (isEnrolled || isExpired) {
                return
            }
            const interval = setInterval(
                () => {
                    refreshStatus()
                },
                POLL_INTERVAL_MS,
            )
            return () => clearInterval(interval)
        },
        [
            refreshStatus,
            isEnrolled,
            isExpired,
        ],
    )

    // arm the expiry timeout while waiting; re-arms whenever the user re-checks
    // (which resets `isExpired` to false), and never fires once enrolled
    useEffect(
        () => {
            if (isEnrolled || isExpired) {
                return
            }
            const timer = setTimeout(
                () => {
                    setIsExpired(true)
                },
                CHECKOUT_EXPIRY_MS,
            )
            return () => clearTimeout(timer)
        },
        [
            isEnrolled,
            isExpired,
        ],
    )

    // re-open the poll window and re-check once more (e.g. a slow transfer just
    // settled after the timeout) — resets the terminal back to the waiting view
    const onRecheck = useCallback(
        () => {
            setIsExpired(false)
            refreshStatus()
        },
        [
            refreshStatus,
        ],
    )

    // once enrolled, give the success screen a beat then redirect to the course
    useEffect(
        () => {
            if (isEnrolled) {
                const timer = setTimeout(
                    () => {
                        router.push(pathConfig().locale(locale).course(courseId).build())
                    },
                    REDIRECT_DELAY_MS,
                )
                return () => clearTimeout(timer)
            }
        },
        [
            isEnrolled,
            courseId,
            locale,
            router,
        ],
    )

    if (isEnrolled) {
        return <EnrolledSuccess />
    }

    if (isExpired) {
        return <CheckoutExpired onRecheck={onRecheck} />
    }

    return (
        <Box principle="page-pad" className="flex min-h-screen flex-col items-center px-4 py-12"
            explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface.">
            <Box principle="center-measure" className="w-full max-w-4xl"
                explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport."
            >
                <Grid
                    columns={{ base: 1, md: 2 }}
                    principle="layout-split"
                    explain="Major layout split — not block-boundary, because this separates primary page regions rather than adjacent blocks."
                    items={[
                        { key: "qr", content: QrPanel },
                        { key: "summary", content: OrderSummary },
                    ]}
                />
            </Box>
        </Box>
    )
}

/**
 * Public SePay checkout entry point.
 *
 * Wraps {@link SepayCheckoutPageContent} in a Suspense boundary (required because
 * the content + panels read `useSearchParams`) with a centered spinner fallback.
 * Mounted by the `/[locale]/checkout/sepay` route.
 */
export const SepayCheckoutPage = () => {
    return (
        <Suspense
            fallback={
                <div className="flex min-h-[80vh] items-center justify-center">
                    <Spinner size="lg" />
                </div>
            }
        >
            <SepayCheckoutPageContent />
        </Suspense>
    )
}

"use client"

import {
    SignOutIcon,
    DesktopIcon,
    DeviceMobileIcon,
} from "@phosphor-icons/react"
import React, {
    useCallback,
    useState,
} from "react"
import {
    Button,
    Chip,
    Spinner,
    Typography,
} from "@heroui/react"
import {
    SettingsBreadcrumb,
} from "@/components/blocks/settings/SettingsBreadcrumb"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { SurfaceListCard, SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import { Box } from "@/components/frames/Box"
import { Cluster } from "@/components/frames/Cluster"
import { StackH, StackV } from "@/components/frames/Stack"
import { useQueryMySessionsSwr } from "@/hooks/swr/api/graphql/queries/useQueryMySessionsSwr"
import { useMutateRevokeSessionSwr } from "@/hooks/swr/api/graphql/mutations/useMutateRevokeSessionSwr"
import type { LoginSession } from "@/modules/api/graphql/queries/types/my-sessions"
import { useGraphQLWithToast } from "@/modules/toast/hooks"

/**
 * SessionsPage / devices feature container.
 *
 * Lists the current user's active login sessions (devices) and lets them log
 * out any device except the one making the request. Owns the page chrome
 * (breadcrumb + header) and the loading gate; revoking optimistically
 * revalidates the list. Mounted by `/profile/sessions`.
 */
export const SessionsPage = () => {
    const t = useTranslations()
    const locale = useLocale()
    const {
        data: sessions,
        isLoading,
        error,
        mutate,
    } = useQueryMySessionsSwr()
    const { trigger: triggerRevoke } = useMutateRevokeSessionSwr()
    const runGraphQL = useGraphQLWithToast()

    // the session id currently being revoked (drives the per-row spinner)
    const [revokingId, setRevokingId] = useState<string | null>(null)


    /** Revoke a device session, then revalidate the list. */
    const onRevoke = useCallback(
        async (sessionId: string) => {
            setRevokingId(sessionId)
            try {
                const ok = await runGraphQL(async () => {
                    // `triggerRevoke` returns the raw Apollo result; unwrap the
                    // standard `{ success, message }` payload for the toast helper.
                    const result = await triggerRevoke({ sessionId })
                    return result.data!.revokeSession
                })
                if (ok) {
                    // refresh so the logged-out device drops off the list
                    await mutate()
                }
            } finally {
                setRevokingId(null)
            }
        },
        [
            runGraphQL,
            triggerRevoke,
            mutate,
        ],
    )

    /** Format an ISO timestamp as `HH:mm MMM DD, YYYY` (24h time + short month). */
    const formatSeen = useCallback(
        (iso: string) => {
            // tolerate a bad/missing date rather than throwing in render
            const date = new Date(iso)
            if (Number.isNaN(date.getTime())) {
                return ""
            }
            const hh = String(date.getHours()).padStart(2, "0")
            const mm = String(date.getMinutes()).padStart(2, "0")
            const month = date.toLocaleString(locale, { month: "short" })
            const day = String(date.getDate()).padStart(2, "0")
            return `${hh}:${mm} ${month} ${day}, ${date.getFullYear()}`
        },
        [
            locale,
        ],
    )

    const sessionList = sessions ?? []

    const skeletonRows = [0, 1, 2].map((row) => () => (
        <SurfaceListCardItem key={row}>
            <div className="h-12">
                <StackH
                    gap={4}
                    align="center"
                    principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                    items={[
                        () => <Skeleton className="size-5 shrink-0 rounded" />,
                        () => (
                            <StackV
                                gap={3}
                                principle="sibling-stack"
                                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                classNames={["min-w-0", "flex-1"]}
                                items={[
                                    () => <Skeleton.Typography type="body-sm" width="1/2" />,
                                    () => <Skeleton className="h-3 w-1/3 rounded" />,
                                ]}
                            />
                        ),
                    ]}
                />
            </div>
        </SurfaceListCardItem>
    ))

    return (
        <div className="flex flex-col gap-10">
            <PageHeader
                breadcrumb={<SettingsBreadcrumb current={t("sessions.title")} />}
                title={t("sessions.title")}
                description={t("sessions.subtitle")}
            />

            <AsyncContent
                isLoading={isLoading && !sessions}
                skeleton={(
                    <SurfaceListCard>
                        {skeletonRows.map((Row, index) => (
                            <Row key={index} />
                        ))}
                    </SurfaceListCard>
                )}
                isEmpty={sessionList.length === 0}
                emptyContent={{ title: t("sessions.empty") }}
                error={error}
                errorContent={{
                    title: t("sessions.empty"),
                    onRetry: () => { void mutate() },
                    retryLabel: t("common.retry"),
                }}
            >
                <SurfaceListCard>
                    {sessionList.map((session: LoginSession) => {
                        // pick a device glyph from the coarse device class
                        const isMobile =
                            session.deviceType === "mobile"
                            || session.deviceType === "tablet"
                        const DeviceIcon = isMobile ? DeviceMobileIcon : DesktopIcon
                        // headline = "Browser on OS", falling back gracefully
                        const headline = [
                            session.browser,
                            session.os,
                        ]
                            .filter(Boolean)
                            .join(" • ") || t("sessions.unknownDevice")

                        const rowItems = [
                            () => <DeviceIcon aria-hidden focusable="false" className="size-5 shrink-0 text-accent-soft-foreground" />,
                            () => (
                                <div className="flex min-w-0 flex-1 flex-col gap-0">
                                    <Cluster
                                        gap={3}
                                        align="center"
                                        principle="chip-row"
                                        explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                        items={[
                                            () => (
                                                <Typography type="body-sm" weight="medium" truncate>
                                                    {headline}
                                                </Typography>
                                            ),
                                            ...(session.current
                                                ? [() => (
                                                    <Chip color="accent" variant="soft" size="sm">
                                                        <Chip.Label>{t("sessions.thisDevice")}</Chip.Label>
                                                    </Chip>
                                                )]
                                                : []),
                                        ]}
                                    />
                                    <div className="flex flex-wrap items-center gap-x-3 gap-y-2">
                                        {session.location ? (
                                            <Typography type="body-xs" color="muted">{session.location}</Typography>
                                        ) : null}
                                        {session.ipAddress ? (
                                            <Typography type="body-xs" color="muted">{session.ipAddress}</Typography>
                                        ) : null}
                                        <Typography type="body-xs" color="muted">{formatSeen(session.lastSeenAt)}</Typography>
                                    </div>
                                </div>
                            ),
                            ...(!session.current
                                ? [() => (
                                    <Box principle="push-end" className="ml-auto shrink-0"
                                        explain="Pushes this peer to the trailing edge so trailing meta stays right-aligned in the row.">
                                        <Button
                                            variant="ghost"
                                            size="sm"
                                            className="text-danger-soft-foreground"
                                            isDisabled={revokingId === session.sessionId}
                                            onPress={() => onRevoke(session.sessionId)}
                                            aria-label={t("sessions.revoke")}
                                        >
                                            {revokingId === session.sessionId ? (
                                                <Spinner color="current" size="sm" />
                                            ) : (
                                                <SignOutIcon aria-hidden focusable="false" className="size-5" />
                                            )}
                                            {t("sessions.revoke")}
                                        </Button>
                                    </Box>
                                )]
                                : []),
                        ]

                        return (
                            <SurfaceListCardItem key={session.id}>
                                <StackH gap={4} align="center" principle="content-row"
                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                    items={rowItems}  />
                            </SurfaceListCardItem>
                        )
                    })}
                </SurfaceListCard>
            </AsyncContent>
        </div>
    )
}

"use client"

import React from "react"
import {
    Typography,
    Chip,
} from "@heroui/react"
import {
    EnvelopeIcon,
} from "@phosphor-icons/react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import {
    SettingsBreadcrumb,
} from "@/components/blocks/settings/SettingsBreadcrumb"
import {
    getSettingsGroups,
} from "@/resources/settings-nav"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { GroupPressableCard } from "@/components/blocks/cards/GroupPressableCard"
import { GithubIcon } from "@/components/svg/GithubIcon"
import { GoogleIcon } from "@/components/svg/GoogleIcon"
import { useAppSelector } from "@/redux/hooks"
import { AuthenticationType } from "@/modules/types/enums/authentication-type"
import { StackH, StackV } from "@/components/frames/Stack"

/** Props for {@link SettingsHomePage}. */
export type SettingsHomePageProps = Record<string, never>
/**
 * Settings hub landing — a responsive grid of every account-management
 * destination (a card per page), so `/profile/settings` answers "where do I
 * manage things?" directly. Shares its destinations with the sidebar via
 * {@link getSettingsGroups}, so the two never drift.
 *
 * @param props - optional root className.
 */
export const SettingsHomePage = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const items = getSettingsGroups(locale).flatMap((group) => group.items)

    // login method (provider) badge — google / github / credentials
    const authType = useAppSelector((state) => state.user.user?.authenticationType)
    const methodMeta = authType === AuthenticationType.Github
        ? { key: "github", icon: <GithubIcon className="size-3.5" /> }
        : authType === AuthenticationType.Google
            ? { key: "google", icon: <GoogleIcon /> }
            : authType === AuthenticationType.Credentials
                ? { key: "credentials", icon: <EnvelopeIcon className="size-3.5" /> }
                : null

    return (
        <div>
            <StackV gap={7} principle="layout-split"
                explain="Major layout split — not block-boundary, because this separates primary page regions rather than adjacent blocks."
                items={[
                    () => (
                        <PageHeader
                            breadcrumb={<SettingsBreadcrumb current={t("profileSettings.title")} />}
                            title={t("profileSettings.title")}
                            description={t("profileSettings.subtitle")}
                        />
                    ),
                    () => (methodMeta ? (
                        <StackH gap={3} principle="identity"
                            explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                            align="center" items={[
                                () => (
                                    <Typography type="body-sm" className="text-default-500">
                                        {t("profileSettings.loginMethod")}
                                    </Typography>
                                ),
                                () => (
                                    <Chip size="sm" variant="soft" color="default">
                                        {methodMeta.icon}
                                        <Chip.Label>
                                            {t(`profileSettings.loginMethodValue.${methodMeta.key}`)}
                                        </Chip.Label>
                                    </Chip>
                                ),
                            ]} />
                    ) : null),
                    () => (
                        <GroupPressableCard
                            ariaLabel={t("profileSettings.itemsAria")}
                            // container steps, not viewport: two-up only once the settings column
                            // is 512px wide (≈252px per card — enough for the icon tile plus a
                            // label that would otherwise truncate)
                            columns={{ base: 1, lg: 2 }}
                            items={items.map((item) => ({
                                key: item.key,
                                onPress: () => router.push(item.href),
                                content: () => (
                                    <StackH gap={4} principle="content-row"
                                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                        align="center" items={[
                                            () => <IconTile icon={item.icon} tone="accent" size="sm" />,
                                            () => (
                                                <Typography type="body-sm" weight="medium" truncate>
                                                    {t(`profileSettings.items.${item.key}`)}
                                                </Typography>
                                            ),
                                        ]} />
                                ),
                            }))}
                        />
                    ),
                ]} />
        </div>
    )
}

"use client"

import React, { useMemo } from "react"
import { Card, CardContent, cn } from "@heroui/react"
import { useTranslations } from "next-intl"
import { CpuIcon } from "@phosphor-icons/react"
import { Box } from "@/components/frames/Box"
import { Cluster } from "@/components/frames/Cluster"
import { StackH, StackV } from "@/components/frames/Stack"
import type { AiKeyHealthGroup } from "@/modules/api/graphql/queries/types/ai-key-health"

/** Props for {@link AiKeyGroup}. */
export interface AiKeyGroupProps {
    /** One per-model AI key health group from GraphQL. */
    group: AiKeyHealthGroup
}

/**
 * One model group of AI keys on the public status page. Header reads
 * "<models> · <provider> · healthy/total keys"; below it a row of masked key
 * chips, each tinted success (healthy) or danger (unhealthy). Token-only colors
 * → works light + dark. The masked label (`sk-...x9f`) is all that is shown.
 *
 * List item: keeps its own `group` payload but reads its own labels from i18n.
 * @param props.group - Masked AI key health for one model.
 */
export const AiKeyGroup = ({ group }: AiKeyGroupProps) => {
    const t = useTranslations("status")

    const header = useMemo(() => {
        const models = group.models.join(", ") || group.provider
        return t("aiKeyGroupHeader", {
            models,
            provider: group.provider,
            healthy: group.healthyKeys,
            total: group.totalKeys,
        })
    }, [group, t])

    const chipItems = group.keys.map((key, index) => () => (
        <span
            key={`${key.keyMask}-${index}`}
            className={cn(
                "inline-flex items-center rounded-full px-2 py-0 font-mono text-xs font-medium",
                key.healthy
                    ? "bg-success-soft text-success-soft-foreground"
                    : "bg-danger-soft text-danger-soft-foreground",
            )}
        >
            {key.keyMask}
        </span>
    ))

    return (
        <Card className="border border-default bg-surface">
            {/* Vendor CardContent padding cleared so house card-padding owns the inset. */}
            <CardContent className="p-0">
                <Box principle="card-padding" className="p-4"
                    explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
                    <StackV
                        principle="label-field"
                        explain="Form label above its field — not title-subtitle, because the upper line labels an input rather than a heading pair."
                        items={[
                            () => (
                                <StackH
                                    principle="identity"
                                    explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                                    items={[
                                        () => (
                                            <CpuIcon
                                                aria-hidden
                                                focusable="false"
                                                className="size-4 shrink-0 text-muted"
                                            />
                                        ),
                                        () => (
                                            <span className="text-sm font-medium text-foreground">
                                                {header}
                                            </span>
                                        ),
                                    ]}
                                />
                            ),
                            () => (group.keys.length > 0 ? (
                                <Cluster gap={3} principle="chip-row" items={chipItems}
                                    explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                />
                            ) : (
                                <span className="text-xs text-muted">{t("noKeys")}</span>
                            )),
                        ]}
                    />
                </Box>
            </CardContent>
        </Card>
    )
}

"use client"

import React, { useMemo } from "react"
import { Card, CardContent } from "@heroui/react"
import {
    CheckCircleIcon,
    WarningIcon,
    XCircleIcon,
} from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import type { IconComponent } from "@/components/atoms/chips/Chip"
import { StatusChip } from "@/components/blocks/chips/StatusChip"
import { Box } from "@/components/frames/Box"
import { FillAvailable } from "@/components/frames/FillAvailable"
import { StackH, StackV } from "@/components/frames/Stack"
import { resolveComponentStatusVisual } from "@/modules/utils/system-status-map"
import { ComponentStatus } from "@/modules/api/graphql/queries/enums"
import type { SystemHealthComponent } from "@/modules/api/graphql/queries/types/system-health-status"
import { getTimeAgoLabel, getTimeAgoMessage } from "@/modules/dayjs"

/** Props for {@link ComponentCard}. */
export interface ComponentCardProps {
    /** One probed infrastructure component from GraphQL. */
    component: SystemHealthComponent
}

/** Leading StatusChip icon per infrastructure status (contract E — component refs). */
const STATUS_CHIP_ICON: Record<ComponentStatus, IconComponent> = {
    [ComponentStatus.Up]: CheckCircleIcon,
    [ComponentStatus.Degraded]: WarningIcon,
    [ComponentStatus.Down]: XCircleIcon,
}

/**
 * A single infrastructure component card on the public status page — status dot
 * + name, a status chip, latency ("12ms"), and a relative last-checked time.
 *
 * List item: keeps its own `component` payload but reads its own status labels
 * + relative-time strings from the i18n hooks (no prop-drilled maps).
 * @param props.component - Probed component snapshot.
 */
export const ComponentCard = ({ component }: ComponentCardProps) => {
    const t = useTranslations()
    const visual = resolveComponentStatusVisual(component.status)
    const statusIcon =
        STATUS_CHIP_ICON[component.status as ComponentStatus] ?? STATUS_CHIP_ICON[ComponentStatus.Down]

    const statusLabel = t(`status.componentStatus.${component.status}`)

    const checkedAgo = useMemo(
        () => getTimeAgoLabel(getTimeAgoMessage(component.checkedAt), t),
        [component.checkedAt, t],
    )

    return (
        <Card className="border border-default bg-surface">
            {/* Vendor CardContent padding cleared so house card-padding owns the inset. */}
            <CardContent className="p-0">
                <Box principle="card-padding" className="p-4"
                    explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
                    <StackV
                        principle="sibling-stack"
                        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                        items={[
                            () => (
                                <StackH
                                    principle="flex-action-between"
                                    explain="Identity and status chip shoved apart on one control row — not plain flex-action, because the status reads as the trailing commit."
                                    items={[
                                        () => (
                                            <FillAvailable
                                                at="base"
                                                explain="Component name takes remaining header width beside the status chip so long service ids truncate."
                                                body={() => (
                                                    <StackH
                                                        principle="identity"
                                                        explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                                                        items={[
                                                            () => (
                                                                <span
                                                                    className={`size-2.5 shrink-0 rounded-full ${visual.dotClassName}`}
                                                                    aria-hidden
                                                                />
                                                            ),
                                                            () => (
                                                                <span className="truncate font-mono text-sm font-medium text-foreground">
                                                                    {component.name}
                                                                </span>
                                                            ),
                                                        ]}
                                                    />
                                                )}
                                            />
                                        ),
                                        () => (
                                            <StatusChip tone={visual.tone} icon={statusIcon}>
                                                {statusLabel}
                                            </StatusChip>
                                        ),
                                    ]}
                                />
                            ),
                            () => (
                                <StackH
                                    principle="flex-action-between"
                                    explain="Latency and checked-ago meta shoved apart on one control row — not plain flex-action, because the pair reads as escape/commit ends."
                                    items={[
                                        () => (
                                            <span className="tabular-nums text-xs text-muted">
                                                {component.latencyMs === null
                                                    ? "—"
                                                    : t("status.latency", { ms: component.latencyMs })}
                                            </span>
                                        ),
                                        () => (
                                            <span className="truncate text-xs text-muted">
                                                {t("status.checked", { ago: checkedAgo })}
                                            </span>
                                        ),
                                    ]}
                                />
                            ),
                            ...(component.message ? [() => (
                                <p className="truncate text-xs text-danger-soft-foreground" title={component.message ?? undefined}>
                                    {component.message}
                                </p>
                            )] : []),
                        ]}
                    />
                </Box>
            </CardContent>
        </Card>
    )
}

import React from "react"
import { cn } from "@heroui/react"
import { CheckCircleIcon, WarningOctagonIcon } from "@phosphor-icons/react"

/** Props for {@link OverallBanner}. */
export interface OverallBannerProps {
    /** True when every probed component is `up`. */
    allUp: boolean
    /** Localized "N/M components healthy" label. */
    label: string
}

/**
 * Top-of-page overall health banner. Tints success (green) when every component
 * is up and danger (red) the moment anything is down/degraded. Token-only so it
 * reads correctly in light + dark.
 *
 * @param props - See {@link OverallBannerProps}.
 */
export const OverallBanner = ({ allUp, label}: OverallBannerProps) => {
    return (
        <div
            className={cn("flex items-center gap-3 rounded-2xl border px-4 py-3",
